method check_match(haystack: seq<int>, needle: seq<int>, s: int) returns (b: bool)
    requires 0 <= s && s + |needle| <= |haystack|
    ensures b == matches_at(haystack, needle, s)
{
    var i := 0;
    while i < |needle|
        invariant 0 <= i <= |needle|
        invariant forall j :: 0 <= j < i ==> haystack[s + j] == needle[j]
    {
        if haystack[s + i] != needle[i] {
            assert !(haystack[s + i] == needle[i]);
            assert !matches_at(haystack, needle, s);
            return false;
        }
        i := i + 1;
    }
    return true;
}

method ac_automata_search(haystack: seq<int>, patterns: seq<seq<int>>) returns (results: seq<(int, int)>)
    requires |patterns| > 0
    requires |haystack| < 1000000
    requires |patterns| < 1000000
    requires forall i :: 0 <= i < |patterns| ==> |patterns[i]| < 1000000
    ensures
        forall i :: 0 <= i < |results| ==>
            var (pid, idx) := results[i];
            && pid >= 0 && idx >= 0 
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)
    ensures
        forall pid, idx ::
            0 <= pid < |patterns| && matches_at(haystack, patterns[pid], idx) ==>
            exists k :: 0 <= k < |results| && results[k] == (pid, idx)
{
    results := [];
    var pid := 0;
    while pid < |patterns|
        invariant 0 <= pid <= |patterns|
        invariant forall i :: 0 <= i < |results| ==>
            0 <= results[i].0 < |patterns| && results[i].1 >= 0
            && matches_at(haystack, patterns[results[i].0], results[i].1)
        invariant forall p, j :: 0 <= p < pid && matches_at(haystack, patterns[p], j) ==> (p, j) in results
    {
        var pat := patterns[pid];
        var idx := 0;
        while idx + |pat| <= |haystack|
            invariant 0 <= idx
            invariant idx == 0 || idx + |pat| <= |haystack| + 1
            invariant forall i :: 0 <= i < |results| ==>
                0 <= results[i].0 < |patterns| && results[i].1 >= 0
                && matches_at(haystack, patterns[results[i].0], results[i].1)
            invariant forall p, j :: 0 <= p < pid && matches_at(haystack, patterns[p], j) ==> (p, j) in results
            invariant forall j :: 0 <= j < idx && matches_at(haystack, pat, j) ==> (pid, j) in results
            decreases |haystack| - idx
        {
            var b := check_match(haystack, pat, idx);
            if b {
                results := results + [(pid, idx)];
            }
            idx := idx + 1;
        }
        assert forall j :: matches_at(haystack, pat, j) ==> j < idx;
        pid := pid + 1;
    }
    assert forall p, j :: 0 <= p < |patterns| && matches_at(haystack, patterns[p], j) ==> (p, j) in results;
}

