lemma ac_match_equivalence(
    haystack: seq<int>,
    needle: seq<int>,
    start_index: int)
    ensures ac_is_match(haystack, needle, start_index)
        <==> matches_at(haystack, needle, start_index)
{
    if 0 <= start_index
        && start_index + |needle| <= |haystack|
    {
        if matches_at(haystack, needle, start_index) {
            assert |haystack[start_index .. start_index + |needle|]| == |needle|;

            forall i | 0 <= i < |needle|
                ensures haystack[start_index .. start_index + |needle|][i]
                    == needle[i]
            {
                assert haystack[start_index .. start_index + |needle|][i]
                    == haystack[start_index + i];
                assert haystack[start_index + i] == needle[i];
            }

            ac_seq_extensional(
                haystack[start_index .. start_index + |needle|],
                needle);
            assert ac_is_match(haystack, needle, start_index);
        }

        if ac_is_match(haystack, needle, start_index) {
            assert haystack[start_index .. start_index + |needle|] == needle;

            forall i | 0 <= i < |needle|
                ensures haystack[start_index + i] == needle[i]
            {
                assert haystack[start_index .. start_index + |needle|][i]
                    == haystack[start_index + i];
                assert haystack[start_index .. start_index + |needle|][i]
                    == needle[i];
            }

            assert matches_at(haystack, needle, start_index);
        }
    } else {
        assert !ac_is_match(haystack, needle, start_index);
        assert !matches_at(haystack, needle, start_index);
    }
}

