    forall idx |
        0 <= idx < next_index + 1
        && matches_at(haystack, patterns[pid], idx)
        ensures ac_contains(results, pid, idx)
    {
        if idx < next_index {
            assert ac_contains(results, pid, idx);
        } else {
            assert idx == next_index;
            assert ac_contains(results, pid, next_index);
