lemma ac_advance_pattern(
    haystack: seq<int>,
    patterns: seq<seq<int>>,
    results: seq<(int, int)>,
    pid: int)
    requires 0 <= pid < |patterns|
    requires ac_complete_before(haystack, patterns, results, pid)
    requires ac_complete_current(
        haystack, patterns, results, pid, |haystack| + 1)
    ensures ac_complete_before(haystack, patterns, results, pid + 1)
{
    forall other_pid, idx |
        0 <= other_pid < pid + 1
        && 0 <= other_pid < |patterns|
        && matches_at(haystack, patterns[other_pid], idx)
        ensures ac_contains(results, other_pid, idx)
    {
        if other_pid < pid {
            assert ac_contains(results, other_pid, idx);
        } else {
            assert other_pid == pid;
            ac_match_start_bound(
                haystack, patterns[other_pid], idx);
            assert 0 <= idx < |haystack| + 1;
            assert ac_contains(results, pid, idx);
        }
    }
}

method ac_automata_search(
    haystack: seq<int>,
    patterns: seq<seq<int>>)
    returns (results: seq<(int, int)>)
    requires |patterns| > 0
    requires |haystack| < 1000000
    requires |patterns| < 1000000
    requires forall i :: 0 <= i < |patterns| ==> |patterns[i]| < 1000000
    ensures
        forall i :: 0 <= i < |results| ==>
            var (pid, idx) := results[i];
            && pid >= 0 && idx >= 0
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)
    ensures
        forall pid, idx ::
            0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx) ==>
            exists k :: 0 <= k < |results|
                && results[k] == (pid, idx)
{
    results := [];
    assert ac_sound(haystack, patterns, results);
    assert ac_complete_before(haystack, patterns, results, 0);

    var pid := 0;

    while pid < |patterns|
        invariant 0 <= pid <= |patterns|
        invariant ac_sound(haystack, patterns, results)
        invariant ac_complete_before(haystack, patterns, results, pid)
        decreases |patterns| - pid
    {
        var idx := 0;
        assert ac_complete_current(
            haystack, patterns, results, pid, idx);

        while idx <= |haystack|
            invariant 0 <= idx <= |haystack| + 1
            invariant ac_sound(haystack, patterns, results)
            invariant ac_complete_before(
                haystack, patterns, results, pid)
            invariant ac_complete_current(
                haystack, patterns, results, pid, idx)
            decreases |haystack| + 1 - idx
        {
            ac_match_equivalence(
                haystack, patterns[pid], idx);

            if ac_is_match(haystack, patterns[pid], idx) {
                assert matches_at(haystack, patterns[pid], idx);
                assert ac_valid_result(
                    haystack, patterns, (pid, idx));

                ac_sound_after_append(
                    haystack, patterns, results, (pid, idx));
                ac_complete_before_after_append(
                    haystack, patterns, results, (pid, idx), pid);
                ac_complete_current_after_append(
                    haystack, patterns, results, (pid, idx), pid, idx);
                ac_appended_is_contained(results, pid, idx);

                results := results + [(pid, idx)];

                assert ac_sound(haystack, patterns, results);
                assert ac_complete_before(
                    haystack, patterns, results, pid);
                assert ac_complete_current(
                    haystack, patterns, results, pid, idx);
                assert ac_contains(results, pid, idx);
            } else {
                assert !matches_at(haystack, patterns[pid], idx);
            }

            assert matches_at(haystack, patterns[pid], idx)
                ==> ac_contains(results, pid, idx);

            ac_extend_current(
                haystack, patterns, results, pid, idx);
            idx := idx + 1;
        }

        assert idx == |haystack| + 1;
        ac_advance_pattern(haystack, patterns, results, pid);
        pid := pid + 1;
    }

    assert pid == |patterns|;
    assert ac_sound(haystack, patterns, results);
    assert ac_complete_before(
        haystack, patterns, results, |patterns|);

    assert forall i :: 0 <= i < |results| ==>
        var (result_pid, result_idx) := results[i];
        result_pid >= 0
        && result_idx >= 0
        && 0 <= result_pid < |patterns|
        && matches_at(
            haystack, patterns[result_pid], result_idx);

    assert forall result_pid, result_idx ::
        0 <= result_pid < |patterns|
        && matches_at(
            haystack, patterns[result_pid], result_idx)
        ==> exists k ::
            0 <= k < |results|
            && results[k] == (result_pid, result_idx);
}

