  requires p[|p| - 1] == v
  requires |p| <= k + 1
  ensures bf_le(bf_distances(g, source, k)[v], path_weight(g, p))
  decreases k
{
  if k == 0 {
    assert |p| == 1;
    assert path_weight(g, p) == 0;
    match source
    case None =>
    case Some(s) =>
      assert p[0] == s;
      assert v == s;
