    0 <= p[j] < |d| && d[p[j]].Some?
  requires forall j: int :: 0 <= j < |p| - 1 ==>
    0 <= p[j] < |d| &&
    0 <= p[j + 1] < |d| &&
    d[p[j]].Some? &&
    d[p[j + 1]].Some? &&
    d[p[j + 1]].value <=
      d[p[j]].value + get_edge_weight(g, p[j], p[j + 1])
  ensures d[p[|p| - 1]].value <=
    d[p[0]].value + path_weight(g, p)
  decreases |p|
