    bf_path_prefix(g, p);

    assert forall j: int :: 0 <= j < |q| ==>
      0 <= q[j] < |d| && d[q[j]].Some? by {
      forall j | 0 <= j < |q|
        ensures 0 <= q[j] < |d| && d[q[j]].Some?
      {
        assert q[j] == p[j];
      }
    }

    assert forall j: int :: 0 <= j < |q| - 1 ==>
      0 <= q[j] < |d| &&
      0 <= q[j + 1] < |d| &&
      d[q[j]].Some? &&
      d[q[j + 1]].Some? &&
      d[q[j + 1]].value <=
        d[q[j]].value + get_edge_weight(g, q[j], q[j + 1]) by {
      forall j | 0 <= j < |q| - 1
        ensures
          0 <= q[j] < |d| &&
          0 <= q[j + 1] < |d| &&
          d[q[j]].Some? &&
          d[q[j + 1]].Some? &&
          d[q[j + 1]].value <=
            d[q[j]].value + get_edge_weight(g, q[j], q[j + 1])
      {
        assert q[j] == p[j];
        assert q[j + 1] == p[j + 1];
