lemma bf_stability_excludes_negative_cycles(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures !has_negative_cycle(g)
{
  var d := bf_distances(g, None, |g| - 1);
  var next := bf_distances(g, None, |g|);

  assert |d| == |g|;
  assert |next| == |g|;

  forall u: int, i: int |
      0 <= u < |g| && 0 <= i < |g[u]|
    ensures
      d[g[u][i].0].Some? &&
      d[u].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
  {
    var v := g[u][i].0;
    assert 0 <= v < |g|;

    bf_distances_all_total(g, |g| - 1, u);
    bf_distances_all_total(g, |g| - 1, v);

    bf_all_rows_covers(
      g, d, v, 0, d[v], u, i, d[u].value);

    assert next[v] ==
      bf_all_rows(g, d, v, 0, d[v]);
    assert next == d;
    assert bf_le(d[v], d[u].value + g[u][i].1);
  }

  if has_negative_cycle(g) {
    var p :| is_path(g, p) &&
             |p| > 1 &&
             p[0] == p[|p| - 1] &&
             path_weight(g, p) < 0;

    bf_path_vertices_bounded(g, p);

    forall j | 0 <= j < |p|
      ensures
        0 <= p[j] < |d| &&
        d[p[j]].Some?
    {
      assert 0 <= p[j] < |g|;
      bf_distances_all_total(g, |g| - 1, p[j]);
    }

    forall j | 0 <= j < |p| - 1
      ensures
        0 <= p[j] < |d| &&
        0 <= p[j + 1] < |d| &&
        d[p[j]].Some? &&
        d[p[j + 1]].Some? &&
        d[p[j + 1]].value <=
          d[p[j]].value +
          get_edge_weight(g, p[j], p[j + 1])
    {
      assert connected(g, p[j], p[j + 1]);
      var w :| has_edge(g, p[j], p[j + 1], w);
      var i :| 0 <= p[j] < |g| &&
               0 <= i < |g[p[j]]| &&
               g[p[j]][i].0 == p[j + 1] &&
               g[p[j]][i].1 == w;
      bf_edge_weight(g, p[j], i);
      assert d[p[j + 1]].value <=
        d[p[j]].value + g[p[j]][i].1;
      assert get_edge_weight(g, p[j], p[j + 1]) ==
        g[p[j]][i].1;
    }

    bf_potential_path(g, d, p);

    var initialPotential := d[p[0]].value;
    assert p[0] == p[|p| - 1];
    assert initialPotential <=
      initialPotential + path_weight(g, p);
    assert false;
  }
}

