lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
{
  var g := graph.adj;
  var v := g[u][i].0;
  var wi := g[u][i].1;
  assert has_edge(g, u, v, wi);
  forall w | has_edge(g, u, v, w) ensures w == wi {
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
  var r := get_edge_weight(g, u, v);
  assert has_edge(g, u, v, r);
}

lemma PrefixPath(g: seq<seq<(int, int)>>, p: seq<int>, b: int)
  requires is_path(g, p)
  requires 1 <= b <= |p|
  ensures is_path(g, p[..b])
{
  var s := p[..b];
  forall j | 0 <= j < |s| - 1 ensures connected(g, s[j], s[j + 1]) {
    assert s[j] == p[j] && s[j + 1] == p[j + 1];
    assert connected(g, p[j], p[j + 1]);
  }
}

lemma SuffixPath(g: seq<seq<(int, int)>>, p: seq<int>, a: int)
  requires is_path(g, p)
  requires 0 <= a < |p|
  ensures is_path(g, p[a..])
{
  var s := p[a..];
  forall j | 0 <= j < |s| - 1 ensures connected(g, s[j], s[j + 1]) {
    var t := a + j;
    assert s[j] == p[t] && s[j + 1] == p[t + 1];
    assert connected(g, p[t], p[t + 1]);
  }
}

lemma AppendPath(graph: WeightedGraph, p: seq<int>, u: int, i: int)
  requires well_formed(graph)
  requires is_path(graph.adj, p) && p[|p| - 1] == u
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures var q := p + [graph.adj[u][i].0];
    is_path(graph.adj, q) && q[0] == p[0] && q[|q| - 1] == graph.adj[u][i].0
    && path_weight(graph.adj, q) == path_weight(graph.adj, p) + graph.adj[u][i].1
{
  var g := graph.adj;
  var v := g[u][i].0;
  var q := p + [v];
  assert has_edge(g, u, v, g[u][i].1);
  assert connected(g, u, v);
  forall j | 0 <= j < |q| - 1 ensures connected(g, q[j], q[j + 1]) {
    if j < |p| - 1 {
      assert q[j] == p[j] && q[j + 1] == p[j + 1];
      assert connected(g, p[j], p[j + 1]);
    } else {
      assert q[j] == u && q[j + 1] == v;
    }
  }
  assert is_path(g, q);
  assert q[..|q| - 1] == p;
  EdgeWeight(graph, u, i);
  assert q[|q| - 2] == u && q[|q| - 1] == v;
  assert path_weight(g, q) == path_weight(g, q[..|q| - 1]) + get_edge_weight(g, q[|q| - 2], q[|q| - 1]);
}

lemma SplitWeight(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
  requires 0 <= k < |p|
  ensures path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, p[k..])
  decreases |p|
{
  if k == |p| - 1 {
    assert p[..k + 1] == p;
    assert |p[k..]| == 1;
  } else {
    var r := p[..|p| - 1];
    SplitWeight(g, r, k);
    assert r[..k + 1] == p[..k + 1];
    var s := p[k..];
    assert |s| >= 2;
    assert s[..|s| - 1] == r[k..];
    assert s[|s| - 2] == p[|p| - 2];
    assert s[|s| - 1] == p[|p| - 1];
    assert path_weight(g, s) == path_weight(g, s[..|s| - 1]) + get_edge_weight(g, s[|s| - 2], s[|s| - 1]);
    assert path_weight(g, p) == path_weight(g, r) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma PathInRange(graph: WeightedGraph, p: seq<int>)
  requires well_formed(graph)
  requires is_path(graph.adj, p)
  requires 0 <= p[0] < |graph.adj|
  ensures forall j :: 0 <= j < |p| ==> 0 <= p[j] < |graph.adj|
{
  var g := graph.adj;
  forall j | 0 <= j < |p| ensures 0 <= p[j] < |g| {
    if j > 0 {
      var x := j - 1;
      assert connected(g, p[x], p[x + 1]);
      var w :| has_edge(g, p[x], p[x + 1], w);
      var t :| 0 <= p[x] < |g| && 0 <= t < |g[p[x]]| && g[p[x]][t].0 == p[x + 1] && g[p[x]][t].1 == w;
      assert 0 <= g[p[x]][t].0 < |g|;
    }
  }
}

lemma Pigeonhole(p: seq<int>, n: nat)
  requires forall i :: 0 <= i < |p| ==> 0 <= p[i] < n
  requires |p| > n
  ensures exists i, j :: 0 <= i < j < |p| && p[i] == p[j]
  decreases n
{
  if n == 0 {
    assert 0 <= p[0] < n;
  } else if exists k :: 0 <= k < |p| && p[k] == n - 1 {
    var k :| 0 <= k < |p| && p[k] == n - 1;
    if exists k2 :: 0 <= k2 < |p| && k2 != k && p[k2] == n - 1 {
      var k2 :| 0 <= k2 < |p| && k2 != k && p[k2] == n - 1;
      if k < k2 {
        assert 0 <= k < k2 < |p| && p[k] == p[k2];
      } else {
        assert 0 <= k2 < k < |p| && p[k2] == p[k];
      }
    } else {
      var q := p[..k] + p[k + 1..];
      assert |q| == |p| - 1;
      forall t | 0 <= t < |q| ensures 0 <= q[t] < n - 1 {
        if t < k {
          assert q[t] == p[t];
        } else {
          assert q[t] == p[t + 1];
        }
      }
      Pigeonhole(q, n - 1);
      var i, j :| 0 <= i < j < |q| && q[i] == q[j];
      var i' := if i < k then i else i + 1;
      var j' := if j < k then j else j + 1;
      assert q[i] == p[i'];
      assert q[j] == p[j'];
      assert 0 <= i' < j' < |p| && p[i'] == p[j'];
    }
  } else {
    Pigeonhole(p, n - 1);
  }
}

lemma Shorten(graph: WeightedGraph, q: seq<int>)
  requires well_formed(graph)
  requires is_path(graph.adj, q)
  requires 0 <= q[0] < |graph.adj|
  ensures has_negative_cycle(graph.adj) ||
    exists q2: seq<int> {:trigger is_path(graph.adj, q2)} :: is_path(graph.adj, q2) && q2[0] == q[0] && q2[|q2| - 1] == q[|q| - 1]
      && |q2| <= |graph.adj| && path_weight(graph.adj, q2) <= path_weight(graph.adj, q)
  decreases |q|
{
  var g := graph.adj;
  var n := |g|;
  if |q| <= n {
    assert is_path(g, q);
  } else {
    PathInRange(graph, q);
    Pigeonhole(q, n);
    var i, j :| 0 <= i < j < |q| && q[i] == q[j];
    SuffixPath(g, q, i);
    var s := q[i..];
    PrefixPath(g, s, j - i + 1);
    var c := s[..j - i + 1];
    assert c[0] == q[i];
    assert c[|c| - 1] == q[j];
    if path_weight(g, c) < 0 {
      assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
    } else {
      var q2 := q[..i + 1] + q[j + 1..];
      assert |q2| == |q| - (j - i);
      forall t | 0 <= t < |q2| - 1 ensures connected(g, q2[t], q2[t + 1]) {
        if t < i {
          assert q2[t] == q[t] && q2[t + 1] == q[t + 1];
          assert connected(g, q[t], q[t + 1]);
        } else {
          var t2 := t - i + j;
          if t == i {
            assert q2[t] == q[i];
          } else {
            assert q2[t] == q[j + 1..][t - (i + 1)];
          }
          assert q2[t + 1] == q[j + 1..][t + 1 - (i + 1)];
          assert q2[t] == q[t2] && q2[t + 1] == q[t2 + 1];
          assert connected(g, q[t2], q[t2 + 1]);
        }
      }
      assert is_path(g, q2);
      forall t | 0 <= t < |q| - j ensures q2[i + t] == q[j + t] {
        if t == 0 {
          assert q2[i] == q[i];
        } else {
          assert q2[i + t] == q[j + 1..][t - 1];
        }
      }
      assert q2[i..] == q[j..];
      assert q2[..i + 1] == q[..i + 1];
      SplitWeight(g, q, i);
      SplitWeight(g, s, j - i);
      assert s[j - i..] == q[j..];
      SplitWeight(g, q2, i);
      assert path_weight(g, q2) <= path_weight(g, q);
      assert q2[0] == q[0];
      var tl := |q| - 1 - j;
      assert q2[i + tl] == q[j + tl];
      assert q2[|q2| - 1] == q[|q| - 1];
      Shorten(graph, q2);
      if !has_negative_cycle(g) {
        var q3 :| is_path(g, q3) && q3[0] == q2[0] && q3[|q3| - 1] == q2[|q2| - 1]
          && |q3| <= |g| && path_weight(g, q3) <= path_weight(g, q2);
        assert is_path(g, q3) && q3[0] == q[0] && q3[|q3| - 1] == q[|q| - 1]
          && |q3| <= |g| && path_weight(g, q3) <= path_weight(g, q);
      }
    }
  }
}

