lemma RoundLemma(graph: WeightedGraph, start: int, old_dist: seq<Option<int>>, dist: seq<Option<int>>, k: int)
  requires well_formed(graph)
  requires k >= 0
  requires |dist| == |graph.adj| && |old_dist| == |graph.adj|
  requires LowerBound(graph.adj, start, old_dist, k)
  requires Le(dist, old_dist)
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| ==> EdgeOk(graph.adj, old_dist, dist, u, i)
  ensures LowerBound(graph.adj, start, dist, k + 1)
{
  var g := graph.adj;
  forall q: seq<int> | is_path(g, q) && q[0] == start && |q| <= k + 2
    ensures 0 <= q[|q| - 1] < |dist| && dist[q[|q| - 1]].Some? && dist[q[|q| - 1]].value <= path_weight(g, q)
  {
    if |q| <= k + 1 {
      assert 0 <= q[|q| - 1] < |old_dist| && old_dist[q[|q| - 1]].Some? && old_dist[q[|q| - 1]].value <= path_weight(g, q);
    } else {
      PrefixPath(g, q, |q| - 1);
      var r := q[..|q| - 1];
      assert is_path(g, r);
      assert r[0] == start;
      assert |r| <= k + 1;
      assert 0 <= r[|r| - 1] < |old_dist| && old_dist[r[|r| - 1]].Some? && old_dist[r[|r| - 1]].value <= path_weight(g, r);
      var x := |q| - 2;
      assert connected(g, q[x], q[x + 1]);
      var u := q[x];
      var v := q[x + 1];
      assert r[|r| - 1] == u;
      var w :| has_edge(g, u, v, w);
      var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
      EdgeWeight(graph, u, j);
      assert EdgeOk(g, old_dist, dist, u, j);
      assert v == q[|q| - 1];
      assert path_weight(g, q) == path_weight(g, r) + get_edge_weight(g, q[|q| - 2], q[|q| - 1]);
    }
  }
}

