  (rd[u].Some? ==> dist[adj[u][i].0].Some? && dist[adj[u][i].0].value <= rd[u].value + adj[u][i].1)
}

ghost predicate Le(a: seq<Option<int>>, b: seq<Option<int>>) {
  |a| == |b| &&
  forall v :: 0 <= v < |b| && b[v].Some? ==> a[v].Some? && a[v].value <= b[v].value
}

