    assert r[|r| - 1] == u;
    var w :| has_edge(g, u, v, w);
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
    EdgeWeight(graph, u, j);
    assert EdgeOk(g, dist, dist, u, j);
