lemma NegCycleLemma(graph: WeightedGraph, start: int, dist: seq<Option<int>>, paths: seq<seq<int>>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |dist| == |graph.adj|
  requires WitnessInv(graph.adj, start, dist, paths)
  requires LowerBound(graph.adj, start, dist, |graph.adj| - 1)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires 0 <= graph.adj[u][i].0 < |dist|
  requires dist[u].Some?
  requires dist[graph.adj[u][i].0].None? || dist[u].value + graph.adj[u][i].1 < dist[graph.adj[u][i].0].value
  ensures has_negative_cycle(view(graph))
{
  var g: seq<seq<(int, int)>> := graph.adj;
  assert view(graph) == g;
  var v: int := g[u][i].0;
  AppendPath(graph, paths[u], u, i);
  var q := paths[u] + [v];
  assert q[0] == start;
  Shorten(graph, q);
  if !has_negative_cycle(g) {
    var q2 :| is_path(g, q2) && q2[0] == q[0] && q2[|q2| - 1] == q[|q| - 1]
      && |q2| <= |g| && path_weight(g, q2) <= path_weight(g, q);
    assert q2[0] == start && |q2| <= (|g| - 1) + 1;
    assert 0 <= q2[|q2| - 1] < |dist| && dist[q2[|q2| - 1]].Some? && dist[q2[|q2| - 1]].value <= path_weight(g, q2);
    assert q2[|q2| - 1] == v;
    assert false;
  }
}

lemma FinalLemma(graph: WeightedGraph, start: int, dist: seq<Option<int>>, paths: seq<seq<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |dist| == |graph.adj|
  requires WitnessInv(graph.adj, start, dist, paths)
  requires dist[start].Some? && dist[start].value <= 0
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| ==> EdgeOk(graph.adj, dist, dist, u, i)
  ensures forall v: int :: 0 <= v < size(graph) ==> (
                match dist[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
{
  var g: seq<seq<(int, int)>> := graph.adj;
  assert view(graph) == g;
  assert size(graph) == |g|;
  forall v: int | 0 <= v < size(graph)
    ensures (match dist[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                })
