lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var wi: int := g[u][i].1;
  assert has_edge(g, u, v, wi);
  forall w | has_edge(g, u, v, w) ensures w == wi {
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
  var r := get_edge_weight(g, u, v);
  assert has_edge(g, u, v, r);
}

lemma PrefixPath(g: seq<seq<(int, int)>>, p: seq<int>, b: int)
  requires is_path(g, p)
  requires 1 <= b <= |p|
  ensures is_path(g, p[..b])
{
  var s := p[..b];
  forall j | 0 <= j < |s| - 1 ensures connected(g, s[j], s[j + 1]) {
    assert s[j] == p[j] && s[j + 1] == p[j + 1];
    assert connected(g, p[j], p[j + 1]);
  }
}

lemma SuffixPath(g: seq<seq<(int, int)>>, p: seq<int>, a: int)
  requires is_path(g, p)
  requires 0 <= a < |p|
  ensures is_path(g, p[a..])
{
  var s := p[a..];
  forall j | 0 <= j < |s| - 1 ensures connected(g, s[j], s[j + 1]) {
    var t := a + j;
    assert s[j] == p[t] && s[j + 1] == p[t + 1];
    assert connected(g, p[t], p[t + 1]);
  }
}

lemma AppendPath(graph: WeightedGraph, p: seq<int>, u: int, i: int)
  requires well_formed(graph)
  requires is_path(graph.adj, p) && p[|p| - 1] == u
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures var q := p + [graph.adj[u][i].0];
    is_path(graph.adj, q) && q[0] == p[0] && q[|q| - 1] == graph.adj[u][i].0
    && path_weight(graph.adj, q) == path_weight(graph.adj, p) + graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var q := p + [v];
  assert has_edge(g, u, v, g[u][i].1);
  assert connected(g, u, v);
  forall j | 0 <= j < |q| - 1 ensures connected(g, q[j], q[j + 1]) {
    if j < |p| - 1 {
      assert q[j] == p[j] && q[j + 1] == p[j + 1];
      assert connected(g, p[j], p[j + 1]);
    } else {
      assert q[j] == u && q[j + 1] == v;
    }
  }
  assert is_path(g, q);
  assert q[..|q| - 1] == p;
  EdgeWeight(graph, u, i);
  assert q[|q| - 2] == u && q[|q| - 1] == v;
  assert path_weight(g, q) == path_weight(g, q[..|q| - 1]) + get_edge_weight(g, q[|q| - 2], q[|q| - 1]);
}

lemma SplitWeight(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
  requires 0 <= k < |p|
  ensures path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, p[k..])
  decreases |p|
{
  if k == |p| - 1 {
    assert p[..k + 1] == p;
    assert |p[k..]| == 1;
  } else {
    var r := p[..|p| - 1];
    SplitWeight(g, r, k);
    assert r[..k + 1] == p[..k + 1];
    var s := p[k..];
    assert |s| >= 2;
    assert s[..|s| - 1] == r[k..];
    assert s[|s| - 2] == p[|p| - 2];
    assert s[|s| - 1] == p[|p| - 1];
    assert path_weight(g, s) == path_weight(g, s[..|s| - 1]) + get_edge_weight(g, s[|s| - 2], s[|s| - 1]);
    assert path_weight(g, p) == path_weight(g, r) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma PathInRange(graph: WeightedGraph, p: seq<int>)
  requires well_formed(graph)
  requires is_path(graph.adj, p)
  requires 0 <= p[0] < |graph.adj|
  ensures forall j :: 0 <= j < |p| ==> 0 <= p[j] < |graph.adj|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  forall j | 0 <= j < |p| ensures 0 <= p[j] < |g| {
    if j > 0 {
      var x := j - 1;
      assert connected(g, p[x], p[x + 1]);
      var w :| has_edge(g, p[x], p[x + 1], w);
      var t :| 0 <= p[x] < |g| && 0 <= t < |g[p[x]]| && g[p[x]][t].0 == p[x + 1] && g[p[x]][t].1 == w;
      assert 0 <= g[p[x]][t].0 < |g|;
    }
  }
}

lemma Pigeonhole(p: seq<int>, n: nat)
  requires forall i :: 0 <= i < |p| ==> 0 <= p[i] < n
  requires |p| > n
  ensures exists i, j :: 0 <= i < j < |p| && p[i] == p[j]
  decreases n
{
  if n == 0 {
    assert 0 <= p[0] < n;
  } else if exists k :: 0 <= k < |p| && p[k] == n - 1 {
    var k :| 0 <= k < |p| && p[k] == n - 1;
    if exists k2 :: 0 <= k2 < |p| && k2 != k && p[k2] == n - 1 {
      var k2 :| 0 <= k2 < |p| && k2 != k && p[k2] == n - 1;
      if k < k2 {
        assert 0 <= k < k2 < |p| && p[k] == p[k2];
      } else {
        assert 0 <= k2 < k < |p| && p[k2] == p[k];
      }
    } else {
      var q := p[..k] + p[k + 1..];
      assert |q| == |p| - 1;
      forall t | 0 <= t < |q| ensures 0 <= q[t] < n - 1 {
        if t < k {
          assert q[t] == p[t];
        } else {
          assert q[t] == p[t + 1];
        }
      }
      Pigeonhole(q, n - 1);
      var i, j :| 0 <= i < j < |q| && q[i] == q[j];
      var i' := if i < k then i else i + 1;
      var j' := if j < k then j else j + 1;
      assert q[i] == p[i'];
      assert q[j] == p[j'];
      assert 0 <= i' < j' < |p| && p[i'] == p[j'];
    }
  } else {
    Pigeonhole(p, n - 1);
  }
}

lemma CutPath(g: seq<seq<(int, int)>>, q: seq<int>, i: int, j: int)
  requires is_path(g, q)
  requires 0 <= i < j < |q| && q[i] == q[j]
  ensures var q2 := q[..i + 1] + q[j + 1..];
    is_path(g, q2) && q2[0] == q[0] && q2[|q2| - 1] == q[|q| - 1] && |q2| == |q| - (j - i)
{
  var q2 := q[..i + 1] + q[j + 1..];
  assert |q2| == |q| - (j - i);
  forall t | 0 <= t < |q2| - 1 ensures connected(g, q2[t], q2[t + 1]) {
    if t < i {
      assert q2[t] == q[t] && q2[t + 1] == q[t + 1];
      assert connected(g, q[t], q[t + 1]);
    } else {
      var t2 := t - i + j;
      if t == i {
        assert q2[t] == q[i];
      } else {
        assert q2[t] == q[j + 1..][t - (i + 1)];
      }
      assert q2[t + 1] == q[j + 1..][t + 1 - (i + 1)];
      assert q2[t] == q[t2] && q2[t + 1] == q[t2 + 1];
      assert connected(g, q[t2], q[t2 + 1]);
    }
  }
  assert q2[0] == q[0];
  if j + 1 < |q| {
    assert q2[|q2| - 1] == q[j + 1..][|q| - j - 2];
  } else {
    assert q2[|q2| - 1] == q[i];
  }
}

lemma CutCycle(g: seq<seq<(int, int)>>, q: seq<int>, i: int, j: int)
  requires is_path(g, q)
  requires 0 <= i < j < |q| && q[i] == q[j]
  ensures var c := q[i..j + 1];
    is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1]
{
  SuffixPath(g, q, i);
  var s := q[i..];
  PrefixPath(g, s, j - i + 1);
  assert s[..j - i + 1] == q[i..j + 1];
  var c := q[i..j + 1];
  assert c[0] == q[i];
  assert c[|c| - 1] == q[j];
}

lemma CutWeight(g: seq<seq<(int, int)>>, q: seq<int>, i: int, j: int)
  requires 0 <= i < j < |q| && q[i] == q[j]
  ensures path_weight(g, q) == path_weight(g, q[..i + 1] + q[j + 1..]) + path_weight(g, q[i..j + 1])
{
  SplitWeight(g, q, i);
  var s := q[i..];
  SplitWeight(g, s, j - i);
  assert s[..j - i + 1] == q[i..j + 1];
  assert s[j - i..] == q[j..];
  var q2 := q[..i + 1] + q[j + 1..];
  SplitWeight(g, q2, i);
  assert q2[..i + 1] == q[..i + 1];
  assert |q2[i..]| == |q[j..]|;
  forall t | 0 <= t < |q| - j ensures q2[i..][t] == q[j..][t] {
    assert q2[i..][t] == q2[i + t];
    assert q[j..][t] == q[j + t];
    if t == 0 {
      assert q2[i] == q[i];
    } else {
      assert q2[i + t] == q[j + 1..][t - 1];
    }
  }
  assert q2[i..] == q[j..];
}

lemma Shorten(graph: WeightedGraph, q: seq<int>)
  requires well_formed(graph)
  requires is_path(graph.adj, q)
  requires 0 <= q[0] < |graph.adj|
  ensures has_negative_cycle(graph.adj) ||
    exists q2: seq<int> {:trigger is_path(graph.adj, q2)} :: is_path(graph.adj, q2) && q2[0] == q[0] && q2[|q2| - 1] == q[|q| - 1]
      && |q2| <= |graph.adj| && path_weight(graph.adj, q2) <= path_weight(graph.adj, q)
  decreases |q|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var n := |g|;
  if |q| <= n {
    assert is_path(g, q);
  } else {
    PathInRange(graph, q);
    Pigeonhole(q, n);
    var i, j :| 0 <= i < j < |q| && q[i] == q[j];
    CutCycle(g, q, i, j);
    CutPath(g, q, i, j);
    CutWeight(g, q, i, j);
    var c := q[i..j + 1];
    var q2 := q[..i + 1] + q[j + 1..];
    if path_weight(g, c) < 0 {
      assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
    } else {
      assert path_weight(g, q2) <= path_weight(g, q);
      Shorten(graph, q2);
      if !has_negative_cycle(g) {
        var q3 :| is_path(g, q3) && q3[0] == q2[0] && q3[|q3| - 1] == q2[|q2| - 1]
          && |q3| <= |g| && path_weight(g, q3) <= path_weight(g, q2);
        assert is_path(g, q3) && q3[0] == q[0] && q3[|q3| - 1] == q[|q| - 1]
          && |q3| <= |g| && path_weight(g, q3) <= path_weight(g, q);
      }
    }
  }
}

lemma WitnessUpdate(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, paths: seq<seq<int>>, v: int, d: int, p: seq<int>)
  requires WitnessInv(g, start, dist, paths)
  requires 0 <= v < |dist|
  requires is_path(g, p) && p[0] == start && p[|p| - 1] == v && path_weight(g, p) == d
  ensures WitnessInv(g, start, dist[v := Some(d)], paths[v := p])
{
  var nd := dist[v := Some(d)];
  var np := paths[v := p];
  forall x | 0 <= x < |nd| && nd[x].Some?
    ensures is_path(g, np[x]) && np[x][0] == start && np[x][|np[x]| - 1] == x && path_weight(g, np[x]) == nd[x].value
  {
    if x == v {
    } else {
      assert nd[x] == dist[x] && np[x] == paths[x];
    }
  }
}

lemma RoundLemma(graph: WeightedGraph, start: int, old_dist: seq<Option<int>>, dist: seq<Option<int>>, k: int)
  requires well_formed(graph)
  requires k >= 0
  requires |dist| == |graph.adj| && |old_dist| == |graph.adj|
  requires LowerBound(graph.adj, start, old_dist, k)
  requires Le(dist, old_dist)
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| ==> EdgeOk(graph.adj, old_dist, dist, u, i)
  ensures LowerBound(graph.adj, start, dist, k + 1)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  forall q: seq<int> | is_path(g, q) && q[0] == start && |q| <= k + 2
    ensures 0 <= q[|q| - 1] < |dist| && dist[q[|q| - 1]].Some? && dist[q[|q| - 1]].value <= path_weight(g, q)
  {
    if |q| <= k + 1 {
      assert 0 <= q[|q| - 1] < |old_dist| && old_dist[q[|q| - 1]].Some? && old_dist[q[|q| - 1]].value <= path_weight(g, q);
    } else {
      PrefixPath(g, q, |q| - 1);
      var r := q[..|q| - 1];
      assert is_path(g, r);
      assert r[0] == start;
      assert |r| <= k + 1;
      assert 0 <= r[|r| - 1] < |old_dist| && old_dist[r[|r| - 1]].Some? && old_dist[r[|r| - 1]].value <= path_weight(g, r);
      var x := |q| - 2;
      assert connected(g, q[x], q[x + 1]);
      var u := q[x];
      var v := q[x + 1];
      assert r[|r| - 1] == u;
      var w :| has_edge(g, u, v, w);
      var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
      EdgeWeight(graph, u, j);
      assert EdgeOk(g, old_dist, dist, u, j);
      assert v == q[|q| - 1];
      assert path_weight(g, q) == path_weight(g, r) + get_edge_weight(g, q[|q| - 2], q[|q| - 1]);
    }
  }
}

lemma StartBound(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, k: int)
  requires LowerBound(g, start, dist, k)
  requires k >= 0
  ensures 0 <= start < |dist| && dist[start].Some? && dist[start].value <= 0
{
  var q := [start];
  assert is_path(g, q);
  assert q[0] == start && |q| <= k + 1;
  assert q[|q| - 1] == start;
  assert path_weight(g, q) == 0;
}

lemma Triangle(graph: WeightedGraph, start: int, dist: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires |dist| == |graph.adj|
  requires 0 <= start < |dist| && dist[start].Some? && dist[start].value <= 0
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| ==> EdgeOk(graph.adj, dist, dist, u, i)
  requires is_path(graph.adj, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |dist| && dist[p[|p| - 1]].Some? && dist[p[|p| - 1]].value <= path_weight(graph.adj, p)
  decreases |p|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  if |p| > 1 {
    PrefixPath(g, p, |p| - 1);
    var r := p[..|p| - 1];
    Triangle(graph, start, dist, r);
    var x := |p| - 2;
    assert connected(g, p[x], p[x + 1]);
    var u := p[x];
    var v := p[x + 1];
    assert r[|r| - 1] == u;
    var w :| has_edge(g, u, v, w);
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w;
    EdgeWeight(graph, u, j);
    assert EdgeOk(g, dist, dist, u, j);
    assert v == p[|p| - 1];
    assert path_weight(g, p) == path_weight(g, r) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma NegCycleLemma(graph: WeightedGraph, start: int, dist: seq<Option<int>>, paths: seq<seq<int>>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |dist| == |graph.adj|
  requires WitnessInv(graph.adj, start, dist, paths)
  requires LowerBound(graph.adj, start, dist, |graph.adj| - 1)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires 0 <= graph.adj[u][i].0 < |dist|
  requires dist[u].Some?
  requires dist[graph.adj[u][i].0].None? || dist[u].value + graph.adj[u][i].1 < dist[graph.adj[u][i].0].value
  ensures has_negative_cycle(view(graph))
{
  var g: seq<seq<(int, int)>> := graph.adj;
  assert view(graph) == g;
  var v: int := g[u][i].0;
  AppendPath(graph, paths[u], u, i);
  var q := paths[u] + [v];
  assert q[0] == start;
  Shorten(graph, q);
  if !has_negative_cycle(g) {
    var q2 :| is_path(g, q2) && q2[0] == q[0] && q2[|q2| - 1] == q[|q| - 1]
      && |q2| <= |g| && path_weight(g, q2) <= path_weight(g, q);
    assert q2[0] == start && |q2| <= (|g| - 1) + 1;
    assert 0 <= q2[|q2| - 1] < |dist| && dist[q2[|q2| - 1]].Some? && dist[q2[|q2| - 1]].value <= path_weight(g, q2);
    assert q2[|q2| - 1] == v;
    assert false;
  }
}

lemma FinalLemma(graph: WeightedGraph, start: int, dist: seq<Option<int>>, paths: seq<seq<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |dist| == |graph.adj|
  requires WitnessInv(graph.adj, start, dist, paths)
  requires dist[start].Some? && dist[start].value <= 0
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| ==> EdgeOk(graph.adj, dist, dist, u, i)
  ensures forall v: int :: 0 <= v < size(graph) ==> (
                match dist[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
{
  var g: seq<seq<(int, int)>> := graph.adj;
  assert view(graph) == g;
  assert size(graph) == |g|;
  forall v: int | 0 <= v < size(graph)
    ensures (match dist[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                })
  {
    if dist[v].Some? {
      var d := dist[v].value;
      assert is_path(g, paths[v]) && paths[v][0] == start && paths[v][|paths[v]| - 1] == v && path_weight(g, paths[v]) == d;
      forall p: seq<int> | is_path(g, p) && p[0] == start && p[|p| - 1] == v
        ensures path_weight(g, p) >= d
      {
        Triangle(graph, start, dist, p);
      }
      assert is_shortest_dist(g, start, v, d);
    } else {
      forall p: seq<int> | is_path(g, p) && p[0] == start && p[|p| - 1] == v
        ensures false
      {
        Triangle(graph, start, dist, p);
      }
    }
  }
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
  var n := |graph.adj|;
  ghost var g: seq<seq<(int, int)>> := graph.adj;
  var dist: seq<Option<int>> := seq(n, (v: int) => if v == start then Some(0) else None);
  ghost var paths: seq<seq<int>> := seq(n, (v: int) => [start]);

  assert is_path(g, [start]);
  assert path_weight(g, [start]) == 0;
  assert dist[start] == Some(0);
  assert WitnessInv(g, start, dist, paths);
  forall q: seq<int> | is_path(g, q) && q[0] == start && |q| <= 0 + 1
    ensures 0 <= q[|q| - 1] < |dist| && dist[q[|q| - 1]].Some? && dist[q[|q| - 1]].value <= path_weight(g, q)
  {
    assert |q| == 1;
    assert q[|q| - 1] == start;
  }
  assert LowerBound(g, start, dist, 0);

  var k := 0;
  while k < n - 1
    invariant 0 <= k <= n - 1
    invariant |dist| == n
    invariant WitnessInv(g, start, dist, paths)
    invariant LowerBound(g, start, dist, k)
    decreases n - 1 - k
  {
    ghost var snap := dist;
    var u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant |dist| == n
      invariant WitnessInv(g, start, dist, paths)
      invariant Le(dist, snap)
      invariant forall u2, i2 :: 0 <= u2 < u && 0 <= i2 < |g[u2]| ==> EdgeOk(g, snap, dist, u2, i2)
      decreases n - u
    {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant |dist| == n
        invariant WitnessInv(g, start, dist, paths)
        invariant Le(dist, snap)
        invariant forall u2, i2 :: 0 <= u2 < u && 0 <= i2 < |g[u2]| ==> EdgeOk(g, snap, dist, u2, i2)
        invariant forall i2 :: 0 <= i2 < i ==> EdgeOk(g, snap, dist, u, i2)
        decreases |graph.adj[u]| - i
      {
        var v: int := graph.adj[u][i].0;
        var w: int := graph.adj[u][i].1;
        assert 0 <= v < n;
        ghost var pre := dist;
        if dist[u].Some? && (dist[v].None? || dist[u].value + w < dist[v].value) {
          AppendPath(graph, paths[u], u, i);
          WitnessUpdate(g, start, dist, paths, v, dist[u].value + w, paths[u] + [v]);
          paths := paths[v := paths[u] + [v]];
          dist := dist[v := Some(dist[u].value + w)];
        }
        assert Le(dist, pre);
        LeTrans(dist, pre, snap);
        forall u2, i2 | 0 <= u2 < u && 0 <= i2 < |g[u2]| ensures EdgeOk(g, snap, dist, u2, i2) {
          EdgeOkMono(g, snap, pre, dist, u2, i2);
        }
        forall i2 | 0 <= i2 < i ensures EdgeOk(g, snap, dist, u, i2) {
          EdgeOkMono(g, snap, pre, dist, u, i2);
        }
        assert EdgeOk(g, snap, dist, u, i);
        i := i + 1;
      }
      u := u + 1;
    }
    RoundLemma(graph, start, snap, dist, k);
    k := k + 1;
  }

  StartBound(g, start, dist, k);

  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant forall u2, i2 :: 0 <= u2 < u && 0 <= i2 < |g[u2]| ==> EdgeOk(g, dist, dist, u2, i2)
    decreases n - u
  {
    var i := 0;
    while i < |graph.adj[u]|
      invariant 0 <= i <= |graph.adj[u]|
      invariant forall u2, i2 :: 0 <= u2 < u && 0 <= i2 < |g[u2]| ==> EdgeOk(g, dist, dist, u2, i2)
      invariant forall i2 :: 0 <= i2 < i ==> EdgeOk(g, dist, dist, u, i2)
      decreases |graph.adj[u]| - i
    {
      var v: int := graph.adj[u][i].0;
      var w: int := graph.adj[u][i].1;
      assert 0 <= v < n;
      if dist[u].Some? && (dist[v].None? || dist[u].value + w < dist[v].value) {
        NegCycleLemma(graph, start, dist, paths, u, i);
        res := None;
        return;
      }
      assert EdgeOk(g, dist, dist, u, i);
      i := i + 1;
    }
    u := u + 1;
  }
  FinalLemma(graph, start, dist, paths);
  res := Some(dist);
}
