method binary_search_lower_bound(s: seq<int>, target: int) returns (result: int)
    requires |s| <= 0x7FFFFFFF
    requires is_sorted(s)
    ensures result >= 0
    ensures result <= |s|
    ensures forall i {:trigger s[i]} :: 0 <= i < result ==> s[i] < target
    ensures forall i {:trigger s[i]} :: result <= i < |s| ==> s[i] >= target
{
    var lo := 0;
    var hi := |s|;
    while lo < hi
        invariant 0 <= lo <= hi <= |s|
        invariant forall i {:trigger s[i]} :: 0 <= i < lo ==> s[i] < target
        invariant forall i {:trigger s[i]} :: hi <= i < |s| ==> s[i] >= target
        decreases hi - lo
    {
        var mid := lo + (hi - lo) / 2;
        if s[mid] < target {
            forall i | 0 <= i <= mid
                ensures s[i] < target
            {
                assert s[i] <= s[mid];
            }
            lo := mid + 1;
        } else {
            forall i | mid <= i < |s|
                ensures s[i] >= target
            {
                assert s[mid] <= s[i];
            }
            hi := mid;
        }
    }
    result := lo;
}

