}

lemma bf_has_edge_bounds(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    w: int)
  requires bf_well_formed(g)
  requires has_edge(g, u, v, w)
  ensures 0 <= u < |g|
  ensures 0 <= v < |g|
{
  var i :| 0 <= u < |g| &&
           0 <= i < |g[u]| &&
           g[u][i].0 == v &&
           g[u][i].1 == w;
}

lemma bf_edge_weight(
    g: seq<seq<(int, int)>>,
    u: int,
    i: int)
  requires bf_well_formed(g)
  requires 0 <= u < |g|
  requires 0 <= i < |g[u]|
  ensures has_edge(g, u, g[u][i].0, g[u][i].1)
  ensures get_edge_weight(g, u, g[u][i].0) == g[u][i].1
{
  var v := g[u][i].0;
  var w := g[u][i].1;
  assert has_edge(g, u, v, w);
  assert exists x: int :: has_edge(g, u, v, x);
  assert has_edge(g, u, v, get_edge_weight(g, u, v));

  var j :| 0 <= u < |g| &&
           0 <= j < |g[u]| &&
           g[u][j].0 == v &&
           g[u][j].1 == get_edge_weight(g, u, v);

  if i != j {
    assert g[u][i].0 != g[u][j].0;
    assert false;
  }
}

