      g, before, v, 0, before[v], previousValue);
    assert after[v] ==
      bf_all_rows(g, before, v, 0, before[v]);
    assert currentValue <= previousValue;

    bf_distances_good(g, None, |g|, v);
    var wp :| is_path(g, wp) &&
              bf_correct_start(None, wp) &&
              wp[|wp| - 1] == v &&
