  requires bf_well_formed(g)
  requires has_edge(g, u, v, w)
  ensures 0 <= u < |g|
  ensures 0 <= v < |g|
{
  var i :| 0 <= u < |g| &&
           0 <= i < |g[u]| &&
           g[u][i].0 == v &&
           g[u][i].1 == w;
}

lemma bf_edge_weight(
    g: seq<seq<(int, int)>>,
    u: int,
    i: int)
  requires bf_well_formed(g)
  requires 0 <= u < |g|
  requires 0 <= i < |g[u]|
  ensures has_edge(g, u, g[u][i].0, g[u][i].1)
  ensures get_edge_weight(g, u, g[u][i].0) == g[u][i].1
{
  var v := g[u][i].0;
  var w := g[u][i].1;
  assert has_edge(g, u, v, w);
  assert exists x: int :: has_edge(g, u, v, x);
  assert has_edge(g, u, v, get_edge_weight(g, u, v));

  var j :| 0 <= u < |g| &&
           0 <= j < |g[u]| &&
           g[u][j].0 == v &&
           g[u][j].1 == get_edge_weight(g, u, v);

  if i != j {
    assert g[u][i].0 != g[u][j].0;
    assert false;
  }
}

lemma bf_path_prefix(g: seq<seq<(int, int)>>, p: seq<int>)
  requires is_path(g, p)
  requires |p| > 1
  ensures is_path(g, p[..|p| - 1])
  ensures p[..|p| - 1][0] == p[0]
  ensures p[..|p| - 1][|p[..|p| - 1]| - 1] == p[|p| - 2]
{
}

lemma bf_append_path(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    v: int,
    w: int)
  requires is_path(g, p)
  requires has_edge(g, p[|p| - 1], v, w)
  requires get_edge_weight(g, p[|p| - 1], v) == w
  ensures is_path(g, p + [v])
  ensures (p + [v])[0] == p[0]
  ensures (p + [v])[|p + [v]| - 1] == v
  ensures path_weight(g, p + [v]) == path_weight(g, p) + w
{
  assert connected(g, p[|p| - 1], v);
  assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma bf_extend_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    previous: Option<int>,
    u: int,
    v: int,
    w: int,
    k: nat)
  requires bf_good(g, source, u, k, previous)
  requires has_edge(g, u, v, w)
  requires get_edge_weight(g, u, v) == w
  ensures bf_good(g, source, v, k + 1, bf_add(previous, w))
{
  match previous
  case None =>
  case Some(d) =>
    var p :| is_path(g, p) &&
             bf_correct_start(source, p) &&
             p[|p| - 1] == u &&
             |p| <= k + 1 &&
             path_weight(g, p) == d;
    bf_append_path(g, p, v, w);
}

lemma bf_min_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    v: int,
    k: nat,
    a: Option<int>,
    b: Option<int>)
  requires bf_good(g, source, v, k, a)
  requires bf_good(g, source, v, k, b)
  ensures bf_good(g, source, v, k, bf_min(a, b))
{
}

lemma bf_row_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    previous: seq<Option<int>>,
    u: nat,
    v: int,
    i: nat,
    best: Option<int>,
    k: nat)
  requires bf_well_formed(g)
  requires |previous| == |g|
  requires u < |g|
  requires i <= |g[u]|
  requires bf_good(g, source, v, k + 1, best)
  requires forall x: int :: 0 <= x < |g| ==>
    bf_good(g, source, x, k, previous[x])
  ensures bf_good(
    g, source, v, k + 1,
    bf_row(g, previous, u, v, i, best))
  decreases |g[u]| - i
{
  if i < |g[u]| {
    var e := g[u][i];
    var candidate :=
      if e.0 == v then bf_add(previous[u], e.1) else None;

    if e.0 == v {
      bf_edge_weight(g, u, i);
      bf_extend_good(
        g, source, previous[u], u, v, e.1, k);
    }

    bf_min_good(g, source, v, k + 1, best, candidate);
    bf_row_good(
      g, source, previous, u, v, i + 1,
      bf_min(best, candidate), k);
  }
}

lemma bf_all_rows_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    previous: seq<Option<int>>,
    v: int,
    u: nat,
    best: Option<int>,
    k: nat)
  requires bf_well_formed(g)
  requires |previous| == |g|
  requires u <= |g|
  requires bf_good(g, source, v, k + 1, best)
  requires forall x: int :: 0 <= x < |g| ==>
    bf_good(g, source, x, k, previous[x])
  ensures bf_good(
    g, source, v, k + 1,
    bf_all_rows(g, previous, v, u, best))
  decreases |g| - u
{
  if u < |g| {
    bf_row_good(g, source, previous, u, v, 0, best, k);
    bf_all_rows_good(
      g, source, previous, v, u + 1,
      bf_row(g, previous, u, v, 0, best), k);
  }
}

lemma bf_distances_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    k: nat,
    v: int)
  requires bf_well_formed(g)
  requires 0 <= v < |g|
  requires source.None? ||
           (source.Some? && 0 <= source.value < |g|)
  ensures bf_good(g, source, v, k, bf_distances(g, source, k)[v])
  decreases k
{
  if k == 0 {
    match source
    case None =>
      assert is_path(g, [v]);
      assert bf_correct_start(source, [v]);
      assert path_weight(g, [v]) == 0;
    case Some(s) =>
      if v == s {
        assert is_path(g, [v]);
        assert bf_correct_start(source, [v]);
        assert path_weight(g, [v]) == 0;
      }
  } else {
    var previous := bf_distances(g, source, k - 1);

    forall x | 0 <= x < |g|
      ensures bf_good(g, source, x, k - 1, previous[x])
    {
      bf_distances_good(g, source, k - 1, x);
    }

    assert bf_good(g, source, v, k, previous[v]);
    bf_all_rows_good(
      g, source, previous, v, 0, previous[v], k - 1);
  }
}

lemma bf_row_monotone(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    u: nat,
    v: int,
    i: nat,
    best: Option<int>,
    x: int)
  requires |previous| == |g|
  requires u < |g|
  requires i <= |g[u]|
  requires bf_le(best, x)
  ensures bf_le(bf_row(g, previous, u, v, i, best), x)
  decreases |g[u]| - i
{
  if i < |g[u]| {
    var e := g[u][i];
    var candidate :=
      if e.0 == v then bf_add(previous[u], e.1) else None;
    bf_min_preserves_left(best, candidate, x);
    bf_row_monotone(
      g, previous, u, v, i + 1,
      bf_min(best, candidate), x);
  }
}

lemma bf_all_rows_monotone(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    v: int,
    u: nat,
    best: Option<int>,
    x: int)
  requires |previous| == |g|
  requires u <= |g|
  requires bf_le(best, x)
  ensures bf_le(bf_all_rows(g, previous, v, u, best), x)
  decreases |g| - u
{
  if u < |g| {
    bf_row_monotone(g, previous, u, v, 0, best, x);
    bf_all_rows_monotone(
      g, previous, v, u + 1,
      bf_row(g, previous, u, v, 0, best), x);
  }
}

lemma bf_row_covers(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    u: nat,
    v: int,
    i: nat,
    best: Option<int>,
    j: int,
    d: int)
  requires |previous| == |g|
  requires u < |g|
  requires i <= j < |g[u]|
  requires g[u][j].0 == v
  requires previous[u] == Some(d)
  ensures bf_le(
    bf_row(g, previous, u, v, i, best),
    d + g[u][j].1)
  decreases |g[u]| - i
{
  var e := g[u][i];
  var candidate :=
    if e.0 == v then bf_add(previous[u], e.1) else None;

  if i == j {
    assert candidate == Some(d + g[u][j].1);
    bf_min_preserves_right(best, candidate, d + g[u][j].1);
    bf_row_monotone(
      g, previous, u, v, i + 1,
      bf_min(best, candidate), d + g[u][j].1);
  } else {
    bf_row_covers(
      g, previous, u, v, i + 1,
      bf_min(best, candidate), j, d);
  }
}

lemma bf_all_rows_covers(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    v: int,
    first: nat,
    best: Option<int>,
    u: int,
    i: int,
    d: int)
  requires |previous| == |g|
  requires first <= u < |g|
  requires 0 <= i < |g[u]|
  requires g[u][i].0 == v
  requires previous[u] == Some(d)
  ensures bf_le(
    bf_all_rows(g, previous, v, first, best),
    d + g[u][i].1)
  decreases |g| - first
{
  if first == u {
    bf_row_covers(g, previous, first, v, 0, best, i, d);
    bf_all_rows_monotone(
      g, previous, v, first + 1,
      bf_row(g, previous, first, v, 0, best),
      d + g[u][i].1);
  } else {
    bf_all_rows_covers(
      g, previous, v, first + 1,
      bf_row(g, previous, first, v, 0, best),
      u, i, d);
  }
}

lemma bf_path_vertices_bounded(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  requires bf_well_formed(g)
  requires is_path(g, p)
  requires |p| > 1
  ensures forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < |g|
{
  forall i | 0 <= i < |p|
    ensures 0 <= p[i] < |g|
  {
    if i < |p| - 1 {
      assert connected(g, p[i], p[i + 1]);
      var w :| has_edge(g, p[i], p[i + 1], w);
      bf_has_edge_bounds(g, p[i], p[i + 1], w);
    } else {
      assert i > 0;
      assert connected(g, p[i - 1], p[i]);
      var w :| has_edge(g, p[i - 1], p[i], w);
      bf_has_edge_bounds(g, p[i - 1], p[i], w);
    }
  }
}

lemma bf_distances_lower(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    k: nat,
    v: int,
    p: seq<int>)
  requires bf_well_formed(g)
  requires source.None? ||
           (source.Some? && 0 <= source.value < |g|)
  requires 0 <= v < |g|
  requires is_path(g, p)
  requires bf_correct_start(source, p)
  requires p[|p| - 1] == v
  requires |p| <= k + 1
  ensures bf_le(bf_distances(g, source, k)[v], path_weight(g, p))
  decreases k
{
  if k == 0 {
    assert |p| == 1;
    assert path_weight(g, p) == 0;
    match source
    case None =>
    case Some(s) =>
      assert p[0] == s;
      assert v == s;
  } else {
    var previous := bf_distances(g, source, k - 1);

    if |p| <= k {
      bf_distances_lower(g, source, k - 1, v, p);
      bf_all_rows_monotone(
        g, previous, v, 0, previous[v], path_weight(g, p));
    } else {
      assert |p| == k + 1;
      assert |p| > 1;

      var q := p[..|p| - 1];
      var u := p[|p| - 2];

      bf_path_prefix(g, p);
      bf_path_vertices_bounded(g, p);
      assert 0 <= u < |g|;
      assert bf_correct_start(source, q);
      bf_distances_lower(g, source, k - 1, u, q);

      var d :| previous[u] == Some(d) &&
               d <= path_weight(g, q);

      assert connected(g, u, v);
      var w :| has_edge(g, u, v, w);
      var i :| 0 <= u < |g| &&
               0 <= i < |g[u]| &&
               g[u][i].0 == v &&
               g[u][i].1 == w;

      bf_edge_weight(g, u, i);
      assert path_weight(g, p) == path_weight(g, q) + w;

      bf_all_rows_covers(
        g, previous, v, 0, previous[v], u, i, d);

      var answer := bf_distances(g, source, k)[v];
      assert bf_le(answer, d + w);
      assert d + w <= path_weight(g, p);
    }
  }
}

ghost function bf_values(p: seq<int>): set<int>
  decreases |p|
{
  if |p| == 0 then {}
  else {p[0]} + bf_values(p[1..])
}

ghost predicate bf_distinct(p: seq<int>)
  decreases |p|
{
  |p| == 0 ||
  (p[0] !in p[1..] && bf_distinct(p[1..]))
}

ghost function bf_range(n: nat): set<int>
  decreases n
{
  if n == 0 then {}
  else bf_range(n - 1) + {n - 1}
}

lemma bf_range_contains(n: nat, x: int)
  requires 0 <= x < n
  ensures x in bf_range(n)
  decreases n
{
  if x < n - 1 {
    bf_range_contains(n - 1, x);
  }
}

lemma bf_range_cardinality(n: nat)
  ensures |bf_range(n)| == n
  decreases n
{
  if n > 0 {
    bf_range_cardinality(n - 1);
    assert n - 1 !in bf_range(n - 1);
  }
}

lemma bf_values_subset_range(p: seq<int>, n: nat)
  requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
  ensures bf_values(p) <= bf_range(n)
  decreases |p|
{
  if |p| > 0 {
    bf_range_contains(n, p[0]);
    assert forall i: int :: 0 <= i < |p[1..]| ==>
      0 <= p[1..][i] < n;
    bf_values_subset_range(p[1..], n);
  }
}

lemma bf_notin_values(p: seq<int>, x: int)
  requires x !in p
  ensures x !in bf_values(p)
  decreases |p|
{
  if |p| > 0 {
    assert x != p[0];
    assert x !in p[1..];
    bf_notin_values(p[1..], x);
  }
}

lemma bf_distinct_cardinality(p: seq<int>)
  requires bf_distinct(p)
  ensures |bf_values(p)| == |p|
  decreases |p|
{
  if |p| > 0 {
    bf_distinct_cardinality(p[1..]);
    bf_notin_values(p[1..], p[0]);
    assert p[0] !in bf_values(p[1..]);
  }
}

lemma bf_distinct_bound(p: seq<int>, n: nat)
  requires bf_distinct(p)
  requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
  ensures |p| <= n
{
  bf_values_subset_range(p, n);
  bf_distinct_cardinality(p);
  bf_range_cardinality(n);
  assert |bf_values(p)| <= |bf_range(n)|;
}

lemma bf_duplicate_indices(p: seq<int>)
  requires !bf_distinct(p)
  ensures exists i: int, j: int ::
    0 <= i < j < |p| && p[i] == p[j]
  decreases |p|
{
  assert |p| > 0;
  if p[0] in p[1..] {
    assert exists j: int ::
      0 <= j < |p[1..]| && p[1..][j] == p[0];
    var j :| 0 <= j < |p[1..]| && p[1..][j] == p[0];
    assert p[j + 1] == p[0];
  } else {
    assert !bf_distinct(p[1..]);
    bf_duplicate_indices(p[1..]);
    var i, j :| 0 <= i < j < |p[1..]| &&
                    p[1..][i] == p[1..][j];
    assert p[i + 1] == p[j + 1];
  }
}

ghost function bf_join(a: seq<int>, b: seq<int>): seq<int>
  requires |a| > 0
  requires |b| > 0
  requires a[|a| - 1] == b[0]
{
  a + b[1..]
}

lemma bf_join_length(a: seq<int>, b: seq<int>)
  requires |a| > 0
  requires |b| > 0
  requires a[|a| - 1] == b[0]
  ensures |bf_join(a, b)| == |a| + |b| - 1
  ensures bf_join(a, b)[0] == a[0]
  ensures bf_join(a, b)[|bf_join(a, b)| - 1] == b[|b| - 1]
{
}

lemma bf_join_path(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
  requires is_path(g, a)
  requires is_path(g, b)
  requires a[|a| - 1] == b[0]
  ensures is_path(g, bf_join(a, b))
  decreases |b|
{
  if |b| > 1 {
    var prefix := b[..|b| - 1];
    bf_path_prefix(g, b);
    bf_join_path(g, a, prefix);
    assert bf_join(a, b)[..|bf_join(a, b)| - 1] ==
           bf_join(a, prefix);
    assert connected(g, b[|b| - 2], b[|b| - 1]);
  }
}

lemma bf_join_weight(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
  requires is_path(g, a)
  requires is_path(g, b)
  requires a[|a| - 1] == b[0]
  ensures path_weight(g, bf_join(a, b)) ==
          path_weight(g, a) + path_weight(g, b)
  decreases |b|
{
  if |b| == 1 {
    assert path_weight(g, b) == 0;
    assert bf_join(a, b) == a;
  } else {
    var prefix := b[..|b| - 1];
    bf_path_prefix(g, b);
    bf_join_path(g, a, prefix);
    bf_join_weight(g, a, prefix);
    assert bf_join(a, b)[..|bf_join(a, b)| - 1] ==
           bf_join(a, prefix);
  }
}

lemma bf_shorten_path(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  returns (q: seq<int>)
  requires bf_well_formed(g)
  requires is_path(g, p)
  requires |g| > 0
  requires |p| > |g|
  requires !has_negative_cycle(g)
  ensures is_path(g, q)
  ensures q[0] == p[0]
  ensures q[|q| - 1] == p[|p| - 1]
  ensures |q| < |p|
  ensures path_weight(g, q) <= path_weight(g, p)
{
  bf_path_vertices_bounded(g, p);

  if bf_distinct(p) {
    bf_distinct_bound(p, |g|);
    assert false;
  }

  bf_duplicate_indices(p);
  var i, j :| 0 <= i < j < |p| && p[i] == p[j];

  var a := p[..i + 1];
  var cycle := p[i..j + 1];
  var b := p[j..];

  assert is_path(g, a);
  assert is_path(g, cycle);
  assert is_path(g, b);
  assert cycle[0] == cycle[|cycle| - 1];
  assert |cycle| > 1;

  assert path_weight(g, cycle) >= 0 by {
    if path_weight(g, cycle) < 0 {
      assert has_negative_cycle(g);
      assert false;
    }
  }

  bf_join_path(g, a, cycle);
  bf_join_weight(g, a, cycle);
  bf_join_path(g, bf_join(a, cycle), b);
  bf_join_weight(g, bf_join(a, cycle), b);

  assert bf_join(bf_join(a, cycle), b) == p;

  q := bf_join(a, b);
  bf_join_path(g, a, b);
  bf_join_weight(g, a, b);
  bf_join_length(a, b);

  assert path_weight(g, p) ==
         path_weight(g, a) +
         path_weight(g, cycle) +
         path_weight(g, b);
  assert path_weight(g, q) ==
         path_weight(g, a) + path_weight(g, b);
}

lemma bf_reduce_path(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  returns (q: seq<int>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires is_path(g, p)
  requires !has_negative_cycle(g)
  ensures is_path(g, q)
  ensures q[0] == p[0]
  ensures q[|q| - 1] == p[|p| - 1]
  ensures |q| <= |g|
  ensures path_weight(g, q) <= path_weight(g, p)
  decreases |p|
{
  if |p| <= |g| {
    q := p;
  } else {
    var shorter := bf_shorten_path(g, p);
    q := bf_reduce_path(g, shorter);
  }
}

lemma bf_distances_all_total(
    g: seq<seq<(int, int)>>,
    k: nat,
    v: int)
  requires 0 <= v < |g|
  ensures bf_distances(g, None, k)[v].Some?
  decreases k
{
  if k > 0 {
    var previous := bf_distances(g, None, k - 1);
    bf_distances_all_total(g, k - 1, v);
    var d := previous[v].value;
    bf_all_rows_monotone(
      g, previous, v, 0, previous[v], d);
  }
}

lemma bf_stable_without_negative_cycle(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  ensures bf_distances(g, None, |g|) ==
          bf_distances(g, None, |g| - 1)
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  assert |before| == |g|;
  assert |after| == |g|;

  forall v | 0 <= v < |g|
    ensures after[v] == before[v]
  {
    bf_distances_all_total(g, |g| - 1, v);
    bf_distances_all_total(g, |g|, v);

    var previousValue := before[v].value;
    var currentValue := after[v].value;

    bf_all_rows_monotone(
      g, before, v, 0, before[v], previousValue);
    assert after[v] ==
      bf_all_rows(g, before, v, 0, before[v]);
    assert currentValue <= previousValue;

    bf_distances_good(g, None, |g|, v);
    var wp :| is_path(g, wp) &&
              bf_correct_start(None, wp) &&
              wp[|wp| - 1] == v &&
              |wp| <= |g| + 1 &&
              path_weight(g, wp) == currentValue;

    var q := bf_reduce_path(g, wp);
    bf_distances_lower(g, None, |g| - 1, v, q);
    assert previousValue <= path_weight(g, q);
    assert path_weight(g, q) <= currentValue;
    assert previousValue == currentValue;
  }

  assert after == before;
}

ghost predicate bf_potential_vertices(
    d: seq<Option<int>>,
    p: seq<int>) {
  forall j: int {:trigger d[p[j]]} ::
    0 <= j < |p| ==>
      0 <= p[j] < |d| && d[p[j]].Some?
}

ghost predicate bf_potential_edges(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>,
    p: seq<int>) {
  forall j: int
    {:trigger get_edge_weight(g, p[j], p[j + 1])} ::
    0 <= j < |p| - 1 ==>
      0 <= p[j] < |d| &&
      0 <= p[j + 1] < |d| &&
      d[p[j]].Some? &&
      d[p[j + 1]].Some? &&
      d[p[j + 1]].value <=
        d[p[j]].value +
        get_edge_weight(g, p[j], p[j + 1])
}

lemma bf_potential_prefix_vertices(
    d: seq<Option<int>>,
    p: seq<int>)
  requires |p| > 1
  requires bf_potential_vertices(d, p)
  ensures bf_potential_vertices(d, p[..|p| - 1])
{
  var q := p[..|p| - 1];
  forall j: int {:trigger d[q[j]]} | 0 <= j < |q|
    ensures 0 <= q[j] < |d| && d[q[j]].Some?
  {
    assert q[j] == p[j];
  }
}

lemma bf_potential_prefix_edges(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>,
    p: seq<int>)
  requires |p| > 1
  requires bf_potential_edges(g, d, p)
  ensures bf_potential_edges(g, d, p[..|p| - 1])
{
  var q := p[..|p| - 1];
  forall j: int
    {:trigger get_edge_weight(g, q[j], q[j + 1])}
    | 0 <= j < |q| - 1
    ensures
      0 <= q[j] < |d| &&
      0 <= q[j + 1] < |d| &&
      d[q[j]].Some? &&
      d[q[j + 1]].Some? &&
      d[q[j + 1]].value <=
        d[q[j]].value +
        get_edge_weight(g, q[j], q[j + 1])
  {
    assert q[j] == p[j];
    assert q[j + 1] == p[j + 1];
  }
