lemma bf_potential_path(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>,
    p: seq<int>)
  requires |d| == |g|
  requires is_path(g, p)
  requires bf_potential_vertices(d, p)
  requires bf_potential_edges(g, d, p)
  ensures d[p[|p| - 1]].value <=
    d[p[0]].value + path_weight(g, p)
  decreases |p|
{
  if |p| > 1 {
    var q := p[..|p| - 1];

    bf_path_prefix(g, p);
    bf_potential_prefix_vertices(d, p);
    bf_potential_prefix_edges(g, d, p);
    bf_potential_path(g, d, q);

    var lastEdge := |p| - 2;
    assert q[0] == p[0];
    assert q[|q| - 1] == p[lastEdge];

    assert 0 <= lastEdge < |p| - 1;
    assert d[p[lastEdge + 1]].value <=
      d[p[lastEdge]].value +
      get_edge_weight(g, p[lastEdge], p[lastEdge + 1]);

    assert path_weight(g, p) ==
      path_weight(g, q) +
      get_edge_weight(g, p[lastEdge], p[lastEdge + 1]);
  }
}

lemma bf_stability_excludes_negative_cycles(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures !has_negative_cycle(g)
{
  var d := bf_distances(g, None, |g| - 1);
  var next := bf_distances(g, None, |g|);

  assert |d| == |g|;
  assert |next| == |g|;

  forall u: int, i: int
    {:trigger g[u][i]}
    | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures
      d[g[u][i].0].Some? &&
      d[u].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
  {
    var v := g[u][i].0;
    assert 0 <= v < |g|;

    bf_distances_all_total(g, |g| - 1, u);
    bf_distances_all_total(g, |g| - 1, v);

    bf_all_rows_covers(
      g, d, v, 0, d[v], u, i, d[u].value);

    assert next[v] ==
      bf_all_rows(g, d, v, 0, d[v]);
    assert next == d;
    assert bf_le(d[v], d[u].value + g[u][i].1);
  }

  if has_negative_cycle(g) {
    var p :| is_path(g, p) &&
             |p| > 1 &&
             p[0] == p[|p| - 1] &&
             path_weight(g, p) < 0;

    bf_path_vertices_bounded(g, p);

    assert bf_potential_vertices(d, p) by {
      forall j: int {:trigger d[p[j]]} | 0 <= j < |p|
        ensures 0 <= p[j] < |d| && d[p[j]].Some?
      {
        assert 0 <= p[j] < |g|;
        bf_distances_all_total(g, |g| - 1, p[j]);
      }
    }

    assert bf_potential_edges(g, d, p) by {
      forall j: int
        {:trigger get_edge_weight(g, p[j], p[j + 1])}
        | 0 <= j < |p| - 1
        ensures
          0 <= p[j] < |d| &&
          0 <= p[j + 1] < |d| &&
          d[p[j]].Some? &&
          d[p[j + 1]].Some? &&
          d[p[j + 1]].value <=
            d[p[j]].value +
            get_edge_weight(g, p[j], p[j + 1])
      {
        assert connected(g, p[j], p[j + 1]);
        var w :| has_edge(g, p[j], p[j + 1], w);
        var i :| 0 <= p[j] < |g| &&
                 0 <= i < |g[p[j]]| &&
                 g[p[j]][i].0 == p[j + 1] &&
                 g[p[j]][i].1 == w;

        bf_edge_weight(g, p[j], i);

        assert d[p[j + 1]].value <=
          d[p[j]].value + g[p[j]][i].1;
        assert get_edge_weight(g, p[j], p[j + 1]) ==
          g[p[j]][i].1;
      }
    }

    bf_potential_path(g, d, p);

    var initialPotential := d[p[0]].value;
    assert p[0] == p[|p| - 1];
    assert initialPotential <=
      initialPotential + path_weight(g, p);
    assert false;
  }
}

method bellman_ford(
    graph: WeightedGraph,
    start: int)
    returns (res: Option<seq<Option<int>>>)
  requires well_formed(graph)
  requires 0 <= start < size(graph)
  requires weights_and_size_bounded(view(graph))
  ensures match res {
    case Some(dists) =>
      |dists| == size(graph) &&
      forall v: int :: 0 <= v < size(graph) ==> (
        match dists[v] {
          case Some(d) =>
            is_shortest_dist(view(graph), start, v, d)
          case None =>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
              (is_path(view(graph), p) &&
               p[0] == start &&
               p[|p| - 1] == v) ==> false
        }
      )
    case None =>
      has_negative_cycle(view(graph))
  }
{
  var g := graph.adj;
  var n := |g|;

  bf_view_well_formed(graph);
  assert n > 0;

  var detectorBefore := bf_distances(g, None, n - 1);
  var detectorAfter := bf_distances(g, None, n);

  if detectorAfter != detectorBefore {
    if !has_negative_cycle(g) {
      bf_stable_without_negative_cycle(g);
      assert detectorAfter == detectorBefore;
      assert false;
    }
    res := None;
  } else {
    bf_stability_excludes_negative_cycles(g);
    assert !has_negative_cycle(g);

    var distances := bf_distances(g, Some(start), n - 1);

    forall v | 0 <= v < n
      ensures
        match distances[v]
        case Some(d) =>
          is_shortest_dist(g, start, v, d)
        case None =>
          forall p: seq<int> {:trigger is_path(g, p)} ::
            (is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v) ==> false
    {
      match distances[v]
      case Some(d) =>
        bf_distances_good(g, Some(start), n - 1, v);
        var wp :|
          is_path(g, wp) &&
          bf_correct_start(Some(start), wp) &&
          wp[|wp| - 1] == v &&
          |wp| <= n &&
          path_weight(g, wp) == d;

        assert exists p: seq<int> {:trigger is_path(g, p)} ::
          is_path(g, p) &&
          p[0] == start &&
          p[|p| - 1] == v &&
          path_weight(g, p) == d;

        forall p: seq<int> {:trigger is_path(g, p)}
          | is_path(g, p) &&
            p[0] == start &&
            p[|p| - 1] == v
          ensures path_weight(g, p) >= d
        {
          var q := bf_reduce_path(g, p);
          assert bf_correct_start(Some(start), q);
          bf_distances_lower(g, Some(start), n - 1, v, q);
          assert d <= path_weight(g, q);
          assert path_weight(g, q) <= path_weight(g, p);
        }

      case None =>
        forall p: seq<int> {:trigger is_path(g, p)}
          | is_path(g, p) &&
            p[0] == start &&
            p[|p| - 1] == v
          ensures false
        {
          var q := bf_reduce_path(g, p);
          assert bf_correct_start(Some(start), q);
          bf_distances_lower(g, Some(start), n - 1, v, q);
          assert bf_le(distances[v], path_weight(g, q));
          assert false;
        }
    }

    res := Some(distances);
  }
}
