method binary_search_lower_bound(s: seq<int>, target: int) returns (result: int)
    requires |s| <= 0x7FFFFFFF
    requires is_sorted(s)
    ensures result >= 0
    ensures result <= |s|
    ensures forall i {:trigger s[i]} :: 0 <= i < result ==> s[i] < target
    ensures forall i {:trigger s[i]} :: result <= i < |s| ==> s[i] >= target
{
    var low := 0;
    var high := |s|;

    while low < high
        invariant 0 <= low <= high <= |s|
        invariant forall i {:trigger s[i]} :: 0 <= i < low ==> s[i] < target
        invariant forall i {:trigger s[i]} :: high <= i < |s| ==> s[i] >= target
        decreases high - low
    {
        var mid := low + (high - low) / 2;
        assert low <= mid < high;

        if s[mid] < target {
            assert forall i | 0 <= i < mid + 1 :: s[i] < target by {
                forall i | 0 <= i < mid + 1
                    ensures s[i] < target
                {
                    if i < low {
                        assert s[i] < target;
                    } else {
                        assert 0 <= i <= mid < |s|;
                        assert s[i] <= s[mid];
                    }
                }
            }
            low := mid + 1;
        } else {
            assert s[mid] >= target;
            assert forall i | mid <= i < |s| :: s[i] >= target by {
                forall i | mid <= i < |s|
                    ensures s[i] >= target
                {
                    if i < high {
                        assert 0 <= mid <= i < |s|;
                        assert s[mid] <= s[i];
                    } else {
                        assert s[i] >= target;
                    }
                }
            }
            high := mid;
        }
    }

    result := low;
}

