function bf_min(a: Option<int>, b: Option<int>): Option<int> {
  match a
  case None => b
  case Some(x) =>
    match b
    case None => a
    case Some(y) => if x <= y then a else b
}

function bf_add(a: Option<int>, w: int): Option<int> {
  match a
  case None => None
  case Some(x) => Some(x + w)
