function bf_row(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    u: nat,
    v: int,
    i: nat,
    best: Option<int>): Option<int>
  requires |previous| == |g|
  requires u < |g|
  requires i <= |g[u]|
  decreases |g[u]| - i
{
  if i == |g[u]| then
    best
  else
    var e := g[u][i];
    var candidate :=
      if e.0 == v then bf_add(previous[u], e.1) else None;
    bf_row(g, previous, u, v, i + 1, bf_min(best, candidate))
}

function bf_all_rows(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    v: int,
    u: nat,
    best: Option<int>): Option<int>
  requires |previous| == |g|
  requires u <= |g|
  decreases |g| - u
{
  if u == |g| then
    best
  else
    bf_all_rows(
      g, previous, v, u + 1,
      bf_row(g, previous, u, v, 0, best))
}

function bf_step(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>): seq<Option<int>>
  requires |previous| == |g|
{
