method bellman_ford(
    graph: WeightedGraph,
    start: int)
    returns (res: Option<seq<Option<int>>>)
  requires well_formed(graph)
  requires 0 <= start < size(graph)
  requires weights_and_size_bounded(view(graph))
  ensures match res {
    case Some(dists) =>
      |dists| == size(graph) &&
      forall v: int :: 0 <= v < size(graph) ==> (
        match dists[v] {
          case Some(d) =>
            is_shortest_dist(view(graph), start, v, d)
          case None =>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
              (is_path(view(graph), p) &&
               p[0] == start &&
               p[|p| - 1] == v) ==> false
        }
      )
    case None =>
      has_negative_cycle(view(graph))
  }
{
  var g := graph.adj;
  var n := |g|;

  bf_view_well_formed(graph);
  assert n > 0;

  var detectorBefore := bf_distances(g, None, n - 1);
  var detectorAfter := bf_distances(g, None, n);

  if detectorAfter != detectorBefore {
    if !has_negative_cycle(g) {
      bf_stable_without_negative_cycle(g);
      assert detectorAfter == detectorBefore;
      assert false;
    }
    res := None;
  } else {
    bf_stability_excludes_negative_cycles(g);
    assert !has_negative_cycle(g);

    var distances := bf_distances(g, Some(start), n - 1);

    forall v | 0 <= v < n
      ensures
        match distances[v]
        case Some(d) =>
          is_shortest_dist(g, start, v, d)
        case None =>
          forall p: seq<int> {:trigger is_path(g, p)} ::
            (is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v) ==> false
    {
      match distances[v]
      case Some(d) =>
        bf_distances_good(g, Some(start), n - 1, v);
        var wp :|
          is_path(g, wp) &&
          bf_correct_start(Some(start), wp) &&
          wp[|wp| - 1] == v &&
          |wp| <= n &&
          path_weight(g, wp) == d;

        assert exists p: seq<int> {:trigger is_path(g, p)} ::
          is_path(g, p) &&
          p[0] == start &&
          p[|p| - 1] == v &&
          path_weight(g, p) == d;

        forall p: seq<int> {:trigger is_path(g, p)}
          | is_path(g, p) &&
            p[0] == start &&
            p[|p| - 1] == v
          ensures path_weight(g, p) >= d
        {
          var q := bf_reduce_path(g, p);
          assert bf_correct_start(Some(start), q);
          bf_distances_lower(g, Some(start), n - 1, v, q);
          assert d <= path_weight(g, q);
          assert path_weight(g, q) <= path_weight(g, p);
        }

      case None =>
        forall p: seq<int> {:trigger is_path(g, p)}
          | is_path(g, p) &&
            p[0] == start &&
            p[|p| - 1] == v
          ensures false
        {
          var q := bf_reduce_path(g, p);
          assert bf_correct_start(Some(start), q);
          bf_distances_lower(g, Some(start), n - 1, v, q);
          assert bf_le(distances[v], path_weight(g, q));
          assert false;
        }
    }

    res := Some(distances);
  }
}
