lemma mid_bounds_lemma(lo: int, hi: int)
    requires 0 <= lo < hi
    ensures lo <= lo + (hi - lo) / 2 < hi
{
    var d := hi - lo;
    var q := d / 2;
    var r := d % 2;
    assert d >= 1;
    assert d == q * 2 + r;
    assert 0 <= r < 2;
    assert q * 2 <= q * 2 + r;
    assert q * 2 <= d;
    assert r <= 1;
    assert q * 2 + r <= q * 2 + 1;
    assert d <= q * 2 + 1;

    if q < 0 {
        assert q <= -1;
        assert q * 2 <= -2;
        assert q * 2 + 1 <= -1;
        assert d <= -1;
        assert false;
