lemma ExtendMatch(haystack: seq<int>, needle: seq<int>, start: int, i: int)
    requires 0 <= start
    requires start + |needle| <= |haystack|
    requires 0 <= i < |needle|
    requires forall j :: 0 <= j < i ==> haystack[start + j] == needle[j]
    requires haystack[start + i] == needle[i]
    ensures forall j :: 0 <= j < i + 1 ==> haystack[start + j] == needle[j]
{
    forall j | 0 <= j < i + 1
        ensures haystack[start + j] == needle[j]
    {
        assert 0 <= j < |needle|;
        assert 0 <= start + j < |haystack|;
        if j < i {
            assert haystack[start + j] == needle[j];
        } else {
            assert j == i;
            assert haystack[start + j] == needle[j];
        }
    }
}

method MatchAt(haystack: seq<int>, needle: seq<int>, start: int) returns (ok: bool)
    requires 0 <= start
    requires start + |needle| <= |haystack|
    ensures ok <==> matches_at(haystack, needle, start)
{
    var i := 0;
    while i < |needle|
        invariant 0 <= i <= |needle|
        invariant forall j :: 0 <= j < i ==> haystack[start + j] == needle[j]
        decreases |needle| - i
    {
        assert 0 <= i < |needle|;
        assert 0 <= start + i;
        assert start + i < start + |needle|;
        assert start + |needle| <= |haystack|;
        assert 0 <= start + i < |haystack|;
        if haystack[start + i] != needle[i] {
            MismatchNotMatch(haystack, needle, start, i);
            assert !matches_at(haystack, needle, start);
            return false;
        }
        assert haystack[start + i] == needle[i];
        var i0 := i;
        ExtendMatch(haystack, needle, start, i0);
        assert forall j :: 0 <= j < i0 + 1 ==> haystack[start + j] == needle[j];
        i := i0 + 1;
        forall j | 0 <= j < i
            ensures haystack[start + j] == needle[j]
        {
            assert j < i0 + 1;
            assert haystack[start + j] == needle[j];
        }
    }
    assert i == |needle|;
    assert 0 <= start;
    assert start + |needle| <= |haystack|;
    assert forall j :: 0 <= j < |needle| ==> haystack[start + j] == needle[j];
    assert matches_at(haystack, needle, start);
    return true;
}

