            assert patterns[combined[i].0] == patterns[pid];
            MatchSameNeedle(haystack, patterns[pid], patterns[combined[i].0], combined[i].1);
        }
    }

    forall p, idy | 0 <= p < pid + 1 && matches_at(haystack, patterns[p], idy)
        ensures exists k :: 0 <= k < |combined| && combined[k] == (p, idy)
    {
        if p < pid {
            var k :| 0 <= k < |results| && results[k] == (p, idy);
            assert combined[k] == results[k];
            assert 0 <= k < |combined|;
            assert combined[k] == (p, idy);
            assert exists t :: 0 <= t < |combined| && combined[t] == (p, idy);
        } else {
            assert p == pid;
            assert patterns[p] == patterns[pid];
            MatchSameNeedle(haystack, patterns[p], patterns[pid], idy);
            assert matches_at(haystack, patterns[pid], idy);
            var k :| 0 <= k < |part| && part[k] == (pid, idy);
            assert combined[|results| + k] == part[k];
            assert 0 <= |results| + k < |combined|;
            assert part[k] == (p, idy);
            assert combined[|results| + k] == (p, idy);
            assert exists t :: 0 <= t < |combined| && combined[t] == (p, idy);
        }
    }
}

lemma ShiftPid(haystack: seq<int>, patterns: seq<seq<int>>, results: seq<(int, int)>, b: int, pid: int)
    requires pid == b
    requires 0 <= pid <= |patterns|
    requires forall i :: 0 <= i < |results| ==>
