lemma SpecHolds(results: seq<(int, int)>, haystack: seq<int>, patterns: seq<seq<int>>)
    requires forall i :: 0 <= i < |results| ==>
        results[i].0 >= 0 && results[i].1 >= 0 && 0 <= results[i].0 < |patterns| &&
        matches_at(haystack, patterns[results[i].0], results[i].1)
    requires forall p, idy ::
        0 <= p < |patterns| && matches_at(haystack, patterns[p], idy) ==>
        exists k :: 0 <= k < |results| && results[k] == (p, idy)
    ensures
        // Soundness: Every result returned is a valid match
        forall i :: 0 <= i < |results| ==>
            var (pid, idx) := results[i];

            // Check bounds BEFORE accessing patterns[pid]
            && pid >= 0 && idx >= 0 
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)
    ensures
        // Completeness: Every valid match for any pattern is contained in the results
        forall pid, idx ::
            0 <= pid < |patterns| && matches_at(haystack, patterns[pid], idx) ==>
            exists k :: 0 <= k < |results| && results[k] == (pid, idx)
{
    forall i | 0 <= i < |results|
        ensures var (pid, idx) := results[i];
            && pid >= 0 && idx >= 0
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)
    {
        var p0 := results[i].0;
        var i0 := results[i].1;
        assert results[i] == (p0, i0);
        assert p0 >= 0 && i0 >= 0;
        assert 0 <= p0 < |patterns|;
        assert matches_at(haystack, patterns[p0], i0);
    }

    forall p, idy | 0 <= p < |patterns| && matches_at(haystack, patterns[p], idy)
        ensures exists k :: 0 <= k < |results| && results[k] == (p, idy)
    {
        var k :| 0 <= k < |results| && results[k] == (p, idy);
        assert exists t :: 0 <= t < |results| && results[t] == (p, idy);
    }
}

method ac_automata_search(haystack: seq<int>, patterns: seq<seq<int>>) returns (results: seq<(int, int)>)
    requires |patterns| > 0
    requires |haystack| < 1000000
    requires |patterns| < 1000000
    requires forall i :: 0 <= i < |patterns| ==> |patterns[i]| < 1000000
    ensures
        // Soundness: Every result returned is a valid match
        forall i :: 0 <= i < |results| ==>
            var (pid, idx) := results[i];

            // Check bounds BEFORE accessing patterns[pid]
            && pid >= 0 && idx >= 0 
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)

    ensures
        // Completeness: Every valid match for any pattern is contained in the results
        forall pid, idx ::
            0 <= pid < |patterns| && matches_at(haystack, patterns[pid], idx) ==>
            exists k :: 0 <= k < |results| && results[k] == (pid, idx)
{
    results := [];
    var pid := 0;
    while pid < |patterns|
        invariant 0 <= pid <= |patterns|
        invariant forall i :: 0 <= i < |results| ==>
            results[i].0 >= 0 && results[i].1 >= 0 && 0 <= results[i].0 < pid &&
            matches_at(haystack, patterns[results[i].0], results[i].1)
        invariant forall p, idy ::
            0 <= p < pid && matches_at(haystack, patterns[p], idy) ==>
            exists k :: 0 <= k < |results| && results[k] == (p, idy)
        decreases |patterns| - pid
    {
        var pid0 := pid;
        assert 0 <= pid0 < |patterns|;
        var part := SearchOne(haystack, patterns[pid0], pid0);
        results := ConcatMatches(haystack, patterns, pid0, results, part);
        pid := pid0 + 1;
        assert pid == pid0 + 1;
        assert 0 <= pid0;
        assert pid0 + 1 <= |patterns|;
        assert 0 <= pid <= |patterns|;
        ShiftPid(haystack, patterns, results, pid0 + 1, pid);
    }
    assert pid == |patterns|;
    assert 0 <= |patterns| <= |patterns|;
    ShiftPid(haystack, patterns, results, pid, |patterns|);
    SpecHolds(results, haystack, patterns);
}
