ghost predicate PathOfLen(g: Graph, start: int, v: int, len: int) {
  exists p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) && p[0] == start && p[|p| - 1] == v && |p| == len
}

ghost predicate Bounded(g: Graph, start: int, dist: seq<int>, k: int) {
  forall p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) && p[0] == start && |p| <= k + 1 ==>
      0 <= p[|p| - 1] < |dist| && 0 <= dist[p[|p| - 1]] <= |p| - 1
}

ghost function CountNeg(s: seq<int>): nat
  decreases |s|
{
  if |s| == 0 then 0
  else CountNeg(s[..|s| - 1]) + (if s[|s| - 1] == -1 then 1 else 0)
}

lemma CountNegUpdate(s: seq<int>, w: int, x: int)
  requires 0 <= w < |s| && s[w] == -1 && x != -1
  ensures CountNeg(s[w := x]) == CountNeg(s) - 1
  decreases |s|
{
  var t := s[w := x];
  if w == |s| - 1 {
    assert t[..|t| - 1] == s[..|s| - 1];
  } else {
    assert t[..|t| - 1] == s[..|s| - 1][w := x];
    CountNegUpdate(s[..|s| - 1], w, x);
  }
}

lemma ExtendPath(g: Graph, start: int, u: int, w: int, len: int)
  requires PathOfLen(g, start, u, len)
  requires has_edge(g, u, w)
  ensures PathOfLen(g, start, w, len + 1)
{
  var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == u && |p| == len;
  var q := p + [w];
  forall t | 0 <= t < |q| - 1
    ensures has_edge(g, q[t], q[t + 1])
  {
    if t < |p| - 1 {
      assert q[t] == p[t] && q[t + 1] == p[t + 1];
    } else {
      assert q[t] == u && q[t + 1] == w;
    }
  }
  assert is_path(g, q);
  assert q[0] == start && q[|q| - 1] == w && |q| == len + 1;
}

lemma StepBounded(g: Graph, start: int, d0: seq<int>, d1: seq<int>, k: int)
  requires well_formed(g)
  requires |d0| == |g.adj| && |d1| == |g.adj|
  requires 0 <= k
  requires Bounded(g, start, d0, k)
  requires forall v :: 0 <= v < |d0| && d0[v] >= 0 ==> d1[v] == d0[v]
  requires forall v :: 0 <= v < |d1| ==> d1[v] <= k + 1
  requires forall u, t :: 0 <= u < |d1| && 0 <= d1[u] <= k && 0 <= t < |g.adj[u]| ==> d1[g.adj[u][t]] >= 0
  ensures Bounded(g, start, d1, k + 1)
{
  forall p: seq<int> | is_path(g, p) && p[0] == start && |p| <= k + 2
    ensures 0 <= p[|p| - 1] < |d1| && 0 <= d1[p[|p| - 1]] <= |p| - 1
  {
    if |p| <= k + 1 {
      assert 0 <= d0[p[|p| - 1]] <= |p| - 1;
    } else {
      var q := p[..|p| - 1];
      forall t | 0 <= t < |q| - 1
        ensures has_edge(g, q[t], q[t + 1])
      {
        assert q[t] == p[t] && q[t + 1] == p[t + 1];
      }
      assert is_path(g, q);
      assert 0 <= d0[q[|q| - 1]] <= |q| - 1;
      var m := |p| - 2;
      var u := p[m];
      assert q[|q| - 1] == u;
      assert has_edge(g, p[m], p[m + 1]);
      var i :| 0 <= u < |g.adj| && 0 <= i < |g.adj[u]| && g.adj[u][i] == p[m + 1];
      assert p[m + 1] == p[|p| - 1];
    }
  }
}

lemma ClosedReach(g: Graph, dist: seq<int>, start: int, p: seq<int>)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist| && dist[start] >= 0
  requires forall u, t :: 0 <= u < |g.adj| && dist[u] >= 0 && 0 <= t < |g.adj[u]| ==> dist[g.adj[u][t]] >= 0
  requires is_path(g, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |dist| && dist[p[|p| - 1]] >= 0
  decreases |p|
{
  if |p| > 1 {
    var q := p[..|p| - 1];
    forall t | 0 <= t < |q| - 1
      ensures has_edge(g, q[t], q[t + 1])
    {
      assert q[t] == p[t] && q[t + 1] == p[t + 1];
    }
    assert is_path(g, q);
    ClosedReach(g, dist, start, q);
    var m := |p| - 2;
    var u := p[m];
    assert q[|q| - 1] == u;
    assert has_edge(g, p[m], p[m + 1]);
    var i :| 0 <= u < |g.adj| && 0 <= i < |g.adj[u]| && g.adj[u][i] == p[m + 1];
    assert p[m + 1] == p[|p| - 1];
  }
}

lemma ClosedUnreachable(g: Graph, dist: seq<int>, start: int, target: int)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist| && dist[start] >= 0
  requires 0 <= target < |dist| && dist[target] < 0
  requires forall u, t :: 0 <= u < |g.adj| && dist[u] >= 0 && 0 <= t < |g.adj[u]| ==> dist[g.adj[u][t]] >= 0
  ensures !reachable(g, start, target)
{
  if reachable(g, start, target) {
    var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == target;
    ClosedReach(g, dist, start, p);
  }
}

lemma FinalShortest(g: Graph, start: int, target: int, dist: seq<int>, k: int)
  requires |dist| == |g.adj|
  requires 0 <= target < |dist|
  requires 0 <= dist[target] <= k
  requires Bounded(g, start, dist, k)
  requires PathOfLen(g, start, target, dist[target] + 1)
  ensures is_shortest_distance(g, start, target, dist[target])
{
  var p0 :| is_path(g, p0) && p0[0] == start && p0[|p0| - 1] == target && |p0| == dist[target] + 1;
  forall p: seq<int> | is_path(g, p) && p[0] == start && p[|p| - 1] == target
    ensures |p| >= dist[target] + 1
  {
    if |p| <= k + 1 {
      assert 0 <= dist[p[|p| - 1]] <= |p| - 1;
    }
  }
}

ghost predicate LayerInv(g: Graph, start: int, d0: seq<int>, dist: seq<int>, next: seq<int>, k: int) {
  |dist| == |g.adj| && |d0| == |g.adj|
  && (forall v :: 0 <= v < |dist| ==> -1 <= dist[v] <= k + 1)
  && (forall v :: 0 <= v < |dist| && d0[v] >= 0 ==> dist[v] == d0[v])
  && (forall v :: 0 <= v < |dist| && d0[v] == -1 ==> dist[v] == -1 || dist[v] == k + 1)
  && (forall v :: 0 <= v < |dist| && dist[v] >= 0 ==> PathOfLen(g, start, v, dist[v] + 1))
  && (forall x :: 0 <= x < |next| ==> 0 <= next[x] < |dist| && dist[next[x]] == k + 1)
  && (forall v :: 0 <= v < |dist| && dist[v] == k + 1 ==> v in next)
  && CountNeg(dist) + |next| == CountNeg(d0)
}

method ProcessNode(graph: Graph, start: int, ghost d0: seq<int>, dist0: seq<int>, next0: seq<int>, u: int, k: int)
  returns (dist: seq<int>, next: seq<int>)
  requires well_formed(graph)
  requires 0 <= k
  requires 0 <= u < |graph.adj| && |d0| == |graph.adj| && d0[u] == k
  requires LayerInv(graph, start, d0, dist0, next0, k)
  ensures LayerInv(graph, start, d0, dist, next, k)
  ensures forall v :: 0 <= v < |dist0| && dist0[v] >= 0 ==> dist[v] == dist0[v]
  ensures forall t :: 0 <= t < |graph.adj[u]| ==> dist[graph.adj[u][t]] >= 0
{
  dist := dist0;
  next := next0;
  var i := 0;
  while i < |graph.adj[u]|
    invariant 0 <= i <= |graph.adj[u]|
    invariant LayerInv(graph, start, d0, dist, next, k)
    invariant forall v :: 0 <= v < |dist0| && dist0[v] >= 0 ==> dist[v] == dist0[v]
    invariant forall ii :: 0 <= ii < i ==> dist[graph.adj[u][ii]] >= 0
  {
    var w := graph.adj[u][i];
    assert 0 <= w < |graph.adj|;
    if dist[w] == -1 {
      assert has_edge(graph, u, w);
      assert dist[u] == k;
      ExtendPath(graph, start, u, w, k + 1);
      CountNegUpdate(dist, w, k + 1);
      dist := dist[w := k + 1];
      next := next + [w];
    }
    i := i + 1;
  }
}

method Layer(graph: Graph, start: int, d0: seq<int>, frontier: seq<int>, k: int)
  returns (dist: seq<int>, next: seq<int>)
  requires well_formed(graph)
  requires 0 <= k
  requires |d0| == |graph.adj|
  requires forall v :: 0 <= v < |d0| ==> -1 <= d0[v] <= k
  requires forall v :: 0 <= v < |d0| && d0[v] >= 0 ==> PathOfLen(graph, start, v, d0[v] + 1)
  requires forall x :: 0 <= x < |frontier| ==> 0 <= frontier[x] < |d0| && d0[frontier[x]] == k
  ensures LayerInv(graph, start, d0, dist, next, k)
  ensures forall x, t :: 0 <= x < |frontier| && 0 <= t < |graph.adj[frontier[x]]| ==> dist[graph.adj[frontier[x]][t]] >= 0
{
  dist := d0;
  next := [];
  var j := 0;
  while j < |frontier|
    invariant 0 <= j <= |frontier|
    invariant LayerInv(graph, start, d0, dist, next, k)
    invariant forall x, t :: 0 <= x < j && 0 <= t < |graph.adj[frontier[x]]| ==> dist[graph.adj[frontier[x]][t]] >= 0
  {
    ghost var dprev := dist;
    dist, next := ProcessNode(graph, start, d0, dist, next, frontier[j], k);
    forall x, t | 0 <= x < j + 1 && 0 <= t < |graph.adj[frontier[x]]|
      ensures dist[graph.adj[frontier[x]][t]] >= 0
    {
      if x < j {
        assert dprev[graph.adj[frontier[x]][t]] >= 0;
      }
    }
    j := j + 1;
  }
}

lemma ClosureStep(g: Graph, d0: seq<int>, dist: seq<int>, frontier: seq<int>, k: int)
  requires well_formed(g)
  requires |d0| == |g.adj| && |dist| == |g.adj|
  requires forall v :: 0 <= v < |d0| ==> -1 <= d0[v] <= k
  requires forall v :: 0 <= v < |d0| && d0[v] >= 0 ==> dist[v] == d0[v]
  requires forall v :: 0 <= v < |d0| && d0[v] == -1 ==> dist[v] == -1 || dist[v] == k + 1
  requires forall u, t :: 0 <= u < |g.adj| && 0 <= d0[u] < k && 0 <= t < |g.adj[u]| ==> d0[g.adj[u][t]] >= 0
  requires forall v :: 0 <= v < |d0| && d0[v] == k ==> v in frontier
  requires forall x :: 0 <= x < |frontier| ==> 0 <= frontier[x] < |g.adj|
  requires forall x, t :: 0 <= x < |frontier| && 0 <= t < |g.adj[frontier[x]]| ==> dist[g.adj[frontier[x]][t]] >= 0
  ensures forall u, t :: 0 <= u < |dist| && 0 <= dist[u] <= k && 0 <= t < |g.adj[u]| ==> dist[g.adj[u][t]] >= 0
{
  forall u, t | 0 <= u < |dist| && 0 <= dist[u] <= k && 0 <= t < |g.adj[u]|
    ensures dist[g.adj[u][t]] >= 0
  {
    assert d0[u] == dist[u];
    if d0[u] == k {
      assert u in frontier;
      var x :| 0 <= x < |frontier| && frontier[x] == u;
      assert dist[g.adj[frontier[x]][t]] >= 0;
    } else {
      assert 0 <= g.adj[u][t] < |g.adj|;
      assert d0[g.adj[u][t]] >= 0;
    }
  }
}

method bfs_shortest_path(graph: Graph, start: int, target: int) returns (res: Option<int>)
  requires well_formed(graph)
  requires size(graph) <= 10000
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures match res {
    case Some(dist) => is_shortest_distance(graph, start, target, dist)
    case None => !reachable(graph, start, target)
  }
{
  var n := |graph.adj|;
  var dist := seq(n, i => -1);
  dist := dist[start := 0];
  assert is_path(graph, [start]);
  assert PathOfLen(graph, start, start, 1);
  forall p: seq<int> | is_path(graph, p) && p[0] == start && |p| <= 1
    ensures 0 <= p[|p| - 1] < |dist| && 0 <= dist[p[|p| - 1]] <= |p| - 1
  {
    assert |p| == 1;
  }
  assert Bounded(graph, start, dist, 0);
  var frontier := [start];
  var k := 0;
  while |frontier| > 0
    invariant |dist| == n
    invariant 0 <= k
    invariant forall v :: 0 <= v < n ==> -1 <= dist[v] <= k
    invariant dist[start] == 0
    invariant forall v :: 0 <= v < n && dist[v] >= 0 ==> PathOfLen(graph, start, v, dist[v] + 1)
    invariant Bounded(graph, start, dist, k)
    invariant forall u, t :: 0 <= u < n && 0 <= dist[u] < k && 0 <= t < |graph.adj[u]| ==> dist[graph.adj[u][t]] >= 0
    invariant forall x :: 0 <= x < |frontier| ==> 0 <= frontier[x] < n && dist[frontier[x]] == k
    invariant forall v :: 0 <= v < n && dist[v] == k ==> v in frontier
    decreases CountNeg(dist), |frontier|
  {
    ghost var d0 := dist;
    var next;
    dist, next := Layer(graph, start, dist, frontier, k);
    assert LayerInv(graph, start, d0, dist, next, k);
    ClosureStep(graph, d0, dist, frontier, k);
    StepBounded(graph, start, d0, dist, k);
    assert CountNeg(dist) + |next| == CountNeg(d0);
    k := k + 1;
    frontier := next;
  }
  assert frontier == [];
  forall u, t | 0 <= u < n && dist[u] >= 0 && 0 <= t < |graph.adj[u]|
    ensures dist[graph.adj[u][t]] >= 0
  {
    if dist[u] == k {
      assert u in frontier;
    }
  }
  if dist[target] >= 0 {
    FinalShortest(graph, start, target, dist, k);
    res := Some(dist[target]);
  } else {
    ClosedUnreachable(graph, dist, start, target);
    res := None;
  }
}

