    ghost var d0 := dist;
    var next;
    dist, next := Layer(graph, start, dist, frontier, k);
    assert LayerInv(graph, start, d0, dist, next, k);
    ClosureStep(graph, d0, dist, frontier, k);
    StepBounded(graph, start, d0, dist, k);
    assert CountNeg(dist) + |next| == CountNeg(d0);
    k := k + 1;
    frontier := next;
