      ensures colors[x] != colors[g.adj[x][k]]
    {
      assert x < u || (x == u && k < j + 1);
    }

    assert bp_scanned_edges(g, colors, u, j);
    assert j < j + 1;
    assert colors[u] != colors[g.adj[u][j]];
  }

  if bp_scanned_edges(g, colors, u, j) &&
     colors[u] != colors[g.adj[u][j]]
  {
    forall x: int, k: int |
      0 <= x < |g.adj| &&
      0 <= k < |g.adj[x]| &&
      (x < u || (x == u && k < j + 1))
      ensures colors[x] != colors[g.adj[x][k]]
    {
