lemma bp_scanned_is_valid(g: Graph, colors: seq<bool>)
  requires well_formed(g)
  requires |colors| == size(g)
  ensures
    bp_scanned_edges(g, colors, |g.adj|, 0)
    <==>
    is_valid_coloring(g, colors)
{
  assert |colors| == |g.adj|;

  if bp_scanned_edges(g, colors, |g.adj|, 0) {
    forall u: int, v: int | has_edge(g, u, v)
      ensures
        0 <= u < |colors| &&
        0 <= v < |colors| &&
        colors[u] != colors[v]
    {
      assert exists i: int ::
        0 <= u < |g.adj| &&
        0 <= i < |g.adj[u]| &&
        g.adj[u][i] == v;

      var i: int :|
        0 <= u < |g.adj| &&
        0 <= i < |g.adj[u]| &&
        g.adj[u][i] == v;

      assert 0 <= g.adj[u][i] < |g.adj|;
      assert 0 <= v < |colors|;
      assert u < |g.adj|;
      assert colors[u] != colors[g.adj[u][i]];
      assert colors[u] != colors[v];
    }

    assert is_valid_coloring(g, colors);
  }

  if is_valid_coloring(g, colors) {
    forall u: int, i: int |
      0 <= u < |g.adj| &&
      0 <= i < |g.adj[u]|
      ensures colors[u] != colors[g.adj[u][i]]
    {
      assert 0 <= g.adj[u][i] < |g.adj|;
      bp_adjacency_is_edge(g, u, i);
      assert has_edge(g, u, g.adj[u][i]);
      assert colors[u] != colors[g.adj[u][i]];
    }

    assert bp_scanned_edges(g, colors, |g.adj|, 0);
  }
}

method bp_coloring_valid(g: Graph, colors: seq<bool>)
    returns (valid: bool)
  requires well_formed(g)
  requires |colors| == size(g)
  ensures valid <==> is_valid_coloring(g, colors)
{
  valid := true;
  var u := 0;

  assert bp_scanned_edges(g, colors, 0, 0);

  while u < |g.adj|
    invariant 0 <= u <= |g.adj|
    invariant valid <==> bp_scanned_edges(g, colors, u, 0)
    decreases |g.adj| - u
  {
    var j := 0;

    while j < |g.adj[u]|
      invariant 0 <= j <= |g.adj[u]|
      invariant valid <==> bp_scanned_edges(g, colors, u, j)
      decreases |g.adj[u]| - j
    {
      assert 0 <= g.adj[u][j] < |g.adj|;
      assert 0 <= g.adj[u][j] < |colors|;

      var different := colors[u] != colors[g.adj[u][j]];
      bp_scanned_step(g, colors, u, j);
      valid := valid && different;
      j := j + 1;
    }

    bp_scanned_next_row(g, colors, u);
    u := u + 1;
  }

  bp_scanned_is_valid(g, colors);
}

method bp_search_coloring(g: Graph, prefix: seq<bool>)
    returns (result: Option<seq<bool>>)
  requires well_formed(g)
  requires |prefix| <= size(g)
  ensures result.Some? ==> is_valid_coloring(g, result.value)
  ensures result.None? ==>
    (forall colors: seq<bool> ::
      is_valid_coloring(g, colors) ==>
      !bp_starts_with(colors, prefix))
  decreases |g.adj| - |prefix|
{
  assert size(g) == |g.adj|;

  if |prefix| == |g.adj| {
    assert |prefix| == size(g);
    var valid := bp_coloring_valid(g, prefix);

    if valid {
      result := Some(prefix);
      return;
    }

    assert !is_valid_coloring(g, prefix);

    forall colors: seq<bool> | is_valid_coloring(g, colors)
      ensures !bp_starts_with(colors, prefix)
    {
      if bp_starts_with(colors, prefix) {
        assert |colors| == size(g);
        assert |colors| == |prefix|;
        bp_starts_equal(colors, prefix);
        assert colors == prefix;
        assert is_valid_coloring(g, prefix);
        assert false;
      }
    }

    result := None;
    return;
  }

  assert |prefix| < |g.adj|;

  var falsePrefix := prefix + [false];
  assert |falsePrefix| <= size(g);
  var falseResult := bp_search_coloring(g, falsePrefix);

  if falseResult.Some? {
    result := falseResult;
    return;
  }

  assert falseResult.None?;
  assert forall colors: seq<bool> ::
    is_valid_coloring(g, colors) ==>
    !bp_starts_with(colors, falsePrefix);

  var truePrefix := prefix + [true];
  assert |truePrefix| <= size(g);
  var trueResult := bp_search_coloring(g, truePrefix);

  if trueResult.Some? {
    result := trueResult;
    return;
  }

  assert trueResult.None?;
  assert forall colors: seq<bool> ::
    is_valid_coloring(g, colors) ==>
    !bp_starts_with(colors, truePrefix);

  forall colors: seq<bool> | is_valid_coloring(g, colors)
    ensures !bp_starts_with(colors, prefix)
  {
    if bp_starts_with(colors, prefix) {
      assert |colors| == size(g);
      assert |prefix| < |colors|;

      if colors[|prefix|] {
        bp_starts_extend(colors, prefix, true);
        assert bp_starts_with(colors, truePrefix);
        assert !bp_starts_with(colors, truePrefix);
        assert false;
      } else {
        bp_starts_extend(colors, prefix, false);
        assert bp_starts_with(colors, falsePrefix);
        assert !bp_starts_with(colors, falsePrefix);
        assert false;
      }
    }
  }

  result := None;
}

method check_bipartite(graph: Graph) returns (res: Option<seq<bool>>)
  requires well_formed(graph)
  ensures match res {
    case Some(colors) => is_valid_coloring(graph, colors)
    case None => !is_bipartite(graph)
  }
{
  var result := bp_search_coloring(graph, []);

  if result.Some? {
    res := result;
    return;
  }

  assert result.None?;
  assert forall colors: seq<bool> ::
    is_valid_coloring(graph, colors) ==>
    !bp_starts_with(colors, []);

  assert !is_bipartite(graph) by {
    if is_bipartite(graph) {
      assert exists colors: seq<bool> ::
        is_valid_coloring(graph, colors);

      var colors: seq<bool> :|
        is_valid_coloring(graph, colors);

      bp_empty_starts(colors);
      assert bp_starts_with(colors, []);
      assert !bp_starts_with(colors, []);
      assert false;
    }
  }

  res := None;
}
