    v: int,
    first: nat,
    best: Option<int>,
    u: int,
    i: int,
    d: int)
  requires |previous| == |g|
  requires first <= u < |g|
  requires 0 <= i < |g[u]|
  requires g[u][i].0 == v
  requires previous[u] == Some(d)
  ensures bf_le(
    bf_all_rows(g, previous, v, first, best),
    d + g[u][i].1)
  decreases |g| - first
{
  if first == u {
    bf_row_covers(g, previous, first, v, 0, best, i, d);
    bf_all_rows_monotone(
      g, previous, v, first + 1,
      bf_row(g, previous, first, v, 0, best),
      d + g[u][i].1);
  } else {
    bf_all_rows_covers(
      g, previous, v, first + 1,
      bf_row(g, previous, first, v, 0, best),
      u, i, d);
  }
}

lemma bf_path_vertices_bounded(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  requires bf_well_formed(g)
  requires is_path(g, p)
  requires |p| > 1
  ensures forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < |g|
{
  forall i | 0 <= i < |p|
    ensures 0 <= p[i] < |g|
  {
    if i < |p| - 1 {
      assert connected(g, p[i], p[i + 1]);
      var w :| has_edge(g, p[i], p[i + 1], w);
      bf_has_edge_bounds(g, p[i], p[i + 1], w);
    } else {
      assert i > 0;
      assert connected(g, p[i - 1], p[i]);
      var w :| has_edge(g, p[i - 1], p[i], w);
      bf_has_edge_bounds(g, p[i - 1], p[i], w);
    }
  }
}

lemma bf_distances_lower(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    k: nat,
    v: int,
    p: seq<int>)
  requires bf_well_formed(g)
  requires source.None? ||
           (source.Some? && 0 <= source.value < |g|)
  requires 0 <= v < |g|
  requires is_path(g, p)
  requires bf_correct_start(source, p)
  requires p[|p| - 1] == v
  requires |p| <= k + 1
  ensures bf_le(bf_distances(g, source, k)[v], path_weight(g, p))
  decreases k
{
  if k == 0 {
    assert |p| == 1;
    assert path_weight(g, p) == 0;
    match source
    case None =>
    case Some(s) =>
      assert p[0] == s;
      assert v == s;
  } else {
    var previous := bf_distances(g, source, k - 1);

    if |p| <= k {
      bf_distances_lower(g, source, k - 1, v, p);
      bf_all_rows_monotone(
        g, previous, v, 0, previous[v], path_weight(g, p));
    } else {
      assert |p| == k + 1;
      assert |p| > 1;

      var q := p[..|p| - 1];
      var u := p[|p| - 2];

      bf_path_prefix(g, p);
      bf_path_vertices_bounded(g, p);
      assert 0 <= u < |g|;
      assert bf_correct_start(source, q);
      bf_distances_lower(g, source, k - 1, u, q);

      var d :| previous[u] == Some(d) &&
               d <= path_weight(g, q);

      assert connected(g, u, v);
      var w :| has_edge(g, u, v, w);
      var i :| 0 <= u < |g| &&
               0 <= i < |g[u]| &&
               g[u][i].0 == v &&
               g[u][i].1 == w;

      bf_edge_weight(g, u, i);
      assert path_weight(g, p) == path_weight(g, q) + w;

      bf_all_rows_covers(
        g, previous, v, 0, previous[v], u, i, d);

      var answer := bf_distances(g, source, k)[v];
      assert bf_le(answer, d + w);
      assert d + w <= path_weight(g, p);
    }
  }
}

ghost function bf_values(p: seq<int>): set<int>
  decreases |p|
{
  if |p| == 0 then {}
  else {p[0]} + bf_values(p[1..])
}

ghost predicate bf_distinct(p: seq<int>)
  decreases |p|
{
  |p| == 0 ||
  (p[0] !in p[1..] && bf_distinct(p[1..]))
}

ghost function bf_range(n: nat): set<int>
  decreases n
{
  if n == 0 then {}
  else bf_range(n - 1) + {n - 1}
}

lemma bf_range_contains(n: nat, x: int)
  requires 0 <= x < n
  ensures x in bf_range(n)
  decreases n
{
  if x < n - 1 {
    bf_range_contains(n - 1, x);
  }
}

lemma bf_range_bounds(n: nat, x: int)
  requires x in bf_range(n)
  ensures 0 <= x < n
  decreases n
{
  assert n > 0;
  if x != n - 1 {
    assert x in bf_range(n - 1);
    bf_range_bounds(n - 1, x);
  }
}

lemma bf_range_cardinality(n: nat)
  ensures |bf_range(n)| == n
  decreases n
{
  if n > 0 {
    bf_range_cardinality(n - 1);
    assert n - 1 !in bf_range(n - 1) by {
      if n - 1 in bf_range(n - 1) {
        bf_range_bounds(n - 1, n - 1);
        assert false;
      }
    }
    assert |bf_range(n)| == |bf_range(n - 1)| + 1;
  }
}

lemma bf_values_subset_range(p: seq<int>, n: nat)
  requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
  ensures bf_values(p) <= bf_range(n)
  decreases |p|
{
  if |p| > 0 {
    bf_range_contains(n, p[0]);
    assert forall i: int :: 0 <= i < |p[1..]| ==>
      0 <= p[1..][i] < n;
    bf_values_subset_range(p[1..], n);
  }
}

lemma bf_notin_values(p: seq<int>, x: int)
  requires x !in p
  ensures x !in bf_values(p)
  decreases |p|
{
  if |p| > 0 {
    assert x != p[0];
    assert x !in p[1..];
    bf_notin_values(p[1..], x);
  }
}

lemma bf_distinct_cardinality(p: seq<int>)
  requires bf_distinct(p)
  ensures |bf_values(p)| == |p|
  decreases |p|
{
  if |p| > 0 {
    bf_distinct_cardinality(p[1..]);
    bf_notin_values(p[1..], p[0]);
    assert p[0] !in bf_values(p[1..]);
    assert |bf_values(p)| == |bf_values(p[1..])| + 1;
  }
}

lemma bf_set_card_subset(a: set<int>, b: set<int>)
  requires a <= b
  ensures |a| <= |b|
  decreases |a|
{
  if a != {} {
    var x :| x in a;
    assert x in b;
    assert a - {x} <= b - {x};
    bf_set_card_subset(a - {x}, b - {x});
    assert |a| == |a - {x}| + 1;
    assert |b| == |b - {x}| + 1;
  }
}

lemma bf_distinct_bound(p: seq<int>, n: nat)
  requires bf_distinct(p)
  requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
  ensures |p| <= n
{
  bf_values_subset_range(p, n);
  bf_distinct_cardinality(p);
  bf_range_cardinality(n);
  bf_set_card_subset(bf_values(p), bf_range(n));
}

lemma bf_duplicate_indices(p: seq<int>)
  requires !bf_distinct(p)
  ensures exists i: int, j: int ::
    0 <= i < j < |p| && p[i] == p[j]
  decreases |p|
{
  assert |p| > 0;
  if p[0] in p[1..] {
    assert exists j: int ::
      0 <= j < |p[1..]| && p[1..][j] == p[0];
    var j :| 0 <= j < |p[1..]| && p[1..][j] == p[0];
    assert p[j + 1] == p[0];
  } else {
    assert !bf_distinct(p[1..]);
    bf_duplicate_indices(p[1..]);
    var i, j :| 0 <= i < j < |p[1..]| &&
                    p[1..][i] == p[1..][j];
    assert p[i + 1] == p[j + 1];
  }
}

ghost function bf_join(a: seq<int>, b: seq<int>): seq<int>
  requires |a| > 0
  requires |b| > 0
  requires a[|a| - 1] == b[0]
{
  a + b[1..]
}

lemma bf_join_length(a: seq<int>, b: seq<int>)
  requires |a| > 0
  requires |b| > 0
  requires a[|a| - 1] == b[0]
  ensures |bf_join(a, b)| == |a| + |b| - 1
  ensures bf_join(a, b)[0] == a[0]
  ensures bf_join(a, b)[|bf_join(a, b)| - 1] == b[|b| - 1]
{
}

lemma bf_join_path(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
  requires is_path(g, a)
  requires is_path(g, b)
  requires a[|a| - 1] == b[0]
  ensures is_path(g, bf_join(a, b))
  decreases |b|
{
  if |b| > 1 {
    var prefix := b[..|b| - 1];
    bf_path_prefix(g, b);
    bf_join_path(g, a, prefix);
    assert bf_join(a, b)[..|bf_join(a, b)| - 1] ==
           bf_join(a, prefix);
    assert connected(g, b[|b| - 2], b[|b| - 1]);
  }
}

lemma bf_join_weight(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
  requires is_path(g, a)
  requires is_path(g, b)
  requires a[|a| - 1] == b[0]
  ensures path_weight(g, bf_join(a, b)) ==
          path_weight(g, a) + path_weight(g, b)
  decreases |b|
{
  if |b| == 1 {
    assert path_weight(g, b) == 0;
    assert bf_join(a, b) == a;
  } else {
    var prefix := b[..|b| - 1];
    bf_path_prefix(g, b);
    bf_join_path(g, a, prefix);
    bf_join_weight(g, a, prefix);
    assert bf_join(a, b)[..|bf_join(a, b)| - 1] ==
           bf_join(a, prefix);
  }
}

lemma bf_shorten_path(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  returns (q: seq<int>)
  requires bf_well_formed(g)
  requires is_path(g, p)
  requires |g| > 0
  requires |p| > |g|
  requires !has_negative_cycle(g)
  ensures is_path(g, q)
  ensures q[0] == p[0]
  ensures q[|q| - 1] == p[|p| - 1]
  ensures |q| < |p|
  ensures path_weight(g, q) <= path_weight(g, p)
{
  bf_path_vertices_bounded(g, p);

  if bf_distinct(p) {
    bf_distinct_bound(p, |g|);
    assert false;
  }

  bf_duplicate_indices(p);
  var i, j :| 0 <= i < j < |p| && p[i] == p[j];

  var a := p[..i + 1];
  var cycle := p[i..j + 1];
  var b := p[j..];

  assert is_path(g, a);
  assert is_path(g, cycle);
  assert is_path(g, b);
  assert cycle[0] == cycle[|cycle| - 1];
  assert |cycle| > 1;

  assert path_weight(g, cycle) >= 0 by {
    if path_weight(g, cycle) < 0 {
      assert has_negative_cycle(g);
      assert false;
    }
  }

  bf_join_path(g, a, cycle);
  bf_join_weight(g, a, cycle);
  bf_join_path(g, bf_join(a, cycle), b);
  bf_join_weight(g, bf_join(a, cycle), b);

  assert bf_join(bf_join(a, cycle), b) == p;

  q := bf_join(a, b);
  bf_join_path(g, a, b);
  bf_join_weight(g, a, b);
  bf_join_length(a, b);

  assert path_weight(g, p) ==
         path_weight(g, a) +
         path_weight(g, cycle) +
         path_weight(g, b);
  assert path_weight(g, q) ==
         path_weight(g, a) + path_weight(g, b);
}

lemma bf_reduce_path(
    g: seq<seq<(int, int)>>,
    p: seq<int>)
  returns (q: seq<int>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires is_path(g, p)
  requires !has_negative_cycle(g)
  ensures is_path(g, q)
  ensures q[0] == p[0]
  ensures q[|q| - 1] == p[|p| - 1]
  ensures |q| <= |g|
  ensures path_weight(g, q) <= path_weight(g, p)
  decreases |p|
{
  if |p| <= |g| {
    q := p;
  } else {
    var shorter := bf_shorten_path(g, p);
    q := bf_reduce_path(g, shorter);
  }
}

lemma bf_distances_all_total(
    g: seq<seq<(int, int)>>,
    k: nat,
    v: int)
  requires 0 <= v < |g|
  ensures bf_distances(g, None, k)[v].Some?
  decreases k
{
  if k > 0 {
    var previous := bf_distances(g, None, k - 1);
    bf_distances_all_total(g, k - 1, v);
    var d := previous[v].value;
    bf_all_rows_monotone(
      g, previous, v, 0, previous[v], d);
  }
}

lemma bf_distances_all_total_everywhere(
    g: seq<seq<(int, int)>>,
    k: nat)
  ensures forall v: int :: 0 <= v < |g| ==>
    bf_distances(g, None, k)[v].Some?
{
  forall v | 0 <= v < |g|
    ensures bf_distances(g, None, k)[v].Some?
  {
    bf_distances_all_total(g, k, v);
  }
}

lemma {:isolate_assertions} bf_step_decreases_vertex(
    g: seq<seq<(int, int)>>,
    v: int)
  requires |g| > 0
  requires 0 <= v < |g|
  ensures bf_distances(g, None, |g| - 1)[v].Some?
  ensures bf_distances(g, None, |g|)[v].Some?
  ensures bf_distances(g, None, |g|)[v].value <=
          bf_distances(g, None, |g| - 1)[v].value
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  bf_distances_all_total(g, |g| - 1, v);
  bf_distances_all_total(g, |g|, v);

  assert before[v].Some?;
  assert after[v].Some?;
  assert bf_le(before[v], before[v].value);

  bf_all_rows_monotone(
    g, before, v, 0, before[v], before[v].value);

  assert after[v] ==
    bf_all_rows(g, before, v, 0, before[v]);
  assert bf_le(after[v], before[v].value);
}

lemma {:isolate_assertions} bf_no_negative_step_increases_vertex(
    g: seq<seq<(int, int)>>,
    v: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  requires 0 <= v < |g|
  ensures bf_distances(g, None, |g| - 1)[v].Some?
  ensures bf_distances(g, None, |g|)[v].Some?
  ensures bf_distances(g, None, |g| - 1)[v].value <=
          bf_distances(g, None, |g|)[v].value
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  bf_distances_all_total(g, |g| - 1, v);
  bf_distances_all_total(g, |g|, v);

  assert before[v].Some?;
  assert after[v].Some?;

  var currentValue := after[v].value;
  assert after[v] == Some(currentValue);

  bf_distances_good(g, None, |g|, v);

  var wp :| is_path(g, wp) &&
            bf_correct_start(None, wp) &&
            wp[|wp| - 1] == v &&
            |wp| <= |g| + 1 &&
            path_weight(g, wp) == currentValue;

  var q := bf_reduce_path(g, wp);

  assert is_path(g, q);
  assert q[|q| - 1] == v;
  assert |q| <= |g|;
  assert bf_correct_start(None, q);

  bf_distances_lower(g, None, |g| - 1, v, q);

  assert bf_le(before[v], path_weight(g, q));
  assert before[v].value <= path_weight(g, q);
  assert path_weight(g, q) <= path_weight(g, wp);
  assert path_weight(g, wp) == currentValue;
}

lemma {:isolate_assertions} bf_stable_vertex_without_negative_cycle(
    g: seq<seq<(int, int)>>,
    v: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  requires 0 <= v < |g|
  ensures bf_distances(g, None, |g|)[v] ==
          bf_distances(g, None, |g| - 1)[v]
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  bf_step_decreases_vertex(g, v);
  bf_no_negative_step_increases_vertex(g, v);

  assert before[v].Some?;
  assert after[v].Some?;
  assert after[v].value <= before[v].value;
  assert before[v].value <= after[v].value;
  assert after[v].value == before[v].value;
  assert before[v] == Some(before[v].value);
  assert after[v] == Some(after[v].value);
  assert after[v] == before[v];
}

lemma {:isolate_assertions} bf_stable_without_negative_cycle(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  ensures bf_distances(g, None, |g|) ==
          bf_distances(g, None, |g| - 1)
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  assert |before| == |g|;
  assert |after| == |g|;

  forall v | 0 <= v < |g|
    ensures after[v] == before[v]
  {
    bf_stable_vertex_without_negative_cycle(g, v);
  }

  assert after == before;
}

ghost predicate bf_relaxed(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>) {
  |d| == |g| &&
  forall u: int, i: int {:trigger g[u][i]} ::
    0 <= u < |g| && 0 <= i < |g[u]| ==>
      0 <= g[u][i].0 < |d| &&
      d[u].Some? &&
      d[g[u][i].0].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
}

lemma {:isolate_assertions} bf_stable_edge_relaxed(
    g: seq<seq<(int, int)>>,
    u: int,
    i: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires 0 <= u < |g|
  requires 0 <= i < |g[u]|
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures 0 <= g[u][i].0 < |g|
  ensures bf_distances(g, None, |g| - 1)[u].Some?
  ensures bf_distances(g, None, |g| - 1)[g[u][i].0].Some?
  ensures
    bf_distances(g, None, |g| - 1)[g[u][i].0].value <=
    bf_distances(g, None, |g| - 1)[u].value + g[u][i].1
{
  var d := bf_distances(g, None, |g| - 1);
  var next := bf_distances(g, None, |g|);
  var v := g[u][i].0;

  assert 0 <= v < |g|;

  bf_distances_all_total(g, |g| - 1, u);
  bf_distances_all_total(g, |g| - 1, v);

  assert d[u].Some?;
  assert d[v].Some?;
  assert d[u] == Some(d[u].value);

  bf_all_rows_covers(
    g, d, v, 0, d[v], u, i, d[u].value);

  assert next[v] ==
    bf_all_rows(g, d, v, 0, d[v]);
  assert bf_le(next[v], d[u].value + g[u][i].1);
  assert next == d;
  assert bf_le(d[v], d[u].value + g[u][i].1);
}

lemma {:isolate_assertions} bf_relaxed_from_stability(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures bf_relaxed(g, bf_distances(g, None, |g| - 1))
{
  var d := bf_distances(g, None, |g| - 1);

  assert |d| == |g|;

  forall u: int, i: int
    {:trigger g[u][i]}
    | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures
      0 <= g[u][i].0 < |d| &&
      d[u].Some? &&
      d[g[u][i].0].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
  {
    bf_stable_edge_relaxed(g, u, i);
    assert |d| == |g|;
  }
}

lemma bf_prefix_vertices_bounded(
    p: seq<int>,
    n: int)
  requires |p| > 1
  requires forall j: int {:trigger p[j]} ::
    0 <= j < |p| ==> 0 <= p[j] < n
  ensures forall j: int {:trigger p[..|p| - 1][j]} ::
    0 <= j < |p[..|p| - 1]| ==>
      0 <= p[..|p| - 1][j] < n
{
  forall j
    {:trigger p[..|p| - 1][j]}
    | 0 <= j < |p[..|p| - 1]|
    ensures 0 <= p[..|p| - 1][j] < n
  {
    assert p[..|p| - 1][j] == p[j];
  }
}

lemma {:isolate_assertions} bf_detector_relaxed_path(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>,
    p: seq<int>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires d == bf_distances(g, None, |g| - 1)
  requires bf_relaxed(g, d)
  requires is_path(g, p)
  requires forall j: int {:trigger p[j]} ::
    0 <= j < |p| ==> 0 <= p[j] < |d|
  ensures d[p[|p| - 1]].value <=
          d[p[0]].value + path_weight(g, p)
  decreases |p|
{
  if |p| == 1 {
    bf_distances_all_total(g, |g| - 1, p[0]);
    assert d[p[0]].Some?;
    assert p[|p| - 1] == p[0];
    assert path_weight(g, p) == 0;
  } else {
    var q := p[..|p| - 1];
    var u := p[|p| - 2];
    var v := p[|p| - 1];

    bf_path_prefix(g, p);
    bf_prefix_vertices_bounded(p, |d|);

    bf_detector_relaxed_path(g, d, q);

    assert 0 <= u < |d|;
    assert 0 <= v < |d|;
    assert |d| == |g|;
    assert 0 <= u < |g|;
