method delete_min(tree: Tree) returns (m: int, res: Tree)
    requires tree != Empty
    requires is_bst(tree)
    ensures is_bst(res)
    ensures m in view(tree)
    ensures forall x :: x in view(tree) ==> m <= x
    ensures view(res) == view(tree) - {m}
    decreases tree
{
    var val, left, right := tree.val, tree.left, tree.right;
    assert view(tree) == view(left) + view(right) + {val};
    if left == Empty {
        m := val;
        res := right;
        assert val !in view(right);
        assert view(tree) == view(right) + {val};
    } else {
        var l;
        m, l := delete_min(left);
        res := Node(val, l, right);
        assert m < val;
        assert m !in view(right);
        assert forall x :: x in view(l) ==> x in view(left);
        assert forall x :: x in view(l) ==> x < val;
        assert view(res) == view(l) + view(right) + {val};
    }
}

method delete(tree: Tree, v: int) returns (res: Tree)
    requires v >= 0
    requires is_bst(tree)
    ensures is_bst(res)
    ensures view(res) == view(tree) - {v}
    decreases tree
{
    if tree == Empty {
        res := Empty;
        return;
    }
    var val, left, right := tree.val, tree.left, tree.right;
    assert view(tree) == view(left) + view(right) + {val};
    if v < val {
        var l := delete(left, v);
        res := Node(val, l, right);
        assert v !in view(right);
        assert forall x :: x in view(l) ==> x in view(left);
        assert forall x :: x in view(l) ==> x < val;
        assert view(res) == view(l) + view(right) + {val};
    } else if v > val {
        var r := delete(right, v);
        res := Node(val, left, r);
        assert v !in view(left);
        assert forall x :: x in view(r) ==> x in view(right);
        assert forall x :: x in view(r) ==> x > val;
        assert view(res) == view(left) + view(r) + {val};
    } else {
        assert val !in view(left);
        assert val !in view(right);
        if left == Empty {
            res := right;
        } else if right == Empty {
            res := left;
        } else {
            var m, r := delete_min(right);
            res := Node(m, left, r);
            assert m > val;
            assert forall x :: x in view(left) ==> x < m;
            assert forall x :: x in view(r) ==> x in view(right) && x != m;
            assert forall x :: x in view(r) ==> x > m;
            assert view(res) == view(left) + view(r) + {m};
        }
    }
}

