ghost predicate bf_well_formed(g: seq<seq<(int, int)>>) {
  (forall u: int, i: int ::
    0 <= u < |g| && 0 <= i < |g[u]| ==>
      0 <= g[u][i].0 < |g|)
  &&
  (forall u: int, i: int, j: int ::
    0 <= u < |g| &&
    0 <= i < |g[u]| &&
    0 <= j < |g[u]| &&
    i != j ==>
      g[u][i].0 != g[u][j].0)
}

