function bf_min(a: Option<int>, b: Option<int>): Option<int> {
  match a
  case None => b
  case Some(x) =>
    match b
    case None => a
    case Some(y) => if x <= y then a else b
}

function bf_add(a: Option<int>, w: int): Option<int> {
  match a
  case None => None
  case Some(x) => Some(x + w)
}

ghost function bf_value(a: Option<int>): int {
  match a
  case None => 0
  case Some(x) => x
}

ghost predicate bf_le(a: Option<int>, x: int) {
  match a
  case None => false
  case Some(y) => y <= x
}

lemma bf_min_preserves_left(a: Option<int>, b: Option<int>, x: int)
  requires bf_le(a, x)
  ensures bf_le(bf_min(a, b), x)
{
}

lemma bf_min_preserves_right(a: Option<int>, b: Option<int>, x: int)
  requires bf_le(b, x)
  ensures bf_le(bf_min(a, b), x)
{
}

function bf_row(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    u: nat,
    v: int,
    i: nat,
    best: Option<int>): Option<int>
  requires |previous| == |g|
  requires u < |g|
  requires i <= |g[u]|
  decreases |g[u]| - i
{
  if i == |g[u]| then
    best
  else
    var e := g[u][i];
    var candidate :=
      if e.0 == v then bf_add(previous[u], e.1) else None;
    bf_row(g, previous, u, v, i + 1, bf_min(best, candidate))
}

function bf_all_rows(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>,
    v: int,
    u: nat,
    best: Option<int>): Option<int>
  requires |previous| == |g|
  requires u <= |g|
  decreases |g| - u
{
  if u == |g| then
    best
  else
    bf_all_rows(
      g, previous, v, u + 1,
      bf_row(g, previous, u, v, 0, best))
}

function bf_step(
    g: seq<seq<(int, int)>>,
    previous: seq<Option<int>>): seq<Option<int>>
  requires |previous| == |g|
{
  seq(|g|, v =>
    if 0 <= v < |previous| then
      bf_all_rows(g, previous, v, 0, previous[v])
    else
      None)
}

function bf_initial(
    g: seq<seq<(int, int)>>,
    source: Option<int>): seq<Option<int>>
{
  seq(|g|, v =>
    match source
    case None => Some(0)
    case Some(s) => if v == s then Some(0) else None)
}

function bf_distances(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    k: nat): seq<Option<int>>
  ensures |bf_distances(g, source, k)| == |g|
  decreases k
{
  if k == 0 then
    bf_initial(g, source)
  else
    bf_step(g, bf_distances(g, source, k - 1))
}

ghost predicate bf_correct_start(source: Option<int>, p: seq<int>) {
  |p| > 0 &&
  match source
  case None => true
  case Some(s) => p[0] == s
}

ghost predicate bf_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    v: int,
    k: nat,
    value: Option<int>) {
  match value
  case None => true
  case Some(d) =>
    exists p: seq<int> {:trigger is_path(g, p)} ::
      is_path(g, p) &&
      bf_correct_start(source, p) &&
      p[|p| - 1] == v &&
      |p| <= k + 1 &&
      path_weight(g, p) == d
}

lemma bf_has_edge_bounds(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    w: int)
  requires bf_well_formed(g)
  requires has_edge(g, u, v, w)
  ensures 0 <= u < |g|
  ensures 0 <= v < |g|
{
  var i :| 0 <= u < |g| &&
           0 <= i < |g[u]| &&
           g[u][i].0 == v &&
           g[u][i].1 == w;
}

lemma bf_edge_weight(
    g: seq<seq<(int, int)>>,
    u: int,
    i: int)
  requires bf_well_formed(g)
  requires 0 <= u < |g|
  requires 0 <= i < |g[u]|
  ensures has_edge(g, u, g[u][i].0, g[u][i].1)
  ensures get_edge_weight(g, u, g[u][i].0) == g[u][i].1
{
  var v := g[u][i].0;
  var w := g[u][i].1;

  assert has_edge(g, u, v, w);
  assert exists x: int :: has_edge(g, u, v, x);
  assert has_edge(g, u, v, get_edge_weight(g, u, v));

  var j :| 0 <= u < |g| &&
           0 <= j < |g[u]| &&
           g[u][j].0 == v &&
           g[u][j].1 == get_edge_weight(g, u, v);

  if i != j {
    assert g[u][i].0 != g[u][j].0;
    assert false;
  }
}

