  assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma bf_extend_good(
    g: seq<seq<(int, int)>>,
    source: Option<int>,
    previous: Option<int>,
    u: int,
    v: int,
    w: int,
    k: nat)
  requires bf_good(g, source, u, k, previous)
  requires has_edge(g, u, v, w)
  requires get_edge_weight(g, u, v) == w
  ensures bf_good(g, source, v, k + 1, bf_add(previous, w))
{
  match previous
  case None =>
  case Some(d) =>
    var p :| is_path(g, p) &&
             bf_correct_start(source, p) &&
             p[|p| - 1] == u &&
             |p| <= k + 1 &&
             path_weight(g, p) == d;
    bf_append_path(g, p, v, w);
}

