lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_step_decreases_vertex(
    g: seq<seq<(int, int)>>,
    v: int)
  returns (beforeValue: int, afterValue: int)
  requires |g| > 0
  requires 0 <= v < |g|
  ensures
    bf_distances(g, None, |g| - 1)[v] ==
      Some(beforeValue)
  ensures
    bf_distances(g, None, |g|)[v] ==
      Some(afterValue)
  ensures afterValue <= beforeValue
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  beforeValue := bf_distances_all_value(g, |g| - 1, v);
  afterValue := bf_distances_all_value(g, |g|, v);

  assert before[v] == Some(beforeValue);
  assert after[v] == Some(afterValue);
  assert bf_le(before[v], beforeValue);

  bf_all_rows_monotone(
    g, before, v, 0, before[v], beforeValue);

  bf_distances_next_at(g, None, |g| - 1, v);
  assert after[v] ==
    bf_all_rows(g, before, v, 0, before[v]);
  assert bf_le(after[v], beforeValue);
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_no_negative_step_increases_vertex(
    g: seq<seq<(int, int)>>,
    v: int)
  returns (beforeValue: int, afterValue: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  requires 0 <= v < |g|
  ensures
    bf_distances(g, None, |g| - 1)[v] ==
      Some(beforeValue)
  ensures
    bf_distances(g, None, |g|)[v] ==
      Some(afterValue)
  ensures beforeValue <= afterValue
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  beforeValue := bf_distances_all_value(g, |g| - 1, v);
  afterValue := bf_distances_all_value(g, |g|, v);

  assert before[v] == Some(beforeValue);
  assert after[v] == Some(afterValue);

  bf_distances_good(g, None, |g|, v);

  var wp :| is_path(g, wp) &&
            bf_correct_start(None, wp) &&
            wp[|wp| - 1] == v &&
            |wp| <= |g| + 1 &&
            path_weight(g, wp) == afterValue;

  var q := bf_reduce_path(g, wp);

  assert is_path(g, q);
  assert q[|q| - 1] == v;
  assert |q| <= |g|;
  assert bf_correct_start(None, q);

  bf_distances_lower(g, None, |g| - 1, v, q);

  assert bf_le(before[v], path_weight(g, q));
  assert beforeValue <= path_weight(g, q);
  assert path_weight(g, q) <= path_weight(g, wp);
  assert path_weight(g, wp) == afterValue;
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_stable_vertex_without_negative_cycle(
    g: seq<seq<(int, int)>>,
    v: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  requires 0 <= v < |g|
  ensures bf_distances(g, None, |g|)[v] ==
          bf_distances(g, None, |g| - 1)[v]
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  var beforeA, afterA := bf_step_decreases_vertex(g, v);
  var beforeB, afterB :=
    bf_no_negative_step_increases_vertex(g, v);

  assert before[v] == Some(beforeA);
  assert after[v] == Some(afterA);
  assert before[v] == Some(beforeB);
  assert after[v] == Some(afterB);
  assert beforeA == beforeB;
  assert afterA == afterB;
  assert afterA <= beforeA;
  assert beforeB <= afterB;
  assert afterA == beforeA;
  assert after[v] == before[v];
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_stable_without_negative_cycle(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires !has_negative_cycle(g)
  ensures bf_distances(g, None, |g|) ==
          bf_distances(g, None, |g| - 1)
{
  var before := bf_distances(g, None, |g| - 1);
  var after := bf_distances(g, None, |g|);

  assert |before| == |g|;
  assert |after| == |g|;

  forall v | 0 <= v < |g|
    ensures after[v] == before[v]
  {
    bf_stable_vertex_without_negative_cycle(g, v);
  }

  assert after == before;
}

ghost predicate bf_relaxed(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>) {
  |d| == |g| &&
  forall u: int, i: int {:trigger g[u][i]} ::
    0 <= u < |g| && 0 <= i < |g[u]| ==>
      0 <= g[u][i].0 < |d| &&
      d[u].Some? &&
      d[g[u][i].0].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_stable_edge_relaxed(
    g: seq<seq<(int, int)>>,
    u: int,
    i: int)
  returns (du: int, dv: int)
  requires bf_well_formed(g)
  requires |g| > 0
  requires 0 <= u < |g|
  requires 0 <= i < |g[u]|
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures 0 <= g[u][i].0 < |g|
  ensures
    bf_distances(g, None, |g| - 1)[u] == Some(du)
  ensures
    bf_distances(g, None, |g| - 1)[g[u][i].0] == Some(dv)
  ensures dv <= du + g[u][i].1
{
  var d := bf_distances(g, None, |g| - 1);
  var next := bf_distances(g, None, |g|);
  var v := g[u][i].0;

  assert 0 <= v < |g|;

  du := bf_distances_all_value(g, |g| - 1, u);
  dv := bf_distances_all_value(g, |g| - 1, v);

  assert d[u] == Some(du);
  assert d[v] == Some(dv);

  bf_all_rows_covers(
    g, d, v, 0, d[v], u, i, du);

  bf_distances_next_at(g, None, |g| - 1, v);
  assert next[v] ==
    bf_all_rows(g, d, v, 0, d[v]);
  assert bf_le(next[v], du + g[u][i].1);
  assert next == d;
  assert bf_le(d[v], du + g[u][i].1);
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_relaxed_from_stability(
    g: seq<seq<(int, int)>>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires bf_distances(g, None, |g|) ==
           bf_distances(g, None, |g| - 1)
  ensures bf_relaxed(g, bf_distances(g, None, |g| - 1))
{
  var d := bf_distances(g, None, |g| - 1);

  assert |d| == |g|;

  forall u: int, i: int
    {:trigger g[u][i]}
    | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures
      0 <= g[u][i].0 < |d| &&
      d[u].Some? &&
      d[g[u][i].0].Some? &&
      d[g[u][i].0].value <= d[u].value + g[u][i].1
  {
    var du, dv := bf_stable_edge_relaxed(g, u, i);
    assert d[u] == Some(du);
    assert d[g[u][i].0] == Some(dv);
    assert dv <= du + g[u][i].1;
    assert |d| == |g|;
  }
}

lemma bf_prefix_vertices_bounded(
    p: seq<int>,
    n: int)
  requires |p| > 1
  requires forall j: int {:trigger p[j]} ::
    0 <= j < |p| ==> 0 <= p[j] < n
  ensures forall j: int {:trigger p[..|p| - 1][j]} ::
    0 <= j < |p[..|p| - 1]| ==>
      0 <= p[..|p| - 1][j] < n
{
  forall j
    {:trigger p[..|p| - 1][j]}
    | 0 <= j < |p[..|p| - 1]|
    ensures 0 <= p[..|p| - 1][j] < n
  {
    assert p[..|p| - 1][j] == p[j];
  }
}

lemma {:isolate_assertions} {:fuel bf_distances, 0}
  bf_detector_relaxed_path(
    g: seq<seq<(int, int)>>,
    d: seq<Option<int>>,
    p: seq<int>)
  requires bf_well_formed(g)
  requires |g| > 0
  requires d == bf_distances(g, None, |g| - 1)
  requires bf_relaxed(g, d)
  requires is_path(g, p)
  requires forall j: int {:trigger p[j]} ::
    0 <= j < |p| ==> 0 <= p[j] < |d|
  ensures bf_value(d[p[|p| - 1]]) <=
          bf_value(d[p[0]]) + path_weight(g, p)
  decreases |p|
{
  if |p| == 1 {
    var x := bf_distances_all_value(g, |g| - 1, p[0]);
    assert d[p[0]] == Some(x);
    assert p[|p| - 1] == p[0];
    assert path_weight(g, p) == 0;
  } else {
    var q := p[..|p| - 1];
    var u := p[|p| - 2];
    var v := p[|p| - 1];

    bf_path_prefix(g, p);
    bf_prefix_vertices_bounded(p, |d|);

    bf_detector_relaxed_path(g, d, q);

    assert 0 <= u < |d|;
    assert 0 <= v < |d|;
    assert |d| == |g|;
    assert 0 <= u < |g|;
    assert 0 <= v < |g|;

    var du := bf_distances_all_value(g, |g| - 1, u);
    var dv := bf_distances_all_value(g, |g| - 1, v);

    assert d[u] == Some(du);
    assert d[v] == Some(dv);
    assert bf_value(d[u]) == du;
    assert bf_value(d[v]) == dv;

    assert connected(g, u, v);
    var w :| has_edge(g, u, v, w);
    var i :| 0 <= u < |g| &&
             0 <= i < |g[u]| &&
             g[u][i].0 == v &&
             g[u][i].1 == w;

    bf_edge_weight(g, u, i);

    assert d[v].value <= d[u].value + g[u][i].1;
    assert dv <= du + w;
