lemma drop_first_append(s: seq<int>, c: int)
    requires |s| >= 1
    ensures (s + [c])[0] == s[0]
    ensures (s + [c])[1..] == s[1..] + [c]
{
    assert (s + [c])[0] == s[0];
    var left := (s + [c])[1..];
    var right := s[1..] + [c];
    assert |s + [c]| == |s| + 1;
    assert |left| == |s + [c]| - 1;
    assert |left| == |s|;
    assert |s[1..]| == |s| - 1;
    assert |right| == |s[1..]| + 1;
    assert |right| == |s|;

    forall k | 0 <= k < |left|
        ensures left[k] == right[k]
    {
        assert left[k] == (s + [c])[k + 1];
        if k < |s| - 1 {
            assert k + 1 < |s|;
            assert (s + [c])[k + 1] == s[k + 1];
            assert k < |s[1..]|;
            assert (s[1..])[k] == s[k + 1];
            assert right[k] == (s[1..])[k];
            assert left[k] == right[k];
        } else {
            assert k == |s| - 1;
            assert k + 1 == |s|;
            assert (s + [c])[k + 1] == (s + [c])[|s|];
            assert (s + [c])[|s|] == c;
            assert k == |s[1..]|;
            assert right[k] == c;
            assert left[k] == c;
            assert left[k] == right[k];
        }
    }
    assert forall k :: 0 <= k < |left| ==> left[k] == right[k];
    assert left == right;
}

lemma total_weight_append(s: seq<int>, c: int)
    ensures total_weight(s + [c]) == total_weight(s) + char_weight(c)
    decreases |s|
{
    if |s| == 0 {
        assert s + [c] == [c];
        calc {
            total_weight(s + [c]);
            == total_weight([c]);
            == char_weight([c][0]) + total_weight([c][1..]);
            == char_weight(c) + total_weight([]);
            == char_weight(c) + 0;
            == total_weight(s) + char_weight(c);
        }
    } else {
        drop_first_append(s, c);
        total_weight_append(s[1..], c);
        assert (s + [c])[0] == s[0];
        assert (s + [c])[1..] == s[1..] + [c];
        assert total_weight(s[1..] + [c]) == total_weight(s[1..]) + char_weight(c);
        assert total_weight(s) == char_weight(s[0]) + total_weight(s[1..]);
        calc {
            total_weight(s + [c]);
            == char_weight((s + [c])[0]) + total_weight((s + [c])[1..]);
            == char_weight(s[0]) + total_weight((s + [c])[1..]);
            == char_weight(s[0]) + total_weight(s[1..] + [c]);
            == char_weight(s[0]) + (total_weight(s[1..]) + char_weight(c));
            == (char_weight(s[0]) + total_weight(s[1..])) + char_weight(c);
            == total_weight(s) + char_weight(c);
        }
    }
}

