method bracket_match(s: seq<int>) returns (res: bool)
    requires
        // CONSTRAINT: Hard limit of 1,000,000 ensures no integer overflow
        // when counting or indexing.
        |s| <= 1000000
    ensures
        res == is_matched(s)
{
    var balance := 0;
    var i := 0;

    assert s[0..0] == [];
    assert total_weight([]) == 0;
    assert total_weight(s[0..0]) == 0;
    forall j | 0 <= j <= 0
        ensures total_weight(s[0..j]) >= 0
    {
        assert j == 0;
        assert total_weight(s[0..j]) == 0;
    }

    while i < |s|
        invariant 0 <= i <= |s|
        invariant balance == total_weight(s[0..i])
        invariant balance >= 0
        invariant forall j :: 0 <= j <= i ==> total_weight(s[0..j]) >= 0
        decreases |s| - i
