        var newBalance := balance + w;
        assert newBalance == total_weight(s[0..(i + 1)]);

        if newBalance < 0 {
            negative_prefix_not_matched(s, i + 1);
            assert !is_matched(s);
            return false;
        }

        assert newBalance >= 0;
        assert total_weight(s[0..(i + 1)]) >= 0;
