        ghost var next := i + 1;
        assert forall j :: 0 <= j <= next ==> total_weight(s[0..j]) >= 0;
        assert newBalance == total_weight(s[0..next]);

        balance := newBalance;
        i := next;

        assert balance == total_weight(s[0..i]);
        assert balance >= 0;
        assert forall j :: 0 <= j <= i ==> total_weight(s[0..j]) >= 0;
    }

    assert i == |s|;
    assert balance == total_weight(s);
    assert forall j :: 0 <= j <= |s| ==> total_weight(s[0..j]) >= 0;
    assert valid_prefix_weights(s);

    if balance == 0 {
        assert total_weight(s) == 0;
        assert is_matched(s);
        res := true;
    } else {
        assert total_weight(s) != 0;
        assert !is_matched(s);
        res := false;
    }
}

