      assert x in (((A + B) + C) - {v});
      assert x in ((A + B) + C);
      assert x != v;
      assert x in (A + B) || x in C;
      if x in C {
        assert x in ((A + (B - {v})) + C);
        assert x in L;
      } else {
        assert x in (A + B);
        assert x in A || x in B;
        if x in A {
          assert x in (A + (B - {v}));
          assert x in ((A + (B - {v})) + C);
          assert x in L;
        } else {
          assert x in B;
          assert x != v;
          assert x in (B - {v});
          assert x in (A + (B - {v}));
          assert x in ((A + (B - {v})) + C);
          assert x in L;
        }
      }
      assert x in L;
    }
  }
  assert L <= R;
  assert R <= L;
  assert L == R;
}

lemma DropValue(Lset: set<int>, Rset: set<int>, v: int)
  requires v !in Lset
  requires v !in Rset
  ensures (((Lset + Rset) + {v}) - {v}) == (Lset + Rset)
{
  var A := Lset + Rset;
  forall y: int
    ensures y in A ==> y != v
  {
    if y in A {
      assert y in Lset || y in Rset;
      if y in Lset {
        assert y != v;
      } else {
        assert y in Rset;
        assert y != v;
      }
    }
  }
  assert v !in A;
  var S := A + {v};
  var D := S - {v};
  forall x: int
    ensures x in D ==> x in A
  {
    if x in D {
      assert x in (S - {v});
      assert x != v;
      assert x in S;
      assert x in (A + {v});
      assert x in A || x == v;
      assert x in A;
    }
  }
  forall x: int
    ensures x in A ==> x in D
  {
    if x in A {
      assert x != v;
      assert x in (A + {v});
      assert x in S;
      assert x in (S - {v});
      assert x in D;
    }
  }
  assert D <= A;
  assert A <= D;
  assert D == A;
}

lemma Reinsert(Lset: set<int>, Rset: set<int>, m: int)
  requires m in Rset
  requires m !in Lset
  ensures (Lset + (Rset - {m})) + {m} == (Lset + Rset)
{
  var Left := (Lset + (Rset - {m})) + {m};
  var Right := Lset + Rset;
  forall x: int
    ensures x in Left ==> x in Right
  {
    if x in Left {
      assert x in ((Lset + (Rset - {m})) + {m});
      assert x in (Lset + (Rset - {m})) || x in {m};
      if x in {m} {
        assert x == m;
        assert m in Rset;
        assert x in (Lset + Rset);
        assert x in Right;
      } else {
        assert x in (Lset + (Rset - {m}));
        assert x in Lset || x in (Rset - {m});
        if x in Lset {
          assert x in (Lset + Rset);
          assert x in Right;
        } else {
          assert x in (Rset - {m});
          assert x in Rset;
          assert x in (Lset + Rset);
          assert x in Right;
        }
      }
      assert x in Right;
    }
  }
  forall x: int
    ensures x in Right ==> x in Left
  {
    if x in Right {
      assert x in (Lset + Rset);
      assert x in Lset || x in Rset;
      if x in Lset {
        assert x in (Lset + (Rset - {m}));
        assert x in ((Lset + (Rset - {m})) + {m});
        assert x in Left;
      } else {
        assert x in Rset;
        if x == m {
          assert x in {m};
          assert x in ((Lset + (Rset - {m})) + {m});
          assert x in Left;
        } else {
          assert x != m;
          assert x in (Rset - {m});
          assert x in (Lset + (Rset - {m}));
          assert x in ((Lset + (Rset - {m})) + {m});
          assert x in Left;
        }
      }
      assert x in Left;
    }
  }
  assert Left <= Right;
  assert Right <= Left;
  assert Left == Right;
}

method deleteMin(tree: Tree) returns (m: int, res: Tree)
  requires tree.Node?
  requires is_bst(tree)
  ensures m in view(tree)
  ensures is_bst(res)
  ensures view(res) == view(tree) - {m}
  ensures forall x :: x in view(res) ==> x > m
  decreases tree
{
  match tree {
    case Empty =>
      m := 0;
      res := Empty;
      assert false;
    case Node(val, left, right) =>
      assert tree == Node(val, left, right);
      assert is_bst(Node(val, left, right));
      UnpackAt(val, left, right);
      assert view(tree) == view(Node(val, left, right));
      assert view(tree) == view(left) + view(right) + {val};
      assert is_bst(left);
      assert is_bst(right);
      assert forall x :: x in view(left) ==> x < val;
      assert forall x :: x in view(right) ==> x > val;

      if left.Empty? {
        m := val;
        res := right;
        EmptyFacts(left);
        assert view(left) == {};
        assert val !in view(left);
        NotInViewGt(right, val);
        assert val !in view(right);
        DropValue(view(left), view(right), val);
        assert (((view(left) + view(right)) + {val}) - {val}) == (view(left) + view(right));
        assert view(tree) == (view(left) + view(right)) + {val};
        assert (view(tree) - {val}) == (((view(left) + view(right)) + {val}) - {val});
        assert (view(tree) - {m}) == (view(left) + view(right));
        UnionEmptyLeft(view(right));
        assert ({} + view(right)) == view(right);
        assert view(left) + view(right) == {} + view(right);
        assert view(left) + view(right) == view(right);
        assert res == right;
        assert view(res) == view(right);
        assert view(res) == view(tree) - {m};
        assert val in {val};
        assert m in (view(left) + view(right) + {val});
        assert m in view(tree);
        assert is_bst(right);
        assert is_bst(res);

        forall x: int | x in view(res)
          ensures x > m
        {
          assert x in view(right);
          assert x > val;
          assert x > m;
        }
        assert forall x :: x in view(res) ==> x > m;
        return;
      }

      assert !left.Empty?;
      assert left.Node?;
      var m0, newLeft := deleteMin(left);
      m := m0;
      assert m in view(left);
      assert m < val;
      assert m != val;
      assert m !in {val};
      assert is_bst(newLeft);
      assert view(newLeft) == view(left) - {m};
      assert forall z :: z in view(newLeft) ==> z > m;

      forall x: int | x in view(right)
        ensures x > m
      {
        assert x > val;
        assert m < val;
        assert x > m;
      }
      assert forall z :: z in view(right) ==> z > m;
      NotInViewGt(right, m);
      assert m !in view(right);

      forall x: int | x in view(newLeft)
        ensures x < val
      {
        assert x in (view(left) - {m});
        assert x in view(left);
        assert x < val;
      }
      assert forall x :: x in view(newLeft) ==> x < val;

      res := Node(val, newLeft, right);
      MkBst(val, newLeft, right);
      assert is_bst(res);
      ViewNode(val, newLeft, right);
      assert view(res) == view(newLeft) + view(right) + {val};

      forall x: int | x in view(res)
        ensures x > m
      {
        assert x in (view(newLeft) + view(right) + {val});
        assert x in (view(newLeft) + view(right)) || x in {val};
        if x in {val} {
          assert x == val;
          assert m < val;
          assert x > m;
        } else {
          assert x in (view(newLeft) + view(right));
          assert x in view(newLeft) || x in view(right);
          if x in view(newLeft) {
            assert x > m;
          } else {
            assert x in view(right);
            assert x > m;
          }
        }
      }
      assert forall x :: x in view(res) ==> x > m;

      UnionDiff(view(left), view(right), {val}, m);
      assert ((view(left) - {m}) + view(right)) + {val} == (((view(left) + view(right)) + {val}) - {m});
      assert view(newLeft) == view(left) - {m};
      assert view(res) == (view(newLeft) + view(right)) + {val};
      assert view(res) == ((view(left) - {m}) + view(right)) + {val};
      assert view(tree) == (view(left) + view(right)) + {val};
      assert (view(tree) - {m}) == (((view(left) + view(right)) + {val}) - {m});
      assert view(res) == view(tree) - {m};
      assert m in view(left);
      assert m in (view(left) + view(right) + {val});
      assert m in view(tree);
      return;
  }
