method deleteRoot(left: Tree, right: Tree, val: int) returns (res: Tree)
  requires is_bst(left)
  requires is_bst(right)
  requires forall x :: x in view(left) ==> x < val
  requires forall x :: x in view(right) ==> x > val
  ensures is_bst(res)
  ensures view(res) == view(left) + view(right)
{
  if left.Empty? {
    EmptyFacts(left);
    res := right;
    assert view(left) == {};
    UnionEmptyLeft(view(right));
    assert ({} + view(right)) == view(right);
    assert view(left) + view(right) == view(right);
    assert res == right;
    assert view(res) == view(right);
    assert view(res) == view(left) + view(right);
    assert is_bst(right);
    assert is_bst(res);
    return;
  }
  if right.Empty? {
    EmptyFacts(right);
    res := left;
    assert view(right) == {};
    UnionEmptyRight(view(left));
    assert (view(left) + {}) == view(left);
    assert view(left) + view(right) == view(left);
    assert res == left;
    assert view(res) == view(left);
    assert view(res) == view(left) + view(right);
    assert is_bst(left);
    assert is_bst(res);
    return;
  }
  assert !right.Empty?;
  assert right.Node?;
  var m, newRight := deleteMin(right);
  assert m in view(right);
  assert m > val;
  assert is_bst(newRight);
  assert view(newRight) == view(right) - {m};
  assert forall z :: z in view(newRight) ==> z > m;

  forall x: int | x in view(left)
    ensures x < m
  {
    assert x < val;
    assert m > val;
    assert x < m;
  }
  assert forall x :: x in view(left) ==> x < m;
  NotInViewLt(left, m);
  assert m !in view(left);

  res := Node(m, left, newRight);
  MkBst(m, left, newRight);
  assert is_bst(res);
  ViewNode(m, left, newRight);
  assert view(res) == view(left) + view(newRight) + {m};
  assert view(newRight) == view(right) - {m};
  assert view(res) == (view(left) + (view(right) - {m})) + {m};
  Reinsert(view(left), view(right), m);
  assert (view(left) + (view(right) - {m})) + {m} == (view(left) + view(right));
  assert view(res) == view(left) + view(right);
  return;
}

