method zig_zag(g: Tree) returns (res: Tree)
    // g corresponds to Box<Node>, so it is non-Empty
    requires g.Node?
    // g.left is Some (P exists)
    requires g.left.Node?
    // g.left.right is Some (X exists - the 'Zig-Zag' shape)
    requires g.left.right.Node?
    requires is_bst(g)
    ensures is_bst(res)
    ensures view(res) == view(g)
    // X (the original grandchild) is now the root
    ensures res.val == g.left.right.val
{
    var p := g.left;
    var x := p.right;
    var a := p.left;
    var b := x.left;
    var c := x.right;
    var d := g.right;

    assert view(g) == view(p) + view(d) + {g.val};
    assert view(p) == view(a) + view(x) + {p.val};
    assert view(x) == view(b) + view(c) + {x.val};

    assert is_bst(p);
    assert is_bst(x);
    assert is_bst(a);
    assert is_bst(b);
    assert is_bst(c);
    assert is_bst(d);

    assert forall v :: v in view(p) ==> v < g.val;
    assert forall v :: v in view(d) ==> v > g.val;
    assert forall v :: v in view(a) ==> v < p.val;
    assert forall v :: v in view(x) ==> v > p.val;
    assert forall v :: v in view(b) ==> v < x.val;
    assert forall v :: v in view(c) ==> v > x.val;

    assert x.val in view(x);
    assert p.val < x.val;
    assert x.val in view(p);
    assert x.val < g.val;

    assert forall v :: v in view(b) ==> v > p.val;
    assert forall v :: v in view(c) ==> v < g.val;

    var newP := Node(p.val, a, b);
    var newG := Node(g.val, c, d);

    assert view(newP) == view(a) + view(b) + {p.val};
    assert view(newG) == view(c) + view(d) + {g.val};
    assert is_bst(newP);
    assert is_bst(newG);
    assert forall v :: v in view(newP) ==> v < x.val;
    assert forall v :: v in view(newG) ==> v > x.val;

    res := Node(x.val, newP, newG);
    assert view(res) == view(newP) + view(newG) + {x.val};
}

response:
The zig-zag case is a double rotation, which makes grandchild `X` the new root:

```
        G                 X
       / \              /   \
      P   D    ==>     P     G
     / \              / \   / \
    A   X            A   B C   D
       / \
      B   C
```

**Why the result is still a BST:**

- **`B` under `P`:** every value in `B` is greater than `P.val` because `B` sat in `P`'s right subtree. Every value in `B` is less than `X.val` because `B` was `X`'s left subtree.
- **`C` under `G`:** every value in `C` is greater than `X.val` because `C` was `X`'s right subtree. Every value in `C` is less than `G.val` because `C` sat in `G`'s left subtree.
- **New left of `X`:** `P.val < X.val` and `A < P.val`, so all of `P`'s new subtree is below `X.val`.
- **New right of `X`:** `X.val < G.val` and `D > G.val`, so all of `G`'s new subtree is above `X.val`.

The assertions spell out how `view` unfolds and chain these comparisons step by step, so the verifier does not have to discover them itself.

