            assert view(Empty) + view(Empty) == e + e;
            EmptyUnion(e);
            assert ({}: set<int>) + e == e;
            assert e == ({}: set<int>);
            assert e + e == ({}: set<int>) + e;
            assert e + e == e;
            assert view(res) == e + {v};
            EmptyUnion({v});
            assert ({}: set<int>) + {v} == {v};
            assert e + {v} == ({}: set<int>) + {v};
            assert e + {v} == {v};
            assert view(res) == {v};
            assert view(tree) + {v} == e + {v};
            assert view(tree) + {v} == {v};
            assert view(res) == view(tree) + {v};
            assert forall x: int :: x in e ==> x < v;
            assert forall x: int :: x in e ==> x > v;
            assert forall x: int :: x in view(Empty) ==> x < v;
            assert forall x: int :: x in view(Empty) ==> x > v;
            assert is_bst(Empty);
            assert is_bst(res);
