            assert tree == Node(val, left, right);
            if v < val {
                var newLeft := insert(left, v);
                LeftInsertOk(val, left, right, newLeft, v);
                res := Node(val, newLeft, right);
                assert is_bst(Node(val, newLeft, right));
                assert view(Node(val, newLeft, right)) == view(Node(val, left, right)) + {v};
                assert view(tree) == view(Node(val, left, right));
                assert view(res) == view(tree) + {v};
                assert is_bst(res);
