                var newRight := insert(right, v);
                RightInsertOk(val, left, right, newRight, v);
                res := Node(val, left, newRight);
                assert is_bst(Node(val, left, newRight));
                assert view(Node(val, left, newRight)) == view(Node(val, left, right)) + {v};
                assert view(tree) == view(Node(val, left, right));
                assert view(res) == view(tree) + {v};
                assert is_bst(res);
            } else {
                assert v == val;
                ViewNode(val, left, right);
                assert view(tree) == (view(left) + view(right)) + {val};
                assert val in {val};
                assert val in (view(left) + view(right)) || val in {val};
                assert val in ((view(left) + view(right)) + {val});
