method {:vcs_split_on_every_assert} color_component(g: Graph, color0: seq<Option<bool>>, root: int)
  returns (res: Option<seq<Option<bool>>>)
  requires well_formed(g)
  requires |color0| == |g.adj|
  requires 0 <= root < |g.adj|
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  ensures match res {
    case Some(c) =>
      && |c| == |g.adj|
      && IsClosed(g, c)
      && EdgesOK(g, c)
      && c[root].Some?
      && forall uu :: 0 <= uu < |g.adj| && color0[uu].Some? ==> c[uu] == color0[uu]
    case None => !is_bipartite(g)
  }
{
  var n := |g.adj|;
  var color := color0[root := Some(false)];
  var in_comp := (seq(n, i => false))[root := true];
  var queue := [root];
  var qh := 0;
  init_comp_inv(g, color0, root);
  count_none_nonneg(color);

  while qh < |queue|
    invariant CompInv(g, color0, color, in_comp, queue, qh, root)
    invariant Forced(g, root, color, in_comp)
    invariant QueueOK(n, color, in_comp, queue)
    invariant InCompOK(color0, color, in_comp, queue)
    invariant OutsideOK(color0, color, in_comp)
    invariant Separated(g, color0, in_comp)
    invariant ProcessedOK(g, color, in_comp, queue, qh)
    invariant color[root] == Some(false)
    invariant in_comp[root]
    invariant |color| == n && |in_comp| == n
    invariant 0 <= qh <= |queue|
    invariant count_none(color) + |queue| - qh >= 0
    decreases count_none(color) + |queue| - qh
  {
    count_none_nonneg(color);
    var measure0 := count_none(color) + |queue| - qh;
    var cn0 := count_none(color);
    var qlen0 := |queue|;
    var qh0 := qh;
    assert 0 <= qh < |queue|;
    assert 0 <= queue[qh] < n && in_comp[queue[qh]] && color[queue[qh]].Some?;
    var u := queue[qh];
    var cu := color[u].value;
    var nbrs := get_neighbors(g, u);
    var j := 0;

    while j < |nbrs|
      invariant 0 <= j <= |nbrs|
      invariant CompInv(g, color0, color, in_comp, queue, qh, root)
      invariant Forced(g, root, color, in_comp)
      invariant QueueOK(n, color, in_comp, queue)
      invariant InCompOK(color0, color, in_comp, queue)
      invariant OutsideOK(color0, color, in_comp)
      invariant Separated(g, color0, in_comp)
      invariant ProcessedOK(g, color, in_comp, queue, qh)
      invariant color[root] == Some(false)
      invariant in_comp[root]
      invariant |color| == n && |in_comp| == n
      invariant 0 <= qh <= |queue|
      invariant qh == qh0 && u == queue[qh] && 0 <= u < n
      invariant color[u] == Some(cu) && in_comp[u]
      invariant count_none(color) + |queue| == cn0 + qlen0
      invariant count_none(color) >= 0
      invariant forall t :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < n && connected(g, u, nbrs[t])
      invariant forall t :: 0 <= t < j ==>
          0 <= nbrs[t] < n && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
      decreases |nbrs| - j
    {
      var v := nbrs[j];
      assert 0 <= v < n && connected(g, u, v);
      if color[v].None? {
        uncolored_not_in_comp(color0, color, in_comp, queue, v);
        assert !in_comp[v];
        assert forall t :: 0 <= t < j ==> nbrs[t] != v by {
          forall t | 0 <= t < j
            ensures nbrs[t] != v
          {
            assert color[nbrs[t]].Some?;
          }
        };
        ghost var c0s := color;
        ghost var i0s := in_comp;
        ghost var q0s := queue;
        var cn_before := count_none(color);
        var q_before := |queue|;
        count_none_update(color, v, !cu);
        after_color(g, color0, color, in_comp, queue, qh, root, u, v, cu);
        color := color[v := Some(!cu)];
        in_comp := in_comp[v := true];
        queue := queue + [v];
        assert color == c0s[v := Some(!cu)];
        assert in_comp == i0s[v := true];
        assert queue == q0s + [v];
        assert count_none(color) == cn_before - 1;
        assert |queue| == q_before + 1;
        assert count_none(color) + |queue| == cn_before + q_before;
        count_none_nonneg(color);
        assert count_none(color) >= 0;
        assert color[v].value == !cu;
        assert !cu != cu;
        assert in_comp[v] && color[v].Some?;
        assert u != v;
        assert color[u] == Some(cu);
        assert forall t :: 0 <= t < j ==>
            color[nbrs[t]] == c0s[nbrs[t]] && in_comp[nbrs[t]] == i0s[nbrs[t]];
        assert 0 <= qh <= |queue|;
      } else if color[v].value == cu {
        neighbor_is_in_comp(g, color0, color, in_comp, queue, u, v);
        assert in_comp[u] && in_comp[v];
        prove_not_bipartite(g, root, u, v, color, in_comp);
        return None;
      } else {
        neighbor_is_in_comp(g, color0, color, in_comp, queue, u, v);
        assert in_comp[v] && color[v].Some? && color[v].value != cu;
      }
      assert 0 <= v < n && in_comp[v] && color[v].Some? && color[v].value != cu;
      j := j + 1;
    }

    prefix_covers(g, color, in_comp, u, cu, nbrs);
    assert color[u].value == cu;
    assert forall w :: 0 <= w < n && connected(g, u, w) ==>
      in_comp[w] && color[w].Some? && color[w].value != color[u].value;
    step_qh(g, color0, color, in_comp, queue, qh, root);
    ghost var qh_old := qh;
    qh := qh + 1;
    assert qh == qh_old + 1;
    assert ProcessedOK(g, color, in_comp, queue, qh);
    assert CompInv(g, color0, color, in_comp, queue, qh, root);
    assert count_none(color) + |queue| == cn0 + qlen0;
    assert qh0 == qh_old;
    assert qlen0 - qh0 >= 1;
    assert cn0 >= 0;
    assert measure0 == cn0 + qlen0 - qh0;
    assert measure0 >= 1;
    assert count_none(color) + |queue| - qh == measure0 - 1;
    assert count_none(color) + |queue| - qh >= 0;
  }

  assert qh == |queue|;
  finish(g, color0, color, in_comp, queue, qh, root);
  return Some(color);
}

method {:vcs_split_on_every_assert} check_bipartite(graph: Graph) returns (res: Option<seq<bool>>)
