      assert forall uu :: 0 <= uu < s ==> color[uu].Some? by {
        forall uu | 0 <= uu < s
          ensures color[uu].Some?
        {
          // preserved from the pre-call coloring: those entries were Some
        }
      };
    }
    assert color[s].Some?;
    s := s + 1;
  }
  assert forall u :: 0 <= u < n ==> color[u].Some?;
  var colors: seq<bool> := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |colors| == i
    invariant forall k :: 0 <= k < n ==> color[k].Some?
    invariant forall k :: 0 <= k < i ==> colors[k] == color[k].value
    decreases n - i
