    assert |colors'| == i + 1;
    assert colors'[i] == bit;
    assert forall k :: 0 <= k < i ==> colors'[k] == colors[k];
    colors := colors';
    i := i + 1;
  }
  to_valid(graph, color, colors);
  return Some(colors);
}
