lemma RotationViewsEqual(y: int, x: int, A: Tree, B: Tree, C: Tree)
    ensures view(Node(x, A, Node(y, B, C))) == view(Node(y, Node(x, A, B), C))
{
    var neu := Node(x, A, Node(y, B, C));
    var old := Node(y, Node(x, A, B), C);
    var mid := Node(y, B, C);
    var left := Node(x, A, B);

    forall v
        ensures v in view(neu) <==> v in view(old)
    {
        if v in view(neu) {
            MembersOfNode(x, A, mid, v);
            assert v == x || v in view(A) || v in view(mid);
            if v == x || v in view(A) {
                MembersOfNode(x, A, B, v);
                assert v in view(left);
                MembersOfNode(y, left, C, v);
                assert v in view(old);
            } else {
                assert v in view(mid);
                MembersOfNode(y, B, C, v);
                assert v == y || v in view(B) || v in view(C);
                if v == y || v in view(C) {
                    MembersOfNode(y, left, C, v);
                    assert v in view(old);
                } else {
                    assert v in view(B);
                    MembersOfNode(x, A, B, v);
                    assert v in view(left);
                    MembersOfNode(y, left, C, v);
                    assert v in view(old);
                }
            }
        }
        if v in view(old) {
            MembersOfNode(y, left, C, v);
            assert v == y || v in view(left) || v in view(C);
            if v == y || v in view(C) {
                MembersOfNode(y, B, C, v);
                assert v in view(mid);
                MembersOfNode(x, A, mid, v);
                assert v in view(neu);
            } else {
                assert v in view(left);
                MembersOfNode(x, A, B, v);
                assert v == x || v in view(A) || v in view(B);
                if v == x || v in view(A) {
                    MembersOfNode(x, A, mid, v);
                    assert v in view(neu);
                } else {
                    assert v in view(B);
                    MembersOfNode(y, B, C, v);
                    assert v in view(mid);
                    MembersOfNode(x, A, mid, v);
                    assert v in view(neu);
                }
            }
        }
    }
    assert forall v :: v in view(neu) <==> v in view(old);
    SetExt(view(neu), view(old));
}

