lemma lemma_snoc_eq(a: seq<int>)
    requires |a| >= 1
    ensures a[..|a| - 1] + [a[|a| - 1]] == a
{
    var b := a[..|a| - 1] + [a[|a| - 1]];
    assert |b| == |a|;
    forall k | 0 <= k < |a|
        ensures b[k] == a[k]
    {
        if k < |a| - 1 {
            assert b[k] == a[k];
        } else {
            assert k == |a| - 1;
            assert b[k] == a[|a| - 1];
        }
    }
}

lemma lemma_append_drop(p: seq<int>, v: int)
    ensures |p + [v]| == |p| + 1
    ensures (p + [v])[|p|] == v
    ensures (p + [v])[..|p|] == p
{
    var q := p + [v];
    assert |q| == |p| + 1;
    assert q[|p|] == v;
    var pre := q[..|p|];
    assert |pre| == |p|;
    forall k | 0 <= k < |p|
        ensures pre[k] == p[k]
    {
        assert q[k] == p[k];
        assert pre[k] == q[k];
    }
}

lemma lemma_slice_snoc(p: seq<int>, s: int, t: int)
    requires 0 <= s < t <= |p|
    ensures p[s..t] == p[s..t - 1] + [p[t - 1]]
{
    var q := p[s..t];
    var q0 := p[s..t - 1] + [p[t - 1]];
    assert |q| == t - s;
    assert |q0| == t - s;
    forall k | 0 <= k < |q|
        ensures q[k] == q0[k]
    {
        if k < t - 1 - s {
            assert q[k] == p[s + k];
            assert (p[s..t - 1])[k] == p[s + k];
            assert q0[k] == p[s + k];
        } else {
            assert k == |q| - 1;
            assert q[k] == p[t - 1];
            assert q0[k] == p[t - 1];
        }
    }
}

lemma lemma_sub_is_path(g: seq<seq<(int, int)>>, p: seq<int>, s: int, t: int)
    requires is_path(g, p)
    requires 0 <= s < t <= |p|
    ensures is_path(g, p[s..t])
    decreases t - s
{
    var q := p[s..t];
    assert |q| == t - s > 0;
    if s + 1 == t {
        assert |q| == 1;
        assert is_path(g, q);
    } else {
        lemma_sub_is_path(g, p, s, t - 1);
        var q0 := p[s..t - 1];
        lemma_slice_snoc(p, s, t);
        assert q == q0 + [p[t - 1]];
        assert 0 <= t - 2 < |p| - 1;
        assert connected(g, p[t - 2], p[t - 1]);
        forall i | 0 <= i < |q| - 1
            ensures connected(g, q[i], q[i + 1])
        {
            if i < |q0| - 1 {
                assert 0 <= i < |q0| - 1;
                assert q[i] == q0[i];
                assert q[i + 1] == q0[i + 1];
                assert is_path(g, q0);
                assert connected(g, q0[i], q0[i + 1]);
            } else {
                assert i == |q| - 2;
                assert |q0| == |q| - 1;
                assert q0[|q0| - 1] == p[t - 2];
                assert q[i] == q0[i];
                assert q[i] == p[t - 2];
                assert q[i + 1] == p[t - 1];
                assert connected(g, p[t - 2], p[t - 1]);
            }
        }
        assert is_path(g, q);
    }
}

lemma lemma_adj_edge(graph: WeightedGraph, g: seq<seq<(int, int)>>, u: int, i: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= u < |g|
    requires 0 <= i < |g[u]|
    ensures 0 <= g[u][i].0 < |g|
    ensures has_edge(g, u, g[u][i].0, g[u][i].1)
    ensures get_edge_weight(g, u, g[u][i].0) == g[u][i].1
    ensures forall w' :: has_edge(g, u, g[u][i].0, w') ==> w' == g[u][i].1
{
    assert g == graph.adj;
    var v := g[u][i].0;
    var w := g[u][i].1;
    lemma_target_in_range(graph, u, i);
    assert 0 <= v < |g|;
    assert 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
    assert has_edge(g, u, v, w);

    forall w' | has_edge(g, u, v, w')
        ensures w' == w
    {
        var j :| 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
        if j != i {
            assert 0 <= u < |graph.adj|;
            assert 0 <= i < |graph.adj[u]| && 0 <= j < |graph.adj[u]|;
            assert graph.adj[u][i].0 != graph.adj[u][j].0;
            assert false;
        }
        assert w' == w;
    }
    assert forall w' :: has_edge(g, u, v, w') ==> w' == w;
    assert has_edge(g, u, v, w);
    assert get_edge_weight(g, u, v) == w;
}

lemma lemma_connected_weight(graph: WeightedGraph, g: seq<seq<(int, int)>>, u: int, v: int) returns (w: int, i: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= u < |g|
    requires connected(g, u, v)
    ensures 0 <= i < |g[u]|
    ensures g[u][i].0 == v && g[u][i].1 == w
    ensures has_edge(g, u, v, w)
    ensures get_edge_weight(g, u, v) == w
    ensures 0 <= v < |g|
{
    var w0 :| has_edge(g, u, v, w0);
    var i0 :| 0 <= i0 < |g[u]| && g[u][i0].0 == v && g[u][i0].1 == w0;
    lemma_adj_edge(graph, g, u, i0);
    w, i := w0, i0;
}

lemma lemma_extend_path(g: seq<seq<(int, int)>>, p: seq<int>, v: int, w: int)
    requires |p| >= 1
    requires is_path(g, p)
    requires has_edge(g, p[|p| - 1], v, w)
    requires get_edge_weight(g, p[|p| - 1], v) == w
    ensures is_path(g, p + [v])
    ensures (p + [v])[0] == p[0]
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(g, p + [v]) == path_weight(g, p) + w
{
    var q := p + [v];
    lemma_append_drop(p, v);
    assert |q| == |p| + 1;
    assert q[0] == p[0];
    assert q[|q| - 1] == v;
    assert q[..|q| - 1] == p;
    forall i | 0 <= i < |q| - 1
        ensures connected(g, q[i], q[i + 1])
    {
        if i < |p| - 1 {
            assert q[i] == p[i] && q[i + 1] == p[i + 1];
            assert connected(g, p[i], p[i + 1]);
        } else {
            assert i == |p| - 1;
            assert q[i] == p[|p| - 1];
            assert q[i + 1] == v;
            assert has_edge(g, p[|p| - 1], v, w);
            assert connected(g, p[|p| - 1], v);
        }
    }
    assert is_path(g, q);
    lemma_path_weight_def(g, q);
    assert q[|q| - 2] == p[|p| - 1];
    assert get_edge_weight(g, q[|q| - 2], q[|q| - 1]) == w;
    assert path_weight(g, q) == path_weight(g, p) + w;
}

lemma lemma_path_weight_concat(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
    requires |a| >= 1 && |b| >= 1
    requires a[|a| - 1] == b[0]
    ensures var q := a[..|a| - 1] + b;
        path_weight(g, q) == path_weight(g, a) + path_weight(g, b)
    decreases |b|
{
    if |b| == 1 {
        lemma_single_weight(g, b);
        lemma_snoc_eq(a);
        assert a[..|a| - 1] + b == a;
    } else {
        var b0 := b[..|b| - 1];
        assert |b0| >= 1;
        assert b0[0] == b[0];
        assert a[|a| - 1] == b0[0];
        lemma_path_weight_concat(g, a, b0);
        var q0 := a[..|a| - 1] + b0;
        var q := a[..|a| - 1] + b;
        lemma_slice_snoc(b, 0, |b|);
        assert b == b0 + [b[|b| - 1]];
        assert q == q0 + [b[|b| - 1]];
        lemma_append_drop(q0, b[|b| - 1]);
        assert |q| >= 2;
        lemma_path_weight_def(g, q);
        lemma_path_weight_def(g, b);
        assert q[|q| - 2] == q0[|q0| - 1];
        assert |q0| >= 1;
        assert q0[|q0| - 1] == b0[|b0| - 1];
        assert b[|b| - 2] == b0[|b0| - 1];
        assert get_edge_weight(g, q[|q| - 2], q[|q| - 1]) == get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, q) == path_weight(g, q0) + get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, b) == path_weight(g, b0) + get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, q0) == path_weight(g, a) + path_weight(g, b0);
        assert path_weight(g, q) == path_weight(g, a) + path_weight(g, b);
    }
}

lemma lemma_join_paths(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
    requires is_path(g, a) && is_path(g, b)
    requires |a| >= 1 && |b| >= 1
    requires a[|a| - 1] == b[0]
    ensures is_path(g, a[..|a| - 1] + b)
{
    var q := a[..|a| - 1] + b;
    assert |q| == |a| - 1 + |b|;
    assert |q| >= 1;
    if |a| == 1 {
        assert a[..|a| - 1] == [];
        assert q == b;
        assert is_path(g, q);
    } else {
        forall i | 0 <= i < |q| - 1
            ensures connected(g, q[i], q[i + 1])
        {
            var L := |a| - 1;
            if i < L - 1 {
                assert q[i] == a[i];
                assert q[i + 1] == a[i + 1];
                assert 0 <= i < |a| - 1;
                assert connected(g, a[i], a[i + 1]);
            } else if i == L - 1 {
                assert q[i] == a[L - 1];
                assert a[L - 1] == a[|a| - 2];
                assert q[i + 1] == b[0];
                assert b[0] == a[|a| - 1];
                assert connected(g, a[|a| - 2], a[|a| - 1]);
            } else {
                assert i >= L;
                var j := i - L;
                assert 0 <= j < |b| - 1;
                assert q[i] == b[j];
                assert q[i + 1] == b[j + 1];
                assert connected(g, b[j], b[j + 1]);
            }
        }
        assert is_path(g, q);
    }
}

lemma lemma_path_weight_split(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, p[k..])
    decreases |p| - k
{
    if k == |p| - 1 {
        assert p[..k + 1] == p;
        assert p[k..] == [p[k]];
        lemma_single_weight(g, p[k..]);
    } else {
        lemma_sub_is_path(g, p, 0, |p| - 1);
        var p0 := p[..|p| - 1];
        assert is_path(g, p0);
        assert 0 <= k < |p0|;
        lemma_path_weight_split(g, p0, k);
        lemma_path_weight_def(g, p);
        assert p[..k + 1] == p0[..k + 1];
        var suf := p[k..];
        var suf0 := p[k..|p| - 1];
        lemma_slice_snoc(p, k, |p|);
        assert suf == suf0 + [p[|p| - 1]];
        assert p0[k..] == suf0;
        assert |suf| >= 2;
        lemma_path_weight_def(g, suf);
        assert suf[..|suf| - 1] == suf0;
        assert suf[|suf| - 2] == p[|p| - 2];
        assert suf[|suf| - 1] == p[|p| - 1];
        assert path_weight(g, p0) == path_weight(g, p[..k + 1]) + path_weight(g, suf0);
        assert path_weight(g, p) == path_weight(g, p0) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
        assert path_weight(g, suf) == path_weight(g, suf0) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
        assert path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, suf);
    }
}

