    requires witness_ok(g, start, before, witBefore)
    requires forall t :: 0 <= t < |g| ==> le_opt(before[t], prev[t])
    requires edges_before(g, prev, before, u)
    requires edges_at(g, prev, before, u, e)
    requires before[start].Some? && before[start].value <= 0
    requires updated ==>
        prev[u].Some? &&
        du == prev[u].value &&
        (before[v].None? || du + wgt < before[v].value) &&
        after == before[v := Some(du + wgt)] &&
        nw == prevWit[u] + [v] &&
        witAfter == witBefore[v := nw]
    requires !updated ==> after == before && witAfter == witBefore
    requires updated <== (prev[u].Some? && (before[v].None? || (prev[u].Some? && du == prev[u].value && du + wgt < before[v].value)))
    ensures witness_ok(g, start, after, witAfter)
    ensures forall t :: 0 <= t < |g| ==> le_opt(after[t], prev[t])
    ensures edges_before(g, prev, after, u)
    ensures edges_at(g, prev, after, u, e + 1)
    ensures after[start].Some? && after[start].value <= 0
{
    // The biconditional above is stronger than needed in one direction and may not match
    // a failed comparison when du was not read. Re-establish the branch from `updated`.
    if updated {
        assert prev[u].Some?;
        assert du == prev[u].value;
        assert before[v].None? || du + wgt < before[v].value;
        assert after == before[v := Some(du + wgt)];
        assert nw == prevWit[u] + [v];
        lemma_witness_one(g, start, prev, prevWit, u);
        var src := prevWit[u];
        assert src[|src| - 1] == u;
        assert path_weight(g, src) == du;
        lemma_adj_edge(graph, g, u, e);
        assert has_edge(g, u, v, wgt);
        assert get_edge_weight(g, u, v) == wgt;
        lemma_extend_path(g, src, v, wgt);
        assert is_path(g, nw);
        assert nw[0] == start;
        assert nw[|nw| - 1] == v;
        assert path_weight(g, nw) == du + wgt;
        lemma_witness_set(g, start, before, witBefore, v, du + wgt, nw);
        assert witness_ok(g, start, after, witAfter);

        assert before[v].None? || (before[v].Some? && du + wgt <= before[v].value);
        lemma_edges_mono(g, prev, before, after, u, u, e, v, du + wgt);

        assert after[v] == Some(du + wgt);
        assert 0 <= u < |prev| && 0 <= v < |after| && prev[u].Some?;
        assert after[v].value == du + wgt <= prev[u].value + wgt;
        assert edge_relaxed(prev, after, u, v, wgt);
        lemma_edges_at_push(g, prev, after, u, e);

        forall t | 0 <= t < |g|
            ensures le_opt(after[t], prev[t])
        {
            if t == v {
                if prev[v].Some? {
                    assert le_opt(before[v], prev[v]);
                    assert before[v].Some?;
                    assert before[v].value <= prev[v].value;
                    assert du + wgt < before[v].value;
                    assert after[v] == Some(du + wgt);
                    assert after[v].value <= prev[v].value;
                }
            } else {
                assert after[t] == before[t];
                assert le_opt(before[t], prev[t]);
            }
        }

        if v == start {
            assert before[start].Some?;
            assert du + wgt < before[start].value;
            assert before[start].value <= 0;
            assert after[start] == Some(du + wgt);
            assert after[start].value < before[start].value <= 0;
            assert after[start].value <= 0;
        } else {
            assert after[start] == before[start];
        }
    } else {
        assert after == before && witAfter == witBefore;
        assert witness_ok(g, start, after, witAfter);
        assert forall t :: 0 <= t < |g| ==> le_opt(after[t], prev[t]);
        assert edges_before(g, prev, after, u);
        assert edges_at(g, prev, after, u, e);
        // Not an improving edge, so the snapshot inequality already holds.
        if prev[u].Some? {
            var pdu := prev[u].value;
            assert !(before[v].None? || pdu + wgt < before[v].value);
            assert before[v].Some?;
            assert before[v].value <= pdu + wgt;
            assert edge_relaxed(prev, after, u, v, wgt);
        } else {
            assert edge_relaxed(prev, after, u, v, wgt);
        }
        lemma_edges_at_push(g, prev, after, u, e);
        assert after[start] == before[start];
    }
}

lemma lemma_extend_bounds(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, prev: seq<Option<int>>, dist: seq<Option<int>>, k: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |prev| == |g| && |dist| == |g|
    requires 0 <= k
    requires dist_bounds_paths(g, start, prev, k)
    requires forall t :: 0 <= t < |g| ==> le_opt(dist[t], prev[t])
    requires edges_before(g, prev, dist, |g|)
    ensures dist_bounds_paths(g, start, dist, k + 1)
{
    reveal dist_bounds_paths;
    forall p: seq<int> {:trigger is_path(g, p)} | |p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= k + 1
        ensures 0 <= p[|p| - 1] < |dist| && dist[p[|p| - 1]].Some? && dist[p[|p| - 1]].value <= path_weight(g, p)
    {
        if |p| - 1 <= k {
            lemma_bound_one(g, start, prev, k, p);
            var vend := p[|p| - 1];
            assert 0 <= vend < |prev|;
            assert prev[vend].Some?;
            assert le_opt(dist[vend], prev[vend]);
            assert dist[vend].Some?;
            assert dist[vend].value <= prev[vend].value <= path_weight(g, p);
        } else {
            assert |p| - 1 == k + 1;
            assert |p| >= 2;
            var prefix := p[..|p| - 1];
            lemma_sub_is_path(g, p, 0, |p| - 1);
            assert is_path(g, prefix);
            assert |prefix| > 0;
            assert prefix[0] == p[0] == start;
            assert |prefix| - 1 == k;
            lemma_bound_one(g, start, prev, k, prefix);
            var u := p[|p| - 2];
            var v := p[|p| - 1];
            assert u == prefix[|prefix| - 1];
            assert 0 <= u < |prev|;
            assert prev[u].Some?;
            var du := prev[u].value;
            assert du <= path_weight(g, prefix);
            assert connected(g, u, v);
            var w, i := lemma_connected_weight(graph, g, u, v);
            lemma_one_relaxed(g, prev, dist, |g|, u, i);
            assert g[u][i].0 == v && g[u][i].1 == w;
            assert edge_relaxed(prev, dist, u, v, w);
            assert dist[v].Some? && dist[v].value <= du + w;
            lemma_snoc_eq(p);
            assert p == prefix + [v];
            lemma_path_weight_def(g, p);
            assert get_edge_weight(g, u, v) == w;
            assert path_weight(g, p) == path_weight(g, prefix) + w;
            assert dist[v].value <= du + w <= path_weight(g, p);
            assert 0 <= v < |g|;
            assert 0 <= v < |dist|;
        }
    }
}

lemma lemma_path_lower_bound(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, p: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |dist| == |g|
    requires edges_before(g, dist, dist, |g|)
    requires dist[start].Some? && dist[start].value <= 0
    requires is_path(g, p)
    requires |p| > 0 && p[0] == start
    ensures 0 <= p[|p| - 1] < |dist|
    ensures dist[p[|p| - 1]].Some?
    ensures dist[p[|p| - 1]].value <= path_weight(g, p)
    decreases |p|
{
    if |p| == 1 {
        assert p[0] == start;
        lemma_single_weight(g, p);
        assert path_weight(g, p) == 0;
        assert dist[start].value <= 0;
    } else {
        var prefix := p[..|p| - 1];
        lemma_sub_is_path(g, p, 0, |p| - 1);
        assert is_path(g, prefix);
        assert prefix[0] == start;
        lemma_path_lower_bound(graph, g, start, dist, prefix);
        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert u == prefix[|prefix| - 1];
        assert dist[u].Some?;
        assert connected(g, u, v);
        var w, i := lemma_connected_weight(graph, g, u, v);
        lemma_one_relaxed(g, dist, dist, |g|, u, i);
        assert edge_relaxed(dist, dist, u, v, w);
        assert dist[v].Some? && dist[v].value <= dist[u].value + w;
        lemma_path_weight_def(g, p);
        lemma_snoc_eq(p);
        assert p[..|p| - 1] == prefix;
        assert get_edge_weight(g, u, v) == w;
        assert path_weight(g, p) == path_weight(g, prefix) + w;
        assert dist[u].value <= path_weight(g, prefix);
        assert dist[v].value <= path_weight(g, p);
        assert 0 <= v < |dist|;
    }
}

lemma lemma_some_post(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, witness: seq<seq<int>>)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |dist| == |g|
    requires witness_ok(g, start, dist, witness)
    requires edges_before(g, dist, dist, |g|)
    requires dist[start].Some? && dist[start].value <= 0
    ensures |dist| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==> (
        match dist[v] {
            case Some(d) => is_shortest_dist(view(graph), start, v, d)
            case None => forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                            is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    )
{
    assert size(graph) == |g|;
    forall v | 0 <= v < |g|
        ensures match dist[v] {
            case Some(d) => is_shortest_dist(g, start, v, d)
            case None => forall p: seq<int> {:trigger is_path(g, p)} ::
                is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    {
        if dist[v].Some? {
            var d := dist[v].value;
            lemma_witness_one(g, start, dist, witness, v);
            var wp := witness[v];
            assert is_path(g, wp);
            assert wp[0] == start && wp[|wp| - 1] == v && path_weight(g, wp) == d;
            forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == v
                ensures path_weight(g, r) >= d
            {
                assert |r| > 0;
                lemma_path_lower_bound(graph, g, start, dist, r);
                assert dist[v].value <= path_weight(g, r);
            }
            assert is_shortest_dist(g, start, v, d);
        } else {
            forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == v
                ensures false
            {
                assert |r| > 0;
                lemma_path_lower_bound(graph, g, start, dist, r);
                assert dist[v].Some?;
                assert false;
            }
        }
    }
}

lemma lemma_violating_edge(
    graph: WeightedGraph,
    g: seq<seq<(int, int)>>,
    start: int,
    dist: seq<Option<int>>,
    witness: seq<seq<int>>,
    u: int,
    e: int
)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |dist| == |g|
    requires witness_ok(g, start, dist, witness)
    requires dist_bounds_paths(g, start, dist, |g| - 1)
    requires 0 <= u < |g|
    requires 0 <= e < |g[u]|
    requires dist[u].Some?
    requires var v := g[u][e].0;
            var wgt := g[u][e].1;
            0 <= v < |g| &&
            (dist[v].None? || dist[u].value + wgt < dist[v].value)
    ensures has_negative_cycle(view(graph))
{
    var v := g[u][e].0;
    var wgt := g[u][e].1;
    lemma_target_in_range(graph, u, e);
    assert 0 <= v < |g|;
    if !has_negative_cycle(g) {
        var du := dist[u].value;
        lemma_witness_one(g, start, dist, witness, u);
        var src := witness[u];
        lemma_adj_edge(graph, g, u, e);
        assert has_edge(g, u, v, wgt);
        assert get_edge_weight(g, u, v) == wgt;
        lemma_extend_path(g, src, v, wgt);
        var p := src + [v];
        assert is_path(g, p);
        assert p[0] == start && p[|p| - 1] == v;
        assert path_weight(g, p) == du + wgt;
        var q := lemma_shorten(graph, g, p);
        assert is_path(g, q);
        assert |q| > 0 && |q| <= |g|;
        assert q[0] == start && q[|q| - 1] == v;
        assert |q| - 1 <= |g| - 1;
        assert path_weight(g, q) <= path_weight(g, p);
        lemma_bound_one(g, start, dist, |g| - 1, q);
        assert dist[v].Some?;
        assert dist[v].value <= path_weight(g, q);
        assert dist[v].value <= du + wgt;
        assert dist[v].None? || du + wgt < dist[v].value;
        assert false;
    }
    assert has_negative_cycle(g);
    assert has_negative_cycle(view(graph));
}

lemma lemma_note_edge(g: seq<seq<(int, int)>>, dist: seq<Option<int>>, u: int, e: int)
    requires 0 <= u < |g|
    requires 0 <= e < |g[u]|
    requires |dist| == |g|
    requires 0 <= g[u][e].0 < |g|
    requires edges_at(g, dist, dist, u, e)
    requires var v := g[u][e].0;
            var wgt := g[u][e].1;
            !(dist[u].Some? && (dist[v].None? || dist[u].value + wgt < dist[v].value))
    ensures edges_at(g, dist, dist, u, e + 1)
{
    var v := g[u][e].0;
    var wgt := g[u][e].1;
    if dist[u].Some? {
        assert !(dist[v].None? || dist[u].value + wgt < dist[v].value);
        assert dist[v].Some?;
        assert !(dist[u].value + wgt < dist[v].value);
        assert dist[v].value <= dist[u].value + wgt;
    }
    assert edge_relaxed(dist, dist, u, v, wgt);
    lemma_edges_at_push(g, dist, dist, u, e);
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p] - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
    ghost var g := view(graph);
    var n := |graph.adj|;
    assert g == graph.adj;
    assert |g| == n;
    assert n == size(graph);
    assert 0 <= start < n;

    var dist: seq<Option<int>> := seq(n, i => if i == start then Some(0) else None);
    ghost var witness: seq<seq<int>> := seq(n, i => if i == start then [start] else []);
    lemma_init(graph, g, start, dist, witness);

    var iter := 0;
    while iter < n - 1
        invariant 0 <= iter <= n - 1
        invariant g == view(graph) && |g| == n
        invariant |dist| == n && |witness| == n
        invariant witness_ok(g, start, dist, witness)
        invariant dist_bounds_paths(g, start, dist, iter)
        invariant dist[start].Some? && dist[start].value <= 0
        decreases n - 1 - iter
    {
        var prev := dist;
        ghost var prevWit := witness;
        lemma_le_opt_refl(prev);
        lemma_edges_before_zero(g, prev, dist);

        var u := 0;
        while u < n
            invariant 0 <= u <= n
            invariant g == view(graph) && |g| == n
            invariant |prev| == n && |dist| == n && |witness| == n && |prevWit| == n
            invariant witness_ok(g, start, prev, prevWit)
            invariant witness_ok(g, start, dist, witness)
            invariant dist_bounds_paths(g, start, prev, iter)
            invariant forall t :: 0 <= t < n ==> le_opt(dist[t], prev[t])
            invariant edges_before(g, prev, dist, u)
            invariant prev[start].Some? && prev[start].value <= 0
            invariant dist[start].Some? && dist[start].value <= 0
            decreases n - u
        {
            lemma_edges_at_zero(g, prev, dist, u);
            var e := 0;
            while e < |graph.adj[u]|
                invariant 0 <= e <= |graph.adj[u]|
                invariant 0 <= u < |g|
                invariant g == view(graph) && |g| == n && graph.adj == g
                invariant |prev| == n && |dist| == n && |witness| == n && |prevWit| == n
                invariant witness_ok(g, start, prev, prevWit)
                invariant witness_ok(g, start, dist, witness)
                invariant dist_bounds_paths(g, start, prev, iter)
                invariant forall t :: 0 <= t < n ==> le_opt(dist[t], prev[t])
                invariant edges_before(g, prev, dist, u)
                invariant edges_at(g, prev, dist, u, e)
                invariant prev[start].Some? && prev[start].value <= 0
                invariant dist[start].Some? && dist[start].value <= 0
                decreases |graph.adj[u]| - e
            {
                var v := graph.adj[u][e].0;
                var wgt := graph.adj[u][e].1;
                lemma_target_in_range(graph, u, e);
                assert 0 <= v < n;

                var before := dist;
                ghost var witBefore := witness;
                var updated := false;
                var du := 0;
                ghost var nw: seq<int> := [];
                if prev[u].Some? && (dist[v].None? || prev[u].value + wgt < dist[v].value) {
                    du := prev[u].value;
                    nw := prevWit[u] + [v];
                    dist := dist[v := Some(du + wgt)];
                    witness := witness[v := nw];
                    updated := true;
                }
                lemma_advance_edge(graph, g, start, prev, prevWit, before, witBefore, dist, witness, u, e, v, wgt, updated, du, nw);
                e := e + 1;
            }
            lemma_close_vertex(g, prev, dist, u);
            u := u + 1;
        }
        lemma_extend_bounds(graph, g, start, prev, dist, iter);
        iter := iter + 1;
    }

    assert iter == n - 1;
    assert dist_bounds_paths(g, start, dist, n - 1);

    var bad := false;
    var u := 0;
    lemma_edges_before_zero(g, dist, dist);
    while u < n && !bad
        invariant 0 <= u <= n
        invariant g == view(graph) && |g| == n
        invariant |dist| == n && |witness| == n
        invariant witness_ok(g, start, dist, witness)
        invariant dist_bounds_paths(g, start, dist, n - 1)
        invariant dist[start].Some? && dist[start].value <= 0
        invariant bad ==> has_negative_cycle(view(graph))
        invariant !bad ==> edges_before(g, dist, dist, u)
        decreases n - u
    {
        lemma_edges_at_zero(g, dist, dist, u);
        var e := 0;
        while e < |graph.adj[u]| && !bad
            invariant 0 <= e <= |graph.adj[u]|
            invariant 0 <= u < n
            invariant g == view(graph) && |g| == n && graph.adj == g
            invariant |dist| == n && |witness| == n
            invariant witness_ok(g, start, dist, witness)
            invariant dist_bounds_paths(g, start, dist, n - 1)
            invariant dist[start].Some? && dist[start].value <= 0
            invariant bad ==> has_negative_cycle(view(graph))
            invariant !bad ==> edges_before(g, dist, dist, u)
            invariant !bad ==> edges_at(g, dist, dist, u, e)
            decreases |graph.adj[u]| - e
        {
            var v := graph.adj[u][e].0;
            var wgt := graph.adj[u][e].1;
            lemma_target_in_range(graph, u, e);
            assert 0 <= v < n;
            if dist[u].Some? && (dist[v].None? || dist[u].value + wgt < dist[v].value) {
                lemma_violating_edge(graph, g, start, dist, witness, u, e);
                bad := true;
            } else {
                lemma_note_edge(g, dist, u, e);
                e := e + 1;
            }
        }
        if !bad {
            assert e == |graph.adj[u]|;
            lemma_close_vertex(g, dist, dist, u);
            u := u + 1;
        }
    }

    if bad {
        assert has_negative_cycle(view(graph));
        res := None;
    } else {
        assert u == n;
        assert edges_before(g, dist, dist, n);
        lemma_some_post(graph, g, start, dist, witness);
        res := Some(dist);
    }
}

