lemma lemma_path_weight_def(g: seq<seq<(int, int)>>, p: seq<int>)
    requires |p| >= 2
    ensures path_weight(g, p) == path_weight(g, p[..|p| - 1]) + get_edge_weight(g, p[|p| - 2], p[|p| - 1])
{
}

lemma lemma_single_weight(g: seq<seq<(int, int)>>, p: seq<int>)
    requires |p| < 2
    ensures path_weight(g, p) == 0
{
}

lemma lemma_snoc_eq(a: seq<int>)
    requires |a| >= 1
    ensures a[..|a| - 1] + [a[|a| - 1]] == a
{
    var b := a[..|a| - 1] + [a[|a| - 1]];
    assert |b| == |a|;
    forall k | 0 <= k < |a|
        ensures b[k] == a[k]
    {
        if k < |a| - 1 {
            assert b[k] == a[k];
        } else {
            assert k == |a| - 1;
            assert b[k] == a[|a| - 1];
        }
    }
}

lemma lemma_append_drop(p: seq<int>, v: int)
    ensures |p + [v]| == |p| + 1
    ensures (p + [v])[|p|] == v
    ensures (p + [v])[..|p|] == p
{
    var q := p + [v];
    assert |q| == |p| + 1;
    assert q[|p|] == v;
    var pre := q[..|p|];
    assert |pre| == |p|;
    forall k | 0 <= k < |p|
        ensures pre[k] == p[k]
    {
        assert q[k] == p[k];
        assert pre[k] == q[k];
    }
}

lemma lemma_slice_snoc(p: seq<int>, s: int, t: int)
    requires 0 <= s < t <= |p|
    ensures p[s..t] == p[s..t - 1] + [p[t - 1]]
{
    var q := p[s..t];
    var q0 := p[s..t - 1] + [p[t - 1]];
    assert |q| == t - s;
    assert |q0| == t - s;
    forall k | 0 <= k < |q|
        ensures q[k] == q0[k]
    {
        if k < t - 1 - s {
            assert q[k] == p[s + k];
            assert (p[s..t - 1])[k] == p[s + k];
            assert q0[k] == p[s + k];
        } else {
            assert k == |q| - 1;
            assert q[k] == p[t - 1];
            assert q0[k] == p[t - 1];
        }
    }
}

lemma lemma_sub_is_path(g: seq<seq<(int, int)>>, p: seq<int>, s: int, t: int)
    requires is_path(g, p)
    requires 0 <= s < t <= |p|
    ensures is_path(g, p[s..t])
    decreases t - s
{
    var q := p[s..t];
    assert |q| == t - s > 0;
    if s + 1 == t {
        assert |q| == 1;
        assert is_path(g, q);
    } else {
        lemma_sub_is_path(g, p, s, t - 1);
        var q0 := p[s..t - 1];
        lemma_slice_snoc(p, s, t);
        assert q == q0 + [p[t - 1]];
        assert 0 <= t - 2 < |p| - 1;
        assert connected(g, p[t - 2], p[t - 1]);
        forall i | 0 <= i < |q| - 1
            ensures connected(g, q[i], q[i + 1])
        {
            if i < |q0| - 1 {
                assert 0 <= i < |q0| - 1;
                assert q[i] == q0[i];
                assert q[i + 1] == q0[i + 1];
                assert is_path(g, q0);
                assert connected(g, q0[i], q0[i + 1]);
            } else {
                assert i == |q| - 2;
                assert |q0| == |q| - 1;
                assert q0[|q0| - 1] == p[t - 2];
                assert q[i] == q0[i];
                assert q[i] == p[t - 2];
                assert q[i + 1] == p[t - 1];
                assert connected(g, p[t - 2], p[t - 1]);
            }
        }
        assert is_path(g, q);
    }
}

lemma lemma_adj_edge(graph: WeightedGraph, g: seq<seq<(int, int)>>, u: int, i: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= u < |g|
    requires 0 <= i < |g[u]|
    ensures 0 <= g[u][i].0 < |g|
    ensures has_edge(g, u, g[u][i].0, g[u][i].1)
    ensures get_edge_weight(g, u, g[u][i].0) == g[u][i].1
    ensures forall w' :: has_edge(g, u, g[u][i].0, w') ==> w' == g[u][i].1
{
    assert g == graph.adj;
    var v := g[u][i].0;
    var w := g[u][i].1;
    lemma_target_in_range(graph, u, i);
    assert 0 <= v < |g|;
    assert 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
    assert has_edge(g, u, v, w);

    forall w' | has_edge(g, u, v, w')
        ensures w' == w
    {
        var j :| 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
        if j != i {
            assert 0 <= u < |graph.adj|;
            assert 0 <= i < |graph.adj[u]| && 0 <= j < |graph.adj[u]|;
            assert graph.adj[u][i].0 != graph.adj[u][j].0;
            assert false;
        }
        assert w' == w;
    }
    assert forall w' :: has_edge(g, u, v, w') ==> w' == w;
    assert has_edge(g, u, v, w);
    assert get_edge_weight(g, u, v) == w;
}

lemma lemma_connected_weight(graph: WeightedGraph, g: seq<seq<(int, int)>>, u: int, v: int) returns (w: int, i: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= u < |g|
    requires connected(g, u, v)
    ensures 0 <= i < |g[u]|
    ensures g[u][i].0 == v && g[u][i].1 == w
    ensures has_edge(g, u, v, w)
    ensures get_edge_weight(g, u, v) == w
    ensures 0 <= v < |g|
{
    var w0 :| has_edge(g, u, v, w0);
    var i0 :| 0 <= i0 < |g[u]| && g[u][i0].0 == v && g[u][i0].1 == w0;
    lemma_adj_edge(graph, g, u, i0);
    w, i := w0, i0;
}

lemma lemma_extend_path(g: seq<seq<(int, int)>>, p: seq<int>, v: int, w: int)
    requires |p| >= 1
    requires is_path(g, p)
    requires has_edge(g, p[|p| - 1], v, w)
    requires get_edge_weight(g, p[|p| - 1], v) == w
    ensures is_path(g, p + [v])
    ensures (p + [v])[0] == p[0]
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(g, p + [v]) == path_weight(g, p) + w
{
    var q := p + [v];
    lemma_append_drop(p, v);
    assert |q| == |p| + 1;
    assert q[0] == p[0];
    assert q[|q| - 1] == v;
    assert q[..|q| - 1] == p;
    forall i | 0 <= i < |q| - 1
        ensures connected(g, q[i], q[i + 1])
    {
        if i < |p| - 1 {
            assert q[i] == p[i] && q[i + 1] == p[i + 1];
            assert connected(g, p[i], p[i + 1]);
        } else {
            assert i == |p| - 1;
            assert q[i] == p[|p| - 1];
            assert q[i + 1] == v;
            assert has_edge(g, p[|p| - 1], v, w);
            assert connected(g, p[|p| - 1], v);
        }
    }
    assert is_path(g, q);
    lemma_path_weight_def(g, q);
    assert q[|q| - 2] == p[|p| - 1];
    assert get_edge_weight(g, q[|q| - 2], q[|q| - 1]) == w;
    assert path_weight(g, q) == path_weight(g, p) + w;
}

lemma lemma_path_weight_concat(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
    requires |a| >= 1 && |b| >= 1
    requires a[|a| - 1] == b[0]
    ensures var q := a[..|a| - 1] + b;
        path_weight(g, q) == path_weight(g, a) + path_weight(g, b)
    decreases |b|
{
    if |b| == 1 {
        lemma_single_weight(g, b);
        lemma_snoc_eq(a);
        assert a[..|a| - 1] + b == a;
    } else {
        var b0 := b[..|b| - 1];
        assert |b0| >= 1;
        assert b0[0] == b[0];
        assert a[|a| - 1] == b0[0];
        lemma_path_weight_concat(g, a, b0);
        var q0 := a[..|a| - 1] + b0;
        var q := a[..|a| - 1] + b;
        lemma_slice_snoc(b, 0, |b|);
        assert b == b0 + [b[|b| - 1]];
        assert q == q0 + [b[|b| - 1]];
        lemma_append_drop(q0, b[|b| - 1]);
        assert |q| >= 2;
        lemma_path_weight_def(g, q);
        lemma_path_weight_def(g, b);
        assert q[|q| - 2] == q0[|q0| - 1];
        assert |q0| >= 1;
        assert q0[|q0| - 1] == b0[|b0| - 1];
        assert b[|b| - 2] == b0[|b0| - 1];
        assert get_edge_weight(g, q[|q| - 2], q[|q| - 1]) == get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, q) == path_weight(g, q0) + get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, b) == path_weight(g, b0) + get_edge_weight(g, b[|b| - 2], b[|b| - 1]);
        assert path_weight(g, q0) == path_weight(g, a) + path_weight(g, b0);
        assert path_weight(g, q) == path_weight(g, a) + path_weight(g, b);
    }
}

lemma lemma_join_paths(g: seq<seq<(int, int)>>, a: seq<int>, b: seq<int>)
    requires is_path(g, a) && is_path(g, b)
    requires |a| >= 1 && |b| >= 1
    requires a[|a| - 1] == b[0]
    ensures is_path(g, a[..|a| - 1] + b)
{
    var q := a[..|a| - 1] + b;
    assert |q| == |a| - 1 + |b|;
    assert |q| >= 1;
    if |a| == 1 {
        assert a[..|a| - 1] == [];
        assert q == b;
        assert is_path(g, q);
    } else {
        forall i | 0 <= i < |q| - 1
            ensures connected(g, q[i], q[i + 1])
        {
            var L := |a| - 1;
            if i < L - 1 {
                assert q[i] == a[i];
                assert q[i + 1] == a[i + 1];
                assert 0 <= i < |a| - 1;
                assert connected(g, a[i], a[i + 1]);
            } else if i == L - 1 {
                assert q[i] == a[L - 1];
                assert a[L - 1] == a[|a| - 2];
                assert q[i + 1] == b[0];
                assert b[0] == a[|a| - 1];
                assert connected(g, a[|a| - 2], a[|a| - 1]);
            } else {
                assert i >= L;
                var j := i - L;
                assert 0 <= j < |b| - 1;
                assert q[i] == b[j];
                assert q[i + 1] == b[j + 1];
                assert connected(g, b[j], b[j + 1]);
            }
        }
        assert is_path(g, q);
    }
}

lemma lemma_path_weight_split(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, p[k..])
    decreases |p| - k
{
    if k == |p| - 1 {
        assert p[..k + 1] == p;
        assert p[k..] == [p[k]];
        lemma_single_weight(g, p[k..]);
    } else {
        lemma_sub_is_path(g, p, 0, |p| - 1);
        var p0 := p[..|p| - 1];
        assert is_path(g, p0);
        assert 0 <= k < |p0|;
        lemma_path_weight_split(g, p0, k);
        lemma_path_weight_def(g, p);
        assert p[..k + 1] == p0[..k + 1];
        var suf := p[k..];
        var suf0 := p[k..|p| - 1];
        lemma_slice_snoc(p, k, |p|);
        assert suf == suf0 + [p[|p| - 1]];
        assert p0[k..] == suf0;
        assert |suf| >= 2;
        lemma_path_weight_def(g, suf);
        assert suf[..|suf| - 1] == suf0;
        assert suf[|suf| - 2] == p[|p| - 2];
        assert suf[|suf| - 1] == p[|p| - 1];
        assert path_weight(g, p0) == path_weight(g, p[..k + 1]) + path_weight(g, suf0);
        assert path_weight(g, p) == path_weight(g, p0) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
        assert path_weight(g, suf) == path_weight(g, suf0) + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
        assert path_weight(g, p) == path_weight(g, p[..k + 1]) + path_weight(g, suf);
    }
}

lemma lemma_path_node_at(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>, idx: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    requires 0 <= idx < |p|
    ensures 0 <= p[idx] < |g|
    decreases idx
{
    if idx == 0 {
    } else {
        lemma_path_node_at(graph, g, p, idx - 1);
        assert connected(g, p[idx - 1], p[idx]);
        var u := p[idx - 1];
        var v := p[idx];
        var w, i := lemma_connected_weight(graph, g, u, v);
        assert 0 <= v < |g|;
    }
}

lemma lemma_path_nodes(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    ensures forall idx :: 0 <= idx < |p| ==> 0 <= p[idx] < |g|
{
    forall idx | 0 <= idx < |p|
        ensures 0 <= p[idx] < |g|
    {
        lemma_path_node_at(graph, g, p, idx);
    }
}

lemma lemma_compress_inj(x: int, y: int, skip: int)
    requires x != skip && y != skip
    requires compress_one(x, skip) == compress_one(y, skip)
    ensures x == y
{
    if x < skip && y < skip {
        assert x == y;
    } else if x >= skip && y >= skip {
        assert x - 1 == y - 1;
        assert x == y;
    } else if x < skip && y >= skip {
        assert x == y - 1;
        assert y <= skip;
        assert y == skip;
        assert false;
    } else {
        assert y == x - 1;
        assert x <= skip;
        assert x == skip;
        assert false;
    }
}

lemma lemma_pigeonhole(p: seq<int>, n: int)
    requires 0 <= n < |p|
    requires forall i :: 0 <= i < |p| ==> 0 <= p[i] < n
    ensures exists i, j :: 0 <= i < j < |p| && p[i] == p[j]
    decreases n
{
    if exists i :: 0 <= i < |p| - 1 && p[i] == p[|p| - 1] {
        var i :| 0 <= i < |p| - 1 && p[i] == p[|p| - 1];
        assert 0 <= i < |p| - 1 < |p|;
        assert p[i] == p[|p| - 1];
    } else {
        var prefix := p[..|p| - 1];
        var skip := p[|p| - 1];
        assert forall i :: 0 <= i < |prefix| ==> prefix[i] != skip;
        assert |prefix| == |p| - 1;
        assert |prefix| >= n;
        if n == 1 {
            assert |prefix| >= 1;
            assert 0 <= prefix[0] < 1;
            assert 0 <= skip < 1;
            assert prefix[0] != skip;
            assert false;
        } else {
            var mapped := seq(|prefix|, i => compress_one(prefix[i], skip));
            forall i | 0 <= i < |mapped|
                ensures 0 <= mapped[i] < n - 1
            {
                assert mapped[i] == compress_one(prefix[i], skip);
                var x := prefix[i];
                assert 0 <= x < n && x != skip;
                assert 0 <= skip < n;
                if x < skip {
                    assert compress_one(x, skip) == x;
                    assert 0 <= x <= skip - 1;
                    assert skip - 1 <= n - 2;
                    assert 0 <= mapped[i] < n - 1;
                } else {
                    assert x > skip;
                    assert compress_one(x, skip) == x - 1;
                    assert x >= skip + 1;
                    assert 0 <= x - 1 <= n - 2;
                    assert 0 <= mapped[i] < n - 1;
                }
            }
            assert |mapped| == |prefix|;
            assert 0 <= n - 1 < |mapped|;
            lemma_pigeonhole(mapped, n - 1);
            var a, b :| 0 <= a < b < |mapped| && mapped[a] == mapped[b];
            lemma_compress_inj(prefix[a], prefix[b], skip);
            assert prefix[a] == prefix[b];
            assert p[a] == p[b];
            assert 0 <= a < b < |p|;
        }
    }
}

lemma lemma_cycle_nonneg(g: seq<seq<(int, int)>>, c: seq<int>)
    requires !has_negative_cycle(g)
    requires is_path(g, c)
    requires |c| > 1
    requires c[0] == c[|c| - 1]
    ensures path_weight(g, c) >= 0
{
    if path_weight(g, c) < 0 {
        assert is_path(g, c);
        assert |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
        assert has_negative_cycle(g);
        assert false;
    }
}

lemma lemma_cut_cycle(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>, i: int, j: int) returns (q: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    requires !has_negative_cycle(g)
    ensures is_path(g, q)
    ensures |q| > 0 && |q| < |p|
    ensures q[0] == p[0] && q[|q| - 1] == p[|p| - 1]
    ensures path_weight(g, q) <= path_weight(g, p)
    ensures 0 <= q[0] < |g|
{
    lemma_path_nodes(graph, g, p);
    var c := p[i..j + 1];
    lemma_sub_is_path(g, p, i, j + 1);
    assert is_path(g, c);
    assert |c| == j + 1 - i >= 2;
    assert c[0] == p[i] && c[|c| - 1] == p[j];
    assert c[0] == c[|c| - 1];
    lemma_cycle_nonneg(g, c);

    var a := p[..i + 1];
    var b := p[j..];
    lemma_sub_is_path(g, p, 0, i + 1);
    lemma_sub_is_path(g, p, j, |p|);
    assert is_path(g, a) && is_path(g, b);
    assert |a| == i + 1 >= 1;
    assert |b| >= 1;
    assert a[|a| - 1] == p[i] == p[j] == b[0];

    lemma_path_weight_split(g, p, j);
    var pj := p[..j + 1];
    lemma_sub_is_path(g, p, 0, j + 1);
    assert is_path(g, pj);
    lemma_path_weight_split(g, pj, i);
    assert pj[..i + 1] == a;
    assert pj[i..] == c;
    assert path_weight(g, p) == path_weight(g, pj) + path_weight(g, b);
    assert path_weight(g, pj) == path_weight(g, a) + path_weight(g, c);
    assert path_weight(g, p) == path_weight(g, a) + path_weight(g, c) + path_weight(g, b);

    q := p[..i] + p[j..];
    lemma_path_weight_concat(g, a, b);
    assert a[..|a| - 1] + b == q;
    assert path_weight(g, q) == path_weight(g, a) + path_weight(g, b);
    assert path_weight(g, c) >= 0;
    assert path_weight(g, q) <= path_weight(g, p);

    lemma_join_paths(g, a, b);
    assert is_path(g, q);
    assert |q| == i + |p| - j;
    assert j - i >= 1;
    assert |q| < |p|;
    assert |q| >= 1;
    if i == 0 {
        assert q == b;
        assert q[0] == b[0] == p[0];
    } else {
        assert q[0] == p[0];
    }
    assert |b| >= 1;
    assert q[|q| - 1] == b[|b| - 1] == p[|p| - 1];
    assert 0 <= q[0] < |g|;
}

lemma lemma_shorten(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>) returns (q: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    requires !has_negative_cycle(g)
    ensures is_path(g, q)
    ensures |q| > 0 && |q| <= |g|
    ensures q[0] == p[0] && q[|q| - 1] == p[|p| - 1]
    ensures path_weight(g, q) <= path_weight(g, p)
    decreases |p|
{
    if |p| <= |g| {
        q := p;
    } else {
        lemma_path_nodes(graph, g, p);
        assert forall idx :: 0 <= idx < |p| ==> 0 <= p[idx] < |g|;
        assert 0 <= |g| < |p|;
        lemma_pigeonhole(p, |g|);
        var i, j :| 0 <= i < j < |p| && p[i] == p[j];
        var q1 := lemma_cut_cycle(graph, g, p, i, j);
        q := lemma_shorten(graph, g, q1);
        assert path_weight(g, q) <= path_weight(g, q1) <= path_weight(g, p);
        assert q[0] == q1[0] == p[0];
        assert q[|q| - 1] == q1[|q1| - 1] == p[|p| - 1];
    }
}

lemma lemma_witness_one(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, witness: seq<seq<int>>, v: int)
    requires witness_ok(g, start, dist, witness)
    requires 0 <= v < |g|
    requires |dist| == |g|
    requires dist[v].Some?
    ensures |witness[v]| > 0
    ensures is_path(g, witness[v])
    ensures witness[v][0] == start
    ensures witness[v][|witness[v]| - 1] == v
    ensures path_weight(g, witness[v]) == dist[v].value
{
    reveal witness_ok;
    assert 0 <= v < |g| && dist[v].Some?;
    assert |witness[v]| > 0;
    assert is_path(g, witness[v]);
    assert witness[v][0] == start;
    assert witness[v][|witness[v]| - 1] == v;
    assert path_weight(g, witness[v]) == dist[v].value;
}

lemma lemma_bound_one(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, k: int, p: seq<int>)
    requires dist_bounds_paths(g, start, dist, k)
    requires |p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= k
    ensures 0 <= p[|p| - 1] < |dist|
    ensures dist[p[|p| - 1]].Some?
    ensures dist[p[|p| - 1]].value <= path_weight(g, p)
{
    reveal dist_bounds_paths;
    assert |p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= k;
    assert dist[p[|p| - 1]].Some?;
    assert dist[p[|p| - 1]].value <= path_weight(g, p);
}

lemma lemma_one_relaxed(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u_lim: int, u: int, i: int)
    requires edges_before(g, prev, dist, u_lim)
    requires 0 <= u < u_lim && 0 <= u < |g| && 0 <= i < |g[u]|
    ensures edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1)
{
    reveal edges_before;
    assert edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1);
}

lemma lemma_edges_before_zero(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>)
    ensures edges_before(g, prev, dist, 0)
{
    reveal edges_before;
    assert forall u, i :: 0 <= u < 0 && 0 <= u < |g| && 0 <= i < |g[u]| ==>
        edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1);
}

lemma lemma_edges_at_zero(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u: int)
    requires 0 <= u < |g|
    ensures edges_at(g, prev, dist, u, 0)
{
    reveal edges_at;
    assert forall i :: 0 <= i < 0 ==>
        (0 <= u < |g| && i < |g[u]| ==> edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1));
}

lemma lemma_edges_at_push(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u: int, e_lim: int)
    requires 0 <= u < |g|
    requires 0 <= e_lim < |g[u]|
    requires edges_at(g, prev, dist, u, e_lim)
    requires edge_relaxed(prev, dist, u, g[u][e_lim].0, g[u][e_lim].1)
    ensures edges_at(g, prev, dist, u, e_lim + 1)
{
    reveal edges_at;
    forall i | 0 <= i < e_lim + 1
        ensures 0 <= u < |g| && i < |g[u]| ==> edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1)
    {
        if i < e_lim {
            assert edges_at(g, prev, dist, u, e_lim);
            assert 0 <= u < |g| && i < |g[u]| ==> edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1);
        } else {
            assert i == e_lim;
            assert edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1);
        }
    }
}

lemma lemma_close_vertex(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u: int)
    requires 0 <= u < |g|
    requires edges_before(g, prev, dist, u)
    requires edges_at(g, prev, dist, u, |g[u]|)
    ensures edges_before(g, prev, dist, u + 1)
{
    reveal edges_before;
    reveal edges_at;
    forall uu, i | 0 <= uu < u + 1 && 0 <= uu < |g| && 0 <= i < |g[uu]|
        ensures edge_relaxed(prev, dist, uu, g[uu][i].0, g[uu][i].1)
    {
        if uu < u {
            assert edge_relaxed(prev, dist, uu, g[uu][i].0, g[uu][i].1);
        } else {
            assert uu == u;
            assert 0 <= i < |g[u]|;
            assert edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1);
        }
    }
}

lemma lemma_edges_mono(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, before: seq<Option<int>>, after: seq<Option<int>>, u_lim: int, u: int, e_lim: int, v: int, newd: int)
    requires |g| == |prev| == |before| == |after|
    requires 0 <= v < |g|
    requires 0 <= u < |g|
    requires 0 <= u_lim <= |g|
    requires 0 <= e_lim <= |g[u]|
    requires after == before[v := Some(newd)]
    requires before[v].None? || (before[v].Some? && newd <= before[v].value)
    requires edges_before(g, prev, before, u_lim)
    requires edges_at(g, prev, before, u, e_lim)
    ensures edges_before(g, prev, after, u_lim)
    ensures edges_at(g, prev, after, u, e_lim)
{
    reveal edges_before;
    reveal edges_at;
    forall uu, i | 0 <= uu < u_lim && 0 <= uu < |g| && 0 <= i < |g[uu]|
        ensures edge_relaxed(prev, after, uu, g[uu][i].0, g[uu][i].1)
    {
        var tv := g[uu][i].0;
        var tw := g[uu][i].1;
        assert edge_relaxed(prev, before, uu, tv, tw);
        if 0 <= uu < |prev| && 0 <= tv < |before| && prev[uu].Some? {
            assert before[tv].Some? && before[tv].value <= prev[uu].value + tw;
            if tv == v {
                assert after[v] == Some(newd);
                assert before[v].Some?;
                assert newd <= before[v].value;
                assert newd <= prev[uu].value + tw;
                assert after[v].Some? && after[v].value <= prev[uu].value + tw;
            } else {
                assert after[tv] == before[tv];
            }
            assert edge_relaxed(prev, after, uu, tv, tw);
        } else {
            assert edge_relaxed(prev, after, uu, tv, tw);
        }
    }
    forall i | 0 <= i < e_lim
        ensures 0 <= u < |g| && i < |g[u]| ==> edge_relaxed(prev, after, u, g[u][i].0, g[u][i].1)
    {
        if 0 <= u < |g| && i < |g[u]| {
            var tv := g[u][i].0;
            var tw := g[u][i].1;
            assert edge_relaxed(prev, before, u, tv, tw);
            if 0 <= u < |prev| && 0 <= tv < |before| && prev[u].Some? {
                assert before[tv].Some? && before[tv].value <= prev[u].value + tw;
                if tv == v {
                    assert after[tv] == Some(newd);
                    assert before[v].Some? && newd <= before[v].value <= prev[u].value + tw;
                } else {
                    assert after[tv] == before[tv];
                }
            }
            assert edge_relaxed(prev, after, u, tv, tw);
        }
    }
}

lemma lemma_witness_set(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, witness: seq<seq<int>>, v: int, newd: int, nw: seq<int>)
    requires witness_ok(g, start, dist, witness)
    requires 0 <= v < |g|
    requires |dist| == |g|
    requires |nw| > 0
    requires is_path(g, nw)
    requires nw[0] == start
    requires nw[|nw| - 1] == v
    requires path_weight(g, nw) == newd
    ensures witness_ok(g, start, dist[v := Some(newd)], witness[v := nw])
{
    reveal witness_ok;
    var dist' := dist[v := Some(newd)];
    var witness' := witness[v := nw];
    assert |dist'| == |g|;
    assert |witness'| == |g|;
    forall t | 0 <= t < |g| && dist'[t].Some?
        ensures |witness'[t]| > 0 && is_path(g, witness'[t]) && witness'[t][0] == start && witness'[t][|witness'[t]| - 1] == t && path_weight(g, witness'[t]) == dist'[t].value
    {
        if t == v {
            assert dist'[t] == Some(newd);
            assert witness'[t] == nw;
            assert path_weight(g, nw) == newd;
        } else {
            assert dist'[t] == dist[t];
            assert witness'[t] == witness[t];
            assert dist[t].Some?;
            assert |witness[t]| > 0;
            assert is_path(g, witness[t]);
            assert witness[t][0] == start;
            assert witness[t][|witness[t]| - 1] == t;
            assert path_weight(g, witness[t]) == dist[t].value;
        }
    }
}

