}

ghost predicate Impossible(coins: seq<int>, b: int) {
    forall counts: seq<int> :: is_valid_change(counts, coins, b) ==> false
}

ghost predicate Correct(coins: seq<int>, b: int, v: int) {
    (v != -1 ==> Achievable(coins, b, v) && LowerBound(coins, b, v)) &&
