lemma AmountUpdate(counts: seq<int>, coins: seq<int>, j: int, d: int)
    requires |counts| == |coins|
    requires 0 <= j < |counts|
    ensures total_amount(counts[j := counts[j] + d], coins) == total_amount(counts, coins) + d * coins[j]
    decreases |counts|
{
    var c2 := counts[j := counts[j] + d];
    if j == 0 {
        assert c2[1..] == counts[1..];
        assert (counts[0] + d) * coins[0] == counts[0] * coins[0] + d * coins[0];
    } else {
        AmountUpdate(counts[1..], coins[1..], j - 1, d);
        assert c2[1..] == counts[1..][j - 1 := counts[1..][j - 1] + d];
    }
}

lemma CoinsUpdate(counts: seq<int>, j: int, d: int)
    requires 0 <= j < |counts|
    ensures total_coins(counts[j := counts[j] + d]) == total_coins(counts) + d
    decreases |counts|
{
    var c2 := counts[j := counts[j] + d];
    if j == 0 {
        assert c2[1..] == counts[1..];
    } else {
        CoinsUpdate(counts[1..], j - 1, d);
        assert c2[1..] == counts[1..][j - 1 := counts[1..][j - 1] + d];
    }
}

