method coin_change(coins: seq<int>, amount: int) returns (min_coins: int)
    requires |coins| > 0
    requires |coins| <= 100
    requires amount <= 10000
    // Coins must be positive
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] <= 10000
    ensures
        // Case 1: Solution exists
        min_coins != -1 ==> (
            // Existence
            (exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == min_coins)
            &&
            // Lower Bound (Optimality)
            (forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> total_coins(counts) >= min_coins)
        )
    ensures
        // Case 2: Impossible
        min_coins == -1 ==> (
            forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
        )
{
    if amount < 0 {
        forall counts | is_valid_change(counts, coins, amount)
            ensures false
        {
            AmountNonneg(counts, coins);
        }
        return -1;
    }
    var dp := new int[amount + 1];
    dp[0] := 0;
    var z := seq(|coins|, _ => 0);
    Zeros(z, coins);
    assert is_valid_change(z, coins, 0) && total_coins(z) == 0;
    forall counts | is_valid_change(counts, coins, 0)
        ensures total_coins(counts) >= 0
    {
        CoinsNonneg(counts);
    }
    assert Correct(coins, 0, dp[0]);

    var a := 1;
    while a <= amount
        invariant 1 <= a <= amount + 1
        invariant forall b :: 0 <= b < a ==> Correct(coins, b, dp[b])
    {
        var best := -1;
        var i := 0;
        while i < |coins|
            invariant 0 <= i <= |coins|
            invariant best == -1 ==> forall j :: 0 <= j < i ==> coins[j] > a || dp[a - coins[j]] == -1
            invariant best != -1 ==> Achievable(coins, a, best)
            invariant best != -1 ==> forall j :: 0 <= j < i && coins[j] <= a && dp[a - coins[j]] != -1 ==> dp[a - coins[j]] + 1 >= best
        {
            if coins[i] <= a && dp[a - coins[i]] != -1 {
                var cand := dp[a - coins[i]] + 1;
                if best == -1 || cand < best {
                    assert Correct(coins, a - coins[i], dp[a - coins[i]]);
                    AchieveStep(coins, a - coins[i], dp[a - coins[i]], i);
                    best := cand;
                }
            }
            i := i + 1;
        }

        forall counts | is_valid_change(counts, coins, a)
            ensures best != -1 && total_coins(counts) >= best
        {
            var j := Decompose(coins, counts, a);
            var c2 := counts[j := counts[j] - 1];
            var r := a - coins[j];
            assert 0 <= r < a;
            assert Correct(coins, r, dp[r]);
            if dp[r] == -1 {
                assert is_valid_change(c2, coins, r);
                assert false;
            }
            assert total_coins(c2) >= dp[r];
        }
        assert Correct(coins, a, best);

        dp[a] := best;
        a := a + 1;
    }
    min_coins := dp[amount];
    assert Correct(coins, amount, dp[amount]);
}

