lemma Decompose(coins: seq<int>, counts: seq<int>, a: int) returns (j: int)
    requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
    requires is_valid_change(counts, coins, a)
    requires a > 0
    ensures 0 <= j < |coins| && counts[j] > 0
    ensures coins[j] <= a
    ensures is_valid_change(counts[j := counts[j] - 1], coins, a - coins[j])
    ensures total_coins(counts[j := counts[j] - 1]) == total_coins(counts) - 1
{
    AmountNonneg(counts, coins);
    j :| 0 <= j < |counts| && counts[j] > 0;
    var c2 := counts[j := counts[j] - 1];
    AmountUpdate(counts, coins, j, -1);
    CoinsUpdate(counts, j, -1);
    assert counts[j := counts[j] + -1] == c2;
    assert forall i :: 0 <= i < |c2| ==> c2[i] >= 0;
    AmountNonneg(c2, coins);
