lemma AchieveStep(coins: seq<int>, b: int, k: int, j: int)
    requires Achievable(coins, b, k)
    requires 0 <= j < |coins|
    ensures Achievable(coins, b + coins[j], k + 1)
{
    var counts :| is_valid_change(counts, coins, b) && total_coins(counts) == k;
    var c2 := counts[j := counts[j] + 1];
    AmountUpdate(counts, coins, j, 1);
    CoinsUpdate(counts, j, 1);
    assert is_valid_change(c2, coins, b + coins[j]) && total_coins(c2) == k + 1;
}

