ghost function adjust_count(counts: seq<int>, i: int, d: int): seq<int>
    requires 0 <= i < |counts|
    decreases |counts|
{
    if i == 0 then
        [counts[0] + d] + counts[1..]
    else
        [counts[0]] + adjust_count(counts[1..], i - 1, d)
}

lemma AdjustCountShape(counts: seq<int>, i: int, d: int)
    requires 0 <= i < |counts|
    ensures |adjust_count(counts, i, d)| == |counts|
    ensures forall k: int :: 0 <= k < |counts| ==>
        adjust_count(counts, i, d)[k] ==
            (if k == i then counts[k] + d else counts[k])
    decreases |counts|
{
    if i == 0 {
        forall k: int | 0 <= k < |counts|
            ensures adjust_count(counts, i, d)[k] ==
                (if k == i then counts[k] + d else counts[k])
        {
            if k > 0 {
                assert adjust_count(counts, i, d)[k] == counts[1..][k - 1];
                assert counts[1..][k - 1] == counts[k];
            }
        }
    } else {
        AdjustCountShape(counts[1..], i - 1, d);

        forall k: int | 0 <= k < |counts|
            ensures adjust_count(counts, i, d)[k] ==
                (if k == i then counts[k] + d else counts[k])
        {
            if k > 0 {
                assert adjust_count(counts, i, d)[k] ==
                    adjust_count(counts[1..], i - 1, d)[k - 1];
                assert counts[1..][k - 1] == counts[k];
            }
        }
    }
}

lemma AdjustCountTotals(
    counts: seq<int>,
    coins: seq<int>,
    i: int,
    d: int)
    requires |counts| == |coins|
    requires 0 <= i < |counts|
    ensures total_coins(adjust_count(counts, i, d))
        == total_coins(counts) + d
    ensures total_amount(adjust_count(counts, i, d), coins)
        == total_amount(counts, coins) + d * coins[i]
    decreases |counts|
{
    AdjustCountShape(counts, i, d);

    if i == 0 {
        assert adjust_count(counts, i, d)
            == [counts[0] + d] + counts[1..];

        assert (counts[0] + d) * coins[0]
            == counts[0] * coins[0] + d * coins[0];

        calc {
            total_coins(adjust_count(counts, i, d));
            == counts[0] + d + total_coins(counts[1..]);
            == total_coins(counts) + d;
        }

        calc {
            total_amount(adjust_count(counts, i, d), coins);
            == (counts[0] + d) * coins[0]
                + total_amount(counts[1..], coins[1..]);
            == total_amount(counts, coins) + d * coins[0];
        }
    } else {
        AdjustCountTotals(counts[1..], coins[1..], i - 1, d);

        assert counts[1..][i - 1] == counts[i];
        assert coins[1..][i - 1] == coins[i];

        calc {
            total_coins(adjust_count(counts, i, d));
            == counts[0]
                + total_coins(adjust_count(counts[1..], i - 1, d));
            == counts[0] + total_coins(counts[1..]) + d;
            == total_coins(counts) + d;
        }

        calc {
            total_amount(adjust_count(counts, i, d), coins);
            == counts[0] * coins[0]
                + total_amount(
                    adjust_count(counts[1..], i - 1, d),
                    coins[1..]);
            == counts[0] * coins[0]
                + total_amount(counts[1..], coins[1..])
                + d * coins[1..][i - 1];
            == total_amount(counts, coins) + d * coins[i];
        }
    }
}

lemma AdjustValidChange(
    counts: seq<int>,
    coins: seq<int>,
    amount: int,
    i: int,
    d: int)
    requires is_valid_change(counts, coins, amount)
    requires 0 <= i < |counts|
    requires counts[i] + d >= 0
    ensures is_valid_change(
        adjust_count(counts, i, d),
        coins,
        amount + d * coins[i])
    ensures total_coins(adjust_count(counts, i, d))
        == total_coins(counts) + d
{
    AdjustCountShape(counts, i, d);
    AdjustCountTotals(counts, coins, i, d);

    forall k: int | 0 <= k < |counts|
        ensures adjust_count(counts, i, d)[k] >= 0
    {
        if k == i {
            assert adjust_count(counts, i, d)[k] == counts[k] + d;
        } else {
            assert adjust_count(counts, i, d)[k] == counts[k];
            assert counts[k] >= 0;
        }
    }

    assert |adjust_count(counts, i, d)| == |coins|;
    assert total_amount(adjust_count(counts, i, d), coins)
        == amount + d * coins[i];
}

