method coin_change(coins: seq<int>, amount: int) returns (min_coins: int)
    requires |coins| > 0
    requires |coins| <= 100
    requires amount <= 10000
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] <= 10000
    ensures
        min_coins != -1 ==> (
            (exists counts: seq<int> ::
                is_valid_change(counts, coins, amount) &&
                total_coins(counts) == min_coins)
            &&
            (forall counts: seq<int> ::
                is_valid_change(counts, coins, amount) ==>
                total_coins(counts) >= min_coins)
        )
    ensures
        min_coins == -1 ==> (
            forall counts: seq<int> ::
                is_valid_change(counts, coins, amount) ==> false
        )
    decreases if amount > 0 then amount else 0
{
    if amount < 0 {
        min_coins := -1;

        forall counts: seq<int>
            | is_valid_change(counts, coins, amount)
            ensures false
        {
            ValidAmountNonnegative(counts, coins, amount);
        }
    } else if amount == 0 {
        min_coins := 0;

        ghost var zeroCounts := seq(|coins|, i requires 0 <= i < |coins| => 0);

        assert |zeroCounts| == |coins|;
        assert forall i: int ::
            0 <= i < |zeroCounts| ==> zeroCounts[i] == 0;

        ZeroCountsAmount(zeroCounts, coins);
        ZeroCountsTotal(zeroCounts);

        assert is_valid_change(zeroCounts, coins, amount);
        assert total_coins(zeroCounts) == min_coins;
        assert exists counts: seq<int> ::
            is_valid_change(counts, coins, amount) &&
            total_coins(counts) == min_coins;

        forall counts: seq<int>
            | is_valid_change(counts, coins, amount)
            ensures total_coins(counts) >= min_coins
        {
            TotalCoinsNonnegative(counts);
        }
    } else {
        min_coins := -1;
        var i := 0;

        while i < |coins|
            invariant 0 <= i <= |coins|
            invariant min_coins != -1 ==> (
                exists counts: seq<int> ::
                    is_valid_change(counts, coins, amount) &&
                    total_coins(counts) == min_coins)
            invariant forall counts: seq<int> ::
                is_valid_change(counts, coins, amount) &&
                (exists j: int :: 0 <= j < i && counts[j] > 0)
                ==>
                min_coins != -1 &&
                total_coins(counts) >= min_coins
            decreases |coins| - i
        {
            var idx := i;
            var oldMin := min_coins;

            assert oldMin != -1 ==> (
                exists counts: seq<int> ::
                    is_valid_change(counts, coins, amount) &&
                    total_coins(counts) == oldMin);

            assert forall counts: seq<int> ::
                is_valid_change(counts, coins, amount) &&
                (exists j: int :: 0 <= j < idx && counts[j] > 0)
                ==>
                oldMin != -1 &&
                total_coins(counts) >= oldMin;

            var r := coin_change(coins, amount - coins[idx]);

            if r != -1 && (oldMin == -1 || r + 1 < oldMin) {
                min_coins := r + 1;

                ghost var remainder :|
                    is_valid_change(
                        remainder,
                        coins,
                        amount - coins[idx]) &&
                    total_coins(remainder) == r;

                AdjustValidChange(
                    remainder,
                    coins,
                    amount - coins[idx],
                    idx,
                    1);

                ghost var full := adjust_count(remainder, idx, 1);

                assert amount - coins[idx] + coins[idx] == amount;
                assert is_valid_change(full, coins, amount);
                assert total_coins(full) == r + 1;
                assert total_coins(full) == min_coins;

                assert exists counts: seq<int> ::
                    is_valid_change(counts, coins, amount) &&
                    total_coins(counts) == min_coins;
            } else {
                min_coins := oldMin;
            }

            assert oldMin != -1 ==>
                min_coins != -1 && min_coins <= oldMin;
            assert r != -1 ==>
                min_coins != -1 && min_coins <= r + 1;

            forall counts: seq<int>
                | is_valid_change(counts, coins, amount) &&
                  counts[idx] > 0
                ensures min_coins != -1 &&
                    total_coins(counts) >= min_coins
            {
                AdjustValidChange(counts, coins, amount, idx, -1);

                ghost var remainder := adjust_count(counts, idx, -1);

                assert amount + (-1) * coins[idx]
                    == amount - coins[idx];
                assert is_valid_change(
                    remainder,
                    coins,
                    amount - coins[idx]);
