ghost predicate edge_relaxed(prev: seq<Option<int>>, dist: seq<Option<int>>, u: int, v: int, w: int) {
    (0 <= u < |prev| && 0 <= v < |dist| && prev[u].Some?) ==>
        (dist[v].Some? && dist[v].value <= prev[u].value + w)
}

ghost predicate {:opaque} witness_ok(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, witness: seq<seq<int>>) {
    |dist| == |g| &&
    |witness| == |g| &&
    (forall v :: 0 <= v < |g| && dist[v].Some? ==>
        |witness[v]| > 0 &&
        is_path(g, witness[v]) &&
        witness[v][0] == start &&
        witness[v][|witness[v]| - 1] == v &&
        path_weight(g, witness[v]) == dist[v].value)
}

ghost predicate {:opaque} dist_bounds_paths(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, k: int) {
    forall p: seq<int> {:trigger is_path(g, p)} ::
        (|p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= k) ==>
            (0 <= p[|p| - 1] < |dist| &&
             dist[p[|p| - 1]].Some? &&
             dist[p[|p| - 1]].value <= path_weight(g, p))
}

ghost predicate {:opaque} edges_before(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u_lim: int) {
    forall u, i :: 0 <= u < u_lim && 0 <= u < |g| && 0 <= i < |g[u]| ==>
        edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1)
}

ghost predicate {:opaque} edges_at(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, dist: seq<Option<int>>, u: int, e_lim: int) {
    forall i :: 0 <= i < e_lim ==>
        (0 <= u < |g| && i < |g[u]| ==>
            edge_relaxed(prev, dist, u, g[u][i].0, g[u][i].1))
}

