            lemma_edges_at_zero(g, prev, dist, u);
            var e := 0;
            while e < |graph.adj[u]|
                invariant 0 <= e <= |graph.adj[u]|
                invariant 0 <= u < |g|
                invariant g == view(graph) && |g| == n && graph.adj == g
                invariant |prev| == n && |dist| == n && |witness| == n && |prevWit| == n
                invariant witness_ok(g, start, prev, prevWit)
                invariant witness_ok(g, start, dist, witness)
                invariant dist_bounds_paths(g, start, prev, iter)
                invariant forall t :: 0 <= t < n ==> le_opt(dist[t], prev[t])
                invariant edges_before(g, prev, dist, u)
                invariant edges_at(g, prev, dist, u, e)
                invariant prev[start].Some? && prev[start].value <= 0
                invariant dist[start].Some? && dist[start].value <= 0
