lemma HC_Concat(g: Graph, p: seq<int>, q: seq<int>)
  requires is_path(g, p)
  requires is_path(g, q)
  requires |p| > 1
  requires |q| > 1
  requires p[|p| - 1] == q[0]
  ensures is_path(g, p + q[1..])
{
  var r := p + q[1..];

  assert |r| > 0;

  forall i: int | 0 <= i < |r| - 1
    ensures has_edge(g, r[i], r[i + 1])
  {
    if i < |p| - 1 {
      assert r[i] == p[i];
      assert r[i + 1] == p[i + 1];
      assert has_edge(g, p[i], p[i + 1]);
    } else {
      var j := i - (|p| - 1);
      assert 0 <= j < |q| - 1;

      if j == 0 {
        assert r[i] == p[|p| - 1];
        assert r[i] == q[0];
      } else {
        assert r[i] == q[j];
      }

      assert r[i + 1] == q[j + 1];
      assert has_edge(g, q[j], q[j + 1]);
    }
  }
}

