  forall i: int | 0 <= i < |p[..k]| - 1
    ensures has_edge(g, p[..k][i], p[..k][i + 1])
  {
    assert 0 <= i < |p| - 1;
    assert p[..k][i] == p[i];
    assert p[..k][i + 1] == p[i + 1];
  }
}

