  requires |p| > 1
  requires HC_ContainsEdges(g, R)
  requires HC_Closed(R)
  ensures (p[0], p[|p| - 1]) in R
  decreases |p|
{
  if |p| == 2 {
    assert has_edge(g, p[0], p[1]);
    assert (p[0], p[1]) in R;
  } else {
    var q := p[..|p| - 1];

    HC_Prefix(g, p, |p| - 1);
    HC_PathInClosed(g, q, R);

    assert q[0] == p[0];
    assert q[|q| - 1] == p[|p| - 2];
    assert (p[0], p[|p| - 2]) in R;

    assert has_edge(g, p[|p| - 2], p[|p| - 1]);
