  while u < n
    invariant 0 <= u <= n
    invariant HC_Valid(R, n)
    invariant HC_Sound(graph, R)
    invariant forall a: int, b: int ::
      0 <= a < u && has_edge(graph, a, b) ==> (a, b) in R
  {
    var j := 0;
    while j < |graph.adj[u]|
      invariant 0 <= j <= |graph.adj[u]|
      invariant HC_Valid(R, n)
      invariant HC_Sound(graph, R)
      invariant forall a: int, b: int ::
        0 <= a < u && has_edge(graph, a, b) ==> (a, b) in R
      invariant forall k: int ::
        0 <= k < j ==> (u, graph.adj[u][k]) in R
    {
      var v := graph.adj[u][j];

      assert 0 <= v < n;
      assert has_edge(graph, u, v);

      var p := [u, v];
      assert |p| == 2;
      assert p[0] == u;
      assert p[1] == v;
      assert forall i: int ::
        0 <= i < |p| - 1 ==> has_edge(graph, p[i], p[i + 1]);
      assert is_path(graph, p);

      R := R + {(u, v)};
      j := j + 1;
    }

    forall b: int | has_edge(graph, u, b)
      ensures (u, b) in R
    {
      var k: int :|
        0 <= u < |graph.adj| &&
        0 <= k < |graph.adj[u]| &&
        graph.adj[u][k] == b;
      assert (u, graph.adj[u][k]) in R;
    }

    u := u + 1;
  }

  assert HC_ContainsEdges(graph, R);

  ghost var universe :=
    set a: int, b: int |
      0 <= a < n && 0 <= b < n :: (a, b);

  HC_ValidSubset(R, n);
  assert R <= universe;

  while true
    invariant HC_Valid(R, n)
    invariant HC_Sound(graph, R)
    invariant HC_ContainsEdges(graph, R)
    invariant R <= universe
    decreases universe - R
  {
    var snapshot := R;
    assert snapshot <= R;

    u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant snapshot <= R
      invariant HC_Valid(R, n)
      invariant HC_Sound(graph, R)
      invariant forall a: int, b: int, c: int ::
        0 <= a < u &&
        0 <= b < n &&
        0 <= c < n &&
        (a, b) in snapshot &&
        (b, c) in snapshot
        ==> (a, c) in R
    {
      var v := 0;
      while v < n
        invariant 0 <= v <= n
        invariant snapshot <= R
        invariant HC_Valid(R, n)
        invariant HC_Sound(graph, R)
        invariant forall a: int, b: int, c: int ::
          0 <= a < u &&
          0 <= b < n &&
          0 <= c < n &&
          (a, b) in snapshot &&
          (b, c) in snapshot
          ==> (a, c) in R
        invariant forall b: int, c: int ::
          0 <= b < v &&
          0 <= c < n &&
          (u, b) in snapshot &&
          (b, c) in snapshot
          ==> (u, c) in R
      {
        var w := 0;
        while w < n
          invariant 0 <= w <= n
          invariant snapshot <= R
          invariant HC_Valid(R, n)
          invariant HC_Sound(graph, R)
          invariant forall a: int, b: int, c: int ::
            0 <= a < u &&
            0 <= b < n &&
            0 <= c < n &&
            (a, b) in snapshot &&
            (b, c) in snapshot
            ==> (a, c) in R
          invariant forall b: int, c: int ::
            0 <= b < v &&
            0 <= c < n &&
            (u, b) in snapshot &&
            (b, c) in snapshot
            ==> (u, c) in R
          invariant forall c: int ::
            0 <= c < w &&
            (u, v) in snapshot &&
            (v, c) in snapshot
            ==> (u, c) in R
        {
          if (u, v) in R && (v, w) in R && (u, w) !in R {
            ghost var p: seq<int> :|
              is_path(graph, p) &&
              |p| > 1 &&
              p[0] == u &&
              p[|p| - 1] == v;

            ghost var q: seq<int> :|
              is_path(graph, q) &&
              |q| > 1 &&
              q[0] == v &&
              q[|q| - 1] == w;

            HC_Concat(graph, p, q);
            ghost var r := p + q[1..];

            assert is_path(graph, r);
            assert |r| > 1;
            assert r[0] == u;
            assert r[|r| - 1] == w;

            R := R + {(u, w)};
          }

          assert (u, v) in snapshot && (v, w) in snapshot
            ==> (u, w) in R;

          w := w + 1;
        }

        v := v + 1;
      }

      u := u + 1;
    }

    assert forall a: int, b: int, c: int ::
      0 <= a < n &&
      0 <= b < n &&
      0 <= c < n &&
      (a, b) in snapshot &&
      (b, c) in snapshot
      ==> (a, c) in R;

    HC_ValidSubset(R, n);
    assert R <= universe;

    if R == snapshot {
      assert HC_Closed(R);
      break;
    }

    assert snapshot < R;
    HC_DifferenceShrinks(universe, snapshot, R);
    assert universe - R < universe - snapshot;
