{
    var n := |v|;
    forall i {:trigger p[i]} | 0 <= i < n
        ensures 0 <= p[i] < n
    {
        assert p[i] == i;
    }
    forall i, j {:trigger p[i], p[j]} | 0 <= i < j < n
        ensures p[i] != p[j]
    {
        assert p[i] == i;
        assert p[j] == j;
    }
    assert is_valid_index_permutation(p, n);
    forall i {:trigger p[i]} | 0 <= i < n
        ensures 0 <= p[i] < n && a[i] == v[p[i]]
    {
