lemma ContentsSwap(v: seq<int>, a0: seq<int>, p0: seq<int>, a: seq<int>, p: seq<int>, j: int)
    requires maps_by(v, a0, p0)
    requires 0 <= j < |a0| - 1
    requires a == a0[j := a0[j+1]][j+1 := a0[j]]
    requires p == p0[j := p0[j+1]][j+1 := p0[j]]
    ensures maps_by(v, a, p)
{
    IndexAfterSwap(a0, j, a);
    IndexAfterSwap(p0, j, p);
    assert |p0| == |v| == |a0|;
    assert is_valid_index_permutation(p0, |p0|);
    PermSwapValid(p0, j);
    assert p == p0[j := p0[j+1]][j+1 := p0[j]];
    assert is_valid_index_permutation(p, |p0|);
    assert is_valid_index_permutation(p, |v|);
    assert |a| == |a0|;
    assert |p| == |p0|;

    forall i {:trigger p[i]} | 0 <= i < |v|
        ensures 0 <= p[i] < |v| && a[i] == v[p[i]]
    {
        assert 0 <= p[i] < |v|;
        if i == j {
            assert a[i] == a0[j+1];
            assert p[i] == p0[j+1];
            assert 0 <= p0[j+1] < |v| && a0[j+1] == v[p0[j+1]];
            assert a[i] == v[p[i]];
        } else if i == j + 1 {
            assert a[i] == a0[j];
            assert p[i] == p0[j];
            assert 0 <= p0[j] < |v| && a0[j] == v[p0[j]];
            assert a[i] == v[p[i]];
        } else {
            assert a[i] == a0[i];
            assert p[i] == p0[i];
            assert 0 <= p0[i] < |v| && a0[i] == v[p0[i]];
            assert a[i] == v[p[i]];
        }
    }
    assert maps_by(v, a, p);
}

lemma MaxAfterSwap(a0: seq<int>, a: seq<int>, j: int)
    requires 0 <= j < |a0| - 1
    requires a == a0[j := a0[j+1]][j+1 := a0[j]]
    requires forall k :: 0 <= k <= j ==> a0[k] <= a0[j]
    requires a0[j] > a0[j+1]
    ensures forall k :: 0 <= k <= j + 1 ==> a[k] <= a[j+1]
{
    IndexAfterSwap(a0, j, a);
    forall k | 0 <= k <= j + 1
        ensures a[k] <= a[j+1]
    {
        if k == j + 1 {
            assert a[k] == a[j+1];
        } else if k == j {
            assert a[j] == a0[j+1];
            assert a[j+1] == a0[j];
            assert a0[j+1] <= a0[j];
        } else {
            assert k < j;
            assert k != j && k != j + 1;
            assert a[k] == a0[k];
            assert a[j+1] == a0[j];
            assert a0[k] <= a0[j];
        }
    }
}

lemma MaxAfterNoSwap(a: seq<int>, j: int)
