lemma OrderPreserved(a0: seq<int>, a: seq<int>, j: int, cut: int)
    requires 0 <= j < |a0| - 1
    requires |a| == |a0|
    requires j + 1 < cut
    requires cut <= |a0|
    requires a == a0[j := a0[j+1]][j+1 := a0[j]]
    requires forall k, m :: cut <= k < m < |a0| ==> a0[k] <= a0[m]
    requires forall k, m :: 0 <= k < cut && cut <= m < |a0| ==> a0[k] <= a0[m]
    ensures forall k, m :: cut <= k < m < |a| ==> a[k] <= a[m]
