        ensures a[k] <= a[m]
    {
        assert j + 1 < cut <= k;
        assert k != j && k != j + 1;
        assert m != j && m != j + 1;
        assert a[k] == a0[k];
        assert a[m] == a0[m];
        assert a0[k] <= a0[m];
    }
    forall k, m | 0 <= k < cut && cut <= m < |a|
        ensures a[k] <= a[m]
    {
