lemma {:vcs_split_on_every_assert} lemma_edges_mono(g: seq<seq<(int, int)>>, prev: seq<Option<int>>, before: seq<Option<int>>, after: seq<Option<int>>, u_lim: int, u: int, e_lim: int, v: int, newd: int)
    requires |g| == |prev| == |before| == |after|
    requires 0 <= v < |g|
    requires 0 <= u < |g|
    requires 0 <= u_lim <= |g|
    requires 0 <= e_lim <= |g[u]|
    requires after == before[v := Some(newd)]
    requires before[v].None? || (before[v].Some? && newd <= before[v].value)
    requires edges_before(g, prev, before, u_lim)
    requires edges_at(g, prev, before, u, e_lim)
    ensures edges_before(g, prev, after, u_lim)
    ensures edges_at(g, prev, after, u, e_lim)
{
    reveal edges_before;
    reveal edges_at;
    forall uu, i | 0 <= uu < u_lim && 0 <= uu < |g| && 0 <= i < |g[uu]|
        ensures edge_relaxed(prev, after, uu, g[uu][i].0, g[uu][i].1)
    {
        var tv := g[uu][i].0;
        var tw := g[uu][i].1;
        assert edge_relaxed(prev, before, uu, tv, tw);
        if 0 <= uu < |prev| && 0 <= tv < |before| && prev[uu].Some? {
            assert before[tv].Some? && before[tv].value <= prev[uu].value + tw;
            if tv == v {
                assert after[v] == Some(newd);
                assert before[v].Some?;
                if before[v].None? {
                    assert false;
                }
                assert newd <= before[v].value;
                assert newd <= prev[uu].value + tw;
                assert after[v].Some? && after[v].value <= prev[uu].value + tw;
            } else {
                assert after[tv] == before[tv];
                assert after[tv].Some? && after[tv].value <= prev[uu].value + tw;
            }
            assert edge_relaxed(prev, after, uu, tv, tw);
        } else {
            assert edge_relaxed(prev, after, uu, tv, tw);
        }
    }
    forall i | 0 <= i < e_lim
        ensures 0 <= u < |g| && i < |g[u]| ==> edge_relaxed(prev, after, u, g[u][i].0, g[u][i].1)
    {
        if 0 <= u < |g| && i < |g[u]| {
            var tv := g[u][i].0;
            var tw := g[u][i].1;
            assert edge_relaxed(prev, before, u, tv, tw);
            if 0 <= u < |prev| && 0 <= tv < |before| && prev[u].Some? {
                assert before[tv].Some? && before[tv].value <= prev[u].value + tw;
                if tv == v {
                    assert after[tv] == Some(newd);
                    assert before[v].Some?;
                    assert newd <= before[v].value;
                    assert newd <= prev[u].value + tw;
                    assert after[tv].Some? && after[tv].value <= prev[u].value + tw;
                } else {
                    assert after[tv] == before[tv];
                    assert after[tv].Some? && after[tv].value <= prev[u].value + tw;
                }
            }
            assert edge_relaxed(prev, after, u, tv, tw);
        }
    }
}

lemma lemma_wits_set(g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, wits: seq<seq<int>>, v: int, newd: int, nw: seq<int>)
    requires wits_ok(g, start, dist, wits)
    requires 0 <= v < |g|
    requires |dist| == |g|
    requires |wits| == |g|
    requires |nw| > 0
    requires is_path(g, nw)
    requires nw[0] == start
    requires nw[|nw| - 1] == v
    requires path_weight(g, nw) == newd
    ensures wits_ok(g, start, dist[v := Some(newd)], wits[v := nw])
{
    reveal wits_ok;
    var dist2 := dist[v := Some(newd)];
    var wits2 := wits[v := nw];
    assert |dist2| == |g|;
    assert |wits2| == |g|;
    forall t | 0 <= t < |g| && dist2[t].Some?
        ensures |wits2[t]| > 0 && is_path(g, wits2[t]) && wits2[t][0] == start && wits2[t][|wits2[t]| - 1] == t && path_weight(g, wits2[t]) == dist2[t].value
    {
        if t == v {
            assert dist2[t] == Some(newd);
            assert wits2[t] == nw;
            assert path_weight(g, nw) == newd;
        } else {
            assert dist2[t] == dist[t];
            assert wits2[t] == wits[t];
            assert dist[t].Some?;
            assert |wits[t]| > 0;
            assert is_path(g, wits[t]);
            assert wits[t][0] == start;
            assert wits[t][|wits[t]| - 1] == t;
            assert path_weight(g, wits[t]) == dist[t].value;
        }
    }
}

