lemma lemma_init(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, wits: seq<seq<int>>)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires dist == seq(|g|, i => if i == start then Some(0) else None)
    requires wits == seq(|g|, i => if i == start then [start] else [])
    ensures wits_ok(g, start, dist, wits)
    ensures dist_bounds_paths(g, start, dist, 0)
    ensures dist[start] == Some(0)
    ensures dist[start].value == 0
{
    reveal wits_ok;
    reveal dist_bounds_paths;
    assert |dist| == |g|;
    assert |wits| == |g|;
    assert dist[start] == Some(0);
    assert wits[start] == [start];
    forall v | 0 <= v < |g| && dist[v].Some?
        ensures |wits[v]| > 0 && is_path(g, wits[v]) && wits[v][0] == start && wits[v][|wits[v]| - 1] == v && path_weight(g, wits[v]) == dist[v].value
    {
        assert dist[v] == (if v == start then Some(0) else None);
        if v == start {
            assert wits[v] == [start];
            assert |wits[v]| == 1;
            assert is_path(g, wits[v]);
            lemma_single_weight(g, wits[v]);
            assert path_weight(g, wits[v]) == 0 == dist[v].value;
        } else {
            assert dist[v] == None;
            assert false;
        }
    }
    forall p: seq<int> {:trigger is_path(g, p)} | |p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= 0
        ensures 0 <= p[|p| - 1] < |dist| && dist[p[|p| - 1]].Some? && dist[p[|p| - 1]].value <= path_weight(g, p)
    {
        assert |p| == 1;
        assert p[|p| - 1] == start;
        lemma_single_weight(g, p);
        assert path_weight(g, p) == 0;
        assert dist[start] == Some(0);
    }
}

lemma {:vcs_split_on_every_assert} lemma_on_relax(
    graph: WeightedGraph,
    g: seq<seq<(int, int)>>,
    start: int,
    prev: seq<Option<int>>,
    prevWit: seq<seq<int>>,
    before: seq<Option<int>>,
    witBefore: seq<seq<int>>,
    after: seq<Option<int>>,
    witAfter: seq<seq<int>>,
    u: int,
    e: int,
    v: int,
    wgt: int,
    du: int,
    nw: seq<int>
)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires 0 <= u < |g|
    requires 0 <= e < |g[u]|
    requires v == g[u][e].0 && wgt == g[u][e].1
    requires 0 <= v < |g|
    requires |prev| == |g| && |before| == |g| && |prevWit| == |g| && |witBefore| == |g|
    requires wits_ok(g, start, prev, prevWit)
    requires wits_ok(g, start, before, witBefore)
    requires forall t :: 0 <= t < |g| ==> le_opt(before[t], prev[t])
    requires edges_before(g, prev, before, u)
    requires edges_at(g, prev, before, u, e)
    requires before[start].Some? && before[start].value <= 0
    requires prev[u].Some?
    requires du == prev[u].value
    requires before[v].None? || du + wgt < before[v].value
    requires nw == prevWit[u] + [v]
    requires after == before[v := Some(du + wgt)]
    requires witAfter == witBefore[v := nw]
    ensures |after| == |g| && |witAfter| == |g|
    ensures wits_ok(g, start, after, witAfter)
    ensures forall t :: 0 <= t < |g| ==> le_opt(after[t], prev[t])
    ensures edges_before(g, prev, after, u)
    ensures edges_at(g, prev, after, u, e + 1)
    ensures after[start].Some? && after[start].value <= 0
{
    assert |after| == |before| == |g|;
    assert |witAfter| == |witBefore| == |g|;

    lemma_wits_one(g, start, prev, prevWit, u);
    var src := prevWit[u];
    assert |src| > 0;
    assert src[|src| - 1] == u;
    assert path_weight(g, src) == du;
    lemma_adj_edge(graph, g, u, e);
    assert has_edge(g, u, v, wgt);
    assert get_edge_weight(g, u, v) == wgt;
    lemma_extend_path(g, src, v, wgt);
    assert is_path(g, nw);
    assert nw[0] == start;
    assert nw[|nw| - 1] == v;
    assert path_weight(g, nw) == du + wgt;
    lemma_wits_set(g, start, before, witBefore, v, du + wgt, nw);
    assert wits_ok(g, start, after, witAfter);

    if before[v].None? {
        assert before[v].None? || (before[v].Some? && du + wgt <= before[v].value);
    } else {
        assert before[v].Some?;
        assert du + wgt < before[v].value;
        assert du + wgt <= before[v].value;
        assert before[v].None? || (before[v].Some? && du + wgt <= before[v].value);
    }
    lemma_edges_mono(g, prev, before, after, u, u, e, v, du + wgt);

    assert after[v] == Some(du + wgt);
    assert 0 <= u < |prev| && 0 <= v < |after| && prev[u].Some?;
    assert after[v].value == du + wgt;
    assert after[v].value <= prev[u].value + wgt;
    assert edge_relaxed(prev, after, u, v, wgt);
    lemma_edges_at_push(g, prev, after, u, e);

    forall t | 0 <= t < |g|
        ensures le_opt(after[t], prev[t])
    {
        if t == v {
            if prev[v].Some? {
                assert le_opt(before[v], prev[v]);
                assert before[v].Some?;
                assert before[v].value <= prev[v].value;
                assert du + wgt < before[v].value;
                assert after[v] == Some(du + wgt);
                assert after[v].value < before[v].value;
                assert after[v].value <= prev[v].value;
                assert le_opt(after[v], prev[v]);
            } else {
                assert le_opt(after[v], prev[v]);
            }
        } else {
            assert after[t] == before[t];
            assert le_opt(before[t], prev[t]);
            assert le_opt(after[t], prev[t]);
        }
    }

    if v == start {
        assert before[start].Some?;
        assert du + wgt < before[start].value;
        assert before[start].value <= 0;
        assert after[start] == Some(du + wgt);
        assert after[start].value < before[start].value;
        assert after[start].value <= 0;
    } else {
        assert after[start] == before[start];
        assert after[start].Some? && after[start].value <= 0;
    }
}

lemma lemma_on_skip(
    g: seq<seq<(int, int)>>,
    start: int,
    prev: seq<Option<int>>,
    before: seq<Option<int>>,
    witBefore: seq<seq<int>>,
    after: seq<Option<int>>,
    witAfter: seq<seq<int>>,
    u: int,
    e: int,
    v: int,
    wgt: int
)
    requires 0 <= start < |g|
    requires 0 <= u < |g|
    requires 0 <= e < |g[u]|
    requires v == g[u][e].0 && wgt == g[u][e].1
    requires 0 <= v < |g|
    requires |prev| == |g| && |before| == |g| && |witBefore| == |g|
    requires wits_ok(g, start, before, witBefore)
    requires forall t :: 0 <= t < |g| ==> le_opt(before[t], prev[t])
    requires edges_before(g, prev, before, u)
    requires edges_at(g, prev, before, u, e)
    requires before[start].Some? && before[start].value <= 0
    requires after == before && witAfter == witBefore
    requires !(prev[u].Some? && (before[v].None? || prev[u].value + wgt < before[v].value))
    ensures |after| == |g| && |witAfter| == |g|
    ensures wits_ok(g, start, after, witAfter)
    ensures forall t :: 0 <= t < |g| ==> le_opt(after[t], prev[t])
    ensures edges_before(g, prev, after, u)
    ensures edges_at(g, prev, after, u, e + 1)
    ensures after[start].Some? && after[start].value <= 0
{
    assert |after| == |g| && |witAfter| == |g|;
    assert wits_ok(g, start, after, witAfter);
    lemma_le_opt_copy(before, after, prev);
    assert edges_before(g, prev, after, u);
    assert edges_at(g, prev, after, u, e);
    assert after[start].Some? && after[start].value <= 0;

    if prev[u].Some? {
        var pdu := prev[u].value;
        assert !(before[v].None? || pdu + wgt < before[v].value);
        assert before[v].Some?;
        assert !(pdu + wgt < before[v].value);
        assert before[v].value <= pdu + wgt;
        assert after[v] == before[v];
        assert after[v].Some?;
        assert after[v].value <= prev[u].value + wgt;
        assert edge_relaxed(prev, after, u, v, wgt);
    } else {
        assert edge_relaxed(prev, after, u, v, wgt);
    }
    lemma_edges_at_push(g, prev, after, u, e);
}

lemma {:vcs_split_on_every_assert} lemma_extend_bounds(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, prev: seq<Option<int>>, dist: seq<Option<int>>, k: int)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |prev| == |g| && |dist| == |g|
    requires 0 <= k
    requires dist_bounds_paths(g, start, prev, k)
    requires forall t :: 0 <= t < |g| ==> le_opt(dist[t], prev[t])
    requires edges_before(g, prev, dist, |g|)
    ensures dist_bounds_paths(g, start, dist, k + 1)
{
    reveal dist_bounds_paths;
    forall p: seq<int> {:trigger is_path(g, p)} | |p| > 0 && is_path(g, p) && p[0] == start && |p| - 1 <= k + 1
        ensures 0 <= p[|p| - 1] < |dist| && dist[p[|p| - 1]].Some? && dist[p[|p| - 1]].value <= path_weight(g, p)
    {
        if |p| - 1 <= k {
            lemma_bound_one(g, start, prev, k, p);
            var vend := p[|p| - 1];
            assert 0 <= vend < |prev|;
            assert prev[vend].Some?;
            assert le_opt(dist[vend], prev[vend]);
            assert dist[vend].Some?;
            assert dist[vend].value <= prev[vend].value;
            assert prev[vend].value <= path_weight(g, p);
            assert dist[vend].value <= path_weight(g, p);
        } else {
            assert |p| - 1 == k + 1;
            assert |p| >= 2;
            var prefix := p[..|p| - 1];
            lemma_sub_is_path(g, p, 0, |p| - 1);
            assert is_path(g, prefix);
            assert |prefix| > 0;
            assert prefix[0] == p[0] == start;
            assert |prefix| - 1 == k;
            lemma_bound_one(g, start, prev, k, prefix);
            var u := p[|p| - 2];
            var v := p[|p| - 1];
            assert u == prefix[|prefix| - 1];
            assert 0 <= u < |prev|;
            assert prev[u].Some?;
            var du := prev[u].value;
            assert du <= path_weight(g, prefix);
            assert connected(g, u, v);
            var w, i := lemma_connected_weight(graph, g, u, v);
            lemma_one_relaxed(g, prev, dist, |g|, u, i);
            assert g[u][i].0 == v && g[u][i].1 == w;
            assert edge_relaxed(prev, dist, u, v, w);
            assert dist[v].Some? && dist[v].value <= du + w;
            lemma_snoc_eq(p);
            assert p == prefix + [v];
            lemma_path_weight_def(g, p);
            assert p[..|p| - 1] == prefix;
            assert get_edge_weight(g, u, v) == w;
            assert path_weight(g, p) == path_weight(g, prefix) + w;
            assert du + w <= path_weight(g, p);
            assert dist[v].value <= path_weight(g, p);
            assert 0 <= v < |g|;
            assert 0 <= v < |dist|;
        }
    }
}

lemma lemma_path_lower_bound(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, p: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
    requires |dist| == |g|
    requires edges_before(g, dist, dist, |g|)
    requires dist[start].Some? && dist[start].value <= 0
    requires is_path(g, p)
    requires |p| > 0 && p[0] == start
    ensures 0 <= p[|p| - 1] < |dist|
    ensures dist[p[|p| - 1]].Some?
    ensures dist[p[|p| - 1]].value <= path_weight(g, p)
    decreases |p|
{
    if |p| == 1 {
        assert p[0] == start;
        lemma_single_weight(g, p);
        assert path_weight(g, p) == 0;
        assert dist[start].value <= 0;
        assert dist[start].value <= path_weight(g, p);
    } else {
        var prefix := p[..|p| - 1];
        lemma_sub_is_path(g, p, 0, |p| - 1);
        assert is_path(g, prefix);
        assert prefix[0] == start;
        lemma_path_lower_bound(graph, g, start, dist, prefix);
        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert u == prefix[|prefix| - 1];
        assert dist[u].Some?;
        assert connected(g, u, v);
        var w, i := lemma_connected_weight(graph, g, u, v);
        lemma_one_relaxed(g, dist, dist, |g|, u, i);
        assert edge_relaxed(dist, dist, u, v, w);
        assert dist[v].Some? && dist[v].value <= dist[u].value + w;
        lemma_path_weight_def(g, p);
        lemma_snoc_eq(p);
        assert p[..|p| - 1] == prefix;
        assert get_edge_weight(g, u, v) == w;
        assert path_weight(g, p) == path_weight(g, prefix) + w;
        assert dist[u].value <= path_weight(g, prefix);
        assert dist[u].value + w <= path_weight(g, p);
        assert dist[v].value <= path_weight(g, p);
        assert 0 <= v < |dist|;
    }
}

lemma lemma_some_post(graph: WeightedGraph, g: seq<seq<(int, int)>>, start: int, dist: seq<Option<int>>, wits: seq<seq<int>>)
    requires well_formed(graph)
    requires g == view(graph)
    requires 0 <= start < |g|
