lemma UpdateHeadTail(s: seq<int>, v: int)
  requires |s| > 0
  ensures (s[0 := v])[1..] == s[1..]
  ensures (s[0 := v])[0] == v
{
  var left := (s[0 := v])[1..];
  var right := s[1..];
  assert |left| == |s| - 1;
  assert |right| == |s| - 1;
  forall j | 0 <= j < |left|
    ensures left[j] == right[j]
  {
    assert left[j] == (s[0 := v])[j + 1];
    assert j + 1 != 0;
    assert (s[0 := v])[j + 1] == s[j + 1];
    assert right[j] == s[j + 1];
  }
  assert |left| == |right|;
  assert forall j :: 0 <= j < |left| ==> left[j] == right[j];
  assert left == right;
}

lemma SeqUpdateTail(s: seq<int>, i: int, v: int)
  requires 0 < i < |s|
  ensures (s[i := v])[1..] == s[1..][i - 1 := v]
  ensures (s[i := v])[0] == s[0]
{
  var left := (s[i := v])[1..];
  var right := s[1..][i - 1 := v];
  assert |left| == |s| - 1;
  assert |right| == |s| - 1;
  forall j | 0 <= j < |left|
    ensures left[j] == right[j]
  {
    if j == i - 1 {
      assert left[j] == (s[i := v])[j + 1];
      assert j + 1 == i;
      assert (s[i := v])[j + 1] == v;
      assert right[j] == v;
    } else {
      assert j != i - 1;
      assert j + 1 != i;
      assert left[j] == (s[i := v])[j + 1];
      assert (s[i := v])[j + 1] == s[j + 1];
      assert right[j] == s[1..][j];
      assert s[1..][j] == s[j + 1];
    }
  }
  assert |left| == |right|;
  assert forall j :: 0 <= j < |left| ==> left[j] == right[j];
  assert left == right;
  assert (s[i := v])[0] == s[0];
}

lemma TotalZeros(counts: seq<int>, coins: seq<int>)
  requires |counts| == |coins|
  requires forall i :: 0 <= i < |counts| ==> counts[i] == 0
  ensures total_amount(counts, coins) == 0
  ensures total_coins(counts) == 0
  decreases |counts|
{
  if |counts| == 0 {
  } else {
    TailCountsZero(counts);
    TotalZeros(counts[1..], coins[1..]);
    UnfoldAmount(counts, coins);
    UnfoldCoins(counts);
    assert counts[0] == 0;
    assert counts[0] * coins[0] == 0;
  }
}

lemma TotalCoinsNonNeg(counts: seq<int>)
  requires forall j :: 0 <= j < |counts| ==> counts[j] >= 0
  ensures total_coins(counts) >= 0
  decreases |counts|
{
  if |counts| == 0 {
  } else {
    TailCountsNonNeg(counts);
    TotalCoinsNonNeg(counts[1..]);
    UnfoldCoins(counts);
  }
}

lemma TotalAmountNonNeg(counts: seq<int>, coins: seq<int>)
  requires |counts| == |coins|
  requires forall j :: 0 <= j < |counts| ==> counts[j] >= 0
  requires forall j :: 0 <= j < |coins| ==> coins[j] > 0
  ensures total_amount(counts, coins) >= 0
  decreases |counts|
{
  if |counts| == 0 {
  } else {
    TailCountsNonNeg(counts);
    TailCoinsPos(coins);
    TotalAmountNonNeg(counts[1..], coins[1..]);
    assert counts[0] >= 0;
    assert coins[0] > 0;
    assert coins[0] >= 0;
    MulNonNeg(counts[0], coins[0]);
    UnfoldAmount(counts, coins);
  }
}

lemma TotalCoinsLeAmount(counts: seq<int>, coins: seq<int>)
  requires |counts| == |coins|
  requires forall j :: 0 <= j < |counts| ==> counts[j] >= 0
  requires forall j :: 0 <= j < |coins| ==> coins[j] > 0
  ensures total_coins(counts) <= total_amount(counts, coins)
  decreases |counts|
{
  if |counts| == 0 {
  } else {
    TailCountsNonNeg(counts);
    TailCoinsPos(coins);
    TotalCoinsLeAmount(counts[1..], coins[1..]);
    assert coins[0] > 0;
    assert coins[0] >= 1;
    assert counts[0] >= 0;
    LeMul(counts[0], coins[0]);
    UnfoldCoins(counts);
    UnfoldAmount(counts, coins);
    assert counts[0] <= counts[0] * coins[0];
    assert total_coins(counts[1..]) <= total_amount(counts[1..], coins[1..]);
  }
}

lemma {:isolate_assertions} TotalAmountInc(counts: seq<int>, coins: seq<int>, i: int)
  requires |counts| == |coins|
  requires 0 <= i < |counts|
  ensures total_amount(counts[i := counts[i] + 1], coins) == total_amount(counts, coins) + coins[i]
  decreases i
{
  if i == 0 {
    var counts' := counts[0 := counts[0] + 1];
    UpdateHeadTail(counts, counts[0] + 1);
    UnfoldAmount(counts, coins);
    UnfoldAmount(counts', coins);
    assert counts'[1..] == counts[1..];
    assert counts'[0] == counts[0] + 1;
    var rest := total_amount(counts[1..], coins[1..]);
    assert total_amount(counts'[1..], coins[1..]) == rest;
    var p := counts[0] * coins[0];
    MulAddOne(counts[0], coins[0]);
    assert (counts[0] + 1) * coins[0] == p + coins[0];
    assert total_amount(counts', coins) == (counts[0] + 1) * coins[0] + rest;
    assert total_amount(counts, coins) == p + rest;
    assert total_amount(counts', coins) == (p + coins[0]) + rest;
    assert (p + coins[0]) + rest == (p + rest) + coins[0];
    assert total_amount(counts', coins) == total_amount(counts, coins) + coins[0];
  } else {
    var counts' := counts[i := counts[i] + 1];
    var tailC := counts[1..];
    var tailCoins := coins[1..];
    assert |tailC| == |counts| - 1;
    assert |tailCoins| == |coins| - 1;
    assert |tailC| == |tailCoins|;
    assert 0 <= i - 1 < |tailC|;
    SeqUpdateTail(counts, i, counts[i] + 1);
    assert counts'[0] == counts[0];
    assert counts'[1..] == tailC[i - 1 := counts[i] + 1];
    assert tailC[i - 1] == counts[i];
    assert tailCoins[i - 1] == coins[i];
    assert tailC[i - 1 := tailC[i - 1] + 1] == tailC[i - 1 := counts[i] + 1];
    TotalAmountInc(tailC, tailCoins, i - 1);
    UnfoldAmount(counts, coins);
    UnfoldAmount(counts', coins);
    assert total_amount(counts'[1..], tailCoins) == total_amount(tailC[i - 1 := tailC[i - 1] + 1], tailCoins);
    assert total_amount(tailC[i - 1 := tailC[i - 1] + 1], tailCoins) == total_amount(tailC, tailCoins) + tailCoins[i - 1];
    assert tailCoins[i - 1] == coins[i];
    var head := counts[0] * coins[0];
    var rest := total_amount(tailC, tailCoins);
    assert total_amount(counts', coins) == counts'[0] * coins[0] + total_amount(counts'[1..], tailCoins);
    assert counts'[0] * coins[0] == head;
    assert total_amount(counts', coins) == head + (rest + coins[i]);
    assert head + (rest + coins[i]) == (head + rest) + coins[i];
    assert total_amount(counts, coins) == head + rest;
    assert total_amount(counts', coins) == total_amount(counts, coins) + coins[i];
  }
}

lemma {:isolate_assertions} TotalAmountDec(counts: seq<int>, coins: seq<int>, i: int)
  requires |counts| == |coins|
  requires 0 <= i < |counts|
  ensures total_amount(counts[i := counts[i] - 1], coins) == total_amount(counts, coins) - coins[i]
  decreases i
{
  if i == 0 {
    var counts' := counts[0 := counts[0] - 1];
    UpdateHeadTail(counts, counts[0] - 1);
    UnfoldAmount(counts, coins);
    UnfoldAmount(counts', coins);
    assert counts'[1..] == counts[1..];
    assert counts'[0] == counts[0] - 1;
    var rest := total_amount(counts[1..], coins[1..]);
    assert total_amount(counts'[1..], coins[1..]) == rest;
    MulSubOne(counts[0], coins[0]);
    var p := counts[0] * coins[0];
    assert (counts[0] - 1) * coins[0] == p - coins[0];
    assert total_amount(counts', coins) == (counts[0] - 1) * coins[0] + rest;
    assert total_amount(counts', coins) == (p - coins[0]) + rest;
    assert total_amount(counts, coins) == p + rest;
    assert (p - coins[0]) + rest == (p + rest) - coins[0];
    assert total_amount(counts', coins) == total_amount(counts, coins) - coins[0];
  } else {
    var counts' := counts[i := counts[i] - 1];
    var tailC := counts[1..];
    var tailCoins := coins[1..];
    assert |tailC| == |tailCoins|;
    assert 0 <= i - 1 < |tailC|;
    SeqUpdateTail(counts, i, counts[i] - 1);
    assert counts'[0] == counts[0];
    assert counts'[1..] == tailC[i - 1 := counts[i] - 1];
    assert tailC[i - 1] == counts[i];
    assert tailCoins[i - 1] == coins[i];
    assert tailC[i - 1 := tailC[i - 1] - 1] == tailC[i - 1 := counts[i] - 1];
    TotalAmountDec(tailC, tailCoins, i - 1);
    UnfoldAmount(counts, coins);
    UnfoldAmount(counts', coins);
    assert total_amount(counts'[1..], tailCoins) == total_amount(tailC[i - 1 := tailC[i - 1] - 1], tailCoins);
    assert total_amount(tailC[i - 1 := tailC[i - 1] - 1], tailCoins) == total_amount(tailC, tailCoins) - tailCoins[i - 1];
    var head := counts[0] * coins[0];
    var rest := total_amount(tailC, tailCoins);
    assert total_amount(counts', coins) == head + (rest - coins[i]);
    assert head + (rest - coins[i]) == (head + rest) - coins[i];
    assert total_amount(counts, coins) == head + rest;
    assert total_amount(counts', coins) == total_amount(counts, coins) - coins[i];
  }
}

lemma TotalCoinsInc(counts: seq<int>, i: int)
  requires 0 <= i < |counts|
  ensures total_coins(counts[i := counts[i] + 1]) == total_coins(counts) + 1
  decreases i
{
  if i == 0 {
    var counts' := counts[0 := counts[0] + 1];
    UpdateHeadTail(counts, counts[0] + 1);
    UnfoldCoins(counts);
    UnfoldCoins(counts');
    assert counts'[1..] == counts[1..];
    assert counts'[0] == counts[0] + 1;
    assert total_coins(counts') == (counts[0] + 1) + total_coins(counts[1..]);
    assert total_coins(counts) == counts[0] + total_coins(counts[1..]);
    assert total_coins(counts') == total_coins(counts) + 1;
  } else {
    var counts' := counts[i := counts[i] + 1];
    var tailC := counts[1..];
    assert 0 <= i - 1 < |tailC|;
    SeqUpdateTail(counts, i, counts[i] + 1);
    assert counts'[0] == counts[0];
    assert counts'[1..] == tailC[i - 1 := counts[i] + 1];
    assert tailC[i - 1] == counts[i];
    assert tailC[i - 1 := tailC[i - 1] + 1] == tailC[i - 1 := counts[i] + 1];
    TotalCoinsInc(tailC, i - 1);
    UnfoldCoins(counts);
    UnfoldCoins(counts');
    assert total_coins(counts'[1..]) == total_coins(tailC[i - 1 := tailC[i - 1] + 1]);
    assert total_coins(tailC[i - 1 := tailC[i - 1] + 1]) == total_coins(tailC) + 1;
    assert total_coins(counts') == counts[0] + total_coins(tailC) + 1;
    assert total_coins(counts) == counts[0] + total_coins(tailC);
  }
}

lemma TotalCoinsDec(counts: seq<int>, i: int)
  requires 0 <= i < |counts|
  ensures total_coins(counts[i := counts[i] - 1]) == total_coins(counts) - 1
  decreases i
{
  if i == 0 {
    var counts' := counts[0 := counts[0] - 1];
    UpdateHeadTail(counts, counts[0] - 1);
    UnfoldCoins(counts);
    UnfoldCoins(counts');
    assert counts'[1..] == counts[1..];
    assert counts'[0] == counts[0] - 1;
    assert total_coins(counts') == (counts[0] - 1) + total_coins(counts[1..]);
    assert total_coins(counts) == counts[0] + total_coins(counts[1..]);
    assert total_coins(counts') == total_coins(counts) - 1;
  } else {
    var counts' := counts[i := counts[i] - 1];
    var tailC := counts[1..];
    assert 0 <= i - 1 < |tailC|;
    SeqUpdateTail(counts, i, counts[i] - 1);
    assert counts'[0] == counts[0];
    assert counts'[1..] == tailC[i - 1 := counts[i] - 1];
    assert tailC[i - 1] == counts[i];
    assert tailC[i - 1 := tailC[i - 1] - 1] == tailC[i - 1 := counts[i] - 1];
    TotalCoinsDec(tailC, i - 1);
    UnfoldCoins(counts);
    UnfoldCoins(counts');
    assert total_coins(counts'[1..]) == total_coins(tailC[i - 1 := tailC[i - 1] - 1]);
    assert total_coins(tailC[i - 1 := tailC[i - 1] - 1]) == total_coins(tailC) - 1;
    assert total_coins(counts') == counts[0] + (total_coins(tailC) - 1);
    assert counts[0] + (total_coins(tailC) - 1) == (counts[0] + total_coins(tailC)) - 1;
    assert total_coins(counts) == counts[0] + total_coins(tailC);
  }
}

lemma IncValid(counts: seq<int>, coins: seq<int>, i: int, amt: int)
  requires |counts| == |coins|
  requires 0 <= i < |counts|
  requires is_valid_change(counts, coins, amt)
  requires forall j :: 0 <= j < |coins| ==> coins[j] > 0
  ensures is_valid_change(counts[i := counts[i] + 1], coins, amt + coins[i])
  ensures total_coins(counts[i := counts[i] + 1]) == total_coins(counts) + 1
{
  assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
  assert total_amount(counts, coins) == amt;
  var counts' := counts[i := counts[i] + 1];
  forall j | 0 <= j < |counts'|
    ensures counts'[j] >= 0
  {
    if j == i {
      assert counts'[j] == counts[i] + 1;
      assert counts[i] >= 0;
    } else {
      assert counts'[j] == counts[j];
    }
  }
  TotalAmountInc(counts, coins, i);
  TotalCoinsInc(counts, i);
  assert total_amount(counts', coins) == amt + coins[i];
  assert total_coins(counts') == total_coins(counts) + 1;
  assert |counts'| == |coins|;
  assert is_valid_change(counts', coins, amt + coins[i]);
}

lemma DecValid(counts: seq<int>, coins: seq<int>, i: int, amt: int)
  requires |counts| == |coins|
  requires 0 <= i < |counts|
  requires counts[i] >= 1
  requires is_valid_change(counts, coins, amt)
  requires forall j :: 0 <= j < |coins| ==> coins[j] > 0
  ensures is_valid_change(counts[i := counts[i] - 1], coins, amt - coins[i])
  ensures total_coins(counts[i := counts[i] - 1]) == total_coins(counts) - 1
{
  assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
  assert total_amount(counts, coins) == amt;
  var counts' := counts[i := counts[i] - 1];
  forall j | 0 <= j < |counts'|
    ensures counts'[j] >= 0
  {
    if j == i {
      assert counts'[j] == counts[i] - 1;
      assert counts[i] >= 1;
    } else {
      assert counts'[j] == counts[j];
    }
  }
  TotalAmountDec(counts, coins, i);
  TotalCoinsDec(counts, i);
  assert total_amount(counts', coins) == amt - coins[i];
  assert total_coins(counts') == total_coins(counts) - 1;
  assert |counts'| == |coins|;
  assert is_valid_change(counts', coins, amt - coins[i]);
}

lemma {:isolate_assertions} AmountAtLeastCoin(counts: seq<int>, coins: seq<int>, i: int)
  requires |counts| == |coins|
  requires 0 <= i < |counts|
  requires counts[i] >= 1
  requires forall j :: 0 <= j < |counts| ==> counts[j] >= 0
  requires forall j :: 0 <= j < |coins| ==> coins[j] > 0
  ensures total_amount(counts, coins) >= coins[i]
  decreases i
{
  if i == 0 {
    TailCountsNonNeg(counts);
    TailCoinsPos(coins);
    TotalAmountNonNeg(counts[1..], coins[1..]);
    assert counts[0] >= 1;
    assert coins[0] > 0;
    assert coins[0] >= 0;
    MulAtLeastSecond(counts[0], coins[0]);
    UnfoldAmount(counts, coins);
    assert total_amount(counts[1..], coins[1..]) >= 0;
    assert counts[0] * coins[0] >= coins[0];
    assert total_amount(counts, coins) >= coins[0];
  } else {
    TailCountsNonNeg(counts);
    TailCoinsPos(coins);
    assert counts[1..][i - 1] == counts[i];
    assert counts[1..][i - 1] >= 1;
    assert coins[1..][i - 1] == coins[i];
    forall j | 0 <= j < |counts[1..]|
      ensures counts[1..][j] >= 0
    {
      assert counts[1..][j] == counts[j + 1];
    }
    forall j | 0 <= j < |coins[1..]|
      ensures coins[1..][j] > 0
    {
      assert coins[1..][j] == coins[j + 1];
    }
    AmountAtLeastCoin(counts[1..], coins[1..], i - 1);
    assert counts[0] >= 0;
    assert coins[0] > 0;
    assert coins[0] >= 0;
    MulNonNeg(counts[0], coins[0]);
    UnfoldAmount(counts, coins);
    assert total_amount(counts[1..], coins[1..]) >= coins[i];
    assert counts[0] * coins[0] >= 0;
    assert total_amount(counts, coins) >= coins[i];
  }
}

ghost function {:opaque} Opt(coins: seq<int>, k: int, a: int, inf: int): int
  requires 0 <= k <= |coins|
  requires a >= 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  decreases a, k
{
  if a == 0 then 0
  else if k == 0 then inf
  else if coins[k - 1] > a then Opt(coins, k - 1, a, inf)
  else if coins[k - 1] <= 0 then inf
  else if Opt(coins, k, a - coins[k - 1], inf) < inf &&
          Opt(coins, k, a - coins[k - 1], inf) + 1 < Opt(coins, k - 1, a, inf) then
    Opt(coins, k, a - coins[k - 1], inf) + 1
  else
    Opt(coins, k - 1, a, inf)
}

lemma OptEqZero(coins: seq<int>, k: int, inf: int)
  requires 0 <= k <= |coins|
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures Opt(coins, k, 0, inf) == 0
{
  assert Opt(coins, k, 0, inf) == 0 by {
    reveal Opt();
  }
}

lemma OptEqNoCoins(coins: seq<int>, a: int, inf: int)
  requires a > 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures Opt(coins, 0, a, inf) == inf
{
  assert Opt(coins, 0, a, inf) == inf by {
    reveal Opt();
  }
}

lemma OptEqSkip(coins: seq<int>, k: int, a: int, inf: int)
  requires 1 <= k <= |coins|
  requires a > 0
  requires coins[k - 1] > a
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures Opt(coins, k, a, inf) == Opt(coins, k - 1, a, inf)
{
  assert Opt(coins, k, a, inf) == Opt(coins, k - 1, a, inf) by {
    reveal Opt();
    assert a > 0;
    assert k > 0;
    assert coins[k - 1] > a;
  }
}

lemma OptEqTake(coins: seq<int>, k: int, a: int, inf: int)
  requires 1 <= k <= |coins|
  requires a > 0
  requires 0 < coins[k - 1] <= a
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures Opt(coins, k, a, inf) ==
    (if Opt(coins, k, a - coins[k - 1], inf) < inf &&
        Opt(coins, k, a - coins[k - 1], inf) + 1 < Opt(coins, k - 1, a, inf)
     then Opt(coins, k, a - coins[k - 1], inf) + 1
     else Opt(coins, k - 1, a, inf))
{
  assert Opt(coins, k, a, inf) ==
    (if Opt(coins, k, a - coins[k - 1], inf) < inf &&
        Opt(coins, k, a - coins[k - 1], inf) + 1 < Opt(coins, k - 1, a, inf)
     then Opt(coins, k, a - coins[k - 1], inf) + 1
     else Opt(coins, k - 1, a, inf)) by {
    reveal Opt();
    assert a > 0;
    assert k > 0;
    assert !(coins[k - 1] > a);
    assert !(coins[k - 1] <= 0);
    assert coins[k - 1] > 0;
    assert a - coins[k - 1] >= 0;
    assert a - coins[k - 1] < a;
  }
}

lemma {:isolate_assertions} OptBound(coins: seq<int>, k: int, a: int, inf: int)
  requires 0 <= k <= |coins|
  requires a >= 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures 0 <= Opt(coins, k, a, inf) <= inf
  decreases a, k
{
  if a == 0 {
    OptEqZero(coins, k, inf);
    assert Opt(coins, k, a, inf) == 0;
  } else if k == 0 {
    assert a > 0;
    OptEqNoCoins(coins, a, inf);
    assert Opt(coins, k, a, inf) == inf;
    assert 0 < inf;
  } else if coins[k - 1] > a {
    assert a > 0;
    assert k >= 1;
    OptEqSkip(coins, k, a, inf);
    OptBound(coins, k - 1, a, inf);
    assert Opt(coins, k, a, inf) == Opt(coins, k - 1, a, inf);
  } else {
    assert a > 0;
    assert k >= 1;
    assert coins[k - 1] <= a;
    assert 0 <= k - 1 < |coins|;
    assert coins[k - 1] > 0;
    OptEqTake(coins, k, a, inf);
    OptBound(coins, k - 1, a, inf);
    assert a - coins[k - 1] < a;
    assert a - coins[k - 1] >= 0;
    OptBound(coins, k, a - coins[k - 1], inf);
    var prev := Opt(coins, k, a - coins[k - 1], inf);
    var without := Opt(coins, k - 1, a, inf);
    assert 0 <= without <= inf;
    assert 0 <= prev <= inf;
    assert Opt(coins, k, a, inf) == (if prev < inf && prev + 1 < without then prev + 1 else without);
    if prev < inf && prev + 1 < without {
      assert Opt(coins, k, a, inf) == prev + 1;
      assert prev <= inf - 1;
      assert prev + 1 <= inf;
      assert prev + 1 >= 1;
    } else {
      assert Opt(coins, k, a, inf) == without;
    }
  }
}

lemma OptLeWithout(coins: seq<int>, k: int, a: int, inf: int)
  requires 1 <= k <= |coins|
  requires a > 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures Opt(coins, k, a, inf) <= Opt(coins, k - 1, a, inf)
{
  if coins[k - 1] > a {
    OptEqSkip(coins, k, a, inf);
    assert Opt(coins, k, a, inf) == Opt(coins, k - 1, a, inf);
  } else {
    assert coins[k - 1] <= a;
    assert coins[k - 1] > 0;
    OptEqTake(coins, k, a, inf);
    var prev := Opt(coins, k, a - coins[k - 1], inf);
    var without := Opt(coins, k - 1, a, inf);
    assert Opt(coins, k, a, inf) == (if prev < inf && prev + 1 < without then prev + 1 else without);
    if prev < inf && prev + 1 < without {
      assert Opt(coins, k, a, inf) == prev + 1;
      assert prev + 1 < without;
      assert Opt(coins, k, a, inf) <= without;
    } else {
      assert Opt(coins, k, a, inf) == without;
    }
  }
}

lemma OptLePrevPlus(coins: seq<int>, k: int, a: int, inf: int)
  requires 1 <= k <= |coins|
  requires a > 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires 0 < coins[k - 1] <= a
  ensures Opt(coins, k, a, inf) <= Opt(coins, k, a - coins[k - 1], inf) + 1
{
  OptEqTake(coins, k, a, inf);
  OptBound(coins, k - 1, a, inf);
  var prev := Opt(coins, k, a - coins[k - 1], inf);
  var without := Opt(coins, k - 1, a, inf);
  assert 0 <= without <= inf;
  assert Opt(coins, k, a, inf) == (if prev < inf && prev + 1 < without then prev + 1 else without);
  if prev < inf && prev + 1 < without {
    assert Opt(coins, k, a, inf) == prev + 1;
  } else if prev < inf {
    assert !(prev + 1 < without);
    assert prev + 1 >= without;
    assert Opt(coins, k, a, inf) == without;
    assert without <= prev + 1;
  } else {
    assert prev >= inf;
    assert Opt(coins, k, a, inf) == without;
    assert without <= inf;
    assert inf <= prev;
    assert without <= prev;
    assert prev <= prev + 1;
    assert without <= prev + 1;
  }
}

lemma OnlyPrefixRelax(counts: seq<int>, k: int)
  requires k >= 0
  requires OnlyPrefix(counts, k)
  ensures OnlyPrefix(counts, k + 1)
{
  forall i | 0 <= i < |counts| && k + 1 <= i
    ensures counts[i] == 0
  {
    assert k <= i;
    assert counts[i] == 0;
  }
}

lemma OnlyPrefixTighten(counts: seq<int>, k: int)
  requires 1 <= k <= |counts|
  requires OnlyPrefix(counts, k)
  requires counts[k - 1] == 0
  ensures OnlyPrefix(counts, k - 1)
{
  forall i | 0 <= i < |counts| && k - 1 <= i
    ensures counts[i] == 0
  {
    if i == k - 1 {
      assert counts[i] == 0;
    } else {
      assert i >= k;
      assert counts[i] == 0;
    }
  }
}

lemma OnlyPrefixPreservePoint(counts: seq<int>, k: int, i: int, v: int)
  requires 0 <= i < |counts|
  requires i < k
  requires OnlyPrefix(counts, k)
  ensures OnlyPrefix(counts[i := v], k)
{
  var counts' := counts[i := v];
  forall j | 0 <= j < |counts'| && k <= j
    ensures counts'[j] == 0
  {
    assert j != i;
    assert counts'[j] == counts[j];
    assert counts[j] == 0;
  }
}

lemma OnlyPrefixVacuous(counts: seq<int>)
  ensures OnlyPrefix(counts, |counts|)
{
  forall i | 0 <= i < |counts| && |counts| <= i
    ensures counts[i] == 0
  {
  }
}

lemma OnlyPrefixZero(counts: seq<int>)
  requires OnlyPrefix(counts, 0)
  ensures forall i :: 0 <= i < |counts| ==> counts[i] == 0
{
  forall i | 0 <= i < |counts|
    ensures counts[i] == 0
  {
    assert 0 <= i;
  }
}

lemma ZerosAreValid(coins: seq<int>, k: int)
  requires k >= 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures is_valid_change(Zeros(|coins|), coins, 0)
  ensures total_coins(Zeros(|coins|)) == 0
  ensures OnlyPrefix(Zeros(|coins|), k)
{
