  ZerosProps(|coins|);
  assert |z| == |coins|;
  forall i | 0 <= i < |z|
    ensures z[i] == 0
  {
    assert ZerosProps(|coins|); 
  }
  assert forall i :: 0 <= i < |z| ==> z[i] == 0;
  TotalZeros(z, coins);
  forall i | 0 <= i < |z|
    ensures z[i] >= 0
  {
    assert z[i] == 0;
  }
  assert is_valid_change(z, coins, 0);
  assert total_coins(z) == 0;
  forall i | 0 <= i < |z| && k <= i
    ensures z[i] == 0
  {
    assert z[i] == 0;
