lemma {:isolate_assertions} OptWitness(coins: seq<int>, k: int, a: int, inf: int) returns (counts: seq<int>)
  requires 0 <= k <= |coins|
  requires a >= 0
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires Opt(coins, k, a, inf) < inf
  ensures |counts| == |coins|
  ensures is_valid_change(counts, coins, a)
  ensures total_coins(counts) == Opt(coins, k, a, inf)
  ensures OnlyPrefix(counts, k)
  decreases a, k
{
  if a == 0 {
    OptEqZero(coins, k, inf);
    counts := Zeros(|coins|);
    ZerosAreValid(coins, k);
    assert total_coins(counts) == 0;
    assert Opt(coins, k, a, inf) == 0;
    assert total_coins(counts) == Opt(coins, k, a, inf);
  } else if k == 0 {
    counts := Zeros(|coins|);
    OptEqNoCoins(coins, a, inf);
    assert Opt(coins, k, a, inf) == inf;
    assert Opt(coins, k, a, inf) < inf;
    assert false;
  } else if coins[k - 1] > a {
    assert a > 0;
    assert k >= 1;
    OptEqSkip(coins, k, a, inf);
    assert Opt(coins, k, a, inf) == Opt(coins, k - 1, a, inf);
    assert Opt(coins, k - 1, a, inf) < inf;
    counts := OptWitness(coins, k - 1, a, inf);
    OnlyPrefixRelax(counts, k - 1);
    assert total_coins(counts) == Opt(coins, k - 1, a, inf);
    assert total_coins(counts) == Opt(coins, k, a, inf);
  } else {
    assert a > 0;
    assert k >= 1;
    assert coins[k - 1] <= a;
    assert coins[k - 1] > 0;
    var c := coins[k - 1];
    assert 0 < c <= a;
    assert 0 <= a - c < a;
    OptEqTake(coins, k, a, inf);
    var prev := Opt(coins, k, a - c, inf);
    var without := Opt(coins, k - 1, a, inf);
    assert Opt(coins, k, a, inf) == (if prev < inf && prev + 1 < without then prev + 1 else without);
    if prev < inf && prev + 1 < without {
      assert Opt(coins, k, a, inf) == prev + 1;
      var w := OptWitness(coins, k, a - c, inf);
      assert |w| == |coins|;
      assert total_coins(w) == prev;
      assert is_valid_change(w, coins, a - c);
      assert OnlyPrefix(w, k);
      IncValid(w, coins, k - 1, a - c);
      counts := w[k - 1 := w[k - 1] + 1];
      assert counts == w[k - 1 := w[k - 1] + 1];
      assert is_valid_change(counts, coins, a - c + c);
      assert a - c + c == a;
      assert is_valid_change(counts, coins, a);
      assert total_coins(counts) == total_coins(w) + 1;
      assert total_coins(counts) == prev + 1;
      assert total_coins(counts) == Opt(coins, k, a, inf);
      OnlyPrefixPreservePoint(w, k, k - 1, w[k - 1] + 1);
      assert OnlyPrefix(counts, k);
    } else {
      assert Opt(coins, k, a, inf) == without;
      assert without < inf;
      counts := OptWitness(coins, k - 1, a, inf);
      OnlyPrefixRelax(counts, k - 1);
      assert total_coins(counts) == without;
      assert total_coins(counts) == Opt(coins, k, a, inf);
    }
  }
}

lemma {:isolate_assertions} OptLowerBound(coins: seq<int>, k: int, a: int, inf: int, counts: seq<int>)
  requires 0 <= k <= |coins|
  requires a >= 0
  requires inf > a
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires is_valid_change(counts, coins, a)
  requires OnlyPrefix(counts, k)
  ensures total_coins(counts) >= Opt(coins, k, a, inf)
  decreases a, k
{
  if a == 0 {
    OptEqZero(coins, k, inf);
    assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
    TotalCoinsNonNeg(counts);
    assert Opt(coins, k, a, inf) == 0;
    assert total_coins(counts) >= 0;
  } else if k == 0 {
    OptEqNoCoins(coins, a, inf);
    OnlyPrefixZero(counts);
    assert forall i :: 0 <= i < |counts| ==> counts[i] == 0;
    TotalZeros(counts, coins);
    assert total_amount(counts, coins) == 0;
    assert total_amount(counts, coins) == a;
    assert a > 0;
    assert false;
  } else if counts[k - 1] == 0 {
    assert a > 0;
    assert 1 <= k <= |coins|;
    assert |counts| == |coins|;
    assert 1 <= k <= |counts|;
    OnlyPrefixTighten(counts, k);
    OptLowerBound(coins, k - 1, a, inf, counts);
    OptLeWithout(coins, k, a, inf);
    assert total_coins(counts) >= Opt(coins, k - 1, a, inf);
    assert Opt(coins, k - 1, a, inf) >= Opt(coins, k, a, inf);
    assert total_coins(counts) >= Opt(coins, k, a, inf);
  } else {
    assert a > 0;
    assert 1 <= k <= |coins|;
    assert |counts| == |coins|;
    var i := k - 1;
    assert 0 <= i < |counts|;
    assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
    assert counts[i] >= 0;
    assert counts[i] != 0;
    assert counts[i] >= 1;
    assert total_amount(counts, coins) == a;
    AmountAtLeastCoin(counts, coins, i);
    assert total_amount(counts, coins) >= coins[i];
    assert coins[i] <= a;
    assert coins[i] > 0;
    var c := coins[i];
    assert 0 <= a - c < a;
    assert inf > a;
    assert a - c < inf;
    assert inf > a - c;
    var counts' := counts[i := counts[i] - 1];
    DecValid(counts, coins, i, a);
    assert is_valid_change(counts', coins, a - c);
    assert total_coins(counts') == total_coins(counts) - 1;
    OnlyPrefixPreservePoint(counts, k, i, counts[i] - 1);
    assert OnlyPrefix(counts', k);
    OptLowerBound(coins, k, a - c, inf, counts');
    var prev := Opt(coins, k, a - c, inf);
    assert total_coins(counts') >= prev;
    if prev >= inf {
      assert forall j :: 0 <= j < |counts'| ==> counts'[j] >= 0;
      TotalCoinsLeAmount(counts', coins);
      assert total_coins(counts') <= total_amount(counts', coins);
      assert total_amount(counts', coins) == a - c;
      assert total_coins(counts') <= a - c;
      assert a - c < inf;
      assert total_coins(counts') >= inf;
      assert total_coins(counts') < inf;
      assert false;
    } else {
      assert total_coins(counts) == total_coins(counts') + 1;
      assert total_coins(counts) >= prev + 1;
      OptLePrevPlus(coins, k, a, inf);
      assert Opt(coins, k, a, inf) <= prev + 1;
      assert total_coins(counts) >= Opt(coins, k, a, inf);
    }
  }
}

lemma ExistsIntro(coins: seq<int>, amount: int, m: int, w: seq<int>)
  requires is_valid_change(w, coins, amount)
  requires total_coins(w) == m
  ensures exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == m
{
  assert is_valid_change(w, coins, amount) && total_coins(w) == m;
}

lemma Complete(coins: seq<int>, amount: int, inf: int, m: int)
  requires amount >= 0
  requires inf == amount + 1
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires m == Opt(coins, |coins|, amount, inf)
  requires m < inf
  ensures exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == m
  ensures forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> total_coins(counts) >= m
{
  assert inf > 0;
  assert inf > amount;
  var w := OptWitness(coins, |coins|, amount, inf);
  assert is_valid_change(w, coins, amount);
  assert total_coins(w) == m;
  ExistsIntro(coins, amount, m, w);
  forall counts: seq<int> | is_valid_change(counts, coins, amount)
    ensures total_coins(counts) >= m
  {
    OnlyPrefixVacuous(counts);
    assert OnlyPrefix(counts, |coins|);
    OptLowerBound(coins, |coins|, amount, inf, counts);
    assert total_coins(counts) >= Opt(coins, |coins|, amount, inf);
    assert Opt(coins, |coins|, amount, inf) == m;
  }
}

lemma Impossible(coins: seq<int>, amount: int, inf: int, m: int)
  requires amount >= 0
  requires inf == amount + 1
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires m == Opt(coins, |coins|, amount, inf)
  requires m == inf
  ensures forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
{
  assert inf > amount;
  forall counts: seq<int> | is_valid_change(counts, coins, amount)
    ensures false
  {
    OnlyPrefixVacuous(counts);
    OptLowerBound(coins, |coins|, amount, inf, counts);
    assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
    TotalCoinsLeAmount(counts, coins);
    assert total_coins(counts) >= m;
    assert total_coins(counts) <= total_amount(counts, coins);
    assert total_amount(counts, coins) == amount;
    assert total_coins(counts) <= amount;
    assert m == amount + 1;
    assert total_coins(counts) >= amount + 1;
    assert false;
  }
}

lemma NegativeImpossible(coins: seq<int>, amount: int)
  requires amount < 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  ensures forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
{
  forall counts: seq<int> | is_valid_change(counts, coins, amount)
    ensures false
  {
    assert forall j :: 0 <= j < |counts| ==> counts[j] >= 0;
    TotalAmountNonNeg(counts, coins);
    assert total_amount(counts, coins) >= 0;
    assert total_amount(counts, coins) == amount;
    assert false;
  }
}

lemma AppendEq(dp: seq<int>, dp2: seq<int>, v: int, inf: int)
  requires dp2 == dp + [v]
  requires forall j :: 0 <= j < |dp| ==> dp[j] == (if j == 0 then 0 else inf)
  requires v == (if |dp| == 0 then 0 else inf)
  ensures forall j :: 0 <= j < |dp2| ==> dp2[j] == (if j == 0 then 0 else inf)
{
  assert |dp2| == |dp| + 1;
  forall j | 0 <= j < |dp2|
    ensures dp2[j] == (if j == 0 then 0 else inf)
  {
    if j < |dp| {
      assert dp2[j] == dp[j];
    } else {
      assert j == |dp|;
      assert dp2[j] == v;
      if j == 0 {
        assert |dp| == 0;
        assert v == 0;
      } else {
        assert |dp| != 0;
        assert v == inf;
      }
    }
  }
}

lemma InitMatch(coins: seq<int>, dp: seq<int>, amount: int, inf: int)
  requires amount >= 0
  requires inf == amount + 1
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires |dp| == amount + 1
  requires forall j :: 0 <= j < |dp| ==> dp[j] == (if j == 0 then 0 else inf)
  ensures forall j :: 0 <= j <= amount ==> dp[j] == Opt(coins, 0, j, inf)
{
  forall j | 0 <= j <= amount
    ensures dp[j] == Opt(coins, 0, j, inf)
  {
    if j == 0 {
      OptEqZero(coins, 0, inf);
      assert dp[j] == 0;
      assert Opt(coins, 0, j, inf) == 0;
    } else {
      assert j > 0;
      OptEqNoCoins(coins, j, inf);
      assert dp[j] == inf;
      assert Opt(coins, 0, j, inf) == inf;
    }
  }
}

lemma {:isolate_assertions} ProveNewV(dp: seq<int>, coins: seq<int>, ki: int, a: int, amount: int, inf: int, newV: int)
  requires 0 <= ki < |coins|
  requires 0 <= a <= amount
  requires |dp| == amount + 1
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires forall x :: 0 <= x < a ==> dp[x] == Opt(coins, ki + 1, x, inf)
  requires forall x :: a <= x <= amount ==> dp[x] == Opt(coins, ki, x, inf)
  requires a == 0 ==> newV == 0
  requires a > 0 && coins[ki] > a ==> newV == dp[a]
  requires a > 0 && coins[ki] <= a && dp[a - coins[ki]] < inf && dp[a - coins[ki]] + 1 < dp[a] ==> newV == dp[a - coins[ki]] + 1
  requires a > 0 && coins[ki] <= a && !(dp[a - coins[ki]] < inf && dp[a - coins[ki]] + 1 < dp[a]) ==> newV == dp[a]
  ensures newV == Opt(coins, ki + 1, a, inf)
{
  if a == 0 {
    OptEqZero(coins, ki + 1, inf);
    assert newV == 0;
    assert Opt(coins, ki + 1, 0, inf) == 0;
    assert newV == Opt(coins, ki + 1, a, inf);
  } else if coins[ki] > a {
    assert a > 0;
    assert 1 <= ki + 1 <= |coins|;
    OptEqSkip(coins, ki + 1, a, inf);
    assert dp[a] == Opt(coins, ki, a, inf);
    assert Opt(coins, ki + 1, a, inf) == Opt(coins, ki, a, inf);
    assert newV == dp[a];
    assert newV == Opt(coins, ki + 1, a, inf);
  } else {
    assert a > 0;
    assert coins[ki] <= a;
    assert coins[ki] > 0;
    var c := coins[ki];
    assert 0 < c <= a;
    assert 0 <= a - c < a;
    assert a - c <= amount;
    assert dp[a] == Opt(coins, ki, a, inf);
    assert dp[a - c] == Opt(coins, ki + 1, a - c, inf);
    assert 1 <= ki + 1 <= |coins|;
    assert coins[(ki + 1) - 1] == c;
    OptEqTake(coins, ki + 1, a, inf);
    var prev := dp[a - c];
    var without := dp[a];
    var prevOpt := Opt(coins, ki + 1, a - c, inf);
    var withoutOpt := Opt(coins, ki, a, inf);
    assert prev == prevOpt;
    assert without == withoutOpt;
    assert Opt(coins, ki + 1, a, inf) == (if prevOpt < inf && prevOpt + 1 < withoutOpt then prevOpt + 1 else withoutOpt);
    if prev < inf && prev + 1 < without {
      assert newV == prev + 1;
      assert Opt(coins, ki + 1, a, inf) == prev + 1;
      assert newV == Opt(coins, ki + 1, a, inf);
    } else {
      assert !(prev < inf && prev + 1 < without);
      assert newV == dp[a];
      assert newV == without;
      assert Opt(coins, ki + 1, a, inf) == without;
      assert newV == Opt(coins, ki + 1, a, inf);
    }
  }
}

lemma Advance(dp: seq<int>, dp2: seq<int>, coins: seq<int>, ki: int, a: int, amount: int, inf: int, newV: int)
  requires 0 <= ki < |coins|
  requires 0 <= a <= amount
  requires inf > 0
  requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
  requires |dp| == amount + 1
  requires dp2 == dp[a := newV]
  requires newV == Opt(coins, ki + 1, a, inf)
  requires forall x :: 0 <= x < a ==> dp[x] == Opt(coins, ki + 1, x, inf)
  requires forall x :: a <= x <= amount ==> dp[x] == Opt(coins, ki, x, inf)
  ensures |dp2| == amount + 1
  ensures forall x :: 0 <= x < a + 1 ==> dp2[x] == Opt(coins, ki + 1, x, inf)
  ensures forall x :: a + 1 <= x <= amount ==> dp2[x] == Opt(coins, ki, x, inf)
{
  assert |dp2| == |dp|;
  forall x | 0 <= x < a + 1
    ensures dp2[x] == Opt(coins, ki + 1, x, inf)
  {
    if x < a {
      assert x != a;
      assert dp2[x] == dp[x];
      assert dp[x] == Opt(coins, ki + 1, x, inf);
    } else {
      assert x == a;
      assert dp2[x] == newV;
      assert newV == Opt(coins, ki + 1, x, inf);
    }
  }
  forall x | a + 1 <= x <= amount
    ensures dp2[x] == Opt(coins, ki, x, inf)
  {
    assert x != a;
    assert dp2[x] == dp[x];
    assert a <= x;
    assert dp[x] == Opt(coins, ki, x, inf);
  }
}

method coin_change(coins: seq<int>, amount: int) returns (min_coins: int)
  requires |coins| > 0
  requires |coins| <= 100
  requires amount <= 10000
  requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
  requires forall i: int :: 0 <= i < |coins| ==> coins[i] <= 10000
  ensures
    min_coins != -1 ==> (
      (exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == min_coins)
      &&
      (forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> total_coins(counts) >= min_coins)
    )
  ensures
    min_coins == -1 ==> (
      forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
    )
{
  if amount < 0 {
    NegativeImpossible(coins, amount);
    min_coins := -1;
    return;
  }

  var inf := amount + 1;
  assert inf == amount + 1;
  assert inf > amount;
  assert inf > 0;

  var dp: seq<int> := [];
  var i := 0;
  while i <= amount
    invariant 0 <= i <= amount + 1
    invariant |dp| == i
    invariant inf == amount + 1
    invariant forall j :: 0 <= j < i ==> dp[j] == (if j == 0 then 0 else inf)
    decreases amount + 1 - i
  {
    var v := if i == 0 then 0 else inf;
    assert v == (if |dp| == 0 then 0 else inf);
    var dp2 := dp + [v];
    AppendEq(dp, dp2, v, inf);
    var nexti := i + 1;
    forall j | 0 <= j < nexti
      ensures dp2[j] == (if j == 0 then 0 else inf)
    {
      assert j < |dp2|;
      assert dp2[j] == (if j == 0 then 0 else inf);
    }
    dp := dp2;
    i := nexti;
    forall j | 0 <= j < i
      ensures dp[j] == (if j == 0 then 0 else inf)
    {
      assert dp[j] == dp2[j];
    }
  }
  assert i == amount + 1;
  assert |dp| == amount + 1;
  InitMatch(coins, dp, amount, inf);

  var ki := 0;
  forall x | 0 <= x <= amount
    ensures dp[x] == Opt(coins, ki, x, inf)
  {
    assert dp[x] == Opt(coins, 0, x, inf);
    assert ki == 0;
  }

  while ki < |coins|
    invariant 0 <= ki <= |coins|
    invariant |dp| == amount + 1
    invariant inf == amount + 1
    invariant inf > 0
    invariant forall x :: 0 <= x <= amount ==> dp[x] == Opt(coins, ki, x, inf)
    decreases |coins| - ki
  {
    var a := 0;
    while a <= amount
      invariant 0 <= a <= amount + 1
      invariant |dp| == amount + 1
      invariant inf == amount + 1
      invariant inf > 0
      invariant ki < |coins|
      invariant forall x :: 0 <= x < a ==> dp[x] == Opt(coins, ki + 1, x, inf)
      invariant forall x :: a <= x <= amount ==> dp[x] == Opt(coins, ki, x, inf)
      decreases amount + 1 - a
    {
      var newV: int;
      if a == 0 {
        newV := 0;
        assert newV == 0;
      } else if coins[ki] > a {
        newV := dp[a];
        assert a > 0;
        assert newV == dp[a];
      } else {
        assert a > 0;
        assert coins[ki] <= a;
        assert coins[ki] > 0;
        var c := coins[ki];
        assert 0 <= a - c < |dp|;
        var prev := dp[a - c];
        var without := dp[a];
        if prev < inf && prev + 1 < without {
