        assert dp2[x] == Opt(coins, ki + 1, x, inf);
      }
      forall x | nexta <= x <= amount
        ensures dp2[x] == Opt(coins, ki, x, inf)
      {
        assert nexta == a + 1;
        assert dp2[x] == Opt(coins, ki, x, inf);
      }

      dp := dp2;
      a := nexta;

      forall x | 0 <= x < a
        ensures dp[x] == Opt(coins, ki + 1, x, inf)
      {
        assert a == nexta;
        assert dp == dp2;
        assert dp[x] == dp2[x];
        assert dp2[x] == Opt(coins, ki + 1, x, inf);
      }
      forall x | a <= x <= amount
        ensures dp[x] == Opt(coins, ki, x, inf)
      {
