        assert dp == dp2;
        assert dp[x] == dp2[x];
        assert dp2[x] == Opt(coins, ki, x, inf);
      }
    }

    assert a == amount + 1;
    var next := ki + 1;
    forall x | 0 <= x <= amount
      ensures dp[x] == Opt(coins, next, x, inf)
    {
      assert x < a;
      assert dp[x] == Opt(coins, ki + 1, x, inf);
      assert next == ki + 1;
    }
    ki := next;
    forall x | 0 <= x <= amount
      ensures dp[x] == Opt(coins, ki, x, inf)
    {
      assert ki == next;
      assert dp[x] == Opt(coins, next, x, inf);
    }
