    min_coins := -1;
  } else {
    assert 0 <= m < inf;
    assert m != -1;
    min_coins := m;
    assert min_coins == m;
    assert min_coins == Opt(coins, |coins|, amount, inf);
    Complete(coins, amount, inf, min_coins);
  }
