lemma GetEdge(g: Graph, u: int, v: int) returns (e: int)
  requires 0 <= u < |g.adj|
  requires has_edge(g, u, v)
  ensures 0 <= e < |g.adj[u]| && g.adj[u][e] == v
{
  e := 0;
  HasEdgeExists(g, u, v);
  var i := 0;
  while i < |g.adj[u]|
    invariant 0 <= i <= |g.adj[u]|
    invariant forall j :: 0 <= j < i ==> g.adj[u][j] != v
    decreases |g.adj[u]| - i
  {
    if g.adj[u][i] == v {
      e := i;
      return;
    }
    i := i + 1;
  }
  assert forall j :: 0 <= j < |g.adj[u]| ==> g.adj[u][j] != v;
  var j0 :| 0 <= j0 < |g.adj[u]| && g.adj[u][j0] == v;
