lemma InitState(g: Graph, start: int, dist: seq<int>, witness: seq<seq<int>>, qpos: seq<int>, queue: seq<int>)
  requires |g.adj| == |dist| == |witness| == |qpos|
  requires 0 <= start < |dist|
  requires queue == [start]
  requires forall j :: 0 <= j < |dist| ==> dist[j] == if j == start then 0 else -1
  requires forall j :: 0 <= j < |witness| ==> witness[j] == if j == start then [start] else []
  requires forall j :: 0 <= j < |qpos| ==> qpos[j] == if j == start then 0 else -1
  ensures QInv(dist, queue, qpos)
