lemma AllMinDistExtend(g: Graph, start: int, dist: seq<int>, v: int, newd: int)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires AllMinDist(g, start, dist)
  requires forall r: seq<int> {:trigger is_path(g, r)} ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= newd + 1
  ensures AllMinDist(g, start, dist[v := newd])
{
  var dist2 := dist[v := newd];
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures forall r: seq<int> {:trigger is_path(g, r)} ::
        is_path(g, r) && r[0] == start && r[|r| - 1] == u ==> |r| >= dist2[u] + 1
  {
    if u == v {
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        assert |r| >= newd + 1;
        assert dist2[u] == newd;
      }
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        MinPath(g, start, dist, u, r);
        assert dist[u] == dist2[u];
      }
    }
  }
}

lemma AllWitnessExtend(
    g: Graph, start: int, dist: seq<int>, witness: seq<seq<int>>,
    v: int, newd: int, newPath: seq<int>)
  requires AllWitness(g, start, dist, witness)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires |newPath| == newd + 1
  requires is_path(g, newPath)
  requires newPath[0] == start
  requires newPath[|newPath| - 1] == v
  ensures AllWitness(g, start, dist[v := newd], witness[v := newPath])
{
  var dist2 := dist[v := newd];
  var wit2 := witness[v := newPath];
  assert |wit2| == |witness|;
  assert |dist2| == |dist|;
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures is_path(g, wit2[u])
      && wit2[u][0] == start
      && |wit2[u]| == dist2[u] + 1
      && wit2[u][|wit2[u]| - 1] == u
  {
    if u == v {
      assert wit2[u] == newPath;
      assert dist2[u] == newd;
      assert |newPath| > 0;
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      assert wit2[u] == witness[u];
      WitnessFacts(g, start, dist, witness, u);
    }
  }
}

lemma QInvEnqueue(dist: seq<int>, queue: seq<int>, qpos: seq<int>, v: int, newd: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures QInv(dist[v := newd], queue + [v], qpos[v := |queue|])
  ensures |queue| < |dist|
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  var qpos2 := qpos[v := |queue|];
  QCount(dist, queue, qpos);
  CountNegAtLeast(dist, 0, v);
  assert CountNeg(dist, 0) >= 1;
  assert |queue| <= |dist| - 1;
  CountNegFlip(dist, 0, v, newd);
  assert CountNeg(dist2, 0) + 1 == CountNeg(dist, 0);
  assert |queue2| == |queue| + 1;
  assert |queue2| + CountNeg(dist2, 0) == |dist2|;
  assert |qpos2| == |qpos| == |dist2|;

  forall i | 0 <= i < |queue|
    ensures queue[i] != v
  {
    QIndex(dist, queue, qpos, i);
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
  }

  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2| && dist2[queue2[i]] >= 0 && qpos2[queue2[i]] == i
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert queue[i] != v;
      QIndex(dist, queue, qpos, i);
      assert dist2[queue[i]] == dist[queue[i]];
      assert qpos2[queue[i]] == qpos[queue[i]];
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == newd;
      assert qpos2[v] == |queue|;
    }
  }

  forall x | 0 <= x < |dist|
    ensures (dist2[x] >= 0 ==> 0 <= qpos2[x] < |queue2| && queue2[qpos2[x]] == x)
         && (dist2[x] < 0 ==> dist2[x] == -1 && qpos2[x] == -1)
  {
    if x == v {
      assert dist2[v] == newd >= 0;
      assert qpos2[v] == |queue|;
      assert queue2[|queue|] == v;
    } else if dist[x] >= 0 {
      QAt(dist, queue, qpos, x);
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
      var ix := qpos[x];
      assert ix < |queue|;
      assert queue2[ix] == queue[ix] == x;
    } else {
      assert dist[x] == -1;
      assert qpos[x] == -1;
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
    }
  }
}

lemma LayerEnqueue(dist: seq<int>, queue: seq<int>, head: int, layer: int, v: int, newd: int)
  requires LayerInv(dist, queue, head, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd == layer + 1
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures LayerInv(dist[v := newd], queue + [v], head, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[queue[i]] >= 0;
      assert dist[v] >= 0;
      assert false;
    }
  }
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |dist|;
    } else {
      assert queue2[i] == v;
    }
  }
  forall i | 0 <= i < head
    ensures dist2[queue2[i]] <= layer
  {
    assert i < |queue|;
    assert queue2[i] == queue[i];
    assert dist2[queue[i]] == dist[queue[i]];
    assert dist[queue[i]] <= layer;
  }
  forall i | head <= i < |queue2|
    ensures layer <= dist2[queue2[i]] && dist2[queue2[i]] <= layer + 1
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert dist2[queue[i]] == dist[queue[i]];
      assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == layer + 1;
    }
  }
  forall a, b | 0 <= a < b < |queue2|
    ensures dist2[queue2[a]] <= dist2[queue2[b]]
  {
    if b < |queue| {
      assert queue2[a] == queue[a] && queue2[b] == queue[b];
      assert dist2[queue[a]] == dist[queue[a]];
      assert dist2[queue[b]] == dist[queue[b]];
      assert dist[queue[a]] <= dist[queue[b]];
    } else {
      assert b == |queue|;
      assert queue2[b] == v;
      assert dist2[v] == layer + 1;
      assert a < |queue|;
      assert queue2[a] == queue[a];
      assert dist2[queue[a]] == dist[queue[a]];
      if a < head {
        assert dist[queue[a]] <= layer;
      } else {
        assert dist[queue[a]] <= layer + 1;
      }
    }
  }
}

lemma DistFromEnqueue(dist: seq<int>, queue: seq<int>, from: int, layer: int, v: int, newd: int)
  requires DistFrom(dist, queue, from, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= layer
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures DistFrom(dist[v := newd], queue + [v], from, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
  }
  forall i | from <= i < |queue2|
    ensures dist2[queue2[i]] >= layer
  {
    if i < |queue| {
      assert dist[queue[i]] >= layer;
      assert dist2[queue2[i]] == dist[queue[i]];
    } else {
      assert queue2[i] == v;
      assert dist2[v] == newd;
    }
  }
}

lemma ExpandedPreserve(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, v: int, newd: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures ExpandedPrefix(g, dist[v := newd], queue, upto)
{
  var dist2 := dist[v := newd];
