lemma ExpandedMerge(g: Graph, dist: seq<int>, queue: seq<int>, head: int, u: int)
  requires |dist| == |g.adj|
  requires 1 <= head <= |queue|
  requires queue[head - 1] == u
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires PrefixNbrs(g, dist, u, |g.adj[u]|)
  ensures ExpandedPrefix(g, dist, queue, head)
{
  forall i | 0 <= i < head
    ensures forall e :: 0 <= e < |g.adj[queue[i]]| ==>
        0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
  {
    if i < head - 1 {
      forall e | 0 <= e < |g.adj[queue[i]]|
        ensures 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
      {
        ExpandedAt(g, dist, queue, head - 1, i, e);
      }
    } else {
      assert i == head - 1;
      assert queue[i] == u;
      forall e | 0 <= e < |g.adj[u]|
        ensures 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0
      {
        assert 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0;
      }
    }
  }
}

