lemma ArrayUpdated(before: seq<int>, after: seq<int>, v: int, newd: int)
  requires |before| == |after|
  requires 0 <= v < |before|
  requires after[v] == newd
  requires forall j :: 0 <= j < |before| && j != v ==> after[j] == before[j]
  ensures after == before[v := newd]
{
  var upd := before[v := newd];
  forall j | 0 <= j < |before|
    ensures after[j] == upd[j]
