  var left := (s[i := v])[1..];
  var right := s[1..][i - 1 := v];
  assert |left| == |s| - 1;
  assert |right| == |s| - 1;
  forall j | 0 <= j < |left|
    ensures left[j] == right[j]
  {
    if j == i - 1 {
      assert left[j] == (s[i := v])[j + 1];
      assert j + 1 == i;
      assert (s[i := v])[j + 1] == v;
      assert right[j] == v;
    } else {
      assert j != i - 1;
      assert j + 1 != i;
      assert left[j] == (s[i := v])[j + 1];
      assert (s[i := v])[j + 1] == s[j + 1];
      assert right[j] == s[1..][j];
      assert s[1..][j] == s[j + 1];
    }
  }
  assert |left| == |right|;
  assert forall j :: 0 <= j < |left| ==> left[j] == right[j];
  assert left == right;
  assert (s[i := v])[0] == s[0];
}

