lemma lemma_concat_assoc(x: seq<int>, y: seq<int>, z: seq<int>)
    ensures (x + y) + z == x + (y + z)
{
    var l := (x + y) + z;
    var r := x + (y + z);
    assert |x + y| == |x| + |y|;
    assert |y + z| == |y| + |z|;
    assert |l| == |x| + |y| + |z|;
    assert |r| == |x| + |y| + |z|;
    forall i | 0 <= i < |l|
        ensures l[i] == r[i]
    {
        if i < |x| {
            assert i < |x + y|;
            assert (x + y)[i] == x[i];
            assert l[i] == (x + y)[i];
            assert r[i] == x[i];
        } else if i < |x| + |y| {
            assert i >= |x|;
            assert i < |x + y|;
            assert (x + y)[i] == y[i - |x|];
            assert l[i] == (x + y)[i];
            assert 0 <= i - |x| < |y|;
            assert (y + z)[i - |x|] == y[i - |x|];
            assert r[i] == (y + z)[i - |x|];
        } else {
            assert i >= |x| + |y|;
            assert i < |x| + |y| + |z|;
            assert i - |x| >= |y|;
            assert |x + y| == |x| + |y|;
            assert i >= |x + y|;
            assert 0 <= i - |x + y| < |z|;
            assert l[i] == z[i - |x + y|];
            assert i - |x + y| == i - (|x| + |y|);
            assert 0 <= i - |x| < |y + z|;
            assert (y + z)[i - |x|] == z[(i - |x|) - |y|];
            assert r[i] == (y + z)[i - |x|];
            assert i - (|x| + |y|) == (i - |x|) - |y|;
            assert l[i] == z[i - (|x| + |y|)];
            assert r[i] == z[(i - |x|) - |y|];
            assert l[i] == r[i];
        }
    }
    assert l == r;
}

