                assert q[i + 1] == a[i + 1];
                assert 0 <= i < |a| - 1;
                assert connected(g, a[i], a[i + 1]);
            } else if i == L - 1 {
                assert q[i] == a[L - 1];
                assert a[L - 1] == a[|a| - 2];
                assert q[i + 1] == b[0];
                assert b[0] == a[|a| - 1];
                assert connected(g, a[|a| - 2], a[|a| - 1]);
