lemma lemma_compress_inj(x: int, y: int, skip: int)
    requires x != skip && y != skip
    requires compress_one(x, skip) == compress_one(y, skip)
    ensures x == y
{
    if x < skip {
        if y < skip {
            assert compress_one(x, skip) == x;
            assert compress_one(y, skip) == y;
            assert x == y;
        } else {
            assert y >= skip;
            assert compress_one(x, skip) == x;
            assert compress_one(y, skip) == y - 1;
            assert x == y - 1;
            assert y == x + 1;
            assert x <= skip - 1;
            assert y <= skip;
            assert y == skip;
            assert false;
        }
    } else {
        assert x >= skip;
        if y < skip {
            assert compress_one(x, skip) == x - 1;
            assert compress_one(y, skip) == y;
            assert y == x - 1;
            assert x == y + 1;
            assert y <= skip - 1;
            assert x <= skip;
            assert x == skip;
            assert false;
        } else {
            assert y >= skip;
            assert compress_one(x, skip) == x - 1;
            assert compress_one(y, skip) == y - 1;
            assert x == y;
        }
    }
}

lemma lemma_build_mapped(prefix: seq<int>, skip: int) returns (mapped: seq<int>)
    ensures |mapped| == |prefix|
    ensures forall i :: 0 <= i < |prefix| ==> mapped[i] == compress_one(prefix[i], skip)
    decreases |prefix|
{
    if |prefix| == 0 {
        mapped := [];
    } else {
        var preSeq := prefix[..|prefix| - 1];
        var pre := lemma_build_mapped(preSeq, skip);
        var last := compress_one(prefix[|prefix| - 1], skip);
        mapped := pre + [last];
        assert |preSeq| == |prefix| - 1;
        assert |pre| == |preSeq|;
        assert |mapped| == |pre| + 1;
        assert |mapped| == |prefix|;
        forall i | 0 <= i < |prefix|
            ensures mapped[i] == compress_one(prefix[i], skip)
        {
            if i < |prefix| - 1 {
                assert 0 <= i < |preSeq|;
                assert preSeq[i] == prefix[i];
                assert pre[i] == compress_one(preSeq[i], skip);
                assert i < |pre|;
                assert mapped[i] == pre[i];
            } else {
                assert i == |prefix| - 1;
                assert mapped[i] == last;
                assert last == compress_one(prefix[i], skip);
            }
        }
    }
}

lemma lemma_pigeonhole(p: seq<int>, n: int)
    requires 0 <= n < |p|
    requires forall i :: 0 <= i < |p| ==> 0 <= p[i] < n
    ensures exists i, j :: 0 <= i < j < |p| && p[i] == p[j]
    decreases n
{
    assert |p| > 0;
    assert 0 <= p[0] < n;
    assert n >= 1;
    if exists i :: 0 <= i < |p| - 1 && p[i] == p[|p| - 1] {
        var i :| 0 <= i < |p| - 1 && p[i] == p[|p| - 1];
        var j := |p| - 1;
        assert 0 <= i < j < |p|;
        assert p[i] == p[j];
    } else {
        var prefix := p[..|p| - 1];
        var skip := p[|p| - 1];
        assert |prefix| == |p| - 1;
        assert 0 <= skip < n;
        forall i | 0 <= i < |prefix|
            ensures prefix[i] != skip
        {
            assert prefix[i] == p[i];
            if prefix[i] == skip {
                assert p[i] == p[|p| - 1];
                assert 0 <= i < |p| - 1 && p[i] == p[|p| - 1];
                assert false;
            }
        }
        assert |prefix| >= n;
        if n == 1 {
            assert |prefix| >= 1;
            assert 0 <= prefix[0] < 1;
            assert prefix[0] == 0;
            assert skip == 0;
            assert prefix[0] != skip;
            assert false;
        } else {
            assert n >= 2;
            var mapped := lemma_build_mapped(prefix, skip);
            assert |mapped| == |prefix|;
            assert forall ii :: 0 <= ii < |prefix| ==> mapped[ii] == compress_one(prefix[ii], skip);
            forall i | 0 <= i < |mapped|
                ensures 0 <= mapped[i] < n - 1
            {
                assert 0 <= i < |prefix|;
                assert mapped[i] == compress_one(prefix[i], skip);
                var x := prefix[i];
                assert 0 <= x < n && x != skip;
                assert 0 <= skip < n;
                if x < skip {
                    assert compress_one(x, skip) == x;
                    assert 0 <= x <= skip - 1;
                    assert skip - 1 <= n - 2;
                    assert 0 <= mapped[i] < n - 1;
                } else {
                    assert x > skip;
                    assert compress_one(x, skip) == x - 1;
                    assert x >= skip + 1;
                    assert 0 <= x - 1 <= n - 2;
                    assert 0 <= mapped[i] < n - 1;
                }
            }
            assert |mapped| == |prefix|;
            assert 0 <= n - 1 < |mapped|;
            lemma_pigeonhole(mapped, n - 1);
            var a, b :| 0 <= a < b < |mapped| && mapped[a] == mapped[b];
            assert 0 <= a < |prefix| && 0 <= b < |prefix|;
            assert mapped[a] == compress_one(prefix[a], skip);
            assert mapped[b] == compress_one(prefix[b], skip);
            assert prefix[a] != skip && prefix[b] != skip;
            lemma_compress_inj(prefix[a], prefix[b], skip);
            assert prefix[a] == prefix[b];
            assert p[a] == prefix[a] && p[b] == prefix[b];
            assert 0 <= a < b < |p|;
            assert p[a] == p[b];
        }
    }
}

lemma lemma_cycle_nonneg(g: seq<seq<(int, int)>>, c: seq<int>)
    requires !has_negative_cycle(g)
    requires is_path(g, c)
    requires |c| > 1
    requires c[0] == c[|c| - 1]
    ensures path_weight(g, c) >= 0
{
    if path_weight(g, c) < 0 {
        assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
        assert has_negative_cycle(g);
        assert false;
    }
}

lemma {:vcs_split_on_every_assert} lemma_cut_cycle(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>, i: int, j: int) returns (q: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    requires !has_negative_cycle(g)
    ensures is_path(g, q)
    ensures |q| > 0 && |q| < |p|
    ensures q[0] == p[0] && q[|q| - 1] == p[|p| - 1]
    ensures path_weight(g, q) <= path_weight(g, p)
    ensures 0 <= q[0] < |g|
{
    lemma_path_nodes(graph, g, p);
    var c := p[i..j + 1];
    lemma_sub_is_path(g, p, i, j + 1);
    assert is_path(g, c);
    assert |c| == j + 1 - i >= 2;
    assert c[0] == p[i] && c[|c| - 1] == p[j];
    assert c[0] == c[|c| - 1];
    lemma_cycle_nonneg(g, c);

    var a := p[..i + 1];
    var b := p[j..];
    lemma_sub_is_path(g, p, 0, i + 1);
    lemma_sub_is_path(g, p, j, |p|);
    assert is_path(g, a) && is_path(g, b);
    assert |a| == i + 1 >= 1;
    assert |b| >= 1;
    assert a[|a| - 1] == p[i] == p[j] == b[0];

    lemma_path_weight_split(g, p, j);
    var pj := p[..j + 1];
    lemma_sub_is_path(g, p, 0, j + 1);
    assert is_path(g, pj);
    lemma_path_weight_split(g, pj, i);
    lemma_prefix_of_prefix(p, i + 1, j + 1);
    assert pj[..i + 1] == a;
    lemma_slice_of_prefix(p, i, j + 1);
    assert pj[i..] == c;
    assert path_weight(g, p) == path_weight(g, pj) + path_weight(g, b);
    assert path_weight(g, pj) == path_weight(g, a) + path_weight(g, c);
    assert path_weight(g, p) == path_weight(g, a) + path_weight(g, c) + path_weight(g, b);

    q := p[..i] + p[j..];
    lemma_prefix_of_prefix(p, i, i + 1);
    assert a[..|a| - 1] == p[..i];
    assert a[..|a| - 1] + b == q;
    lemma_path_weight_concat(g, a, b);
    assert path_weight(g, q) == path_weight(g, a) + path_weight(g, b);
    assert path_weight(g, c) >= 0;
    assert path_weight(g, q) <= path_weight(g, p);

    lemma_join_paths(g, a, b);
    assert is_path(g, q);
    assert |q| == i + |p| - j;
    assert j - i >= 1;
    assert |q| < |p|;
    assert |q| >= 1;
    if i == 0 {
        assert q == b;
        assert q[0] == b[0] == p[0];
    } else {
        assert q[0] == p[0];
    }
    assert |b| >= 1;
    assert q[|q| - 1] == b[|b| - 1] == p[|p| - 1];
    assert 0 <= q[0] < |g|;
}

lemma lemma_shorten(graph: WeightedGraph, g: seq<seq<(int, int)>>, p: seq<int>) returns (q: seq<int>)
    requires well_formed(graph)
    requires g == view(graph)
    requires is_path(g, p)
    requires |p| > 0 && 0 <= p[0] < |g|
    requires !has_negative_cycle(g)
    ensures is_path(g, q)
    ensures |q| > 0 && |q| <= |g|
    ensures q[0] == p[0] && q[|q| - 1] == p[|p| - 1]
    ensures path_weight(g, q) <= path_weight(g, p)
    decreases |p|
{
    if |p| <= |g| {
        q := p;
    } else {
        lemma_path_nodes(graph, g, p);
        assert forall idx :: 0 <= idx < |p| ==> 0 <= p[idx] < |g|;
        assert 0 <= |g| < |p|;
        lemma_pigeonhole(p, |g|);
        var i, j :| 0 <= i < j < |p| && p[i] == p[j];
        var q1 := lemma_cut_cycle(graph, g, p, i, j);
        q := lemma_shorten(graph, g, q1);
        assert path_weight(g, q) <= path_weight(g, q1);
        assert path_weight(g, q1) <= path_weight(g, p);
        assert path_weight(g, q) <= path_weight(g, p);
        assert q[0] == q1[0];
        assert q1[0] == p[0];
        assert q[0] == p[0];
        assert q[|q| - 1] == q1[|q1| - 1];
        assert q1[|q1| - 1] == p[|p| - 1];
        assert q[|q| - 1] == p[|p| - 1];
    }
}

