    var i: int :|
        0 <= u < |graph.adj|
        && 0 <= i < |graph.adj[u]|
        && graph.adj[u][i].0 == v
        && graph.adj[u][i].1 == w;

    var j: int :|
        0 <= u < |graph.adj|
        && 0 <= j < |graph.adj[u]|
        && graph.adj[u][j].0 == v
        && graph.adj[u][j].1 ==
            get_edge_weight(view(graph), u, v);

    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma ExtendPath(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[|p| - 1] >= 0
    requires has_edge(view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures (p + [v])[0] == p[0]
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(view(graph), p + [v])
            == path_weight(view(graph), p) + w
{
    var u := p[|p| - 1];
    EdgeWeightIsUnique(graph, u, v, w);

    assert |p + [v]| > 0;
    forall i: int | 0 <= i < |p + [v]| - 1
        ensures connected(
            view(graph),
            (p + [v])[i],
            (p + [v])[i + 1]
        )
    {
        if i < |p| - 1 {
            assert (p + [v])[i] == p[i];
            assert (p + [v])[i + 1] == p[i + 1];
        } else {
            assert i == |p| - 1;
            assert has_edge(view(graph), u, v, w);
        }
    }

    assert (p + [v])[..|p + [v]| - 1] == p;
}

