lemma PathHasOpenFrontier(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    p: seq<int>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires p[|p| - 1] !in done
    ensures exists x: int, dx: int ::
        0 <= x < size(graph)
        && x !in done
        && ds[x] == Some(dx)
        && dx <= path_weight(view(graph), p)
{
    PathVerticesAreBounded(graph, p, start);

    var k := 0;
    while p[k] in done
        invariant 0 <= k < |p|
        invariant forall j: int :: 0 <= j < k ==> p[j] in done
        decreases |p| - k
    {
        assert k != |p| - 1;
        k := k + 1;
    }

    PrefixWeightAtMostPath(graph, p, k);

    if k == 0 {
        assert p[k] == start;
        assert path_weight(view(graph), p[..1]) == 0;
    } else {
        assert p[k - 1] in done;
        var dp: int :|
            ds[p[k - 1]] == Some(dp)
            && is_shortest_dist(
                view(graph), start, p[k - 1], dp
            );

        assert connected(view(graph), p[k - 1], p[k]);
        var w: int :|
            has_edge(view(graph), p[k - 1], p[k], w);

        var dprev: int, dx: int :|
            ds[p[k - 1]] == Some(dprev)
            && ds[p[k]] == Some(dx)
            && dx <= dprev + w;
        assert dprev == dp;

        EdgeWeightIsUnique(graph, p[k - 1], p[k], w);
        PathPrefix(view(graph), p, k - 1);

        assert (p[..k])[0] == start;
        assert (p[..k])[|p[..k]| - 1] == p[k - 1];
        assert path_weight(view(graph), p[..k]) >= dp;

        assert p[..k + 1][..|p[..k + 1]| - 1] == p[..k];
        assert path_weight(view(graph), p[..k + 1])
            == path_weight(view(graph), p[..k]) + w;
        assert dx <= path_weight(view(graph), p[..k + 1]);
    }
}

lemma MinimumOpenDistanceIsShortest(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    u: int,
    du: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires DistWitness(graph, start, ds)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires 0 <= u < size(graph)
    requires u !in done
    requires ds[u] == Some(du)
    requires forall v: int, d: int ::
        0 <= v < size(graph)
        && v !in done
        && ds[v] == Some(d)
        ==> du <= d
    ensures is_shortest_dist(view(graph), start, u, du)
{
    var witness: seq<int> :|
        is_path(view(graph), witness)
        && witness[0] == start
        && witness[|witness| - 1] == u
        && path_weight(view(graph), witness) == du;

    forall p: seq<int> |
        is_path(view(graph), p)
        && p[0] == start
        && p[|p| - 1] == u
        ensures path_weight(view(graph), p) >= du
    {
        PathHasOpenFrontier(
            graph, start, ds, done, p
        );
        var x: int, dx: int :|
            0 <= x < size(graph)
            && x !in done
            && ds[x] == Some(dx)
            && dx <= path_weight(view(graph), p);
        assert du <= dx;
    }
}

