            == path_weight(view(graph), p) + w
{
    var u := p[|p| - 1];
    EdgeWeightIsUnique(graph, u, v, w);

    assert |p + [v]| > 0;
    forall i: int | 0 <= i < |p + [v]| - 1
        ensures connected(
            view(graph),
            (p + [v])[i],
            (p + [v])[i + 1]
        )
    {
        if i < |p| - 1 {
            assert (p + [v])[i] == p[i];
            assert (p + [v])[i + 1] == p[i + 1];
        } else {
            assert i == |p| - 1;
            assert has_edge(view(graph), u, v, w);
        }
    }

    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma PathWeightNonnegative(
    graph: WeightedGraph,
    p: seq<int>
)
    requires is_path(view(graph), p)
    requires weights_non_negative(view(graph))
    ensures path_weight(view(graph), p) >= 0
    decreases |p|
{
    if |p| >= 2 {
        var q := p[..|p| - 1];
        PathPrefix(view(graph), p, |p| - 2);
        PathWeightNonnegative(graph, q);

        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert connected(view(graph), u, v);
        ChosenEdge(view(graph), u, v);
        assert get_edge_weight(view(graph), u, v) >= 0;
    }
}

lemma PrefixWeightAtMostPath(
    graph: WeightedGraph,
    p: seq<int>,
    k: int
)
    requires is_path(view(graph), p)
    requires weights_non_negative(view(graph))
    requires 0 <= k < |p|
    ensures path_weight(view(graph), p[..k + 1])
            <= path_weight(view(graph), p)
    decreases |p| - k
{
    if k == |p| - 1 {
        assert p[..k + 1] == p;
    } else {
        var q := p[..|p| - 1];
        PathPrefix(view(graph), p, |p| - 2);
        PrefixWeightAtMostPath(graph, q, k);

        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert connected(view(graph), u, v);
        ChosenEdge(view(graph), u, v);
        assert get_edge_weight(view(graph), u, v) >= 0;
        assert q[..k + 1] == p[..k + 1];
    }
}

lemma PathVerticesAreBounded(
    graph: WeightedGraph,
    p: seq<int>,
    start: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires 0 <= start < size(graph)
    ensures forall k: int :: 0 <= k < |p| ==>
        0 <= p[k] < size(graph)
{
    forall k: int | 0 <= k < |p|
        ensures 0 <= p[k] < size(graph)
    {
        var j := 0;
        while j < k
            invariant 0 <= j <= k
            invariant 0 <= p[j] < size(graph)
            decreases k - j
        {
            assert j < |p| - 1;
            assert connected(view(graph), p[j], p[j + 1]);
            var w: int :| has_edge(view(graph), p[j], p[j + 1], w);
            var ei: int :|
                0 <= p[j] < |graph.adj|
                && 0 <= ei < |graph.adj[p[j]]|
                && graph.adj[p[j]][ei].0 == p[j + 1]
                && graph.adj[p[j]][ei].1 == w;
            assert 0 <= graph.adj[p[j]][ei].0 < |graph.adj|;
            j := j + 1;
        }
    }
}

lemma DistWitnessUpdate(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    v: int,
    d: int,
    p: seq<int>
)
    requires DistWitness(graph, start, ds)
    requires 0 <= v < size(graph)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires p[|p| - 1] == v
    requires path_weight(view(graph), p) == d
    ensures DistWitness(graph, start, ds[v := Some(d)])
{
    forall x: int, dx: int |
        0 <= x < size(graph)
        && ds[v := Some(d)][x] == Some(dx)
        ensures exists q: seq<int> {:trigger is_path(view(graph), q)} ::
            is_path(view(graph), q)
            && q[0] == start
            && q[|q| - 1] == x
            && path_weight(view(graph), q) == dx
    {
        if x == v {
            assert dx == d;
        } else {
            assert ds[x] == Some(dx);
        }
    }
}

lemma LowerUpdatePreservesClosed(
    graph: WeightedGraph,
    ds: seq<Option<int>>,
    done: set<int>,
    v: int,
    d: int
)
    requires |ds| == size(graph)
    requires 0 <= v < size(graph)
    requires v !in done
    requires ClosedEdges(graph, ds, done)
    requires ds[v] == None
        || exists previous: int ::
            ds[v] == Some(previous) && d <= previous
    ensures ClosedEdges(graph, ds[v := Some(d)], done)
{
    forall a: int, b: int, w: int |
        a in done && has_edge(view(graph), a, b, w)
        ensures exists da: int, db: int ::
            ds[v := Some(d)][a] == Some(da)
            && ds[v := Some(d)][b] == Some(db)
            && db <= da + w
    {
        var da: int, db: int :|
            ds[a] == Some(da)
            && ds[b] == Some(db)
            && db <= da + w;

        if b == v {
            assert ds[v] != None;
            var previous: int :|
                ds[v] == Some(previous) && d <= previous;
            assert db == previous;
        }
        assert a != v;
    }
}

lemma LowerUpdatePreservesProcessed(
    graph: WeightedGraph,
    ds: seq<Option<int>>,
    u: int,
    du: int,
    count: int,
    v: int,
    d: int
)
    requires 0 <= u < size(graph)
    requires 0 <= count <= |graph.adj[u]|
    requires 0 <= v < |ds|
    requires ProcessedEdges(graph, ds, u, du, count)
    requires ds[v] == None
        || exists previous: int ::
            ds[v] == Some(previous) && d <= previous
    ensures ProcessedEdges(
        graph, ds[v := Some(d)], u, du, count
    )
{
    forall i: int | 0 <= i < count
        ensures exists dv: int ::
            ds[v := Some(d)][graph.adj[u][i].0] == Some(dv)
            && dv <= du + graph.adj[u][i].1
    {
        var oldValue: int :|
            ds[graph.adj[u][i].0] == Some(oldValue)
            && oldValue <= du + graph.adj[u][i].1;

        if graph.adj[u][i].0 == v {
            assert ds[v] != None;
            var previous: int :|
                ds[v] == Some(previous) && d <= previous;
            assert previous == oldValue;
        }
    }
}

