                0 <= u < |graph.adj|
                && 0 <= i < |graph.adj[u]|
                && graph.adj[u][i].0 == b
                && graph.adj[u][i].1 == w;
            var db: int :|
                ds[graph.adj[u][i].0] == Some(db)
                && db <= du + graph.adj[u][i].1;
