lemma PathHasOpenFrontier(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    p: seq<int>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires p[|p| - 1] !in done
    ensures exists x: int, dx: int ::
        0 <= x < size(graph)
        && x !in done
        && ds[x] == Some(dx)
        && dx <= path_weight(view(graph), p)
{
    PathVerticesAreBounded(graph, p, start);

    var k := 0;
    while p[k] in done
        invariant 0 <= k < |p|
        invariant forall j: int :: 0 <= j < k ==> p[j] in done
        decreases |p| - k
    {
        assert k != |p| - 1;
        k := k + 1;
    }

    PrefixWeightAtMostPath(graph, p, k);

    if k == 0 {
        assert p[k] == start;
        assert path_weight(view(graph), p[..1]) == 0;
    } else {
        assert p[k - 1] in done;
        var dp: int :|
            ds[p[k - 1]] == Some(dp)
            && is_shortest_dist(
                view(graph), start, p[k - 1], dp
            );

        assert connected(view(graph), p[k - 1], p[k]);
        var w: int :|
            has_edge(view(graph), p[k - 1], p[k], w);

        var dprev: int, dx: int :|
            ds[p[k - 1]] == Some(dprev)
            && ds[p[k]] == Some(dx)
            && dx <= dprev + w;
        assert dprev == dp;

        EdgeWeightIsUnique(graph, p[k - 1], p[k], w);
        PathPrefix(view(graph), p, k - 1);

        assert (p[..k])[0] == start;
        assert (p[..k])[|p[..k]| - 1] == p[k - 1];
        assert path_weight(view(graph), p[..k]) >= dp;

        assert p[..k + 1][..|p[..k + 1]| - 1] == p[..k];
        assert path_weight(view(graph), p[..k + 1])
            == path_weight(view(graph), p[..k]) + w;
        assert dx <= path_weight(view(graph), p[..k + 1]);
    }
}

lemma MinimumOpenDistanceIsShortest(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    u: int,
    du: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires DistWitness(graph, start, ds)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires 0 <= u < size(graph)
    requires u !in done
    requires ds[u] == Some(du)
    requires forall v: int, d: int ::
        0 <= v < size(graph)
        && v !in done
        && ds[v] == Some(d)
        ==> du <= d
    ensures is_shortest_dist(view(graph), start, u, du)
{
    var witnessPath: seq<int> :|
        is_path(view(graph), witnessPath)
        && witnessPath[0] == start
        && witnessPath[|witnessPath| - 1] == u
        && path_weight(view(graph), witnessPath) == du;

    forall p: seq<int> |
        is_path(view(graph), p)
        && p[0] == start
        && p[|p| - 1] == u
        ensures path_weight(view(graph), p) >= du
    {
        PathHasOpenFrontier(
            graph, start, ds, done, p
        );
        var x: int, dx: int :|
            0 <= x < size(graph)
            && x !in done
            && ds[x] == Some(dx)
            && dx <= path_weight(view(graph), p);
        assert du <= dx;
    }
}

method dijkstra_shortest_paths(
    graph: WeightedGraph,
    start: int
) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        match res[v] {
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
        }
{
    var n := size(graph);
    var dist := seq(n, i =>
        if i == start then Some(0) else None);
    var done: set<int> := {};
    var stopped := false;
    ghost var vertices: set<int> :=
        set i: int | 0 <= i < n;

    assert is_path(view(graph), [start]);
    assert path_weight(view(graph), [start]) == 0;
    assert DistWitness(graph, start, dist);
    assert DistancesNonnegative(dist);
    assert Settled(graph, start, dist, done);
    assert ClosedEdges(graph, dist, done);
    assert dist[start] == Some(0);

    while !stopped
        invariant |dist| == n
        invariant done <= vertices
        invariant dist[start] == Some(0)
        invariant DistWitness(graph, start, dist)
        invariant DistancesNonnegative(dist)
        invariant Settled(graph, start, dist, done)
        invariant ClosedEdges(graph, dist, done)
        invariant stopped ==> NoOpenDistance(graph, dist, done)
        decreases if stopped then 0 else |vertices - done| + 1
    {
        var found := false;
        var u := 0;
        var du := 0;
        var scan := 0;

        while scan < n
            invariant 0 <= scan <= n
            invariant found ==>
                0 <= u < n
                && u !in done
                && dist[u] == Some(du)
            invariant forall v: int, d: int ::
                0 <= v < scan
                && v !in done
                && dist[v] == Some(d)
                ==> found && du <= d
            decreases n - scan
        {
            match dist[scan]
            case Some(d) =>
                if scan !in done {
                    if !found || d < du {
                        found := true;
                        u := scan;
                        du := d;
                    }
                }
            case None =>
            scan := scan + 1;
        }

        if !found {
            assert NoOpenDistance(graph, dist, done);
            stopped := true;
        } else {
            assert forall v: int, d: int ::
                0 <= v < n
                && v !in done
                && dist[v] == Some(d)
                ==> du <= d;

            MinimumOpenDistanceIsShortest(
                graph, start, dist, done, u, du
            );
            assert is_shortest_dist(
                view(graph), start, u, du
            );

            var witnessPath: seq<int> :|
                is_path(view(graph), witnessPath)
                && witnessPath[0] == start
                && witnessPath[|witnessPath| - 1] == u
                && path_weight(view(graph), witnessPath) == du;

            var edgeIndex := 0;
            assert ProcessedEdges(
                graph, dist, u, du, edgeIndex
            );

            while edgeIndex < |graph.adj[u]|
                invariant 0 <= edgeIndex <= |graph.adj[u]|
                invariant |dist| == n
                invariant dist[start] == Some(0)
                invariant dist[u] == Some(du)
                invariant DistWitness(graph, start, dist)
                invariant DistancesNonnegative(dist)
                invariant Settled(graph, start, dist, done)
                invariant ClosedEdges(graph, dist, done)
                invariant ProcessedEdges(
                    graph, dist, u, du, edgeIndex
                )
                decreases |graph.adj[u]| - edgeIndex
            {
                var v := graph.adj[u][edgeIndex].0;
                var w := graph.adj[u][edgeIndex].1;
                assert has_edge(view(graph), u, v, w);
                assert 0 <= v < n;
                assert w >= 0;
                assert du >= 0;

                var candidate := du + w;

                if v in done {
                    var dv: int :|
                        dist[v] == Some(dv)
                        && is_shortest_dist(
                            view(graph), start, v, dv
                        );

                    ExtendPath(graph, witnessPath, v, w);
                    var extended := witnessPath + [v];
                    assert is_path(view(graph), extended);
                    assert extended[0] == start;
                    assert extended[|extended| - 1] == v;
                    assert path_weight(view(graph), extended)
                        == candidate;
                    assert dv <= candidate;
                } else {
                    match dist[v]
                    case None =>
                        ExtendPath(graph, witnessPath, v, w);
                        var extended := witnessPath + [v];

                        DistWitnessUpdate(
                            graph, start, dist,
                            v, candidate, extended
                        );
                        LowerUpdatePreservesClosed(
                            graph, dist, done, v, candidate
                        );
                        LowerUpdatePreservesProcessed(
                            graph, dist, u, du,
                            edgeIndex, v, candidate
                        );

                        if v == start {
                            assert dist[start] == Some(0);
                            assert false;
                        }

                        dist := dist[v := Some(candidate)];

                    case Some(oldDistance) =>
                        if candidate < oldDistance {
                            ExtendPath(graph, witnessPath, v, w);
                            var extended := witnessPath + [v];

                            DistWitnessUpdate(
                                graph, start, dist,
                                v, candidate, extended
                            );
                            LowerUpdatePreservesClosed(
                                graph, dist, done, v, candidate
                            );
                            LowerUpdatePreservesProcessed(
                                graph, dist, u, du,
                                edgeIndex, v, candidate
                            );

                            if v == start {
                                assert oldDistance == 0;
                                assert candidate >= 0;
                                assert false;
                            }
                            if v == u {
                                assert oldDistance == du;
                                assert candidate >= du;
                                assert false;
                            }

                            dist := dist[v := Some(candidate)];
                        } else {
                            assert oldDistance <= candidate;
                        }
                }

                assert exists dv: int ::
                    dist[v] == Some(dv) && dv <= candidate;
                edgeIndex := edgeIndex + 1;
            }

            AddClosedVertex(
                graph, dist, done, u, du
            );
            AddSettledVertex(
                graph, start, dist, done, u, du
            );

            done := done + {u};
            assert u in vertices;
        }
    }

    assert NoOpenDistance(graph, dist, done);
    res := dist;

    forall v: int | 0 <= v < size(graph)
        ensures
            match res[v] {
                case Some(d) =>
                    is_shortest_dist(
                        view(graph), start, v, d
                    )
                case None =>
                    forall p: seq<int>
                        {:trigger is_path(view(graph), p)} ::
                        is_path(view(graph), p)
                        && p[0] == start
                        && p[|p| - 1] == v
                        ==> false
            }
    {
        match res[v]
        case Some(d) =>
            if v !in done {
                assert false;
            }
        case None =>
            assert v !in done;
            forall p: seq<int> |
                is_path(view(graph), p)
                && p[0] == start
                && p[|p| - 1] == v
                ensures false
            {
                PathHasOpenFrontier(
                    graph, start, res, done, p
                );
                var x: int, dx: int :|
                    0 <= x < size(graph)
                    && x !in done
                    && res[x] == Some(dx)
                    && dx <= path_weight(view(graph), p);
                assert false;
            }
    }
}
