lemma CardRemove(s: set<int>, x: int)
  requires x in s
  ensures |s - {x}| < |s|
{
  var t := s - {x};
  assert x !in t;
  assert t * {x} == {};
  assert s == t + {x};
}

lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures has_edge(graph.adj, u, graph.adj[u][i].0, graph.adj[u][i].1)
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var w: int := g[u][i].1;
  assert 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
  assert has_edge(g, u, v, w);
  forall w': int | has_edge(g, u, v, w') ensures w' == w {
    var j: int :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
}

lemma ExtendPath(graph: WeightedGraph, p: seq<int>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires is_path(graph.adj, p) && p[|p| - 1] == u
  ensures is_path(graph.adj, p + [graph.adj[u][i].0])
  ensures (p + [graph.adj[u][i].0])[0] == p[0]
  ensures (p + [graph.adj[u][i].0])[|p|] == graph.adj[u][i].0
  ensures path_weight(graph.adj, p + [graph.adj[u][i].0]) == path_weight(graph.adj, p) + graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var q: seq<int> := p + [v];
  EdgeWeight(graph, u, i);
  assert connected(g, u, v);
  forall k: int | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
    if k < |p| - 1 {
      assert connected(g, p[k], p[k+1]);
      assert q[k] == p[k] && q[k+1] == p[k+1];
    } else {
      assert q[k] == u && q[k+1] == v;
    }
  }
  assert q[..|q| - 1] == p;
  assert q[|q| - 2] == u && q[|q| - 1] == v;
}

lemma PathLowerBound(graph: WeightedGraph, start: int, dist: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires |dist| == |graph.adj|
  requires 0 <= start < |graph.adj|
  requires dist[start] == Some(0)
