lemma PathPrefix(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    k: int
)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures is_path(g, p[..k + 1])
{
    assert |p[..k + 1]| > 0;
    forall i: int | 0 <= i < |p[..k + 1]| - 1
        ensures connected(g, p[..k + 1][i], p[..k + 1][i + 1])
    {
        assert p[..k + 1][i] == p[i];
        assert p[..k + 1][i + 1] == p[i + 1];
    }
}

