lemma PathPrefix(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    k: int
)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures is_path(g, p[..k + 1])
{
    assert |p[..k + 1]| > 0;
    forall i: int | 0 <= i < |p[..k + 1]| - 1
        ensures connected(
            g,
            p[..k + 1][i],
            p[..k + 1][i + 1]
        )
    {
        assert p[..k + 1][i] == p[i];
        assert p[..k + 1][i + 1] == p[i + 1];
    }
}

lemma ChosenEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int
)
    requires connected(g, u, v)
    ensures has_edge(g, u, v, get_edge_weight(g, u, v))
{
    assert exists w: int :: has_edge(g, u, v, w);
}

lemma EdgeWeightIsUnique(
    graph: WeightedGraph,
    u: int,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w)
    ensures get_edge_weight(view(graph), u, v) == w
{
    ChosenEdge(view(graph), u, v);

    var i: int :|
        0 <= u < |graph.adj|
        && 0 <= i < |graph.adj[u]|
        && graph.adj[u][i].0 == v
        && graph.adj[u][i].1 == w;

    var j: int :|
        0 <= u < |graph.adj|
        && 0 <= j < |graph.adj[u]|
        && graph.adj[u][j].0 == v
        && graph.adj[u][j].1
            == get_edge_weight(view(graph), u, v);

    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma ExtendPath(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[|p| - 1] >= 0
    requires has_edge(view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures (p + [v])[0] == p[0]
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(view(graph), p + [v])
        == path_weight(view(graph), p) + w
{
    var u := p[|p| - 1];
    EdgeWeightIsUnique(graph, u, v, w);

    assert |p + [v]| > 0;
    forall i: int | 0 <= i < |p + [v]| - 1
        ensures connected(
            view(graph),
            (p + [v])[i],
            (p + [v])[i + 1]
        )
    {
        if i < |p| - 1 {
            assert (p + [v])[i] == p[i];
            assert (p + [v])[i + 1] == p[i + 1];
        } else {
            assert i == |p| - 1;
            assert (p + [v])[i] == u;
            assert (p + [v])[i + 1] == v;
            assert connected(view(graph), u, v);
        }
    }

    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma PrefixWeightAtMostPath(
    graph: WeightedGraph,
    p: seq<int>,
    k: int
)
    requires is_path(view(graph), p)
    requires weights_non_negative(view(graph))
    requires 0 <= k < |p|
    ensures path_weight(view(graph), p[..k + 1])
        <= path_weight(view(graph), p)
    decreases |p| - k
{
    if k == |p| - 1 {
        assert p[..k + 1] == p;
    } else {
        var q := p[..|p| - 1];
        PathPrefix(view(graph), p, |p| - 2);
        PrefixWeightAtMostPath(graph, q, k);

        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert connected(view(graph), u, v);
        ChosenEdge(view(graph), u, v);
        assert get_edge_weight(view(graph), u, v) >= 0;
        assert q[..k + 1] == p[..k + 1];
    }
}

lemma PathVerticesAreBounded(
    graph: WeightedGraph,
    p: seq<int>,
    start: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires 0 <= start < size(graph)
    ensures forall k: int :: 0 <= k < |p| ==>
        0 <= p[k] < size(graph)
{
    forall k: int | 0 <= k < |p|
        ensures 0 <= p[k] < size(graph)
    {
        var j := 0;
        while j < k
            invariant 0 <= j <= k
            invariant k < |p|
            invariant 0 <= p[j] < size(graph)
            decreases k - j
        {
            assert j < |p| - 1;
            assert connected(view(graph), p[j], p[j + 1]);

            var w: int :|
                has_edge(view(graph), p[j], p[j + 1], w);
            var ei: int :|
                0 <= p[j] < |graph.adj|
                && 0 <= ei < |graph.adj[p[j]]|
                && graph.adj[p[j]][ei].0 == p[j + 1]
                && graph.adj[p[j]][ei].1 == w;

            assert 0 <= graph.adj[p[j]][ei].0 < |graph.adj|;
            j := j + 1;
        }
    }
}

lemma DistWitnessUpdate(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    v: int,
    d: int,
    p: seq<int>
)
    requires DistWitness(graph, start, ds)
    requires 0 <= v < size(graph)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires p[|p| - 1] == v
    requires path_weight(view(graph), p) == d
    ensures DistWitness(graph, start, ds[v := Some(d)])
{
    assert |ds[v := Some(d)]| == size(graph);

    forall x: int, dx: int |
        0 <= x < size(graph)
        && ds[v := Some(d)][x] == Some(dx)
        ensures exists q: seq<int>
            {:trigger is_path(view(graph), q)} ::
            is_path(view(graph), q)
            && q[0] == start
            && q[|q| - 1] == x
            && path_weight(view(graph), q) == dx
    {
        if x == v {
            assert ds[v := Some(d)][x] == Some(d);
            assert dx == d;
        } else {
            assert ds[v := Some(d)][x] == ds[x];
            assert ds[x] == Some(dx);
        }
    }
}

lemma NonnegativeUpdate(
    ds: seq<Option<int>>,
    v: int,
    d: int
)
    requires DistancesNonnegative(ds)
    requires 0 <= v < |ds|
    requires 0 <= d
    ensures DistancesNonnegative(ds[v := Some(d)])
{
    forall x: int, dx: int |
        0 <= x < |ds[v := Some(d)]|
        && ds[v := Some(d)][x] == Some(dx)
        ensures 0 <= dx
    {
        if x == v {
            assert dx == d;
        } else {
            assert ds[v := Some(d)][x] == ds[x];
            assert ds[x] == Some(dx);
        }
    }
}

lemma UpdatePreservesSettled(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    v: int,
    d: int
)
    requires Settled(graph, start, ds, done)
    requires 0 <= v < |ds|
    requires v !in done
    ensures Settled(
        graph, start, ds[v := Some(d)], done
    )
{
    assert |ds[v := Some(d)]| == size(graph);

    forall x: int | x in done
        ensures 0 <= x < |ds[v := Some(d)]|
        &&
        exists dx: int ::
            ds[v := Some(d)][x] == Some(dx)
            && is_shortest_dist(
                view(graph), start, x, dx
            )
    {
        assert x != v;
        var dx: int :|
            ds[x] == Some(dx)
            && is_shortest_dist(
                view(graph), start, x, dx
            );
        assert ds[v := Some(d)][x] == ds[x];
    }
}

lemma LowerUpdatePreservesClosed(
    graph: WeightedGraph,
    ds: seq<Option<int>>,
    done: set<int>,
    v: int,
    d: int
)
    requires ClosedEdges(graph, ds, done)
    requires 0 <= v < |ds|
    requires v !in done
    requires ds[v] == None
        || exists previous: int ::
            ds[v] == Some(previous) && d <= previous
    ensures ClosedEdges(
        graph, ds[v := Some(d)], done
    )
{
    assert |ds[v := Some(d)]| == size(graph);
    assert well_formed(graph);

    forall a: int, b: int, w: int |
        a in done && has_edge(view(graph), a, b, w)
        ensures 0 <= a < |ds[v := Some(d)]|
        && 0 <= b < |ds[v := Some(d)]|
        &&
        exists da: int, db: int ::
            ds[v := Some(d)][a] == Some(da)
            && ds[v := Some(d)][b] == Some(db)
            && db <= da + w
    {
        assert 0 <= a < |ds|;
        assert 0 <= b < |ds|;

        var da: int, db: int :|
            ds[a] == Some(da)
            && ds[b] == Some(db)
            && db <= da + w;

        assert a != v;

        if b == v {
            assert ds[v] == Some(db);
            assert ds[v] != None;
            var previous: int :|
                ds[v] == Some(previous) && d <= previous;
            assert previous == db;
            assert d <= da + w;
            assert ds[v := Some(d)][a] == Some(da);
            assert ds[v := Some(d)][b] == Some(d);
        } else {
            assert ds[v := Some(d)][a] == Some(da);
            assert ds[v := Some(d)][b] == Some(db);
        }
    }
}

lemma LowerUpdatePreservesProcessed(
    graph: WeightedGraph,
    ds: seq<Option<int>>,
    u: int,
    du: int,
    count: int,
    v: int,
    d: int
)
    requires ProcessedEdges(
        graph, ds, u, du, count
    )
    requires 0 <= v < |ds|
    requires ds[v] == None
        || exists previous: int ::
            ds[v] == Some(previous) && d <= previous
    ensures ProcessedEdges(
        graph, ds[v := Some(d)], u, du, count
    )
{
    assert |ds[v := Some(d)]| == size(graph);
    assert well_formed(graph);
    assert 0 <= u < size(graph);
    assert 0 <= count <= |graph.adj[u]|;

    forall i: int | 0 <= i < count
        ensures
            0 <= graph.adj[u][i].0
                < |ds[v := Some(d)]|
            &&
            exists dv: int ::
                ds[v := Some(d)][graph.adj[u][i].0]
                    == Some(dv)
                && dv <= du + graph.adj[u][i].1
    {
        var x := graph.adj[u][i].0;
        assert 0 <= x < |ds|;

        var oldValue: int :|
            ds[x] == Some(oldValue)
            && oldValue <= du + graph.adj[u][i].1;

        if x == v {
            assert ds[v] == Some(oldValue);
            assert ds[v] != None;
            var previous: int :|
                ds[v] == Some(previous) && d <= previous;
            assert previous == oldValue;
            assert d <= du + graph.adj[u][i].1;
            assert ds[v := Some(d)][x] == Some(d);
        } else {
            assert ds[v := Some(d)][x] == Some(oldValue);
        }
    }
}

lemma AddSettledVertex(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    u: int,
    du: int
)
    requires Settled(graph, start, ds, done)
    requires u !in done
    requires 0 <= u < size(graph)
    requires ds[u] == Some(du)
    requires is_shortest_dist(
        view(graph), start, u, du
    )
    ensures Settled(
        graph, start, ds, done + {u}
    )
{
    assert |ds| == size(graph);

    forall v: int | v in done + {u}
        ensures 0 <= v < |ds|
        &&
        exists d: int ::
            ds[v] == Some(d)
            && is_shortest_dist(
                view(graph), start, v, d
            )
    {
        if v == u {
        } else {
            assert v in done;
        }
    }
}

lemma AddClosedVertex(
    graph: WeightedGraph,
    ds: seq<Option<int>>,
    done: set<int>,
    u: int,
    du: int
)
    requires ClosedEdges(graph, ds, done)
    requires 0 <= u < size(graph)
    requires ds[u] == Some(du)
    requires ProcessedEdges(
        graph, ds, u, du, |graph.adj[u]|
    )
    ensures ClosedEdges(
        graph, ds, done + {u}
    )
{
    assert |ds| == size(graph);
    assert well_formed(graph);

    forall a: int, b: int, w: int |
        a in done + {u}
        && has_edge(view(graph), a, b, w)
        ensures 0 <= a < |ds|
        && 0 <= b < |ds|
        &&
        exists da: int, db: int ::
            ds[a] == Some(da)
            && ds[b] == Some(db)
            && db <= da + w
    {
        if a == u {
            var i: int :|
                0 <= u < |graph.adj|
                && 0 <= i < |graph.adj[u]|
                && graph.adj[u][i].0 == b
                && graph.adj[u][i].1 == w;

            assert 0 <= graph.adj[u][i].0 < |ds|;

            var db: int :|
                ds[graph.adj[u][i].0] == Some(db)
                && db <= du + graph.adj[u][i].1;

            assert ds[a] == Some(du);
            assert ds[b] == Some(db);
            assert db <= du + w;
        } else {
            assert a in done;
        }
    }
}

lemma PathHasOpenFrontier(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    p: seq<int>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires p[|p| - 1] !in done
    ensures exists x: int, dx: int ::
        0 <= x < size(graph)
        && x !in done
        && ds[x] == Some(dx)
        && dx <= path_weight(view(graph), p)
{
    PathVerticesAreBounded(graph, p, start);

    var k := 0;
    while p[k] in done
        invariant 0 <= k < |p|
        invariant forall j: int ::
            0 <= j < k ==> p[j] in done
        decreases |p| - k
    {
        assert k != |p| - 1;
        k := k + 1;
    }

    assert 0 <= p[k] < size(graph);
    assert p[k] !in done;
    PrefixWeightAtMostPath(graph, p, k);

    if k == 0 {
        assert p[k] == start;
        assert p[..1] == [start];
        assert path_weight(view(graph), p[..1]) == 0;
        assert 0 <= path_weight(view(graph), p);
    } else {
        assert p[k - 1] in done;

        var dp: int :|
            ds[p[k - 1]] == Some(dp)
            && is_shortest_dist(
                view(graph), start, p[k - 1], dp
            );

        assert connected(view(graph), p[k - 1], p[k]);
        var w: int :|
            has_edge(
                view(graph), p[k - 1], p[k], w
            );

        var dprev: int, dx: int :|
            ds[p[k - 1]] == Some(dprev)
            && ds[p[k]] == Some(dx)
            && dx <= dprev + w;

        assert dprev == dp;
        EdgeWeightIsUnique(
            graph, p[k - 1], p[k], w
        );
        PathPrefix(view(graph), p, k - 1);

        assert (p[..k])[0] == start;
        assert (p[..k])[|p[..k]| - 1] == p[k - 1];
        assert path_weight(view(graph), p[..k]) >= dp;

        assert p[..k + 1][..|p[..k + 1]| - 1]
            == p[..k];
        assert path_weight(view(graph), p[..k + 1])
            == path_weight(view(graph), p[..k]) + w;
        assert dx <= path_weight(
            view(graph), p[..k + 1]
        );
        assert dx <= path_weight(view(graph), p);
    }
}

lemma MinimumOpenDistanceIsShortest(
    graph: WeightedGraph,
    start: int,
    ds: seq<Option<int>>,
    done: set<int>,
    u: int,
    du: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |ds| == size(graph)
    requires ds[start] == Some(0)
    requires DistWitness(graph, start, ds)
    requires Settled(graph, start, ds, done)
    requires ClosedEdges(graph, ds, done)
    requires 0 <= u < size(graph)
    requires u !in done
    requires ds[u] == Some(du)
    requires forall v: int, d: int ::
        0 <= v < size(graph)
        && v !in done
        && ds[v] == Some(d)
        ==> du <= d
    ensures is_shortest_dist(
        view(graph), start, u, du
    )
{
    var witnessPath: seq<int> :|
        is_path(view(graph), witnessPath)
        && witnessPath[0] == start
        && witnessPath[|witnessPath| - 1] == u
        && path_weight(view(graph), witnessPath) == du;

    forall p: seq<int> |
        is_path(view(graph), p)
        && p[0] == start
        && p[|p| - 1] == u
        ensures path_weight(view(graph), p) >= du
    {
        PathHasOpenFrontier(
            graph, start, ds, done, p
        );

        var x: int, dx: int :|
            0 <= x < size(graph)
            && x !in done
            && ds[x] == Some(dx)
            && dx <= path_weight(view(graph), p);

        assert du <= dx;
    }
}

method {:isolate_assertions} dijkstra_shortest_paths(
    graph: WeightedGraph,
    start: int
) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        match res[v] {
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
        }
{
    var n := |graph.adj|;
    var dist := seq(n, i =>
        if i == start then Some(0) else None);
    var done: set<int> := {};
    var stopped := false;

    ghost var vertices: set<int> :=
        set i: int | 0 <= i < n;

    assert n == size(graph);
    assert |dist| == n;
    assert dist[start] == Some(0);
    assert is_path(view(graph), [start]);
    assert path_weight(view(graph), [start]) == 0;

    forall v: int, d: int |
        0 <= v < size(graph)
        && dist[v] == Some(d)
        ensures exists p: seq<int>
            {:trigger is_path(view(graph), p)} ::
            is_path(view(graph), p)
            && p[0] == start
            && p[|p| - 1] == v
            && path_weight(view(graph), p) == d
    {
        if v == start {
            assert d == 0;
        } else {
            assert dist[v] == None;
            assert false;
        }
    }

    assert DistWitness(graph, start, dist);
    assert DistancesNonnegative(dist);
    assert Settled(graph, start, dist, done);
    assert ClosedEdges(graph, dist, done);

    while !stopped
        invariant n == size(graph)
        invariant |dist| == n
        invariant done <= vertices
        invariant dist[start] == Some(0)
        invariant DistWitness(graph, start, dist)
        invariant DistancesNonnegative(dist)
        invariant Settled(graph, start, dist, done)
        invariant ClosedEdges(graph, dist, done)
        invariant stopped ==>
            NoOpenDistance(graph, dist, done)
        decreases
            if stopped then 0
            else |vertices - done| + 1
    {
        var found := false;
        var u := 0;
        var du := 0;
        var scan := 0;

        while scan < n
            invariant 0 <= scan <= n
            invariant found ==>
                0 <= u < n
                && u !in done
                && dist[u] == Some(du)
            invariant forall v: int, d: int ::
                0 <= v < scan
                && v !in done
                && dist[v] == Some(d)
                ==> found && du <= d
            decreases n - scan
        {
            match dist[scan]
            case Some(d) =>
                if scan !in done {
                    if !found || d < du {
                        found := true;
                        u := scan;
                        du := d;
                    }
                }
            case None =>

            scan := scan + 1;
        }

        if !found {
            assert NoOpenDistance(graph, dist, done);
            stopped := true;
        } else {
            assert 0 <= u < n;
            assert u !in done;
            assert dist[u] == Some(du);

            assert forall v: int, d: int ::
                0 <= v < n
                && v !in done
                && dist[v] == Some(d)
                ==> du <= d;

            MinimumOpenDistanceIsShortest(
                graph, start, dist, done, u, du
            );

            assert is_shortest_dist(
                view(graph), start, u, du
            );

            ghost var witnessPath: seq<int> :|
                is_path(view(graph), witnessPath)
                && witnessPath[0] == start
                && witnessPath[|witnessPath| - 1] == u
                && path_weight(
                    view(graph), witnessPath
                ) == du;

            assert 0 <= du;
            assert witnessPath[|witnessPath| - 1] == u;
            assert witnessPath[|witnessPath| - 1] >= 0;

            var edgeIndex := 0;
            assert ProcessedEdges(
                graph, dist, u, du, edgeIndex
            );

            while edgeIndex < |graph.adj[u]|
                invariant 0 <= edgeIndex
                    <= |graph.adj[u]|
                invariant n == size(graph)
                invariant |dist| == n
                invariant dist[start] == Some(0)
                invariant dist[u] == Some(du)
                invariant DistWitness(
                    graph, start, dist
                )
                invariant DistancesNonnegative(dist)
                invariant Settled(
                    graph, start, dist, done
                )
                invariant ClosedEdges(
                    graph, dist, done
                )
                invariant ProcessedEdges(
                    graph, dist, u, du, edgeIndex
                )
                decreases |graph.adj[u]| - edgeIndex
            {
                var v := graph.adj[u][edgeIndex].0;
                var w := graph.adj[u][edgeIndex].1;

                assert has_edge(view(graph), u, v, w);
                assert 0 <= v < n;
                assert w >= 0;
                assert du >= 0;

                var candidate := du + w;
                assert candidate >= 0;

                if v in done {
                    var dv: int :|
                        dist[v] == Some(dv)
                        && is_shortest_dist(
                            view(graph), start, v, dv
                        );

                    ExtendPath(
                        graph, witnessPath, v, w
                    );
                    ghost var extended :=
                        witnessPath + [v];

                    assert is_path(
                        view(graph), extended
                    );
                    assert extended[0] == start;
                    assert extended[|extended| - 1] == v;
                    assert path_weight(
                        view(graph), extended
                    ) == candidate;
                    assert dv <= candidate;
                } else {
                    match dist[v]
                    case None =>
                        ExtendPath(
                            graph, witnessPath, v, w
                        );
                        ghost var extended :=
                            witnessPath + [v];

                        DistWitnessUpdate(
                            graph, start, dist,
                            v, candidate, extended
                        );
                        NonnegativeUpdate(
                            dist, v, candidate
                        );
                        UpdatePreservesSettled(
                            graph, start, dist,
                            done, v, candidate
                        );
                        LowerUpdatePreservesClosed(
                            graph, dist, done,
                            v, candidate
                        );
                        LowerUpdatePreservesProcessed(
                            graph, dist, u, du,
                            edgeIndex, v, candidate
                        );

                        if v == start {
                            assert dist[start] == Some(0);
                            assert false;
                        }

                        assert v != u;
                        dist := dist[v := Some(candidate)];

                    case Some(oldDistance) =>
                        if candidate < oldDistance {
                            ExtendPath(
                                graph, witnessPath, v, w
                            );
                            ghost var extended :=
                                witnessPath + [v];

                            DistWitnessUpdate(
                                graph, start, dist,
                                v, candidate, extended
                            );
                            NonnegativeUpdate(
                                dist, v, candidate
                            );
                            UpdatePreservesSettled(
                                graph, start, dist,
                                done, v, candidate
                            );
                            LowerUpdatePreservesClosed(
                                graph, dist, done,
                                v, candidate
                            );
                            LowerUpdatePreservesProcessed(
                                graph, dist, u, du,
                                edgeIndex, v, candidate
                            );

                            if v == start {
                                assert oldDistance == 0;
                                assert candidate >= 0;
                                assert false;
                            }

                            if v == u {
                                assert oldDistance == du;
                                assert candidate == du + w;
                                assert w >= 0;
                                assert candidate >= du;
                                assert false;
                            }

                            dist :=
                                dist[v := Some(candidate)];
                        } else {
                            assert oldDistance <= candidate;
                        }
                }

                assert 0 <= v < |dist|;
                assert exists dv: int ::
                    dist[v] == Some(dv)
                    && dv <= candidate;

                edgeIndex := edgeIndex + 1;
                assert ProcessedEdges(
