lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures has_edge(graph.adj, u, graph.adj[u][i].0, graph.adj[u][i].1)
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var w: int := g[u][i].1;
  assert 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
  assert has_edge(g, u, v, w);
  forall w': int | has_edge(g, u, v, w') ensures w' == w {
    var j: int :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
}

lemma ExtendPath(graph: WeightedGraph, p: seq<int>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires is_path(graph.adj, p) && p[|p| - 1] == u
  ensures is_path(graph.adj, p + [graph.adj[u][i].0])
  ensures (p + [graph.adj[u][i].0])[0] == p[0]
  ensures (p + [graph.adj[u][i].0])[|p|] == graph.adj[u][i].0
  ensures path_weight(graph.adj, p + [graph.adj[u][i].0]) == path_weight(graph.adj, p) + graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var q: seq<int> := p + [v];
  EdgeWeight(graph, u, i);
  assert connected(g, u, v);
  forall k: int | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
    if k < |p| - 1 {
      assert connected(g, p[k], p[k+1]);
      assert q[k] == p[k] && q[k+1] == p[k+1];
    } else {
      assert q[k] == u && q[k+1] == v;
    }
  }
  assert q[..|q| - 1] == p;
  assert q[|q| - 2] == u && q[|q| - 1] == v;
}

lemma PathLowerBound(graph: WeightedGraph, start: int, dist: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires |dist| == |graph.adj|
  requires 0 <= start < |graph.adj|
  requires dist[start] == Some(0)
  requires forall u: int, i: int :: 0 <= u < |graph.adj| && dist[u].Some? && 0 <= i < |graph.adj[u]| ==>
    dist[graph.adj[u][i].0].Some? && dist[graph.adj[u][i].0].value <= dist[u].value + graph.adj[u][i].1
  requires is_path(graph.adj, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |graph.adj|
  ensures dist[p[|p| - 1]].Some? && path_weight(graph.adj, p) >= dist[p[|p| - 1]].value
  decreases |p|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  if |p| == 1 {
    assert p[|p| - 1] == start;
  } else {
    var q: seq<int> := p[..|p| - 1];
    forall k: int | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
      assert connected(g, p[k], p[k+1]);
      assert q[k] == p[k] && q[k+1] == p[k+1];
    }
    assert is_path(g, q);
    assert q[0] == p[0];
    PathLowerBound(graph, start, dist, q);
    var m: int := |p| - 2;
    var u: int := p[m];
    var v: int := p[m+1];
    assert connected(g, p[m], p[m+1]);
    assert q[|q| - 1] == u;
    var w: int :| has_edge(g, u, v, w);
    var i: int :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
    EdgeWeight(graph, u, i);
    assert dist[g[u][i].0].Some? && dist[g[u][i].0].value <= dist[u].value + g[u][i].1;
    assert path_weight(g, p) == path_weight(g, q) + get_edge_weight(g, u, v);
    assert v == p[|p| - 1];
  }
}

method FindMin(dist: seq<Option<int>>, done: seq<bool>) returns (bu: int)
  requires |dist| == |done|
  ensures -1 <= bu < |done|
  ensures bu == -1 ==> forall k: int :: 0 <= k < |done| ==> done[k]
  ensures bu != -1 ==> !done[bu] && forall k: int :: 0 <= k < |done| && !done[k] ==> le_opt(dist[bu], dist[k])
{
  bu := -1;
  var j: int := 0;
  while j < |done|
    invariant 0 <= j <= |done|
    invariant -1 <= bu < |done|
    invariant bu == -1 ==> forall k: int :: 0 <= k < j ==> done[k]
    invariant bu != -1 ==> (!done[bu] &&
      forall k: int :: 0 <= k < j && !done[k] ==> le_opt(dist[bu], dist[k]))
  {
    if !done[j] {
      if bu == -1 {
        bu := j;
      } else if dist[j].Some? && (dist[bu].None? || dist[j].value < dist[bu].value) {
        bu := j;
      }
    }
    j := j + 1;
  }
}

method Relax(graph: WeightedGraph, start: int, bu: int, dist: seq<Option<int>>, ghost paths: seq<seq<int>>)
  returns (nd: seq<Option<int>>, ghost np: seq<seq<int>>)
  requires well_formed(graph)
  requires weights_non_negative(graph.adj)
  requires 0 <= start < |graph.adj| && 0 <= bu < |graph.adj|
  requires |dist| == |graph.adj|
  requires dist[bu].Some? && dist[start] == Some(0)
  requires NonNeg(dist) && PathsOk(graph.adj, start, dist, paths)
  ensures |nd| == |graph.adj| && nd[bu] == dist[bu] && nd[start] == Some(0)
  ensures NonNeg(nd) && PathsOk(graph.adj, start, nd, np)
  ensures Changed(dist, nd, dist[bu].value)
  ensures BuRelaxed(graph.adj, bu, nd, dist[bu].value)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var n: int := |g|;
  var du: int := dist[bu].value;
  nd := dist;
  np := paths;
  var i: int := 0;
  while i < |g[bu]|
    invariant 0 <= i <= |g[bu]|
    invariant |nd| == n && nd[bu] == Some(du) && nd[start] == Some(0)
    invariant NonNeg(nd) && PathsOk(g, start, nd, np)
    invariant Changed(dist, nd, du)
    invariant forall k: int :: 0 <= k < i ==>
      0 <= g[bu][k].0 < n && nd[g[bu][k].0].Some? && nd[g[bu][k].0].value <= du + g[bu][k].1
  {
    var v: int := g[bu][i].0;
    var w: int := g[bu][i].1;
    EdgeWeight(graph, bu, i);
    assert has_edge(g, bu, v, w);
    assert w >= 0;
    assert 0 <= v < n;
    var cand: int := du + w;
    if nd[v].None? || cand < nd[v].value {
      ghost var p: seq<int> := np[bu];
      assert is_path(g, p) && p[0] == start && p[|p| - 1] == bu && path_weight(g, p) == du;
      ExtendPath(graph, p, bu, i);
      np := np[v := p + [v]];
      nd := nd[v := Some(cand)];
      assert is_path(g, np[v]) && np[v][0] == start && np[v][|np[v]| - 1] == v
        && path_weight(g, np[v]) == nd[v].value;
    }
    i := i + 1;
  }
}

lemma StepLemma(g: seq<seq<(int, int)>>, bu: int, dist0: seq<Option<int>>, dist: seq<Option<int>>, done: seq<bool>)
  requires |dist0| == |g| && |dist| == |g| && |done| == |g|
  requires 0 <= bu < |g| && !done[bu] && dist0[bu].Some? && dist[bu] == dist0[bu]
  requires DoneSome(dist0, done) && DoneRelaxed(g, dist0, done) && Ordered(dist0, done)
  requires forall k: int :: 0 <= k < |g| && !done[k] ==> le_opt(dist0[bu], dist0[k])
  requires Changed(dist0, dist, dist0[bu].value)
  requires BuRelaxed(g, bu, dist, dist0[bu].value)
  ensures DoneSome(dist, done[bu := true])
  ensures DoneRelaxed(g, dist, done[bu := true])
  ensures Ordered(dist, done[bu := true])
{
  var n: int := |g|;
  var du: int := dist0[bu].value;
  var nd: seq<bool> := done[bu := true];
  forall x: int | 0 <= x < n && done[x] ensures dist[x] == dist0[x] {
    assert le_opt(dist0[x], dist0[bu]);
  }
  forall v: int | 0 <= v < n && nd[v] ensures dist[v].Some? {
    if v != bu {
      assert done[v];
    }
  }
  assert DoneSome(dist, nd);
  forall u: int, k: int | 0 <= u < n && nd[u] && 0 <= k < |g[u]|
    ensures dist[u].Some? && 0 <= g[u][k].0 < n && dist[g[u][k].0].Some?
      && dist[g[u][k].0].value <= dist[u].value + g[u][k].1
  {
    if u != bu {
      assert done[u];
      var t: int := g[u][k].0;
      assert 0 <= t < n && dist0[t].Some? && dist0[t].value <= dist0[u].value + g[u][k].1;
    }
  }
  assert DoneRelaxed(g, dist, nd);
  forall x: int, y: int | 0 <= x < n && 0 <= y < n && nd[x] && !nd[y]
    ensures le_opt(dist[x], dist[y])
  {
    assert y != bu && !done[y];
    assert le_opt(dist0[bu], dist0[y]);
    if x != bu {
      assert done[x];
      assert le_opt(dist0[x], dist0[bu]);
      assert dist[x] == dist0[x];
    }
  }
  assert Ordered(dist, nd);
}

