    &&
    forall u: int, v: int, w: int ::
        u in done && has_edge(view(graph), u, v, w) ==>
        0 <= u < |ds|
        && 0 <= v < |ds|
        &&
        exists du: int, dv: int ::
            ds[u] == Some(du)
            && ds[v] == Some(dv)
            && dv <= du + w
}

ghost predicate ProcessedEdges(
