lemma PathPrefix(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    k: int
)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures is_path(g, p[..k + 1])
{
    assert |p[..k + 1]| > 0;
    forall i: int | 0 <= i < |p[..k + 1]| - 1
        ensures connected(
            g,
            p[..k + 1][i],
            p[..k + 1][i + 1]
        )
    {
        assert p[..k + 1][i] == p[i];
        assert p[..k + 1][i + 1] == p[i + 1];
    }
}

lemma ChosenEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int
)
    requires connected(g, u, v)
    ensures has_edge(g, u, v, get_edge_weight(g, u, v))
{
    assert exists w: int :: has_edge(g, u, v, w);
}

lemma EdgeWeightIsUnique(
    graph: WeightedGraph,
    u: int,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w)
    ensures get_edge_weight(view(graph), u, v) == w
{
    ChosenEdge(view(graph), u, v);

    var i: int :|
        0 <= u < |graph.adj|
        && 0 <= i < |graph.adj[u]|
        && graph.adj[u][i].0 == v
        && graph.adj[u][i].1 == w;

    var j: int :|
        0 <= u < |graph.adj|
        && 0 <= j < |graph.adj[u]|
        && graph.adj[u][j].0 == v
        && graph.adj[u][j].1
            == get_edge_weight(view(graph), u, v);

    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma ExtendPath(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[|p| - 1] >= 0
    requires has_edge(view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures (p + [v])[0] == p[0]
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(view(graph), p + [v])
        == path_weight(view(graph), p) + w
{
    var u := p[|p| - 1];
    EdgeWeightIsUnique(graph, u, v, w);

    assert |p + [v]| > 0;
    forall i: int | 0 <= i < |p + [v]| - 1
        ensures connected(
            view(graph),
            (p + [v])[i],
            (p + [v])[i + 1]
        )
    {
        if i < |p| - 1 {
            assert (p + [v])[i] == p[i];
            assert (p + [v])[i + 1] == p[i + 1];
        } else {
            assert i == |p| - 1;
            assert (p + [v])[i] == u;
            assert (p + [v])[i + 1] == v;
            assert connected(view(graph), u, v);
        }
    }

    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma PrefixWeightAtMostPath(
    graph: WeightedGraph,
    p: seq<int>,
    k: int
)
    requires is_path(view(graph), p)
    requires weights_non_negative(view(graph))
    requires 0 <= k < |p|
    ensures path_weight(view(graph), p[..k + 1])
        <= path_weight(view(graph), p)
    decreases |p| - k
{
    if k == |p| - 1 {
        assert p[..k + 1] == p;
    } else {
        var q := p[..|p| - 1];
        PathPrefix(view(graph), p, |p| - 2);
        PrefixWeightAtMostPath(graph, q, k);

        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert connected(view(graph), u, v);
        ChosenEdge(view(graph), u, v);
        assert get_edge_weight(view(graph), u, v) >= 0;
        assert q[..k + 1] == p[..k + 1];
    }
}

lemma PathVerticesAreBounded(
    graph: WeightedGraph,
    p: seq<int>,
    start: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires p[0] == start
    requires 0 <= start < size(graph)
    ensures forall k: int :: 0 <= k < |p| ==>
        0 <= p[k] < size(graph)
{
    forall k: int | 0 <= k < |p|
        ensures 0 <= p[k] < size(graph)
    {
        var j := 0;
        while j < k
            invariant 0 <= j <= k
            invariant k < |p|
            invariant 0 <= p[j] < size(graph)
            decreases k - j
        {
            assert j < |p| - 1;
            assert connected(view(graph), p[j], p[j + 1]);

            var w: int :|
                has_edge(view(graph), p[j], p[j + 1], w);
            var ei: int :|
                0 <= p[j] < |graph.adj|
                && 0 <= ei < |graph.adj[p[j]]|
                && graph.adj[p[j]][ei].0 == p[j + 1]
                && graph.adj[p[j]][ei].1 == w;

            assert 0 <= graph.adj[p[j]][ei].0 < |graph.adj|;
            j := j + 1;
        }
    }
}

lemma DistWitnessUpdate(
