    assert dist[queue[i]] == layer + 1;
  }
}

lemma LayerDequeue(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  requires dist[queue[head]] == layer
  ensures LayerInv(dist, queue, head + 1, layer)
{
  forall i | 0 <= i < head + 1
    ensures dist[queue[i]] <= layer
  {
    if i < head {
      assert dist[queue[i]] <= layer;
    } else {
      assert i == head;
      assert dist[queue[i]] == layer;
    }
  }
  forall i | head + 1 <= i < |queue|
    ensures layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1
  {
    assert head <= i < |queue|;
    assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
  }
}

lemma MinPath(g: Graph, start: int, dist: seq<int>, u: int, r: seq<int>)
  requires AllMinDist(g, start, dist)
  requires 0 <= u < |dist|
  requires dist[u] >= 0
  requires is_path(g, r)
  requires r[0] == start
  requires r[|r| - 1] == u
  ensures |r| >= dist[u] + 1
{
  assert forall vv {:trigger dist[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    forall rr: seq<int> {:trigger is_path(g, rr)} ::
      is_path(g, rr) && rr[0] == start && rr[|rr| - 1] == vv ==> |rr| >= dist[vv] + 1;
  assert is_path(g, r);
  assert dist[u] >= 0;
  assert |r| >= dist[u] + 1;
}

lemma WitnessFacts(g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>, v: int)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= v < |dist|
  requires dist[v] >= 0
  ensures is_path(g, wits[v])
  ensures wits[v][0] == start
  ensures |wits[v]| == dist[v] + 1
  ensures wits[v][|wits[v]| - 1] == v
{
  assert forall vv {:trigger wits[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    is_path(g, wits[vv])
    && wits[vv][0] == start
    && |wits[vv]| == dist[vv] + 1
    && wits[vv][|wits[vv]| - 1] == vv;
  assert wits[v] == wits[v];
  assert dist[v] >= 0;
}

lemma ExpandedAt(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, i: int, e: int)
