      assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u}) + 1;
    }
    assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u}) + 1;
  }
}

predicate IndexClosed(g: Graph, S: set<int>) {
  forall u :: u in S ==>
    0 <= u < |g.adj| && (forall j :: 0 <= j < |g.adj[u]| ==> g.adj[u][j] in S)
}

predicate edge_closed(g: Graph, S: set<int>) {
  forall u, v :: u in S && has_edge(g, u, v) ==> v in S
}

lemma prefix_path(g: Graph, p: seq<int>)
  requires is_path(g, p)
  requires |p| >= 2
  ensures is_path(g, p[..(|p| - 1)])
{
  var q := p[..(|p| - 1)];
  assert |q| > 0;
  forall i | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    assert q[i] == p[i];
    assert q[i + 1] == p[i + 1];
    assert 0 <= i < |p| - 1;
    assert has_edge(g, p[i], p[i + 1]);
  }
}

lemma path_end_in_closed_set(g: Graph, start: int, S: set<int>, p: seq<int>)
  requires edge_closed(g, S)
  requires is_path(g, p)
  requires p[0] == start
  requires start in S
  ensures p[|p| - 1] in S
  decreases |p|
{
  if |p| == 1 {
    assert p[|p| - 1] == p[0];
    assert p[|p| - 1] in S;
  } else {
    assert |p| >= 2;
    prefix_path(g, p);
    var prefix := p[..(|p| - 1)];
    assert is_path(g, prefix);
    assert prefix[0] == start;
    path_end_in_closed_set(g, start, S, prefix);
    assert prefix[|prefix| - 1] in S;
    assert 0 <= |p| - 2 < |p| - 1;
    assert has_edge(g, p[|p| - 2], p[|p| - 1]);
    assert prefix[|prefix| - 1] == p[|p| - 2];
    assert forall a, b :: a in S && has_edge(g, a, b) ==> b in S;
    assert p[|p| - 1] in S;
  }
}

lemma to_edge_closed(g: Graph, S: set<int>)
  requires IndexClosed(g, S)
  ensures edge_closed(g, S)
{
  assert forall x :: x in S ==>
    0 <= x < |g.adj| && (forall t :: 0 <= t < |g.adj[x]| ==> g.adj[x][t] in S);
  forall u, v | u in S && has_edge(g, u, v)
    ensures v in S
  {
    var j :| 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| && g.adj[u][j] == v;
    assert forall t :: 0 <= t < |g.adj[u]| ==> g.adj[u][t] in S;
    assert g.adj[u][j] in S;
  }
}

lemma not_reachable_outside(g: Graph, start: int, target: int, S: set<int>)
  requires 0 <= start < |g.adj|
  requires 0 <= target < |g.adj|
  requires start in S
  requires target !in S
  requires IndexClosed(g, S)
  ensures !reachable(g, start, target)
{
  to_edge_closed(g, S);
  if reachable(g, start, target) {
    var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == target;
    path_end_in_closed_set(g, start, S, p);
    assert p[|p| - 1] in S;
    assert false;
  }
}

predicate OuterInv(g: Graph, n: int, start: int, target: int, visited: set<int>, stack: seq<int>) {
  0 <= n &&
  n == |g.adj| &&
  well_formed(g) &&
  0 <= start < n &&
  0 <= target < n &&
  (forall x :: x in visited ==> 0 <= x < n) &&
  (forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n) &&
  (forall x :: x in visited ==> reachable(g, start, x)) &&
  (forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k])) &&
  (forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))) &&
  (start in visited || inStack(stack, start)) &&
  target !in visited
}

predicate PartialInv(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stack: seq<int>, u: int, i: int
) {
  0 <= n &&
  n == |g.adj| &&
  well_formed(g) &&
  0 <= start < n &&
  0 <= target < n &&
  0 <= u < |g.adj| &&
  u in visited &&
  u !in visitedEntry &&
  u != target &&
  visited == visitedEntry + {u} &&
  target !in visited &&
  0 <= i <= |g.adj[u]| &&
  (forall x :: x in visited ==> 0 <= x < n) &&
  (forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n) &&
  (forall x :: x in visited ==> reachable(g, start, x)) &&
  (forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k])) &&
  (forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))) &&
  (start in visited || inStack(stack, start))
}

