  init_inv(graph, n, start, target, visited, stack);

  while |stack| > 0
    invariant 0 <= n
    invariant OuterInv(graph, n, start, target, visited, stack)
    decreases unvisitedCount(n, visited), |stack|
  {
    var u := stack[|stack| - 1];
    if u == target {
      found_target(graph, n, start, target, visited, stack, u);
      assert reachable(graph, start, target);
      return true;
    }

    ghost var oldLen := |stack|;
    ghost var stackBefore := stack;
    ghost var visitedEntry := visited;
    assert |stackBefore| > 0;
    assert |stackBefore| == oldLen;
    assert u == stackBefore[|stackBefore| - 1];
    assert visited == visitedEntry;
    assert u != target;
    outer_copy(graph, n, start, target, visited, stack, visitedEntry, stackBefore);

    stack := stack[..(|stack| - 1)];
    assert stack == stackBefore[..(|stackBefore| - 1)];

    if u in visited {
      assert visited == visitedEntry;
      assert u in visitedEntry;
      pop_seen(graph, n, start, target, visited, visitedEntry, stackBefore, stack, u);
      assert OuterInv(graph, n, start, target, visited, stack);
      assert |stack| == |stackBefore| - 1;
      assert |stack| < oldLen;
      assert visited == visitedEntry;
      assert unvisitedCount(n, visited) == unvisitedCount(n, visitedEntry);
    } else {
      assert visited == visitedEntry;
      assert u !in visited;
      assert u !in visitedEntry;
      visited := visited + {u};
      assert visited == visitedEntry + {u};
      var i := 0;
      pop_new(graph, n, start, target, visitedEntry, visited, stackBefore, stack, u, i);
      assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert 0 <= u < |graph.adj|;
      assert 0 <= i <= |graph.adj[u]|;

      while i < |graph.adj[u]|
        invariant 0 <= u < |graph.adj|
        invariant 0 <= i <= |graph.adj[u]|
        invariant PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i)
