        assert 0 <= i0 < |graph.adj[u]|;
        partial_same(graph, n, start, target, visited, visitedEntry, stack, u, i, stack0, i0);
        var v := graph.adj[u][i];
        assert v == graph.adj[u][i0];
        stack := stack + [v];
        i := i + 1;
        assert stack == stack0 + [v];
        assert i == i0 + 1;
        push_ok(graph, n, start, target, visited, visitedEntry, stack0, u, i0, v, stack, i);
        assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
        assert 0 <= i <= |graph.adj[u]|;
        assert |graph.adj[u]| - i < |graph.adj[u]| - i0;
      }

      assert 0 <= i <= |graph.adj[u]|;
      assert i == |graph.adj[u]|;
      partial_to_outer(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert OuterInv(graph, n, start, target, visited, stack);
      assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert u !in visitedEntry;
      assert visited == visitedEntry + {u};
      assert 0 <= u < n;
      count_shrink(n, visitedEntry, u);
      assert unvisitedCount(n, visited) == unvisitedCount(n, visitedEntry + {u});
      assert unvisitedCount(n, visitedEntry) == unvisitedCount(n, visited) + 1;
      assert unvisitedCount(n, visited) < unvisitedCount(n, visitedEntry);
    }
  }

  assert |stack| == 0;
  conclude_unreachable(graph, n, start, target, visited, stack);
  assert !reachable(graph, start, target);
  return false;
}
