lemma {:vcs_split_on_every_assert} forcing_extend(
  g: Graph, root: int, u: int, v: int, cu: bool,
  color: seq<Option<bool>>, in_comp: seq<bool>
)
  requires well_formed(g)
  requires Forced(g, root, color, in_comp)
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires u != v
  requires in_comp[u] && color[u] == Some(cu)
  requires color[v].None?
  requires !in_comp[v]
  requires connected(g, u, v)
  ensures Forced(g, root, color[v := Some(!cu)], in_comp[v := true])
{
  var n := |g.adj|;
  var color' := color[v := Some(!cu)];
  var in_comp' := in_comp[v := true];
  assert color[root] == Some(false);
  assert root != v;
  assert color'[root] == Some(false);
  assert |color'| == n && |in_comp'| == n;
  assert 0 <= root < n;
  forall C | is_valid_coloring(g, C)
    ensures |C| == n && 0 <= root < |C| &&
      forall uu :: 0 <= uu < n && in_comp'[uu] && color'[uu].Some? ==>
        0 <= uu < |C| && C[uu] == (C[root] != color'[uu].value)
  {
    assert |C| == n && 0 <= root < |C|;
    forced_at(g, root, color, in_comp, C, u);
    assert C[u] == (C[root] != color[u].value);
    assert C[u] == (C[root] != cu);
    forall uu | 0 <= uu < n && in_comp'[uu] && color'[uu].Some?
      ensures 0 <= uu < |C| && C[uu] == (C[root] != color'[uu].value)
    {
      assert 0 <= uu < |C|;
      if uu == v {
        connected_diff(g, C, u, v);
        assert C[v] != C[u];
        xor_step(C[root], cu, C[u], C[v]);
        assert color'[v].value == !cu;
        assert C[v] == (C[root] != color'[v].value);
      } else {
        assert in_comp[uu];
        assert color'[uu] == color[uu];
        assert color[uu].Some?;
        forced_at(g, root, color, in_comp, C, uu);
        assert C[uu] == (C[root] != color[uu].value);
        assert C[uu] == (C[root] != color'[uu].value);
      }
    }
  }
  assert Forced(g, root, color', in_comp');
}

lemma {:vcs_split_on_every_assert} prove_not_bipartite(
  g: Graph, root: int, u: int, v: int,
  color: seq<Option<bool>>, in_comp: seq<bool>
)
  requires Forced(g, root, color, in_comp)
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires in_comp[u] && in_comp[v]
  requires color[u].Some? && color[v].Some?
  requires color[u].value == color[v].value
  requires connected(g, u, v)
  ensures !is_bipartite(g)
{
  if is_bipartite(g) {
    var C :| is_valid_coloring(g, C);
    forced_at(g, root, color, in_comp, C, u);
    forced_at(g, root, color, in_comp, C, v);
    assert C[u] == (C[root] != color[u].value);
    assert C[v] == (C[root] != color[v].value);
    assert C[u] == C[v];
    connected_diff(g, C, u, v);
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} init_comp_inv(g: Graph, color0: seq<Option<bool>>, root: int)
  requires well_formed(g)
  requires |color0| == |g.adj|
  requires 0 <= root < |g.adj|
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  ensures var n := |g.adj|;
          var color := color0[root := Some(false)];
          var in_comp := (seq(n, i => false))[root := true];
          var queue := [root];
          && CompInv(g, color0, color, in_comp, queue, 0, root)
          && Forced(g, root, color, in_comp)
          && QueueOK(n, color, in_comp, queue)
          && InCompOK(color0, color, in_comp, queue)
          && OutsideOK(color0, color, in_comp)
          && Separated(g, color0, in_comp)
          && ProcessedOK(g, color, in_comp, queue, 0)
          && color[root] == Some(false)
          && in_comp[root]
{
  var n := |g.adj|;
  var color := color0[root := Some(false)];
  var base := seq(n, i => false);
  var in_comp := base[root := true];
  var queue := [root];
  var qh := 0;

  forall i | 0 <= i < n
    ensures in_comp[i] == (i == root)
  {
    if i == root {
      assert in_comp[i] == true;
    } else {
      assert base[i] == false;
      assert in_comp[i] == false;
    }
  }
  forall i | 0 <= i < n && i != root
    ensures color[i] == color0[i]
  {
    assert color[i] == color0[i];
  }

  forall k | 0 <= k < |queue|
    ensures 0 <= queue[k] < n && in_comp[queue[k]] && color[queue[k]].Some?
  {
    assert queue[k] == root;
  }
  assert QueueOK(n, color, in_comp, queue);

  forall uu | 0 <= uu < n && in_comp[uu]
    ensures uu in queue && color[uu].Some? && color0[uu].None?
  {
    assert uu == root;
    assert root in queue;
    assert color0[root].None?;
    assert color[root].Some?;
  }
  assert InCompOK(color0, color, in_comp, queue);

  forall uu | 0 <= uu < n && !in_comp[uu]
    ensures color[uu] == color0[uu]
  {
    assert uu != root;
  }
  assert OutsideOK(color0, color, in_comp);

  forall a, b | 0 <= a < n && 0 <= b < n && in_comp[a] && color0[b].Some?
    ensures !connected(g, a, b)
  {
    assert a == root;
    if connected(g, root, b) {
      connected_sym(g, root, b);
      assert connected(g, b, root);
      closed_step(g, color0, b, root);
      assert color0[root].Some?;
      assert false;
    }
  }
  assert Separated(g, color0, in_comp);

  assert 0 <= qh <= |queue|;
  assert ProcessedOK(g, color, in_comp, queue, qh);

  assert color[root] == Some(false);
  forall C | is_valid_coloring(g, C)
    ensures |C| == n && 0 <= root < |C| &&
      forall uu :: 0 <= uu < n && in_comp[uu] && color[uu].Some? ==>
        0 <= uu < |C| && C[uu] == (C[root] != color[uu].value)
  {
    assert |C| == size(g);
    assert |C| == n;
    forall uu | 0 <= uu < n && in_comp[uu] && color[uu].Some?
      ensures 0 <= uu < |C| && C[uu] == (C[root] != color[uu].value)
    {
      assert uu == root;
      assert color[uu].value == false;
      root_force(C[uu]);
      assert C[uu] == (C[root] != false);
    }
  }
  assert Forced(g, root, color, in_comp);

  assert color[root] == Some(false);
  assert in_comp[root];
  assert CompInv(g, color0, color, in_comp, queue, qh, root);
}

lemma {:vcs_split_on_every_assert} after_color(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, v: int, cu: bool
)
  requires well_formed(g)
  requires |g.adj| == |color0| == |color| == |in_comp|
  requires 0 <= root < |g.adj|
  requires 0 <= qh < |queue|
  requires u == queue[qh]
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires color[root] == Some(false)
  requires in_comp[root]
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires color[u] == Some(cu) && in_comp[u]
  requires color[v].None? && !in_comp[v]
  requires connected(g, u, v)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires Forced(g, root, color, in_comp)
  ensures CompInv(g, color0, color[v := Some(!cu)], in_comp[v := true], queue + [v], qh, root)
  ensures Forced(g, root, color[v := Some(!cu)], in_comp[v := true])
  ensures QueueOK(|g.adj|, color[v := Some(!cu)], in_comp[v := true], queue + [v])
  ensures InCompOK(color0, color[v := Some(!cu)], in_comp[v := true], queue + [v])
  ensures OutsideOK(color0, color[v := Some(!cu)], in_comp[v := true])
  ensures Separated(g, color0, in_comp[v := true])
  ensures ProcessedOK(g, color[v := Some(!cu)], in_comp[v := true], queue + [v], qh)
  ensures (color[v := Some(!cu)])[root] == Some(false)
  ensures (in_comp[v := true])[root]
  ensures (color[v := Some(!cu)])[u] == Some(cu)
  ensures u != v
{
  var n := |g.adj|;
  var color' := color[v := Some(!cu)];
  var in_comp' := in_comp[v := true];
  var queue' := queue + [v];

  assert u != v;
  assert root != v;
  assert color'[root] == Some(false);
  assert in_comp'[root] == in_comp[root];
  assert in_comp'[root];
  assert color'[u] == Some(cu);
  assert |color'| == n && |in_comp'| == n && |queue'| == |queue| + 1;
  assert 0 <= qh <= |queue'|;
  assert queue'[qh] == queue[qh];

  forall k | 0 <= k < |queue|
    ensures queue[k] != v
  {
    assert color[queue[k]].Some?;
    assert color[v].None?;
  }

  forall k | 0 <= k < |queue'|
    ensures 0 <= queue'[k] < n && in_comp'[queue'[k]] && color'[queue'[k]].Some?
  {
    if k < |queue| {
      assert queue'[k] == queue[k];
      assert queue[k] != v;
      assert in_comp'[queue[k]] == in_comp[queue[k]];
      assert color'[queue[k]] == color[queue[k]];
    } else {
      assert k == |queue|;
      assert queue'[k] == v;
      assert in_comp'[v] && color'[v].Some?;
    }
  }
  assert QueueOK(n, color', in_comp', queue');

  assert color[v] == color0[v];
  assert color0[v].None?;

  forall uu | 0 <= uu < n && in_comp'[uu]
    ensures uu in queue' && color'[uu].Some? && color0[uu].None?
  {
    if uu == v {
      mem_last(queue, v);
      assert v in queue + [v];
      assert queue' == queue + [v];
      assert v in queue';
      assert color'[v].Some?;
      assert color0[v].None?;
    } else {
      assert in_comp[uu];
      assert uu in queue;
      mem_append(queue, uu, v);
      assert uu in queue + [v];
      assert uu in queue';
      assert color'[uu] == color[uu];
      assert color[uu].Some? && color0[uu].None?;
    }
  }
  assert InCompOK(color0, color', in_comp', queue');

  forall uu | 0 <= uu < n && !in_comp'[uu]
    ensures color'[uu] == color0[uu]
  {
    assert uu != v;
    assert !in_comp[uu];
    assert color'[uu] == color[uu];
    assert color[uu] == color0[uu];
  }
  assert OutsideOK(color0, color', in_comp');

  forall a, b | 0 <= a < n && 0 <= b < n && in_comp'[a] && color0[b].Some?
    ensures !connected(g, a, b)
  {
    if a == v {
      if connected(g, v, b) {
        connected_sym(g, v, b);
        assert connected(g, b, v);
        closed_step(g, color0, b, v);
        assert color0[v].Some?;
        assert false;
      }
    } else {
      assert in_comp[a];
      assert !connected(g, a, b);
    }
  }
  assert Separated(g, color0, in_comp');

  forall p | 0 <= p < qh
    ensures !connected(g, queue[p], v)
  {
    if connected(g, queue[p], v) {
      assert color[v].Some?;
      assert false;
    }
  }

  forall p | 0 <= p < qh
    ensures 0 <= queue'[p] < n && color'[queue'[p]].Some? &&
      forall w :: 0 <= w < n && connected(g, queue'[p], w) ==>
        in_comp'[w] && color'[w].Some? && color'[w].value != color'[queue'[p]].value
  {
    assert queue'[p] == queue[p];
    assert queue[p] != v;
    assert color'[queue[p]] == color[queue[p]];
    assert color[queue[p]].Some?;
    forall w | 0 <= w < n && connected(g, queue[p], w)
      ensures in_comp'[w] && color'[w].Some? && color'[w].value != color'[queue[p]].value
    {
      assert w != v;
      assert in_comp[w] && color[w].Some?;
      assert color[w].value != color[queue[p]].value;
      assert in_comp'[w] == in_comp[w];
      assert color'[w] == color[w];
    }
  }
  assert ProcessedOK(g, color', in_comp', queue', qh);

  forcing_extend(g, root, u, v, cu, color, in_comp);
  assert Forced(g, root, color', in_comp');

  assert CompInv(g, color0, color', in_comp', queue', qh, root);
}

lemma {:vcs_split_on_every_assert} step_qh(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int
)
  requires well_formed(g)
  requires |color0| == |g.adj| == |color| == |in_comp|
  requires 0 <= root < |g.adj|
  requires 0 <= qh < |queue|
  requires 0 <= queue[qh] < |g.adj|
  requires color[queue[qh]].Some?
  requires color[root] == Some(false)
  requires in_comp[root]
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires Forced(g, root, color, in_comp)
  requires forall w :: 0 <= w < |g.adj| && connected(g, queue[qh], w) ==>
      in_comp[w] && color[w].Some? && color[w].value != color[queue[qh]].value
  ensures ProcessedOK(g, color, in_comp, queue, qh + 1)
  ensures CompInv(g, color0, color, in_comp, queue, qh + 1, root)
{
  var n := |g.adj|;
  var u := queue[qh];
  assert 0 <= qh + 1 <= |queue|;
  forall p | 0 <= p < qh + 1
    ensures 0 <= queue[p] < n && color[queue[p]].Some? &&
      forall w :: 0 <= w < n && connected(g, queue[p], w) ==>
        in_comp[w] && color[w].Some? && color[w].value != color[queue[p]].value
  {
    if p < qh {
    } else {
      assert p == qh;
      assert queue[p] == u;
      assert color[u].Some?;
    }
  }
  assert ProcessedOK(g, color, in_comp, queue, qh + 1);
  assert CompInv(g, color0, color, in_comp, queue, qh + 1, root);
}

lemma {:vcs_split_on_every_assert} prefix_covers(
  g: Graph, color: seq<Option<bool>>, in_comp: seq<bool>,
  u: int, cu: bool, nbrs: seq<int>
)
  requires 0 <= u < |g.adj|
  requires |color| == |g.adj| == |in_comp|
  requires color[u] == Some(cu)
  requires forall t :: 0 <= t < |nbrs| ==>
      0 <= nbrs[t] < |g.adj| && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  requires forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==> w in nbrs
  ensures forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==>
      in_comp[w] && color[w].Some? && color[w].value != cu
{
  forall w | 0 <= w < |g.adj| && connected(g, u, w)
    ensures in_comp[w] && color[w].Some? && color[w].value != cu
  {
    assert w in nbrs;
    assert exists t :: 0 <= t < |nbrs| && nbrs[t] == w;
    var t :| 0 <= t < |nbrs| && nbrs[t] == w;
  }
}

lemma {:vcs_split_on_every_assert} finish(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int
)
  requires well_formed(g)
  requires |color| == |g.adj| == |color0| == |in_comp|
  requires 0 <= root < |g.adj|
  requires qh == |queue|
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires color[root].Some?
  ensures IsClosed(g, color)
  ensures EdgesOK(g, color)
  ensures forall uu :: 0 <= uu < |g.adj| && color0[uu].Some? ==> color[uu] == color0[uu]
  ensures color[root].Some?
  ensures |color| == |g.adj|
{
  var n := |g.adj|;
  forall a, b | 0 <= a < n && 0 <= b < n && connected(g, a, b) && color[a].Some?
    ensures color[b].Some?
  {
    if in_comp[a] {
      assert a in queue;
      assert exists p :: 0 <= p < |queue| && queue[p] == a;
      var p :| 0 <= p < |queue| && queue[p] == a;
      assert p < qh;
      assert color[b].Some?;
    } else {
      assert color[a] == color0[a];
      assert color0[a].Some?;
      closed_step(g, color0, a, b);
      assert color0[b].Some?;
      if in_comp[b] {
        assert color0[b].None?;
        assert false;
      }
      assert color[b] == color0[b];
    }
  }
  assert IsClosed(g, color);

  forall a, b | 0 <= a < n && 0 <= b < n && has_edge(g, a, b) && color[a].Some? && color[b].Some?
    ensures color[a].value != color[b].value
  {
    assert connected(g, a, b);
    if in_comp[a] && in_comp[b] {
      assert a in queue;
      assert exists p :: 0 <= p < |queue| && queue[p] == a;
      var p :| 0 <= p < |queue| && queue[p] == a;
      assert p < qh;
      assert color[b].value != color[a].value;
    } else if !in_comp[a] && !in_comp[b] {
      assert color[a] == color0[a];
      assert color[b] == color0[b];
      assert color0[a].Some? && color0[b].Some?;
      edges_step(g, color0, a, b);
      assert color0[a].value != color0[b].value;
    } else if in_comp[a] {
      assert !in_comp[b];
      assert color[b] == color0[b];
      assert color0[b].Some?;
      assert !connected(g, a, b);
      assert false;
    } else {
      assert in_comp[b] && !in_comp[a];
      assert color[a] == color0[a];
      assert color0[a].Some?;
      connected_sym(g, a, b);
      assert !connected(g, b, a);
      assert false;
    }
  }
  assert EdgesOK(g, color);

  forall uu | 0 <= uu < n && color0[uu].Some?
    ensures color[uu] == color0[uu]
  {
    if in_comp[uu] {
      assert color0[uu].None?;
      assert false;
    }
    assert color[uu] == color0[uu];
  }
}

lemma {:vcs_split_on_every_assert} pack_inv(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, cu: bool, nbrs: seq<int>, j: int,
  cn0: int, qlen0: int, qh0: int
)
  requires CompInv(g, color0, color, in_comp, queue, qh, root)
  requires Forced(g, root, color, in_comp)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires color0[root].None?
  requires color[root] == Some(false)
  requires in_comp[root]
  requires |color| == |g.adj| && |in_comp| == |g.adj|
  requires 0 <= qh <= |queue|
  requires qh == qh0 && qh0 < qlen0 && |queue| >= qlen0
  requires qh < |queue|
  requires u == queue[qh] && 0 <= u < |g.adj|
  requires color[u] == Some(cu) && in_comp[u]
  requires count_none(color) + |queue| == cn0 + qlen0
  requires count_none(color) >= 0
  requires forall t :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < |g.adj| && connected(g, u, nbrs[t])
  requires forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==> w in nbrs
  requires 0 <= j <= |nbrs|
  requires forall t :: 0 <= t < j ==>
      0 <= nbrs[t] < |g.adj| && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  ensures NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0)
{
  assert NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0);
}

