ghost predicate {:fuel 2} NeighborInv(
  g: Graph,
  color0: seq<Option<bool>>,
  color: seq<Option<bool>>,
  in_comp: seq<bool>,
  queue: seq<int>,
  qh: int,
  root: int,
  u: int,
  cu: bool,
  nbrs: seq<int>,
  j: int,
  cn0: int,
  qlen0: int,
  qh0: int
