  Forced(g, root, color, in_comp) &&
  QueueOK(n, color, in_comp, queue) &&
  InCompOK(color0, color, in_comp, queue) &&
  OutsideOK(color0, color, in_comp) &&
  Separated(g, color0, in_comp) &&
  ProcessedOK(g, color, in_comp, queue, qh) &&
  IsClosed(g, color0) &&
  EdgesOK(g, color0) &&
  color0[root].None? &&
  color[root] == Some(false) &&
  in_comp[root] &&
  |color| == n && |in_comp| == n &&
  0 <= qh <= |queue| &&
  qh == qh0 && qh0 < qlen0 && |queue| >= qlen0 &&
  qh < |queue| &&
  u == queue[qh] && 0 <= u < n &&
  color[u] == Some(cu) && in_comp[u] &&
  count_none(color) + |queue| == cn0 + qlen0 &&
  count_none(color) >= 0 &&
  (forall t {:trigger nbrs[t]} :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < n && connected(g, u, nbrs[t])) &&
  (forall w {:trigger connected(g, u, w)} :: 0 <= w < n && connected(g, u, w) ==> w in nbrs) &&
  0 <= j <= |nbrs| &&
  (forall t {:trigger nbrs[t]} :: 0 <= t < j ==>
