ghost function count_none(color: seq<Option<bool>>): int
  decreases |color|
{
  if |color| == 0 then 0
  else (if color[0].None? then 1 else 0) + count_none(color[1..])
}

lemma {:vcs_split_on_every_assert} count_none_nonneg(color: seq<Option<bool>>)
  ensures count_none(color) >= 0
  decreases |color|
{
  if |color| == 0 {
  } else {
