  assert exists i :: 0 <= i < |s| && s[i] == x;
  var i :| 0 <= i < |s| && s[i] == x;
  assert (s + [y])[i] == s[i];
  assert (s + [y])[i] == x;
  assert x in s + [y];
}

lemma {:vcs_split_on_every_assert} mem_last<T(==)>(s: seq<T>, y: T)
