  ensures inStack(s + [v], x)
{
  var s2 := s + [v];
  if x == v {
    assert 0 <= |s| < |s2|;
    assert s2[|s|] == x;
    assert exists j :: 0 <= j < |s2| && s2[j] == x;
    assert inStack(s2, x);
  } else {
    assert inStack(s, x);
    var k :| 0 <= k < |s| && s[k] == x;
    assert s2[k] == x;
    assert exists j :: 0 <= j < |s2| && s2[j] == x;
    assert inStack(s2, x);
  }
}

lemma inStack_same(a: seq<int>, b: seq<int>, x: int)
  requires a == b
  requires inStack(a, x)
  ensures inStack(b, x)
{
  var k :| 0 <= k < |a| && a[k] == x;
  assert b[k] == x;
