lemma neighbor_in_range(g: Graph, uu: int, ii: int)
  requires well_formed(g)
  requires 0 <= uu < |g.adj|
  requires 0 <= ii < |g.adj[uu]|
  ensures 0 <= g.adj[uu][ii] < |g.adj|
{
  assert forall a, b ::
    0 <= a < |g.adj| && 0 <= b < |g.adj[a]| ==> 0 <= g.adj[a][b] < |g.adj|;
  assert 0 <= uu < |g.adj| && 0 <= ii < |g.adj[uu]|;
  assert 0 <= g.adj[uu][ii] < |g.adj|;
}

lemma edge_at(g: Graph, uu: int, ii: int)
  requires 0 <= uu < |g.adj|
  requires 0 <= ii < |g.adj[uu]|
  ensures has_edge(g, uu, g.adj[uu][ii])
{
  var i := ii;
  assert 0 <= i < |g.adj[uu]| && g.adj[uu][i] == g.adj[uu][ii];
  assert exists j :: 0 <= uu < |g.adj| && 0 <= j < |g.adj[uu]| && g.adj[uu][j] == g.adj[uu][ii];
  assert has_edge(g, uu, g.adj[uu][ii]);
}

ghost function unvisitedCount(n: int, visited: set<int>): nat
  requires 0 <= n
  decreases n
{
  if n == 0 then 0
  else if (n - 1) !in visited then unvisitedCount(n - 1, visited) + 1
  else unvisitedCount(n - 1, visited)
}

lemma count_plus_same(n: int, visited: set<int>, u: int)
  requires 0 <= n
  requires u < 0 || n <= u
  ensures unvisitedCount(n, visited) == unvisitedCount(n, visited + {u})
  decreases n
{
  if n == 0 {
  } else {
    count_plus_same(n - 1, visited, u);
    assert (n - 1) != u;
    if (n - 1) !in visited {
      assert (n - 1) !in (visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n - 1, visited) + 1;
      assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u}) + 1;
      assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u});
    } else {
      assert (n - 1) in visited;
      assert (n - 1) in (visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n - 1, visited);
      assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u});
    }
    assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u});
  }
}

lemma count_shrink(n: int, visited: set<int>, u: int)
  requires 0 <= u < n
  requires u !in visited
  ensures unvisitedCount(n, visited) == unvisitedCount(n, visited + {u}) + 1
  decreases n
{
  if u == n - 1 {
    assert n >= 1;
    count_plus_same(n - 1, visited, u);
    assert (n - 1) !in visited;
    assert unvisitedCount(n, visited) == unvisitedCount(n - 1, visited) + 1;
    assert (n - 1) in (visited + {u});
    assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u});
    assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u});
    var c := unvisitedCount(n - 1, visited);
    assert unvisitedCount(n, visited) == c + 1;
    assert unvisitedCount(n, visited + {u}) == c;
    assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u}) + 1;
  } else {
    assert 0 <= u < n - 1;
    count_shrink(n - 1, visited, u);
    assert (n - 1) != u;
    if (n - 1) !in visited {
      assert (n - 1) !in (visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n - 1, visited) + 1;
      assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u}) + 1;
      assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u}) + 1;
      var c := unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n - 1, visited) == c + 1;
      assert unvisitedCount(n, visited) == (c + 1) + 1;
      assert unvisitedCount(n, visited + {u}) == c + 1;
      assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u}) + 1;
    } else {
      assert (n - 1) in visited;
      assert (n - 1) in (visited + {u});
      assert unvisitedCount(n, visited) == unvisitedCount(n - 1, visited);
      assert unvisitedCount(n, visited + {u}) == unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n - 1, visited) == unvisitedCount(n - 1, visited + {u}) + 1;
      var c := unvisitedCount(n - 1, visited + {u});
      assert unvisitedCount(n - 1, visited) == c + 1;
      assert unvisitedCount(n, visited) == c + 1;
      assert unvisitedCount(n, visited + {u}) == c;
      assert unvisitedCount(n, visited) == unvisitedCount(n, visited + {u}) + 1;
    }
  }
}

ghost predicate IndexClosed(g: Graph, S: set<int>) {
  forall u :: u in S ==>
    0 <= u < |g.adj| && (forall j :: 0 <= j < |g.adj[u]| ==> g.adj[u][j] in S)
}

ghost predicate edge_closed(g: Graph, S: set<int>) {
  forall u, v :: u in S && has_edge(g, u, v) ==> v in S
}

lemma prefix_path(g: Graph, p: seq<int>)
  requires is_path(g, p)
  requires |p| >= 2
  ensures is_path(g, p[..(|p| - 1)])
{
  var q := p[..(|p| - 1)];
  assert |q| > 0;
  forall i | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    assert q[i] == p[i];
    assert q[i + 1] == p[i + 1];
    assert 0 <= i < |p| - 1;
    assert has_edge(g, p[i], p[i + 1]);
  }
}

lemma path_end_in_closed_set(g: Graph, start: int, S: set<int>, p: seq<int>)
  requires edge_closed(g, S)
  requires is_path(g, p)
  requires p[0] == start
  requires start in S
  ensures p[|p| - 1] in S
  decreases |p|
{
  if |p| == 1 {
    assert p[|p| - 1] == p[0];
    assert p[|p| - 1] in S;
  } else {
    assert |p| >= 2;
    prefix_path(g, p);
    var prefix := p[..(|p| - 1)];
    assert is_path(g, prefix);
    assert prefix[0] == start;
    path_end_in_closed_set(g, start, S, prefix);
    assert prefix[|prefix| - 1] in S;
    assert 0 <= |p| - 2 < |p| - 1;
    assert has_edge(g, p[|p| - 2], p[|p| - 1]);
    assert prefix[|prefix| - 1] == p[|p| - 2];
    assert forall a, b :: a in S && has_edge(g, a, b) ==> b in S;
    assert p[|p| - 1] in S;
  }
}

lemma to_edge_closed(g: Graph, S: set<int>)
  requires IndexClosed(g, S)
  ensures edge_closed(g, S)
{
  assert forall x :: x in S ==>
    0 <= x < |g.adj| && (forall t :: 0 <= t < |g.adj[x]| ==> g.adj[x][t] in S);
  forall u, v | u in S && has_edge(g, u, v)
    ensures v in S
  {
    var j :| 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| && g.adj[u][j] == v;
    assert forall t :: 0 <= t < |g.adj[u]| ==> g.adj[u][t] in S;
    assert g.adj[u][j] in S;
    assert v in S;
  }
}

lemma not_reachable_outside(g: Graph, start: int, target: int, S: set<int>)
  requires 0 <= start < |g.adj|
  requires 0 <= target < |g.adj|
  requires start in S
  requires target !in S
  requires IndexClosed(g, S)
  ensures !reachable(g, start, target)
{
  to_edge_closed(g, S);
  if reachable(g, start, target) {
    var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == target;
    path_end_in_closed_set(g, start, S, p);
    assert p[|p| - 1] in S;
    assert target in S;
    assert false;
  }
  assert !reachable(g, start, target);
}

ghost predicate OuterInv(g: Graph, n: int, start: int, target: int, visited: set<int>, stack: seq<int>) {
  0 <= n &&
  n == |g.adj| &&
  well_formed(g) &&
  0 <= start < n &&
  0 <= target < n &&
  (forall x :: x in visited ==> 0 <= x < n) &&
  (forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n) &&
  (forall x :: x in visited ==> reachable(g, start, x)) &&
  (forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k])) &&
  (forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))) &&
  (start in visited || inStack(stack, start)) &&
  target !in visited
}

ghost predicate PartialInv(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stack: seq<int>, u: int, i: int
) {
  0 <= n &&
  n == |g.adj| &&
  well_formed(g) &&
  0 <= start < n &&
  0 <= target < n &&
  0 <= u < |g.adj| &&
  u in visited &&
  u !in visitedEntry &&
  u != target &&
  visited == visitedEntry + {u} &&
  target !in visited &&
  0 <= i <= |g.adj[u]| &&
  (forall x :: x in visited ==> 0 <= x < n) &&
  (forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n) &&
  (forall x :: x in visited ==> reachable(g, start, x)) &&
  (forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k])) &&
  (forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))) &&
  (start in visited || inStack(stack, start))
}

lemma {:vcs_split_on_every_assert} outer_copy(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, stack: seq<int>,
  visitedEntry: set<int>, stackBefore: seq<int>
)
  requires visitedEntry == visited
  requires stackBefore == stack
  requires OuterInv(g, n, start, target, visited, stack)
  ensures OuterInv(g, n, start, target, visitedEntry, stackBefore)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert forall x :: x in visited ==> 0 <= x < n;
  assert forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n;
  assert forall x :: x in visited ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k]);
  assert forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visited || inStack(stack, g.adj[w][j]));
  assert start in visited || inStack(stack, start);
  assert target !in visited;

  forall x | x in visitedEntry
    ensures 0 <= x < n
  {
    assert x in visited;
  }
  forall k | 0 <= k < |stackBefore|
    ensures 0 <= stackBefore[k] < n
  {
    assert stackBefore[k] == stack[k];
  }
  forall x | x in visitedEntry
    ensures reachable(g, start, x)
  {
    assert x in visited;
  }
  forall k | 0 <= k < |stackBefore|
    ensures reachable(g, start, stackBefore[k])
  {
    assert stackBefore[k] == stack[k];
  }
  forall w | w in visitedEntry
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        g.adj[w][j] in visitedEntry || inStack(stackBefore, g.adj[w][j]))
  {
    assert w in visited;
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures g.adj[w][j] in visitedEntry || inStack(stackBefore, g.adj[w][j])
    {
      var y := g.adj[w][j];
      assert y in visited || inStack(stack, y);
      if y in visited {
        assert y in visitedEntry;
      } else {
        assert inStack(stack, y);
        inStack_same(stack, stackBefore, y);
      }
    }
  }
  if start in visitedEntry {
  } else {
    assert inStack(stack, start);
    inStack_same(stack, stackBefore, start);
  }
  assert target !in visitedEntry;
  assert OuterInv(g, n, start, target, visitedEntry, stackBefore);
}

lemma {:vcs_split_on_every_assert} partial_same(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stack: seq<int>, u: int, i: int,
  stack0: seq<int>, i0: int
)
  requires stack0 == stack
  requires i0 == i
  requires PartialInv(g, n, start, target, visited, visitedEntry, stack, u, i)
  ensures PartialInv(g, n, start, target, visited, visitedEntry, stack0, u, i0)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert 0 <= u < |g.adj|;
  assert u in visited;
  assert u !in visitedEntry;
  assert u != target;
  assert visited == visitedEntry + {u};
  assert target !in visited;
  assert 0 <= i <= |g.adj[u]|;
  assert 0 <= i0 <= |g.adj[u]|;
  assert forall x :: x in visited ==> 0 <= x < n;
  assert forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n;
  assert forall x :: x in visited ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k]);
  assert forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]));
  assert start in visited || inStack(stack, start);

  forall k | 0 <= k < |stack0|
    ensures 0 <= stack0[k] < n
  {
    assert stack0[k] == stack[k];
  }
  forall k | 0 <= k < |stack0|
    ensures reachable(g, start, stack0[k])
  {
    assert stack0[k] == stack[k];
  }
  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        (w == u && j >= i0) || g.adj[w][j] in visited || inStack(stack0, g.adj[w][j]))
  {
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures (w == u && j >= i0) || g.adj[w][j] in visited || inStack(stack0, g.adj[w][j])
    {
      var y := g.adj[w][j];
      assert (w == u && j >= i) || y in visited || inStack(stack, y);
      if w == u && j >= i {
        assert j >= i0;
      } else if y in visited {
      } else {
        assert inStack(stack, y);
        inStack_same(stack, stack0, y);
      }
    }
  }
  if start in visited {
  } else {
    assert inStack(stack, start);
    inStack_same(stack, stack0, start);
  }
  assert PartialInv(g, n, start, target, visited, visitedEntry, stack0, u, i0);
}

lemma prefix_props(g: Graph, n: int, start: int, stackBefore: seq<int>, stack: seq<int>)
  requires |stackBefore| > 0
  requires stack == stackBefore[..(|stackBefore| - 1)]
  requires forall k :: 0 <= k < |stackBefore| ==> 0 <= stackBefore[k] < n
  requires forall k :: 0 <= k < |stackBefore| ==> reachable(g, start, stackBefore[k])
  ensures forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n
  ensures forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k])
{
  forall k | 0 <= k < |stack|
    ensures 0 <= stack[k] < n
  {
    assert stack[k] == stackBefore[k];
  }
  forall k | 0 <= k < |stack|
    ensures reachable(g, start, stack[k])
  {
    assert stack[k] == stackBefore[k];
  }
}

lemma {:vcs_split_on_every_assert} pop_seen(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stackBefore: seq<int>, stack: seq<int>, u: int
)
  requires OuterInv(g, n, start, target, visitedEntry, stackBefore)
  requires visited == visitedEntry
  requires |stackBefore| > 0
  requires u == stackBefore[|stackBefore| - 1]
  requires u in visited
  requires stack == stackBefore[..(|stackBefore| - 1)]
  ensures OuterInv(g, n, start, target, visited, stack)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert target !in visitedEntry;
  assert target !in visited;
  assert u in visitedEntry;
  assert forall x :: x in visitedEntry ==> 0 <= x < n;
  assert forall x :: x in visitedEntry ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stackBefore| ==> 0 <= stackBefore[k] < n;
  assert forall k :: 0 <= k < |stackBefore| ==> reachable(g, start, stackBefore[k]);
  assert forall w :: w in visitedEntry ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visitedEntry || inStack(stackBefore, g.adj[w][j]));
  assert start in visitedEntry || inStack(stackBefore, start);

  forall x | x in visited
    ensures 0 <= x < n
  {
    assert x in visitedEntry;
  }
  forall x | x in visited
    ensures reachable(g, start, x)
  {
    assert x in visitedEntry;
  }
  prefix_props(g, n, start, stackBefore, stack);

  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))
  {
    assert w in visitedEntry;
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures g.adj[w][j] in visited || inStack(stack, g.adj[w][j])
    {
      var y := g.adj[w][j];
      assert y in visitedEntry || inStack(stackBefore, y);
      if y in visitedEntry {
        assert y in visited;
      } else {
        assert u in visitedEntry;
        if y == u {
          assert y in visitedEntry;
          assert false;
        }
        assert y != u;
        inStack_pop_bwd(stackBefore, y);
        assert inStack(stackBefore[..(|stackBefore| - 1)], y) || y == u;
        assert inStack(stackBefore[..(|stackBefore| - 1)], y);
        inStack_same(stackBefore[..(|stackBefore| - 1)], stack, y);
      }
    }
  }

  if start in visited {
  } else {
    assert start !in visitedEntry;
    assert inStack(stackBefore, start);
    assert start != u;
    inStack_pop_bwd(stackBefore, start);
    assert inStack(stackBefore[..(|stackBefore| - 1)], start);
    inStack_same(stackBefore[..(|stackBefore| - 1)], stack, start);
  }
  assert OuterInv(g, n, start, target, visited, stack);
}

lemma {:vcs_split_on_every_assert} pop_new(
  g: Graph, n: int, start: int, target: int,
  visitedEntry: set<int>, visited: set<int>,
  stackBefore: seq<int>, stack: seq<int>, u: int, i: int
)
  requires OuterInv(g, n, start, target, visitedEntry, stackBefore)
  requires |stackBefore| > 0
  requires u == stackBefore[|stackBefore| - 1]
  requires u !in visitedEntry
  requires u != target
  requires visited == visitedEntry + {u}
  requires stack == stackBefore[..(|stackBefore| - 1)]
  requires i == 0
  ensures PartialInv(g, n, start, target, visited, visitedEntry, stack, u, i)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert target !in visitedEntry;
  assert forall x :: x in visitedEntry ==> 0 <= x < n;
  assert forall x :: x in visitedEntry ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stackBefore| ==> 0 <= stackBefore[k] < n;
  assert forall k :: 0 <= k < |stackBefore| ==> reachable(g, start, stackBefore[k]);
  assert forall w :: w in visitedEntry ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visitedEntry || inStack(stackBefore, g.adj[w][j]));
  assert start in visitedEntry || inStack(stackBefore, start);

  assert 0 <= |stackBefore| - 1 < |stackBefore|;
  assert 0 <= stackBefore[|stackBefore| - 1] < n;
  assert reachable(g, start, stackBefore[|stackBefore| - 1]);
  assert 0 <= u < n;
  assert 0 <= u < |g.adj|;
  assert reachable(g, start, u);
  assert u in visited;
  assert visited == visitedEntry + {u};
  if target in visited {
    assert target == u || target in visitedEntry;
    assert false;
  }
  assert target !in visited;
  assert 0 <= i <= |g.adj[u]|;

  forall x | x in visited
    ensures 0 <= x < n
  {
    assert x == u || x in visitedEntry;
    if x == u {
      assert 0 <= u < n;
    } else {
      assert x in visitedEntry;
    }
  }
  forall x | x in visited
    ensures reachable(g, start, x)
  {
    assert x == u || x in visitedEntry;
    if x == u {
      assert reachable(g, start, u);
    } else {
      assert x in visitedEntry;
    }
  }
  prefix_props(g, n, start, stackBefore, stack);

  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))
  {
    assert w == u || w in visitedEntry;
    if w == u {
      assert 0 <= w < |g.adj|;
    } else {
      assert w in visitedEntry;
      assert 0 <= w < n;
      assert 0 <= w < |g.adj|;
    }
    forall j | 0 <= j < |g.adj[w]|
      ensures (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j])
    {
      var y := g.adj[w][j];
      if w == u {
        assert i == 0;
        assert 0 <= j;
        assert j >= i;
      } else {
        assert w in visitedEntry;
        assert y in visitedEntry || inStack(stackBefore, y);
        if y in visitedEntry {
          assert y in visited;
        } else {
          inStack_pop_bwd(stackBefore, y);
          if y == u {
            assert y in visited;
          } else {
            assert inStack(stackBefore[..(|stackBefore| - 1)], y) || y == u;
            assert y != u;
            assert inStack(stackBefore[..(|stackBefore| - 1)], y);
            inStack_same(stackBefore[..(|stackBefore| - 1)], stack, y);
          }
        }
      }
    }
  }

  if start in visitedEntry {
    assert start in visited;
  } else if start == u {
    assert start in visited;
  } else {
    assert inStack(stackBefore, start);
    inStack_pop_bwd(stackBefore, start);
    assert start != u;
    assert inStack(stackBefore[..(|stackBefore| - 1)], start) || start == u;
    assert inStack(stackBefore[..(|stackBefore| - 1)], start);
    inStack_same(stackBefore[..(|stackBefore| - 1)], stack, start);
  }
