    invariant exists j :: i <= j < |g.adj[u]| && g.adj[u][j] == v
    decreases |g.adj[u]| - i
  {
    if g.adj[u][i] == v {
      e := i;
      assert 0 <= e < |g.adj[u]| && g.adj[u][e] == v;
      return;
    }
    var oldI := i;
    assert g.adj[u][oldI] != v;
    ExistsShift(g.adj[u], oldI, v);
    assert exists j :: oldI + 1 <= j < |g.adj[u]| && g.adj[u][j] == v;
    assert forall j :: 0 <= j < oldI ==> g.adj[u][j] != v;
    i := oldI + 1;
    forall j | 0 <= j < i
      ensures g.adj[u][j] != v
    {
      if j < oldI {
        assert g.adj[u][j] != v;
      } else {
        assert j == oldI;
        assert g.adj[u][j] != v;
      }
    }
    assert exists j :: i <= j < |g.adj[u]| && g.adj[u][j] == v;
  }
  assert i == |g.adj[u]|;
  var j0 :| i <= j0 < |g.adj[u]| && g.adj[u][j0] == v;
  assert false;
}

lemma PathExtend(g: Graph, p: seq<int>, v: int)
  requires is_path(g, p)
  requires has_edge(g, p[|p| - 1], v)
  ensures is_path(g, p + [v])
  ensures (p + [v])[0] == p[0]
  ensures (p + [v])[|p + [v]| - 1] == v
  ensures |p + [v]| == |p| + 1
{
  var q := p + [v];
  forall i | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    if i < |p| - 1 {
      assert q[i] == p[i];
      assert q[i + 1] == p[i + 1];
      assert has_edge(g, p[i], p[i + 1]);
    } else {
      assert i == |p| - 1;
      assert q[i] == p[|p| - 1];
      assert q[i + 1] == v;
    }
  }
}

lemma PrefixIsPath(g: Graph, p: seq<int>, t: int)
  requires is_path(g, p)
  requires 1 <= t <= |p|
  ensures is_path(g, p[..t])
  ensures |p[..t]| == t
  ensures (p[..t])[0] == p[0]
  ensures (p[..t])[t - 1] == p[t - 1]
{
  var q := p[..t];
  forall i | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    assert q[i] == p[i];
    assert q[i + 1] == p[i + 1];
    assert 0 <= i < |p| - 1;
    assert has_edge(g, p[i], p[i + 1]);
  }
}

lemma PathNodesInRange(g: Graph, p: seq<int>, start: int)
  requires well_formed(g)
  requires is_path(g, p)
  requires 0 <= start < |g.adj|
  requires p[0] == start
  ensures forall k :: 0 <= k < |p| ==> 0 <= p[k] < |g.adj|
{
  var k := 0;
  while k < |p|
    invariant 0 <= k <= |p|
    invariant forall j :: 0 <= j < k ==> 0 <= p[j] < |g.adj|
    decreases |p| - k
  {
    if k == 0 {
      assert p[0] == start;
      assert 0 <= p[0] < |g.adj|;
    } else {
      assert 0 <= p[k - 1] < |g.adj|;
      assert has_edge(g, p[k - 1], p[k]);
      var e := GetEdge(g, p[k - 1], p[k]);
      NbrRange(g, p[k - 1], e);
      assert g.adj[p[k - 1]][e] == p[k];
      assert 0 <= p[k] < |g.adj|;
    }
    k := k + 1;
  }
}

lemma FirstUnvisitedIndex(dist: seq<int>, p: seq<int>) returns (t: int)
  requires |p| >= 1
  requires forall k :: 0 <= k < |p| ==> 0 <= p[k] < |dist|
  requires dist[p[0]] >= 0
  requires dist[p[|p| - 1]] < 0
  ensures 0 < t < |p|
  ensures dist[p[t]] < 0
  ensures forall j :: 0 <= j < t ==> dist[p[j]] >= 0
{
  t := 0;
  while t < |p| && dist[p[t]] >= 0
    invariant 0 <= t <= |p|
    invariant forall j :: 0 <= j < t ==> dist[p[j]] >= 0
    decreases |p| - t
  {
    t := t + 1;
  }
  if t == |p| {
    assert dist[p[|p| - 1]] >= 0;
    assert false;
  }
  assert t < |p|;
  assert dist[p[t]] < 0;
  if t == 0 {
    assert dist[p[0]] < 0;
    assert false;
  }
}

lemma QIndex(dist: seq<int>, queue: seq<int>, qpos: seq<int>, i: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= i < |queue|
  ensures 0 <= queue[i] < |dist|
  ensures dist[queue[i]] >= 0
  ensures qpos[queue[i]] == i
{
  assert 0 <= queue[i] < |dist| && dist[queue[i]] >= 0 && qpos[queue[i]] == i;
}

lemma QAt(dist: seq<int>, queue: seq<int>, qpos: seq<int>, v: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= v < |dist|
  requires dist[v] >= 0
  ensures 0 <= qpos[v] < |queue|
  ensures queue[qpos[v]] == v
{
  assert 0 <= qpos[v] < |queue| && queue[qpos[v]] == v;
}

lemma QCount(dist: seq<int>, queue: seq<int>, qpos: seq<int>)
  requires QInv(dist, queue, qpos)
  ensures |qpos| == |dist|
  ensures |queue| + CountNeg(dist, 0) == |dist|
  ensures |queue| <= |dist|
{
  CountBound(|queue|, CountNeg(dist, 0), |dist|);
}

lemma LayerHead(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  ensures 0 <= queue[head] < |dist|
  ensures layer <= dist[queue[head]] <= layer + 1
{
  assert 0 <= queue[head] < |dist|;
  assert layer <= dist[queue[head]] && dist[queue[head]] <= layer + 1;
}

lemma LayerBump(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  requires dist[queue[head]] == layer + 1
  ensures LayerInv(dist, queue, head, layer + 1)
{
  forall i | head <= i < |queue|
    ensures dist[queue[i]] == layer + 1
  {
    assert dist[queue[head]] == layer + 1;
    assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
    if i > head {
      assert dist[queue[head]] <= dist[queue[i]];
    }
  }
  assert layer + 1 >= 0;
  forall i | 0 <= i < head
    ensures dist[queue[i]] <= layer + 1
  {
    assert dist[queue[i]] <= layer;
  }
  forall i | head <= i < |queue|
    ensures layer + 1 <= dist[queue[i]] && dist[queue[i]] <= layer + 2
  {
    assert dist[queue[i]] == layer + 1;
  }
}

lemma LayerDequeue(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  requires dist[queue[head]] == layer
  ensures LayerInv(dist, queue, head + 1, layer)
{
  forall i | 0 <= i < head + 1
    ensures dist[queue[i]] <= layer
  {
    if i < head {
      assert dist[queue[i]] <= layer;
    } else {
      assert i == head;
      assert dist[queue[i]] == layer;
    }
  }
  forall i | head + 1 <= i < |queue|
    ensures layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1
  {
    assert head <= i < |queue|;
    assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
  }
}

lemma MinPath(g: Graph, start: int, dist: seq<int>, u: int, r: seq<int>)
  requires AllMinDist(g, start, dist)
  requires 0 <= u < |dist|
  requires dist[u] >= 0
  requires is_path(g, r)
  requires r[0] == start
  requires r[|r| - 1] == u
  ensures |r| >= dist[u] + 1
{
  assert forall vv {:trigger dist[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    forall rr: seq<int> {:trigger is_path(g, rr)} ::
      is_path(g, rr) && rr[0] == start && rr[|rr| - 1] == vv ==> |rr| >= dist[vv] + 1;
  assert is_path(g, r);
  assert dist[u] >= 0;
  assert |r| >= dist[u] + 1;
}

lemma WitnessFacts(g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>, v: int)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= v < |dist|
  requires dist[v] >= 0
  ensures is_path(g, wits[v])
  ensures wits[v][0] == start
  ensures |wits[v]| == dist[v] + 1
  ensures wits[v][|wits[v]| - 1] == v
{
  assert forall vv {:trigger wits[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    is_path(g, wits[vv])
    && wits[vv][0] == start
    && |wits[vv]| == dist[vv] + 1
    && wits[vv][|wits[vv]| - 1] == vv;
  assert wits[v] == wits[v];
  assert dist[v] >= 0;
  assert is_path(g, wits[v]);
  assert wits[v][0] == start;
  assert |wits[v]| == dist[v] + 1;
  assert wits[v][|wits[v]| - 1] == v;
}

lemma ExpandedAt(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, i: int, e: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= i < upto
  requires 0 <= e < |g.adj[queue[i]]|
  ensures 0 <= queue[i] < |g.adj|
  ensures 0 <= g.adj[queue[i]][e] < |dist|
  ensures dist[g.adj[queue[i]][e]] >= 0
{
  assert 0 <= i < |queue|;
  assert 0 <= queue[i] < |g.adj|;
  assert 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0;
}

lemma DistFromAt(dist: seq<int>, queue: seq<int>, from: int, layer: int, i: int)
  requires DistFrom(dist, queue, from, layer)
  requires from <= i < |queue|
  ensures 0 <= queue[i] < |dist|
  ensures dist[queue[i]] >= layer
{
  assert dist[queue[i]] >= layer;
}

lemma EnsureDistFrom(dist: seq<int>, queue: seq<int>, head: int, layer: int, u: int)
  requires LayerInv(dist, queue, head, layer)
  requires 1 <= head <= |queue|
  requires queue[head - 1] == u
  requires 0 <= u < |dist|
  requires dist[u] == layer
  ensures DistFrom(dist, queue, head - 1, layer)
{
  assert 0 <= head - 1 <= |queue|;
  forall i | 0 <= i < |queue|
    ensures 0 <= queue[i] < |dist|
  {
    assert 0 <= queue[i] < |dist|;
  }
  forall i | head - 1 <= i < |queue|
    ensures dist[queue[i]] >= layer
  {
    if i == head - 1 {
      assert queue[i] == u;
      assert dist[queue[i]] == layer;
    } else {
      assert head <= i;
      assert layer <= dist[queue[i]];
    }
  }
}

lemma UnvisitedPathLowerBound(
    g: Graph, start: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>,
    head: int, layer: int, x: int, p: seq<int>)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires dist[start] >= 0
  requires QInv(dist, queue, qpos)
  requires AllMinDist(g, start, dist)
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires DistFrom(dist, queue, head - 1, layer)
  requires 1 <= head
  requires 0 <= x < |dist| && dist[x] < 0
  requires is_path(g, p) && p[0] == start && p[|p| - 1] == x
  ensures |p| >= layer + 2
{
  PathNodesInRange(g, p, start);
  assert |dist| == |g.adj|;
  forall k | 0 <= k < |p|
    ensures 0 <= p[k] < |dist|
  {
    assert 0 <= p[k] < |g.adj|;
  }
  assert dist[p[0]] >= 0;
  assert p[|p| - 1] == x;
  assert dist[p[|p| - 1]] < 0;
  var t := FirstUnvisitedIndex(dist, p);
  var pred := p[t - 1];
  assert 0 <= pred < |dist|;
  assert dist[pred] >= 0;
  assert has_edge(g, pred, p[t]);
  QAt(dist, queue, qpos, pred);
  var ip := qpos[pred];
  assert queue[ip] == pred;

  if ip < head - 1 {
    var e := GetEdge(g, pred, p[t]);
    ExpandedAt(g, dist, queue, head - 1, ip, e);
    assert g.adj[queue[ip]][e] == p[t];
    assert dist[p[t]] >= 0;
    assert dist[p[t]] < 0;
    assert false;
  }
  assert ip >= head - 1;
  DistFromAt(dist, queue, head - 1, layer, ip);
  assert dist[pred] >= layer;

  PrefixIsPath(g, p, t);
  var prefix := p[..t];
  assert is_path(g, prefix);
  assert prefix[0] == start;
  assert prefix[|prefix| - 1] == pred;
  assert |prefix| == t;
  MinPath(g, start, dist, pred, prefix);
  assert t >= dist[pred] + 1;
  assert t >= layer + 1;
  assert |p| >= t + 1;
  assert |p| >= layer + 2;
}

lemma ProveNewMin(
    g: Graph, start: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>,
    head: int, layer: int, v: int)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires dist[start] >= 0
  requires QInv(dist, queue, qpos)
  requires AllMinDist(g, start, dist)
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires DistFrom(dist, queue, head - 1, layer)
  requires 1 <= head
  requires 0 <= v < |dist| && dist[v] < 0
  ensures forall r: seq<int> {:trigger is_path(g, r)} ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= layer + 2
{
  forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == v
    ensures |r| >= layer + 2
  {
    UnvisitedPathLowerBound(g, start, dist, queue, qpos, head, layer, v, r);
  }
}

lemma AllMinDistExtend(g: Graph, start: int, dist: seq<int>, v: int, newd: int)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires AllMinDist(g, start, dist)
  requires forall r: seq<int> {:trigger is_path(g, r)} ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= newd + 1
  ensures AllMinDist(g, start, dist[v := newd])
{
  var dist2 := dist[v := newd];
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures forall r: seq<int> {:trigger is_path(g, r)} ::
        is_path(g, r) && r[0] == start && r[|r| - 1] == u ==> |r| >= dist2[u] + 1
  {
    if u == v {
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        assert |r| >= newd + 1;
        assert dist2[u] == newd;
      }
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        MinPath(g, start, dist, u, r);
        assert dist[u] == dist2[u];
      }
    }
  }
}

lemma AllWitnessExtend(
    g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>,
    v: int, newd: int, newPath: seq<int>)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires |newPath| == newd + 1
  requires is_path(g, newPath)
  requires newPath[0] == start
  requires newPath[|newPath| - 1] == v
  ensures AllWitness(g, start, dist[v := newd], wits[v := newPath])
{
  var dist2 := dist[v := newd];
  var wit2 := wits[v := newPath];
  assert |wit2| == |wits|;
  assert |dist2| == |dist|;
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures is_path(g, wit2[u])
      && wit2[u][0] == start
      && |wit2[u]| == dist2[u] + 1
      && wit2[u][|wit2[u]| - 1] == u
  {
    if u == v {
      assert wit2[u] == newPath;
      assert dist2[u] == newd;
      assert |newPath| > 0;
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      assert wit2[u] == wits[u];
      WitnessFacts(g, start, dist, wits, u);
    }
  }
}

lemma QInvEnqueue(dist: seq<int>, queue: seq<int>, qpos: seq<int>, v: int, newd: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures QInv(dist[v := newd], queue + [v], qpos[v := |queue|])
  ensures |queue| < |dist|
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  var qpos2 := qpos[v := |queue|];
  QCount(dist, queue, qpos);
  CountNegAtLeast(dist, 0, v);
  assert CountNeg(dist, 0) >= 1;
  assert |queue| + CountNeg(dist, 0) == |dist|;
  assert |queue| <= |dist| - 1;
  CountNegFlip(dist, 0, v, newd);
  assert CountNeg(dist2, 0) + 1 == CountNeg(dist, 0);
  assert |queue2| == |queue| + 1;
  assert |dist2| == |dist|;
  assert |queue2| + CountNeg(dist2, 0) == |dist2|;
  assert |qpos2| == |qpos|;
  assert |qpos| == |dist|;
  assert |qpos2| == |dist2|;

  forall i | 0 <= i < |queue|
    ensures queue[i] != v
  {
    QIndex(dist, queue, qpos, i);
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
  }

  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2| && dist2[queue2[i]] >= 0 && qpos2[queue2[i]] == i
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert queue[i] != v;
      QIndex(dist, queue, qpos, i);
      assert dist2[queue[i]] == dist[queue[i]];
      assert qpos2[queue[i]] == qpos[queue[i]];
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == newd;
      assert qpos2[v] == |queue|;
    }
  }

  forall x | 0 <= x < |dist|
    ensures (dist2[x] >= 0 ==> 0 <= qpos2[x] < |queue2| && queue2[qpos2[x]] == x)
         && (dist2[x] < 0 ==> dist2[x] == -1 && qpos2[x] == -1)
  {
    if x == v {
      assert dist2[v] == newd >= 0;
      assert qpos2[v] == |queue|;
      assert queue2[|queue|] == v;
    } else if dist[x] >= 0 {
      QAt(dist, queue, qpos, x);
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
      var ix := qpos[x];
      assert ix < |queue|;
      assert queue2[ix] == queue[ix];
      assert queue[ix] == x;
    } else {
      assert dist[x] == -1;
      assert qpos[x] == -1;
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
    }
  }
}

lemma LayerEnqueue(dist: seq<int>, queue: seq<int>, head: int, layer: int, v: int, newd: int)
  requires LayerInv(dist, queue, head, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd == layer + 1
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures LayerInv(dist[v := newd], queue + [v], head, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[queue[i]] >= 0;
      assert dist[v] >= 0;
      assert false;
    }
  }
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |dist|;
    } else {
      assert queue2[i] == v;
    }
  }
  forall i | 0 <= i < head
    ensures dist2[queue2[i]] <= layer
  {
    assert i < |queue|;
    assert queue2[i] == queue[i];
    assert dist2[queue[i]] == dist[queue[i]];
    assert dist[queue[i]] <= layer;
  }
  forall i | head <= i < |queue2|
    ensures layer <= dist2[queue2[i]] && dist2[queue2[i]] <= layer + 1
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert dist2[queue[i]] == dist[queue[i]];
      assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == layer + 1;
    }
  }
  forall a, b | 0 <= a < b < |queue2|
    ensures dist2[queue2[a]] <= dist2[queue2[b]]
  {
    if b < |queue| {
      assert queue2[a] == queue[a] && queue2[b] == queue[b];
      assert dist2[queue[a]] == dist[queue[a]];
      assert dist2[queue[b]] == dist[queue[b]];
      assert dist[queue[a]] <= dist[queue[b]];
    } else {
      assert b == |queue|;
      assert queue2[b] == v;
      assert dist2[v] == layer + 1;
      assert a < |queue|;
      assert queue2[a] == queue[a];
      assert dist2[queue[a]] == dist[queue[a]];
      if a < head {
        assert dist[queue[a]] <= layer;
      } else {
        assert dist[queue[a]] <= layer + 1;
      }
    }
  }
}

lemma DistFromEnqueue(dist: seq<int>, queue: seq<int>, from: int, layer: int, v: int, newd: int)
  requires DistFrom(dist, queue, from, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= layer
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures DistFrom(dist[v := newd], queue + [v], from, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  assert |dist2| == |dist|;
  assert 0 <= from <= |queue|;
  assert from <= |queue2|;
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
    assert queue[i] != v;
    assert dist2[queue[i]] == dist[queue[i]];
  }
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |dist|;
    } else {
      assert queue2[i] == v;
      assert 0 <= v < |dist2|;
    }
  }
  forall i | from <= i < |queue2|
    ensures dist2[queue2[i]] >= layer
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert dist[queue[i]] >= layer;
      assert dist2[queue2[i]] == dist[queue[i]];
    } else {
      assert queue2[i] == v;
      assert dist2[v] == newd;
      assert newd >= layer;
    }
  }
}

lemma ExpandedPreserve(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, v: int, newd: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures ExpandedPrefix(g, dist[v := newd], queue, upto)
{
  var dist2 := dist[v := newd];
  forall i | 0 <= i < upto
    ensures forall e :: 0 <= e < |g.adj[queue[i]]| ==>
        0 <= g.adj[queue[i]][e] < |dist2| && dist2[g.adj[queue[i]][e]] >= 0
  {
    forall e | 0 <= e < |g.adj[queue[i]]|
      ensures 0 <= g.adj[queue[i]][e] < |dist2| && dist2[g.adj[queue[i]][e]] >= 0
    {
      ExpandedAt(g, dist, queue, upto, i, e);
      var nbr := g.adj[queue[i]][e];
      assert dist[nbr] >= 0;
      assert nbr != v;
      assert dist2[nbr] == dist[nbr];
    }
  }
}

lemma ExpandedPrefixAppend(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, v: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= v < |g.adj|
  ensures ExpandedPrefix(g, dist, queue + [v], upto)
{
  var queue2 := queue + [v];
  assert |dist| == |g.adj|;
  assert 0 <= upto <= |queue|;
  assert upto <= |queue2|;
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |g.adj|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |g.adj|;
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
    }
  }
  forall i | 0 <= i < upto
    ensures forall e :: 0 <= e < |g.adj[queue2[i]]| ==>
        0 <= g.adj[queue2[i]][e] < |dist| && dist[g.adj[queue2[i]][e]] >= 0
  {
    assert i < |queue|;
    assert queue2[i] == queue[i];
    forall e | 0 <= e < |g.adj[queue[i]]|
      ensures 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
    {
      ExpandedAt(g, dist, queue, upto, i, e);
    }
  }
}

lemma PrefixNbrsPreserve(g: Graph, dist: seq<int>, u: int, k: int, v: int, newd: int)
  requires PrefixNbrs(g, dist, u, k)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures PrefixNbrs(g, dist[v := newd], u, k)
{
  var dist2 := dist[v := newd];
  forall e | 0 <= e < k
    ensures 0 <= g.adj[u][e] < |dist2| && dist2[g.adj[u][e]] >= 0
  {
    assert 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0;
    var nbr := g.adj[u][e];
    assert nbr != v;
    assert dist2[nbr] == dist[nbr];
  }
}

lemma ExtendPrefixNbrs(g: Graph, dist: seq<int>, u: int, k: int)
  requires PrefixNbrs(g, dist, u, k)
  requires k < |g.adj[u]|
  requires 0 <= g.adj[u][k] < |dist|
  requires dist[g.adj[u][k]] >= 0
  ensures PrefixNbrs(g, dist, u, k + 1)
{
  forall e | 0 <= e < k + 1
    ensures 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0
  {
    if e < k {
      assert 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0;
    }
  }
}

lemma ExpandedMerge(g: Graph, dist: seq<int>, queue: seq<int>, head: int, u: int)
  requires |dist| == |g.adj|
  requires 1 <= head <= |queue|
  requires queue[head - 1] == u
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires PrefixNbrs(g, dist, u, |g.adj[u]|)
  ensures ExpandedPrefix(g, dist, queue, head)
{
  forall i | 0 <= i < head
    ensures forall e :: 0 <= e < |g.adj[queue[i]]| ==>
        0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
  {
    if i < head - 1 {
      forall e | 0 <= e < |g.adj[queue[i]]|
        ensures 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
      {
        ExpandedAt(g, dist, queue, head - 1, i, e);
      }
    } else {
      assert i == head - 1;
      assert queue[i] == u;
      forall e | 0 <= e < |g.adj[u]|
        ensures 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0
      {
        assert 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0;
      }
    }
  }
}

lemma NonnegQueue(dist: seq<int>, queue: seq<int>, qpos: seq<int>)
  requires QInv(dist, queue, qpos)
  ensures forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
{
  forall i | 0 <= i < |queue|
    ensures dist[queue[i]] >= 0
  {
    QIndex(dist, queue, qpos, i);
  }
}

lemma ToShortest(g: Graph, start: int, v: int, d: int, w: seq<int>)
  requires is_path(g, w)
  requires w[0] == start
  requires w[|w| - 1] == v
  requires |w| == d + 1
  requires forall r: seq<int> ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= d + 1
  ensures is_shortest_distance(g, start, v, d)
{
  assert is_path(g, w) && w[0] == start && w[|w| - 1] == v && |w| == d + 1;
}

lemma FinishSome(g: Graph, start: int, target: int, dist: seq<int>, wits: seq<seq<int>>)
  requires AllMinDist(g, start, dist)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= target < |dist|
  requires dist[target] >= 0
  ensures is_shortest_distance(g, start, target, dist[target])
{
  WitnessFacts(g, start, dist, wits, target);
  var w := wits[target];
  var d := dist[target];
  forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == target
    ensures |r| >= d + 1
  {
    MinPath(g, start, dist, target, r);
  }
  ToShortest(g, start, target, d, w);
}

lemma ClosureAt(g: Graph, dist: seq<int>, queue: seq<int>, qpos: seq<int>, u: int, e: int)
  requires |dist| == |g.adj|
  requires QInv(dist, queue, qpos)
  requires ExpandedPrefix(g, dist, queue, |queue|)
  requires 0 <= u < |dist| && dist[u] >= 0
  requires 0 <= e < |g.adj[u]|
  ensures dist[g.adj[u][e]] >= 0
  ensures 0 <= g.adj[u][e] < |dist|
{
  QAt(dist, queue, qpos, u);
  var i := qpos[u];
  assert queue[i] == u;
  assert 0 <= i < |queue|;
  ExpandedAt(g, dist, queue, |queue|, i, e);
}

lemma PathStaysVisited(g: Graph, start: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>, p: seq<int>)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires dist[start] >= 0
  requires QInv(dist, queue, qpos)
  requires ExpandedPrefix(g, dist, queue, |queue|)
  requires is_path(g, p)
  requires p[0] == start
  ensures forall k :: 0 <= k < |p| ==> 0 <= p[k] < |dist| && dist[p[k]] >= 0
{
  PathNodesInRange(g, p, start);
  var k := 0;
  while k < |p|
    invariant 0 <= k <= |p|
    invariant forall j :: 0 <= j < k ==> dist[p[j]] >= 0
    decreases |p| - k
  {
    assert 0 <= p[k] < |g.adj|;
    assert |dist| == |g.adj|;
    if k == 0 {
      assert p[0] == start;
      assert dist[p[0]] >= 0;
    } else {
      assert dist[p[k - 1]] >= 0;
      assert 0 <= p[k - 1] < |dist|;
      assert has_edge(g, p[k - 1], p[k]);
      var e := GetEdge(g, p[k - 1], p[k]);
      ClosureAt(g, dist, queue, qpos, p[k - 1], e);
      assert g.adj[p[k - 1]][e] == p[k];
      assert dist[p[k]] >= 0;
    }
    k := k + 1;
  }
  forall kk | 0 <= kk < |p|
    ensures 0 <= p[kk] < |dist| && dist[p[kk]] >= 0
  {
    assert 0 <= p[kk] < |g.adj|;
    assert dist[p[kk]] >= 0;
  }
}

lemma NotReachable(g: Graph, start: int, target: int)
  requires forall p: seq<int> {:trigger is_path(g, p)} ::
      is_path(g, p) && p[0] == start && p[|p| - 1] == target ==> false
  ensures !reachable(g, start, target)
{
  if reachable(g, start, target) {
    var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == target;
    assert is_path(g, p);
    assert false;
  }
}

lemma FinishNone(g: Graph, start: int, target: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires 0 <= target < |dist|
  requires dist[start] >= 0
  requires dist[target] < 0
  requires QInv(dist, queue, qpos)
  requires ExpandedPrefix(g, dist, queue, |queue|)
  ensures !reachable(g, start, target)
{
  forall p: seq<int> {:trigger is_path(g, p)} | is_path(g, p) && p[0] == start && p[|p| - 1] == target
    ensures false
  {
    PathStaysVisited(g, start, dist, queue, qpos, p);
    assert dist[p[|p| - 1]] >= 0;
    assert dist[target] >= 0;
    assert false;
  }
  NotReachable(g, start, target);
}

lemma SingletonPath(g: Graph, start: int)
  requires 0 <= start < |g.adj|
  ensures is_path(g, [start])
{
}

lemma InitState(g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>, qpos: seq<int>, queue: seq<int>)
  requires |g.adj| == |dist|
  requires |dist| == |wits|
  requires |wits| == |qpos|
  requires 0 <= start < |dist|
  requires queue == [start]
  requires forall j :: 0 <= j < |dist| ==> dist[j] == if j == start then 0 else -1
  requires forall j :: 0 <= j < |wits| ==> wits[j] == if j == start then [start] else []
  requires forall j :: 0 <= j < |qpos| ==> qpos[j] == if j == start then 0 else -1
  ensures QInv(dist, queue, qpos)
  ensures LayerInv(dist, queue, 0, 0)
  ensures AllMinDist(g, start, dist)
  ensures AllWitness(g, start, dist, wits)
  ensures ExpandedPrefix(g, dist, queue, 0)
  ensures dist[start] == 0
  ensures |queue| <= |dist|
{
  assert dist[start] == 0;
  assert forall j :: 0 <= j < |dist| && j != start ==> dist[j] < 0 by {
    forall j | 0 <= j < |dist| && j != start
      ensures dist[j] < 0
    {
      assert dist[j] == -1;
    }
  }
  CountNegInitFrom(dist, start, 0);
  assert CountNeg(dist, 0) == |dist| - 1;
  assert |queue| == 1;
  assert |queue| + CountNeg(dist, 0) == |dist|;
  CountBound(|queue|, CountNeg(dist, 0), |dist|);

  forall i | 0 <= i < |queue|
    ensures 0 <= queue[i] < |dist| && dist[queue[i]] >= 0 && qpos[queue[i]] == i
  {
    assert i == 0;
    assert queue[0] == start;
    assert dist[start] == 0;
    assert qpos[start] == 0;
  }
  forall v | 0 <= v < |dist|
    ensures (dist[v] >= 0 ==> 0 <= qpos[v] < |queue| && queue[qpos[v]] == v)
         && (dist[v] < 0 ==> dist[v] == -1 && qpos[v] == -1)
  {
    if v == start {
      assert dist[v] == 0;
      assert qpos[v] == 0;
      assert queue[0] == start;
    } else {
      assert dist[v] == -1;
      assert qpos[v] == -1;
    }
  }

  SingletonPath(g, start);
  forall v | 0 <= v < |dist| && dist[v] >= 0
    ensures forall r: seq<int> {:trigger is_path(g, r)} ::
        is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= dist[v] + 1
  {
    if v != start {
      assert dist[v] == -1;
      assert false;
    }
    assert v == start;
    assert dist[v] == 0;
    forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == v
      ensures |r| >= 1
    {
      assert |r| > 0;
    }
  }
  forall v | 0 <= v < |dist| && dist[v] >= 0
    ensures is_path(g, wits[v])
      && wits[v][0] == start
      && |wits[v]| == dist[v] + 1
      && wits[v][|wits[v]| - 1] == v
  {
    if v != start {
      assert dist[v] == -1;
      assert false;
    }
    assert v == start;
    assert wits[v] == [start];
    assert dist[v] == 0;
    assert is_path(g, [start]);
  }

  assert forall i :: 0 <= i < |queue| ==> 0 <= queue[i] < |dist| by {
    forall i | 0 <= i < |queue|
      ensures 0 <= queue[i] < |dist|
    {
      assert queue[i] == start;
    }
  }
}

lemma PrefixNbrsZero(g: Graph, dist: seq<int>, u: int)
  requires |dist| == |g.adj|
  requires 0 <= u < |g.adj|
  ensures PrefixNbrs(g, dist, u, 0)
{
}

method {:vcs_split_on_every_assert} bfs_shortest_path(graph: Graph, start: int, target: int) returns (res: Option<int>)
  requires well_formed(graph)
  requires size(graph) <= 10000
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures match res {
    case Some(dist) => is_shortest_distance(graph, start, target, dist)
    case None => !reachable(graph, start, target)
  }
{
  var n := |graph.adj|;
  assert n == size(graph);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert n >= 1;

  var distArr := new int[n];
  var bi := 0;
  while bi < n
    invariant 0 <= bi <= n
    invariant distArr.Length == n
    invariant forall j :: 0 <= j < bi ==> distArr[j] == -1
    decreases n - bi
  {
    distArr[bi] := -1;
    bi := bi + 1;
  }
  distArr[start] := 0;

  assert forall j :: 0 <= j < n ==> distArr[j] == if j == start then 0 else -1 by {
    forall j | 0 <= j < n
      ensures distArr[j] == if j == start then 0 else -1
    {
      if j == start {
        assert distArr[start] == 0;
      } else {
        assert distArr[j] == -1;
      }
    }
  }

  var dists := distArr[..];
  assert |dists| == n;
  forall j | 0 <= j < n
    ensures dists[j] == if j == start then 0 else -1
  {
    assert dists[j] == distArr[j];
    assert distArr[j] == if j == start then 0 else -1;
  }

  ghost var wits: seq<seq<int>> := seq(n, j => if j == start then [start] else []);
  ghost var qpos: seq<int> := seq(n, j => if j == start then 0 else -1);
  assert |wits| == n;
  assert |qpos| == n;
  forall j | 0 <= j < n
    ensures wits[j] == if j == start then [start] else []
  {
    if j == start {
      assert wits[j] == [start];
    } else {
      assert wits[j] == [];
    }
  }
  forall j | 0 <= j < n
    ensures qpos[j] == if j == start then 0 else -1
  {
    if j == start {
      assert qpos[j] == 0;
    } else {
      assert qpos[j] == -1;
    }
  }

  var queue: seq<int> := [start];
  var head: int := 0;
  var layer: int := 0;

  InitState(graph, start, dists, wits, qpos, queue);
  assert |queue| <= n;

  while head < |queue|
    invariant |dists| == n
    invariant |wits| == n
    invariant |qpos| == n
    invariant 0 <= head <= |queue| <= n
    invariant dists[start] == 0
    invariant layer >= 0
    invariant QInv(dists, queue, qpos)
    invariant LayerInv(dists, queue, head, layer)
    invariant AllMinDist(graph, start, dists)
    invariant AllWitness(graph, start, dists, wits)
    invariant ExpandedPrefix(graph, dists, queue, head)
    decreases n - head
  {
    LayerHead(dists, queue, head, layer);
    var u := queue[head];
    assert 0 <= u < n;
    assert layer <= dists[u] <= layer + 1;

    if dists[u] > layer {
      var oldLayer := layer;
      assert dists[u] == oldLayer + 1;
      LayerBump(dists, queue, head, oldLayer);
      assert LayerInv(dists, queue, head, oldLayer + 1);
      layer := oldLayer + 1;
      assert LayerInv(dists, queue, head, layer);
      assert dists[u] == layer;
    } else {
      assert dists[u] == layer;
    }
    assert dists[u] == layer;
    assert queue[head] == u;

    var oldHead := head;
    assert ExpandedPrefix(graph, dists, queue, oldHead);
    assert dists[queue[oldHead]] == layer;
    LayerDequeue(dists, queue, oldHead, layer);
    assert LayerInv(dists, queue, oldHead + 1, layer);
    head := oldHead + 1;
    assert head == oldHead + 1;
    assert head <= |queue|;
    assert LayerInv(dists, queue, head, layer);
    assert queue[head - 1] == u;
    assert ExpandedPrefix(graph, dists, queue, head - 1);
    assert dists[u] == layer;
    EnsureDistFrom(dists, queue, head, layer, u);
    assert DistFrom(dists, queue, head - 1, layer);

    var adj := graph.adj[u];
    var k := 0;
    PrefixNbrsZero(graph, dists, u);
    assert PrefixNbrs(graph, dists, u, 0);

    while k < |adj|
      invariant |dists| == n
      invariant |wits| == n
      invariant |qpos| == n
      invariant 1 <= head <= |queue| <= n
      invariant dists[start] == 0
      invariant layer >= 0
      invariant 0 <= u < n
      invariant queue[head - 1] == u
      invariant dists[u] == layer
      invariant adj == graph.adj[u]
      invariant 0 <= k <= |adj|
      invariant QInv(dists, queue, qpos)
      invariant LayerInv(dists, queue, head, layer)
      invariant AllMinDist(graph, start, dists)
      invariant AllWitness(graph, start, dists, wits)
      invariant ExpandedPrefix(graph, dists, queue, head - 1)
      invariant DistFrom(dists, queue, head - 1, layer)
      invariant PrefixNbrs(graph, dists, u, k)
      decreases |adj| - k
    {
      NbrRange(graph, u, k);
      var v := adj[k];
      assert adj[k] == graph.adj[u][k];
      assert 0 <= v < n;

      if dists[v] < 0 {
        ghost var distB := dists;
        ghost var witB := wits;
        ghost var qposB := qpos;
        ghost var queueB := queue;
        assert dists == distB;
        assert queue == queueB;
        assert wits == witB;
        assert qpos == qposB;
        assert |distB| == n;

        assert distB[v] < 0;
        assert distB[start] == 0;
        assert distB[u] == layer;
        assert u != v;
        assert v != start;
        ProveNewMin(graph, start, distB, queueB, qposB, head, layer, v);

        var newd := layer + 1;
        assert newd >= 0;
        WitnessFacts(graph, start, distB, witB, u);
        NbrEdge(graph, u, k);
        assert has_edge(graph, u, v);
        assert witB[u][|witB[u]| - 1] == u;
        assert has_edge(graph, witB[u][|witB[u]| - 1], v);
        PathExtend(graph, witB[u], v);
        ghost var newPath := witB[u] + [v];
        assert is_path(graph, newPath);
        assert newPath[0] == start;
        assert newPath[|newPath| - 1] == v;
        assert |witB[u]| == distB[u] + 1;
        assert |newPath| == |witB[u]| + 1;
        assert |newPath| == layer + 2;
        assert |newPath| == newd + 1;

        forall r: seq<int> {:trigger is_path(graph, r)} | is_path(graph, r) && r[0] == start && r[|r| - 1] == v
          ensures |r| >= newd + 1
        {
          assert |r| >= layer + 2;
        }
        AllMinDistExtend(graph, start, distB, v, newd);
        AllWitnessExtend(graph, start, distB, witB, v, newd, newPath);
        QInvEnqueue(distB, queueB, qposB, v, newd);
        NonnegQueue(distB, queueB, qposB);
        LayerEnqueue(distB, queueB, head, layer, v, newd);
        DistFromEnqueue(distB, queueB, head - 1, layer, v, newd);
        ExpandedPreserve(graph, distB, queueB, head - 1, v, newd);
        assert 0 <= v < |graph.adj|;
        ExpandedPrefixAppend(graph, distB[v := newd], queueB, head - 1, v);
        assert ExpandedPrefix(graph, distB[v := newd], queueB + [v], head - 1);
        PrefixNbrsPreserve(graph, distB, u, k, v, newd);

        assert dists == distB;
        assert wits == witB;
        assert qpos == qposB;
        assert queue == queueB;

        dists := distB[v := newd];
        wits := witB[v := newPath];
        ghost var newIndex := |queueB|;
        qpos := qposB[v := newIndex];
        queue := queueB + [v];

        assert dists == distB[v := newd];
        assert wits == witB[v := newPath];
        assert qpos == qposB[v := |queueB|];
        assert queue == queueB + [v];

        assert QInv(dists, queue, qpos);
        assert LayerInv(dists, queue, head, layer);
        assert AllMinDist(graph, start, dists);
        assert AllWitness(graph, start, dists, wits);
        assert ExpandedPrefix(graph, dists, queue, head - 1);
        assert DistFrom(dists, queue, head - 1, layer);
        assert PrefixNbrs(graph, dists, u, k);
        QCount(dists, queue, qpos);
        assert |queueB| < n;
        assert |queue| == |queueB| + 1;
        assert |queue| <= n;
        assert v != start;
        assert dists[start] == distB[start];
        assert dists[start] == 0;
        assert u != v;
        assert dists[u] == distB[u];
        assert dists[u] == layer;
        assert 0 <= head - 1 < |queueB|;
        assert queue[head - 1] == queueB[head - 1];
        assert queue[head - 1] == u;
      }
      assert dists[v] >= 0;
      assert 0 <= graph.adj[u][k] < n;
