lemma {:vcs_split_on_every_assert} push_ok(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stack0: seq<int>, u: int, i0: int, v: int,
  stack: seq<int>, i: int
)
  requires PartialInv(g, n, start, target, visited, visitedEntry, stack0, u, i0)
  requires 0 <= u < |g.adj|
  requires 0 <= i0 < |g.adj[u]|
  requires v == g.adj[u][i0]
  requires stack == stack0 + [v]
  requires i == i0 + 1
  ensures PartialInv(g, n, start, target, visited, visitedEntry, stack, u, i)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert u in visited;
  assert u !in visitedEntry;
  assert u != target;
  assert visited == visitedEntry + {u};
  assert target !in visited;
  assert forall x :: x in visited ==> 0 <= x < n;
  assert forall x :: x in visited ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stack0| ==> 0 <= stack0[k] < n;
  assert forall k :: 0 <= k < |stack0| ==> reachable(g, start, stack0[k]);
  assert forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      (w == u && j >= i0) || g.adj[w][j] in visited || inStack(stack0, g.adj[w][j]));
  assert start in visited || inStack(stack0, start);
  assert reachable(g, start, u);

  neighbor_in_range(g, u, i0);
  assert 0 <= v < |g.adj|;
  assert 0 <= v < n;
  edge_at(g, u, i0);
  assert has_edge(g, u, v);
  reach_step(g, start, u, v);
  assert reachable(g, start, v);

  assert 0 <= i0;
  assert i0 + 1 <= |g.adj[u]|;
  assert 0 <= i <= |g.adj[u]|;
  assert |stack| == |stack0| + 1;

  forall k | 0 <= k < |stack|
    ensures 0 <= stack[k] < n
  {
    if k < |stack0| {
      assert stack[k] == stack0[k];
    } else {
      assert k == |stack0|;
      assert stack[k] == v;
      assert 0 <= v < n;
    }
  }
  forall k | 0 <= k < |stack|
    ensures reachable(g, start, stack[k])
  {
    if k < |stack0| {
      assert stack[k] == stack0[k];
    } else {
      assert k == |stack0|;
      assert stack[k] == v;
      assert reachable(g, start, v);
    }
  }

  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))
  {
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j])
    {
      var y := g.adj[w][j];
      assert (w == u && j >= i0) || y in visited || inStack(stack0, y);
      if y in visited {
      } else if inStack(stack0, y) {
        inStack_push_fwd(stack0, v, y);
        inStack_same(stack0 + [v], stack, y);
      } else {
        assert w == u && j >= i0;
        if j >= i {
        } else {
          assert j < i;
          assert i == i0 + 1;
          assert j >= i0;
          assert j == i0;
          assert y == g.adj[w][j];
          assert y == g.adj[u][i0];
          assert y == v;
          inStack_push_fwd(stack0, v, y);
          inStack_same(stack0 + [v], stack, y);
        }
      }
    }
  }

  if start in visited {
  } else {
    assert inStack(stack0, start);
    inStack_push_fwd(stack0, v, start);
    inStack_same(stack0 + [v], stack, start);
  }
  assert PartialInv(g, n, start, target, visited, visitedEntry, stack, u, i);
}

lemma {:vcs_split_on_every_assert} partial_to_outer(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, visitedEntry: set<int>,
  stack: seq<int>, u: int, i: int
)
  requires PartialInv(g, n, start, target, visited, visitedEntry, stack, u, i)
  requires 0 <= u < |g.adj|
  requires i == |g.adj[u]|
  ensures OuterInv(g, n, start, target, visited, stack)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert well_formed(g);
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert forall x :: x in visited ==> 0 <= x < n;
  assert forall k :: 0 <= k < |stack| ==> 0 <= stack[k] < n;
  assert forall x :: x in visited ==> reachable(g, start, x);
  assert forall k :: 0 <= k < |stack| ==> reachable(g, start, stack[k]);
  assert target !in visited;
  assert start in visited || inStack(stack, start);
  assert forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      (w == u && j >= i) || g.adj[w][j] in visited || inStack(stack, g.adj[w][j]));

  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==>
        g.adj[w][j] in visited || inStack(stack, g.adj[w][j]))
  {
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures g.adj[w][j] in visited || inStack(stack, g.adj[w][j])
    {
      var y := g.adj[w][j];
      assert (w == u && j >= i) || y in visited || inStack(stack, y);
      if w == u && j >= i {
        assert j < |g.adj[w]|;
        assert |g.adj[w]| == |g.adj[u]|;
        assert j < |g.adj[u]|;
        assert i == |g.adj[u]|;
        assert j >= |g.adj[u]|;
        assert false;
      }
      assert y in visited || inStack(stack, y);
    }
  }
  assert OuterInv(g, n, start, target, visited, stack);
}

