  assert exists k :: 0 <= k < |stack| && stack[k] == start;
  assert inStack(stack, start);
  forall k | 0 <= k < |stack|
    ensures 0 <= stack[k] < n
  {
    assert |stack| == 1;
    assert k == 0;
    assert stack[k] == start;
    assert 0 <= start < n;
  }
  forall k | 0 <= k < |stack|
    ensures reachable(g, start, stack[k])
  {
    assert |stack| == 1;
