lemma {:vcs_split_on_every_assert} conclude_unreachable(
  g: Graph, n: int, start: int, target: int,
  visited: set<int>, stack: seq<int>
)
  requires OuterInv(g, n, start, target, visited, stack)
  requires |stack| == 0
  ensures !reachable(g, start, target)
{
  assert 0 <= n;
  assert n == |g.adj|;
  assert 0 <= start < n;
  assert 0 <= target < n;
  assert 0 <= start < |g.adj|;
  assert 0 <= target < |g.adj|;
  assert target !in visited;
  assert start in visited || inStack(stack, start);
  assert forall w :: w in visited ==>
    0 <= w < |g.adj| &&
    (forall j :: 0 <= j < |g.adj[w]| ==>
      g.adj[w][j] in visited || inStack(stack, g.adj[w][j]));
  assert |stack| == 0;

  if start !in visited {
    assert inStack(stack, start);
    inStack_nonempty(stack, start);
    assert |stack| > 0;
    assert false;
  }
  assert start in visited;

  forall w | w in visited
    ensures 0 <= w < |g.adj| &&
      (forall j :: 0 <= j < |g.adj[w]| ==> g.adj[w][j] in visited)
  {
    assert 0 <= w < |g.adj|;
    forall j | 0 <= j < |g.adj[w]|
      ensures g.adj[w][j] in visited
    {
      var y := g.adj[w][j];
      assert y in visited || inStack(stack, y);
      if inStack(stack, y) {
        inStack_nonempty(stack, y);
        assert |stack| > 0;
        assert false;
      }
      assert y in visited;
    }
  }
  assert IndexClosed(g, visited);
  not_reachable_outside(g, start, target, visited);
  assert !reachable(g, start, target);
}

method {:vcs_split_on_every_assert} dfs_check_reachability(graph: Graph, start: int, target: int) returns (res: bool)
  requires well_formed(graph)
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures res == reachable(graph, start, target)
{
  assert size(graph) == |graph.adj|;
  var n := |graph.adj|;
  assert 0 <= n;
  assert 0 <= start < n;
  assert 0 <= target < n;
  var visited: set<int> := {};
  var stack: seq<int> := [start];
  init_inv(graph, n, start, target, visited, stack);

  while |stack| > 0
    invariant 0 <= n
    invariant OuterInv(graph, n, start, target, visited, stack)
    decreases unvisitedCount(n, visited), |stack|
  {
    ghost var oldLen: int := |stack|;
    ghost var oldCount: nat := unvisitedCount(n, visited);
    assert |stack| > 0;
    assert 0 <= |stack| - 1 < |stack|;
    var u := stack[|stack| - 1];
    if u == target {
      found_target(graph, n, start, target, visited, stack, u);
      assert reachable(graph, start, target);
      return true;
    }

    ghost var stackBefore := stack;
    ghost var visitedEntry := visited;
    assert |stackBefore| > 0;
    assert |stackBefore| == oldLen;
    assert u == stackBefore[|stackBefore| - 1];
    assert visited == visitedEntry;
    assert unvisitedCount(n, visitedEntry) == oldCount;
    assert u != target;
    outer_copy(graph, n, start, target, visited, stack, visitedEntry, stackBefore);

    stack := stack[..(|stack| - 1)];
    assert stack == stackBefore[..(|stackBefore| - 1)];

    if u in visited {
      assert visited == visitedEntry;
      assert u in visitedEntry;
      pop_seen(graph, n, start, target, visited, visitedEntry, stackBefore, stack, u);
      assert OuterInv(graph, n, start, target, visited, stack);
      assert |stackBefore| == oldLen;
      assert |stack| == |stackBefore| - 1;
      assert |stack| == oldLen - 1;
      assert |stack| < oldLen;
      assert visited == visitedEntry;
      assert unvisitedCount(n, visited) == unvisitedCount(n, visitedEntry);
      assert unvisitedCount(n, visited) == oldCount;
    } else {
      assert visited == visitedEntry;
      assert u !in visited;
      assert u !in visitedEntry;
      visited := visited + {u};
      assert visited == visitedEntry + {u};
      var i := 0;
      pop_new(graph, n, start, target, visitedEntry, visited, stackBefore, stack, u, i);
      assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert 0 <= u < |graph.adj|;
      assert 0 <= i <= |graph.adj[u]|;

      while i < |graph.adj[u]|
        invariant 0 <= u < |graph.adj|
        invariant 0 <= i <= |graph.adj[u]|
        invariant PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i)
        decreases |graph.adj[u]| - i
      {
        ghost var stack0 := stack;
        ghost var i0 := i;
        assert i == i0;
        assert stack == stack0;
        assert 0 <= i0 < |graph.adj[u]|;
        partial_same(graph, n, start, target, visited, visitedEntry, stack, u, i, stack0, i0);
        var v := graph.adj[u][i];
        assert v == graph.adj[u][i0];
        stack := stack + [v];
        i := i + 1;
        assert stack == stack0 + [v];
        assert i == i0 + 1;
        push_ok(graph, n, start, target, visited, visitedEntry, stack0, u, i0, v, stack, i);
        assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
        assert 0 <= i <= |graph.adj[u]|;
        assert |graph.adj[u]| - i < |graph.adj[u]| - i0;
      }

      assert 0 <= i <= |graph.adj[u]|;
      assert i == |graph.adj[u]|;
      partial_to_outer(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert OuterInv(graph, n, start, target, visited, stack);
      assert PartialInv(graph, n, start, target, visited, visitedEntry, stack, u, i);
      assert u !in visitedEntry;
      assert visited == visitedEntry + {u};
      assert 0 <= u < n;
      count_shrink(n, visitedEntry, u);
      assert unvisitedCount(n, visitedEntry) == unvisitedCount(n, visitedEntry + {u}) + 1;
      assert unvisitedCount(n, visited) == unvisitedCount(n, visitedEntry + {u});
      assert unvisitedCount(n, visitedEntry) == unvisitedCount(n, visited) + 1;
      assert unvisitedCount(n, visited) < unvisitedCount(n, visitedEntry);
      assert unvisitedCount(n, visitedEntry) == oldCount;
      assert unvisitedCount(n, visited) < oldCount;
    }
  }

  assert |stack| == 0;
  conclude_unreachable(graph, n, start, target, visited, stack);
  assert !reachable(graph, start, target);
  return false;
