lemma MaximumFlowExists(
    graph: CapacityGraph,
    s: int,
    t: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: is_max_flow(view(graph), f, s, t)
{
    var g := view(graph);
    var bound := |g[s]| * 100_000;

    EmptyFlowValid(g, s, t);
    assert 0 <= bound;

    ghost var attainable: set<int> :=
        set value: int |
            0 <= value <= bound
            && (exists f: FlowMap ::
                is_valid_flow(g, f, s, t)
                && flow_val(g, f, s) == value)
        :: value;

    assert 0 in attainable by
    {
        assert is_valid_flow(g, map[], s, t);
        assert flow_val(g, map[], s) == 0;
    }

    ghost var maximum := SetMaximum(attainable);
    assert maximum in attainable;
    assert 0 <= maximum <= bound;
    assert exists f: FlowMap ::
        is_valid_flow(g, f, s, t)
        && flow_val(g, f, s) == maximum;

    ghost var best :|
        is_valid_flow(g, best, s, t)
        && flow_val(g, best, s) == maximum;

    assert forall other: FlowMap
        {:trigger is_valid_flow(g, other, s, t)} ::
        is_valid_flow(g, other, s, t)
        ==> flow_val(g, best, s) >= flow_val(g, other, s) by
    {
        forall other: FlowMap |
            is_valid_flow(g, other, s, t)
            ensures flow_val(g, best, s) >= flow_val(g, other, s)
        {
            FlowValueUpperBound(g, other, s, t);

            if flow_val(g, other, s) >= 0 {
                assert flow_val(g, other, s) in attainable by
                {
                    assert 0 <= flow_val(g, other, s) <= bound;
                    assert exists f: FlowMap ::
                        is_valid_flow(g, f, s, t)
                        && flow_val(g, f, s)
                            == flow_val(g, other, s);
                }

                assert flow_val(g, other, s) <= maximum;
            } else {
                assert 0 <= maximum;
            }
        }
    }

    assert is_max_flow(g, best, s, t);
}

