lemma GetEdge(g: Graph, u: int, v: int) returns (e: int)
  requires 0 <= u < |g.adj|
  requires has_edge(g, u, v)
  ensures 0 <= e < |g.adj[u]| && g.adj[u][e] == v
{
  HasEdgeExists(g, u, v);
  e := 0;
  var i := 0;
  while i < |g.adj[u]|
    invariant 0 <= i <= |g.adj[u]|
    invariant forall j :: 0 <= j < i ==> g.adj[u][j] != v
    invariant exists j :: i <= j < |g.adj[u]| && g.adj[u][j] == v
    decreases |g.adj[u]| - i
  {
    if g.adj[u][i] == v {
      e := i;
      assert 0 <= e < |g.adj[u]| && g.adj[u][e] == v;
      return;
    }
    var oldI := i;
    assert g.adj[u][oldI] != v;
    ExistsShift(g.adj[u], oldI, v);
    assert exists j :: oldI + 1 <= j < |g.adj[u]| && g.adj[u][j] == v;
    assert forall j :: 0 <= j < oldI ==> g.adj[u][j] != v;
    i := oldI + 1;
    forall j | 0 <= j < i
      ensures g.adj[u][j] != v
    {
      if j < oldI {
        assert g.adj[u][j] != v;
      } else {
        assert j == oldI;
        assert g.adj[u][j] != v;
      }
    }
    assert exists j :: i <= j < |g.adj[u]| && g.adj[u][j] == v;
  }
  assert i == |g.adj[u]|;
  var j0 :| i <= j0 < |g.adj[u]| && g.adj[u][j0] == v;
  assert false;
}

