    } else {
      assert i == head - 1;
      assert queue[i] == u;
      forall e | 0 <= e < |g.adj[u]|
        ensures 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0
      {
        assert 0 <= g.adj[u][e] < |dist| && dist[g.adj[u][e]] >= 0;
