lemma InitState(g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>, qpos: seq<int>, queue: seq<int>)
  requires |g.adj| == |dist|
  requires |dist| == |wits|
  requires |wits| == |qpos|
  requires 0 <= start < |dist|
  requires queue == [start]
  requires forall j :: 0 <= j < |dist| ==> dist[j] == if j == start then 0 else -1
  requires forall j :: 0 <= j < |wits| ==> wits[j] == if j == start then [start] else []
  requires forall j :: 0 <= j < |qpos| ==> qpos[j] == if j == start then 0 else -1
  ensures QInv(dist, queue, qpos)
  ensures LayerInv(dist, queue, 0, 0)
  ensures AllMinDist(g, start, dist)
  ensures AllWitness(g, start, dist, wits)
  ensures ExpandedPrefix(g, dist, queue, 0)
  ensures dist[start] == 0
  ensures |queue| <= |dist|
{
  assert dist[start] == 0;
  assert forall j :: 0 <= j < |dist| && j != start ==> dist[j] < 0 by {
    forall j | 0 <= j < |dist| && j != start
      ensures dist[j] < 0
    {
      assert dist[j] == -1;
    }
  }
  CountNegInitFrom(dist, start, 0);
  assert CountNeg(dist, 0) == |dist| - 1;
  assert |queue| == 1;
  assert |queue| + CountNeg(dist, 0) == |dist|;
