    ensures has_edge(g, q[i], q[i + 1])
  {
    assert q[i] == p[i];
    assert q[i + 1] == p[i + 1];
    assert 0 <= i < |p| - 1;
    assert has_edge(g, p[i], p[i + 1]);
  }
}

lemma PathNodesInRange(g: Graph, p: seq<int>, start: int)
  requires well_formed(g)
  requires is_path(g, p)
  requires 0 <= start < |g.adj|
  requires p[0] == start
  ensures forall k :: 0 <= k < |p| ==> 0 <= p[k] < |g.adj|
{
  var k := 0;
  while k < |p|
    invariant 0 <= k <= |p|
    invariant forall j :: 0 <= j < k ==> 0 <= p[j] < |g.adj|
    decreases |p| - k
  {
    if k == 0 {
      assert p[0] == start;
      assert 0 <= p[0] < |g.adj|;
    } else {
      assert 0 <= p[k - 1] < |g.adj|;
      assert has_edge(g, p[k - 1], p[k]);
      var e := GetEdge(g, p[k - 1], p[k]);
      NbrRange(g, p[k - 1], e);
      assert g.adj[p[k - 1]][e] == p[k];
      assert 0 <= p[k] < |g.adj|;
    }
    k := k + 1;
  }
}

lemma FirstUnvisitedIndex(dist: seq<int>, p: seq<int>) returns (t: int)
  requires |p| >= 1
  requires forall k :: 0 <= k < |p| ==> 0 <= p[k] < |dist|
  requires dist[p[0]] >= 0
  requires dist[p[|p| - 1]] < 0
  ensures 0 < t < |p|
  ensures dist[p[t]] < 0
  ensures forall j :: 0 <= j < t ==> dist[p[j]] >= 0
{
  t := 0;
  while t < |p| && dist[p[t]] >= 0
    invariant 0 <= t <= |p|
    invariant forall j :: 0 <= j < t ==> dist[p[j]] >= 0
    decreases |p| - t
  {
    t := t + 1;
  }
  if t == |p| {
    assert dist[p[|p| - 1]] >= 0;
    assert false;
  }
  assert t < |p|;
  assert dist[p[t]] < 0;
  if t == 0 {
    assert dist[p[0]] < 0;
    assert false;
  }
}

lemma QIndex(dist: seq<int>, queue: seq<int>, qpos: seq<int>, i: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= i < |queue|
  ensures 0 <= queue[i] < |dist|
  ensures dist[queue[i]] >= 0
  ensures qpos[queue[i]] == i
{
  assert 0 <= queue[i] < |dist| && dist[queue[i]] >= 0 && qpos[queue[i]] == i;
}

lemma QAt(dist: seq<int>, queue: seq<int>, qpos: seq<int>, v: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= v < |dist|
  requires dist[v] >= 0
  ensures 0 <= qpos[v] < |queue|
  ensures queue[qpos[v]] == v
{
  assert 0 <= qpos[v] < |queue| && queue[qpos[v]] == v;
}

lemma QCount(dist: seq<int>, queue: seq<int>, qpos: seq<int>)
  requires QInv(dist, queue, qpos)
  ensures |qpos| == |dist|
  ensures |queue| + CountNeg(dist, 0) == |dist|
  ensures |queue| <= |dist|
{
  CountBound(|queue|, CountNeg(dist, 0), |dist|);
}

lemma LayerHead(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  ensures 0 <= queue[head] < |dist|
  ensures layer <= dist[queue[head]] <= layer + 1
{
  assert 0 <= queue[head] < |dist|;
  assert layer <= dist[queue[head]] && dist[queue[head]] <= layer + 1;
}

lemma LayerBump(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  requires dist[queue[head]] == layer + 1
  ensures LayerInv(dist, queue, head, layer + 1)
{
  forall i | head <= i < |queue|
    ensures dist[queue[i]] == layer + 1
  {
    assert dist[queue[head]] == layer + 1;
    assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
    if i > head {
      assert dist[queue[head]] <= dist[queue[i]];
    }
  }
  assert layer + 1 >= 0;
  forall i | 0 <= i < head
    ensures dist[queue[i]] <= layer + 1
  {
    assert dist[queue[i]] <= layer;
  }
  forall i | head <= i < |queue|
    ensures layer + 1 <= dist[queue[i]] && dist[queue[i]] <= layer + 2
  {
    assert dist[queue[i]] == layer + 1;
  }
}

lemma LayerDequeue(dist: seq<int>, queue: seq<int>, head: int, layer: int)
  requires LayerInv(dist, queue, head, layer)
  requires head < |queue|
  requires dist[queue[head]] == layer
  ensures LayerInv(dist, queue, head + 1, layer)
{
  forall i | 0 <= i < head + 1
    ensures dist[queue[i]] <= layer
  {
    if i < head {
      assert dist[queue[i]] <= layer;
    } else {
      assert i == head;
      assert dist[queue[i]] == layer;
    }
  }
  forall i | head + 1 <= i < |queue|
    ensures layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1
  {
    assert head <= i < |queue|;
    assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
  }
}

lemma MinPath(g: Graph, start: int, dist: seq<int>, u: int, r: seq<int>)
  requires AllMinDist(g, start, dist)
  requires 0 <= u < |dist|
  requires dist[u] >= 0
  requires is_path(g, r)
  requires r[0] == start
  requires r[|r| - 1] == u
  ensures |r| >= dist[u] + 1
{
  assert forall vv {:trigger dist[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    forall rr: seq<int> {:trigger is_path(g, rr)} ::
      is_path(g, rr) && rr[0] == start && rr[|rr| - 1] == vv ==> |rr| >= dist[vv] + 1;
  assert is_path(g, r);
  assert dist[u] >= 0;
  assert |r| >= dist[u] + 1;
}

lemma WitnessFacts(g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>, v: int)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= v < |dist|
  requires dist[v] >= 0
  ensures is_path(g, wits[v])
  ensures wits[v][0] == start
  ensures |wits[v]| == dist[v] + 1
  ensures wits[v][|wits[v]| - 1] == v
{
  assert forall vv {:trigger wits[vv]} :: 0 <= vv < |dist| && dist[vv] >= 0 ==>
    is_path(g, wits[vv])
    && wits[vv][0] == start
    && |wits[vv]| == dist[vv] + 1
    && wits[vv][|wits[vv]| - 1] == vv;
  assert wits[v] == wits[v];
  assert dist[v] >= 0;
  assert is_path(g, wits[v]);
  assert wits[v][0] == start;
  assert |wits[v]| == dist[v] + 1;
  assert wits[v][|wits[v]| - 1] == v;
}

lemma ExpandedAt(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, i: int, e: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= i < upto
  requires 0 <= e < |g.adj[queue[i]]|
  ensures 0 <= queue[i] < |g.adj|
  ensures 0 <= g.adj[queue[i]][e] < |dist|
  ensures dist[g.adj[queue[i]][e]] >= 0
{
  assert 0 <= i < |queue|;
  assert 0 <= queue[i] < |g.adj|;
  assert 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0;
}

lemma DistFromAt(dist: seq<int>, queue: seq<int>, from: int, layer: int, i: int)
  requires DistFrom(dist, queue, from, layer)
  requires from <= i < |queue|
  ensures 0 <= queue[i] < |dist|
  ensures dist[queue[i]] >= layer
{
  assert dist[queue[i]] >= layer;
}

lemma EnsureDistFrom(dist: seq<int>, queue: seq<int>, head: int, layer: int, u: int)
  requires LayerInv(dist, queue, head, layer)
  requires 1 <= head <= |queue|
  requires queue[head - 1] == u
  requires 0 <= u < |dist|
  requires dist[u] == layer
  ensures DistFrom(dist, queue, head - 1, layer)
{
  assert 0 <= head - 1 <= |queue|;
  forall i | 0 <= i < |queue|
    ensures 0 <= queue[i] < |dist|
  {
    assert 0 <= queue[i] < |dist|;
  }
  forall i | head - 1 <= i < |queue|
    ensures dist[queue[i]] >= layer
  {
    if i == head - 1 {
      assert queue[i] == u;
      assert dist[queue[i]] == layer;
    } else {
      assert head <= i;
      assert layer <= dist[queue[i]];
    }
  }
}

lemma UnvisitedPathLowerBound(
    g: Graph, start: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>,
    head: int, layer: int, x: int, p: seq<int>)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires dist[start] >= 0
  requires QInv(dist, queue, qpos)
  requires AllMinDist(g, start, dist)
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires DistFrom(dist, queue, head - 1, layer)
  requires 1 <= head
  requires 0 <= x < |dist| && dist[x] < 0
  requires is_path(g, p) && p[0] == start && p[|p| - 1] == x
  ensures |p| >= layer + 2
{
  PathNodesInRange(g, p, start);
  assert |dist| == |g.adj|;
  forall k | 0 <= k < |p|
    ensures 0 <= p[k] < |dist|
  {
    assert 0 <= p[k] < |g.adj|;
  }
  assert dist[p[0]] >= 0;
  assert p[|p| - 1] == x;
  assert dist[p[|p| - 1]] < 0;
  var t := FirstUnvisitedIndex(dist, p);
  var pred := p[t - 1];
  assert 0 <= pred < |dist|;
  assert dist[pred] >= 0;
  assert has_edge(g, pred, p[t]);
  QAt(dist, queue, qpos, pred);
  var ip := qpos[pred];
  assert queue[ip] == pred;

  if ip < head - 1 {
    var e := GetEdge(g, pred, p[t]);
    ExpandedAt(g, dist, queue, head - 1, ip, e);
    assert g.adj[queue[ip]][e] == p[t];
    assert dist[p[t]] >= 0;
    assert dist[p[t]] < 0;
    assert false;
  }
  assert ip >= head - 1;
  DistFromAt(dist, queue, head - 1, layer, ip);
  assert dist[pred] >= layer;

  PrefixIsPath(g, p, t);
  var prefix := p[..t];
  assert is_path(g, prefix);
  assert prefix[0] == start;
  assert prefix[|prefix| - 1] == pred;
  assert |prefix| == t;
  MinPath(g, start, dist, pred, prefix);
  assert t >= dist[pred] + 1;
  assert t >= layer + 1;
  assert |p| >= t + 1;
  assert |p| >= layer + 2;
}

lemma ProveNewMin(
    g: Graph, start: int, dist: seq<int>, queue: seq<int>, qpos: seq<int>,
    head: int, layer: int, v: int)
  requires well_formed(g)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires dist[start] >= 0
  requires QInv(dist, queue, qpos)
  requires AllMinDist(g, start, dist)
  requires ExpandedPrefix(g, dist, queue, head - 1)
  requires DistFrom(dist, queue, head - 1, layer)
  requires 1 <= head
  requires 0 <= v < |dist| && dist[v] < 0
  ensures forall r: seq<int> {:trigger is_path(g, r)} ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= layer + 2
{
  forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == v
    ensures |r| >= layer + 2
  {
    UnvisitedPathLowerBound(g, start, dist, queue, qpos, head, layer, v, r);
  }
}

lemma AllMinDistExtend(g: Graph, start: int, dist: seq<int>, v: int, newd: int)
  requires |dist| == |g.adj|
  requires 0 <= start < |dist|
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires AllMinDist(g, start, dist)
  requires forall r: seq<int> {:trigger is_path(g, r)} ::
      is_path(g, r) && r[0] == start && r[|r| - 1] == v ==> |r| >= newd + 1
  ensures AllMinDist(g, start, dist[v := newd])
{
  var dist2 := dist[v := newd];
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures forall r: seq<int> {:trigger is_path(g, r)} ::
        is_path(g, r) && r[0] == start && r[|r| - 1] == u ==> |r| >= dist2[u] + 1
  {
    if u == v {
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        assert |r| >= newd + 1;
        assert dist2[u] == newd;
      }
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      forall r: seq<int> {:trigger is_path(g, r)} | is_path(g, r) && r[0] == start && r[|r| - 1] == u
        ensures |r| >= dist2[u] + 1
      {
        MinPath(g, start, dist, u, r);
        assert dist[u] == dist2[u];
      }
    }
  }
}

lemma AllWitnessExtend(
    g: Graph, start: int, dist: seq<int>, wits: seq<seq<int>>,
    v: int, newd: int, newPath: seq<int>)
  requires AllWitness(g, start, dist, wits)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  requires |newPath| == newd + 1
  requires is_path(g, newPath)
  requires newPath[0] == start
  requires newPath[|newPath| - 1] == v
  ensures AllWitness(g, start, dist[v := newd], wits[v := newPath])
{
  var dist2 := dist[v := newd];
  var wit2 := wits[v := newPath];
  assert |wit2| == |wits|;
  assert |dist2| == |dist|;
  forall u | 0 <= u < |dist2| && dist2[u] >= 0
    ensures is_path(g, wit2[u])
      && wit2[u][0] == start
      && |wit2[u]| == dist2[u] + 1
      && wit2[u][|wit2[u]| - 1] == u
  {
    if u == v {
      assert wit2[u] == newPath;
      assert dist2[u] == newd;
      assert |newPath| > 0;
    } else {
      assert dist2[u] == dist[u];
      assert dist[u] >= 0;
      assert wit2[u] == wits[u];
      WitnessFacts(g, start, dist, wits, u);
    }
  }
}

lemma QInvEnqueue(dist: seq<int>, queue: seq<int>, qpos: seq<int>, v: int, newd: int)
  requires QInv(dist, queue, qpos)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures QInv(dist[v := newd], queue + [v], qpos[v := |queue|])
  ensures |queue| < |dist|
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  var qpos2 := qpos[v := |queue|];
  QCount(dist, queue, qpos);
  CountNegAtLeast(dist, 0, v);
  assert CountNeg(dist, 0) >= 1;
  assert |queue| + CountNeg(dist, 0) == |dist|;
  assert |queue| <= |dist| - 1;
  CountNegFlip(dist, 0, v, newd);
  assert CountNeg(dist2, 0) + 1 == CountNeg(dist, 0);
  assert |queue2| == |queue| + 1;
  assert |dist2| == |dist|;
  assert |queue2| + CountNeg(dist2, 0) == |dist2|;
  assert |qpos2| == |qpos|;
  assert |qpos| == |dist|;
  assert |qpos2| == |dist2|;

  forall i | 0 <= i < |queue|
    ensures queue[i] != v
  {
    QIndex(dist, queue, qpos, i);
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
  }

  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2| && dist2[queue2[i]] >= 0 && qpos2[queue2[i]] == i
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert queue[i] != v;
      QIndex(dist, queue, qpos, i);
      assert dist2[queue[i]] == dist[queue[i]];
      assert qpos2[queue[i]] == qpos[queue[i]];
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == newd;
      assert qpos2[v] == |queue|;
    }
  }

  forall x | 0 <= x < |dist|
    ensures (dist2[x] >= 0 ==> 0 <= qpos2[x] < |queue2| && queue2[qpos2[x]] == x)
         && (dist2[x] < 0 ==> dist2[x] == -1 && qpos2[x] == -1)
  {
    if x == v {
      assert dist2[v] == newd >= 0;
      assert qpos2[v] == |queue|;
      assert queue2[|queue|] == v;
    } else if dist[x] >= 0 {
      QAt(dist, queue, qpos, x);
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
      var ix := qpos[x];
      assert ix < |queue|;
      assert queue2[ix] == queue[ix];
      assert queue[ix] == x;
    } else {
      assert dist[x] == -1;
      assert qpos[x] == -1;
      assert dist2[x] == dist[x];
      assert qpos2[x] == qpos[x];
    }
  }
}

lemma LayerEnqueue(dist: seq<int>, queue: seq<int>, head: int, layer: int, v: int, newd: int)
  requires LayerInv(dist, queue, head, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd == layer + 1
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures LayerInv(dist[v := newd], queue + [v], head, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[queue[i]] >= 0;
      assert dist[v] >= 0;
      assert false;
    }
  }
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |dist|;
    } else {
      assert queue2[i] == v;
    }
  }
  forall i | 0 <= i < head
    ensures dist2[queue2[i]] <= layer
  {
    assert i < |queue|;
    assert queue2[i] == queue[i];
    assert dist2[queue[i]] == dist[queue[i]];
    assert dist[queue[i]] <= layer;
  }
  forall i | head <= i < |queue2|
    ensures layer <= dist2[queue2[i]] && dist2[queue2[i]] <= layer + 1
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert dist2[queue[i]] == dist[queue[i]];
      assert layer <= dist[queue[i]] && dist[queue[i]] <= layer + 1;
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
      assert dist2[v] == layer + 1;
    }
  }
  forall a, b | 0 <= a < b < |queue2|
    ensures dist2[queue2[a]] <= dist2[queue2[b]]
  {
    if b < |queue| {
      assert queue2[a] == queue[a] && queue2[b] == queue[b];
      assert dist2[queue[a]] == dist[queue[a]];
      assert dist2[queue[b]] == dist[queue[b]];
      assert dist[queue[a]] <= dist[queue[b]];
    } else {
      assert b == |queue|;
      assert queue2[b] == v;
      assert dist2[v] == layer + 1;
      assert a < |queue|;
      assert queue2[a] == queue[a];
      assert dist2[queue[a]] == dist[queue[a]];
      if a < head {
        assert dist[queue[a]] <= layer;
      } else {
        assert dist[queue[a]] <= layer + 1;
      }
    }
  }
}

lemma DistFromEnqueue(dist: seq<int>, queue: seq<int>, from: int, layer: int, v: int, newd: int)
  requires DistFrom(dist, queue, from, layer)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= layer
  requires forall i :: 0 <= i < |queue| ==> dist[queue[i]] >= 0
  ensures DistFrom(dist[v := newd], queue + [v], from, layer)
{
  var dist2 := dist[v := newd];
  var queue2 := queue + [v];
  assert |dist2| == |dist|;
  assert 0 <= from <= |queue|;
  assert from <= |queue2|;
  forall i | 0 <= i < |queue|
    ensures queue[i] != v && dist2[queue[i]] == dist[queue[i]]
  {
    if queue[i] == v {
      assert dist[v] >= 0;
      assert false;
    }
    assert queue[i] != v;
    assert dist2[queue[i]] == dist[queue[i]];
  }
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |dist2|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |dist|;
    } else {
      assert queue2[i] == v;
      assert 0 <= v < |dist2|;
    }
  }
  forall i | from <= i < |queue2|
    ensures dist2[queue2[i]] >= layer
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert dist[queue[i]] >= layer;
      assert dist2[queue2[i]] == dist[queue[i]];
    } else {
      assert queue2[i] == v;
      assert dist2[v] == newd;
      assert newd >= layer;
    }
  }
}

lemma ExpandedPreserve(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, v: int, newd: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= v < |dist|
  requires dist[v] < 0
  requires newd >= 0
  ensures ExpandedPrefix(g, dist[v := newd], queue, upto)
{
  var dist2 := dist[v := newd];
  forall i | 0 <= i < upto
    ensures forall e :: 0 <= e < |g.adj[queue[i]]| ==>
        0 <= g.adj[queue[i]][e] < |dist2| && dist2[g.adj[queue[i]][e]] >= 0
  {
    forall e | 0 <= e < |g.adj[queue[i]]|
      ensures 0 <= g.adj[queue[i]][e] < |dist2| && dist2[g.adj[queue[i]][e]] >= 0
    {
      ExpandedAt(g, dist, queue, upto, i, e);
      var nbr := g.adj[queue[i]][e];
      assert dist[nbr] >= 0;
      assert nbr != v;
      assert dist2[nbr] == dist[nbr];
    }
  }
}

lemma ExpandedPrefixAppend(g: Graph, dist: seq<int>, queue: seq<int>, upto: int, v: int)
  requires ExpandedPrefix(g, dist, queue, upto)
  requires 0 <= v < |g.adj|
  ensures ExpandedPrefix(g, dist, queue + [v], upto)
{
  var queue2 := queue + [v];
  assert |dist| == |g.adj|;
  assert 0 <= upto <= |queue|;
  assert upto <= |queue2|;
  forall i | 0 <= i < |queue2|
    ensures 0 <= queue2[i] < |g.adj|
  {
    if i < |queue| {
      assert queue2[i] == queue[i];
      assert 0 <= queue[i] < |g.adj|;
    } else {
      assert i == |queue|;
      assert queue2[i] == v;
    }
  }
  forall i | 0 <= i < upto
    ensures forall e :: 0 <= e < |g.adj[queue2[i]]| ==>
        0 <= g.adj[queue2[i]][e] < |dist| && dist[g.adj[queue2[i]][e]] >= 0
  {
    assert i < |queue|;
    assert queue2[i] == queue[i];
    forall e | 0 <= e < |g.adj[queue[i]]|
      ensures 0 <= g.adj[queue[i]][e] < |dist| && dist[g.adj[queue[i]][e]] >= 0
