ghost function W(f: FlowMap, S: seq<bool>, a: int, b: int): int
{
  (if inS(S, a) then get_flow(f, a, b) else 0) - (if inS(S, b) then get_flow(f, a, b) else 0)
}

ghost function MatW(f: FlowMap, S: seq<bool>): (int, int) -> int
{
  (a: int, b: int) => W(f, S, a, b)
}

// ---------- generic sums ----------

ghost function RowSum(H: (int, int) -> int, u: int, m: int): int
  decreases m
{
  if m <= 0 then 0 else RowSum(H, u, m - 1) + H(u, m - 1)
}

ghost function ColSum(H: (int, int) -> int, v: int, n: int): int
  decreases n
{
  if n <= 0 then 0 else ColSum(H, v, n - 1) + H(n - 1, v)
}

ghost function DR(H: (int, int) -> int, n: int, m: int): int
  decreases n
{
  if n <= 0 then 0 else DR(H, n - 1, m) + RowSum(H, n - 1, m)
}

ghost function DC(H: (int, int) -> int, n: int, m: int): int
  decreases m
{
  if m <= 0 then 0 else DC(H, n, m - 1) + ColSum(H, m - 1, n)
}

lemma RowSum_ext(H1: (int, int) -> int, H2: (int, int) -> int, u: int, m: int)
  requires forall v :: 0 <= v < m ==> H1(u, v) == H2(u, v)
  ensures RowSum(H1, u, m) == RowSum(H2, u, m)
  decreases m
{
  if m > 0 { RowSum_ext(H1, H2, u, m - 1); }
}

lemma RowSum_zero(H: (int, int) -> int, u: int, m: int)
  requires forall v :: 0 <= v < m ==> H(u, v) == 0
  ensures RowSum(H, u, m) == 0
  decreases m
{
  if m > 0 { RowSum_zero(H, u, m - 1); }
}

lemma RowSum_sub(H1: (int, int) -> int, H2: (int, int) -> int, H3: (int, int) -> int, u: int, m: int)
  requires forall v :: 0 <= v < m ==> H3(u, v) == H1(u, v) - H2(u, v)
  ensures RowSum(H3, u, m) == RowSum(H1, u, m) - RowSum(H2, u, m)
  decreases m
{
  if m > 0 { RowSum_sub(H1, H2, H3, u, m - 1); }
}

lemma RowSum_mono(H1: (int, int) -> int, H2: (int, int) -> int, u: int, m: int)
  requires forall v :: 0 <= v < m ==> H1(u, v) <= H2(u, v)
  ensures RowSum(H1, u, m) <= RowSum(H2, u, m)
  decreases m
{
  if m > 0 { RowSum_mono(H1, H2, u, m - 1); }
}

lemma RowSum_remove(H: (int, int) -> int, H2: (int, int) -> int, u: int, x: int, m: int)
  requires 0 <= x < m
  requires forall v :: 0 <= v < m ==> H2(u, v) == (if v == x then 0 else H(u, v))
  ensures RowSum(H, u, m) == RowSum(H2, u, m) + H(u, x)
  decreases m
{
  if x == m - 1 {
    RowSum_ext(H, H2, u, m - 1);
  } else {
    RowSum_remove(H, H2, u, x, m - 1);
  }
}

lemma DR_sub(H1: (int, int) -> int, H2: (int, int) -> int, H3: (int, int) -> int, n: int, m: int)
  requires forall u, v :: 0 <= u < n && 0 <= v < m ==> H3(u, v) == H1(u, v) - H2(u, v)
  ensures DR(H3, n, m) == DR(H1, n, m) - DR(H2, n, m)
  decreases n
{
  if n > 0 {
    DR_sub(H1, H2, H3, n - 1, m);
    RowSum_sub(H1, H2, H3, n - 1, m);
  }
}

lemma DR_mono(H1: (int, int) -> int, H2: (int, int) -> int, n: int, m: int)
  requires forall u, v :: 0 <= u < n && 0 <= v < m ==> H1(u, v) <= H2(u, v)
  ensures DR(H1, n, m) <= DR(H2, n, m)
  decreases n
{
  if n > 0 {
    DR_mono(H1, H2, n - 1, m);
    RowSum_mono(H1, H2, n - 1, m);
  }
}

lemma DC_zero(H: (int, int) -> int, m: int)
  ensures DC(H, 0, m) == 0
  decreases m
{
  if m > 0 { DC_zero(H, m - 1); }
}

lemma DC_peel(H: (int, int) -> int, n: int, m: int)
  requires n >= 1
  ensures DC(H, n, m) == DC(H, n - 1, m) + RowSum(H, n - 1, m)
  decreases m
{
  if m > 0 {
    DC_peel(H, n, m - 1);
    assert ColSum(H, m - 1, n) == ColSum(H, m - 1, n - 1) + H(n - 1, m - 1);
  }
}

lemma Swap(H: (int, int) -> int, n: int, m: int)
  requires n >= 0
  ensures DR(H, n, m) == DC(H, n, m)
  decreases n
{
  if n == 0 {
    DC_zero(H, m);
  } else {
    Swap(H, n - 1, m);
    DC_peel(H, n, m);
  }
}

// ---------- edge-list sums ----------

ghost function SumE(es: seq<(int, int)>, k: int, H: (int, int) -> int, u: int): int
  requires 0 <= k <= |es|
  decreases k
{
  if k == 0 then 0 else SumE(es, k - 1, H, u) + H(u, es[k - 1].0)
}

lemma SumE_ext(es: seq<(int, int)>, k: int, H1: (int, int) -> int, H2: (int, int) -> int, u: int)
  requires 0 <= k <= |es|
  requires forall i :: 0 <= i < k ==> H1(u, es[i].0) == H2(u, es[i].0)
  ensures SumE(es, k, H1, u) == SumE(es, k, H2, u)
  decreases k
{
  if k > 0 { SumE_ext(es, k - 1, H1, H2, u); }
}

lemma Conv(g: seq<seq<(int, int)>>, u: int, k: int, H: (int, int) -> int)
  requires WFs(g) && 0 <= u < |g| && 0 <= k <= |g[u]|
  requires forall v :: 0 <= v < |g| && (forall i :: 0 <= i < k ==> g[u][i].0 != v) ==> H(u, v) == 0
  ensures SumE(g[u], k, H, u) == RowSum(H, u, |g|)
  decreases k
{
  if k == 0 {
    forall v | 0 <= v < |g| ensures H(u, v) == 0 {
      assert forall i :: 0 <= i < k ==> g[u][i].0 != v;
    }
    RowSum_zero(H, u, |g|);
  } else {
    var x := g[u][k - 1].0;
    var H2: (int, int) -> int := (a: int, b: int) => if a == u && b == x then 0 else H(a, b);
    forall v | 0 <= v < |g| && (forall i :: 0 <= i < k - 1 ==> g[u][i].0 != v)
      ensures H2(u, v) == 0
    {
      if v != x {
        assert forall i :: 0 <= i < k ==> g[u][i].0 != v;
      }
    }
    Conv(g, u, k - 1, H2);
    forall i | 0 <= i < k - 1
      ensures H(u, g[u][i].0) == H2(u, g[u][i].0)
    {
      assert g[u][i].0 != g[u][k - 1].0;
    }
    SumE_ext(g[u], k - 1, H, H2, u);
    RowSum_remove(H, H2, u, x, |g|);
  }
}

lemma OutRecE(g: seq<seq<(int, int)>>, f: FlowMap, u: int, k: int)
  requires 0 <= u < |g| && 0 <= k <= |g[u]|
  ensures sum_flow_out_recursive(g, f, u, k) == SumE(g[u], k, MatF(f), u)
  decreases k
{
  if k > 0 { OutRecE(g, f, u, k - 1); }
}

lemma OutConv(g: seq<seq<(int, int)>>, f: FlowMap, s: int, t: int, u: int)
  requires WFs(g) && is_valid_flow(g, f, s, t) && 0 <= u < |g|
  ensures total_flow_out(g, f, u) == RowSum(MatF(f), u, |g|)
{
  OutRecE(g, f, u, |g[u]|);
  assert respects_capacity(g, f);
  assert Nonneg(f);
  forall v | 0 <= v < |g| && (forall i :: 0 <= i < |g[u]| ==> g[u][i].0 != v)
    ensures MatF(f)(u, v) == 0
  {
    if (u, v) in f && f[(u, v)] > 0 {
      var c :| has_capacity(g, u, v, c) && f[(u, v)] <= c;
      var i :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == c;
      assert false;
    }
    assert get_flow(f, u, v) == 0;
  }
  Conv(g, u, |g[u]|, MatF(f));
}

// ---------- cut value ----------

ghost function SOut(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, k: int): int
  decreases k
{
  if k <= 0 then 0 else SOut(g, f, S, k - 1) + (if inS(S, k - 1) then total_flow_out(g, f, k - 1) else 0)
}

ghost function SIn(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, k: int): int
  decreases k
{
  if k <= 0 then 0 else SIn(g, f, S, k - 1) + (if inS(S, k - 1) then total_flow_in(g, f, k - 1) else 0)
}

lemma NetSum(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, s: int, t: int, k: int)
  requires 0 <= s < |g| && 0 <= t < |g| && |S| == |g| && S[s] && !S[t]
  requires is_conserved(g, f, s, t)
  requires 0 <= k <= |g|
  ensures SOut(g, f, S, k) - SIn(g, f, S, k) == (if s < k then flow_val(g, f, s) else 0)
  decreases k
{
  if k > 0 {
    NetSum(g, f, S, s, t, k - 1);
    var u := k - 1;
    if u != s && inS(S, u) {
      assert u != t;
      assert total_flow_in(g, f, u) == total_flow_out(g, f, u);
    }
  }
}

lemma OutPart(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, s: int, t: int, k: int)
  requires WFs(g) && is_valid_flow(g, f, s, t) && |S| == |g| && 0 <= k <= |g|
  ensures DR(MatA(f, S), k, |g|) == SOut(g, f, S, k)
  decreases k
{
  if k > 0 {
    OutPart(g, f, S, s, t, k - 1);
    var u := k - 1;
    if inS(S, u) {
      RowSum_ext(MatA(f, S), MatF(f), u, |g|);
      OutConv(g, f, s, t, u);
    } else {
      RowSum_zero(MatA(f, S), u, |g|);
    }
  }
}

lemma ColIn(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, v: int, j: int)
  requires j >= 0
  ensures ColSum(MatB(f, S), v, j) == (if inS(S, v) then sum_flow_in_recursive(g, f, v, j) else 0)
  decreases j
{
  if j > 0 { ColIn(g, f, S, v, j - 1); }
}

lemma InPartK(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, k: int)
  requires 0 <= k
  ensures DC(MatB(f, S), |g|, k) == SIn(g, f, S, k)
  decreases k
{
  if k > 0 {
    InPartK(g, f, S, k - 1);
    ColIn(g, f, S, k - 1, |g|);
  }
}

lemma InPart(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>)
  ensures DR(MatB(f, S), |g|, |g|) == SIn(g, f, S, |g|)
{
  Swap(MatB(f, S), |g|, |g|);
  InPartK(g, f, S, |g|);
}

lemma CutVal(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, s: int, t: int)
  requires WFs(g) && 0 <= s < |g| && 0 <= t < |g| && |S| == |g| && S[s] && !S[t]
  requires is_valid_flow(g, f, s, t)
  ensures flow_val(g, f, s) == DR(MatW(f, S), |g|, |g|)
{
  var n := |g|;
  assert is_conserved(g, f, s, t);
  NetSum(g, f, S, s, t, n);
  OutPart(g, f, S, s, t, n);
  InPart(g, f, S);
  DR_sub(MatA(f, S), MatB(f, S), MatW(f, S), n, n);
}

lemma WCompare(g: seq<seq<(int, int)>>, f: FlowMap, o: FlowMap, S: seq<bool>, s: int, t: int, a: int, b: int)
  requires WFs(g) && |S| == |g| && 0 <= a < |g| && 0 <= b < |g|
  requires is_valid_flow(g, f, s, t) && is_valid_flow(g, o, s, t)
  requires forall u, i :: 0 <= u < |g| && S[u] && 0 <= i < |g[u]| && get_flow(f, u, g[u][i].0) < g[u][i].1 ==> 0 <= g[u][i].0 < |g| && S[g[u][i].0]
  requires forall u, w :: 0 <= u < |g| && S[u] && 0 <= w < |g| && get_flow(f, w, u) > 0 ==> S[w]
  ensures W(o, S, a, b) <= W(f, S, a, b)
{
  assert Nonneg(f) && Nonneg(o);
  assert get_flow(f, a, b) >= 0;
  assert get_flow(o, a, b) >= 0;
  if S[a] && !S[b] {
    if get_flow(o, a, b) > 0 {
      assert (a, b) in o && o[(a, b)] > 0;
      assert respects_capacity(g, o);
      var c :| has_capacity(g, a, b, c) && o[(a, b)] <= c;
      var i :| 0 <= a < |g| && 0 <= i < |g[a]| && g[a][i].0 == b && g[a][i].1 == c;
      if get_flow(f, a, g[a][i].0) < g[a][i].1 {
        assert S[g[a][i].0];
        assert false;
      }
    }
  } else if !S[a] && S[b] {
    if get_flow(f, a, b) > 0 {
      assert S[a];
      assert false;
    }
  }
}

lemma MaxLemma(g: seq<seq<(int, int)>>, f: FlowMap, s: int, t: int, S: seq<bool>)
  requires WFs(g) && 0 <= s < |g| && 0 <= t < |g| && s != t
  requires is_valid_flow(g, f, s, t)
  requires |S| == |g| && S[s] && !S[t]
  requires forall u, i :: 0 <= u < |g| && S[u] && 0 <= i < |g[u]| && get_flow(f, u, g[u][i].0) < g[u][i].1 ==> 0 <= g[u][i].0 < |g| && S[g[u][i].0]
  requires forall u, w :: 0 <= u < |g| && S[u] && 0 <= w < |g| && get_flow(f, w, u) > 0 ==> S[w]
  ensures is_max_flow(g, f, s, t)
{
  var n := |g|;
  forall other: FlowMap | is_valid_flow(g, other, s, t)
    ensures flow_val(g, f, s) >= flow_val(g, other, s)
  {
    CutVal(g, f, S, s, t);
    CutVal(g, other, S, s, t);
    forall a, b | 0 <= a < n && 0 <= b < n
      ensures MatW(other, S)(a, b) <= MatW(f, S)(a, b)
    {
      WCompare(g, f, other, S, s, t, a, b);
    }
    DR_mono(MatW(other, S), MatW(f, S), n, n);
  }
}

// ---------- updates ----------

lemma GetFlowUpd(f: FlowMap, a: int, b: int, x: int, p: int, q: int)
  ensures get_flow(f[(a, b) := x], p, q) == (if p == a && q == b then x else get_flow(f, p, q))
{
}

lemma UpdOut(g: seq<seq<(int, int)>>, f: FlowMap, a: int, b: int, x: int, j: int, w: int, k: int)
  requires WFs(g) && 0 <= a < |g| && 0 <= j < |g[a]| && g[a][j].0 == b
  ensures sum_flow_out_recursive(g, f[(a, b) := x], w, k)
          == sum_flow_out_recursive(g, f, w, k) + (if w == a && j < k then x - get_flow(f, a, b) else 0)
  decreases k
{
  if k > 0 && 0 <= w < |g| {
    UpdOut(g, f, a, b, x, j, w, k - 1);
    if k - 1 < |g[w]| {
      var y := g[w][k - 1].0;
      GetFlowUpd(f, a, b, x, w, y);
      if w == a && y == b {
        if k - 1 != j { assert g[a][k - 1].0 != g[a][j].0; }
      }
    }
  }
}

lemma UpdIn(g: seq<seq<(int, int)>>, f: FlowMap, a: int, b: int, x: int, w: int, k: int)
  requires 0 <= a
  ensures sum_flow_in_recursive(g, f[(a, b) := x], w, k)
          == sum_flow_in_recursive(g, f, w, k) + (if w == b && a < k then x - get_flow(f, a, b) else 0)
  decreases k
{
  if k > 0 {
    UpdIn(g, f, a, b, x, w, k - 1);
    GetFlowUpd(f, a, b, x, k - 1, w);
  }
}

lemma NetUpd(g: seq<seq<(int, int)>>, f: FlowMap, a: int, b: int, x: int, j: int, w: int)
  requires WFs(g) && 0 <= a < |g| && 0 <= j < |g[a]| && g[a][j].0 == b
  ensures Net(g, f[(a, b) := x], w)
          == Net(g, f, w) + (if w == a then x - get_flow(f, a, b) else 0) - (if w == b then x - get_flow(f, a, b) else 0)
{
  assert 0 <= b < |g|;
  UpdIn(g, f, a, b, x, w, |g|);
  if 0 <= w < |g| {
    UpdOut(g, f, a, b, x, j, w, |g[w]|);
  }
}

lemma RespUpd(g: seq<seq<(int, int)>>, f: FlowMap, a: int, b: int, x: int, c: int)
  requires respects_capacity(g, f) && has_capacity(g, a, b, c) && x <= c
  ensures respects_capacity(g, f[(a, b) := x])
{
  var f' := f[(a, b) := x];
  forall u, v | (u, v) in f' && f'[(u, v)] > 0
    ensures exists c' :: has_capacity(g, u, v, c') && f'[(u, v)] <= c'
  {
    if u == a && v == b {
      assert has_capacity(g, u, v, c) && f'[(u, v)] <= c;
    } else {
      assert (u, v) in f && f'[(u, v)] == f[(u, v)];
    }
  }
}

lemma NonnegUpd(f: FlowMap, a: int, b: int, x: int)
  requires Nonneg(f) && x >= 0
  ensures Nonneg(f[(a, b) := x])
{
  var f' := f[(a, b) := x];
  forall u, v | (u, v) in f' ensures f'[(u, v)] >= 0 {
    if !(u == a && v == b) { assert (u, v) in f; }
  }
}

lemma AugStep(g: seq<seq<(int, int)>>, f: FlowMap, f0: FlowMap, t: int, visited: seq<bool>, lbl: seq<int>,
              v: int, u: int, a: int, b: int, x: int, j: int)
  requires WFs(g)
  requires |visited| == |g| && |lbl| == |g|
  requires 0 <= v < |g| && visited[v] && 0 <= u < |g| && visited[u] && lbl[u] < lbl[v]
  requires (a == u && b == v && x == get_flow(f, a, b) + 1) || (a == v && b == u && x == get_flow(f, a, b) - 1)
  requires 0 <= j < |g[a]| && g[a][j].0 == b && x <= g[a][j].1 && x >= 0
  requires respects_capacity(g, f) && Nonneg(f)
  requires forall w :: 0 <= w < |g| ==> Net(g, f, w) == Net(g, f0, w) + (if w == v then 1 else 0) - (if w == t then 1 else 0)
  requires forall p, q :: get_flow(f, p, q) != get_flow(f0, p, q) ==> 0 <= p < |g| && 0 <= q < |g| && visited[p] && visited[q] && lbl[p] >= lbl[v] && lbl[q] >= lbl[v]
  ensures respects_capacity(g, f[(a, b) := x]) && Nonneg(f[(a, b) := x])
  ensures forall w :: 0 <= w < |g| ==> Net(g, f[(a, b) := x], w) == Net(g, f0, w) + (if w == u then 1 else 0) - (if w == t then 1 else 0)
  ensures forall p, q :: get_flow(f[(a, b) := x], p, q) != get_flow(f0, p, q) ==> 0 <= p < |g| && 0 <= q < |g| && visited[p] && visited[q] && lbl[p] >= lbl[u] && lbl[q] >= lbl[u]
{
  var f' := f[(a, b) := x];
  assert has_capacity(g, a, b, g[a][j].1) by {
    assert 0 <= a < |g| && 0 <= j < |g[a]| && g[a][j].0 == b && g[a][j].1 == g[a][j].1;
  }
  RespUpd(g, f, a, b, x, g[a][j].1);
  NonnegUpd(f, a, b, x);
  forall w | 0 <= w < |g|
    ensures Net(g, f', w) == Net(g, f0, w) + (if w == u then 1 else 0) - (if w == t then 1 else 0)
  {
    NetUpd(g, f, a, b, x, j, w);
  }
  forall p, q | get_flow(f', p, q) != get_flow(f0, p, q)
    ensures 0 <= p < |g| && 0 <= q < |g| && visited[p] && visited[q] && lbl[p] >= lbl[u] && lbl[q] >= lbl[u]
  {
    GetFlowUpd(f, a, b, x, p, q);
    if !(p == a && q == b) {
      assert get_flow(f, p, q) != get_flow(f0, p, q);
    }
  }
}

// ---------- empty flow / bounds ----------

lemma EmptyOut(g: seq<seq<(int, int)>>, f: FlowMap, u: int, k: int)
  requires f == map[]
  ensures sum_flow_out_recursive(g, f, u, k) == 0
  decreases k
{
  if k > 0 { EmptyOut(g, f, u, k - 1); }
}

lemma EmptyIn(g: seq<seq<(int, int)>>, f: FlowMap, u: int, k: int)
  requires f == map[]
  ensures sum_flow_in_recursive(g, f, u, k) == 0
  decreases k
{
  if k > 0 { EmptyIn(g, f, u, k - 1); }
}

lemma EmptyFlow(g: seq<seq<(int, int)>>, f: FlowMap, s: int, t: int)
  requires f == map[]
  ensures is_valid_flow(g, f, s, t) && flow_val(g, f, s) == 0
{
  forall u: int ensures total_flow_out(g, f, u) == 0 && total_flow_in(g, f, u) == 0 {
    if 0 <= u < |g| { EmptyOut(g, f, u, |g[u]|); }
    EmptyIn(g, f, u, |g|);
  }
}

ghost function CapOut(es: seq<(int, int)>, k: int): int
  requires 0 <= k <= |es|
  decreases k
{
