lemma OutCap(g: seq<seq<(int, int)>>, f: FlowMap, u: int, k: int)
  requires WFs(g) && respects_capacity(g, f) && 0 <= u < |g| && 0 <= k <= |g[u]|
  ensures sum_flow_out_recursive(g, f, u, k) <= CapOut(g[u], k)
  decreases k
{
  if k > 0 {
    OutCap(g, f, u, k - 1);
    var y := g[u][k - 1].0;
    if (u, y) in f && f[(u, y)] > 0 {
