function CapacityFrom(row: seq<(int, int)>, v: int, n: int): int
    requires 0 <= n <= |row|
    decreases n
{
    if n == 0 then
        0
    else if row[n - 1].0 == v then
        row[n - 1].1
    else
        CapacityFrom(row, v, n - 1)
}

function CapacityAt(g: seq<seq<(int, int)>>, u: int, v: int): int
{
    if 0 <= u < |g| then CapacityFrom(g[u], v, |g[u]|) else 0
}

function ActualGet(f: FlowMap, u: int, v: int): int
{
    if (u, v) in f then f[(u, v)] else 0
}

function ActualSumOut(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int): int
    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        ActualSumOut(g, f, u, idx - 1)
            + ActualGet(f, u, g[u][idx - 1].0)
    else
        ActualSumOut(g, f, u, idx - 1)
}

function ActualSumIn(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        ActualSumIn(g, f, u, idx - 1)
            + ActualGet(f, idx - 1, u)
}

function ActualFlowValue(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int): int
{
    (if 0 <= s < |g|
        then ActualSumOut(g, f, s, |g[s]|)
        else 0)
    - ActualSumIn(g, f, s, |g|)
}

function ActualConservedPrefix(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    n: int): bool
    requires 0 <= n <= |g|
    decreases n
{
    if n == 0 then
        true
    else
        ActualConservedPrefix(g, f, s, t, n - 1)
        &&
        ((n - 1 == s || n - 1 == t)
         ||
         ActualSumIn(g, f, n - 1, |g|)
            == ActualSumOut(g, f, n - 1, |g[n - 1]|))
}

function CanonicalPrefix(f: FlowMap, n: int, k: int): FlowMap
    requires 0 < n
    requires 0 <= k <= n * n
    decreases k
{
    if k == 0 then
        map[]
    else
        CanonicalPrefix(f, n, k - 1)
            [((k - 1) / n, (k - 1) % n)
                := ActualGet(f, (k - 1) / n, (k - 1) % n)]
}

function EnumeratedFlows(
    g: seq<seq<(int, int)>>,
    k: int): set<FlowMap>
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    decreases k
{
    if k == 0 then
        {map[]}
    else
        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;
        set p: FlowMap, x: int |
            p in EnumeratedFlows(g, k - 1)
            && 0 <= x <= CapacityAt(g, u, v)
        :: p[(u, v) := x]
}

ghost predicate PrefixShape(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
{
    && 0 <= k <= |g| * |g|
    && (forall u: int, v: int ::
            (u, v) in f
            <==>
            0 <= u < |g|
            && 0 <= v < |g|
            && u * |g| + v < k)
    && (forall u: int, v: int ::
            0 <= u < |g|
            && 0 <= v < |g|
            && u * |g| + v < k
            ==>
            0 <= f[(u, v)] <= CapacityAt(g, u, v))
}

lemma ActualGetAgreement(f: FlowMap, u: int, v: int)
    ensures ActualGet(f, u, v) == get_flow(f, u, v)
{
}

lemma ActualSumOutAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumOut(g, f, u, idx)
        == sum_flow_out_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ActualSumOutAgreement(g, f, u, idx - 1);
        if 0 <= u < |g| && idx - 1 < |g[u]| {
            ActualGetAgreement(f, u, g[u][idx - 1].0);
        }
    }
}

lemma ActualSumInAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumIn(g, f, u, idx)
        == sum_flow_in_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ActualSumInAgreement(g, f, u, idx - 1);
        ActualGetAgreement(f, idx - 1, u);
    }
}

lemma ActualFlowValueAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int)
    requires 0 <= s < |g|
    ensures ActualFlowValue(g, f, s) == flow_val(g, f, s)
{
    ActualSumOutAgreement(g, f, s, |g[s]|);
    ActualSumInAgreement(g, f, s, |g|);
}

lemma LookupAtIndex(
    row: seq<(int, int)>,
    v: int,
    c: int,
    i: int)
    requires 0 <= i < |row|
    requires row[i].0 == v
    requires row[i].1 == c
    requires forall a: int, b: int ::
        0 <= a < |row| && 0 <= b < |row| && a != b
        ==> row[a].0 != row[b].0
    ensures CapacityFrom(row, v, |row|) == c
    decreases |row|
{
    if i == |row| - 1 {
    } else {
        assert row[|row| - 1].0 != v;
        LookupAtIndex(row[..|row| - 1], v, c, i);
    }
}

lemma CapacityMatchesEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    c: int)
    requires well_formed(CapacityGraph(g))
    requires has_capacity(g, u, v, c)
    ensures CapacityAt(g, u, v) == c
{
    var i :|
        0 <= u < |g|
        && 0 <= i < |g[u]|
        && g[u][i].0 == v
        && g[u][i].1 == c;

    assert forall a: int, b: int ::
        0 <= a < |g[u]| && 0 <= b < |g[u]| && a != b
        ==> g[u][a].0 != g[u][b].0;

    LookupAtIndex(g[u], v, c, i);
}

lemma CapacityFromProducesEdge(
    row: seq<(int, int)>,
    v: int,
    n: int)
    requires 0 <= n <= |row|
    requires CapacityFrom(row, v, n) != 0
    ensures exists i: int ::
        0 <= i < n
        && row[i].0 == v
        && row[i].1 == CapacityFrom(row, v, n)
    decreases n
{
    if n > 0 {
        if row[n - 1].0 == v {
            assert row[n - 1].1 == CapacityFrom(row, v, n);
        } else {
            CapacityFromProducesEdge(row, v, n - 1);
        }
    }
}

lemma CapacityProducesEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int)
    requires 0 <= u < |g|
    requires CapacityAt(g, u, v) != 0
    ensures has_capacity(g, u, v, CapacityAt(g, u, v))
{
    CapacityFromProducesEdge(g[u], v, |g[u]|);
    var i :|
        0 <= i < |g[u]|
        && g[u][i].0 == v
        && g[u][i].1 == CapacityAt(g, u, v);
}

lemma CapacityNonnegative(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int)
    requires capacities_bounded(g)
    requires 0 <= u < |g|
    ensures CapacityAt(g, u, v) >= 0
{
    if CapacityAt(g, u, v) != 0 {
        CapacityProducesEdge(g, u, v);
        assert has_capacity(g, u, v, CapacityAt(g, u, v));
    }
}

lemma EnumeratedCharacterization(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    ensures f in EnumeratedFlows(g, k) <==> PrefixShape(g, k, f)
    decreases k
{
    if k == 0 {
        if f in EnumeratedFlows(g, k) {
            assert f == map[];
            assert PrefixShape(g, k, f);
        }
        if PrefixShape(g, k, f) {
            assert f == map[];
            assert f in EnumeratedFlows(g, k);
        }
    } else {
        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;
        assert 0 <= u < n;
        assert 0 <= v < n;
        assert u * n + v == k - 1;

        if f in EnumeratedFlows(g, k) {
            var p: FlowMap, x: int :|
                p in EnumeratedFlows(g, k - 1)
                && 0 <= x <= CapacityAt(g, u, v)
                && f == p[(u, v) := x];

            EnumeratedCharacterization(g, k - 1, p);
            assert PrefixShape(g, k - 1, p);
            assert PrefixShape(g, k, f);
        }

        if PrefixShape(g, k, f) {
            var p := f - {(u, v)};
            assert PrefixShape(g, k - 1, p);
            EnumeratedCharacterization(g, k - 1, p);
            assert p in EnumeratedFlows(g, k - 1);
            assert 0 <= f[(u, v)] <= CapacityAt(g, u, v);
