method max_flow_value(graph: CapacityGraph, s: int, t: int)
    returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := view(graph);
    var all := EnumeratedFlows(g, |g| * |g|);
    var remaining := all;

    var best := CanonicalPrefix(map[], |g|, |g| * |g|);
    max_val := 0;

    EmptyCanonicalValid(graph, s, t);
    EnumeratedConservedIsValid(graph, best, s, t);
    ActualFlowValueAgreement(g, best, s);

    while remaining != {}
        invariant remaining <= all
        invariant best in all
        invariant ActualConservedPrefix(g, best, s, t, |g|)
        invariant is_valid_flow(g, best, s, t)
        invariant ActualFlowValue(g, best, s) == max_val
        invariant flow_val(g, best, s) == max_val
        invariant forall f: FlowMap ::
            f in all - remaining
            && ActualConservedPrefix(g, f, s, t, |g|)
            ==> ActualFlowValue(g, f, s) <= max_val
        decreases |remaining|
    {
        var f :| f in remaining;

        if ActualConservedPrefix(g, f, s, t, |g|) {
            EnumeratedConservedIsValid(graph, f, s, t);
            ActualFlowValueAgreement(g, f, s);

            if ActualFlowValue(g, f, s) > max_val {
                best := f;
                max_val := ActualFlowValue(g, f, s);
            }
        }

        remaining := remaining - {f};
    }

    assert remaining == {};
    assert forall f: FlowMap ::
        f in all
        && ActualConservedPrefix(g, f, s, t, |g|)
        ==> ActualFlowValue(g, f, s) <= max_val;

    assert forall other: FlowMap
        {:trigger is_valid_flow(g, other, s, t)} ::
        is_valid_flow(g, other, s, t)
        ==> flow_val(g, best, s) >= flow_val(g, other, s) by
    {
        forall other: FlowMap |
            is_valid_flow(g, other, s, t)
            ensures flow_val(g, best, s) >= flow_val(g, other, s)
        {
            var canonical :=
                CanonicalPrefix(other, |g|, |g| * |g|);

            CanonicalEnumerated(g, other, s, t);
            CanonicalPreservesConservation(graph, other, s, t);

            assert canonical in all;
            assert ActualConservedPrefix(
                g, canonical, s, t, |g|);
            assert ActualFlowValue(g, canonical, s)
                == flow_val(g, other, s);
            assert ActualFlowValue(g, canonical, s) <= max_val;
            assert flow_val(g, best, s) == max_val;
        }
    }

    assert is_max_flow(g, best, s, t);
    assert flow_val(g, best, s) == max_val;
}
