  }
}

lemma xor_step(cr: bool, cu: bool, Cu: bool, Cv: bool)
  requires Cu == (cr != cu)
  requires Cv != Cu
  ensures Cv == (cr != !cu)
{
  if cu {
    assert (cr != true) == !cr;
    assert Cu == !cr;
    assert Cv == !Cu;
    assert Cv == cr;
    assert (cr != false) == cr;
  } else {
    assert (cr != false) == cr;
    assert Cu == cr;
    assert Cv == !Cu;
    assert Cv == !cr;
    assert (cr != true) == !cr;
  }
}

lemma {:vcs_split_on_every_assert} edge_from_index(g: Graph, u: int, i: int)
  requires 0 <= u < |g.adj|
  requires 0 <= i < |g.adj[u]|
  ensures has_edge(g, u, g.adj[u][i])
{
  var v := g.adj[u][i];
  assert 0 <= u < |g.adj| && 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
}

lemma {:vcs_split_on_every_assert} neighbor_in_range(g: Graph, u: int, i: int)
  requires well_formed(g)
  requires 0 <= u < |g.adj|
  requires 0 <= i < |g.adj[u]|
  ensures 0 <= g.adj[u][i] < |g.adj|
{
  assert 0 <= u < |g.adj| && 0 <= i < |g.adj[u]|;
  assert 0 <= g.adj[u][i] < |g.adj|;
}

lemma {:vcs_split_on_every_assert} endpoints(g: Graph, a: int, b: int)
  requires well_formed(g)
  requires has_edge(g, a, b)
  ensures 0 <= a < |g.adj| && 0 <= b < |g.adj|
{
  var i :| 0 <= a < |g.adj| && 0 <= i < |g.adj[a]| && g.adj[a][i] == b;
  neighbor_in_range(g, a, i);
  assert b == g.adj[a][i];
}

lemma {:vcs_split_on_every_assert} connected_sym(g: Graph, a: int, b: int)
  ensures connected(g, a, b) <==> connected(g, b, a)
{
  if connected(g, a, b) {
    if has_edge(g, a, b) {
      assert connected(g, b, a);
    } else {
      assert has_edge(g, b, a);
      assert connected(g, b, a);
    }
  }
  if connected(g, b, a) {
    if has_edge(g, b, a) {
      assert connected(g, a, b);
    } else {
      assert has_edge(g, a, b);
      assert connected(g, a, b);
    }
  }
  assert connected(g, a, b) ==> connected(g, b, a);
  assert connected(g, b, a) ==> connected(g, a, b);
}

lemma {:vcs_split_on_every_assert} edge_connected(g: Graph, a: int, b: int)
  requires has_edge(g, a, b)
  ensures connected(g, a, b)
{
  assert has_edge(g, a, b) || has_edge(g, b, a);
}

lemma {:vcs_split_on_every_assert} connected_diff(g: Graph, C: seq<bool>, a: int, b: int)
  requires is_valid_coloring(g, C)
  requires connected(g, a, b)
  ensures 0 <= a < |C| && 0 <= b < |C| && C[a] != C[b]
{
  if has_edge(g, a, b) {
    assert 0 <= a < |C| && 0 <= b < |C| && C[a] != C[b];
  } else {
    assert has_edge(g, b, a);
    assert 0 <= b < |C| && 0 <= a < |C| && C[a] != C[b];
  }
}

lemma {:vcs_split_on_every_assert} mem_append(s: seq<int>, x: int, y: int)
  requires x in s
  ensures x in s + [y]
{
  assert exists i :: 0 <= i < |s| && s[i] == x;
  var i :| 0 <= i < |s| && s[i] == x;
  assert (s + [y])[i] == s[i];
  assert (s + [y])[i] == x;
  assert x in s + [y];
}

lemma {:vcs_split_on_every_assert} mem_last(s: seq<int>, y: int)
  ensures y in s + [y]
{
  assert (s + [y])[|s|] == y;
  assert y in s + [y];
}

lemma {:vcs_split_on_every_assert} nbrs_complete(g: Graph, u: int, nbrs: seq<int>)
  requires well_formed(g)
  requires 0 <= u < |g.adj|
  requires forall k :: 0 <= k < |g.adj[u]| ==> g.adj[u][k] in nbrs
  requires forall x, t :: 0 <= x < |g.adj| && 0 <= t < |g.adj[x]| && g.adj[x][t] == u ==> x in nbrs
  ensures forall v :: 0 <= v < |g.adj| && connected(g, u, v) ==> v in nbrs
{
  forall v | 0 <= v < |g.adj| && connected(g, u, v)
    ensures v in nbrs
  {
    if has_edge(g, u, v) {
      var i :| 0 <= u < |g.adj| && 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
      assert g.adj[u][i] in nbrs;
      assert v in nbrs;
    } else {
      assert has_edge(g, v, u);
      var i :| 0 <= v < |g.adj| && 0 <= i < |g.adj[v]| && g.adj[v][i] == u;
      assert v in nbrs;
    }
  }
}

lemma {:vcs_split_on_every_assert} closed_step(g: Graph, color: seq<Option<bool>>, a: int, b: int)
  requires IsClosed(g, color)
  requires 0 <= a < |g.adj| && 0 <= b < |g.adj|
  requires connected(g, a, b)
  requires color[a].Some?
  ensures color[b].Some?
{
  assert connected(g, a, b);
  assert color[a].Some?;
}

lemma {:vcs_split_on_every_assert} edges_step(g: Graph, color: seq<Option<bool>>, a: int, b: int)
  requires EdgesOK(g, color)
  requires 0 <= a < |color| && 0 <= b < |color|
  requires has_edge(g, a, b)
  requires color[a].Some? && color[b].Some?
  ensures color[a].value != color[b].value
{
  assert has_edge(g, a, b);
  assert color[a].Some? && color[b].Some?;
}

lemma {:vcs_split_on_every_assert} forced_at(
  g: Graph, root: int, color: seq<Option<bool>>, in_comp: seq<bool>, C: seq<bool>, uu: int
)
  requires Forced(g, root, color, in_comp)
  requires is_valid_coloring(g, C)
  requires 0 <= uu < |g.adj|
  requires in_comp[uu]
  requires color[uu].Some?
  ensures |C| == |g.adj|
  ensures 0 <= root < |C|
  ensures 0 <= uu < |C|
  ensures C[uu] == (C[root] != color[uu].value)
{
  assert is_valid_coloring(g, C);
  assert 0 <= uu < |g.adj| && in_comp[uu] && color[uu].Some?;
  assert |C| == |g.adj|;
  assert 0 <= root < |C|;
  assert 0 <= uu < |C|;
  assert C[uu] == (C[root] != color[uu].value);
}

method {:vcs_split_on_every_assert} get_neighbors(g: Graph, u: int) returns (nbrs: seq<int>)
  requires well_formed(g)
  requires 0 <= u < |g.adj|
  ensures forall i :: 0 <= i < |nbrs| ==> 0 <= nbrs[i] < |g.adj| && connected(g, u, nbrs[i])
  ensures forall v :: 0 <= v < |g.adj| && connected(g, u, v) ==> v in nbrs
{
  var n := |g.adj|;
  var mark := seq(n, i => false);
  forall x | 0 <= x < n
    ensures mark[x] == false
  {
    assert mark[x] == false;
  }

  var j := 0;
  while j < |g.adj[u]|
    invariant 0 <= j <= |g.adj[u]|
    invariant |mark| == n
    invariant forall x :: 0 <= x < n && mark[x] ==> connected(g, u, x)
    invariant forall k :: 0 <= k < j ==> mark[g.adj[u][k]]
    decreases |g.adj[u]| - j
  {
    var v := g.adj[u][j];
    neighbor_in_range(g, u, j);
    edge_from_index(g, u, j);
    edge_connected(g, u, v);
    assert 0 <= v < n;
    assert connected(g, u, v);
    var markPrev := mark;
    mark := markPrev[v := true];
    assert mark == markPrev[v := true];
    assert mark[v] == true;
    forall x | 0 <= x < n && mark[x]
      ensures connected(g, u, x)
    {
      if x == v {
        assert connected(g, u, v);
      } else {
        assert mark[x] == markPrev[x];
        assert markPrev[x];
        assert connected(g, u, x);
      }
    }
    forall k | 0 <= k < j + 1
      ensures mark[g.adj[u][k]]
    {
      if k == j {
        assert g.adj[u][k] == v;
        assert mark[v];
      } else {
        assert markPrev[g.adj[u][k]];
        if g.adj[u][k] == v {
          assert mark[v];
        } else {
          assert mark[g.adj[u][k]] == markPrev[g.adj[u][k]];
        }
      }
    }
    j := j + 1;
  }

  var w := 0;
  while w < n
    invariant 0 <= w <= n
    invariant |mark| == n
    invariant forall x :: 0 <= x < n && mark[x] ==> connected(g, u, x)
    invariant forall k :: 0 <= k < |g.adj[u]| ==> mark[g.adj[u][k]]
    invariant forall x, t :: 0 <= x < w && 0 <= t < |g.adj[x]| && g.adj[x][t] == u ==> mark[x]
    decreases n - w
  {
    var t := 0;
    while t < |g.adj[w]|
      invariant 0 <= t <= |g.adj[w]|
      invariant |mark| == n
      invariant forall x :: 0 <= x < n && mark[x] ==> connected(g, u, x)
      invariant forall k :: 0 <= k < |g.adj[u]| ==> mark[g.adj[u][k]]
      invariant forall x, tt :: 0 <= x < w && 0 <= tt < |g.adj[x]| && g.adj[x][tt] == u ==> mark[x]
      invariant forall tt :: 0 <= tt < t && g.adj[w][tt] == u ==> mark[w]
      decreases |g.adj[w]| - t
    {
      if g.adj[w][t] == u {
        edge_from_index(g, w, t);
        edge_connected(g, w, u);
        connected_sym(g, w, u);
        assert connected(g, u, w);
        var markPrev := mark;
        mark := markPrev[w := true];
        assert mark == markPrev[w := true];
        assert mark[w];
        forall x | 0 <= x < n && mark[x]
          ensures connected(g, u, x)
        {
          if x == w {
            assert connected(g, u, w);
          } else {
            assert mark[x] == markPrev[x];
            assert markPrev[x];
            assert connected(g, u, x);
          }
        }
        forall k | 0 <= k < |g.adj[u]|
          ensures mark[g.adj[u][k]]
        {
          assert markPrev[g.adj[u][k]];
          if g.adj[u][k] == w {
            assert mark[w];
          } else {
            assert mark[g.adj[u][k]] == markPrev[g.adj[u][k]];
          }
        }
        forall x, tt | 0 <= x < w && 0 <= tt < |g.adj[x]| && g.adj[x][tt] == u
          ensures mark[x]
        {
          assert markPrev[x];
          if x == w {
            assert mark[w];
          } else {
            assert mark[x] == markPrev[x];
          }
        }
        forall tt | 0 <= tt < t && g.adj[w][tt] == u
          ensures mark[w]
        {
          assert mark[w];
        }
      }
      assert g.adj[w][t] == u ==> mark[w];
      forall tt | 0 <= tt < t + 1 && g.adj[w][tt] == u
        ensures mark[w]
      {
        if tt < t {
          assert mark[w];
        } else {
          assert tt == t;
          assert g.adj[w][t] == u;
          assert mark[w];
        }
      }
      t := t + 1;
    }
    forall x, tt | 0 <= x < w + 1 && 0 <= tt < |g.adj[x]| && g.adj[x][tt] == u
      ensures mark[x]
    {
      if x < w {
        assert mark[x];
      } else {
        assert x == w;
        assert 0 <= tt < |g.adj[w]|;
        assert g.adj[w][tt] == u;
        assert mark[w];
      }
    }
    w := w + 1;
  }

  nbrs := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |mark| == n
    invariant forall x :: 0 <= x < n && mark[x] ==> connected(g, u, x)
    invariant forall k :: 0 <= k < |g.adj[u]| ==> mark[g.adj[u][k]]
    invariant forall x, t :: 0 <= x < n && 0 <= t < |g.adj[x]| && g.adj[x][t] == u ==> mark[x]
    invariant forall t :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < i && mark[nbrs[t]] && connected(g, u, nbrs[t])
    invariant forall x :: 0 <= x < i && mark[x] ==> x in nbrs
    decreases n - i
  {
    if mark[i] {
      assert connected(g, u, i);
      var prev := nbrs;
      mem_last(prev, i);
      nbrs := prev + [i];
      assert nbrs == prev + [i];
      assert i in nbrs;
      forall x | 0 <= x < i + 1 && mark[x]
        ensures x in nbrs
      {
        if x == i {
          assert i in nbrs;
        } else {
          assert 0 <= x < i;
          assert x in prev;
          mem_append(prev, x, i);
          assert x in prev + [i];
          assert nbrs == prev + [i];
          assert x in nbrs;
        }
      }
      forall t | 0 <= t < |nbrs|
        ensures 0 <= nbrs[t] < i + 1 && mark[nbrs[t]] && connected(g, u, nbrs[t])
      {
        if t < |prev| {
          assert nbrs[t] == prev[t];
          assert 0 <= prev[t] < i;
          assert mark[prev[t]];
          assert connected(g, u, prev[t]);
        } else {
          assert t == |prev|;
          assert nbrs[t] == i;
          assert mark[i];
          assert connected(g, u, i);
        }
      }
    } else {
      forall x | 0 <= x < i + 1 && mark[x]
        ensures x in nbrs
      {
        assert x != i;
        assert 0 <= x < i;
        assert x in nbrs;
      }
    }
    i := i + 1;
  }

  forall k | 0 <= k < |g.adj[u]|
    ensures g.adj[u][k] in nbrs
  {
    neighbor_in_range(g, u, k);
    var v := g.adj[u][k];
    assert mark[v];
    assert 0 <= v < n;
    assert v in nbrs;
  }
  forall x, t | 0 <= x < n && 0 <= t < |g.adj[x]| && g.adj[x][t] == u
    ensures x in nbrs
  {
    assert mark[x];
    assert x in nbrs;
  }
  nbrs_complete(g, u, nbrs);
}

lemma {:vcs_split_on_every_assert} init_coloring_ok(g: Graph, color: seq<Option<bool>>)
  requires |color| == |g.adj|
  requires forall u :: 0 <= u < |color| ==> color[u].None?
  ensures IsClosed(g, color)
  ensures EdgesOK(g, color)
{
  forall u, v | 0 <= u < |g.adj| && 0 <= v < |g.adj| && connected(g, u, v) && color[u].Some?
    ensures color[v].Some?
  {
    assert color[u].None?;
    assert false;
  }
  forall u, v | 0 <= u < |g.adj| && 0 <= v < |g.adj| && has_edge(g, u, v) && color[u].Some? && color[v].Some?
    ensures color[u].value != color[v].value
  {
    assert color[u].None?;
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} to_valid(g: Graph, color: seq<Option<bool>>, colors: seq<bool>)
  requires well_formed(g)
  requires |color| == |g.adj|
  requires |colors| == |g.adj|
  requires EdgesOK(g, color)
  requires forall k :: 0 <= k < |g.adj| ==> color[k].Some? && colors[k] == color[k].value
  ensures is_valid_coloring(g, colors)
{
  assert |colors| == size(g);
  forall a, b | has_edge(g, a, b)
    ensures 0 <= a < |colors| && 0 <= b < |colors| && colors[a] != colors[b]
  {
    endpoints(g, a, b);
    assert 0 <= a < |color| && 0 <= b < |color|;
    assert color[a].Some? && color[b].Some?;
    edges_step(g, color, a, b);
    assert color[a].value != color[b].value;
    assert colors[a] != colors[b];
  }
}

lemma {:vcs_split_on_every_assert} uncolored_not_in_comp(
  color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>, queue: seq<int>, v: int
)
  requires InCompOK(color0, color, in_comp, queue)
  requires 0 <= v < |color|
  requires color[v].None?
  ensures !in_comp[v]
{
  if in_comp[v] {
    assert color[v].Some?;
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} neighbor_is_in_comp(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, u: int, v: int
)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires |color| == |g.adj|
  requires in_comp[u]
  requires connected(g, u, v)
  requires color[v].Some?
  ensures in_comp[v]
{
  if !in_comp[v] {
    assert color[v] == color0[v];
    assert color0[v].Some?;
    assert !connected(g, u, v);
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} forcing_extend(
  g: Graph, root: int, u: int, v: int, cu: bool,
  color: seq<Option<bool>>, in_comp: seq<bool>
)
  requires well_formed(g)
  requires Forced(g, root, color, in_comp)
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires u != v
  requires in_comp[u] && color[u] == Some(cu)
  requires color[v].None?
  requires !in_comp[v]
  requires connected(g, u, v)
  ensures Forced(g, root, color[v := Some(!cu)], in_comp[v := true])
{
  var n := |g.adj|;
  var color' := color[v := Some(!cu)];
  var in_comp' := in_comp[v := true];
  assert color[root] == Some(false);
  assert color[v].None?;
  assert root != v;
  assert color'[root] == Some(false);
  assert |color'| == n && |in_comp'| == n;
  assert 0 <= root < n;
  forall C | is_valid_coloring(g, C)
    ensures |C| == n && 0 <= root < |C| &&
      forall uu :: 0 <= uu < n && in_comp'[uu] && color'[uu].Some? ==>
        0 <= uu < |C| && C[uu] == (C[root] != color'[uu].value)
  {
    assert |C| == n && 0 <= root < |C|;
    forced_at(g, root, color, in_comp, C, u);
    assert C[u] == (C[root] != color[u].value);
    assert C[u] == (C[root] != cu);
    forall uu | 0 <= uu < n && in_comp'[uu] && color'[uu].Some?
      ensures 0 <= uu < |C| && C[uu] == (C[root] != color'[uu].value)
    {
      assert 0 <= uu < |C|;
      if uu == v {
        connected_diff(g, C, u, v);
        assert C[v] != C[u];
        xor_step(C[root], cu, C[u], C[v]);
        assert color'[v].value == !cu;
        assert C[v] == (C[root] != !cu);
        assert C[v] == (C[root] != color'[v].value);
      } else {
        assert in_comp[uu];
        assert color'[uu] == color[uu];
        assert color[uu].Some?;
        forced_at(g, root, color, in_comp, C, uu);
        assert C[uu] == (C[root] != color[uu].value);
        assert C[uu] == (C[root] != color'[uu].value);
      }
    }
  }
  assert Forced(g, root, color', in_comp');
}

lemma {:vcs_split_on_every_assert} prove_not_bipartite(
  g: Graph, root: int, u: int, v: int,
  color: seq<Option<bool>>, in_comp: seq<bool>
)
  requires Forced(g, root, color, in_comp)
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires in_comp[u] && in_comp[v]
  requires color[u].Some? && color[v].Some?
  requires color[u].value == color[v].value
  requires connected(g, u, v)
  ensures !is_bipartite(g)
{
  if is_bipartite(g) {
    var C :| is_valid_coloring(g, C);
    forced_at(g, root, color, in_comp, C, u);
    forced_at(g, root, color, in_comp, C, v);
    assert C[u] == (C[root] != color[u].value);
    assert C[v] == (C[root] != color[v].value);
    assert color[u].value == color[v].value;
    assert C[u] == C[v];
    connected_diff(g, C, u, v);
    assert C[u] != C[v];
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} init_comp_inv(g: Graph, color0: seq<Option<bool>>, root: int)
  requires well_formed(g)
  requires |color0| == |g.adj|
  requires 0 <= root < |g.adj|
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  ensures var n := |g.adj|;
          var color := color0[root := Some(false)];
          var in_comp := (seq(n, i => false))[root := true];
          var queue := [root];
          && CompInv(g, color0, color, in_comp, queue, 0, root)
          && Forced(g, root, color, in_comp)
          && QueueOK(n, color, in_comp, queue)
          && InCompOK(color0, color, in_comp, queue)
          && OutsideOK(color0, color, in_comp)
          && Separated(g, color0, in_comp)
          && ProcessedOK(g, color, in_comp, queue, 0)
          && color[root] == Some(false)
          && in_comp[root]
{
  var n := |g.adj|;
  var color := color0[root := Some(false)];
  var base := seq(n, i => false);
  var in_comp := base[root := true];
  var queue := [root];
  var qh := 0;

  forall i | 0 <= i < n
    ensures in_comp[i] == (i == root)
  {
    if i == root {
      assert in_comp[i] == true;
    } else {
      assert base[i] == false;
      assert in_comp[i] == false;
    }
  }
  forall i | 0 <= i < n && i != root
    ensures color[i] == color0[i]
  {
    assert color[i] == color0[i];
  }

  forall k | 0 <= k < |queue|
    ensures 0 <= queue[k] < n && in_comp[queue[k]] && color[queue[k]].Some?
  {
    assert queue[k] == root;
    assert color[root] == Some(false);
    assert in_comp[root];
  }
  assert QueueOK(n, color, in_comp, queue);

  forall uu | 0 <= uu < n && in_comp[uu]
    ensures uu in queue && color[uu].Some? && color0[uu].None?
  {
    assert uu == root;
    assert root in queue;
    assert color0[root].None?;
    assert color[root].Some?;
  }
  assert InCompOK(color0, color, in_comp, queue);

  forall uu | 0 <= uu < n && !in_comp[uu]
    ensures color[uu] == color0[uu]
  {
    assert uu != root;
    assert color[uu] == color0[uu];
  }
  assert OutsideOK(color0, color, in_comp);

  forall a, b | 0 <= a < n && 0 <= b < n && in_comp[a] && color0[b].Some?
    ensures !connected(g, a, b)
  {
    assert a == root;
    assert color0[b].Some?;
    if connected(g, root, b) {
      connected_sym(g, root, b);
      assert connected(g, b, root);
      closed_step(g, color0, b, root);
      assert color0[root].Some?;
      assert false;
    }
    assert !connected(g, root, b);
  }
  assert Separated(g, color0, in_comp);

  assert 0 <= qh <= |queue|;
  assert ProcessedOK(g, color, in_comp, queue, qh);

  assert color[root] == Some(false);
  forall C | is_valid_coloring(g, C)
    ensures |C| == n && 0 <= root < |C| &&
      forall uu :: 0 <= uu < n && in_comp[uu] && color[uu].Some? ==>
        0 <= uu < |C| && C[uu] == (C[root] != color[uu].value)
  {
    assert |C| == size(g);
    assert |C| == n;
    forall uu | 0 <= uu < n && in_comp[uu] && color[uu].Some?
      ensures 0 <= uu < |C| && C[uu] == (C[root] != color[uu].value)
    {
      assert uu == root;
      assert color[uu].value == false;
      root_force(C[uu]);
      assert C[uu] == (C[root] != false);
      assert C[uu] == (C[root] != color[uu].value);
    }
  }
  assert Forced(g, root, color, in_comp);

  assert color[root] == Some(false);
  assert in_comp[root];
  assert CompInv(g, color0, color, in_comp, queue, qh, root);
}

lemma {:vcs_split_on_every_assert} after_color(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, v: int, cu: bool
)
  requires well_formed(g)
  requires |g.adj| == |color0| == |color| == |in_comp|
  requires 0 <= root < |g.adj|
  requires 0 <= qh < |queue|
  requires u == queue[qh]
  requires 0 <= u < |g.adj| && 0 <= v < |g.adj|
  requires color[root] == Some(false)
  requires in_comp[root]
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires color[u] == Some(cu) && in_comp[u]
  requires color[v].None? && !in_comp[v]
  requires connected(g, u, v)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires Forced(g, root, color, in_comp)
  ensures CompInv(g, color0, color[v := Some(!cu)], in_comp[v := true], queue + [v], qh, root)
  ensures Forced(g, root, color[v := Some(!cu)], in_comp[v := true])
  ensures QueueOK(|g.adj|, color[v := Some(!cu)], in_comp[v := true], queue + [v])
  ensures InCompOK(color0, color[v := Some(!cu)], in_comp[v := true], queue + [v])
  ensures OutsideOK(color0, color[v := Some(!cu)], in_comp[v := true])
  ensures Separated(g, color0, in_comp[v := true])
  ensures ProcessedOK(g, color[v := Some(!cu)], in_comp[v := true], queue + [v], qh)
  ensures (color[v := Some(!cu)])[root] == Some(false)
  ensures (in_comp[v := true])[root]
  ensures (color[v := Some(!cu)])[u] == Some(cu)
  ensures u != v
{
  var n := |g.adj|;
  var color' := color[v := Some(!cu)];
  var in_comp' := in_comp[v := true];
  var queue' := queue + [v];

  assert color[u].Some? && color[v].None?;
  assert u != v;
  assert color[root] == Some(false);
  assert root != v;
  assert color'[root] == Some(false);
  assert in_comp'[root] == in_comp[root];
  assert in_comp'[root];
  assert color'[u] == Some(cu);
  assert |color'| == n && |in_comp'| == n && |queue'| == |queue| + 1;
  assert 0 <= qh <= |queue'|;
  assert queue'[qh] == queue[qh];

  forall k | 0 <= k < |queue|
    ensures queue[k] != v
  {
    assert 0 <= queue[k] < n;
    assert color[queue[k]].Some?;
    assert color[v].None?;
    assert queue[k] != v;
  }

  forall k | 0 <= k < |queue'|
    ensures 0 <= queue'[k] < n && in_comp'[queue'[k]] && color'[queue'[k]].Some?
  {
    if k < |queue| {
      assert queue'[k] == queue[k];
      assert queue[k] != v;
      assert in_comp'[queue[k]] == in_comp[queue[k]];
      assert color'[queue[k]] == color[queue[k]];
      assert in_comp[queue[k]] && color[queue[k]].Some?;
    } else {
      assert k == |queue|;
      assert queue'[k] == v;
      assert in_comp'[v] && color'[v].Some?;
    }
  }
  assert QueueOK(n, color', in_comp', queue');

  assert !in_comp[v];
  assert color[v] == color0[v];
  assert color0[v].None?;

  forall uu | 0 <= uu < n && in_comp'[uu]
    ensures uu in queue' && color'[uu].Some? && color0[uu].None?
  {
    if uu == v {
      mem_last(queue, v);
      assert v in queue + [v];
      assert queue' == queue + [v];
      assert v in queue';
      assert color'[v].Some?;
      assert color0[v].None?;
    } else {
      assert in_comp[uu];
      assert uu in queue;
      mem_append(queue, uu, v);
      assert uu in queue + [v];
      assert uu in queue';
      assert uu != v;
      assert color'[uu] == color[uu];
      assert color[uu].Some? && color0[uu].None?;
    }
  }
  assert InCompOK(color0, color', in_comp', queue');

  forall uu | 0 <= uu < n && !in_comp'[uu]
    ensures color'[uu] == color0[uu]
  {
    assert uu != v;
    assert !in_comp[uu];
    assert color'[uu] == color[uu];
    assert color[uu] == color0[uu];
  }
  assert OutsideOK(color0, color', in_comp');

  forall a, b | 0 <= a < n && 0 <= b < n && in_comp'[a] && color0[b].Some?
    ensures !connected(g, a, b)
  {
    assert color0[b].Some?;
    if a == v {
      if connected(g, v, b) {
        connected_sym(g, v, b);
        assert connected(g, b, v);
        closed_step(g, color0, b, v);
        assert color0[v].Some?;
        assert false;
      }
      assert !connected(g, v, b);
    } else {
      assert in_comp[a];
      assert !connected(g, a, b);
    }
  }
  assert Separated(g, color0, in_comp');

  forall p | 0 <= p < qh
    ensures !connected(g, queue[p], v)
  {
    if connected(g, queue[p], v) {
      assert 0 <= queue[p] < n && color[queue[p]].Some?;
      assert in_comp[v] && color[v].Some?;
      assert false;
    }
  }

  forall p | 0 <= p < qh
    ensures 0 <= queue'[p] < n && color'[queue'[p]].Some? &&
      forall w :: 0 <= w < n && connected(g, queue'[p], w) ==>
        in_comp'[w] && color'[w].Some? && color'[w].value != color'[queue'[p]].value
  {
    assert queue'[p] == queue[p];
    assert queue[p] != v;
    assert color'[queue[p]] == color[queue[p]];
    assert color[queue[p]].Some?;
    forall w | 0 <= w < n && connected(g, queue[p], w)
      ensures in_comp'[w] && color'[w].Some? && color'[w].value != color'[queue[p]].value
    {
      assert connected(g, queue[p], w);
      if w == v {
        assert connected(g, queue[p], v);
        assert false;
      }
      assert w != v;
      assert in_comp[w] && color[w].Some?;
      assert color[w].value != color[queue[p]].value;
      assert in_comp'[w] == in_comp[w];
      assert color'[w] == color[w];
    }
  }
  assert ProcessedOK(g, color', in_comp', queue', qh);

  forcing_extend(g, root, u, v, cu, color, in_comp);
  assert Forced(g, root, color', in_comp');

  assert color'[root] == Some(false);
  assert in_comp'[root];
  assert color0[root].None?;
  assert IsClosed(g, color0);
  assert EdgesOK(g, color0);
  assert 0 <= qh <= |queue'|;
  assert CompInv(g, color0, color', in_comp', queue', qh, root);
}

lemma {:vcs_split_on_every_assert} step_qh(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int
)
  requires well_formed(g)
  requires |color0| == |g.adj| == |color| == |in_comp|
  requires 0 <= root < |g.adj|
  requires 0 <= qh < |queue|
  requires 0 <= queue[qh] < |g.adj|
  requires color[queue[qh]].Some?
  requires color[root] == Some(false)
  requires in_comp[root]
  requires color0[root].None?
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires Forced(g, root, color, in_comp)
  requires forall w :: 0 <= w < |g.adj| && connected(g, queue[qh], w) ==>
      in_comp[w] && color[w].Some? && color[w].value != color[queue[qh]].value
  ensures ProcessedOK(g, color, in_comp, queue, qh + 1)
  ensures CompInv(g, color0, color, in_comp, queue, qh + 1, root)
{
  var n := |g.adj|;
  var u := queue[qh];
  assert 0 <= qh + 1 <= |queue|;
  assert ProcessedOK(g, color, in_comp, queue, qh);
  forall p | 0 <= p < qh + 1
    ensures 0 <= queue[p] < n && color[queue[p]].Some? &&
      forall w :: 0 <= w < n && connected(g, queue[p], w) ==>
        in_comp[w] && color[w].Some? && color[w].value != color[queue[p]].value
  {
    if p < qh {
      assert 0 <= queue[p] < n;
      assert color[queue[p]].Some?;
      forall w | 0 <= w < n && connected(g, queue[p], w)
        ensures in_comp[w] && color[w].Some? && color[w].value != color[queue[p]].value
      {
        assert connected(g, queue[p], w);
        assert in_comp[w] && color[w].Some?;
        assert color[w].value != color[queue[p]].value;
      }
    } else {
      assert p == qh;
      assert queue[p] == u;
      assert 0 <= u < n;
      assert color[u].Some?;
      forall w | 0 <= w < n && connected(g, queue[p], w)
        ensures in_comp[w] && color[w].Some? && color[w].value != color[queue[p]].value
      {
        assert u == queue[qh];
        assert connected(g, queue[qh], w);
        assert in_comp[w] && color[w].Some?;
        assert color[w].value != color[queue[qh]].value;
        assert color[queue[p]].value == color[u].value;
        assert color[queue[qh]].value == color[u].value;
      }
    }
  }
  assert ProcessedOK(g, color, in_comp, queue, qh + 1);
  assert CompInv(g, color0, color, in_comp, queue, qh + 1, root);
}

lemma {:vcs_split_on_every_assert} prefix_covers(
  g: Graph, color: seq<Option<bool>>, in_comp: seq<bool>,
  u: int, cu: bool, nbrs: seq<int>
)
  requires 0 <= u < |g.adj|
  requires |color| == |g.adj| == |in_comp|
  requires color[u] == Some(cu)
  requires forall t :: 0 <= t < |nbrs| ==>
      0 <= nbrs[t] < |g.adj| && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  requires forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==> w in nbrs
  ensures forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==>
      in_comp[w] && color[w].Some? && color[w].value != cu
{
  forall w | 0 <= w < |g.adj| && connected(g, u, w)
    ensures in_comp[w] && color[w].Some? && color[w].value != cu
  {
    assert w in nbrs;
    var t :| 0 <= t < |nbrs| && nbrs[t] == w;
    assert 0 <= nbrs[t] < |g.adj|;
    assert in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu;
    assert in_comp[w] && color[w].Some? && color[w].value != cu;
  }
}

lemma {:vcs_split_on_every_assert} finish(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int
)
  requires well_formed(g)
  requires |color| == |g.adj| == |color0| == |in_comp|
  requires 0 <= root < |g.adj|
  requires qh == |queue|
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires color[root].Some?
  ensures IsClosed(g, color)
  ensures EdgesOK(g, color)
  ensures forall uu :: 0 <= uu < |g.adj| && color0[uu].Some? ==> color[uu] == color0[uu]
  ensures color[root].Some?
  ensures |color| == |g.adj|
{
  var n := |g.adj|;
  forall a, b | 0 <= a < n && 0 <= b < n && connected(g, a, b) && color[a].Some?
    ensures color[b].Some?
  {
    if in_comp[a] {
      assert a in queue;
      var p :| 0 <= p < |queue| && queue[p] == a;
      assert p < qh;
      assert queue[p] == a;
      assert connected(g, queue[p], b);
      assert in_comp[b] && color[b].Some?;
    } else {
      assert color[a] == color0[a];
      assert color0[a].Some?;
      closed_step(g, color0, a, b);
      assert color0[b].Some?;
      if in_comp[b] {
        assert color0[b].None?;
        assert false;
      }
      assert !in_comp[b];
      assert color[b] == color0[b];
      assert color[b].Some?;
    }
  }
  assert IsClosed(g, color);

  forall a, b | 0 <= a < n && 0 <= b < n && has_edge(g, a, b) && color[a].Some? && color[b].Some?
    ensures color[a].value != color[b].value
  {
    edge_connected(g, a, b);
    assert connected(g, a, b);
    if in_comp[a] && in_comp[b] {
      assert a in queue;
      var p :| 0 <= p < |queue| && queue[p] == a;
      assert p < qh;
      assert queue[p] == a;
      assert connected(g, queue[p], b);
      assert color[b].value != color[queue[p]].value;
      assert color[queue[p]] == color[a];
      assert color[b].value != color[a].value;
    } else if !in_comp[a] && !in_comp[b] {
      assert color[a] == color0[a];
      assert color[b] == color0[b];
      assert color0[a].Some? && color0[b].Some?;
      edges_step(g, color0, a, b);
      assert color0[a].value != color0[b].value;
      assert color[a].value != color[b].value;
    } else if in_comp[a] {
      assert !in_comp[b];
      assert color[b] == color0[b];
      assert color0[b].Some?;
      assert in_comp[a] && color0[b].Some?;
      assert !connected(g, a, b);
      assert false;
    } else {
      assert in_comp[b] && !in_comp[a];
      assert color[a] == color0[a];
      assert color0[a].Some?;
      connected_sym(g, a, b);
      assert connected(g, b, a);
      assert in_comp[b] && color0[a].Some?;
      assert !connected(g, b, a);
      assert false;
    }
  }
  assert EdgesOK(g, color);

  forall uu | 0 <= uu < n && color0[uu].Some?
    ensures color[uu] == color0[uu]
  {
    if in_comp[uu] {
      assert color0[uu].None?;
      assert false;
    }
    assert !in_comp[uu];
    assert color[uu] == color0[uu];
  }
}

lemma {:vcs_split_on_every_assert} pack_inv(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, cu: bool, nbrs: seq<int>, j: int,
  cn0: int, qlen0: int, qh0: int
)
  requires CompInv(g, color0, color, in_comp, queue, qh, root)
  requires Forced(g, root, color, in_comp)
  requires QueueOK(|g.adj|, color, in_comp, queue)
  requires InCompOK(color0, color, in_comp, queue)
  requires OutsideOK(color0, color, in_comp)
  requires Separated(g, color0, in_comp)
  requires ProcessedOK(g, color, in_comp, queue, qh)
  requires IsClosed(g, color0)
  requires EdgesOK(g, color0)
  requires color0[root].None?
  requires color[root] == Some(false)
  requires in_comp[root]
  requires |color| == |g.adj| && |in_comp| == |g.adj|
  requires 0 <= qh <= |queue|
  requires qh == qh0 && qh0 < qlen0 && |queue| >= qlen0
  requires qh < |queue|
  requires u == queue[qh] && 0 <= u < |g.adj|
  requires color[u] == Some(cu) && in_comp[u]
  requires count_none(color) + |queue| == cn0 + qlen0
  requires count_none(color) >= 0
  requires forall t :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < |g.adj| && connected(g, u, nbrs[t])
  requires forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==> w in nbrs
  requires 0 <= j <= |nbrs|
  requires forall t :: 0 <= t < j ==>
      0 <= nbrs[t] < |g.adj| && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  ensures NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0)
{
  assert NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0);
}

lemma {:vcs_split_on_every_assert} unpack_inv(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, cu: bool, nbrs: seq<int>, j: int,
  cn0: int, qlen0: int, qh0: int
)
  requires NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0)
  ensures CompInv(g, color0, color, in_comp, queue, qh, root)
  ensures Forced(g, root, color, in_comp)
  ensures QueueOK(|g.adj|, color, in_comp, queue)
  ensures InCompOK(color0, color, in_comp, queue)
  ensures OutsideOK(color0, color, in_comp)
  ensures Separated(g, color0, in_comp)
  ensures ProcessedOK(g, color, in_comp, queue, qh)
  ensures IsClosed(g, color0)
  ensures EdgesOK(g, color0)
  ensures color0[root].None?
  ensures color[root] == Some(false)
  ensures in_comp[root]
  ensures |color| == |g.adj| && |in_comp| == |g.adj|
  ensures 0 <= qh <= |queue|
  ensures qh == qh0 && qh0 < qlen0 && |queue| >= qlen0
  ensures qh < |queue|
  ensures u == queue[qh] && 0 <= u < |g.adj|
  ensures color[u] == Some(cu) && in_comp[u]
  ensures count_none(color) + |queue| == cn0 + qlen0
  ensures count_none(color) >= 0
  ensures forall t :: 0 <= t < |nbrs| ==> 0 <= nbrs[t] < |g.adj| && connected(g, u, nbrs[t])
  ensures forall w :: 0 <= w < |g.adj| && connected(g, u, w) ==> w in nbrs
  ensures 0 <= j <= |nbrs|
  ensures forall t :: 0 <= t < j ==>
      0 <= nbrs[t] < |g.adj| && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  ensures well_formed(g)
  ensures |color0| == |g.adj|
  ensures 0 <= root < |g.adj|
{
  assert NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0);
}

lemma {:vcs_split_on_every_assert} extend_inv(
  g: Graph, color0: seq<Option<bool>>, color: seq<Option<bool>>, in_comp: seq<bool>,
  queue: seq<int>, qh: int, root: int, u: int, cu: bool, v: int, nbrs: seq<int>, j: int,
  cn0: int, qlen0: int, qh0: int
)
  requires NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0)
  requires 0 <= j < |nbrs|
  requires v == nbrs[j]
  requires 0 <= v < |g.adj|
  requires in_comp[v] && color[v].Some? && color[v].value != cu
  ensures NeighborInv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j + 1, cn0, qlen0, qh0)
{
  unpack_inv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j, cn0, qlen0, qh0);
  var n := |g.adj|;
  assert 0 <= j + 1 <= |nbrs|;
  forall t | 0 <= t < j + 1
    ensures 0 <= nbrs[t] < n && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu
  {
    if t < j {
      assert 0 <= nbrs[t] < n && in_comp[nbrs[t]] && color[nbrs[t]].Some? && color[nbrs[t]].value != cu;
    } else {
      assert t == j;
      assert nbrs[t] == v;
      assert 0 <= v < n && in_comp[v] && color[v].Some? && color[v].value != cu;
    }
  }
  pack_inv(g, color0, color, in_comp, queue, qh, root, u, cu, nbrs, j + 1, cn0, qlen0, qh0);
}

method {:vcs_split_on_every_assert} consider_neighbor(
  g: Graph,
  color0: seq<Option<bool>>,
  colorIn: seq<Option<bool>>,
  inCompIn: seq<bool>,
  queueIn: seq<int>,
  qh: int,
  root: int,
  u: int,
  cu: bool,
  v: int,
  nbrs: seq<int>,
  j: int,
  qlen0: int,
  qh0: int,
  ghost cn0: int
) returns (colorOut: seq<Option<bool>>, inCompOut: seq<bool>, queueOut: seq<int>, failed: bool)
