    assert r.Some?;
    var c := r.value;
    assert |c| == n;
    assert IsClosed(graph, c);
    assert EdgesOK(graph, c);
    assert c[s].Some?;
    assert forall uu :: 0 <= uu < n && color0[uu].Some? ==> c[uu] == color0[uu];
