      if u < s {
        assert color0[u].Some?;
        assert c[u] == color0[u];
        assert color[u] == c[u];
        assert color[u].Some?;
      } else {
        assert u == s;
        assert c[s].Some?;
        assert color[u] == c[u];
        assert color[u].Some?;
      }
    }
    assert |color| == n;
    assert IsClosed(graph, color);
    assert EdgesOK(graph, color);
    return;
  } else {
    assert color0[s].Some?;
    color := color0;
    failed := false;
    forall u | 0 <= u < s + 1
      ensures color[u].Some?
    {
      if u < s {
        assert color0[u].Some?;
        assert color[u] == color0[u];
      } else {
        assert u == s;
        assert color0[s].Some?;
        assert color[u] == color0[u];
