lemma {:vcs_split_on_every_assert} drop_update<T>(s: seq<T>, i: int, x: T)
  requires 0 <= i < |s|
  ensures if i == 0 then (s[i := x])[1..] == s[1..]
          else (s[i := x])[1..] == (s[1..])[i - 1 := x]
{
  var a := (s[i := x])[1..];
  if |s| == 1 {
    assert i == 0;
    assert |a| == 0;
    assert |s[1..]| == 0;
    assert a == s[1..];
  } else if i == 0 {
    var b := s[1..];
    assert |a| == |b|;
    forall k | 0 <= k < |a|
      ensures a[k] == b[k]
    {
      assert a[k] == (s[0 := x])[k + 1];
      assert k + 1 != 0;
      assert (s[0 := x])[k + 1] == s[k + 1];
      assert b[k] == s[k + 1];
    }
    assert forall k :: 0 <= k < |a| ==> a[k] == b[k];
    assert a == b;
  } else {
    var b := (s[1..])[i - 1 := x];
    assert |a| == |s| - 1;
    assert |b| == |s| - 1;
    assert 0 <= i - 1 < |s| - 1;
    forall k | 0 <= k < |a|
      ensures a[k] == b[k]
    {
      assert a[k] == (s[i := x])[k + 1];
      if k + 1 == i {
        assert (s[i := x])[k + 1] == x;
        assert b[k] == x;
      } else {
        assert (s[i := x])[k + 1] == s[k + 1];
        assert (s[1..])[k] == s[k + 1];
        assert k != i - 1;
        assert b[k] == (s[1..])[k];
      }
    }
    assert forall k :: 0 <= k < |a| ==> a[k] == b[k];
    assert a == b;
  }
}

lemma {:vcs_split_on_every_assert} count_none_update(color: seq<Option<bool>>, v: int, b: bool)
  requires 0 <= v < |color|
  requires color[v].None?
  ensures count_none(color) >= 1
  ensures count_none(color[v := Some(b)]) == count_none(color) - 1
  decreases |color|
{
  count_none_nonneg(color);
  if v == 0 {
    var rest := color[1..];
    var color' := color[v := Some(b)];
    assert color'[0] == Some(b);
    drop_update(color, v, Some(b));
    assert color'[1..] == rest;
    assert count_none(color) == (if color[0].None? then 1 else 0) + count_none(color[1..]);
    assert color[0].None?;
    assert count_none(color) == 1 + count_none(rest);
    assert count_none(color') == (if color'[0].None? then 1 else 0) + count_none(color'[1..]);
    assert count_none(color') == count_none(rest);
    assert count_none(color) >= 1;
  } else {
    var rest := color[1..];
    assert 0 <= v - 1 < |rest|;
    assert rest[v - 1] == color[v];
    assert rest[v - 1].None?;
    count_none_update(rest, v - 1, b);
    var color' := color[v := Some(b)];
    drop_update(color, v, Some(b));
    assert color'[0] == color[0];
    assert color'[1..] == rest[v - 1 := Some(b)];
    var delta := if color[0].None? then 1 else 0;
    assert count_none(color) == (if color[0].None? then 1 else 0) + count_none(color[1..]);
    assert count_none(color) == delta + count_none(rest);
    assert count_none(color') == (if color'[0].None? then 1 else 0) + count_none(color'[1..]);
    assert count_none(color') == delta + count_none(color'[1..]);
    assert count_none(color'[1..]) == count_none(rest) - 1;
    assert count_none(color') == count_none(color) - 1;
    assert count_none(rest) >= 1;
    assert count_none(color) >= 1;
  }
}

