  requires Cv != Cu
  ensures Cv == (cr != !cu)
{
  if cu {
    assert (cr != true) == !cr;
    assert Cu == !cr;
    assert Cv == !Cu;
    assert Cv == cr;
    assert (cr != false) == cr;
  } else {
    assert (cr != false) == cr;
    assert Cu == cr;
    assert Cv == !Cu;
    assert Cv == !cr;
    assert (cr != true) == !cr;
  }
