      assert connected(g, a, b);
    } else {
      assert has_edge(g, a, b);
      assert connected(g, a, b);
    }
  }
  assert connected(g, a, b) ==> connected(g, b, a);
  assert connected(g, b, a) ==> connected(g, a, b);
