lemma PowSucc(b: nat, e: nat)
  ensures spec_pow(b, e + 1) == b * spec_pow(b, e)
{
  assert e + 1 > 0;
  assert (e + 1) - 1 == e;
  assert spec_pow(b, e + 1) == b * spec_pow(b, (e + 1) - 1);
