lemma DivLe(d: nat, n: nat)
  requires n > 0 && divides(d, n)
  ensures d <= n
{
  var k: nat :| d * k == n;
  if k == 0 {
    assert d * 0 == 0;
    assert false;
  }
  MulNonneg(d, k - 1);
  assert d * k == d * (k - 1) + d;
}

lemma DividesMod(d: nat, x: nat, y: nat)
  requires y > 0 && divides(d, x) && divides(d, y)
  ensures divides(d, x % y)
{
  var k1: nat :| d * k1 == x;
  var k2: nat :| d * k2 == y;
  var q: nat := x / y;
  var r: nat := x % y;
  assert x == q * y + r;
  assert q * y == q * (d * k2);
  assert q * (d * k2) == d * (q * k2);
  var k: int := k1 - q * k2;
  assert d * k == d * k1 - d * (q * k2);
  assert d * k == r;
  if d == 0 {
    assert d * k2 == 0;
    assert false;
  }
  if k < 0 {
    MulPosNeg(d, k);
    assert false;
  }
  var kn: nat := k;
  assert d * kn == r;
}

