  assert divides(x, x);
  assert x * 0 == 0;
  assert divides(x, y);
  assert divides(x, a) && divides(x, b);
  forall d: nat | divides(d, a) && divides(d, b)
    ensures d <= x
  {
    assert divides(d, x);
    DivLe(d, x);
  }
  assert is_gcd(x, a, b);
  SpecGcdEq(x, a, b);
  res := x;
}

