lemma EmptyFlowValid(
    graph: CapacityGraph,
    s: int,
    t: int)
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    ensures is_valid_flow(view(graph), map[], s, t)
{
    var g := view(graph);
    var empty: FlowMap := map[];

    assert respects_capacity(g, empty);
    assert forall u: int, v: int ::
        (u, v) in empty ==> empty[(u, v)] >= 0;

    assert is_conserved(g, empty, s, t) by
    {
        forall u: int |
            0 <= u < |g| && u != s && u != t
            ensures total_flow_in(g, empty, u)
                == total_flow_out(g, empty, u)
        {
            EmptySumIn(g, u, |g|);
            EmptySumOut(g, u, |g[u]|);
            ActualSumInAgreement(g, empty, u, |g|);
            ActualSumOutAgreement(g, empty, u, |g[u]|);
        }
    }
}

lemma {:vcs_split_on_every_assert} EmptyCanonicalValid(
    graph: CapacityGraph,
    s: int,
    t: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    ensures CanonicalPrefix(
                map[], size(graph), size(graph) * size(graph))
            in EnumeratedFlows(
                view(graph), size(graph) * size(graph))
    ensures ActualConservedPrefix(
                view(graph),
                CanonicalPrefix(
                    map[], size(graph), size(graph) * size(graph)),
                s, t, size(graph))
    ensures ActualFlowValue(
                view(graph),
                CanonicalPrefix(
                    map[], size(graph), size(graph) * size(graph)),
                s) == 0
{
    var g := view(graph);
    var empty: FlowMap := map[];
    var z := CanonicalPrefix(empty, |g|, |g| * |g|);

    assert 0 < |g|;
    EmptyFlowValid(graph, s, t);
    assert is_valid_flow(g, empty, s, t);

    CanonicalEnumerated(g, empty, s, t);
    CanonicalPreservesConservation(graph, empty, s, t);

    EmptySumOut(g, s, |g[s]|);
    EmptySumIn(g, s, |g|);
    ActualFlowValueAgreement(g, empty, s);
    assert flow_val(g, empty, s) == 0;
}

method {:vcs_split_on_every_assert} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    assert 0 < |g|;

    var all := EnumeratedFlows(g, |g| * |g|);
    var remaining := all;

    var best := CanonicalPrefix(map[], |g|, |g| * |g|);
    max_val := 0;

    EmptyCanonicalValid(graph, s, t);
    EnumeratedConservedIsValid(graph, best, s, t);
    ActualFlowValueAgreement(g, best, s);

    assert forall f: FlowMap ::
        f in all - remaining
        && ActualConservedPrefix(g, f, s, t, |g|)
        ==> ActualFlowValue(g, f, s) <= max_val;

    while remaining != {}
        invariant remaining <= all
        invariant best in all
        invariant ActualConservedPrefix(g, best, s, t, |g|)
        invariant is_valid_flow(g, best, s, t)
        invariant ActualFlowValue(g, best, s) == max_val
        invariant flow_val(g, best, s) == max_val
        invariant forall f: FlowMap ::
            f in all - remaining
            && ActualConservedPrefix(g, f, s, t, |g|)
            ==> ActualFlowValue(g, f, s) <= max_val
        decreases |remaining|
    {
        var oldRemaining := remaining;
        var oldMax := max_val;
        var f :| f in oldRemaining;

        if ActualConservedPrefix(g, f, s, t, |g|) {
            EnumeratedConservedIsValid(graph, f, s, t);
            ActualFlowValueAgreement(g, f, s);

            if ActualFlowValue(g, f, s) > max_val {
                best := f;
                max_val := ActualFlowValue(g, f, s);
            }
        }

        assert oldMax <= max_val;
        remaining := oldRemaining - {f};

        assert remaining < oldRemaining;
        assert remaining <= all;

        assert forall q: FlowMap ::
            q in all - remaining
            && ActualConservedPrefix(g, q, s, t, |g|)
            ==> ActualFlowValue(g, q, s) <= max_val by
        {
            forall q: FlowMap |
                q in all - remaining
                && ActualConservedPrefix(g, q, s, t, |g|)
                ensures ActualFlowValue(g, q, s) <= max_val
            {
                if q in oldRemaining {
                    assert q == f;
                    if ActualFlowValue(g, f, s) > oldMax {
                        assert max_val == ActualFlowValue(g, f, s);
                    } else {
                        assert ActualFlowValue(g, f, s) <= oldMax;
                    }
                } else {
                    assert q in all - oldRemaining;
                    assert ActualFlowValue(g, q, s) <= oldMax;
                }
            }
        }
    }

    assert remaining == {};
    assert forall f: FlowMap ::
        f in all
        && ActualConservedPrefix(g, f, s, t, |g|)
        ==> ActualFlowValue(g, f, s) <= max_val;

    assert forall other: FlowMap
        {:trigger is_valid_flow(g, other, s, t)} ::
        is_valid_flow(g, other, s, t)
        ==> flow_val(g, best, s) >= flow_val(g, other, s) by
    {
        forall other: FlowMap |
            is_valid_flow(g, other, s, t)
            ensures flow_val(g, best, s)
                >= flow_val(g, other, s)
        {
            var canonical :=
                CanonicalPrefix(other, |g|, |g| * |g|);

            CanonicalEnumerated(g, other, s, t);
            CanonicalPreservesConservation(
                graph, other, s, t);

            assert canonical in all;
            assert ActualConservedPrefix(
                g, canonical, s, t, |g|);
            assert ActualFlowValue(g, canonical, s)
                == flow_val(g, other, s);
            assert ActualFlowValue(g, canonical, s)
                <= max_val;
            assert flow_val(g, best, s) == max_val;
        }
    }

    assert is_max_flow(g, best, s, t);
    assert flow_val(g, best, s) == max_val;
    assert exists f: FlowMap ::
        is_max_flow(g, f, s, t)
        && flow_val(g, f, s) == max_val;
}
