lemma gcd_MulMono(d: nat, p: nat, q: nat)
  requires p <= q
  ensures d * p <= d * q
{
  assert q == p + (q - p);
  assert d * q == d * p + d * (q - p);
}

lemma gcd_DividesZero(d: nat)
  ensures divides(d, 0)
{
  assert d * 0 == 0;
  assert exists k: nat :: d * k == 0;
}

lemma gcd_DividesSelf(n: nat)
  ensures divides(n, n)
{
  assert n * 1 == n;
  assert exists k: nat :: n * k == n;
}

lemma gcd_DividesAdd(d: nat, x: nat, y: nat)
  requires divides(d, x)
  requires divides(d, y)
  ensures divides(d, x + y)
{
  var kx: nat :| d * kx == x;
  var ky: nat :| d * ky == y;
  assert d * (kx + ky) == d * kx + d * ky;
  assert d * (kx + ky) == x + y;
  assert exists k: nat :: d * k == x + y;
}

lemma gcd_DividesSub(d: nat, x: nat, y: nat)
  requires y <= x
  requires divides(d, x)
  requires divides(d, y)
  ensures divides(d, x - y)
{
  var kx: nat :| d * kx == x;
  var ky: nat :| d * ky == y;

  if d == 0 {
    assert x == 0;
    assert y == 0;
    assert x - y == 0;
    gcd_DividesZero(d);
  } else {
    if ky > kx {
      assert kx + 1 <= ky;
      gcd_MulMono(d, kx + 1, ky);
      assert d * (kx + 1) == d * kx + d;
      assert d * kx < d * (kx + 1);
      assert d * ky <= d * kx;
      assert false;
    }

    assert ky <= kx;
    assert kx == ky + (kx - ky);
    assert d * kx == d * ky + d * (kx - ky);
    assert x == y + d * (kx - ky);
    assert x - y == d * (kx - ky);
    assert exists k: nat :: d * k == x - y;
  }
}

lemma gcd_CommonDivisorsSub(x: nat, y: nat)
  requires y <= x
  ensures forall d: nat ::
    (divides(d, x) && divides(d, y)) <==>
    (divides(d, x - y) && divides(d, y))
{
  forall d: nat
    ensures
      (divides(d, x) && divides(d, y)) <==>
      (divides(d, x - y) && divides(d, y))
  {
    if divides(d, x) && divides(d, y) {
      gcd_DividesSub(d, x, y);
    }

    if divides(d, x - y) && divides(d, y) {
      gcd_DividesAdd(d, x - y, y);
      assert x - y + y == x;
      assert divides(d, x);
    }
  }
}

lemma gcd_DivisorBound(d: nat, n: nat)
  requires n > 0
  requires divides(d, n)
  ensures d <= n
{
  var k: nat :| d * k == n;
  assert k > 0;
  assert 1 <= k;
  gcd_MulMono(d, 1, k);
  assert d * 1 <= d * k;
  assert d <= n;
}

lemma gcd_IsGcdZeroLeft(n: nat)
  requires n > 0
  ensures is_gcd(n, 0, n)
{
  gcd_DividesZero(n);
  gcd_DividesSelf(n);

  forall d: nat | divides(d, 0) && divides(d, n)
    ensures d <= n
  {
    gcd_DivisorBound(d, n);
  }
}

lemma gcd_IsGcdZeroRight(n: nat)
  requires n > 0
  ensures is_gcd(n, n, 0)
{
  gcd_DividesSelf(n);
  gcd_DividesZero(n);

  forall d: nat | divides(d, n) && divides(d, 0)
    ensures d <= n
  {
    gcd_DivisorBound(d, n);
  }
}

lemma gcd_DeterminesSpec(g: nat, a: nat, b: nat)
  requires a != 0 || b != 0
  requires is_gcd(g, a, b)
  ensures spec_gcd(a, b) == g
{
  assert !(a == 0 && b == 0);
  assert exists h: nat :: is_gcd(h, a, b);

  var s := spec_gcd(a, b);
  assert is_gcd(s, a, b);

  assert divides(s, a) && divides(s, b);
  assert divides(g, a) && divides(g, b);

  assert forall d: nat ::
    divides(d, a) && divides(d, b) ==> d <= g;
  assert forall d: nat ::
    divides(d, a) && divides(d, b) ==> d <= s;

  assert s <= g;
  assert g <= s;
  assert s == g;
}

method compute_gcd(a: int, b: int) returns (res: int)
  // Simulate u64: inputs are non-negative
  requires a >= 0 && b >= 0
  ensures res == spec_gcd(a, b)
  // Result is unsigned
  ensures res >= 0
{
  var aa: nat := a;
  var bb: nat := b;

  if aa == 0 && bb == 0 {
    assert spec_gcd(aa, bb) == 0;
    res := 0;
    return;
  }

  if aa == 0 {
    assert bb > 0;
    gcd_IsGcdZeroLeft(bb);
    gcd_DeterminesSpec(bb, aa, bb);
    res := bb;
    return;
  }

  if bb == 0 {
    assert aa > 0;
    gcd_IsGcdZeroRight(aa);
    gcd_DeterminesSpec(aa, aa, bb);
    res := aa;
    return;
  }

  var x: nat := aa;
  var y: nat := bb;

  while x != y
    invariant x > 0
    invariant y > 0
    invariant forall d: nat ::
      (divides(d, x) && divides(d, y)) <==>
      (divides(d, aa) && divides(d, bb))
    decreases x + y
  {
    if x > y {
      gcd_CommonDivisorsSub(x, y);

      forall d: nat
        ensures
          (divides(d, x - y) && divides(d, y)) <==>
          (divides(d, aa) && divides(d, bb))
      {
        assert
          (divides(d, x) && divides(d, y)) <==>
          (divides(d, x - y) && divides(d, y));
        assert
          (divides(d, x) && divides(d, y)) <==>
          (divides(d, aa) && divides(d, bb));
      }

      x := x - y;
    } else {
      assert y > x;
      gcd_CommonDivisorsSub(y, x);

      forall d: nat
        ensures
          (divides(d, x) && divides(d, y - x)) <==>
          (divides(d, aa) && divides(d, bb))
      {
        assert
          (divides(d, y) && divides(d, x)) <==>
          (divides(d, y - x) && divides(d, x));
        assert
          (divides(d, x) && divides(d, y)) <==>
          (divides(d, aa) && divides(d, bb));
      }

      y := y - x;
    }
  }

  assert x == y;
  gcd_DividesSelf(x);
  assert divides(x, x) && divides(x, y);
  assert
    (divides(x, x) && divides(x, y)) <==>
    (divides(x, aa) && divides(x, bb));
  assert divides(x, aa) && divides(x, bb);

  forall d: nat | divides(d, aa) && divides(d, bb)
    ensures d <= x
  {
    assert
      (divides(d, x) && divides(d, y)) <==>
      (divides(d, aa) && divides(d, bb));
    assert divides(d, x) && divides(d, y);
    gcd_DivisorBound(d, x);
  }

  assert is_gcd(x, aa, bb);
  gcd_DeterminesSpec(x, aa, bb);
  res := x;
}
