function CapacityFrom(row: seq<(int, int)>, v: int, n: int): int
    requires 0 <= n <= |row|
    decreases n
{
    if n == 0 then
        0
    else if row[n - 1].0 == v then
        row[n - 1].1
    else
        CapacityFrom(row, v, n - 1)
}

function CapacityAt(g: seq<seq<(int, int)>>, u: int, v: int): int
{
    if 0 <= u < |g| then CapacityFrom(g[u], v, |g[u]|) else 0
}

function ActualGet(f: FlowMap, u: int, v: int): int
{
    if (u, v) in f then f[(u, v)] else 0
}

function ActualSumOut(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int): int
    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        ActualSumOut(g, f, u, idx - 1)
        + ActualGet(f, u, g[u][idx - 1].0)
    else
        ActualSumOut(g, f, u, idx - 1)
}

function ActualSumIn(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        ActualSumIn(g, f, u, idx - 1)
        + ActualGet(f, idx - 1, u)
}

function ActualFlowValue(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int): int
{
    (if 0 <= s < |g|
        then ActualSumOut(g, f, s, |g[s]|)
        else 0)
    - ActualSumIn(g, f, s, |g|)
}

function ActualConservedPrefix(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    n: int): bool
    requires 0 <= n <= |g|
    decreases n
{
    if n == 0 then
        true
    else
        ActualConservedPrefix(g, f, s, t, n - 1)
        &&
        ((n - 1 == s || n - 1 == t)
         ||
         ActualSumIn(g, f, n - 1, |g|)
            == ActualSumOut(g, f, n - 1, |g[n - 1]|))
}

function CanonicalPrefix(f: FlowMap, n: int, k: int): FlowMap
    requires 0 < n
    requires 0 <= k <= n * n
    decreases k
{
    if k == 0 then
        map[]
    else
        CanonicalPrefix(f, n, k - 1)
            [((k - 1) / n, (k - 1) % n)
                := ActualGet(f, (k - 1) / n, (k - 1) % n)]
}

function EnumeratedFlows(
    g: seq<seq<(int, int)>>,
    k: int): set<FlowMap>
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    decreases k
{
    if k == 0 then
        {map[]}
    else
        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;
        set p: FlowMap, x: int
            {:trigger (p[(u, v) := x])[(u, v)]}
        |
            p in EnumeratedFlows(g, k - 1)
            && 0 <= x <= CapacityAt(g, u, v)
        :: p[(u, v) := x]
}

ghost predicate PrefixShape(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
{
    && 0 <= k <= |g| * |g|
    && (forall u: int, v: int ::
            (u, v) in f
            <==>
            0 <= u < |g|
            && 0 <= v < |g|
            && u * |g| + v < k)
    && (forall u: int, v: int ::
            0 <= u < |g|
            && 0 <= v < |g|
            && u * |g| + v < k
            ==>
            0 <= f[(u, v)] <= CapacityAt(g, u, v))
}

lemma MulMonoNonnegative(a: int, b: int, c: int)
    requires 0 <= a <= b
    requires 0 <= c
    ensures a * c <= b * c
{
    assert 0 <= (b - a) * c;
    assert b * c - a * c == (b - a) * c;
}

lemma IndexCoordinates(n: int, k: int)
    requires 0 < n
    requires 0 <= k < n * n
    ensures 0 <= k / n < n
    ensures 0 <= k % n < n
    ensures (k / n) * n + k % n == k
{
    assert 0 <= k / n;
    assert 0 <= k % n < n;
    assert (k / n) * n + k % n == k;
    assert (k / n) * n <= k;

    if k / n >= n {
        MulMonoNonnegative(n, k / n, n);
        assert n * n <= (k / n) * n;
        assert n * n <= k;
        assert false;
    }
}

lemma GridIndexRange(n: int, u: int, v: int)
    requires 0 < n
    requires 0 <= u < n
    requires 0 <= v < n
    ensures 0 <= u * n + v < n * n
{
    assert 0 <= u * n;
    assert 0 <= u * n + v;
    assert u + 1 <= n;
    assert u * n + v < u * n + n;
    assert u * n + n == (u + 1) * n;
    MulMonoNonnegative(u + 1, n, n);
    assert (u + 1) * n <= n * n;
}

lemma {:isolate_assertions} GridIndexFacts(
    n: int,
    k: int,
    u: int,
    v: int)
    requires 0 < n
    requires 0 <= k < n * n
    requires 0 <= u < n
    requires 0 <= v < n
    requires u * n + v == k
    ensures u == k / n
    ensures v == k % n
{
    IndexCoordinates(n, k);
    assert v / n == 0;
    assert (u * n + v) / n == u + v / n;
    assert k / n == u;
    assert (k / n) * n + k % n == k;
    assert k % n == v;
}

