lemma {:isolate_assertions} PrefixExtendDomain(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    ensures forall u: int, v: int ::
        (u, v) in p[(k / |g|, k % |g|) := x]
        <==>
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k + 1
{
    var n := |g|;
    var a := k / n;
    var b := k % n;
    var f := p[(a, b) := x];

    IndexCoordinates(n, k);
    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k;

    assert forall u: int, v: int ::
        (u, v) in f
        <==>
        0 <= u < n && 0 <= v < n && u * n + v < k + 1 by
    {
        forall u: int, v: int
            ensures
                (u, v) in f
                <==>
                0 <= u < n && 0 <= v < n
                && u * n + v < k + 1
        {
            if (u, v) in f {
                if u == a && v == b {
                    assert 0 <= u < n;
                    assert 0 <= v < n;
                    assert u * n + v == k;
                } else {
                    assert (u, v) in p;
                    assert 0 <= u < n;
                    assert 0 <= v < n;
                    assert u * n + v < k;
                }
            }

            if 0 <= u < n && 0 <= v < n
                && u * n + v < k + 1
            {
                if u * n + v < k {
                    assert (u, v) in p;
                    assert (u, v) in f;
                } else {
                    assert u * n + v == k;
                    GridIndexFacts(n, k, u, v);
                    assert u == a && v == b;
                    assert (u, v) in f;
                }
            }
        }
    }
}

lemma {:isolate_assertions} PrefixExtendBounds(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    requires 0 <= x <= CapacityAt(g, k / |g|, k % |g|)
    ensures forall u: int, v: int ::
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k + 1
        ==>
        0 <= p[(k / |g|, k % |g|) := x][(u, v)]
            <= CapacityAt(g, u, v)
{
    var n := |g|;
    var a := k / n;
    var b := k % n;
    var f := p[(a, b) := x];

    IndexCoordinates(n, k);
    assert a * n + b == k;

    assert forall u: int, v: int ::
        0 <= u < n && 0 <= v < n
        && u * n + v < k + 1
        ==> 0 <= f[(u, v)] <= CapacityAt(g, u, v) by
    {
        forall u: int, v: int |
            0 <= u < n && 0 <= v < n
            && u * n + v < k + 1
            ensures 0 <= f[(u, v)] <= CapacityAt(g, u, v)
        {
            if u * n + v < k {
                assert 0 <= p[(u, v)] <= CapacityAt(g, u, v);
                if u == a && v == b {
                    assert u * n + v == k;
                    assert false;
                }
                assert f[(u, v)] == p[(u, v)];
            } else {
                assert u * n + v == k;
                GridIndexFacts(n, k, u, v);
                assert u == a && v == b;
                assert f[(u, v)] == x;
            }
        }
    }
}

lemma PrefixExtendShape(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    requires 0 <= x <= CapacityAt(g, k / |g|, k % |g|)
    ensures PrefixShape(
        g, k + 1,
        p[(k / |g|, k % |g|) := x])
{
    PrefixExtendDomain(g, k, p, x);
    PrefixExtendBounds(g, k, p, x);
    assert 0 <= k + 1 <= |g| * |g|;
}

lemma {:isolate_assertions} PrefixRemoveDomain(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures forall u: int, v: int ::
        (u, v) in
            f - {((k - 1) / |g|, (k - 1) % |g|)}
        <==>
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k - 1
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;

    assert forall u: int, v: int ::
        (u, v) in p
        <==>
        0 <= u < n && 0 <= v < n && u * n + v < k - 1 by
    {
        forall u: int, v: int
            ensures
                (u, v) in p
                <==>
                0 <= u < n && 0 <= v < n
                && u * n + v < k - 1
        {
            if (u, v) in p {
                assert (u, v) in f;
                assert !(u == a && v == b);
                assert 0 <= u < n;
                assert 0 <= v < n;
                assert u * n + v < k;

                if !(u * n + v < k - 1) {
                    assert u * n + v == k - 1;
                    GridIndexFacts(n, k - 1, u, v);
                    assert u == a && v == b;
                    assert false;
                }
            }

            if 0 <= u < n && 0 <= v < n
                && u * n + v < k - 1
            {
                assert (u, v) in f;
                if u == a && v == b {
                    assert u * n + v == k - 1;
                    assert false;
                }
                assert (u, v) in p;
            }
        }
    }
}

lemma {:isolate_assertions} PrefixRemoveBounds(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures forall u: int, v: int ::
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k - 1
        ==>
        0 <=
            (f - {((k - 1) / |g|, (k - 1) % |g|)})[(u, v)]
            <= CapacityAt(g, u, v)
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;

    assert forall u: int, v: int ::
        0 <= u < n && 0 <= v < n
        && u * n + v < k - 1
        ==> 0 <= p[(u, v)] <= CapacityAt(g, u, v) by
    {
        forall u: int, v: int |
            0 <= u < n && 0 <= v < n
            && u * n + v < k - 1
            ensures 0 <= p[(u, v)] <= CapacityAt(g, u, v)
        {
            assert 0 <= f[(u, v)] <= CapacityAt(g, u, v);
            if u == a && v == b {
                assert u * n + v == k - 1;
                assert false;
            }
            assert p[(u, v)] == f[(u, v)];
        }
    }
}

lemma PrefixRemoveRestore(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures
        (f - {((k - 1) / |g|, (k - 1) % |g|)})
            [((k - 1) / |g|, (k - 1) % |g|)
                := f[((k - 1) / |g|, (k - 1) % |g|)]]
        == f
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;
    assert (a, b) in f;
    assert (f - {(a, b)})[(a, b) := f[(a, b)]] == f;
}

lemma PrefixRemoveShape(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures PrefixShape(
        g, k - 1,
        f - {((k - 1) / |g|, (k - 1) % |g|)})
    ensures 0 <= f[((k - 1) / |g|, (k - 1) % |g|)]
        <= CapacityAt(
            g, (k - 1) / |g|, (k - 1) % |g|)
    ensures
        (f - {((k - 1) / |g|, (k - 1) % |g|)})
            [((k - 1) / |g|, (k - 1) % |g|)
                := f[((k - 1) / |g|, (k - 1) % |g|)]]
        == f
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k - 1;
    assert (a, b) in f;
    assert 0 <= f[(a, b)] <= CapacityAt(g, a, b);

    PrefixRemoveDomain(g, k, f);
    PrefixRemoveBounds(g, k, f);
    PrefixRemoveRestore(g, k, f);

    assert 0 <= k - 1 <= n * n;
    assert PrefixShape(g, k - 1, p);
}

lemma {:isolate_assertions} EnumeratedCharacterization(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    ensures f in EnumeratedFlows(g, k) <==> PrefixShape(g, k, f)
    decreases k
{
    if k == 0 {
        if f in EnumeratedFlows(g, k) {
            assert f == map[];
            assert PrefixShape(g, k, f);
        }
        if PrefixShape(g, k, f) {
            PrefixShapeZeroIsEmpty(g, f);
            assert f == map[];
            assert f in EnumeratedFlows(g, k);
        }
    } else {
        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;

        IndexCoordinates(n, k - 1);
        assert 0 <= u < n;
        assert 0 <= v < n;
        assert u * n + v == k - 1;

        if f in EnumeratedFlows(g, k) {
            var p: FlowMap, x: int :|
                p in EnumeratedFlows(g, k - 1)
                && 0 <= x <= CapacityAt(g, u, v)
                && f == p[(u, v) := x];

            EnumeratedCharacterization(g, k - 1, p);
            assert PrefixShape(g, k - 1, p);
            PrefixExtendShape(g, k - 1, p, x);
            assert PrefixShape(g, k, f);
        }

        if PrefixShape(g, k, f) {
            var p := f - {(u, v)};
            PrefixRemoveShape(g, k, f);
            assert PrefixShape(g, k - 1, p);
            EnumeratedCharacterization(g, k - 1, p);
            assert p in EnumeratedFlows(g, k - 1);
            assert 0 <= f[(u, v)] <= CapacityAt(g, u, v);
            assert p[(u, v) := f[(u, v)]] == f;
            assert f in EnumeratedFlows(g, k);
        }
    }
}

lemma ValidGetBounds(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    ensures 0 <= ActualGet(f, u, v) <= CapacityAt(g, u, v)
{
    ActualGetAgreement(f, u, v);
    CapacityNonnegative(g, u, v);

    if (u, v) in f {
        assert f[(u, v)] >= 0;
        if f[(u, v)] > 0 {
            var c :|
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c;
            CapacityMatchesEdge(g, u, v, c);
        }
    }
}

lemma {:isolate_assertions} CanonicalGet(
    f: FlowMap,
    n: int,
    k: int,
    u: int,
    v: int)
    requires 0 < n
    requires 0 <= k <= n * n
    requires 0 <= u < n
    requires 0 <= v < n
    requires u * n + v < k
    ensures ActualGet(CanonicalPrefix(f, n, k), u, v)
        == ActualGet(f, u, v)
    decreases k
{
    if k > 0 {
        var a := (k - 1) / n;
        var b := (k - 1) % n;
        var z := u * n + v;

        IndexCoordinates(n, k - 1);

        if z == k - 1 {
            GridIndexFacts(n, k - 1, u, v);
            assert u == a && v == b;
        } else {
            assert z < k - 1;
            CanonicalGet(f, n, k - 1, u, v);
            assert a * n + b == k - 1;
            if u == a && v == b {
                assert z == k - 1;
                assert false;
            }
        }
    }
}

lemma {:isolate_assertions} CanonicalShape(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    k: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    ensures PrefixShape(g, k, CanonicalPrefix(f, |g|, k))
    decreases k
{
    if k == 0 {
        assert CanonicalPrefix(f, |g|, k) == map[];
        assert PrefixShape(g, k, map[]);
    } else {
        CanonicalShape(g, f, s, t, k - 1);

        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;
        var p := CanonicalPrefix(f, n, k - 1);
        var x := ActualGet(f, u, v);

        IndexCoordinates(n, k - 1);
        assert 0 <= u < n;
        assert 0 <= v < n;

        ValidGetBounds(g, f, s, t, u, v);
        PrefixExtendShape(g, k - 1, p, x);

        assert CanonicalPrefix(f, n, k)
            == p[(u, v) := x];
    }
}

lemma CanonicalEnumerated(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 < |g|
    ensures CanonicalPrefix(f, |g|, |g| * |g|)
        in EnumeratedFlows(g, |g| * |g|)
{
    CanonicalShape(g, f, s, t, |g| * |g|);
    EnumeratedCharacterization(
        g, |g| * |g|,
        CanonicalPrefix(f, |g|, |g| * |g|));
}

lemma PointwiseSumOut(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    h: FlowMap,
    u: int,
    idx: int)
    requires well_formed(CapacityGraph(g))
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    requires forall a: int, b: int ::
        0 <= a < |g| && 0 <= b < |g|
        ==> ActualGet(f, a, b) == ActualGet(h, a, b)
    ensures ActualSumOut(g, f, u, idx)
        == ActualSumOut(g, h, u, idx)
    decreases idx
{
    if idx > 0 {
        PointwiseSumOut(g, f, h, u, idx - 1);
        assert 0 <= idx - 1 < |g[u]|;
        assert 0 <= g[u][idx - 1].0 < |g|;
        assert ActualGet(f, u, g[u][idx - 1].0)
            == ActualGet(h, u, g[u][idx - 1].0);
    }
}

lemma PointwiseSumIn(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    h: FlowMap,
    u: int,
    idx: int)
    requires 0 <= u < |g|
    requires 0 <= idx <= |g|
    requires forall a: int, b: int ::
        0 <= a < |g| && 0 <= b < |g|
        ==> ActualGet(f, a, b) == ActualGet(h, a, b)
    ensures ActualSumIn(g, f, u, idx)
        == ActualSumIn(g, h, u, idx)
    decreases idx
{
    if idx > 0 {
        PointwiseSumIn(g, f, h, u, idx - 1);
        assert 0 <= idx - 1 < |g|;
        assert ActualGet(f, idx - 1, u)
            == ActualGet(h, idx - 1, u);
    }
}

lemma {:isolate_assertions} CanonicalPreservesSums(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= u < |g|
    ensures ActualSumOut(
                g,
                CanonicalPrefix(f, |g|, |g| * |g|),
                u,
                |g[u]|)
            == ActualSumOut(g, f, u, |g[u]|)
    ensures ActualSumIn(
                g,
                CanonicalPrefix(f, |g|, |g| * |g|),
                u,
                |g|)
            == ActualSumIn(g, f, u, |g|)
{
    var h := CanonicalPrefix(f, |g|, |g| * |g|);

    assert forall a: int, b: int ::
        0 <= a < |g| && 0 <= b < |g|
        ==> ActualGet(h, a, b) == ActualGet(f, a, b) by
    {
        forall a: int, b: int |
            0 <= a < |g| && 0 <= b < |g|
            ensures ActualGet(h, a, b) == ActualGet(f, a, b)
        {
            GridIndexRange(|g|, a, b);
            CanonicalGet(f, |g|, |g| * |g|, a, b);
        }
    }

    PointwiseSumOut(g, h, f, u, |g[u]|);
    PointwiseSumIn(g, h, f, u, |g|);
}

lemma {:isolate_assertions} ConservedPrefixAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    n: int)
    requires 0 <= n <= |g|
    ensures ActualConservedPrefix(g, f, s, t, n)
        <==>
        (forall u: int ::
            0 <= u < n && u != s && u != t
            ==> total_flow_in(g, f, u)
                == total_flow_out(g, f, u))
    decreases n
{
    if n > 0 {
        ConservedPrefixAgreement(g, f, s, t, n - 1);
        ActualSumInAgreement(g, f, n - 1, |g|);
        ActualSumOutAgreement(g, f, n - 1, |g[n - 1]|);

        if ActualConservedPrefix(g, f, s, t, n) {
            assert ActualConservedPrefix(g, f, s, t, n - 1);

            assert forall u: int ::
                0 <= u < n && u != s && u != t
                ==> total_flow_in(g, f, u)
                    == total_flow_out(g, f, u) by
            {
                forall u: int |
                    0 <= u < n && u != s && u != t
                    ensures total_flow_in(g, f, u)
                        == total_flow_out(g, f, u)
                {
                    if u == n - 1 {
                        assert ActualSumIn(g, f, u, |g|)
                            == ActualSumOut(g, f, u, |g[u]|);
                    } else {
                        assert u < n - 1;
                    }
                }
            }
        }

        if forall u: int ::
            0 <= u < n && u != s && u != t
            ==> total_flow_in(g, f, u)
                == total_flow_out(g, f, u)
        {
            assert forall u: int ::
                0 <= u < n - 1 && u != s && u != t
                ==> total_flow_in(g, f, u)
                    == total_flow_out(g, f, u);

            assert ActualConservedPrefix(g, f, s, t, n - 1);

            if n - 1 != s && n - 1 != t {
                assert total_flow_in(g, f, n - 1)
                    == total_flow_out(g, f, n - 1);
                assert ActualSumIn(g, f, n - 1, |g|)
                    == ActualSumOut(g, f, n - 1, |g[n - 1]|);
            }
        }
    }
}

lemma {:isolate_assertions} EnumeratedConservedIsValid(
    graph: CapacityGraph,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 < size(graph)
    requires f in EnumeratedFlows(
        view(graph), size(graph) * size(graph))
    requires ActualConservedPrefix(
        view(graph), f, s, t, size(graph))
    ensures is_valid_flow(view(graph), f, s, t)
{
    var g := view(graph);
    EnumeratedCharacterization(g, |g| * |g|, f);
    assert PrefixShape(g, |g| * |g|, f);

    assert forall u: int, v: int ::
        (u, v) in f ==> f[(u, v)] >= 0 by
    {
        forall u: int, v: int |
            (u, v) in f
            ensures f[(u, v)] >= 0
        {
            assert 0 <= u < |g|;
            assert 0 <= v < |g|;
            GridIndexRange(|g|, u, v);
        }
    }

    assert respects_capacity(g, f) by
    {
        forall u: int, v: int |
            (u, v) in f
            ensures
                f[(u, v)] > 0
                ==> exists c: int ::
                    has_capacity(g, u, v, c)
                    && f[(u, v)] <= c
        {
            if f[(u, v)] > 0 {
                assert 0 <= u < |g|;
                assert 0 <= v < |g|;
                GridIndexRange(|g|, u, v);
                assert f[(u, v)] <= CapacityAt(g, u, v);
                assert CapacityAt(g, u, v) > 0;
                CapacityProducesEdge(g, u, v);
                assert has_capacity(
                    g, u, v, CapacityAt(g, u, v));
            }
        }
    }

    ConservedPrefixAgreement(g, f, s, t, |g|);
    assert is_conserved(g, f, s, t);
}

lemma {:isolate_assertions} CanonicalPreservesConservation(
    graph: CapacityGraph,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(graph)
    requires is_valid_flow(view(graph), f, s, t)
    requires 0 < size(graph)
    requires 0 <= s < size(graph)
    ensures ActualConservedPrefix(
        view(graph),
        CanonicalPrefix(
            f, size(graph), size(graph) * size(graph)),
        s, t, size(graph))
    ensures ActualFlowValue(
        view(graph),
        CanonicalPrefix(
            f, size(graph), size(graph) * size(graph)),
        s)
        == flow_val(view(graph), f, s)
{
    var g := view(graph);
    var h := CanonicalPrefix(f, |g|, |g| * |g|);

    assert forall u: int ::
        0 <= u < |g| && u != s && u != t
        ==> total_flow_in(g, h, u)
            == total_flow_out(g, h, u) by
    {
        forall u: int |
            0 <= u < |g| && u != s && u != t
            ensures total_flow_in(g, h, u)
                == total_flow_out(g, h, u)
        {
            CanonicalPreservesSums(g, f, u);
            ActualSumInAgreement(g, f, u, |g|);
            ActualSumOutAgreement(g, f, u, |g[u]|);
            ActualSumInAgreement(g, h, u, |g|);
            ActualSumOutAgreement(g, h, u, |g[u]|);
            assert total_flow_in(g, f, u)
                == total_flow_out(g, f, u);
        }
    }

    ConservedPrefixAgreement(g, h, s, t, |g|);

    CanonicalPreservesSums(g, f, s);
    ActualFlowValueAgreement(g, f, s);
    ActualFlowValueAgreement(g, h, s);
}

lemma EmptySumOut(
    g: seq<seq<(int, int)>>,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumOut(g, map[], u, idx) == 0
    decreases idx
{
    if idx > 0 {
        EmptySumOut(g, u, idx - 1);
    }
}

lemma EmptySumIn(
    g: seq<seq<(int, int)>>,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumIn(g, map[], u, idx) == 0
    decreases idx
{
    if idx > 0 {
        EmptySumIn(g, u, idx - 1);
    }
}

lemma EmptyFlowValid(
    graph: CapacityGraph,
    s: int,
    t: int)
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    ensures is_valid_flow(view(graph), map[], s, t)
{
    var g := view(graph);
    var empty: FlowMap := map[];

    assert respects_capacity(g, empty);
    assert forall u: int, v: int ::
        (u, v) in empty ==> empty[(u, v)] >= 0;

    assert is_conserved(g, empty, s, t) by
    {
        forall u: int |
            0 <= u < |g| && u != s && u != t
            ensures total_flow_in(g, empty, u)
                == total_flow_out(g, empty, u)
        {
            EmptySumIn(g, u, |g|);
            EmptySumOut(g, u, |g[u]|);
            ActualSumInAgreement(g, empty, u, |g|);
            ActualSumOutAgreement(g, empty, u, |g[u]|);
        }
    }
}

lemma {:isolate_assertions} EmptyCanonicalValid(
    graph: CapacityGraph,
    s: int,
    t: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    ensures CanonicalPrefix(
                map[], size(graph), size(graph) * size(graph))
            in EnumeratedFlows(
                view(graph), size(graph) * size(graph))
    ensures ActualConservedPrefix(
                view(graph),
                CanonicalPrefix(
                    map[], size(graph), size(graph) * size(graph)),
                s, t, size(graph))
    ensures ActualFlowValue(
                view(graph),
                CanonicalPrefix(
                    map[], size(graph), size(graph) * size(graph)),
                s) == 0
{
    var g := view(graph);
    var empty: FlowMap := map[];
    var z := CanonicalPrefix(empty, |g|, |g| * |g|);

    assert 0 < |g|;
    EmptyFlowValid(graph, s, t);
    assert is_valid_flow(g, empty, s, t);

    CanonicalEnumerated(g, empty, s, t);
    CanonicalPreservesConservation(graph, empty, s, t);

    EmptySumOut(g, s, |g[s]|);
    EmptySumIn(g, s, |g|);
    ActualFlowValueAgreement(g, empty, s);
    assert flow_val(g, empty, s) == 0;
}

method {:isolate_assertions} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    assert 0 < |g|;

    var all := EnumeratedFlows(g, |g| * |g|);
    var remaining := all;

    var best := CanonicalPrefix(map[], |g|, |g| * |g|);
    max_val := 0;

    EmptyCanonicalValid(graph, s, t);
    EnumeratedConservedIsValid(graph, best, s, t);
    ActualFlowValueAgreement(g, best, s);

    assert forall f: FlowMap ::
        f in all - remaining
        && ActualConservedPrefix(g, f, s, t, |g|)
        ==> ActualFlowValue(g, f, s) <= max_val;

    while remaining != {}
        invariant remaining <= all
        invariant best in all
        invariant ActualConservedPrefix(g, best, s, t, |g|)
        invariant is_valid_flow(g, best, s, t)
        invariant ActualFlowValue(g, best, s) == max_val
        invariant flow_val(g, best, s) == max_val
        invariant forall f: FlowMap ::
            f in all - remaining
            && ActualConservedPrefix(g, f, s, t, |g|)
            ==> ActualFlowValue(g, f, s) <= max_val
        decreases |remaining|
    {
        var oldRemaining := remaining;
        var oldMax := max_val;
        var f :| f in oldRemaining;

        if ActualConservedPrefix(g, f, s, t, |g|) {
            EnumeratedConservedIsValid(graph, f, s, t);
            ActualFlowValueAgreement(g, f, s);

            if ActualFlowValue(g, f, s) > max_val {
                best := f;
                max_val := ActualFlowValue(g, f, s);
            }
        }

        assert oldMax <= max_val;
        remaining := oldRemaining - {f};

        assert remaining < oldRemaining;
        assert remaining <= all;

        assert forall q: FlowMap ::
            q in all - remaining
            && ActualConservedPrefix(g, q, s, t, |g|)
            ==> ActualFlowValue(g, q, s) <= max_val by
        {
            forall q: FlowMap |
                q in all - remaining
                && ActualConservedPrefix(g, q, s, t, |g|)
                ensures ActualFlowValue(g, q, s) <= max_val
            {
                if q in oldRemaining {
                    assert q == f;
                    if ActualFlowValue(g, f, s) > oldMax {
                        assert max_val == ActualFlowValue(g, f, s);
                    } else {
