}

lemma {:isolate_assertions} CanonicalGet(
    f: FlowMap,
    n: int,
    k: int,
    u: int,
    v: int)
    requires 0 < n
    requires 0 <= k <= n * n
    requires 0 <= u < n
    requires 0 <= v < n
    requires u * n + v < k
    ensures ActualGet(CanonicalPrefix(f, n, k), u, v)
        == ActualGet(f, u, v)
    decreases k
{
    if k > 0 {
        var a := (k - 1) / n;
        var b := (k - 1) % n;
        var z := u * n + v;

        IndexCoordinates(n, k - 1);

        if z == k - 1 {
            GridIndexFacts(n, k - 1, u, v);
            assert u == a && v == b;
        } else {
            assert z < k - 1;
            CanonicalGet(f, n, k - 1, u, v);
            assert a * n + b == k - 1;
            if u == a && v == b {
                assert z == k - 1;
                assert false;
            }
        }
    }
}

lemma {:isolate_assertions} CanonicalShape(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    k: int)
