lemma {:isolate_assertions} CanonicalPreservesSums(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= u < |g|
    ensures ActualSumOut(
                g,
                CanonicalPrefix(f, |g|, |g| * |g|),
                u,
                |g[u]|)
            == ActualSumOut(g, f, u, |g[u]|)
    ensures ActualSumIn(
                g,
                CanonicalPrefix(f, |g|, |g| * |g|),
                u,
                |g|)
            == ActualSumIn(g, f, u, |g|)
{
    var h := CanonicalPrefix(f, |g|, |g| * |g|);

    assert forall a: int, b: int ::
        0 <= a < |g| && 0 <= b < |g|
        ==> ActualGet(h, a, b) == ActualGet(f, a, b) by
    {
        forall a: int, b: int |
            0 <= a < |g| && 0 <= b < |g|
            ensures ActualGet(h, a, b) == ActualGet(f, a, b)
        {
            GridIndexRange(|g|, a, b);
            CanonicalGet(f, |g|, |g| * |g|, a, b);
        }
    }

    PointwiseSumOut(g, h, f, u, |g[u]|);
    PointwiseSumIn(g, h, f, u, |g|);
}

lemma {:isolate_assertions} ConservedPrefixAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    n: int)
    requires 0 <= n <= |g|
    ensures ActualConservedPrefix(g, f, s, t, n)
        <==>
        (forall u: int ::
            0 <= u < n && u != s && u != t
            ==> total_flow_in(g, f, u)
                == total_flow_out(g, f, u))
    decreases n
{
    if n > 0 {
        ConservedPrefixAgreement(g, f, s, t, n - 1);
        ActualSumInAgreement(g, f, n - 1, |g|);
        ActualSumOutAgreement(g, f, n - 1, |g[n - 1]|);

        if ActualConservedPrefix(g, f, s, t, n) {
            assert ActualConservedPrefix(g, f, s, t, n - 1);

            assert forall u: int ::
                0 <= u < n && u != s && u != t
                ==> total_flow_in(g, f, u)
                    == total_flow_out(g, f, u) by
            {
                forall u: int |
                    0 <= u < n && u != s && u != t
                    ensures total_flow_in(g, f, u)
                        == total_flow_out(g, f, u)
                {
                    if u == n - 1 {
                        assert ActualSumIn(g, f, u, |g|)
                            == ActualSumOut(g, f, u, |g[u]|);
                    } else {
                        assert u < n - 1;
                    }
                }
            }
        }

        if forall u: int ::
            0 <= u < n && u != s && u != t
            ==> total_flow_in(g, f, u)
                == total_flow_out(g, f, u)
        {
            assert forall u: int ::
                0 <= u < n - 1 && u != s && u != t
                ==> total_flow_in(g, f, u)
                    == total_flow_out(g, f, u);

            assert ActualConservedPrefix(g, f, s, t, n - 1);

            if n - 1 != s && n - 1 != t {
                assert total_flow_in(g, f, n - 1)
                    == total_flow_out(g, f, n - 1);
                assert ActualSumIn(g, f, n - 1, |g|)
                    == ActualSumOut(g, f, n - 1, |g[n - 1]|);
            }
        }
    }
}

lemma {:isolate_assertions} EnumeratedConservedIsValid(
    graph: CapacityGraph,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 < size(graph)
    requires f in EnumeratedFlows(
        view(graph), size(graph) * size(graph))
    requires ActualConservedPrefix(
        view(graph), f, s, t, size(graph))
    ensures is_valid_flow(view(graph), f, s, t)
{
    var g := view(graph);
    EnumeratedCharacterization(g, |g| * |g|, f);
    assert PrefixShape(g, |g| * |g|, f);

    assert forall u: int, v: int ::
        (u, v) in f ==> f[(u, v)] >= 0 by
    {
        forall u: int, v: int |
            (u, v) in f
            ensures f[(u, v)] >= 0
        {
            assert 0 <= u < |g|;
            assert 0 <= v < |g|;
            GridIndexRange(|g|, u, v);
        }
    }

    assert respects_capacity(g, f) by
    {
        forall u: int, v: int |
            (u, v) in f
            ensures
                f[(u, v)] > 0
                ==> exists c: int ::
                    has_capacity(g, u, v, c)
                    && f[(u, v)] <= c
        {
            if f[(u, v)] > 0 {
                assert 0 <= u < |g|;
                assert 0 <= v < |g|;
                GridIndexRange(|g|, u, v);
                assert f[(u, v)] <= CapacityAt(g, u, v);
                assert CapacityAt(g, u, v) > 0;
                CapacityProducesEdge(g, u, v);
                assert has_capacity(
                    g, u, v, CapacityAt(g, u, v));
            }
        }
    }

    ConservedPrefixAgreement(g, f, s, t, |g|);
    assert is_conserved(g, f, s, t);
}

lemma {:isolate_assertions} CanonicalPreservesConservation(
    graph: CapacityGraph,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(graph)
    requires is_valid_flow(view(graph), f, s, t)
    requires 0 < size(graph)
    requires 0 <= s < size(graph)
    ensures ActualConservedPrefix(
        view(graph),
        CanonicalPrefix(
            f, size(graph), size(graph) * size(graph)),
        s, t, size(graph))
    ensures ActualFlowValue(
        view(graph),
        CanonicalPrefix(
            f, size(graph), size(graph) * size(graph)),
        s)
        == flow_val(view(graph), f, s)
{
    var g := view(graph);
    var h := CanonicalPrefix(f, |g|, |g| * |g|);

    assert forall u: int ::
        0 <= u < |g| && u != s && u != t
        ==> total_flow_in(g, h, u)
            == total_flow_out(g, h, u) by
    {
        forall u: int |
            0 <= u < |g| && u != s && u != t
            ensures total_flow_in(g, h, u)
                == total_flow_out(g, h, u)
        {
            CanonicalPreservesSums(g, f, u);
            ActualSumInAgreement(g, f, u, |g|);
            ActualSumOutAgreement(g, f, u, |g[u]|);
            ActualSumInAgreement(g, h, u, |g|);
            ActualSumOutAgreement(g, h, u, |g[u]|);
            assert total_flow_in(g, f, u)
                == total_flow_out(g, f, u);
        }
    }

    ConservedPrefixAgreement(g, h, s, t, |g|);

    CanonicalPreservesSums(g, f, s);
    ActualFlowValueAgreement(g, f, s);
    ActualFlowValueAgreement(g, h, s);
}

