lemma IndexCoordinates(n: int, k: int)
    requires 0 < n
    requires 0 <= k < n * n
    ensures 0 <= k / n < n
    ensures 0 <= k % n < n
    ensures (k / n) * n + k % n == k
{
    assert 0 <= k / n;
    assert 0 <= k % n < n;
    assert (k / n) * n + k % n == k;
    assert (k / n) * n <= k;

    if k / n >= n {
        MulMonoNonnegative(n, k / n, n);
        assert n * n <= (k / n) * n;
        assert n * n <= k;
        assert false;
    }
}

lemma GridIndexRange(n: int, u: int, v: int)
    requires 0 < n
    requires 0 <= u < n
    requires 0 <= v < n
    ensures 0 <= u * n + v < n * n
{
    assert 0 <= u * n;
    assert 0 <= u * n + v;
    assert u + 1 <= n;
    assert u * n + v < u * n + n;
    assert u * n + n == (u + 1) * n;
    MulMonoNonnegative(u + 1, n, n);
    assert (u + 1) * n <= n * n;
}

lemma {:isolate_assertions} GridIndexFacts(
    n: int,
    k: int,
    u: int,
    v: int)
    requires 0 < n
    requires 0 <= k < n * n
    requires 0 <= u < n
    requires 0 <= v < n
    requires u * n + v == k
    ensures u == k / n
    ensures v == k % n
{
    IndexCoordinates(n, k);

    var a := k / n;
    var b := k % n;

    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k;

    if u < a {
        assert u + 1 <= a;
        MulMonoNonnegative(u + 1, a, n);
        assert u * n + v < u * n + n;
        assert u * n + n == (u + 1) * n;
        assert (u + 1) * n <= a * n;
        assert a * n <= a * n + b;
        assert u * n + v < a * n + b;
        assert false;
    }

    if a < u {
        assert a + 1 <= u;
        MulMonoNonnegative(a + 1, u, n);
        assert a * n + b < a * n + n;
        assert a * n + n == (a + 1) * n;
        assert (a + 1) * n <= u * n;
        assert u * n <= u * n + v;
        assert a * n + b < u * n + v;
        assert false;
    }

    assert u == a;
    assert u * n + v == a * n + b;
    assert v == b;
}

lemma ActualGetAgreement(f: FlowMap, u: int, v: int)
    ensures ActualGet(f, u, v) == get_flow(f, u, v)
{
}

lemma ActualSumOutAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumOut(g, f, u, idx)
        == sum_flow_out_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ActualSumOutAgreement(g, f, u, idx - 1);
        if 0 <= u < |g| && idx - 1 < |g[u]| {
            ActualGetAgreement(f, u, g[u][idx - 1].0);
        }
    }
}

lemma ActualSumInAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int)
    requires 0 <= idx
    ensures ActualSumIn(g, f, u, idx)
        == sum_flow_in_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ActualSumInAgreement(g, f, u, idx - 1);
        ActualGetAgreement(f, idx - 1, u);
    }
}

lemma ActualFlowValueAgreement(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int)
    requires 0 <= s < |g|
    ensures ActualFlowValue(g, f, s) == flow_val(g, f, s)
{
    ActualSumOutAgreement(g, f, s, |g[s]|);
    ActualSumInAgreement(g, f, s, |g|);
}

lemma LookupAtIndexPrefix(
    row: seq<(int, int)>,
    v: int,
    c: int,
    i: int,
    n: int)
    requires 0 <= i < n <= |row|
    requires row[i].0 == v
    requires row[i].1 == c
    requires forall a: int, b: int ::
        0 <= a < |row| && 0 <= b < |row| && a != b
        ==> row[a].0 != row[b].0
    ensures CapacityFrom(row, v, n) == c
    decreases n - i
{
    if i != n - 1 {
        assert i < n - 1;
        assert 0 <= n - 1 < |row|;
        assert row[n - 1].0 != row[i].0;
        assert row[n - 1].0 != v;
        LookupAtIndexPrefix(row, v, c, i, n - 1);
    }
}

lemma CapacityMatchesEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    c: int)
    requires well_formed(CapacityGraph(g))
    requires has_capacity(g, u, v, c)
    ensures CapacityAt(g, u, v) == c
{
    var i :|
        0 <= u < |g|
        && 0 <= i < |g[u]|
        && g[u][i].0 == v
        && g[u][i].1 == c;

    assert forall a: int, b: int ::
        0 <= a < |g[u]| && 0 <= b < |g[u]| && a != b
        ==> g[u][a].0 != g[u][b].0;

    LookupAtIndexPrefix(g[u], v, c, i, |g[u]|);
}

lemma CapacityFromProducesEdge(
    row: seq<(int, int)>,
    v: int,
    n: int)
    requires 0 <= n <= |row|
    requires CapacityFrom(row, v, n) != 0
    ensures exists i: int ::
        0 <= i < n
        && row[i].0 == v
        && row[i].1 == CapacityFrom(row, v, n)
    decreases n
{
    if n > 0 {
        if row[n - 1].0 == v {
            assert row[n - 1].1 == CapacityFrom(row, v, n);
        } else {
            CapacityFromProducesEdge(row, v, n - 1);
        }
    }
}

lemma CapacityProducesEdge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int)
    requires 0 <= u < |g|
    requires CapacityAt(g, u, v) != 0
    ensures has_capacity(g, u, v, CapacityAt(g, u, v))
{
    CapacityFromProducesEdge(g[u], v, |g[u]|);
    var i :|
        0 <= i < |g[u]|
        && g[u][i].0 == v
        && g[u][i].1 == CapacityAt(g, u, v);
}

lemma CapacityNonnegative(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int)
    requires capacities_bounded(g)
    requires 0 <= u < |g|
    ensures CapacityAt(g, u, v) >= 0
{
    if CapacityAt(g, u, v) != 0 {
        CapacityProducesEdge(g, u, v);
        assert has_capacity(g, u, v, CapacityAt(g, u, v));
    }
}

lemma PrefixShapeZeroIsEmpty(
    g: seq<seq<(int, int)>>,
    f: FlowMap)
    requires 0 < |g|
    requires PrefixShape(g, 0, f)
    ensures f == map[]
{
    assert forall q: (int, int) :: q !in f by
    {
        forall q: (int, int) |
            q in f
            ensures false
        {
            assert (q.0, q.1) in f;
            assert 0 <= q.0 < |g|;
            assert 0 <= q.1 < |g|;
            assert q.0 * |g| + q.1 < 0;
            assert 0 <= q.0 * |g| + q.1;
        }
    }
}

lemma {:isolate_assertions} PrefixExtendDomain(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    ensures forall u: int, v: int ::
        (u, v) in p[(k / |g|, k % |g|) := x]
        <==>
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k + 1
{
    var n := |g|;
    var a := k / n;
    var b := k % n;
    var f := p[(a, b) := x];

    IndexCoordinates(n, k);
    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k;

    assert forall u: int, v: int ::
        (u, v) in f
        <==>
        0 <= u < n && 0 <= v < n && u * n + v < k + 1 by
    {
        forall u: int, v: int
            ensures
                (u, v) in f
                <==>
                0 <= u < n && 0 <= v < n
                && u * n + v < k + 1
        {
            if (u, v) in f {
                if u == a && v == b {
                    assert 0 <= u < n;
                    assert 0 <= v < n;
                    assert u * n + v == k;
                } else {
                    assert (u, v) in p;
                    assert 0 <= u < n;
                    assert 0 <= v < n;
                    assert u * n + v < k;
                }
            }

            if 0 <= u < n && 0 <= v < n
                && u * n + v < k + 1
            {
                if u * n + v < k {
                    assert (u, v) in p;
                    assert (u, v) in f;
                } else {
                    assert u * n + v == k;
                    GridIndexFacts(n, k, u, v);
                    assert u == a && v == b;
                    assert (u, v) in f;
                }
            }
        }
    }
}

lemma {:isolate_assertions} PrefixExtendBoundAt(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int,
    f: FlowMap,
    u: int,
    v: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    requires 0 <= x <= CapacityAt(g, k / |g|, k % |g|)
    requires f == p[(k / |g|, k % |g|) := x]
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires u * |g| + v < k + 1
    ensures 0 <= f[(u, v)] <= CapacityAt(g, u, v)
{
    var n := |g|;
    var a := k / n;
    var b := k % n;

    IndexCoordinates(n, k);
    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k;

    if u == a && v == b {
        assert f[(u, v)] == x;
    } else {
        if !(u * n + v < k) {
            assert u * n + v == k;
            GridIndexFacts(n, k, u, v);
            assert u == a;
            assert v == b;
            assert false;
        }

        assert 0 <= p[(u, v)] <= CapacityAt(g, u, v);
        assert f[(u, v)] == p[(u, v)];
    }
}

lemma PrefixExtendShape(
    g: seq<seq<(int, int)>>,
    k: int,
    p: FlowMap,
    x: int)
    requires 0 < |g|
    requires 0 <= k < |g| * |g|
    requires PrefixShape(g, k, p)
    requires 0 <= x <= CapacityAt(g, k / |g|, k % |g|)
    ensures PrefixShape(
        g, k + 1,
        p[(k / |g|, k % |g|) := x])
{
    var n := |g|;
    var a := k / n;
    var b := k % n;
    var f := p[(a, b) := x];

    PrefixExtendDomain(g, k, p, x);

    assert forall u: int, v: int ::
        0 <= u < n
        && 0 <= v < n
        && u * n + v < k + 1
        ==>
        0 <= f[(u, v)] <= CapacityAt(g, u, v) by
    {
        forall u: int, v: int |
            0 <= u < n
            && 0 <= v < n
            && u * n + v < k + 1
            ensures 0 <= f[(u, v)] <= CapacityAt(g, u, v)
        {
            PrefixExtendBoundAt(g, k, p, x, f, u, v);
        }
    }

    assert 0 <= k + 1 <= n * n;
    assert PrefixShape(g, k + 1, f);
}

lemma {:isolate_assertions} PrefixRemoveDomain(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures forall u: int, v: int ::
        (u, v) in
            f - {((k - 1) / |g|, (k - 1) % |g|)}
        <==>
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k - 1
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;

    assert forall u: int, v: int ::
        (u, v) in p
        <==>
        0 <= u < n && 0 <= v < n && u * n + v < k - 1 by
    {
        forall u: int, v: int
            ensures
                (u, v) in p
                <==>
                0 <= u < n && 0 <= v < n
                && u * n + v < k - 1
        {
            if (u, v) in p {
                assert (u, v) in f;
                assert !(u == a && v == b);
                assert 0 <= u < n;
                assert 0 <= v < n;
                assert u * n + v < k;

                if !(u * n + v < k - 1) {
                    assert u * n + v == k - 1;
                    GridIndexFacts(n, k - 1, u, v);
                    assert u == a && v == b;
                    assert false;
                }
            }

            if 0 <= u < n && 0 <= v < n
                && u * n + v < k - 1
            {
                assert (u, v) in f;
                if u == a && v == b {
                    assert u * n + v == k - 1;
                    assert false;
                }
                assert (u, v) in p;
            }
        }
    }
}

lemma {:isolate_assertions} PrefixRemoveBounds(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures forall u: int, v: int ::
        0 <= u < |g|
        && 0 <= v < |g|
        && u * |g| + v < k - 1
        ==>
        0 <=
            (f - {((k - 1) / |g|, (k - 1) % |g|)})[(u, v)]
            <= CapacityAt(g, u, v)
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;

    assert forall u: int, v: int ::
        0 <= u < n && 0 <= v < n
        && u * n + v < k - 1
        ==> 0 <= p[(u, v)] <= CapacityAt(g, u, v) by
    {
        forall u: int, v: int |
            0 <= u < n && 0 <= v < n
            && u * n + v < k - 1
            ensures 0 <= p[(u, v)] <= CapacityAt(g, u, v)
        {
            assert 0 <= f[(u, v)] <= CapacityAt(g, u, v);
            if u == a && v == b {
                assert u * n + v == k - 1;
                assert false;
            }
            assert p[(u, v)] == f[(u, v)];
        }
    }
}

lemma PrefixRemoveRestore(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures
        (f - {((k - 1) / |g|, (k - 1) % |g|)})
            [((k - 1) / |g|, (k - 1) % |g|)
                := f[((k - 1) / |g|, (k - 1) % |g|)]]
        == f
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;

    IndexCoordinates(n, k - 1);
    assert a * n + b == k - 1;
    assert (a, b) in f;
    assert (f - {(a, b)})[(a, b) := f[(a, b)]] == f;
}

lemma PrefixRemoveShape(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 < k <= |g| * |g|
    requires PrefixShape(g, k, f)
    ensures PrefixShape(
        g, k - 1,
        f - {((k - 1) / |g|, (k - 1) % |g|)})
    ensures 0 <= f[((k - 1) / |g|, (k - 1) % |g|)]
        <= CapacityAt(
            g, (k - 1) / |g|, (k - 1) % |g|)
    ensures
        (f - {((k - 1) / |g|, (k - 1) % |g|)})
            [((k - 1) / |g|, (k - 1) % |g|)
                := f[((k - 1) / |g|, (k - 1) % |g|)]]
        == f
{
    var n := |g|;
    var a := (k - 1) / n;
    var b := (k - 1) % n;
    var p := f - {(a, b)};

    IndexCoordinates(n, k - 1);
    assert 0 <= a < n;
    assert 0 <= b < n;
    assert a * n + b == k - 1;
    assert (a, b) in f;
    assert 0 <= f[(a, b)] <= CapacityAt(g, a, b);

    PrefixRemoveDomain(g, k, f);
    PrefixRemoveBounds(g, k, f);
    PrefixRemoveRestore(g, k, f);

    assert 0 <= k - 1 <= n * n;
    assert PrefixShape(g, k - 1, p);
}

lemma {:isolate_assertions} EnumeratedCharacterization(
    g: seq<seq<(int, int)>>,
    k: int,
    f: FlowMap)
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    ensures f in EnumeratedFlows(g, k) <==> PrefixShape(g, k, f)
    decreases k
{
    if k == 0 {
        if f in EnumeratedFlows(g, k) {
            assert f == map[];
            assert PrefixShape(g, k, f);
        }
        if PrefixShape(g, k, f) {
            PrefixShapeZeroIsEmpty(g, f);
            assert f == map[];
            assert f in EnumeratedFlows(g, k);
        }
    } else {
        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;

        IndexCoordinates(n, k - 1);
        assert 0 <= u < n;
        assert 0 <= v < n;
        assert u * n + v == k - 1;

        if f in EnumeratedFlows(g, k) {
            var p: FlowMap, x: int :|
                p in EnumeratedFlows(g, k - 1)
                && 0 <= x <= CapacityAt(g, u, v)
                && f == p[(u, v) := x];

            EnumeratedCharacterization(g, k - 1, p);
            assert PrefixShape(g, k - 1, p);
            PrefixExtendShape(g, k - 1, p, x);
            assert PrefixShape(g, k, f);
        }

        if PrefixShape(g, k, f) {
            var p := f - {(u, v)};
            PrefixRemoveShape(g, k, f);
            assert PrefixShape(g, k - 1, p);
            EnumeratedCharacterization(g, k - 1, p);
            assert p in EnumeratedFlows(g, k - 1);
            assert 0 <= f[(u, v)] <= CapacityAt(g, u, v);
            assert p[(u, v) := f[(u, v)]] == f;
            assert f in EnumeratedFlows(g, k);
        }
    }
}

lemma ValidGetBounds(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    ensures 0 <= ActualGet(f, u, v) <= CapacityAt(g, u, v)
{
    ActualGetAgreement(f, u, v);
    CapacityNonnegative(g, u, v);

    if (u, v) in f {
        assert f[(u, v)] >= 0;
        if f[(u, v)] > 0 {
            var c :|
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c;
            CapacityMatchesEdge(g, u, v, c);
        }
    }
}

lemma {:isolate_assertions} CanonicalGet(
    f: FlowMap,
    n: int,
    k: int,
    u: int,
    v: int)
    requires 0 < n
    requires 0 <= k <= n * n
    requires 0 <= u < n
    requires 0 <= v < n
    requires u * n + v < k
    ensures ActualGet(CanonicalPrefix(f, n, k), u, v)
        == ActualGet(f, u, v)
    decreases k
{
    if k > 0 {
        var a := (k - 1) / n;
        var b := (k - 1) % n;
        var z := u * n + v;

        IndexCoordinates(n, k - 1);

        if z == k - 1 {
            GridIndexFacts(n, k - 1, u, v);
            assert u == a && v == b;
        } else {
            assert z < k - 1;
            CanonicalGet(f, n, k - 1, u, v);
            assert a * n + b == k - 1;
            if u == a && v == b {
                assert z == k - 1;
                assert false;
            }
        }
    }
}

lemma {:isolate_assertions} CanonicalShape(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    k: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 < |g|
    requires 0 <= k <= |g| * |g|
    ensures PrefixShape(g, k, CanonicalPrefix(f, |g|, k))
    decreases k
{
    if k == 0 {
        assert CanonicalPrefix(f, |g|, k) == map[];
        assert PrefixShape(g, k, map[]);
    } else {
        CanonicalShape(g, f, s, t, k - 1);

        var n := |g|;
        var u := (k - 1) / n;
        var v := (k - 1) % n;
        var p := CanonicalPrefix(f, n, k - 1);
        var x := ActualGet(f, u, v);

        IndexCoordinates(n, k - 1);
        assert 0 <= u < n;
        assert 0 <= v < n;

        ValidGetBounds(g, f, s, t, u, v);
        PrefixExtendShape(g, k - 1, p, x);

        assert CanonicalPrefix(f, n, k)
            == p[(u, v) := x];
    }
}

lemma CanonicalEnumerated(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 < |g|
    ensures CanonicalPrefix(f, |g|, |g| * |g|)
        in EnumeratedFlows(g, |g| * |g|)
{
    CanonicalShape(g, f, s, t, |g| * |g|);
    EnumeratedCharacterization(
        g, |g| * |g|,
        CanonicalPrefix(f, |g|, |g| * |g|));
}

lemma PointwiseSumOut(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    h: FlowMap,
    u: int,
    idx: int)
    requires well_formed(CapacityGraph(g))
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    requires forall a: int, b: int ::
        0 <= a < |g| && 0 <= b < |g|
        ==> ActualGet(f, a, b) == ActualGet(h, a, b)
    ensures ActualSumOut(g, f, u, idx)
        == ActualSumOut(g, h, u, idx)
    decreases idx
{
    if idx > 0 {
        PointwiseSumOut(g, f, h, u, idx - 1);
        assert 0 <= idx - 1 < |g[u]|;
        assert 0 <= g[u][idx - 1].0 < |g|;
        assert ActualGet(f, u, g[u][idx - 1].0)
            == ActualGet(h, u, g[u][idx - 1].0);
    }
}

lemma PointwiseSumIn(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
