lemma LootShiftUp(
    houses: seq<int>, nums: seq<int>, delta: int)
    requires 0 <= delta <= |nums|
    requires forall i: int :: 0 <= i < |houses| ==>
        0 <= houses[i] < |nums| - delta
    ensures total_loot(shift_indices(houses, delta), nums) ==
            total_loot(houses, nums[delta..])
    decreases |houses|
{
    if |houses| > 0 {
        ShiftTail(houses, delta);

        assert 0 <= houses[0] < |nums| - delta;
        assert 0 <= houses[0] + delta < |nums|;
        assert nums[delta..][houses[0]] ==
               nums[houses[0] + delta];

        forall i: int | 0 <= i < |houses[1..]|
            ensures 0 <= houses[1..][i] < |nums| - delta
        {
            assert houses[1..][i] == houses[i + 1];
            assert 0 <= i + 1 < |houses|;
        }

        LootShiftUp(houses[1..], nums, delta);

        calc {
            total_loot(shift_indices(houses, delta), nums);
            == nums[houses[0] + delta] +
               total_loot(
                   shift_indices(houses[1..], delta), nums);
            == nums[delta..][houses[0]] +
               total_loot(houses[1..], nums[delta..]);
            == total_loot(houses, nums[delta..]);
        }
    }
}

lemma LootShiftDown(
    houses: seq<int>, nums: seq<int>, delta: int)
    requires 0 <= delta <= |nums|
    requires forall i: int :: 0 <= i < |houses| ==>
        delta <= houses[i] < |nums|
    ensures total_loot(houses, nums) ==
            total_loot(
                shift_indices(houses, -delta), nums[delta..])
    decreases |houses|
{
