lemma PrependZeroValid(houses: seq<int>, nums_len: int)
    requires nums_len >= 2
    requires is_valid_robbery(houses, nums_len - 2)
    ensures is_valid_robbery(
        [0] + shift_indices(houses, 2), nums_len)
{
    ValidShiftUp(houses, nums_len - 2, 2);
    ShiftProperties(houses, 2);

    forall i: int |
        0 <= i < |[0] + shift_indices(houses, 2)|
        ensures 0 <= ([0] + shift_indices(houses, 2))[i] <
                nums_len
    {
        if i == 0 {
            assert ([0] + shift_indices(houses, 2))[i] == 0;
        } else {
            assert 0 <= i - 1 < |shift_indices(houses, 2)|;
            assert ([0] + shift_indices(houses, 2))[i] ==
                   shift_indices(houses, 2)[i - 1];
        }
    }

    forall i: int |
        0 <= i < |[0] + shift_indices(houses, 2)| - 1
        ensures ([0] + shift_indices(houses, 2))[i + 1] >=
                ([0] + shift_indices(houses, 2))[i] + 2
    {
        if i == 0 {
            assert |houses| > 0;
            assert 0 <= houses[0];
            assert shift_indices(houses, 2)[0] ==
                   houses[0] + 2;
            assert ([0] + shift_indices(houses, 2))[0] == 0;
            assert ([0] + shift_indices(houses, 2))[1] ==
                   shift_indices(houses, 2)[0];
        } else {
            assert ([0] + shift_indices(houses, 2))[i] ==
                   shift_indices(houses, 2)[i - 1];
            assert ([0] + shift_indices(houses, 2))[i + 1] ==
                   shift_indices(houses, 2)[i];
            assert shift_indices(houses, 2)[i] >=
                   shift_indices(houses, 2)[i - 1] + 2;
        }
    }
}

method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    ensures forall houses: seq<int> ::
        (is_valid_robbery(houses, |nums|)
            ==> total_loot(houses, nums) <= max_amount)
    ensures exists houses: seq<int> ::
        (is_valid_robbery(houses, |nums|)
            && total_loot(houses, nums) == max_amount)
    decreases |nums|
{
    if |nums| == 0 {
        max_amount := 0;

        forall houses: seq<int> |
            is_valid_robbery(houses, |nums|)
            ensures total_loot(houses, nums) <= max_amount
        {
            if |houses| > 0 {
                assert 0 <= houses[0] < 0;
                assert false;
            }
            assert |houses| == 0;
            assert total_loot(houses, nums) == 0;
        }

        assert is_valid_robbery([], 0);
        assert total_loot([], nums) == 0;
        assert exists houses: seq<int> ::
            is_valid_robbery(houses, |nums|) &&
            total_loot(houses, nums) == max_amount;
    } else if |nums| == 1 {
        max_amount := nums[0];
        assert max_amount >= 0;

        forall houses: seq<int> |
            is_valid_robbery(houses, |nums|)
            ensures total_loot(houses, nums) <= max_amount
        {
            if |houses| == 0 {
                assert total_loot(houses, nums) == 0;
            } else {
                assert 0 <= houses[0] < 1;
                assert houses[0] == 0;

                if |houses| > 1 {
                    assert houses[1] >= houses[0] + 2;
                    assert 0 <= houses[1] < 1;
                    assert false;
                }

                assert |houses| == 1;
                assert houses == [0];
                assert total_loot(houses, nums) == nums[0];
            }
        }

        assert is_valid_robbery([0], |nums|);
        assert total_loot([0], nums) == nums[0];
        assert exists houses: seq<int> ::
            is_valid_robbery(houses, |nums|) &&
            total_loot(houses, nums) == max_amount;
    } else {
        forall i: int | 0 <= i < |nums[1..]|
            ensures nums[1..][i] >= 0
            ensures nums[1..][i] <= 10000
        {
            assert nums[1..][i] == nums[i + 1];
            assert 0 <= i + 1 < |nums|;
        }

        forall i: int | 0 <= i < |nums[2..]|
            ensures nums[2..][i] >= 0
            ensures nums[2..][i] <= 10000
        {
            assert nums[2..][i] == nums[i + 2];
            assert 0 <= i + 2 < |nums|;
        }

        var skip_amount := rob(nums[1..]);
        var rest_amount := rob(nums[2..]);
        var take_amount := nums[0] + rest_amount;

        ghost var skip_houses: seq<int> :|
            is_valid_robbery(skip_houses, |nums[1..]|) &&
            total_loot(skip_houses, nums[1..]) == skip_amount;

        ghost var take_houses: seq<int> :|
            is_valid_robbery(take_houses, |nums[2..]|) &&
            total_loot(take_houses, nums[2..]) == rest_amount;

        if skip_amount >= take_amount {
            max_amount := skip_amount;
        } else {
            max_amount := take_amount;
        }

        assert skip_amount >= 0;
        assert rest_amount >= 0;
        assert nums[0] >= 0;
        assert take_amount >= 0;
        assert max_amount >= 0;
        assert skip_amount <= max_amount;
        assert take_amount <= max_amount;

        forall houses: seq<int> |
            is_valid_robbery(houses, |nums|)
            ensures total_loot(houses, nums) <= max_amount
        {
            if |houses| == 0 {
                assert total_loot(houses, nums) == 0;
            } else if houses[0] == 0 {
                ValidTail(houses, |nums|);

                if |houses[1..]| > 0 {
                    assert houses[1] >= houses[0] + 2;
                    FirstIsMinimum(houses[1..], |nums|);
                }

                forall i: int | 0 <= i < |houses[1..]|
                    ensures 2 <= houses[1..][i] < |nums|
                {
                    assert houses[1..][i] == houses[i + 1];
                    if |houses[1..]| > 0 {
                        assert houses[1..][i] >=
                               houses[1..][0];
                        assert houses[1..][0] == houses[1];
                        assert houses[1] >= 2;
                    }
                }

                ValidShiftDown(houses[1..], |nums|, 2);
                LootShiftDown(houses[1..], nums, 2);

                ghost var reduced :=
                    shift_indices(houses[1..], -2);

                assert is_valid_robbery(reduced, |nums| - 2);
                assert |nums[2..]| == |nums| - 2;
                assert is_valid_robbery(reduced, |nums[2..]|);
                assert total_loot(reduced, nums[2..]) <=
                       rest_amount;
                assert total_loot(houses[1..], nums) ==
                       total_loot(reduced, nums[2..]);

                calc {
                    total_loot(houses, nums);
                    == nums[0] +
                       total_loot(houses[1..], nums);
                    == nums[0] +
                       total_loot(reduced, nums[2..]);
                    <= nums[0] + rest_amount;
                    == take_amount;
                    <= max_amount;
                }
            } else {
                assert 0 <= houses[0] < |nums|;
                assert houses[0] >= 1;
                FirstIsMinimum(houses, |nums|);

                forall i: int | 0 <= i < |houses|
                    ensures 1 <= houses[i] < |nums|
                {
                    assert houses[i] >= houses[0];
                }

                ValidShiftDown(houses, |nums|, 1);
                LootShiftDown(houses, nums, 1);

                ghost var reduced :=
                    shift_indices(houses, -1);

                assert is_valid_robbery(reduced, |nums| - 1);
                assert |nums[1..]| == |nums| - 1;
                assert is_valid_robbery(reduced, |nums[1..]|);
                assert total_loot(reduced, nums[1..]) <=
                       skip_amount;
                assert total_loot(houses, nums) ==
                       total_loot(reduced, nums[1..]);

                calc {
                    total_loot(houses, nums);
                    == total_loot(reduced, nums[1..]);
                    <= skip_amount;
                    <= max_amount;
                }
            }
        }

        if skip_amount >= take_amount {
            ghost var chosen_plan :=
                shift_indices(skip_houses, 1);

            ValidShiftUp(skip_houses, |nums[1..]|, 1);
            assert |nums[1..]| + 1 == |nums|;
            assert is_valid_robbery(chosen_plan, |nums|);

            forall i: int | 0 <= i < |skip_houses|
                ensures 0 <= skip_houses[i] < |nums| - 1
            {
                assert 0 <= skip_houses[i] < |nums[1..]|;
            }

            LootShiftUp(skip_houses, nums, 1);
            assert total_loot(chosen_plan, nums) ==
                   total_loot(skip_houses, nums[1..]);
            assert total_loot(chosen_plan, nums) == max_amount;

            assert exists houses: seq<int> ::
                is_valid_robbery(houses, |nums|) &&
                total_loot(houses, nums) == max_amount;
        } else {
            ghost var chosen_plan :=
                [0] + shift_indices(take_houses, 2);

            assert |nums[2..]| == |nums| - 2;
            PrependZeroValid(take_houses, |nums|);
            assert is_valid_robbery(chosen_plan, |nums|);

            forall i: int | 0 <= i < |take_houses|
                ensures 0 <= take_houses[i] < |nums| - 2
            {
                assert 0 <= take_houses[i] < |nums[2..]|;
            }

            LootShiftUp(take_houses, nums, 2);

            calc {
                total_loot(chosen_plan, nums);
                == nums[0] +
                   total_loot(
                       shift_indices(take_houses, 2), nums);
                == nums[0] +
                   total_loot(take_houses, nums[2..]);
                == nums[0] + rest_amount;
                == take_amount;
                == max_amount;
            }

            assert exists houses: seq<int> ::
                is_valid_robbery(houses, |nums|) &&
                total_loot(houses, nums) == max_amount;
        }
    }
}

