  assert cs[u] == 0;
  assert c[u] == 1;

  forall v | 0 <= v < |c| && cs[v] == 2
    ensures c[v] == 2 && r[v] == rs[v]
  {
    assert v != u;
    assert c[v] == cs[v];
    assert r[v] == rs[v];
  }
  forall v | 0 <= v < |c| && cs[v] == 1
    ensures c[v] == 1
  {
    assert cs[u] == 0;
    assert v != u;
    assert c[v] == cs[v];
  }
  forall v | 0 <= v < |c| && cs[v] == 0 && v != u
    ensures c[v] == 0 || c[v] == 2
  {
    assert c[v] == cs[v];
    assert c[v] == 0;
  }
  forall v | 0 <= v < |c| && c[v] == 0
    ensures cs[v] == 0 && v != u
  {
    assert c[u] == 1;
    assert v != u;
    assert c[v] == cs[v];
  }
  forall v | 0 <= v < |c| && c[v] == 1 && v != u
    ensures cs[v] == 1
  {
    assert c[v] == cs[v];
  }
  assert loop_rel(cs, c, rs, r, u);
}

lemma chain_loop_rel(
  cs: seq<int>, cb: seq<int>, ca: seq<int>,
  rs: seq<int>, rb: seq<int>, ra: seq<int>,
  u: int, v: int
)
  requires loop_rel(cs, cb, rs, rb, u)
  requires post_rel(cb, ca, rb, ra, v)
  requires u != v
  requires colors_valid(cb, |cb|)
  ensures loop_rel(cs, ca, rs, ra, u)
{
  assert |cs| == |cb|;
  assert |cb| == |ca|;
  assert |rs| == |rb|;
  assert |rb| == |ra|;
  assert |cs| == |ca|;
  assert |rs| == |ra|;
  assert |cs| == |rs|;
  assert 0 <= u < |cb|;
  assert 0 <= u < |ca|;
  assert cs[u] == 0;
  assert cb[u] == 1;
  assert ca[u] == 1;

  forall x | 0 <= x < |ca| && cs[x] == 2
    ensures ca[x] == 2 && ra[x] == rs[x]
  {
    assert cb[x] == 2 && rb[x] == rs[x];
    assert ca[x] == 2 && ra[x] == rb[x];
  }
  forall x | 0 <= x < |ca| && cs[x] == 1
    ensures ca[x] == 1
  {
    assert cb[x] == 1;
    assert ca[x] == 1;
  }
  forall x | 0 <= x < |ca| && cs[x] == 0 && x != u
    ensures ca[x] == 0 || ca[x] == 2
  {
    assert cb[x] == 0 || cb[x] == 2;
    if cb[x] == 2 {
      assert ca[x] == 2;
    } else {
      assert cb[x] == 0;
      assert ca[x] == 0 || ca[x] == 2;
    }
  }
  forall x | 0 <= x < |ca| && ca[x] == 0
    ensures cs[x] == 0 && x != u
  {
    assert cb[x] == 0 || cb[x] == 1 || cb[x] == 2;
    if cb[x] == 1 {
      assert ca[x] == 1;
      assert false;
    } else if cb[x] == 2 {
      assert ca[x] == 2;
      assert false;
    } else {
      assert cb[x] == 0;
      assert cs[x] == 0 && x != u;
    }
  }
  forall x | 0 <= x < |ca| && ca[x] == 1 && x != u
    ensures cs[x] == 1
  {
    assert cb[x] == 1;
    assert cs[x] == 1;
  }
  assert loop_rel(cs, ca, rs, ra, u);
}

lemma finish_node(g: Graph, color: seq<int>, rank: seq<int>, u: int, time: int)
  requires colors_valid(color, |g.adj|)
  requires 0 <= u < |g.adj|
  requires color[u] == 1
  requires time_ok(color, rank, time)
  requires black_edges_ranked(g, color, rank)
  requires forall j :: 0 <= j < |g.adj[u]| ==> 0 <= g.adj[u][j] < |g.adj| && color[g.adj[u][j]] == 2
  ensures colors_valid(color[u := 2], |g.adj|)
  ensures black_edges_ranked(g, color[u := 2], rank[u := time])
  ensures time_ok(color[u := 2], rank[u := time], time + 1)
{
  var c2 := color[u := 2];
  var r2 := rank[u := time];
  var n := |g.adj|;

  forall v | 0 <= v < n
    ensures c2[v] == 0 || c2[v] == 1 || c2[v] == 2
  {
    if v == u {
      assert c2[v] == 2;
    } else {
      assert c2[v] == color[v];
    }
  }

  forall x, j | 0 <= x < n && c2[x] == 2 && 0 <= j < |g.adj[x]|
    ensures 0 <= g.adj[x][j] < n && c2[g.adj[x][j]] == 2 && r2[g.adj[x][j]] < r2[x]
  {
    var y := g.adj[x][j];
    if x == u {
      assert 0 <= y < n && color[y] == 2;
      assert color[u] == 1;
      assert y != u;
      assert c2[y] == color[y];
      assert r2[y] == rank[y];
      assert 0 <= rank[y] < time;
      assert r2[x] == time;
      assert r2[y] < r2[x];
    } else {
      assert c2[x] == color[x];
      assert color[x] == 2;
      assert 0 <= y < n && color[y] == 2 && rank[y] < rank[x];
      assert color[u] == 1;
      assert y != u;
      assert c2[y] == color[y];
      assert r2[y] == rank[y];
      assert r2[x] == rank[x];
    }
  }

  forall v | 0 <= v < n && c2[v] == 2
    ensures 0 <= r2[v] < time + 1
  {
    if v == u {
      assert r2[v] == time;
      assert time >= 0;
      assert r2[v] < time + 1;
    } else {
      assert c2[v] == color[v];
      assert color[v] == 2;
      assert 0 <= rank[v] < time;
      assert r2[v] == rank[v];
      assert r2[v] < time + 1;
    }
  }

  assert colors_valid(c2, n);
  assert black_edges_ranked(g, c2, r2);
  assert time_ok(c2, r2, time + 1);
}

lemma finish_rel(cs: seq<int>, c: seq<int>, rs: seq<int>, r: seq<int>, u: int, time: int)
  requires loop_rel(cs, c, rs, r, u)
  ensures post_rel(cs, c[u := 2], rs, r[u := time], u)
{
  var c2 := c[u := 2];
  var r2 := r[u := time];
  assert |cs| == |c2|;
  assert |rs| == |r2|;
  assert |cs| == |rs|;
  assert 0 <= u < |c2|;
  assert c2[u] == 2;
  assert cs[u] == 0;
  assert c[u] == 1;

  forall x | 0 <= x < |c2| && cs[x] == 2
    ensures c2[x] == 2 && r2[x] == rs[x]
  {
    assert x != u;
    assert c[x] == 2 && r[x] == rs[x];
    assert c2[x] == c[x];
    assert r2[x] == r[x];
  }
  forall x | 0 <= x < |c2| && cs[x] == 1
    ensures c2[x] == 1
  {
    assert x != u;
    assert c[x] == 1;
    assert c2[x] == c[x];
  }
  forall x | 0 <= x < |c2| && cs[x] == 0
    ensures c2[x] == 0 || c2[x] == 2
  {
    if x == u {
      assert c2[x] == 2;
    } else {
      assert c[x] == 0 || c[x] == 2;
      assert c2[x] == c[x];
    }
  }
  forall x | 0 <= x < |c2| && c2[x] == 1
    ensures cs[x] == 1
  {
    assert c2[u] == 2;
    assert x != u;
    assert c[x] == c2[x];
    assert c[x] == 1;
    assert cs[x] == 1;
  }
  assert post_rel(cs, c2, rs, r2, u);
}

lemma transfer_stack_gray(cb: seq<int>, ca: seq<int>, rb: seq<int>, ra: seq<int>, stack: seq<int>, child: int)
  requires stack_gray(cb, stack, |cb|)
  requires post_rel(cb, ca, rb, ra, child)
  ensures stack_gray(ca, stack, |ca|)
{
  var n := |ca|;
  assert |cb| == n;
  forall t | 0 <= t < |stack|
    ensures 0 <= stack[t] < n && ca[stack[t]] == 1
  {
    assert 0 <= stack[t] < |cb|;
    assert cb[stack[t]] == 1;
    assert ca[stack[t]] == 1;
  }
  forall v | 0 <= v < n && ca[v] == 1
    ensures v in stack
  {
    assert cb[v] == 1;
    assert v in stack;
  }
}

lemma restore_processed(
  g: Graph, u: int, ei: int,
  cb: seq<int>, ca: seq<int>, rb: seq<int>, ra: seq<int>, child: int
)
  requires well_formed(g)
  requires |cb| == |g.adj|
  requires 0 <= u < |g.adj|
  requires 0 <= ei <= |g.adj[u]|
  requires post_rel(cb, ca, rb, ra, child)
  requires forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < |cb| && cb[g.adj[u][j]] == 2
  ensures forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < |ca| && ca[g.adj[u][j]] == 2
{
  assert |ca| == |cb|;
  forall j | 0 <= j < ei
    ensures 0 <= g.adj[u][j] < |ca| && ca[g.adj[u][j]] == 2
  {
    var y := g.adj[u][j];
    assert 0 <= y < |cb| && cb[y] == 2;
    assert 0 <= y < |ca|;
    assert ca[y] == 2;
  }
}

lemma node_from_edge(g: Graph, u: int, v: int)
  requires well_formed(g)
  requires has_edge(g, u, v)
  ensures 0 <= u < |g.adj|
  ensures 0 <= v < |g.adj|
{
  var j :| 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| && g.adj[u][j] == v;
  assert 0 <= u < |g.adj| && 0 <= j < |g.adj[u]|;
  assert 0 <= g.adj[u][j] < |g.adj|;
  assert v == g.adj[u][j];
}

lemma cycle_nodes_in_range(g: Graph, p: seq<int>)
  requires well_formed(g)
  requires is_cycle(g, p)
  ensures forall i :: 0 <= i < |p| ==> 0 <= p[i] < |g.adj|
{
  assert is_path(g, p);
  assert |p| > 1;
  forall i | 0 <= i < |p|
    ensures 0 <= p[i] < |g.adj|
  {
    if i == |p| - 1 {
      assert has_edge(g, p[|p| - 2], p[|p| - 1]);
      node_from_edge(g, p[|p| - 2], p[|p| - 1]);
    } else {
      assert has_edge(g, p[i], p[i + 1]);
      node_from_edge(g, p[i], p[i + 1]);
    }
  }
}

lemma edge_rank_decrease(g: Graph, color: seq<int>, rank: seq<int>, u: int, v: int)
  requires black_edges_ranked(g, color, rank)
  requires 0 <= u < |g.adj|
  requires color[u] == 2
  requires has_edge(g, u, v)
  ensures 0 <= v < |g.adj|
  ensures color[v] == 2
  ensures rank[v] < rank[u]
{
  var j :| 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| && g.adj[u][j] == v;
  assert 0 <= g.adj[u][j] < |g.adj| && color[g.adj[u][j]] == 2 && rank[g.adj[u][j]] < rank[u];
  assert v == g.adj[u][j];
}

lemma path_rank_drop(g: Graph, color: seq<int>, rank: seq<int>, p: seq<int>, a: int, b: int)
  requires well_formed(g)
  requires black_edges_ranked(g, color, rank)
  requires is_path(g, p)
  requires 0 <= a <= b < |p|
  requires forall i :: 0 <= i < |p| ==> 0 <= p[i] < |g.adj| && color[p[i]] == 2
  ensures rank[p[b]] <= rank[p[a]] - (b - a)
  decreases b - a
{
  if a < b {
    assert has_edge(g, p[a], p[a + 1]);
    assert 0 <= p[a] < |g.adj| && color[p[a]] == 2;
    edge_rank_decrease(g, color, rank, p[a], p[a + 1]);
    assert rank[p[a + 1]] < rank[p[a]];
    assert rank[p[a + 1]] <= rank[p[a]] - 1;
    path_rank_drop(g, color, rank, p, a + 1, b);
    var ra := rank[p[a]];
    var r1 := rank[p[a + 1]];
    var rb := rank[p[b]];
    assert r1 <= ra - 1;
    assert rb <= r1 - (b - (a + 1));
    assert rb <= ra - 1 - (b - a - 1);
    assert ra - 1 - (b - a - 1) == ra - (b - a);
    assert rb <= ra - (b - a);
  }
}

lemma ranked_acyclic(g: Graph, color: seq<int>, rank: seq<int>)
  requires well_formed(g)
  requires black_edges_ranked(g, color, rank)
  requires forall v :: 0 <= v < |g.adj| ==> color[v] == 2
  ensures !graph_has_cycle(g)
{
  forall p | is_cycle(g, p)
    ensures false
  {
    cycle_nodes_in_range(g, p);
    assert is_path(g, p);
    assert |p| > 1;
    forall i | 0 <= i < |p|
      ensures 0 <= p[i] < |g.adj| && color[p[i]] == 2
    {
      assert 0 <= p[i] < |g.adj|;
      assert color[p[i]] == 2;
    }
    var drop := |p| - 1;
    path_rank_drop(g, color, rank, p, 0, drop);
    assert rank[p[drop]] <= rank[p[0]] - drop;
    assert p[drop] == p[0];
    assert drop >= 1;
    var r0 := rank[p[0]];
    assert r0 <= r0 - drop;
    assert r0 <= r0 - 1;
    assert false;
  }
  assert !graph_has_cycle(g);
}

lemma init_black_edges(g: Graph, color: seq<int>, rank: seq<int>)
  requires |color| == |g.adj|
  requires |rank| == |g.adj|
  requires forall v :: 0 <= v < |g.adj| ==> color[v] == 0
  ensures colors_valid(color, |g.adj|)
  ensures time_ok(color, rank, 0)
  ensures black_edges_ranked(g, color, rank)
{
  var n := |g.adj|;
  forall v | 0 <= v < n
    ensures color[v] == 0 || color[v] == 1 || color[v] == 2
  {
    assert color[v] == 0;
  }
  forall u, j | 0 <= u < n && color[u] == 2 && 0 <= j < |g.adj[u]|
    ensures 0 <= g.adj[u][j] < n && color[g.adj[u][j]] == 2 && rank[g.adj[u][j]] < rank[u]
  {
    assert color[u] == 0;
    assert false;
  }
  forall v | 0 <= v < n && color[v] == 2
    ensures 0 <= rank[v] < 0
  {
    assert color[v] == 0;
    assert false;
  }
  assert colors_valid(color, n);
  assert time_ok(color, rank, 0);
  assert black_edges_ranked(g, color, rank);
}

lemma after_top_visit(before: seq<int>, after: seq<int>, rb: seq<int>, ra: seq<int>, i: int, n: int)
  requires post_rel(before, after, rb, ra, i)
  requires |before| == n
  requires forall v :: 0 <= v < n ==> before[v] == 0 || before[v] == 2
  requires forall v :: 0 <= v < i ==> before[v] == 2
  requires 0 <= i < n
  ensures forall v :: 0 <= v < n ==> after[v] == 0 || after[v] == 2
  ensures forall v :: 0 <= v < i + 1 ==> after[v] == 2
  ensures after[i] == 2
{
  forall v | 0 <= v < n
    ensures after[v] == 0 || after[v] == 2
  {
    if before[v] == 2 {
      assert after[v] == 2;
    } else {
      assert before[v] == 0;
      assert after[v] == 0 || after[v] == 2;
    }
  }
  forall v | 0 <= v < i + 1
    ensures after[v] == 2
  {
    if v < i {
      assert before[v] == 2;
      assert after[v] == 2;
    } else {
      assert v == i;
      assert after[i] == 2;
    }
  }
}

lemma close_node(color: seq<int>, i: int, n: int)
  requires |color| == n
  requires 0 <= i < n
  requires forall v :: 0 <= v < i ==> color[v] == 2
  requires color[i] == 2
  ensures forall v :: 0 <= v < i + 1 ==> color[v] == 2
{
  forall v | 0 <= v < i + 1
    ensures color[v] == 2
  {
    if v < i {
      assert color[v] == 2;
    } else {
      assert v == i;
      assert color[v] == 2;
    }
  }
}

lemma empty_stack_ok(color: seq<int>, n: int)
  requires |color| == n
  requires forall v :: 0 <= v < n ==> color[v] == 0 || color[v] == 2
  ensures stack_gray(color, [], n)
{
  forall v | 0 <= v < n && color[v] == 1
    ensures v in []
  {
    assert color[v] == 0 || color[v] == 2;
    assert false;
  }
}

method visit(g: Graph, u: int, color: seq<int>, rank: seq<int>, time: int, stack: seq<int>)
  returns (color': seq<int>, rank': seq<int>, time': int, found: bool)
  requires well_formed(g)
  requires colors_valid(color, |g.adj|)
  requires |rank| == |g.adj|
  requires 0 <= u < |g.adj|
  requires color[u] == 0
  requires time_ok(color, rank, time)
  requires black_edges_ranked(g, color, rank)
  requires stack_gray(color, stack, |g.adj|)
  requires |stack| == 0 || is_path(g, stack)
  requires |stack| > 0 ==> has_edge(g, stack[|stack| - 1], u)
  ensures colors_valid(color', |g.adj|)
  ensures |rank'| == |g.adj|
  ensures found ==> graph_has_cycle(g)
  ensures !found ==> color'[u] == 2
  ensures !found ==> time_ok(color', rank', time')
  ensures !found ==> black_edges_ranked(g, color', rank')
  ensures !found ==> post_rel(color, color', rank, rank', u)
  decreases white_count(color)
{
  var n := |g.adj|;
  var colorCur := color[u := 1];
  var rankCur := rank;
  var timeCur := time;
  paint_gray_ok(g, color, rank, time, u);

  var localStack := stack + [u];
  extend_stack_gray(color, stack, u, n);
  path_extend(g, stack, u);
  init_loop_rel(color, rank, u);

  assert |localStack| == |stack| + 1;
  assert localStack[|localStack| - 1] == u;
  assert is_path(g, localStack);
  assert stack_gray(colorCur, localStack, n);
  assert loop_rel(color, colorCur, rank, rankCur, u);
  assert colors_valid(colorCur, n);
  assert time_ok(colorCur, rankCur, timeCur);
  assert black_edges_ranked(g, colorCur, rankCur);
  assert colorCur[u] == 1;
  assert |rankCur| == n;

  var ei := 0;
  while ei < |g.adj[u]|
    invariant 0 <= ei <= |g.adj[u]|
    invariant colors_valid(colorCur, n)
    invariant |rankCur| == n
    invariant time_ok(colorCur, rankCur, timeCur)
    invariant black_edges_ranked(g, colorCur, rankCur)
    invariant stack_gray(colorCur, localStack, n)
    invariant is_path(g, localStack)
    invariant |localStack| >= 1
    invariant localStack[|localStack| - 1] == u
    invariant colorCur[u] == 1
    invariant loop_rel(color, colorCur, rank, rankCur, u)
    invariant forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < n && colorCur[g.adj[u][j]] == 2
    decreases |g.adj[u]| - ei
  {
    var v := g.adj[u][ei];
    neighbor_in_range(g, u, ei);
    assert 0 <= v < n;

    if colorCur[v] == 1 {
      assert stack_gray(colorCur, localStack, n);
      assert v in localStack;
      ghost var k: int;
      k := find_index(localStack, v);
      adj_has_edge(g, u, ei);
      assert has_edge(g, u, v);
      assert localStack[|localStack| - 1] == u;
      assert localStack[k] == v;
      assert has_edge(g, localStack[|localStack| - 1], localStack[k]);
      assert is_path(g, localStack);
      cycle_from_backedge(g, localStack, k);
      assert is_cycle(g, localStack[k..] + [localStack[k]]);
      assert graph_has_cycle(g);
      color' := colorCur;
      rank' := rankCur;
      time' := timeCur;
      found := true;
      return;
    } else if colorCur[v] == 0 {
      assert is_path(g, localStack);
      assert localStack[|localStack| - 1] == u;
      adj_has_edge(g, u, ei);
      assert has_edge(g, u, v);
      assert colorCur[u] == 1;
      assert u != v;

      var colorBefore := colorCur;
      var rankBefore := rankCur;
      var timeBefore := timeCur;
      assert colorBefore == colorCur;
      assert rankBefore == rankCur;
      assert loop_rel(color, colorBefore, rank, rankBefore, u);
      assert stack_gray(colorBefore, localStack, n);
      assert forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < n && colorBefore[g.adj[u][j]] == 2;
      assert black_edges_ranked(g, colorBefore, rankBefore);
      assert time_ok(colorBefore, rankBefore, timeBefore);
      assert colors_valid(colorBefore, n);
      assert |colorBefore| == n;
      assert colors_valid(colorBefore, |colorBefore|);
      assert has_edge(g, localStack[|localStack| - 1], v);
      assert 0 <= localStack[|localStack| - 1] < n;

      white_shrink_rel(color, colorBefore, rank, rankBefore, u);
      assert white_count(colorBefore) < white_count(color);

      var foundNow: bool;
      colorCur, rankCur, timeCur, foundNow := visit(g, v, colorBefore, rankBefore, timeBefore, localStack);
      if foundNow {
        assert graph_has_cycle(g);
        color' := colorCur;
        rank' := rankCur;
        time' := timeCur;
        found := true;
        return;
      }
      assert post_rel(colorBefore, colorCur, rankBefore, rankCur, v);
      assert colorCur[v] == 2;
      assert time_ok(colorCur, rankCur, timeCur);
      assert black_edges_ranked(g, colorCur, rankCur);
      assert colors_valid(colorCur, n);
      assert |rankCur| == n;
      chain_loop_rel(color, colorBefore, colorCur, rank, rankBefore, rankCur, u, v);
      assert loop_rel(color, colorCur, rank, rankCur, u);
      assert colorCur[u] == 1;
      transfer_stack_gray(colorBefore, colorCur, rankBefore, rankCur, localStack, v);
      assert stack_gray(colorCur, localStack, n);
      restore_processed(g, u, ei, colorBefore, colorCur, rankBefore, rankCur, v);
      assert forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < n && colorCur[g.adj[u][j]] == 2;
    } else {
      assert colorCur[v] != 0 && colorCur[v] != 1;
      assert colorCur[v] == 0 || colorCur[v] == 1 || colorCur[v] == 2;
      assert colorCur[v] == 2;
      assert forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < n && colorCur[g.adj[u][j]] == 2;
    }

    assert forall j :: 0 <= j < ei ==> 0 <= g.adj[u][j] < n && colorCur[g.adj[u][j]] == 2;
    assert colorCur[v] == 2;
    assert v == g.adj[u][ei];
    neighbor_in_range(g, u, ei);
    forall jj | 0 <= jj < ei + 1
      ensures 0 <= g.adj[u][jj] < n && colorCur[g.adj[u][jj]] == 2
    {
      if jj < ei {
        assert 0 <= g.adj[u][jj] < n && colorCur[g.adj[u][jj]] == 2;
      } else {
        assert jj == ei;
        assert g.adj[u][jj] == v;
        assert 0 <= v < n && colorCur[v] == 2;
      }
    }
    ei := ei + 1;
