  forall x, y | 0 <= x < y < n ensures q[x] != q[y] {
    var fx := if x == j then i else if x == i then j else x;
    var fy := if y == j then i else if y == i then j else y;
    assert q[x] == p[fx];
    assert q[y] == p[fy];
    assert fx != fy;
    assert 0 <= fx < n && 0 <= fy < n;
    if fx < fy {
      assert p[fx] != p[fy];
