method can_jump(nums: seq<int>) returns (reachable: bool)
  requires |nums| > 0
  requires |nums| <= 10000
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
  ensures
    // reachable <==> exists path
    reachable <==> exists path: seq<int> :: is_valid_jump_path(path, nums)
{
  var maxR := 0;
  var idx := 0;
  FarthestZero(nums);

  while idx < |nums|
    invariant 0 <= idx <= |nums|
    invariant maxR == Farthest(nums, idx)
    decreases |nums| - idx
  {
    assert maxR == Farthest(nums, idx);
    if idx <= maxR {
      var cand := idx + nums[idx];
      if cand > maxR {
        FarthestTakeJump(nums, idx);
        assert Farthest(nums, idx + 1) == cand;
        maxR := cand;
        assert maxR == Farthest(nums, idx + 1);
      } else {
        FarthestKeep(nums, idx);
        assert Farthest(nums, idx + 1) == maxR;
      }
    } else {
      FarthestStuck(nums, idx);
      assert Farthest(nums, idx + 1) == maxR;
    }
    assert maxR == Farthest(nums, idx + 1);
    idx := idx + 1;
  }

  assert idx == |nums|;
  assert maxR == Farthest(nums, |nums|);
  reachable := maxR >= |nums| - 1;
  if reachable {
    assert Farthest(nums, |nums|) >= |nums| - 1;
    ExistsPath(nums);
    assert exists path: seq<int> :: is_valid_jump_path(path, nums);
  } else {
    assert Farthest(nums, |nums|) < |nums| - 1;
    NoPathWhenShort(nums);
    assert !(exists path: seq<int> :: is_valid_jump_path(path, nums));
  }
}
