  ensures swapped_index(i, j, a) != swapped_index(i, j, b)
{
  var ia := swapped_index(i, j, a);
  var ib := swapped_index(i, j, b);
  if a == i {
    assert ia == j;
    if b == j {
      assert ib == i;
      assert ia != ib;
    } else {
      assert a != b;
      assert b != i;
      assert b != j;
      assert ib == b;
      assert ia != ib;
    }
  } else if a == j {
    assert a != i;
    assert ia == i;
    if b == i {
      assert ib == j;
      assert ia != ib;
    } else {
      assert b != i;
      assert b != j;
      assert ib == b;
      assert ia != ib;
    }
  } else {
    assert a != i && a != j;
    assert ia == a;
    if b == i {
      assert ib == j;
      assert a != j;
      assert ia != ib;
    } else if b == j {
      assert ib == i;
      assert a != i;
      assert ia != ib;
    } else {
      assert ib == b;
      assert ia != ib;
    }
  }
}

lemma f_injective(i: int, j: int, a: int, b: int)
  requires a != b
  ensures swapped_index(i, j, a) != swapped_index(i, j, b)
{
  if i == j {
    swapped_index_is_id(i, j, a);
    swapped_index_is_id(i, j, b);
    assert swapped_index(i, j, a) == a;
    assert swapped_index(i, j, b) == b;
  } else {
    f_injective_distinct(i, j, a, b);
  }
}

lemma assemble_valid(p: seq<int>, n: int)
  requires |p| == n
  requires forall i {:trigger p[i]} :: 0 <= i < n ==> 0 <= p[i] < n
  requires forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j]
  ensures is_valid_index_permutation(p, n)
{
  assert |p| == n;
  assert forall i {:trigger p[i]} :: 0 <= i < n ==> 0 <= p[i] < n;
  assert forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j];
}

lemma index_in_range(p: seq<int>, n: int, ia: int)
  requires is_valid_index_permutation(p, n)
  requires 0 <= ia < n
  ensures 0 <= p[ia] < n
{
  assert forall i {:trigger p[i]} :: 0 <= i < n ==> 0 <= p[i] < n;
  assert 0 <= p[ia] < n;
}

lemma values_differ(p: seq<int>, n: int, x: int, y: int)
  requires is_valid_index_permutation(p, n)
  requires 0 <= x < n && 0 <= y < n && x != y
  ensures p[x] != p[y]
{
  assert forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j];
  if x < y {
    assert 0 <= x < y < n;
    assert p[x] != p[y];
  } else {
    assert 0 <= y < x < n;
    assert p[y] != p[x];
  }
}

lemma update_twice_spec(s: seq<int>, i: int, j: int, r: seq<int>)
  requires 0 <= i < |s| && 0 <= j < |s|
  requires r == (s[i := s[j]])[j := s[i]]
  ensures |r| == |s|
  ensures r[i] == s[j]
  ensures r[j] == s[i]
  ensures forall a :: 0 <= a < |s| && a != i && a != j ==> r[a] == s[a]
{
  var s1 := s[i := s[j]];
  assert s1 == s[i := s[j]];
  assert r == s1[j := s[i]];
  assert |s1| == |s|;
  assert |r| == |s1|;
  assert |r| == |s|;

  assert s1[i] == s[j];
  forall k | 0 <= k < |s| && k != i
    ensures s1[k] == s[k]
  {
    assert s1[k] == s[k];
  }

  assert r[j] == s[i];
  forall k | 0 <= k < |s| && k != j
    ensures r[k] == s1[k]
  {
    assert r[k] == s1[k];
  }

  if i == j {
    assert r[j] == s[i];
    assert r[i] == s[i];
    assert s[j] == s[i];
    assert r[i] == s[j];
  } else {
    assert r[i] == s1[i];
    assert s1[i] == s[j];
    assert r[i] == s[j];
    assert r[j] == s[i];
  }

  forall a | 0 <= a < |s| && a != i && a != j
    ensures r[a] == s[a]
  {
    assert s1[a] == s[a];
    assert r[a] == s1[a];
  }
}

lemma q_at_swapped(p: seq<int>, q: seq<int>, i: int, j: int, a: int)
  requires 0 <= i < |p| && 0 <= j < |p|
  requires |q| == |p|
  requires q[i] == p[j] && q[j] == p[i]
  requires forall b :: 0 <= b < |p| && b != i && b != j ==> q[b] == p[b]
  requires 0 <= a < |p|
  ensures q[a] == p[swapped_index(i, j, a)]
{
  if a == i {
    assert swapped_index(i, j, a) == j;
    assert q[a] == p[j];
  } else if a == j {
    assert a != i;
    assert swapped_index(i, j, a) == i;
    assert q[a] == p[i];
  } else {
    assert 0 <= a < |p| && a != i && a != j;
    assert swapped_index(i, j, a) == a;
    assert q[a] == p[a];
  }
}

lemma {:vcs_split_on_every_assert} swap_preserves_valid(p: seq<int>, q: seq<int>, n: int, i: int, j: int)
  requires is_valid_index_permutation(p, n)
  requires 0 <= i < n && 0 <= j < n
  requires |q| == n
  requires q[i] == p[j]
  requires q[j] == p[i]
  requires forall a :: 0 <= a < n && a != i && a != j ==> q[a] == p[a]
  ensures is_valid_index_permutation(q, n)
{
  assert |p| == n;
  assert |q| == |p|;

  forall a {:trigger q[a]} | 0 <= a < n
    ensures 0 <= q[a] < n
  {
    q_at_swapped(p, q, i, j, a);
    var ia := swapped_index(i, j, a);
    swapped_index_range(i, j, a, n);
    index_in_range(p, n, ia);
    assert q[a] == p[ia];
    assert 0 <= q[a] < n;
  }

  forall a, b {:trigger q[a], q[b]} | 0 <= a < b < n
    ensures q[a] != q[b]
  {
    var ia := swapped_index(i, j, a);
    var ib := swapped_index(i, j, b);
    q_at_swapped(p, q, i, j, a);
    q_at_swapped(p, q, i, j, b);
    f_injective(i, j, a, b);
    swapped_index_range(i, j, a, n);
    swapped_index_range(i, j, b, n);
    values_differ(p, n, ia, ib);
    assert q[a] == p[ia];
    assert q[b] == p[ib];
    assert q[a] != q[b];
  }

  assert forall aa {:trigger q[aa]} :: 0 <= aa < n ==> 0 <= q[aa] < n;
  assert forall aa, bb {:trigger q[aa], q[bb]} :: 0 <= aa < bb < n ==> q[aa] != q[bb];
  assemble_valid(q, n);
}

lemma mapping_preserved(
  v: seq<int>, sorted: seq<int>, p: seq<int>, s2: seq<int>, p2: seq<int>, i: int, m: int
)
  requires |v| == |sorted| == |p| == |s2| == |p2|
  requires 0 <= i < |v| && 0 <= m < |v|
  requires forall t {:trigger p[t]} :: 0 <= t < |v| ==> 0 <= p[t] < |v| && sorted[t] == v[p[t]]
  requires s2[i] == sorted[m] && s2[m] == sorted[i]
  requires p2[i] == p[m] && p2[m] == p[i]
  requires forall a :: 0 <= a < |v| && a != i && a != m ==> s2[a] == sorted[a]
  requires forall a :: 0 <= a < |v| && a != i && a != m ==> p2[a] == p[a]
  ensures forall t {:trigger p2[t]} :: 0 <= t < |v| ==> 0 <= p2[t] < |v| && s2[t] == v[p2[t]]
{
  forall t {:trigger p2[t]} | 0 <= t < |v|
    ensures 0 <= p2[t] < |v| && s2[t] == v[p2[t]]
  {
    if t == i {
      assert s2[t] == sorted[m];
      assert p2[t] == p[m];
      assert 0 <= m < |v|;
      assert 0 <= p[m] < |v| && sorted[m] == v[p[m]];
      assert 0 <= p2[t] < |v|;
      assert s2[t] == v[p[m]];
      assert v[p2[t]] == v[p[m]];
      assert s2[t] == v[p2[t]];
    } else if t == m {
      assert t != i;
      assert s2[t] == sorted[i];
      assert p2[t] == p[i];
      assert 0 <= i < |v|;
      assert 0 <= p[i] < |v| && sorted[i] == v[p[i]];
      assert 0 <= p2[t] < |v|;
      assert s2[t] == v[p[i]];
      assert v[p2[t]] == v[p[i]];
      assert s2[t] == v[p2[t]];
    } else {
      assert t != i && t != m;
      assert s2[t] == sorted[t];
      assert p2[t] == p[t];
      assert 0 <= p[t] < |v| && sorted[t] == v[p[t]];
      assert 0 <= p2[t] < |v|;
      assert s2[t] == v[p[t]];
      assert v[p2[t]] == v[p[t]];
      assert s2[t] == v[p2[t]];
    }
  }
}

lemma {:vcs_split_on_every_assert} selection_prefix_sorted(sorted: seq<int>, s2: seq<int>, i: int, minIdx: int)
  requires 0 <= i <= minIdx < |sorted|
  requires |s2| == |sorted|
  requires s2[i] == sorted[minIdx]
  requires forall a :: 0 <= a < |sorted| && a != i && a != minIdx ==> s2[a] == sorted[a]
  requires forall a, b :: 0 <= a < b < i ==> sorted[a] <= sorted[b]
  requires forall a, b :: 0 <= a < i && i <= b < |sorted| ==> sorted[a] <= sorted[b]
  ensures forall a, b :: 0 <= a < b < i + 1 ==> s2[a] <= s2[b]
{
  forall a, b | 0 <= a < b < i + 1
    ensures s2[a] <= s2[b]
  {
    if b < i {
      assert 0 <= a < b < i;
      assert a != i && b != i;
      assert a != minIdx && b != minIdx;
      assert s2[a] == sorted[a];
      assert s2[b] == sorted[b];
      assert sorted[a] <= sorted[b];
    } else {
      assert b == i;
      assert 0 <= a < i;
      assert a != i && a != minIdx;
      assert s2[a] == sorted[a];
      assert s2[b] == sorted[minIdx];
      assert 0 <= a < i && i <= minIdx < |sorted|;
      assert sorted[a] <= sorted[minIdx];
    }
  }
}

lemma {:vcs_split_on_every_assert} selection_prefix_le_suffix(sorted: seq<int>, s2: seq<int>, i: int, minIdx: int)
  requires 0 <= i <= minIdx < |sorted|
  requires |s2| == |sorted|
  requires s2[i] == sorted[minIdx]
  requires s2[minIdx] == sorted[i]
  requires forall a :: 0 <= a < |sorted| && a != i && a != minIdx ==> s2[a] == sorted[a]
  requires forall a, b :: 0 <= a < i && i <= b < |sorted| ==> sorted[a] <= sorted[b]
  requires forall t :: i <= t < |sorted| ==> sorted[minIdx] <= sorted[t]
  ensures forall a, b :: 0 <= a < i + 1 && i + 1 <= b < |sorted| ==> s2[a] <= s2[b]
{
  var n := |sorted|;
  forall a, b | 0 <= a < i + 1 && i + 1 <= b < n
    ensures s2[a] <= s2[b]
  {
    if b == minIdx {
      assert s2[b] == sorted[i];
    } else {
      assert b != i && b != minIdx;
      assert s2[b] == sorted[b];
    }
    if a < i {
      assert a != i && a != minIdx;
      assert s2[a] == sorted[a];
      if b == minIdx {
        assert s2[b] == sorted[i];
        assert 0 <= a < i && i <= i < n;
        assert sorted[a] <= sorted[i];
      } else {
        assert s2[b] == sorted[b];
        assert 0 <= a < i && i <= b < n;
        assert sorted[a] <= sorted[b];
      }
    } else {
      assert a == i;
      assert s2[a] == sorted[minIdx];
      if b == minIdx {
        assert s2[b] == sorted[i];
        assert i <= i < n;
        assert sorted[minIdx] <= sorted[i];
      } else {
        assert s2[b] == sorted[b];
        assert i <= b < n;
        assert sorted[minIdx] <= sorted[b];
      }
    }
  }
}

lemma min_update(sorted: seq<int>, i: int, j: int, minIdx: int)
  requires 0 <= i <= minIdx < j < |sorted|
  requires forall u :: i <= u < j ==> sorted[minIdx] <= sorted[u]
  requires sorted[j] < sorted[minIdx]
  ensures forall u :: i <= u < j + 1 ==> sorted[j] <= sorted[u]
{
  forall u | i <= u < j + 1
    ensures sorted[j] <= sorted[u]
  {
    if u < j {
      assert sorted[minIdx] <= sorted[u];
      assert sorted[j] < sorted[minIdx];
      assert sorted[j] <= sorted[u];
    } else {
      assert u == j;
      assert sorted[j] <= sorted[u];
    }
  }
}

lemma min_keep(sorted: seq<int>, i: int, j: int, minIdx: int)
  requires 0 <= i <= minIdx < j < |sorted|
  requires forall u :: i <= u < j ==> sorted[minIdx] <= sorted[u]
  requires sorted[minIdx] <= sorted[j]
  ensures forall u :: i <= u < j + 1 ==> sorted[minIdx] <= sorted[u]
{
  forall u | i <= u < j + 1
    ensures sorted[minIdx] <= sorted[u]
  {
    if u < j {
      assert sorted[minIdx] <= sorted[u];
    } else {
      assert u == j;
      assert sorted[minIdx] <= sorted[j];
    }
  }
}

lemma establish_sorted(s: seq<int>)
  requires forall a, b :: 0 <= a < b < |s| ==> s[a] <= s[b]
  ensures is_sorted(s)
{
  forall a, b | 0 <= a < b < |s|
    ensures s[a] <= s[b]
  {
    assert s[a] <= s[b];
  }
}

lemma {:vcs_split_on_every_assert} perm_rename(p: seq<int>, n: int, m: int)
  requires n == m
  requires is_valid_index_permutation(p, n)
  ensures is_valid_index_permutation(p, m)
{
  assert |p| == n;
  assert |p| == m;
  assert forall i {:trigger p[i]} :: 0 <= i < n ==> 0 <= p[i] < n;
  assert forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j];

  forall i {:trigger p[i]} | 0 <= i < m
    ensures 0 <= p[i] < m
  {
    assert 0 <= i < n;
    assert 0 <= p[i] < n;
    assert 0 <= p[i] < m;
  }

  forall i, j {:trigger p[i], p[j]} | 0 <= i < j < m
    ensures p[i] != p[j]
  {
    assert 0 <= i < j < n;
    assert p[i] != p[j];
  }

  assert forall aa {:trigger p[aa]} :: 0 <= aa < m ==> 0 <= p[aa] < m;
  assert forall aa, bb {:trigger p[aa], p[bb]} :: 0 <= aa < bb < m ==> p[aa] != p[bb];
  assemble_valid(p, m);
}

lemma prove_permutation(v1: seq<int>, v2: seq<int>, p: seq<int>)
  requires is_valid_index_permutation(p, |v1|)
  requires |v1| == |v2|
  requires forall i {:trigger p[i]} :: 0 <= i < |v1| ==> 0 <= p[i] < |v1| && v2[i] == v1[p[i]]
  ensures is_permutation(v1, v2)
{
  forall i {:trigger p[i]} | 0 <= i < |v1|
    ensures v2[i] == v1[p[i]]
  {
    index_in_range(p, |v1|, i);
    assert 0 <= p[i] < |v1|;
    assert 0 <= p[i] < |v1| && v2[i] == v1[p[i]];
  }
  assert is_valid_index_permutation(p, |v1|);
  assert |v1| == |v2|;
  assert forall i {:trigger p[i]} :: 0 <= i < |v1| ==> v2[i] == v1[p[i]];
}

lemma prove_kth(s: seq<int>, k: int, val: int, sorted_s: seq<int>)
  requires |sorted_s| == |s|
  requires 0 <= k < |s|
  requires is_permutation(s, sorted_s)
  requires is_sorted(sorted_s)
  requires sorted_s[k] == val
  ensures is_kth_smallest(s, k, val)
{
  assert is_permutation(s, sorted_s);
  assert is_sorted(sorted_s);
  assert 0 <= k < |s|;
  assert sorted_s[k] == val;
}

lemma append_identity(p: seq<int>, t: int)
  requires 0 <= t && |p| == t
  requires forall i :: 0 <= i < t ==> p[i] == i
  ensures |p + [t]| == t + 1
  ensures forall i :: 0 <= i < t + 1 ==> (p + [t])[i] == i
{
  var q := p + [t];
  assert |q| == |p| + 1 == t + 1;
  forall i | 0 <= i < |q|
    ensures q[i] == i
  {
    if i < |p| {
      assert q[i] == p[i];
      assert p[i] == i;
    } else {
      assert i == |p| == t;
      assert q[i] == t;
    }
  }
  assert q == p + [t];
  assert forall i :: 0 <= i < t + 1 ==> q[i] == i;
}

lemma identity_perm(p: seq<int>, n: int)
  requires |p| == n
  requires forall i :: 0 <= i < n ==> p[i] == i
  ensures is_valid_index_permutation(p, n)
{
  forall i {:trigger p[i]} | 0 <= i < n
    ensures 0 <= p[i] < n
  {
    assert p[i] == i;
  }
  forall i, j {:trigger p[i], p[j]} | 0 <= i < j < n
    ensures p[i] != p[j]
  {
    assert p[i] == i;
    assert p[j] == j;
  }
  assemble_valid(p, n);
}

lemma identity_mapping(v: seq<int>, p: seq<int>)
  requires |p| == |v|
  requires forall i :: 0 <= i < |v| ==> p[i] == i
  ensures forall i {:trigger p[i]} :: 0 <= i < |v| ==> v[i] == v[p[i]]
{
  forall i | 0 <= i < |v|
    ensures v[i] == v[p[i]]
  {
    assert p[i] == i;
  }
}

method {:vcs_split_on_every_assert} find_min(sorted: seq<int>, start: int) returns (minIdx: int)
  requires 0 <= start < |sorted|
  ensures start <= minIdx < |sorted|
  ensures forall t :: start <= t < |sorted| ==> sorted[minIdx] <= sorted[t]
{
  minIdx := start;
  var j := start + 1;
  while j < |sorted|
    invariant start <= minIdx < j <= |sorted|
    invariant forall t :: start <= t < j ==> sorted[minIdx] <= sorted[t]
    decreases |sorted| - j
  {
    if sorted[j] < sorted[minIdx] {
      min_update(sorted, start, j, minIdx);
      minIdx := j;
      assert forall t :: start <= t < j + 1 ==> sorted[minIdx] <= sorted[t];
    } else {
      assert sorted[minIdx] <= sorted[j];
      min_keep(sorted, start, j, minIdx);
      assert forall t :: start <= t < j + 1 ==> sorted[minIdx] <= sorted[t];
    }
    j := j + 1;
  }
  assert j == |sorted|;
  assert start <= minIdx < |sorted|;
}

method {:vcs_split_on_every_assert} quick_select(v: seq<int>, k: int) returns (v_new: seq<int>, res: int)
  requires 0 <= k < |v|
  ensures
    // 1. Data Integrity: The array remains a valid permutation of the input
    is_permutation(v, v_new)
  ensures
    // 2. Correctness: The return value is truly the k-th smallest element
    is_kth_smallest(v, k, res)
{
  var n := |v|;
  var sorted := v;
  ghost var p: seq<int> := [];
  var c := 0;
  while c < n
    invariant 0 <= c <= n
    invariant |p| == c
    invariant forall i :: 0 <= i < c ==> p[i] == i
    decreases n - c
  {
    ghost var pNext := p + [c];
    append_identity(p, c);
    assert pNext == p + [c];
    assert |pNext| == c + 1;
    assert forall i :: 0 <= i < c + 1 ==> pNext[i] == i;
    p := pNext;
    c := c + 1;
  }
  assert c == n;
  assert |p| == n;
  assert forall i :: 0 <= i < n ==> p[i] == i;
  identity_perm(p, n);
  identity_mapping(v, p);
  assert sorted == v;

  forall uu {:trigger p[uu]} | 0 <= uu < n
    ensures 0 <= p[uu] < n && sorted[uu] == v[p[uu]]
  {
    index_in_range(p, n, uu);
    assert 0 <= p[uu] < n;
    assert v[uu] == v[p[uu]];
    assert sorted[uu] == v[uu];
    assert sorted[uu] == v[p[uu]];
  }

  var i := 0;
  assert forall a, b :: 0 <= a < b < i ==> sorted[a] <= sorted[b];
  assert forall a, b :: 0 <= a < i && i <= b < n ==> sorted[a] <= sorted[b];

  while i < n
    invariant 0 <= i <= n
    invariant |sorted| == n
    invariant |p| == n
    invariant is_valid_index_permutation(p, n)
    invariant forall t {:trigger p[t]} :: 0 <= t < n ==> 0 <= p[t] < n && sorted[t] == v[p[t]]
    invariant forall a, b :: 0 <= a < b < i ==> sorted[a] <= sorted[b]
    invariant forall a, b :: 0 <= a < i && i <= b < n ==> sorted[a] <= sorted[b]
    decreases n - i
  {
    var minIdx := find_min(sorted, i);
    assert 0 <= i <= minIdx < n;
    assert forall t :: i <= t < n ==> sorted[minIdx] <= sorted[t];

    var s1 := sorted[i := sorted[minIdx]];
    var sorted2 := s1[minIdx := sorted[i]];
    assert s1 == sorted[i := sorted[minIdx]];
    assert sorted2 == s1[minIdx := sorted[i]];
    assert sorted2 == (sorted[i := sorted[minIdx]])[minIdx := sorted[i]];
    update_twice_spec(sorted, i, minIdx, sorted2);

    ghost var p1 := p[i := p[minIdx]];
    ghost var p2 := p1[minIdx := p[i]];
    assert p1 == p[i := p[minIdx]];
    assert p2 == p1[minIdx := p[i]];
    assert p2 == (p[i := p[minIdx]])[minIdx := p[i]];
    update_twice_spec(p, i, minIdx, p2);

    assert |sorted2| == |sorted| == n;
    assert |p2| == |p| == n;
    assert sorted2[i] == sorted[minIdx];
    assert sorted2[minIdx] == sorted[i];
    assert p2[i] == p[minIdx];
    assert p2[minIdx] == p[i];

    assert n == |v|;
    forall t {:trigger p[t]} | 0 <= t < |v|
      ensures 0 <= p[t] < |v| && sorted[t] == v[p[t]]
    {
      assert 0 <= t < n;
      assert 0 <= p[t] < n && sorted[t] == v[p[t]];
      assert 0 <= p[t] < |v|;
    }

    mapping_preserved(v, sorted, p, sorted2, p2, i, minIdx);
