    var i := 0;
    while i <= |haystack| - |needle|
        invariant 0 <= i <= |haystack| - |needle| + 1
        invariant forall k :: 0 <= k < |indices| ==> 0 <= indices[k] < i
        invariant forall k :: 0 <= k < |indices| ==> matches_at(haystack, needle, indices[k])
        invariant forall p :: 0 <= p < i && matches_at(haystack, needle, p) ==>
            exists k :: 0 <= k < |indices| && indices[k] == p
        decreases |haystack| - |needle| + 1 - i
