    0
  else if n == 1 then
    nums[0]
  else if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1] then
    maxRob(nums, n - 1)
  else
    maxRob(nums, n - 2) + nums[n - 1]
}

ghost function optPlan(nums: seq<int>, n: int): seq<int>
  requires 0 <= n <= |nums|
  decreases n
{
  if n == 0 then
    []
  else if n == 1 then
    [0]
  else if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1] then
    optPlan(nums, n - 1)
  else
    optPlan(nums, n - 2) + [n - 1]
}

lemma maxRob_rec(nums: seq<int>, n: int)
  requires 0 <= n <= |nums|
  ensures n == 0 ==> maxRob(nums, n) == 0
  ensures n == 1 ==> maxRob(nums, n) == nums[0]
  ensures n >= 2 ==>
    maxRob(nums, n) == (if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1]
                        then maxRob(nums, n - 1)
                        else maxRob(nums, n - 2) + nums[n - 1])
{
  if n == 0 {
    assert maxRob(nums, n) == 0;
  } else if n == 1 {
    assert maxRob(nums, n) == nums[0];
  } else {
    assert maxRob(nums, n) == (if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1]
                                then maxRob(nums, n - 1)
                                else maxRob(nums, n - 2) + nums[n - 1]);
  }
}

lemma optPlan_rec(nums: seq<int>, n: int)
  requires 0 <= n <= |nums|
  ensures n == 0 ==> optPlan(nums, n) == []
  ensures n == 1 ==> optPlan(nums, n) == [0]
  ensures n >= 2 ==>
    (if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1]
     then optPlan(nums, n) == optPlan(nums, n - 1)
     else optPlan(nums, n) == optPlan(nums, n - 2) + [n - 1])
{
  if n == 0 {
    assert optPlan(nums, n) == [];
  } else if n == 1 {
    assert optPlan(nums, n) == [0];
  } else {
    if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1] {
      assert optPlan(nums, n) == optPlan(nums, n - 1);
    } else {
      assert optPlan(nums, n) == optPlan(nums, n - 2) + [n - 1];
    }
  }
}

lemma maxRob_nonneg(nums: seq<int>, n: int)
  requires 0 <= n <= |nums|
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  ensures maxRob(nums, n) >= 0
  decreases n
{
  maxRob_rec(nums, n);
  if n == 0 {
  } else if n == 1 {
    assert 0 <= 0 < |nums|;
    assert nums[0] >= 0;
  } else {
    maxRob_nonneg(nums, n - 1);
    maxRob_nonneg(nums, n - 2);
    assert 0 <= n - 1 < |nums|;
    assert nums[n - 1] >= 0;
    var skip := maxRob(nums, n - 1);
    var take := maxRob(nums, n - 2) + nums[n - 1];
    assert maxRob(nums, n) == if skip >= take then skip else take;
    if skip >= take {
      assert maxRob(nums, n) == skip;
    } else {
      assert take >= 0;
      assert maxRob(nums, n) == take;
    }
  }
}

lemma maxRob_mono_step(nums: seq<int>, n: int)
  requires 2 <= n <= |nums|
  ensures maxRob(nums, n) >= maxRob(nums, n - 1)
  ensures maxRob(nums, n) >= maxRob(nums, n - 2) + nums[n - 1]
{
  maxRob_rec(nums, n);
  var skip := maxRob(nums, n - 1);
  var take := maxRob(nums, n - 2) + nums[n - 1];
  assert maxRob(nums, n) == if skip >= take then skip else take;
  if skip >= take {
    assert maxRob(nums, n) == skip;
    assert maxRob(nums, n) >= take;
  } else {
    assert maxRob(nums, n) == take;
    assert take > skip;
    assert maxRob(nums, n) >= skip;
  }
}

lemma total_loot_cons(houses: seq<int>, nums: seq<int>)
  requires |houses| >= 1
  requires 0 <= houses[0] < |nums|
  ensures total_loot(houses, nums) == nums[houses[0]] + total_loot(houses[1..], nums)
{
  assert total_loot(houses, nums) == nums[houses[0]] + total_loot(houses[1..], nums);
}

lemma split_last(s: seq<int>)
  requires |s| >= 1
  ensures s == s[..|s| - 1] + [s[|s| - 1]]
{
  var pref := s[..|s| - 1];
  var last := s[|s| - 1];
  var t := pref + [last];
  assert |t| == |s|;
  forall i: int | 0 <= i < |s|
    ensures s[i] == t[i]
  {
    if i < |pref| {
      assert t[i] == pref[i];
      assert pref[i] == s[i];
    } else {
      assert i == |pref|;
      assert t[i] == last;
      assert s[i] == last;
    }
  }
  assert s == t;
}

lemma append_drop_first(prefix: seq<int>, h: int)
  requires |prefix| >= 1
  ensures (prefix + [h])[0] == prefix[0]
  ensures (prefix + [h])[1..] == prefix[1..] + [h]
{
  var s := prefix + [h];
  var L := s[1..];
  var R := prefix[1..] + [h];
  assert s[0] == prefix[0];
  assert |s| == |prefix| + 1;
  assert |L| == |prefix|;
  assert |prefix[1..]| == |prefix| - 1;
  assert |R| == |prefix|;
  forall i: int | 0 <= i < |L|
    ensures L[i] == R[i]
  {
    assert L[i] == s[i + 1];
    if i + 1 < |prefix| {
      assert s[i + 1] == prefix[i + 1];
      assert R[i] == prefix[1..][i];
      assert prefix[1..][i] == prefix[i + 1];
    } else {
      assert i + 1 == |prefix|;
      assert s[i + 1] == h;
      assert i == |prefix| - 1;
      assert R[i] == h;
    }
  }
  assert L == R;
}

lemma total_loot_append(prefix: seq<int>, h: int, nums: seq<int>)
  requires forall i: int :: 0 <= i < |prefix| ==> 0 <= prefix[i] < |nums|
  requires 0 <= h < |nums|
  ensures total_loot(prefix + [h], nums) == total_loot(prefix, nums) + nums[h]
  decreases |prefix|
{
  if |prefix| == 0 {
    assert prefix + [h] == [h];
    total_loot_cons([h], nums);
    assert [h][1..] == [];
    assert total_loot([], nums) == 0;
    assert total_loot(prefix, nums) == 0;
  } else {
    append_drop_first(prefix, h);
    var combined := prefix + [h];
    var tail := prefix[1..];
    assert combined[0] == prefix[0];
    assert combined[1..] == tail + [h];
    assert 0 <= prefix[0] < |nums|;
    total_loot_cons(combined, nums);
    forall i: int | 0 <= i < |tail|
      ensures 0 <= tail[i] < |nums|
    {
      assert 0 <= i + 1 < |prefix|;
      assert tail[i] == prefix[i + 1];
      assert 0 <= prefix[i + 1] < |nums|;
    }
    total_loot_append(tail, h, nums);
    total_loot_cons(prefix, nums);
    assert total_loot(combined[1..], nums) == total_loot(tail + [h], nums);
    assert total_loot(combined, nums) == nums[prefix[0]] + total_loot(tail + [h], nums);
    assert total_loot(tail + [h], nums) == total_loot(tail, nums) + nums[h];
    assert total_loot(prefix, nums) == nums[prefix[0]] + total_loot(tail, nums);
  }
}

lemma loot_split_last(houses: seq<int>, nums: seq<int>)
  requires |houses| >= 1
  requires forall i: int :: 0 <= i < |houses| ==> 0 <= houses[i] < |nums|
  ensures total_loot(houses, nums) ==
          total_loot(houses[..|houses| - 1], nums) + nums[houses[|houses| - 1]]
{
  var rest := houses[..|houses| - 1];
  var last := houses[|houses| - 1];
  split_last(houses);
  assert houses == rest + [last];
  forall k: int | 0 <= k < |rest|
    ensures 0 <= rest[k] < |nums|
  {
    assert rest[k] == houses[k];
  }
  total_loot_append(rest, last, nums);
  assert total_loot(houses, nums) == total_loot(rest, nums) + nums[last];
}

lemma singleton_eq(s: seq<int>, v: int)
  requires |s| == 1
  requires s[0] == v
  ensures s == [v]
{
  var t := [v];
  assert |s| == |t|;
  forall i: int | 0 <= i < |s|
    ensures s[i] == t[i]
  {
    assert i == 0;
    assert t[0] == v;
  }
  assert s == t;
}

lemma elem_le_last(houses: seq<int>, k: int)
  requires 0 <= k < |houses|
  requires forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2
  ensures houses[k] <= houses[|houses| - 1]
  decreases |houses| - k
{
  if k < |houses| - 1 {
    assert houses[k + 1] >= houses[k] + 2;
    assert houses[k + 1] >= houses[k];
    assert houses[k] <= houses[k + 1];
    assert 0 <= k + 1 < |houses|;
    elem_le_last(houses, k + 1);
    assert houses[k + 1] <= houses[|houses| - 1];
  }
}

lemma elem_below_last_by_two(houses: seq<int>, k: int)
  requires 0 <= k < |houses| - 1
  requires forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2
  ensures houses[k] <= houses[|houses| - 1] - 2
  decreases |houses| - k
{
  assert houses[k + 1] >= houses[k] + 2;
  assert houses[k] <= houses[k + 1] - 2;
  if k + 1 == |houses| - 1 {
    assert houses[k + 1] == houses[|houses| - 1];
    assert houses[k] <= houses[|houses| - 1] - 2;
  } else {
    assert k < |houses| - 1;
    assert k + 1 <= |houses| - 1;
    assert k + 1 != |houses| - 1;
    assert k + 1 < |houses| - 1;
    assert 0 <= k + 1;
    elem_below_last_by_two(houses, k + 1);
    assert houses[k + 1] <= houses[|houses| - 1] - 2;
    assert houses[k] <= houses[|houses| - 1] - 2;
  }
}

lemma still_valid_smaller_bound(houses: seq<int>, oldBound: int, newBound: int)
  requires is_valid_robbery(houses, oldBound)
  requires newBound >= 0
  requires forall k: int :: 0 <= k < |houses| ==> houses[k] < newBound
  ensures is_valid_robbery(houses, newBound)
{
  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < newBound
  {
    assert 0 <= houses[k] < oldBound;
    assert houses[k] < newBound;
  }
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;
}

lemma still_valid_larger_bound(houses: seq<int>, oldBound: int, newBound: int)
  requires is_valid_robbery(houses, oldBound)
  requires oldBound <= newBound
  ensures is_valid_robbery(houses, newBound)
{
  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < newBound
  {
    assert 0 <= houses[k] < oldBound;
    assert oldBound <= newBound;
  }
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;
}

lemma prefix_before_last(houses: seq<int>, n: int)
  requires |houses| >= 1
  requires n >= 2
  requires is_valid_robbery(houses, n)
  requires houses[|houses| - 1] == n - 1
  ensures is_valid_robbery(houses[..|houses| - 1], n - 2)
{
  var rest := houses[..|houses| - 1];
  var last := houses[|houses| - 1];
  assert last == n - 1;
  assert forall i: int :: 0 <= i < |houses| ==> 0 <= houses[i] < n;
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;

  forall k: int | 0 <= k < |rest|
    ensures 0 <= rest[k] < n - 2
  {
    assert rest[k] == houses[k];
    assert 0 <= houses[k] < n;
    elem_below_last_by_two(houses, k);
    assert houses[k] <= last - 2;
    assert last - 2 == n - 3;
    assert houses[k] <= n - 3;
    assert houses[k] < n - 2;
  }

  forall k: int | 0 <= k < |rest| - 1
    ensures rest[k + 1] >= rest[k] + 2
  {
    assert rest[k] == houses[k];
    assert rest[k + 1] == houses[k + 1];
    assert houses[k + 1] >= houses[k] + 2;
  }
}

lemma append_house_ok(prev: seq<int>, n: int)
  requires n >= 2
  requires is_valid_robbery(prev, n - 2)
  ensures is_valid_robbery(prev + [n - 1], n)
{
  var plan := prev + [n - 1];
  assert |plan| == |prev| + 1;
  assert forall i: int :: 0 <= i < |prev| ==> 0 <= prev[i] < n - 2;
  assert forall i: int :: 0 <= i < |prev| - 1 ==> prev[i + 1] >= prev[i] + 2;

  forall i: int | 0 <= i < |prev|
    ensures plan[i] == prev[i]
  {
  }
  assert plan[|prev|] == n - 1;

  forall i: int | 0 <= i < |plan|
    ensures 0 <= plan[i] < n
  {
    if i < |prev| {
      assert plan[i] == prev[i];
      assert 0 <= prev[i] < n - 2;
      assert prev[i] < n;
    } else {
      assert i == |prev|;
      assert plan[i] == n - 1;
      assert 0 <= n - 1 < n;
    }
  }

  forall i: int | 0 <= i < |plan| - 1
    ensures plan[i + 1] >= plan[i] + 2
  {
    if i < |prev| - 1 {
      assert plan[i] == prev[i];
      assert plan[i + 1] == prev[i + 1];
      assert prev[i + 1] >= prev[i] + 2;
    } else {
      assert i < |prev|;
      assert i >= |prev| - 1;
      assert |prev| >= 1;
      assert i == |prev| - 1;
      assert plan[i] == prev[i];
      assert plan[i + 1] == n - 1;
      assert 0 <= prev[i] < n - 2;
      assert prev[i] <= n - 3;
      assert prev[i] + 2 <= n - 1;
    }
  }
}

lemma rob_upper(nums: seq<int>, n: int, houses: seq<int>)
  requires 0 <= n <= |nums|
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  requires is_valid_robbery(houses, n)
  ensures total_loot(houses, nums) <= maxRob(nums, n)
  decreases n
{
  if |houses| == 0 {
    assert total_loot(houses, nums) == 0;
    maxRob_nonneg(nums, n);
  } else {
    assert forall i: int :: 0 <= i < |houses| ==> 0 <= houses[i] < n;
    assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;
    var last := houses[|houses| - 1];
    assert 0 <= last < n;
    if n == 0 {
      assert false;
    } else if last == n - 1 {
      if n == 1 {
        if |houses| >= 2 {
          elem_below_last_by_two(houses, 0);
          assert houses[0] <= last - 2;
          assert last == 0;
          assert houses[0] <= -2;
          assert 0 <= houses[0];
          assert false;
        }
        assert |houses| == 1;
        assert houses[0] == 0;
        singleton_eq(houses, 0);
        assert houses == [0];
        assert 0 <= 0 < |nums|;
        total_loot_cons([0], nums);
        assert [0][1..] == [];
        assert total_loot([], nums) == 0;
        assert total_loot(houses, nums) == nums[0];
        maxRob_rec(nums, 1);
        assert maxRob(nums, 1) == nums[0];
      } else {
        assert n >= 2;
        forall k: int | 0 <= k < |houses|
          ensures 0 <= houses[k] < |nums|
        {
          assert 0 <= houses[k] < n;
          assert n <= |nums|;
        }
        var rest := houses[..|houses| - 1];
        loot_split_last(houses, nums);
        assert total_loot(houses, nums) == total_loot(rest, nums) + nums[last];
        assert nums[last] == nums[n - 1];
        prefix_before_last(houses, n);
        assert is_valid_robbery(rest, n - 2);
        assert 0 <= n - 2 <= |nums|;
        rob_upper(nums, n - 2, rest);
        assert total_loot(rest, nums) <= maxRob(nums, n - 2);
        maxRob_mono_step(nums, n);
        assert maxRob(nums, n) >= maxRob(nums, n - 2) + nums[n - 1];
        assert total_loot(houses, nums) <= maxRob(nums, n - 2) + nums[n - 1];
      }
    } else {
      assert last < n - 1;
      assert last <= n - 2;
      assert n >= 2;
      forall k: int | 0 <= k < |houses|
        ensures houses[k] < n - 1
      {
        elem_le_last(houses, k);
        assert houses[k] <= last;
        assert last <= n - 2;
        assert houses[k] <= n - 2;
        assert houses[k] < n - 1;
      }
      assert n - 1 >= 0;
      still_valid_smaller_bound(houses, n, n - 1);
      assert 0 <= n - 1 <= |nums|;
      rob_upper(nums, n - 1, houses);
      maxRob_mono_step(nums, n);
      assert total_loot(houses, nums) <= maxRob(nums, n - 1);
      assert maxRob(nums, n) >= maxRob(nums, n - 1);
    }
  }
}

lemma optPlan_correct(nums: seq<int>, n: int)
  requires 0 <= n <= |nums|
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  ensures is_valid_robbery(optPlan(nums, n), n)
  ensures total_loot(optPlan(nums, n), nums) == maxRob(nums, n)
  decreases n
{
  if n == 0 {
    optPlan_rec(nums, 0);
    maxRob_rec(nums, 0);
    assert optPlan(nums, 0) == [];
    assert total_loot([], nums) == 0;
    assert maxRob(nums, 0) == 0;
    assert is_valid_robbery([], 0);
  } else if n == 1 {
    optPlan_rec(nums, 1);
    maxRob_rec(nums, 1);
    assert optPlan(nums, 1) == [0];
    assert |nums| >= 1;
    assert 0 <= 0 < |nums|;
    total_loot_cons([0], nums);
    assert [0][1..] == [];
    assert total_loot([], nums) == 0;
    assert total_loot([0], nums) == nums[0];
    assert maxRob(nums, 1) == nums[0];
    assert is_valid_robbery([0], 1);
  } else {
    optPlan_rec(nums, n);
    maxRob_rec(nums, n);
    if maxRob(nums, n - 1) >= maxRob(nums, n - 2) + nums[n - 1] {
      optPlan_correct(nums, n - 1);
      var p := optPlan(nums, n - 1);
      assert optPlan(nums, n) == p;
      assert is_valid_robbery(p, n - 1);
      still_valid_larger_bound(p, n - 1, n);
      assert is_valid_robbery(p, n);
      assert maxRob(nums, n) == maxRob(nums, n - 1);
      assert total_loot(p, nums) == maxRob(nums, n - 1);
      assert total_loot(optPlan(nums, n), nums) == maxRob(nums, n);
    } else {
      optPlan_correct(nums, n - 2);
      var prev := optPlan(nums, n - 2);
      assert optPlan(nums, n) == prev + [n - 1];
      assert is_valid_robbery(prev, n - 2);
      append_house_ok(prev, n);
      assert is_valid_robbery(prev + [n - 1], n);
      forall i: int | 0 <= i < |prev|
        ensures 0 <= prev[i] < |nums|
      {
        assert 0 <= prev[i] < n - 2;
        assert n - 2 <= |nums|;
        assert prev[i] < |nums|;
      }
      assert 0 <= n - 1 < |nums|;
      total_loot_append(prev, n - 1, nums);
      assert total_loot(prev, nums) == maxRob(nums, n - 2);
      assert maxRob(nums, n) == maxRob(nums, n - 2) + nums[n - 1];
      assert total_loot(optPlan(nums, n), nums) == maxRob(nums, n);
    }
  }
}

lemma rob_spec(nums: seq<int>, max_amount: int)
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  requires max_amount == maxRob(nums, |nums|)
  ensures max_amount >= 0
  ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|)
          ==> total_loot(houses, nums) <= max_amount)
  ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|)
          && total_loot(houses, nums) == max_amount)
{
  maxRob_nonneg(nums, |nums|);
  assert maxRob(nums, |nums|) >= 0;

  forall houses: seq<int> | is_valid_robbery(houses, |nums|)
    ensures total_loot(houses, nums) <= max_amount
  {
    rob_upper(nums, |nums|, houses);
    assert total_loot(houses, nums) <= maxRob(nums, |nums|);
  }

  var houses := optPlan(nums, |nums|);
  optPlan_correct(nums, |nums|);
  assert is_valid_robbery(houses, |nums|);
  assert total_loot(houses, nums) == maxRob(nums, |nums|);
  assert total_loot(houses, nums) == max_amount;
}

method rob(nums: seq<int>) returns (max_amount: int)
  requires |nums| <= 100
  // Constraints matching Verus u64
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
  requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
  ensures max_amount >= 0
  // 1. Upper Bound
  ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|)
          ==> total_loot(houses, nums) <= max_amount)
  // 2. Existence
  ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|)
          && total_loot(houses, nums) == max_amount)
{
  if |nums| == 0 {
    max_amount := 0;
    maxRob_rec(nums, 0);
    assert maxRob(nums, 0) == 0;
    assert max_amount == maxRob(nums, |nums|);
  } else {
    var i: int := 1;
    var best: int := nums[0];
    var prev: int := 0;
    maxRob_rec(nums, 0);
    maxRob_rec(nums, 1);
    assert maxRob(nums, 0) == 0;
    assert maxRob(nums, 1) == nums[0];
    assert prev == maxRob(nums, 0);
    assert best == maxRob(nums, 1);

    while i < |nums|
      invariant 1 <= i <= |nums|
      invariant best == maxRob(nums, i)
      invariant prev == maxRob(nums, i - 1)
      decreases |nums| - i
    {
      assert 0 <= i - 1;
      assert 0 <= i + 1 <= |nums|;
      maxRob_rec(nums, i + 1);
      assert (i + 1) - 1 == i;
      assert (i + 1) - 2 == i - 1;
      assert maxRob(nums, (i + 1) - 1) == maxRob(nums, i);
      assert maxRob(nums, (i + 1) - 2) == maxRob(nums, i - 1);
      assert nums[(i + 1) - 1] == nums[i];
      assert maxRob(nums, i + 1) ==
        (if maxRob(nums, i) >= maxRob(nums, i - 1) + nums[i]
