    ensures 0 <= SwapIndex(a, b, k) < n
{
    SwapIndexCases(a, b, k);
    if k == a {
        assert SwapIndex(a, b, k) == b;
        assert 0 <= b < n;
    } else if k == b {
        assert k != a;
        assert SwapIndex(a, b, k) == a;
        assert 0 <= a < n;
    } else {
        assert k != a && k != b;
        assert SwapIndex(a, b, k) == k;
        assert 0 <= k < n;
    }
    assert 0 <= SwapIndex(a, b, k) < n;
}

lemma {:vcs_split_on_every_assert} SwapIndexInj(a: int, b: int, i: int, j: int)
    requires i != j
    ensures SwapIndex(a, b, i) != SwapIndex(a, b, j)
{
    SwapIndexCases(a, b, i);
    SwapIndexCases(a, b, j);
    var ri := if i == a then b else if i == b then a else i;
    var rj := if j == a then b else if j == b then a else j;
    assert SwapIndex(a, b, i) == (if i == a then b else if i == b then a else i);
    assert SwapIndex(a, b, j) == (if j == a then b else if j == b then a else j);
    assert ri == (if i == a then b else if i == b then a else i);
    assert rj == (if j == a then b else if j == b then a else j);
    assert SwapIndex(a, b, i) == ri;
    assert SwapIndex(a, b, j) == rj;

    if i == a {
        assert ri == b;
        if a == b {
            assert i == a;
            assert b == a;
            assert b == i;
            assert ri == i;
            assert j != i;
            assert j != a;
            assert j != b;
            assert (if j == a then b else if j == b then a else j) == j;
            assert rj == j;
            assert ri != rj;
        } else if j == b {
            assert a != b;
            assert j == b;
            assert j != a;
            assert ri == b;
            assert (if j == a then b else if j == b then a else j) == a;
            assert rj == a;
            assert ri != rj;
        } else {
            assert a != b;
            assert j != b;
            assert i == a;
            assert j != i;
            assert j != a;
            assert ri == b;
            assert (if j == a then b else if j == b then a else j) == j;
            assert rj == j;
            assert j != b;
            assert ri != rj;
        }
    } else if i == b {
        assert i != a;
        assert a != b;
        assert (if i == a then b else if i == b then a else i) == a;
        assert ri == a;
        if j == a {
            assert (if j == a then b else if j == b then a else j) == b;
            assert rj == b;
            assert a != b;
            assert ri != rj;
        } else {
            assert j != a;
            assert j != i;
            assert i == b;
            assert j != b;
            assert (if j == a then b else if j == b then a else j) == j;
            assert rj == j;
            assert j != a;
            assert ri != rj;
        }
    } else {
        assert i != a && i != b;
        assert (if i == a then b else if i == b then a else i) == i;
        assert ri == i;
        if j == a {
            assert (if j == a then b else if j == b then a else j) == b;
            assert rj == b;
            assert i != b;
            assert ri != rj;
        } else if j == b {
            assert j != a;
            assert (if j == a then b else if j == b then a else j) == a;
            assert rj == a;
            assert i != a;
            assert ri != rj;
        } else {
            assert j != a && j != b;
            assert (if j == a then b else if j == b then a else j) == j;
            assert rj == j;
            assert i != j;
            assert ri != rj;
        }
    }
    assert ri != rj;
    assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
}

lemma {:vcs_split_on_every_assert} SwapPerm(p: seq<int>, n: int, a: int, b: int)
    requires is_valid_index_permutation(p, n)
    requires 0 <= a < n && 0 <= b < n
    ensures is_valid_index_permutation(Swap(p, a, b), n)
{
    var q := Swap(p, a, b);
    assert |p| == n;
    SwapReflects(p, a, b, a);
    assert |q| == n;

    forall i | 0 <= i < n
        ensures 0 <= q[i] < n
    {
        SwapReflects(p, a, b, i);
        SwapIndexInRange(a, b, n, i);
        var r := SwapIndex(a, b, i);
        assert q[i] == p[r];
        assert 0 <= r < n;
        assert 0 <= p[r] < n;
        assert 0 <= q[i] < n;
    }

    forall i, j | 0 <= i < j < n
        ensures q[i] != q[j]
    {
        SwapIndexInj(a, b, i, j);
        SwapIndexInRange(a, b, n, i);
        SwapIndexInRange(a, b, n, j);
        SwapReflects(p, a, b, i);
        SwapReflects(p, a, b, j);
        var ri := SwapIndex(a, b, i);
        var rj := SwapIndex(a, b, j);
        assert ri != rj;
        assert 0 <= ri < n;
        assert 0 <= rj < n;
        assert q[i] == p[ri];
        assert q[j] == p[rj];
        if ri < rj {
            assert p[ri] != p[rj];
        } else {
            assert rj < ri;
            assert p[rj] != p[ri];
        }
        assert q[i] != q[j];
    }

    assert forall i {:trigger q[i]} :: 0 <= i < n ==> 0 <= q[i] < n;
    assert forall i, j {:trigger q[i], q[j]} :: 0 <= i < j < n ==> q[i] != q[j];
    assert is_valid_index_permutation(q, n);
}

lemma {:vcs_split_on_every_assert} SwapWitness(v: seq<int>, w: seq<int>, p: seq<int>, a: int, b: int)
    requires IsWitness(v, w, p)
    requires 0 <= a < |w| && 0 <= b < |w|
    ensures IsWitness(v, Swap(w, a, b), Swap(p, a, b))
{
    assert is_valid_index_permutation(p, |v|);
    assert |v| == |w|;
    assert |p| == |v|;
    assert 0 <= a < |p| && 0 <= b < |p|;
    var w2 := Swap(w, a, b);
    var p2 := Swap(p, a, b);
    SwapReflects(w, a, b, a);
    assert |w2| == |w|;
    assert |v| == |w2|;
    SwapPerm(p, |v|, a, b);
    assert is_valid_index_permutation(p2, |v|);

    forall i | 0 <= i < |v|
        ensures w2[i] == v[p2[i]]
    {
        SwapReflects(w, a, b, i);
        SwapReflects(p, a, b, i);
        SwapIndexInRange(a, b, |v|, i);
        var r := SwapIndex(a, b, i);
        assert 0 <= r < |v|;
        assert w2[i] == w[r];
        assert p2[i] == p[r];
        assert w[r] == v[p[r]];
        assert w2[i] == v[p2[i]];
    }

    assert forall i {:trigger p2[i]} :: 0 <= i < |v| ==> w2[i] == v[p2[i]];
    assert IsWitness(v, w2, p2);
    assert w2 == Swap(w, a, b);
    assert p2 == Swap(p, a, b);
    assert IsWitness(v, Swap(w, a, b), Swap(p, a, b));
}

lemma {:vcs_split_on_every_assert} IdPermProps(n: int, p: seq<int>)
    requires n >= 0
    requires p == seq(n, (i: int) => i)
    ensures |p| == n
    ensures forall k :: 0 <= k < n ==> p[k] == k
    ensures is_valid_index_permutation(p, n)
{
    assert |p| == n;
    forall k | 0 <= k < n
        ensures p[k] == k && 0 <= p[k] < n
    {
        assert seq(n, (i: int) => i)[k] == k;
        assert p[k] == k;
        assert 0 <= p[k] < n;
    }
    forall i, j | 0 <= i < j < n
        ensures p[i] != p[j]
    {
        assert p[i] == i;
        assert p[j] == j;
        assert i != j;
        assert p[i] != p[j];
    }
    assert forall k {:trigger p[k]} :: 0 <= k < n ==> 0 <= p[k] < n;
    assert forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j];
    assert is_valid_index_permutation(p, n);
}

lemma {:vcs_split_on_every_assert} InitWitness(v: seq<int>, p: seq<int>)
    requires p == seq(|v|, (i: int) => i)
    ensures IsWitness(v, v, p)
{
    IdPermProps(|v|, p);
    forall k | 0 <= k < |v|
        ensures v[k] == v[p[k]]
    {
        assert p[k] == k;
        assert v[k] == v[p[k]];
    }
    assert is_valid_index_permutation(p, |v|);
    assert |v| == |v|;
    assert forall i {:trigger p[i]} :: 0 <= i < |v| ==> v[i] == v[p[i]];
    assert IsWitness(v, v, p);
}

lemma {:vcs_split_on_every_assert} UnpackWitness(v1: seq<int>, v2: seq<int>, p: seq<int>)
    requires IsWitness(v1, v2, p)
    ensures is_valid_index_permutation(p, |v1|)
    ensures |v1| == |v2|
    ensures forall i {:trigger p[i]} :: 0 <= i < |v1| ==> v2[i] == v1[p[i]]
{
    assert is_valid_index_permutation(p, |v1|);
    assert |v1| == |v2|;
    assert forall i {:trigger p[i]} :: 0 <= i < |v1| ==> v2[i] == v1[p[i]];
}

lemma {:vcs_split_on_every_assert} WitnessImpliesPerm(v1: seq<int>, v2: seq<int>, p: seq<int>)
    requires IsWitness(v1, v2, p)
    ensures is_permutation(v1, v2)
{
    UnpackWitness(v1, v2, p);
    var q := p;
    assert q == p;
    assert is_valid_index_permutation(q, |v1|);
    assert |v1| == |v2|;
    assert forall i {:trigger q[i]} :: 0 <= i < |v1| ==> v2[i] == v1[q[i]];
}

lemma {:vcs_split_on_every_assert} SortedSliceIndex(s: seq<int>, lo: int, hi: int, x: int, y: int)
    requires 0 <= lo <= x < y < hi <= |s|
    requires is_sorted(s[lo..hi])
    ensures s[x] <= s[y]
{
    var t := s[lo..hi];
    assert |t| == hi - lo;
    assert 0 <= x - lo < y - lo < |t|;
    assert t[x - lo] == s[x];
    assert t[y - lo] == s[y];
    assert is_sorted(t);
    assert t[x - lo] <= t[y - lo];
    assert s[x] <= s[y];
}

lemma {:vcs_split_on_every_assert} ProveSortedSlice(s: seq<int>, lo: int, hi: int)
    requires 0 <= lo <= hi <= |s|
    requires forall x, y :: lo <= x < y < hi ==> s[x] <= s[y]
    ensures is_sorted(s[lo..hi])
{
    var t := s[lo..hi];
    assert |t| == hi - lo;
    forall a, b | 0 <= a < b < |t|
        ensures t[a] <= t[b]
    {
        if |t| == 0 {
            assert b < 0;
            assert 0 <= a;
            assert false;
        } else if |t| == 1 {
            assert b < 1;
            assert a >= 0;
            assert b > a;
            assert b >= a + 1;
            assert b >= 1;
            assert false;
        } else {
            assert |t| >= 2;
            assert 0 <= a < b < |t|;
            assert lo <= lo + a;
            assert lo + a < lo + b;
            assert b < |t|;
            assert |t| == hi - lo;
            assert lo + b < hi;
            assert lo <= lo + a < lo + b < hi;
            assert s[lo + a] <= s[lo + b];
            assert t[a] == s[lo + a];
            assert t[b] == s[lo + b];
            assert t[a] <= t[b];
        }
    }
    assert is_sorted(t);
    assert t == s[lo..hi];
    assert is_sorted(s[lo..hi]);
}

lemma {:vcs_split_on_every_assert} EmptySorted(s: seq<int>)
    ensures is_sorted(s[..0])
{
    var t := s[..0];
    assert |t| == 0;
    forall a, b | 0 <= a < b < |t|
        ensures t[a] <= t[b]
    {
        assert b < 0;
        assert false;
    }
    assert is_sorted(t);
    assert t == s[..0];
    assert is_sorted(s[..0]);
}

lemma {:vcs_split_on_every_assert} SingletonSorted(s: seq<int>, k: int)
    requires 0 <= k < |s|
    ensures is_sorted(s[k..(k + 1)])
{
    var t := s[k..(k + 1)];
    assert |t| == 1;
    forall a, b | 0 <= a < b < |t|
        ensures t[a] <= t[b]
    {
        assert b < 1;
        assert a >= 0;
        assert b > a;
        assert b >= a + 1;
        assert b >= 1;
        assert false;
    }
    assert is_sorted(t);
    assert t == s[k..(k + 1)];
    assert is_sorted(s[k..(k + 1)]);
}

lemma {:vcs_split_on_every_assert} PrefixAtZero(s: seq<int>, hi: int)
    requires 0 <= hi <= |s|
    ensures s[..hi] == s[0..hi]
{
    var a := s[..hi];
    var b := s[0..hi];
    assert |a| == hi;
    assert |b| == hi;
    forall k | 0 <= k < hi
        ensures a[k] == b[k]
    {
        assert a[k] == s[k];
        assert 0 + k == k;
        assert b[k] == s[0 + k];
        assert s[0 + k] == s[k];
        assert a[k] == b[k];
    }
    assert a == b;
    assert s[..hi] == s[0..hi];
}

lemma {:vcs_split_on_every_assert} SortedFull(s: seq<int>)
    requires is_sorted(s[..|s|])
    ensures is_sorted(s)
{
    var t := s[..|s|];
    assert |t| == |s|;
    forall a, b | 0 <= a < b < |s|
        ensures s[a] <= s[b]
    {
        assert t[a] == s[a];
        assert t[b] == s[b];
        assert 0 <= a < b < |t|;
        assert is_sorted(t);
        assert t[a] <= t[b];
        assert s[a] <= s[b];
    }
    assert is_sorted(s);
}

lemma {:vcs_split_on_every_assert} NotGtLe(a: int, b: int)
    requires !(a > b)
    ensures a <= b
{
    if a > b {
        assert false;
    } else if a == b {
        assert a <= b;
    } else {
        assert a < b;
        assert a <= b;
    }
}

lemma {:vcs_split_on_every_assert} BubbleStep(s: seq<int>, j: int, i: int)
    requires 0 < j <= i < |s|
    requires s[j - 1] > s[j]
    requires is_sorted(s[..j])
    requires is_sorted(s[j..(i + 1)])
    requires forall m, n :: 0 <= m < j && j < n <= i ==> s[m] <= s[n]
    ensures is_sorted(Swap(s, j - 1, j)[..(j - 1)])
    ensures is_sorted(Swap(s, j - 1, j)[(j - 1)..(i + 1)])
    ensures forall m, n :: 0 <= m < j - 1 && j - 1 < n <= i ==> Swap(s, j - 1, j)[m] <= Swap(s, j - 1, j)[n]
{
    var lo := j - 1;
    var hi := i + 1;
    assert lo == j - 1;
    assert hi == i + 1;
    assert 0 <= lo < j < |s|;
    assert j <= i;
    assert i + 1 <= |s|;
    assert hi <= |s|;
    assert s[lo] > s[j];
    assert s[j] <= s[lo];

    var w := Swap(s, lo, j);
    SwapReflects(s, lo, j, lo);
    assert |w| == |s|;
    assert w == Swap(s, j - 1, j);

    if lo == 0 {
        EmptySorted(w);
        assert is_sorted(w[..0]);
        assert is_sorted(w[..lo]);
    } else {
        forall x, y | 0 <= x < y < lo
            ensures w[x] <= w[y]
        {
            assert x < lo && y < lo;
            assert x != lo && y != lo;
            assert x != j && y != j;
            SwapReflects(s, lo, j, x);
            SwapReflects(s, lo, j, y);
            SwapIndexCases(lo, j, x);
            SwapIndexCases(lo, j, y);
            assert SwapIndex(lo, j, x) == x;
            assert SwapIndex(lo, j, y) == y;
            assert w[x] == s[x];
            assert w[y] == s[y];
            assert 0 <= x < y < j;
            assert j <= |s|;
            PrefixAtZero(s, j);
            assert s[..j] == s[0..j];
            assert is_sorted(s[0..j]);
            SortedSliceIndex(s, 0, j, x, y);
            assert w[x] <= w[y];
        }
        assert forall x, y :: 0 <= x < y < lo ==> w[x] <= w[y];
        assert 0 <= lo <= |w|;
        ProveSortedSlice(w, 0, lo);
        assert is_sorted(w[..lo]);
    }
    assert is_sorted(w[..(j - 1)]);

    forall c, d | 0 <= c < lo && lo < d <= i
        ensures w[c] <= w[d]
    {
        assert c < lo;
        assert c != lo && c != j;
        SwapReflects(s, lo, j, c);
        SwapIndexCases(lo, j, c);
        assert SwapIndex(lo, j, c) == c;
        assert w[c] == s[c];
        if d == j {
            SwapReflects(s, lo, j, d);
            SwapIndexCases(lo, j, d);
            assert d == j;
            assert d != lo;
            assert SwapIndex(lo, j, d) == lo;
            assert w[d] == s[lo];
            assert 0 <= c < lo < j <= |s|;
            PrefixAtZero(s, j);
            assert is_sorted(s[0..j]);
            SortedSliceIndex(s, 0, j, c, lo);
            assert s[c] <= s[lo];
            assert w[c] <= w[d];
        } else {
            assert d != j;
            assert d > lo;
            assert d >= j;
            assert d != j;
            assert d > j;
            assert d != lo;
            SwapReflects(s, lo, j, d);
            SwapIndexCases(lo, j, d);
            assert SwapIndex(lo, j, d) == d;
            assert w[d] == s[d];
            assert 0 <= c < j;
            assert j < d <= i;
            assert s[c] <= s[d];
            assert w[c] <= w[d];
        }
    }
    assert forall m, n :: 0 <= m < j - 1 && j - 1 < n <= i ==> w[m] <= w[n];

    forall x, y | lo <= x < y < hi
        ensures w[x] <= w[y]
    {
        assert 0 <= x < |w|;
        assert 0 <= y < |w|;
        if x == lo && y == j {
            SwapReflects(s, lo, j, x);
            SwapReflects(s, lo, j, y);
            SwapIndexCases(lo, j, x);
            SwapIndexCases(lo, j, y);
            assert SwapIndex(lo, j, x) == j;
            assert SwapIndex(lo, j, y) == lo;
            assert w[x] == s[j];
            assert w[y] == s[lo];
            assert s[j] <= s[lo];
            assert w[x] <= w[y];
        } else if x == lo {
            assert y != j;
            assert y > lo;
            assert y > j;
            assert y < hi;
            assert y <= i;
            SwapReflects(s, lo, j, x);
            SwapReflects(s, lo, j, y);
            SwapIndexCases(lo, j, x);
            SwapIndexCases(lo, j, y);
            assert x == lo;
            assert SwapIndex(lo, j, x) == j;
            assert w[x] == s[j];
            assert y != lo && y != j;
            assert SwapIndex(lo, j, y) == y;
            assert w[y] == s[y];
            assert j < y < hi;
            assert hi <= |s|;
            SortedSliceIndex(s, j, hi, j, y);
            assert s[j] <= s[y];
            assert w[x] <= w[y];
        } else if x == j {
            assert y > j;
            assert y < hi;
            assert y <= i;
            assert y != lo && y != j;
            SwapReflects(s, lo, j, x);
            SwapReflects(s, lo, j, y);
            SwapIndexCases(lo, j, x);
            SwapIndexCases(lo, j, y);
            assert x == j && x != lo;
            assert SwapIndex(lo, j, x) == lo;
            assert w[x] == s[lo];
            assert SwapIndex(lo, j, y) == y;
            assert w[y] == s[y];
            assert 0 <= lo < j;
            assert j < y <= i;
            assert s[lo] <= s[y];
            assert w[x] <= w[y];
        } else {
            assert x != lo && x != j;
            assert x > lo;
            assert x > j;
            assert x >= j + 1;
            assert y > x;
            assert y != lo && y != j;
            SwapReflects(s, lo, j, x);
            SwapReflects(s, lo, j, y);
            SwapIndexCases(lo, j, x);
            SwapIndexCases(lo, j, y);
            assert SwapIndex(lo, j, x) == x;
            assert SwapIndex(lo, j, y) == y;
            assert w[x] == s[x];
            assert w[y] == s[y];
            assert j <= x < y < hi;
            SortedSliceIndex(s, j, hi, x, y);
            assert w[x] <= w[y];
        }
    }
    assert forall x, y :: lo <= x < y < hi ==> w[x] <= w[y];
    assert 0 <= lo <= hi <= |w|;
    ProveSortedSlice(w, lo, hi);
    assert is_sorted(w[lo..hi]);
    assert is_sorted(w[(j - 1)..(i + 1)]);
    assert forall m, n :: 0 <= m < j - 1 && j - 1 < n <= i ==> Swap(s, j - 1, j)[m] <= Swap(s, j - 1, j)[n];
}

lemma {:vcs_split_on_every_assert} InsertDone(s: seq<int>, j: int, i: int)
    requires 0 <= j <= i < |s|
    requires j == 0 || s[j - 1] <= s[j]
    requires is_sorted(s[..j])
    requires is_sorted(s[j..(i + 1)])
    ensures is_sorted(s[..(i + 1)])
{
    var hi := i + 1;
    assert 0 <= j <= i;
    assert i < |s|;
    assert hi == i + 1;
    assert hi <= |s|;
    assert 0 <= j <= hi <= |s|;

    if i == 0 {
        assert j == 0;
        assert |s| >= 1;
        SingletonSorted(s, 0);
        assert is_sorted(s[0..1]);
        PrefixAtZero(s, 1);
        assert s[..1] == s[0..1];
        assert is_sorted(s[..1]);
        assert i + 1 == 1;
        assert is_sorted(s[..(i + 1)]);
        return;
    }

    assert i >= 1;
    assert hi >= 2;

    forall x, y | 0 <= x < y < hi
        ensures s[x] <= s[y]
    {
        if y < j {
            assert 0 <= x < y < j;
            assert j <= |s|;
            PrefixAtZero(s, j);
            assert s[..j] == s[0..j];
            assert is_sorted(s[0..j]);
            SortedSliceIndex(s, 0, j, x, y);
            assert s[x] <= s[y];
        } else if x >= j {
            assert j <= x < y < hi;
            assert hi <= |s|;
            SortedSliceIndex(s, j, hi, x, y);
            assert s[x] <= s[y];
        } else {
            assert x < j;
            assert j <= y;
            assert x >= 0;
            assert j >= 1;
            assert j > 0;
            assert s[j - 1] <= s[j];
            if x < j - 1 {
                assert 0 <= x < j - 1 < j;
                assert j <= |s|;
                PrefixAtZero(s, j);
