lemma UB(sel: seq<bool>, w: seq<int>, v: seq<int>, c: int)
    requires |sel| == |w| == |v|
    requires forall i :: 0 <= i < |w| ==> w[i] >= 0
    requires total_weight(sel, w) <= c
    ensures total_value(sel, v) <= opt(w, v, c)
    decreases |w|
{
    if |w| > 0 {
        TWNonneg(sel[1..], w[1..]);
        if sel[0] {
