lemma Exists(w: seq<int>, v: seq<int>, c: int) returns (sel: seq<bool>)
    requires |w| == |v|
    requires c >= 0
    ensures |sel| == |w|
    ensures total_weight(sel, w) <= c
    ensures total_value(sel, v) == opt(w, v, c)
    decreases |w|
{
    if |w| == 0 {
        sel := [];
    } else {
        var skip := opt(w[1..], v[1..], c);
        if w[0] <= c && !(skip >= v[0] + opt(w[1..], v[1..], c - w[0])) {
            var r := Exists(w[1..], v[1..], c - w[0]);
            sel := [true] + r;
            assert sel[1..] == r;
        } else {
            var r := Exists(w[1..], v[1..], c);
