method solve_knapsack_01(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| <= 100 // Reasonable bound for recursion/verification time
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000 // Explicitly constrain non-negative weights
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000   // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            ==> total_value(selected, values) <= max_val
    ensures
        // 2. Existence
        exists selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            && total_value(selected, values) == max_val
{
    var n := |weights|;
    var dp := new int[capacity + 1](_ => 0);
    var i := n;
    while i > 0
        invariant 0 <= i <= n
        invariant dp.Length == capacity + 1
        invariant forall c :: 0 <= c <= capacity ==> dp[c] == opt(weights[i..], values[i..], c)
        decreases i
    {
        i := i - 1;
        var ndp := new int[capacity + 1];
        assert weights[i..][1..] == weights[i+1..];
        assert values[i..][1..] == values[i+1..];
        var c := 0;
        while c <= capacity
            modifies ndp
            invariant 0 <= c <= capacity + 1
            invariant forall k :: 0 <= k < c ==> ndp[k] == opt(weights[i..], values[i..], k)
            invariant forall k :: 0 <= k <= capacity ==> dp[k] == opt(weights[i+1..], values[i+1..], k)
            decreases capacity + 1 - c
        {
            if weights[i] <= c {
                ndp[c] := max(dp[c], values[i] + dp[c - weights[i]]);
            } else {
                ndp[c] := dp[c];
            }
            c := c + 1;
        }
        dp := ndp;
    }
    assert weights[0..] == weights;
    assert values[0..] == values;
    max_val := dp[capacity];
    assert max_val == opt(weights, values, capacity);

    OptNonneg(weights, values, capacity);

    forall selected: seq<bool> | is_valid_strategy(selected, weights, capacity)
        ensures total_value(selected, values) <= max_val
    {
        UB(selected, weights, values, capacity);
    }

    var sel := Exists(weights, values, capacity);
    assert is_valid_strategy(sel, weights, capacity) && total_value(sel, values) == max_val;
}

response:
The approach is a bottom-up dynamic program over suffixes of the item list. A ghost function `opt` defines the best value achievable from a suffix, and lemmas connect it to the contract.

- **`opt(w, v, c)`**: the best value using items `w`/`v` with capacity `c`. For the first item it takes the larger of skipping it and taking it, where taking is only allowed when `w[0] <= c`.
- **DP loop**: goes from the last item back to the first. It keeps `dp[c] == opt(weights[i..], values[i..], c)` for every `c`. The inner loop is given `modifies ndp` so the verifier knows the old `dp` array stays unchanged.
- **`UB`**: any valid selection's value is at most `opt`. It relies on `TWNonneg` (total weight is never negative) to show that a chosen item fits.
- **`Exists`**: builds a selection that achieves exactly `opt`, which serves as the witness for the existence postcondition.
- **`OptNonneg`**: shows `opt` is never negative, giving `max_val >= 0`.

