lemma total_loot_cons(houses: seq<int>, nums: seq<int>)
  requires |houses| >= 1
  requires 0 <= houses[0] < |nums|
  ensures total_loot(houses, nums) == nums[houses[0]] + total_loot(houses[1..], nums)
