lemma split_last(s: seq<int>)
  requires |s| >= 1
  ensures s == s[..|s| - 1] + [s[|s| - 1]]
{
  var pref := s[..|s| - 1];
  var last := s[|s| - 1];
  var t := pref + [last];
  assert |t| == |s|;
  forall i: int | 0 <= i < |s|
    ensures s[i] == t[i]
  {
    if i < |pref| {
      assert t[i] == pref[i];
      assert pref[i] == s[i];
    } else {
      assert i == |pref|;
      assert t[i] == last;
      assert s[i] == last;
    }
  }
  assert s == t;
}

lemma append_drop_first(prefix: seq<int>, h: int)
  requires |prefix| >= 1
  ensures (prefix + [h])[0] == prefix[0]
  ensures (prefix + [h])[1..] == prefix[1..] + [h]
{
  var s := prefix + [h];
  var L := s[1..];
  var R := prefix[1..] + [h];
  assert s[0] == prefix[0];
  assert |s| == |prefix| + 1;
  assert |L| == |prefix|;
  assert |prefix[1..]| == |prefix| - 1;
  assert |R| == |prefix|;
  forall i: int | 0 <= i < |L|
    ensures L[i] == R[i]
  {
    assert L[i] == s[i + 1];
    if i + 1 < |prefix| {
      assert s[i + 1] == prefix[i + 1];
      assert R[i] == prefix[1..][i];
      assert prefix[1..][i] == prefix[i + 1];
    } else {
      assert i + 1 == |prefix|;
      assert s[i + 1] == h;
      assert i == |prefix| - 1;
      assert R[i] == h;
    }
  }
  assert L == R;
}

lemma total_loot_append(prefix: seq<int>, h: int, nums: seq<int>)
  requires forall i: int :: 0 <= i < |prefix| ==> 0 <= prefix[i] < |nums|
  requires 0 <= h < |nums|
  ensures total_loot(prefix + [h], nums) == total_loot(prefix, nums) + nums[h]
  decreases |prefix|
{
  if |prefix| == 0 {
    assert prefix + [h] == [h];
    total_loot_cons([h], nums);
    assert [h][1..] == [];
    assert total_loot([], nums) == 0;
    assert total_loot(prefix, nums) == 0;
  } else {
    append_drop_first(prefix, h);
    var combined := prefix + [h];
    var tail := prefix[1..];
    assert combined[0] == prefix[0];
    assert combined[1..] == tail + [h];
    assert 0 <= prefix[0] < |nums|;
    total_loot_cons(combined, nums);
    forall i: int | 0 <= i < |tail|
      ensures 0 <= tail[i] < |nums|
    {
      assert 0 <= i + 1 < |prefix|;
      assert tail[i] == prefix[i + 1];
      assert 0 <= prefix[i + 1] < |nums|;
    }
    total_loot_append(tail, h, nums);
    total_loot_cons(prefix, nums);
    assert total_loot(combined[1..], nums) == total_loot(tail + [h], nums);
    assert total_loot(combined, nums) == nums[prefix[0]] + total_loot(tail + [h], nums);
    assert total_loot(tail + [h], nums) == total_loot(tail, nums) + nums[h];
    assert total_loot(prefix, nums) == nums[prefix[0]] + total_loot(tail, nums);
  }
}

