  ensures is_valid_robbery(houses, newBound)
{
  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < newBound
  {
    assert 0 <= houses[k] < oldBound;
    assert houses[k] < newBound;
  }
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;
}

lemma still_valid_larger_bound(houses: seq<int>, oldBound: int, newBound: int)
  requires is_valid_robbery(houses, oldBound)
  requires oldBound <= newBound
  ensures is_valid_robbery(houses, newBound)
{
  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < newBound
  {
    assert 0 <= houses[k] < oldBound;
    assert oldBound <= newBound;
  }
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;
}

lemma prefix_before_last(houses: seq<int>, n: int)
  requires |houses| >= 1
  requires n >= 2
  requires is_valid_robbery(houses, n)
  requires houses[|houses| - 1] == n - 1
  ensures is_valid_robbery(houses[..|houses| - 1], n - 2)
{
  var rest := houses[..|houses| - 1];
  var last := houses[|houses| - 1];
  assert last == n - 1;
  assert forall i: int :: 0 <= i < |houses| ==> 0 <= houses[i] < n;
  assert forall i: int :: 0 <= i < |houses| - 1 ==> houses[i + 1] >= houses[i] + 2;

  forall k: int | 0 <= k < |rest|
    ensures 0 <= rest[k] < n - 2
  {
    assert rest[k] == houses[k];
    assert 0 <= houses[k] < n;
    elem_below_last_by_two(houses, k);
    assert houses[k] <= last - 2;
    assert last - 2 == n - 3;
    assert houses[k] <= n - 3;
    assert houses[k] < n - 2;
  }

  forall k: int | 0 <= k < |rest| - 1
    ensures rest[k + 1] >= rest[k] + 2
  {
    assert rest[k] == houses[k];
    assert rest[k + 1] == houses[k + 1];
    assert houses[k + 1] >= houses[k] + 2;
  }
}

lemma append_house_ok(prev: seq<int>, n: int)
  requires n >= 2
  requires is_valid_robbery(prev, n - 2)
  ensures is_valid_robbery(prev + [n - 1], n)
{
  var plan := prev + [n - 1];
  assert |plan| == |prev| + 1;
  assert forall i: int :: 0 <= i < |prev| ==> 0 <= prev[i] < n - 2;
  assert forall i: int :: 0 <= i < |prev| - 1 ==> prev[i + 1] >= prev[i] + 2;

  forall i: int | 0 <= i < |prev|
    ensures plan[i] == prev[i]
  {
  }
  assert plan[|prev|] == n - 1;

  forall i: int | 0 <= i < |plan|
    ensures 0 <= plan[i] < n
  {
    if i < |prev| {
      assert plan[i] == prev[i];
      assert 0 <= prev[i] < n - 2;
      assert prev[i] < n;
    } else {
      assert i == |prev|;
      assert plan[i] == n - 1;
      assert 0 <= n - 1 < n;
    }
  }

  forall i: int | 0 <= i < |plan| - 1
    ensures plan[i + 1] >= plan[i] + 2
  {
    if i < |prev| - 1 {
      assert plan[i] == prev[i];
      assert plan[i + 1] == prev[i + 1];
      assert prev[i + 1] >= prev[i] + 2;
    } else {
      assert i < |prev|;
      assert i >= |prev| - 1;
      assert |prev| >= 1;
      assert i == |prev| - 1;
      assert plan[i] == prev[i];
      assert plan[i + 1] == n - 1;
      assert 0 <= prev[i] < n - 2;
      assert prev[i] <= n - 3;
      assert prev[i] + 2 <= n - 1;
    }
  }
}

lemma valid_same_bound(houses: seq<int>, b1: int, b2: int)
  requires is_valid_robbery(houses, b1)
  requires b1 == b2
  ensures is_valid_robbery(houses, b2)
{
  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < b2
  {
    assert 0 <= houses[k] < b1;
    assert b1 == b2;
    assert houses[k] < b2;
  }
  assert forall j: int :: 0 <= j < |houses| - 1 ==> houses[j + 1] >= houses[j] + 2;
}

lemma transport_upper(nums: seq<int>, b1: int, b2: int, cap1: int, cap2: int)
  requires b1 == b2
  requires cap1 == cap2
  requires forall h: seq<int> :: is_valid_robbery(h, b1) ==> total_loot(h, nums) <= cap1
  ensures forall h: seq<int> :: is_valid_robbery(h, b2) ==> total_loot(h, nums) <= cap2
{
  forall h: seq<int> | is_valid_robbery(h, b2)
    ensures total_loot(h, nums) <= cap2
  {
    valid_same_bound(h, b2, b1);
    assert is_valid_robbery(h, b1);
    assert total_loot(h, nums) <= cap1;
    assert cap1 == cap2;
  }
}

lemma init_plans(nums: seq<int>)
  requires |nums| >= 1
  ensures is_valid_robbery([], 0)
  ensures is_valid_robbery([0], 1)
  ensures total_loot([], nums) == 0
  ensures total_loot([0], nums) == nums[0]
{
  assert |[]| == 0;
  assert total_loot([], nums) == 0;
  assert forall j: int :: 0 <= j < |[]| ==> 0 <= [][j] < 0;
  assert forall j: int :: 0 <= j < |[]| - 1 ==> [][j + 1] >= [][j] + 2;
  assert is_valid_robbery([], 0);

  forall j: int | 0 <= j < |[0]|
    ensures 0 <= [0][j] < 1
  {
    assert j == 0;
    assert [0][j] == 0;
  }
  assert forall j: int :: 0 <= j < |[0]| - 1 ==> [0][j + 1] >= [0][j] + 2;
  assert is_valid_robbery([0], 1);

  assert 0 <= 0 < |nums|;
  total_loot_cons([0], nums);
  assert [0][1..] == [];
  assert total_loot([0], nums) == nums[0] + total_loot([], nums);
  assert total_loot([0], nums) == nums[0];
}

lemma bound0(nums: seq<int>, houses: seq<int>)
  requires is_valid_robbery(houses, 0)
  ensures houses == []
  ensures total_loot(houses, nums) == 0
{
  if |houses| != 0 {
    assert 0 <= houses[0] < 0;
    assert false;
  }
  assert |houses| == 0;
  assert houses == [];
  assert total_loot(houses, nums) == 0;
}

lemma bound1(nums: seq<int>, houses: seq<int>)
  requires |nums| >= 1
  requires nums[0] >= 0
  requires is_valid_robbery(houses, 1)
  ensures total_loot(houses, nums) <= nums[0]
{
  if |houses| == 0 {
    assert total_loot(houses, nums) == 0;
    assert 0 <= nums[0];
  } else {
    var last := houses[|houses| - 1];
    assert 0 <= last < 1;
    assert last == 0;
    if |houses| >= 2 {
      assert forall j: int :: 0 <= j < |houses| - 1 ==> houses[j + 1] >= houses[j] + 2;
      elem_below_last_by_two(houses, 0);
      assert houses[0] <= last - 2;
      assert houses[0] <= -2;
      assert 0 <= houses[0];
      assert false;
    }
    assert |houses| == 1;
    assert houses[0] == 0;
    singleton_eq(houses, 0);
    assert houses == [0];
    assert 0 <= 0 < |nums|;
    total_loot_cons(houses, nums);
    assert houses[1..] == [];
    assert total_loot([], nums) == 0;
    assert total_loot(houses, nums) == nums[0];
  }
}

lemma take_plan_props(nums: seq<int>, i: int, prevPlan: seq<int>, prev: int)
  requires 1 <= i < |nums|
  requires is_valid_robbery(prevPlan, i - 1)
  requires total_loot(prevPlan, nums) == prev
  ensures is_valid_robbery(prevPlan + [i], i + 1)
  ensures total_loot(prevPlan + [i], nums) == prev + nums[i]
{
  append_house_ok(prevPlan, i + 1);
  assert is_valid_robbery(prevPlan + [i], i + 1);

  forall k: int | 0 <= k < |prevPlan|
    ensures 0 <= prevPlan[k] < |nums|
  {
    assert 0 <= prevPlan[k] < i - 1;
    assert i - 1 < i;
    assert prevPlan[k] < i;
    assert i < |nums|;
    assert prevPlan[k] < |nums|;
  }
  assert 0 <= i < |nums|;
  total_loot_append(prevPlan, i, nums);
  assert total_loot(prevPlan + [i], nums) == total_loot(prevPlan, nums) + nums[i];
  assert total_loot(prevPlan, nums) == prev;
  assert total_loot(prevPlan + [i], nums) == prev + nums[i];
}

lemma extend_upper_take(nums: seq<int>, i: int, prev: int, houses: seq<int>)
  requires 1 <= i < |nums|
  requires forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
  requires is_valid_robbery(houses, i + 1)
  requires |houses| >= 1
  requires houses[|houses| - 1] == i
  ensures total_loot(houses, nums) <= prev + nums[i]
{
  var n := i + 1;
  var last := houses[|houses| - 1];
  var rest := houses[..|houses| - 1];
  assert n >= 2;
  assert last == i;
  assert last == n - 1;

  forall k: int | 0 <= k < |houses|
    ensures 0 <= houses[k] < |nums|
  {
    assert 0 <= houses[k] < n;
    assert i < |nums|;
    assert n <= |nums|;
    assert houses[k] < |nums|;
  }
  loot_split_last(houses, nums);
  assert total_loot(houses, nums) == total_loot(rest, nums) + nums[last];

  prefix_before_last(houses, n);
  assert is_valid_robbery(rest, n - 2);
  assert n - 2 == i - 1;
  valid_same_bound(rest, n - 2, i - 1);
  assert is_valid_robbery(rest, i - 1);
  assert total_loot(rest, nums) <= prev;
  assert nums[last] == nums[i];
  assert total_loot(houses, nums) == total_loot(rest, nums) + nums[i];
  assert total_loot(houses, nums) <= prev + nums[i];
}

lemma extend_upper_skip(nums: seq<int>, i: int, best: int, houses: seq<int>)
  requires 1 <= i < |nums|
  requires forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
  requires is_valid_robbery(houses, i + 1)
  requires |houses| >= 1
  requires houses[|houses| - 1] != i
  ensures total_loot(houses, nums) <= best
{
  var last := houses[|houses| - 1];
  assert 0 <= last < i + 1;
  assert last != i;
  if last > i - 1 {
    assert last >= i;
    assert last < i + 1;
    assert last == i;
    assert false;
  }
  assert last <= i - 1;

  assert forall j: int :: 0 <= j < |houses| - 1 ==> houses[j + 1] >= houses[j] + 2;
  forall k: int | 0 <= k < |houses|
    ensures houses[k] < i
  {
    elem_le_last(houses, k);
    assert houses[k] <= last;
    assert last <= i - 1;
    assert houses[k] <= i - 1;
    assert houses[k] < i;
  }
  assert i >= 1;
  still_valid_smaller_bound(houses, i + 1, i);
  assert is_valid_robbery(houses, i);
  assert total_loot(houses, nums) <= best;
}

lemma extend_upper(nums: seq<int>, i: int, prev: int, best: int, houses: seq<int>)
  requires 1 <= i < |nums|
  requires forall k: int :: 0 <= k < |nums| ==> nums[k] >= 0
  requires forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
  requires forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
  requires prev >= 0
  requires best >= 0
  requires is_valid_robbery(houses, i + 1)
  ensures total_loot(houses, nums) <= (if best >= prev + nums[i] then best else prev + nums[i])
{
  var take := prev + nums[i];
  if |houses| == 0 {
    assert houses == [];
    assert total_loot(houses, nums) == 0;
    if best >= take {
      assert 0 <= best;
      assert total_loot(houses, nums) <= best;
      assert total_loot(houses, nums) <= (if best >= take then best else take);
    } else {
      assert 0 <= i < |nums|;
      assert nums[i] >= 0;
      assert prev >= 0;
      assert take >= 0;
      assert total_loot(houses, nums) <= take;
      assert total_loot(houses, nums) <= (if best >= take then best else take);
    }
  } else {
    var last := houses[|houses| - 1];
    assert 0 <= last < i + 1;
    if last == i {
      extend_upper_take(nums, i, prev, houses);
      assert total_loot(houses, nums) <= take;
      if best >= take {
        assert total_loot(houses, nums) <= best;
        assert total_loot(houses, nums) <= (if best >= take then best else take);
      } else {
        assert total_loot(houses, nums) <= take;
        assert total_loot(houses, nums) <= (if best >= take then best else take);
      }
    } else {
      extend_upper_skip(nums, i, best, houses);
      assert total_loot(houses, nums) <= best;
      if best >= take {
        assert total_loot(houses, nums) <= (if best >= take then best else take);
      } else {
        assert best < take;
        assert best <= take;
        assert total_loot(houses, nums) <= take;
        assert total_loot(houses, nums) <= (if best >= take then best else take);
      }
    }
  }
  assert take == prev + nums[i];
  assert total_loot(houses, nums) <= (if best >= prev + nums[i] then best else prev + nums[i]);
}

lemma step_ok(
  nums: seq<int>,
  i: int,
  prev: int,
  best: int,
  planPrev: seq<int>,
  planBest: seq<int>,
  newPrev: int,
  newBest: int,
  newPlanPrev: seq<int>,
  newPlanBest: seq<int>
)
  requires 1 <= i < |nums|
  requires forall k: int :: 0 <= k < |nums| ==> nums[k] >= 0
  requires prev >= 0 && best >= 0
  requires is_valid_robbery(planPrev, i - 1)
  requires is_valid_robbery(planBest, i)
  requires total_loot(planPrev, nums) == prev
  requires total_loot(planBest, nums) == best
  requires forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
  requires forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
  requires newPrev == best
  requires newBest == (if best >= prev + nums[i] then best else prev + nums[i])
  requires newPlanPrev == planBest
  requires newPlanBest == (if best >= prev + nums[i] then planBest else planPrev + [i])
  ensures newPrev >= 0 && newBest >= 0
  ensures is_valid_robbery(newPlanPrev, i)
  ensures is_valid_robbery(newPlanBest, i + 1)
  ensures total_loot(newPlanPrev, nums) == newPrev
  ensures total_loot(newPlanBest, nums) == newBest
  ensures forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= newPrev
  ensures forall h: seq<int> :: is_valid_robbery(h, i + 1) ==> total_loot(h, nums) <= newBest
{
  var take := prev + nums[i];
  assert take == prev + nums[i];

  if best >= take {
    assert newBest == best;
    assert newPlanBest == planBest;
    assert newBest >= 0;
  } else {
    assert newBest == take;
    assert newPlanBest == planPrev + [i];
    assert 0 <= i < |nums|;
    assert nums[i] >= 0;
    assert prev >= 0;
    assert take >= 0;
    assert newBest >= 0;
  }
  assert newPlanPrev == planBest;
  assert newPrev == best;
  assert newPrev >= 0;

  assert is_valid_robbery(planBest, i);
  assert is_valid_robbery(newPlanPrev, i);
  assert total_loot(planBest, nums) == best;
  assert total_loot(newPlanPrev, nums) == newPrev;

  if best >= take {
    still_valid_larger_bound(planBest, i, i + 1);
    assert is_valid_robbery(planBest, i + 1);
    assert is_valid_robbery(newPlanBest, i + 1);
    assert total_loot(planBest, nums) == best;
    assert newBest == best;
    assert total_loot(newPlanBest, nums) == newBest;
  } else {
    take_plan_props(nums, i, planPrev, prev);
    assert is_valid_robbery(planPrev + [i], i + 1);
    assert newPlanBest == planPrev + [i];
    assert is_valid_robbery(newPlanBest, i + 1);
    assert total_loot(planPrev + [i], nums) == prev + nums[i];
    assert newBest == prev + nums[i];
    assert total_loot(newPlanBest, nums) == newBest;
  }

  forall h: seq<int> | is_valid_robbery(h, i)
    ensures total_loot(h, nums) <= newPrev
  {
    assert total_loot(h, nums) <= best;
    assert newPrev == best;
  }

  forall h: seq<int> | is_valid_robbery(h, i + 1)
    ensures total_loot(h, nums) <= newBest
  {
    extend_upper(nums, i, prev, best, h);
    assert total_loot(h, nums) <= (if best >= prev + nums[i] then best else prev + nums[i]);
    assert newBest == (if best >= prev + nums[i] then best else prev + nums[i]);
  }
}

method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    // Constraints matching Verus u64
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    // 1. Upper Bound
    ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            ==> total_loot(houses, nums) <= max_amount)
    // 2. Existence
    ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            && total_loot(houses, nums) == max_amount)
{
  if |nums| == 0 {
    max_amount := 0;
    forall h: seq<int> | is_valid_robbery(h, |nums|)
      ensures total_loot(h, nums) <= max_amount
    {
      assert |nums| == 0;
      bound0(nums, h);
      assert total_loot(h, nums) == 0;
      assert max_amount == 0;
    }
    assert is_valid_robbery([], |nums|);
    assert total_loot([], nums) == 0;
    assert total_loot([], nums) == max_amount;
    return;
  }

  assert |nums| >= 1;
  assert 0 <= 0 < |nums|;
  assert nums[0] >= 0;

  var i: int := 1;
  var best: int := nums[0];
  var prev: int := 0;
  ghost var planBest: seq<int> := [0];
  ghost var planPrev: seq<int> := [];

  init_plans(nums);
  assert planPrev == [];
  assert planBest == [0];
  assert is_valid_robbery(planPrev, 0);
  assert is_valid_robbery(planBest, 1);
  assert total_loot(planPrev, nums) == 0;
  assert total_loot(planBest, nums) == nums[0];
  assert i == 1;
  assert i - 1 == 0;
  valid_same_bound(planPrev, 0, i - 1);
  valid_same_bound(planBest, 1, i);
  assert is_valid_robbery(planPrev, i - 1);
  assert is_valid_robbery(planBest, i);
  assert prev == 0;
  assert total_loot(planPrev, nums) == prev;
  assert best == nums[0];
  assert total_loot(planBest, nums) == best;
  assert prev >= 0;
  assert best >= 0;

  forall h: seq<int> | is_valid_robbery(h, 0)
    ensures total_loot(h, nums) <= prev
  {
    bound0(nums, h);
    assert prev == 0;
    assert total_loot(h, nums) == 0;
  }
  assert i - 1 == 0;
  transport_upper(nums, 0, i - 1, 0, prev);

  forall h: seq<int> | is_valid_robbery(h, 1)
    ensures total_loot(h, nums) <= best
  {
    bound1(nums, h);
    assert best == nums[0];
  }
  assert i == 1;
  transport_upper(nums, 1, i, nums[0], best);

  while i < |nums|
    invariant 1 <= i <= |nums|
    invariant prev >= 0 && best >= 0
    invariant is_valid_robbery(planPrev, i - 1)
    invariant is_valid_robbery(planBest, i)
    invariant total_loot(planPrev, nums) == prev
    invariant total_loot(planBest, nums) == best
    invariant forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
    invariant forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
    decreases |nums| - i
  {
    var iOld := i;
    var take := prev + nums[iOld];
    var newBest := if best >= take then best else take;
    ghost var newPlanBest: seq<int> := if best >= take then planBest else planPrev + [iOld];
    ghost var newPlanPrev: seq<int> := planBest;
    var newPrev := best;

    assert iOld == i;
    assert 1 <= iOld < |nums|;
    assert forall k: int :: 0 <= k < |nums| ==> nums[k] >= 0;
    assert prev >= 0 && best >= 0;
    assert is_valid_robbery(planPrev, i - 1);
    assert iOld - 1 == i - 1;
    valid_same_bound(planPrev, i - 1, iOld - 1);
    assert is_valid_robbery(planPrev, iOld - 1);
    assert is_valid_robbery(planBest, i);
    valid_same_bound(planBest, i, iOld);
    assert is_valid_robbery(planBest, iOld);
    assert total_loot(planPrev, nums) == prev;
    assert total_loot(planBest, nums) == best;
    transport_upper(nums, i - 1, iOld - 1, prev, prev);
    transport_upper(nums, i, iOld, best, best);
    assert newPrev == best;
    assert take == prev + nums[iOld];
    assert newBest == (if best >= prev + nums[iOld] then best else prev + nums[iOld]);
    assert newPlanPrev == planBest;
    assert newPlanBest == (if best >= prev + nums[iOld] then planBest else planPrev + [iOld]);

    step_ok(nums, iOld, prev, best, planPrev, planBest, newPrev, newBest, newPlanPrev, newPlanBest);

    planPrev := newPlanPrev;
    planBest := newPlanBest;
    prev := newPrev;
    best := newBest;
    i := iOld + 1;

    assert i == iOld + 1;
    assert i - 1 == iOld;
    assert 1 <= i <= |nums|;
    assert prev == newPrev;
    assert best == newBest;
    assert prev >= 0 && best >= 0;
    assert planPrev == newPlanPrev;
    assert planBest == newPlanBest;

    assert is_valid_robbery(newPlanPrev, iOld);
    assert is_valid_robbery(planPrev, iOld);
    valid_same_bound(planPrev, iOld, i - 1);
    assert is_valid_robbery(planPrev, i - 1);

    assert is_valid_robbery(newPlanBest, iOld + 1);
    assert is_valid_robbery(planBest, iOld + 1);
    assert i == iOld + 1;
    valid_same_bound(planBest, iOld + 1, i);
    assert is_valid_robbery(planBest, i);

    assert total_loot(newPlanPrev, nums) == newPrev;
    assert total_loot(planPrev, nums) == newPrev;
    assert total_loot(planPrev, nums) == prev;

    assert total_loot(newPlanBest, nums) == newBest;
    assert total_loot(planBest, nums) == newBest;
    assert total_loot(planBest, nums) == best;

    transport_upper(nums, iOld, i - 1, newPrev, prev);
    transport_upper(nums, iOld + 1, i, newBest, best);
  }

  assert i <= |nums|;
  assert !(i < |nums|);
  assert i >= |nums|;
  assert i == |nums|;
  max_amount := best;
  assert max_amount == best;
