lemma knapsack_witness(
    weights: seq<int>,
    values: seq<int>,
    capacity: int
) returns (selected: seq<bool>)
    requires |weights| == |values|
    requires 0 <= capacity
    requires knapsack_nonnegative(weights)
    requires knapsack_nonnegative(values)
    ensures is_valid_strategy(selected, weights, capacity)
    ensures
        total_value(selected, values) ==
        knapsack_opt(weights, values, capacity)
    decreases |weights|
{
    if |weights| == 0 {
        selected := [];
    } else {
        assert |values| > 0;
        assert knapsack_nonnegative(weights[1..]);
        assert knapsack_nonnegative(values[1..]);

        if weights[0] > capacity {
            var tail := knapsack_witness(
                weights[1..],
                values[1..],
                capacity
            );
            selected := [false] + tail;

            knapsack_weight_prepend(false, tail, weights);
            knapsack_value_prepend(false, tail, values);

            assert |selected| == |weights|;
            assert
                total_weight(selected, weights) ==
                total_weight(tail, weights[1..]);
            assert total_weight(selected, weights) <= capacity;
            assert is_valid_strategy(selected, weights, capacity);

            assert
                total_value(selected, values) ==
                total_value(tail, values[1..]);
            assert
                knapsack_opt(weights, values, capacity) ==
                knapsack_opt(
                    weights[1..],
                    values[1..],
                    capacity
                );
        } else {
            var skip := knapsack_opt(
                weights[1..],
                values[1..],
                capacity
            );
            var take :=
                values[0] +
                knapsack_opt(
                    weights[1..],
                    values[1..],
                    capacity - weights[0]
                );

            if skip >= take {
                var tail := knapsack_witness(
                    weights[1..],
                    values[1..],
                    capacity
                );
                selected := [false] + tail;

                knapsack_weight_prepend(false, tail, weights);
                knapsack_value_prepend(false, tail, values);

                assert |selected| == |weights|;
                assert
                    total_weight(selected, weights) ==
                    total_weight(tail, weights[1..]);
                assert total_weight(selected, weights) <= capacity;
                assert is_valid_strategy(selected, weights, capacity);

                assert
                    total_value(selected, values) ==
                    total_value(tail, values[1..]);
                assert knapsack_opt(weights, values, capacity) == skip;
            } else {
                var tail := knapsack_witness(
                    weights[1..],
                    values[1..],
                    capacity - weights[0]
                );
                selected := [true] + tail;

                knapsack_weight_prepend(true, tail, weights);
                knapsack_value_prepend(true, tail, values);

                assert |selected| == |weights|;
                assert
                    total_weight(selected, weights) ==
                    weights[0] +
                    total_weight(tail, weights[1..]);
                assert
                    total_weight(tail, weights[1..]) <=
                    capacity - weights[0];
                assert total_weight(selected, weights) <= capacity;
                assert is_valid_strategy(selected, weights, capacity);

                assert
                    total_value(selected, values) ==
                    values[0] +
                    total_value(tail, values[1..]);
                assert knapsack_opt(weights, values, capacity) == take;
            }
        }
    }
}

method solve_knapsack_01(
    weights: seq<int>,
    values: seq<int>,
    capacity: int
) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| <= 100
    requires 0 <= capacity <= 1000
    requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000
    ensures max_val >= 0
    ensures
        forall selected: seq<bool> ::
            is_valid_strategy(selected, weights, capacity)
            ==> total_value(selected, values) <= max_val
    ensures
        exists selected: seq<bool> ::
            is_valid_strategy(selected, weights, capacity)
            && total_value(selected, values) == max_val
{
    assert forall i :: 0 <= i < |weights| ==> 0 <= weights[i];
    assert forall i :: 0 <= i < |values| ==> 0 <= values[i];

    knapsack_forall_nonnegative(weights);
    knapsack_forall_nonnegative(values);

    max_val := knapsack_opt(weights, values, capacity);

    forall selected: seq<bool>
        | is_valid_strategy(selected, weights, capacity)
        ensures total_value(selected, values) <= max_val
    {
        knapsack_upper_bound(
            selected,
            weights,
            values,
            capacity
        );
    }

    ghost var optimalSelection := knapsack_witness(
        weights,
        values,
        capacity
    );

    assert is_valid_strategy(optimalSelection, weights, capacity);
    assert total_value(optimalSelection, values) == max_val;
    assert exists selected: seq<bool> ::
        is_valid_strategy(selected, weights, capacity)
        && total_value(selected, values) == max_val;
}

