                    total_weight(selected, weights) ==
                    weights[0] +
                    total_weight(tail, weights[1..]);
                assert
                    total_weight(tail, weights[1..]) <=
                    capacity - weights[0];
                assert total_weight(selected, weights) <= capacity;
                assert is_valid_strategy(selected, weights, capacity);

                assert
                    total_value(selected, values) ==
                    values[0] +
                    total_value(tail, values[1..]);
                assert knapsack_opt(weights, values, capacity) == take;
            }
        }
    }
}

