    requires 0 <= start
    requires foundHere <==> matches_at(haystack, needle, start)
    requires newIndices == (if foundHere then oldIndices + [start] else oldIndices)
    requires Sound(haystack, needle, oldIndices, start)
    requires Complete(haystack, needle, oldIndices, start)
    ensures Sound(haystack, needle, newIndices, start + 1)
    ensures Complete(haystack, needle, newIndices, start + 1)
{
    if foundHere {
        assert newIndices == oldIndices + [start];
        assert |newIndices| == |oldIndices| + 1;
    } else {
        assert newIndices == oldIndices;
        assert |newIndices| == |oldIndices|;
    }

    forall k | 0 <= k < |newIndices|
        ensures 0 <= newIndices[k] < start + 1 && matches_at(haystack, needle, newIndices[k])
    {
        if k < |oldIndices| {
            if foundHere {
                assert newIndices == oldIndices + [start];
                assert newIndices[k] == oldIndices[k];
            } else {
                assert newIndices == oldIndices;
                assert newIndices[k] == oldIndices[k];
            }
            assert 0 <= oldIndices[k] < start && matches_at(haystack, needle, oldIndices[k]);
            assert 0 <= newIndices[k] < start + 1;
            assert matches_at(haystack, needle, newIndices[k]);
        } else {
            if !foundHere {
                assert newIndices == oldIndices;
                assert |newIndices| == |oldIndices|;
                assert false;
            }
            assert foundHere;
            assert newIndices == oldIndices + [start];
            assert |newIndices| == |oldIndices| + 1;
            assert k == |oldIndices|;
            assert newIndices[k] == start;
            assert matches_at(haystack, needle, start);
            assert 0 <= start < start + 1;
        }
    }

    forall j | 0 <= j < start + 1 && matches_at(haystack, needle, j)
        ensures exists k :: 0 <= k < |newIndices| && newIndices[k] == j
    {
        if j < start {
            assert 0 <= j < start && matches_at(haystack, needle, j);
            assert exists u :: 0 <= u < |oldIndices| && oldIndices[u] == j;
            var w :| 0 <= w < |oldIndices| && oldIndices[w] == j;
            if foundHere {
                assert newIndices == oldIndices + [start];
                assert newIndices[w] == oldIndices[w];
            } else {
                assert newIndices == oldIndices;
                assert newIndices[w] == oldIndices[w];
