            assert newIndices[w] == j;
            assert 0 <= w < |newIndices|;
            assert exists k :: k == w && 0 <= k < |newIndices| && newIndices[k] == j;
        } else {
            assert j == start;
            assert matches_at(haystack, needle, start);
            assert foundHere;
            assert newIndices == oldIndices + [start];
            assert |newIndices| == |oldIndices| + 1;
            assert newIndices[|oldIndices|] == start;
            assert exists k :: k == |oldIndices| && 0 <= k < |newIndices| && newIndices[k] == j;
        }
    }
}

