method kmp_search(haystack: seq<int>, needle: seq<int>) returns (indices: seq<int>)
    requires |haystack| < 1000000
    requires |needle| < 1000000
    ensures 
        // Type Constraint: Indices must be non-negative (simulating usize)
        forall k :: 0 <= k < |indices| ==> indices[k] >= 0
    ensures
        // Soundness: Every index returned is a valid match
        forall i :: 0 <= i < |indices| ==> 
            matches_at(haystack, needle, indices[i])
    ensures
        // Completeness: Every valid match in the haystack is found
        forall i :: matches_at(haystack, needle, i) ==> 
            exists k :: 0 <= k < |indices| && indices[k] == i
{
    indices := [];
    var start := 0;
    Init(haystack, needle, indices, start);

    while start <= |haystack|
        invariant 0 <= start <= |haystack| + 1
        invariant Sound(haystack, needle, indices, start)
        invariant Complete(haystack, needle, indices, start)
        decreases |haystack| + 1 - start
    {
        assert Sound(haystack, needle, indices, start);
        assert Complete(haystack, needle, indices, start);

        var oldIndices := indices;
        var startBefore := start;
        assert oldIndices == indices && startBefore == start;
        assert Sound(haystack, needle, oldIndices, startBefore);
        assert Complete(haystack, needle, oldIndices, startBefore);
        assert 0 <= startBefore <= |haystack|;

        var foundHere: bool;
        if startBefore + |needle| <= |haystack| {
            foundHere := CheckAt(haystack, needle, startBefore);
            assert foundHere <==> matches_at(haystack, needle, startBefore);
        } else {
            NoMatchPastEnd(haystack, needle, startBefore);
            foundHere := false;
            assert foundHere <==> matches_at(haystack, needle, startBefore);
        }

        var nextIndices := if foundHere then oldIndices + [startBefore] else oldIndices;
        assert nextIndices == (if foundHere then oldIndices + [startBefore] else oldIndices);
        StepComplete(haystack, needle, oldIndices, startBefore, foundHere, nextIndices);

        indices := nextIndices;
        start := startBefore + 1;
        assert indices == nextIndices && start == startBefore + 1;
        assert Sound(haystack, needle, indices, start);
        assert Complete(haystack, needle, indices, start);
    }

    assert !(start <= |haystack|);
    assert start >= |haystack| + 1;
    assert start <= |haystack| + 1;
    assert start == |haystack| + 1;
    Finish(haystack, needle, indices, start);
}

