lemma step_ok(
  nums: seq<int>,
  i: int,
  prev: int,
  best: int,
  planPrev: seq<int>,
  planBest: seq<int>,
  newPrev: int,
  newBest: int,
  newPlanPrev: seq<int>,
  newPlanBest: seq<int>
)
  requires 1 <= i < |nums|
  requires forall k: int :: 0 <= k < |nums| ==> nums[k] >= 0
  requires prev >= 0 && best >= 0
  requires is_valid_robbery(planPrev, i - 1)
  requires is_valid_robbery(planBest, i)
  requires total_loot(planPrev, nums) == prev
  requires total_loot(planBest, nums) == best
  requires forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
  requires forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
  requires newPrev == best
  requires newBest == (if best >= prev + nums[i] then best else prev + nums[i])
  requires newPlanPrev == planBest
  requires newPlanBest == (if best >= prev + nums[i] then planBest else planPrev + [i])
  ensures newPrev >= 0 && newBest >= 0
  ensures is_valid_robbery(newPlanPrev, i)
  ensures is_valid_robbery(newPlanBest, i + 1)
  ensures total_loot(newPlanPrev, nums) == newPrev
  ensures total_loot(newPlanBest, nums) == newBest
  ensures forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= newPrev
  ensures forall h: seq<int> :: is_valid_robbery(h, i + 1) ==> total_loot(h, nums) <= newBest
{
  var take := prev + nums[i];
  assert take == prev + nums[i];

  if best >= take {
    assert newBest == best;
    assert newPlanBest == planBest;
    assert newBest >= 0;
  } else {
    assert newBest == take;
    assert newPlanBest == planPrev + [i];
    assert 0 <= i < |nums|;
    assert nums[i] >= 0;
    assert prev >= 0;
    assert take >= 0;
    assert newBest >= 0;
  }
  assert newPlanPrev == planBest;
  assert newPrev == best;
  assert newPrev >= 0;

  assert is_valid_robbery(planBest, i);
  assert is_valid_robbery(newPlanPrev, i);
  assert total_loot(planBest, nums) == best;
  assert total_loot(newPlanPrev, nums) == newPrev;

  if best >= take {
    still_valid_larger_bound(planBest, i, i + 1);
    assert is_valid_robbery(planBest, i + 1);
    assert is_valid_robbery(newPlanBest, i + 1);
    assert total_loot(planBest, nums) == best;
    assert newBest == best;
    assert total_loot(newPlanBest, nums) == newBest;
  } else {
    take_plan_props(nums, i, planPrev, prev);
    assert is_valid_robbery(planPrev + [i], i + 1);
    assert newPlanBest == planPrev + [i];
    assert is_valid_robbery(newPlanBest, i + 1);
    assert total_loot(planPrev + [i], nums) == prev + nums[i];
    assert newBest == prev + nums[i];
    assert total_loot(newPlanBest, nums) == newBest;
  }

  forall h: seq<int> | is_valid_robbery(h, i)
    ensures total_loot(h, nums) <= newPrev
  {
    assert total_loot(h, nums) <= best;
    assert newPrev == best;
  }

  forall h: seq<int> | is_valid_robbery(h, i + 1)
    ensures total_loot(h, nums) <= newBest
  {
    extend_upper(nums, i, prev, best, h);
    assert total_loot(h, nums) <= (if best >= prev + nums[i] then best else prev + nums[i]);
    assert newBest == (if best >= prev + nums[i] then best else prev + nums[i]);
  }
}

method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    // Constraints matching Verus u64
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    // 1. Upper Bound
    ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            ==> total_loot(houses, nums) <= max_amount)
    // 2. Existence
    ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            && total_loot(houses, nums) == max_amount)
{
  if |nums| == 0 {
    max_amount := 0;
    forall h: seq<int> | is_valid_robbery(h, |nums|)
      ensures total_loot(h, nums) <= max_amount
    {
      assert |nums| == 0;
      bound0(nums, h);
      assert total_loot(h, nums) == 0;
      assert max_amount == 0;
    }
    assert is_valid_robbery([], |nums|);
    assert total_loot([], nums) == 0;
    assert total_loot([], nums) == max_amount;
    return;
  }

  assert |nums| >= 1;
  assert 0 <= 0 < |nums|;
  assert nums[0] >= 0;

  var i: int := 1;
  var best: int := nums[0];
  var prev: int := 0;
  ghost var planBest: seq<int> := [0];
  ghost var planPrev: seq<int> := [];

  init_plans(nums);
  assert planPrev == [];
  assert planBest == [0];
  assert is_valid_robbery(planPrev, 0);
  assert is_valid_robbery(planBest, 1);
  assert total_loot(planPrev, nums) == 0;
  assert total_loot(planBest, nums) == nums[0];
  assert i == 1;
  assert i - 1 == 0;
  valid_same_bound(planPrev, 0, i - 1);
  valid_same_bound(planBest, 1, i);
  assert is_valid_robbery(planPrev, i - 1);
  assert is_valid_robbery(planBest, i);
  assert prev == 0;
  assert total_loot(planPrev, nums) == prev;
  assert best == nums[0];
  assert total_loot(planBest, nums) == best;
  assert prev >= 0;
  assert best >= 0;

  forall h: seq<int> | is_valid_robbery(h, 0)
    ensures total_loot(h, nums) <= prev
  {
    bound0(nums, h);
    assert prev == 0;
    assert total_loot(h, nums) == 0;
  }
  assert i - 1 == 0;
  transport_upper(nums, 0, i - 1, 0, prev);

  forall h: seq<int> | is_valid_robbery(h, 1)
    ensures total_loot(h, nums) <= best
  {
    bound1(nums, h);
    assert best == nums[0];
  }
  assert i == 1;
  transport_upper(nums, 1, i, nums[0], best);

  while i < |nums|
    invariant 1 <= i <= |nums|
    invariant prev >= 0 && best >= 0
    invariant is_valid_robbery(planPrev, i - 1)
    invariant is_valid_robbery(planBest, i)
    invariant total_loot(planPrev, nums) == prev
    invariant total_loot(planBest, nums) == best
    invariant forall h: seq<int> :: is_valid_robbery(h, i - 1) ==> total_loot(h, nums) <= prev
    invariant forall h: seq<int> :: is_valid_robbery(h, i) ==> total_loot(h, nums) <= best
    decreases |nums| - i
  {
    var iOld := i;
    var take := prev + nums[iOld];
    var newBest := if best >= take then best else take;
    ghost var newPlanBest: seq<int> := if best >= take then planBest else planPrev + [iOld];
    ghost var newPlanPrev: seq<int> := planBest;
    var newPrev := best;

    assert iOld == i;
    assert 1 <= iOld < |nums|;
    assert forall k: int :: 0 <= k < |nums| ==> nums[k] >= 0;
    assert prev >= 0 && best >= 0;
    assert is_valid_robbery(planPrev, i - 1);
    assert iOld - 1 == i - 1;
    valid_same_bound(planPrev, i - 1, iOld - 1);
    assert is_valid_robbery(planPrev, iOld - 1);
    assert is_valid_robbery(planBest, i);
    valid_same_bound(planBest, i, iOld);
    assert is_valid_robbery(planBest, iOld);
    assert total_loot(planPrev, nums) == prev;
    assert total_loot(planBest, nums) == best;
    transport_upper(nums, i - 1, iOld - 1, prev, prev);
    transport_upper(nums, i, iOld, best, best);
    assert newPrev == best;
    assert take == prev + nums[iOld];
    assert newBest == (if best >= prev + nums[iOld] then best else prev + nums[iOld]);
    assert newPlanPrev == planBest;
    assert newPlanBest == (if best >= prev + nums[iOld] then planBest else planPrev + [iOld]);

    step_ok(nums, iOld, prev, best, planPrev, planBest, newPrev, newBest, newPlanPrev, newPlanBest);

    planPrev := newPlanPrev;
    planBest := newPlanBest;
    prev := newPrev;
    best := newBest;
    i := iOld + 1;

    assert i == iOld + 1;
    assert i - 1 == iOld;
    assert 1 <= i <= |nums|;
    assert prev == newPrev;
    assert best == newBest;
    assert prev >= 0 && best >= 0;
    assert planPrev == newPlanPrev;
    assert planBest == newPlanBest;

    assert is_valid_robbery(newPlanPrev, iOld);
    assert is_valid_robbery(planPrev, iOld);
    valid_same_bound(planPrev, iOld, i - 1);
    assert is_valid_robbery(planPrev, i - 1);

    assert is_valid_robbery(newPlanBest, iOld + 1);
    assert is_valid_robbery(planBest, iOld + 1);
    assert i == iOld + 1;
    valid_same_bound(planBest, iOld + 1, i);
    assert is_valid_robbery(planBest, i);

    assert total_loot(newPlanPrev, nums) == newPrev;
    assert total_loot(planPrev, nums) == newPrev;
    assert total_loot(planPrev, nums) == prev;

    assert total_loot(newPlanBest, nums) == newBest;
    assert total_loot(planBest, nums) == newBest;
    assert total_loot(planBest, nums) == best;

    transport_upper(nums, iOld, i - 1, newPrev, prev);
    transport_upper(nums, iOld + 1, i, newBest, best);
  }

  assert i <= |nums|;
  assert !(i < |nums|);
  assert i >= |nums|;
  assert i == |nums|;
  max_amount := best;
  assert max_amount == best;
  assert max_amount >= 0;

  assert is_valid_robbery(planBest, i);
  valid_same_bound(planBest, i, |nums|);
  assert is_valid_robbery(planBest, |nums|);
  assert total_loot(planBest, nums) == best;
  assert total_loot(planBest, nums) == max_amount;

  transport_upper(nums, i, |nums|, best, max_amount);
}

