    assert |u| == a;
    assert |v| == b;
    assert |u| == |v|;
    forall k | 0 <= k < |u|
        ensures u[k] == v[k]
    {
        assert u[k] == s[k];
        assert v[k] == s[k];
        assert u[k] == v[k];
    }
    assert u == v;
    SortedSame(u, v);
    assert v == s[..b];
    assert is_sorted(s[..b]);
}

lemma SortedRangeSubst(s: seq<int>, a: int, b: int, hi: int)
    requires 0 <= a <= hi <= |s|
    requires a == b
    requires is_sorted(s[a..hi])
    ensures is_sorted(s[b..hi])
{
    assert 0 <= b;
    assert b <= hi;
    SliceSame(s, a, hi, b, hi);
    assert s[a..hi] == s[b..hi];
    SortedSame(s[a..hi], s[b..hi]);
    assert is_sorted(s[b..hi]);
}

lemma TransferSortedPrefix(a: seq<int>, b: seq<int>, k: int)
    requires a == b
    requires 0 <= k <= |a|
    requires is_sorted(a[..k])
    ensures is_sorted(b[..k])
{
    assert |b| == |a|;
    assert 0 <= k <= |b|;
    var sa := a[..k];
    var sb := b[..k];
    assert |sa| == k;
    assert |sb| == k;
    assert |sa| == |sb|;
    forall i | 0 <= i < k
        ensures sa[i] == sb[i]
    {
        assert sa[i] == a[i];
        assert sb[i] == b[i];
        assert a[i] == b[i];
        assert sa[i] == sb[i];
    }
    assert sa == sb;
    SortedSame(sa, sb);
    assert sb == b[..k];
    assert is_sorted(b[..k]);
}

lemma TransferSortedRange(a: seq<int>, b: seq<int>, lo: int, hi: int)
    requires a == b
    requires 0 <= lo <= hi <= |a|
    requires is_sorted(a[lo..hi])
    ensures is_sorted(b[lo..hi])
{
    assert |b| == |a|;
    assert 0 <= lo <= hi <= |b|;
    var sa := a[lo..hi];
    var sb := b[lo..hi];
    assert |sa| == hi - lo;
    assert |sb| == hi - lo;
    assert |sa| == |sb|;
    forall i | 0 <= i < |sa|
        ensures sa[i] == sb[i]
    {
        assert sa[i] == a[lo + i];
        assert sb[i] == b[lo + i];
        assert a[lo + i] == b[lo + i];
        assert sa[i] == sb[i];
    }
    assert sa == sb;
    SortedSame(sa, sb);
    assert sb == b[lo..hi];
    assert is_sorted(b[lo..hi]);
}

lemma TransferCross(a: seq<int>, b: seq<int>, j: int, i: int)
    requires a == b
    requires 0 <= j <= i < |a|
    requires |a| == |b|
    requires forall m, n {:trigger a[m], a[n]} :: 0 <= m < j && j < n <= i ==> a[m] <= a[n]
    ensures forall m, n {:trigger b[m], b[n]} :: 0 <= m < j && j < n <= i ==> b[m] <= b[n]
{
    forall m, n | 0 <= m < j && j < n <= i
        ensures b[m] <= b[n]
    {
        assert 0 <= m < |a|;
        assert 0 <= n;
        assert n <= i;
        assert i < |a|;
        assert n < |a|;
        assert a[m] <= a[n];
        assert a[m] == b[m];
        assert a[n] == b[n];
        assert b[m] <= b[n];
    }
}

lemma {:vcs_split_on_every_assert} SwapIndexCases(a: int, b: int, k: int)
    ensures SwapIndex(a, b, k) == (if k == a then b else if k == b then a else k)
    ensures k == a ==> SwapIndex(a, b, k) == b
    ensures (k != a && k == b) ==> SwapIndex(a, b, k) == a
    ensures (k != a && k != b) ==> SwapIndex(a, b, k) == k
{
    if k == a {
        assert SwapIndex(a, b, k) == b;
        assert (if k == a then b else if k == b then a else k) == b;
    } else if k == b {
        assert k != a;
        assert SwapIndex(a, b, k) == a;
        assert (if k == a then b else if k == b then a else k) == a;
    } else {
        assert k != a && k != b;
        assert SwapIndex(a, b, k) == k;
        assert (if k == a then b else if k == b then a else k) == k;
    }
}

lemma SwapDef(s: seq<int>, a: int, b: int)
    requires 0 <= a < |s| && 0 <= b < |s|
    ensures Swap(s, a, b) == s[a := s[b]][b := s[a]]
{
    assert Swap(s, a, b) == s[a := s[b]][b := s[a]];
}

lemma {:vcs_split_on_every_assert} SwapReflects(s: seq<int>, a: int, b: int, k: int)
    requires 0 <= a < |s| && 0 <= b < |s|
    requires 0 <= k < |s|
    ensures |Swap(s, a, b)| == |s|
    ensures Swap(s, a, b)[k] == s[SwapIndex(a, b, k)]
{
    var s1 := s[a := s[b]];
    var s2 := s1[b := s[a]];
    assert |s1| == |s|;
    assert |s2| == |s|;
    assert s1 == s[a := s[b]];
    assert s2 == s1[b := s[a]];
    assert s2 == s[a := s[b]][b := s[a]];
    SwapDef(s, a, b);
    assert Swap(s, a, b) == s[a := s[b]][b := s[a]];
    assert Swap(s, a, b) == s2;
    assert |Swap(s, a, b)| == |s|;
    SwapIndexCases(a, b, k);
    if k == a {
        assert SwapIndex(a, b, k) == b;
        if a == b {
            assert s2[k] == s[a];
            assert s[a] == s[b];
            assert s[SwapIndex(a, b, k)] == s[b];
            assert s2[k] == s[SwapIndex(a, b, k)];
        } else {
            assert a != b;
            assert s1[k] == s[b];
            assert s2[k] == s1[k];
            assert s2[k] == s[b];
            assert s[SwapIndex(a, b, k)] == s[b];
            assert s2[k] == s[SwapIndex(a, b, k)];
        }
    } else if k == b {
        assert k != a;
        assert a != b;
        assert SwapIndex(a, b, k) == a;
        assert s2[k] == s[a];
        assert s[SwapIndex(a, b, k)] == s[a];
        assert s2[k] == s[SwapIndex(a, b, k)];
    } else {
        assert k != a && k != b;
        assert SwapIndex(a, b, k) == k;
        assert s1[k] == s[k];
        assert s2[k] == s1[k];
        assert s2[k] == s[k];
        assert s[SwapIndex(a, b, k)] == s[k];
        assert s2[k] == s[SwapIndex(a, b, k)];
    }
    assert Swap(s, a, b)[k] == s2[k];
    assert s2[k] == s[SwapIndex(a, b, k)];
    assert Swap(s, a, b)[k] == s[SwapIndex(a, b, k)];
}

lemma SwapAt(s: seq<int>, a: int, b: int, k: int)
    requires 0 <= a < |s| && 0 <= b < |s|
    requires 0 <= k < |s|
    ensures |Swap(s, a, b)| == |s|
    ensures Swap(s, a, b)[k] == s[SwapIndex(a, b, k)]
    ensures k == a ==> Swap(s, a, b)[k] == s[b]
    ensures (k != a && k == b) ==> Swap(s, a, b)[k] == s[a]
    ensures (k != a && k != b) ==> Swap(s, a, b)[k] == s[k]
{
    SwapReflects(s, a, b, k);
    SwapIndexCases(a, b, k);
    if k == a {
        assert SwapIndex(a, b, k) == b;
        assert Swap(s, a, b)[k] == s[b];
    } else if k == b {
        assert k != a;
        assert SwapIndex(a, b, k) == a;
        assert Swap(s, a, b)[k] == s[a];
    } else {
        assert k != a && k != b;
        assert SwapIndex(a, b, k) == k;
        assert Swap(s, a, b)[k] == s[k];
    }
}

lemma SwapIndexInRange(a: int, b: int, n: int, k: int)
    requires 0 <= a < n && 0 <= b < n && 0 <= k < n
    ensures 0 <= SwapIndex(a, b, k) < n
{
    SwapIndexCases(a, b, k);
    if k == a {
        assert SwapIndex(a, b, k) == b;
        assert 0 <= b < n;
        assert 0 <= SwapIndex(a, b, k) < n;
    } else if k == b {
        assert k != a;
        assert SwapIndex(a, b, k) == a;
        assert 0 <= a < n;
        assert 0 <= SwapIndex(a, b, k) < n;
    } else {
        assert k != a && k != b;
        assert SwapIndex(a, b, k) == k;
        assert 0 <= k < n;
        assert 0 <= SwapIndex(a, b, k) < n;
    }
}

lemma {:vcs_split_on_every_assert} SwapIndexInj(a: int, b: int, i: int, j: int)
    requires i != j
    ensures SwapIndex(a, b, i) != SwapIndex(a, b, j)
{
    SwapIndexCases(a, b, i);
    SwapIndexCases(a, b, j);
    if i == a {
        assert SwapIndex(a, b, i) == b;
        if j == a {
            assert i == j;
            assert false;
        } else if j == b {
            assert j != a;
            assert b != a;
            assert a != b;
            assert SwapIndex(a, b, j) == a;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        } else {
            assert j != a && j != b;
            assert SwapIndex(a, b, j) == j;
            assert j != b;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        }
    } else if i == b {
        assert i != a;
        assert b != a;
        assert a != b;
        assert SwapIndex(a, b, i) == a;
        if j == a {
            assert SwapIndex(a, b, j) == b;
            assert a != b;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        } else if j == b {
            assert i == j;
            assert false;
        } else {
            assert j != a && j != b;
            assert SwapIndex(a, b, j) == j;
            assert j != a;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        }
    } else {
        assert i != a && i != b;
        assert SwapIndex(a, b, i) == i;
        if j == a {
            assert SwapIndex(a, b, j) == b;
            assert i != b;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        } else if j == b {
            assert j != a;
            assert SwapIndex(a, b, j) == a;
            assert i != a;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        } else {
            assert j != a && j != b;
            assert SwapIndex(a, b, j) == j;
            assert i != j;
            assert SwapIndex(a, b, i) != SwapIndex(a, b, j);
        }
    }
}

lemma {:vcs_split_on_every_assert} SwapPerm(p: seq<int>, n: int, a: int, b: int)
    requires is_valid_index_permutation(p, n)
    requires 0 <= a < n && 0 <= b < n
    ensures is_valid_index_permutation(Swap(p, a, b), n)
{
    var q := Swap(p, a, b);
    assert |p| == n;
    assert |q| == n;

    forall i | 0 <= i < n
        ensures 0 <= q[i] < n
    {
        SwapReflects(p, a, b, i);
        SwapIndexInRange(a, b, n, i);
        var r := SwapIndex(a, b, i);
        assert 0 <= r < n;
        assert q[i] == p[r];
        assert 0 <= p[r] < n;
        assert 0 <= q[i] < n;
    }

    forall i, j | 0 <= i < j < n
        ensures q[i] != q[j]
    {
        var ri := SwapIndex(a, b, i);
        var rj := SwapIndex(a, b, j);
        SwapIndexInj(a, b, i, j);
        SwapIndexInRange(a, b, n, i);
        SwapIndexInRange(a, b, n, j);
        SwapReflects(p, a, b, i);
        SwapReflects(p, a, b, j);
        assert ri == SwapIndex(a, b, i);
        assert rj == SwapIndex(a, b, j);
        assert ri != rj;
        assert 0 <= ri < n;
        assert 0 <= rj < n;
        assert q[i] == p[ri];
        assert q[j] == p[rj];
        if ri < rj {
            assert 0 <= ri < rj < n;
            assert p[ri] != p[rj];
        } else {
            assert !(ri < rj);
            assert ri != rj;
            assert rj < ri;
            assert 0 <= rj < ri < n;
            assert p[rj] != p[ri];
            assert p[ri] != p[rj];
        }
        assert q[i] != q[j];
    }

    assert forall i {:trigger q[i]} :: 0 <= i < n ==> 0 <= q[i] < n;
    assert forall i, j {:trigger q[i], q[j]} :: 0 <= i < j < n ==> q[i] != q[j];
    assert |q| == n;
    assert is_valid_index_permutation(q, n);
}

lemma {:vcs_split_on_every_assert} SwapWitness(v: seq<int>, w: seq<int>, p: seq<int>, a: int, b: int)
    requires IsWitness(v, w, p)
    requires 0 <= a < |w| && 0 <= b < |w|
    ensures IsWitness(v, Swap(w, a, b), Swap(p, a, b))
{
    assert is_valid_index_permutation(p, |v|);
    assert |v| == |w|;
    assert |p| == |v|;
    assert forall i {:trigger p[i]} :: 0 <= i < |v| ==> w[i] == v[p[i]];
    assert 0 <= a < |p| && 0 <= b < |p|;
    var w2 := Swap(w, a, b);
    var p2 := Swap(p, a, b);
    assert |w2| == |w|;
    assert |v| == |w2|;
    SwapPerm(p, |v|, a, b);
    assert p2 == Swap(p, a, b);
    assert is_valid_index_permutation(p2, |v|);

    forall i | 0 <= i < |v|
        ensures w2[i] == v[p2[i]]
    {
        SwapReflects(w, a, b, i);
        SwapReflects(p, a, b, i);
        SwapIndexInRange(a, b, |v|, i);
        var r := SwapIndex(a, b, i);
        assert 0 <= r < |v|;
        assert w2[i] == w[r];
        assert p2[i] == p[r];
        assert w[r] == v[p[r]];
        assert w2[i] == v[p[r]];
        assert p[r] == p2[i];
        assert w2[i] == v[p2[i]];
    }

    assert forall i {:trigger p2[i]} :: 0 <= i < |v| ==> w2[i] == v[p2[i]];
    assert is_valid_index_permutation(p2, |v|);
    assert |v| == |w2|;
    assert IsWitness(v, w2, p2);
    assert w2 == Swap(w, a, b);
    assert p2 == Swap(p, a, b);
    assert IsWitness(v, Swap(w, a, b), Swap(p, a, b));
}

lemma {:vcs_split_on_every_assert} InitWitness(v: seq<int>, p: seq<int>)
    requires p == seq(|v|, IdFun)
    ensures IsWitness(v, v, p)
{
    var n := |v|;
    assert n == |v|;
    assert p == seq(n, IdFun);
    assert |p| == n;
    forall k | 0 <= k < n
        ensures p[k] == k
    {
        assert seq(n, IdFun)[k] == IdFun(k);
        assert p[k] == seq(n, IdFun)[k];
        assert IdFun(k) == k;
        assert p[k] == k;
    }
    assert forall k :: 0 <= k < n ==> p[k] == k;
    forall k | 0 <= k < n
        ensures 0 <= p[k] < n
    {
        assert p[k] == k;
        assert 0 <= p[k] < n;
    }
    forall i, j | 0 <= i < j < n
        ensures p[i] != p[j]
    {
        assert p[i] == i;
        assert p[j] == j;
        assert i != j;
        assert p[i] != p[j];
    }
    assert forall k {:trigger p[k]} :: 0 <= k < n ==> 0 <= p[k] < n;
    assert forall i, j {:trigger p[i], p[j]} :: 0 <= i < j < n ==> p[i] != p[j];
    assert is_valid_index_permutation(p, n);
    assert is_valid_index_permutation(p, |v|);
    forall k | 0 <= k < n
        ensures v[k] == v[p[k]]
    {
        assert p[k] == k;
        assert v[k] == v[p[k]];
    }
    assert forall i {:trigger p[i]} :: 0 <= i < |v| ==> v[i] == v[p[i]];
    assert |v| == |v|;
    assert IsWitness(v, v, p);
}

lemma {:vcs_split_on_every_assert} WitnessImpliesPerm(v1: seq<int>, v2: seq<int>, p: seq<int>)
    requires IsWitness(v1, v2, p)
    ensures is_permutation(v1, v2)
{
    assert is_valid_index_permutation(p, |v1|);
    assert |v1| == |v2|;
    assert forall i {:trigger p[i]} :: 0 <= i < |v1| ==> v2[i] == v1[p[i]];
    var q := p;
    assert q == p;
    assert is_valid_index_permutation(q, |v1|);
    forall i | 0 <= i < |v1|
        ensures v2[i] == v1[q[i]]
    {
        assert q[i] == p[i];
        assert v2[i] == v1[p[i]];
        assert v2[i] == v1[q[i]];
    }
    assert forall i {:trigger q[i]} :: 0 <= i < |v1| ==> v2[i] == v1[q[i]];
    assert is_valid_index_permutation(q, |v1|) && |v1| == |v2| && (forall i {:trigger q[i]} :: 0 <= i < |v1| ==> v2[i] == v1[q[i]]);
    assert exists q2: seq<int> ::
        q2 == q
        && is_valid_index_permutation(q2, |v1|)
        && |v1| == |v2|
        && (forall i {:trigger q2[i]} :: 0 <= i < |v1| ==> v2[i] == v1[q2[i]]);
    assert is_permutation(v1, v2);
}

lemma {:vcs_split_on_every_assert} BubbleStep(s: seq<int>, j: int, i: int)
    requires 0 < j <= i < |s|
    requires s[j - 1] > s[j]
    requires is_sorted(s[..j])
    requires is_sorted(s[j..(i + 1)])
    requires forall m, n {:trigger s[m], s[n]} :: 0 <= m < j && j < n <= i ==> s[m] <= s[n]
    ensures is_sorted(Swap(s, j - 1, j)[..(j - 1)])
    ensures is_sorted(Swap(s, j - 1, j)[(j - 1)..(i + 1)])
    ensures forall m, n {:trigger Swap(s, j - 1, j)[m], Swap(s, j - 1, j)[n]} ::
        0 <= m < j - 1 && j - 1 < n <= i ==> Swap(s, j - 1, j)[m] <= Swap(s, j - 1, j)[n]
{
    assert 0 <= j - 1;
    assert j - 1 < j;
    assert j < |s|;
    assert j <= |s|;
    assert i + 1 <= |s|;
    assert j - 1 != j;
    GtFlip(s[j - 1], s[j]);
    assert s[j] <= s[j - 1];

    var w := Swap(s, j - 1, j);
    assert |w| == |s|;
    assert w == Swap(s, j - 1, j);

    if j == 1 {
        EmptySorted(w);
        assert j - 1 == 0;
        assert is_sorted(w[..0]);
        assert is_sorted(w[..(j - 1)]);
    } else {
        assert j >= 2;
        assert j - 1 >= 1;
        forall x, y | 0 <= x < y < j - 1
            ensures w[x] <= w[y]
        {
            assert x < j - 1;
            assert y < j - 1;
            assert x != j - 1 && y != j - 1;
            assert x != j && y != j;
            assert 0 <= x < |w|;
            assert 0 <= y < |w|;
            SwapAt(s, j - 1, j, x);
            SwapAt(s, j - 1, j, y);
            assert w[x] == s[x];
            assert w[y] == s[y];
            assert 0 <= x < y < j;
            assert j <= |s|;
            PrefixLe(s, j, x, y);
            assert w[x] <= w[y];
        }
        assert forall x, y :: 0 <= x < y < j - 1 ==> w[x] <= w[y];
        assert 0 <= j - 1 <= |w|;
        ProveSortedSlice(w, 0, j - 1);
        assert is_sorted(w[0..(j - 1)]);
        PrefixAtZero(w, j - 1);
        assert w[..(j - 1)] == w[0..(j - 1)];
        SortedSame(w[0..(j - 1)], w[..(j - 1)]);
        assert is_sorted(w[..(j - 1)]);
    }
    assert is_sorted(w[..(j - 1)]);

    forall m, n | 0 <= m < j - 1 && j - 1 < n <= i
        ensures w[m] <= w[n]
    {
        if j == 1 {
            assert m < 0;
            assert false;
        } else {
            assert j >= 2;
            assert m < j - 1;
            assert m != j - 1 && m != j;
            assert 0 <= m < |w|;
            SwapAt(s, j - 1, j, m);
            assert w[m] == s[m];
            if n == j {
                assert 0 <= n < |w|;
                SwapAt(s, j - 1, j, n);
                assert n == j;
                assert n != j - 1;
                assert w[n] == s[j - 1];
                assert 0 <= m < j - 1;
                assert j - 1 < j;
                assert j <= |s|;
                PrefixLe(s, j, m, j - 1);
                assert s[m] <= s[j - 1];
                assert w[m] <= w[n];
            } else {
                assert n != j;
                assert n > j - 1;
                assert n >= j;
                assert n > j;
                assert n != j - 1;
                assert 0 <= n <= i;
                assert i < |s|;
                assert n < |s|;
                assert 0 <= n < |w|;
                SwapAt(s, j - 1, j, n);
                assert w[n] == s[n];
                assert 0 <= m < j;
                assert j < n <= i;
                assert s[m] <= s[n];
                assert w[m] <= w[n];
            }
        }
    }
    assert forall m, n {:trigger w[m], w[n]} :: 0 <= m < j - 1 && j - 1 < n <= i ==> w[m] <= w[n];
    assert w == Swap(s, j - 1, j);
    assert forall m, n {:trigger Swap(s, j - 1, j)[m], Swap(s, j - 1, j)[n]} ::
        0 <= m < j - 1 && j - 1 < n <= i ==> Swap(s, j - 1, j)[m] <= Swap(s, j - 1, j)[n];

    forall x, y | j - 1 <= x < y < i + 1
        ensures w[x] <= w[y]
    {
        assert 0 <= x < |w|;
        assert 0 <= y < |w|;
        assert y <= i;
        assert i < |s|;
        assert y < |s|;
        if x == j - 1 && y == j {
            SwapAt(s, j - 1, j, x);
            SwapAt(s, j - 1, j, y);
            assert x == j - 1;
            assert y == j;
            assert y != j - 1;
            assert w[x] == s[j];
            assert w[y] == s[j - 1];
            assert s[j] <= s[j - 1];
            assert w[x] <= w[y];
        } else if x == j - 1 {
            assert y != j;
            assert y > j - 1;
            assert y >= j;
            assert y > j;
            assert y < i + 1;
