        } else if x == j {
            assert y > j;
            assert y < i + 1;
            assert y <= i;
            assert y != j - 1 && y != j;
            SwapAt(s, j - 1, j, x);
            SwapAt(s, j - 1, j, y);
            assert x == j;
            assert x != j - 1;
            assert w[x] == s[j - 1];
            assert w[y] == s[y];
            assert 0 <= j - 1 < j;
            assert j < y <= i;
            assert s[j - 1] <= s[y];
            assert w[x] <= w[y];
        } else {
            assert x != j - 1;
            assert x != j;
            assert x > j - 1;
            assert x >= j;
            assert x > j;
            assert y > x;
