    SortedSame(s[j..(i + 1)], s[j..hi]);
    assert is_sorted(s[j..hi]);

    forall x, y | 0 <= x < y < hi
        ensures s[x] <= s[y]
    {
        if y < j {
            assert 0 <= x < y < j;
            assert j <= |s|;
            PrefixLe(s, j, x, y);
            assert s[x] <= s[y];
        } else if x >= j {
            assert j <= x < y < hi;
            assert hi <= |s|;
            SortedSliceIndex(s, j, hi, x, y);
            assert s[x] <= s[y];
        } else {
            assert x < j;
            assert y >= j;
            assert 0 <= x;
            assert j > x;
            assert j > 0;
            assert s[j - 1] <= s[j];
            if x < j - 1 {
                assert 0 <= x < j - 1 < j;
                assert j <= |s|;
                PrefixLe(s, j, x, j - 1);
                assert s[x] <= s[j - 1];
            } else {
                assert x < j;
