lemma TotalWeightNonNeg(selected: seq<bool>, weights: seq<int>)
  requires |selected| <= |weights|
  requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i]
  ensures total_weight(selected, weights) >= 0
  decreases |selected|
{
  if |selected| == 0 {
    assert total_weight(selected, weights) == 0;
  } else {
    assert |weights| > 0;
    NonNegSuffix(weights);
    assert |selected[1..]| == |selected| - 1;
    assert |weights[1..]| == |weights| - 1;
    assert |selected[1..]| <= |weights[1..]|;
    TotalWeightNonNeg(selected[1..], weights[1..]);
    WeightDecomp(selected, weights);
    if selected[0] {
      assert 0 <= weights[0];
      assert total_weight(selected, weights) ==
        weights[0] + total_weight(selected[1..], weights[1..]);
      assert total_weight(selected, weights) >= 0;
    } else {
      assert total_weight(selected, weights) ==
        total_weight(selected[1..], weights[1..]);
      assert total_weight(selected, weights) >= 0;
    }
  }
}

