      assert total_value(s, values) == values[0] + total_value(s[1..], v1);
      assert total_value(s, values) <= values[0] + takeBest;
      assert takeTotal == values[0] + takeBest;
      assert total_value(s, values) <= takeTotal;
      assert takeTotal <= best;
      assert total_value(s, values) <= best;
    } else {
      assert total_weight(s, weights) == total_weight(s[1..], weights[1..]);
      assert total_weight(s[1..], w1) == total_weight(s[1..], weights[1..]);
      assert total_weight(s, weights) == total_weight(s[1..], w1);
      assert total_weight(s[1..], w1) <= capacity;
      CloseStrategy(s[1..], w1, capacity);
      assert is_valid_strategy(s[1..], w1, capacity);
      assert total_value(s[1..], v1) <= skipBest;
      assert total_value(s, values) == total_value(s[1..], values[1..]);
      assert total_value(s[1..], values[1..]) == total_value(s[1..], v1);
      assert total_value(s, values) == total_value(s[1..], v1);
      assert total_value(s, values) <= skipBest;
      assert skipBest <= best;
      assert total_value(s, values) <= best;
    }
  }
}

method {:vcs_split_on_every_assert} KnapsackRec(
  weights: seq<int>,
  values: seq<int>,
  capacity: int
) returns (best: int, selected: seq<bool>)
  requires |weights| == |values|
  requires 0 <= capacity
  requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i]
  requires forall i :: 0 <= i < |values| ==> 0 <= values[i]
  ensures |selected| == |weights|
  ensures total_weight(selected, weights) <= capacity
  ensures total_value(selected, values) == best
  ensures best >= 0
  ensures forall s: seq<bool> {:trigger is_valid_strategy(s, weights, capacity)} ::
            is_valid_strategy(s, weights, capacity) ==> total_value(s, values) <= best
  decreases |weights|
{
  if |weights| == 0 {
    best := 0;
    selected := [];
    assert |selected| == |weights|;
    assert total_weight(selected, weights) == 0;
    assert total_weight(selected, weights) <= capacity;
    assert total_value(selected, values) == 0;
    assert total_value(selected, values) == best;
    assert best >= 0;
    forall s: seq<bool> | is_valid_strategy(s, weights, capacity)
      ensures total_value(s, values) <= best
    {
      OpenStrategy(s, weights, capacity);
      assert |s| == 0;
      assert s == [];
      assert total_value(s, values) == 0;
      assert total_value(s, values) <= best;
    }
    return;
  }

  assert |weights| > 0;
  assert |values| == |weights|;
  var w1 := weights[1..];
  var v1 := values[1..];
  assert w1 == weights[1..];
  assert v1 == values[1..];
  assert |w1| == |weights| - 1;
  assert |v1| == |values| - 1;
  assert |w1| == |v1|;

  forall i | 0 <= i < |w1|
    ensures 0 <= w1[i]
  {
    assert w1[i] == weights[i + 1];
    assert i + 1 < |weights|;
    assert 0 <= weights[i + 1];
  }
  forall i | 0 <= i < |v1|
    ensures 0 <= v1[i]
  {
    assert v1[i] == values[i + 1];
    assert i + 1 < |values|;
    assert 0 <= values[i + 1];
  }

  var skipBest, skipSel := KnapsackRec(w1, v1, capacity);
  assert |skipSel| == |w1|;
  assert total_weight(skipSel, w1) <= capacity;
  assert total_value(skipSel, v1) == skipBest;
  assert skipBest >= 0;

  forall s: seq<bool> | is_valid_strategy(s, w1, capacity)
    ensures total_value(s, v1) <= skipBest
  {
    assert is_valid_strategy(s, w1, capacity);
    assert total_value(s, v1) <= skipBest;
  }

  if weights[0] > capacity {
    best := skipBest;
