    assert selected == [false] + skipSel;
    assert |skipSel| == |weights[1..]|;
    assert |skipSel| == |values[1..]|;
    assert total_weight(skipSel, weights[1..]) == total_weight(skipSel, w1);
    assert total_weight(skipSel, weights[1..]) <= capacity;
    assert total_value(skipSel, values[1..]) == total_value(skipSel, v1);
    assert total_value(skipSel, values[1..]) == skipBest;
    SkipWitnessCorrect(weights, values, capacity, skipSel, selected, skipBest);
