    assert forall s: seq<bool> {:trigger is_valid_strategy(s, weights, capacity)} ::
      is_valid_strategy(s, weights, capacity) ==> total_value(s, values) <= best;
    return;
  }

  assert weights[0] <= capacity;
  var capTake := capacity - weights[0];
  assert capTake == capacity - weights[0];
  assert 0 <= capTake;

  var takeBest, takeSel := KnapsackRec(w1, v1, capTake);
  assert |takeSel| == |w1|;
  assert total_weight(takeSel, w1) <= capTake;
  assert total_value(takeSel, v1) == takeBest;
  assert takeBest >= 0;

  forall s: seq<bool> | is_valid_strategy(s, w1, capTake)
    ensures total_value(s, v1) <= takeBest
  {
    assert is_valid_strategy(s, w1, capTake);
    assert total_value(s, v1) <= takeBest;
  }

  assert 0 <= values[0];
  var takeTotal := values[0] + takeBest;
  assert takeTotal == values[0] + takeBest;
  assert takeTotal >= 0;

  if takeTotal >= skipBest {
