    assert total_weight(selected, weights) <= capacity;
    assert total_value(selected, values) == values[0] + takeBest;
    assert total_value(selected, values) == best;
    assert best >= 0;
    assert best >= skipBest;
    assert best >= takeTotal;
  } else {
    best := skipBest;
    selected := [false] + skipSel;
    assert selected == [false] + skipSel;
    assert |skipSel| == |weights[1..]|;
    assert |skipSel| == |values[1..]|;
    assert total_weight(skipSel, weights[1..]) == total_weight(skipSel, w1);
    assert total_weight(skipSel, weights[1..]) <= capacity;
    assert total_value(skipSel, values[1..]) == total_value(skipSel, v1);
    assert total_value(skipSel, values[1..]) == skipBest;
    SkipWitnessCorrect(weights, values, capacity, skipSel, selected, skipBest);
    assert |selected| == |weights|;
    assert total_weight(selected, weights) <= capacity;
    assert total_value(selected, values) == best;
    assert best >= 0;
    assert best >= skipBest;
    assert takeTotal < skipBest;
    assert best >= takeTotal;
  }

  assert |selected| == |weights|;
  assert total_weight(selected, weights) <= capacity;
  assert total_value(selected, values) == best;
  assert best >= 0;
  assert best >= skipBest;
  assert best >= takeTotal;

  UpperLight(weights, values, capacity, w1, v1, skipBest, takeBest, takeTotal, capTake, best);
  assert forall s: seq<bool> {:trigger is_valid_strategy(s, weights, capacity)} ::
    is_valid_strategy(s, weights, capacity) ==> total_value(s, values) <= best;
}

method solve_knapsack_01(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
  requires |weights| == |values|
  requires |weights| <= 100 // Reasonable bound for recursion/verification time
  requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
  requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000 // Explicitly constrain non-negative weights
  requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000   // Explicitly constrain non-negative values
  ensures max_val >= 0
  ensures
    // 1. Upper Bound
    forall selected: seq<bool> ::
      is_valid_strategy(selected, weights, capacity)
      ==> total_value(selected, values) <= max_val
  ensures
    // 2. Existence
    exists selected: seq<bool> ::
      is_valid_strategy(selected, weights, capacity)
      && total_value(selected, values) == max_val
{
