    ensures 0 <= weights[i]
  {
    assert 0 <= weights[i] <= 1000;
  }
  forall i | 0 <= i < |values|
    ensures 0 <= values[i]
  {
    assert 0 <= values[i] <= 1000;
  }
  assert 0 <= capacity;

  var best, chosen := KnapsackRec(weights, values, capacity);
  max_val := best;

  assert best >= 0;
  assert max_val >= 0;
  assert |chosen| == |weights|;
  assert total_weight(chosen, weights) <= capacity;
  CloseStrategy(chosen, weights, capacity);
  assert is_valid_strategy(chosen, weights, capacity);
  assert total_value(chosen, values) == best;
  assert total_value(chosen, values) == max_val;

  forall sel: seq<bool> | is_valid_strategy(sel, weights, capacity)
