  }

  assert exists selected: seq<bool> ::
    is_valid_strategy(selected, weights, capacity) &&
    total_value(selected, values) == max_val
  by {
    var selected := chosen;
    assert is_valid_strategy(selected, weights, capacity);
    assert total_value(selected, values) == max_val;
  }
}
