lemma FindCrossing(p: seq<int>, vis: set<int>) returns (k: int)
  requires |p| > 0 && p[0] in vis && p[|p| - 1] !in vis
  ensures 0 <= k < |p| - 1 && p[k] in vis && p[k+1] !in vis
{
  k := 0;
  while p[k+1] in vis
    invariant 0 <= k < |p| - 1
    invariant p[k] in vis
    decreases |p| - k
