      invariant !changed ==> visited == oldVis
      invariant changed ==> 0 <= wit < n && wit in visited && wit !in oldVis
      invariant !changed ==> forall j :: 0 <= j < i ==> (edges[j].0 in visited <==> edges[j].1 in visited)
    {
      var a := edges[i].0;
      var c := edges[i].1;
      if a in visited && c !in visited {
        assert edge_in_set(edges, a, c) by { assert edges[i].0 == a && edges[i].1 == c; }
        ConnectedAppend(edges, 0, a, c);
        visited := visited + {c};
        changed := true;
        wit := c;
      } else if c in visited && a !in visited {
        assert edge_in_set(edges, c, a) by { assert edges[i].0 == a && edges[i].1 == c; }
        ConnectedAppend(edges, 0, c, a);
        visited := visited + {a};
        changed := true;
        wit := a;
      }
      i := i + 1;
    }
    if changed {
      UnvisitedShrinks(n, oldVis, visited, wit);
    } else {
      assert visited == oldVis;
    }
  }
  b := forall x :: 0 <= x < n ==> x in visited;
  if b {
    SpanningFromRoot(g, edges);
  } else {
    NotSpanning(g, edges, visited);
  }
}

lemma FindCrossing(p: seq<int>, vis: set<int>) returns (k: int)
  requires |p| > 0 && p[0] in vis && p[|p| - 1] !in vis
  ensures 0 <= k < |p| - 1 && p[k] in vis && p[k+1] !in vis
{
  k := 0;
  while p[k+1] in vis
    invariant 0 <= k < |p| - 1
    invariant p[k] in vis
    decreases |p| - k
  {
    k := k + 1;
  }
}

lemma SpanningTreeExists(g: seq<seq<(int, int)>>) returns (t: seq<Edge>)
  requires |g| > 0
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
  requires graph_is_connected(g)
  ensures is_spanning_tree(g, t)
{
  var n := |g|;
  var visited: set<int> := {0};
  t := [];
  ConnectedRefl(t, 0);
  while exists v :: 0 <= v < n && v !in visited
    invariant forall x :: x in visited ==> 0 <= x < n
    invariant 0 in visited
    invariant |t| + 1 == |visited|
    invariant are_valid_edges(g, t)
    invariant forall x :: x in visited ==> edges_connected(t, 0, x)
    decreases Unvisited(n, visited)
  {
    var v :| 0 <= v < n && v !in visited;
    assert nodes_have_path(g, 0, v);
    var p :| |p| > 0 && p[0] == 0 && p[|p| - 1] == v && path_follows_graph(g, p);
    var k := FindCrossing(p, visited);
    assert graph_has_any_edge(g, p[k], p[k+1]);
    var a := p[k];
    var b := p[k+1];
    var i :| 0 <= a < |g| && 0 <= i < |g[a]| && g[a][i].0 == b;
    var w := g[a][i].1;
    assert 0 <= b < n;
    var e: Edge := (a, b, w);
    var t2 := t + [e];
    assert has_edge(g, a, b, w);
    assert are_valid_edges(g, t2) by {
      forall j | 0 <= j < |t2|
        ensures has_edge(g, t2[j].0, t2[j].1, t2[j].2)
      {
        if j < |t| {
          assert t2[j] == t[j];
        } else {
          assert t2[j] == e;
        }
      }
    }
    forall x | x in visited
      ensures edges_connected(t2, 0, x)
    {
      ConnectedExtend(t, e, 0, x);
    }
    assert edge_in_set(t2, a, b) by { assert t2[|t|] == e; }
    ConnectedAppend(t2, 0, a, b);
    CardAddOne(visited, b);
    UnvisitedShrinks(n, visited, visited + {b}, b);
    visited := visited + {b};
    t := t2;
  }
  assert forall x :: 0 <= x < n ==> x in visited;
  assert visited == Range(n);
  RangeCard(n);
  SpanningFromRoot(g, t);
}

method BuildEdges(g: seq<seq<(int, int)>>) returns (E: seq<Edge>)
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
  ensures forall k :: 0 <= k < |E| ==> has_edge(g, E[k].0, E[k].1, E[k].2) && 0 <= E[k].0 < |g| && 0 <= E[k].1 < |g|
  ensures forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> (u, g[u][i].0, g[u][i].1) in E
{
  E := [];
  var u := 0;
  while u < |g|
    invariant 0 <= u <= |g|
    invariant forall k :: 0 <= k < |E| ==> has_edge(g, E[k].0, E[k].1, E[k].2) && 0 <= E[k].0 < |g| && 0 <= E[k].1 < |g|
    invariant forall uu, i :: 0 <= uu < u && 0 <= i < |g[uu]| ==> (uu, g[uu][i].0, g[uu][i].1) in E
  {
    var j := 0;
    while j < |g[u]|
      invariant 0 <= j <= |g[u]|
      invariant forall k :: 0 <= k < |E| ==> has_edge(g, E[k].0, E[k].1, E[k].2) && 0 <= E[k].0 < |g| && 0 <= E[k].1 < |g|
      invariant forall uu, i :: 0 <= uu < u && 0 <= i < |g[uu]| ==> (uu, g[uu][i].0, g[uu][i].1) in E
      invariant forall i :: 0 <= i < j ==> (u, g[u][i].0, g[u][i].1) in E
    {
      assert has_edge(g, u, g[u][j].0, g[u][j].1);
      E := E + [(u, g[u][j].0, g[u][j].1)];
      j := j + 1;
    }
    u := u + 1;
  }
}

lemma AllInFromValid(g: seq<seq<(int, int)>>, E: seq<Edge>, s: seq<Edge>)
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> (u, g[u][i].0, g[u][i].1) in E
  requires are_valid_edges(g, s)
  ensures AllIn(s, E)
{
  forall k | 0 <= k < |s|
    ensures s[k] in E
  {
    assert has_edge(g, s[k].0, s[k].1, s[k].2);
    var u := s[k].0;
    var i :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == s[k].1 && g[u][i].1 == s[k].2;
    assert (u, g[u][i].0, g[u][i].1) in E;
    assert (u, g[u][i].0, g[u][i].1) == s[k];
  }
}

lemma AllInProps(g: seq<seq<(int, int)>>, E: seq<Edge>, s: seq<Edge>)
  requires forall k :: 0 <= k < |E| ==> has_edge(g, E[k].0, E[k].1, E[k].2) && 0 <= E[k].0 < |g| && 0 <= E[k].1 < |g|
  requires AllIn(s, E)
  ensures are_valid_edges(g, s)
  ensures forall j :: 0 <= j < |s| ==> 0 <= s[j].0 < |g| && 0 <= s[j].1 < |g|
{
  forall k | 0 <= k < |s|
    ensures has_edge(g, s[k].0, s[k].1, s[k].2) && 0 <= s[k].0 < |g| && 0 <= s[k].1 < |g|
  {
    assert s[k] in E;
    var idx :| 0 <= idx < |E| && E[idx] == s[k];
    assert has_edge(g, E[idx].0, E[idx].1, E[idx].2);
  }
}

lemma AllInAppend(E: seq<Edge>, s: seq<Edge>, x: Edge)
  requires AllIn(s, E) && x in E
  ensures AllIn(s + [x], E)
{
  forall k | 0 <= k < |s + [x]|
    ensures (s + [x])[k] in E
  {
    if k < |s| {
      assert (s + [x])[k] == s[k];
    } else {
      assert (s + [x])[k] == x;
    }
  }
}

lemma AllInTail(E: seq<Edge>, s: seq<Edge>)
  requires AllIn(s, E) && |s| > 0
  ensures AllIn(s[1..], E)
{
  forall k | 0 <= k < |s[1..]|
    ensures s[1..][k] in E
  {
    assert s[1..][k] == s[k+1];
  }
}

method Search(g: seq<seq<(int, int)>>, E: seq<Edge>, prefix: seq<Edge>, depth: nat, best0: seq<Edge>, found0: bool)
  returns (best: seq<Edge>, found: bool)
  requires |g| > 0
  requires forall k :: 0 <= k < |E| ==> has_edge(g, E[k].0, E[k].1, E[k].2) && 0 <= E[k].0 < |g| && 0 <= E[k].1 < |g|
  requires AllIn(prefix, E)
  requires |prefix| + depth == |g| - 1
  requires found0 ==> is_spanning_tree(g, best0)
  ensures found ==> is_spanning_tree(g, best)
  ensures found0 ==> found && total_weight(best) <= total_weight(best0)
  ensures forall s :: |s| == depth && AllIn(s, E) && is_spanning_tree(g, prefix + s) ==> found && total_weight(best) <= total_weight(prefix + s)
  decreases depth
{
  best, found := best0, found0;
  if depth == 0 {
    AllInProps(g, E, prefix);
    var ok := CheckSpanning(g, prefix);
    if ok {
      TWEq(prefix);
      if found { TWEq(best); }
      if !found || TW(prefix) < TW(best) {
        best := prefix;
        found := true;
      }
    }
    forall s | |s| == depth && AllIn(s, E) && is_spanning_tree(g, prefix + s)
      ensures found && total_weight(best) <= total_weight(prefix + s)
    {
      assert s == [];
      assert prefix + s == prefix;
    }
  } else {
    var i := 0;
    while i < |E|
      invariant 0 <= i <= |E|
      invariant found ==> is_spanning_tree(g, best)
      invariant found0 ==> found && total_weight(best) <= total_weight(best0)
      invariant forall s :: |s| == depth && AllIn(s, E) && s[0] in E[..i] && is_spanning_tree(g, prefix + s) ==> found && total_weight(best) <= total_weight(prefix + s)
    {
      ghost var oldBest, oldFound := best, found;
      var p2 := prefix + [E[i]];
      assert E[i] in E;
      AllInAppend(E, prefix, E[i]);
      best, found := Search(g, E, p2, depth - 1, best, found);
      forall s | |s| == depth && AllIn(s, E) && s[0] in E[..i+1] && is_spanning_tree(g, prefix + s)
        ensures found && total_weight(best) <= total_weight(prefix + s)
      {
        assert E[..i+1] == E[..i] + [E[i]];
        if s[0] in E[..i] {
          assert oldFound && total_weight(oldBest) <= total_weight(prefix + s);
        } else {
          assert s[0] == E[i];
          var rest := s[1..];
          AllInTail(E, s);
          assert s == [s[0]] + rest;
          assert p2 + rest == prefix + s;
          assert is_spanning_tree(g, p2 + rest);
          assert AllIn(rest, E);
        }
      }
      i := i + 1;
    }
    forall s | |s| == depth && AllIn(s, E) && is_spanning_tree(g, prefix + s)
      ensures found && total_weight(best) <= total_weight(prefix + s)
    {
      assert s[0] in E;
      assert E[..|E|] == E;
      assert s[0] in E[..i];
    }
  }
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  var g := graph.adj;
  assert view(graph) == g;
  assert |g| > 0;
  var E := BuildEdges(g);
  ghost var t := SpanningTreeExists(g);
  AllInFromValid(g, E, t);
  var best, found := Search(g, E, [], |g| - 1, [], false);
  assert [] + t == t;
  assert is_spanning_tree(g, [] + t);
  assert found;
  edges := best;
  forall other | is_spanning_tree(view(graph), other)
    ensures total_weight(edges) <= total_weight(other)
  {
    AllInFromValid(g, E, other);
    assert [] + other == other;
    assert is_spanning_tree(g, [] + other);
  }
}
