lemma bounded_set_cardinality(s: set<int>, n: nat)
    requires forall x: int :: x in s ==> 0 <= x < n
    ensures |s| <= n
    decreases n
{
    if n == 0 {
        assert s == {};
    } else {
        var t := s - {n - 1};
        assert forall x: int :: x in t ==> 0 <= x < n - 1;
        bounded_set_cardinality(t, n - 1);

        if n - 1 in s {
            assert s == t + {n - 1};
            assert n - 1 !in t;
            assert |s| == |t| + 1;
        } else {
            assert s == t;
        }
    }
}

lemma edge_membership_preserved_by_append(
    edges: seq<Edge>, e: Edge, u: int, v: int)
    requires edge_in_set(edges, u, v)
    ensures edge_in_set(edges + [e], u, v)
{
    var i :| 0 <= i < |edges| &&
        ((edges[i].0 == u && edges[i].1 == v) ||
         (edges[i].0 == v && edges[i].1 == u));

    assert (edges + [e])[i] == edges[i];
}

lemma connected_preserved_by_append(
    edges: seq<Edge>, e: Edge, u: int, v: int)
    requires edges_connected(edges, u, v)
    ensures edges_connected(edges + [e], u, v)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(edges, p);

    assert path_follows_edges(edges + [e], p) by {
        forall k: int | 0 <= k < |p| - 1
            ensures edge_in_set(edges + [e], p[k], p[k + 1])
        {
            assert edge_in_set(edges, p[k], p[k + 1]);
            edge_membership_preserved_by_append(
                edges, e, p[k], p[k + 1]);
        }
    }
}

lemma edge_connection_symmetric(
    edges: seq<Edge>, u: int, v: int)
    requires edges_connected(edges, u, v)
    ensures edges_connected(edges, v, u)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(edges, p);

    var q := seq(|p|, i => p[|p| - 1 - i]);

    assert |q| == |p|;
    assert q[0] == v;
    assert q[|q| - 1] == u;

    assert path_follows_edges(edges, q) by {
        forall k: int | 0 <= k < |q| - 1
            ensures edge_in_set(edges, q[k], q[k + 1])
        {
            var j := |p| - 2 - k;
            assert 0 <= j < |p| - 1;
            assert q[k] == p[j + 1];
            assert q[k + 1] == p[j];
            assert edge_in_set(edges, p[j], p[j + 1]);
            assert edge_in_set(edges, p[j + 1], p[j]);
        }
    }
}

lemma edge_connection_transitive(
    edges: seq<Edge>, u: int, v: int, z: int)
    requires edges_connected(edges, u, v)
    requires edges_connected(edges, v, z)
    ensures edges_connected(edges, u, z)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(edges, p);

    var q :| |q| > 0 &&
        q[0] == v &&
        q[|q| - 1] == z &&
        path_follows_edges(edges, q);

    var r := p + q[1..];

    assert |r| > 0;
    assert r[0] == u;
    assert r[|r| - 1] == z;

    assert path_follows_edges(edges, r) by {
        forall k: int | 0 <= k < |r| - 1
            ensures edge_in_set(edges, r[k], r[k + 1])
        {
            if k < |p| - 1 {
                assert r[k] == p[k];
                assert r[k + 1] == p[k + 1];
                assert edge_in_set(edges, p[k], p[k + 1]);
            } else if k == |p| - 1 {
                assert |q| > 1;
                assert r[k] == p[|p| - 1];
                assert r[k] == q[0];
                assert r[k + 1] == q[1];
                assert edge_in_set(edges, q[0], q[1]);
            } else {
                var j := k - |p| + 1;
                assert 1 <= j < |q| - 1;
                assert r[k] == q[j];
                assert r[k + 1] == q[j + 1];
                assert edge_in_set(edges, q[j], q[j + 1]);
            }
        }
    }
}

lemma spanning_tree_exists(graph: WeightedGraph)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    ensures exists edges: seq<Edge> ::
        is_spanning_tree(view(graph), edges)
{
    var g := view(graph);
    var n := |g|;
    var seen: set<int> := {0};
    var edges: seq<Edge> := [];

    assert n > 0;
    assert rooted_connected(edges, seen) by {
        forall x: int | x in seen
            ensures edges_connected(edges, 0, x)
        {
            assert x == 0;
            var p := [0];
            assert path_follows_edges(edges, p);
        }
    }

    while exists target: int :: 0 <= target < n && target !in seen
        invariant n > 0
        invariant 0 in seen
        invariant forall x: int :: x in seen ==> 0 <= x < n
        invariant |seen| <= n
        invariant rooted_connected(edges, seen)
        invariant are_valid_edges(g, edges)
        invariant |edges| == |seen| - 1
        decreases n - |seen|
    {
        var target :| 0 <= target < n && target !in seen;

        assert nodes_have_path(g, 0, target);
        var p :| |p| > 0 &&
            p[0] == 0 &&
            p[|p| - 1] == target &&
            path_follows_graph(g, p);

        assert p[0] in seen;
        assert p[|p| - 1] !in seen;
        assert |p| > 1;

        var idx := 1;
        while idx < |p| && p[idx] in seen
            invariant 1 <= idx <= |p|
            invariant forall j: int :: 0 <= j < idx ==> p[j] in seen
            decreases |p| - idx
        {
            idx := idx + 1;
        }

        assert idx < |p|;
        assert p[idx] !in seen;
        assert p[idx - 1] in seen;

        var u := p[idx - 1];
        var v := p[idx];

        assert graph_has_any_edge(g, u, v);
        var ai :| 0 <= u < |g| &&
            0 <= ai < |g[u]| &&
            g[u][ai].0 == v;

        var w := g[u][ai].1;
        assert has_edge(g, u, v, w);

        assert 0 <= v < n by {
            assert 0 <= u < |graph.adj|;
            assert 0 <= ai < |graph.adj[u]|;
            assert graph.adj[u][ai].0 == v;
        }

        var oldSeen := seen;
        var oldEdges := edges;
        var e: Edge := (u, v, w);

        edges := oldEdges + [e];
        seen := oldSeen + {v};

        assert v !in oldSeen;
        assert |seen| == |oldSeen| + 1;
        assert |edges| == |oldEdges| + 1;

        assert are_valid_edges(g, edges) by {
            forall k: int | 0 <= k < |edges|
                ensures has_edge(g, edges[k].0, edges[k].1, edges[k].2)
            {
                if k < |oldEdges| {
                    assert edges[k] == oldEdges[k];
                    assert has_edge(
                        g,
                        oldEdges[k].0,
                        oldEdges[k].1,
                        oldEdges[k].2);
                } else {
                    assert k == |oldEdges|;
                    assert edges[k] == e;
                    assert has_edge(g, u, v, w);
                }
            }
        }

        assert edge_in_set(edges, u, v) by {
            assert edges[|oldEdges|] == e;
        }

        assert edges_connected(edges, u, v) by {
            var uv := [u, v];
            assert path_follows_edges(edges, uv) by {
                forall k: int | 0 <= k < |uv| - 1
                    ensures edge_in_set(edges, uv[k], uv[k + 1])
                {
                    assert k == 0;
                }
            }
        }

        assert rooted_connected(edges, seen) by {
            forall x: int | x in seen
                ensures edges_connected(edges, 0, x)
            {
                if x == v {
                    assert edges_connected(oldEdges, 0, u);
                    connected_preserved_by_append(oldEdges, e, 0, u);
                    edge_connection_transitive(edges, 0, u, v);
                } else {
                    assert x in oldSeen;
                    assert edges_connected(oldEdges, 0, x);
                    connected_preserved_by_append(oldEdges, e, 0, x);
                }
            }
        }

        bounded_set_cardinality(seen, n);
    }

    assert forall x: int :: 0 <= x < n ==> x in seen;

    assert is_spanning(g, edges) by {
        forall u: int, v: int |
            0 <= u < |g| && 0 <= v < |g|
            ensures edges_connected(edges, u, v)
        {
            assert u in seen;
            assert v in seen;
            assert edges_connected(edges, 0, u);
            assert edges_connected(edges, 0, v);
            edge_connection_symmetric(edges, 0, u);
            edge_connection_transitive(edges, u, 0, v);
        }
    }

    assert |edges| == |g| - 1;
    assert is_spanning_tree(g, edges);
}

lemma valid_edges_weight_lower_bound(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires weights_bounded(g)
    requires are_valid_edges(g, edges)
    ensures total_weight(edges) >= -100_000 * |edges|
    decreases |edges|
{
    if |edges| != 0 {
        assert has_edge(
            g, edges[0].0, edges[0].1, edges[0].2);
        assert edges[0].2 >= -100_000;

        assert are_valid_edges(g, edges[1..]) by {
            forall k: int | 0 <= k < |edges[1..]|
                ensures has_edge(
                    g,
                    edges[1..][k].0,
                    edges[1..][k].1,
                    edges[1..][k].2)
            {
                assert edges[1..][k] == edges[k + 1];
                assert has_edge(
                    g,
                    edges[k + 1].0,
                    edges[k + 1].1,
                    edges[k + 1].2);
            }
        }

        valid_edges_weight_lower_bound(g, edges[1..]);
        assert |edges[1..]| == |edges| - 1;
    }
}

lemma minimum_spanning_tree_from_candidate(
    g: seq<seq<(int, int)>>,
    current: seq<Edge>,
    lower: int)
    requires weights_bounded(g)
    requires is_spanning_tree(g, current)
    requires total_weight(current) >= lower
    ensures exists best: seq<Edge> ::
        is_spanning_tree(g, best) &&
        (forall other: seq<Edge>
            {:trigger is_spanning_tree(g, other)} ::
            is_spanning_tree(g, other) ==>
                total_weight(best) <= total_weight(other))
    decreases total_weight(current) - lower
{
    if forall other: seq<Edge>
        {:trigger is_spanning_tree(g, other)} ::
        is_spanning_tree(g, other) ==>
            total_weight(current) <= total_weight(other)
    {
        assert exists best: seq<Edge> ::
            is_spanning_tree(g, best) &&
            (forall other: seq<Edge>
                {:trigger is_spanning_tree(g, other)} ::
                is_spanning_tree(g, other) ==>
                    total_weight(best) <= total_weight(other))
            by {
                assert is_spanning_tree(g, current);
            }
    } else {
        assert exists other: seq<Edge> ::
