        assert spec_get_depth(r, av).Some?;
        DepthNonneg(r, av);
        assert spec_get_depth(root, av) == Some(spec_get_depth(r, av).get + 1);
        forall x | is_common_ancestor(root, x, p, q)
          ensures spec_get_depth(root, x).Some? &&
