method lowest_common_ancestor(root: Tree, p: int, q: int)
    returns (res: Option<int>)
    requires p >= 0
    requires q >= 0
    requires contains(root, p)
    requires contains(root, q)
    requires tree_distinct(root)
    ensures res.Some?
    ensures is_common_ancestor(root, res.get, p, q)
    ensures forall x: int :: is_common_ancestor(root, x, p, q) ==>
        spec_get_depth(root, x).Some? &&
        spec_get_depth(root, res.get).Some? &&
        spec_get_depth(root, x).get <= spec_get_depth(root, res.get).get
    decreases root
{
    match root
    case Nil =>
        assert !contains(root, p);
        assert false;

    case Node(v, l, r) =>
        lca_distinct_facts(v, l, r, p);
        lca_distinct_facts(v, l, r, q);

        if v == p || v == q {
            res := Some(v);

            assert spec_get_subtree(root, v) == root;
            assert is_common_ancestor(root, v, p, q);
            assert spec_get_depth(root, v) == Some(0);

            forall x: int | is_common_ancestor(root, x, p, q)
                ensures spec_get_depth(root, x).Some? &&
                        spec_get_depth(root, res.get).Some? &&
                        spec_get_depth(root, x).get <=
                            spec_get_depth(root, res.get).get
            {
                lca_common_present(root, x, p, q);

                if x != v {
                    if contains(l, x) {
                        lca_common_left(v, l, r, x, p, q);
                        assert is_common_ancestor(l, x, p, q);
                        lca_common_present(l, x, p, q);

                        if v == p {
                            assert contains(l, v);
                            assert false;
                        } else {
                            assert v == q;
                            assert contains(l, v);
                            assert false;
                        }
                    } else {
                        assert contains(r, x);
                        lca_common_right(v, l, r, x, p, q);
                        assert is_common_ancestor(r, x, p, q);
                        lca_common_present(r, x, p, q);

                        if v == p {
                            assert contains(r, v);
                            assert false;
                        } else {
                            assert v == q;
                            assert contains(r, v);
                            assert false;
                        }
                    }
                }

                assert x == v;
                assert res.get == v;
                assert spec_get_depth(root, x) == Some(0);
                assert spec_get_depth(root, res.get) == Some(0);
            }
        } else if contains(l, p) && contains(l, q) {
            var subres := lowest_common_ancestor(l, p, q);
            res := subres;

            lca_common_present(l, res.get, p, q);
            assert contains(l, res.get);
            lca_common_left(v, l, r, res.get, p, q);
            assert is_common_ancestor(root, res.get, p, q);
            lca_depth_left(v, l, r, res.get);

            forall x: int | is_common_ancestor(root, x, p, q)
                ensures spec_get_depth(root, x).Some? &&
                        spec_get_depth(root, res.get).Some? &&
                        spec_get_depth(root, x).get <=
                            spec_get_depth(root, res.get).get
