                if x == v {
                    lca_depth_nonnegative(l, res.get);
                    lca_depth_left(v, l, r, res.get);

                    assert spec_get_depth(root, x) == Some(0);
                    assert spec_get_depth(l, res.get).get >= 0;
                    assert spec_get_depth(root, res.get).get ==
                           spec_get_depth(l, res.get).get + 1;
                } else if contains(l, x) {
                    lca_common_left(v, l, r, x, p, q);
                    assert is_common_ancestor(l, x, p, q);

                    assert spec_get_depth(l, x).Some?;
                    assert spec_get_depth(l, res.get).Some?;
                    assert spec_get_depth(l, x).get <=
                           spec_get_depth(l, res.get).get;

                    lca_depth_left(v, l, r, x);
                    lca_depth_left(v, l, r, res.get);

                    assert spec_get_depth(root, x).get ==
                           spec_get_depth(l, x).get + 1;
                    assert spec_get_depth(root, res.get).get ==
                           spec_get_depth(l, res.get).get + 1;
                } else {
                    assert contains(r, x);
                    lca_common_right(v, l, r, x, p, q);
                    assert is_common_ancestor(r, x, p, q);
                    lca_common_present(r, x, p, q);
                    assert contains(r, p);
                    assert false;
                }
            }
        } else if contains(r, p) && contains(r, q) {
            var subres := lowest_common_ancestor(r, p, q);
            res := subres;

            lca_common_present(r, res.get, p, q);
            assert contains(r, res.get);
            lca_common_right(v, l, r, res.get, p, q);
            assert is_common_ancestor(root, res.get, p, q);
            lca_depth_right(v, l, r, res.get);

            forall x: int | is_common_ancestor(root, x, p, q)
                ensures spec_get_depth(root, x).Some? &&
                        spec_get_depth(root, res.get).Some? &&
                        spec_get_depth(root, x).get <=
                            spec_get_depth(root, res.get).get
            {
                lca_common_present(root, x, p, q);

                if x == v {
                    lca_depth_nonnegative(r, res.get);
                    lca_depth_right(v, l, r, res.get);

                    assert spec_get_depth(root, x) == Some(0);
                    assert spec_get_depth(r, res.get).get >= 0;
                    assert spec_get_depth(root, res.get).get ==
