lemma kt_old_edge_preserved(
    edges: seq<Edge>,
    added: Edge,
    u: int,
    v: int)
    requires edge_in_set(edges, u, v)
    ensures edge_in_set(edges + [added], u, v)
{
    var i :| 0 <= i < |edges|
        && ((edges[i].0 == u && edges[i].1 == v)
            || (edges[i].0 == v && edges[i].1 == u));
    assert (edges + [added])[i] == edges[i];
}

lemma kt_added_edge_present(
    edges: seq<Edge>,
    u: int,
    v: int,
    w: int)
    ensures edge_in_set(edges + [(u, v, w)], u, v)
{
    assert 0 <= |edges| < |edges + [(u, v, w)]|;
    assert (edges + [(u, v, w)])[|edges|] == (u, v, w);
}

lemma kt_append_path(
    edges: seq<Edge>,
    p: seq<int>,
    a: int,
    x: int,
    w: int)
    requires |p| > 0
    requires p[|p| - 1] == a
    requires path_follows_edges(edges, p)
    ensures path_follows_edges(
        edges + [(a, x, w)], p + [x])
{
    forall k: int | 0 <= k < |p + [x]| - 1
        ensures edge_in_set(
            edges + [(a, x, w)],
            (p + [x])[k],
            (p + [x])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + [x])[k] == p[k];
            assert (p + [x])[k + 1] == p[k + 1];
            assert edge_in_set(edges, p[k], p[k + 1]);
            kt_old_edge_preserved(
                edges, (a, x, w), p[k], p[k + 1]);
        } else {
            assert k == |p| - 1;
            assert (p + [x])[k] == a;
            assert (p + [x])[k + 1] == x;
            kt_added_edge_present(edges, a, x, w);
        }
    }
}

lemma kt_prepend_path(
