    requires p[0] == a
    requires path_follows_edges(edges, p)
    ensures path_follows_edges(
        edges + [(a, x, w)], [x] + p)
{
    forall k: int | 0 <= k < |[x] + p| - 1
        ensures edge_in_set(
            edges + [(a, x, w)],
            ([x] + p)[k],
            ([x] + p)[k + 1])
    {
        if k == 0 {
            assert ([x] + p)[0] == x;
            assert ([x] + p)[1] == a;
            kt_added_edge_present(edges, a, x, w);
