    assert are_valid_edges(g, edges + [(a, x, w)]) by
    {
        forall k: int | 0 <= k < |edges + [(a, x, w)]|
            ensures has_edge(
                g,
                (edges + [(a, x, w)])[k].0,
                (edges + [(a, x, w)])[k].1,
                (edges + [(a, x, w)])[k].2)
