            if v == x {
                var q := [x];
                assert |q| > 0;
                assert q[0] == x;
                assert q[|q| - 1] == x;
                assert path_follows_edges(
                    edges + [(a, x, w)], q);
                assert edges_connected(
                    edges + [(a, x, w)], x, x);
            } else {
                assert v in vertices;
                assert edges_connected(edges, a, v);
                var p :| |p| > 0
                    && p[0] == a
                    && p[|p| - 1] == v
                    && path_follows_edges(edges, p);
                kt_prepend_path(edges, p, a, x, w);
                var q := [x] + p;
                assert |q| > 0;
                assert q[0] == x;
                assert q[|q| - 1] == v;
                assert path_follows_edges(
                    edges + [(a, x, w)], q);
                assert edges_connected(
                    edges + [(a, x, w)], x, v);
