}

lemma kt_minimum_tree(
    g: seq<seq<(int, int)>>,
    candidate: seq<Edge>)
    returns (result: seq<Edge>)
    requires |g| > 0
    requires weights_bounded(g)
    requires is_spanning_tree(g, candidate)
    ensures is_mst(g, result)
    decreases total_weight(candidate) + 100000 * (|g| - 1)
{
    kt_weight_lower_bound(g, candidate);
    assert |candidate| == |g| - 1;
    assert total_weight(candidate)
        + 100000 * (|g| - 1) >= 0;

    if forall other: seq<Edge>
        {:trigger is_spanning_tree(g, other)} ::
        is_spanning_tree(g, other)
        ==> total_weight(candidate) <= total_weight(other)
    {
        result := candidate;
        assert is_mst(g, result);
    } else {
        var other :| is_spanning_tree(g, other)
            && total_weight(other) < total_weight(candidate);

        kt_weight_lower_bound(g, other);
        assert |other| == |g| - 1;
        assert total_weight(other)
            + 100000 * (|g| - 1) >= 0;
        assert total_weight(other)
            + 100000 * (|g| - 1)
            < total_weight(candidate)
                + 100000 * (|g| - 1);

        result := kt_minimum_tree(g, other);
    }
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
