                edges + [(a, x, w)], q);
            assert edges_connected(
                edges + [(a, x, w)], u, x);
        } else {
            assert u in vertices;
            assert v in vertices;
            assert edges_connected(edges, u, v);
            var p :| |p| > 0
                && p[0] == u
                && p[|p| - 1] == v
                && path_follows_edges(edges, p);
            forall k: int | 0 <= k < |p| - 1
                ensures edge_in_set(
                    edges + [(a, x, w)], p[k], p[k + 1])
            {
                kt_old_edge_preserved(
                    edges, (a, x, w), p[k], p[k + 1]);
            }
            assert path_follows_edges(
                edges + [(a, x, w)], p);
            assert edges_connected(
                edges + [(a, x, w)], u, v);
        }
    }
}

lemma kt_crossing_index(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    vertices: set<int>,
    i: int)
    returns (k: int)
    requires |p| > 0
    requires path_follows_graph(g, p)
    requires 0 <= i < |p|
    requires p[i] in vertices
    requires p[|p| - 1] !in vertices
    ensures i <= k < |p| - 1
    ensures p[k] in vertices
    ensures p[k + 1] !in vertices
    ensures graph_has_any_edge(g, p[k], p[k + 1])
    decreases |p| - i
{
    assert i < |p| - 1;
    assert graph_has_any_edge(g, p[i], p[i + 1]);
    if p[i + 1] !in vertices {
        k := i;
    } else {
        k := kt_crossing_index(g, p, vertices, i + 1);
    }
}

lemma kt_find_crossing(
    graph: WeightedGraph,
    vertices: set<int>)
    returns (a: int, x: int, w: int)
    requires well_formed(graph)
    requires |view(graph)| > 0
    requires graph_is_connected(view(graph))
    requires vertices <= kt_nodes(view(graph))
    requires 0 in vertices
    requires vertices != kt_nodes(view(graph))
    ensures a in vertices
    ensures x in kt_nodes(view(graph))
    ensures x !in vertices
    ensures has_edge(view(graph), a, x, w)
{
    var target :| target in kt_nodes(view(graph))
        && target !in vertices;

    assert nodes_have_path(view(graph), 0, target);
    var p :| |p| > 0
        && p[0] == 0
        && p[|p| - 1] == target
        && path_follows_graph(view(graph), p);

    var k := kt_crossing_index(
        view(graph), p, vertices, 0);

    a := p[k];
    x := p[k + 1];

    assert graph_has_any_edge(view(graph), a, x);
    var i :| 0 <= a < |graph.adj|
        && 0 <= i < |graph.adj[a]|
        && graph.adj[a][i].0 == x;

    w := graph.adj[a][i].1;
    assert has_edge(view(graph), a, x, w);

    assert 0 <= graph.adj[a][i].0 < |graph.adj|;
    assert x in kt_nodes(view(graph));
}

lemma kt_build_tree(
    graph: WeightedGraph,
    vertices: set<int>,
    partial: seq<Edge>)
    returns (result: seq<Edge>)
    requires well_formed(graph)
    requires |view(graph)| > 0
    requires graph_is_connected(view(graph))
    requires kt_tree_state(view(graph), vertices, partial)
    ensures is_spanning_tree(view(graph), result)
    decreases |view(graph)| - |vertices|
{
    kt_nodes_cardinality(|view(graph)|);
    assert |kt_nodes(view(graph))| == |view(graph)|;

    if vertices == kt_nodes(view(graph)) {
        result := partial;

        assert is_spanning(view(graph), result) by
        {
            forall u: int, v: int
                | 0 <= u < |view(graph)|
                    && 0 <= v < |view(graph)|
                ensures edges_connected(result, u, v)
            {
                assert u in vertices;
                assert v in vertices;
            }
        }

        assert |result| == |view(graph)| - 1;
        assert is_spanning_tree(view(graph), result);
    } else {
        var a, x, w := kt_find_crossing(graph, vertices);
        kt_extend_state(
            view(graph), vertices, partial, a, x, w);

        var nextVertices := vertices + {x};
        var nextEdges := partial + [(a, x, w)];

        assert |nextVertices| == |vertices| + 1;
        result := kt_build_tree(
            graph, nextVertices, nextEdges);
    }
}

lemma kt_initial_state(graph: WeightedGraph)
    requires |view(graph)| > 0
    ensures kt_tree_state(view(graph), {0}, [])
{
    assert 0 in kt_nodes(view(graph));
    assert |{0}| == 1;
    assert 0 == |{0}| - 1;
    assert are_valid_edges(view(graph), []);

    forall u: int, v: int | u in {0} && v in {0}
        ensures edges_connected([], u, v)
    {
        assert u == 0;
        assert v == 0;
        var p := [0];
        assert |p| > 0;
        assert p[0] == 0;
        assert p[|p| - 1] == 0;
        assert path_follows_edges([], p);
        assert edges_connected([], 0, 0);
    }
}

lemma kt_weight_lower_bound(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires weights_bounded(g)
    requires are_valid_edges(g, edges)
    ensures total_weight(edges) >= -100000 * |edges|
    decreases |edges|
{
    if |edges| > 0 {
        assert has_edge(
            g, edges[0].0, edges[0].1, edges[0].2);
        assert edges[0].2 >= -100000;

        assert are_valid_edges(g, edges[1..]) by
        {
            forall k: int | 0 <= k < |edges[1..]|
                ensures has_edge(
                    g,
                    edges[1..][k].0,
                    edges[1..][k].1,
                    edges[1..][k].2)
            {
                assert edges[1..][k] == edges[k + 1];
            }
        }

        kt_weight_lower_bound(g, edges[1..]);
        assert |edges[1..]| == |edges| - 1;
    }
}

lemma kt_minimum_tree(
    g: seq<seq<(int, int)>>,
    candidate: seq<Edge>)
    returns (result: seq<Edge>)
    requires |g| > 0
    requires weights_bounded(g)
    requires is_spanning_tree(g, candidate)
    ensures is_mst(g, result)
    decreases total_weight(candidate) + 100000 * (|g| - 1)
{
    kt_weight_lower_bound(g, candidate);
    assert |candidate| == |g| - 1;
    assert total_weight(candidate)
        + 100000 * (|g| - 1) >= 0;

    if forall other: seq<Edge>
        {:trigger is_spanning_tree(g, other)} ::
        is_spanning_tree(g, other)
        ==> total_weight(candidate) <= total_weight(other)
    {
        result := candidate;
        assert is_mst(g, result);
    } else {
        var other :| is_spanning_tree(g, other)
            && total_weight(other) < total_weight(candidate);

        kt_weight_lower_bound(g, other);
        assert |other| == |g| - 1;
        assert total_weight(other)
            + 100000 * (|g| - 1) >= 0;
        assert total_weight(other)
            + 100000 * (|g| - 1)
            < total_weight(candidate)
                + 100000 * (|g| - 1);

        result := kt_minimum_tree(g, other);
    }
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
    kt_initial_state(graph);
    ghost var tree := kt_build_tree(graph, {0}, []);
    ghost var minimum := kt_minimum_tree(view(graph), tree);
    assert is_mst(view(graph), minimum);
    assert exists candidate: seq<Edge> ::
        is_mst(view(graph), candidate);
    edges :| is_mst(view(graph), edges);
}
