        ((row[k] * x[k]) % 2 + dot(row, x, k - 1)) % 2
    else
        dot(row, x, k - 1)
}

lemma DotEq(row: seq<int>, x: seq<int>, k: int)
    ensures dot(row, x, k) == spec_dot_product_gf2(row, x, k)
