method Search(matrix: seq<seq<int>>, b: seq<int>, prefix: seq<int>, n: int) returns (res: Option<seq<int>>)
    requires |matrix| > 0
    requires |matrix| == |b|
    requires n == |matrix[0]|
    requires |prefix| <= n
    requires is_binary_vector(prefix)
    decreases n - |prefix|
    ensures res.Some? ==> is_solution(matrix, b, res.value)
    ensures res.None? ==>
        forall x: seq<int> ::
            (|x| == n && is_binary_vector(x) && x[..|prefix|] == prefix)
            ==> !is_solution(matrix, b, x)
{
    if |prefix| == n {
        if forall i :: 0 <= i < |matrix| ==> dot(matrix[i], prefix, n - 1) == b[i] {
            forall i | 0 <= i < |matrix|
                ensures spec_dot_product_gf2(matrix[i], prefix, n - 1) == b[i]
            {
                DotEq(matrix[i], prefix, n - 1);
            }
            return Some(prefix);
        } else {
            ghost var i :| 0 <= i < |matrix| && dot(matrix[i], prefix, n - 1) != b[i];
            DotEq(matrix[i], prefix, n - 1);
            forall x: seq<int> | |x| == n && is_binary_vector(x) && x[..|prefix|] == prefix
                ensures !is_solution(matrix, b, x)
            {
                assert x == x[..|prefix|];
                assert x == prefix;
            }
            return None;
        }
    }
    var p0 := prefix + [0];
    assert is_binary_vector(p0);
    var r0 := Search(matrix, b, p0, n);
    if r0.Some? {
        return r0;
    }
    var p1 := prefix + [1];
    assert is_binary_vector(p1);
    var r1 := Search(matrix, b, p1, n);
    if r1.Some? {
        return r1;
    }
    forall x: seq<int> | |x| == n && is_binary_vector(x) && x[..|prefix|] == prefix
        ensures !is_solution(matrix, b, x)
    {
        var k := |prefix|;
        assert x[k] == 0 || x[k] == 1;
        assert x[..k+1] == x[..k] + [x[k]];
        if x[k] == 0 {
            assert x[..|p0|] == p0;
        } else {
            assert x[..|p1|] == p1;
        }
    }
    return None;
}

method solve_linear_system_gf2(matrix: seq<seq<int>>, b: seq<int>) returns (res: Option<seq<int>>)
    requires |matrix| > 0
    requires |matrix[0]| > 0
    requires |matrix| == |b|
    requires |matrix| <= 100
    requires |matrix[0]| <= 100
    requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
    requires is_binary_vector(b)

    ensures match res
        case Some(x) => is_solution(matrix, b, x)
        case None => 
            forall x: seq<int> :: 
                (|x| == |matrix[0]| && is_binary_vector(x)) 
                ==> !is_solution(matrix, b, x)
{
