    else
        calc_dot_product_gf2(row, x, k - 1)
}

lemma calc_dot_product_agrees(row: seq<int>, x: seq<int>, k: int)
    ensures calc_dot_product_gf2(row, x, k)
         == spec_dot_product_gf2(row, x, k)
    decreases if k < 0 then 0 else k + 1
{
    if k >= 0 {
        calc_dot_product_agrees(row, x, k - 1);
    }
}

function check_rows(
    a: seq<seq<int>>,
    b: seq<int>,
    x: seq<int>,
    i: nat
): bool
    requires |a| == |b|
    requires i <= |a|
    decreases |a| - i
{
    if i == |a| then
        true
    else
        calc_dot_product_gf2(a[i], x, |x| - 1) == b[i]
        && check_rows(a, b, x, i + 1)
}

lemma check_rows_sound(
    a: seq<seq<int>>,
    b: seq<int>,
    x: seq<int>,
    i: nat
)
    requires |a| == |b|
    requires i <= |a|
    requires check_rows(a, b, x, i)
    ensures forall j :: i <= j < |a| ==>
        spec_dot_product_gf2(a[j], x, |x| - 1) == b[j]
    decreases |a| - i
{
    if i < |a| {
