lemma {:vcs_split_on_every_assert} sum_decrement(s: seq<int>, k: int)
  requires 0 <= k < |s|
  ensures sum_seq(DecrAt(s, k)) == sum_seq(s) - 1
  decreases k
{
  assert DecrAt(s, k) == s[k := s[k] - 1];
  if k == 0 {
    slice_update_head(s, s[0] - 1);
    assert DecrAt(s, k)[1..] == s[1..];
    assert DecrAt(s, k)[0] == s[0] - 1;
    assert sum_seq(s) == s[0] + sum_seq(s[1..]);
    assert sum_seq(DecrAt(s, k)) == (s[0] - 1) + sum_seq(s[1..]);
  } else {
    slice_update_commute(s, k, s[k] - 1);
