lemma {:vcs_split_on_every_assert} find_positive(counts: seq<int>) returns (k: int)
  requires |counts| > 0
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires sum_seq(counts) > 0
  ensures 0 <= k < |counts|
  ensures counts[k] > 0
  decreases |counts|
{
  if counts[0] > 0 {
    k := 0;
  } else {
    assert counts[0] == 0;
    assert sum_seq(counts) == counts[0] + sum_seq(counts[1..]);
    assert sum_seq(counts[1..]) > 0;
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] >= 0
    {
      assert counts[1..][i] == counts[i + 1];
    }
    if |counts| == 1 {
      assert |counts[1..]| == 0;
      assert sum_seq(counts[1..]) == 0;
      assert sum_seq(counts) == 0;
      assert false;
      k := 0;
    } else {
      assert |counts| > 1;
      var kTail := find_positive(counts[1..]);
      k := kTail + 1;
      assert 0 <= kTail < |counts[1..]|;
      assert counts[k] == counts[kTail + 1];
      assert counts[kTail + 1] == counts[1..][kTail];
      assert counts[k] > 0;
    }
  }
}

