  requires forall i :: 0 <= i < |a| ==> a[i] == b[i]
  ensures a == b
{
  assert a == b;
}

lemma append_len<T>(s: seq<T>, x: T)
  ensures |(s + [x])| == |s| + 1
  ensures (s + [x])[|s|] == x
{
  assert |(s + [x])| == |s| + 1;
  assert (s + [x])[|s|] == x;
}

lemma append_prefix<T>(s: seq<T>, x: T, j: int)
  requires 0 <= j < |s|
  ensures (s + [x])[j] == s[j]
{
  assert (s + [x])[j] == s[j];
}

lemma zeros_nonneg(n: int)
  requires n >= 0
  ensures |Zeros(n)| == n
  ensures forall i :: 0 <= i < n ==> Zeros(n)[i] == 0
{
  assert Zeros(n) == seq(n, i => 0);
  assert |seq(n, i => 0)| == n;
  forall i | 0 <= i < n
    ensures Zeros(n)[i] == 0
  {
    assert (seq(n, i2 => 0))[i] == 0;
    assert Zeros(n)[i] == 0;
  }
}

lemma zeros_tail(n: int)
  requires n > 0
  ensures Zeros(n)[1..] == Zeros(n - 1)
{
  zeros_nonneg(n);
  zeros_nonneg(n - 1);
  var a := Zeros(n)[1..];
  var b := Zeros(n - 1);
  assert |a| == n - 1;
  assert |b| == n - 1;
  forall i | 0 <= i < n - 1
    ensures a[i] == b[i]
  {
    assert a[i] == Zeros(n)[i + 1];
    assert Zeros(n)[i + 1] == 0;
    assert b[i] == 0;
  }
  seq_equal(a, b);
}

lemma {:vcs_split_on_every_assert} dot_zeros(xs: seq<int>)
  ensures dot(Zeros(|xs|), xs) == 0
  decreases |xs|
{
  if |xs| == 0 {
    assert |Zeros(0)| == 0;
    assert dot(Zeros(0), xs) == 0;
  } else {
    zeros_nonneg(|xs|);
    zeros_tail(|xs|);
    assert |xs[1..]| == |xs| - 1;
    dot_zeros(xs[1..]);
    assert Zeros(|xs[1..]|) == Zeros(|xs| - 1);
    assert Zeros(|xs|)[0] == 0;
    assert Zeros(|xs|)[1..] == Zeros(|xs| - 1);
    assert dot(Zeros(|xs|), xs) == Zeros(|xs|)[0] * xs[0] + dot(Zeros(|xs|)[1..], xs[1..]);
    assert 0 * xs[0] == 0;
    assert dot(Zeros(|xs| - 1), xs[1..]) == 0;
    assert dot(Zeros(|xs|)[1..], xs[1..]) == dot(Zeros(|xs| - 1), xs[1..]);
    assert dot(Zeros(|xs|), xs) == 0;
  }
}

lemma {:vcs_split_on_every_assert} dot_eq_weight(counts: seq<int>, weights: seq<int>)
  requires |counts| <= |weights|
  ensures dot(counts, weights) == total_weight(counts, weights)
  decreases |counts|
{
  if |counts| == 0 {
    assert dot(counts, weights) == 0;
    assert total_weight(counts, weights) == 0;
  } else {
    dot_eq_weight(counts[1..], weights[1..]);
    assert dot(counts, weights) == counts[0] * weights[0] + dot(counts[1..], weights[1..]);
    assert total_weight(counts, weights) == counts[0] * weights[0] + total_weight(counts[1..], weights[1..]);
  }
}

