}

lemma mul_nonneg(a: int, b: int)
  requires a >= 0 && b >= 0
  ensures a * b >= 0
  decreases a
{
  if a == 0 {
    assert a * b == 0;
  } else {
    mul_nonneg(a - 1, b);
    assert a * b == (a - 1) * b + b;
    assert (a - 1) * b >= 0;
    assert a * b >= 0;
  }
}

lemma {:vcs_split_on_every_assert} dot_nonneg(counts: seq<int>, xs: seq<int>)
  requires |counts| <= |xs|
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires forall i :: 0 <= i < |counts| ==> xs[i] >= 0
  ensures dot(counts, xs) >= 0
  decreases |counts|
{
  if |counts| > 0 {
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] >= 0 && xs[1..][i] >= 0
    {
      assert counts[1..][i] == counts[i + 1];
      assert xs[1..][i] == xs[i + 1];
    }
    mul_nonneg(counts[0], xs[0]);
    dot_nonneg(counts[1..], xs[1..]);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
  }
}

lemma {:vcs_split_on_every_assert} slice_update_head(s: seq<int>, newv: int)
  requires |s| > 0
  ensures (s[0 := newv])[1..] == s[1..]
{
  var left := (s[0 := newv])[1..];
  var right := s[1..];
  assert |left| == |s| - 1;
  assert |right| == |s| - 1;
  forall idx | 0 <= idx < |left|
    ensures left[idx] == right[idx]
  {
    assert 0 <= idx + 1 < |s|;
    assert left[idx] == (s[0 := newv])[idx + 1];
    assert idx + 1 != 0;
    assert (s[0 := newv])[idx + 1] == s[idx + 1];
    assert right[idx] == s[idx + 1];
  }
  seq_equal(left, right);
}

lemma {:vcs_split_on_every_assert} slice_update_commute(s: seq<int>, k: int, newv: int)
  requires 0 < k < |s|
  ensures (s[k := newv])[1..] == s[1..][k - 1 := newv]
{
  var left := (s[k := newv])[1..];
  var right := s[1..][k - 1 := newv];
  assert |left| == |s| - 1;
  assert |s[1..]| == |s| - 1;
  assert 0 <= k - 1 < |s[1..]|;
  assert |right| == |s| - 1;
  forall idx | 0 <= idx < |left|
    ensures left[idx] == right[idx]
  {
    assert 0 <= idx + 1 < |s|;
    assert left[idx] == (s[k := newv])[idx + 1];
    if idx + 1 == k {
      assert left[idx] == newv;
      assert idx == k - 1;
      assert right[idx] == newv;
    } else {
      assert (s[k := newv])[idx + 1] == s[idx + 1];
      assert left[idx] == s[idx + 1];
      assert idx != k - 1;
      assert right[idx] == s[1..][idx];
      assert s[1..][idx] == s[idx + 1];
    }
  }
  seq_equal(left, right);
}

lemma incr_at_spec(counts: seq<int>, k: int)
  requires 0 <= k < |counts|
  ensures |IncrAt(counts, k)| == |counts|
  ensures IncrAt(counts, k)[k] == counts[k] + 1
  ensures forall i :: 0 <= i < |counts| && i != k ==> IncrAt(counts, k)[i] == counts[i]
{
  assert IncrAt(counts, k) == counts[k := counts[k] + 1];
  assert |counts[k := counts[k] + 1]| == |counts|;
  assert (counts[k := counts[k] + 1])[k] == counts[k] + 1;
  forall i | 0 <= i < |counts| && i != k
    ensures IncrAt(counts, k)[i] == counts[i]
  {
    assert (counts[k := counts[k] + 1])[i] == counts[i];
  }
}

lemma decr_at_spec(counts: seq<int>, k: int)
  requires 0 <= k < |counts|
  ensures |DecrAt(counts, k)| == |counts|
  ensures DecrAt(counts, k)[k] == counts[k] - 1
  ensures forall i :: 0 <= i < |counts| && i != k ==> DecrAt(counts, k)[i] == counts[i]
{
  assert DecrAt(counts, k) == counts[k := counts[k] - 1];
  assert |counts[k := counts[k] - 1]| == |counts|;
  assert (counts[k := counts[k] - 1])[k] == counts[k] - 1;
  forall i | 0 <= i < |counts| && i != k
    ensures DecrAt(counts, k)[i] == counts[i]
  {
    assert (counts[k := counts[k] - 1])[i] == counts[i];
  }
}

lemma {:vcs_split_on_every_assert} dot_increment(counts: seq<int>, xs: seq<int>, k: int)
  requires |counts| == |xs|
  requires 0 <= k < |counts|
  ensures dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[k]
  decreases k
{
  assert IncrAt(counts, k) == counts[k := counts[k] + 1];
  if k == 0 {
    slice_update_head(counts, counts[0] + 1);
    assert (counts[0 := counts[0] + 1])[1..] == counts[1..];
    assert IncrAt(counts, k)[1..] == counts[1..];
    assert IncrAt(counts, k)[0] == counts[0] + 1;
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(IncrAt(counts, k), xs) == (counts[0] + 1) * xs[0] + dot(counts[1..], xs[1..]);
    assert (counts[0] + 1) * xs[0] == counts[0] * xs[0] + xs[0];
    assert dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[0];
  } else {
    slice_update_commute(counts, k, counts[k] + 1);
    assert |counts| == |xs|;
    assert |counts[1..]| == |xs[1..]|;
    assert 0 <= k - 1 < |counts[1..]|;
    assert counts[k] == counts[1..][k - 1];
    assert xs[k] == xs[1..][k - 1];
    assert counts[k] + 1 == counts[1..][k - 1] + 1;
    assert counts[1..][k - 1 := counts[k] + 1] == counts[1..][k - 1 := counts[1..][k - 1] + 1];
    assert IncrAt(counts[1..], k - 1) == counts[1..][k - 1 := counts[1..][k - 1] + 1];
    assert (counts[k := counts[k] + 1])[1..] == counts[1..][k - 1 := counts[k] + 1];
    assert IncrAt(counts, k)[1..] == IncrAt(counts[1..], k - 1);
    assert IncrAt(counts, k)[0] == counts[0];
    dot_increment(counts[1..], xs[1..], k - 1);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(IncrAt(counts, k), xs) == counts[0] * xs[0] + dot(IncrAt(counts, k)[1..], xs[1..]);
    assert dot(IncrAt(counts[1..], k - 1), xs[1..]) == dot(counts[1..], xs[1..]) + xs[1..][k - 1];
    assert dot(IncrAt(counts, k)[1..], xs[1..]) == dot(counts[1..], xs[1..]) + xs[k];
    assert dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[k];
  }
}

lemma {:vcs_split_on_every_assert} dot_decrement(counts: seq<int>, xs: seq<int>, k: int)
  requires |counts| == |xs|
  requires 0 <= k < |counts|
  ensures dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[k]
  decreases k
{
  assert DecrAt(counts, k) == counts[k := counts[k] - 1];
  if k == 0 {
    slice_update_head(counts, counts[0] - 1);
    assert (counts[0 := counts[0] - 1])[1..] == counts[1..];
    assert DecrAt(counts, k)[1..] == counts[1..];
    assert DecrAt(counts, k)[0] == counts[0] - 1;
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(DecrAt(counts, k), xs) == (counts[0] - 1) * xs[0] + dot(counts[1..], xs[1..]);
    assert (counts[0] - 1) * xs[0] == counts[0] * xs[0] - xs[0];
    assert dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[0];
  } else {
    slice_update_commute(counts, k, counts[k] - 1);
    assert |counts[1..]| == |xs[1..]|;
    assert 0 <= k - 1 < |counts[1..]|;
    assert counts[k] == counts[1..][k - 1];
    assert xs[k] == xs[1..][k - 1];
    assert counts[k] - 1 == counts[1..][k - 1] - 1;
    assert counts[1..][k - 1 := counts[k] - 1] == counts[1..][k - 1 := counts[1..][k - 1] - 1];
    assert DecrAt(counts[1..], k - 1) == counts[1..][k - 1 := counts[1..][k - 1] - 1];
    assert (counts[k := counts[k] - 1])[1..] == counts[1..][k - 1 := counts[k] - 1];
    assert DecrAt(counts, k)[1..] == DecrAt(counts[1..], k - 1);
    assert DecrAt(counts, k)[0] == counts[0];
    dot_decrement(counts[1..], xs[1..], k - 1);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(DecrAt(counts, k), xs) == counts[0] * xs[0] + dot(DecrAt(counts, k)[1..], xs[1..]);
    assert dot(DecrAt(counts[1..], k - 1), xs[1..]) == dot(counts[1..], xs[1..]) - xs[1..][k - 1];
    assert dot(DecrAt(counts, k)[1..], xs[1..]) == dot(counts[1..], xs[1..]) - xs[k];
    assert dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[k];
  }
}

lemma total_weight_increment(counts: seq<int>, weights: seq<int>, k: int)
  requires |counts| == |weights|
