  ensures |counts| == |weights|
  ensures forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  ensures total_weight(counts, weights) <= cap
{
  assert |counts| == |weights|;
  assert forall i :: 0 <= i < |counts| ==> counts[i] >= 0;
  assert total_weight(counts, weights) <= cap;
}

lemma {:vcs_split_on_every_assert} increment_ok(
  base: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  k: int,
  cap: int,
  baseCap: int,
  baseVal: int
)
  requires |weights| == |values|
  requires 0 <= k < |weights|
  requires is_valid_strategy(base, weights, baseCap)
  requires total_value(base, values) == baseVal
  requires baseCap + weights[k] <= cap
  ensures is_valid_strategy(IncrAt(base, k), weights, cap)
  ensures total_value(IncrAt(base, k), values) == baseVal + values[k]
  ensures |IncrAt(base, k)| == |weights|
{
  open_valid(base, weights, baseCap);
  incr_at_spec(base, k);
  var nw := IncrAt(base, k);
  assert |nw| == |base|;
  assert |base| == |weights|;
  total_weight_increment(base, weights, k);
  total_value_increment(base, values, k);
  forall i | 0 <= i < |nw|
    ensures nw[i] >= 0
  {
    if i == k {
      assert nw[i] == base[i] + 1;
      assert base[i] >= 0;
    } else {
      assert nw[i] == base[i];
      assert base[i] >= 0;
    }
  }
  assert total_weight(nw, weights) == total_weight(base, weights) + weights[k];
  assert total_weight(base, weights) <= baseCap;
  assert total_weight(nw, weights) <= baseCap + weights[k];
  assert total_weight(nw, weights) <= cap;
  assert total_value(nw, values) == total_value(base, values) + values[k];
  assert total_value(nw, values) == baseVal + values[k];
  assert |nw| == |weights|;
  assert forall i :: 0 <= i < |nw| ==> nw[i] >= 0;
  assert is_valid_strategy(nw, weights, cap);
}

lemma {:vcs_split_on_every_assert} zeros_witness(weights: seq<int>, values: seq<int>, cap: int)
  requires |weights| == |values|
  requires cap >= 0
  ensures |Zeros(|weights|)| == |weights|
  ensures is_valid_strategy(Zeros(|weights|), weights, cap)
  ensures total_value(Zeros(|weights|), values) == 0
  ensures total_weight(Zeros(|weights|), weights) == 0
{
  var z := Zeros(|weights|);
  zeros_nonneg(|weights|);
  assert |z| == |weights|;
  dot_zeros(weights);
  dot_eq_weight(z, weights);
  assert dot(z, weights) == 0;
  assert total_weight(z, weights) == 0;
  dot_zeros(values);
  assert |values| == |weights|;
  assert Zeros(|values|) == z;
  dot_eq_value(z, values);
  assert dot(z, values) == 0;
  assert total_value(z, values) == 0;
  forall i | 0 <= i < |z|
    ensures z[i] >= 0
  {
    assert z[i] == 0;
  }
  assert forall i :: 0 <= i < |z| ==> z[i] >= 0;
  assert is_valid_strategy(z, weights, cap);
}

lemma open_dp_nonneg(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int, j: int)
  requires DpOK(dp, weights, values, c)
  requires 0 <= j <= c
  ensures |dp| == c + 1
  ensures j < |dp|
  ensures dp[j] >= 0
{
  assert |dp| == c + 1;
  assert j < |dp| && dp[j] >= 0;
}

lemma open_dp_step(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int, j: int, ii: int)
  requires DpOK(dp, weights, values, c)
  requires 0 <= j <= c
  requires 0 <= ii < |weights|
  requires weights[ii] <= j
  ensures ii < |values|
  ensures 0 <= j - weights[ii] < |dp|
  ensures j < |dp|
  ensures dp[j - weights[ii]] + values[ii] <= dp[j]
{
  assert 0 <= j - weights[ii] < |dp| && j < |dp| && ii < |values| &&
    dp[j - weights[ii]] + values[ii] <= dp[j];
}

lemma open_witness(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, c: int, j: int)
  requires WitnessState(dp, wit, weights, values, c)
  requires 0 <= j <= c
  ensures |dp| == c + 1 && |wit| == c + 1
  ensures j < |wit| && j < |dp|
  ensures |wit[j]| == |weights| && |wit[j]| == |values|
  ensures is_valid_strategy(wit[j], weights, j)
  ensures total_value(wit[j], values) == dp[j]
  ensures dp[j] >= 0
{
  assert |dp| == c + 1 && |wit| == c + 1;
  assert j < |wit| && j < |dp| &&
    |wit[j]| == |weights| &&
    |wit[j]| == |values| &&
    is_valid_strategy(wit[j], weights, j) &&
    total_value(wit[j], values) == dp[j] &&
    dp[j] >= 0;
}

lemma open_covered(dp: seq<int>, weights: seq<int>, values: seq<int>, next: int, best: int, i: int, t: int)
  requires 0 <= i <= |weights|
  requires CoveredPrefix(dp, weights, values, next, best, i)
  requires 0 <= t < i && weights[t] <= next
  ensures 0 <= next - weights[t] < |dp|
  ensures t < |values|
  ensures dp[next - weights[t]] + values[t] <= best
{
  assert 0 <= next - weights[t] < |dp| && t < |values| &&
    dp[next - weights[t]] + values[t] <= best;
}

lemma covered_empty(dp: seq<int>, weights: seq<int>, values: seq<int>, next: int, best: int)
  requires |weights| >= 0
  ensures CoveredPrefix(dp, weights, values, next, best, 0)
{
  forall t | 0 <= t < 0 && weights[t] <= next
    ensures 0 <= next - weights[t] < |dp| && t < |values| &&
            dp[next - weights[t]] + values[t] <= best
  {
    assert false;
  }
}

lemma covered_same(dp: seq<int>, weights: seq<int>, values: seq<int>, next: int, b1: int, b2: int, i1: int, i2: int)
  requires 0 <= i1 <= |weights|
  requires 0 <= i2 <= |weights|
  requires b1 == b2 && i1 == i2
  requires CoveredPrefix(dp, weights, values, next, b1, i1)
  ensures CoveredPrefix(dp, weights, values, next, b2, i2)
{
  forall t | 0 <= t < i2 && weights[t] <= next
    ensures 0 <= next - weights[t] < |dp| && t < |values| &&
            dp[next - weights[t]] + values[t] <= b2
  {
    assert 0 <= t < i1;
    open_covered(dp, weights, values, next, b1, i1, t);
    assert b1 == b2;
  }
}

lemma {:vcs_split_on_every_assert} covered_extend(
  dp: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  next: int,
  prevBest: int,
  best: int,
  seen: int
)
  requires |weights| == |values|
  requires 0 <= seen < |weights|
  requires prevBest <= best
  requires CoveredPrefix(dp, weights, values, next, prevBest, seen)
  requires weights[seen] <= next ==>
      0 <= next - weights[seen] < |dp| &&
      dp[next - weights[seen]] + values[seen] <= best
  ensures CoveredPrefix(dp, weights, values, next, best, seen + 1)
{
  forall t | 0 <= t < seen + 1 && weights[t] <= next
    ensures 0 <= next - weights[t] < |dp| && t < |values| &&
            dp[next - weights[t]] + values[t] <= best
  {
    if t < seen {
      open_covered(dp, weights, values, next, prevBest, seen, t);
      assert dp[next - weights[t]] + values[t] <= prevBest;
      assert prevBest <= best;
      assert dp[next - weights[t]] + values[t] <= best;
    } else {
      assert t == seen;
      assert weights[seen] <= next;
      assert seen < |values|;
      assert 0 <= next - weights[seen] < |dp|;
      assert dp[next - weights[seen]] + values[seen] <= best;
    }
  }
}

lemma {:vcs_split_on_every_assert} initial_state(
  weights: seq<int>,
  values: seq<int>,
  dp: seq<int>,
  wit: seq<seq<int>>
)
  requires |weights| == |values|
  requires |weights| > 0
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires dp == [0]
  requires wit == [Zeros(|weights|)]
  ensures WitnessState(dp, wit, weights, values, 0)
  ensures DpOK(dp, weights, values, 0)
{
  zeros_witness(weights, values, 0);
  assert |dp| == 1;
  assert |wit| == 1;
  assert dp[0] == 0;
  assert wit[0] == Zeros(|weights|);
  assert is_valid_strategy(wit[0], weights, 0);
  assert total_value(wit[0], values) == 0;
  assert |wit[0]| == |weights|;
  assert |wit[0]| == |values|;

  assert forall j :: 0 <= j <= 0 ==>
      j < |wit| && j < |dp| &&
      |wit[j]| == |weights| &&
      |wit[j]| == |values| &&
      is_valid_strategy(wit[j], weights, j) &&
      total_value(wit[j], values) == dp[j] &&
      dp[j] >= 0
  by {
    forall j | 0 <= j <= 0
      ensures j < |wit| && j < |dp| &&
        |wit[j]| == |weights| &&
        |wit[j]| == |values| &&
        is_valid_strategy(wit[j], weights, j) &&
        total_value(wit[j], values) == dp[j] &&
        dp[j] >= 0
    {
      assert j == 0;
    }
  };
  assert WitnessState(dp, wit, weights, values, 0);

  assert forall j :: 0 <= j <= 0 ==> j < |dp| && dp[j] >= 0 by {
    forall j | 0 <= j <= 0
      ensures j < |dp| && dp[j] >= 0
    {
      assert j == 0;
      assert dp[0] == 0;
    }
  };
  forall j, ii | 0 <= j <= 0 && 0 <= ii < |weights| && weights[ii] <= j
    ensures 0 <= j - weights[ii] < |dp| && j < |dp| && ii < |values| &&
            dp[j - weights[ii]] + values[ii] <= dp[j]
  {
    assert weights[ii] > 0;
    assert j == 0;
    assert weights[ii] <= 0;
    assert false;
  }
  assert DpOK(dp, weights, values, 0);
}

lemma {:vcs_split_on_every_assert} step_state(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  next: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires WitnessState(dp, wit, weights, values, c)
  requires DpOK(dp, weights, values, c)
  requires next == c + 1
  requires best >= 0
  requires |bestWit| == |values|
  requires is_valid_strategy(bestWit, weights, next)
  requires total_value(bestWit, values) == best
  requires CoveredPrefix(dp, weights, values, next, best, |weights|)
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  ensures WitnessState(dpNext, witNext, weights, values, next)
  ensures DpOK(dpNext, weights, values, next)
{
  open_witness(dp, wit, weights, values, c, 0);
  append_len(dp, best);
  append_len(wit, bestWit);
  assert |dp| == c + 1;
  assert |wit| == c + 1;
  assert |dp| == next;
  assert |wit| == next;
  assert |dpNext| == |dp| + 1;
  assert |witNext| == |wit| + 1;
  assert |dpNext| == next + 1;
  assert |witNext| == next + 1;
  assert dpNext[|dp|] == best;
  assert witNext[|wit|] == bestWit;
  assert dpNext[next] == best;
  assert witNext[next] == bestWit;

  assert forall j :: 0 <= j <= next ==>
      j < |witNext| && j < |dpNext| &&
      |witNext[j]| == |weights| &&
      |witNext[j]| == |values| &&
      is_valid_strategy(witNext[j], weights, j) &&
      total_value(witNext[j], values) == dpNext[j] &&
      dpNext[j] >= 0
  by {
    forall j | 0 <= j <= next
      ensures j < |witNext| && j < |dpNext| &&
        |witNext[j]| == |weights| &&
        |witNext[j]| == |values| &&
        is_valid_strategy(witNext[j], weights, j) &&
        total_value(witNext[j], values) == dpNext[j] &&
        dpNext[j] >= 0
    {
      if j < next {
        assert 0 <= j <= c;
        open_witness(dp, wit, weights, values, c, j);
        append_prefix(dp, best, j);
        append_prefix(wit, bestWit, j);
        assert dpNext[j] == dp[j];
        assert witNext[j] == wit[j];
        assert j < |dpNext|;
        assert j < |witNext|;
      } else {
        assert j == next;
        assert witNext[j] == bestWit;
        assert dpNext[j] == best;
        assert |bestWit| == |weights|;
        assert j < |dpNext|;
        assert j < |witNext|;
        assert best >= 0;
      }
    }
  };
  assert WitnessState(dpNext, witNext, weights, values, next);

  assert forall j :: 0 <= j <= next ==> j < |dpNext| && dpNext[j] >= 0 by {
    forall j | 0 <= j <= next
      ensures j < |dpNext| && dpNext[j] >= 0
    {
      if j < next {
        open_dp_nonneg(dp, weights, values, c, j);
        append_prefix(dp, best, j);
        assert dpNext[j] == dp[j];
        assert j < |dpNext|;
      } else {
        assert j == next;
        assert dpNext[j] == best;
        assert j < |dpNext|;
      }
    }
  };

  assert forall j, ii ::
      0 <= j <= next && 0 <= ii < |weights| && weights[ii] <= j ==>
        0 <= j - weights[ii] < |dpNext| && j < |dpNext| && ii < |values| &&
        dpNext[j - weights[ii]] + values[ii] <= dpNext[j]
  by {
    forall j, ii | 0 <= j <= next && 0 <= ii < |weights| && weights[ii] <= j
      ensures 0 <= j - weights[ii] < |dpNext| && j < |dpNext| && ii < |values| &&
              dpNext[j - weights[ii]] + values[ii] <= dpNext[j]
    {
      if j < next {
        assert 0 <= j <= c;
        open_dp_step(dp, weights, values, c, j, ii);
        var idxx := j - weights[ii];
        assert 0 <= idxx < |dp|;
        append_prefix(dp, best, idxx);
        append_prefix(dp, best, j);
        assert dpNext[idxx] == dp[idxx];
        assert dpNext[j] == dp[j];
        assert idxx < |dpNext|;
        assert j < |dpNext|;
        assert dpNext[idxx] + values[ii] <= dpNext[j];
      } else {
        assert j == next;
        open_covered(dp, weights, values, next, best, |weights|, ii);
        var idxx := next - weights[ii];
        assert 0 <= idxx < |dp|;
        append_prefix(dp, best, idxx);
        assert dpNext[idxx] == dp[idxx];
        assert dpNext[next] == best;
        assert j < |dpNext|;
        assert idxx < |dpNext|;
        assert dpNext[idxx] + values[ii] <= dpNext[j];
        assert ii < |values|;
      }
    }
  };
  assert DpOK(dpNext, weights, values, next);
}

lemma {:vcs_split_on_every_assert} strategy_bounded(
  counts: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  cap: int,
  limit: int,
  dp: seq<int>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires |counts| == |weights|
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires total_weight(counts, weights) <= cap
  requires 0 <= cap <= limit
  requires DpOK(dp, weights, values, limit)
  ensures total_value(counts, values) <= dp[cap]
  decreases sum_seq(counts)
{
  sum_nonneg(counts);
  if sum_seq(counts) == 0 {
    all_zero_from_sum(counts);
    total_value_when_all_zero(counts, values);
    open_dp_nonneg(dp, weights, values, limit, cap);
    assert total_value(counts, values) == 0;
    assert dp[cap] >= 0;
    assert total_value(counts, values) <= dp[cap];
  } else {
    assert sum_seq(counts) > 0;
    if |counts| == 0 {
      assert sum_seq(counts) == 0;
      assert false;
    }
    assert |counts| > 0;
    var k := find_positive(counts);
    assert 0 <= k < |counts|;
    assert counts[k] > 0;
    assert counts[k] >= 1;
    assert 0 <= k < |weights|;
    var rest := DecrAt(counts, k);
    decr_at_spec(counts, k);
    assert |rest| == |counts|;
    forall i | 0 <= i < |rest|
      ensures rest[i] >= 0
    {
      if i == k {
        assert rest[i] == counts[i] - 1;
        assert rest[i] >= 0;
      } else {
        assert rest[i] == counts[i];
        assert rest[i] >= 0;
      }
    }
    forall i | 0 <= i < |weights|
      ensures weights[i] >= 0
    {
      assert weights[i] > 0;
    }
    assert forall i :: 0 <= i < |rest| ==> rest[i] >= 0;
    assert forall i :: 0 <= i < |weights| ==> weights[i] >= 0;
    total_weight_nonneg(rest, weights);
    total_weight_decrement(counts, weights, k);
    total_value_decrement(counts, values, k);
    assert total_weight(rest, weights) == total_weight(counts, weights) - weights[k];
    assert total_weight(counts, weights) == total_weight(rest, weights) + weights[k];
    assert total_weight(rest, weights) >= 0;
    assert total_weight(counts, weights) >= weights[k];
    assert weights[k] > 0;
    if cap < weights[k] {
      assert total_weight(counts, weights) <= cap;
      assert total_weight(counts, weights) >= weights[k];
      assert weights[k] > cap;
      assert false;
      assert total_value(counts, values) <= dp[cap];
    } else {
      assert weights[k] <= cap;
      var newCap := cap - weights[k];
      assert newCap >= 0;
      assert newCap <= cap;
      assert newCap <= limit;
      assert total_weight(rest, weights) <= cap - weights[k];
      assert total_weight(rest, weights) <= newCap;
      sum_decrement(counts, k);
      assert sum_seq(rest) == sum_seq(counts) - 1;
      assert sum_seq(rest) >= 0;
      assert sum_seq(rest) < sum_seq(counts);
      strategy_bounded(rest, weights, values, newCap, limit, dp);
      open_dp_step(dp, weights, values, limit, cap, k);
      assert total_value(rest, values) == total_value(counts, values) - values[k];
      assert total_value(counts, values) == total_value(rest, values) + values[k];
      assert total_value(rest, values) <= dp[newCap];
      assert newCap == cap - weights[k];
      assert dp[newCap] == dp[cap - weights[k]];
      assert dp[newCap] + values[k] <= dp[cap];
      assert total_value(counts, values) <= dp[newCap] + values[k];
      assert total_value(counts, values) <= dp[cap];
    }
  }
}

lemma {:vcs_split_on_every_assert} all_strategies_bounded(
  weights: seq<int>,
  values: seq<int>,
  capacity: int,
  dp: seq<int>,
  max_val: int
)
  requires |weights| == |values|
  requires |weights| > 0
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires 0 <= capacity
  requires DpOK(dp, weights, values, capacity)
  requires max_val == dp[capacity]
  ensures forall counts: seq<int> ::
      is_valid_strategy(counts, weights, capacity) ==>
        total_value(counts, values) <= max_val
{
  forall counts | is_valid_strategy(counts, weights, capacity)
    ensures total_value(counts, values) <= max_val
  {
    open_valid(counts, weights, capacity);
    strategy_bounded(counts, weights, values, capacity, capacity, dp);
    assert total_value(counts, values) <= dp[capacity];
    assert dp[capacity] == max_val;
  }
}

method {:vcs_split_on_every_assert} solve_knapsack_unbounded(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| > 0
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> weights[i] > 0 // Weights must be positive (> 0) to avoid infinite loops
    requires forall i :: 0 <= i < |weights| ==> weights[i] <= 1000
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000 // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            ==> total_value(counts, values) <= max_val
    ensures
        // 2. Existence
        exists counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            && total_value(counts, values) == max_val
{
  var dp: seq<int> := [0];
  ghost var wit: seq<seq<int>> := [Zeros(|weights|)];
  var c := 0;
  initial_state(weights, values, dp, wit);
  assert WitnessState(dp, wit, weights, values, 0);
  assert DpOK(dp, weights, values, 0);

  while c < capacity
    invariant 0 <= c <= capacity
    invariant WitnessState(dp, wit, weights, values, c)
    invariant DpOK(dp, weights, values, c)
    decreases capacity - c
  {
    assert WitnessState(dp, wit, weights, values, c);
    assert DpOK(dp, weights, values, c);
    var next := c + 1;
    assert c < capacity;
    assert next <= capacity;

    ghost var bestWit := Zeros(|weights|);
    var best := 0;
    zeros_witness(weights, values, next);
    assert bestWit == Zeros(|weights|);
    assert |bestWit| == |weights|;
    assert |bestWit| == |values|;
    assert total_value(bestWit, values) == 0;
    assert total_value(bestWit, values) == best;
    assert is_valid_strategy(bestWit, weights, next);
    assert best >= 0;
    covered_empty(dp, weights, values, next, best);
    assert CoveredPrefix(dp, weights, values, next, best, 0);

    var i := 0;
    while i < |weights|
      invariant 0 <= i <= |weights|
      invariant |bestWit| == |values|
      invariant total_value(bestWit, values) == best
      invariant best >= 0
      invariant is_valid_strategy(bestWit, weights, next)
      invariant CoveredPrefix(dp, weights, values, next, best, i)
      decreases |weights| - i
    {
      var seen := i;
      var prevBest := best;
      covered_same(dp, weights, values, next, best, prevBest, i, seen);
      assert CoveredPrefix(dp, weights, values, next, prevBest, seen);

      if weights[i] <= next {
        var idx := next - weights[i];
        assert weights[i] > 0;
        assert weights[i] >= 1;
        open_dp_nonneg(dp, weights, values, c, 0);
        assert |dp| == c + 1;
        assert next == c + 1;
        assert |dp| == next;
        assert 0 <= idx;
        assert idx <= next - 1;
        assert idx < |dp|;
        assert idx <= c;
        open_witness(dp, wit, weights, values, c, idx);
        assert total_value(wit[idx], values) == dp[idx];
        assert is_valid_strategy(wit[idx], weights, idx);
        assert |wit[idx]| == |weights|;
        assert 0 <= i < |wit[idx]|;
        var cand := dp[idx] + values[i];
        if cand > best {
          ghost var newWit := IncrAt(wit[idx], i);
          assert idx + weights[i] == next;
          assert idx + weights[i] <= next;
          increment_ok(wit[idx], weights, values, i, next, idx, dp[idx]);
          assert newWit == IncrAt(wit[idx], i);
          assert is_valid_strategy(newWit, weights, next);
          assert total_value(newWit, values) == dp[idx] + values[i];
          assert total_value(newWit, values) == cand;
          assert |newWit| == |weights|;
          assert |newWit| == |values|;
          bestWit := newWit;
          best := cand;
          assert total_value(bestWit, values) == best;
          assert is_valid_strategy(bestWit, weights, next);
          assert |bestWit| == |values|;
          assert best >= 0;
        }
        assert cand <= best;
        assert cand == dp[idx] + values[i];
        assert dp[idx] + values[i] <= best;
        assert idx == next - weights[i];
        assert 0 <= next - weights[i] < |dp|;
        assert dp[next - weights[i]] + values[i] <= best;
        assert |bestWit| == |values|;
        assert total_value(bestWit, values) == best;
        assert best >= 0;
        assert is_valid_strategy(bestWit, weights, next);
      } else {
