    assert (s[k := s[k] - 1])[1..] == s[1..][k - 1 := s[k] - 1];
    assert DecrAt(s, k)[1..] == DecrAt(s[1..], k - 1);
    assert DecrAt(s, k)[0] == s[0];
    sum_decrement(s[1..], k - 1);
    assert sum_seq(s) == s[0] + sum_seq(s[1..]);
    assert sum_seq(DecrAt(s, k)) == s[0] + sum_seq(DecrAt(s, k)[1..]);
    assert sum_seq(DecrAt(s[1..], k - 1)) == sum_seq(s[1..]) - 1;
    assert sum_seq(DecrAt(s, k)) == sum_seq(s) - 1;
  }
}

lemma {:vcs_split_on_every_assert} all_zero_from_sum(counts: seq<int>)
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires sum_seq(counts) == 0
  ensures forall i :: 0 <= i < |counts| ==> counts[i] == 0
  decreases |counts|
{
  if |counts| > 0 {
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] >= 0
    {
      assert counts[1..][i] == counts[i + 1];
    }
    sum_nonneg(counts[1..]);
    assert sum_seq(counts) == counts[0] + sum_seq(counts[1..]);
    assert counts[0] == 0;
    assert sum_seq(counts[1..]) == 0;
    all_zero_from_sum(counts[1..]);
    forall i | 0 <= i < |counts|
      ensures counts[i] == 0
    {
      if i == 0 {
        assert counts[i] == 0;
      } else {
        assert 0 <= i - 1 < |counts| - 1;
        assert counts[i] == counts[1..][i - 1];
        assert counts[1..][i - 1] == 0;
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} total_value_when_all_zero(counts: seq<int>, values: seq<int>)
  requires |counts| <= |values|
  requires forall i :: 0 <= i < |counts| ==> counts[i] == 0
  ensures total_value(counts, values) == 0
  decreases |counts|
{
  if |counts| > 0 {
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] == 0
    {
      assert counts[1..][i] == counts[i + 1];
    }
    total_value_when_all_zero(counts[1..], values[1..]);
    assert counts[0] == 0;
    assert total_value(counts, values) == 0 * values[0] + total_value(counts[1..], values[1..]);
    assert 0 * values[0] == 0;
  }
}

lemma {:vcs_split_on_every_assert} find_positive(counts: seq<int>) returns (k: int)
  requires |counts| > 0
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires sum_seq(counts) > 0
  ensures 0 <= k < |counts|
  ensures counts[k] > 0
  decreases |counts|
{
  if counts[0] > 0 {
    k := 0;
  } else {
    assert counts[0] == 0;
    assert sum_seq(counts) == counts[0] + sum_seq(counts[1..]);
    assert sum_seq(counts[1..]) > 0;
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] >= 0
    {
      assert counts[1..][i] == counts[i + 1];
    }
    if |counts| == 1 {
      assert |counts[1..]| == 0;
      assert sum_seq(counts[1..]) == 0;
      assert sum_seq(counts) == 0;
      assert false;
      k := 0;
    } else {
      assert |counts| > 1;
      var kTail := find_positive(counts[1..]);
      k := kTail + 1;
      assert 0 <= kTail < |counts[1..]|;
      assert counts[k] == counts[kTail + 1];
      assert counts[kTail + 1] == counts[1..][kTail];
      assert counts[k] > 0;
    }
  }
}

