  seen: int
)
  requires |weights| == |values|
  requires 0 <= seen < |weights|
  requires prevBest <= best
  requires CoveredPrefix(dp, weights, values, next, prevBest, seen)
  requires weights[seen] <= next ==>
      0 <= next - weights[seen] < |dp| &&
      dp[next - weights[seen]] + values[seen] <= best
  ensures CoveredPrefix(dp, weights, values, next, best, seen + 1)
{
  forall t | 0 <= t < seen + 1 && weights[t] <= next
    ensures 0 <= next - weights[t] < |dp| && t < |values| &&
            dp[next - weights[t]] + values[t] <= best
  {
    if t < seen {
      open_covered(dp, weights, values, next, prevBest, seen, t);
      assert dp[next - weights[t]] + values[t] <= prevBest;
      assert prevBest <= best;
      assert dp[next - weights[t]] + values[t] <= best;
    } else {
      assert t == seen;
      assert weights[seen] <= next;
      assert seen < |values|;
      assert 0 <= next - weights[seen] < |dp|;
      assert dp[next - weights[seen]] + values[seen] <= best;
    }
  }
}

