lemma {:vcs_split_on_every_assert} step_state(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  next: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires WitnessState(dp, wit, weights, values, c)
  requires DpOK(dp, weights, values, c)
  requires next == c + 1
  requires best >= 0
  requires |bestWit| == |values|
  requires is_valid_strategy(bestWit, weights, next)
  requires total_value(bestWit, values) == best
  requires CoveredPrefix(dp, weights, values, next, best, |weights|)
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  ensures WitnessState(dpNext, witNext, weights, values, next)
  ensures DpOK(dpNext, weights, values, next)
{
  open_witness(dp, wit, weights, values, c, 0);
  append_len(dp, best);
  append_len(wit, bestWit);
  assert |dp| == c + 1;
  assert |wit| == c + 1;
  assert |dp| == next;
  assert |wit| == next;
  assert |dpNext| == |dp| + 1;
  assert |witNext| == |wit| + 1;
  assert |dpNext| == next + 1;
  assert |witNext| == next + 1;
  assert dpNext[|dp|] == best;
  assert witNext[|wit|] == bestWit;
  assert dpNext[next] == best;
  assert witNext[next] == bestWit;
  assert |bestWit| == |weights|;

  forall j | 0 <= j <= next
    ensures j < |witNext| && j < |dpNext| &&
      |witNext[j]| == |weights| &&
      |witNext[j]| == |values| &&
      is_valid_strategy(witNext[j], weights, j) &&
      total_value(witNext[j], values) == dpNext[j] &&
      dpNext[j] >= 0
  {
    if j < next {
      assert 0 <= j <= c;
      open_witness(dp, wit, weights, values, c, j);
      append_prefix(dp, best, j);
      append_prefix(wit, bestWit, j);
      assert dpNext[j] == dp[j];
      assert witNext[j] == wit[j];
      assert j < |dpNext|;
      assert j < |witNext|;
      assert |witNext[j]| == |weights|;
      assert |witNext[j]| == |values|;
      assert is_valid_strategy(witNext[j], weights, j);
      assert total_value(witNext[j], values) == dpNext[j];
      assert dpNext[j] >= 0;
    } else {
      assert j == next;
      assert witNext[j] == bestWit;
      assert dpNext[j] == best;
      assert |bestWit| == |weights|;
      assert |bestWit| == |values|;
      assert j < |dpNext|;
      assert j < |witNext|;
      assert best >= 0;
      assert is_valid_strategy(bestWit, weights, next);
      assert is_valid_strategy(witNext[j], weights, j);
      assert total_value(bestWit, values) == best;
      assert total_value(witNext[j], values) == dpNext[j];
      assert dpNext[j] >= 0;
    }
  }
  assert WitnessState(dpNext, witNext, weights, values, next);

  forall j | 0 <= j <= next
    ensures j < |dpNext| && dpNext[j] >= 0
  {
    if j < next {
      open_dp_nonneg(dp, weights, values, c, j);
      append_prefix(dp, best, j);
      assert dpNext[j] == dp[j];
      assert j < |dpNext|;
      assert dpNext[j] >= 0;
    } else {
      assert j == next;
      assert dpNext[j] == best;
      assert j < |dpNext|;
      assert best >= 0;
      assert dpNext[j] >= 0;
    }
  }

  forall j, ii | 0 <= j <= next && 0 <= ii < |weights| && weights[ii] <= j
    ensures 0 <= j - weights[ii] < |dpNext| && j < |dpNext| && ii < |values| &&
            dpNext[j - weights[ii]] + values[ii] <= dpNext[j]
  {
    if j < next {
      assert 0 <= j <= c;
      open_dp_step(dp, weights, values, c, j, ii);
      var idxx := j - weights[ii];
      assert 0 <= idxx < |dp|;
      assert idxx == j - weights[ii];
      append_prefix(dp, best, idxx);
      append_prefix(dp, best, j);
      assert dpNext[idxx] == dp[idxx];
      assert dpNext[j] == dp[j];
      assert idxx < |dpNext|;
      assert j < |dpNext|;
      assert 0 <= j - weights[ii] < |dpNext|;
      assert ii < |values|;
      assert dpNext[idxx] + values[ii] <= dpNext[j];
      assert dpNext[j - weights[ii]] == dpNext[idxx];
      assert dpNext[j - weights[ii]] + values[ii] <= dpNext[j];
    } else {
      assert j == next;
      open_covered(dp, weights, values, next, best, |weights|, ii);
      var idxx := next - weights[ii];
      assert 0 <= idxx < |dp|;
      assert idxx == j - weights[ii];
      append_prefix(dp, best, idxx);
      assert dpNext[idxx] == dp[idxx];
      assert dpNext[next] == best;
      assert j < |dpNext|;
      assert idxx < |dpNext|;
      assert 0 <= j - weights[ii] < |dpNext|;
      assert dpNext[idxx] + values[ii] <= dpNext[j];
      assert dpNext[j - weights[ii]] == dpNext[idxx];
      assert dpNext[j - weights[ii]] + values[ii] <= dpNext[j];
      assert ii < |values|;
    }
  }
  assert DpOK(dpNext, weights, values, next);
}

lemma {:vcs_split_on_every_assert} strategy_bounded(
  counts: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  cap: int,
  limit: int,
  dp: seq<int>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires |counts| == |weights|
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires total_weight(counts, weights) <= cap
  requires 0 <= cap <= limit
  requires DpOK(dp, weights, values, limit)
  ensures total_value(counts, values) <= dp[cap]
  decreases sum_seq(counts)
{
  sum_nonneg(counts);
  if sum_seq(counts) == 0 {
    all_zero_from_sum(counts);
    total_value_when_all_zero(counts, values);
    open_dp_nonneg(dp, weights, values, limit, cap);
    assert total_value(counts, values) == 0;
    assert dp[cap] >= 0;
    assert total_value(counts, values) <= dp[cap];
  } else {
    assert sum_seq(counts) > 0;
    if |counts| == 0 {
      assert sum_seq(counts) == 0;
      assert false;
    }
    assert |counts| > 0;
    var k := find_positive(counts);
    assert 0 <= k < |counts|;
    assert counts[k] > 0;
    assert counts[k] >= 1;
    assert 0 <= k < |weights|;
    assert |counts| == |values|;
    var rest := DecrAt(counts, k);
    decr_at_spec(counts, k);
    assert |rest| == |counts|;
    forall i | 0 <= i < |rest|
      ensures rest[i] >= 0
    {
      if i == k {
        assert rest[i] == counts[i] - 1;
        assert rest[i] >= 0;
      } else {
        assert rest[i] == counts[i];
        assert rest[i] >= 0;
      }
    }
    forall i | 0 <= i < |weights|
      ensures weights[i] >= 0
    {
      assert weights[i] > 0;
    }
    assert forall i :: 0 <= i < |rest| ==> rest[i] >= 0;
    assert forall i :: 0 <= i < |weights| ==> weights[i] >= 0;
    total_weight_nonneg(rest, weights);
    total_weight_decrement(counts, weights, k);
    total_value_decrement(counts, values, k);
    assert total_weight(rest, weights) == total_weight(counts, weights) - weights[k];
    assert total_weight(counts, weights) == total_weight(rest, weights) + weights[k];
    assert total_weight(rest, weights) >= 0;
    assert total_weight(counts, weights) >= weights[k];
    assert weights[k] > 0;
    if cap < weights[k] {
      assert total_weight(counts, weights) <= cap;
      assert total_weight(counts, weights) >= weights[k];
      assert weights[k] > cap;
      assert false;
      assert total_value(counts, values) <= dp[cap];
    } else {
      assert weights[k] <= cap;
      var newCap := cap - weights[k];
      assert newCap >= 0;
      assert newCap <= cap;
      assert newCap <= limit;
      assert total_weight(rest, weights) <= cap - weights[k];
      assert total_weight(rest, weights) <= newCap;
      sum_decrement(counts, k);
      assert sum_seq(rest) == sum_seq(counts) - 1;
      assert sum_seq(rest) >= 0;
      assert sum_seq(rest) < sum_seq(counts);
      strategy_bounded(rest, weights, values, newCap, limit, dp);
      open_dp_step(dp, weights, values, limit, cap, k);
      assert total_value(rest, values) == total_value(counts, values) - values[k];
      assert total_value(counts, values) == total_value(rest, values) + values[k];
      assert total_value(rest, values) <= dp[newCap];
      assert newCap == cap - weights[k];
      assert dp[newCap] == dp[cap - weights[k]];
      assert dp[newCap] + values[k] <= dp[cap];
      assert total_value(counts, values) <= dp[newCap] + values[k];
      assert total_value(counts, values) <= dp[cap];
    }
  }
}

lemma {:vcs_split_on_every_assert} all_strategies_bounded(
  weights: seq<int>,
  values: seq<int>,
  capacity: int,
  dp: seq<int>,
  max_val: int
)
  requires |weights| == |values|
  requires |weights| > 0
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires 0 <= capacity
  requires DpOK(dp, weights, values, capacity)
  requires max_val == dp[capacity]
  ensures forall counts: seq<int> ::
      is_valid_strategy(counts, weights, capacity) ==>
        total_value(counts, values) <= max_val
{
  forall counts | is_valid_strategy(counts, weights, capacity)
    ensures total_value(counts, values) <= max_val
  {
    open_valid(counts, weights, capacity);
    strategy_bounded(counts, weights, values, capacity, capacity, dp);
    assert total_value(counts, values) <= dp[capacity];
    assert dp[capacity] == max_val;
  }
}

lemma {:vcs_split_on_every_assert} ProveExists(
  counts: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  capacity: int,
  max_val: int
)
  requires |weights| == |values|
  requires |counts| <= |values|
  requires is_valid_strategy(counts, weights, capacity)
  requires total_value(counts, values) == max_val
  ensures exists c: seq<int> ::
      is_valid_strategy(c, weights, capacity) &&
      total_value(c, values) == max_val
{
  var c := counts;
  assert is_valid_strategy(c, weights, capacity);
  assert total_value(c, values) == max_val;
  assert exists c2: seq<int> ::
      c2 == c &&
      is_valid_strategy(c2, weights, capacity) &&
      total_value(c2, values) == max_val;
}

method {:vcs_split_on_every_assert} solve_knapsack_unbounded(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| > 0
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> weights[i] > 0 // Weights must be positive (> 0) to avoid infinite loops
    requires forall i :: 0 <= i < |weights| ==> weights[i] <= 1000
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000 // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            ==> total_value(counts, values) <= max_val
    ensures
        // 2. Existence
        exists counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            && total_value(counts, values) == max_val
{
  var dp: seq<int> := [0];
  ghost var wit: seq<seq<int>> := [Zeros(|weights|)];
  var c := 0;
  initial_state(weights, values, dp, wit);
  assert WitnessState(dp, wit, weights, values, 0);
  assert DpOK(dp, weights, values, 0);

  while c < capacity
    invariant 0 <= c <= capacity
    invariant WitnessState(dp, wit, weights, values, c)
    invariant DpOK(dp, weights, values, c)
    decreases capacity - c
  {
    assert WitnessState(dp, wit, weights, values, c);
    assert DpOK(dp, weights, values, c);
    var next := c + 1;
    assert c < capacity;
    assert next <= capacity;
    assert next == c + 1;

    ghost var bestWit := Zeros(|weights|);
    var best := 0;
    zeros_witness(weights, values, next);
    assert bestWit == Zeros(|weights|);
    assert |bestWit| == |weights|;
    assert |bestWit| == |values|;
    assert total_value(bestWit, values) == 0;
    assert total_value(bestWit, values) == best;
    assert is_valid_strategy(bestWit, weights, next);
    assert best >= 0;
    covered_empty(dp, weights, values, next, best);
    assert CoveredPrefix(dp, weights, values, next, best, 0);

    var i := 0;
    while i < |weights|
      invariant 0 <= i <= |weights|
      invariant |bestWit| == |values|
      invariant total_value(bestWit, values) == best
      invariant best >= 0
      invariant is_valid_strategy(bestWit, weights, next)
      invariant CoveredPrefix(dp, weights, values, next, best, i)
      decreases |weights| - i
    {
      assert 0 <= i < |weights|;
      assert i < |values|;
      var seen := i;
      var prevBest := best;
      assert seen == i;
      assert prevBest == best;
      covered_same(dp, weights, values, next, best, prevBest, i, seen);
      assert CoveredPrefix(dp, weights, values, next, prevBest, seen);

      if weights[i] <= next {
        var idx := next - weights[i];
        assert weights[i] > 0;
        assert weights[i] >= 1;
        open_dp_nonneg(dp, weights, values, c, 0);
        assert |dp| == c + 1;
        assert next == c + 1;
        assert |dp| == next;
        assert 0 <= idx;
        assert idx <= next - 1;
        assert idx < |dp|;
        assert idx <= c;
        open_witness(dp, wit, weights, values, c, idx);
        assert total_value(wit[idx], values) == dp[idx];
        assert is_valid_strategy(wit[idx], weights, idx);
        assert |wit[idx]| == |weights|;
        assert 0 <= i < |wit[idx]|;
        assert 0 <= values[i];
        assert dp[idx] >= 0;
        var cand := dp[idx] + values[i];
        assert cand >= 0;
        if cand > best {
          assert best == prevBest;
          assert cand > prevBest;
          ghost var newWit := IncrAt(wit[idx], i);
          assert idx + weights[i] == next;
          assert idx + weights[i] <= next;
          increment_ok(wit[idx], weights, values, i, next, idx, dp[idx]);
          assert newWit == IncrAt(wit[idx], i);
          assert is_valid_strategy(newWit, weights, next);
          assert total_value(newWit, values) == dp[idx] + values[i];
          assert total_value(newWit, values) == cand;
          assert |newWit| == |weights|;
          assert |newWit| == |values|;
          bestWit := newWit;
          best := cand;
          assert total_value(bestWit, values) == best;
          assert is_valid_strategy(bestWit, weights, next);
          assert |bestWit| == |values|;
          assert best >= 0;
          assert prevBest <= best;
        }
        assert cand <= best;
        assert cand == dp[idx] + values[i];
        assert dp[idx] + values[i] <= best;
        assert idx == next - weights[i];
        assert 0 <= next - weights[i] < |dp|;
        assert dp[next - weights[i]] + values[i] <= best;
        assert |bestWit| == |values|;
        assert total_value(bestWit, values) == best;
        assert best >= 0;
        assert is_valid_strategy(bestWit, weights, next);
        assert prevBest <= best;
      } else {
        assert weights[i] > next;
        assert |bestWit| == |values|;
        assert total_value(bestWit, values) == best;
        assert best >= 0;
        assert is_valid_strategy(bestWit, weights, next);
        assert best == prevBest;
        assert prevBest <= best;
      }

      assert best >= prevBest;
      assert seen == i;
      if weights[seen] <= next {
        assert 0 <= next - weights[seen] < |dp|;
        assert dp[next - weights[seen]] + values[seen] <= best;
      }
      assert weights[seen] <= next ==>
          0 <= next - weights[seen] < |dp| &&
          dp[next - weights[seen]] + values[seen] <= best;
      covered_extend(dp, weights, values, next, prevBest, best, seen);
      assert CoveredPrefix(dp, weights, values, next, best, seen + 1);
      assert |bestWit| == |values|;
      assert total_value(bestWit, values) == best;
      assert best >= 0;
      assert is_valid_strategy(bestWit, weights, next);
      i := seen + 1;
      assert i == seen + 1;
      assert CoveredPrefix(dp, weights, values, next, best, i);
    }

    assert i == |weights|;
    assert CoveredPrefix(dp, weights, values, next, best, |weights|);
    assert is_valid_strategy(bestWit, weights, next);
    assert total_value(bestWit, values) == best;
    assert |bestWit| == |values|;
    assert best >= 0;

    var dpNext := dp + [best];
    ghost var witNext := wit + [bestWit];
    step_state(dp, wit, weights, values, c, next, best, bestWit, dpNext, witNext);
    dp := dpNext;
    wit := witNext;
    c := next;
    assert dp == dpNext;
    assert wit == witNext;
    assert c == next;
    assert WitnessState(dp, wit, weights, values, c);
    assert DpOK(dp, weights, values, c);
    assert 0 <= c <= capacity;
  }

  assert c == capacity;
  assert WitnessState(dp, wit, weights, values, c);
  assert DpOK(dp, weights, values, c);
  open_dp_nonneg(dp, weights, values, c, c);
  max_val := dp[c];
  assert max_val == dp[capacity];
  assert max_val >= 0;
  open_witness(dp, wit, weights, values, c, c);
  ghost var witnessCounts := wit[c];
  assert |witnessCounts| == |weights|;
  assert |witnessCounts| == |values|;
  assert |witnessCounts| <= |values|;
  assert is_valid_strategy(witnessCounts, weights, capacity);
  assert total_value(witnessCounts, values) == dp[c];
  assert total_value(witnessCounts, values) == max_val;
  ProveExists(witnessCounts, weights, values, capacity, max_val);
  all_strategies_bounded(weights, values, capacity, dp, max_val);
}
