lemma {:vcs_split_on_every_assert} SubtreeNested(t: Tree, higher: int, lower: int)
    requires tree_distinct(t)
    requires contains(t, higher)
    requires contains(spec_get_subtree(t, higher), lower)
    ensures contains(t, lower)
    ensures spec_get_subtree(t, lower) == spec_get_subtree(spec_get_subtree(t, higher), lower)
    decreases t
{
    if t.Nil? {
        ContainsUnfoldNil(higher);
        assert false;
    }
    assert t.Node?;
    if t.val == higher {
        SubtreeAtRoot(t);
        assert spec_get_subtree(t, higher) == t;
        assert contains(t, lower);
        assert spec_get_subtree(t, lower) == spec_get_subtree(spec_get_subtree(t, higher), lower);
    } else if contains(t.left, higher) {
        DistinctParts(t);
        SubtreeFromLeft(t, higher);
        assert spec_get_subtree(t, higher) == spec_get_subtree(t.left, higher);
        assert contains(spec_get_subtree(t.left, higher), lower);
        SubtreeNested(t.left, higher, lower);
        assert contains(t.left, lower);
        ContainsFromLeft(t, lower);
        SubtreeFromLeft(t, lower);
        assert spec_get_subtree(t, lower) == spec_get_subtree(t.left, lower);
        assert spec_get_subtree(t.left, lower) == spec_get_subtree(spec_get_subtree(t.left, higher), lower);
        assert spec_get_subtree(spec_get_subtree(t, higher), lower) ==
            spec_get_subtree(spec_get_subtree(t.left, higher), lower);
        assert spec_get_subtree(t, lower) == spec_get_subtree(spec_get_subtree(t, higher), lower);
    } else {
        assert t.val != higher;
        InSomeChild(t, higher);
        assert !contains(t.left, higher);
        assert contains(t.right, higher);
        DistinctParts(t);
        SubtreeFromRight(t, higher);
        assert spec_get_subtree(t, higher) == spec_get_subtree(t.right, higher);
        assert contains(spec_get_subtree(t.right, higher), lower);
        SubtreeNested(t.right, higher, lower);
        assert contains(t.right, lower);
        ContainsFromRight(t, lower);
        SubtreeFromRight(t, lower);
        assert spec_get_subtree(t, lower) == spec_get_subtree(t.right, lower);
        assert spec_get_subtree(t.right, lower) == spec_get_subtree(spec_get_subtree(t.right, higher), lower);
        assert spec_get_subtree(spec_get_subtree(t, higher), lower) ==
            spec_get_subtree(spec_get_subtree(t.right, higher), lower);
        assert spec_get_subtree(t, lower) == spec_get_subtree(spec_get_subtree(t, higher), lower);
    }
}

lemma {:vcs_split_on_every_assert} AncestorChain(t: Tree, a: int, b: int, y: int)
    requires tree_distinct(t)
    requires contains(t, a)
    requires contains(t, b)
    requires contains(spec_get_subtree(t, a), y)
    requires contains(spec_get_subtree(t, b), y)
    ensures contains(spec_get_subtree(t, a), b) || contains(spec_get_subtree(t, b), a)
    decreases t
{
    if t.Nil? {
        ContainsUnfoldNil(a);
        assert false;
    }
    assert t.Node?;
    if t.val == a {
        SubtreeAtRoot(t);
        assert spec_get_subtree(t, a) == t;
        assert contains(spec_get_subtree(t, a), b);
    } else if t.val == b {
        SubtreeAtRoot(t);
        assert spec_get_subtree(t, b) == t;
        assert contains(spec_get_subtree(t, b), a);
    } else {
        DistinctParts(t);
        InSomeChild(t, a);
        InSomeChild(t, b);
        if contains(t.left, a) && contains(t.left, b) {
            SubtreeFromLeft(t, a);
            SubtreeFromLeft(t, b);
            assert contains(spec_get_subtree(t.left, a), y);
            assert contains(spec_get_subtree(t.left, b), y);
            AncestorChain(t.left, a, b, y);
            assert spec_get_subtree(t, a) == spec_get_subtree(t.left, a);
            assert spec_get_subtree(t, b) == spec_get_subtree(t.left, b);
            assert contains(spec_get_subtree(t, a), b) || contains(spec_get_subtree(t, b), a);
        } else if contains(t.right, a) && contains(t.right, b) {
            SubtreeFromRight(t, a);
            SubtreeFromRight(t, b);
            assert contains(spec_get_subtree(t.right, a), y);
            assert contains(spec_get_subtree(t.right, b), y);
            AncestorChain(t.right, a, b, y);
            assert spec_get_subtree(t, a) == spec_get_subtree(t.right, a);
            assert spec_get_subtree(t, b) == spec_get_subtree(t.right, b);
            assert contains(spec_get_subtree(t, a), b) || contains(spec_get_subtree(t, b), a);
        } else {
            assert !(contains(t.left, a) && contains(t.left, b));
            assert !(contains(t.right, a) && contains(t.right, b));
            if contains(t.left, a) {
                assert !contains(t.left, b);
                assert contains(t.right, b);
                MemberFromLeft(t, a, y);
                MemberFromRight(t, b, y);
                assert !contains(t.right, y);
                assert contains(t.right, y);
                assert false;
            } else {
                assert contains(t.right, a);
                assert contains(t.left, b);
                MemberFromRight(t, a, y);
                MemberFromLeft(t, b, y);
                assert !contains(t.left, y);
                assert contains(t.left, y);
                assert false;
            }
        }
    }
}

lemma {:vcs_split_on_every_assert} DepthAncestorOf(t: Tree, higher: int, lower: int)
    requires tree_distinct(t)
    requires contains(t, higher)
    requires contains(spec_get_subtree(t, higher), lower)
    ensures contains(t, lower)
    ensures spec_get_depth(t, higher).Some? && spec_get_depth(t, lower).Some? &&
            spec_get_depth(t, higher).get <= spec_get_depth(t, lower).get
    decreases t
{
    if t.Nil? {
        ContainsUnfoldNil(higher);
        assert false;
    }
    assert t.Node?;
    if t.val == higher {
        SubtreeAtRoot(t);
        assert spec_get_subtree(t, higher) == t;
        assert contains(t, lower);
        DepthNonNeg(t, lower);
        NodeReconstruct(t);
        DepthUnfoldEq(t.val, t.left, t.right, higher);
        assert spec_get_depth(t, higher) == Some(0);
        assert spec_get_depth(t, higher).get == 0;
        assert spec_get_depth(t, lower).get >= 0;
        assert spec_get_depth(t, higher).get <= spec_get_depth(t, lower).get;
    } else if contains(t.left, higher) {
        DistinctParts(t);
        MemberFromLeft(t, higher, lower);
        assert contains(t.left, lower);
        ContainsFromLeft(t, lower);
        SubtreeFromLeft(t, higher);
        assert contains(spec_get_subtree(t.left, higher), lower);
        DepthAncestorOf(t.left, higher, lower);
        DepthShiftLeft(t, higher);
        DepthShiftLeft(t, lower);
        assert spec_get_depth(t.left, higher).get <= spec_get_depth(t.left, lower).get;
        PlusOneMonotone(spec_get_depth(t.left, higher).get, spec_get_depth(t.left, lower).get);
        assert spec_get_depth(t, higher).get == spec_get_depth(t.left, higher).get + 1;
        assert spec_get_depth(t, lower).get == spec_get_depth(t.left, lower).get + 1;
        assert spec_get_depth(t, higher).get <= spec_get_depth(t, lower).get;
    } else {
        assert t.val != higher;
        assert !contains(t.left, higher);
        InSomeChild(t, higher);
        assert contains(t.right, higher);
        DistinctParts(t);
        MemberFromRight(t, higher, lower);
        assert contains(t.right, lower);
        ContainsFromRight(t, lower);
        SubtreeFromRight(t, higher);
        assert contains(spec_get_subtree(t.right, higher), lower);
        DepthAncestorOf(t.right, higher, lower);
        DepthShiftRight(t, higher);
        DepthShiftRight(t, lower);
        assert spec_get_depth(t.right, higher).get <= spec_get_depth(t.right, lower).get;
        PlusOneMonotone(spec_get_depth(t.right, higher).get, spec_get_depth(t.right, lower).get);
        assert spec_get_depth(t, higher).get == spec_get_depth(t.right, higher).get + 1;
        assert spec_get_depth(t, lower).get == spec_get_depth(t.right, lower).get + 1;
        assert spec_get_depth(t, higher).get <= spec_get_depth(t, lower).get;
    }
}

lemma CAContains(t: Tree, a: int, p: int, q: int)
    requires is_common_ancestor(t, a, p, q)
    ensures spec_get_subtree(t, a).Node?
    ensures contains(spec_get_subtree(t, a), p)
    ensures contains(spec_get_subtree(t, a), q)
{
    var subtree := spec_get_subtree(t, a);
    assert subtree.Node?;
    assert contains(subtree, p);
    assert contains(subtree, q);
}

lemma IntroCA(t: Tree, a: int, p: int, q: int)
    requires spec_get_subtree(t, a).Node?
    requires contains(spec_get_subtree(t, a), p)
    requires contains(spec_get_subtree(t, a), q)
    ensures is_common_ancestor(t, a, p, q)
{
    var subtree := spec_get_subtree(t, a);
    assert subtree.Node?;
    assert contains(subtree, p);
    assert contains(subtree, q);
    assert is_common_ancestor(t, a, p, q);
}

lemma OpenLCA(t: Tree, anc: int, p: int, q: int)
    requires LCAChar(t, anc, p, q)
    ensures is_common_ancestor(t, anc, p, q)
    ensures SplitOrSelf(spec_get_subtree(t, anc), p, q)
{
    assert is_common_ancestor(t, anc, p, q);
    assert SplitOrSelf(spec_get_subtree(t, anc), p, q);
}

lemma IntroLCA(t: Tree, anc: int, p: int, q: int)
    requires is_common_ancestor(t, anc, p, q)
    requires SplitOrSelf(spec_get_subtree(t, anc), p, q)
    ensures LCAChar(t, anc, p, q)
{
    assert LCAChar(t, anc, p, q);
}

lemma OpenSplit(sub: Tree, p: int, q: int)
    requires sub.Node?
    requires SplitOrSelf(sub, p, q)
    ensures sub.val == p || sub.val == q ||
            (contains(sub.left, p) && contains(sub.right, q)) ||
            (contains(sub.left, q) && contains(sub.right, p))
{
    assert sub.val == p || sub.val == q ||
        (contains(sub.left, p) && contains(sub.right, q)) ||
        (contains(sub.left, q) && contains(sub.right, p));
}

lemma CharInTree(s: Tree, anc: int, p: int, q: int)
    requires LCAChar(s, anc, p, q)
    ensures contains(s, anc)
{
    CAContains(s, anc, p, q);
    assert spec_get_subtree(s, anc).Node?;
    SubtreeNodeVal(s, anc);
    assert contains(s, anc);
}

lemma CharShape(t: Tree, anc: int, p: int, q: int)
    requires LCAChar(t, anc, p, q)
    ensures spec_get_subtree(t, anc).Node? &&
            spec_get_subtree(t, anc).val == anc &&
            contains(t, anc) &&
            contains(spec_get_subtree(t, anc), p) &&
            contains(spec_get_subtree(t, anc), q) &&
            (spec_get_subtree(t, anc).val == p ||
             spec_get_subtree(t, anc).val == q ||
             (contains(spec_get_subtree(t, anc).left, p) && contains(spec_get_subtree(t, anc).right, q)) ||
             (contains(spec_get_subtree(t, anc).left, q) && contains(spec_get_subtree(t, anc).right, p)))
{
    OpenLCA(t, anc, p, q);
    CAContains(t, anc, p, q);
    SubtreeNodeVal(t, anc);
    var sub := spec_get_subtree(t, anc);
    assert sub.Node?;
    assert sub.val == anc;
    assert contains(t, anc);
    assert contains(sub, p) && contains(sub, q);
    assert SplitOrSelf(sub, p, q);
    OpenSplit(sub, p, q);
}

lemma ProperDescendantExcludesRoot(t: Tree, anc: int, x: int)
    requires tree_distinct(t)
    requires contains(t, anc)
    requires contains(spec_get_subtree(t, anc), x)
    requires x != anc
    ensures !contains(spec_get_subtree(t, x), anc)
{
    var sub := spec_get_subtree(t, anc);
    ContainsSubtreeNode(t, anc);
    assert sub.Node?;
    assert sub.val == anc;
    assert tree_distinct(sub);
    assert x != sub.val;
    assert contains(sub, x);
    SubtreeNested(t, anc, x);
    assert spec_get_subtree(t, x) == spec_get_subtree(sub, x);
    InSomeChild(sub, x);
    if contains(sub.left, x) {
        DistinctParts(sub);
        SubtreeFromLeft(sub, x);
        ViewSubset(sub.left, x);
        assert view(spec_get_subtree(sub, x)) <= view(sub.left);
        assert !contains(sub.left, sub.val);
        ContainsView(sub.left, sub.val);
        assert sub.val !in view(sub.left);
        NotMemberSubset(view(spec_get_subtree(sub, x)), view(sub.left), sub.val);
        ContainsView(spec_get_subtree(sub, x), sub.val);
        assert !contains(spec_get_subtree(sub, x), sub.val);
        assert !contains(spec_get_subtree(t, x), anc);
    } else {
        assert contains(sub.right, x);
        DistinctParts(sub);
        SubtreeFromRight(sub, x);
        ViewSubset(sub.right, x);
        assert view(spec_get_subtree(sub, x)) <= view(sub.right);
        assert !contains(sub.right, sub.val);
        ContainsView(sub.right, sub.val);
        assert sub.val !in view(sub.right);
        NotMemberSubset(view(spec_get_subtree(sub, x)), view(sub.right), sub.val);
        ContainsView(spec_get_subtree(sub, x), sub.val);
        assert !contains(spec_get_subtree(sub, x), sub.val);
        assert !contains(spec_get_subtree(t, x), anc);
    }
}

lemma ForbidOtherSide(s: Tree, x: int, target: int)
    requires s.Node?
    requires tree_distinct(s)
    requires contains(s.left, x)
    requires contains(s.right, target)
    ensures !contains(spec_get_subtree(s, x), target)
{
    DistinctParts(s);
    SubtreeFromLeft(s, x);
    ViewSubset(s.left, x);
    assert view(spec_get_subtree(s, x)) <= view(s.left);
    ContainsView(s.right, target);
    assert target in view(s.right);
    DisjointNotBoth(view(s.right), view(s.left), target);
    assert target !in view(s.left);
    NotMemberSubset(view(spec_get_subtree(s, x)), view(s.left), target);
    ContainsView(spec_get_subtree(s, x), target);
    assert !contains(spec_get_subtree(s, x), target);
}

lemma ForbidFromRight(s: Tree, x: int, target: int)
    requires s.Node?
    requires tree_distinct(s)
    requires contains(s.right, x)
    requires contains(s.left, target)
    ensures !contains(spec_get_subtree(s, x), target)
{
    DistinctParts(s);
    SubtreeFromRight(s, x);
    ViewSubset(s.right, x);
    assert view(spec_get_subtree(s, x)) <= view(s.right);
    ContainsView(s.left, target);
    assert target in view(s.left);
    DisjointNotBoth(view(s.left), view(s.right), target);
    assert target !in view(s.right);
    NotMemberSubset(view(spec_get_subtree(s, x)), view(s.right), target);
    ContainsView(spec_get_subtree(s, x), target);
    assert !contains(spec_get_subtree(s, x), target);
}

lemma {:vcs_split_on_every_assert} DescendantNotCA(t: Tree, anc: int, x: int, p: int, q: int)
    requires tree_distinct(t)
    requires LCAChar(t, anc, p, q)
    requires is_common_ancestor(t, x, p, q)
    requires x != anc
    requires contains(spec_get_subtree(t, anc), x)
    ensures false
{
    CharShape(t, anc, p, q);
    var sub := spec_get_subtree(t, anc);
    assert sub.Node?;
    assert sub.val == anc;
    assert contains(t, anc);
    CAContains(t, x, p, q);
    assert contains(spec_get_subtree(t, x), p);
    assert contains(spec_get_subtree(t, x), q);
    if anc == p || anc == q {
        assert contains(spec_get_subtree(t, x), anc);
        ProperDescendantExcludesRoot(t, anc, x);
        assert !contains(spec_get_subtree(t, x), anc);
        assert false;
    } else {
        assert anc != p && anc != q;
        assert sub.val != p && sub.val != q;
        assert (contains(sub.left, p) && contains(sub.right, q)) ||
               (contains(sub.left, q) && contains(sub.right, p));
        ContainsSubtreeNode(t, anc);
        assert tree_distinct(sub);
        SubtreeNested(t, anc, x);
        assert contains(sub, x);
        assert spec_get_subtree(t, x) == spec_get_subtree(sub, x);
        InSomeChild(sub, x);
        if contains(sub.left, x) {
            if contains(sub.left, p) && contains(sub.right, q) {
                ForbidOtherSide(sub, x, q);
                assert !contains(spec_get_subtree(sub, x), q);
                assert !contains(spec_get_subtree(t, x), q);
                assert false;
            } else {
                assert !(contains(sub.left, p) && contains(sub.right, q));
                assert contains(sub.left, q) && contains(sub.right, p);
                ForbidOtherSide(sub, x, p);
                assert !contains(spec_get_subtree(sub, x), p);
                assert !contains(spec_get_subtree(t, x), p);
                assert false;
            }
        } else {
            assert contains(sub.right, x);
            if contains(sub.left, p) && contains(sub.right, q) {
                ForbidFromRight(sub, x, p);
                assert !contains(spec_get_subtree(sub, x), p);
                assert !contains(spec_get_subtree(t, x), p);
                assert false;
            } else {
                assert !(contains(sub.left, p) && contains(sub.right, q));
                assert contains(sub.left, q) && contains(sub.right, p);
                ForbidFromRight(sub, x, q);
                assert !contains(spec_get_subtree(sub, x), q);
                assert !contains(spec_get_subtree(t, x), q);
                assert false;
            }
        }
    }
}

lemma {:vcs_split_on_every_assert} DepthLe(t: Tree, anc: int, x: int, p: int, q: int)
    requires tree_distinct(t)
    requires LCAChar(t, anc, p, q)
    requires is_common_ancestor(t, x, p, q)
    ensures spec_get_depth(t, x).Some? && spec_get_depth(t, anc).Some? &&
            spec_get_depth(t, x).get <= spec_get_depth(t, anc).get
{
    CAContains(t, x, p, q);
    CAContains(t, anc, p, q);
    SubtreeNodeVal(t, x);
    CharInTree(t, anc, p, q);
    assert spec_get_subtree(t, x).Node?;
    assert contains(t, x);
    assert contains(t, anc);
    assert contains(spec_get_subtree(t, x), p);
    assert contains(spec_get_subtree(t, anc), p);
    AncestorChain(t, x, anc, p);
    assert contains(spec_get_subtree(t, x), anc) || contains(spec_get_subtree(t, anc), x);
    if contains(spec_get_subtree(t, x), anc) {
        DepthAncestorOf(t, x, anc);
    } else {
        assert contains(spec_get_subtree(t, anc), x);
        if x == anc {
            SubtreeContainsSelf(t, anc);
            assert contains(spec_get_subtree(t, x), anc);
            assert false;
        }
        assert x != anc;
        DescendantNotCA(t, anc, x, p, q);
        assert false;
    }
}

lemma Establish(t: Tree, anc: int, p: int, q: int)
    requires tree_distinct(t)
    requires contains(t, p)
    requires contains(t, q)
    requires LCAChar(t, anc, p, q)
    ensures is_common_ancestor(t, anc, p, q)
    ensures forall x: int :: is_common_ancestor(t, x, p, q) ==>
        spec_get_depth(t, x).Some? &&
        spec_get_depth(t, anc).Some? &&
        spec_get_depth(t, x).get <= spec_get_depth(t, anc).get
{
    OpenLCA(t, anc, p, q);
    assert is_common_ancestor(t, anc, p, q);
    forall x: int | is_common_ancestor(t, x, p, q)
        ensures spec_get_depth(t, x).Some? &&
                spec_get_depth(t, anc).Some? &&
                spec_get_depth(t, x).get <= spec_get_depth(t, anc).get
    {
        DepthLe(t, anc, x, p, q);
    }
}

lemma OpenChild(s: Tree, p: int, q: int, r: Option<int>)
    requires ChildEns(s, p, q, r)
    ensures (!contains(s, p) && !contains(s, q)) ==> r == None
    ensures (contains(s, p) && !contains(s, q)) ==> r == Some(p)
    ensures (!contains(s, p) && contains(s, q)) ==> r == Some(q)
    ensures (contains(s, p) && contains(s, q)) ==> HoldsChar(s, p, q, r)
{
}

lemma MakeChildEns(s: Tree, p: int, q: int, r: Option<int>)
    requires (!contains(s, p) && !contains(s, q)) ==> r == None
    requires (contains(s, p) && !contains(s, q)) ==> r == Some(p)
    requires (!contains(s, p) && contains(s, q)) ==> r == Some(q)
    requires (contains(s, p) && contains(s, q)) ==> HoldsChar(s, p, q, r)
    ensures ChildEns(s, p, q, r)
{
}

lemma OpenHolds(s: Tree, p: int, q: int, r: Option<int>)
    requires HoldsChar(s, p, q, r)
    ensures r.Some? && LCAChar(s, r.get, p, q)
{
    match r {
        case Some(a) =>
            assert r.Some?;
            assert r.get == a;
            assert LCAChar(s, a, p, q);
            assert LCAChar(s, r.get, p, q);
        case None =>
            assert HoldsChar(s, p, q, r) == false;
            assert false;
    }
}

lemma IntroHolds(s: Tree, p: int, q: int, a: int)
    requires LCAChar(s, a, p, q)
    ensures HoldsChar(s, p, q, Some(a))
{
    assert HoldsChar(s, p, q, Some(a));
}

lemma HoldsFromGet(s: Tree, p: int, q: int, r: Option<int>)
    requires r.Some?
    requires LCAChar(s, r.get, p, q)
    ensures HoldsChar(s, p, q, r)
{
    match r {
        case Some(a) =>
            assert a == r.get;
            assert LCAChar(s, a, p, q);
            assert HoldsChar(s, p, q, r);
        case None =>
            assert r.Some?;
            assert false;
    }
}

lemma OptionNoneAbsent(s: Tree, p: int, q: int, r: Option<int>)
    requires ChildEns(s, p, q, r)
    requires r == None
    ensures !contains(s, p)
    ensures !contains(s, q)
{
    OpenChild(s, p, q, r);
    if contains(s, p) && contains(s, q) {
        assert HoldsChar(s, p, q, r);
        OpenHolds(s, p, q, r);
        assert r.Some?;
        assert false;
    } else if contains(s, p) && !contains(s, q) {
        assert r == Some(p);
        assert false;
    } else if !contains(s, p) && contains(s, q) {
        assert r == Some(q);
        assert false;
    } else {
        assert !contains(s, p) && !contains(s, q);
    }
}

lemma SomeMeansPresent(s: Tree, p: int, q: int, r: Option<int>)
    requires ChildEns(s, p, q, r)
    requires r.Some?
    ensures contains(s, p) || contains(s, q)
{
    OpenChild(s, p, q, r);
    if !contains(s, p) && !contains(s, q) {
        assert r == None;
        assert false;
    }
}

lemma CASameSubtree(t1: Tree, t2: Tree, a: int, p: int, q: int)
