lemma LiftCharLeft(t: Tree, anc: int, p: int, q: int)
    requires t.Node?
    requires tree_distinct(t)
    requires contains(t.left, anc)
    requires LCAChar(t.left, anc, p, q)
    ensures LCAChar(t, anc, p, q)
{
    OpenLCA(t.left, anc, p, q);
    SubtreeFromLeft(t, anc);
    assert spec_get_subtree(t, anc) == spec_get_subtree(t.left, anc);
    CASameSubtree(t, t.left, anc, p, q);
    assert is_common_ancestor(t, anc, p, q);
    assert SplitOrSelf(spec_get_subtree(t.left, anc), p, q);
    assert SplitOrSelf(spec_get_subtree(t, anc), p, q);
    IntroLCA(t, anc, p, q);
}

lemma LiftCharRight(t: Tree, anc: int, p: int, q: int)
    requires t.Node?
    requires tree_distinct(t)
    requires contains(t.right, anc)
    requires LCAChar(t.right, anc, p, q)
    ensures LCAChar(t, anc, p, q)
{
    OpenLCA(t.right, anc, p, q);
    SubtreeFromRight(t, anc);
    assert spec_get_subtree(t, anc) == spec_get_subtree(t.right, anc);
    CASameSubtree(t, t.right, anc, p, q);
    assert is_common_ancestor(t, anc, p, q);
    assert SplitOrSelf(spec_get_subtree(t.right, anc), p, q);
    assert SplitOrSelf(spec_get_subtree(t, anc), p, q);
    IntroLCA(t, anc, p, q);
}

lemma ProveSelfChar(t: Tree, p: int, q: int)
    requires t.Node?
    requires contains(t, p)
