predicate LCAChar(t: Tree, anc: int, p: int, q: int)
{
    is_common_ancestor(t, anc, p, q) && SplitOrSelf(spec_get_subtree(t, anc), p, q)
}

predicate HoldsChar(s: Tree, p: int, q: int, r: Option<int>)
{
    match r {
        case Some(a) => LCAChar(s, a, p, q)
        case None => false
    }
}

predicate ChildEns(s: Tree, p: int, q: int, r: Option<int>)
{
    ((!contains(s, p) && !contains(s, q)) ==> r == None) &&
    ((contains(s, p) && !contains(s, q)) ==> r == Some(p)) &&
    ((!contains(s, p) && contains(s, q)) ==> r == Some(q)) &&
    ((contains(s, p) && contains(s, q)) ==> HoldsChar(s, p, q, r))
