    if x in B {
        assert x in A * B;
        assert x in {};
        assert false;
    }
}

lemma ContainsView(t: Tree, x: int)
    ensures contains(t, x) <==> x in view(t)
    decreases t
{
    match t {
        case Nil =>
            ContainsUnfoldNil(x);
            ViewUnfoldNil();
            assert contains(t, x) == false;
            assert view(t) == {};
            assert x !in view(t);
        case Node(v, l, r) =>
            ContainsView(l, x);
            ContainsView(r, x);
            ContainsUnfoldNode(v, l, r, x);
            ViewUnfoldNode(v, l, r);
            assert t == Node(v, l, r);
            assert view(t) == view(l) + view(r) + {v};
            assert contains(t, x) == (v == x || contains(l, x) || contains(r, x));
            assert contains(l, x) == (x in view(l));
            assert contains(r, x) == (x in view(r));
            InUnion3(view(l), view(r), {v}, x);
            assert (x in {v}) == (x == v);
            assert (x in view(t)) == (x in view(l) || x in view(r) || x == v);
            assert contains(t, x) == (x in view(t));
    }
}

lemma DistinctParts(t: Tree)
    requires t.Node?
    requires tree_distinct(t)
    ensures tree_distinct(t.left)
    ensures tree_distinct(t.right)
    ensures !contains(t.left, t.val)
    ensures !contains(t.right, t.val)
    ensures view(t.left) * view(t.right) == {}
{
    NodeReconstruct(t);
    DistinctUnfold(t.val, t.left, t.right);
    assert tree_distinct(t.left);
    assert tree_distinct(t.right);
    assert !contains(t.left, t.val);
    assert !contains(t.right, t.val);
    assert view(t.left) * view(t.right) == {};
}

lemma NotBothChildren(t: Tree, x: int)
    requires t.Node?
    requires tree_distinct(t)
    requires contains(t.left, x)
    ensures !contains(t.right, x)
    ensures x != t.val
{
    DistinctParts(t);
    ContainsView(t.left, x);
    assert x in view(t.left);
    DisjointNotBoth(view(t.left), view(t.right), x);
    ContainsView(t.right, x);
    assert !contains(t.right, x);
    if x == t.val {
        ContainsView(t.left, t.val);
        assert contains(t.left, t.val);
        assert !contains(t.left, t.val);
        assert false;
    }
}

lemma NotBothChildrenRight(t: Tree, x: int)
