lemma SubtreeFromLeft(t: Tree, x: int)
    requires t.Node?
    requires tree_distinct(t)
    requires contains(t.left, x)
    ensures x != t.val
    ensures !contains(t.right, x)
    ensures spec_get_subtree(t.left, x).Node?
    ensures spec_get_subtree(t, x) == spec_get_subtree(t.left, x)
{
