    NotBothChildren(t, x);
    ContainsSubtreeNode(t.left, x);
    NotContainsSubtreeNil(t.right, x);
    assert spec_get_subtree(t.right, x) == Nil;
    assert spec_get_subtree(t.left, x).Node?;
