lemma DepthIff(t: Tree, x: int)
    ensures spec_get_depth(t, x).Some? <==> contains(t, x)
    decreases t
{
    match t {
        case Nil =>
            ContainsUnfoldNil(x);
            DepthUnfoldNil(x);
        case Node(v, l, r) =>
            assert t == Node(v, l, r);
            ContainsUnfoldNode(v, l, r, x);
            DepthIff(l, x);
            DepthIff(r, x);
            if v == x {
                DepthUnfoldEq(v, l, r, x);
                assert contains(t, x);
                assert spec_get_depth(t, x) == Some(0);
                assert spec_get_depth(t, x).Some?;
            } else if contains(l, x) {
                assert spec_get_depth(l, x).Some?;
                DepthUnfoldLeft(v, l, r, x);
                assert spec_get_depth(t, x).Some?;
            } else if contains(r, x) {
                assert !contains(l, x);
                assert !spec_get_depth(l, x).Some?;
                NoneIsNone(spec_get_depth(l, x));
                assert spec_get_depth(l, x) == None;
                assert spec_get_depth(r, x).Some?;
                DepthUnfoldRight(v, l, r, x);
                assert spec_get_depth(t, x).Some?;
            } else {
                assert !contains(t, x);
                assert !spec_get_depth(l, x).Some?;
                assert !spec_get_depth(r, x).Some?;
                NoneIsNone(spec_get_depth(l, x));
                NoneIsNone(spec_get_depth(r, x));
                DepthUnfoldNone(v, l, r, x);
                assert spec_get_depth(t, x) == None;
            }
    }
}

lemma DepthNonNeg(t: Tree, x: int)
    requires contains(t, x)
    ensures spec_get_depth(t, x).Some? && spec_get_depth(t, x).get >= 0
    decreases t
{
    DepthIff(t, x);
    match t {
        case Nil =>
            ContainsUnfoldNil(x);
            assert false;
        case Node(v, l, r) =>
            assert t == Node(v, l, r);
            if v == x {
                DepthUnfoldEq(v, l, r, x);
                assert spec_get_depth(t, x) == Some(0);
                assert spec_get_depth(t, x).get == 0;
            } else if contains(l, x) {
                DepthNonNeg(l, x);
                assert spec_get_depth(l, x).Some?;
                DepthUnfoldLeft(v, l, r, x);
                assert spec_get_depth(t, x) == Some(spec_get_depth(l, x).get + 1);
                assert spec_get_depth(t, x).get == spec_get_depth(l, x).get + 1;
                assert spec_get_depth(t, x).get >= 0;
            } else {
                ContainsUnfoldNode(v, l, r, x);
                assert contains(r, x);
                DepthNonNeg(r, x);
                DepthIff(l, x);
                assert !contains(l, x);
                assert !spec_get_depth(l, x).Some?;
                NoneIsNone(spec_get_depth(l, x));
                DepthUnfoldRight(v, l, r, x);
                assert spec_get_depth(t, x) == Some(spec_get_depth(r, x).get + 1);
                assert spec_get_depth(t, x).get == spec_get_depth(r, x).get + 1;
                assert spec_get_depth(t, x).get >= 0;
            }
    }
}

lemma DepthShiftLeft(t: Tree, x: int)
    requires t.Node?
