lemma SubtreeNodeVal(t: Tree, x: int)
    ensures spec_get_subtree(t, x).Node? ==> spec_get_subtree(t, x).val == x && contains(t, x)
    decreases t
{
    if spec_get_subtree(t, x).Node? {
        match t {
            case Nil =>
                SubUnfoldNil(x);
                assert false;
            case Node(v, l, r) =>
                if v == x {
                    SubUnfoldHit(v, l, r, x);
                    assert t == Node(v, l, r);
                    assert spec_get_subtree(t, x) == t;
                    assert spec_get_subtree(t, x).val == x;
                    ContainsUnfoldNode(v, l, r, x);
                    assert contains(t, x);
                } else {
                    SubtreeNodeVal(l, x);
                    SubtreeNodeVal(r, x);
                    if spec_get_subtree(l, x).Node? {
                        SubChooseLeft(v, l, r, x);
                        assert t == Node(v, l, r);
                        assert spec_get_subtree(t, x) == spec_get_subtree(l, x);
                        assert spec_get_subtree(l, x).val == x;
                        assert spec_get_subtree(t, x).val == x;
                        assert contains(l, x);
                        ContainsUnfoldNode(v, l, r, x);
                        assert contains(t, x);
                    } else {
                        SubChooseRight(v, l, r, x);
                        assert t == Node(v, l, r);
                        assert spec_get_subtree(t, x) == spec_get_subtree(r, x);
                        assert spec_get_subtree(r, x).Node?;
                        assert spec_get_subtree(r, x).val == x;
                        assert contains(r, x);
                        ContainsUnfoldNode(v, l, r, x);
                        assert contains(t, x);
                    }
                }
        }
    }
}

lemma NotContainsSubtreeNil(t: Tree, x: int)
    requires !contains(t, x)
    ensures spec_get_subtree(t, x) == Nil
    decreases t
{
    match t {
        case Nil =>
            SubUnfoldNil(x);
        case Node(v, l, r) =>
            ContainsUnfoldNode(v, l, r, x);
            assert v != x;
            assert !contains(l, x);
            assert !contains(r, x);
            NotContainsSubtreeNil(l, x);
            NotContainsSubtreeNil(r, x);
            assert spec_get_subtree(l, x) == Nil;
            assert !spec_get_subtree(l, x).Node?;
            SubChooseRight(v, l, r, x);
            assert t == Node(v, l, r);
            assert spec_get_subtree(t, x) == spec_get_subtree(r, x);
            assert spec_get_subtree(r, x) == Nil;
            assert spec_get_subtree(t, x) == Nil;
    }
}

lemma ContainsSubtreeNode(t: Tree, x: int)
    requires tree_distinct(t)
    requires contains(t, x)
    ensures spec_get_subtree(t, x).Node? &&
            spec_get_subtree(t, x).val == x &&
            tree_distinct(spec_get_subtree(t, x))
    decreases t
{
    match t {
        case Nil =>
            ContainsUnfoldNil(x);
            assert false;
        case Node(v, l, r) =>
            assert t == Node(v, l, r);
            DistinctParts(t);
            if v == x {
                SubUnfoldHit(v, l, r, x);
                assert spec_get_subtree(t, x) == t;
                assert spec_get_subtree(t, x).Node?;
                assert spec_get_subtree(t, x).val == x;
                assert tree_distinct(spec_get_subtree(t, x));
            } else if contains(l, x) {
                NotBothChildren(t, x);
                ContainsSubtreeNode(l, x);
                NotContainsSubtreeNil(r, x);
                assert spec_get_subtree(l, x).Node?;
                SubChooseLeft(v, l, r, x);
                assert spec_get_subtree(t, x) == spec_get_subtree(l, x);
                assert spec_get_subtree(t, x).val == x;
                assert tree_distinct(spec_get_subtree(t, x));
            } else {
                ContainsUnfoldNode(v, l, r, x);
                assert contains(r, x);
                NotBothChildrenRight(t, x);
                ContainsSubtreeNode(r, x);
                NotContainsSubtreeNil(l, x);
                assert spec_get_subtree(l, x) == Nil;
                assert !spec_get_subtree(l, x).Node?;
                SubChooseRight(v, l, r, x);
                assert spec_get_subtree(t, x) == spec_get_subtree(r, x);
                assert spec_get_subtree(t, x).val == x;
                assert tree_distinct(spec_get_subtree(t, x));
            }
    }
}

