method lca_rec(t: Tree, p: int, q: int) returns (res: Option<int>)
    requires tree_distinct(t)
    decreases t
    ensures ChildEns(t, p, q, res)
{
    res := None;
    match t {
        case Nil =>
            res := None;
            NilEns(p, q);
            assert ChildEns(t, p, q, res);
        case Node(v, left, right) =>
            assert t == Node(v, left, right);
            DistinctParts(t);
            assert v == t.val && left == t.left && right == t.right;
            assert tree_distinct(left) && tree_distinct(right);
            if v == p || v == q {
                res := Some(t.val);
                HitRoot(t, p, q);
                assert res == Some(t.val);
                assert ChildEns(t, p, q, res);
            } else {
                var lr := lca_rec(left, p, q);
                var rr := lca_rec(right, p, q);
                assert ChildEns(t.left, p, q, lr);
                assert ChildEns(t.right, p, q, rr);
                if lr.Some? && rr.Some? {
                    res := Some(t.val);
                    BothSome(t, p, q, lr, rr);
                    assert res == Some(t.val);
                    assert ChildEns(t, p, q, res);
                } else if lr.Some? {
                    assert !rr.Some?;
                    NoneIsNone(rr);
                    assert rr == None;
                    res := lr;
                    LeftPropagate(t, p, q, lr, rr);
                    assert ChildEns(t, p, q, res);
                } else if rr.Some? {
                    assert !lr.Some?;
                    NoneIsNone(lr);
                    assert lr == None;
                    res := rr;
                    RightPropagate(t, p, q, lr, rr);
                    assert ChildEns(t, p, q, res);
                } else {
                    assert !lr.Some? && !rr.Some?;
                    NoneIsNone(lr);
                    NoneIsNone(rr);
                    assert lr == None && rr == None;
                    res := None;
                    BothNone(t, p, q, lr, rr);
                    assert ChildEns(t, p, q, res);
                }
            }
    }
}

