lemma SortedAppend(a: seq<int>, b: seq<int>)
    requires Sorted(a) && Sorted(b)
    requires forall x, y :: x in a && y in b ==> x < y
    ensures Sorted(a + b)
{
    var s := a + b;
    forall i, j | 0 <= i < j < |s| ensures s[i] < s[j] {
        if j < |a| {
            assert s[i] == a[i] && s[j] == a[j];
        } else if i >= |a| {
            assert s[i] == b[i - |a|] && s[j] == b[j - |a|];
        } else {
            assert s[i] == a[i];
            assert s[j] == b[j - |a|];
            assert a[i] in a;
            assert b[j - |a|] in b;
        }
    }
}

lemma SortedSplit(s: seq<int>, k: int)
    requires Sorted(s) && 0 <= k < |s|
    ensures Sorted(s[..k]) && Sorted(s[k+1..])
    ensures forall y :: y in s[..k] ==> y < s[k]
    ensures forall y :: y in s[k+1..] ==> y > s[k]
    ensures forall y :: y in s <==> (y in s[..k] || y == s[k] || y in s[k+1..])
{
    assert s == s[..k] + [s[k]] + s[k+1..];
    forall i, j | 0 <= i < j < |s[..k]| ensures s[..k][i] < s[..k][j] {
        assert s[..k][i] == s[i] && s[..k][j] == s[j];
    }
    forall i, j | 0 <= i < j < |s[k+1..]| ensures s[k+1..][i] < s[k+1..][j] {
        assert s[k+1..][i] == s[k+1+i] && s[k+1..][j] == s[k+1+j];
    }
    forall y | y in s[..k] ensures y < s[k] {
        var i :| 0 <= i < k && s[..k][i] == y;
        assert s[i] == y;
    }
    forall y | y in s[k+1..] ensures y > s[k] {
        var i :| 0 <= i < |s| - k - 1 && s[k+1..][i] == y;
        assert s[k+1+i] == y;
    }
}

lemma FlatProps(t: Option<Node>, v: int)
    requires t.Some? ==> t.value.is_bst()
    ensures Sorted(Flat(t, v))
    ensures forall x :: x in Flat(t, v) <==> (x in view_opt(t) && x != v)
    decreases t
{
    match t {
        case None =>
        case Some(n) =>
            match n.left {
                case Some(l) =>
                    assert l.is_bst();
                    assert forall x :: x in l.view() ==> x < n.val;
                    assert view_opt(n.left) == l.view();
                case None =>
            }
            match n.right {
                case Some(r) =>
                    assert r.is_bst();
                    assert forall x :: x in r.view() ==> x > n.val;
                    assert view_opt(n.right) == r.view();
                case None =>
            }
            FlatProps(n.left, v);
            FlatProps(n.right, v);
            var L := Flat(n.left, v);
            var M: seq<int> := if n.val == v then [] else [n.val];
            var R := Flat(n.right, v);
            assert forall x :: x in view_opt(n.left) ==> x < n.val;
            assert forall x :: x in view_opt(n.right) ==> x > n.val;
            assert n.view() == view_opt(n.left) + view_opt(n.right) + {n.val};
            SortedAppend(L, M);
            SortedAppend(L + M, R);
            assert Flat(t, v) == L + M + R;
    }
}

