lemma NodeOk(x: int, red: bool, l: Option<Node>, r: Option<Node>, h: int)
    requires is_llrbt_opt(l) && is_llrbt_opt(r)
    requires h >= 1 && bh_opt(l) == h && bh_opt(r) == h
    requires !red_opt(r)
    requires red ==> !red_opt(l)
    requires red_opt(l) ==> !red_opt(l.value.left)
    requires forall y :: y in view_opt(l) ==> y < x
    requires forall y :: y in view_opt(r) ==> y > x
    ensures Node(x, red, l, r).is_llrbt()
    ensures Node(x, red, l, r).black_height() == (if red then h else h + 1)
    ensures view_opt(Some(Node(x, red, l, r))) == view_opt(l) + view_opt(r) + {x}
{
    var n := Node(x, red, l, r);
    match l {
        case None =>
        case Some(ln) =>
            assert view_opt(l) == ln.view();
            assert ln.is_bst() && ln.black_height() == h && ln.satisfies_red_props();
            assert forall y :: y in ln.view() ==> y < x;
    }
    match r {
        case None =>
        case Some(rn) =>
            assert view_opt(r) == rn.view();
            assert rn.is_bst() && rn.black_height() == h && rn.satisfies_red_props();
            assert forall y :: y in rn.view() ==> y > x;
            assert !rn.is_red;
    }
    assert n.is_bst();
    assert n.black_height() == (if red then h else h + 1);
    assert n.satisfies_red_props();
    ViewNode(n);
    assert n.view() == view_opt(l) + view_opt(r) + {x};
}

method Build(s: seq<int>, h: nat) returns (res: Option<Node>)
    requires h >= 1
    requires Sorted(s)
    requires Mn(h) <= |s| <= Mx(h)
    ensures is_llrbt_opt(res)
    ensures bh_opt(res) == h
    ensures !red_opt(res)
    ensures forall y :: y in view_opt(res) <==> y in s
    decreases h
{
    if h == 1 {
        assert |s| == 0;
        res := None;
        return;
    }
    Bounds(h - 1);
    var m := Mn(h - 1);
    var M := Mx(h - 1);
    assert Mn(h) == 2 * m + 1;
    assert Mx(h) == 3 * M + 2;
    if |s| - 1 <= 2 * M {
        var r := |s| - 1;
        var a := r / 2;
        assert 2 * a <= r < 2 * a + 2;
        SortedSplit(s, a);
        var left := Build(s[..a], h - 1);
        var right := Build(s[a+1..], h - 1);
        NodeOk(s[a], false, left, right, h - 1);
        res := Some(Node(s[a], false, left, right));
    } else {
        var k := |s| - 2;
        var a := k / 3;
        assert 3 * a <= k < 3 * a + 3;
        var b := (k - a) / 2;
        assert 2 * b <= k - a < 2 * b + 2;
        var k2 := a + 1 + b;
        SortedSplit(s, k2);
        var P := s[..k2];
        SortedSplit(P, a);
        var A := Build(P[..a], h - 1);
        var B := Build(P[a+1..], h - 1);
        NodeOk(P[a], true, A, B, h - 1);
        var redn := Some(Node(P[a], true, A, B));
        assert forall y :: y in view_opt(redn) <==> y in P;
        var C := Build(s[k2+1..], h - 1);
        NodeOk(s[k2], false, redn, C, h - 1);
        res := Some(Node(s[k2], false, redn, C));
    }
}

method delete(tree: Option<Node>, v: int) returns (res: Option<Node>)
    requires is_llrbt_opt(tree)
    ensures 
        // Functional Correctness
        view_opt(res) == view_opt(tree) - {v}
    ensures
        // Invariant Maintenance
        is_llrbt_opt(res)
{
    var s := Flat(tree, v);
    FlatProps(tree, v);
    var h: nat := 1;
    while Mx(h) < |s|
        invariant h >= 1
        invariant Mn(h) <= |s|
        invariant h - 1 <= Mx(h)
        invariant h <= |s| + 1
        decreases |s| + 1 - h
    {
        Bounds(h);
        h := h + 1;
    }
    res := Build(s, h);
    assert forall y :: y in view_opt(res) <==> (y in view_opt(tree) && y != v);
    assert view_opt(res) == view_opt(tree) - {v};
}
