        res := acc;
        return;
    }

    var n := tree.value;
    var afterLeft := collect_without(n.left, v, acc);
    var afterRight := collect_without(n.right, v, afterLeft);

    if n.val == v {
        res := afterRight;
    } else {
        res := canonical_insert(afterRight, n.val);
    }

    assert view_opt(res)
        == view_opt(acc) + (view_opt(tree) - {v});
}

