method canonical_insert(t: Option<Node>, x: int)
    returns (res: Option<Node>)
    requires canonical(t)
    ensures canonical(res)
    ensures view_opt(res) == view_opt(t) + {x}
{
    var split, a, key, b, whole := insert23(t, x);

    if split {
        res := Some(Node(key, false, a, b));
        assert canonical(res);
        assert view_opt(res) == view_opt(t) + {x};
    } else {
        res := whole;
    }
}

method collect_without(
    tree: Option<Node>,
    v: int,
    acc: Option<Node>
) returns (res: Option<Node>)
    requires canonical(acc)
    ensures canonical(res)
    ensures view_opt(res) == view_opt(acc) + (view_opt(tree) - {v})
    decreases tree
{
    if tree.None? {
        res := acc;
        return;
    }

    var n := tree.value;
    var afterLeft := collect_without(n.left, v, acc);
    var afterRight := collect_without(n.right, v, afterLeft);

    if n.val == v {
        res := afterRight;
    } else {
        res := canonical_insert(afterRight, n.val);
    }

    assert view_opt(res)
        == view_opt(acc) + (view_opt(tree) - {v});
}

method delete(tree: Option<Node>, v: int) returns (res: Option<Node>)
    requires is_llrbt_opt(tree)
    ensures
        view_opt(res) == view_opt(tree) - {v}
    ensures
        is_llrbt_opt(res)
{
    res := collect_without(tree, v, None);
    canonical_facts(res);
}
