  {
    if t < seen {
      open_covered(dp, weights, values, next, prevBest, seen, t);
      assert dp[next - weights[t]] + values[t] <= prevBest;
      assert prevBest <= best;
      assert dp[next - weights[t]] + values[t] <= best;
    } else {
      assert t == seen;
      assert weights[seen] <= next;
      assert seen < |values|;
      assert 0 <= next - weights[seen] < |dp|;
      assert dp[next - weights[seen]] + values[seen] <= best;
    }
  }
}

lemma {:vcs_split_on_every_assert} step_at_vacuous(dp: seq<int>, weights: seq<int>, values: seq<int>, j: int, ii: int)
  requires 0 <= ii < |weights|
  requires 0 <= j < |dp|
  requires weights[ii] > j
  ensures StepAt(dp, weights, values, j, ii)
{
  assert weights[ii] > j;
  assert !(weights[ii] <= j);
  assert !(0 <= ii < |weights| && 0 <= j < |dp| && weights[ii] <= j);
  assert StepAt(dp, weights, values, j, ii);
}

lemma {:vcs_split_on_every_assert} step_at_hit(dp: seq<int>, weights: seq<int>, values: seq<int>, j: int, ii: int)
  requires 0 <= ii < |weights|
  requires 0 <= j < |dp|
  requires weights[ii] <= j
  requires ii < |values|
  requires 0 <= j - weights[ii] < |dp|
  requires dp[j - weights[ii]] + values[ii] <= dp[j]
  ensures StepAt(dp, weights, values, j, ii)
{
  assert ii < |values|;
  assert 0 <= j - weights[ii] < |dp|;
  assert dp[j - weights[ii]] + values[ii] <= dp[j];
  assert StepAt(dp, weights, values, j, ii);
}

lemma dp_bound_from_parts(dp: seq<int>, c: int)
  requires forall j {:trigger dp[j]} :: 0 <= j <= c ==> j < |dp| && dp[j] >= 0
  ensures DpBound(dp, c)
{
  reveal DpBound();
}

lemma dp_steps_from_parts(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int)
  requires forall j, ii {:trigger StepAt(dp, weights, values, j, ii)} ::
      0 <= j <= c && 0 <= ii < |weights| ==>
        StepAt(dp, weights, values, j, ii)
  ensures DpSteps(dp, weights, values, c)
{
  reveal DpSteps();
}

lemma dp_ok_from_parts(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int)
  requires |dp| == c + 1
  requires DpBound(dp, c)
  requires DpSteps(dp, weights, values, c)
  ensures DpOK(dp, weights, values, c)
{
  reveal DpOK();
}

lemma witness_from_parts(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, c: int)
  requires |dp| == c + 1
  requires |wit| == c + 1
  requires forall j {:trigger WitnessAt(dp, wit, weights, values, j)} ::
      0 <= j <= c ==> WitnessAt(dp, wit, weights, values, j)
  ensures WitnessState(dp, wit, weights, values, c)
{
  reveal WitnessAll();
  reveal WitnessState();
}

lemma dp_lengths(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int)
  requires DpOK(dp, weights, values, c)
  ensures |dp| == c + 1
{
  reveal DpOK();
}

lemma witness_lengths(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, c: int)
  requires WitnessState(dp, wit, weights, values, c)
  ensures |dp| == c + 1
  ensures |wit| == c + 1
{
  reveal WitnessState();
