lemma {:vcs_split_on_every_assert} dp_cell_old(
  dp: seq<int>,
  dpNext: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  best: int,
  j: int,
  ii: int
)
  requires DpOK(dp, weights, values, c)
  requires dpNext == dp + [best]
  requires 0 <= j <= c
  requires 0 <= ii < |weights|
  requires weights[ii] <= j
  ensures j < |dpNext|
  ensures ii < |values|
  ensures 0 <= j - weights[ii] < |dpNext|
  ensures dpNext[j - weights[ii]] + values[ii] <= dpNext[j]
{
  open_dp_step(dp, weights, values, c, j, ii);
  append_len(dp, best);
  var idxx := j - weights[ii];
  assert 0 <= idxx < |dp|;
  assert j < |dp|;
  assert idxx == j - weights[ii];
  append_prefix(dp, best, idxx);
  append_prefix(dp, best, j);
  assert dpNext[idxx] == dp[idxx];
  assert dpNext[j] == dp[j];
  assert |dpNext| == |dp| + 1;
  assert idxx < |dpNext|;
  assert j < |dpNext|;
  assert 0 <= j - weights[ii] < |dpNext|;
  assert ii < |values|;
  assert dpNext[idxx] + values[ii] <= dpNext[j];
  assert dpNext[j - weights[ii]] == dpNext[idxx];
  assert dpNext[j - weights[ii]] + values[ii] <= dpNext[j];
}

lemma {:vcs_split_on_every_assert} dp_cell_new(
  dp: seq<int>,
  dpNext: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  next: int,
  best: int,
  j: int,
  ii: int
)
  requires dpNext == dp + [best]
  requires |dp| == next
  requires j == next
  requires CoveredPrefix(dp, weights, values, next, best, |weights|)
  requires 0 <= ii < |weights|
  requires weights[ii] <= next
  ensures j < |dpNext|
  ensures ii < |values|
  ensures 0 <= j - weights[ii] < |dpNext|
  ensures dpNext[j - weights[ii]] + values[ii] <= dpNext[j]
{
  open_covered(dp, weights, values, next, best, |weights|, ii);
  append_len(dp, best);
  var idxx := next - weights[ii];
  assert 0 <= idxx < |dp|;
  assert idxx == next - weights[ii];
  append_prefix(dp, best, idxx);
  assert dpNext[idxx] == dp[idxx];
  assert |(dp + [best])| == |dp| + 1;
  assert (dp + [best])[|dp|] == best;
  assert dpNext[|dp|] == best;
  assert |dp| == next;
  assert dpNext[next] == best;
  assert |dpNext| == next + 1;
  assert j == next;
  assert next < |dpNext|;
  assert j < |dpNext|;
  assert idxx < |dpNext|;
  assert 0 <= j - weights[ii] < |dpNext|;
  assert dpNext[idxx] + values[ii] <= best;
  assert dpNext[idxx] + values[ii] <= dpNext[j];
  assert dpNext[j - weights[ii]] == dpNext[idxx];
  assert dpNext[j - weights[ii]] + values[ii] <= dpNext[j];
  assert ii < |values|;
}

lemma {:vcs_split_on_every_assert} witness_cell_old(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>,
  j: int
)
  requires WitnessState(dp, wit, weights, values, c)
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  requires 0 <= j <= c
  ensures WitnessAt(dpNext, witNext, weights, values, j)
{
  open_witness(dp, wit, weights, values, c, j);
  append_len(dp, best);
  append_len(wit, bestWit);
  append_prefix(dp, best, j);
  append_prefix(wit, bestWit, j);
  assert dpNext[j] == dp[j];
  assert witNext[j] == wit[j];
  assert j < |dp|;
  assert j < |wit|;
  assert |dpNext| == |dp| + 1;
  assert |witNext| == |wit| + 1;
  assert j < |dpNext|;
  assert j < |witNext|;
  assert |witNext[j]| == |weights|;
  assert |witNext[j]| == |values|;
  assert is_valid_strategy(witNext[j], weights, j);
  assert total_value(witNext[j], values) == dpNext[j];
  assert dpNext[j] >= 0;
  assert WitnessAt(dpNext, witNext, weights, values, j);
}

lemma {:vcs_split_on_every_assert} witness_cell_new(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  next: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>,
  j: int
)
  requires |weights| == |values|
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  requires |dp| == next
  requires |wit| == next
  requires j == next
  requires best >= 0
  requires |bestWit| == |values|
  requires is_valid_strategy(bestWit, weights, next)
  requires total_value(bestWit, values) == best
  ensures WitnessAt(dpNext, witNext, weights, values, j)
{
  append_len(dp, best);
  append_len(wit, bestWit);
  assert |dpNext| == next + 1;
  assert |witNext| == next + 1;
  assert dpNext[next] == best;
  assert witNext[next] == bestWit;
  assert j == next;
  assert dpNext[j] == best;
  assert witNext[j] == bestWit;
  assert j < |dpNext|;
  assert j < |witNext|;
  assert |bestWit| == |weights|;
  assert |witNext[j]| == |weights|;
  assert |witNext[j]| == |values|;
  assert is_valid_strategy(bestWit, weights, j);
  assert is_valid_strategy(witNext[j], weights, j);
  assert total_value(bestWit, values) == dpNext[j];
  assert total_value(witNext[j], values) == dpNext[j];
  assert dpNext[j] >= 0;
  assert WitnessAt(dpNext, witNext, weights, values, j);
}

lemma {:vcs_split_on_every_assert} prove_witness_extend(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  next: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>
)
  requires |weights| == |values|
  requires WitnessState(dp, wit, weights, values, c)
  requires next == c + 1
  requires best >= 0
  requires |bestWit| == |values|
  requires is_valid_strategy(bestWit, weights, next)
  requires total_value(bestWit, values) == best
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  ensures WitnessState(dpNext, witNext, weights, values, next)
{
  witness_lengths(dp, wit, weights, values, c);
  assert |dp| == c + 1;
  assert |wit| == c + 1;
  assert |dp| == next;
  assert |wit| == next;
  append_len(dp, best);
  append_len(wit, bestWit);
  assert |dpNext| == next + 1;
  assert |witNext| == next + 1;
  assert |bestWit| == |weights|;

  assert (forall j {:trigger WitnessAt(dpNext, witNext, weights, values, j)} ::
      0 <= j <= next ==> WitnessAt(dpNext, witNext, weights, values, j)) by {
    forall j {:trigger WitnessAt(dpNext, witNext, weights, values, j)} | 0 <= j <= next
      ensures WitnessAt(dpNext, witNext, weights, values, j)
    {
      if j < next {
        assert next == c + 1;
        assert 0 <= j <= c;
        witness_cell_old(dp, wit, weights, values, c, best, bestWit, dpNext, witNext, j);
      } else {
        assert j == next;
        witness_cell_new(dp, wit, weights, values, next, best, bestWit, dpNext, witNext, j);
      }
    }
  };
  witness_from_parts(dpNext, witNext, weights, values, next);
}

lemma {:vcs_split_on_every_assert} prove_dp_extend(
  dp: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  next: int,
  best: int,
  dpNext: seq<int>
)
  requires |weights| == |values|
  requires DpOK(dp, weights, values, c)
  requires next == c + 1
  requires best >= 0
  requires CoveredPrefix(dp, weights, values, next, best, |weights|)
  requires dpNext == dp + [best]
  ensures DpOK(dpNext, weights, values, next)
{
  dp_lengths(dp, weights, values, c);
  assert |dp| == c + 1;
  assert |dp| == next;
  append_len(dp, best);
  assert |dpNext| == |dp| + 1;
  assert |dpNext| == next + 1;
  assert dpNext[|dp|] == best;
  assert dpNext[next] == best;

  assert (forall j {:trigger dpNext[j]} :: 0 <= j <= next ==> j < |dpNext| && dpNext[j] >= 0) by {
    forall j {:trigger dpNext[j]} | 0 <= j <= next
      ensures j < |dpNext| && dpNext[j] >= 0
    {
      assert |dpNext| == next + 1;
      if j < next {
        assert next == c + 1;
        assert 0 <= j <= c;
        open_dp_nonneg(dp, weights, values, c, j);
        append_prefix(dp, best, j);
        assert dpNext[j] == dp[j];
        assert dpNext[j] >= 0;
        assert j < |dpNext|;
      } else {
        assert j == next;
        assert dpNext[j] == best;
        assert best >= 0;
        assert j < |dpNext|;
      }
    }
  };
  dp_bound_from_parts(dpNext, next);

  assert (forall j, ii {:trigger StepAt(dpNext, weights, values, j, ii)} ::
      0 <= j <= next && 0 <= ii < |weights| ==>
        StepAt(dpNext, weights, values, j, ii)) by {
    forall j, ii {:trigger StepAt(dpNext, weights, values, j, ii)} | 0 <= j <= next && 0 <= ii < |weights|
      ensures StepAt(dpNext, weights, values, j, ii)
    {
      assert |dpNext| == next + 1;
      assert 0 <= j < |dpNext|;
      if weights[ii] <= j {
        if j < next {
          assert next == c + 1;
          assert 0 <= j <= c;
          dp_cell_old(dp, dpNext, weights, values, c, best, j, ii);
        } else {
          assert j == next;
          assert weights[ii] <= next;
          dp_cell_new(dp, dpNext, weights, values, next, best, j, ii);
        }
        assert j < |dpNext|;
        assert 0 <= j < |dpNext|;
        assert ii < |values|;
        assert 0 <= j - weights[ii] < |dpNext|;
        assert dpNext[j - weights[ii]] + values[ii] <= dpNext[j];
        step_at_hit(dpNext, weights, values, j, ii);
      } else {
        assert weights[ii] > j;
        step_at_vacuous(dpNext, weights, values, j, ii);
      }
    }
  };
  dp_steps_from_parts(dpNext, weights, values, next);
  dp_ok_from_parts(dpNext, weights, values, next);
}

lemma {:vcs_split_on_every_assert} initial_state(
  weights: seq<int>,
  values: seq<int>,
  dp: seq<int>,
  wit: seq<seq<int>>
)
  requires |weights| == |values|
  requires |weights| > 0
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires dp == [0]
  requires wit == [Zeros(|weights|)]
  ensures WitnessState(dp, wit, weights, values, 0)
  ensures DpOK(dp, weights, values, 0)
{
  zeros_witness(weights, values, 0);
  assert |dp| == 1;
  assert |wit| == 1;
  assert dp[0] == 0;
  assert wit[0] == Zeros(|weights|);
  assert is_valid_strategy(wit[0], weights, 0);
  assert total_value(wit[0], values) == 0;
  assert |wit[0]| == |weights|;
  assert |wit[0]| == |values|;

  assert (forall j {:trigger WitnessAt(dp, wit, weights, values, j)} ::
      0 <= j <= 0 ==> WitnessAt(dp, wit, weights, values, j)) by {
    forall j {:trigger WitnessAt(dp, wit, weights, values, j)} | 0 <= j <= 0
      ensures WitnessAt(dp, wit, weights, values, j)
    {
      assert j == 0;
      assert |wit| == 1;
      assert |dp| == 1;
      assert j < |wit| && j < |dp|;
      assert wit[0] == Zeros(|weights|);
      assert dp[0] == 0;
      assert |wit[0]| == |weights|;
      assert |wit[0]| == |values|;
      assert is_valid_strategy(wit[0], weights, 0);
      assert is_valid_strategy(wit[j], weights, j);
      assert total_value(wit[0], values) == 0;
      assert total_value(wit[j], values) == dp[j];
      assert dp[j] >= 0;
      assert WitnessAt(dp, wit, weights, values, j);
    }
  };
  witness_from_parts(dp, wit, weights, values, 0);

  assert (forall j {:trigger dp[j]} :: 0 <= j <= 0 ==> j < |dp| && dp[j] >= 0) by {
    forall j {:trigger dp[j]} | 0 <= j <= 0
      ensures j < |dp| && dp[j] >= 0
    {
      assert j == 0;
      assert |dp| == 1;
      assert dp[0] == 0;
      assert j < |dp|;
      assert dp[j] >= 0;
    }
  };
  dp_bound_from_parts(dp, 0);

  assert (forall j, ii {:trigger StepAt(dp, weights, values, j, ii)} ::
      0 <= j <= 0 && 0 <= ii < |weights| ==>
        StepAt(dp, weights, values, j, ii)) by {
    forall j, ii {:trigger StepAt(dp, weights, values, j, ii)} | 0 <= j <= 0 && 0 <= ii < |weights|
      ensures StepAt(dp, weights, values, j, ii)
    {
      assert j == 0;
      assert |dp| == 1;
      assert 0 <= j < |dp|;
      assert 0 <= ii < |weights|;
      assert weights[ii] > 0;
      assert weights[ii] > j;
      step_at_vacuous(dp, weights, values, j, ii);
    }
  };
  dp_steps_from_parts(dp, weights, values, 0);
  dp_ok_from_parts(dp, weights, values, 0);
}

lemma step_state(
  dp: seq<int>,
  wit: seq<seq<int>>,
  weights: seq<int>,
  values: seq<int>,
  c: int,
  next: int,
  best: int,
  bestWit: seq<int>,
  dpNext: seq<int>,
  witNext: seq<seq<int>>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires WitnessState(dp, wit, weights, values, c)
  requires DpOK(dp, weights, values, c)
  requires next == c + 1
  requires best >= 0
  requires |bestWit| == |values|
  requires is_valid_strategy(bestWit, weights, next)
  requires total_value(bestWit, values) == best
  requires CoveredPrefix(dp, weights, values, next, best, |weights|)
  requires dpNext == dp + [best]
  requires witNext == wit + [bestWit]
  ensures WitnessState(dpNext, witNext, weights, values, next)
  ensures DpOK(dpNext, weights, values, next)
{
  prove_witness_extend(dp, wit, weights, values, c, next, best, bestWit, dpNext, witNext);
  prove_dp_extend(dp, weights, values, c, next, best, dpNext);
}

lemma {:vcs_split_on_every_assert} strategy_bounded(
  counts: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  cap: int,
  limit: int,
  dp: seq<int>
)
  requires |weights| == |values|
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires |counts| == |weights|
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires total_weight(counts, weights) <= cap
  requires 0 <= cap <= limit
  requires DpOK(dp, weights, values, limit)
  ensures total_value(counts, values) <= dp[cap]
  decreases sum_seq(counts)
{
  sum_nonneg(counts);
  if sum_seq(counts) == 0 {
    all_zero_from_sum(counts);
    total_value_when_all_zero(counts, values);
    open_dp_nonneg(dp, weights, values, limit, cap);
    assert total_value(counts, values) == 0;
    assert dp[cap] >= 0;
    assert total_value(counts, values) <= dp[cap];
  } else {
    assert sum_seq(counts) > 0;
    if |counts| == 0 {
      assert sum_seq(counts) == 0;
      assert false;
    }
    assert |counts| > 0;
    var k := find_positive(counts);
    assert 0 <= k < |counts|;
    assert counts[k] > 0;
    assert counts[k] >= 1;
    assert 0 <= k < |weights|;
    assert |counts| == |values|;
    var rest := DecrAt(counts, k);
    decr_at_spec(counts, k);
    assert |rest| == |counts|;
    forall i | 0 <= i < |rest|
      ensures rest[i] >= 0
    {
      if i == k {
        assert rest[i] == counts[i] - 1;
        assert rest[i] >= 0;
      } else {
        assert rest[i] == counts[i];
        assert rest[i] >= 0;
      }
    }
    forall i | 0 <= i < |weights|
      ensures weights[i] >= 0
    {
      assert weights[i] > 0;
    }
    assert forall i :: 0 <= i < |rest| ==> rest[i] >= 0;
    assert forall i :: 0 <= i < |weights| ==> weights[i] >= 0;
    total_weight_nonneg(rest, weights);
    total_weight_decrement(counts, weights, k);
    total_value_decrement(counts, values, k);
    assert total_weight(rest, weights) == total_weight(counts, weights) - weights[k];
    assert total_weight(counts, weights) == total_weight(rest, weights) + weights[k];
    assert total_weight(rest, weights) >= 0;
    assert total_weight(counts, weights) >= weights[k];
    assert weights[k] > 0;
    if cap < weights[k] {
      assert total_weight(counts, weights) <= cap;
      assert total_weight(counts, weights) >= weights[k];
      assert weights[k] > cap;
      assert false;
      assert total_value(counts, values) <= dp[cap];
    } else {
      assert weights[k] <= cap;
      var newCap := cap - weights[k];
      assert newCap >= 0;
      assert newCap <= cap;
      assert newCap <= limit;
      assert total_weight(rest, weights) <= cap - weights[k];
      assert total_weight(rest, weights) <= newCap;
      sum_decrement(counts, k);
      assert sum_seq(rest) == sum_seq(counts) - 1;
      assert sum_seq(rest) >= 0;
      assert sum_seq(rest) < sum_seq(counts);
      strategy_bounded(rest, weights, values, newCap, limit, dp);
      open_dp_step(dp, weights, values, limit, cap, k);
      assert total_value(rest, values) == total_value(counts, values) - values[k];
      assert total_value(counts, values) == total_value(rest, values) + values[k];
      assert total_value(rest, values) <= dp[newCap];
      assert newCap == cap - weights[k];
      assert dp[newCap] == dp[cap - weights[k]];
      assert dp[newCap] + values[k] <= dp[cap];
      assert total_value(counts, values) <= dp[newCap] + values[k];
      assert total_value(counts, values) <= dp[cap];
    }
  }
}

lemma {:vcs_split_on_every_assert} all_strategies_bounded(
  weights: seq<int>,
  values: seq<int>,
  capacity: int,
  dp: seq<int>,
  max_val: int
)
  requires |weights| == |values|
  requires |weights| > 0
  requires forall i :: 0 <= i < |weights| ==> weights[i] > 0
  requires 0 <= capacity
  requires DpOK(dp, weights, values, capacity)
  requires max_val == dp[capacity]
  ensures forall counts: seq<int> ::
      is_valid_strategy(counts, weights, capacity) ==>
        total_value(counts, values) <= max_val
{
  forall counts | is_valid_strategy(counts, weights, capacity)
    ensures total_value(counts, values) <= max_val
  {
    open_valid(counts, weights, capacity);
    strategy_bounded(counts, weights, values, capacity, capacity, dp);
    assert total_value(counts, values) <= dp[capacity];
    assert dp[capacity] == max_val;
  }
}

lemma {:vcs_split_on_every_assert} ProveExists(
  counts: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  capacity: int,
  max_val: int
)
  requires |weights| == |values|
  requires |counts| <= |values|
  requires is_valid_strategy(counts, weights, capacity)
  requires total_value(counts, values) == max_val
  ensures exists c: seq<int> ::
      is_valid_strategy(c, weights, capacity) &&
      total_value(c, values) == max_val
{
  var c := counts;
  assert is_valid_strategy(c, weights, capacity);
  assert total_value(c, values) == max_val;
