ghost function canon_height(t: Option<Node>): nat
    decreases t
{
    match t
    case None => 0
    case Some(n) =>
        match n.left
        case Some(l) =>
            if l.is_red then 1 + canon_height(l.left)
            else 1 + canon_height(n.left)
        case None => 1
}

ghost predicate canonical(t: Option<Node>)
    decreases t
{
    match t
    case None => true
    case Some(n) =>
        !n.is_red &&
        n.is_bst() &&
        (match n.left
         case Some(l) =>
             if l.is_red then
                 canonical(l.left) &&
                 canonical(l.right) &&
                 canonical(n.right) &&
                 canon_height(l.left) == canon_height(l.right) &&
                 canon_height(l.right) == canon_height(n.right)
             else
                 canonical(n.left) &&
                 canonical(n.right) &&
                 canon_height(n.left) == canon_height(n.right)
         case None =>
             canonical(n.right) &&
             canon_height(n.right) == 0)
}

ghost function option_black_height(t: Option<Node>): int
    decreases t
{
    match t
    case None => 1
    case Some(n) => n.black_height()
}

lemma view_opt_parts(t: Option<Node>)
    ensures view_opt(t) ==
        match t
        case None => {}
        case Some(n) => view_opt(n.left) + view_opt(n.right) + {n.val}
