lemma canonical_facts(t: Option<Node>)
    requires canonical(t)
    ensures is_llrbt_opt(t)
    ensures option_black_height(t) == canon_height(t) + 1
    decreases t
{
    match t
    case None =>
    case Some(n) =>
        match n.left
        case Some(l) =>
            if l.is_red {
                canonical_facts(l.left);
                canonical_facts(l.right);
                canonical_facts(n.right);

                assert option_black_height(l.left)
                    == canon_height(l.left) + 1;
                assert option_black_height(l.right)
                    == canon_height(l.right) + 1;
                assert option_black_height(n.right)
                    == canon_height(n.right) + 1;

                assert l.black_height()
                    == option_black_height(l.left);
                assert l.black_height() != -1;
                assert n.black_height() == l.black_height() + 1;
                assert n.black_height() != -1;

                assert l.satisfies_red_props();
                assert n.satisfies_red_props();
                assert n.is_llrbt();
            } else {
                canonical_facts(n.left);
                canonical_facts(n.right);

                assert option_black_height(n.left)
                    == canon_height(n.left) + 1;
                assert option_black_height(n.right)
