method insert23(t: Option<Node>, x: int)
    returns (
        split: bool,
        a: Option<Node>,
        key: int,
        b: Option<Node>,
        whole: Option<Node>
    )
    requires canonical(t)
    ensures split ==> canonical(a) && canonical(b)
    ensures split ==> canon_height(a) == canon_height(t)
    ensures split ==> canon_height(b) == canon_height(t)
    ensures split ==> view_opt(a) + {key} + view_opt(b)
                       == view_opt(t) + {x}
    ensures split ==> (forall z :: z in view_opt(a) ==> z < key)
    ensures split ==> (forall z :: z in view_opt(b) ==> key < z)
    ensures split ==> x !in view_opt(t)
    ensures !split ==> canonical(whole)
    ensures !split ==> canon_height(whole) == canon_height(t)
    ensures !split ==> view_opt(whole) == view_opt(t) + {x}
    ensures x in view_opt(t) ==> !split
    decreases t
