    if t.None? {
        split := true;
        a := None;
        key := x;
        b := None;
        whole := None;
        return;
    }

    var n := t.value;

    if n.left.Some? && n.left.value.is_red {
        var r := n.left.value;
        var k1 := r.val;
        var k2 := n.val;

        if x == k1 || x == k2 {
            view_opt_parts(t);
            view_opt_parts(n.left);

            assert k1 in r.view();
            assert k1 in view_opt(n.left);
            assert k2 in n.view();

            if x == k1 {
                assert x in view_opt(t);
            } else {
                assert x == k2;
                assert x in view_opt(t);
            }

            assert view_opt(t) + {x} == view_opt(t);

            split := false;
            a := None;
            key := 0;
            b := None;
            whole := t;
            return;
        }

        if x < k1 {
            var s, sa, sk, sb, sw := insert23(r.left, x);

