  dot_eq_value(IncrAt(counts, k), values);
  assert dot(IncrAt(counts, k), values) == dot(counts, values) + values[k];
  assert total_value(IncrAt(counts, k), values) == dot(IncrAt(counts, k), values);
  assert total_value(counts, values) == dot(counts, values);
}

