  requires |counts| <= |xs|
  decreases |counts|
{
  if |counts| == 0 then 0
  else counts[0] * xs[0] + dot(counts[1..], xs[1..])
}

ghost function sum_seq(s: seq<int>): int
  decreases |s|
{
  if |s| == 0 then 0 else s[0] + sum_seq(s[1..])
}

ghost function IncrAt(counts: seq<int>, k: int): seq<int>
  requires 0 <= k < |counts|
{
  counts[k := counts[k] + 1]
}

ghost function DecrAt(counts: seq<int>, k: int): seq<int>
  requires 0 <= k < |counts|
{
  counts[k := counts[k] - 1]
}

ghost predicate StepAt(dp: seq<int>, weights: seq<int>, values: seq<int>, j: int, ii: int)
{
  (0 <= ii < |weights| && 0 <= j < |dp| && weights[ii] <= j) ==>
    (ii < |values| &&
     0 <= j - weights[ii] < |dp| &&
     dp[j - weights[ii]] + values[ii] <= dp[j])
}

ghost predicate {:opaque} DpBound(dp: seq<int>, c: int)
{
  forall j {:trigger dp[j]} :: 0 <= j <= c ==> j < |dp| && dp[j] >= 0
}

ghost predicate {:opaque} DpSteps(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int)
{
  forall j, ii {:trigger StepAt(dp, weights, values, j, ii)} ::
    0 <= j <= c && 0 <= ii < |weights| ==>
      StepAt(dp, weights, values, j, ii)
}

ghost predicate {:opaque} DpOK(dp: seq<int>, weights: seq<int>, values: seq<int>, c: int)
{
  |dp| == c + 1 &&
  DpBound(dp, c) &&
  DpSteps(dp, weights, values, c)
}

ghost predicate WitnessAt(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, j: int)
{
  j < |wit| &&
  j < |dp| &&
  |wit[j]| == |weights| &&
  |wit[j]| == |values| &&
  is_valid_strategy(wit[j], weights, j) &&
  total_value(wit[j], values) == dp[j] &&
  dp[j] >= 0
}

ghost predicate {:opaque} WitnessAll(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, c: int)
{
  forall j {:trigger WitnessAt(dp, wit, weights, values, j)} ::
    0 <= j <= c ==> WitnessAt(dp, wit, weights, values, j)
}

ghost predicate {:opaque} WitnessState(dp: seq<int>, wit: seq<seq<int>>, weights: seq<int>, values: seq<int>, c: int)
{
  |dp| == c + 1 &&
  |wit| == c + 1 &&
  WitnessAll(dp, wit, weights, values, c)
}

ghost predicate CoveredPrefix(dp: seq<int>, weights: seq<int>, values: seq<int>, next: int, best: int, i: int)
  requires 0 <= i <= |weights|
{
  forall t :: 0 <= t < i && weights[t] <= next ==>
    0 <= next - weights[t] < |dp| && t < |values| &&
    dp[next - weights[t]] + values[t] <= best
}

