lemma mul_nonneg(a: int, b: int)
  requires a >= 0 && b >= 0
  ensures a * b >= 0
  decreases a
{
  if a == 0 {
    assert a * b == 0;
  } else {
    mul_nonneg(a - 1, b);
    assert a * b == (a - 1) * b + b;
    assert (a - 1) * b >= 0;
    assert a * b >= 0;
  }
}

lemma {:vcs_split_on_every_assert} dot_nonneg(counts: seq<int>, xs: seq<int>)
  requires |counts| <= |xs|
  requires forall i :: 0 <= i < |counts| ==> counts[i] >= 0
  requires forall i :: 0 <= i < |counts| ==> xs[i] >= 0
  ensures dot(counts, xs) >= 0
  decreases |counts|
{
  if |counts| > 0 {
    forall i | 0 <= i < |counts| - 1
      ensures counts[1..][i] >= 0 && xs[1..][i] >= 0
    {
      assert counts[1..][i] == counts[i + 1];
      assert xs[1..][i] == xs[i + 1];
    }
    mul_nonneg(counts[0], xs[0]);
    dot_nonneg(counts[1..], xs[1..]);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
  }
}

lemma {:vcs_split_on_every_assert} slice_update_head(s: seq<int>, newv: int)
  requires |s| > 0
  ensures (s[0 := newv])[1..] == s[1..]
{
  var left := (s[0 := newv])[1..];
  var right := s[1..];
  assert |left| == |s| - 1;
  assert |right| == |s| - 1;
  forall idx | 0 <= idx < |left|
    ensures left[idx] == right[idx]
  {
    assert 0 <= idx + 1 < |s|;
    assert left[idx] == (s[0 := newv])[idx + 1];
    assert idx + 1 != 0;
    assert (s[0 := newv])[idx + 1] == s[idx + 1];
    assert right[idx] == s[idx + 1];
  }
  seq_equal(left, right);
}

lemma {:vcs_split_on_every_assert} slice_update_commute(s: seq<int>, k: int, newv: int)
  requires 0 < k < |s|
  ensures (s[k := newv])[1..] == s[1..][k - 1 := newv]
{
  var left := (s[k := newv])[1..];
  var right := s[1..][k - 1 := newv];
  assert |left| == |s| - 1;
  assert |s[1..]| == |s| - 1;
  assert 0 <= k - 1 < |s[1..]|;
  assert |right| == |s| - 1;
  forall idx | 0 <= idx < |left|
    ensures left[idx] == right[idx]
  {
    assert 0 <= idx + 1 < |s|;
    assert left[idx] == (s[k := newv])[idx + 1];
    if idx + 1 == k {
      assert left[idx] == newv;
      assert idx == k - 1;
      assert right[idx] == newv;
    } else {
      assert (s[k := newv])[idx + 1] == s[idx + 1];
      assert left[idx] == s[idx + 1];
      assert idx != k - 1;
      assert right[idx] == s[1..][idx];
      assert s[1..][idx] == s[idx + 1];
    }
  }
  seq_equal(left, right);
}

lemma incr_at_spec(counts: seq<int>, k: int)
  requires 0 <= k < |counts|
  ensures |IncrAt(counts, k)| == |counts|
  ensures IncrAt(counts, k)[k] == counts[k] + 1
  ensures forall i :: 0 <= i < |counts| && i != k ==> IncrAt(counts, k)[i] == counts[i]
