lemma {:vcs_split_on_every_assert} dot_increment(counts: seq<int>, xs: seq<int>, k: int)
  requires |counts| == |xs|
  requires 0 <= k < |counts|
  ensures dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[k]
  decreases k
{
  assert IncrAt(counts, k) == counts[k := counts[k] + 1];
  if k == 0 {
    slice_update_head(counts, counts[0] + 1);
    assert (counts[0 := counts[0] + 1])[1..] == counts[1..];
    assert IncrAt(counts, k)[1..] == counts[1..];
    assert IncrAt(counts, k)[0] == counts[0] + 1;
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(IncrAt(counts, k), xs) == (counts[0] + 1) * xs[0] + dot(counts[1..], xs[1..]);
    assert (counts[0] + 1) * xs[0] == counts[0] * xs[0] + xs[0];
    assert dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[0];
  } else {
    slice_update_commute(counts, k, counts[k] + 1);
    assert |counts| == |xs|;
    assert |counts[1..]| == |xs[1..]|;
    assert 0 <= k - 1 < |counts[1..]|;
    assert counts[k] == counts[1..][k - 1];
    assert xs[k] == xs[1..][k - 1];
    assert counts[k] + 1 == counts[1..][k - 1] + 1;
    assert counts[1..][k - 1 := counts[k] + 1] == counts[1..][k - 1 := counts[1..][k - 1] + 1];
    assert IncrAt(counts[1..], k - 1) == counts[1..][k - 1 := counts[1..][k - 1] + 1];
    assert (counts[k := counts[k] + 1])[1..] == counts[1..][k - 1 := counts[k] + 1];
    assert IncrAt(counts, k)[1..] == IncrAt(counts[1..], k - 1);
    assert IncrAt(counts, k)[0] == counts[0];
    dot_increment(counts[1..], xs[1..], k - 1);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(IncrAt(counts, k), xs) == counts[0] * xs[0] + dot(IncrAt(counts, k)[1..], xs[1..]);
    assert dot(IncrAt(counts[1..], k - 1), xs[1..]) == dot(counts[1..], xs[1..]) + xs[1..][k - 1];
    assert dot(IncrAt(counts, k)[1..], xs[1..]) == dot(counts[1..], xs[1..]) + xs[k];
    assert dot(IncrAt(counts, k), xs) == dot(counts, xs) + xs[k];
  }
}

lemma {:vcs_split_on_every_assert} dot_decrement(counts: seq<int>, xs: seq<int>, k: int)
  requires |counts| == |xs|
  requires 0 <= k < |counts|
  ensures dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[k]
  decreases k
{
  assert DecrAt(counts, k) == counts[k := counts[k] - 1];
  if k == 0 {
    slice_update_head(counts, counts[0] - 1);
    assert (counts[0 := counts[0] - 1])[1..] == counts[1..];
    assert DecrAt(counts, k)[1..] == counts[1..];
    assert DecrAt(counts, k)[0] == counts[0] - 1;
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(DecrAt(counts, k), xs) == (counts[0] - 1) * xs[0] + dot(counts[1..], xs[1..]);
    assert (counts[0] - 1) * xs[0] == counts[0] * xs[0] - xs[0];
    assert dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[0];
  } else {
    slice_update_commute(counts, k, counts[k] - 1);
    assert |counts[1..]| == |xs[1..]|;
    assert 0 <= k - 1 < |counts[1..]|;
    assert counts[k] == counts[1..][k - 1];
    assert xs[k] == xs[1..][k - 1];
    assert counts[k] - 1 == counts[1..][k - 1] - 1;
    assert counts[1..][k - 1 := counts[k] - 1] == counts[1..][k - 1 := counts[1..][k - 1] - 1];
    assert DecrAt(counts[1..], k - 1) == counts[1..][k - 1 := counts[1..][k - 1] - 1];
    assert (counts[k := counts[k] - 1])[1..] == counts[1..][k - 1 := counts[k] - 1];
    assert DecrAt(counts, k)[1..] == DecrAt(counts[1..], k - 1);
    assert DecrAt(counts, k)[0] == counts[0];
    dot_decrement(counts[1..], xs[1..], k - 1);
    assert dot(counts, xs) == counts[0] * xs[0] + dot(counts[1..], xs[1..]);
    assert dot(DecrAt(counts, k), xs) == counts[0] * xs[0] + dot(DecrAt(counts, k)[1..], xs[1..]);
    assert dot(DecrAt(counts[1..], k - 1), xs[1..]) == dot(counts[1..], xs[1..]) - xs[1..][k - 1];
    assert dot(DecrAt(counts, k)[1..], xs[1..]) == dot(counts[1..], xs[1..]) - xs[k];
    assert dot(DecrAt(counts, k), xs) == dot(counts, xs) - xs[k];
  }
}

