    assert dot(Zeros(|xs| - 1), xs[1..]) == 0;
    assert dot(Zeros(|xs|)[1..], xs[1..]) == dot(Zeros(|xs| - 1), xs[1..]);
    assert dot(Zeros(|xs|), xs) == 0;
  }
}

lemma {:vcs_split_on_every_assert} dot_eq_weight(counts: seq<int>, weights: seq<int>)
