lemma {:vcs_split_on_every_assert} increment_ok(
  base: seq<int>,
  weights: seq<int>,
  values: seq<int>,
  k: int,
  cap: int,
  baseCap: int,
  baseVal: int
)
  requires |weights| == |values|
  requires 0 <= k < |weights|
  requires is_valid_strategy(base, weights, baseCap)
  requires total_value(base, values) == baseVal
  requires baseCap + weights[k] <= cap
  ensures is_valid_strategy(IncrAt(base, k), weights, cap)
  ensures total_value(IncrAt(base, k), values) == baseVal + values[k]
  ensures |IncrAt(base, k)| == |weights|
{
  open_valid(base, weights, baseCap);
  incr_at_spec(base, k);
  var nw := IncrAt(base, k);
  assert |nw| == |base|;
  assert |base| == |weights|;
  total_weight_increment(base, weights, k);
  total_value_increment(base, values, k);
  forall i | 0 <= i < |nw|
    ensures nw[i] >= 0
  {
    if i == k {
      assert nw[i] == base[i] + 1;
      assert base[i] >= 0;
    } else {
      assert nw[i] == base[i];
      assert base[i] >= 0;
    }
  }
  assert total_weight(nw, weights) == total_weight(base, weights) + weights[k];
  assert total_weight(base, weights) <= baseCap;
  assert total_weight(nw, weights) <= baseCap + weights[k];
  assert total_weight(nw, weights) <= cap;
  assert total_value(nw, values) == total_value(base, values) + values[k];
  assert total_value(nw, values) == baseVal + values[k];
  assert |nw| == |weights|;
  assert forall i :: 0 <= i < |nw| ==> nw[i] >= 0;
  assert is_valid_strategy(nw, weights, cap);
}

