method flip_colors(node: Node) returns (res: Node)
    requires node.left.Some? && node.right.Some?
    // Precondition: Parent color differs from children, children have same color
    // (Standard case: Black Parent, Red Children)
    requires node.is_red != node.left.value.is_red
    requires node.left.value.is_red == node.right.value.is_red
    // Explicitly ensure result children exist so .value access is safe
    ensures res.left.Some? && res.right.Some?
    ensures 
        res.view() == node.view()
    ensures
        res.is_bst() == node.is_bst()
    ensures
        // Preservation of Balance: Swapping colors here preserves Black Height
        res.black_height() == node.black_height()
    ensures
        // Toggles
        res.is_red != node.is_red
    ensures
        res.left.value.is_red != node.left.value.is_red
{
    var l := node.left.value;
    var r := node.right.value;
    var nl := Node(l.val, !l.is_red, l.left, l.right);
    var nr := Node(r.val, !r.is_red, r.left, r.right);
    res := Node(node.val, !node.is_red, Some(nl), Some(nr));

    assert nl.view() == l.view();
    assert nr.view() == r.view();
    assert nl.is_bst() == l.is_bst();
    assert nr.is_bst() == r.is_bst();

    assert nl.black_height() == (if l.black_height() == -1 then -1
                                 else if l.is_red then l.black_height() + 1
                                 else l.black_height() - 1);
    assert nr.black_height() == (if r.black_height() == -1 then -1
                                 else if r.is_red then r.black_height() + 1
                                 else r.black_height() - 1);
    assert res.view() == nl.view() + nr.view() + {node.val};
    assert node.view() == l.view() + r.view() + {node.val};
}

response:
Flipping the colors builds a new node. The root's color is toggled, both children's colors are toggled, and everything else is unchanged.

- **`view` and `is_bst`**: each new child has the same value and subtrees as the old one, so both are preserved. This needs only one level of unfolding, which the first two pairs of asserts give.
- **`black_height`**: the precondition says both children have the same color. Flipping both shifts their heights the same way: +1 if a child was red, −1 if it was black, unchanged if it was invalid (−1). Toggling the root then cancels that shift. The asserts state this rule for each child.

