lemma ToggleBlackHeight(n: Node)
    ensures
        (n.black_height() == -1) ==
        (Node(n.val, !n.is_red, n.left, n.right).black_height() == -1)
    ensures n.black_height() != -1 && n.is_red ==>
        Node(n.val, !n.is_red, n.left, n.right).black_height()
            == n.black_height() + 1
    ensures n.black_height() != -1 && !n.is_red ==>
        Node(n.val, !n.is_red, n.left, n.right).black_height()
            == n.black_height() - 1
{
    BlackHeightRange(n);

    var t := Node(n.val, !n.is_red, n.left, n.right);
    var lh := match n.left {
        case Some(l) => l.black_height()
        case None => 1
    };
    var rh := match n.right {
        case Some(r) => r.black_height()
        case None => 1
