function minSize(h: int): int
  requires h >= 1
  decreases h
{
  if h == 1 then 0 else 1 + 2 * minSize(h - 1)
}

function maxSize(h: int): int
  requires h >= 1
  decreases h
{
  if h == 1 then 0 else 2 + 3 * maxSize(h - 1)
}

ghost function SetOf(s: seq<int>): set<int> {
  set i | 0 <= i < |s| :: s[i]
}

ghost predicate StrictlySorted(s: seq<int>) {
  forall i, j :: 0 <= i < j < |s| ==> s[i] < s[j]
}

ghost predicate AllLt(s: seq<int>, v: int) {
  forall i :: 0 <= i < |s| ==> s[i] < v
}

ghost predicate AllGt(s: seq<int>, v: int) {
  forall i :: 0 <= i < |s| ==> s[i] > v
}

ghost predicate AllBetween(s: seq<int>, lo: int, hi: int) {
  forall i :: 0 <= i < |s| ==> lo < s[i] < hi
}

