      assert (pre + one)[k] == s[i];
      assert t[k] == s[i];
    } else {
      assert |pre + one| == i + 1;
      assert t[k] == post[k - (i + 1)];
      assert post[k - i - 1] == s[k];
    }
  }
  assert t == s;
}

lemma LemmaSlicePrefix(s: seq<int>, j: int, i: int)
  requires 0 <= i <= j <= |s|
  ensures s[..j][..i] == s[..i]
{
  var a := s[..j][..i];
  var b := s[..i];
  assert |a| == |b|;
  forall k | 0 <= k < |a|
    ensures a[k] == b[k]
  {
    assert a[k] == s[k];
    assert b[k] == s[k];
  }
  assert a == b;
}

lemma LemmaSliceAt(s: seq<int>, j: int, i: int)
  requires 0 <= i < j <= |s|
  ensures (s[..j])[i] == s[i]
{
  assert (s[..j])[i] == s[i];
}

lemma LemmaSliceSuffix(s: seq<int>, j: int, i: int)
  requires 0 <= i <= j <= |s|
  ensures s[..j][i..] == s[i..j]
{
  var a := s[..j][i..];
  var b := s[i..j];
  assert |a| == |b|;
  forall k | 0 <= k < |a|
    ensures a[k] == b[k]
  {
    assert a[k] == s[i + k];
    assert b[k] == s[i + k];
  }
  assert a == b;
}

lemma LemmaSetSplit2(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures SetOf(s) == SetOf(s[..i]) + {s[i]} + SetOf(s[i + 1..])
{
  LemmaSeqSplit(s, i);
  var left := s[..i];
  var mid := [s[i]];
  var right := s[i + 1..];
  var lm := left + mid;
  LemmaSetOfAppend(left, mid);
  LemmaSetOfSingleton(s[i]);
  assert SetOf(lm) == SetOf(left) + {s[i]};
  LemmaSetOfAppend(lm, right);
  assert lm + right == left + mid + right;
  assert left + mid + right == s;
  assert SetOf(s) == SetOf(lm) + SetOf(right);
  assert SetOf(s) == SetOf(left) + {s[i]} + SetOf(right);
}

lemma LemmaSetSplit3(s: seq<int>, ia: int, ib: int)
  requires 0 <= ia < ib < |s|
  ensures SetOf(s) == SetOf(s[..ia]) + {s[ia]} + SetOf(s[ia + 1..ib]) + {s[ib]} + SetOf(s[ib + 1..])
{
  LemmaSetSplit2(s, ib);
  assert SetOf(s) == SetOf(s[..ib]) + {s[ib]} + SetOf(s[ib + 1..]);
  var pref := s[..ib];
  assert |pref| == ib;
  assert 0 <= ia < |pref|;
  LemmaSetSplit2(pref, ia);
  LemmaSlicePrefix(s, ib, ia);
  LemmaSliceAt(s, ib, ia);
  LemmaSliceSuffix(s, ib, ia + 1);
  assert pref[..ia] == s[..ia];
  assert pref[ia] == s[ia];
  assert pref[ia + 1..] == s[ia + 1..ib];
  assert SetOf(pref) == SetOf(s[..ia]) + {s[ia]} + SetOf(s[ia + 1..ib]);
  assert SetOf(s) == SetOf(s[..ia]) + {s[ia]} + SetOf(s[ia + 1..ib]) + {s[ib]} + SetOf(s[ib + 1..]);
}

lemma LemmaSliceSorted(s: seq<int>, lo: int, hi: int)
  requires StrictlySorted(s)
  requires 0 <= lo <= hi <= |s|
  ensures StrictlySorted(s[lo..hi])
{
  var t := s[lo..hi];
  forall i, j | 0 <= i < j < |t|
    ensures t[i] < t[j]
  {
    assert t[i] == s[lo + i];
    assert t[j] == s[lo + j];
    assert s[lo + i] < s[lo + j];
  }
}

lemma LemmaPrefixAllLt(s: seq<int>, k: int)
  requires StrictlySorted(s)
  requires 0 <= k < |s|
  ensures AllLt(s[..k], s[k])
{
  var t := s[..k];
  forall i | 0 <= i < |t|
    ensures t[i] < s[k]
  {
    assert t[i] == s[i];
    assert i < k;
    assert s[i] < s[k];
  }
}

lemma LemmaSuffixAllGt(s: seq<int>, k: int)
  requires StrictlySorted(s)
  requires 0 <= k < |s|
  ensures AllGt(s[k + 1..], s[k])
{
  var t := s[k + 1..];
  forall i | 0 <= i < |t|
    ensures t[i] > s[k]
  {
    assert t[i] == s[k + 1 + i];
    assert k < k + 1 + i;
    assert s[k + 1 + i] > s[k];
  }
}

lemma LemmaMidBetween(s: seq<int>, lo: int, hi: int)
  requires StrictlySorted(s)
  requires 0 <= lo < hi < |s|
  ensures AllBetween(s[lo + 1..hi], s[lo], s[hi])
{
  var t := s[lo + 1..hi];
  forall i | 0 <= i < |t|
    ensures s[lo] < t[i] < s[hi]
  {
    assert t[i] == s[lo + 1 + i];
    assert lo < lo + 1 + i < hi;
    assert s[lo] < s[lo + 1 + i];
    assert s[lo + 1 + i] < s[hi];
  }
}

lemma LemmaBetweenSplit(s: seq<int>, lo: int, hi: int)
  requires AllBetween(s, lo, hi)
  ensures AllGt(s, lo)
  ensures AllLt(s, hi)
{
  forall i | 0 <= i < |s|
    ensures s[i] > lo && s[i] < hi
  {
    assert lo < s[i] < hi;
  }
}

lemma LemmaAllLtTrans(s: seq<int>, mid: int, bound: int)
  requires AllLt(s, mid)
  requires mid < bound
  ensures AllLt(s, bound)
{
  forall i | 0 <= i < |s|
    ensures s[i] < bound
  {
    assert s[i] < mid;
  }
}

lemma LemmaAllLtSet(s: seq<int>, v: int)
  requires AllLt(s, v)
  ensures forall x :: x in SetOf(s) ==> x < v
{
  forall x | x in SetOf(s)
    ensures x < v
  {
    var i :| 0 <= i < |s| && s[i] == x;
    assert s[i] < v;
  }
}

lemma LemmaAllGtSet(s: seq<int>, v: int)
  requires AllGt(s, v)
  ensures forall x :: x in SetOf(s) ==> x > v
{
  forall x | x in SetOf(s)
    ensures x > v
  {
    var i :| 0 <= i < |s| && s[i] == x;
    assert s[i] > v;
  }
}

lemma LemmaSeqFromSetLt(s: seq<int>, v: int)
  requires forall x :: x in SetOf(s) ==> x < v
  ensures AllLt(s, v)
{
  forall i | 0 <= i < |s|
    ensures s[i] < v
  {
    assert s[i] in SetOf(s);
  }
}

lemma LemmaSeqFromSetGt(s: seq<int>, v: int)
  requires forall x :: x in SetOf(s) ==> x > v
  ensures AllGt(s, v)
{
  forall i | 0 <= i < |s|
    ensures s[i] > v
  {
    assert s[i] in SetOf(s);
  }
}

lemma LemmaSandwichAt(a: seq<int>, v: int, b: seq<int>, i: int)
  requires 0 <= i < |a| + 1 + |b|
  ensures var s := a + [v] + b;
    (i < |a| ==> s[i] == a[i]) &&
    (i == |a| ==> s[i] == v) &&
    (i > |a| ==> s[i] == b[i - |a| - 1])
{
  var s := a + [v] + b;
  var left := a + [v];
  assert |left| == |a| + 1;
  assert s == left + b;
  if i < |a| {
    assert s[i] == a[i];
  } else if i == |a| {
    assert left[i] == v;
    assert s[i] == v;
  } else {
    assert s[i] == b[i - |a| - 1];
  }
}

lemma {:vcs_split_on_every_assert} LemmaSortedSandwich(a: seq<int>, v: int, b: seq<int>)
  requires StrictlySorted(a)
  requires StrictlySorted(b)
  requires AllLt(a, v)
  requires AllGt(b, v)
  ensures StrictlySorted(a + [v] + b)
{
  var s := a + [v] + b;
  assert |s| == |a| + 1 + |b|;
  forall i, j | 0 <= i < j < |s|
    ensures s[i] < s[j]
  {
    LemmaSandwichAt(a, v, b, i);
    LemmaSandwichAt(a, v, b, j);
    if j < |a| {
      assert s[i] == a[i];
      assert s[j] == a[j];
      assert a[i] < a[j];
    } else if i > |a| {
      var i2 := i - |a| - 1;
      var j2 := j - |a| - 1;
      assert s[i] == b[i2];
      assert s[j] == b[j2];
      assert 0 <= i2 < j2 < |b|;
      assert b[i2] < b[j2];
    } else if i < |a| && j == |a| {
      assert s[i] == a[i];
      assert s[j] == v;
      assert a[i] < v;
    } else if i == |a| {
      var j2 := j - |a| - 1;
      assert j > |a|;
      assert s[i] == v;
      assert s[j] == b[j2];
      assert 0 <= j2 < |b|;
      assert b[j2] > v;
    } else {
      var j2 := j - |a| - 1;
      assert i < |a| && j > |a|;
      assert s[i] == a[i];
      assert s[j] == b[j2];
      assert 0 <= j2 < |b|;
      assert a[i] < v;
      assert b[j2] > v;
    }
  }
}

lemma LemmaView(n: Node)
  ensures n.view() == view_opt(n.left) + view_opt(n.right) + {n.val}
{
  match n.left {
    case Some(l) => assert view_opt(n.left) == l.view();
    case None => assert view_opt(n.left) == {};
  }
  match n.right {
    case Some(r) => assert view_opt(n.right) == r.view();
    case None => assert view_opt(n.right) == {};
  }
  assert n.view() == view_opt(n.left) + view_opt(n.right) + {n.val};
}

lemma LemmaBH(n: Node, childBh: int)
  requires childBh >= 1
  requires BHOpt(n.left) == childBh
  requires BHOpt(n.right) == childBh
  ensures n.black_height() == if n.is_red then childBh else childBh + 1
{
  if n.left.Some? {
    assert n.left.value.black_height() == childBh;
  } else {
    assert childBh == 1;
  }
  if n.right.Some? {
    assert n.right.value.black_height() == childBh;
  } else {
    assert childBh == 1;
  }
  assert n.black_height() == if n.is_red then childBh else childBh + 1;
}

lemma ChildBST(n: Node)
  requires n.is_bst()
  ensures n.left.Some? ==> n.left.value.is_bst()
  ensures n.right.Some? ==> n.right.value.is_bst()
  ensures n.left.Some? ==> forall x :: x in n.left.value.view() ==> x < n.val
  ensures n.right.Some? ==> forall x :: x in n.right.value.view() ==> x > n.val
{
  if n.left.Some? {
    var l := n.left.value;
    assert l.is_bst();
    assert forall x :: x in l.view() ==> x < n.val;
  }
  if n.right.Some? {
    var r := n.right.value;
    assert r.is_bst();
    assert forall x :: x in r.view() ==> x > n.val;
  }
}

lemma {:vcs_split_on_every_assert} LemmaJoin(n: Node, childBh: int, ls: seq<int>, rs: seq<int>)
  requires childBh >= 1
  requires BHOpt(n.left) == childBh
  requires BHOpt(n.right) == childBh
  requires is_llrbt_opt(n.left)
  requires is_llrbt_opt(n.right)
  requires n.left.Some? ==> !n.left.value.is_red
  requires n.right.Some? ==> !n.right.value.is_red
  requires view_opt(n.left) == SetOf(ls)
  requires view_opt(n.right) == SetOf(rs)
  requires AllLt(ls, n.val)
  requires AllGt(rs, n.val)
  ensures n.is_llrbt()
  ensures n.black_height() == if n.is_red then childBh else childBh + 1
  ensures n.view() == SetOf(ls) + {n.val} + SetOf(rs)
{
  LemmaAllLtSet(ls, n.val);
  LemmaAllGtSet(rs, n.val);
  forall x | x in view_opt(n.left)
    ensures x < n.val
  {
    assert x in SetOf(ls);
  }
  forall x | x in view_opt(n.right)
    ensures x > n.val
  {
    assert x in SetOf(rs);
  }
  if n.left.Some? {
    var l := n.left.value;
    assert l.is_llrbt();
    assert l.is_bst();
    assert l.satisfies_red_props();
    assert !l.is_red;
    assert l.view() == view_opt(n.left);
    assert forall x :: x in l.view() ==> x < n.val;
  }
  if n.right.Some? {
    var r := n.right.value;
    assert r.is_llrbt();
    assert r.is_bst();
    assert r.satisfies_red_props();
    assert !r.is_red;
    assert r.view() == view_opt(n.right);
    assert forall x :: x in r.view() ==> x > n.val;
  }
  assert n.is_bst();
  assert n.satisfies_red_props();
  LemmaBH(n, childBh);
  assert n.black_height() == if n.is_red then childBh else childBh + 1;
  assert n.black_height() != -1;
  assert n.is_llrbt();
  LemmaView(n);
  assert n.view() == view_opt(n.left) + view_opt(n.right) + {n.val};
  assert n.view() == SetOf(ls) + SetOf(rs) + {n.val};
  assert SetOf(ls) + SetOf(rs) + {n.val} == SetOf(ls) + {n.val} + SetOf(rs);
}

lemma {:vcs_split_on_every_assert} LemmaBlackWithRedLeft(n: Node, h: int)
  requires h >= 2
  requires !n.is_red
  requires n.left.Some?
  requires n.left.value.is_red
  requires n.left.value.is_llrbt()
  requires n.left.value.black_height() == h - 1
  requires BHOpt(n.right) == h - 1
  requires is_llrbt_opt(n.right)
  requires n.right.Some? ==> !n.right.value.is_red
  requires n.left.value.left.Some? ==> !n.left.value.left.value.is_red
  requires forall x :: x in n.left.value.view() ==> x < n.val
  requires forall x :: x in view_opt(n.right) ==> x > n.val
  ensures n.is_llrbt()
  ensures n.black_height() == h
  ensures n.view() == n.left.value.view() + view_opt(n.right) + {n.val}
{
  var red := n.left.value;
  assert red.is_llrbt();
  assert red.is_bst();
  assert red.satisfies_red_props();
  assert red.is_red;
  assert forall x :: x in red.view() ==> x < n.val;
  if red.left.Some? {
    assert !red.left.value.is_red;
  }
  if n.right.Some? {
    var r := n.right.value;
    assert r.is_llrbt();
    assert r.is_bst();
    assert r.satisfies_red_props();
    assert !r.is_red;
    assert r.view() == view_opt(n.right);
    assert forall x :: x in r.view() ==> x > n.val;
  }
  assert n.is_bst();
  assert n.satisfies_red_props();
  assert BHOpt(n.left) == red.black_height() == h - 1;
  LemmaBH(n, h - 1);
  assert n.black_height() == h;
  assert n.black_height() != -1;
  assert n.is_llrbt();
  LemmaView(n);
  assert n.view() == red.view() + view_opt(n.right) + {n.val};
}

lemma LemmaConnectBH(t: Option<Node>, bh: int)
  requires bh >= 1
  requires t.None? <==> bh == 1
  requires t.Some? ==> t.value.black_height() == bh
  ensures BHOpt(t) == bh
{
  if t.Some? {
    assert t.value.black_height() == bh;
    assert BHOpt(t) == bh;
  } else {
    assert bh == 1;
    assert BHOpt(t) == 1;
  }
}

method {:vcs_split_on_every_assert} FindHeight(n: int) returns (h: int)
  requires n >= 1
  ensures h >= 2
  ensures minSize(h) <= n <= maxSize(h)
{
  h := 2;
  while maxSize(h) < n
    invariant h >= 2
    invariant h <= n + 1
    invariant h == 2 || maxSize(h - 1) < n
    decreases n + 1 - h
  {
    var oldH := h;
    assert maxSize(oldH) < n;
    LemmaMaxSizeGe(oldH);
    assert maxSize(oldH) >= oldH;
    assert oldH < n;
    assert oldH + 1 <= n + 1;
    h := oldH + 1;
    assert maxSize(h - 1) < n;
  }
  assert maxSize(h) >= n;
  if h == 2 {
    assert minSize(1) == 0;
    assert minSize(2) == 1 + 2 * minSize(1);
    assert minSize(2) == 1;
    assert minSize(2) <= n;
  } else {
    assert maxSize(h - 1) < n;
    LemmaMinFitsPrevMax(h);
    assert minSize(h) <= maxSize(h - 1) + 1 <= n;
  }
}

method Split2(rem: int, lo: int, hi: int) returns (a: int, b: int)
  requires 0 <= lo <= hi
  requires 2 * lo <= rem <= 2 * hi
  ensures lo <= a <= hi
  ensures lo <= b <= hi
  ensures a + b == rem
{
  if rem - lo <= hi {
    a := rem - lo;
    b := lo;
    assert a == rem - lo;
    assert rem >= 2 * lo;
    assert a >= lo;
    assert a <= hi;
    assert a + b == rem;
  } else {
    a := hi;
    b := rem - hi;
    assert rem - lo > hi;
    assert b > lo;
    assert b >= lo;
    assert rem <= 2 * hi;
    assert b <= hi;
    assert a + b == rem;
  }
}

method Split3(rem: int, lo: int, hi: int) returns (a: int, b: int, c: int)
  requires 0 <= lo <= hi
  requires 3 * lo <= rem <= 3 * hi
  ensures lo <= a <= hi
  ensures lo <= b <= hi
  ensures lo <= c <= hi
  ensures a + b + c == rem
{
  if rem - 2 * lo <= hi {
    a := rem - 2 * lo;
    b := lo;
    c := lo;
    assert a == rem - 2 * lo;
    assert rem >= 3 * lo;
    assert a >= lo;
    assert a <= hi;
    assert a + b + c == rem;
  } else {
    a := hi;
    var rest := rem - hi;
    assert rem - 2 * lo > hi;
    assert rest > 2 * lo;
    assert rest >= 2 * lo + 1;
    assert rem <= 3 * hi;
    assert rest <= 2 * hi;
    if rest - lo <= hi {
      b := rest - lo;
      c := lo;
      assert b >= (2 * lo + 1) - lo;
      assert b >= lo;
      assert b <= hi;
      assert a + b + c == rem;
    } else {
      b := hi;
      c := rest - hi;
      assert rest - lo > hi;
      assert c > lo;
      assert c >= lo;
      assert c <= hi;
      assert a + b + c == rem;
    }
  }
}

method {:vcs_split_on_every_assert} BuildOfHeight(s: seq<int>, h: int) returns (t: Option<Node>)
  requires h >= 1
  requires minSize(h) <= |s| <= maxSize(h)
  requires StrictlySorted(s)
  ensures is_llrbt_opt(t)
  ensures view_opt(t) == SetOf(s)
  ensures t.None? <==> h == 1
  ensures t.Some? ==> !t.value.is_red && t.value.black_height() == h
  decreases h
{
  if h == 1 {
    assert maxSize(1) == 0;
    assert minSize(1) == 0;
    assert |s| == 0;
    assert s == [];
    LemmaSetOfEmpty();
    t := None;
    assert view_opt(t) == {};
    assert SetOf(s) == {};
  } else {
    var n := |s|;
    var lo := minSize(h - 1);
    var hi := maxSize(h - 1);
    LemmaMaxMinRatio(h - 1);
    assert 0 <= lo <= hi;
    assert minSize(h) == 1 + 2 * lo;
    assert maxSize(h) == 2 + 3 * hi;
    assert n >= 1;
    if n <= 1 + 2 * hi {
      var rem := n - 1;
      assert 2 * lo <= rem <= 2 * hi;
      var a, b := Split2(rem, lo, hi);
      assert 0 <= a < n;
      assert a + b == rem;
      assert b == n - 1 - a;
      LemmaSliceSorted(s, 0, a);
      LemmaSliceSorted(s, a + 1, n);
      var leftSeq := s[..a];
      var rightSeq := s[a + 1..];
      var rootv := s[a];
      assert |leftSeq| == a;
      assert |rightSeq| == b;
      assert StrictlySorted(leftSeq);
      assert StrictlySorted(rightSeq);
      assert minSize(h - 1) <= |leftSeq| <= maxSize(h - 1);
      assert minSize(h - 1) <= |rightSeq| <= maxSize(h - 1);
      var leftTree := BuildOfHeight(leftSeq, h - 1);
      var rightTree := BuildOfHeight(rightSeq, h - 1);
      LemmaConnectBH(leftTree, h - 1);
      LemmaConnectBH(rightTree, h - 1);
      assert BHOpt(leftTree) == h - 1;
      assert BHOpt(rightTree) == h - 1;
      LemmaPrefixAllLt(s, a);
      LemmaSuffixAllGt(s, a);
      assert AllLt(leftSeq, rootv);
      assert AllGt(rightSeq, rootv);
      var node := Node(rootv, false, leftTree, rightTree);
      assert view_opt(node.left) == SetOf(leftSeq);
      assert view_opt(node.right) == SetOf(rightSeq);
      assert is_llrbt_opt(node.left);
      assert is_llrbt_opt(node.right);
      if node.left.Some? {
        assert !node.left.value.is_red;
      }
      if node.right.Some? {
        assert !node.right.value.is_red;
      }
      LemmaJoin(node, h - 1, leftSeq, rightSeq);
      LemmaSetSplit2(s, a);
      assert node.view() == SetOf(leftSeq) + {rootv} + SetOf(rightSeq);
      assert SetOf(s) == SetOf(leftSeq) + {rootv} + SetOf(rightSeq);
      assert node.view() == SetOf(s);
      assert node.black_height() == h;
      assert node.is_llrbt();
      t := Some(node);
      assert view_opt(t) == node.view();
    } else {
      var rem := n - 2;
      assert n >= 2 + 2 * hi;
      assert 2 * hi >= 3 * lo;
      assert 3 * lo <= rem <= 3 * hi;
      var aSize, bSize, cSize := Split3(rem, lo, hi);
      assert aSize + bSize + cSize + 2 == n;
      var ia := aSize;
      var ib := aSize + 1 + bSize;
      assert ib == n - 1 - cSize;
      assert 0 <= ia < ib < n;
      assert s[ia] < s[ib];
      LemmaSliceSorted(s, 0, ia);
      LemmaSliceSorted(s, ia + 1, ib);
      LemmaSliceSorted(s, ib + 1, n);
      var aSeq := s[..ia];
      var bSeq := s[ia + 1..ib];
      var cSeq := s[ib + 1..];
      var rv := s[ia];
      var bv := s[ib];
      assert |aSeq| == aSize;
      assert |bSeq| == bSize;
      assert |cSeq| == cSize;
      assert StrictlySorted(aSeq) && StrictlySorted(bSeq) && StrictlySorted(cSeq);
      assert minSize(h - 1) <= |aSeq| <= maxSize(h - 1);
      assert minSize(h - 1) <= |bSeq| <= maxSize(h - 1);
      assert minSize(h - 1) <= |cSeq| <= maxSize(h - 1);
      LemmaPrefixAllLt(s, ia);
