lemma LemmaRemoveAt(s: seq<int>, k: int, j: int)
  requires 0 <= k < |s|
  requires 0 <= j < |s| - 1
  ensures (s[..k] + s[k + 1..])[j] == if j < k then s[j] else s[j + 1]
{
  var r := s[..k] + s[k + 1..];
  if j < k {
    assert j < |s[..k]|;
    assert r[j] == s[j];
  } else {
    assert r[j] == (s[k + 1..])[j - k];
    assert (s[k + 1..])[j - k] == s[k + 1 + (j - k)];
    assert k + 1 + (j - k) == j + 1;
  }
}

lemma LemmaUnique(s: seq<int>, k: int)
  requires StrictlySorted(s)
  requires 0 <= k < |s|
  ensures forall i :: 0 <= i < |s| && i != k ==> s[i] != s[k]
{
  forall i | 0 <= i < |s| && i != k
    ensures s[i] != s[k]
  {
    if i < k {
      assert s[i] < s[k];
    } else {
      assert s[k] < s[i];
    }
  }
}

lemma {:vcs_split_on_every_assert} LemmaSortedRemove(s: seq<int>, k: int)
  requires StrictlySorted(s)
  requires 0 <= k < |s|
  ensures StrictlySorted(s[..k] + s[k + 1..])
{
  var r := s[..k] + s[k + 1..];
  assert |r| == |s| - 1;
  forall i, j | 0 <= i < j < |r|
    ensures r[i] < r[j]
  {
    LemmaRemoveAt(s, k, i);
    LemmaRemoveAt(s, k, j);
    var ii := if i < k then i else i + 1;
    var jj := if j < k then j else j + 1;
    assert r[i] == s[ii];
    assert r[j] == s[jj];
    if j < k {
      assert ii == i && jj == j && ii < jj;
    } else if i >= k {
      assert ii == i + 1 && jj == j + 1 && ii < jj;
    } else {
      assert i < k <= j;
      assert ii == i && jj == j + 1 && ii < jj;
    }
    assert s[ii] < s[jj];
  }
}

lemma {:vcs_split_on_every_assert} LemmaSetRemove(s: seq<int>, k: int)
