    assert i == |s| || (i < |s| && s[i] > v);
    LemmaAbsent(s, i, v);
    r := s;
    if v in SetOf(s) {
      var k :| 0 <= k < |s| && s[k] == v;
      assert s[k] != v;
      assert false;
    }
    assert v !in SetOf(s);
    assert SetOf(r) == SetOf(s) - {v};
    assert StrictlySorted(r);
  }
}

