lemma AddRowAt(m: seq<seq<int>>, dst: int, src: int, i: int)
  requires 0 <= dst < |m| && 0 <= src < |m|
  requires |m[dst]| == |m[src]|
  requires 0 <= i < |m|
  ensures |AddRowTo(m, dst, src)| == |m|
  ensures i == dst ==> AddRowTo(m, dst, src)[i] == XorRow(m[dst], m[src])
  ensures i != dst ==> AddRowTo(m, dst, src)[i] == m[i]
{
  var n := AddRowTo(m, dst, src);
  assert n == m[dst := XorRow(m[dst], m[src])];
  assert |n| == |m|;
  if i == dst {
    assert n[i] == XorRow(m[dst], m[src]);
  } else {
    assert n[i] == m[i];
  }
}

lemma {:vcs_split_on_every_assert} AddRowPreservesSol(
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  x: seq<int>,
  nCols: int)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  requires forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1
  requires forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(AddRowTo(aug, dst, src), x, nCols)
{
  var newA := AddRowTo(aug, dst, src);
  var r1 := aug[dst];
  var r2 := aug[src];
  var xr := XorRow(r1, r2);
  assert |r1| == nCols + 1 && |r2| == nCols + 1;
  assert newA[dst] == xr;
  forall i | 0 <= i < |aug|
    ensures |newA[i]| == nCols + 1
  {
    if i == dst {
      AddRowAt(aug, dst, src, i);
      assert |xr| == nCols + 1;
    } else {
      AddRowAt(aug, dst, src, i);
      assert newA[i] == aug[i];
    }
  }

  assert forall j :: 0 <= j <= nCols - 1 && j < |r1| && j < |x| ==>
    IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j]) by {
    forall j | 0 <= j <= nCols - 1 && j < |r1| && j < |x|
      ensures IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j])
    {
      assert IsBit(r1[j]);
      assert IsBit(r2[j]);
      assert 0 <= j < |x|;
      assert x[j] == 0 || x[j] == 1;
      assert IsBit(x[j]);
    }
  };
  DotLinear(r1, r2, x, nCols - 1);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r1| && j < |x| ==> IsBit(r1[j]) && IsBit(x[j]);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r2| && j < |x| ==> IsBit(r2[j]) && IsBit(x[j]);
  DotIsBit(r1, x, nCols - 1);
  DotIsBit(r2, x, nCols - 1);

  assert SolvesAug(aug, x, nCols) ==> SolvesAug(newA, x, nCols) by {
    if SolvesAug(aug, x, nCols) {
      forall i | 0 <= i < |newA|
        ensures |newA[i]| == nCols + 1 &&
          spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          assert sd == r1[nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(r1[nCols], r2[nCols]) == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          assert newA[i] == xr;
        }
      }
    }
  };

  assert SolvesAug(newA, x, nCols) ==> SolvesAug(aug, x, nCols) by {
    if SolvesAug(newA, x, nCols) {
      forall i | 0 <= i < |aug|
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          AddRowAt(aug, dst, src, src);
          assert newA[src] == aug[src];
          assert spec_dot_product_gf2(newA[src], x, nCols - 1) == newA[src][nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          assert newA[dst] == xr;
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == add_gf2(r1[nCols], r2[nCols]);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert IsBit(sd) && IsBit(ss);
          assert IsBit(r1[nCols]) && IsBit(r2[nCols]);
          assert ss == r2[nCols];
          XorCancel(sd, ss);
          XorCancel(r1[nCols], ss);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], ss);
          assert add_gf2(add_gf2(sd, ss), ss) == add_gf2(add_gf2(r1[nCols], ss), ss);
          assert add_gf2(add_gf2(sd, ss), ss) == sd;
          assert add_gf2(add_gf2(r1[nCols], ss), ss) == r1[nCols];
          assert sd == r1[nCols];
        }
      }
    }
  };
}

lemma SwapRowEq(m: seq<seq<int>>, r1: int, r2: int, i: int)
  requires 0 <= r1 < |m| && 0 <= r2 < |m| && 0 <= i < |m|
  ensures SwapRows(m, r1, r2)[i] ==
    (if r1 == r2 then m[i] else if i == r1 then m[r2] else if i == r2 then m[r1] else m[i])
{
  if r1 == r2 {
    assert SwapRows(m, r1, r2) == m;
  } else {
    var m1 := m[r1 := m[r2]];
    var m2 := m1[r2 := m[r1]];
    assert SwapRows(m, r1, r2) == m2;
    assert m1[r1] == m[r2];
    if i == r2 {
      assert m2[r2] == m[r1];
    } else if i == r1 {
      assert m2[r1] == m1[r1];
      assert m1[r1] == m[r2];
    } else {
      assert m1[i] == m[i];
      assert m2[i] == m1[i];
    }
  }
}

lemma {:vcs_split_on_every_assert} SwapPreservesSol(
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  x: seq<int>,
  nCols: int)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(SwapRows(aug, r1, r2), x, nCols)
{
  var s := SwapRows(aug, r1, r2);
  assert |s| == |aug|;

  assert SolvesAug(aug, x, nCols) ==> SolvesAug(s, x, nCols) by {
    if SolvesAug(aug, x, nCols) {
      forall i | 0 <= i < |s|
        ensures |s[i]| == nCols + 1 &&
          spec_dot_product_gf2(s[i], x, nCols - 1) == s[i][nCols]
      {
        var src := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, i);
        assert s[i] == aug[src];
        assert 0 <= src < |aug|;
        assert spec_dot_product_gf2(aug[src], x, nCols - 1) == aug[src][nCols];
      }
    }
  };

  assert SolvesAug(s, x, nCols) ==> SolvesAug(aug, x, nCols) by {
    if SolvesAug(s, x, nCols) {
      forall i | 0 <= i < |aug|
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        var dst := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, dst);
        if r1 == r2 {
          assert s[dst] == aug[i];
        } else if i == r1 {
          assert dst == r2;
          assert s[dst] == aug[r1];
        } else if i == r2 {
          assert dst == r1;
          assert s[dst] == aug[r2];
        } else {
          assert dst == i;
          assert s[dst] == aug[i];
        }
        assert s[dst] == aug[i];
        assert spec_dot_product_gf2(s[dst], x, nCols - 1) == s[dst][nCols];
        assert |aug[i]| == nCols + 1;
      }
    }
  };
}

lemma {:vcs_split_on_every_assert} SameSolAfterAdd(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  ensures SameSol(matrix, b, AddRowTo(aug, dst, src), nCols)
{
  reveal SameSol();
  var newA := AddRowTo(aug, dst, src);
  forall x | |x| == nCols && is_binary_vector(x)
    ensures is_solution(matrix, b, x) <==> SolvesAug(newA, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    assert forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1;
    assert forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j]);
    AddRowPreservesSol(aug, dst, src, x, nCols);
  }
}

lemma {:vcs_split_on_every_assert} SameSolAfterSwap(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  ensures SameSol(matrix, b, SwapRows(aug, r1, r2), nCols)
{
  reveal SameSol();
  var s := SwapRows(aug, r1, r2);
  forall x | |x| == nCols && is_binary_vector(x)
    ensures is_solution(matrix, b, x) <==> SolvesAug(s, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    SwapPreservesSol(aug, r1, r2, x, nCols);
  }
}

