function IsRed(t: Option<Node>): bool {
    match t
    case Some(n) => n.is_red
    case None => false
}

function LeftOf(t: Option<Node>): Option<Node> {
    match t
    case Some(n) => n.left
    case None => None
}

function repaint(n: Node, c: bool): Node {
    Node(n.val, c, n.left, n.right)
}

function repaintOpt(t: Option<Node>, c: bool): Option<Node> {
    match t
    case Some(n) => Some(repaint(n, c))
    case None => None
}

ghost function bhOpt(t: Option<Node>): int {
    match t
    case Some(n) => n.black_height()
    case None => 1
}

ghost predicate linkOk(t: Option<Node>) {
    !IsRed(t) || !IsRed(LeftOf(t))
}

ghost predicate poised(n: Node) {
    n.is_bst() &&
    is_llrbt_opt(n.left) &&
    is_llrbt_opt(n.right) &&
    bhOpt(n.left) == bhOpt(n.right)
}

function rotateLeft(n: Node): Node
    requires IsRed(n.right)
{
    match n.right
    case Some(r) =>
        Node(r.val, n.is_red,
             Some(Node(n.val, true, n.left, r.left)),
             r.right)
}

function rotateRight(n: Node): Node
    requires IsRed(n.left)
{
    match n.left
    case Some(l) =>
        Node(l.val, n.is_red,
             l.left,
             Some(Node(n.val, true, l.right, n.right)))
}

function colorFlip(n: Node): Node {
    Node(n.val, true,
         repaintOpt(n.left, false),
         repaintOpt(n.right, false))
}

function balance(n: Node): Node {
    var a :=
        if IsRed(n.right) && !IsRed(n.left)
        then rotateLeft(n)
        else n;

    var b :=
        if IsRed(a.left) && IsRed(LeftOf(a.left))
        then rotateRight(a)
        else a;

    if IsRed(b.left) && IsRed(b.right)
    then colorFlip(b)
    else b
}

function insertImpl(tree: Option<Node>, v: int): Node
    decreases tree
{
    match tree
    case None =>
        Node(v, true, None, None)

    case Some(n) =>
        if v < n.val then
            balance(Node(n.val, n.is_red,
                         Some(insertImpl(n.left, v)),
                         n.right))
        else if v > n.val then
            balance(Node(n.val, n.is_red,
                         n.left,
                         Some(insertImpl(n.right, v))))
        else
            n
}

