lemma {:vcs_split_on_every_assert} ParentPreservesViewBST(node: Node, res: Node)
    requires node.left.Some? && node.right.Some?
    requires res.left.Some? && res.right.Some?
    requires res.val == node.val
    requires res.left.value.val == node.left.value.val
    requires res.left.value.left == node.left.value.left
    requires res.left.value.right == node.left.value.right
    requires res.right.value.val == node.right.value.val
    requires res.right.value.left == node.right.value.left
    requires res.right.value.right == node.right.value.right
    ensures res.view() == node.view()
    ensures res.is_bst() == node.is_bst()
{
    var l := node.left.value;
    var r := node.right.value;
    var nl := res.left.value;
    var nr := res.right.value;

    assert node.left == Some(l);
    assert node.right == Some(r);
    assert res.left == Some(nl);
    assert res.right == Some(nr);

    SameUnderColor(l, nl);
    SameUnderColor(r, nr);
    NodeParts(node, l, r);
    NodeParts(res, nl, nr);

    assert l.view() == nl.view();
    assert r.view() == nr.view();
    assert l.is_bst() == nl.is_bst();
    assert r.is_bst() == nr.is_bst();
    assert node.val == res.val;

    assert node.view() == l.view() + r.view() + {node.val};
    assert res.view() == nl.view() + nr.view() + {res.val};
    assert node.view() == res.view();

    SetBoundLess(l.view(), nl.view(), node.val);
    SetBoundGreater(r.view(), nr.view(), node.val);

    assert (forall x :: x in l.view() ==> x < node.val)
        == (forall x :: x in nl.view() ==> x < node.val);
    assert (forall x :: x in nl.view() ==> x < node.val)
        == (forall x :: x in nl.view() ==> x < res.val);
    assert (forall x :: x in r.view() ==> x > node.val)
        == (forall x :: x in nr.view() ==> x > node.val);
    assert (forall x :: x in nr.view() ==> x > node.val)
        == (forall x :: x in nr.view() ==> x > res.val);

    assert node.is_bst() == (
        (forall x :: x in l.view() ==> x < node.val) && l.is_bst() &&
        (forall x :: x in r.view() ==> x > node.val) && r.is_bst());
    assert res.is_bst() == (
        (forall x :: x in nl.view() ==> x < res.val) && nl.is_bst() &&
        (forall x :: x in nr.view() ==> x > res.val) && nr.is_bst());
    assert node.is_bst() == res.is_bst();
