    LHSome(node, l);
    RHSome(node, r);
    LHSome(res, newL);
    RHSome(res, newR);
    OpenBH(node);
    OpenBH(res);

    var lb := l.black_height();
    var rb := r.black_height();
    var lb2 := newL.black_height();
    var rb2 := newR.black_height();

    assert LH(node) == lb && RH(node) == rb;
    assert LH(res) == lb2 && RH(res) == rb2;

    assert node.black_height() == (
        if lb != -1 && rb != -1 && lb == rb then
            if !node.is_red then lb + 1 else lb
        else
            -1
    );
    assert res.black_height() == (
        if lb2 != -1 && rb2 != -1 && lb2 == rb2 then
            if !res.is_red then lb2 + 1 else lb2
        else
            -1
    );

    assert (lb == -1) == (lb2 == -1);
    assert (rb == -1) == (rb2 == -1);
    assert l.is_red == r.is_red;
    assert node.is_red != l.is_red;
    assert res.is_red == !node.is_red;

    if lb != -1 && rb != -1 && lb == rb {
        assert lb2 == lb + (if l.is_red then 1 else -1);
        assert rb2 == rb + (if l.is_red then 1 else -1);
        assert lb2 == rb2;
        assert lb2 != -1 && rb2 != -1;

