            assert node.is_red;
            assert !res.is_red;
            assert node.black_height() == lb;
            assert lb2 == lb - 1;
            assert res.black_height() == lb2 + 1;
            assert lb2 + 1 == lb;
            assert node.black_height() == res.black_height();
