            assert res.black_height() == -1;
        } else if rb == -1 {
            assert rb2 == -1;
            assert res.black_height() == -1;
        } else {
            assert lb != rb;
            assert lb != -1 && rb != -1;
            var delta := if l.is_red then 1 else -1;
            assert lb2 == lb + delta;
            assert rb2 == rb + delta;
