    var r := node.right.value;
    var newL := l.(is_red := !l.is_red);
    var newR := r.(is_red := !r.is_red);
    res := node.(is_red := !node.is_red, left := Some(newL), right := Some(newR));

    assert res.val == node.val;
    assert res.is_red == !node.is_red;
    assert res.left == Some(newL);
    assert res.right == Some(newR);
    assert newL.val == l.val && newL.left == l.left && newL.right == l.right && newL.is_red == !l.is_red;
    assert newR.val == r.val && newR.left == r.left && newR.right == r.right && newR.is_red == !r.is_red;
    assert l == node.left.value && r == node.right.value;
    assert res.left.value.val == node.left.value.val;
    assert res.left.value.left == node.left.value.left;
    assert res.left.value.right == node.left.value.right;
    assert res.left.value.is_red == !node.left.value.is_red;
    assert res.right.value.val == node.right.value.val;
    assert res.right.value.left == node.right.value.left;
    assert res.right.value.right == node.right.value.right;
    assert res.right.value.is_red == !node.right.value.is_red;

    ParentPreservesViewBST(node, res);
    FlipPreservesBlackHeight(node, res);

