    case None => None
}

function repaint(n: Node, c: bool): Node {
    Node(n.val, c, n.left, n.right)
}

function repaintOpt(t: Option<Node>, c: bool): Option<Node> {
    match t
    case Some(n) => Some(repaint(n, c))
    case None => None
}

ghost function bhOpt(t: Option<Node>): int {
