    case Some(l) =>
        Node(l.val, n.is_red,
             l.left,
             Some(Node(n.val, true, l.right, n.right)))
}

function colorFlip(n: Node): Node {
    Node(n.val, true,
         repaintOpt(n.left, false),
         repaintOpt(n.right, false))
}

function balance(n: Node): Node {
    var a :=
        if IsRed(n.right) && !IsRed(n.left)
        then rotateLeft(n)
        else n;

    var b :=
        if IsRed(a.left) && IsRed(LeftOf(a.left))
        then rotateRight(a)
        else a;

    if IsRed(b.left) && IsRed(b.right)
