lemma {:vcs_split_on_every_assert} BalanceLemma(n: Node)
    requires poised(n)
    requires !IsRed(n.right) || linkOk(n.right)
    requires !(IsRed(n.right) &&
               IsRed(n.left) &&
               IsRed(LeftOf(n.left)))
    ensures balance(n).view() == n.view()
    ensures balance(n).is_llrbt()
    ensures balance(n).black_height() ==
        bhOpt(n.left) +
        (if n.is_red then 0 else 1) +
        (if n.is_red &&
             ((IsRed(n.left) && IsRed(LeftOf(n.left))) ||
              (IsRed(n.left) && IsRed(n.right)))
         then 1 else 0)
    ensures !n.is_red ==> linkOk(Some(balance(n)))
{
    var first := IsRed(n.right) && !IsRed(n.left);

    if first {
        assert IsRed(n.right);
        assert !IsRed(n.left);
        assert linkOk(n.right);

        RotateLeftLemma(n);
        var a := rotateLeft(n);

        assert a.is_llrbt();
        assert a.view() == n.view();
        assert !IsRed(LeftOf(a.left));
        assert !(IsRed(a.left) && IsRed(LeftOf(a.left)));
        assert !IsRed(a.right);
        assert balance(n) == a;

        assert !(IsRed(n.left) && IsRed(LeftOf(n.left)));
        assert !(IsRed(n.left) && IsRed(n.right));
        assert !(n.is_red &&
                 ((IsRed(n.left) && IsRed(LeftOf(n.left))) ||
                  (IsRed(n.left) && IsRed(n.right))));

    } else {
        var second :=
            IsRed(n.left) && IsRed(LeftOf(n.left));

        if second {
            assert IsRed(n.left);
            assert IsRed(LeftOf(n.left));
            assert !IsRed(n.right);

            RotateRightPreparedLemma(n);
            var a := rotateRight(n);

            assert poised(a);
            assert IsRed(a.left);
            assert IsRed(a.right);
            ColorFlipLemma(a);

            assert balance(n) == colorFlip(a);
            assert colorFlip(a).view() == n.view();
            assert colorFlip(a).is_llrbt();

            match n.left
            case None =>
                assert false;

            case Some(l) =>
                assert l.is_red;
                assert l.is_llrbt();
                assert bhOpt(l.left) == bhOpt(l.right);
                assert l.black_height() == bhOpt(l.left);
                assert bhOpt(n.left) == l.black_height();
                assert bhOpt(a.left) == bhOpt(l.left);
                assert bhOpt(a.left) == bhOpt(n.left);

            if n.is_red {
                assert n.is_red &&
                       ((IsRed(n.left) &&
                         IsRed(LeftOf(n.left))) ||
                        (IsRed(n.left) && IsRed(n.right)));
            }

        } else if IsRed(n.left) && IsRed(n.right) {
            assert !second;
            ColorFlipLemma(n);

            assert balance(n) == colorFlip(n);
            assert colorFlip(n).view() == n.view();
            assert colorFlip(n).is_llrbt();

            if n.is_red {
                assert n.is_red &&
                       ((IsRed(n.left) &&
                         IsRed(LeftOf(n.left))) ||
                        (IsRed(n.left) && IsRed(n.right)));
            }

        } else {
            assert !IsRed(n.right);
            assert !(IsRed(n.left) && IsRed(LeftOf(n.left)));
            assert !(IsRed(n.left) && IsRed(n.right));

            assert n.is_bst();
            assert is_llrbt_opt(n.left);
            assert is_llrbt_opt(n.right);
            assert bhOpt(n.left) == bhOpt(n.right);
            assert !IsRed(n.right);

            BhOptBound(n.left);
            assert bhOpt(n.left) != -1;
            assert bhOpt(n.left) >= 1;

            assert n.satisfies_red_props();
            assert n.black_height() ==
                   bhOpt(n.left) + (if n.is_red then 0 else 1);

            if n.is_red {
                assert n.black_height() == bhOpt(n.left);
                assert n.black_height() >= 1;
            } else {
                assert n.black_height() == bhOpt(n.left) + 1;
                assert n.black_height() >= 2;
            }

            assert n.black_height() != -1;
            assert n.is_llrbt();
            assert balance(n) == n;

            assert !(n.is_red &&
                     ((IsRed(n.left) &&
                       IsRed(LeftOf(n.left))) ||
                      (IsRed(n.left) && IsRed(n.right))));
        }
    }
}

