  if a.right.Some? {
    var c := a.right.value;
    assert a.right == Some(c);
    assert b.right == Some(c);
    RHSome(a, c);
    RHSome(b, c);
  } else {
    assert a.right == None;
    assert b.right == None;
    RHNone(a);
    RHNone(b);
  }
}

lemma RHEqualsLHOfRightChild(a: Node, b: Node)
  requires a.right == b.left
  ensures RH(a) == LH(b)
{
  if a.right.Some? {
    var c := a.right.value;
    assert a.right == Some(c);
    assert b.left == Some(c);
    RHSome(a, c);
    LHSome(b, c);
  } else {
    assert a.right == None;
    assert b.left == None;
    RHNone(a);
    LHNone(b);
  }
}

lemma BHMatches(n: Node)
  ensures n.black_height() == BhOf(LH(n), RH(n), n.is_red)
{
  var lh := match n.left { case Some(l) => l.black_height() case None => 1 };
  var rh := match n.right { case Some(r) => r.black_height() case None => 1 };
  assert lh == LH(n);
  assert rh == RH(n);
  assert n.black_height() == (if lh != -1 && rh != -1 && lh == rh then
                                (if !n.is_red then lh + 1 else lh)
                              else
                                -1);
  assert BhOf(lh, rh, n.is_red) == (if lh != -1 && rh != -1 && lh == rh then
                                      (if !n.is_red then lh + 1 else lh)
                                    else
                                      -1);
  assert n.black_height() == BhOf(lh, rh, n.is_red);
}

lemma BhOfRed(lh: int, rh: int)
  ensures BhOf(lh, rh, true) == (if lh != -1 && rh != -1 && lh == rh then lh else -1)
{
  if lh != -1 && rh != -1 && lh == rh {
    assert BhOf(lh, rh, true) == (if !true then lh + 1 else lh);
    assert (if !true then lh + 1 else lh) == lh;
    assert BhOf(lh, rh, true) == lh;
  } else {
    assert BhOf(lh, rh, true) == (if lh != -1 && rh != -1 && lh == rh then (if !true then lh + 1 else lh) else -1);
    assert BhOf(lh, rh, true) == -1;
  }
}

lemma {:vcs_split_on_every_assert} RotateBhInts(lhN: int, lhR: int, rhR: int, nodeRed: bool)
  ensures BhOf(BhOf(lhN, lhR, true), rhR, nodeRed) == BhOf(lhN, BhOf(lhR, rhR, true), nodeRed)
{
  BhOfRed(lhR, rhR);
  BhOfRed(lhN, lhR);

  var innerR := BhOf(lhR, rhR, true);
  var bhNew := BhOf(lhN, lhR, true);
  var bhN := BhOf(lhN, innerR, nodeRed);
  var bhRes := BhOf(bhNew, rhR, nodeRed);

  assert innerR == (if lhR != -1 && rhR != -1 && lhR == rhR then lhR else -1);
  assert bhNew == (if lhN != -1 && lhR != -1 && lhN == lhR then lhN else -1);
  assert bhN == (if lhN != -1 && innerR != -1 && lhN == innerR then (if !nodeRed then lhN + 1 else lhN) else -1);
  assert bhRes == (if bhNew != -1 && rhR != -1 && bhNew == rhR then (if !nodeRed then bhNew + 1 else bhNew) else -1);

  if lhN != -1 && innerR != -1 && lhN == innerR {
    if !(lhR != -1 && rhR != -1 && lhR == rhR) {
      assert innerR == -1;
      assert false;
    }
    assert lhR != -1 && rhR != -1 && lhR == rhR;
    assert innerR == lhR;
    assert lhN == lhR;
    assert lhN == rhR;
    assert bhNew == lhN;
    assert bhNew == rhR;
    assert bhNew != -1 && rhR != -1 && bhNew == rhR;
    assert bhRes == (if !nodeRed then bhNew + 1 else bhNew);
    assert bhN == (if !nodeRed then lhN + 1 else lhN);
    assert bhNew == lhN;
    assert bhRes == bhN;
  } else {
    assert !(lhN != -1 && innerR != -1 && lhN == innerR);
    assert bhN == -1;
    if bhNew != -1 && rhR != -1 && bhNew == rhR {
      if !(lhN != -1 && lhR != -1 && lhN == lhR) {
        assert bhNew == -1;
        assert false;
      }
      assert lhN != -1 && lhR != -1 && lhN == lhR;
      assert bhNew == lhN;
      assert lhR == rhR;
      assert rhR != -1;
      assert lhR != -1 && rhR != -1 && lhR == rhR;
      assert innerR == lhR;
      assert lhN == innerR;
      assert innerR != -1;
      assert lhN != -1 && innerR != -1 && lhN == innerR;
      assert false;
    }
    assert !(bhNew != -1 && rhR != -1 && bhNew == rhR);
    assert bhRes == -1;
    assert bhRes == bhN;
  }

  assert bhRes == bhN;
  assert bhRes == BhOf(BhOf(lhN, lhR, true), rhR, nodeRed);
  assert bhN == BhOf(lhN, BhOf(lhR, rhR, true), nodeRed);
}

lemma {:vcs_split_on_every_assert} ProveBH(node: Node, r: Node, newLeft: Node, res: Node)
  requires node.right == Some(r)
  requires r.is_red
  requires newLeft == Node(node.val, true, node.left, r.left)
  requires res == Node(r.val, node.is_red, Some(newLeft), r.right)
  ensures res.black_height() == node.black_height()
{
  var lhN := LH(node);
  var lhR := LH(r);
  var rhR := RH(r);

  assert newLeft.left == node.left;
  assert newLeft.right == r.left;
  assert newLeft.is_red == true;
  assert res.left == Some(newLeft);
  assert res.right == r.right;
  assert res.is_red == node.is_red;

  BHMatches(r);
  assert r.black_height() == BhOf(lhR, rhR, true);

  RHSome(node, r);
  assert RH(node) == r.black_height();

  BHMatches(node);
  assert node.black_height() == BhOf(lhN, RH(node), node.is_red);
  assert node.black_height() == BhOf(lhN, BhOf(lhR, rhR, true), node.is_red);

  LHDependsOnLeft(newLeft, node);
  assert LH(newLeft) == lhN;
  RHEqualsLHOfRightChild(newLeft, r);
  assert RH(newLeft) == lhR;

  BHMatches(newLeft);
  assert newLeft.black_height() == BhOf(lhN, lhR, true);

  LHSome(res, newLeft);
  assert LH(res) == newLeft.black_height();
  RHDependsOnRight(res, r);
  assert RH(res) == rhR;

  BHMatches(res);
  assert res.black_height() == BhOf(LH(res), RH(res), res.is_red);
  assert res.black_height() == BhOf(newLeft.black_height(), rhR, node.is_red);
  assert res.black_height() == BhOf(BhOf(lhN, lhR, true), rhR, node.is_red);

  RotateBhInts(lhN, lhR, rhR, node.is_red);
  assert res.black_height() == node.black_height();
}

lemma VMatches(n: Node)
  ensures n.view() == VL(n) + VR(n) + {n.val}
{
  var ls := match n.left { case Some(l) => l.view() case None => {} };
  var rs := match n.right { case Some(r) => r.view() case None => {} };
  assert ls == VL(n);
  assert rs == VR(n);
  assert n.view() == ls + rs + {n.val};
  assert n.view() == VL(n) + VR(n) + {n.val};
}

lemma VLSome(n: Node, c: Node)
  requires n.left == Some(c)
  ensures VL(n) == c.view()
{
  assert VL(n) == (match n.left { case Some(l2) => l2.view() case None => {} });
  match n.left {
    case Some(l) =>
      assert l == c;
      assert (match n.left { case Some(l2) => l2.view() case None => {} }) == l.view();
      assert VL(n) == c.view();
    case None =>
      assert n.left == Some(c);
      assert false;
  }
}

lemma VLNone(n: Node)
  requires n.left == None
  ensures VL(n) == {}
{
  assert VL(n) == (match n.left { case Some(l2) => l2.view() case None => {} });
  match n.left {
    case Some(l) =>
      assert n.left == None;
      assert false;
    case None =>
      assert (match n.left { case Some(l2) => l2.view() case None => {} }) == {};
      assert VL(n) == {};
  }
}

lemma VRSome(n: Node, c: Node)
  requires n.right == Some(c)
  ensures VR(n) == c.view()
{
  assert VR(n) == (match n.right { case Some(r2) => r2.view() case None => {} });
  match n.right {
    case Some(r) =>
      assert r == c;
      assert (match n.right { case Some(r2) => r2.view() case None => {} }) == r.view();
      assert VR(n) == c.view();
    case None =>
      assert n.right == Some(c);
      assert false;
  }
}

lemma VRNone(n: Node)
  requires n.right == None
  ensures VR(n) == {}
{
  assert VR(n) == (match n.right { case Some(r2) => r2.view() case None => {} });
  match n.right {
    case Some(r) =>
      assert n.right == None;
      assert false;
    case None =>
      assert (match n.right { case Some(r2) => r2.view() case None => {} }) == {};
      assert VR(n) == {};
  }
}

lemma VLSame(a: Node, b: Node)
  requires a.left == b.left
  ensures VL(a) == VL(b)
{
  if a.left.Some? {
    var c := a.left.value;
    assert a.left == Some(c);
    assert b.left == Some(c);
    VLSome(a, c);
    VLSome(b, c);
  } else {
    assert a.left == None;
    assert b.left == None;
    VLNone(a);
    VLNone(b);
  }
}

lemma VRSame(a: Node, b: Node)
  requires a.right == b.right
  ensures VR(a) == VR(b)
{
  if a.right.Some? {
    var c := a.right.value;
    assert a.right == Some(c);
    assert b.right == Some(c);
    VRSome(a, c);
    VRSome(b, c);
  } else {
    assert a.right == None;
    assert b.right == None;
    VRNone(a);
    VRNone(b);
  }
}

lemma VREqVL(a: Node, b: Node)
  requires a.right == b.left
  ensures VR(a) == VL(b)
{
  if a.right.Some? {
    var c := a.right.value;
    assert a.right == Some(c);
    assert b.left == Some(c);
    VRSome(a, c);
    VLSome(b, c);
  } else {
    assert a.right == None;
    assert b.left == None;
    VRNone(a);
    VLNone(b);
  }
}

lemma ValInOwnView(n: Node)
  ensures n.val in n.view()
{
  VMatches(n);
  assert n.val in VL(n) + VR(n) + {n.val};
  assert n.val in n.view();
}

lemma LeftViewSubset(n: Node, l: Node)
  requires n.left == Some(l)
  ensures l.view() <= n.view()
{
  VMatches(n);
  VLSome(n, l);
  assert l.view() == VL(n);
  assert n.view() == VL(n) + VR(n) + {n.val};
  assert VL(n) <= VL(n) + VR(n) + {n.val};
  assert l.view() <= n.view();
}

lemma {:vcs_split_on_every_assert} ProveView(node: Node, r: Node, newLeft: Node, res: Node)
  requires node.right == Some(r)
  requires newLeft == Node(node.val, true, node.left, r.left)
  requires res == Node(r.val, node.is_red, Some(newLeft), r.right)
  ensures res.view() == node.view()
{
  VMatches(node);
  VMatches(r);
  VMatches(newLeft);
  VMatches(res);

  assert newLeft.left == node.left;
  assert newLeft.right == r.left;
  assert newLeft.val == node.val;
  assert res.left == Some(newLeft);
  assert res.right == r.right;
  assert res.val == r.val;

  VLSame(newLeft, node);
  VREqVL(newLeft, r);
  VRSome(node, r);
  VRSame(res, r);
  VLSome(res, newLeft);

  var A := VL(node);
  var B := VL(r);
  var C := VR(r);

  assert VL(newLeft) == A;
  assert VR(newLeft) == B;
  assert VR(node) == r.view();
  assert VR(res) == C;
  assert VL(res) == newLeft.view();

  assert newLeft.view() == A + B + {node.val};
  assert r.view() == B + C + {r.val};
  assert node.view() == A + r.view() + {node.val};
  assert res.view() == VL(res) + VR(res) + {res.val};
  assert res.view() == newLeft.view() + C + {r.val};

  forall z {:trigger z in res.view()} {:trigger z in node.view()}
    ensures z in res.view() <==> z in node.view()
  {
    assert res.view() == newLeft.view() + C + {r.val};
    assert newLeft.view() == A + B + {node.val};
    assert r.view() == B + C + {r.val};
    assert node.view() == A + r.view() + {node.val};

    if z in res.view() {
      assert z in (newLeft.view() + C) + {r.val};
      if z == r.val {
        assert z in {r.val};
        assert z in B + C + {r.val};
        assert z in r.view();
        assert z in A + r.view() + {node.val};
        assert z in node.view();
      } else {
        assert z in newLeft.view() + C || z == r.val;
        assert z != r.val;
        assert z in newLeft.view() + C;
        if z in C {
          assert z in B + C + {r.val};
          assert z in r.view();
          assert z in A + r.view() + {node.val};
          assert z in node.view();
        } else {
          assert z in newLeft.view() || z in C;
          assert z !in C;
          assert z in newLeft.view();
          assert z in (A + B) + {node.val};
          if z == node.val {
            assert z in {node.val};
            assert z in A + r.view() + {node.val};
            assert z in node.view();
          } else {
            assert z in A + B || z == node.val;
            assert z != node.val;
            assert z in A + B;
            if z in A {
              assert z in A + r.view() + {node.val};
              assert z in node.view();
            } else {
              assert z in A || z in B;
              assert z !in A;
              assert z in B;
              assert z in B + C + {r.val};
              assert z in r.view();
              assert z in A + r.view() + {node.val};
              assert z in node.view();
            }
          }
        }
      }
    }

    if z in node.view() {
      assert z in (A + r.view()) + {node.val};
      if z == node.val {
        assert z in {node.val};
        assert z in A + B + {node.val};
        assert z in newLeft.view();
        assert z in newLeft.view() + C + {r.val};
        assert z in res.view();
      } else {
        assert z in A + r.view() || z == node.val;
        assert z != node.val;
        assert z in A + r.view();
        if z in A {
          assert z in A + B + {node.val};
          assert z in newLeft.view();
          assert z in newLeft.view() + C + {r.val};
          assert z in res.view();
        } else {
          assert z in A || z in r.view();
          assert z !in A;
          assert z in r.view();
          assert z in (B + C) + {r.val};
          if z == r.val {
            assert z in {r.val};
            assert z in newLeft.view() + C + {r.val};
            assert z in res.view();
          } else {
            assert z in B + C || z == r.val;
            assert z != r.val;
            assert z in B + C;
            if z in C {
              assert z in newLeft.view() + C + {r.val};
              assert z in res.view();
            } else {
              assert z in B || z in C;
              assert z !in C;
              assert z in B;
              assert z in A + B + {node.val};
              assert z in newLeft.view();
              assert z in newLeft.view() + C + {r.val};
              assert z in res.view();
            }
          }
        }
      }
    }
  }
  assert res.view() == node.view();
}

lemma {:vcs_split_on_every_assert} IsBstIff(n: Node)
  ensures n.is_bst() == (LeftOK(n) && RightOK(n))
{
  var mL := match n.left {
    case Some(l) => (forall x :: x in l.view() ==> x < n.val) && l.is_bst()
    case None => true
  };
  var mR := match n.right {
    case Some(r) => (forall x :: x in r.view() ==> x > n.val) && r.is_bst()
    case None => true
  };

  assert n.is_bst() == (
    (match n.left {
      case Some(l) => (forall x :: x in l.view() ==> x < n.val) && l.is_bst()
      case None => true
    }) && (match n.right {
      case Some(r) => (forall x :: x in r.view() ==> x > n.val) && r.is_bst()
      case None => true
    })
  );
  assert mL == (match n.left {
    case Some(l) => (forall x :: x in l.view() ==> x < n.val) && l.is_bst()
    case None => true
  });
  assert mR == (match n.right {
    case Some(r) => (forall x :: x in r.view() ==> x > n.val) && r.is_bst()
    case None => true
  });
  assert n.is_bst() == (mL && mR);

  if n.left.Some? {
    var l := n.left.value;
    assert n.left == Some(l);
    match n.left {
      case Some(ll) =>
        assert ll == l;
        assert mL == ((forall x :: x in ll.view() ==> x < n.val) && ll.is_bst());
        assert mL == ((forall x :: x in l.view() ==> x < n.val) && l.is_bst());
      case None =>
        assert n.left == Some(l);
        assert false;
    }
    assert mL == ((forall x :: x in l.view() ==> x < n.val) && l.is_bst());
    assert n.left.Some?;
    assert n.left.value == l;
    assert LeftOK(n) == ((forall x :: x in n.left.value.view() ==> x < n.val) && n.left.value.is_bst());
    assert LeftOK(n) == ((forall x :: x in l.view() ==> x < n.val) && l.is_bst());
    assert mL == LeftOK(n);
  } else {
    assert n.left == None;
    match n.left {
      case Some(ll) =>
        assert n.left == None;
        assert false;
      case None =>
        assert mL == true;
    }
    assert mL == true;
    assert !n.left.Some?;
    assert LeftOK(n) == true;
    assert mL == LeftOK(n);
  }

  if n.right.Some? {
    var rv := n.right.value;
    assert n.right == Some(rv);
    match n.right {
      case Some(rr) =>
        assert rr == rv;
        assert mR == ((forall x :: x in rr.view() ==> x > n.val) && rr.is_bst());
        assert mR == ((forall x :: x in rv.view() ==> x > n.val) && rv.is_bst());
      case None =>
        assert n.right == Some(rv);
        assert false;
    }
    assert mR == ((forall x :: x in rv.view() ==> x > n.val) && rv.is_bst());
    assert n.right.Some?;
    assert n.right.value == rv;
    assert RightOK(n) == ((forall x :: x in n.right.value.view() ==> x > n.val) && n.right.value.is_bst());
    assert RightOK(n) == ((forall x :: x in rv.view() ==> x > n.val) && rv.is_bst());
    assert mR == RightOK(n);
  } else {
    assert n.right == None;
    match n.right {
      case Some(rr) =>
        assert n.right == None;
        assert false;
      case None =>
        assert mR == true;
    }
    assert mR == true;
    assert !n.right.Some?;
    assert RightOK(n) == true;
    assert mR == RightOK(n);
  }

  assert mL == LeftOK(n);
  assert mR == RightOK(n);
  assert n.is_bst() == (LeftOK(n) && RightOK(n));
}

lemma BstFromOK(n: Node)
  requires LeftOK(n)
  requires RightOK(n)
  ensures n.is_bst()
{
  IsBstIff(n);
}

lemma ChildLeftProps(n: Node, l: Node)
  requires n.is_bst()
  requires n.left == Some(l)
  ensures l.is_bst()
  ensures forall x :: x in l.view() ==> x < n.val
{
  IsBstIff(n);
  assert LeftOK(n) && RightOK(n);
  assert LeftOK(n);
  assert n.left == Some(l);
  assert n.left.Some?;
  assert n.left.value == l;
  assert LeftOK(n) == ((forall x :: x in n.left.value.view() ==> x < n.val) && n.left.value.is_bst());
  assert n.left.value.view() == l.view();
  assert n.left.value.is_bst() == l.is_bst();
  assert (forall x :: x in l.view() ==> x < n.val) && l.is_bst();
}

lemma ChildRightProps(n: Node, r: Node)
  requires n.is_bst()
  requires n.right == Some(r)
  ensures r.is_bst()
  ensures forall x :: x in r.view() ==> x > n.val
{
  IsBstIff(n);
