  assert n.right == Some(r);
  assert n.right.Some?;
  assert n.right.value == r;
  assert RightOK(n) == ((forall x :: x in n.right.value.view() ==> x > n.val) && n.right.value.is_bst());
  assert n.right.value.view() == r.view();
  assert n.right.value.is_bst() == r.is_bst();
  assert (forall x :: x in r.view() ==> x > n.val) && r.is_bst();
}

