    assert lhR != -1 && rhR != -1 && lhR == rhR;
    assert innerR == lhR;
    assert lhN == lhR;
    assert lhN == rhR;
    assert bhNew == lhN;
    assert bhNew == rhR;
    assert bhNew != -1 && rhR != -1 && bhNew == rhR;
    assert bhRes == (if !nodeRed then bhNew + 1 else bhNew);
    assert bhN == (if !nodeRed then lhN + 1 else lhN);
    assert bhNew == lhN;
    assert bhRes == bhN;
  } else {
    assert !(lhN != -1 && innerR != -1 && lhN == innerR);
    assert bhN == -1;
    if bhNew != -1 && rhR != -1 && bhNew == rhR {
      if !(lhN != -1 && lhR != -1 && lhN == lhR) {
        assert bhNew == -1;
        assert false;
      }
      assert lhN != -1 && lhR != -1 && lhN == lhR;
      assert bhNew == lhN;
      assert lhR == rhR;
      assert rhR != -1;
      assert lhR != -1 && rhR != -1 && lhR == rhR;
      assert innerR == lhR;
      assert lhN == innerR;
      assert innerR != -1;
      assert lhN != -1 && innerR != -1 && lhN == innerR;
      assert false;
    }
    assert !(bhNew != -1 && rhR != -1 && bhNew == rhR);
    assert bhRes == -1;
    assert bhRes == bhN;
