lemma VLSame(a: Node, b: Node)
  requires a.left == b.left
  ensures VL(a) == VL(b)
{
  if a.left.Some? {
    var c := a.left.value;
    assert a.left == Some(c);
    assert b.left == Some(c);
    VLSome(a, c);
    VLSome(b, c);
  } else {
    assert a.left == None;
    assert b.left == None;
    VLNone(a);
    VLNone(b);
  }
}

