lemma {:vcs_split_on_every_assert} ProveView(node: Node, r: Node, newLeft: Node, res: Node)
  requires node.right == Some(r)
  requires newLeft == Node(node.val, true, node.left, r.left)
  requires res == Node(r.val, node.is_red, Some(newLeft), r.right)
  ensures res.view() == node.view()
{
  VMatches(node);
  VMatches(r);
  VMatches(newLeft);
  VMatches(res);

  assert newLeft.left == node.left;
  assert newLeft.right == r.left;
  assert newLeft.val == node.val;
  assert res.left == Some(newLeft);
  assert res.right == r.right;
  assert res.val == r.val;

  VLSame(newLeft, node);
  VREqVL(newLeft, r);
  VRSome(node, r);
  VRSame(res, r);
  VLSome(res, newLeft);

  var A := VL(node);
  var B := VL(r);
  var C := VR(r);

  assert VL(newLeft) == A;
  assert VR(newLeft) == B;
  assert VR(node) == r.view();
  assert VR(res) == C;
  assert VL(res) == newLeft.view();

  assert newLeft.view() == A + B + {node.val};
  assert r.view() == B + C + {r.val};
  assert node.view() == A + r.view() + {node.val};
  assert res.view() == VL(res) + VR(res) + {res.val};
  assert res.view() == newLeft.view() + C + {r.val};

  forall z {:trigger z in res.view()} {:trigger z in node.view()}
    ensures z in res.view() <==> z in node.view()
  {
    assert res.view() == newLeft.view() + C + {r.val};
    assert newLeft.view() == A + B + {node.val};
    assert r.view() == B + C + {r.val};
    assert node.view() == A + r.view() + {node.val};

    if z in res.view() {
      assert z in (newLeft.view() + C) + {r.val};
      if z == r.val {
        assert z in {r.val};
        assert z in B + C + {r.val};
        assert z in r.view();
        assert z in A + r.view() + {node.val};
        assert z in node.view();
      } else {
        assert z in newLeft.view() + C || z == r.val;
        assert z != r.val;
        assert z in newLeft.view() + C;
        if z in C {
          assert z in B + C + {r.val};
          assert z in r.view();
          assert z in A + r.view() + {node.val};
          assert z in node.view();
        } else {
          assert z in newLeft.view() || z in C;
          assert z !in C;
          assert z in newLeft.view();
          assert z in (A + B) + {node.val};
          if z == node.val {
            assert z in {node.val};
            assert z in A + r.view() + {node.val};
            assert z in node.view();
          } else {
            assert z in A + B || z == node.val;
            assert z != node.val;
            assert z in A + B;
            if z in A {
              assert z in A + r.view() + {node.val};
              assert z in node.view();
            } else {
              assert z in A || z in B;
              assert z !in A;
              assert z in B;
              assert z in B + C + {r.val};
              assert z in r.view();
              assert z in A + r.view() + {node.val};
              assert z in node.view();
            }
          }
        }
      }
    }

    if z in node.view() {
      assert z in (A + r.view()) + {node.val};
      if z == node.val {
        assert z in {node.val};
        assert z in A + B + {node.val};
        assert z in newLeft.view();
        assert z in newLeft.view() + C + {r.val};
        assert z in res.view();
      } else {
        assert z in A + r.view() || z == node.val;
        assert z != node.val;
        assert z in A + r.view();
        if z in A {
          assert z in A + B + {node.val};
          assert z in newLeft.view();
          assert z in newLeft.view() + C + {r.val};
          assert z in res.view();
        } else {
          assert z in A || z in r.view();
          assert z !in A;
          assert z in r.view();
          assert z in (B + C) + {r.val};
          if z == r.val {
            assert z in {r.val};
            assert z in newLeft.view() + C + {r.val};
            assert z in res.view();
          } else {
            assert z in B + C || z == r.val;
            assert z != r.val;
            assert z in B + C;
            if z in C {
              assert z in newLeft.view() + C + {r.val};
              assert z in res.view();
            } else {
              assert z in B || z in C;
              assert z !in C;
              assert z in B;
              assert z in A + B + {node.val};
              assert z in newLeft.view();
              assert z in newLeft.view() + C + {r.val};
              assert z in res.view();
            }
          }
        }
      }
    }
  }
  assert res.view() == node.view();
}

