lemma {:induction false} BstFromOK(n: Node)
  requires LeftOK(n)
  requires RightOK(n)
  ensures n.is_bst()
{
  if n.left.Some? {
    var l := n.left.value;
    assert n.left == Some(l);
    FromLeftOKChild(n, l);
    forall x | x in l.view()
      ensures x < n.val
    {
      FromLeftOKElem(n, l, x);
    }
    if n.right.Some? {
      var rv := n.right.value;
      assert n.right == Some(rv);
      FromRightOKChild(n, rv);
      forall x | x in rv.view()
        ensures x > n.val
      {
        FromRightOKElem(n, rv, x);
      }
      IntroBstLR(n, l, rv);
    } else {
      assert n.right == None;
      IntroBstL(n, l);
    }
  } else {
    assert n.left == None;
    if n.right.Some? {
      var rv := n.right.value;
      assert n.right == Some(rv);
      FromRightOKChild(n, rv);
      forall x | x in rv.view()
        ensures x > n.val
      {
        FromRightOKElem(n, rv, x);
      }
      IntroBstR(n, rv);
    } else {
      assert n.right == None;
      IntroBstNone(n);
    }
  }
}

