  assert n.right.Some?;
  assert n.right.value == c;
  assert (forall x :: x in c.view() ==> x > n.val) && c.is_bst();
  assert RightOK(n) == ((forall x :: x in n.right.value.view() ==> x > n.val) && n.right.value.is_bst());
  assert RightOK(n) == ((forall x :: x in c.view() ==> x > n.val) && c.is_bst());
  assert RightOK(n);
}

lemma LeftOKNone(n: Node)
  requires n.left == None
  ensures LeftOK(n)
{
  assert n.left == None;
  assert !n.left.Some?;
  assert LeftOK(n) == true;
}

lemma RightOKNone(n: Node)
  requires n.right == None
  ensures RightOK(n)
{
  assert n.right == None;
  assert !n.right.Some?;
  assert RightOK(n) == true;
}

lemma {:vcs_split_on_every_assert} NewLeftBelow(node: Node, r: Node, newLeft: Node)
  requires node.is_bst()
  requires node.right == Some(r)
  requires newLeft == Node(node.val, true, node.left, r.left)
  ensures forall x :: x in newLeft.view() ==> x < r.val
{
  ChildRightProps(node, r);
  ValInOwnView(r);
  assert r.val in r.view();
  assert r.val > node.val;
  assert node.val < r.val;

  assert newLeft.val == node.val;
  assert newLeft.left == node.left;
  assert newLeft.right == r.left;
  VMatches(newLeft);

  forall x | x in newLeft.view()
    ensures x < r.val
  {
    assert newLeft.view() == VL(newLeft) + VR(newLeft) + {newLeft.val};
    assert x in (VL(newLeft) + VR(newLeft)) + {newLeft.val};
    if x == newLeft.val {
      assert x == node.val;
      assert node.val < r.val;
      assert x < r.val;
    } else {
      assert x in VL(newLeft) + VR(newLeft) || x == newLeft.val;
      assert x != newLeft.val;
      assert x in VL(newLeft) + VR(newLeft);
      if x in VL(newLeft) {
        if newLeft.left.None? {
          assert newLeft.left == None;
          VLNone(newLeft);
          assert VL(newLeft) == {};
          assert x in VL(newLeft);
          assert false;
        }
        var l := newLeft.left.value;
        assert newLeft.left == Some(l);
        assert node.left == Some(l);
        VLSome(newLeft, l);
        assert x in l.view();
        ChildLeftProps(node, l);
        assert x < node.val;
        assert node.val < r.val;
        assert x < r.val;
      } else {
        assert x in VL(newLeft) || x in VR(newLeft);
        assert x !in VL(newLeft);
        assert x in VR(newLeft);
        if newLeft.right.None? {
          assert newLeft.right == None;
          VRNone(newLeft);
          assert VR(newLeft) == {};
          assert x in VR(newLeft);
          assert false;
        }
        var rl := newLeft.right.value;
        assert newLeft.right == Some(rl);
        assert r.left == Some(rl);
        VRSome(newLeft, rl);
        assert x in rl.view();
        ChildLeftProps(r, rl);
        assert x < r.val;
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} ProveBst(node: Node, r: Node, newLeft: Node, res: Node)
  requires node.is_bst()
  requires node.right == Some(r)
  requires newLeft == Node(node.val, true, node.left, r.left)
  requires res == Node(r.val, node.is_red, Some(newLeft), r.right)
  ensures res.is_bst()
{
  assert newLeft.val == node.val;
  assert newLeft.left == node.left;
  assert newLeft.right == r.left;
  assert res.val == r.val;
  assert res.left == Some(newLeft);
  assert res.right == r.right;

  ChildRightProps(node, r);
  assert r.is_bst();

  if newLeft.left.Some? {
    var l := newLeft.left.value;
    assert newLeft.left == Some(l);
    assert node.left == Some(l);
    ChildLeftProps(node, l);
    forall x | x in l.view()
      ensures x < newLeft.val
    {
      assert x < node.val;
      assert node.val == newLeft.val;
    }
    LeftOKFromChild(newLeft, l);
  } else {
    assert newLeft.left == None;
    LeftOKNone(newLeft);
  }

  if newLeft.right.Some? {
    var rl := newLeft.right.value;
    assert newLeft.right == Some(rl);
    assert r.left == Some(rl);
    ChildLeftProps(r, rl);
    forall x | x in rl.view()
      ensures x > newLeft.val
    {
      LeftViewSubset(r, rl);
      assert rl.view() <= r.view();
      assert x in rl.view();
      assert x in r.view();
      assert x > node.val;
      assert node.val == newLeft.val;
    }
    RightOKFromChild(newLeft, rl);
  } else {
    assert newLeft.right == None;
    RightOKNone(newLeft);
  }

  assert LeftOK(newLeft);
  assert RightOK(newLeft);
  BstFromOK(newLeft);
  assert newLeft.is_bst();

  NewLeftBelow(node, r, newLeft);
  forall x | x in newLeft.view()
    ensures x < res.val
  {
    assert x < r.val;
    assert r.val == res.val;
  }
  LeftOKFromChild(res, newLeft);
  assert LeftOK(res);

  if res.right.Some? {
    var rr := res.right.value;
    assert res.right == Some(rr);
    assert r.right == Some(rr);
    ChildRightProps(r, rr);
    forall x | x in rr.view()
      ensures x > res.val
    {
      assert x > r.val;
      assert r.val == res.val;
    }
    RightOKFromChild(res, rr);
  } else {
    assert res.right == None;
    RightOKNone(res);
  }

  assert RightOK(res);
  BstFromOK(res);
}

method fixup_rotate_left(node: Node) returns (res: Node)
    requires node.is_bst()
    requires node.right.Some? && node.right.value.is_red
    // Explicitly ensure the result structure allows property access
    ensures res.left.Some?
    ensures
        // Structural
        res.is_bst()
    ensures
        res.view() == node.view()
    ensures
        // Colors & Balance
        res.black_height() == node.black_height() // The Critical Proof
    ensures
        res.is_red == node.is_red
    ensures
        res.left.value.is_red
{
  var r := node.right.value;
  assert node.right == Some(r);
  assert r.is_red;

  var newLeft := Node(node.val, true, node.left, r.left);
  res := Node(r.val, node.is_red, Some(newLeft), r.right);

  assert res.left == Some(newLeft);
  assert newLeft.is_red;
  assert res.left.value == newLeft;
  assert res.is_red == node.is_red;

  ProveView(node, r, newLeft, res);
  ProveBst(node, r, newLeft, res);
  ProveBH(node, r, newLeft, res);
}
