method solve_longest_common_subsequence(s: seq<char>, t: seq<char>) returns (len: int)
    requires |s| <= 3000
    requires |t| <= 3000
    ensures len == lcs_spec(s, t)
    // Implicit constraint from usize in Verus
    ensures len >= 0
{
    var m := |t|;
    var prev := new int[m + 1];
    var j := 0;
    while j <= m
        invariant 0 <= j <= m + 1
        invariant forall k :: 0 <= k < j ==> prev[k] == lcs_spec(s[..0], t[..k]) && prev[k] >= 0
    {
        prev[j] := 0;
        j := j + 1;
    }
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant prev.Length == m + 1
        invariant forall k :: 0 <= k <= m ==> prev[k] == lcs_spec(s[..i], t[..k]) && prev[k] >= 0
    {
        var cur := new int[m + 1];
        cur[0] := 0;
        assert lcs_spec(s[..i+1], t[..0]) == 0;
        j := 1;
        while j <= m
            invariant 1 <= j <= m + 1
            invariant cur != prev
            invariant forall k :: 0 <= k < j ==> cur[k] == lcs_spec(s[..i+1], t[..k]) && cur[k] >= 0
            invariant forall k :: 0 <= k <= m ==> prev[k] == lcs_spec(s[..i], t[..k]) && prev[k] >= 0
        {
            assert s[..i+1][..i] == s[..i];
            assert t[..j][..j-1] == t[..j-1];
            assert s[..i+1][i] == s[i];
            assert t[..j][j-1] == t[j-1];
            if s[i] == t[j-1] {
                assert lcs_spec(s[..i+1], t[..j]) == 1 + lcs_spec(s[..i], t[..j-1]);
                cur[j] := prev[j-1] + 1;
            } else {
                assert lcs_spec(s[..i+1], t[..j]) == max(lcs_spec(s[..i], t[..j]), lcs_spec(s[..i+1], t[..j-1]));
                if prev[j] > cur[j-1] {
                    cur[j] := prev[j];
                } else {
                    cur[j] := cur[j-1];
                }
            }
            j := j + 1;
        }
        prev := cur;
        i := i + 1;
    }
    assert s[..|s|] == s;
    assert t[..m] == t;
    len := prev[m];
}

