code:
method solve_longest_common_subsequence(s: seq<char>, t: seq<char>) returns (len: int)
    requires |s| <= 3000
    requires |t| <= 3000
    ensures len == lcs_spec(s, t)
    // Implicit constraint from usize in Verus
    ensures len >= 0
    decreases |s| + |t|
{
    if |s| == 0 || |t| == 0 {
        len := 0;
    } else if s[|s|-1] == t[|t|-1] {
        var prefixLen := solve_longest_common_subsequence(
            s[..|s|-1],
            t[..|t|-1]
        );
        len := 1 + prefixLen;
    } else {
        var withoutSLast := solve_longest_common_subsequence(
            s[..|s|-1],
            t
        );
        var withoutTLast := solve_longest_common_subsequence(
            s,
            t[..|t|-1]
        );
        len := if withoutSLast > withoutTLast
               then withoutSLast
               else withoutTLast;
    }
}

