// Gaussian elimination over GF(2). Solution-set equivalence is preserved by
// row swaps and row additions; a constructed assignment is checked against
// the reduced system, and a 0 = 1 row rules out every candidate.

ghost predicate IsBit(v: int) {
  v == 0 || v == 1
}

ghost predicate AugOK(aug: seq<seq<int>>, rows: int, nCols: int) {
  |aug| == rows &&
  rows >= 1 &&
  nCols >= 1 &&
  (forall i :: 0 <= i < rows ==>
    |aug[i]| == nCols + 1 &&
    (forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])))
}

ghost predicate PivotOK(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  |pivotCol| == rows &&
  |rowOfCol| == nCols &&
  0 <= numPivots <= rows &&
  0 <= col <= nCols &&
  (forall r :: numPivots <= r < rows && r < |pivotCol| ==> pivotCol[r] == -1) &&
  (forall r :: 0 <= r < numPivots && r < |pivotCol| ==>
    0 <= pivotCol[r] < col &&
    pivotCol[r] < |rowOfCol| &&
    rowOfCol[pivotCol[r]] == r) &&
  (forall j :: 0 <= j < nCols && j < |rowOfCol| ==>
    rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots &&
     rowOfCol[j] < |pivotCol| &&
     pivotCol[rowOfCol[j]] == j)) &&
  (forall j :: col <= j < nCols && j < |rowOfCol| ==> rowOfCol[j] == -1)
}

ghost predicate UnitPivots(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  forall r :: 0 <= r < numPivots && r < |aug| && r < |pivotCol| ==>
    0 <= pivotCol[r] < col &&
    pivotCol[r] < nCols &&
    pivotCol[r] < |aug[r]| &&
    aug[r][pivotCol[r]] == 1 &&
    (forall i :: 0 <= i < rows && i < |aug| && i != r && pivotCol[r] < |aug[i]| ==>
      aug[i][pivotCol[r]] == 0)
}

ghost predicate LowerZeros(
  aug: seq<seq<int>>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  forall r, j ::
    numPivots <= r < rows && r < |aug| && 0 <= j < col && j < |aug[r]| ==>
      aug[r][j] == 0
}

ghost predicate RREFState(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  AugOK(aug, rows, nCols) &&
  PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols) &&
  UnitPivots(aug, pivotCol, numPivots, col, rows, nCols) &&
  LowerZeros(aug, numPivots, col, rows, nCols)
}

ghost predicate SolvesAug(aug: seq<seq<int>>, x: seq<int>, nCols: int) {
  |x| == nCols &&
  is_binary_vector(x) &&
  (forall i :: 0 <= i < |aug| ==>
    |aug[i]| == nCols + 1 &&
    spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols])
}

ghost predicate {:opaque} SameSol(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  nCols: int)
{
  forall x {:trigger is_solution(matrix, b, x)} {:trigger SolvesAug(aug, x, nCols)} ::
    |x| == nCols && is_binary_vector(x) ==>
      (is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols))
}

function BuildAug(matrix: seq<seq<int>>, b: seq<int>): seq<seq<int>>
  requires |matrix| == |b|
{
  seq(|matrix|, i requires 0 <= i < |matrix| => matrix[i] + [b[i]])
}

function XorRow(a: seq<int>, b: seq<int>): seq<int>
  requires |a| == |b|
{
  seq(|a|, i requires 0 <= i < |a| => (a[i] + b[i]) % 2)
}

function AddRowTo(m: seq<seq<int>>, dst: int, src: int): seq<seq<int>>
  requires 0 <= dst < |m| && 0 <= src < |m|
  requires |m[dst]| == |m[src]|
{
  m[dst := XorRow(m[dst], m[src])]
}

function SwapRows(m: seq<seq<int>>, r1: int, r2: int): seq<seq<int>>
  requires 0 <= r1 < |m| && 0 <= r2 < |m|
{
  if r1 == r2 then m else (m[r1 := m[r2]])[r2 := m[r1]]
}

function XFrom(aug: seq<seq<int>>, rowOfCol: seq<int>, nCols: int): seq<int>
  requires |rowOfCol| == nCols
  requires nCols >= 1
  requires forall j :: 0 <= j < nCols ==>
    rowOfCol[j] == -1 || (0 <= rowOfCol[j] < |aug| && nCols < |aug[rowOfCol[j]]|)
{
  seq(nCols, j requires 0 <= j < nCols =>
    if rowOfCol[j] == -1 then 0 else aug[rowOfCol[j]][nCols])
}

lemma TwoTimesNotOne(k: int)
  ensures 2 * k != 1
{
  if k <= 0 {
    assert 2 * k <= 0;
  } else {
    assert k >= 1;
    assert 2 * k >= 2;
  }
}

lemma TwoTimesNotNegOne(k: int)
  ensures 2 * k != -1
{
  if k >= 0 {
    assert 2 * k >= 0;
  } else {
    assert k <= -1;
    assert 2 * k <= -2;
  }
}

lemma DivModUnique2(n: int, q: int, r: int)
  requires n == 2 * q + r
  requires 0 <= r < 2
  ensures n % 2 == r
  ensures n / 2 == q
{
  var q0 := n / 2;
  var r0 := n % 2;
  assert n == 2 * q0 + r0;
  assert 0 <= r0 < 2;
  if r != r0 {
    var diffR := r0 - r;
    assert -1 <= diffR <= 1;
    assert diffR != 0;
    assert diffR == -1 || diffR == 1;
    if diffR == 1 {
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == -1;
      assert 2 * (q - q0) == -1;
      TwoTimesNotNegOne(q - q0);
      assert false;
    } else {
      assert diffR == -1;
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == 1;
      assert 2 * (q - q0) == 1;
      TwoTimesNotOne(q - q0);
      assert false;
    }
  }
  assert r == r0;
  assert 2 * q + r == 2 * q0 + r0;
  assert 2 * (q - q0) == 0;
  if q != q0 {
    var m := q - q0;
    assert 2 * m == 0;
    if m > 0 {
      assert m >= 1;
      assert 2 * m >= 2;
      assert false;
    } else {
      assert m <= -1;
      assert 2 * m <= -2;
      assert false;
    }
  }
}

lemma XorPairToSum(a: int, b: int, c: int, d: int)
  requires IsBit(a) && IsBit(b) && IsBit(c) && IsBit(d)
  ensures ((a + b) % 2 + (c + d) % 2) % 2 == (a + b + c + d) % 2
{
  var ab := (a + b) % 2;
  var cd := (c + d) % 2;
  var s := a + b + c + d;
  assert a + b == 2 * ((a + b) / 2) + ab;
  assert c + d == 2 * ((c + d) / 2) + cd;
  assert 0 <= ab < 2;
  assert 0 <= cd < 2;
  assert ab <= 1 && cd <= 1;
  var q1 := (a + b) / 2 + (c + d) / 2;
  var r1 := ab + cd;
  assert s == 2 * q1 + r1;
  assert 0 <= r1 <= 2;
  if r1 < 2 {
    DivModUnique2(s, q1, r1);
    assert s % 2 == r1;
    if r1 == 0 {
      assert (0) % 2 == 0;
    } else {
      assert r1 == 1;
      assert (1) % 2 == 1;
    }
    assert (ab + cd) % 2 == s % 2;
  } else {
    assert r1 == 2;
    assert s == 2 * (q1 + 1) + 0;
    DivModUnique2(s, q1 + 1, 0);
    assert s % 2 == 0;
    assert (2) % 2 == 0;
    assert (ab + cd) % 2 == 0;
  }
}

lemma XorFourRearrange(a: int, b: int, c: int, d: int)
  requires IsBit(a) && IsBit(b) && IsBit(c) && IsBit(d)
  ensures add_gf2(add_gf2(a, b), add_gf2(c, d)) == add_gf2(add_gf2(a, c), add_gf2(b, d))
{
  XorPairToSum(a, b, c, d);
  XorPairToSum(a, c, b, d);
  var left := ((a + b) % 2 + (c + d) % 2) % 2;
  var right := ((a + c) % 2 + (b + d) % 2) % 2;
  assert left == (a + b + c + d) % 2;
  assert right == (a + c + b + d) % 2;
  assert a + b + c + d == a + c + b + d;
  assert left == right;
  var ab := add_gf2(a, b);
  var cd := add_gf2(c, d);
  var ac := add_gf2(a, c);
  var bd := add_gf2(b, d);
  assert ab == (a + b) % 2;
  assert cd == (c + d) % 2;
  assert ac == (a + c) % 2;
  assert bd == (b + d) % 2;
  assert add_gf2(ab, cd) == (ab + cd) % 2;
  assert ab + cd == (a + b) % 2 + (c + d) % 2;
  assert add_gf2(ab, cd) == left;
  assert add_gf2(ac, bd) == (ac + bd) % 2;
  assert ac + bd == (a + c) % 2 + (b + d) % 2;
  assert add_gf2(ac, bd) == right;
  assert add_gf2(add_gf2(a, b), add_gf2(c, d)) == add_gf2(ab, cd);
  assert add_gf2(add_gf2(a, c), add_gf2(b, d)) == add_gf2(ac, bd);
}

lemma BitMod2(a: int)
  requires IsBit(a)
  ensures a % 2 == a
{
  if a == 0 {
    assert (0) % 2 == 0;
  } else {
    assert a == 1;
    assert (1) % 2 == 1;
  }
}

lemma AddIsBit(a: int, b: int)
  requires IsBit(a) && IsBit(b)
  ensures IsBit(add_gf2(a, b))
  ensures add_gf2(a, b) == (if a == b then 0 else 1)
{
  if a == 0 && b == 0 {
    assert (0 + 0) % 2 == 0;
    assert add_gf2(0, 0) == 0;
  } else if a == 0 && b == 1 {
    assert (0 + 1) % 2 == 1;
    assert add_gf2(0, 1) == 1;
  } else if a == 1 && b == 0 {
    assert (1 + 0) % 2 == 1;
    assert add_gf2(1, 0) == 1;
  } else {
    assert a == 1 && b == 1;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(1, 1) == 0;
  }
}

lemma AddZero(a: int)
  requires IsBit(a)
  ensures add_gf2(0, a) == a
  ensures add_gf2(a, 0) == a
{
  BitMod2(a);
  assert (0 + a) % 2 == a % 2;
  assert (a + 0) % 2 == a % 2;
  assert add_gf2(0, a) == (0 + a) % 2;
  assert add_gf2(a, 0) == (a + 0) % 2;
}

lemma MulIsBit(a: int, b: int)
  requires IsBit(a) && IsBit(b)
  ensures IsBit(mul_gf2(a, b))
  ensures mul_gf2(a, b) == a * b
{
  if a == 0 || b == 0 {
    assert a * b == 0;
    assert (0) % 2 == 0;
    assert mul_gf2(a, b) == (a * b) % 2;
  } else {
    assert a == 1 && b == 1;
    assert a * b == 1;
    assert (1) % 2 == 1;
    assert mul_gf2(a, b) == (a * b) % 2;
  }
}

lemma MulZero(a: int)
  ensures mul_gf2(0, a) == 0
  ensures mul_gf2(a, 0) == 0
{
  assert 0 * a == 0;
  assert a * 0 == 0;
  assert (0) % 2 == 0;
  assert mul_gf2(0, a) == (0 * a) % 2;
  assert mul_gf2(a, 0) == (a * 0) % 2;
}

lemma MulOne(a: int)
  requires IsBit(a)
  ensures mul_gf2(1, a) == a
  ensures mul_gf2(a, 1) == a
{
  BitMod2(a);
  assert 1 * a == a;
  assert a * 1 == a;
  assert (1 * a) % 2 == a % 2;
  assert (a * 1) % 2 == a % 2;
  assert mul_gf2(1, a) == (1 * a) % 2;
  assert mul_gf2(a, 1) == (a * 1) % 2;
}

lemma XorCancel(a: int, s: int)
  requires IsBit(a) && IsBit(s)
  ensures add_gf2(add_gf2(a, s), s) == a
{
  if a == 0 && s == 0 {
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
    assert add_gf2(0, 0) == 0;
    assert add_gf2(add_gf2(0, 0), 0) == add_gf2(0, 0);
  } else if a == 0 && s == 1 {
    assert add_gf2(0, 1) == (0 + 1) % 2;
    assert (0 + 1) % 2 == 1;
    assert add_gf2(1, 1) == (1 + 1) % 2;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(add_gf2(0, 1), 1) == add_gf2(1, 1);
    assert add_gf2(1, 1) == 0;
  } else if a == 1 && s == 0 {
    assert add_gf2(1, 0) == (1 + 0) % 2;
    assert (1 + 0) % 2 == 1;
    assert add_gf2(add_gf2(1, 0), 0) == add_gf2(1, 0);
    assert add_gf2(1, 0) == 1;
  } else {
    assert a == 1 && s == 1;
    assert add_gf2(1, 1) == (1 + 1) % 2;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(0, 1) == (0 + 1) % 2;
    assert (0 + 1) % 2 == 1;
    assert add_gf2(add_gf2(1, 1), 1) == add_gf2(0, 1);
    assert add_gf2(0, 1) == 1;
  }
}

lemma DistrBit(a: int, b: int, x: int)
  requires IsBit(a) && IsBit(b) && IsBit(x)
  ensures mul_gf2(add_gf2(a, b), x) == add_gf2(mul_gf2(a, x), mul_gf2(b, x))
{
  AddIsBit(a, b);
  var s := add_gf2(a, b);
  assert IsBit(s);
  if x == 0 {
    MulZero(s);
    MulZero(a);
    MulZero(b);
    assert mul_gf2(s, 0) == 0;
    assert mul_gf2(a, 0) == 0;
    assert mul_gf2(b, 0) == 0;
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
    assert add_gf2(mul_gf2(a, 0), mul_gf2(b, 0)) == 0;
  } else {
    assert x == 1;
    MulOne(s);
    MulOne(a);
    MulOne(b);
    assert mul_gf2(s, 1) == s;
    assert mul_gf2(a, 1) == a;
    assert mul_gf2(b, 1) == b;
    assert add_gf2(a, b) == s;
    assert add_gf2(mul_gf2(a, 1), mul_gf2(b, 1)) == add_gf2(a, b);
  }
}

lemma DotProductDependsOnPrefix(r1: seq<int>, r2: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires forall j :: 0 <= j <= k && j < |x| ==> j < |r1| && j < |r2| && r1[j] == r2[j]
  ensures spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r2, x, k)
{
  if k >= 0 {
    assert forall j :: 0 <= j <= k - 1 && j < |x| ==> j < |r1| && j < |r2| && r1[j] == r2[j];
    DotProductDependsOnPrefix(r1, r2, x, k - 1);
    if k < |x| {
      assert k < |r1| && k < |r2| && r1[k] == r2[k];
      assert spec_dot_product_gf2(r1, x, k) ==
        add_gf2(mul_gf2(r1[k], x[k]), spec_dot_product_gf2(r1, x, k - 1));
      assert spec_dot_product_gf2(r2, x, k) ==
        add_gf2(mul_gf2(r2[k], x[k]), spec_dot_product_gf2(r2, x, k - 1));
    } else {
      assert spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r1, x, k - 1);
      assert spec_dot_product_gf2(r2, x, k) == spec_dot_product_gf2(r2, x, k - 1);
    }
  }
}

lemma DotIsBit(row: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  ensures IsBit(spec_dot_product_gf2(row, x, k))
{
  if k < 0 {
    assert spec_dot_product_gf2(row, x, k) == 0;
  } else {
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    DotIsBit(row, x, k - 1);
    if k < |row| && k < |x| {
      assert IsBit(row[k]) && IsBit(x[k]);
      MulIsBit(row[k], x[k]);
      var prod := mul_gf2(row[k], x[k]);
      var rest := spec_dot_product_gf2(row, x, k - 1);
      assert IsBit(prod) && IsBit(rest);
      AddIsBit(prod, rest);
      assert spec_dot_product_gf2(row, x, k) == add_gf2(prod, rest);
      assert IsBit(add_gf2(prod, rest));
    } else {
      assert spec_dot_product_gf2(row, x, k) == spec_dot_product_gf2(row, x, k - 1);
    }
  }
}

lemma ZeroDot(row: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  ensures spec_dot_product_gf2(row, x, k) == 0
{
  if k < 0 {
    assert spec_dot_product_gf2(row, x, k) == 0;
  } else {
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0;
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    ZeroDot(row, x, k - 1);
    if k < |row| && k < |x| {
      assert row[k] == 0 || x[k] == 0;
      if row[k] == 0 {
        MulZero(x[k]);
        assert mul_gf2(row[k], x[k]) == mul_gf2(0, x[k]);
        assert mul_gf2(0, x[k]) == 0;
      } else {
        assert x[k] == 0;
        MulZero(row[k]);
        assert mul_gf2(row[k], x[k]) == mul_gf2(row[k], 0);
        assert mul_gf2(row[k], 0) == 0;
      }
      assert mul_gf2(row[k], x[k]) == 0;
      assert spec_dot_product_gf2(row, x, k - 1) == 0;
      assert add_gf2(0, 0) == (0 + 0) % 2;
      assert (0 + 0) % 2 == 0;
      assert spec_dot_product_gf2(row, x, k) ==
        add_gf2(mul_gf2(row[k], x[k]), spec_dot_product_gf2(row, x, k - 1));
      assert spec_dot_product_gf2(row, x, k) == add_gf2(0, 0);
    } else {
      assert spec_dot_product_gf2(row, x, k) == spec_dot_product_gf2(row, x, k - 1);
    }
  }
}

lemma DotProductSingle(row: seq<int>, x: seq<int>, k: int, p: int)
  decreases if k < 0 then 0 else k + 1
  requires 0 <= p <= k
  requires p < |row| && p < |x|
  requires k < |row| && k < |x|
  requires row[p] == 1
  requires IsBit(x[p])
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  requires forall j :: 0 <= j <= k && j != p && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0
  ensures spec_dot_product_gf2(row, x, k) == x[p]
{
  if k == p {
    if k == 0 {
      assert spec_dot_product_gf2(row, x, -1) == 0;
      assert row[0] == 1;
      MulOne(x[0]);
      assert mul_gf2(row[0], x[0]) == mul_gf2(1, x[0]);
      assert mul_gf2(1, x[0]) == x[0];
      AddZero(x[0]);
      assert spec_dot_product_gf2(row, x, 0) ==
        add_gf2(mul_gf2(row[0], x[0]), spec_dot_product_gf2(row, x, -1));
      assert spec_dot_product_gf2(row, x, 0) == add_gf2(x[0], 0);
      assert add_gf2(x[0], 0) == x[0];
    } else {
      assert (forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0) by {
        forall j | (0 <= j <= k - 1 && j < (|row|) && j < (|x|))
          ensures row[j] == 0 || x[j] == 0
        {
          assert j != p;
          assert row[j] == 0 || x[j] == 0;
        }
      }
      assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
      ZeroDot(row, x, k - 1);
      assert row[k] == 1;
      MulOne(x[k]);
      assert mul_gf2(row[k], x[k]) == x[k];
      assert spec_dot_product_gf2(row, x, k - 1) == 0;
      AddZero(x[k]);
      assert spec_dot_product_gf2(row, x, k) ==
        add_gf2(mul_gf2(row[k], x[k]), spec_dot_product_gf2(row, x, k - 1));
      assert spec_dot_product_gf2(row, x, k) == add_gf2(x[k], 0);
    }
  } else {
    assert k > p;
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    assert forall j :: 0 <= j <= k - 1 && j != p && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0;
    DotProductSingle(row, x, k - 1, p);
    assert row[k] == 0 || x[k] == 0;
    if row[k] == 0 {
      MulZero(x[k]);
      assert mul_gf2(row[k], x[k]) == 0;
    } else {
      assert x[k] == 0;
      MulZero(row[k]);
      assert mul_gf2(row[k], x[k]) == 0;
    }
    var rest := spec_dot_product_gf2(row, x, k - 1);
    assert rest == x[p];
    assert IsBit(rest);
    AddZero(rest);
    assert spec_dot_product_gf2(row, x, k) ==
      add_gf2(mul_gf2(row[k], x[k]), rest);
    assert mul_gf2(row[k], x[k]) == 0;
    assert spec_dot_product_gf2(row, x, k) == add_gf2(0, rest);
    assert add_gf2(0, rest) == rest;
  }
}

lemma DotLinear(r1: seq<int>, r2: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires |r1| == |r2|
  requires forall j :: 0 <= j <= k && j < |r1| && j < |x| ==> IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j])
  ensures spec_dot_product_gf2(XorRow(r1, r2), x, k) ==
    add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k))
{
  if k < 0 {
    assert spec_dot_product_gf2(XorRow(r1, r2), x, k) == 0;
    assert spec_dot_product_gf2(r1, x, k) == 0;
    assert spec_dot_product_gf2(r2, x, k) == 0;
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
  } else {
    assert forall j :: 0 <= j <= k - 1 && j < |r1| && j < |x| ==>
      IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j]);
    DotLinear(r1, r2, x, k - 1);
    if k < |r1| && k < |x| {
      assert IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]);
      var xr := XorRow(r1, r2);
      assert |xr| == |r1|;
      assert xr[k] == (r1[k] + r2[k]) % 2;
      assert add_gf2(r1[k], r2[k]) == (r1[k] + r2[k]) % 2;
      AddIsBit(r1[k], r2[k]);
      var rx := xr[k];
      assert rx == add_gf2(r1[k], r2[k]);
      assert IsBit(rx);
      var p1 := mul_gf2(r1[k], x[k]);
      var p2 := mul_gf2(r2[k], x[k]);
      var px := mul_gf2(rx, x[k]);
      MulIsBit(r1[k], x[k]);
      MulIsBit(r2[k], x[k]);
      MulIsBit(rx, x[k]);
      assert IsBit(p1) && IsBit(p2) && IsBit(px);
      assert forall j :: 0 <= j <= k - 1 && j < |r1| && j < |x| ==> IsBit(r1[j]) && IsBit(x[j]);
      assert forall j :: 0 <= j <= k - 1 && j < |r2| && j < |x| ==> IsBit(r2[j]) && IsBit(x[j]);
      DotIsBit(r1, x, k - 1);
      DotIsBit(r2, x, k - 1);
      var s1 := spec_dot_product_gf2(r1, x, k - 1);
      var s2 := spec_dot_product_gf2(r2, x, k - 1);
      var sx := spec_dot_product_gf2(xr, x, k - 1);
      assert IsBit(s1) && IsBit(s2);
      assert sx == add_gf2(s1, s2);
      AddIsBit(s1, s2);
      assert IsBit(sx);
      DistrBit(r1[k], r2[k], x[k]);
      assert px == mul_gf2(add_gf2(r1[k], r2[k]), x[k]);
      assert px == add_gf2(p1, p2);
      assert spec_dot_product_gf2(xr, x, k) == add_gf2(px, sx);
      assert spec_dot_product_gf2(r1, x, k) == add_gf2(p1, s1);
      assert spec_dot_product_gf2(r2, x, k) == add_gf2(p2, s2);
      AddIsBit(p1, s1);
      AddIsBit(p2, s2);
      AddIsBit(p1, p2);
      XorFourRearrange(p1, p2, s1, s2);
      assert add_gf2(px, sx) == add_gf2(add_gf2(p1, p2), add_gf2(s1, s2));
      assert add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k)) ==
        add_gf2(add_gf2(p1, s1), add_gf2(p2, s2));
      assert add_gf2(add_gf2(p1, p2), add_gf2(s1, s2)) ==
        add_gf2(add_gf2(p1, s1), add_gf2(p2, s2));
    } else {
      assert spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r1, x, k - 1);
      assert spec_dot_product_gf2(r2, x, k) == spec_dot_product_gf2(r2, x, k - 1);
      assert !(k < |XorRow(r1, r2)| && k < |x|);
      assert spec_dot_product_gf2(XorRow(r1, r2), x, k) ==
        spec_dot_product_gf2(XorRow(r1, r2), x, k - 1);
    }
  }
}

lemma XorEntry(a: seq<int>, b: seq<int>, j: int)
  requires |a| == |b|
  requires 0 <= j < |a|
  ensures XorRow(a, b)[j] == (a[j] + b[j]) % 2
{
