lemma AddRowAt(m: seq<seq<int>>, dst: int, src: int, i: int)
  requires 0 <= dst < |m| && 0 <= src < |m|
  requires |m[dst]| == |m[src]|
  requires 0 <= i < |m|
  ensures |AddRowTo(m, dst, src)| == |m|
  ensures i == dst ==> AddRowTo(m, dst, src)[i] == XorRow(m[dst], m[src])
  ensures i != dst ==> AddRowTo(m, dst, src)[i] == m[i]
{
  var n := AddRowTo(m, dst, src);
  assert n == m[dst := XorRow(m[dst], m[src])];
  assert |n| == |m|;
  if i == dst {
    assert n[i] == XorRow(m[dst], m[src]);
  } else {
    assert n[i] == m[i];
  }
}

lemma {:vcs_split_on_every_assert} AddRowPreservesSol(
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  x: seq<int>,
  nCols: int)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  requires forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1
  requires forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(AddRowTo(aug, dst, src), x, nCols)
{
  var newA := AddRowTo(aug, dst, src);
  var r1 := aug[dst];
  var r2 := aug[src];
  var xr := XorRow(r1, r2);
  assert |r1| == nCols + 1 && |r2| == nCols + 1;
  assert newA[dst] == xr;
  forall i | (0 <= i < (|aug|))
    ensures |newA[i]| == nCols + 1
  {
    if i == dst {
      AddRowAt(aug, dst, src, i);
      assert |xr| == nCols + 1;
    } else {
      AddRowAt(aug, dst, src, i);
      assert newA[i] == aug[i];
    }
  }

  assert (forall j :: 0 <= j <= nCols - 1 && j < |r1| && j < |x| ==>
    IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j])) by {
    forall j | (0 <= j <= nCols - 1 && j < (|r1|) && j < (|x|))
      ensures IsBit(r1[j]) && IsBit(r2[j]) && IsBit(x[j])
    {
      assert IsBit(r1[j]);
      assert IsBit(r2[j]);
      assert 0 <= j < |x|;
      assert x[j] == 0 || x[j] == 1;
      assert IsBit(x[j]);
    }
  }
  DotLinear(r1, r2, x, nCols - 1);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r1| && j < |x| ==> IsBit(r1[j]) && IsBit(x[j]);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r2| && j < |x| ==> IsBit(r2[j]) && IsBit(x[j]);
  DotIsBit(r1, x, nCols - 1);
  DotIsBit(r2, x, nCols - 1);

  assert (SolvesAug(aug, x, nCols) ==> SolvesAug(newA, x, nCols)) by {
    if SolvesAug(aug, x, nCols) {
      forall i | (0 <= i < (|newA|))
        ensures |newA[i]| == nCols + 1 &&
          spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          assert sd == r1[nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(r1[nCols], r2[nCols]) == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          assert newA[i] == xr;
        }
      }
    }
  }

  assert (SolvesAug(newA, x, nCols) ==> SolvesAug(aug, x, nCols)) by {
    if SolvesAug(newA, x, nCols) {
      forall i | (0 <= i < (|aug|))
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          AddRowAt(aug, dst, src, src);
          assert newA[src] == aug[src];
          assert spec_dot_product_gf2(newA[src], x, nCols - 1) == newA[src][nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          assert newA[dst] == xr;
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == add_gf2(r1[nCols], r2[nCols]);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert IsBit(sd) && IsBit(ss);
          assert IsBit(r1[nCols]) && IsBit(r2[nCols]);
          assert ss == r2[nCols];
          XorCancel(sd, ss);
          XorCancel(r1[nCols], ss);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], ss);
          assert add_gf2(add_gf2(sd, ss), ss) == add_gf2(add_gf2(r1[nCols], ss), ss);
          assert add_gf2(add_gf2(sd, ss), ss) == sd;
          assert add_gf2(add_gf2(r1[nCols], ss), ss) == r1[nCols];
          assert sd == r1[nCols];
        }
      }
    }
  }
}

lemma SwapRowEq(m: seq<seq<int>>, r1: int, r2: int, i: int)
  requires 0 <= r1 < |m| && 0 <= r2 < |m| && 0 <= i < |m|
  ensures SwapRows(m, r1, r2)[i] ==
    (if r1 == r2 then m[i] else if i == r1 then m[r2] else if i == r2 then m[r1] else m[i])
{
  if r1 == r2 {
    assert SwapRows(m, r1, r2) == m;
  } else {
    var m1 := m[r1 := m[r2]];
    var m2 := m1[r2 := m[r1]];
    assert SwapRows(m, r1, r2) == m2;
    assert m1[r1] == m[r2];
    if i == r2 {
      assert m2[r2] == m[r1];
    } else if i == r1 {
      assert m2[r1] == m1[r1];
      assert m1[r1] == m[r2];
    } else {
      assert m1[i] == m[i];
      assert m2[i] == m1[i];
    }
  }
}

lemma {:vcs_split_on_every_assert} SwapPreservesSol(
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  x: seq<int>,
  nCols: int)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(SwapRows(aug, r1, r2), x, nCols)
{
  var s := SwapRows(aug, r1, r2);
  assert |s| == |aug|;

  assert (SolvesAug(aug, x, nCols) ==> SolvesAug(s, x, nCols)) by {
    if SolvesAug(aug, x, nCols) {
      forall i | (0 <= i < (|s|))
        ensures |s[i]| == nCols + 1 &&
          spec_dot_product_gf2(s[i], x, nCols - 1) == s[i][nCols]
      {
        var src := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, i);
        assert s[i] == aug[src];
        assert 0 <= src < |aug|;
        assert spec_dot_product_gf2(aug[src], x, nCols - 1) == aug[src][nCols];
      }
    }
  }

  assert (SolvesAug(s, x, nCols) ==> SolvesAug(aug, x, nCols)) by {
    if SolvesAug(s, x, nCols) {
      forall i | (0 <= i < (|aug|))
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        var dst := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, dst);
        if r1 == r2 {
          assert s[dst] == aug[i];
        } else if i == r1 {
          assert dst == r2;
          assert s[dst] == aug[r1];
        } else if i == r2 {
          assert dst == r1;
          assert s[dst] == aug[r2];
        } else {
          assert dst == i;
          assert s[dst] == aug[i];
        }
        assert s[dst] == aug[i];
        assert spec_dot_product_gf2(s[dst], x, nCols - 1) == s[dst][nCols];
        assert |aug[i]| == nCols + 1;
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} SameSolAfterAdd(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  ensures SameSol(matrix, b, AddRowTo(aug, dst, src), nCols)
{
  reveal SameSol();
  var newA := AddRowTo(aug, dst, src);
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures is_solution(matrix, b, x) <==> SolvesAug(newA, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    assert forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1;
    assert forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j]);
    AddRowPreservesSol(aug, dst, src, x, nCols);
  }
}

lemma {:vcs_split_on_every_assert} SameSolAfterSwap(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  ensures SameSol(matrix, b, SwapRows(aug, r1, r2), nCols)
{
  reveal SameSol();
  var s := SwapRows(aug, r1, r2);
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures is_solution(matrix, b, x) <==> SolvesAug(s, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    SwapPreservesSol(aug, r1, r2, x, nCols);
  }
}

lemma StateParts(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, col, rows, nCols)
  ensures AugOK(aug, rows, nCols)
  ensures PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  ensures UnitPivots(aug, pivotCol, numPivots, col, rows, nCols)
  ensures LowerZeros(aug, numPivots, col, rows, nCols)
{
}

lemma AugBit(aug: seq<seq<int>>, rows: int, nCols: int, i: int, j: int)
  requires AugOK(aug, rows, nCols)
  requires 0 <= i < rows
  requires 0 <= j <= nCols
  ensures |aug[i]| == nCols + 1
  ensures IsBit(aug[i][j])
{
  assert |aug[i]| == nCols + 1;
  assert IsBit(aug[i][j]);
}

lemma PivotFact(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int)
  requires PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  requires 0 <= r < numPivots
  ensures 0 <= pivotCol[r] < col
  ensures pivotCol[r] < nCols
  ensures rowOfCol[pivotCol[r]] == r
{
  assert |pivotCol| == rows;
  assert numPivots <= rows;
  assert r < |pivotCol|;
  assert 0 <= pivotCol[r] < col;
  assert pivotCol[r] < |rowOfCol|;
  assert rowOfCol[pivotCol[r]] == r;
  assert |rowOfCol| == nCols;
  assert pivotCol[r] < nCols;
}

lemma RowOfFact(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  j: int)
  requires PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  requires 0 <= j < nCols
  ensures rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots && pivotCol[rowOfCol[j]] == j)
  ensures j >= col ==> rowOfCol[j] == -1
{
  assert j < |rowOfCol|;
  assert rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots && rowOfCol[j] < |pivotCol| && pivotCol[rowOfCol[j]] == j);
  if j >= col {
    assert rowOfCol[j] == -1;
  }
}

lemma UnitFact(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int)
  requires UnitPivots(aug, pivotCol, numPivots, col, rows, nCols)
  requires AugOK(aug, rows, nCols)
  requires 0 <= r < numPivots
  requires r < |pivotCol|
  ensures 0 <= pivotCol[r] < col
  ensures aug[r][pivotCol[r]] == 1
  ensures forall i :: 0 <= i < rows && i != r ==> aug[i][pivotCol[r]] == 0
{
  assert r < |aug|;
  var p := pivotCol[r];
  assert 0 <= p < col;
  assert p < nCols;
  assert p < |aug[r]|;
  assert aug[r][p] == 1;
  forall i | (0 <= i < rows && i != r)
    ensures aug[i][p] == 0
  {
    AugBit(aug, rows, nCols, i, p);
    assert p < |aug[i]|;
    assert aug[i][p] == 0;
  }
}

lemma LowerFact(
  aug: seq<seq<int>>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int,
  j: int)
  requires LowerZeros(aug, numPivots, col, rows, nCols)
  requires AugOK(aug, rows, nCols)
  requires numPivots <= r < rows
  requires 0 <= j < col
  ensures aug[r][j] == 0
{
  AugBit(aug, rows, nCols, r, j);
  assert j < |aug[r]|;
  assert aug[r][j] == 0;
}

lemma {:vcs_split_on_every_assert} InitState(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  pc: seq<int>,
  rc: seq<int>)
  requires |matrix| > 0 && |matrix[0]| > 0
  requires |matrix| == |b|
  requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
  requires is_binary_vector(b)
  requires aug == BuildAug(matrix, b)
  requires |pc| == |matrix|
  requires forall r :: 0 <= r < |matrix| ==> pc[r] == -1
  requires |rc| == |matrix[0]|
  requires forall j :: 0 <= j < |matrix[0]| ==> rc[j] == -1
  ensures RREFState(aug, pc, rc, 0, 0, |matrix|, |matrix[0]|)
  ensures SameSol(matrix, b, aug, |matrix[0]|)
{
  var rows := |matrix|;
  var nCols := |matrix[0]|;
  assert |aug| == rows;

  forall i | (0 <= i < rows)
    ensures |aug[i]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])
  {
    assert aug[i] == matrix[i] + [b[i]];
    assert |matrix[i]| == nCols;
    assert |aug[i]| == nCols + 1;
    forall j | (0 <= j <= nCols)
      ensures IsBit(aug[i][j])
    {
      if j < nCols {
        assert aug[i][j] == matrix[i][j];
        assert matrix[i][j] == 0 || matrix[i][j] == 1;
      } else {
        assert aug[i][j] == b[i];
        assert b[i] == 0 || b[i] == 1;
      }
    }
  }
  assert AugOK(aug, rows, nCols);

  assert forall r :: 0 <= r < rows && r < |pc| ==> pc[r] == -1;
  assert forall r :: 0 <= r < 0 && r < |pc| ==> 0 <= pc[r] < 0 && pc[r] < |rc| && rc[pc[r]] == r;
  assert forall j :: 0 <= j < nCols && j < |rc| ==> rc[j] == -1;
  assert PivotOK(pc, rc, 0, 0, rows, nCols);
  assert UnitPivots(aug, pc, 0, 0, rows, nCols);
  assert LowerZeros(aug, 0, 0, rows, nCols);
  assert RREFState(aug, pc, rc, 0, 0, rows, nCols);

  reveal SameSol();
  forall xv | ((|xv|) == nCols && is_binary_vector(xv))
    ensures is_solution(matrix, b, xv) <==> SolvesAug(aug, xv, nCols)
  {
    forall i | (0 <= i < rows)
      ensures spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
        spec_dot_product_gf2(matrix[i], xv, nCols - 1)
      ensures aug[i][nCols] == b[i]
      ensures |aug[i]| == nCols + 1
    {
      assert aug[i] == matrix[i] + [b[i]];
      assert |matrix[i]| == nCols;
      assert |aug[i]| == nCols + 1;
      assert aug[i][nCols] == b[i];
      assert (forall j :: 0 <= j <= nCols - 1 && j < |xv| ==>
        j < |aug[i]| && j < |matrix[i]| && aug[i][j] == matrix[i][j]) by {
        forall j | (0 <= j <= nCols - 1 && j < (|xv|))
          ensures j < |aug[i]| && j < |matrix[i]| && aug[i][j] == matrix[i][j]
        {
          assert j < nCols;
          assert aug[i][j] == matrix[i][j];
        }
      }
      DotProductDependsOnPrefix(aug[i], matrix[i], xv, nCols - 1);
    }

    assert |matrix| == |b| && |matrix| > 0 && |xv| == |matrix[0]| && is_binary_vector(xv);
    assert is_solution(matrix, b, xv) <==>
      (forall i :: 0 <= i < |matrix| ==>
        spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i]);
    assert forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1;
    assert SolvesAug(aug, xv, nCols) <==>
      (forall i :: 0 <= i < |aug| ==>
        spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols]);

    if is_solution(matrix, b, xv) {
      forall i | (0 <= i < (|aug|))
        ensures spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols]
      {
        assert spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i];
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
          spec_dot_product_gf2(matrix[i], xv, nCols - 1);
        assert aug[i][nCols] == b[i];
      }
    }
    if SolvesAug(aug, xv, nCols) {
      forall i | (0 <= i < (|matrix|))
        ensures spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i]
      {
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols];
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
          spec_dot_product_gf2(matrix[i], xv, nCols - 1);
        assert aug[i][nCols] == b[i];
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} AfterSwap(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  sel: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots <= sel < rows
  requires aug[sel][c] == 1
  ensures var s := SwapRows(aug, numPivots, sel);
    RREFState(s, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  ensures SwapRows(aug, numPivots, sel)[numPivots][c] == 1
{
  var s := SwapRows(aug, numPivots, sel);
  StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
  assert |s| == |aug|;

  forall i | (0 <= i < rows)
    ensures |s[i]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(s[i][j])
  {
    var src := if numPivots == sel then i else if i == numPivots then sel else if i == sel then numPivots else i;
    SwapRowEq(aug, numPivots, sel, i);
    assert s[i] == aug[src];
    assert 0 <= src < rows;
    AugBit(aug, rows, nCols, src, 0);
    assert |aug[src]| == nCols + 1;
    forall j | (0 <= j <= nCols)
      ensures IsBit(s[i][j])
    {
      AugBit(aug, rows, nCols, src, j);
      assert s[i][j] == aug[src][j];
    }
  }
  assert AugOK(s, rows, nCols);
  assert PivotOK(pivotCol, rowOfCol, numPivots, c, rows, nCols);

  forall r | (0 <= r < numPivots && r < |s| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c && pivotCol[r] < nCols && pivotCol[r] < |s[r]| &&
      s[r][pivotCol[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |s| && i != r && pivotCol[r] < |s[i]| ==> s[i][pivotCol[r]] == 0)
  {
    PivotFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, r);
    var p := pivotCol[r];
    assert r < numPivots <= sel;
    assert r != numPivots && r != sel;
    SwapRowEq(aug, numPivots, sel, r);
    assert s[r] == aug[r];
    UnitFact(aug, pivotCol, numPivots, c, rows, nCols, r);
    assert aug[r][p] == 1;
    assert s[r][p] == 1;
    assert p < |s[r]|;
    forall i | (0 <= i < rows && i < |s| && i != r && p < |s[i]|)
      ensures s[i][p] == 0
    {
      var src := if numPivots == sel then i else if i == numPivots then sel else if i == sel then numPivots else i;
      SwapRowEq(aug, numPivots, sel, i);
      assert s[i] == aug[src];
      assert src != r;
      assert 0 <= src < rows;
      AugBit(aug, rows, nCols, src, p);
      assert aug[src][p] == 0;
      assert s[i][p] == 0;
    }
  }
  assert UnitPivots(s, pivotCol, numPivots, c, rows, nCols);

  forall r, j | (numPivots <= r < rows && r < |s| && 0 <= j < c && j < |s[r]|)
    ensures s[r][j] == 0
  {
    var src := if numPivots == sel then r else if r == numPivots then sel else if r == sel then numPivots else r;
    SwapRowEq(aug, numPivots, sel, r);
    assert s[r] == aug[src];
    assert numPivots <= src < rows;
    LowerFact(aug, numPivots, c, rows, nCols, src, j);
    assert s[r][j] == 0;
  }
  assert LowerZeros(s, numPivots, c, rows, nCols);
  assert RREFState(s, pivotCol, rowOfCol, numPivots, c, rows, nCols);

  SwapRowEq(aug, numPivots, sel, numPivots);
  if numPivots == sel {
    assert s[numPivots] == aug[numPivots];
  } else {
    assert s[numPivots] == aug[sel];
  }
  assert s[numPivots] == aug[sel];
  assert s[numPivots][c] == aug[sel][c];
  assert s[numPivots][c] == 1;
}

lemma {:vcs_split_on_every_assert} AddElimStep(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  i: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots < rows
  requires 0 <= i < rows && i != numPivots
  requires aug[numPivots][c] == 1
  requires aug[i][c] == 1
  ensures var n := AddRowTo(aug, i, numPivots);
    RREFState(n, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  ensures AddRowTo(aug, i, numPivots)[numPivots][c] == 1
  ensures AddRowTo(aug, i, numPivots)[i][c] == 0
{
  var P := numPivots;
  var n := AddRowTo(aug, i, P);
  StateParts(aug, pivotCol, rowOfCol, P, c, rows, nCols);
  AugBit(aug, rows, nCols, i, c);
  AugBit(aug, rows, nCols, P, c);
  assert |aug[i]| == |aug[P]|;
  AddRowAt(aug, i, P, i);
  AddRowAt(aug, i, P, P);
  assert n[i] == XorRow(aug[i], aug[P]);
  assert n[P] == aug[P];
  assert n[P][c] == 1;

  XorEntry(aug[i], aug[P], c);
  assert aug[i][c] == 1 && aug[P][c] == 1;
  assert (1 + 1) % 2 == 0;
  assert n[i][c] == 0;

  forall t | (0 <= t < rows)
    ensures |n[t]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(n[t][j])
  {
    if t == i {
      assert |n[t]| == nCols + 1;
      forall j | (0 <= j <= nCols)
        ensures IsBit(n[t][j])
      {
        AugBit(aug, rows, nCols, i, j);
        AugBit(aug, rows, nCols, P, j);
        XorEntry(aug[i], aug[P], j);
        AddIsBit(aug[i][j], aug[P][j]);
        assert n[t][j] == (aug[i][j] + aug[P][j]) % 2;
        assert add_gf2(aug[i][j], aug[P][j]) == (aug[i][j] + aug[P][j]) % 2;
        assert IsBit(add_gf2(aug[i][j], aug[P][j]));
        assert IsBit(n[t][j]);
      }
    } else {
      AddRowAt(aug, i, P, t);
      assert n[t] == aug[t];
      AugBit(aug, rows, nCols, t, 0);
      forall j | (0 <= j <= nCols)
        ensures IsBit(n[t][j])
      {
        AugBit(aug, rows, nCols, t, j);
        assert n[t][j] == aug[t][j];
      }
    }
  }
  assert AugOK(n, rows, nCols);
  assert PivotOK(pivotCol, rowOfCol, P, c, rows, nCols);

  forall r | (0 <= r < P && r < |n| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c && pivotCol[r] < nCols && pivotCol[r] < |n[r]| &&
      n[r][pivotCol[r]] == 1 &&
      (forall t :: 0 <= t < rows && t < |n| && t != r && pivotCol[r] < |n[t]| ==> n[t][pivotCol[r]] == 0)
  {
    PivotFact(pivotCol, rowOfCol, P, c, rows, nCols, r);
    UnitFact(aug, pivotCol, P, c, rows, nCols, r);
    var p := pivotCol[r];
    assert p < c;
    assert aug[P][p] == 0;
    if i == r {
      AddRowAt(aug, i, P, r);
      XorEntry(aug[r], aug[P], p);
      assert aug[r][p] == 1 && aug[P][p] == 0;
      assert (1 + 0) % 2 == 1;
      assert n[r][p] == 1;
    } else {
      AddRowAt(aug, i, P, r);
      assert n[r] == aug[r];
      assert n[r][p] == 1;
    }
    assert p < |n[r]|;
    forall t | (0 <= t < rows && t < |n| && t != r && p < |n[t]|)
      ensures n[t][p] == 0
    {
      if t == i {
        assert i != r;
        assert aug[i][p] == 0;
        assert aug[P][p] == 0;
        XorEntry(aug[i], aug[P], p);
        assert (0 + 0) % 2 == 0;
        assert n[i][p] == 0;
      } else {
        AddRowAt(aug, i, P, t);
        assert n[t] == aug[t];
        assert aug[t][p] == 0;
        assert n[t][p] == 0;
      }
    }
  }
  assert UnitPivots(n, pivotCol, P, c, rows, nCols);

  forall r, j | (P <= r < rows && r < |n| && 0 <= j < c && j < |n[r]|)
    ensures n[r][j] == 0
  {
    LowerFact(aug, P, c, rows, nCols, P, j);
    if r == i {
      assert r != P;
      LowerFact(aug, P, c, rows, nCols, r, j);
      XorEntry(aug[r], aug[P], j);
      assert aug[r][j] == 0 && aug[P][j] == 0;
      assert (0 + 0) % 2 == 0;
      assert n[r][j] == 0;
    } else {
      AddRowAt(aug, i, P, r);
      assert n[r] == aug[r];
      LowerFact(aug, P, c, rows, nCols, r, j);
      assert n[r][j] == 0;
    }
  }
  assert LowerZeros(n, P, c, rows, nCols);
  assert RREFState(n, pivotCol, rowOfCol, P, c, rows, nCols);
}

lemma {:vcs_split_on_every_assert} NoPivotAdvance(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires forall r :: numPivots <= r < rows ==> aug[r][c] == 0
  ensures RREFState(aug, pivotCol, rowOfCol, numPivots, c + 1, rows, nCols)
{
  StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
  assert AugOK(aug, rows, nCols);

  assert |pivotCol| == rows && |rowOfCol| == nCols;
  assert 0 <= numPivots <= rows && 0 <= c + 1 <= nCols;
  assert forall r :: numPivots <= r < rows && r < |pivotCol| ==> pivotCol[r] == -1;

  forall r | (0 <= r < numPivots && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c + 1 && pivotCol[r] < |rowOfCol| && rowOfCol[pivotCol[r]] == r
  {
    PivotFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, r);
    assert pivotCol[r] < c;
    assert pivotCol[r] < c + 1;
  }

  forall j | (0 <= j < nCols && j < |rowOfCol|)
    ensures rowOfCol[j] == -1 ||
      (0 <= rowOfCol[j] < numPivots && rowOfCol[j] < |pivotCol| && pivotCol[rowOfCol[j]] == j)
  {
    RowOfFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, j);
    if rowOfCol[j] != -1 {
      var rr := rowOfCol[j];
      assert 0 <= rr < numPivots;
      assert rr < |pivotCol|;
      assert pivotCol[rr] == j;
    }
  }

  forall j | (c + 1 <= j < nCols && j < |rowOfCol|)
    ensures rowOfCol[j] == -1
  {
    assert j >= c;
    RowOfFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, j);
  }
  assert PivotOK(pivotCol, rowOfCol, numPivots, c + 1, rows, nCols);

  forall r | (0 <= r < numPivots && r < |aug| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c + 1 && pivotCol[r] < nCols && pivotCol[r] < |aug[r]| &&
      aug[r][pivotCol[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |aug| && i != r && pivotCol[r] < |aug[i]| ==>
        aug[i][pivotCol[r]] == 0)
  {
    UnitFact(aug, pivotCol, numPivots, c, rows, nCols, r);
    assert pivotCol[r] < c + 1;
  }
  assert UnitPivots(aug, pivotCol, numPivots, c + 1, rows, nCols);

  forall r, j | (numPivots <= r < rows && r < |aug| && 0 <= j < c + 1 && j < |aug[r]|)
    ensures aug[r][j] == 0
  {
    if j < c {
      LowerFact(aug, numPivots, c, rows, nCols, r, j);
    } else {
      assert j == c;
      assert aug[r][c] == 0;
    }
  }
  assert LowerZeros(aug, numPivots, c + 1, rows, nCols);
  assert RREFState(aug, pivotCol, rowOfCol, numPivots, c + 1, rows, nCols);
}

lemma {:vcs_split_on_every_assert} RecordPivot(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots < rows
  requires 0 <= numPivots < |pivotCol|
  requires 0 <= c < |rowOfCol|
  requires aug[numPivots][c] == 1
  requires forall t :: 0 <= t < rows && t != numPivots ==> aug[t][c] == 0
  ensures RREFState(
    aug,
    pivotCol[numPivots := c],
    rowOfCol[c := numPivots],
    numPivots + 1,
    c + 1,
    rows,
    nCols)
{
  var P := numPivots;
  var pc2 := pivotCol[P := c];
  var rc2 := rowOfCol[c := P];
  var np := P + 1;
  var col2 := c + 1;
  StateParts(aug, pivotCol, rowOfCol, P, c, rows, nCols);
  assert AugOK(aug, rows, nCols);

  assert |pc2| == |pivotCol| == rows;
  assert |rc2| == |rowOfCol| == nCols;
  assert pc2[P] == c;
  assert rc2[c] == P;
  forall t | (0 <= t < |pivotCol| && t != P)
    ensures pc2[t] == pivotCol[t]
  {
  }
  forall t | (0 <= t < |rowOfCol| && t != c)
    ensures rc2[t] == rowOfCol[t]
  {
  }

  forall r | (np <= r < rows && r < |pc2|)
    ensures pc2[r] == -1
  {
    assert r != P;
    assert r >= P;
    assert pivotCol[r] == -1;
    assert pc2[r] == pivotCol[r];
  }

  forall r | (0 <= r < np && r < |pc2|)
    ensures 0 <= pc2[r] < col2 && pc2[r] < |rc2| && rc2[pc2[r]] == r
  {
    if r < P {
      PivotFact(pivotCol, rowOfCol, P, c, rows, nCols, r);
      assert pc2[r] == pivotCol[r];
      assert pivotCol[r] < c;
      assert pivotCol[r] != c;
      assert rc2[pc2[r]] == rowOfCol[pivotCol[r]];
      assert rowOfCol[pivotCol[r]] == r;
      assert pc2[r] < col2;
    } else {
      assert r == P;
      assert pc2[r] == c;
      assert rc2[c] == P;
      assert 0 <= c < col2;
      assert c < |rc2|;
    }
  }

  forall j | (0 <= j < nCols && j < |rc2|)
    ensures rc2[j] == -1 ||
      (0 <= rc2[j] < np && rc2[j] < |pc2| && pc2[rc2[j]] == j)
  {
    if j == c {
      assert rc2[j] == P;
      assert 0 <= P < np;
      assert pc2[P] == c;
    } else {
      assert rc2[j] == rowOfCol[j];
      RowOfFact(pivotCol, rowOfCol, P, c, rows, nCols, j);
      if rowOfCol[j] == -1 {
        assert rc2[j] == -1;
      } else {
        var rr := rowOfCol[j];
        assert 0 <= rr < P;
        assert rr != P;
        assert pc2[rr] == pivotCol[rr];
        assert pivotCol[rr] == j;
        assert rr < np;
      }
    }
  }

  forall j | (col2 <= j < nCols && j < |rc2|)
    ensures rc2[j] == -1
  {
    assert j != c && j >= c;
    assert rc2[j] == rowOfCol[j];
    RowOfFact(pivotCol, rowOfCol, P, c, rows, nCols, j);
  }
  assert PivotOK(pc2, rc2, np, col2, rows, nCols);

  forall r | (0 <= r < np && r < |aug| && r < |pc2|)
    ensures 0 <= pc2[r] < col2 && pc2[r] < nCols && pc2[r] < |aug[r]| &&
      aug[r][pc2[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |aug| && i != r && pc2[r] < |aug[i]| ==>
        aug[i][pc2[r]] == 0)
  {
    if r < P {
      assert pc2[r] == pivotCol[r];
      UnitFact(aug, pivotCol, P, c, rows, nCols, r);
      assert pivotCol[r] < c;
      assert pc2[r] < col2;
      forall i | (0 <= i < rows && i < |aug| && i != r && pc2[r] < |aug[i]|)
        ensures aug[i][pc2[r]] == 0
      {
        assert aug[i][pivotCol[r]] == 0;
      }
    } else {
      assert r == P;
      assert pc2[r] == c;
      AugBit(aug, rows, nCols, r, c);
      assert c < |aug[r]|;
      assert aug[r][c] == 1;
      forall i | (0 <= i < rows && i < |aug| && i != r && c < |aug[i]|)
        ensures aug[i][c] == 0
      {
        assert aug[i][c] == 0;
      }
    }
  }
  assert UnitPivots(aug, pc2, np, col2, rows, nCols);

  forall r, j | (np <= r < rows && r < |aug| && 0 <= j < col2 && j < |aug[r]|)
    ensures aug[r][j] == 0
  {
    assert r != P;
    if j < c {
      LowerFact(aug, P, c, rows, nCols, r, j);
    } else {
      assert j == c;
      assert aug[r][c] == 0;
    }
  }
  assert LowerZeros(aug, np, col2, rows, nCols);
  assert RREFState(aug, pc2, rc2, np, col2, rows, nCols);
}

lemma XFromIndex(aug: seq<seq<int>>, rowOfCol: seq<int>, nCols: int, j: int)
  requires |rowOfCol| == nCols
