lemma {:vcs_split_on_every_assert} InconsistentNone(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  nCols: int,
  bad: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires |matrix| == |b| == |aug|
  requires |matrix| > 0 && nCols == |matrix[0]| && nCols >= 1
  requires 0 <= bad < |aug|
  requires forall j :: 0 <= j < nCols ==> aug[bad][j] == 0
  requires aug[bad][nCols] == 1
  ensures forall x: seq<int> ::
    (|x| == |matrix[0]| && is_binary_vector(x)) ==> !is_solution(matrix, b, x)
{
  reveal SameSol();
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures !is_solution(matrix, b, x)
  {
    if is_solution(matrix, b, x) {
      assert SolvesAug(aug, x, nCols);
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[bad]| && j < |x| ==>
        aug[bad][j] == 0 || x[j] == 0) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[bad]|) && j < (|x|))
          ensures aug[bad][j] == 0 || x[j] == 0
        {
          assert aug[bad][j] == 0;
        }
      }
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[bad]| && j < |x| ==>
        IsBit(aug[bad][j]) && IsBit(x[j])) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[bad]|) && j < (|x|))
          ensures IsBit(aug[bad][j]) && IsBit(x[j])
        {
          AugBit(aug, |aug|, nCols, bad, j);
          assert x[j] == 0 || x[j] == 1;
        }
      }
      ZeroDot(aug[bad], x, nCols - 1);
      assert spec_dot_product_gf2(aug[bad], x, nCols - 1) == 0;
      assert spec_dot_product_gf2(aug[bad], x, nCols - 1) == aug[bad][nCols];
      assert aug[bad][nCols] == 1;
      assert false;
    }
  }
}

method {:vcs_split_on_every_assert} solve_linear_system_gf2(matrix: seq<seq<int>>, b: seq<int>) returns (res: Option<seq<int>>)
  requires |matrix| > 0
  requires |matrix[0]| > 0
  requires |matrix| == |b|
  requires |matrix| <= 100
  requires |matrix[0]| <= 100
  requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
  requires is_binary_vector(b)
  ensures match res
    case Some(x) => is_solution(matrix, b, x)
    case None =>
      forall x: seq<int> ::
        (|x| == |matrix[0]| && is_binary_vector(x))
        ==> !is_solution(matrix, b, x)
{
  var rows := |matrix|;
  var nCols := |matrix[0]|;
  var aug := BuildAug(matrix, b);
  var pivotCol := seq(rows, i => -1);
  var rowOfCol := seq(nCols, j => -1);
  forall r | (0 <= r < rows)
    ensures pivotCol[r] == -1
  {
  }
  forall j | (0 <= j < nCols)
    ensures rowOfCol[j] == -1
  {
  }
  InitState(matrix, b, aug, pivotCol, rowOfCol);

  var numPivots := 0;
  var c := 0;
  while c < nCols
    invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
    invariant SameSol(matrix, b, aug, nCols)
    decreases nCols - c
  {
    var sel := numPivots;
    while sel < rows && aug[sel][c] == 0
      invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
      invariant numPivots <= sel <= rows
      invariant forall t :: numPivots <= t < sel ==> aug[t][c] == 0
      decreases rows - sel
    {
      sel := sel + 1;
    }

    if sel == rows {
      assert forall r :: numPivots <= r < rows ==> aug[r][c] == 0;
      var newC := c + 1;
      NoPivotAdvance(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert RREFState(aug, pivotCol, rowOfCol, numPivots, newC, rows, nCols);
      c := newC;
    } else {
      StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      AugBit(aug, rows, nCols, sel, c);
      assert aug[sel][c] != 0;
      assert aug[sel][c] == 1;
      assert numPivots < rows;

      var swapped := SwapRows(aug, numPivots, sel);
      AfterSwap(aug, pivotCol, rowOfCol, numPivots, c, sel, rows, nCols);
      SameSolAfterSwap(matrix, b, aug, numPivots, sel, nCols);
      assert RREFState(swapped, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert SameSol(matrix, b, swapped, nCols);
      assert swapped[numPivots][c] == 1;
      aug := swapped;

      var i := 0;
      while i < rows
        invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
        invariant SameSol(matrix, b, aug, nCols)
        invariant aug[numPivots][c] == 1
        invariant forall t :: 0 <= t < i && t != numPivots ==> aug[t][c] == 0
        invariant 0 <= i <= rows
        invariant numPivots < rows
        invariant 0 <= c < nCols
        decreases rows - i
      {
        if i != numPivots && aug[i][c] == 1 {
          var newAug := AddRowTo(aug, i, numPivots);
          AddElimStep(aug, pivotCol, rowOfCol, numPivots, c, i, rows, nCols);
          SameSolAfterAdd(matrix, b, aug, i, numPivots, nCols);
          assert RREFState(newAug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
          assert SameSol(matrix, b, newAug, nCols);
          assert newAug[numPivots][c] == 1;
          assert newAug[i][c] == 0;
          assert (forall t :: 0 <= t < i && t != numPivots ==> newAug[t][c] == 0) by {
            forall t | (0 <= t < i && t != numPivots)
              ensures newAug[t][c] == 0
            {
              assert t != i;
              AddRowAt(aug, i, numPivots, t);
              assert newAug[t] == aug[t];
              assert aug[t][c] == 0;
            }
          }
          aug := newAug;
          assert (forall t :: 0 <= t < i + 1 && t != numPivots ==> aug[t][c] == 0) by {
            forall t | (0 <= t < i + 1 && t != numPivots)
              ensures aug[t][c] == 0
            {
              if t < i {
                assert aug[t][c] == 0;
              } else {
                assert t == i;
                assert aug[i][c] == 0;
              }
            }
          }
        } else if i != numPivots {
          StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
          AugBit(aug, rows, nCols, i, c);
          assert aug[i][c] != 1;
          assert aug[i][c] == 0;
          assert (forall t :: 0 <= t < i + 1 && t != numPivots ==> aug[t][c] == 0) by {
            forall t | (0 <= t < i + 1 && t != numPivots)
              ensures aug[t][c] == 0
            {
              if t < i {
                assert aug[t][c] == 0;
              } else {
                assert t == i;
                assert aug[i][c] == 0;
              }
            }
          }
        } else {
          assert i == numPivots;
          assert (forall t :: 0 <= t < i + 1 && t != numPivots ==> aug[t][c] == 0) by {
            forall t | (0 <= t < i + 1 && t != numPivots)
              ensures aug[t][c] == 0
            {
              assert t != i;
              assert t < i;
              assert aug[t][c] == 0;
            }
          }
        }
        i := i + 1;
      }

      assert forall t :: 0 <= t < rows && t != numPivots ==> aug[t][c] == 0;
      assert aug[numPivots][c] == 1;
      var newPc := pivotCol[numPivots := c];
      var newRc := rowOfCol[c := numPivots];
      var newNp := numPivots + 1;
      var newC := c + 1;
      RecordPivot(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert RREFState(aug, newPc, newRc, newNp, newC, rows, nCols);
      pivotCol := newPc;
      rowOfCol := newRc;
      numPivots := newNp;
      c := newC;
    }
  }

  var rr := numPivots;
  while rr < rows
    invariant RREFState(aug, pivotCol, rowOfCol, numPivots, nCols, rows, nCols)
    invariant SameSol(matrix, b, aug, nCols)
    invariant numPivots <= rr <= rows
    invariant forall t :: numPivots <= t < rr ==> aug[t][nCols] == 0
    decreases rows - rr
  {
    StateParts(aug, pivotCol, rowOfCol, numPivots, nCols, rows, nCols);
    AugBit(aug, rows, nCols, rr, nCols);
    if aug[rr][nCols] == 1 {
      assert (forall j :: 0 <= j < nCols ==> aug[rr][j] == 0) by {
        forall j | (0 <= j < nCols)
          ensures aug[rr][j] == 0
        {
          LowerFact(aug, numPivots, nCols, rows, nCols, rr, j);
        }
      }
      InconsistentNone(matrix, b, aug, nCols, rr);
      return None;
    }
    assert aug[rr][nCols] == 0;
    rr := rr + 1;
  }

  assert forall t :: numPivots <= t < rows ==> aug[t][nCols] == 0;
  ConstructedSolves(aug, pivotCol, rowOfCol, numPivots, rows, nCols);
  var x := XFrom(aug, rowOfCol, nCols);
  assert SolvesAug(aug, x, nCols);
  reveal SameSol();
  assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
  assert is_solution(matrix, b, x);
  return Some(x);
}
