lemma {:vcs_split_on_every_assert} RotateBHCalc(a: int, b: int, r: int, nodeRed: bool)
    ensures BHOf(a, BHOf(b, r, true), nodeRed) == BHOf(BHOf(a, b, true), r, nodeRed)
{
    BHOfAny(a, b, true);
    BHOfAny(b, r, true);
    var lbh := BHOf(a, b, true);
    var nrbh := BHOf(b, r, true);
    assert lbh == (if a != -1 && b != -1 && a == b then a else -1);
    assert nrbh == (if b != -1 && r != -1 && b == r then b else -1);

    BHOfAny(a, nrbh, nodeRed);
    BHOfAny(lbh, r, nodeRed);
    var rbh := BHOf(a, nrbh, nodeRed);
    var nbh := BHOf(lbh, r, nodeRed);
    assert rbh == BHOf(a, BHOf(b, r, true), nodeRed);
    assert nbh == BHOf(BHOf(a, b, true), r, nodeRed);

    if a != -1 && b != -1 && a == b && r != -1 && r == a {
        assert b == a;
        assert lbh == a;
        assert b != -1 && r != -1 && b == r;
        assert nrbh == b;
        assert nrbh == a;
        assert rbh == (if !nodeRed then a + 1 else a);
        assert nbh == (if !nodeRed then a + 1 else a);
        assert rbh == nbh;
        assert BHOf(a, BHOf(b, r, true), nodeRed) == BHOf(BHOf(a, b, true), r, nodeRed);
        return;
    } else if a != -1 && b != -1 && a == b {
        assert b == a;
        assert lbh == a;
        assert b != -1;
        assert r == -1 || r != a;
        assert !(r != -1 && r == b);
        assert !(b != -1 && r != -1 && b == r);
        assert nrbh == -1;
        assert nbh == -1;
        assert rbh == -1;
        assert rbh == nbh;
        assert BHOf(a, BHOf(b, r, true), nodeRed) == BHOf(BHOf(a, b, true), r, nodeRed);
        return;
    } else {
        assert !(a != -1 && b != -1 && a == b);
        assert lbh == -1;
        assert nbh == -1;
        if b != -1 && r != -1 && b == r {
            assert nrbh == b;
            assert a == -1 || a != b;
            assert !(a != -1 && b != -1 && a == b);
            assert rbh == BHOf(a, b, nodeRed);
            assert BHOf(a, b, nodeRed) == -1;
            assert rbh == -1;
        } else {
            assert !(b != -1 && r != -1 && b == r);
            assert nrbh == -1;
            assert rbh == -1;
        }
        assert rbh == nbh;
        assert BHOf(a, BHOf(b, r, true), nodeRed) == BHOf(BHOf(a, b, true), r, nodeRed);
    }
}

