lemma {:vcs_split_on_every_assert} ProveNrBst(node: Node, l: Node, nr: Node)
    requires node.is_bst()
    requires node.left == Some(l)
    requires nr == Node(node.val, true, l.right, node.right)
    ensures nr.is_bst()
{
    BstLeft(node, l);
    assert l.is_bst();
    assert forall x :: x in l.view() ==> x < node.val;

    if l.right.Some? && node.right.Some? {
        var b := l.right.value;
        var rv := node.right.value;
        assert l.right == Some(b);
        assert node.right == Some(rv);
        BstRight(l, b);
        ViewSubsetRight(l, b);
        assert b.view() <= l.view();
        ForallLtSubset(b.view(), l.view(), node.val);
        BstRight(node, rv);
        assert b.is_bst();
        assert rv.is_bst();
        assert forall x :: x in b.view() ==> x < node.val;
        assert forall x :: x in rv.view() ==> x > node.val;
        var built := Node(node.val, true, Some(b), Some(rv));
        Bst_SS(node.val, true, b, rv);
        assert built.is_bst();
        assert nr == built;
        assert nr.is_bst();
    } else if l.right.Some? {
        var b := l.right.value;
        assert l.right == Some(b);
        assert !node.right.Some?;
        assert node.right == None;
        BstRight(l, b);
        ViewSubsetRight(l, b);
        assert b.view() <= l.view();
        ForallLtSubset(b.view(), l.view(), node.val);
        assert b.is_bst();
        assert forall x :: x in b.view() ==> x < node.val;
        var built := Node(node.val, true, Some(b), None);
        Bst_SN(node.val, true, b);
        assert built.is_bst();
        assert nr == built;
        assert nr.is_bst();
    } else if node.right.Some? {
        var rv := node.right.value;
        assert !l.right.Some?;
        assert l.right == None;
        assert node.right == Some(rv);
        BstRight(node, rv);
        assert rv.is_bst();
        assert forall x :: x in rv.view() ==> x > node.val;
        var built := Node(node.val, true, None, Some(rv));
        Bst_NS(node.val, true, rv);
        assert built.is_bst();
        assert nr == built;
        assert nr.is_bst();
    } else {
        assert l.right == None;
        assert node.right == None;
        var built := Node(node.val, true, None, None);
        Bst_NN(node.val, true);
        assert built.is_bst();
        assert nr == built;
        assert nr.is_bst();
    }
    assert nr.is_bst();
}

