predicate lis_extends(
    s: seq<int>,
    prefix: seq<int>,
    start: int,
    candidate: seq<int>)
{
    is_valid_is(s, candidate)
    && |prefix| <= |candidate|
    && candidate[..|prefix|] == prefix
    && (forall k: int ::
        |prefix| <= k < |candidate| ==> start <= candidate[k])
}

lemma lis_append_valid(s: seq<int>, prefix: seq<int>, i: int)
    requires is_valid_is(s, prefix)
    requires 0 <= i < |s|
    requires forall k: int :: 0 <= k < |prefix| ==> prefix[k] < i
    requires |prefix| == 0 || s[prefix[|prefix| - 1]] < s[i]
    ensures is_valid_is(s, prefix + [i])
{
    assert forall k: int, m: int |
        0 <= k < m < |prefix + [i]|
        ensures (prefix + [i])[k] < (prefix + [i])[m]
    {
        if m < |prefix| {
            assert prefix[k] < prefix[m];
        } else {
            assert m == |prefix|;
            assert (prefix + [i])[m] == i;
            assert prefix[k] < i;
        }
    }

    assert forall k: int |
        0 <= k < |prefix + [i]|
        ensures 0 <= (prefix + [i])[k] < |s|
    {
        if k < |prefix| {
            assert 0 <= prefix[k] < |s|;
        } else {
            assert k == |prefix|;
            assert (prefix + [i])[k] == i;
        }
    }

    assert forall k: int, m: int |
        0 <= k < m < |prefix + [i]|
        ensures s[(prefix + [i])[k]] < s[(prefix + [i])[m]]
    {
        if m < |prefix| {
            assert s[prefix[k]] < s[prefix[m]];
        } else {
            assert m == |prefix|;
            assert |prefix| > 0;
            assert (prefix + [i])[m] == i;

            if k < |prefix| - 1 {
                assert s[prefix[k]] < s[prefix[|prefix| - 1]];
                assert s[prefix[|prefix| - 1]] < s[i];
            } else {
                assert k == |prefix| - 1;
                assert s[prefix[k]] < s[i];
