        }
    }

    forall k: int, m: int |
        0 <= k < m < |prefix + [i]|
        ensures s[(prefix + [i])[k]] < s[(prefix + [i])[m]]
    {
        if m < |prefix| {
            assert (prefix + [i])[k] == prefix[k];
            assert (prefix + [i])[m] == prefix[m];
            assert s[prefix[k]] < s[prefix[m]];
        } else {
            assert m == |prefix|;
            assert k < |prefix|;
            assert |prefix| > 0;
            assert (prefix + [i])[k] == prefix[k];
            assert (prefix + [i])[m] == i;

            if k < |prefix| - 1 {
                assert 0 <= k < |prefix| - 1 < |prefix|;
                assert s[prefix[k]] < s[prefix[|prefix| - 1]];
                assert s[prefix[|prefix| - 1]] < s[i];
            } else {
                assert k == |prefix| - 1;
                assert s[prefix[k]] < s[i];
            }
        }
    }
}

lemma lis_extension_at_end(
    s: seq<int>,
    prefix: seq<int>,
    candidate: seq<int>)
    requires lis_extends(s, prefix, |s|, candidate)
    ensures candidate == prefix
{
    if |candidate| > |prefix| {
        assert |prefix| < |candidate|;
        assert |s| <= candidate[|prefix|];
        assert 0 <= candidate[|prefix|] < |s|;
        assert false;
    }

    assert |prefix| <= |candidate|;
    assert |candidate| <= |prefix|;
    assert |candidate| == |prefix|;
    assert candidate[..|prefix|] == candidate;
    assert candidate[..|prefix|] == prefix;
}

lemma lis_promote_skipped_position(
    s: seq<int>,
    prefix: seq<int>,
    start: int,
    candidate: seq<int>)
    requires lis_extends(s, prefix, start, candidate)
    requires |candidate| == |prefix|
          || candidate[|prefix|] != start
    ensures lis_extends(s, prefix, start + 1, candidate)
{
    forall k: int |
        |prefix| <= k < |candidate|
        ensures start + 1 <= candidate[k]
    {
        assert start <= candidate[k];

        if k == |prefix| {
            assert |candidate| != |prefix|;
            assert candidate[k] != start;
        } else {
            assert |prefix| < k;
            assert 0 <= |prefix| < k < |candidate|;
            assert candidate[|prefix|] < candidate[k];
            assert start <= candidate[|prefix|];
        }
    }
}

lemma lis_promote_selected_position(
    s: seq<int>,
    prefix: seq<int>,
    start: int,
    candidate: seq<int>)
    requires lis_extends(s, prefix, start, candidate)
    requires |prefix| < |candidate|
    requires candidate[|prefix|] == start
    ensures lis_extends(
        s, prefix + [start], start + 1, candidate)
{
    assert candidate[..(|prefix| + 1)]
        == candidate[..|prefix|] + [candidate[|prefix|]];
    assert candidate[..|prefix|] == prefix;
    assert candidate[..(|prefix| + 1)] == prefix + [start];

    forall k: int |
        |prefix + [start]| <= k < |candidate|
        ensures start + 1 <= candidate[k]
    {
        assert |prefix + [start]| == |prefix| + 1;
        assert 0 <= |prefix| < k < |candidate|;
        assert candidate[|prefix|] < candidate[k];
        assert candidate[|prefix|] == start;
    }
}

lemma lis_weaken_start(
    s: seq<int>,
    prefix: seq<int>,
    low: int,
    high: int,
    candidate: seq<int>)
    requires low <= high
    requires lis_extends(s, prefix, high, candidate)
    ensures lis_extends(s, prefix, low, candidate)
{
    forall k: int |
        |prefix| <= k < |candidate|
        ensures low <= candidate[k]
    {
        assert high <= candidate[k];
    }
}

lemma lis_forget_selected_position(
    s: seq<int>,
    prefix: seq<int>,
    start: int,
    candidate: seq<int>)
    requires lis_extends(
        s, prefix + [start], start + 1, candidate)
    ensures lis_extends(s, prefix, start, candidate)
{
    assert |prefix + [start]| == |prefix| + 1;
    assert candidate[..(|prefix| + 1)] == prefix + [start];
    assert (candidate[..(|prefix| + 1)])[..|prefix|]
        == candidate[..|prefix|];
    assert (prefix + [start])[..|prefix|] == prefix;
    assert candidate[..|prefix|] == prefix;

    forall k: int |
        |prefix| <= k < |candidate|
        ensures start <= candidate[k]
    {
        if k == |prefix| {
            assert candidate[k] == start;
        } else {
            assert |prefix| + 1 <= k;
            assert start + 1 <= candidate[k];
        }
    }
}

lemma lis_selected_position_is_compatible(
    s: seq<int>,
    prefix: seq<int>,
    start: int,
    candidate: seq<int>)
    requires lis_extends(s, prefix, start, candidate)
    requires 0 < |prefix| < |candidate|
    requires candidate[|prefix|] == start
    ensures s[prefix[|prefix| - 1]] < s[start]
{
    assert candidate[..|prefix|] == prefix;
    assert candidate[|prefix| - 1]
        == prefix[|prefix| - 1];
    assert 0 <= |prefix| - 1 < |prefix| < |candidate|;
    assert s[candidate[|prefix| - 1]]
        < s[candidate[|prefix|]];
}

lemma lis_empty_prefix_extension(
    s: seq<int>,
    candidate: seq<int>)
    requires is_valid_is(s, candidate)
    ensures lis_extends(s, [], 0, candidate)
{
    assert candidate[..0] == [];

    forall k: int |
        0 <= k < |candidate|
        ensures 0 <= candidate[k]
    {
        assert 0 <= candidate[k] < |s|;
    }
}

method lis_search(
    s: seq<int>,
    prefix: seq<int>,
    start: int)
    returns (best: int, wit: seq<int>)
    requires 0 <= start <= |s|
    requires is_valid_is(s, prefix)
    requires forall k: int ::
        0 <= k < |prefix| ==> prefix[k] < start
    ensures best == |wit|
    ensures lis_extends(s, prefix, start, wit)
    ensures forall candidate: seq<int> ::
        lis_extends(s, prefix, start, candidate)
        ==> |candidate| <= best
    decreases |s| - start
{
    if start == |s| {
        best := |prefix|;
        wit := prefix;

        assert lis_extends(s, prefix, start, wit);

        forall candidate: seq<int> |
            lis_extends(s, prefix, start, candidate)
            ensures |candidate| <= best
        {
            lis_extension_at_end(s, prefix, candidate);
        }
    } else {
        assert start < |s|;

        forall k: int |
            0 <= k < |prefix|
            ensures prefix[k] < start + 1
        {
            assert prefix[k] < start;
        }

        var skippedBest, skippedWit :=
            lis_search(s, prefix, start + 1);

        if |prefix| == 0
           || s[prefix[|prefix| - 1]] < s[start]
        {
            lis_append_valid(s, prefix, start);

            forall k: int |
                0 <= k < |prefix + [start]|
                ensures (prefix + [start])[k] < start + 1
            {
                if k < |prefix| {
                    assert (prefix + [start])[k] == prefix[k];
                    assert prefix[k] < start;
                } else {
                    assert k == |prefix|;
                    assert (prefix + [start])[k] == start;
                }
            }

            var selectedBest, selectedWit :=
                lis_search(s, prefix + [start], start + 1);

            if selectedBest > skippedBest {
                best := selectedBest;
                wit := selectedWit;
                lis_forget_selected_position(
                    s, prefix, start, wit);
            } else {
                best := skippedBest;
                wit := skippedWit;
                lis_weaken_start(
                    s, prefix, start, start + 1, wit);
            }

            assert skippedBest <= best;
            assert selectedBest <= best;

            forall candidate: seq<int> |
                lis_extends(s, prefix, start, candidate)
                ensures |candidate| <= best
            {
                if |candidate| == |prefix| {
                    lis_promote_skipped_position(
                        s, prefix, start, candidate);
                    assert |candidate| <= skippedBest;
                } else {
                    assert |prefix| < |candidate|;

                    if candidate[|prefix|] == start {
                        lis_promote_selected_position(
                            s, prefix, start, candidate);
                        assert |candidate| <= selectedBest;
                    } else {
                        lis_promote_skipped_position(
                            s, prefix, start, candidate);
                        assert |candidate| <= skippedBest;
                    }
                }
            }
        } else {
            best := skippedBest;
            wit := skippedWit;
            lis_weaken_start(
                s, prefix, start, start + 1, wit);

            forall candidate: seq<int> |
                lis_extends(s, prefix, start, candidate)
                ensures |candidate| <= best
            {
                if |candidate| == |prefix| {
                    lis_promote_skipped_position(
                        s, prefix, start, candidate);
                    assert |candidate| <= skippedBest;
                } else {
                    assert |prefix| < |candidate|;

                    if candidate[|prefix|] == start {
                        assert |prefix| > 0;
                        lis_selected_position_is_compatible(
                            s, prefix, start, candidate);
                        assert !(s[prefix[|prefix| - 1]] < s[start]);
                        assert false;
                    } else {
                        lis_promote_skipped_position(
                            s, prefix, start, candidate);
                        assert |candidate| <= skippedBest;
                    }
                }
            }
        }
    }
}

method longest_increasing_subsequence(s: seq<int>) returns (result: int)
    requires |s| <= 0x7FFFFFFFFFFFFFFF
    ensures result >= 0
    ensures
        forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result
    ensures
        exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result
{
    var wit: seq<int>;
    result, wit := lis_search(s, [], 0);

    assert result == |wit|;
    assert result >= 0;
    assert is_valid_is(s, wit);

    forall sub: seq<int> |
        is_valid_is(s, sub) && |sub| > 0
        ensures |sub| <= result
    {
        lis_empty_prefix_extension(s, sub);
        assert |sub| <= result;
    }

    assert is_valid_is(s, wit) && |wit| == result;
    assert exists sub: seq<int> ::
        is_valid_is(s, sub) && |sub| == result;
}
