method CheckPal(s: seq<int>, i: int, len: int) returns (b: bool)
    requires is_valid_subrange(s, i, len)
    ensures b == is_palindrome(s[i .. i + len])
{
    var k := 0;
    while k < len / 2
        invariant 0 <= k <= len / 2
        invariant forall j :: 0 <= j < k ==> s[i + j] == s[i + len - 1 - j]
    {
        if s[i + k] != s[i + len - 1 - k] {
            ghost var t := s[i .. i + len];
            assert t[k] == s[i + k];
            assert t[|t| - 1 - k] == s[i + len - 1 - k];
            return false;
        }
        k := k + 1;
    }
    ghost var t := s[i .. i + len];
    forall j | 0 <= j < |t|
        ensures t[j] == t[|t| - 1 - j]
    {
        if j < len / 2 {
            assert t[j] == s[i + j];
            assert t[|t| - 1 - j] == s[i + len - 1 - j];
        } else if len - 1 - j < len / 2 {
            var j' := len - 1 - j;
            assert s[i + j'] == s[i + len - 1 - j'];
            assert t[j'] == s[i + j'];
            assert t[|t| - 1 - j'] == s[i + len - 1 - j'];
        } else {
            assert j == len - 1 - j;
        }
    }
    assert is_palindrome(t);
    return true;
}

method longest_palindromic_substring(s: seq<int>) returns (res: (int, int))
    requires
        |s| <= 1000000
    ensures
        res.0 >= 0 && res.1 >= 0
    ensures
        is_valid_subrange(s, res.0, res.1)
    ensures
        is_palindrome(s[res.0 .. res.0 + res.1])
    ensures
        forall i, len :: 
            is_valid_subrange(s, i, len) && is_palindrome(s[i .. i + len])
            ==> len <= res.1
{
    var len := |s|;
    while len > 0
        invariant 0 <= len <= |s|
        invariant forall i, l :: is_valid_subrange(s, i, l) && is_palindrome(s[i .. i + l]) ==> l <= len
        decreases len
    {
        var i := 0;
        while i + len <= |s|
            invariant 0 <= i <= |s| - len + 1
            invariant forall i' :: 0 <= i' < i ==> !is_palindrome(s[i' .. i' + len])
            decreases |s| - i
        {
            var b := CheckPal(s, i, len);
            if b {
                return (i, len);
            }
            i := i + 1;
        }
        forall i', l | is_valid_subrange(s, i', l) && is_palindrome(s[i' .. i' + l])
            ensures l <= len - 1
        {
            if l == len {
                assert i' < i;
                assert !is_palindrome(s[i' .. i' + len]);
                assert false;
            }
        }
        len := len - 1;
    }
    assert is_palindrome(s[0 .. 0]);
    return (0, 0);
}

