    ensures prev[y] == lcs_spec(s[..(i - 1)], t[..y]) && prev[y] >= 0
  {
    assert prev[y] == lcs_spec(s[..0], t[..y]);
    assert s[..(i - 1)] == s[..0];
  }

  while i <= n
    invariant 1 <= i <= n + 1
    invariant |prev| == m + 1
    invariant forall y :: 0 <= y <= m ==> prev[y] == lcs_spec(s[..(i - 1)], t[..y])
    invariant forall y :: 0 <= y <= m ==> prev[y] >= 0
    decreases n + 1 - i
  {
    var row: seq<int> := [0];
    LcsBase(s, t, i, 0);
    assert |row| == 1;
    assert row[0] == 0;
    assert lcs_spec(s[..i], t[..0]) == 0;
    assert row[0] == lcs_spec(s[..i], t[..0]);
    assert row[0] >= 0;

    var j := 1;
    while j <= m
      invariant 1 <= j <= m + 1
      invariant |row| == j
      invariant |prev| == m + 1
      invariant forall y :: 0 <= y < j ==> row[y] == lcs_spec(s[..i], t[..y])
      invariant forall y :: 0 <= y < j ==> row[y] >= 0
      invariant forall y :: 0 <= y <= m ==> prev[y] == lcs_spec(s[..(i - 1)], t[..y])
      invariant forall y :: 0 <= y <= m ==> prev[y] >= 0
      decreases m + 1 - j
    {
      assert 0 <= i - 1 < |s|;
      assert 0 <= j - 1 < |t|;
      assert 0 <= j < |prev|;
      assert 0 <= j - 1 < |row|;

      var up := prev[j];
      var left := row[j - 1];
      var diag := prev[j - 1];
      assert up == lcs_spec(s[..(i - 1)], t[..j]);
      assert left == lcs_spec(s[..i], t[..(j - 1)]);
      assert diag == lcs_spec(s[..(i - 1)], t[..(j - 1)]);
      assert up >= 0 && left >= 0 && diag >= 0;

