        val := diag + 1;
        assert val == 1 + lcs_spec(s[..(i - 1)], t[..(j - 1)]);
        assert val == lcs_spec(s[..i], t[..j]);
        assert val >= 0;
      } else {
        LcsMiss(s, t, i, j);
        val := if up > left then up else left;
        MaxDef(up, left);
        assert val == (if up > left then up else left);
        assert max(up, left) == (if up > left then up else left);
        assert val == max(up, left);
        assert max(up, left) == max(lcs_spec(s[..(i - 1)], t[..j]), lcs_spec(s[..i], t[..(j - 1)]));
        assert val == lcs_spec(s[..i], t[..j]);
        if up > left {
          assert val == up;
          assert val >= 0;
        } else {
          assert val == left;
          assert val >= 0;
        }
      }

      var newRow := row + [val];
      RowExtend(row, val, s, t, i, j);
      assert newRow == row + [val];
      assert |newRow| == j + 1;
      assert forall y :: 0 <= y < j + 1 ==> newRow[y] == lcs_spec(s[..i], t[..y]);
      assert forall y :: 0 <= y < j + 1 ==> newRow[y] >= 0;
      row := newRow;
      assert row == newRow;
      assert |row| == j + 1;
      assert forall y :: 0 <= y < j + 1 ==> row[y] == lcs_spec(s[..i], t[..y]);
      assert forall y :: 0 <= y < j + 1 ==> row[y] >= 0;
      j := j + 1;
    }

    assert j == m + 1;
    forall y | 0 <= y <= m
      ensures row[y] == lcs_spec(s[..i], t[..y]) && row[y] >= 0
    {
      assert 0 <= y < j;
    }
    prev := row;
    assert |prev| == m + 1;
    assert s[..i] == s[..((i + 1) - 1)];
    forall y | 0 <= y <= m
      ensures prev[y] == lcs_spec(s[..((i + 1) - 1)], t[..y]) && prev[y] >= 0
    {
      assert prev[y] == row[y];
      assert row[y] == lcs_spec(s[..i], t[..y]);
      assert row[y] >= 0;
    }
    i := i + 1;
  }

  assert i == n + 1;
  FullPrefix(s);
  FullPrefix(t);
  assert s[..n] == s;
  assert t[..m] == t;
  assert s[..(i - 1)] == s[..n];
  len := prev[m];
  assert len == lcs_spec(s[..(i - 1)], t[..m]);
  assert lcs_spec(s[..(i - 1)], t[..m]) == lcs_spec(s[..n], t[..m]);
  assert lcs_spec(s[..n], t[..m]) == lcs_spec(s, t);
  assert len == lcs_spec(s, t);
  assert len >= 0;
}
