lemma bounds_monotone(
    s: seq<int>,
    cutoff: int,
    oldBound: int,
    newBound: int)
    requires oldBound <= newBound
    requires forall i, len {:trigger pal_range(s, i, len)} ::
        pal_range(s, i, len) && len < cutoff
        ==> len <= oldBound
    ensures forall i, len {:trigger pal_range(s, i, len)} ::
        pal_range(s, i, len) && len < cutoff
        ==> len <= newBound
{
    forall i, len {:trigger pal_range(s, i, len)} |
        pal_range(s, i, len) && len < cutoff
        ensures len <= newBound
    {
        assert len <= oldBound;
        assert oldBound <= newBound;
    }
}

