method palindrome_check(t: seq<int>) returns (ok: bool)
    ensures ok <==> is_palindrome(t)
{
    var i := 0;

    while i < |t|
        invariant 0 <= i <= |t|
        invariant forall k {:trigger t[k]} ::
            0 <= k < i
            ==> t[k] == t[|t| - 1 - k]
        decreases |t| - i
    {
        if t[i] != t[|t| - 1 - i] {
            ok := false;

            assert !is_palindrome(t) by {
                if is_palindrome(t) {
                    assert t[i] == t[|t| - 1 - i];
                    assert false;
                }
            }
            return;
        }

        i := i + 1;
    }

    assert is_palindrome(t) by {
        forall k {:trigger t[k]} | 0 <= k < |t|
            ensures t[k] == t[|t| - 1 - k]
        {
            assert k < i;
        }
    }

    ok := true;
}

