  requires 0 <= i <= |adj[u]|
  ensures is_matching(adj, m) && |m| == bestFrom(adj, u, used, i)
  ensures forall e: (int, int) :: e in m ==> u <= e.0 && e.1 !in used
  decreases |adj| - u, 0, |adj[u]| - i
{
  if i == |adj[u]| {
    m := {};
  } else {
    var v := adj[u][i];
    var rest := bestFrom(adj, u, used, i + 1);
    if v in used {
      m := BestFromWitness(adj, u, used, i + 1);
    } else if 1 + best(adj, u + 1, used + {v}) >= rest {
      var m2 := BestWitness(adj, u + 1, used + {v});
      assert (u, v) !in m2;
      m := m2 + {(u, v)};
      assert |m| == |m2| + 1;
      forall edge | edge in m
        ensures exists k: int :: 0 <= edge.0 < |adj| && 0 <= k < |adj[edge.0]| && adj[edge.0][k] == edge.1
