function mbm_max(a: nat, b: nat): nat {
    if a >= b then a else b
}

function mbm_search(
    adj: seq<seq<int>>,
    u: int,
    i: int,
    used: set<int>
): nat
    requires 0 <= u <= |adj|
    requires u < |adj| ==> 0 <= i <= |adj[u]|
    decreases |adj| - u,
              if u < |adj| then |adj[u]| - i else 0
{
    if u == |adj| then
        0
    else if i == |adj[u]| then
        mbm_search(adj, u + 1, 0, used)
    else
        var skipped := mbm_search(adj, u, i + 1, used);
        var v := adj[u][i];
        if v in used then
            skipped
        else
            mbm_max(
                skipped,
                1 + mbm_search(adj, u + 1, 0, used + {v})
            )
}

ghost predicate mbm_admissible(
    adj: seq<seq<int>>,
    u: int,
    i: int,
    used: set<int>,
    m: Matching
)
    requires 0 <= u <= |adj|
    requires u < |adj| ==> 0 <= i <= |adj[u]|
{
    is_matching(adj, m)
    &&
    (forall e: (int, int) :: e in m ==> u <= e.0)
    &&
    (forall e: (int, int) :: e in m ==> e.1 !in used)
    &&
    (forall e: (int, int) ::
        e in m && e.0 == u ==>
            u < |adj|
            &&
            (exists j: int ::
                i <= j < |adj[u]|
                && adj[u][j] == e.1))
