    requires is_matching(adj, larger)
    ensures is_matching(adj, smaller)
{
    assert matching_valid_edges(adj, smaller) by {
        forall e: (int, int) | e in smaller
            ensures exists j: int ::
                0 <= e.0 < |adj|
                && 0 <= j < |adj[e.0]|
                && adj[e.0][j] == e.1
        {
            assert e in larger;
