        assert e != front;
        assert u <= e.0;

        if e.0 == u {
            assert is_disjoint(m);
            assert e.0 != front.0 && e.1 != front.1;
            assert e.0 != front.0;
            assert false;
        }
    }

    forall e: (int, int) | e in rest
        ensures e.1 !in used + {v}
    {
        assert e in m;
        assert e.1 !in used;
        assert e != front;

        if e.1 == v {
            assert is_disjoint(m);
            assert e.0 != front.0 && e.1 != front.1;
            assert e.1 != front.1;
            assert false;
        }
    }

