        ensures e.1 !in used + {v}
    {
        assert e in m;
        assert e.1 !in used;
        assert e != front;

        if e.1 == v {
            assert is_disjoint(m);
            assert e.0 != front.0 && e.1 != front.1;
            assert e.1 != front.1;
            assert false;
        }
    }

    forall e: (int, int) | e in rest && e.0 == u + 1
        ensures exists j: int ::
            0 <= j < |adj[u + 1]|
            && adj[u + 1][j] == e.1
    {
        assert e in m;
        assert matching_valid_edges(adj, m);
        var j :| 0 <= e.0 < |adj|
                   && 0 <= j < |adj[e.0]|
                   && adj[e.0][j] == e.1;
        assert e.0 == u + 1;
    }

    assert mbm_admissible(
        adj, u + 1, 0, used + {v}, rest
    );

    assert m == rest + {front} by {
        forall e: (int, int)
            ensures e in m <==> e in rest + {front}
        {
            if e in m {
                if e != front {
                    assert e in rest;
                }
            } else {
                assert e !in rest;
                assert e != front;
            }
        }
    }

    assert front !in rest;
    assert |m| == |rest| + 1;
}

lemma mbm_search_witness(
    adj: seq<seq<int>>,
    u: int,
    i: int,
    used: set<int>
)
    requires 0 <= u <= |adj|
    requires u < |adj| ==> 0 <= i <= |adj[u]|
    ensures exists m: Matching ::
        mbm_admissible(adj, u, i, used, m)
        && |m| == mbm_search(adj, u, i, used)
    decreases |adj| - u,
              if u < |adj| then |adj[u]| - i else 0
{
    if u == |adj| {
        ghost var empty: Matching := {};
        assert matching_valid_edges(adj, empty);
        assert is_disjoint(empty);
        assert is_matching(adj, empty);
        assert mbm_admissible(adj, u, i, used, empty);
        assert |empty| == mbm_search(adj, u, i, used);
    } else if i == |adj[u]| {
        mbm_search_witness(adj, u + 1, 0, used);
        var m :| mbm_admissible(adj, u + 1, 0, used, m)
                    && |m| == mbm_search(adj, u + 1, 0, used);

        mbm_end_row_from_next(adj, u, used, m);
        assert mbm_search(adj, u, i, used)
            == mbm_search(adj, u + 1, 0, used);
    } else {
        mbm_search_witness(adj, u, i + 1, used);
        var skipped :| mbm_admissible(
                            adj, u, i + 1, used, skipped
                        )
                        && |skipped|
                            == mbm_search(adj, u, i + 1, used);
        mbm_weaken_suffix(adj, u, i, used, skipped);

        var v := adj[u][i];
        if v in used {
            assert mbm_search(adj, u, i, used)
                == mbm_search(adj, u, i + 1, used);
        } else {
            mbm_search_witness(
                adj, u + 1, 0, used + {v}
            );
            var takenRest :| mbm_admissible(
                                adj, u + 1, 0,
                                used + {v}, takenRest
                            )
                            && |takenRest|
                                == mbm_search(
                                    adj, u + 1, 0, used + {v}
                                );

            mbm_add_front(adj, u, i, used, takenRest);
            var taken := takenRest + {(u, v)};

            assert mbm_admissible(adj, u, i, used, taken);
            assert |taken|
                == 1 + mbm_search(
                    adj, u + 1, 0, used + {v}
                );

            if mbm_search(adj, u, i + 1, used)
                >= 1 + mbm_search(
                    adj, u + 1, 0, used + {v}
                )
            {
                assert mbm_search(adj, u, i, used)
                    == mbm_search(adj, u, i + 1, used);
            } else {
                assert mbm_search(adj, u, i, used)
                    == 1 + mbm_search(
                        adj, u + 1, 0, used + {v}
                    );
            }
        }
    }
}

lemma mbm_search_bound(
    adj: seq<seq<int>>,
    u: int,
    i: int,
    used: set<int>,
    m: Matching
)
    requires 0 <= u <= |adj|
    requires u < |adj| ==> 0 <= i <= |adj[u]|
    requires mbm_admissible(adj, u, i, used, m)
    ensures |m| <= mbm_search(adj, u, i, used)
    decreases |adj| - u,
              if u < |adj| then |adj[u]| - i else 0
{
    if u == |adj| {
        assert m == {} by {
            forall e: (int, int)
                ensures e in m <==> e in {}
            {
                if e in m {
                    assert matching_valid_edges(adj, m);
                    var j :| 0 <= e.0 < |adj|
                               && 0 <= j < |adj[e.0]|
                               && adj[e.0][j] == e.1;
                    assert u <= e.0;
                    assert u == |adj|;
                    assert false;
                }
            }
        }
        assert |m| == 0;
    } else if i == |adj[u]| {
        mbm_end_row_to_next(adj, u, used, m);
        mbm_search_bound(adj, u + 1, 0, used, m);
        assert mbm_search(adj, u, i, used)
            == mbm_search(adj, u + 1, 0, used);
    } else {
        var v := adj[u][i];
        var front := (u, v);

        if front in m {
            assert v !in used;
            mbm_remove_front(adj, u, i, used, m);
            var rest := m - {front};

            mbm_search_bound(
                adj, u + 1, 0, used + {v}, rest
            );

            assert |m| == |rest| + 1;
            assert |rest|
                <= mbm_search(
                    adj, u + 1, 0, used + {v}
                );
            assert |m|
                <= 1 + mbm_search(
                    adj, u + 1, 0, used + {v}
                );
            assert 1 + mbm_search(
                        adj, u + 1, 0, used + {v}
                   )
                <= mbm_max(
                    mbm_search(adj, u, i + 1, used),
                    1 + mbm_search(
                        adj, u + 1, 0, used + {v}
                    )
                );
        } else {
            mbm_advance_suffix(adj, u, i, used, m);
            mbm_search_bound(adj, u, i + 1, used, m);
            assert |m| <= mbm_search(adj, u, i + 1, used);

            if v in used {
                assert mbm_search(adj, u, i, used)
                    == mbm_search(adj, u, i + 1, used);
            } else {
                assert mbm_search(adj, u, i + 1, used)
                    <= mbm_max(
                        mbm_search(adj, u, i + 1, used),
                        1 + mbm_search(
                            adj, u + 1, 0, used + {v}
                        )
                    );
            }
        }
    }
}

