method max_bipartite_matching(graph: BipartiteGraph) returns (size: int)
    requires well_formed(graph)
    requires size_bounded(graph)
    ensures size >= 0
    ensures exists m: Matching ::
            is_max_matching(graph.adj, m)
            && |m| == size
{
    size := mbm_search(graph.adj, 0, 0, {});

    mbm_search_witness(graph.adj, 0, 0, {});
    ghost var best :| mbm_admissible(
                            graph.adj, 0, 0, {}, best
                        )
                        && |best|
                            == mbm_search(graph.adj, 0, 0, {});

    assert is_matching(graph.adj, best);

    assert forall other: Matching ::
        is_matching(graph.adj, other) ==> |best| >= |other|
    by {
        forall other: Matching | is_matching(graph.adj, other)
            ensures |best| >= |other|
        {
            mbm_initial_admissible(graph.adj, other);
            mbm_search_bound(graph.adj, 0, 0, {}, other);
            assert |other|
                <= mbm_search(graph.adj, 0, 0, {});
            assert |best|
                == mbm_search(graph.adj, 0, 0, {});
        }
    }

    assert is_max_matching(graph.adj, best);
    assert |best| == size;
}
