  x: seq<int>,
  k: int)
  requires 0 <= k
  requires |r1| == |r2|
  requires k < |r1| && k < |x|
  requires BitsOK(r1, r2, x, k)
  requires spec_dot_product_gf2(XorRow(r1, r2), x, k - 1) ==
