    BstBounds(n);
    if m.left.Some? {
        assert m.left.value.is_bst();
        assert forall y :: y in m.left.value.view() ==> y < m.val;
    }
    if m.right.Some? {
        assert m.right.value.is_bst();
        assert forall y :: y in m.right.value.view() ==> y > m.val;
    }
    ProveBstFromBounds(m);
}

