method {:vcs_split_on_every_assert} FlipColors(h: Node) returns (res: Node)
    requires h.left.Some? && h.right.Some?
    requires h.left.value.is_red && h.right.value.is_red
    requires h.left.value.is_llrbt() && h.right.value.is_llrbt()
    requires h.is_bst()
    requires h.left.value.black_height() == h.right.value.black_height()
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures !IsRedOpt(res.left) && !IsRedOpt(res.right)
    ensures res.is_red == !h.is_red
    ensures res.black_height() == h.left.value.black_height() + (if h.is_red then 2 else 1)
{
    var l := h.left.value;
    var r := h.right.value;
    var l2 := Node(l.val, false, l.left, l.right);
    var r2 := Node(r.val, false, r.left, r.right);
    res := Node(h.val, !h.is_red, Some(l2), Some(r2));

    LLRBTParts(l);
    LLRBTParts(r);
    TransferBst(l, l2);
    TransferBst(r, r2);
