lemma LLRBTParts(n: Node)
    requires n.is_llrbt()
    ensures n.is_bst()
    ensures n.satisfies_red_props()
    ensures n.black_height() != -1
    ensures BhOpt(n.left) == BhOpt(n.right)
    ensures BhOpt(n.left) != -1
    ensures n.black_height() == BhOpt(n.left) + (if n.is_red then 0 else 1)
    ensures n.black_height() == BhAfter(BhOpt(n.left), n.is_red, false)
    ensures !IsRedOpt(n.right)
    ensures !(n.left.Some? && n.left.value.is_red && IsRedOpt(n.left.value.left))
    ensures n.left.Some? ==> n.left.value.is_llrbt()
    ensures n.right.Some? ==> n.right.value.is_llrbt()
    ensures n.left.Some? ==> !RootDoubleRed(n.left.value)
    ensures n.right.Some? ==> !n.right.value.is_red
    ensures n.val in n.view()
    ensures is_llrbt_opt(n.left)
    ensures is_llrbt_opt(n.right)
{
    LLRBTDef(n);
    assert n.is_bst();
    assert n.satisfies_red_props();
    assert n.black_height() != -1;
    BhValid(n);
    BhAfterFalse(BhOpt(n.left), n.is_red);
    assert n.black_height() == BhAfter(BhOpt(n.left), n.is_red, false);
    RedParts(n);
    RightBlackExpr(n);
    // RightBlackExpr is the inverse direction; derive !IsRedOpt from the match.
    match n.right {
        case None =>
            assert !IsRedOpt(n.right);
        case Some(r) =>
            assert !r.is_red;
            IsRedOptDef(n.right);
            assert !IsRedOpt(n.right);
    }
    match n.left {
        case None =>
            assert !(n.left.Some? && n.left.value.is_red && IsRedOpt(n.left.value.left));
        case Some(l) =>
            if l.is_red {
                assert match l.left { case Some(ll) => !ll.is_red case None => true };
                match l.left {
                    case None =>
                        IsRedOptDef(l.left);
                        assert !IsRedOpt(l.left);
                    case Some(ll) =>
                        assert !ll.is_red;
                        IsRedOptDef(l.left);
                        assert !IsRedOpt(l.left);
                }
                assert !IsRedOpt(l.left);
                assert !RootDoubleRed(l);
            } else {
                assert !RootDoubleRed(l);
            }
            assert !(l.is_red && IsRedOpt(l.left));
    }
    BstBounds(n);
    if n.left.Some? {
        var l := n.left.value;
        assert l.is_bst();
        RedParts(n);
        assert l.satisfies_red_props();
        assert BhOpt(n.left) == l.black_height();
        assert l.black_height() != -1;
        ProveLLRBT(l);
        LLRBTOptDef(n.left);
        assert !RootDoubleRed(l);
    } else {
        LLRBTOptDef(n.left);
    }
    if n.right.Some? {
        var r := n.right.value;
        assert r.is_bst();
        assert r.satisfies_red_props();
        assert r.black_height() != -1;
        ProveLLRBT(r);
        LLRBTOptDef(n.right);
        assert !r.is_red;
    } else {
        LLRBTOptDef(n.right);
    }
    ViewDef(n);
}

