lemma PlusLeftView(h: Node, h2: Node, newL: Node, v: int)
    requires h2.val == h.val && h2.left == Some(newL) && h2.right == h.right
    requires newL.view() == view_opt(h.left) + {v}
    ensures h2.view() == h.view() + {v}
{
    ViewDef(h);
    ViewDef(h2);
    ViewOptDef(h2.left);
    assert h2.view() == newL.view() + view_opt(h.right) + {h.val};
    calc {
        h2.view();
        (view_opt(h.left) + {v}) + view_opt(h.right) + {h.val};
        view_opt(h.left) + view_opt(h.right) + {h.val} + {v};
        h.view() + {v};
    }
}

lemma PlusRightView(h: Node, h2: Node, newR: Node, v: int)
