ghost predicate LowerZeros(
  aug: seq<seq<int>>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  forall r {:trigger aug[r]} ::
    0 <= r < |aug| && numPivots <= r < rows ==>
      forall j {:trigger aug[r][j]} ::
        0 <= j < col && j < |aug[r]| ==>
          aug[r][j] == 0
}

ghost predicate ClearedBefore(aug: seq<seq<int>>, pivotRow: int, c: int, upto: int)
{
  forall t {:trigger aug[t][c]} ::
    0 <= t < upto && t < |aug| && 0 <= c < |aug[t]| && t != pivotRow ==>
      aug[t][c] == 0
}

ghost predicate RREFState(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  AugOK(aug, rows, nCols) &&
  PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols) &&
  UnitPivots(aug, pivotCol, numPivots, col, rows, nCols) &&
  LowerZeros(aug, numPivots, col, rows, nCols)
}

ghost predicate SolvesAug(aug: seq<seq<int>>, x: seq<int>, nCols: int) {
  |x| == nCols &&
  is_binary_vector(x) &&
  (forall i :: 0 <= i < |aug| ==>
    |aug[i]| == nCols + 1 &&
    spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols])
}

ghost predicate {:opaque} SameSol(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  nCols: int)
{
  forall x {:trigger is_solution(matrix, b, x)} {:trigger SolvesAug(aug, x, nCols)} ::
    |x| == nCols && is_binary_vector(x) ==>
      (is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols))
}

function BuildAug(matrix: seq<seq<int>>, b: seq<int>): seq<seq<int>>
  requires |matrix| == |b|
{
  seq(|matrix|, i requires 0 <= i < |matrix| => matrix[i] + [b[i]])
}

function XorRow(a: seq<int>, b: seq<int>): seq<int>
  requires |a| == |b|
{
  seq(|a|, i requires 0 <= i < |a| => (a[i] + b[i]) % 2)
}

function AddRowTo(m: seq<seq<int>>, dst: int, src: int): seq<seq<int>>
  requires 0 <= dst < |m| && 0 <= src < |m|
  requires |m[dst]| == |m[src]|
{
  m[dst := XorRow(m[dst], m[src])]
}

function SwapRows(m: seq<seq<int>>, r1: int, r2: int): seq<seq<int>>
  requires 0 <= r1 < |m| && 0 <= r2 < |m|
{
  if r1 == r2 then m else (m[r1 := m[r2]])[r2 := m[r1]]
}

function XFrom(aug: seq<seq<int>>, rowOfCol: seq<int>, nCols: int): seq<int>
  requires |rowOfCol| == nCols
  requires nCols >= 1
  requires forall j :: 0 <= j < nCols ==>
    rowOfCol[j] == -1 || (0 <= rowOfCol[j] < |aug| && nCols < |aug[rowOfCol[j]]|)
{
  seq(nCols, j requires 0 <= j < nCols =>
    if rowOfCol[j] == -1 then 0 else aug[rowOfCol[j]][nCols])
}

lemma TwoTimesNotOne(k: int)
  ensures 2 * k != 1
{
  if k <= 0 {
    assert 2 * k <= 0;
  } else {
    assert k >= 1;
    assert 2 * k >= 2;
  }
}

lemma TwoTimesNotNegOne(k: int)
  ensures 2 * k != -1
{
  if k >= 0 {
    assert 2 * k >= 0;
  } else {
    assert k <= -1;
    assert 2 * k <= -2;
  }
}

lemma DivModUnique2(n: int, q: int, r: int)
  requires n == 2 * q + r
  requires 0 <= r < 2
  ensures n % 2 == r
  ensures n / 2 == q
{
  var q0 := n / 2;
  var r0 := n % 2;
  assert n == 2 * q0 + r0;
  assert 0 <= r0 < 2;
  if r != r0 {
    var diffR := r0 - r;
    assert -1 <= diffR <= 1;
    assert diffR != 0;
    assert diffR == -1 || diffR == 1;
    if diffR == 1 {
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == -1;
      assert 2 * (q - q0) == -1;
      TwoTimesNotNegOne(q - q0);
      assert false;
    } else {
      assert diffR == -1;
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == 1;
      assert 2 * (q - q0) == 1;
      TwoTimesNotOne(q - q0);
      assert false;
    }
  }
  assert r == r0;
  assert 2 * q + r == 2 * q0 + r0;
  assert 2 * (q - q0) == 0;
  if q != q0 {
    var m := q - q0;
    assert 2 * m == 0;
    if m > 0 {
      assert m >= 1;
      assert 2 * m >= 2;
      assert false;
    } else {
      assert m <= -1;
      assert 2 * m <= -2;
      assert false;
    }
  }
}

lemma XorPairToSum(a: int, b: int, c: int, d: int)
  requires IsBit(a) && IsBit(b) && IsBit(c) && IsBit(d)
  ensures ((a + b) % 2 + (c + d) % 2) % 2 == (a + b + c + d) % 2
{
  var ab := (a + b) % 2;
  var cd := (c + d) % 2;
  var s := a + b + c + d;
  assert a + b == 2 * ((a + b) / 2) + ab;
  assert c + d == 2 * ((c + d) / 2) + cd;
  assert 0 <= ab < 2;
  assert 0 <= cd < 2;
  assert ab <= 1 && cd <= 1;
  var q1 := (a + b) / 2 + (c + d) / 2;
  var r1 := ab + cd;
  assert s == 2 * q1 + r1;
  assert 0 <= r1 <= 2;
  if r1 < 2 {
    DivModUnique2(s, q1, r1);
    assert s % 2 == r1;
    if r1 == 0 {
      assert (0) % 2 == 0;
    } else {
      assert r1 == 1;
      assert (1) % 2 == 1;
    }
    assert (ab + cd) % 2 == s % 2;
  } else {
    assert r1 == 2;
    assert s == 2 * (q1 + 1) + 0;
    DivModUnique2(s, q1 + 1, 0);
    assert s % 2 == 0;
    assert (2) % 2 == 0;
    assert (ab + cd) % 2 == 0;
  }
}

lemma XorFourRearrange(a: int, b: int, c: int, d: int)
  requires IsBit(a) && IsBit(b) && IsBit(c) && IsBit(d)
  ensures add_gf2(add_gf2(a, b), add_gf2(c, d)) == add_gf2(add_gf2(a, c), add_gf2(b, d))
{
  XorPairToSum(a, b, c, d);
  XorPairToSum(a, c, b, d);
  var left := ((a + b) % 2 + (c + d) % 2) % 2;
  var right := ((a + c) % 2 + (b + d) % 2) % 2;
  assert left == (a + b + c + d) % 2;
  assert right == (a + c + b + d) % 2;
  assert a + b + c + d == a + c + b + d;
  assert left == right;
  var ab := add_gf2(a, b);
  var cd := add_gf2(c, d);
  var ac := add_gf2(a, c);
  var bd := add_gf2(b, d);
  assert ab == (a + b) % 2;
  assert cd == (c + d) % 2;
  assert ac == (a + c) % 2;
  assert bd == (b + d) % 2;
  assert add_gf2(ab, cd) == (ab + cd) % 2;
  assert ab + cd == (a + b) % 2 + (c + d) % 2;
  assert add_gf2(ab, cd) == left;
  assert add_gf2(ac, bd) == (ac + bd) % 2;
  assert ac + bd == (a + c) % 2 + (b + d) % 2;
  assert add_gf2(ac, bd) == right;
  assert add_gf2(add_gf2(a, b), add_gf2(c, d)) == add_gf2(ab, cd);
  assert add_gf2(add_gf2(a, c), add_gf2(b, d)) == add_gf2(ac, bd);
}

lemma BitMod2(a: int)
  requires IsBit(a)
  ensures a % 2 == a
{
  if a == 0 {
    assert (0) % 2 == 0;
  } else {
    assert a == 1;
    assert (1) % 2 == 1;
  }
}

lemma AddIsBit(a: int, b: int)
  requires IsBit(a) && IsBit(b)
  ensures IsBit(add_gf2(a, b))
  ensures add_gf2(a, b) == (if a == b then 0 else 1)
{
  if a == 0 && b == 0 {
    assert (0 + 0) % 2 == 0;
    assert add_gf2(0, 0) == 0;
  } else if a == 0 && b == 1 {
    assert (0 + 1) % 2 == 1;
    assert add_gf2(0, 1) == 1;
  } else if a == 1 && b == 0 {
    assert (1 + 0) % 2 == 1;
    assert add_gf2(1, 0) == 1;
  } else {
    assert a == 1 && b == 1;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(1, 1) == 0;
  }
}

lemma AddZero(a: int)
  requires IsBit(a)
  ensures add_gf2(0, a) == a
  ensures add_gf2(a, 0) == a
{
  BitMod2(a);
  assert (0 + a) % 2 == a % 2;
  assert (a + 0) % 2 == a % 2;
  assert add_gf2(0, a) == (0 + a) % 2;
  assert add_gf2(a, 0) == (a + 0) % 2;
}

lemma MulIsBit(a: int, b: int)
  requires IsBit(a) && IsBit(b)
  ensures IsBit(mul_gf2(a, b))
  ensures mul_gf2(a, b) == a * b
{
  if a == 0 || b == 0 {
    assert a * b == 0;
    assert (0) % 2 == 0;
    assert mul_gf2(a, b) == (a * b) % 2;
  } else {
    assert a == 1 && b == 1;
    assert a * b == 1;
    assert (1) % 2 == 1;
    assert mul_gf2(a, b) == (a * b) % 2;
  }
}

lemma MulZero(a: int)
  ensures mul_gf2(0, a) == 0
  ensures mul_gf2(a, 0) == 0
{
  assert 0 * a == 0;
  assert a * 0 == 0;
  assert (0) % 2 == 0;
  assert mul_gf2(0, a) == (0 * a) % 2;
  assert mul_gf2(a, 0) == (a * 0) % 2;
}

lemma MulOne(a: int)
  requires IsBit(a)
  ensures mul_gf2(1, a) == a
  ensures mul_gf2(a, 1) == a
{
  BitMod2(a);
  assert 1 * a == a;
  assert a * 1 == a;
  assert (1 * a) % 2 == a % 2;
  assert (a * 1) % 2 == a % 2;
  assert mul_gf2(1, a) == (1 * a) % 2;
  assert mul_gf2(a, 1) == (a * 1) % 2;
}

lemma XorCancel(a: int, s: int)
  requires IsBit(a) && IsBit(s)
  ensures add_gf2(add_gf2(a, s), s) == a
{
  if a == 0 && s == 0 {
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
    assert add_gf2(0, 0) == 0;
    assert add_gf2(add_gf2(0, 0), 0) == add_gf2(0, 0);
  } else if a == 0 && s == 1 {
    assert add_gf2(0, 1) == (0 + 1) % 2;
    assert (0 + 1) % 2 == 1;
    assert add_gf2(1, 1) == (1 + 1) % 2;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(add_gf2(0, 1), 1) == add_gf2(1, 1);
    assert add_gf2(1, 1) == 0;
  } else if a == 1 && s == 0 {
    assert add_gf2(1, 0) == (1 + 0) % 2;
    assert (1 + 0) % 2 == 1;
    assert add_gf2(add_gf2(1, 0), 0) == add_gf2(1, 0);
    assert add_gf2(1, 0) == 1;
  } else {
    assert a == 1 && s == 1;
    assert add_gf2(1, 1) == (1 + 1) % 2;
    assert (1 + 1) % 2 == 0;
    assert add_gf2(0, 1) == (0 + 1) % 2;
    assert (0 + 1) % 2 == 1;
    assert add_gf2(add_gf2(1, 1), 1) == add_gf2(0, 1);
    assert add_gf2(0, 1) == 1;
  }
}

lemma DistrBit(a: int, b: int, x: int)
  requires IsBit(a) && IsBit(b) && IsBit(x)
  ensures mul_gf2(add_gf2(a, b), x) == add_gf2(mul_gf2(a, x), mul_gf2(b, x))
{
  AddIsBit(a, b);
  var s := add_gf2(a, b);
  assert IsBit(s);
  if x == 0 {
    MulZero(s);
    MulZero(a);
    MulZero(b);
    assert mul_gf2(s, 0) == 0;
    assert mul_gf2(a, 0) == 0;
    assert mul_gf2(b, 0) == 0;
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
    assert add_gf2(mul_gf2(a, 0), mul_gf2(b, 0)) == 0;
  } else {
    assert x == 1;
    MulOne(s);
    MulOne(a);
    MulOne(b);
    assert mul_gf2(s, 1) == s;
    assert mul_gf2(a, 1) == a;
    assert mul_gf2(b, 1) == b;
    assert add_gf2(a, b) == s;
    assert add_gf2(mul_gf2(a, 1), mul_gf2(b, 1)) == add_gf2(a, b);
  }
}

ghost predicate RowsAgree(r1: seq<int>, r2: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
{
  if k < 0 then
    true
  else
    (k < |x| ==> k < |r1| && k < |r2| && r1[k] == r2[k]) &&
    RowsAgree(r1, r2, x, k - 1)
}

lemma {:fuel RowsAgree, 2} RowAgreeStep(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  requires 0 <= k
  requires RowsAgree(r1, r2, x, k - 1)
  requires k < |x| ==> k < |r1| && k < |r2| && r1[k] == r2[k]
  ensures RowsAgree(r1, r2, x, k)
{
  assert RowsAgree(r1, r2, x, k) ==
    ((k < |x| ==> k < |r1| && k < |r2| && r1[k] == r2[k]) &&
     RowsAgree(r1, r2, x, k - 1));
  assert RowsAgree(r1, r2, x, k);
}

lemma {:vcs_split_on_every_assert} {:fuel RowsAgree, 2} RowsAgreeDot(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  decreases if k < 0 then 0 else k + 1
  requires RowsAgree(r1, r2, x, k)
  ensures spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r2, x, k)
{
  if k < 0 {
    assert spec_dot_product_gf2(r1, x, k) == 0;
    assert spec_dot_product_gf2(r2, x, k) == 0;
  } else {
    assert RowsAgree(r1, r2, x, k) ==
      ((k < |x| ==> k < |r1| && k < |r2| && r1[k] == r2[k]) &&
       RowsAgree(r1, r2, x, k - 1));
    assert RowsAgree(r1, r2, x, k - 1);
    RowsAgreeDot(r1, r2, x, k - 1);
    if k < |x| {
      assert k < |r1| && k < |r2| && r1[k] == r2[k];
      assert spec_dot_product_gf2(r1, x, k) ==
        add_gf2(mul_gf2(r1[k], x[k]), spec_dot_product_gf2(r1, x, k - 1));
      assert spec_dot_product_gf2(r2, x, k) ==
        add_gf2(mul_gf2(r2[k], x[k]), spec_dot_product_gf2(r2, x, k - 1));
      assert mul_gf2(r1[k], x[k]) == mul_gf2(r2[k], x[k]);
    } else {
      assert spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r1, x, k - 1);
      assert spec_dot_product_gf2(r2, x, k) == spec_dot_product_gf2(r2, x, k - 1);
    }
  }
}

lemma {:fuel RowsAgree, 2} DotProductDependsOnPrefix(r1: seq<int>, r2: seq<int>, x: seq<int>, k: int)
  requires forall j {:trigger Id(j)} ::
    0 <= j <= k && j < |x| ==> j < |r1| && j < |r2| && r1[j] == r2[j]
  ensures spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r2, x, k)
{
  if k < 0 {
    assert spec_dot_product_gf2(r1, x, k) == 0;
    assert spec_dot_product_gf2(r2, x, k) == 0;
  } else {
    var i := -1;
    assert RowsAgree(r1, r2, x, -1);
    assert i == -1;
    assert RowsAgree(r1, r2, x, i);
    while i < k
      invariant -1 <= i <= k
      invariant RowsAgree(r1, r2, x, i)
      decreases k - i
    {
      var next := i + 1;
      assert -1 <= i < k;
      assert 0 <= next <= k;
      assert next < |x| ==> next < |r1| && next < |r2| && r1[next] == r2[next]
      by {
        if next < |x| {
          assert Id(next) == next;
          assert 0 <= next <= k && next < |x|;
          assert next < |r1| && next < |r2|;
          assert r1[next] == r2[next];
        }
      };
      assert next - 1 == i;
      assert RowsAgree(r1, r2, x, next - 1);
      RowAgreeStep(r1, r2, x, next);
      i := next;
    }
    assert i == k;
    assert RowsAgree(r1, r2, x, k);
    RowsAgreeDot(r1, r2, x, k);
  }
}

lemma DotIsBit(row: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  ensures IsBit(spec_dot_product_gf2(row, x, k))
{
  if k < 0 {
    assert spec_dot_product_gf2(row, x, k) == 0;
  } else {
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    DotIsBit(row, x, k - 1);
    if k < |row| && k < |x| {
      assert IsBit(row[k]) && IsBit(x[k]);
      MulIsBit(row[k], x[k]);
      var prod := mul_gf2(row[k], x[k]);
      var rest := spec_dot_product_gf2(row, x, k - 1);
      assert IsBit(prod) && IsBit(rest);
      AddIsBit(prod, rest);
      assert spec_dot_product_gf2(row, x, k) == add_gf2(prod, rest);
      assert IsBit(add_gf2(prod, rest));
    } else {
      assert spec_dot_product_gf2(row, x, k) == spec_dot_product_gf2(row, x, k - 1);
    }
  }
}

lemma ZeroDot(row: seq<int>, x: seq<int>, k: int)
  decreases if k < 0 then 0 else k + 1
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  ensures spec_dot_product_gf2(row, x, k) == 0
{
  if k < 0 {
    assert spec_dot_product_gf2(row, x, k) == 0;
  } else {
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0;
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    ZeroDot(row, x, k - 1);
    if k < |row| && k < |x| {
      assert row[k] == 0 || x[k] == 0;
      if row[k] == 0 {
        MulZero(x[k]);
        assert mul_gf2(row[k], x[k]) == mul_gf2(0, x[k]);
        assert mul_gf2(0, x[k]) == 0;
      } else {
        assert x[k] == 0;
        MulZero(row[k]);
        assert mul_gf2(row[k], x[k]) == mul_gf2(row[k], 0);
        assert mul_gf2(row[k], 0) == 0;
      }
      assert mul_gf2(row[k], x[k]) == 0;
      assert spec_dot_product_gf2(row, x, k - 1) == 0;
      assert add_gf2(0, 0) == (0 + 0) % 2;
      assert (0 + 0) % 2 == 0;
      assert spec_dot_product_gf2(row, x, k) ==
        add_gf2(mul_gf2(row[k], x[k]), spec_dot_product_gf2(row, x, k - 1));
      assert spec_dot_product_gf2(row, x, k) == add_gf2(0, 0);
    } else {
      assert spec_dot_product_gf2(row, x, k) == spec_dot_product_gf2(row, x, k - 1);
    }
  }
}

lemma DotProductSingle(row: seq<int>, x: seq<int>, k: int, p: int)
  decreases if k < 0 then 0 else k + 1
  requires 0 <= p <= k
  requires p < |row| && p < |x|
  requires k < |row| && k < |x|
  requires row[p] == 1
  requires IsBit(x[p])
  requires forall j :: 0 <= j <= k && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j])
  requires forall j :: 0 <= j <= k && j != p && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0
  ensures spec_dot_product_gf2(row, x, k) == x[p]
{
  if k == p {
    if k == 0 {
      assert spec_dot_product_gf2(row, x, -1) == 0;
      assert row[0] == 1;
      MulOne(x[0]);
      assert mul_gf2(row[0], x[0]) == mul_gf2(1, x[0]);
      assert mul_gf2(1, x[0]) == x[0];
      AddZero(x[0]);
      assert spec_dot_product_gf2(row, x, 0) ==
        add_gf2(mul_gf2(row[0], x[0]), spec_dot_product_gf2(row, x, -1));
      assert spec_dot_product_gf2(row, x, 0) == add_gf2(x[0], 0);
      assert add_gf2(x[0], 0) == x[0];
    } else {
      assert (forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0) by {
        forall j | (0 <= j <= k - 1 && j < (|row|) && j < (|x|))
          ensures row[j] == 0 || x[j] == 0
        {
          assert j != p;
          assert row[j] == 0 || x[j] == 0;
        }
      }
      assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
      ZeroDot(row, x, k - 1);
      assert row[k] == 1;
      MulOne(x[k]);
      assert mul_gf2(row[k], x[k]) == x[k];
      assert spec_dot_product_gf2(row, x, k - 1) == 0;
      AddZero(x[k]);
      assert spec_dot_product_gf2(row, x, k) ==
        add_gf2(mul_gf2(row[k], x[k]), spec_dot_product_gf2(row, x, k - 1));
      assert spec_dot_product_gf2(row, x, k) == add_gf2(x[k], 0);
    }
  } else {
    assert k > p;
    assert forall j :: 0 <= j <= k - 1 && j < |row| && j < |x| ==> IsBit(row[j]) && IsBit(x[j]);
    assert forall j :: 0 <= j <= k - 1 && j != p && j < |row| && j < |x| ==> row[j] == 0 || x[j] == 0;
    DotProductSingle(row, x, k - 1, p);
    assert row[k] == 0 || x[k] == 0;
    if row[k] == 0 {
      MulZero(x[k]);
      assert mul_gf2(row[k], x[k]) == 0;
    } else {
      assert x[k] == 0;
      MulZero(row[k]);
      assert mul_gf2(row[k], x[k]) == 0;
    }
    var rest := spec_dot_product_gf2(row, x, k - 1);
    assert rest == x[p];
    assert IsBit(rest);
    AddZero(rest);
    assert spec_dot_product_gf2(row, x, k) ==
      add_gf2(mul_gf2(row[k], x[k]), rest);
    assert mul_gf2(row[k], x[k]) == 0;
    assert spec_dot_product_gf2(row, x, k) == add_gf2(0, rest);
    assert add_gf2(0, rest) == rest;
  }
}

ghost predicate BitsOK(r1: seq<int>, r2: seq<int>, x: seq<int>, k: int)
  requires |r1| == |r2|
  decreases if k < 0 then 0 else k + 1
{
  if k < 0 then
    true
  else if k < |r1| && k < |x| then
    IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]) && BitsOK(r1, r2, x, k - 1)
  else
    BitsOK(r1, r2, x, k - 1)
}

lemma {:fuel BitsOK, 2} BitsOKBase(r1: seq<int>, r2: seq<int>, x: seq<int>)
  requires |r1| == |r2|
  ensures BitsOK(r1, r2, x, -1)
{
  assert BitsOK(r1, r2, x, -1);
}

lemma {:fuel BitsOK, 2} BitsOKStep(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  requires |r1| == |r2|
  requires 0 <= k
  requires BitsOK(r1, r2, x, k - 1)
  requires k < |r1| && k < |x| ==> IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k])
  ensures BitsOK(r1, r2, x, k)
{
  if k < |r1| && k < |x| {
    assert k < |r1| && k < |x|;
    assert IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]);
    assert BitsOK(r1, r2, x, k) ==
      (IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]) && BitsOK(r1, r2, x, k - 1));
  } else {
    assert BitsOK(r1, r2, x, k) == BitsOK(r1, r2, x, k - 1);
  }
  assert BitsOK(r1, r2, x, k);
}

lemma {:vcs_split_on_every_assert} {:fuel BitsOK, 2} DotBit(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  decreases if k < 0 then 0 else k + 1
  requires |r1| == |r2|
  requires BitsOK(r1, r2, x, k)
  ensures IsBit(spec_dot_product_gf2(r1, x, k))
  ensures IsBit(spec_dot_product_gf2(r2, x, k))
{
  if k < 0 {
    assert spec_dot_product_gf2(r1, x, k) == 0;
    assert spec_dot_product_gf2(r2, x, k) == 0;
    assert IsBit(0);
  } else if k < |r1| && k < |x| {
    assert BitsOK(r1, r2, x, k) ==
      (IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]) && BitsOK(r1, r2, x, k - 1));
    assert BitsOK(r1, r2, x, k - 1);
    assert IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]);
    DotBit(r1, r2, x, k - 1);
    MulIsBit(r1[k], x[k]);
    MulIsBit(r2[k], x[k]);
    var p1 := mul_gf2(r1[k], x[k]);
    var p2 := mul_gf2(r2[k], x[k]);
    var s1 := spec_dot_product_gf2(r1, x, k - 1);
    var s2 := spec_dot_product_gf2(r2, x, k - 1);
    assert IsBit(s1) && IsBit(s2);
    AddIsBit(p1, s1);
    AddIsBit(p2, s2);
    assert spec_dot_product_gf2(r1, x, k) == add_gf2(p1, s1);
    assert spec_dot_product_gf2(r2, x, k) == add_gf2(p2, s2);
  } else {
    assert BitsOK(r1, r2, x, k) == BitsOK(r1, r2, x, k - 1);
    DotBit(r1, r2, x, k - 1);
    assert spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r1, x, k - 1);
    assert spec_dot_product_gf2(r2, x, k) == spec_dot_product_gf2(r2, x, k - 1);
  }
}

lemma {:vcs_split_on_every_assert} BitDotStepAlgebra(a: int, b: int, xv: int, s1: int, s2: int)
  requires IsBit(a) && IsBit(b) && IsBit(xv) && IsBit(s1) && IsBit(s2)
  ensures add_gf2(mul_gf2(add_gf2(a, b), xv), add_gf2(s1, s2)) ==
    add_gf2(add_gf2(mul_gf2(a, xv), s1), add_gf2(mul_gf2(b, xv), s2))
{
  AddIsBit(a, b);
  var ab := add_gf2(a, b);
  assert IsBit(ab);
  DistrBit(a, b, xv);
  MulIsBit(a, xv);
  MulIsBit(b, xv);
  MulIsBit(ab, xv);
  var p1 := mul_gf2(a, xv);
  var p2 := mul_gf2(b, xv);
  var px := mul_gf2(ab, xv);
  assert px == add_gf2(p1, p2);
  assert IsBit(p1) && IsBit(p2) && IsBit(px);
  AddIsBit(s1, s2);
  var s := add_gf2(s1, s2);
  assert IsBit(s);
  AddIsBit(px, s);
  AddIsBit(p1, s1);
  AddIsBit(p2, s2);
  AddIsBit(p1, p2);
  XorFourRearrange(p1, p2, s1, s2);
  assert add_gf2(px, s) == add_gf2(add_gf2(p1, p2), s);
  assert s == add_gf2(s1, s2);
  assert add_gf2(add_gf2(p1, p2), add_gf2(s1, s2)) ==
    add_gf2(add_gf2(p1, s1), add_gf2(p2, s2));
  assert add_gf2(px, add_gf2(s1, s2)) ==
    add_gf2(add_gf2(p1, s1), add_gf2(p2, s2));
}

lemma {:vcs_split_on_every_assert} {:fuel BitsOK, 2} DotLinearStep(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  requires 0 <= k
  requires |r1| == |r2|
  requires k < |r1| && k < |x|
  requires BitsOK(r1, r2, x, k)
  requires spec_dot_product_gf2(XorRow(r1, r2), x, k - 1) ==
    add_gf2(spec_dot_product_gf2(r1, x, k - 1), spec_dot_product_gf2(r2, x, k - 1))
  ensures spec_dot_product_gf2(XorRow(r1, r2), x, k) ==
    add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k))
{
  assert BitsOK(r1, r2, x, k) ==
    (IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]) && BitsOK(r1, r2, x, k - 1));
  assert IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]);
  assert BitsOK(r1, r2, x, k - 1);
  DotBit(r1, r2, x, k - 1);
  var s1 := spec_dot_product_gf2(r1, x, k - 1);
  var s2 := spec_dot_product_gf2(r2, x, k - 1);
  assert IsBit(s1) && IsBit(s2);
  var xr := XorRow(r1, r2);
  assert |xr| == |r1|;
  XorEntry(r1, r2, k);
  assert xr[k] == (r1[k] + r2[k]) % 2;
  assert add_gf2(r1[k], r2[k]) == (r1[k] + r2[k]) % 2;
  assert xr[k] == add_gf2(r1[k], r2[k]);
  assert spec_dot_product_gf2(xr, x, k - 1) == add_gf2(s1, s2);
  BitDotStepAlgebra(r1[k], r2[k], x[k], s1, s2);
  assert k < |xr| && k < |x|;
  assert spec_dot_product_gf2(xr, x, k) ==
    add_gf2(mul_gf2(xr[k], x[k]), spec_dot_product_gf2(xr, x, k - 1));
  assert mul_gf2(xr[k], x[k]) == mul_gf2(add_gf2(r1[k], r2[k]), x[k]);
  assert spec_dot_product_gf2(xr, x, k) ==
    add_gf2(mul_gf2(add_gf2(r1[k], r2[k]), x[k]), add_gf2(s1, s2));
  assert spec_dot_product_gf2(r1, x, k) == add_gf2(mul_gf2(r1[k], x[k]), s1);
  assert spec_dot_product_gf2(r2, x, k) == add_gf2(mul_gf2(r2[k], x[k]), s2);
  assert add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k)) ==
    add_gf2(add_gf2(mul_gf2(r1[k], x[k]), s1), add_gf2(mul_gf2(r2[k], x[k]), s2));
  assert spec_dot_product_gf2(xr, x, k) ==
    add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k));
}

lemma {:vcs_split_on_every_assert} {:fuel BitsOK, 2} DotLinear(
  r1: seq<int>,
  r2: seq<int>,
  x: seq<int>,
  k: int)
  decreases if k < 0 then 0 else k + 1
  requires |r1| == |r2|
  requires BitsOK(r1, r2, x, k)
  ensures spec_dot_product_gf2(XorRow(r1, r2), x, k) ==
    add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k))
{
  if k < 0 {
    assert spec_dot_product_gf2(XorRow(r1, r2), x, k) == 0;
    assert spec_dot_product_gf2(r1, x, k) == 0;
    assert spec_dot_product_gf2(r2, x, k) == 0;
    assert add_gf2(0, 0) == (0 + 0) % 2;
    assert (0 + 0) % 2 == 0;
    assert add_gf2(0, 0) == 0;
  } else if k < |r1| && k < |x| {
    assert BitsOK(r1, r2, x, k) ==
      (IsBit(r1[k]) && IsBit(r2[k]) && IsBit(x[k]) && BitsOK(r1, r2, x, k - 1));
    assert BitsOK(r1, r2, x, k - 1);
    DotLinear(r1, r2, x, k - 1);
    DotLinearStep(r1, r2, x, k);
  } else {
    assert BitsOK(r1, r2, x, k) == BitsOK(r1, r2, x, k - 1);
    DotLinear(r1, r2, x, k - 1);
    assert spec_dot_product_gf2(r1, x, k) == spec_dot_product_gf2(r1, x, k - 1);
    assert spec_dot_product_gf2(r2, x, k) == spec_dot_product_gf2(r2, x, k - 1);
    var xr := XorRow(r1, r2);
    assert |xr| == |r1|;
    assert !(k < |xr| && k < |x|);
    assert spec_dot_product_gf2(xr, x, k) == spec_dot_product_gf2(xr, x, k - 1);
    assert spec_dot_product_gf2(xr, x, k - 1) ==
      add_gf2(spec_dot_product_gf2(r1, x, k - 1), spec_dot_product_gf2(r2, x, k - 1));
    assert add_gf2(spec_dot_product_gf2(r1, x, k), spec_dot_product_gf2(r2, x, k)) ==
      add_gf2(spec_dot_product_gf2(r1, x, k - 1), spec_dot_product_gf2(r2, x, k - 1));
  }
}

lemma XorEntry(a: seq<int>, b: seq<int>, j: int)
  requires |a| == |b|
  requires 0 <= j < |a|
  ensures XorRow(a, b)[j] == (a[j] + b[j]) % 2
{
}

lemma AddRowAt(m: seq<seq<int>>, dst: int, src: int, i: int)
  requires 0 <= dst < |m| && 0 <= src < |m|
  requires |m[dst]| == |m[src]|
  requires 0 <= i < |m|
  ensures |AddRowTo(m, dst, src)| == |m|
  ensures i == dst ==> AddRowTo(m, dst, src)[i] == XorRow(m[dst], m[src])
  ensures i != dst ==> AddRowTo(m, dst, src)[i] == m[i]
{
  var n := AddRowTo(m, dst, src);
  assert n == m[dst := XorRow(m[dst], m[src])];
  assert |n| == |m|;
  if i == dst {
    assert n[i] == XorRow(m[dst], m[src]);
  } else {
    assert n[i] == m[i];
  }
}

lemma {:vcs_split_on_every_assert} AddRowPreservesSol(
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  x: seq<int>,
  nCols: int)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  requires forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1
  requires forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(AddRowTo(aug, dst, src), x, nCols)
{
  var newA := AddRowTo(aug, dst, src);
  var r1 := aug[dst];
  var r2 := aug[src];
  var xr := XorRow(r1, r2);
  assert |r1| == nCols + 1 && |r2| == nCols + 1;
  assert newA[dst] == xr;
  forall i | (0 <= i < (|aug|))
    ensures |newA[i]| == nCols + 1
  {
    if i == dst {
      AddRowAt(aug, dst, src, i);
      assert |xr| == nCols + 1;
    } else {
      AddRowAt(aug, dst, src, i);
      assert newA[i] == aug[i];
    }
  }

  assert |r1| == |r2|;
  BitsOKBase(r1, r2, x);
  var bi := -1;
  assert BitsOK(r1, r2, x, -1);
  assert bi == -1;
  assert BitsOK(r1, r2, x, bi);
  while bi < nCols - 1
    invariant -1 <= bi <= nCols - 1
    invariant BitsOK(r1, r2, x, bi)
    decreases nCols - 1 - bi
  {
    var next := bi + 1;
    assert -1 <= bi < nCols - 1;
    assert 0 <= next <= nCols - 1;
    assert (next < |r1| && next < |x|) ==> IsBit(r1[next]) && IsBit(r2[next]) && IsBit(x[next])
    by {
      if next < |r1| && next < |x| {
        assert IsBit(r1[next]);
        assert IsBit(r2[next]);
        assert 0 <= next < |x|;
        assert x[next] == 0 || x[next] == 1;
        assert IsBit(x[next]);
      }
    };
    assert next - 1 == bi;
    assert BitsOK(r1, r2, x, next - 1);
    BitsOKStep(r1, r2, x, next);
    bi := next;
  }
  assert bi == nCols - 1;
  assert BitsOK(r1, r2, x, nCols - 1);
  DotLinear(r1, r2, x, nCols - 1);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r1| && j < |x| ==> IsBit(r1[j]) && IsBit(x[j]);
  assert forall j :: 0 <= j <= nCols - 1 && j < |r2| && j < |x| ==> IsBit(r2[j]) && IsBit(x[j]);
  DotIsBit(r1, x, nCols - 1);
  DotIsBit(r2, x, nCols - 1);

  assert (SolvesAug(aug, x, nCols) ==> SolvesAug(newA, x, nCols)) by {
    if SolvesAug(aug, x, nCols) {
      forall i | (0 <= i < (|newA|))
        ensures |newA[i]| == nCols + 1 &&
          spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          assert sd == r1[nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(r1[nCols], r2[nCols]) == (r1[nCols] + r2[nCols]) % 2;
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          assert newA[i] == xr;
        }
      }
    }
  }

  assert (SolvesAug(newA, x, nCols) ==> SolvesAug(aug, x, nCols)) by {
    if SolvesAug(newA, x, nCols) {
      forall i | (0 <= i < (|aug|))
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        if i != dst {
          AddRowAt(aug, dst, src, i);
          assert newA[i] == aug[i];
          assert spec_dot_product_gf2(newA[i], x, nCols - 1) == newA[i][nCols];
        } else {
          var sd := spec_dot_product_gf2(r1, x, nCols - 1);
          var ss := spec_dot_product_gf2(r2, x, nCols - 1);
          AddRowAt(aug, dst, src, src);
          assert newA[src] == aug[src];
          assert spec_dot_product_gf2(newA[src], x, nCols - 1) == newA[src][nCols];
          assert ss == r2[nCols];
          assert spec_dot_product_gf2(xr, x, nCols - 1) == add_gf2(sd, ss);
          assert newA[dst] == xr;
          assert spec_dot_product_gf2(xr, x, nCols - 1) == xr[nCols];
          XorEntry(r1, r2, nCols);
          assert xr[nCols] == add_gf2(r1[nCols], r2[nCols]);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], r2[nCols]);
          assert IsBit(sd) && IsBit(ss);
          assert IsBit(r1[nCols]) && IsBit(r2[nCols]);
          assert ss == r2[nCols];
          XorCancel(sd, ss);
          XorCancel(r1[nCols], ss);
          assert add_gf2(sd, ss) == add_gf2(r1[nCols], ss);
          assert add_gf2(add_gf2(sd, ss), ss) == add_gf2(add_gf2(r1[nCols], ss), ss);
          assert add_gf2(add_gf2(sd, ss), ss) == sd;
          assert add_gf2(add_gf2(r1[nCols], ss), ss) == r1[nCols];
          assert sd == r1[nCols];
        }
      }
    }
  }
}

lemma SwapRowEq(m: seq<seq<int>>, r1: int, r2: int, i: int)
  requires 0 <= r1 < |m| && 0 <= r2 < |m| && 0 <= i < |m|
  ensures SwapRows(m, r1, r2)[i] ==
    (if r1 == r2 then m[i] else if i == r1 then m[r2] else if i == r2 then m[r1] else m[i])
{
  if r1 == r2 {
    assert SwapRows(m, r1, r2) == m;
  } else {
    var m1 := m[r1 := m[r2]];
    var m2 := m1[r2 := m[r1]];
    assert SwapRows(m, r1, r2) == m2;
    assert m1[r1] == m[r2];
    if i == r2 {
      assert m2[r2] == m[r1];
    } else if i == r1 {
      assert m2[r1] == m1[r1];
      assert m1[r1] == m[r2];
    } else {
      assert m1[i] == m[i];
      assert m2[i] == m1[i];
    }
  }
}

lemma {:vcs_split_on_every_assert} SwapPreservesSol(
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  x: seq<int>,
  nCols: int)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  requires |x| == nCols && is_binary_vector(x)
  ensures SolvesAug(aug, x, nCols) <==> SolvesAug(SwapRows(aug, r1, r2), x, nCols)
{
  var s := SwapRows(aug, r1, r2);
  assert |s| == |aug|;

  assert (SolvesAug(aug, x, nCols) ==> SolvesAug(s, x, nCols)) by {
    if SolvesAug(aug, x, nCols) {
      forall i | (0 <= i < (|s|))
        ensures |s[i]| == nCols + 1 &&
          spec_dot_product_gf2(s[i], x, nCols - 1) == s[i][nCols]
      {
        var src := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, i);
        assert s[i] == aug[src];
        assert 0 <= src < |aug|;
        assert spec_dot_product_gf2(aug[src], x, nCols - 1) == aug[src][nCols];
      }
    }
  }

  assert (SolvesAug(s, x, nCols) ==> SolvesAug(aug, x, nCols)) by {
    if SolvesAug(s, x, nCols) {
      forall i | (0 <= i < (|aug|))
        ensures |aug[i]| == nCols + 1 &&
          spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
      {
        var dst := if r1 == r2 then i else if i == r1 then r2 else if i == r2 then r1 else i;
        SwapRowEq(aug, r1, r2, dst);
        if r1 == r2 {
          assert s[dst] == aug[i];
        } else if i == r1 {
          assert dst == r2;
          assert s[dst] == aug[r1];
        } else if i == r2 {
          assert dst == r1;
          assert s[dst] == aug[r2];
        } else {
          assert dst == i;
          assert s[dst] == aug[i];
        }
        assert s[dst] == aug[i];
        assert spec_dot_product_gf2(s[dst], x, nCols - 1) == s[dst][nCols];
        assert |aug[i]| == nCols + 1;
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} SameSolAfterAdd(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  dst: int,
  src: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= dst < |aug| && 0 <= src < |aug| && dst != src
  requires nCols >= 1
  ensures SameSol(matrix, b, AddRowTo(aug, dst, src), nCols)
{
  reveal SameSol();
  var newA := AddRowTo(aug, dst, src);
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures is_solution(matrix, b, x) <==> SolvesAug(newA, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    assert forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1;
    assert forall i :: 0 <= i < |aug| ==> forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j]);
    AddRowPreservesSol(aug, dst, src, x, nCols);
  }
}

lemma {:vcs_split_on_every_assert} SameSolAfterSwap(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  r1: int,
  r2: int,
  nCols: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires 0 <= r1 < |aug| && 0 <= r2 < |aug|
  ensures SameSol(matrix, b, SwapRows(aug, r1, r2), nCols)
{
  reveal SameSol();
  var s := SwapRows(aug, r1, r2);
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures is_solution(matrix, b, x) <==> SolvesAug(s, x, nCols)
  {
    assert is_solution(matrix, b, x) <==> SolvesAug(aug, x, nCols);
    SwapPreservesSol(aug, r1, r2, x, nCols);
  }
}

lemma StateParts(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, col, rows, nCols)
  ensures AugOK(aug, rows, nCols)
  ensures PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  ensures UnitPivots(aug, pivotCol, numPivots, col, rows, nCols)
  ensures LowerZeros(aug, numPivots, col, rows, nCols)
{
}

lemma AugBit(aug: seq<seq<int>>, rows: int, nCols: int, i: int, j: int)
  requires AugOK(aug, rows, nCols)
  requires 0 <= i < rows
  requires 0 <= j <= nCols
  ensures |aug[i]| == nCols + 1
  ensures IsBit(aug[i][j])
{
  assert |aug[i]| == nCols + 1;
  assert IsBit(aug[i][j]);
}

lemma PivotFact(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int)
  requires PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  requires 0 <= r < numPivots
  ensures 0 <= pivotCol[r] < col
  ensures pivotCol[r] < nCols
  ensures rowOfCol[pivotCol[r]] == r
{
  assert |pivotCol| == rows;
  assert numPivots <= rows;
  assert r < |pivotCol|;
  assert 0 <= pivotCol[r] < col;
  assert pivotCol[r] < |rowOfCol|;
  assert rowOfCol[pivotCol[r]] == r;
  assert |rowOfCol| == nCols;
  assert pivotCol[r] < nCols;
}

lemma RowOfFact(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  j: int)
  requires PivotOK(pivotCol, rowOfCol, numPivots, col, rows, nCols)
  requires 0 <= j < nCols
  ensures rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots && pivotCol[rowOfCol[j]] == j)
  ensures j >= col ==> rowOfCol[j] == -1
{
  assert j < |rowOfCol|;
  assert rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots && rowOfCol[j] < |pivotCol| && pivotCol[rowOfCol[j]] == j);
  if j >= col {
    assert rowOfCol[j] == -1;
  }
}

lemma UnitFact(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int)
  requires UnitPivots(aug, pivotCol, numPivots, col, rows, nCols)
  requires AugOK(aug, rows, nCols)
  requires 0 <= r < numPivots
  requires numPivots <= rows
  requires r < |pivotCol|
  ensures 0 <= pivotCol[r] < col
  ensures pivotCol[r] < nCols
  ensures aug[r][pivotCol[r]] == 1
  ensures forall i :: 0 <= i < rows && i != r ==> aug[i][pivotCol[r]] == 0
{
  assert |aug| == rows;
  assert r < rows;
  assert r < |aug|;
  var p := pivotCol[r];
  assert 0 <= p < col;
  assert p < nCols;
  assert p < |aug[r]|;
  assert aug[r][p] == 1;
  forall i | (0 <= i < rows && i != r)
    ensures aug[i][p] == 0
  {
    AugBit(aug, rows, nCols, i, p);
    assert p < |aug[i]|;
    assert aug[i][p] == 0;
  }
}

lemma LowerFact(
  aug: seq<seq<int>>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int,
  r: int,
  j: int)
  requires LowerZeros(aug, numPivots, col, rows, nCols)
  requires AugOK(aug, rows, nCols)
  requires 0 <= r < rows
  requires numPivots <= r
  requires 0 <= j < col
  requires 0 <= j <= nCols
  ensures aug[r][j] == 0
{
  AugBit(aug, rows, nCols, r, j);
  assert |aug| == rows;
  assert 0 <= r < |aug|;
  assert j < |aug[r]|;
  assert numPivots <= r < rows;
  assert 0 <= j < col && j < |aug[r]|;
  assert aug[r][j] == 0;
}

lemma {:vcs_split_on_every_assert} InitState(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  pc: seq<int>,
  rc: seq<int>)
  requires |matrix| > 0 && |matrix[0]| > 0
  requires |matrix| == |b|
  requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
  requires is_binary_vector(b)
  requires aug == BuildAug(matrix, b)
  requires |pc| == |matrix|
  requires forall r :: 0 <= r < |matrix| ==> pc[r] == -1
  requires |rc| == |matrix[0]|
  requires forall j :: 0 <= j < |matrix[0]| ==> rc[j] == -1
  ensures RREFState(aug, pc, rc, 0, 0, |matrix|, |matrix[0]|)
  ensures SameSol(matrix, b, aug, |matrix[0]|)
{
  var rows := |matrix|;
  var nCols := |matrix[0]|;
  assert |aug| == rows;

  forall i | (0 <= i < rows)
    ensures |aug[i]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])
  {
    assert aug[i] == matrix[i] + [b[i]];
    assert |matrix[i]| == nCols;
    assert |aug[i]| == nCols + 1;
    forall j | (0 <= j <= nCols)
      ensures IsBit(aug[i][j])
    {
      if j < nCols {
        assert aug[i][j] == matrix[i][j];
        assert matrix[i][j] == 0 || matrix[i][j] == 1;
      } else {
        assert aug[i][j] == b[i];
        assert b[i] == 0 || b[i] == 1;
      }
    }
  }
  assert AugOK(aug, rows, nCols);

  assert forall r :: 0 <= r < rows && r < |pc| ==> pc[r] == -1;
  assert forall r :: 0 <= r < 0 && r < |pc| ==> 0 <= pc[r] < 0 && pc[r] < |rc| && rc[pc[r]] == r;
  assert forall j :: 0 <= j < nCols && j < |rc| ==> rc[j] == -1;
  assert PivotOK(pc, rc, 0, 0, rows, nCols);
  assert UnitPivots(aug, pc, 0, 0, rows, nCols);
  assert LowerZeros(aug, 0, 0, rows, nCols) by {
    forall r | 0 <= r < |aug| && 0 <= r < rows
      ensures forall j :: 0 <= j < 0 && j < |aug[r]| ==> aug[r][j] == 0
    {
    }
  }
  assert RREFState(aug, pc, rc, 0, 0, rows, nCols);

  reveal SameSol();
  forall xv | ((|xv|) == nCols && is_binary_vector(xv))
    ensures is_solution(matrix, b, xv) <==> SolvesAug(aug, xv, nCols)
  {
    forall i | (0 <= i < rows)
      ensures spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
        spec_dot_product_gf2(matrix[i], xv, nCols - 1)
      ensures aug[i][nCols] == b[i]
      ensures |aug[i]| == nCols + 1
    {
      assert aug[i] == matrix[i] + [b[i]];
      assert |matrix[i]| == nCols;
      assert |aug[i]| == nCols + 1;
      assert aug[i][nCols] == b[i];
      assert (forall j {:trigger Id(j)} :: 0 <= j <= nCols - 1 && j < |xv| ==>
        j < |aug[i]| && j < |matrix[i]| && aug[i][j] == matrix[i][j]) by {
        forall j | (0 <= j <= nCols - 1 && j < (|xv|))
          ensures j < |aug[i]| && j < |matrix[i]| && aug[i][j] == matrix[i][j]
        {
          assert j < nCols;
          assert aug[i][j] == matrix[i][j];
        }
      }
      DotProductDependsOnPrefix(aug[i], matrix[i], xv, nCols - 1);
    }

    assert |matrix| == |b| && |matrix| > 0 && |xv| == |matrix[0]| && is_binary_vector(xv);
    assert is_solution(matrix, b, xv) <==>
      (forall i :: 0 <= i < |matrix| ==>
        spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i]);
    assert forall i :: 0 <= i < |aug| ==> |aug[i]| == nCols + 1;
    assert SolvesAug(aug, xv, nCols) <==>
      (forall i :: 0 <= i < |aug| ==>
        spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols]);

    if is_solution(matrix, b, xv) {
      forall i | (0 <= i < (|aug|))
        ensures spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols]
      {
        assert spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i];
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
          spec_dot_product_gf2(matrix[i], xv, nCols - 1);
        assert aug[i][nCols] == b[i];
      }
    }
    if SolvesAug(aug, xv, nCols) {
      forall i | (0 <= i < (|matrix|))
        ensures spec_dot_product_gf2(matrix[i], xv, nCols - 1) == b[i]
      {
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) == aug[i][nCols];
        assert spec_dot_product_gf2(aug[i], xv, nCols - 1) ==
          spec_dot_product_gf2(matrix[i], xv, nCols - 1);
        assert aug[i][nCols] == b[i];
      }
    }
  }
}

lemma {:vcs_split_on_every_assert} AfterSwap(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  sel: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots <= sel < rows
  requires aug[sel][c] == 1
  ensures var s := SwapRows(aug, numPivots, sel);
    RREFState(s, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  ensures SwapRows(aug, numPivots, sel)[numPivots][c] == 1
{
  var s := SwapRows(aug, numPivots, sel);
  StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
  assert 0 <= numPivots <= rows;
  assert c <= nCols;
  assert |s| == |aug|;

  forall i | (0 <= i < rows)
    ensures |s[i]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(s[i][j])
  {
    var src := if numPivots == sel then i else if i == numPivots then sel else if i == sel then numPivots else i;
    SwapRowEq(aug, numPivots, sel, i);
    assert s[i] == aug[src];
    assert 0 <= src < rows;
    AugBit(aug, rows, nCols, src, 0);
    assert |aug[src]| == nCols + 1;
    forall j | (0 <= j <= nCols)
      ensures IsBit(s[i][j])
    {
      AugBit(aug, rows, nCols, src, j);
      assert s[i][j] == aug[src][j];
    }
  }
  assert AugOK(s, rows, nCols);
  assert PivotOK(pivotCol, rowOfCol, numPivots, c, rows, nCols);

  forall r | (0 <= r < numPivots && r < |s| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c && pivotCol[r] < nCols && pivotCol[r] < |s[r]| &&
      s[r][pivotCol[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |s| && i != r && pivotCol[r] < |s[i]| ==> s[i][pivotCol[r]] == 0)
  {
    PivotFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, r);
    var p := pivotCol[r];
    assert r < numPivots <= sel;
    assert r != numPivots && r != sel;
    SwapRowEq(aug, numPivots, sel, r);
    assert s[r] == aug[r];
    assert numPivots <= rows;
    assert |aug| == rows;
    assert r < |aug|;
    UnitFact(aug, pivotCol, numPivots, c, rows, nCols, r);
    assert aug[r][p] == 1;
    assert s[r][p] == 1;
    assert p < |s[r]|;
    forall i | (0 <= i < rows && i < |s| && i != r && p < |s[i]|)
      ensures s[i][p] == 0
    {
      var src := if numPivots == sel then i else if i == numPivots then sel else if i == sel then numPivots else i;
      SwapRowEq(aug, numPivots, sel, i);
      assert s[i] == aug[src];
      assert src != r;
      assert 0 <= src < rows;
      AugBit(aug, rows, nCols, src, p);
      assert aug[src][p] == 0;
      assert s[i][p] == 0;
    }
  }
  assert UnitPivots(s, pivotCol, numPivots, c, rows, nCols);

  forall r | 0 <= r < |s| && numPivots <= r < rows
    ensures forall j :: 0 <= j < c && j < |s[r]| ==> s[r][j] == 0
  {
    forall j | 0 <= j < c && j < |s[r]|
      ensures s[r][j] == 0
    {
      var src := if numPivots == sel then r else if r == numPivots then sel else if r == sel then numPivots else r;
      SwapRowEq(aug, numPivots, sel, r);
      assert s[r] == aug[src];
      assert numPivots <= src < rows;
      assert 0 <= numPivots <= src;
      assert 0 <= src < rows;
      assert c <= nCols;
      assert j < c;
      assert j <= nCols;
      LowerFact(aug, numPivots, c, rows, nCols, src, j);
      assert s[r][j] == 0;
    }
  }
  assert LowerZeros(s, numPivots, c, rows, nCols);
  assert RREFState(s, pivotCol, rowOfCol, numPivots, c, rows, nCols);

  SwapRowEq(aug, numPivots, sel, numPivots);
  if numPivots == sel {
    assert s[numPivots] == aug[numPivots];
  } else {
    assert s[numPivots] == aug[sel];
  }
  assert s[numPivots] == aug[sel];
  assert s[numPivots][c] == aug[sel][c];
  assert s[numPivots][c] == 1;
}

lemma {:vcs_split_on_every_assert} AddElimStep(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  i: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots < rows
  requires 0 <= i < rows && i != numPivots
  requires aug[numPivots][c] == 1
  requires aug[i][c] == 1
  ensures var n := AddRowTo(aug, i, numPivots);
    RREFState(n, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  ensures AddRowTo(aug, i, numPivots)[numPivots][c] == 1
  ensures AddRowTo(aug, i, numPivots)[i][c] == 0
{
  var P := numPivots;
  var n := AddRowTo(aug, i, P);
  StateParts(aug, pivotCol, rowOfCol, P, c, rows, nCols);
  assert 0 <= P <= rows;
  assert c <= nCols;
  AugBit(aug, rows, nCols, i, c);
  AugBit(aug, rows, nCols, P, c);
  assert |aug[i]| == |aug[P]|;
  AddRowAt(aug, i, P, i);
  AddRowAt(aug, i, P, P);
  assert n[i] == XorRow(aug[i], aug[P]);
  assert n[P] == aug[P];
  assert n[P][c] == 1;

  XorEntry(aug[i], aug[P], c);
  assert aug[i][c] == 1 && aug[P][c] == 1;
  assert (1 + 1) % 2 == 0;
  assert n[i][c] == 0;

  forall t | (0 <= t < rows)
    ensures |n[t]| == nCols + 1
    ensures forall j :: 0 <= j <= nCols ==> IsBit(n[t][j])
  {
    if t == i {
      assert |n[t]| == nCols + 1;
      forall j | (0 <= j <= nCols)
        ensures IsBit(n[t][j])
      {
        AugBit(aug, rows, nCols, i, j);
        AugBit(aug, rows, nCols, P, j);
        XorEntry(aug[i], aug[P], j);
        AddIsBit(aug[i][j], aug[P][j]);
        assert n[t][j] == (aug[i][j] + aug[P][j]) % 2;
        assert add_gf2(aug[i][j], aug[P][j]) == (aug[i][j] + aug[P][j]) % 2;
        assert IsBit(add_gf2(aug[i][j], aug[P][j]));
        assert IsBit(n[t][j]);
      }
    } else {
      AddRowAt(aug, i, P, t);
      assert n[t] == aug[t];
      AugBit(aug, rows, nCols, t, 0);
      forall j | (0 <= j <= nCols)
        ensures IsBit(n[t][j])
      {
        AugBit(aug, rows, nCols, t, j);
        assert n[t][j] == aug[t][j];
      }
    }
  }
  assert AugOK(n, rows, nCols);
  assert PivotOK(pivotCol, rowOfCol, P, c, rows, nCols);

  forall r | (0 <= r < P && r < |n| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c && pivotCol[r] < nCols && pivotCol[r] < |n[r]| &&
      n[r][pivotCol[r]] == 1 &&
      (forall t :: 0 <= t < rows && t < |n| && t != r && pivotCol[r] < |n[t]| ==> n[t][pivotCol[r]] == 0)
  {
    PivotFact(pivotCol, rowOfCol, P, c, rows, nCols, r);
    assert P <= rows;
    assert |aug| == rows;
    assert r < |aug|;
    UnitFact(aug, pivotCol, P, c, rows, nCols, r);
    var p := pivotCol[r];
    assert p < c;
    assert aug[P][p] == 0;
    if i == r {
      AddRowAt(aug, i, P, r);
      XorEntry(aug[r], aug[P], p);
      assert aug[r][p] == 1 && aug[P][p] == 0;
      assert (1 + 0) % 2 == 1;
      assert n[r][p] == 1;
    } else {
      AddRowAt(aug, i, P, r);
      assert n[r] == aug[r];
      assert n[r][p] == 1;
    }
    assert p < |n[r]|;
    forall t | (0 <= t < rows && t < |n| && t != r && p < |n[t]|)
      ensures n[t][p] == 0
    {
      if t == i {
        assert i != r;
        assert aug[i][p] == 0;
        assert aug[P][p] == 0;
        XorEntry(aug[i], aug[P], p);
        assert (0 + 0) % 2 == 0;
        assert n[i][p] == 0;
      } else {
        AddRowAt(aug, i, P, t);
        assert n[t] == aug[t];
        assert aug[t][p] == 0;
        assert n[t][p] == 0;
      }
    }
  }
  assert UnitPivots(n, pivotCol, P, c, rows, nCols);

  forall r | 0 <= r < |n| && P <= r < rows
    ensures forall j :: 0 <= j < c && j < |n[r]| ==> n[r][j] == 0
  {
    forall j | 0 <= j < c && j < |n[r]|
      ensures n[r][j] == 0
    {
      assert 0 <= P < rows;
      assert j <= nCols;
      LowerFact(aug, P, c, rows, nCols, P, j);
      if r == i {
        assert r != P;
        assert 0 <= r < rows;
        LowerFact(aug, P, c, rows, nCols, r, j);
        assert n[r] == XorRow(aug[r], aug[P]);
        XorEntry(aug[r], aug[P], j);
        assert aug[r][j] == 0 && aug[P][j] == 0;
        assert (0 + 0) % 2 == 0;
        assert n[r][j] == 0;
      } else {
        AddRowAt(aug, i, P, r);
        assert n[r] == aug[r];
        assert 0 <= r < rows;
        LowerFact(aug, P, c, rows, nCols, r, j);
        assert n[r][j] == 0;
      }
    }
  }
  assert LowerZeros(n, P, c, rows, nCols);
  assert RREFState(n, pivotCol, rowOfCol, P, c, rows, nCols);
}

lemma {:vcs_split_on_every_assert} NoPivotAdvance(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires forall r :: numPivots <= r < rows ==> aug[r][c] == 0
  ensures RREFState(aug, pivotCol, rowOfCol, numPivots, c + 1, rows, nCols)
{
  StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
  assert 0 <= numPivots <= rows;
  assert c <= nCols;
  assert AugOK(aug, rows, nCols);

  assert |pivotCol| == rows && |rowOfCol| == nCols;
  assert 0 <= numPivots <= rows && 0 <= c + 1 <= nCols;
  assert forall r :: numPivots <= r < rows && r < |pivotCol| ==> pivotCol[r] == -1;

  forall r | (0 <= r < numPivots && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c + 1 && pivotCol[r] < |rowOfCol| && rowOfCol[pivotCol[r]] == r
  {
    PivotFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, r);
    assert pivotCol[r] < c;
    assert pivotCol[r] < c + 1;
  }

  forall j | (0 <= j < nCols && j < |rowOfCol|)
    ensures rowOfCol[j] == -1 ||
      (0 <= rowOfCol[j] < numPivots && rowOfCol[j] < |pivotCol| && pivotCol[rowOfCol[j]] == j)
  {
    RowOfFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, j);
    if rowOfCol[j] != -1 {
      var rr := rowOfCol[j];
      assert 0 <= rr < numPivots;
      assert rr < |pivotCol|;
      assert pivotCol[rr] == j;
    }
  }

  forall j | (c + 1 <= j < nCols && j < |rowOfCol|)
    ensures rowOfCol[j] == -1
  {
    assert j >= c;
    RowOfFact(pivotCol, rowOfCol, numPivots, c, rows, nCols, j);
  }
  assert PivotOK(pivotCol, rowOfCol, numPivots, c + 1, rows, nCols);

  forall r | (0 <= r < numPivots && r < |aug| && r < |pivotCol|)
    ensures 0 <= pivotCol[r] < c + 1 && pivotCol[r] < nCols && pivotCol[r] < |aug[r]| &&
      aug[r][pivotCol[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |aug| && i != r && pivotCol[r] < |aug[i]| ==>
        aug[i][pivotCol[r]] == 0)
  {
    assert numPivots <= rows;
    UnitFact(aug, pivotCol, numPivots, c, rows, nCols, r);
    assert pivotCol[r] < c + 1;
  }
  assert UnitPivots(aug, pivotCol, numPivots, c + 1, rows, nCols);

  forall r | 0 <= r < |aug| && numPivots <= r < rows
    ensures forall j :: 0 <= j < c + 1 && j < |aug[r]| ==> aug[r][j] == 0
  {
    forall j | 0 <= j < c + 1 && j < |aug[r]|
      ensures aug[r][j] == 0
    {
      if j < c {
        assert 0 <= r < rows;
        assert j <= nCols;
        LowerFact(aug, numPivots, c, rows, nCols, r, j);
      } else {
        assert j == c;
        assert aug[r][c] == 0;
      }
    }
  }
  assert LowerZeros(aug, numPivots, c + 1, rows, nCols);
  assert RREFState(aug, pivotCol, rowOfCol, numPivots, c + 1, rows, nCols);
}

lemma {:vcs_split_on_every_assert} RecordPivot(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  c: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
  requires 0 <= c < nCols
  requires numPivots < rows
  requires 0 <= numPivots < |pivotCol|
  requires 0 <= c < |rowOfCol|
  requires aug[numPivots][c] == 1
  requires forall t :: 0 <= t < rows && t != numPivots ==> aug[t][c] == 0
  ensures RREFState(
    aug,
    pivotCol[numPivots := c],
    rowOfCol[c := numPivots],
    numPivots + 1,
    c + 1,
    rows,
    nCols)
{
  var P := numPivots;
  var pc2 := pivotCol[P := c];
  var rc2 := rowOfCol[c := P];
  var np := P + 1;
  var col2 := c + 1;
  StateParts(aug, pivotCol, rowOfCol, P, c, rows, nCols);
  assert 0 <= P <= rows;
  assert c <= nCols;
  assert AugOK(aug, rows, nCols);

  assert |pc2| == |pivotCol| == rows;
  assert |rc2| == |rowOfCol| == nCols;
  assert pc2[P] == c;
  assert rc2[c] == P;
  forall t | (0 <= t < |pivotCol| && t != P)
    ensures pc2[t] == pivotCol[t]
  {
  }
  forall t | (0 <= t < |rowOfCol| && t != c)
    ensures rc2[t] == rowOfCol[t]
  {
  }

  forall r | (np <= r < rows && r < |pc2|)
    ensures pc2[r] == -1
  {
    assert r != P;
    assert r >= P;
    assert pivotCol[r] == -1;
    assert pc2[r] == pivotCol[r];
  }

  forall r | (0 <= r < np && r < |pc2|)
    ensures 0 <= pc2[r] < col2 && pc2[r] < |rc2| && rc2[pc2[r]] == r
  {
    if r < P {
      PivotFact(pivotCol, rowOfCol, P, c, rows, nCols, r);
      assert pc2[r] == pivotCol[r];
      assert pivotCol[r] < c;
      assert pivotCol[r] != c;
      assert rc2[pc2[r]] == rowOfCol[pivotCol[r]];
      assert rowOfCol[pivotCol[r]] == r;
      assert pc2[r] < col2;
    } else {
      assert r == P;
      assert pc2[r] == c;
      assert rc2[c] == P;
      assert 0 <= c < col2;
      assert c < |rc2|;
    }
  }

  forall j | (0 <= j < nCols && j < |rc2|)
    ensures rc2[j] == -1 ||
      (0 <= rc2[j] < np && rc2[j] < |pc2| && pc2[rc2[j]] == j)
  {
    if j == c {
      assert rc2[j] == P;
      assert 0 <= P < np;
      assert pc2[P] == c;
    } else {
      assert rc2[j] == rowOfCol[j];
      RowOfFact(pivotCol, rowOfCol, P, c, rows, nCols, j);
      if rowOfCol[j] == -1 {
        assert rc2[j] == -1;
      } else {
        var rr := rowOfCol[j];
        assert 0 <= rr < P;
        assert rr != P;
        assert pc2[rr] == pivotCol[rr];
        assert pivotCol[rr] == j;
        assert rr < np;
      }
    }
  }

  forall j | (col2 <= j < nCols && j < |rc2|)
    ensures rc2[j] == -1
  {
    assert j != c && j >= c;
    assert rc2[j] == rowOfCol[j];
    RowOfFact(pivotCol, rowOfCol, P, c, rows, nCols, j);
  }
  assert PivotOK(pc2, rc2, np, col2, rows, nCols);

  forall r | (0 <= r < np && r < |aug| && r < |pc2|)
    ensures 0 <= pc2[r] < col2 && pc2[r] < nCols && pc2[r] < |aug[r]| &&
      aug[r][pc2[r]] == 1 &&
      (forall i :: 0 <= i < rows && i < |aug| && i != r && pc2[r] < |aug[i]| ==>
        aug[i][pc2[r]] == 0)
  {
    if r < P {
      assert pc2[r] == pivotCol[r];
      assert P <= rows;
      assert r < |pivotCol|;
      UnitFact(aug, pivotCol, P, c, rows, nCols, r);
      assert pivotCol[r] < c;
      assert pc2[r] < col2;
      forall i | (0 <= i < rows && i < |aug| && i != r && pc2[r] < |aug[i]|)
        ensures aug[i][pc2[r]] == 0
      {
        assert aug[i][pivotCol[r]] == 0;
      }
    } else {
      assert r == P;
      assert pc2[r] == c;
      AugBit(aug, rows, nCols, r, c);
      assert c < |aug[r]|;
      assert aug[r][c] == 1;
      forall i | (0 <= i < rows && i < |aug| && i != r && c < |aug[i]|)
        ensures aug[i][c] == 0
      {
        assert aug[i][c] == 0;
      }
    }
  }
  assert UnitPivots(aug, pc2, np, col2, rows, nCols);

  forall r | 0 <= r < |aug| && np <= r < rows
    ensures forall j :: 0 <= j < col2 && j < |aug[r]| ==> aug[r][j] == 0
  {
    forall j | 0 <= j < col2 && j < |aug[r]|
      ensures aug[r][j] == 0
    {
      assert r >= P + 1;
      assert r != P;
      if j < c {
        assert 0 <= r < rows;
        assert P <= r;
        assert j <= nCols;
        LowerFact(aug, P, c, rows, nCols, r, j);
      } else {
        assert j == c;
        assert 0 <= r < rows;
        assert aug[r][c] == 0;
      }
    }
  }
  assert LowerZeros(aug, np, col2, rows, nCols);
  assert RREFState(aug, pc2, rc2, np, col2, rows, nCols);
}

lemma XFromIndex(aug: seq<seq<int>>, rowOfCol: seq<int>, nCols: int, j: int)
  requires |rowOfCol| == nCols
  requires nCols >= 1
  requires 0 <= j < nCols
  requires forall t :: 0 <= t < nCols ==>
    rowOfCol[t] == -1 || (0 <= rowOfCol[t] < |aug| && nCols < |aug[rowOfCol[t]]|)
  ensures XFrom(aug, rowOfCol, nCols)[j] ==
    (if rowOfCol[j] == -1 then 0 else aug[rowOfCol[j]][nCols])
{
}

lemma {:vcs_split_on_every_assert} ConstructedSolves(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  rows: int,
  nCols: int)
  requires RREFState(aug, pivotCol, rowOfCol, numPivots, nCols, rows, nCols)
  requires forall r :: numPivots <= r < rows ==> aug[r][nCols] == 0
  ensures SolvesAug(aug, XFrom(aug, rowOfCol, nCols), nCols)
{
  StateParts(aug, pivotCol, rowOfCol, numPivots, nCols, rows, nCols);
  assert 0 <= numPivots <= rows;
  assert (forall j :: 0 <= j < nCols ==>
    rowOfCol[j] == -1 || (0 <= rowOfCol[j] < |aug| && nCols < |aug[rowOfCol[j]]|)) by {
    forall j | (0 <= j < nCols)
      ensures rowOfCol[j] == -1 || (0 <= rowOfCol[j] < |aug| && nCols < |aug[rowOfCol[j]]|)
    {
      RowOfFact(pivotCol, rowOfCol, numPivots, nCols, rows, nCols, j);
      if rowOfCol[j] != -1 {
        var rr := rowOfCol[j];
        assert 0 <= rr < numPivots <= rows;
        assert rr < |aug|;
        AugBit(aug, rows, nCols, rr, nCols);
        assert |aug[rr]| == nCols + 1;
        assert nCols < |aug[rr]|;
      }
    }
  }
  var x := XFrom(aug, rowOfCol, nCols);
  assert |x| == nCols;

  forall j | (0 <= j < nCols)
    ensures IsBit(x[j])
  {
    XFromIndex(aug, rowOfCol, nCols, j);
    if rowOfCol[j] == -1 {
      assert x[j] == 0;
    } else {
      var rr := rowOfCol[j];
      assert x[j] == aug[rr][nCols];
      AugBit(aug, rows, nCols, rr, nCols);
      assert IsBit(aug[rr][nCols]);
    }
  }
  assert is_binary_vector(x);

  forall i | (0 <= i < rows)
    ensures |aug[i]| == nCols + 1 &&
      spec_dot_product_gf2(aug[i], x, nCols - 1) == aug[i][nCols]
  {
    AugBit(aug, rows, nCols, i, nCols);
    assert |aug[i]| == nCols + 1;
    if i >= numPivots {
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[i]| && j < |x| ==>
        aug[i][j] == 0 || x[j] == 0) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[i]|) && j < (|x|))
          ensures aug[i][j] == 0 || x[j] == 0
        {
          assert 0 <= j < nCols;
          assert 0 <= i < rows;
          assert numPivots <= i;
          assert 0 <= j <= nCols;
          LowerFact(aug, numPivots, nCols, rows, nCols, i, j);
        }
      }
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[i]| && j < |x| ==>
        IsBit(aug[i][j]) && IsBit(x[j])) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[i]|) && j < (|x|))
          ensures IsBit(aug[i][j]) && IsBit(x[j])
        {
          AugBit(aug, rows, nCols, i, j);
          assert IsBit(x[j]);
        }
      }
      ZeroDot(aug[i], x, nCols - 1);
      assert aug[i][nCols] == 0;
      assert spec_dot_product_gf2(aug[i], x, nCols - 1) == 0;
    } else {
      PivotFact(pivotCol, rowOfCol, numPivots, nCols, rows, nCols, i);
      assert i < |pivotCol|;
      assert numPivots <= rows;
      UnitFact(aug, pivotCol, numPivots, nCols, rows, nCols, i);
      var p := pivotCol[i];
      assert 0 <= p < nCols;
      assert rowOfCol[p] == i;
      XFromIndex(aug, rowOfCol, nCols, p);
      assert x[p] == aug[i][nCols];
      assert aug[i][p] == 1;
      assert IsBit(x[p]);
      assert 0 <= p <= nCols - 1;

      forall j | (0 <= j <= nCols - 1 && j != p && j < (|aug[i]|) && j < (|x|))
        ensures aug[i][j] == 0 || x[j] == 0
      {
        assert 0 <= j < nCols;
        RowOfFact(pivotCol, rowOfCol, numPivots, nCols, rows, nCols, j);
        if rowOfCol[j] == -1 {
          XFromIndex(aug, rowOfCol, nCols, j);
          assert x[j] == 0;
        } else {
          var r2 := rowOfCol[j];
          assert 0 <= r2 < numPivots;
          assert pivotCol[r2] == j;
          if r2 == i {
            assert pivotCol[i] == j;
            assert pivotCol[i] == p;
            assert false;
          }
          assert r2 != i;
          assert r2 < |pivotCol|;
          UnitFact(aug, pivotCol, numPivots, nCols, rows, nCols, r2);
          assert aug[i][j] == 0;
        }
      }
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[i]| && j < |x| ==>
        IsBit(aug[i][j]) && IsBit(x[j])) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[i]|) && j < (|x|))
          ensures IsBit(aug[i][j]) && IsBit(x[j])
        {
          AugBit(aug, rows, nCols, i, j);
          assert IsBit(x[j]);
        }
      }
      DotProductSingle(aug[i], x, nCols - 1, p);
      assert spec_dot_product_gf2(aug[i], x, nCols - 1) == x[p];
      assert x[p] == aug[i][nCols];
    }
  }
}

lemma {:vcs_split_on_every_assert} InconsistentNone(
  matrix: seq<seq<int>>,
  b: seq<int>,
  aug: seq<seq<int>>,
  nCols: int,
  bad: int)
  requires SameSol(matrix, b, aug, nCols)
  requires AugOK(aug, |aug|, nCols)
  requires |matrix| == |b| == |aug|
  requires |matrix| > 0 && nCols == |matrix[0]| && nCols >= 1
  requires 0 <= bad < |aug|
  requires forall j :: 0 <= j < nCols ==> aug[bad][j] == 0
  requires aug[bad][nCols] == 1
  ensures forall x: seq<int> ::
    (|x| == |matrix[0]| && is_binary_vector(x)) ==> !is_solution(matrix, b, x)
{
  reveal SameSol();
  forall x | ((|x|) == nCols && is_binary_vector(x))
    ensures !is_solution(matrix, b, x)
  {
    if is_solution(matrix, b, x) {
      assert SolvesAug(aug, x, nCols);
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[bad]| && j < |x| ==>
        aug[bad][j] == 0 || x[j] == 0) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[bad]|) && j < (|x|))
          ensures aug[bad][j] == 0 || x[j] == 0
        {
          assert aug[bad][j] == 0;
        }
      }
      assert (forall j :: 0 <= j <= nCols - 1 && j < |aug[bad]| && j < |x| ==>
        IsBit(aug[bad][j]) && IsBit(x[j])) by {
        forall j | (0 <= j <= nCols - 1 && j < (|aug[bad]|) && j < (|x|))
          ensures IsBit(aug[bad][j]) && IsBit(x[j])
        {
          AugBit(aug, |aug|, nCols, bad, j);
          assert x[j] == 0 || x[j] == 1;
        }
      }
      ZeroDot(aug[bad], x, nCols - 1);
      assert spec_dot_product_gf2(aug[bad], x, nCols - 1) == 0;
      assert spec_dot_product_gf2(aug[bad], x, nCols - 1) == aug[bad][nCols];
      assert aug[bad][nCols] == 1;
      assert false;
    }
  }
}

method {:vcs_split_on_every_assert} solve_linear_system_gf2(matrix: seq<seq<int>>, b: seq<int>) returns (res: Option<seq<int>>)
  requires |matrix| > 0
  requires |matrix[0]| > 0
  requires |matrix| == |b|
  requires |matrix| <= 100
  requires |matrix[0]| <= 100
  requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
  requires is_binary_vector(b)
  ensures match res
    case Some(x) => is_solution(matrix, b, x)
    case None =>
      forall x: seq<int> ::
        (|x| == |matrix[0]| && is_binary_vector(x))
        ==> !is_solution(matrix, b, x)
{
  var rows := |matrix|;
  var nCols := |matrix[0]|;
  var aug := BuildAug(matrix, b);
  var pivotCol := seq(rows, i => -1);
  var rowOfCol := seq(nCols, j => -1);
  forall r | (0 <= r < rows)
    ensures pivotCol[r] == -1
  {
  }
  forall j | (0 <= j < nCols)
    ensures rowOfCol[j] == -1
  {
  }
  InitState(matrix, b, aug, pivotCol, rowOfCol);

  var numPivots := 0;
  var c := 0;
  while c < nCols
    invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
    invariant SameSol(matrix, b, aug, nCols)
    decreases nCols - c
  {
    var sel := numPivots;
    while sel < rows && aug[sel][c] == 0
      invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
      invariant numPivots <= sel <= rows
      invariant forall t :: numPivots <= t < sel ==> aug[t][c] == 0
      decreases rows - sel
    {
      sel := sel + 1;
    }

    if sel == rows {
      assert forall r :: numPivots <= r < rows ==> aug[r][c] == 0;
      var newC := c + 1;
      NoPivotAdvance(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert RREFState(aug, pivotCol, rowOfCol, numPivots, newC, rows, nCols);
      c := newC;
    } else {
      StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      AugBit(aug, rows, nCols, sel, c);
      assert aug[sel][c] != 0;
      assert aug[sel][c] == 1;
      assert numPivots < rows;

      var swapped := SwapRows(aug, numPivots, sel);
      AfterSwap(aug, pivotCol, rowOfCol, numPivots, c, sel, rows, nCols);
      SameSolAfterSwap(matrix, b, aug, numPivots, sel, nCols);
      assert RREFState(swapped, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert SameSol(matrix, b, swapped, nCols);
      assert swapped[numPivots][c] == 1;
      aug := swapped;

      var i := 0;
      assert ClearedBefore(aug, numPivots, c, 0) by {
        forall t | 0 <= t < 0 && t < |aug| && 0 <= c < |aug[t]| && t != numPivots
          ensures aug[t][c] == 0
        {
        }
      }
      while i < rows
        invariant 0 <= i <= rows
        invariant numPivots < rows
        invariant 0 <= c < nCols
        invariant RREFState(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols)
        invariant SameSol(matrix, b, aug, nCols)
        invariant aug[numPivots][c] == 1
        invariant ClearedBefore(aug, numPivots, c, i)
        decreases rows - i
      {
        if i != numPivots && aug[i][c] == 1 {
          var newAug := AddRowTo(aug, i, numPivots);
          AddElimStep(aug, pivotCol, rowOfCol, numPivots, c, i, rows, nCols);
          SameSolAfterAdd(matrix, b, aug, i, numPivots, nCols);
          assert RREFState(newAug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
          assert SameSol(matrix, b, newAug, nCols);
          assert newAug[numPivots][c] == 1;
          assert newAug[i][c] == 0;
          assert |newAug| == |aug|;
          assert ClearedBefore(newAug, numPivots, c, i) by {
            forall t | 0 <= t < i && t < |newAug| && 0 <= c < |newAug[t]| && t != numPivots
              ensures newAug[t][c] == 0
            {
              assert t != i;
              assert t < |aug|;
              AddRowAt(aug, i, numPivots, t);
              assert newAug[t] == aug[t];
              assert 0 <= c < |aug[t]|;
              assert aug[t][c] == 0;
            }
          }
          aug := newAug;
          assert ClearedBefore(aug, numPivots, c, i + 1) by {
            forall t | 0 <= t < i + 1 && t < |aug| && 0 <= c < |aug[t]| && t != numPivots
              ensures aug[t][c] == 0
            {
              if t < i {
                assert aug[t][c] == 0;
              } else {
                assert t == i;
                assert aug[i][c] == 0;
              }
            }
          }
        } else if i != numPivots {
          StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
          AugBit(aug, rows, nCols, i, c);
          assert aug[i][c] != 1;
          assert aug[i][c] == 0;
          assert ClearedBefore(aug, numPivots, c, i + 1) by {
            forall t | 0 <= t < i + 1 && t < |aug| && 0 <= c < |aug[t]| && t != numPivots
              ensures aug[t][c] == 0
            {
              if t < i {
                assert aug[t][c] == 0;
              } else {
                assert t == i;
                assert aug[i][c] == 0;
              }
            }
          }
        } else {
          assert i == numPivots;
          assert ClearedBefore(aug, numPivots, c, i + 1) by {
            forall t | 0 <= t < i + 1 && t < |aug| && 0 <= c < |aug[t]| && t != numPivots
              ensures aug[t][c] == 0
            {
              assert t != numPivots;
              assert t < i;
              assert aug[t][c] == 0;
            }
          }
        }
        i := i + 1;
      }

      assert i == rows;
      assert forall t :: 0 <= t < rows && t != numPivots ==> aug[t][c] == 0 by {
        forall t | 0 <= t < rows && t != numPivots
          ensures aug[t][c] == 0
        {
          StateParts(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
          AugBit(aug, rows, nCols, t, c);
          assert t < |aug|;
          assert 0 <= c < |aug[t]|;
          assert t < i;
          assert aug[t][c] == 0;
        }
      }
      assert aug[numPivots][c] == 1;
      var newPc := pivotCol[numPivots := c];
      var newRc := rowOfCol[c := numPivots];
      var newNp := numPivots + 1;
      var newC := c + 1;
      RecordPivot(aug, pivotCol, rowOfCol, numPivots, c, rows, nCols);
      assert RREFState(aug, newPc, newRc, newNp, newC, rows, nCols);
      pivotCol := newPc;
      rowOfCol := newRc;
