  requires s[a] < s[b]
  ensures dp[a] + 1 <= dp[b]
{
  assert dp[a] + 1 <= dp[b];
}

lemma PrefixOKEq(
    s: seq<int>,
    dp1: seq<int>, paths1: seq<seq<int>>,
    dp2: seq<int>, paths2: seq<seq<int>>,
    n: int, m: int
  )
  requires |dp1| == |paths1|
  requires |dp2| == |paths2|
  requires dp1 == dp2
  requires paths1 == paths2
  requires 0 <= n <= |dp1|
  requires n <= |s|
  requires n == m
  requires PrefixOK(s, dp1, paths1, n)
  ensures PrefixOK(s, dp2, paths2, m)
{
  forall k | 0 <= k < m
    ensures dp2[k] >= 1 && dp2[k] <= k + 1 && is_valid_is(s, paths2[k]) && |paths2[k]| == dp2[k] && LastOrNeg(paths2[k]) == k
  {
    assert k < n;
    PrefixAt(s, dp1, paths1, n, k);
    assert dp2[k] == dp1[k];
    assert paths2[k] == paths1[k];
    assert is_valid_is(s, paths2[k]);
    assert LastOrNeg(paths2[k]) == LastOrNeg(paths1[k]);
  }
  forall a, b | 0 <= a < b < m && s[a] < s[b]
    ensures dp2[a] + 1 <= dp2[b]
  {
    assert a < b < n;
    assert dp2[a] == dp1[a];
    assert dp2[b] == dp1[b];
    PrefixDom(s, dp1, paths1, n, a, b);
  }
  AssemblePrefix(s, dp2, paths2, m);
}

lemma PrefixOKEmpty(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>)
  requires |dp| == 0 && |paths| == 0
  ensures PrefixOK(s, dp, paths, 0)
{
  assert forall k :: 0 <= k < 0 ==> dp[k] >= 1 && dp[k] <= k + 1 && is_valid_is(s, paths[k]) && |paths[k]| == dp[k] && LastOrNeg(paths[k]) == k;
  assert forall a, b :: 0 <= a < b < 0 && s[a] < s[b] ==> dp[a] + 1 <= dp[b];
  AssemblePrefix(s, dp, paths, 0);
}

predicate GoodChoice(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>, i: int, j: int, best: int, bestPred: int)
  requires |dp| == i && |paths| == i
  requires 0 <= j <= i
  requires i < |s|
{
  best >= 1 && best <= i + 1 &&
  (
    (bestPred == -1 && best == 1)
    ||
    (
      0 <= bestPred < j &&
      dp[bestPred] >= 1 &&
      s[bestPred] < s[i] &&
      best == dp[bestPred] + 1 &&
      is_valid_is(s, paths[bestPred]) &&
      |paths[bestPred]| == dp[bestPred] &&
      LastOrNeg(paths[bestPred]) == bestPred
    )
  )
}

lemma ChoiceBase(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>, i: int, j: int)
  requires |dp| == i && |paths| == i
  requires 0 <= j <= i
  requires i < |s|
  ensures GoodChoice(s, dp, paths, i, j, 1, -1)
{
  assert 1 <= i + 1;
  assert GoodChoice(s, dp, paths, i, j, 1, -1);
}

lemma ChoiceFromWitness(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, j: int, best: int, bestPred: int
  )
  requires |dp| == i && |paths| == i
  requires 0 <= j <= i
  requires i < |s|
  requires best >= 1
  requires best <= i + 1
  requires 0 <= bestPred < j
  requires dp[bestPred] >= 1
  requires s[bestPred] < s[i]
  requires best == dp[bestPred] + 1
  requires is_valid_is(s, paths[bestPred])
  requires |paths[bestPred]| == dp[bestPred]
  requires LastOrNeg(paths[bestPred]) == bestPred
  ensures GoodChoice(s, dp, paths, i, j, best, bestPred)
{
  assert GoodChoice(s, dp, paths, i, j, best, bestPred);
}

lemma GoodChoiceFacts(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, j: int, best: int, bestPred: int
  )
  requires |dp| == i && |paths| == i
  requires 0 <= j <= i
  requires i < |s|
  requires GoodChoice(s, dp, paths, i, j, best, bestPred)
  ensures best >= 1
  ensures best <= i + 1
  ensures bestPred == -1 ==> best == 1
  ensures bestPred != -1 ==> 0 <= bestPred < j && dp[bestPred] >= 1
  ensures 0 <= bestPred < j && dp[bestPred] >= 1 ==>
    s[bestPred] < s[i] &&
    best == dp[bestPred] + 1 &&
    is_valid_is(s, paths[bestPred]) &&
    |paths[bestPred]| == dp[bestPred] &&
    LastOrNeg(paths[bestPred]) == bestPred
{
  if bestPred == -1 {
    assert best == 1;
  } else {
    assert 0 <= bestPred < j;
    assert dp[bestPred] >= 1;
    assert s[bestPred] < s[i];
    assert best == dp[bestPred] + 1;
    assert is_valid_is(s, paths[bestPred]);
    assert |paths[bestPred]| == dp[bestPred];
    assert LastOrNeg(paths[bestPred]) == bestPred;
  }
}

lemma ChoiceAdvanceJ(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, j: int, nextJ: int, best: int, bestPred: int
  )
  requires |dp| == i && |paths| == i
  requires 0 <= j < nextJ <= i
  requires i < |s|
  requires GoodChoice(s, dp, paths, i, j, best, bestPred)
  ensures GoodChoice(s, dp, paths, i, nextJ, best, bestPred)
{
  GoodChoiceFacts(s, dp, paths, i, j, best, bestPred);
  if bestPred == -1 {
    assert best == 1;
    ChoiceBase(s, dp, paths, i, nextJ);
  } else {
    assert 0 <= bestPred < j;
    assert bestPred < nextJ;
    assert dp[bestPred] >= 1;
    assert s[bestPred] < s[i];
    assert best == dp[bestPred] + 1;
    assert is_valid_is(s, paths[bestPred]);
    assert |paths[bestPred]| == dp[bestPred];
    assert LastOrNeg(paths[bestPred]) == bestPred;
    assert best >= 1;
    assert best <= i + 1;
    ChoiceFromWitness(s, dp, paths, i, nextJ, best, bestPred);
  }
}

lemma GoodChoiceEq(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, j1: int, j2: int, best: int, bestPred: int
  )
  requires |dp| == i && |paths| == i
  requires 0 <= j1 <= i
  requires 0 <= j2 <= i
  requires i < |s|
  requires j1 == j2
  requires GoodChoice(s, dp, paths, i, j1, best, bestPred)
  ensures GoodChoice(s, dp, paths, i, j2, best, bestPred)
{
  GoodChoiceFacts(s, dp, paths, i, j1, best, bestPred);
  if bestPred == -1 {
    assert best == 1;
    ChoiceBase(s, dp, paths, i, j2);
  } else {
    assert 0 <= bestPred < j1;
    assert bestPred < j2;
    assert dp[bestPred] >= 1;
    assert s[bestPred] < s[i];
    assert best == dp[bestPred] + 1;
    assert is_valid_is(s, paths[bestPred]);
    assert |paths[bestPred]| == dp[bestPred];
    assert LastOrNeg(paths[bestPred]) == bestPred;
    assert best >= 1;
    assert best <= i + 1;
    ChoiceFromWitness(s, dp, paths, i, j2, best, bestPred);
  }
}

