{
  assert dp[m] + 1 <= best;
}

lemma StepCovers(s: seq<int>, dp: seq<int>, elem: int, j: int, best: int)
  requires |dp| == elem
  requires 0 <= j < elem < |s|
  requires forall m :: 0 <= m < j && s[m] < s[elem] ==> dp[m] + 1 <= best
  requires s[j] < s[elem] ==> dp[j] + 1 <= best
  ensures forall m :: 0 <= m < j + 1 && s[m] < s[elem] ==> dp[m] + 1 <= best
{
  forall m | 0 <= m < j + 1 && s[m] < s[elem]
    ensures dp[m] + 1 <= best
  {
    if m < j {
      assert dp[m] + 1 <= best;
    } else {
      assert m == j;
      assert s[j] < s[elem] ==> dp[j] + 1 <= best;
