lemma ProveSpec(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>, result: int, wit: int)
  requires |dp| == |s| && |paths| == |s|
  requires PrefixOK(s, dp, paths, |s|)
  requires 0 <= wit < |s|
  requires result == dp[wit]
  requires forall k :: 0 <= k < |s| ==> dp[k] <= result
  ensures result >= 0
  ensures forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result
  ensures exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result
{
  PrefixAt(s, dp, paths, |s|, wit);
  assert dp[wit] >= 1;
  assert result >= 1;
  assert result >= 0;

  assert forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result by {
    forall sub: seq<int> | is_valid_is(s, sub) && |sub| > 0
      ensures |sub| <= result
    {
      UpperBound(s, dp, paths, sub);
      var last := sub[|sub| - 1];
      InBounds(s, sub, |sub| - 1);
      assert |sub| <= dp[last];
      assert 0 <= last < |s|;
      assert last < |dp|;
      LeResult(dp, |s|, result, last);
      assert dp[last] <= result;
      assert |sub| <= result;
    }
  };

  var witness := paths[wit];
  assert is_valid_is(s, witness);
  assert |witness| == dp[wit];
  assert |witness| == result;
  assert exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result;
}

method longest_increasing_subsequence(s: seq<int>) returns (result: int)
  requires |s| <= 0x7FFFFFFFFFFFFFFF
  ensures result >= 0
  ensures forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result
  ensures exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result
{
  if |s| == 0 {
    result := 0;
    ghost var e: seq<int> := [];
    EmptyValid(s, e);
    assert is_valid_is(s, e);
    assert |e| == result;
    assert exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result;
    assert forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result by {
      forall sub: seq<int> | is_valid_is(s, sub) && |sub| > 0
        ensures |sub| <= result
      {
        InBounds(s, sub, 0);
        assert 0 <= sub[0] < |s|;
        assert |s| == 0;
        assert false;
      }
    };
    return;
  }

  var dp: seq<int> := [];
  ghost var paths: seq<seq<int>> := [];
  var i: int := 0;
  PrefixOKEmpty(s, dp, paths);

  while i < |s|
    invariant 0 <= i <= |s|
    invariant |dp| == i && |paths| == i
    invariant PrefixOK(s, dp, paths, i)
    decreases |s| - i
  {
    var best := 1;
    var bestPred := -1;
    var j := 0;
    InitChoice(s, dp, paths, i);

    while j < i
      invariant 0 <= i < |s|
      invariant |dp| == i && |paths| == i
      invariant 0 <= j <= i
      invariant PrefixOK(s, dp, paths, i)
      invariant GoodChoice(s, dp, paths, i, j, best, bestPred)
      invariant forall m :: 0 <= m < j && s[m] < s[i] ==> dp[m] + 1 <= best
      decreases i - j
    {
      var nextJ := j + 1;
      assert j < i;
      assert nextJ == j + 1;
      assert nextJ <= i;

      if s[j] < s[i] && dp[j] + 1 > best {
        ghost var oldBest := best;
        assert oldBest == best;
        assert forall m :: 0 <= m < j && s[m] < s[i] ==> dp[m] + 1 <= oldBest;
        PrefixAt(s, dp, paths, i, j);
        assert dp[j] >= 1;
        assert dp[j] <= j + 1;
        assert j + 1 <= i;
        assert dp[j] <= i;
        assert dp[j] + 1 <= i + 1;
        assert oldBest < dp[j] + 1;
        assert is_valid_is(s, paths[j]);
        assert |paths[j]| == dp[j];
        assert LastOrNeg(paths[j]) == j;
        best := dp[j] + 1;
        bestPred := j;
        assert best == dp[j] + 1;
        assert best == dp[bestPred] + 1;
        assert oldBest < best;
        assert best >= 1;
        assert best <= i + 1;
        assert 0 <= bestPred < nextJ;
        assert dp[bestPred] >= 1;
        assert s[bestPred] < s[i];
        assert is_valid_is(s, paths[bestPred]);
        assert |paths[bestPred]| == dp[bestPred];
        assert LastOrNeg(paths[bestPred]) == bestPred;
        StepImproves(s, dp, i, j, oldBest, best);
        RenameCov(s, dp, i, j + 1, nextJ, best);
        ChoiceFromWitness(s, dp, paths, i, nextJ, best, bestPred);
      } else {
        if s[j] < s[i] {
          assert dp[j] + 1 <= best;
        }
        assert s[j] < s[i] ==> dp[j] + 1 <= best;
        StepCovers(s, dp, i, j, best);
        RenameCov(s, dp, i, j + 1, nextJ, best);
        ChoiceAdvanceJ(s, dp, paths, i, j, nextJ, best, bestPred);
      }

      assert GoodChoice(s, dp, paths, i, nextJ, best, bestPred);
      assert forall m :: 0 <= m < nextJ && s[m] < s[i] ==> dp[m] + 1 <= best;
      j := nextJ;
      GoodChoiceEq(s, dp, paths, i, nextJ, j, best, bestPred);
      RenameCov(s, dp, i, nextJ, j, best);
    }

    assert j <= i;
    assert !(j < i);
    assert j == i;
    GoodChoiceEq(s, dp, paths, i, j, i, best, bestPred);
    RenameCov(s, dp, i, j, i, best);

    ghost var i0 := i;
    ghost var newPath: seq<int> := ExtendOK(s, dp, paths, i, best, bestPred);
    var dpNext := dp + [best];
