        (view_opt(h.left) + {v}) + view_opt(h.right) + {h.val};
        view_opt(h.left) + view_opt(h.right) + {h.val} + {v};
        h.view() + {v};
    }
}

lemma PlusRightView(h: Node, h2: Node, newR: Node, v: int)
    requires h2.val == h.val && h2.right == Some(newR) && h2.left == h.left
    requires newR.view() == view_opt(h.right) + {v}
    ensures h2.view() == h.view() + {v}
{
    ViewDef(h);
    ViewDef(h2);
    ViewOptDef(h2.right);
    assert h2.view() == view_opt(h.left) + newR.view() + {h.val};
    calc {
        h2.view();
        view_opt(h.left) + (view_opt(h.right) + {v}) + {h.val};
        view_opt(h.left) + view_opt(h.right) + {h.val} + {v};
        h.view() + {v};
    }
}

lemma SubsetLt(s: set<int>, whole: set<int>, bound: int)
    requires s <= whole
    requires forall y :: y in whole ==> y < bound
    ensures forall y :: y in s ==> y < bound
{
    forall y | y in s
        ensures y < bound
    {
        assert y in whole;
    }
}

lemma SubsetGt(s: set<int>, whole: set<int>, bound: int)
    requires s <= whole
    requires forall y :: y in whole ==> y > bound
    ensures forall y :: y in s ==> y > bound
{
    forall y | y in s
        ensures y < bound || y > bound
    {
        assert y in whole;
        assert y > bound;
    }
}

method {:vcs_split_on_every_assert} RotateLeft(h: Node) returns (res: Node)
    requires h.right.Some?
    requires h.right.value.is_red
    requires h.right.value.is_llrbt()
    requires !IsRedOpt(h.right.value.left)
    requires is_llrbt_opt(h.left)
    requires !IsRedOpt(h.left)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures res.is_red == h.is_red
    ensures res.black_height() == BhOpt(h.left) + (if h.is_red then 0 else 1)
{
    var x := h.right.value;
    var newH := Node(h.val, true, h.left, x.left);
    res := Node(x.val, h.is_red, Some(newH), x.right);

    LLRBTParts(x);
    LeftLt(h);
    RightGt(h);
    LeftLt(x);
    RightGt(x);
    ViewDef(x);
    assert x.val in x.view();
    assert forall y :: y in x.view() ==> y > h.val;
    assert x.val > h.val;

    var H := BhOpt(h.left);
    assert x.black_height() == H;
    assert BhOpt(x.left) == H;
    assert BhOpt(x.right) == H;
    assert BhOpt(newH.left) == H;
    assert BhOpt(newH.right) == H;

    forall y | y in view_opt(x.left)
        ensures y > h.val
    {
        ViewDef(x);
        assert y in x.view();
        assert y > h.val;
    }
    assert forall y :: y in view_opt(h.left) ==> y < h.val;
    if newH.left.Some? {
        ViewOptDef(newH.left);
        assert newH.left.value.is_bst();
        assert forall y :: y in newH.left.value.view() ==> y < newH.val;
    }
    if newH.right.Some? {
        ViewOptDef(newH.right);
        LLRBTOptDef(x.left);
        assert x.left.value.is_llrbt();
        LLRBTDef(x.left.value);
        assert newH.right.value.is_bst();
        assert forall y :: y in newH.right.value.view() ==> y > newH.val;
    }
    ProveBstFromBounds(newH);
    LLRBTOptDef(newH.left);
    LLRBTOptDef(newH.right);
    assert is_llrbt_opt(newH.left);
    assert is_llrbt_opt(newH.right);
    assert !IsRedOpt(newH.right);
    assert !(newH.left.Some? && newH.left.value.is_red && IsRedOpt(newH.left.value.left));
    ConstructLLRBT(newH);
    assert newH.black_height() == H;

    ViewDef(newH);
    forall y | y in newH.view()
        ensures y < x.val
    {
        assert newH.view() == view_opt(h.left) + view_opt(x.left) + {h.val};
        if y in view_opt(h.left) {
            assert y < h.val;
            assert y < x.val;
        } else if y in view_opt(x.left) {
            assert y < x.val;
        } else {
            assert y == h.val;
            assert y < x.val;
        }
    }
    assert forall y :: y in view_opt(x.right) ==> y > x.val;
    if res.left.Some? {
        assert res.left.value == newH;
        assert newH.is_bst();
        ViewOptDef(res.left);
        assert forall y :: y in res.left.value.view() ==> y < res.val;
    }
    if res.right.Some? {
        ViewOptDef(res.right);
        assert res.right.value.is_bst();
        assert forall y :: y in res.right.value.view() ==> y > res.val;
    }
    ProveBstFromBounds(res);

    assert !IsRedOpt(x.right);
    assert !IsRedOpt(res.right);
    assert res.left.Some?;
    assert res.left.value.is_red;
    assert !IsRedOpt(res.left.value.left);
    assert !(res.left.Some? && res.left.value.is_red && IsRedOpt(res.left.value.left));
    LLRBTOptDef(res.left);
    LLRBTOptDef(res.right);
    assert is_llrbt_opt(res.left);
    assert is_llrbt_opt(res.right);
    assert BhOpt(res.left) == newH.black_height() == H;
    assert BhOpt(res.right) == H;
    ConstructLLRBT(res);
    assert res.is_red == h.is_red;
    assert res.black_height() == H + (if h.is_red then 0 else 1);

    ViewDef(h);
    ViewDef(res);
    calc {
        res.view();
        newH.view() + view_opt(x.right) + {x.val};
        (view_opt(h.left) + view_opt(x.left) + {h.val}) + view_opt(x.right) + {x.val};
        view_opt(h.left) + (view_opt(x.left) + view_opt(x.right) + {x.val}) + {h.val};
        view_opt(h.left) + x.view() + {h.val};
        h.view();
    }
}

method {:vcs_split_on_every_assert} RotateRight(h: Node) returns (res: Node)
    requires h.left.Some?
    requires h.left.value.is_red
    requires h.left.value.is_llrbt()
    requires IsRedOpt(h.left.value.left)
    requires is_llrbt_opt(h.right)
    requires !IsRedOpt(h.right)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.view() == h.view()
    ensures res.is_bst()
    ensures res.is_red == h.is_red
    ensures res.left.Some? && res.right.Some?
    ensures res.left.value.is_red && res.right.value.is_red
    ensures res.left.value.is_llrbt() && res.right.value.is_llrbt()
    ensures !IsRedOpt(res.left.value.left)
    ensures res.left.value.black_height() == BhOpt(h.left)
    ensures res.right.value.black_height() == BhOpt(h.left)
    ensures res.black_height() == BhOpt(h.left) + (if h.is_red then 0 else 1)
