method {:vcs_split_on_every_assert} FlipColors(h: Node) returns (res: Node)
    requires h.left.Some? && h.right.Some?
    requires h.left.value.is_red && h.right.value.is_red
    requires h.left.value.is_llrbt() && h.right.value.is_llrbt()
    requires h.is_bst()
    requires h.left.value.black_height() == h.right.value.black_height()
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures !IsRedOpt(res.left) && !IsRedOpt(res.right)
    ensures res.is_red == !h.is_red
    ensures res.black_height() == h.left.value.black_height() + (if h.is_red then 2 else 1)
{
    var l := h.left.value;
    var r := h.right.value;
    var l2 := Node(l.val, false, l.left, l.right);
    var r2 := Node(r.val, false, r.left, r.right);
    res := Node(h.val, !h.is_red, Some(l2), Some(r2));

    LLRBTParts(l);
    LLRBTParts(r);
    TransferBst(l, l2);
    TransferBst(r, r2);
    TransferView(l, l2);
    TransferView(r, r2);

    assert is_llrbt_opt(l2.left) && is_llrbt_opt(l2.right);
    assert !IsRedOpt(l2.right);
    assert !(l2.left.Some? && l2.left.value.is_red && IsRedOpt(l2.left.value.left));
    assert BhOpt(l2.left) == BhOpt(l.left);
    assert BhOpt(l2.right) == BhOpt(l.right);
    assert BhOpt(l2.left) == BhOpt(l2.right) && BhOpt(l2.left) != -1;
    ConstructLLRBT(l2);
    assert l.is_red;
    assert l.black_height() == BhOpt(l.left);
    assert !l2.is_red;
    assert l2.black_height() == BhOpt(l.left) + 1;
    assert l2.black_height() == l.black_height() + 1;

    assert is_llrbt_opt(r2.left) && is_llrbt_opt(r2.right);
    assert !IsRedOpt(r2.right);
    assert !(r2.left.Some? && r2.left.value.is_red && IsRedOpt(r2.left.value.left));
    assert BhOpt(r2.left) == BhOpt(r2.right) && BhOpt(r2.left) != -1;
    ConstructLLRBT(r2);
    assert r2.black_height() == r.black_height() + 1;
    assert l2.black_height() == r2.black_height();

    BstBounds(h);
    forall y | y in l2.view()
        ensures y < h.val
    {
        assert y in l.view();
        assert y < h.val;
    }
    forall y | y in r2.view()
        ensures y > h.val
    {
        assert y in r.view();
        assert y > h.val;
    }
    assert l2.is_bst() && r2.is_bst();
    assert forall y :: y in res.left.value.view() ==> y < res.val;
    assert forall y :: y in res.right.value.view() ==> y > res.val;
    ProveBstFromBounds(res);

    assert !l2.is_red && !r2.is_red;
    IsRedOptDef(res.left);
    IsRedOptDef(res.right);
    assert !IsRedOpt(res.left) && !IsRedOpt(res.right);
    assert !(res.left.Some? && res.left.value.is_red && IsRedOpt(res.left.value.left));
    LLRBTOptDef(res.left);
    LLRBTOptDef(res.right);
    assert BhOpt(res.left) == l2.black_height();
    assert BhOpt(res.right) == r2.black_height();
    ConstructLLRBT(res);

    var H := l.black_height();
    assert l2.black_height() == H + 1;
    if h.is_red {
        assert !res.is_red;
        assert res.black_height() == (H + 1) + 1;
    } else {
        assert res.is_red;
        assert res.black_height() == H + 1;
    }
    assert res.is_red == !h.is_red;

    ViewDef(h);
    ViewDef(res);
    calc {
        res.view();
        l2.view() + r2.view() + {res.val};
        l.view() + r.view() + {h.val};
        h.view();
    }
}

method {:vcs_split_on_every_assert} FixAfterLeft(h: Node) returns (res: Node)
    requires h.left.Some?
    requires h.left.value.is_llrbt()
    requires is_llrbt_opt(h.right)
    requires !IsRedOpt(h.right)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures res.black_height() == BhAfter(BhOpt(h.left), h.is_red, h.left.value.is_red && IsRedOpt(h.left.value.left) && h.is_red)
    ensures !h.is_red ==> !RootDoubleRed(res)
{
    var L := h.left.value;
    var H := BhOpt(h.left);
    if L.is_red && IsRedOpt(L.left) {
        var rotated := RotateRight(h);
        assert rotated.left.value.black_height() == H;
        assert rotated.right.value.black_height() == H;
        assert rotated.is_red == h.is_red;
        assert rotated.is_bst();
        res := FlipColors(rotated);
        assert res.view() == rotated.view() == h.view();
        assert res.black_height() == H + (if h.is_red then 2 else 1);
        assert !IsRedOpt(res.left);
        assert !RootDoubleRed(res);
        if h.is_red {
            assert BhAfter(H, true, true) == H + 2;
            assert res.black_height() == BhAfter(H, h.is_red, true);
        } else {
            BhAfterFalse(H, false);
            assert res.black_height() == BhAfter(H, h.is_red, false);
        }
        assert (L.is_red && IsRedOpt(L.left) && h.is_red) == h.is_red;
        assert res.black_height() == BhAfter(H, h.is_red, L.is_red && IsRedOpt(L.left) && h.is_red);
    } else {
        res := h;
        LLRBTOptDef(h.left);
        assert is_llrbt_opt(h.left);
        assert !(h.left.Some? && h.left.value.is_red && IsRedOpt(h.left.value.left));
        ConstructLLRBT(h);
        BhAfterFalse(H, h.is_red);
        assert h.black_height() == BhAfter(H, h.is_red, false);
        assert !(L.is_red && IsRedOpt(L.left) && h.is_red);
        assert BhAfter(H, h.is_red, false) == BhAfter(H, h.is_red, L.is_red && IsRedOpt(L.left) && h.is_red);
        if !h.is_red {
            assert !res.is_red;
            assert !RootDoubleRed(res);
        }
    }
}

method {:vcs_split_on_every_assert} FixAfterRight(h: Node) returns (res: Node)
    requires h.right.Some?
    requires h.right.value.is_llrbt()
    requires is_llrbt_opt(h.left)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    requires h.right.value.is_red ==> !IsRedOpt(h.right.value.left)
