    }
}

method {:vcs_split_on_every_assert} insert(tree: Option<Node>, v: int) returns (res: Node)
    requires is_llrbt_opt(tree)
    ensures res.view() == view_opt(tree) + {v}
    ensures res.is_llrbt()
    ensures tree.None? ==> res.black_height() == 1
    ensures tree.Some? && !RootDoubleRed(tree.value) ==> res.black_height() == tree.value.black_height()
    ensures tree.None? || (tree.Some? && !tree.value.is_red) ==> !RootDoubleRed(res)
    decreases tree
{
    match tree {
        case None =>
            res := Node(v, true, None, None);
            ViewOptDef(res.left);
            ViewOptDef(res.right);
            LLRBTOptDef(res.left);
            LLRBTOptDef(res.right);
            assert is_llrbt_opt(res.left) && is_llrbt_opt(res.right);
            assert !IsRedOpt(res.left) && !IsRedOpt(res.right);
            assert BhOpt(res.left) == 1 && BhOpt(res.right) == 1;
            ProveBstFromBounds(res);
            ConstructLLRBT(res);
            ViewDef(res);
            assert res.view() == {v};
            ViewOptDef(tree);
            assert view_opt(tree) == {};
            assert res.view() == view_opt(tree) + {v};
            assert res.black_height() == 1;
            assert !RootDoubleRed(res);

        case Some(h) =>
            LLRBTOptDef(tree);
            assert h.is_llrbt();
            LLRBTParts(h);
            ViewOptDef(tree);
            assert view_opt(tree) == h.view();

            if v < h.val {
                var newL := insert(h.left, v);
                assert newL.is_llrbt();
                assert newL.view() == view_opt(h.left) + {v};
                if h.left.None? {
                    assert newL.black_height() == 1;
                    assert !RootDoubleRed(newL);
                } else {
                    assert !RootDoubleRed(h.left.value);
                    assert newL.black_height() == h.left.value.black_height();
                    if !h.left.value.is_red {
                        assert !RootDoubleRed(newL);
                    }
                }
                assert newL.black_height() == BhOpt(h.left);

                var h2 := Node(h.val, h.is_red, Some(newL), h.right);
                LLRBTDef(newL);
                assert newL.is_bst();
                LeftLt(h);
                RightGt(h);
                forall y | y in newL.view()
