lemma AllLt3(a: set<int>, b: set<int>, v: int, bound: int)
    requires forall y :: y in a ==> y < bound
    requires forall y :: y in b ==> y < bound
    requires v < bound
    ensures forall y :: y in a + b + {v} ==> y < bound
{
    forall y | y in a + b + {v}
        ensures y < bound
    {
        if y in a {
            assert y < bound;
        } else if y in b {
            assert y < bound;
        } else {
            assert y == v;
        }
    }
}

lemma AllGt3(a: set<int>, b: set<int>, v: int, bound: int)
    requires forall y :: y in a ==> y > bound
    requires forall y :: y in b ==> y > bound
    requires v > bound
    ensures forall y :: y in a + b + {v} ==> y > bound
{
    forall y | y in a + b + {v}
        ensures y > bound
    {
        if y in a {
            assert y > bound;
        } else if y in b {
            assert y > bound;
        } else {
            assert y == v;
        }
    }
}

