lemma PlusLeftView(h: Node, h2: Node, newL: Node, v: int)
    requires h2.val == h.val && h2.left == Some(newL) && h2.right == h.right
    requires newL.view() == view_opt(h.left) + {v}
    ensures h2.view() == h.view() + {v}
{
    ViewDef(h);
    ViewDef(h2);
    ViewOptDef(h2.left);
    assert h2.view() == newL.view() + view_opt(h.right) + {h.val};
    calc {
        h2.view();
        (view_opt(h.left) + {v}) + view_opt(h.right) + {h.val};
        view_opt(h.left) + view_opt(h.right) + {h.val} + {v};
        h.view() + {v};
    }
}

lemma PlusRightView(h: Node, h2: Node, newR: Node, v: int)
    requires h2.val == h.val && h2.right == Some(newR) && h2.left == h.left
    requires newR.view() == view_opt(h.right) + {v}
    ensures h2.view() == h.view() + {v}
{
    ViewDef(h);
    ViewDef(h2);
    ViewOptDef(h2.right);
    assert h2.view() == view_opt(h.left) + newR.view() + {h.val};
    calc {
        h2.view();
        view_opt(h.left) + (view_opt(h.right) + {v}) + {h.val};
        view_opt(h.left) + view_opt(h.right) + {h.val} + {v};
        h.view() + {v};
    }
}

lemma SubsetLt(s: set<int>, whole: set<int>, bound: int)
    requires s <= whole
    requires forall y :: y in whole ==> y < bound
    ensures forall y :: y in s ==> y < bound
{
    forall y | y in s
        ensures y < bound
    {
        assert y in whole;
    }
}

lemma SubsetGt(s: set<int>, whole: set<int>, bound: int)
    requires s <= whole
    requires forall y :: y in whole ==> y > bound
    ensures forall y :: y in s ==> y > bound
{
    forall y | y in s
        ensures y < bound || y > bound
    {
        assert y in whole;
        assert y > bound;
    }
}

method {:vcs_split_on_every_assert} RotateLeft(h: Node) returns (res: Node)
    requires h.right.Some?
    requires h.right.value.is_red
    requires h.right.value.is_llrbt()
    requires !IsRedOpt(h.right.value.left)
    requires is_llrbt_opt(h.left)
    requires !IsRedOpt(h.left)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures res.is_red == h.is_red
    ensures res.black_height() == BhOpt(h.left) + (if h.is_red then 0 else 1)
{
    var x := h.right.value;
    var newH := Node(h.val, true, h.left, x.left);
    res := Node(x.val, h.is_red, Some(newH), x.right);

    LLRBTParts(x);
    LeftLt(h);
    RightGt(h);
    LeftLt(x);
    RightGt(x);
    ViewDef(x);
    assert x.val in x.view();
    assert forall y :: y in x.view() ==> y > h.val;
    assert x.val > h.val;

    var H := BhOpt(h.left);
    assert x.black_height() == H;
    assert BhOpt(x.left) == H;
    assert BhOpt(x.right) == H;
    assert BhOpt(newH.left) == H;
    assert BhOpt(newH.right) == H;

    forall y | y in view_opt(x.left)
        ensures y > h.val
    {
        ViewDef(x);
        assert y in x.view();
        assert y > h.val;
    }
    assert forall y :: y in view_opt(h.left) ==> y < h.val;
    if newH.left.Some? {
        ViewOptDef(newH.left);
        assert newH.left.value.is_bst();
        assert forall y :: y in newH.left.value.view() ==> y < newH.val;
    }
    if newH.right.Some? {
        ViewOptDef(newH.right);
        LLRBTOptDef(x.left);
        assert x.left.value.is_llrbt();
        LLRBTDef(x.left.value);
        assert newH.right.value.is_bst();
        assert forall y :: y in newH.right.value.view() ==> y > newH.val;
    }
    ProveBstFromBounds(newH);
    LLRBTOptDef(newH.left);
    LLRBTOptDef(newH.right);
    assert is_llrbt_opt(newH.left);
    assert is_llrbt_opt(newH.right);
    assert !IsRedOpt(newH.right);
    assert !(newH.left.Some? && newH.left.value.is_red && IsRedOpt(newH.left.value.left));
    ConstructLLRBT(newH);
    assert newH.black_height() == H;

    ViewDef(newH);
    forall y | y in newH.view()
        ensures y < x.val
    {
        assert newH.view() == view_opt(h.left) + view_opt(x.left) + {h.val};
        if y in view_opt(h.left) {
            assert y < h.val;
            assert y < x.val;
        } else if y in view_opt(x.left) {
            assert y < x.val;
        } else {
            assert y == h.val;
            assert y < x.val;
        }
    }
    assert forall y :: y in view_opt(x.right) ==> y > x.val;
    if res.left.Some? {
        assert res.left.value == newH;
        assert newH.is_bst();
        ViewOptDef(res.left);
        assert forall y :: y in res.left.value.view() ==> y < res.val;
    }
    if res.right.Some? {
        ViewOptDef(res.right);
        assert res.right.value.is_bst();
        assert forall y :: y in res.right.value.view() ==> y > res.val;
    }
    ProveBstFromBounds(res);

    assert !IsRedOpt(x.right);
    assert !IsRedOpt(res.right);
    assert res.left.Some?;
    assert res.left.value.is_red;
    assert !IsRedOpt(res.left.value.left);
    assert !(res.left.Some? && res.left.value.is_red && IsRedOpt(res.left.value.left));
    LLRBTOptDef(res.left);
    LLRBTOptDef(res.right);
    assert is_llrbt_opt(res.left);
    assert is_llrbt_opt(res.right);
    assert BhOpt(res.left) == newH.black_height() == H;
    assert BhOpt(res.right) == H;
    ConstructLLRBT(res);
    assert res.is_red == h.is_red;
    assert res.black_height() == H + (if h.is_red then 0 else 1);

    ViewDef(h);
    ViewDef(res);
    calc {
        res.view();
        newH.view() + view_opt(x.right) + {x.val};
        (view_opt(h.left) + view_opt(x.left) + {h.val}) + view_opt(x.right) + {x.val};
        view_opt(h.left) + (view_opt(x.left) + view_opt(x.right) + {x.val}) + {h.val};
        view_opt(h.left) + x.view() + {h.val};
        h.view();
    }
}

method {:vcs_split_on_every_assert} RotateRight(h: Node) returns (res: Node)
    requires h.left.Some?
    requires h.left.value.is_red
    requires h.left.value.is_llrbt()
    requires IsRedOpt(h.left.value.left)
    requires is_llrbt_opt(h.right)
    requires !IsRedOpt(h.right)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.view() == h.view()
    ensures res.is_bst()
    ensures res.is_red == h.is_red
    ensures res.left.Some? && res.right.Some?
    ensures res.left.value.is_red && res.right.value.is_red
    ensures res.left.value.is_llrbt() && res.right.value.is_llrbt()
    ensures !IsRedOpt(res.left.value.left)
    ensures res.left.value.black_height() == BhOpt(h.left)
    ensures res.right.value.black_height() == BhOpt(h.left)
    ensures res.black_height() == BhOpt(h.left) + (if h.is_red then 0 else 1)
{
    var x := h.left.value;
    assert x.left.Some?;
    var a := x.left.value;
    var newH := Node(h.val, true, x.right, h.right);
    res := Node(x.val, h.is_red, Some(a), Some(newH));

    LLRBTParts(x);
    LLRBTParts(a);
    LeftLt(h);
    RightGt(h);
    LeftLt(x);
    RightGt(x);
    ViewDef(x);
    assert x.val in x.view();
    assert forall y :: y in x.view() ==> y < h.val;
    assert x.val < h.val;

    var H := BhOpt(h.left);
    assert x.black_height() == H;
    assert a.black_height() == H;
    assert BhOpt(x.right) == H;
    assert BhOpt(h.right) == H;

    forall y | y in view_opt(x.right)
        ensures y < h.val
    {
        ViewDef(x);
        assert y in x.view();
        assert y < h.val;
    }
    assert forall y :: y in view_opt(h.right) ==> y > h.val;

    if newH.left.Some? {
        ViewOptDef(newH.left);
        LLRBTOptDef(x.right);
        assert newH.left.value.is_llrbt();
        LLRBTDef(newH.left.value);
        assert newH.left.value.is_bst();
        assert forall y :: y in newH.left.value.view() ==> y < newH.val;
    }
    if newH.right.Some? {
        ViewOptDef(newH.right);
        LLRBTOptDef(h.right);
        assert newH.right.value.is_llrbt();
        LLRBTDef(newH.right.value);
        assert newH.right.value.is_bst();
        assert forall y :: y in newH.right.value.view() ==> y > newH.val;
    }
    ProveBstFromBounds(newH);
    LLRBTOptDef(newH.left);
    LLRBTOptDef(newH.right);
    assert !IsRedOpt(x.right);
    assert !IsRedOpt(newH.right);
    assert !(newH.left.Some? && newH.left.value.is_red && IsRedOpt(newH.left.value.left));
    assert BhOpt(newH.left) == H && BhOpt(newH.right) == H;
    ConstructLLRBT(newH);
    assert newH.is_llrbt();
    assert newH.is_red;
    assert newH.black_height() == H;

    assert !IsRedOpt(a.left);
    assert a.is_red;
    assert a.is_llrbt();

    assert forall y :: y in a.view() ==> y < x.val;
    ViewDef(newH);
    forall y | y in newH.view()
        ensures y > x.val
    {
        assert newH.view() == view_opt(x.right) + view_opt(h.right) + {h.val};
        if y in view_opt(x.right) {
            assert y > x.val;
        } else if y == h.val {
            assert y > x.val;
        } else {
            assert y in view_opt(h.right);
            assert y > h.val;
            assert h.val > x.val;
            assert y > x.val;
        }
    }
    ViewOptDef(res.left);
    ViewOptDef(res.right);
    assert res.left.value.is_bst();
    assert res.right.value.is_bst();
    assert forall y :: y in res.left.value.view() ==> y < res.val;
    assert forall y :: y in res.right.value.view() ==> y > res.val;
    ProveBstFromBounds(res);

    BhOf(res);
    assert BhOpt(res.left) == a.black_height() == H;
    assert BhOpt(res.right) == newH.black_height() == H;
    assert res.black_height() == H + (if h.is_red then 0 else 1);
    assert res.is_red == h.is_red;
    assert !IsRedOpt(a.left);

    ViewDef(h);
    ViewDef(res);
    calc {
        res.view();
        a.view() + newH.view() + {x.val};
        a.view() + (view_opt(x.right) + view_opt(h.right) + {h.val}) + {x.val};
        (a.view() + view_opt(x.right) + {x.val}) + view_opt(h.right) + {h.val};
        x.view() + view_opt(h.right) + {h.val};
        h.view();
    }
}

method {:vcs_split_on_every_assert} FlipColors(h: Node) returns (res: Node)
    requires h.left.Some? && h.right.Some?
    requires h.left.value.is_red && h.right.value.is_red
    requires h.left.value.is_llrbt() && h.right.value.is_llrbt()
    requires h.is_bst()
    requires h.left.value.black_height() == h.right.value.black_height()
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures !IsRedOpt(res.left) && !IsRedOpt(res.right)
    ensures res.is_red == !h.is_red
    ensures res.black_height() == h.left.value.black_height() + (if h.is_red then 2 else 1)
{
    var l := h.left.value;
    var r := h.right.value;
    var l2 := Node(l.val, false, l.left, l.right);
    var r2 := Node(r.val, false, r.left, r.right);
    res := Node(h.val, !h.is_red, Some(l2), Some(r2));

    LLRBTParts(l);
    LLRBTParts(r);
    TransferBst(l, l2);
    TransferBst(r, r2);
    TransferView(l, l2);
    TransferView(r, r2);

    assert is_llrbt_opt(l2.left) && is_llrbt_opt(l2.right);
    assert !IsRedOpt(l2.right);
    assert !(l2.left.Some? && l2.left.value.is_red && IsRedOpt(l2.left.value.left));
    assert BhOpt(l2.left) == BhOpt(l.left);
    assert BhOpt(l2.right) == BhOpt(l.right);
    assert BhOpt(l2.left) == BhOpt(l2.right) && BhOpt(l2.left) != -1;
    ConstructLLRBT(l2);
    assert l.is_red;
    assert l.black_height() == BhOpt(l.left);
    assert !l2.is_red;
    assert l2.black_height() == BhOpt(l.left) + 1;
    assert l2.black_height() == l.black_height() + 1;

    assert is_llrbt_opt(r2.left) && is_llrbt_opt(r2.right);
    assert !IsRedOpt(r2.right);
    assert !(r2.left.Some? && r2.left.value.is_red && IsRedOpt(r2.left.value.left));
    assert BhOpt(r2.left) == BhOpt(r2.right) && BhOpt(r2.left) != -1;
    ConstructLLRBT(r2);
    assert r2.black_height() == r.black_height() + 1;
    assert l2.black_height() == r2.black_height();

    BstBounds(h);
    forall y | y in l2.view()
        ensures y < h.val
    {
        assert y in l.view();
        assert y < h.val;
    }
    forall y | y in r2.view()
        ensures y > h.val
    {
        assert y in r.view();
        assert y > h.val;
    }
    assert l2.is_bst() && r2.is_bst();
    assert forall y :: y in res.left.value.view() ==> y < res.val;
    assert forall y :: y in res.right.value.view() ==> y > res.val;
    ProveBstFromBounds(res);

    assert !l2.is_red && !r2.is_red;
    IsRedOptDef(res.left);
    IsRedOptDef(res.right);
    assert !IsRedOpt(res.left) && !IsRedOpt(res.right);
    assert !(res.left.Some? && res.left.value.is_red && IsRedOpt(res.left.value.left));
    LLRBTOptDef(res.left);
    LLRBTOptDef(res.right);
    assert BhOpt(res.left) == l2.black_height();
    assert BhOpt(res.right) == r2.black_height();
    ConstructLLRBT(res);

    var H := l.black_height();
    assert l2.black_height() == H + 1;
    if h.is_red {
        assert !res.is_red;
        assert res.black_height() == (H + 1) + 1;
    } else {
        assert res.is_red;
        assert res.black_height() == H + 1;
    }
    assert res.is_red == !h.is_red;

    ViewDef(h);
    ViewDef(res);
    calc {
        res.view();
        l2.view() + r2.view() + {res.val};
        l.view() + r.view() + {h.val};
        h.view();
    }
}

method {:vcs_split_on_every_assert} FixAfterLeft(h: Node) returns (res: Node)
    requires h.left.Some?
    requires h.left.value.is_llrbt()
    requires is_llrbt_opt(h.right)
    requires !IsRedOpt(h.right)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures res.black_height() == BhAfter(BhOpt(h.left), h.is_red, h.left.value.is_red && IsRedOpt(h.left.value.left) && h.is_red)
    ensures !h.is_red ==> !RootDoubleRed(res)
{
    var L := h.left.value;
    var H := BhOpt(h.left);
    if L.is_red && IsRedOpt(L.left) {
        var rotated := RotateRight(h);
        assert rotated.left.value.black_height() == H;
        assert rotated.right.value.black_height() == H;
        assert rotated.is_red == h.is_red;
        assert rotated.is_bst();
        res := FlipColors(rotated);
        assert res.view() == rotated.view() == h.view();
        assert res.black_height() == H + (if h.is_red then 2 else 1);
        assert !IsRedOpt(res.left);
        assert !RootDoubleRed(res);
        if h.is_red {
            assert BhAfter(H, true, true) == H + 2;
            assert res.black_height() == BhAfter(H, h.is_red, true);
        } else {
            BhAfterFalse(H, false);
            assert res.black_height() == BhAfter(H, h.is_red, false);
        }
        assert (L.is_red && IsRedOpt(L.left) && h.is_red) == h.is_red;
        assert res.black_height() == BhAfter(H, h.is_red, L.is_red && IsRedOpt(L.left) && h.is_red);
    } else {
        res := h;
        LLRBTOptDef(h.left);
        assert is_llrbt_opt(h.left);
        assert !(h.left.Some? && h.left.value.is_red && IsRedOpt(h.left.value.left));
        ConstructLLRBT(h);
        BhAfterFalse(H, h.is_red);
        assert h.black_height() == BhAfter(H, h.is_red, false);
        assert !(L.is_red && IsRedOpt(L.left) && h.is_red);
        assert BhAfter(H, h.is_red, false) == BhAfter(H, h.is_red, L.is_red && IsRedOpt(L.left) && h.is_red);
        if !h.is_red {
            assert !res.is_red;
            assert !RootDoubleRed(res);
        }
    }
}

method {:vcs_split_on_every_assert} FixAfterRight(h: Node) returns (res: Node)
    requires h.right.Some?
    requires h.right.value.is_llrbt()
    requires is_llrbt_opt(h.left)
    requires h.is_bst()
    requires BhOpt(h.left) == BhOpt(h.right)
    requires BhOpt(h.left) != -1
    requires h.right.value.is_red ==> !IsRedOpt(h.right.value.left)
    requires !(h.left.Some? && h.left.value.is_red && IsRedOpt(h.left.value.left))
    ensures res.is_llrbt()
    ensures res.view() == h.view()
    ensures res.black_height() == BhAfter(BhOpt(h.left), h.is_red, IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red)
    ensures !h.is_red ==> !RootDoubleRed(res)
{
    var H := BhOpt(h.left);
    if IsRedOpt(h.right) && !IsRedOpt(h.left) {
        assert h.right.value.is_red;
        assert !IsRedOpt(h.right.value.left);
        res := RotateLeft(h);
        assert res.view() == h.view();
        assert res.is_red == h.is_red;
        assert res.black_height() == H + (if h.is_red then 0 else 1);
        BhAfterFalse(H, h.is_red);
        assert !(IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red);
        assert res.black_height() == BhAfter(H, h.is_red, false);
        assert res.black_height() == BhAfter(H, h.is_red, IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red);
        if !h.is_red {
            assert !res.is_red;
            assert !RootDoubleRed(res);
        }
    } else if IsRedOpt(h.right) && IsRedOpt(h.left) {
        assert h.left.Some? && h.right.Some?;
        var L := h.left.value;
        var R := h.right.value;
        assert L.is_red && R.is_red;
        assert L.is_llrbt() && R.is_llrbt();
        assert !IsRedOpt(L.left);
        assert L.black_height() == R.black_height() == H;
        res := FlipColors(h);
        assert res.view() == h.view();
        assert res.black_height() == H + (if h.is_red then 2 else 1);
        assert !IsRedOpt(res.left);
        assert !RootDoubleRed(res);
        if h.is_red {
            assert BhAfter(H, true, true) == H + 2;
            assert res.black_height() == BhAfter(H, h.is_red, true);
        } else {
            BhAfterFalse(H, false);
            assert res.black_height() == BhAfter(H, h.is_red, false);
        }
        assert (IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red) == h.is_red;
        assert res.black_height() == BhAfter(H, h.is_red, IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red);
    } else {
        assert !IsRedOpt(h.right);
        res := h;
        LLRBTOptDef(h.right);
        assert is_llrbt_opt(h.right);
        ConstructLLRBT(h);
        BhAfterFalse(H, h.is_red);
        assert !(IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red);
        assert h.black_height() == BhAfter(H, h.is_red, false);
        assert res.black_height() == BhAfter(H, h.is_red, IsRedOpt(h.right) && IsRedOpt(h.left) && h.is_red);
        if !h.is_red {
            assert !res.is_red;
            assert !RootDoubleRed(res);
        }
    }
