method {:vcs_split_on_every_assert} insert(tree: Option<Node>, v: int) returns (res: Node)
    requires is_llrbt_opt(tree)
    ensures res.view() == view_opt(tree) + {v}
    ensures res.is_llrbt()
    ensures tree.None? ==> res.black_height() == 1
    ensures tree.Some? && !RootDoubleRed(tree.value) ==> res.black_height() == tree.value.black_height()
    ensures tree.None? || (tree.Some? && !tree.value.is_red) ==> !RootDoubleRed(res)
    decreases tree
{
    match tree {
        case None =>
            res := Node(v, true, None, None);
            ViewOptDef(res.left);
            ViewOptDef(res.right);
            LLRBTOptDef(res.left);
            LLRBTOptDef(res.right);
            assert is_llrbt_opt(res.left) && is_llrbt_opt(res.right);
            assert !IsRedOpt(res.left) && !IsRedOpt(res.right);
            assert BhOpt(res.left) == 1 && BhOpt(res.right) == 1;
            ProveBstFromBounds(res);
            ConstructLLRBT(res);
            ViewDef(res);
            assert res.view() == {v};
            ViewOptDef(tree);
            assert view_opt(tree) == {};
            assert res.view() == view_opt(tree) + {v};
            assert res.black_height() == 1;
            assert !RootDoubleRed(res);

        case Some(h) =>
            LLRBTOptDef(tree);
            assert h.is_llrbt();
            LLRBTParts(h);
            ViewOptDef(tree);
            assert view_opt(tree) == h.view();

            if v < h.val {
                var newL := insert(h.left, v);
                assert newL.is_llrbt();
                assert newL.view() == view_opt(h.left) + {v};
                if h.left.None? {
                    assert newL.black_height() == 1;
                    assert !RootDoubleRed(newL);
                } else {
                    assert !RootDoubleRed(h.left.value);
                    assert newL.black_height() == h.left.value.black_height();
                    if !h.left.value.is_red {
                        assert !RootDoubleRed(newL);
                    }
                }
                assert newL.black_height() == BhOpt(h.left);

                var h2 := Node(h.val, h.is_red, Some(newL), h.right);
                LLRBTDef(newL);
                assert newL.is_bst();
                LeftLt(h);
                RightGt(h);
                forall y | y in newL.view()
                    ensures y < h.val
                {
                    if y in view_opt(h.left) {
                        assert y < h.val;
                    } else {
                        assert y == v;
                    }
                }
                ViewOptDef(h2.left);
                assert forall y :: y in h2.left.value.view() ==> y < h2.val;
                if h2.right.Some? {
                    ViewOptDef(h2.right);
                    assert h2.right.value.is_bst();
                    assert forall y :: y in h2.right.value.view() ==> y > h2.val;
                }
                ProveBstFromBounds(h2);
                assert BhOpt(h2.left) == newL.black_height();
                assert BhOpt(h2.right) == BhOpt(h.right);
                assert BhOpt(h2.left) == BhOpt(h2.right) && BhOpt(h2.left) != -1;
                assert !IsRedOpt(h2.right);
                LLRBTOptDef(h2.right);
                PlusLeftView(h, h2, newL, v);

                res := FixAfterLeft(h2);
                assert res.is_llrbt();
                assert res.view() == h2.view();
                assert res.view() == h.view() + {v};
                assert res.view() == view_opt(tree) + {v};

                var H := BhOpt(h.left);
                var grew := newL.is_red && IsRedOpt(newL.left) && h.is_red;
                assert res.black_height() == BhAfter(H, h.is_red, grew);
                if !RootDoubleRed(h) {
                    if grew {
                        assert h.is_red && !IsRedOpt(h.left);
                        assert h.left.None? || !h.left.value.is_red;
                        assert !RootDoubleRed(newL);
                        assert false;
                    }
                    assert !grew;
                    assert res.black_height() == BhAfter(H, h.is_red, false);
                    assert h.black_height() == BhAfter(H, h.is_red, false);
                    assert res.black_height() == h.black_height();
                }
                if !h.is_red {
                    assert !RootDoubleRed(res);
                }

            } else if h.val < v {
                var newR := insert(h.right, v);
                assert newR.is_llrbt();
                assert newR.view() == view_opt(h.right) + {v};
                assert h.right.None? || !h.right.value.is_red;
                assert !RootDoubleRed(newR);
                if h.right.None? {
                    assert newR.black_height() == 1;
                } else {
                    assert newR.black_height() == h.right.value.black_height();
                }
                assert newR.black_height() == BhOpt(h.right);

                var h2 := Node(h.val, h.is_red, h.left, Some(newR));
                LLRBTDef(newR);
                LeftLt(h);
                RightGt(h);
                forall y | y in newR.view()
                    ensures y > h.val
                {
                    if y in view_opt(h.right) {
                        assert y > h.val;
                    } else {
                        assert y == v;
                    }
                }
                if h2.left.Some? {
                    ViewOptDef(h2.left);
                    assert h2.left.value.is_bst();
                    assert forall y :: y in h2.left.value.view() ==> y < h2.val;
                }
                ViewOptDef(h2.right);
                assert forall y :: y in h2.right.value.view() ==> y > h2.val;
                ProveBstFromBounds(h2);
                assert BhOpt(h2.right) == newR.black_height();
                assert BhOpt(h2.left) == BhOpt(h.left);
                assert BhOpt(h2.left) == BhOpt(h2.right) && BhOpt(h2.left) != -1;
                assert newR.is_red ==> !IsRedOpt(newR.left);
                assert !(h2.left.Some? && h2.left.value.is_red && IsRedOpt(h2.left.value.left));
                LLRBTOptDef(h2.left);
                PlusRightView(h, h2, newR, v);

                res := FixAfterRight(h2);
                assert res.is_llrbt();
                assert res.view() == h.view() + {v};
                assert res.view() == view_opt(tree) + {v};

                var H := BhOpt(h.left);
                var grew := IsRedOpt(h2.right) && IsRedOpt(h2.left) && h.is_red;
                assert res.black_height() == BhAfter(H, h.is_red, grew);
                if !RootDoubleRed(h) {
                    if grew {
                        assert RootDoubleRed(h);
                        assert false;
                    }
                    assert !grew;
                    assert res.black_height() == BhAfter(H, h.is_red, false);
                    assert h.black_height() == BhAfter(H, h.is_red, false);
                    assert res.black_height() == h.black_height();
                }
                if !h.is_red {
                    assert !RootDoubleRed(res);
                }

            } else {
                assert v == h.val;
                res := h;
                ViewDef(h);
                assert v in h.view();
                assert h.view() + {v} == h.view();
                assert res.view() == view_opt(tree) + {v};
                assert res.is_llrbt();
                if !RootDoubleRed(h) {
                    assert res.black_height() == h.black_height();
                }
                if !h.is_red {
                    assert !RootDoubleRed(res);
                }
            }
    }
