    assert t[k] == s[k + 1];
    assert 0 <= k + 1 < |s| && (k + 1) != 0;
    assert s[k + 1] != s[0];
  }

  if u in SeqSet(t) {
    SeqSetWitness(t, u);
    var k :| 0 <= k < |t| && t[k] == u;
    assert t[k] != u;
    assert false;
  }
  assert u !in SeqSet(t);

  forall x: int | x in SeqSet(s)
    ensures x in SeqSet(t) + {u}
  {
    SeqSetWitness(s, x);
    var k :| 0 <= k < |s| && s[k] == x;
    if k == 0 {
      assert x == u;
      assert x in SeqSet(t) + {u};
    } else {
      assert 1 <= k < |s|;
      assert 0 <= k - 1 < |t|;
      assert t[k - 1] == s[(k - 1) + 1];
      assert t[k - 1] == s[k];
      assert t[k - 1] == x;
      SeqSetIndex(t, k - 1);
      assert x in SeqSet(t);
