    if x == u {
      SeqSetIndex(s, 0);
      assert s[0] == u;
      assert u in SeqSet(s);
    } else {
      assert x in SeqSet(t);
      SeqSetWitness(t, x);
      var k :| 0 <= k < |t| && t[k] == x;
      assert 0 <= k + 1 < |s|;
      assert s[k + 1] == t[k];
      assert s[k + 1] == x;
      SeqSetIndex(s, k + 1);
