// Gaussian elimination over GF(2). Row swaps and row additions preserve the
// solution set. A constructed assignment is checked against the reduced system,
// and a 0 = 1 row rules out every candidate.

ghost predicate IsBit(v: int) {
  v == 0 || v == 1
}

ghost function Id(j: int): int { j }

ghost predicate AugOK(aug: seq<seq<int>>, rows: int, nCols: int) {
  |aug| == rows &&
  rows >= 1 &&
  nCols >= 1 &&
  (forall i :: 0 <= i < rows ==>
    |aug[i]| == nCols + 1 &&
    (forall j :: 0 <= j <= nCols ==> IsBit(aug[i][j])))
}

ghost predicate PivotOK(
  pivotCol: seq<int>,
  rowOfCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  |pivotCol| == rows &&
  |rowOfCol| == nCols &&
  0 <= numPivots <= rows &&
  0 <= col <= nCols &&
  (forall r :: numPivots <= r < rows && r < |pivotCol| ==> pivotCol[r] == -1) &&
  (forall r :: 0 <= r < numPivots && r < |pivotCol| ==>
    0 <= pivotCol[r] < col &&
    pivotCol[r] < |rowOfCol| &&
    rowOfCol[pivotCol[r]] == r) &&
  (forall j :: 0 <= j < nCols && j < |rowOfCol| ==>
    rowOfCol[j] == -1 ||
    (0 <= rowOfCol[j] < numPivots &&
     rowOfCol[j] < |pivotCol| &&
     pivotCol[rowOfCol[j]] == j)) &&
  (forall j :: col <= j < nCols && j < |rowOfCol| ==> rowOfCol[j] == -1)
}

ghost predicate UnitPivots(
  aug: seq<seq<int>>,
  pivotCol: seq<int>,
  numPivots: int,
  col: int,
  rows: int,
  nCols: int)
{
  forall r :: 0 <= r < numPivots && r < |aug| && r < |pivotCol| ==>
    0 <= pivotCol[r] < col &&
    pivotCol[r] < nCols &&
    pivotCol[r] < |aug[r]| &&
    aug[r][pivotCol[r]] == 1 &&
    (forall i :: 0 <= i < rows && i < |aug| && i != r && pivotCol[r] < |aug[i]| ==>
      aug[i][pivotCol[r]] == 0)
