lemma TwoTimesNotOne(k: int)
  ensures 2 * k != 1
{
  if k <= 0 {
    assert 2 * k <= 0;
  } else {
    assert k >= 1;
    assert 2 * k >= 2;
  }
}

lemma TwoTimesNotNegOne(k: int)
  ensures 2 * k != -1
