lemma DivModUnique2(n: int, q: int, r: int)
  requires n == 2 * q + r
  requires 0 <= r < 2
  ensures n % 2 == r
  ensures n / 2 == q
{
  var q0 := n / 2;
  var r0 := n % 2;
  assert n == 2 * q0 + r0;
  assert 0 <= r0 < 2;
  if r != r0 {
    var diffR := r0 - r;
    assert -1 <= diffR <= 1;
    assert diffR != 0;
    assert diffR == -1 || diffR == 1;
    if diffR == 1 {
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == -1;
      assert 2 * (q - q0) == -1;
      TwoTimesNotNegOne(q - q0);
      assert false;
    } else {
      assert diffR == -1;
      assert 2 * (q - q0) == r - r0;
      assert r - r0 == 1;
      assert 2 * (q - q0) == 1;
      TwoTimesNotOne(q - q0);
      assert false;
    }
  }
  assert r == r0;
  assert 2 * q + r == 2 * q0 + r0;
  assert 2 * (q - q0) == 0;
  if q != q0 {
    var m := q - q0;
    assert 2 * m == 0;
    if m > 0 {
      assert m >= 1;
      assert 2 * m >= 2;
      assert false;
    } else {
      assert m <= -1;
      assert 2 * m <= -2;
      assert false;
    }
  }
}

lemma XorPairToSum(a: int, b: int, c: int, d: int)
  requires IsBit(a) && IsBit(b) && IsBit(c) && IsBit(d)
  ensures ((a + b) % 2 + (c + d) % 2) % 2 == (a + b + c + d) % 2
{
  var ab := (a + b) % 2;
  var cd := (c + d) % 2;
  var s := a + b + c + d;
  assert a + b == 2 * ((a + b) / 2) + ab;
  assert c + d == 2 * ((c + d) / 2) + cd;
  assert 0 <= ab < 2;
  assert 0 <= cd < 2;
  assert ab <= 1 && cd <= 1;
  var q1 := (a + b) / 2 + (c + d) / 2;
  var r1 := ab + cd;
  assert s == 2 * q1 + r1;
  assert 0 <= r1 <= 2;
  if r1 < 2 {
    DivModUnique2(s, q1, r1);
    assert s % 2 == r1;
    if r1 == 0 {
      assert (0) % 2 == 0;
    } else {
      assert r1 == 1;
      assert (1) % 2 == 1;
    }
    assert (ab + cd) % 2 == s % 2;
  } else {
    assert r1 == 2;
    assert s == 2 * (q1 + 1) + 0;
    DivModUnique2(s, q1 + 1, 0);
    assert s % 2 == 0;
    assert (2) % 2 == 0;
    assert (ab + cd) % 2 == 0;
  }
}

