lemma StepL(s: seq<int>, i: int, L: int, oldBest: int, bestLen: int, isPal: bool)
  requires is_valid_subrange(s, i, L)
  requires MaxSoFar(s, i, L, oldBest)
  requires oldBest <= bestLen
  requires isPal == is_palindrome(s[i .. i + L])
  requires isPal ==> bestLen >= L
  ensures MaxSoFar(s, i, L + 1, bestLen)
{
  reveal MaxSoFar();
  forall a: int, len: int {:trigger is_valid_subrange(s, a, len)}
    ensures is_valid_subrange(s, a, len) ==>
      (is_palindrome(s[a .. a + len]) && Seen(a, len, i, L + 1) ==>
        len <= bestLen)
  {
    if is_valid_subrange(s, a, len) && is_palindrome(s[a .. a + len]) && Seen(a, len, i, L + 1) {
      if Seen(a, len, i, L) {
        MaxSoFarApplies(s, i, L, oldBest, a, len);
        assert len <= oldBest;
        assert oldBest <= bestLen;
        assert len <= bestLen;
      } else {
        NewSeenIsCurrent(a, len, i, L);
        assert a == i && len == L;
        assert s[a .. a + len] == s[i .. i + L];
        SamePal(s[a .. a + len], s[i .. i + L]);
        assert is_palindrome(s[i .. i + L]);
        assert isPal == is_palindrome(s[i .. i + L]);
        assert isPal;
        assert bestLen >= L;
        assert len == L;
        assert len <= bestLen;
      }
      assert len <= bestLen;
    }
  }
  assert MaxSoFar(s, i, L + 1, bestLen);
}

