        MaxSoFarApplies(s, i, L, bestLen, a, len);
        assert len <= bestLen;
      } else {
        assert !(a < i);
        assert a != i;
        assert a >= i + 1;
        ValidParts(s, a, len);
        assert 0 <= len;
        NoFutureStart(a, len, i);
        assert false;
        assert len <= bestLen;
      }
      assert len <= bestLen;
    }
  }
  assert MaxSoFar(s, i + 1, 0, bestLen);
}

