method CheckPal(s: seq<int>, start: int, len: int) returns (b: bool)
  requires is_valid_subrange(s, start, len)
  ensures b == is_palindrome(s[start .. start + len])
{
  if len == 0 {
    EmptyIsPalindrome(s, start);
    assert s[start .. start + len] == s[start .. start];
    SamePal(s[start .. start], s[start .. start + len]);
    b := true;
    return;
  }
  var k := 0;
  PrefixZero(s, start, len);
  while k < len
    invariant 0 <= k <= len
    invariant PrefixAgrees(s, start, len, k)
    decreases len - k
  {
    IndexInBounds(s, start, len, k);
    var left := s[start + k];
    var right := s[start + len - 1 - k];
    if left != right {
      var t := s[start .. start + len];
      assert |t| == len;
      assert t[k] == s[start + k];
      assert t[k] == left;
      assert t[|t| - 1 - k] == s[start + len - 1 - k];
      assert t[|t| - 1 - k] == right;
      assert t[k] != t[|t| - 1 - k];
      NotPalindromeAt(t, k);
      assert !is_palindrome(t);
      assert t == s[start .. start + len];
      SamePal(t, s[start .. start + len]);
      b := false;
      assert !is_palindrome(s[start .. start + len]);
      return;
    }
    assert s[start + k] == left;
    assert s[start + len - 1 - k] == right;
    assert s[start + k] == s[start + len - 1 - k];
    var knext := k + 1;
    ExtendPrefix(s, start, len, k);
    assert knext == k + 1;
    assert PrefixAgrees(s, start, len, knext);
    k := knext;
  }
  assert k == len;
  SliceIsPalindrome(s, start, len);
  b := true;
}

method longest_palindromic_substring(s: seq<int>) returns (res: (int, int))
  requires
    // CONSTRAINT: Hard limit of 1,000,000.
    // Even with Manacher's expansion (2*N + 1), the required size
    // is ~2,000,001, which fits easily in u32/usize.
    |s| <= 1000000
  ensures
    // Type Constraint: Results must be non-negative (simulating usize)
    res.0 >= 0 && res.1 >= 0
  ensures
    // 1. The result defines a valid substring of the input.
    is_valid_subrange(s, res.0, res.1)
  ensures
    // 2. The substring found is indeed a palindrome.
    is_palindrome(s[res.0 .. res.0 + res.1])
  ensures
    // 3. Maximality: There exists no other valid palindromic substring
    // with a length strictly greater than the result found.
    forall i, len ::
      is_valid_subrange(s, i, len) && is_palindrome(s[i .. i + len])
      ==> len <= res.1
{
  var bestStart := 0;
  var bestLen := 0;
  assert 0 <= |s|;
  ValidFromParts(s, 0, 0);
  EmptyIsPalindrome(s, 0);
  assert is_palindrome(s[0 .. 0]);
  assert s[bestStart .. bestStart + bestLen] == s[0 .. 0];
  SamePal(s[0 .. 0], s[bestStart .. bestStart + bestLen]);
  assert is_palindrome(s[bestStart .. bestStart + bestLen]);
  InitMax(s);

  var i := 0;
  while i < |s|
    invariant 0 <= i <= |s|
    invariant bestStart >= 0 && bestLen >= 0
    invariant is_valid_subrange(s, bestStart, bestLen)
    invariant is_palindrome(s[bestStart .. bestStart + bestLen])
    invariant MaxSoFar(s, i, 0, bestLen)
    decreases |s| - i
  {
    var L := 0;
    while L <= |s| - i
      invariant 0 <= L <= |s| - i + 1
      invariant bestStart >= 0 && bestLen >= 0
      invariant is_valid_subrange(s, bestStart, bestLen)
      invariant is_palindrome(s[bestStart .. bestStart + bestLen])
      invariant MaxSoFar(s, i, L, bestLen)
      decreases |s| - i + 1 - L
    {
      var oldBest := bestLen;
      MaxEq(s, i, L, bestLen, oldBest);

      assert 0 <= i < |s|;
      assert 0 <= L;
      assert L <= |s| - i;
      assert i + L <= |s|;
      ValidFromParts(s, i, L);
      var isPal := CheckPal(s, i, L);
      assert isPal == is_palindrome(s[i .. i + L]);

      if isPal && L > bestLen {
        assert bestLen == oldBest;
        assert L > oldBest;
        assert is_palindrome(s[i .. i + L]);
        assert is_valid_subrange(s, i, L);
        bestStart := i;
        bestLen := L;
        assert bestStart >= 0 && bestLen >= 0;
        assert is_valid_subrange(s, bestStart, bestLen);
        assert s[bestStart .. bestStart + bestLen] == s[i .. i + L];
        SamePal(s[i .. i + L], s[bestStart .. bestStart + bestLen]);
        assert is_palindrome(s[bestStart .. bestStart + bestLen]);
        assert oldBest <= bestLen;
        assert bestLen >= L;
        assert isPal ==> bestLen >= L;
      } else {
        assert bestLen == oldBest;
        assert bestStart >= 0 && bestLen >= 0;
        assert is_valid_subrange(s, bestStart, bestLen);
        assert is_palindrome(s[bestStart .. bestStart + bestLen]);
        if isPal {
          assert !(L > bestLen);
          assert L <= bestLen;
        }
        assert isPal ==> bestLen >= L;
        assert oldBest <= bestLen;
      }
      assert bestStart >= 0 && bestLen >= 0;
      assert is_valid_subrange(s, bestStart, bestLen);
      assert is_palindrome(s[bestStart .. bestStart + bestLen]);
      assert oldBest <= bestLen;
      assert isPal ==> bestLen >= L;

      var Lnext := L + 1;
      StepL(s, i, L, oldBest, bestLen, isPal);
      assert MaxSoFar(s, i, Lnext, bestLen);
      assert 0 <= Lnext <= |s| - i + 1;
      L := Lnext;
    }
    assert L == |s| - i + 1;
    var inext := i + 1;
    AdvanceI(s, i, L, bestLen);
    assert MaxSoFar(s, inext, 0, bestLen);
    assert 0 <= inext <= |s|;
    i := inext;
  }

  assert i == |s|;
  assert MaxSoFar(s, |s|, 0, bestLen);
  assert bestStart >= 0 && bestLen >= 0;
  assert is_valid_subrange(s, bestStart, bestLen);
  assert is_palindrome(s[bestStart .. bestStart + bestLen]);

  res := (bestStart, bestLen);
  assert res.0 == bestStart && res.1 == bestLen;
  assert res.0 >= 0 && res.1 >= 0;
  assert is_valid_subrange(s, res.0, res.1);
  assert s[res.0 .. res.0 + res.1] == s[bestStart .. bestStart + bestLen];
  SamePal(s[bestStart .. bestStart + bestLen], s[res.0 .. res.0 + res.1]);
  assert is_palindrome(s[res.0 .. res.0 + res.1]);
  assert MaxSoFar(s, |s|, 0, res.1);
  assert res.1 >= 0;
  AllBounded(s, res.1);
}
