lemma {:induction false} SeqSetIndex(s: seq<int>, k: int)
  requires 0 <= k < |s|
  ensures s[k] in SeqSet(s)
{
  assert s[k] in set t: int | 0 <= t < |s| :: s[t];
}

lemma {:induction false} SeqSetWitness(s: seq<int>, u: int)
  requires u in SeqSet(s)
  ensures exists k: int :: 0 <= k < |s| && s[k] == u
{
  assert u in set t: int | 0 <= t < |s| :: s[t];
  assert exists k: int :: 0 <= k < |s| && s[k] == u;
}

lemma {:induction false} DistinctTail(s: seq<int>)
  requires |s| >= 1
  requires Distinct(s)
  ensures Distinct(s[1..])
{
  var t := s[1..];
  forall i: int, j: int | 0 <= i < |t| && 0 <= j < |t| && i != j
    ensures t[i] != t[j]
  {
    assert t[i] == s[i + 1];
    assert t[j] == s[j + 1];
    assert 0 <= i + 1 < |s| && 0 <= j + 1 < |s| && i + 1 != j + 1;
    assert s[i + 1] != s[j + 1];
  }
}

lemma {:induction false} BoundsTail(adj: seq<seq<int>>, s: seq<int>)
  requires |s| >= 1
  requires forall k: int :: 0 <= k < |s| ==> 0 <= s[k] < |adj|
  ensures forall k: int :: 0 <= k < |s[1..]| ==> 0 <= s[1..][k] < |adj|
{
  var t := s[1..];
  forall k: int | 0 <= k < |t|
    ensures 0 <= t[k] < |adj|
  {
    assert t[k] == s[k + 1];
    assert 0 <= k + 1 < |s|;
    assert 0 <= s[k + 1] < |adj|;
  }
}

lemma {:induction false} SeqSetDecomp(s: seq<int>)
  requires |s| >= 1
  requires Distinct(s)
  ensures s[0] !in SeqSet(s[1..])
  ensures SeqSet(s) == SeqSet(s[1..]) + {s[0]}
{
  var u := s[0];
  var t := s[1..];
  assert |t| == |s| - 1;

  forall k: int | 0 <= k < |t|
    ensures t[k] != u
  {
    assert t[k] == s[k + 1];
    assert 0 <= k + 1 < |s| && (k + 1) != 0;
    assert s[k + 1] != s[0];
  }

  if u in SeqSet(t) {
    SeqSetWitness(t, u);
    var k :| 0 <= k < |t| && t[k] == u;
    assert t[k] != u;
    assert false;
  }
  assert u !in SeqSet(t);

  forall x: int | x in SeqSet(s)
    ensures x in SeqSet(t) + {u}
  {
    SeqSetWitness(s, x);
    var k :| 0 <= k < |s| && s[k] == x;
    if k == 0 {
      assert x == u;
      assert x in SeqSet(t) + {u};
    } else {
      assert 1 <= k < |s|;
      assert 0 <= k - 1 < |t|;
      assert t[k - 1] == s[(k - 1) + 1];
      assert t[k - 1] == s[k];
      assert t[k - 1] == x;
      SeqSetIndex(t, k - 1);
      assert x in SeqSet(t);
    }
  }

  forall x: int | x in SeqSet(t) + {u}
    ensures x in SeqSet(s)
  {
    if x == u {
      SeqSetIndex(s, 0);
      assert s[0] == u;
      assert u in SeqSet(s);
    } else {
      assert x in SeqSet(t);
      SeqSetWitness(t, x);
      var k :| 0 <= k < |t| && t[k] == x;
      assert 0 <= k + 1 < |s|;
      assert s[k + 1] == t[k];
      assert s[k + 1] == x;
      SeqSetIndex(s, k + 1);
    }
  }
}

lemma {:induction false} SetRemove(s: set<int>, x: int, r: set<int>)
  requires x !in r
  requires s == r + {x}
  ensures r == s - {x}
{
  forall y: int | y in r
    ensures y in s - {x}
  {
    assert y in s;
    assert y != x;
    assert y in s - {x};
  }
  forall y: int | y in s - {x}
    ensures y in r
  {
    assert y in s;
    assert y != x;
    assert y in r + {x};
    assert y in r;
  }
}

ghost function RowEdgeSeq(adj: seq<seq<int>>, u: int): seq<(int, int)>
  requires 0 <= u < |adj|
{
  seq(|adj[u]|, j requires 0 <= j < |adj[u]| => (u, adj[u][j]))
}

lemma {:induction false} RowEdgeSeqAt(adj: seq<seq<int>>, u: int, j: int)
  requires 0 <= u < |adj|
  requires 0 <= j < |adj[u]|
  ensures |RowEdgeSeq(adj, u)| == |adj[u]|
  ensures RowEdgeSeq(adj, u)[j] == (u, adj[u][j])
{
  var row := RowEdgeSeq(adj, u);
  assert |row| == |adj[u]|;
  assert row[j] == (u, adj[u][j]);
}

ghost function AllEdgeSeq(adj: seq<seq<int>>): seq<(int, int)>
  decreases |adj|
{
  if |adj| == 0 then []
  else AllEdgeSeq(adj[..|adj| - 1]) + RowEdgeSeq(adj, |adj| - 1)
}

ghost function SeqImage(s: seq<(int, int)>): set<(int, int)>
{
  set i: int | 0 <= i < |s| :: s[i]
}

lemma {:induction false} SeqImageIndex(s: seq<(int, int)>, i: int)
  requires 0 <= i < |s|
  ensures s[i] in SeqImage(s)
{
  assert s[i] in set t: int | 0 <= t < |s| :: s[t];
}

lemma {:induction false} SeqImageWitness(s: seq<(int, int)>, x: (int, int))
  requires x in SeqImage(s)
  ensures exists i: int :: 0 <= i < |s| && s[i] == x
{
  assert x in set i: int | 0 <= i < |s| :: s[i];
  assert exists i: int :: 0 <= i < |s| && s[i] == x;
}

lemma {:induction false} SeqImageConcat(a: seq<(int, int)>, b: seq<(int, int)>)
  ensures SeqImage(a + b) == SeqImage(a) + SeqImage(b)
{
  var ab := a + b;
  assert |ab| == |a| + |b|;

  forall x: (int, int) | x in SeqImage(ab)
    ensures x in SeqImage(a) + SeqImage(b)
  {
    SeqImageWitness(ab, x);
    var i :| 0 <= i < |ab| && ab[i] == x;
    if i < |a| {
      assert a[i] == ab[i] == x;
      SeqImageIndex(a, i);
      assert x in SeqImage(a);
    } else {
      var k := i - |a|;
      assert |a| <= i < |a| + |b|;
      assert 0 <= k < |b|;
      assert ab[i] == b[k];
      SeqImageIndex(b, k);
      assert x in SeqImage(b);
    }
  }

  forall x: (int, int) | x in SeqImage(a) + SeqImage(b)
    ensures x in SeqImage(ab)
  {
    if x in SeqImage(a) {
      SeqImageWitness(a, x);
      var i :| 0 <= i < |a| && a[i] == x;
      assert 0 <= i < |ab|;
      assert ab[i] == a[i] == x;
      SeqImageIndex(ab, i);
    } else {
      assert x in SeqImage(b);
      SeqImageWitness(b, x);
      var k :| 0 <= k < |b| && b[k] == x;
      assert 0 <= |a| + k < |ab|;
      assert ab[|a| + k] == b[k] == x;
      SeqImageIndex(ab, |a| + k);
    }
  }
}

ghost function PossibleEdges(adj: seq<seq<int>>): set<(int, int)>
{
  SeqImage(AllEdgeSeq(adj))
}

lemma {:induction false} PossibleMember(adj: seq<seq<int>>, u: int, j: int)
  requires 0 <= u < |adj|
  requires 0 <= j < |adj[u]|
  ensures (u, adj[u][j]) in PossibleEdges(adj)
  decreases |adj| - u
{
  var edge := (u, adj[u][j]);
  if u == |adj| - 1 {
    RowEdgeSeqAt(adj, u, j);
    var row := RowEdgeSeq(adj, u);
    assert row[j] == edge;
    SeqImageIndex(row, j);
    assert edge in SeqImage(row);
    var preAdj := adj[..|adj| - 1];
    var pre := AllEdgeSeq(preAdj);
    assert AllEdgeSeq(adj) == pre + row;
    SeqImageConcat(pre, row);
    assert edge in SeqImage(pre) + SeqImage(row);
    assert edge in SeqImage(pre + row);
    assert PossibleEdges(adj) == SeqImage(AllEdgeSeq(adj));
    assert edge in PossibleEdges(adj);
  } else {
    assert u != |adj| - 1;
    assert u < |adj| - 1;
    var preAdj := adj[..|adj| - 1];
    assert |preAdj| == |adj| - 1;
    assert 0 <= u < |preAdj|;
    assert preAdj[u] == adj[u];
    assert |preAdj[u]| == |adj[u]|;
    assert 0 <= j < |preAdj[u]|;
    PossibleMember(preAdj, u, j);
    assert edge in PossibleEdges(preAdj);
    var pre := AllEdgeSeq(preAdj);
    assert PossibleEdges(preAdj) == SeqImage(pre);
    assert edge in SeqImage(pre);
    var row := RowEdgeSeq(adj, |adj| - 1);
    assert AllEdgeSeq(adj) == pre + row;
    SeqImageConcat(pre, row);
    assert edge in SeqImage(pre) + SeqImage(row);
    assert edge in SeqImage(pre + row);
    assert PossibleEdges(adj) == SeqImage(AllEdgeSeq(adj));
    assert edge in PossibleEdges(adj);
  }
}

lemma {:induction false} IndexInSeqSet(n: int, k: int)
  requires n >= 0 && 0 <= k < n
  ensures k in SeqSet(LeftSeq(n))
{
  LeftSeqProps(n);
  var s := LeftSeq(n);
  assert |s| == n;
  assert s[k] == k;
  SeqSetIndex(s, k);
}

ghost predicate InPrefix(s: seq<int>, i: int, x: int) {
  exists j: int :: 0 <= j < |s| && j < i && s[j] == x
}

lemma {:induction false} PrefixExtend(s: seq<int>, i: int, x: int)
  requires 0 <= i < |s|
  ensures InPrefix(s, i + 1, x) <==> InPrefix(s, i, x) || x == s[i]
{
  if InPrefix(s, i + 1, x) {
    var j :| 0 <= j < |s| && j < i + 1 && s[j] == x;
    if j < i {
      assert 0 <= j < |s| && j < i && s[j] == x;
      assert InPrefix(s, i, x);
    } else {
      assert j == i;
      assert x == s[i];
    }
    assert InPrefix(s, i, x) || x == s[i];
  }
  if InPrefix(s, i, x) {
    var j :| 0 <= j < |s| && j < i && s[j] == x;
    assert j < i + 1;
    assert 0 <= j < |s| && j < i + 1 && s[j] == x;
    assert InPrefix(s, i + 1, x);
  }
  if x == s[i] {
    assert 0 <= i < |s| && i < i + 1 && s[i] == x;
    assert InPrefix(s, i + 1, x);
  }
}

ghost predicate LeftIn(mt: Matching, lefts: set<int>) {
  forall e: (int, int) :: e in mt ==> e.0 in lefts
}

ghost predicate NoRightUsed(mt: Matching, used: set<int>) {
  forall e: (int, int) :: e in mt ==> e.1 !in used
}

ghost predicate NoU(mt: Matching, u: int) {
  forall e: (int, int) :: e in mt ==> e.0 != u
}

ghost predicate MatchesUIn(mt: Matching, u: int, s: seq<int>, i: int, used: set<int>) {
  exists e: (int, int) :: e in mt && e.0 == u && InPrefix(s, i, e.1) && e.1 !in used
}

ghost predicate valid_on(adj: seq<seq<int>>, lefts: set<int>, used: set<int>, mt: Matching) {
  mt <= PossibleEdges(adj)
  && is_matching(adj, mt)
  && LeftIn(mt, lefts)
  && NoRightUsed(mt, used)
}

ghost predicate max_on(adj: seq<seq<int>>, lefts: set<int>, used: set<int>, mt: Matching) {
  valid_on(adj, lefts, used, mt)
  && (forall other: Matching ::
        valid_on(adj, lefts, used, other) ==> |mt| >= |other|)
}

lemma {:induction false} CardAdd<T>(s: set<T>, x: T)
  requires x !in s
  ensures |s + {x}| == |s| + 1
{
}

lemma {:induction false} CardSub<T>(s: set<T>, x: T)
  requires x in s
  ensures |s| == |s - {x}| + 1
{
  var r := s - {x};
  assert x !in r;
  forall y: T | y in s
    ensures y in r + {x}
  {
    if y == x {
      assert y in r + {x};
    } else {
      assert y in r;
      assert y in r + {x};
    }
  }
  forall y: T | y in r + {x}
    ensures y in s
  {
    if y == x {
      assert x in s;
    } else {
      assert y != x;
      assert y in r;
      assert y in s;
    }
  }
  assert s == r + {x};
  assert r <= s;
  CardAdd(r, x);
  assert |s| == |r + {x}|;
  assert |r + {x}| == |r| + 1;
}

lemma {:induction false} ValidEdge(adj: seq<seq<int>>, mt: Matching, e: (int, int))
  requires matching_valid_edges(adj, mt)
  requires e in mt
  ensures exists i: int :: 0 <= e.0 < |adj| && 0 <= i < |adj[e.0]| && adj[e.0][i] == e.1
{
}

lemma {:induction false} DisjointPair(mt: Matching, e1: (int, int), e2: (int, int))
  requires is_disjoint(mt)
  requires e1 in mt && e2 in mt && e1 != e2
  ensures e1.0 != e2.0 && e1.1 != e2.1
{
}

lemma {:induction false} NotNoU(mt: Matching, u: int)
  requires !NoU(mt, u)
  ensures exists e: (int, int) :: e in mt && e.0 == u
{
  if forall e: (int, int) :: e in mt ==> e.0 != u {
    assert NoU(mt, u);
    assert false;
  } else {
    assert exists e: (int, int) :: e in mt && e.0 == u;
  }
}

lemma {:induction false} MatchingInPossible(adj: seq<seq<int>>, mt: Matching)
  requires matching_valid_edges(adj, mt)
  ensures mt <= PossibleEdges(adj)
{
  forall e: (int, int) | e in mt
    ensures e in PossibleEdges(adj)
  {
    ValidEdge(adj, mt, e);
    var j :| 0 <= e.0 < |adj| && 0 <= j < |adj[e.0]| && adj[e.0][j] == e.1;
    PossibleMember(adj, e.0, j);
    assert e == (e.0, adj[e.0][j]);
    assert e in PossibleEdges(adj);
  }
}

lemma {:induction false} SubsetIsMatching(adj: seq<seq<int>>, a: Matching, b: Matching)
  requires is_matching(adj, a)
  requires b <= a
  ensures is_matching(adj, b)
{
  assert matching_valid_edges(adj, a);
  assert is_disjoint(a);
  forall e: (int, int) | e in b
    ensures exists i: int :: 0 <= e.0 < |adj| && 0 <= i < |adj[e.0]| && adj[e.0][i] == e.1
  {
    assert e in a;
    ValidEdge(adj, a, e);
  }
  forall e1: (int, int), e2: (int, int) | e1 in b && e2 in b && e1 != e2
    ensures e1.0 != e2.0 && e1.1 != e2.1
  {
    assert e1 in a && e2 in a;
    DisjointPair(a, e1, e2);
  }
  assert matching_valid_edges(adj, b);
  assert is_disjoint(b);
}

lemma {:induction false} ExtendMatching(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    v: int,
    idx: int,
    mTake: Matching
)
  requires 0 <= u < |adj|
  requires 0 <= idx < |adj[u]|
  requires adj[u][idx] == v
  requires u in lefts
  requires v !in used
  requires valid_on(adj, lefts - {u}, used + {v}, mTake)
  ensures (u, v) !in mTake
  ensures valid_on(adj, lefts, used, mTake + {(u, v)})
  ensures |mTake + {(u, v)}| == |mTake| + 1
{
  var edge := (u, v);
  var mNew := mTake + {edge};

  forall e: (int, int) | e in mTake
    ensures e.0 != u && e.1 != v
  {
    assert e.0 in lefts - {u};
    assert e.1 !in used + {v};
    assert e.0 != u;
    assert e.1 != v;
  }
  if edge in mTake {
    assert edge.0 != u;
    assert edge.0 == u;
    assert false;
  }
  assert edge !in mTake;

  PossibleMember(adj, u, idx);
  assert edge in PossibleEdges(adj);
  assert mTake <= PossibleEdges(adj);

  forall e: (int, int) | e in mNew
    ensures e in PossibleEdges(adj)
  {
    if e == edge {
      assert e in PossibleEdges(adj);
    } else {
      assert e in mTake;
      assert e in PossibleEdges(adj);
    }
  }
  assert mNew <= PossibleEdges(adj);

  assert is_matching(adj, mTake);
  assert matching_valid_edges(adj, mTake);
  forall e: (int, int) | e in mNew
    ensures exists q: int :: 0 <= e.0 < |adj| && 0 <= q < |adj[e.0]| && adj[e.0][q] == e.1
  {
    if e == edge {
      assert 0 <= idx < |adj[u]| && adj[u][idx] == v;
      assert e.0 == u && e.1 == v;
    } else {
      assert e in mTake;
      ValidEdge(adj, mTake, e);
    }
  }
  assert matching_valid_edges(adj, mNew);

  assert is_disjoint(mTake);
  forall e1: (int, int), e2: (int, int) | e1 in mNew && e2 in mNew && e1 != e2
    ensures e1.0 != e2.0 && e1.1 != e2.1
  {
    if e1 == edge {
      assert e2 != edge;
      assert e2 in mTake;
      assert e2.0 != u && e2.1 != v;
      assert e1.0 == u && e1.1 == v;
    } else if e2 == edge {
      assert e1 in mTake;
      assert e1.0 != u && e1.1 != v;
      assert e2.0 == u && e2.1 == v;
    } else {
      assert e1 in mTake && e2 in mTake && e1 != e2;
      DisjointPair(mTake, e1, e2);
    }
  }
  assert is_disjoint(mNew);
  assert is_matching(adj, mNew);

  forall e: (int, int) | e in mNew
    ensures e.0 in lefts
  {
    if e == edge {
      assert u in lefts;
    } else {
      assert e in mTake;
      assert e.0 in lefts - {u};
      assert e.0 in lefts;
    }
  }
  assert LeftIn(mNew, lefts);

  forall e: (int, int) | e in mNew
    ensures e.1 !in used
  {
    if e == edge {
      assert v !in used;
    } else {
      assert e in mTake;
      assert e.1 !in used + {v};
      assert e.1 !in used;
    }
  }
  assert NoRightUsed(mNew, used);
  assert valid_on(adj, lefts, used, mNew);

  CardAdd(mTake, edge);
  assert |mNew| == |mTake| + 1;
}

lemma {:induction false} ProjectTake(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    v: int,
    other: Matching
)
  requires u in lefts
  requires (u, v) in other
  requires valid_on(adj, lefts, used, other)
  ensures v !in used
  ensures valid_on(adj, lefts - {u}, used + {v}, other - {(u, v)})
  ensures |other| == |other - {(u, v)}| + 1
{
  var edge := (u, v);
  var otherP := other - {edge};
  assert edge in other;
  assert edge.1 !in used;
  assert v !in used;

  assert other <= PossibleEdges(adj);
  assert otherP <= other;
  assert otherP <= PossibleEdges(adj);
  assert is_matching(adj, other);
  SubsetIsMatching(adj, other, otherP);
  assert is_matching(adj, otherP);
  assert is_disjoint(other);

  forall e: (int, int) | e in otherP
    ensures e.0 != u && e.1 != v
  {
    assert e in other && edge in other && e != edge;
    DisjointPair(other, e, edge);
    assert e.0 != edge.0 && e.1 != edge.1;
  }

  forall e: (int, int) | e in otherP
    ensures e.0 in lefts - {u}
  {
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(otherP, lefts - {u});

  forall e: (int, int) | e in otherP
    ensures e.1 !in used + {v}
  {
    assert e.1 !in used;
    assert e.1 != v;
    assert e.1 !in used + {v};
  }
  assert NoRightUsed(otherP, used + {v});
  assert valid_on(adj, lefts - {u}, used + {v}, otherP);

  CardSub(other, edge);
}

lemma {:induction false} ProjectSkip(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    other: Matching
)
  requires u in lefts
  requires valid_on(adj, lefts, used, other)
  requires NoU(other, u)
  ensures valid_on(adj, lefts - {u}, used, other)
{
  forall e: (int, int) | e in other
    ensures e.0 in lefts - {u}
  {
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(other, lefts - {u});
  assert other <= PossibleEdges(adj);
  assert is_matching(adj, other);
  assert NoRightUsed(other, used);
  assert valid_on(adj, lefts - {u}, used, other);
}

lemma {:induction false} LiftFromRest(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    mt: Matching
)
  requires u in lefts
  requires valid_on(adj, lefts - {u}, used, mt)
  ensures valid_on(adj, lefts, used, mt)
  ensures NoU(mt, u)
{
  forall e: (int, int) | e in mt
    ensures e.0 in lefts && e.0 != u
  {
    assert e.0 in lefts - {u};
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(mt, lefts);
  assert NoU(mt, u);
  assert mt <= PossibleEdges(adj);
  assert is_matching(adj, mt);
  assert NoRightUsed(mt, used);
  assert valid_on(adj, lefts, used, mt);
}

lemma {:induction false} {:vcs_split_on_every_assert} Conclude(
    adj: seq<seq<int>>,
    L: set<int>,
    used: set<int>,
    u: int,
    neighbors: seq<int>,
    bestSize: int,
    bestM: Matching
)
  requires 0 <= u < |adj|
  requires neighbors == adj[u]
  requires valid_on(adj, L, used, bestM)
  requires |bestM| == bestSize
  requires forall other: Matching ::
      valid_on(adj, L, used, other) && NoU(other, u) ==> |other| <= bestSize
  requires forall other: Matching ::
      valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, |neighbors|, used)
      ==> |other| <= bestSize
  ensures max_on(adj, L, used, bestM)
{
  forall other: Matching | valid_on(adj, L, used, other)
    ensures |bestM| >= |other|
  {
    assert other <= PossibleEdges(adj);
    if forall e: (int, int) :: e in other ==> e.0 != u {
      assert NoU(other, u);
      assert |other| <= bestSize;
      assert bestSize == |bestM|;
