    assert edge in SeqImage(pre) + SeqImage(row);
    assert edge in SeqImage(pre + row);
    assert PossibleEdges(adj) == SeqImage(AllEdgeSeq(adj));
    assert edge in PossibleEdges(adj);
  }
}

lemma {:induction false} IndexInSeqSet(n: int, k: int)
  requires n >= 0 && 0 <= k < n
  ensures k in SeqSet(LeftSeq(n))
{
  LeftSeqProps(n);
  var s := LeftSeq(n);
  assert |s| == n;
  assert s[k] == k;
  SeqSetIndex(s, k);
}

ghost predicate InPrefix(s: seq<int>, i: int, x: int) {
  exists j: int :: 0 <= j < |s| && j < i && s[j] == x
}

lemma {:induction false} PrefixExtend(s: seq<int>, i: int, x: int)
  requires 0 <= i < |s|
  ensures InPrefix(s, i + 1, x) <==> InPrefix(s, i, x) || x == s[i]
{
  if InPrefix(s, i + 1, x) {
    var j :| 0 <= j < |s| && j < i + 1 && s[j] == x;
    if j < i {
      assert 0 <= j < |s| && j < i && s[j] == x;
      assert InPrefix(s, i, x);
    } else {
      assert j == i;
      assert x == s[i];
    }
    assert InPrefix(s, i, x) || x == s[i];
  }
  if InPrefix(s, i, x) {
    var j :| 0 <= j < |s| && j < i && s[j] == x;
    assert j < i + 1;
    assert 0 <= j < |s| && j < i + 1 && s[j] == x;
    assert InPrefix(s, i + 1, x);
  }
  if x == s[i] {
    assert 0 <= i < |s| && i < i + 1 && s[i] == x;
    assert InPrefix(s, i + 1, x);
  }
}

ghost predicate LeftIn(mt: Matching, lefts: set<int>) {
  forall e: (int, int) :: e in mt ==> e.0 in lefts
}

ghost predicate NoRightUsed(mt: Matching, used: set<int>) {
  forall e: (int, int) :: e in mt ==> e.1 !in used
}

ghost predicate NoU(mt: Matching, u: int) {
  forall e: (int, int) :: e in mt ==> e.0 != u
}

ghost predicate MatchesUIn(mt: Matching, u: int, s: seq<int>, i: int, used: set<int>) {
  exists e: (int, int) :: e in mt && e.0 == u && InPrefix(s, i, e.1) && e.1 !in used
}

ghost predicate valid_on(adj: seq<seq<int>>, lefts: set<int>, used: set<int>, mt: Matching) {
  mt <= PossibleEdges(adj)
  && is_matching(adj, mt)
  && LeftIn(mt, lefts)
  && NoRightUsed(mt, used)
}

ghost predicate max_on(adj: seq<seq<int>>, lefts: set<int>, used: set<int>, mt: Matching) {
  valid_on(adj, lefts, used, mt)
  && (forall other: Matching ::
        valid_on(adj, lefts, used, other) ==> |mt| >= |other|)
}

lemma {:induction false} CardAdd<T>(s: set<T>, x: T)
  requires x !in s
  ensures |s + {x}| == |s| + 1
{
}

lemma {:induction false} CardSub<T>(s: set<T>, x: T)
  requires x in s
  ensures |s| == |s - {x}| + 1
{
  var r := s - {x};
  assert x !in r;
  forall y: T | y in s
    ensures y in r + {x}
  {
    if y == x {
      assert y in r + {x};
    } else {
      assert y in r;
      assert y in r + {x};
    }
  }
  forall y: T | y in r + {x}
    ensures y in s
  {
    if y == x {
      assert x in s;
    } else {
      assert y != x;
      assert y in r;
      assert y in s;
    }
  }
  assert s == r + {x};
  assert r <= s;
  CardAdd(r, x);
  assert |s| == |r + {x}|;
  assert |r + {x}| == |r| + 1;
}

lemma {:induction false} ValidEdge(adj: seq<seq<int>>, mt: Matching, e: (int, int))
  requires matching_valid_edges(adj, mt)
  requires e in mt
  ensures exists i: int :: 0 <= e.0 < |adj| && 0 <= i < |adj[e.0]| && adj[e.0][i] == e.1
{
}

lemma {:induction false} DisjointPair(mt: Matching, e1: (int, int), e2: (int, int))
  requires is_disjoint(mt)
  requires e1 in mt && e2 in mt && e1 != e2
  ensures e1.0 != e2.0 && e1.1 != e2.1
{
}

lemma {:induction false} NotNoU(mt: Matching, u: int)
  requires !NoU(mt, u)
  ensures exists e: (int, int) :: e in mt && e.0 == u
{
  if forall e: (int, int) :: e in mt ==> e.0 != u {
    assert NoU(mt, u);
    assert false;
  } else {
    assert exists e: (int, int) :: e in mt && e.0 == u;
  }
}

lemma {:induction false} MatchingInPossible(adj: seq<seq<int>>, mt: Matching)
  requires matching_valid_edges(adj, mt)
  ensures mt <= PossibleEdges(adj)
{
  forall e: (int, int) | e in mt
    ensures e in PossibleEdges(adj)
  {
    ValidEdge(adj, mt, e);
    var j :| 0 <= e.0 < |adj| && 0 <= j < |adj[e.0]| && adj[e.0][j] == e.1;
    PossibleMember(adj, e.0, j);
    assert e == (e.0, adj[e.0][j]);
    assert e in PossibleEdges(adj);
  }
}

lemma {:induction false} SubsetIsMatching(adj: seq<seq<int>>, a: Matching, b: Matching)
  requires is_matching(adj, a)
  requires b <= a
  ensures is_matching(adj, b)
{
  assert matching_valid_edges(adj, a);
  assert is_disjoint(a);
  forall e: (int, int) | e in b
    ensures exists i: int :: 0 <= e.0 < |adj| && 0 <= i < |adj[e.0]| && adj[e.0][i] == e.1
  {
    assert e in a;
    ValidEdge(adj, a, e);
  }
  forall e1: (int, int), e2: (int, int) | e1 in b && e2 in b && e1 != e2
    ensures e1.0 != e2.0 && e1.1 != e2.1
  {
    assert e1 in a && e2 in a;
    DisjointPair(a, e1, e2);
  }
  assert matching_valid_edges(adj, b);
  assert is_disjoint(b);
}

lemma {:induction false} ExtendMatching(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    v: int,
    idx: int,
    mTake: Matching
)
  requires 0 <= u < |adj|
  requires 0 <= idx < |adj[u]|
  requires adj[u][idx] == v
  requires u in lefts
  requires v !in used
  requires valid_on(adj, lefts - {u}, used + {v}, mTake)
  ensures (u, v) !in mTake
  ensures valid_on(adj, lefts, used, mTake + {(u, v)})
  ensures |mTake + {(u, v)}| == |mTake| + 1
{
  var edge := (u, v);
  var mNew := mTake + {edge};

  forall e: (int, int) | e in mTake
    ensures e.0 != u && e.1 != v
  {
    assert e.0 in lefts - {u};
    assert e.1 !in used + {v};
    assert e.0 != u;
    assert e.1 != v;
  }
  if edge in mTake {
    assert edge.0 != u;
    assert edge.0 == u;
    assert false;
  }
  assert edge !in mTake;

  PossibleMember(adj, u, idx);
  assert edge in PossibleEdges(adj);
  assert mTake <= PossibleEdges(adj);

  forall e: (int, int) | e in mNew
    ensures e in PossibleEdges(adj)
  {
    if e == edge {
      assert e in PossibleEdges(adj);
    } else {
      assert e in mTake;
      assert e in PossibleEdges(adj);
    }
  }
  assert mNew <= PossibleEdges(adj);

  assert is_matching(adj, mTake);
  assert matching_valid_edges(adj, mTake);
  forall e: (int, int) | e in mNew
    ensures exists q: int :: 0 <= e.0 < |adj| && 0 <= q < |adj[e.0]| && adj[e.0][q] == e.1
  {
    if e == edge {
      assert 0 <= idx < |adj[u]| && adj[u][idx] == v;
      assert e.0 == u && e.1 == v;
    } else {
      assert e in mTake;
      ValidEdge(adj, mTake, e);
    }
  }
  assert matching_valid_edges(adj, mNew);

  assert is_disjoint(mTake);
  forall e1: (int, int), e2: (int, int) | e1 in mNew && e2 in mNew && e1 != e2
    ensures e1.0 != e2.0 && e1.1 != e2.1
  {
    if e1 == edge {
      assert e2 != edge;
      assert e2 in mTake;
      assert e2.0 != u && e2.1 != v;
      assert e1.0 == u && e1.1 == v;
    } else if e2 == edge {
      assert e1 in mTake;
      assert e1.0 != u && e1.1 != v;
      assert e2.0 == u && e2.1 == v;
    } else {
      assert e1 in mTake && e2 in mTake && e1 != e2;
      DisjointPair(mTake, e1, e2);
    }
  }
  assert is_disjoint(mNew);
  assert is_matching(adj, mNew);

  forall e: (int, int) | e in mNew
    ensures e.0 in lefts
  {
    if e == edge {
      assert u in lefts;
    } else {
      assert e in mTake;
      assert e.0 in lefts - {u};
      assert e.0 in lefts;
    }
  }
  assert LeftIn(mNew, lefts);

  forall e: (int, int) | e in mNew
    ensures e.1 !in used
  {
    if e == edge {
      assert v !in used;
    } else {
      assert e in mTake;
      assert e.1 !in used + {v};
      assert e.1 !in used;
    }
  }
  assert NoRightUsed(mNew, used);
  assert valid_on(adj, lefts, used, mNew);

  CardAdd(mTake, edge);
  assert |mNew| == |mTake| + 1;
}

lemma {:induction false} ProjectTake(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    v: int,
    other: Matching
)
  requires u in lefts
  requires (u, v) in other
  requires valid_on(adj, lefts, used, other)
  ensures v !in used
  ensures valid_on(adj, lefts - {u}, used + {v}, other - {(u, v)})
  ensures |other| == |other - {(u, v)}| + 1
{
  var edge := (u, v);
  var otherP := other - {edge};
  assert edge in other;
  assert edge.1 !in used;
  assert v !in used;

  assert other <= PossibleEdges(adj);
  assert otherP <= other;
  assert otherP <= PossibleEdges(adj);
  assert is_matching(adj, other);
  SubsetIsMatching(adj, other, otherP);
  assert is_matching(adj, otherP);
  assert is_disjoint(other);

  forall e: (int, int) | e in otherP
    ensures e.0 != u && e.1 != v
  {
    assert e in other && edge in other && e != edge;
    DisjointPair(other, e, edge);
    assert e.0 != edge.0 && e.1 != edge.1;
  }

  forall e: (int, int) | e in otherP
    ensures e.0 in lefts - {u}
  {
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(otherP, lefts - {u});

  forall e: (int, int) | e in otherP
    ensures e.1 !in used + {v}
  {
    assert e.1 !in used;
    assert e.1 != v;
    assert e.1 !in used + {v};
  }
  assert NoRightUsed(otherP, used + {v});
  assert valid_on(adj, lefts - {u}, used + {v}, otherP);

  CardSub(other, edge);
}

lemma {:induction false} ProjectSkip(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    other: Matching
)
  requires u in lefts
  requires valid_on(adj, lefts, used, other)
  requires NoU(other, u)
  ensures valid_on(adj, lefts - {u}, used, other)
{
  forall e: (int, int) | e in other
    ensures e.0 in lefts - {u}
  {
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(other, lefts - {u});
  assert other <= PossibleEdges(adj);
  assert is_matching(adj, other);
  assert NoRightUsed(other, used);
  assert valid_on(adj, lefts - {u}, used, other);
}

lemma {:induction false} LiftFromRest(
    adj: seq<seq<int>>,
    lefts: set<int>,
    used: set<int>,
    u: int,
    mt: Matching
)
  requires u in lefts
  requires valid_on(adj, lefts - {u}, used, mt)
  ensures valid_on(adj, lefts, used, mt)
  ensures NoU(mt, u)
{
  forall e: (int, int) | e in mt
    ensures e.0 in lefts && e.0 != u
  {
    assert e.0 in lefts - {u};
    assert e.0 in lefts;
    assert e.0 != u;
  }
  assert LeftIn(mt, lefts);
  assert NoU(mt, u);
  assert mt <= PossibleEdges(adj);
  assert is_matching(adj, mt);
  assert NoRightUsed(mt, used);
  assert valid_on(adj, lefts, used, mt);
}

lemma {:induction false} {:vcs_split_on_every_assert} Conclude(
    adj: seq<seq<int>>,
    L: set<int>,
    used: set<int>,
    u: int,
    neighbors: seq<int>,
    bestSize: int,
    bestM: Matching
)
  requires 0 <= u < |adj|
  requires neighbors == adj[u]
  requires valid_on(adj, L, used, bestM)
  requires |bestM| == bestSize
  requires forall other: Matching ::
      valid_on(adj, L, used, other) && NoU(other, u) ==> |other| <= bestSize
  requires forall other: Matching ::
      valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, |neighbors|, used)
      ==> |other| <= bestSize
  ensures max_on(adj, L, used, bestM)
{
  forall other: Matching | valid_on(adj, L, used, other)
    ensures |bestM| >= |other|
  {
    assert other <= PossibleEdges(adj);
    if forall e: (int, int) :: e in other ==> e.0 != u {
      assert NoU(other, u);
      assert |other| <= bestSize;
      assert bestSize == |bestM|;
      assert |bestM| >= |other|;
    } else {
      assert !(forall e: (int, int) :: e in other ==> e.0 != u);
      assert !NoU(other, u);
      NotNoU(other, u);
      var e :| e in other && e.0 == u;
      assert NoRightUsed(other, used);
      assert e.1 !in used;
      assert is_matching(adj, other);
      assert matching_valid_edges(adj, other);
      ValidEdge(adj, other, e);
      var k :| 0 <= e.0 < |adj| && 0 <= k < |adj[e.0]| && adj[e.0][k] == e.1;
      assert e.0 == u;
      assert neighbors == adj[u];
      assert 0 <= k < |neighbors|;
      assert neighbors[k] == e.1;
      assert 0 <= k < |neighbors| && k < |neighbors| && neighbors[k] == e.1;
      assert InPrefix(neighbors, |neighbors|, e.1);
      assert e in other && e.0 == u && InPrefix(neighbors, |neighbors|, e.1) && e.1 !in used;
      assert MatchesUIn(other, u, neighbors, |neighbors|, used);
      assert |other| <= bestSize;
      assert |bestM| == bestSize;
      assert |bestM| >= |other|;
    }
  }
  assert valid_on(adj, L, used, bestM);
  assert max_on(adj, L, used, bestM);
}

method {:vcs_split_on_every_assert} MaxMatch(adj: seq<seq<int>>, lefts: seq<int>, used: set<int>)
  returns (size: int, ghost m: Matching)
  requires Distinct(lefts)
  requires forall k: int :: 0 <= k < |lefts| ==> 0 <= lefts[k] < |adj|
  decreases |lefts|
  ensures max_on(adj, SeqSet(lefts), used, m) && |m| == size && size >= 0
{
  if |lefts| == 0 {
    size := 0;
    m := {};
    assert m <= PossibleEdges(adj);
    assert matching_valid_edges(adj, m);
    assert is_disjoint(m);
    assert is_matching(adj, m);
    assert LeftIn(m, SeqSet(lefts));
    assert NoRightUsed(m, used);
    assert valid_on(adj, SeqSet(lefts), used, m);
    assert |m| == 0;
    forall other: Matching | valid_on(adj, SeqSet(lefts), used, other)
      ensures |m| >= |other|
    {
      assert other <= PossibleEdges(adj);
      if exists e: (int, int) :: e in other {
        var e :| e in other;
        assert LeftIn(other, SeqSet(lefts));
        assert e.0 in SeqSet(lefts);
        SeqSetWitness(lefts, e.0);
        var k :| 0 <= k < |lefts| && lefts[k] == e.0;
        assert 0 <= k < 0;
        assert false;
      }
      assert forall e: (int, int) :: e !in other;
      assert other == {};
      assert |other| == 0;
      assert |m| >= |other|;
    }
    assert max_on(adj, SeqSet(lefts), used, m);
    assert size >= 0;
    return;
  }

  assert |lefts| >= 1;
  var u := lefts[0];
  var restSeq := lefts[1..];
  assert 0 <= u < |adj|;
  DistinctTail(lefts);
  BoundsTail(adj, lefts);
  assert Distinct(restSeq);
  assert forall k: int :: 0 <= k < |restSeq| ==> 0 <= restSeq[k] < |adj|;
  assert |restSeq| == |lefts| - 1;
  assert |restSeq| < |lefts|;

  SeqSetDecomp(lefts);
  ghost var L := SeqSet(lefts);
  ghost var R := SeqSet(restSeq);
  assert u !in R;
  assert L == R + {u};
  SetRemove(L, u, R);
  assert R == L - {u};
  assert u in L;

  var sizeSkip, mSkip := MaxMatch(adj, restSeq, used);
  assert max_on(adj, R, used, mSkip);
  assert |mSkip| == sizeSkip;
  assert valid_on(adj, R, used, mSkip);
  assert mSkip <= PossibleEdges(adj);
  assert sizeSkip >= 0;
  assert valid_on(adj, L - {u}, used, mSkip);
  LiftFromRest(adj, L, used, u, mSkip);
  assert valid_on(adj, L, used, mSkip);
  assert NoU(mSkip, u);

  var neighbors := adj[u];
  assert neighbors == adj[u];
  var bestSize := sizeSkip;
  ghost var bestM := mSkip;
  assert |bestM| == bestSize;
  assert bestSize >= 0;

  forall other: Matching | valid_on(adj, L, used, other) && NoU(other, u)
    ensures |other| <= bestSize
  {
    ProjectSkip(adj, L, used, u, other);
    assert valid_on(adj, L - {u}, used, other);
    assert L - {u} == R;
    assert valid_on(adj, R, used, other);
    assert other <= PossibleEdges(adj);
    assert |other| <= |mSkip|;
    assert |mSkip| == bestSize;
    assert |other| <= bestSize;
  }

  forall other: Matching | valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, 0, used)
    ensures |other| <= bestSize
  {
    var e :| e in other && e.0 == u && InPrefix(neighbors, 0, e.1) && e.1 !in used;
    assert InPrefix(neighbors, 0, e.1);
    var j :| 0 <= j < |neighbors| && j < 0 && neighbors[j] == e.1;
    assert 0 <= j && j < 0;
    assert false;
  }

  var i := 0;
  while i < |neighbors|
    invariant 0 <= i <= |neighbors|
    invariant neighbors == adj[u]
    invariant bestSize >= 0
    invariant valid_on(adj, L, used, bestM)
    invariant |bestM| == bestSize
    invariant forall other: Matching ::
        valid_on(adj, L, used, other) && NoU(other, u) ==> |other| <= bestSize
    invariant forall other: Matching ::
        valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, i, used)
        ==> |other| <= bestSize
    decreases |neighbors| - i
  {
    var v := neighbors[i];
    var nextI := i + 1;
    assert v == neighbors[i];
    assert 0 <= nextI <= |neighbors|;
    assert nextI == i + 1;
    if v in used {
      forall other: Matching |
          valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, nextI, used)
        ensures |other| <= bestSize
      {
        var e :| e in other && e.0 == u && InPrefix(neighbors, nextI, e.1) && e.1 !in used;
        assert InPrefix(neighbors, i + 1, e.1);
        PrefixExtend(neighbors, i, e.1);
        assert InPrefix(neighbors, i, e.1) || e.1 == neighbors[i];
        assert neighbors[i] == v;
        if e.1 == v {
          assert e.1 !in used;
          assert v in used;
          assert false;
        }
        assert e.1 != v;
        assert InPrefix(neighbors, i, e.1);
        assert e in other && e.0 == u && InPrefix(neighbors, i, e.1) && e.1 !in used;
        assert MatchesUIn(other, u, neighbors, i, used);
        assert |other| <= bestSize;
      }
      i := nextI;
      assert forall other: Matching ::
          valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, i, used)
          ==> |other| <= bestSize;
    } else {
      assert v !in used;
      assert |restSeq| < |lefts|;
      var sizeTake, mTake := MaxMatch(adj, restSeq, used + {v});
      assert {:split_here} true;
      assert max_on(adj, SeqSet(restSeq), used + {v}, mTake);
      assert SeqSet(restSeq) == R;
      assert R == L - {u};
      assert max_on(adj, L - {u}, used + {v}, mTake);
      assert valid_on(adj, L - {u}, used + {v}, mTake);
      assert |mTake| == sizeTake;
      assert 0 <= i < |neighbors|;
      assert |neighbors| == |adj[u]|;
      assert 0 <= i < |adj[u]|;
      assert adj[u][i] == v;
      assert u in L;
      ExtendMatching(adj, L, used, u, v, i, mTake);
      ghost var mNew := mTake + {(u, v)};
      assert valid_on(adj, L, used, mNew);
      assert |mNew| == |mTake| + 1;
      assert |mNew| == sizeTake + 1;

      var newSize := bestSize;
      ghost var newM := bestM;
      if sizeTake + 1 > bestSize {
        newSize := sizeTake + 1;
        newM := mNew;
        assert newM == mNew;
        assert valid_on(adj, L, used, newM);
        assert |newM| == newSize;
        assert newSize >= bestSize;
        assert newSize >= sizeTake + 1;
      } else {
        assert sizeTake + 1 <= bestSize;
        assert newSize == bestSize;
        assert newM == bestM;
        assert valid_on(adj, L, used, newM);
        assert |newM| == newSize;
        assert newSize >= sizeTake + 1;
        assert newSize >= bestSize;
      }
      assert newSize >= bestSize;
      assert newSize >= sizeTake + 1;
      assert newSize >= 0;
      assert valid_on(adj, L, used, newM);
      assert |newM| == newSize;

      forall other: Matching |
          valid_on(adj, L, used, other) && NoU(other, u)
        ensures |other| <= newSize
      {
        assert |other| <= bestSize;
        assert bestSize <= newSize;
        assert |other| <= newSize;
      }

      forall other: Matching |
          valid_on(adj, L, used, other) && MatchesUIn(other, u, neighbors, nextI, used)
        ensures |other| <= newSize
      {
        var e :| e in other && e.0 == u && InPrefix(neighbors, nextI, e.1) && e.1 !in used;
        assert other <= PossibleEdges(adj);
        assert InPrefix(neighbors, i + 1, e.1);
        PrefixExtend(neighbors, i, e.1);
        assert InPrefix(neighbors, i, e.1) || e.1 == neighbors[i];
        if InPrefix(neighbors, i, e.1) {
