method poly_multiply(a: seq<int>, b: seq<int>) returns (res: seq<int>)
    requires |a| > 0
    requires |b| > 0
    requires |a| + |b| <= 1000
    requires coeffs_bounded(a)
    requires coeffs_bounded(b)

    ensures |res| == |a| + |b| - 1
    ensures forall k :: 0 <= k < |res| ==>
        res[k] == spec_poly_mul_coeff(a, b, k)
{
    var n := |a| + |b| - 1;
    var r: seq<int> := [];
    var k := 0;

    while k < n
        invariant 0 <= k <= n
        invariant |r| == k
        invariant forall j :: 0 <= j < k ==>
            r[j] == spec_poly_mul_coeff(a, b, j)
        decreases n - k
    {
        var sum := 0;
        var i := k;

        while i >= 0
            invariant -1 <= i <= k
            invariant sum + spec_convolution_sum(a, b, k, i)
                == spec_convolution_sum(a, b, k, k)
            decreases i + 1
        {
            var term :=
                if i < |a| && k - i < |b| && k - i >= 0
                then a[i] * b[k - i]
                else 0;

            convolution_step(a, b, k, i);
            assert spec_convolution_sum(a, b, k, i)
                == term + spec_convolution_sum(a, b, k, i - 1);
            assert (sum + term)
                    + spec_convolution_sum(a, b, k, i - 1)
                == spec_convolution_sum(a, b, k, k);

            sum := sum + term;
            i := i - 1;
        }

