                assert r[j] == spec_poly_mul_coeff(a, b, j);
                assert next[j] == r[j];
            } else {
                assert j == |r|;
                assert j == k;
                assert next[j] == sum;
            }
        }

        r := next;
        k := k + 1;
    }

    res := r;
}

