  requires forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j)
  requires forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m]
  requires forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]]
  requires i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i]
  requires j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j]
  ensures MergeInv(a, b, c, p, i, j)
{
}

lemma MergeInvInit(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires c == [] && p == [] && i == 0 && j == 0
  ensures MergeInv(a, b, c, p, i, j)
{
  SortedShort(c);
  assert 0 <= i <= |a|;
  assert 0 <= j <= |b|;
  assert |c| == i + j;
  assert |p| == |c|;
  assert is_sorted(c);
  assert forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
  assert forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m];
  assert forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  assert i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i];
  assert j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j];
  CloseMergeInv(a, b, c, p, i, j);
}

lemma CopyInv(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>, i: int, j: int,
  c2: seq<int>, p2: seq<int>, i2: int, j2: int
)
  requires MergeInv(a, b, c, p, i, j)
  requires c2 == c && p2 == p && i2 == i && j2 == j
  ensures MergeInv(a, b, c2, p2, i2, j2)
{
  OpenMergeInv(a, b, c, p, i, j);
  assert 0 <= i2 <= |a|;
  assert 0 <= j2 <= |b|;
  assert |c2| == i2 + j2;
  assert |p2| == |c2|;

  OpenSorted(c);
  forall ia, ja | 0 <= ia < ja < |c2|
    ensures c2[ia] <= c2[ja]
  {
    assert c2[ia] == c[ia] && c2[ja] == c[ja];
    assert c[ia] <= c[ja];
  }
  assert forall ia, ja :: 0 <= ia < ja < |c2| ==> c2[ia] <= c2[ja];
  CloseSorted(c2);

  forall k | 0 <= k < |p2|
    ensures (0 <= p2[k] < i2) || (|a| <= p2[k] < |a| + j2)
  {
    assert p2[k] == p[k];
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
  }

  forall k, m | 0 <= k < m < |p2|
    ensures p2[k] != p2[m]
  {
    assert p2[k] == p[k] && p2[m] == p[m];
    assert p[k] != p[m];
  }

  forall k | 0 <= k < |p2|
    ensures 0 <= p2[k] < |a| + |b|
  {
    assert p2[k] == p[k];
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  forall k | 0 <= k < |p2|
    ensures c2[k] == (a + b)[p2[k]]
  {
    assert p2[k] == p[k];
    assert 0 <= p2[k] < |a| + |b|;
    assert c2[k] == c[k];
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  if i2 < |a| {
    assert i == i2 && i < |a|;
    assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
    forall k | 0 <= k < |c2|
      ensures c2[k] <= a[i2]
    {
      assert c[k] <= a[i];
      assert c2[k] == c[k];
      assert a[i2] == a[i];
    }
  }

  if j2 < |b| {
    assert j == j2 && j < |b|;
    assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
    forall k | 0 <= k < |c2|
      ensures c2[k] <= b[j2]
    {
      assert c[k] <= b[j];
      assert c2[k] == c[k];
      assert b[j2] == b[j];
    }
  }

  assert forall k {:trigger p2[k]} :: 0 <= k < |p2| ==> (0 <= p2[k] < i2) || (|a| <= p2[k] < |a| + j2);
  assert forall k, m {:trigger p2[k], p2[m]} :: 0 <= k < m < |p2| ==> p2[k] != p2[m];
  assert forall k {:trigger p2[k]} :: 0 <= k < |p2| ==> 0 <= p2[k] < |a| + |b| && c2[k] == (a + b)[p2[k]];
  assert i2 < |a| ==> forall k :: 0 <= k < |c2| ==> c2[k] <= a[i2];
  assert j2 < |b| ==> forall k :: 0 <= k < |c2| ==> c2[k] <= b[j2];
  CloseMergeInv(a, b, c2, p2, i2, j2);
}

lemma LemTakeA(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>,
  i: int, j: int,
  cNew: seq<int>, pNew: seq<int>
)
  requires is_sorted(a) && is_sorted(b)
  requires MergeInv(a, b, c, p, i, j)
  requires 0 <= i < |a|
  requires j < |b| ==> a[i] <= b[j]
  requires cNew == c + [a[i]]
  requires pNew == p + [i]
  ensures MergeInv(a, b, cNew, pNew, i + 1, j)
{
  OpenMergeInv(a, b, c, p, i, j);
  var i1 := i + 1;
  assert i1 == i + 1;
  assert 0 <= i1 <= |a|;

  forall k | 0 <= k < |p|
    ensures p[k] != i
  {
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
    if 0 <= p[k] < i {
      assert p[k] != i;
    } else {
      assert |a| <= p[k];
      assert i < |a|;
    }
  }

  forall k, m | 0 <= k < m < |pNew|
    ensures pNew[k] != pNew[m]
  {
    if m < |p| {
      assert pNew[k] == p[k] && pNew[m] == p[m];
      assert p[k] != p[m];
    } else {
      assert m == |p|;
      assert pNew[k] == p[k];
      assert pNew[m] == i;
      assert p[k] != i;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j)
  {
    if k < |p| {
      assert pNew[k] == p[k];
      if 0 <= p[k] < i {
        assert 0 <= pNew[k] < i1;
      } else {
        assert |a| <= p[k] < |a| + j;
      }
    } else {
      assert pNew[k] == i;
      assert 0 <= i < i1;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures 0 <= pNew[k] < |a| + |b|
  {
    assert (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j);
    if 0 <= pNew[k] < i1 {
      assert i1 <= |a|;
      assert pNew[k] < |a| + |b|;
    } else {
      assert |a| <= pNew[k] < |a| + j;
      assert j <= |b|;
      assert 0 <= pNew[k] < |a| + |b|;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures cNew[k] == (a + b)[pNew[k]]
  {
    assert 0 <= pNew[k] < |a| + |b|;
    if k < |c| {
      assert cNew[k] == c[k];
      assert pNew[k] == p[k];
      assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
    } else {
      assert k == |c|;
      assert cNew[k] == a[i];
      assert pNew[k] == i;
      assert (a + b)[i] == a[i];
    }
  }

  assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
  SortedAppend(c, a[i]);
  assert cNew == c + [a[i]];
  assert is_sorted(cNew);

  if i1 < |a| {
    SortedAt(a, i, i1);
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= a[i1]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= a[i];
        assert a[i] <= a[i1];
      } else {
        assert cNew[k] == a[i];
        assert a[i] <= a[i1];
      }
    }
  }

  if j < |b| {
    assert a[i] <= b[j];
    assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= b[j]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= b[j];
      } else {
        assert cNew[k] == a[i];
        assert a[i] <= b[j];
      }
    }
  }

  assert |cNew| == i1 + j;
  assert |pNew| == |cNew|;
  assert 0 <= j <= |b|;
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j);
  assert forall k, m {:trigger pNew[k], pNew[m]} :: 0 <= k < m < |pNew| ==> pNew[k] != pNew[m];
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> 0 <= pNew[k] < |a| + |b| && cNew[k] == (a + b)[pNew[k]];
  assert i1 < |a| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= a[i1];
  assert j < |b| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= b[j];
  CloseMergeInv(a, b, cNew, pNew, i1, j);
  assert i1 == i + 1;
  CopyInv(a, b, cNew, pNew, i1, j, cNew, pNew, i + 1, j);
}

lemma LemTakeB(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>,
  i: int, j: int,
  cNew: seq<int>, pNew: seq<int>
)
  requires is_sorted(a) && is_sorted(b)
  requires MergeInv(a, b, c, p, i, j)
  requires 0 <= j < |b|
  requires i < |a| ==> b[j] <= a[i]
  requires cNew == c + [b[j]]
  requires pNew == p + [|a| + j]
  ensures MergeInv(a, b, cNew, pNew, i, j + 1)
{
  OpenMergeInv(a, b, c, p, i, j);
  var j1 := j + 1;
  var idx := |a| + j;
  assert j1 == j + 1;
  assert 0 <= j1 <= |b|;
  assert 0 <= i <= |a|;

  forall k | 0 <= k < |p|
    ensures p[k] != idx
  {
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
    if 0 <= p[k] < i {
      assert p[k] < i <= |a|;
      assert idx >= |a|;
      assert p[k] < idx;
    } else {
      assert |a| <= p[k] < idx;
    }
  }

  forall k, m | 0 <= k < m < |pNew|
    ensures pNew[k] != pNew[m]
  {
    if m < |p| {
      assert pNew[k] == p[k] && pNew[m] == p[m];
      assert p[k] != p[m];
    } else {
      assert m == |p|;
      assert pNew[k] == p[k];
      assert pNew[m] == idx;
      assert p[k] != idx;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1)
  {
    if k < |p| {
      assert pNew[k] == p[k];
      if 0 <= p[k] < i {
        assert 0 <= pNew[k] < i;
      } else {
        assert |a| <= p[k] < |a| + j;
        assert |a| <= pNew[k] < |a| + j1;
      }
    } else {
      assert pNew[k] == idx;
      assert |a| <= idx < |a| + j1;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures 0 <= pNew[k] < |a| + |b|
  {
    assert (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1);
    if 0 <= pNew[k] < i {
      assert i <= |a|;
      assert 0 <= pNew[k] < |a| + |b|;
    } else {
      assert |a| <= pNew[k] < |a| + j1;
      assert j1 <= |b|;
      assert 0 <= pNew[k] < |a| + |b|;
    }
  }

  assert (a + b)[idx] == b[j];

  forall k | 0 <= k < |pNew|
    ensures cNew[k] == (a + b)[pNew[k]]
  {
    assert 0 <= pNew[k] < |a| + |b|;
    if k < |c| {
      assert cNew[k] == c[k];
      assert pNew[k] == p[k];
      assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
    } else {
      assert k == |c|;
      assert cNew[k] == b[j];
      assert pNew[k] == idx;
      assert (a + b)[idx] == b[j];
    }
  }

  assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
  SortedAppend(c, b[j]);
  assert is_sorted(cNew);

  if j1 < |b| {
    SortedAt(b, j, j1);
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= b[j1]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= b[j];
        assert b[j] <= b[j1];
      } else {
        assert cNew[k] == b[j];
        assert b[j] <= b[j1];
      }
    }
  }

  if i < |a| {
    assert b[j] <= a[i];
    assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= a[i]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= a[i];
      } else {
        assert cNew[k] == b[j];
        assert b[j] <= a[i];
      }
    }
  }

  assert |cNew| == i + j1;
  assert |pNew| == |cNew|;
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1);
  assert forall k, m {:trigger pNew[k], pNew[m]} :: 0 <= k < m < |pNew| ==> pNew[k] != pNew[m];
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> 0 <= pNew[k] < |a| + |b| && cNew[k] == (a + b)[pNew[k]];
  assert i < |a| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= a[i];
  assert j1 < |b| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= b[j1];
  CloseMergeInv(a, b, cNew, pNew, i, j1);
  CopyInv(a, b, cNew, pNew, i, j1, cNew, pNew, i, j + 1);
}

lemma LemValidAtEnd(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires MergeInv(a, b, c, p, i, j)
  requires i == |a| && j == |b|
  ensures is_sorted(c)
  ensures |c| == |a| + |b|
  ensures is_valid_index_permutation(p, |a| + |b|)
  ensures forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]]
{
  OpenMergeInv(a, b, c, p, i, j);
  var n := |a| + |b|;
  assert |c| == i + j == n;
  assert |p| == |c| == n;
  assert is_sorted(c);

  forall k | 0 <= k < n
    ensures 0 <= p[k] < n
  {
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  forall k, m | 0 <= k < m < n
    ensures p[k] != p[m]
  {
    assert p[k] != p[m];
  }

  assert forall k {:trigger p[k]} :: 0 <= k < n ==> 0 <= p[k] < n;
  assert forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < n ==> p[k] != p[m];
  ClosePerm(p, n);

  forall k | 0 <= k < |c|
    ensures c[k] == (a + b)[p[k]]
  {
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }
  assert forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]];
}

method merge(a: seq<int>, b: seq<int>) returns (c: seq<int>, ghost p: seq<int>)
  requires is_sorted(a)
  requires is_sorted(b)
  ensures is_sorted(c)
  ensures |c| == |a| + |b|
  ensures is_valid_index_permutation(p, |a| + |b|)
  ensures forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]]
{
  c := [];
  p := [];
  var i := 0;
  var j := 0;
  MergeInvInit(a, b, c, p, i, j);

  while i < |a| || j < |b|
    invariant MergeInv(a, b, c, p, i, j)
    decreases |a| + |b| - i - j
  {
    OpenMergeInv(a, b, c, p, i, j);
    assert 0 <= i <= |a|;
    assert 0 <= j <= |b|;

    if i < |a| && j < |b| && a[i] <= b[j] {
      var i0 := i;
      var v0 := |a| + |b| - i0 - j;
      var cNew := c + [a[i0]];
      ghost var pNew := p + [i0];
      assert a[i0] <= b[j];
      LemTakeA(a, b, c, p, i0, j, cNew, pNew);
      c := cNew;
      p := pNew;
      i := i0 + 1;
      CopyInv(a, b, cNew, pNew, i0 + 1, j, c, p, i, j);
      assert |a| + |b| - i - j == v0 - 1;
    } else if i < |a| && j == |b| {
      var i0 := i;
      var v0 := |a| + |b| - i0 - j;
      var cNew := c + [a[i0]];
      ghost var pNew := p + [i0];
      assert j == |b|;
      assert j < |b| ==> a[i0] <= b[j];
      LemTakeA(a, b, c, p, i0, j, cNew, pNew);
      c := cNew;
      p := pNew;
      i := i0 + 1;
      CopyInv(a, b, cNew, pNew, i0 + 1, j, c, p, i, j);
      assert |a| + |b| - i - j == v0 - 1;
    } else {
      if j == |b| {
        assert i < |a| || j < |b|;
        assert !(j < |b|);
        assert i < |a|;
        assert !(i < |a| && j == |b|);
        assert false;
      }
      assert j != |b|;
      assert j < |b|;
      if i < |a| {
        if a[i] <= b[j] {
          assert i < |a| && j < |b| && a[i] <= b[j];
          assert false;
        }
        assert b[j] <= a[i];
      }
      assert i < |a| ==> b[j] <= a[i];
      var j0 := j;
      var v0 := |a| + |b| - i - j0;
      var cNew := c + [b[j0]];
      ghost var pNew := p + [|a| + j0];
      LemTakeB(a, b, c, p, i, j0, cNew, pNew);
      c := cNew;
      p := pNew;
      j := j0 + 1;
      CopyInv(a, b, cNew, pNew, i, j0 + 1, c, p, i, j);
      assert |a| + |b| - i - j == v0 - 1;
    }
  }

  OpenMergeInv(a, b, c, p, i, j);
  assert !(i < |a|);
  assert !(j < |b|);
  assert i == |a| && j == |b|;
  LemValidAtEnd(a, b, c, p, i, j);
}

ghost function ConcatIndex(pL: seq<int>, pR: seq<int>, mid: int, n: int, i: int): int
  requires 0 <= i < n
  requires 0 <= mid <= n
  requires |pL| == mid
  requires |pR| == n - mid
  ensures i < mid ==> ConcatIndex(pL, pR, mid, n, i) == pL[i]
  ensures i >= mid ==> ConcatIndex(pL, pR, mid, n, i) == mid + pR[i - mid]
{
  if i < mid then pL[i] else mid + pR[i - mid]
}

lemma LemConcat(
  v: seq<int>, ls: seq<int>, rs: seq<int>,
  pL: seq<int>, pR: seq<int>, mid: int
) returns (pc: seq<int>)
  requires 0 <= mid <= |v|
  requires |ls| == mid
  requires |rs| == |v| - mid
  requires is_valid_index_permutation(pL, mid)
  requires is_valid_index_permutation(pR, |v| - mid)
  requires forall i {:trigger pL[i]} :: 0 <= i < mid ==> ls[i] == v[..mid][pL[i]]
  requires forall i {:trigger pR[i]} :: 0 <= i < |v| - mid ==> rs[i] == v[mid..][pR[i]]
  ensures is_valid_index_permutation(pc, |v|)
  ensures forall i {:trigger pc[i]} :: 0 <= i < |v| ==> (ls + rs)[i] == v[pc[i]]
{
  var n := |v|;
  OpenPerm(pL, mid);
  OpenPerm(pR, n - mid);
  assert |pL| == mid;
  assert |pR| == n - mid;
  assert 0 <= mid <= n;
  pc := seq(n, i => ConcatIndex(pL, pR, mid, n, i));
  assert |pc| == n;
  assert |ls + rs| == n;

  forall i | 0 <= i < n
    ensures 0 <= pc[i] < n
    ensures (ls + rs)[i] == v[pc[i]]
  {
    assert pc[i] == ConcatIndex(pL, pR, mid, n, i);
    if i < mid {
      assert ConcatIndex(pL, pR, mid, n, i) == pL[i];
      assert pc[i] == pL[i];
      PermInRange(pL, mid, i);
      assert 0 <= pL[i] < mid <= n;
      assert (ls + rs)[i] == ls[i];
      assert ls[i] == v[..mid][pL[i]];
      assert 0 <= pL[i] < mid;
      assert v[..mid][pL[i]] == v[pL[i]];
      assert v[pL[i]] == v[pc[i]];
    } else {
      assert ConcatIndex(pL, pR, mid, n, i) == mid + pR[i - mid];
      assert pc[i] == mid + pR[i - mid];
      assert 0 <= i - mid < n - mid;
      PermInRange(pR, n - mid, i - mid);
      assert 0 <= pR[i - mid] < n - mid;
      assert mid <= pc[i] < n;
      assert (ls + rs)[i] == rs[i - mid];
