  requires 0 in S
  requires forall u, i :: 0 <= u < |G| && 0 <= i < |G[u]| ==> (u, G[u][i].0, G[u][i].1) in E
  requires !(exists k :: 0 <= k < |E| && E[k].0 in S && E[k].1 !in S)
