lemma UnreachedShrink(R: set<int>, n: int, v: int)
  requires 0 <= v < n && v !in R
  ensures Unreached(R + {v}, n) < Unreached(R, n)
{
  var A := Unreached(R, n);
  var B := Unreached(R + {v}, n);
  assert v in A;
  assert v !in B;
  assert forall x :: x in B ==> x in A;
  assert B <= A;
  assert B != A;
}

lemma CardAddOne(S: set<int>, v: int)
  requires v !in S
  ensures |S + {v}| == |S| + 1
{
