lemma RangeCard(n: int)
  requires n >= 0
  ensures |set i | 0 <= i < n| == n
  decreases n
{
  if n == 0 {
    assert (set i | 0 <= i < n) == {};
  } else {
    RangeCard(n - 1);
    var A := set i | 0 <= i < n - 1;
    assert (set i | 0 <= i < n) == A + {n - 1};
    assert n - 1 !in A;
    CardAddOne(A, n - 1);
  }
}

