    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
    var g := graph.adj;
    var n := |g|;

    ghost var witness :=
        spanning_tree_witness(graph);

    var items := graph_edges_from(g, 0);
    var candidates := powers(items, n - 1);

    assert forall i: int ::
        0 <= i < |witness| ==> witness[i] in items by {
        forall i: int | 0 <= i < |witness|
            ensures witness[i] in items
        {
            assert has_edge(
                g,
                witness[i].0,
                witness[i].1,
                witness[i].2);
            valid_edge_in_graph_edges(g, witness[i]);
