    powers_complete(items, witness);
    assert |witness| == n - 1;
    assert witness in candidates;

    spanning_implies_concretely_spanning(g, witness);

    edges := choose_best(candidates, n);

    powers_sound(items, n - 1, edges);

    assert are_valid_edges(g, edges) by {
        forall i: int | 0 <= i < |edges|
            ensures has_edge(
