                    valid_edge_in_graph_edges(g, other[i]);
                }
            }

            powers_complete(items, other);
            assert |other| == n - 1;
            assert other in candidates;

            spanning_implies_concretely_spanning(g, other);

            concrete_weight_equivalence(edges);
            concrete_weight_equivalence(other);
        }
    }
