  assert n == 2 * m + r;
  assert 0 <= r < 2;
  assert m >= 0;
  if m == 0 {
    assert n == r;
    assert n < 2;
    assert false;
  }
  assert m >= 1;
  assert n >= 2 * m;
  assert 2 * m >= m + 1;
  assert n >= m + 1;
  assert m < n;
  assert n - m == m + r;
  assert n - m >= 1;
  assert n - m < n;
}

lemma VariantPos(a: int, b: int, i: int, j: int)
  requires 0 <= i <= a
  requires 0 <= j <= b
  requires i < a || j < b
  ensures a + b - i - j >= 1
{
  if i < a {
    assert a - i >= 1;
    assert 0 <= b - j;
    assert a + b - i - j >= 1;
  } else {
    assert !(i < a);
    assert i == a;
    assert j < b;
    assert b - j >= 1;
    assert a - i == 0;
    assert a + b - i - j >= 1;
  }
}

ghost predicate MergeInv(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int) {
  && 0 <= i <= |a|
  && 0 <= j <= |b|
  && |c| == i + j
  && |p| == |c|
  && is_sorted(c)
  && (forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j))
  && (forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m])
  && (forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]])
  && (i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i])
  && (j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j])
}

lemma OpenMergeInv(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires MergeInv(a, b, c, p, i, j)
  ensures 0 <= i <= |a|
  ensures 0 <= j <= |b|
  ensures |c| == i + j
  ensures |p| == |c|
  ensures is_sorted(c)
  ensures forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j)
  ensures forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m]
  ensures forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]]
  ensures i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i]
  ensures j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j]
{
}

lemma CloseMergeInv(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires 0 <= i <= |a|
  requires 0 <= j <= |b|
  requires |c| == i + j
  requires |p| == |c|
  requires is_sorted(c)
  requires forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j)
  requires forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m]
  requires forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]]
  requires i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i]
  requires j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j]
  ensures MergeInv(a, b, c, p, i, j)
{
}

lemma MergeInvInit(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires c == [] && p == [] && i == 0 && j == 0
  ensures MergeInv(a, b, c, p, i, j)
{
  SortedShort(c);
  assert 0 <= i <= |a|;
  assert 0 <= j <= |b|;
  assert |c| == i + j;
  assert |p| == |c|;
  assert is_sorted(c);
  assert forall k {:trigger p[k]} :: 0 <= k < |p| ==> (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
  assert forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < |p| ==> p[k] != p[m];
  assert forall k {:trigger p[k]} :: 0 <= k < |p| ==> 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  assert i < |a| ==> forall k :: 0 <= k < |c| ==> c[k] <= a[i];
  assert j < |b| ==> forall k :: 0 <= k < |c| ==> c[k] <= b[j];
  CloseMergeInv(a, b, c, p, i, j);
}

lemma CopyInv(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>, i: int, j: int,
  c2: seq<int>, p2: seq<int>, i2: int, j2: int
)
  requires MergeInv(a, b, c, p, i, j)
  requires c2 == c && p2 == p && i2 == i && j2 == j
  ensures MergeInv(a, b, c2, p2, i2, j2)
{
  OpenMergeInv(a, b, c, p, i, j);
  assert 0 <= i2 <= |a|;
  assert 0 <= j2 <= |b|;
  assert |c2| == i2 + j2;
  assert |p2| == |c2|;

  OpenSorted(c);
  forall ia, ja | 0 <= ia < ja < |c2|
    ensures c2[ia] <= c2[ja]
  {
    assert c2[ia] == c[ia] && c2[ja] == c[ja];
    assert c[ia] <= c[ja];
  }
  assert forall ia, ja :: 0 <= ia < ja < |c2| ==> c2[ia] <= c2[ja];
  CloseSorted(c2);

  forall k | 0 <= k < |p2|
    ensures (0 <= p2[k] < i2) || (|a| <= p2[k] < |a| + j2)
  {
    assert p2[k] == p[k];
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
  }

  forall k, m | 0 <= k < m < |p2|
    ensures p2[k] != p2[m]
  {
    assert p2[k] == p[k] && p2[m] == p[m];
    assert p[k] != p[m];
  }

  forall k | 0 <= k < |p2|
    ensures 0 <= p2[k] < |a| + |b|
  {
    assert p2[k] == p[k];
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  forall k | 0 <= k < |p2|
    ensures c2[k] == (a + b)[p2[k]]
  {
    assert p2[k] == p[k];
    assert 0 <= p2[k] < |a| + |b|;
    assert c2[k] == c[k];
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  if i2 < |a| {
    assert i == i2 && i < |a|;
    assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
    forall k | 0 <= k < |c2|
      ensures c2[k] <= a[i2]
    {
      assert c[k] <= a[i];
      assert c2[k] == c[k];
      assert a[i2] == a[i];
    }
  }

  if j2 < |b| {
    assert j == j2 && j < |b|;
    assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
    forall k | 0 <= k < |c2|
      ensures c2[k] <= b[j2]
    {
      assert c[k] <= b[j];
      assert c2[k] == c[k];
      assert b[j2] == b[j];
    }
  }

  assert forall k {:trigger p2[k]} :: 0 <= k < |p2| ==> (0 <= p2[k] < i2) || (|a| <= p2[k] < |a| + j2);
  assert forall k, m {:trigger p2[k], p2[m]} :: 0 <= k < m < |p2| ==> p2[k] != p2[m];
  assert forall k {:trigger p2[k]} :: 0 <= k < |p2| ==> 0 <= p2[k] < |a| + |b| && c2[k] == (a + b)[p2[k]];
  assert i2 < |a| ==> forall k :: 0 <= k < |c2| ==> c2[k] <= a[i2];
  assert j2 < |b| ==> forall k :: 0 <= k < |c2| ==> c2[k] <= b[j2];
  CloseMergeInv(a, b, c2, p2, i2, j2);
}

lemma LemTakeA(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>,
  i: int, j: int,
  cNew: seq<int>, pNew: seq<int>
)
  requires is_sorted(a) && is_sorted(b)
  requires MergeInv(a, b, c, p, i, j)
  requires 0 <= i < |a|
  requires j < |b| ==> a[i] <= b[j]
  requires cNew == c + [a[i]]
  requires pNew == p + [i]
  ensures MergeInv(a, b, cNew, pNew, i + 1, j)
{
  OpenMergeInv(a, b, c, p, i, j);
  var i1 := i + 1;
  assert i1 == i + 1;
  assert 0 <= i1 <= |a|;
  assert |pNew| == |p| + 1;
  assert |cNew| == |c| + 1;
  assert |c| == |p|;

  forall k | 0 <= k < |p|
    ensures p[k] != i
  {
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
    if 0 <= p[k] < i {
      assert p[k] != i;
    } else {
      assert |a| <= p[k] < |a| + j;
      assert i < |a|;
      assert p[k] != i;
    }
  }

  forall k, m | 0 <= k < m < |pNew|
    ensures pNew[k] != pNew[m]
  {
    if m < |p| {
      assert pNew[k] == p[k] && pNew[m] == p[m];
      assert p[k] != p[m];
    } else {
      assert m == |p|;
      assert pNew[k] == p[k];
      assert pNew[m] == i;
      assert p[k] != i;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j)
  {
    if k < |p| {
      assert pNew[k] == p[k];
      assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
      if 0 <= p[k] < i {
        assert 0 <= pNew[k] < i1;
      } else {
        assert |a| <= p[k] < |a| + j;
        assert |a| <= pNew[k] < |a| + j;
      }
    } else {
      assert pNew[k] == i;
      assert 0 <= i < i1;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures 0 <= pNew[k] < |a| + |b|
  {
    assert (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j);
    if 0 <= pNew[k] < i1 {
      assert i1 <= |a|;
      assert 0 <= pNew[k] < |a| + |b|;
    } else {
      assert |a| <= pNew[k] < |a| + j;
      assert j <= |b|;
      assert 0 <= pNew[k] < |a| + |b|;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures cNew[k] == (a + b)[pNew[k]]
  {
    assert 0 <= pNew[k] < |a| + |b|;
    if k < |c| {
      assert cNew[k] == c[k];
      assert pNew[k] == p[k];
      assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
    } else {
      assert k == |c|;
      assert cNew[k] == a[i];
      assert pNew[k] == i;
      assert 0 <= i < |a|;
      assert (a + b)[i] == a[i];
    }
  }

  assert i < |a|;
  assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
  SortedAppend(c, a[i]);
  assert cNew == c + [a[i]];
  assert is_sorted(cNew);

  if i1 < |a| {
    SortedAt(a, i, i1);
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= a[i1]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= a[i];
        assert a[i] <= a[i1];
      } else {
        assert cNew[k] == a[i];
        assert a[i] <= a[i1];
      }
    }
  }

  if j < |b| {
    assert a[i] <= b[j];
    assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= b[j]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= b[j];
      } else {
        assert cNew[k] == a[i];
        assert a[i] <= b[j];
      }
    }
  }

  assert |cNew| == i1 + j;
  assert |pNew| == |cNew|;
  assert 0 <= j <= |b|;
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> (0 <= pNew[k] < i1) || (|a| <= pNew[k] < |a| + j);
  assert forall k, m {:trigger pNew[k], pNew[m]} :: 0 <= k < m < |pNew| ==> pNew[k] != pNew[m];
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> 0 <= pNew[k] < |a| + |b| && cNew[k] == (a + b)[pNew[k]];
  assert i1 < |a| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= a[i1];
  assert j < |b| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= b[j];
  CloseMergeInv(a, b, cNew, pNew, i1, j);
  CopyInv(a, b, cNew, pNew, i1, j, cNew, pNew, i + 1, j);
}

lemma LemTakeB(
  a: seq<int>, b: seq<int>,
  c: seq<int>, p: seq<int>,
  i: int, j: int,
  cNew: seq<int>, pNew: seq<int>
)
  requires is_sorted(a) && is_sorted(b)
  requires MergeInv(a, b, c, p, i, j)
  requires 0 <= j < |b|
  requires i < |a| ==> b[j] <= a[i]
  requires cNew == c + [b[j]]
  requires pNew == p + [|a| + j]
  ensures MergeInv(a, b, cNew, pNew, i, j + 1)
{
  OpenMergeInv(a, b, c, p, i, j);
  var j1 := j + 1;
  var idx := |a| + j;
  assert j1 == j + 1;
  assert 0 <= j1 <= |b|;
  assert 0 <= i <= |a|;
  assert |pNew| == |p| + 1;
  assert |cNew| == |c| + 1;
  assert |c| == |p|;
  assert idx == |a| + j;
  assert 0 <= idx < |a| + |b|;
  assert (a + b)[idx] == b[j];

  forall k | 0 <= k < |p|
    ensures p[k] != idx
  {
    assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
    if 0 <= p[k] < i {
      assert p[k] < i <= |a|;
      assert idx >= |a|;
      assert p[k] < idx;
      assert p[k] != idx;
    } else {
      assert |a| <= p[k] < |a| + j;
      assert p[k] < idx;
      assert p[k] != idx;
    }
  }

  forall k, m | 0 <= k < m < |pNew|
    ensures pNew[k] != pNew[m]
  {
    if m < |p| {
      assert pNew[k] == p[k] && pNew[m] == p[m];
      assert p[k] != p[m];
    } else {
      assert m == |p|;
      assert pNew[k] == p[k];
      assert pNew[m] == idx;
      assert p[k] != idx;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1)
  {
    if k < |p| {
      assert pNew[k] == p[k];
      assert (0 <= p[k] < i) || (|a| <= p[k] < |a| + j);
      if 0 <= p[k] < i {
        assert 0 <= pNew[k] < i;
      } else {
        assert |a| <= p[k] < |a| + j;
        assert |a| <= pNew[k] < |a| + j1;
      }
    } else {
      assert pNew[k] == idx;
      assert |a| <= idx < |a| + j1;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures 0 <= pNew[k] < |a| + |b|
  {
    assert (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1);
    if 0 <= pNew[k] < i {
      assert i <= |a|;
      assert 0 <= pNew[k] < |a| + |b|;
    } else {
      assert |a| <= pNew[k] < |a| + j1;
      assert j1 <= |b|;
      assert 0 <= pNew[k] < |a| + |b|;
    }
  }

  forall k | 0 <= k < |pNew|
    ensures cNew[k] == (a + b)[pNew[k]]
  {
    assert 0 <= pNew[k] < |a| + |b|;
    if k < |c| {
      assert cNew[k] == c[k];
      assert pNew[k] == p[k];
      assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
    } else {
      assert k == |c|;
      assert cNew[k] == b[j];
      assert pNew[k] == idx;
      assert (a + b)[idx] == b[j];
    }
  }

  assert j < |b|;
  assert forall k :: 0 <= k < |c| ==> c[k] <= b[j];
  SortedAppend(c, b[j]);
  assert is_sorted(cNew);

  if j1 < |b| {
    SortedAt(b, j, j1);
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= b[j1]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= b[j];
        assert b[j] <= b[j1];
      } else {
        assert cNew[k] == b[j];
        assert b[j] <= b[j1];
      }
    }
  }

  if i < |a| {
    assert b[j] <= a[i];
    assert forall k :: 0 <= k < |c| ==> c[k] <= a[i];
    forall k | 0 <= k < |cNew|
      ensures cNew[k] <= a[i]
    {
      if k < |c| {
        assert cNew[k] == c[k];
        assert c[k] <= a[i];
      } else {
        assert cNew[k] == b[j];
        assert b[j] <= a[i];
      }
    }
  }

  assert |cNew| == i + j1;
  assert |pNew| == |cNew|;
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> (0 <= pNew[k] < i) || (|a| <= pNew[k] < |a| + j1);
  assert forall k, m {:trigger pNew[k], pNew[m]} :: 0 <= k < m < |pNew| ==> pNew[k] != pNew[m];
  assert forall k {:trigger pNew[k]} :: 0 <= k < |pNew| ==> 0 <= pNew[k] < |a| + |b| && cNew[k] == (a + b)[pNew[k]];
  assert i < |a| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= a[i];
  assert j1 < |b| ==> forall k :: 0 <= k < |cNew| ==> cNew[k] <= b[j1];
  CloseMergeInv(a, b, cNew, pNew, i, j1);
  CopyInv(a, b, cNew, pNew, i, j1, cNew, pNew, i, j + 1);
}

lemma LemValidAtEnd(a: seq<int>, b: seq<int>, c: seq<int>, p: seq<int>, i: int, j: int)
  requires MergeInv(a, b, c, p, i, j)
  requires i == |a| && j == |b|
  ensures is_sorted(c)
  ensures |c| == |a| + |b|
  ensures is_valid_index_permutation(p, |a| + |b|)
  ensures forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]]
{
  OpenMergeInv(a, b, c, p, i, j);
  var n := |a| + |b|;
  assert |c| == i + j == n;
  assert |p| == |c| == n;
  assert is_sorted(c);

  forall k | 0 <= k < n
    ensures 0 <= p[k] < n
  {
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }

  forall k, m | 0 <= k < m < n
    ensures p[k] != p[m]
  {
    assert p[k] != p[m];
  }

  assert forall k {:trigger p[k]} :: 0 <= k < n ==> 0 <= p[k] < n;
  assert forall k, m {:trigger p[k], p[m]} :: 0 <= k < m < n ==> p[k] != p[m];
  ClosePerm(p, n);

  forall k | 0 <= k < |c|
    ensures c[k] == (a + b)[p[k]]
  {
    assert 0 <= p[k] < |a| + |b| && c[k] == (a + b)[p[k]];
  }
  assert forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]];
}

method merge(a: seq<int>, b: seq<int>) returns (c: seq<int>, ghost p: seq<int>)
  requires is_sorted(a)
  requires is_sorted(b)
  ensures is_sorted(c)
  ensures |c| == |a| + |b|
  ensures is_valid_index_permutation(p, |a| + |b|)
  ensures forall k {:trigger p[k]} :: 0 <= k < |c| ==> c[k] == (a + b)[p[k]]
{
  c := [];
  p := [];
  var i := 0;
  var j := 0;
  MergeInvInit(a, b, c, p, i, j);

  while i < |a| || j < |b|
    invariant MergeInv(a, b, c, p, i, j)
    decreases |a| + |b| - i - j
  {
    OpenMergeInv(a, b, c, p, i, j);
    assert 0 <= i <= |a|;
    assert 0 <= j <= |b|;
    ghost var before := |a| + |b| - i - j;
    VariantPos(|a|, |b|, i, j);
    assert before >= 1;

    if i == |a| {
      assert !(i < |a|);
      assert i < |a| || j < |b|;
      assert j < |b|;
      assert 0 <= j < |b|;
      assert i < |a| ==> b[j] <= a[i];
      var j0 := j;
      var cNew := c + [b[j0]];
      ghost var pNew := p + [|a| + j0];
      LemTakeB(a, b, c, p, i, j0, cNew, pNew);
      c := cNew;
      p := pNew;
      j := j0 + 1;
      CopyInv(a, b, cNew, pNew, i, j0 + 1, c, p, i, j);
      assert |a| + |b| - i - j == before - 1;
    } else if j == |b| {
      assert i != |a|;
      assert i < |a|;
      assert 0 <= i < |a|;
      assert j < |b| ==> a[i] <= b[j];
      var i0 := i;
      var cNew := c + [a[i0]];
      ghost var pNew := p + [i0];
      LemTakeA(a, b, c, p, i0, j, cNew, pNew);
      c := cNew;
      p := pNew;
      i := i0 + 1;
      CopyInv(a, b, cNew, pNew, i0 + 1, j, c, p, i, j);
      assert |a| + |b| - i - j == before - 1;
    } else {
      assert i != |a|;
