lemma LemConcat(
  v: seq<int>, ls: seq<int>, rs: seq<int>,
  pL: seq<int>, pR: seq<int>, mid: int
) returns (pc: seq<int>)
  requires 0 <= mid <= |v|
  requires |ls| == mid
  requires |rs| == |v| - mid
  requires is_valid_index_permutation(pL, mid)
  requires is_valid_index_permutation(pR, |v| - mid)
  requires forall i {:trigger pL[i]} :: 0 <= i < mid ==> ls[i] == v[..mid][pL[i]]
  requires forall i {:trigger pR[i]} :: 0 <= i < |v| - mid ==> rs[i] == v[mid..][pR[i]]
  ensures is_valid_index_permutation(pc, |v|)
  ensures forall i {:trigger pc[i]} :: 0 <= i < |v| ==> (ls + rs)[i] == v[pc[i]]
{
  var n := |v|;
  OpenPerm(pL, mid);
  OpenPerm(pR, n - mid);
  assert |pL| == mid;
  assert |pR| == n - mid;
  assert 0 <= mid <= n;
  pc := seq(n, i => ConcatIndex(pL, pR, mid, n, i));
  assert |pc| == n;
  assert |ls + rs| == n;

  forall i | 0 <= i < n
    ensures 0 <= pc[i] < n
    ensures (ls + rs)[i] == v[pc[i]]
  {
    assert pc[i] == ConcatIndex(pL, pR, mid, n, i);
    if i < mid {
      assert ConcatIndex(pL, pR, mid, n, i) == pL[i];
      assert pc[i] == pL[i];
      PermInRange(pL, mid, i);
      assert 0 <= pL[i] < mid <= n;
      assert (ls + rs)[i] == ls[i];
      assert ls[i] == v[..mid][pL[i]];
      assert 0 <= pL[i] < mid;
      assert v[..mid][pL[i]] == v[pL[i]];
      assert v[pL[i]] == v[pc[i]];
    } else {
      assert ConcatIndex(pL, pR, mid, n, i) == mid + pR[i - mid];
      assert pc[i] == mid + pR[i - mid];
      assert 0 <= i - mid < n - mid;
      PermInRange(pR, n - mid, i - mid);
      assert 0 <= pR[i - mid] < n - mid;
      assert mid <= pc[i] < n;
      assert (ls + rs)[i] == rs[i - mid];
      assert rs[i - mid] == v[mid..][pR[i - mid]];
      assert v[mid..][pR[i - mid]] == v[mid + pR[i - mid]];
      assert v[mid + pR[i - mid]] == v[pc[i]];
    }
  }

  forall i, j | 0 <= i < j < n
    ensures pc[i] != pc[j]
  {
    assert pc[i] == ConcatIndex(pL, pR, mid, n, i);
    assert pc[j] == ConcatIndex(pL, pR, mid, n, j);
    if j < mid {
      assert pc[i] == pL[i] && pc[j] == pL[j];
      PermNeq(pL, mid, i, j);
      assert pc[i] != pc[j];
    } else if i >= mid {
      assert pc[i] == mid + pR[i - mid];
      assert pc[j] == mid + pR[j - mid];
      assert 0 <= i - mid < j - mid < n - mid;
      PermNeq(pR, n - mid, i - mid, j - mid);
      assert pR[i - mid] != pR[j - mid];
      assert pc[i] != pc[j];
    } else {
      assert i < mid <= j;
      assert pc[i] == pL[i];
      PermInRange(pL, mid, i);
      assert pc[i] < mid;
      assert pc[j] == mid + pR[j - mid];
      PermInRange(pR, n - mid, j - mid);
      assert 0 <= pR[j - mid];
      assert pc[j] >= mid;
      assert pc[i] < pc[j];
      assert pc[i] != pc[j];
    }
  }

  assert forall i {:trigger pc[i]} :: 0 <= i < n ==> 0 <= pc[i] < n;
  assert forall i, j {:trigger pc[i], pc[j]} :: 0 <= i < j < n ==> pc[i] != pc[j];
  ClosePerm(pc, n);
  assert forall i {:trigger pc[i]} :: 0 <= i < n ==> (ls + rs)[i] == v[pc[i]];
}

