lemma LemCompose(
  a: seq<int>, b: seq<int>, c: seq<int>,
  p: seq<int>, q: seq<int>
) returns (r: seq<int>)
  requires |a| == |b| == |c|
  requires is_valid_index_permutation(p, |a|)
  requires is_valid_index_permutation(q, |b|)
  requires forall i {:trigger p[i]} :: 0 <= i < |a| ==> b[i] == a[p[i]]
  requires forall i {:trigger q[i]} :: 0 <= i < |b| ==> c[i] == b[q[i]]
  ensures is_valid_index_permutation(r, |a|)
  ensures forall i {:trigger r[i]} :: 0 <= i < |a| ==> c[i] == a[r[i]]
{
  OpenPerm(p, |a|);
  OpenPerm(q, |b|);
  assert |p| == |a| && |q| == |b| && |p| == |q|;

  forall i | 0 <= i < |q|
    ensures 0 <= q[i] < |p|
  {
    PermInRange(q, |q|, i);
    assert |p| == |q|;
    assert 0 <= q[i] < |p|;
  }
  assert forall i {:trigger q[i]} :: 0 <= i < |q| ==> 0 <= q[i] < |p|;

  r := seq(|q|, i => ComposeIndex(p, q, i));
  assert |r| == |a|;

  forall i | 0 <= i < |a|
    ensures 0 <= r[i] < |a|
    ensures r[i] == p[q[i]]
    ensures c[i] == a[r[i]]
  {
    PermInRange(q, |b|, i);
    assert 0 <= q[i] < |p|;
    assert r[i] == ComposeIndex(p, q, i);
    assert ComposeIndex(p, q, i) == p[q[i]];
    PermInRange(p, |a|, q[i]);
    assert 0 <= p[q[i]] < |a|;
    assert c[i] == b[q[i]];
    assert 0 <= q[i] < |a|;
    assert b[q[i]] == a[p[q[i]]];
    assert a[p[q[i]]] == a[r[i]];
  }

  forall i, j | 0 <= i < j < |a|
    ensures r[i] != r[j]
  {
    PermNeq(q, |b|, i, j);
    PermInRange(q, |b|, i);
    PermInRange(q, |b|, j);
    assert r[i] == p[q[i]];
    assert r[j] == p[q[j]];
    assert q[i] != q[j];
    if q[i] < q[j] {
      assert 0 <= q[i] < q[j] < |a|;
      PermNeq(p, |a|, q[i], q[j]);
      assert p[q[i]] != p[q[j]];
    } else {
      assert q[j] < q[i];
      assert 0 <= q[j] < q[i] < |a|;
      PermNeq(p, |a|, q[j], q[i]);
      assert p[q[j]] != p[q[i]];
    }
    assert r[i] != r[j];
  }

  assert forall i {:trigger r[i]} :: 0 <= i < |a| ==> 0 <= r[i] < |a|;
  assert forall i, j {:trigger r[i], r[j]} :: 0 <= i < j < |a| ==> r[i] != r[j];
  ClosePerm(r, |a|);
  assert forall i {:trigger r[i]} :: 0 <= i < |a| ==> c[i] == a[r[i]];
}

