    else vertex_range(n - 1) + {n - 1}
}

lemma vertex_range_facts(n: nat)
    ensures |vertex_range(n)| == n
    ensures forall x: int :: x in vertex_range(n) <==> 0 <= x < n
    decreases n
{
    if n != 0 {
        vertex_range_facts(n - 1);
        assert n - 1 !in vertex_range(n - 1);
    }
}

lemma missing_vertex(vs: set<int>, n: nat)
    requires forall x: int :: x in vs ==> 0 <= x < n
    requires |vs| < n
    ensures exists x: int :: 0 <= x < n && x !in vs
{
    vertex_range_facts(n);

    assert vs <= vertex_range(n) by {
        forall x: int | x in vs
            ensures x in vertex_range(n)
        {
        }
    }

    if !(exists x: int :: 0 <= x < n && x !in vs) {
        assert vertex_range(n) <= vs by {
            forall x: int | x in vertex_range(n)
                ensures x in vs
            {
            }
        }
        assert vs == vertex_range(n);
        assert |vs| == n;
        assert false;
    }
}

lemma crossing_index(p: seq<int>, vs: set<int>)
    requires |p| >= 2
    requires p[0] in vs
    requires p[|p| - 1] !in vs
    ensures exists j: int ::
        0 < j < |p| &&
        p[j - 1] in vs &&
        p[j] !in vs
    decreases |p|
{
    if p[1] !in vs {
        assert 0 < 1 < |p|;
    } else {
        if |p| == 2 {
            assert p[1] == p[|p| - 1];
            assert false;
        }

        crossing_index(p[1..], vs);

        var k: int :|
            0 < k < |p[1..]| &&
            p[1..][k - 1] in vs &&
            p[1..][k] !in vs;

        assert 0 < k + 1 < |p|;
        assert p[k] in vs;
        assert p[k + 1] !in vs;
    }
}

lemma edge_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    u: int,
    v: int)
    requires edge_in_set(oldEdges, u, v)
    ensures edge_in_set(oldEdges + [e], u, v)
{
    var i: int :|
        0 <= i < |oldEdges| &&
        ((oldEdges[i].0 == u && oldEdges[i].1 == v) ||
         (oldEdges[i].0 == v && oldEdges[i].1 == u));

    assert (oldEdges + [e])[i] == oldEdges[i];
}

lemma path_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    p: seq<int>)
    requires path_follows_edges(oldEdges, p)
    ensures path_follows_edges(oldEdges + [e], p)
{
    forall k: int | 0 <= k < |p| - 1
        ensures edge_in_set(oldEdges + [e], p[k], p[k + 1])
    {
        edge_in_extended(oldEdges, e, p[k], p[k + 1]);
    }
}

lemma connected_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    u: int,
    v: int)
    requires edges_connected(oldEdges, u, v)
    ensures edges_connected(oldEdges + [e], u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(oldEdges, p);

    path_in_extended(oldEdges, e, p);
}

lemma path_append_vertex(
    edges: seq<Edge>,
    p: seq<int>,
    v: int)
    requires |p| > 0
    requires path_follows_edges(edges, p)
    requires edge_in_set(edges, p[|p| - 1], v)
    ensures path_follows_edges(edges, p + [v])
{
    forall k: int | 0 <= k < |p + [v]| - 1
        ensures edge_in_set(edges, (p + [v])[k], (p + [v])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + [v])[k] == p[k];
            assert (p + [v])[k + 1] == p[k + 1];
        } else {
            assert k == |p| - 1;
            assert (p + [v])[k] == p[|p| - 1];
            assert (p + [v])[k + 1] == v;
        }
    }
}

lemma path_prepend_vertex(
    edges: seq<Edge>,
    u: int,
    p: seq<int>)
    requires |p| > 0
    requires path_follows_edges(edges, p)
    requires edge_in_set(edges, u, p[0])
    ensures path_follows_edges(edges, [u] + p)
{
    forall k: int | 0 <= k < |[u] + p| - 1
        ensures edge_in_set(edges, ([u] + p)[k], ([u] + p)[k + 1])
    {
        if k == 0 {
            assert ([u] + p)[0] == u;
            assert ([u] + p)[1] == p[0];
        } else {
            assert ([u] + p)[k] == p[k - 1];
            assert ([u] + p)[k + 1] == p[k];
            assert 0 <= k - 1 < |p| - 1;
        }
    }
}

lemma connected_append_vertex(
    edges: seq<Edge>,
    u: int,
    x: int,
    v: int)
    requires edges_connected(edges, u, x)
    requires edge_in_set(edges, x, v)
    ensures edges_connected(edges, u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == x &&
        path_follows_edges(edges, p);

    path_append_vertex(edges, p, v);
}

lemma connected_prepend_vertex(
    edges: seq<Edge>,
    u: int,
    x: int,
    v: int)
    requires edge_in_set(edges, u, x)
    requires edges_connected(edges, x, v)
    ensures edges_connected(edges, u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == x &&
        p[|p| - 1] == v &&
        path_follows_edges(edges, p);

    path_prepend_vertex(edges, u, p);
}

lemma path_join(
    edges: seq<Edge>,
    p: seq<int>,
    q: seq<int>)
    requires |p| > 0
    requires |q| > 0
    requires p[|p| - 1] == q[0]
    requires path_follows_edges(edges, p)
    requires path_follows_edges(edges, q)
    ensures path_follows_edges(edges, p + q[1..])
{
    if |q| == 1 {
        assert q[1..] == [];
    } else {
        forall k: int | 0 <= k < |p + q[1..]| - 1
            ensures edge_in_set(
                edges,
                (p + q[1..])[k],
                (p + q[1..])[k + 1])
        {
            if k < |p| - 1 {
                assert (p + q[1..])[k] == p[k];
                assert (p + q[1..])[k + 1] == p[k + 1];
            } else if k == |p| - 1 {
                assert (p + q[1..])[k] == p[|p| - 1];
                assert (p + q[1..])[k + 1] == q[1];
                assert edge_in_set(edges, q[0], q[1]);
            } else {
                var j := k - |p| + 1;
                assert 1 <= j < |q| - 1;
                assert (p + q[1..])[k] == q[j];
                assert (p + q[1..])[k + 1] == q[j + 1];
            }
        }
    }
}

lemma connected_transitive(
    edges: seq<Edge>,
    u: int,
    x: int,
    v: int)
    requires edges_connected(edges, u, x)
    requires edges_connected(edges, x, v)
    ensures edges_connected(edges, u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == x &&
        path_follows_edges(edges, p);

    var q: seq<int> :|
        |q| > 0 &&
        q[0] == x &&
        q[|q| - 1] == v &&
        path_follows_edges(edges, q);

    path_join(edges, p, q);

    if |q| == 1 {
        assert q[0] == v;
        assert x == v;
    }
}

lemma add_valid_edge(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    e: Edge)
    requires are_valid_edges(g, edges)
    requires has_edge(g, e.0, e.1, e.2)
    ensures are_valid_edges(g, edges + [e])
{
    forall k: int | 0 <= k < |edges + [e]|
        ensures has_edge(
            g,
            (edges + [e])[k].0,
            (edges + [e])[k].1,
            (edges + [e])[k].2)
    {
        if k < |edges| {
            assert (edges + [e])[k] == edges[k];
        } else {
            assert k == |edges|;
            assert (edges + [e])[k] == e;
        }
    }
}

ghost method build_spanning_tree(
    graph: WeightedGraph,
    vs: set<int>,
    partial: seq<Edge>)
    returns (tree: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    requires 0 in vs
    requires forall x: int :: x in vs ==> 0 <= x < size(graph)
    requires are_valid_edges(view(graph), partial)
    requires |partial| == |vs| - 1
    requires forall x: int :: x in vs ==>
        edges_connected(partial, 0, x) &&
        edges_connected(partial, x, 0)
    ensures are_valid_edges(view(graph), tree)
    ensures |tree| == size(graph) - 1
    ensures forall x: int :: 0 <= x < size(graph) ==>
        edges_connected(tree, 0, x) &&
        edges_connected(tree, x, 0)
    decreases size(graph) - |vs|
{
    var n := size(graph);

    if |vs| == n {
        tree := partial;

        vertex_range_facts(n);

        assert vs <= vertex_range(n) by {
            forall x: int | x in vs
                ensures x in vertex_range(n)
            {
            }
        }

        assert vertex_range(n) <= vs by {
            forall x: int | x in vertex_range(n)
                ensures x in vs
            {
                if x !in vs {
                    assert vs + {x} <= vertex_range(n);
                    assert |vs + {x}| == |vs| + 1;
                    assert false;
                }
            }
        }

        assert vs == vertex_range(n);
    } else {
        assert |vs| < n;
        missing_vertex(vs, n);

        var target: int :| 0 <= target < n && target !in vs;

        var p: seq<int> :|
            |p| > 0 &&
            p[0] == 0 &&
            p[|p| - 1] == target &&
            path_follows_graph(view(graph), p);

        assert p[0] in vs;
        assert p[|p| - 1] !in vs;
        assert |p| >= 2;

        crossing_index(p, vs);

        var j: int :|
            0 < j < |p| &&
            p[j - 1] in vs &&
            p[j] !in vs;

        var x := p[j - 1];
        var y := p[j];

        assert graph_has_any_edge(view(graph), x, y);

        var i: int :|
            0 <= x < |view(graph)| &&
            0 <= i < |view(graph)[x]| &&
            view(graph)[x][i].0 == y;

        var w := view(graph)[x][i].1;
        var e: Edge := (x, y, w);

        var nextEdges := partial + [e];
        var nextVs := vs + {y};

        add_valid_edge(view(graph), partial, e);

        assert edge_in_set(nextEdges, x, y) by {
            assert nextEdges[|partial|] == e;
        }
        assert edge_in_set(nextEdges, y, x);

        connected_in_extended(partial, e, 0, x);
        connected_in_extended(partial, e, x, 0);
        connected_append_vertex(nextEdges, 0, x, y);
        connected_prepend_vertex(nextEdges, y, x, 0);

        forall z: int | z in nextVs
            ensures edges_connected(nextEdges, 0, z) &&
                    edges_connected(nextEdges, z, 0)
        {
            if z != y {
                assert z in vs;
                connected_in_extended(partial, e, 0, z);
                connected_in_extended(partial, e, z, 0);
            }
        }

        assert y !in vs;
        assert |nextVs| == |vs| + 1;
        assert |nextEdges| == |partial| + 1;
        assert |nextEdges| == |nextVs| - 1;

        forall z: int | z in nextVs
            ensures 0 <= z < n
        {
            if z != y {
                assert z in vs;
            }
        }

        tree := build_spanning_tree(graph, nextVs, nextEdges);
    }
}

lemma rooted_tree_is_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires forall x: int :: 0 <= x < |g| ==>
        edges_connected(edges, 0, x) &&
        edges_connected(edges, x, 0)
    ensures is_spanning(g, edges)
{
    forall u: int, v: int |
        0 <= u < |g| && 0 <= v < |g|
        ensures edges_connected(edges, u, v)
    {
        connected_transitive(edges, u, 0, v);
    }
}

ghost method spanning_tree_witness(graph: WeightedGraph)
    returns (tree: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    ensures is_spanning_tree(view(graph), tree)
{
    var initial: seq<Edge> := [];
    var initialVertices: set<int> := {0};

    assert edges_connected(initial, 0, 0) by {
        var p := [0];
        assert path_follows_edges(initial, p);
    }

    tree :=
        build_spanning_tree(graph, initialVertices, initial);

    rooted_tree_is_spanning(view(graph), tree);
}

predicate concrete_edge_in_set(edges: seq<Edge>, u: int, v: int)
{
    exists i: int ::
        0 <= i < |edges| &&
        ((edges[i].0 == u && edges[i].1 == v) ||
         (edges[i].0 == v && edges[i].1 == u))
}

function closure_step(
    edges: seq<Edge>,
    reached: set<int>,
    n: nat): set<int>
{
    set v: int |
        0 <= v < n &&
        (v in reached ||
         exists u: int ::
            u in reached &&
            concrete_edge_in_set(edges, u, v))
}

function closure(
    edges: seq<Edge>,
    n: nat,
    steps: nat): set<int>
    decreases steps
{
    if steps == 0 then {0}
    else closure_step(edges, closure(edges, n, steps - 1), n)
}

predicate concretely_spanning(n: nat, edges: seq<Edge>)
{
    n > 0 &&
    forall v: int :: 0 <= v < n ==> v in closure(edges, n, n)
}

function concrete_weight(edges: seq<Edge>): int
    decreases |edges|
{
    if |edges| == 0 then 0
    else edges[0].2 + concrete_weight(edges[1..])
}

lemma concrete_edge_equivalence(
    edges: seq<Edge>,
    u: int,
    v: int)
    ensures concrete_edge_in_set(edges, u, v)
        <==> edge_in_set(edges, u, v)
{
}

lemma closure_bounded(
    edges: seq<Edge>,
    n: nat,
    steps: nat)
    requires n > 0
    ensures forall v: int ::
        v in closure(edges, n, steps) ==> 0 <= v < n
    decreases steps
{
    if steps == 0 {
    } else {
        closure_bounded(edges, n, steps - 1);
    }
}

lemma closure_monotone_one(
    edges: seq<Edge>,
    n: nat,
    steps: nat)
    requires n > 0
    ensures closure(edges, n, steps)
        <= closure(edges, n, steps + 1)
{
    closure_bounded(edges, n, steps);

    forall v: int | v in closure(edges, n, steps)
        ensures v in closure(edges, n, steps + 1)
    {
    }
}

lemma closure_member_connected(
    edges: seq<Edge>,
    n: nat,
    steps: nat,
    v: int)
    requires n > 0
    requires v in closure(edges, n, steps)
    ensures edges_connected(edges, 0, v)
    ensures edges_connected(edges, v, 0)
    decreases steps
{
    if steps == 0 {
        assert v == 0;

        assert edges_connected(edges, 0, 0) by {
            var p := [0];
            assert path_follows_edges(edges, p);
        }
    } else {
        var previous := closure(edges, n, steps - 1);

        if v in previous {
            closure_member_connected(edges, n, steps - 1, v);
        } else {
            var u: int :|
                u in previous &&
                concrete_edge_in_set(edges, u, v);

            closure_member_connected(edges, n, steps - 1, u);
            concrete_edge_equivalence(edges, u, v);

            connected_append_vertex(edges, 0, u, v);
            connected_prepend_vertex(edges, v, u, 0);
        }
    }
}

lemma concretely_spanning_implies_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires concretely_spanning(|g|, edges)
    ensures is_spanning(g, edges)
{
    forall v: int | 0 <= v < |g|
        ensures edges_connected(edges, 0, v) &&
                edges_connected(edges, v, 0)
    {
        closure_member_connected(edges, |g|, |g|, v);
    }

    rooted_tree_is_spanning(g, edges);
}

lemma valid_edge_endpoints(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    u: int,
    v: int)
    requires are_valid_edges(g, edges)
    requires edge_in_set(edges, u, v)
    ensures 0 <= u < |g|
    ensures 0 <= v < |g|
{
    var i: int :|
        0 <= i < |edges| &&
        ((edges[i].0 == u && edges[i].1 == v) ||
         (edges[i].0 == v && edges[i].1 == u));

    assert has_edge(
        g, edges[i].0, edges[i].1, edges[i].2);

    var j: int :|
        0 <= edges[i].0 < |g| &&
        0 <= j < |g[edges[i].0]| &&
        g[edges[i].0][j].0 == edges[i].1 &&
        g[edges[i].0][j].1 == edges[i].2;

    assert 0 <= edges[i].1 < |g|;
}

lemma closure_growth(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    steps: nat)
    requires |g| > 0
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    requires steps < |g|
    requires !(forall v: int ::
        0 <= v < |g| ==> v in closure(edges, |g|, steps))
    ensures |closure(edges, |g|, steps + 1)|
        >= |closure(edges, |g|, steps)| + 1
{
    var reached := closure(edges, |g|, steps);

    var target: int :|
        0 <= target < |g| &&
        target !in reached;

    assert edges_connected(edges, 0, target);

    var p: seq<int> :|
        |p| > 0 &&
        p[0] == 0 &&
        p[|p| - 1] == target &&
        path_follows_edges(edges, p);

    assert 0 in reached by {
        if steps == 0 {
        } else {
            closure_monotone_one(edges, |g|, 0);
            assert 0 in closure(edges, |g|, 1);

            var k: nat := 1;
            while k < steps
                invariant 1 <= k <= steps
                invariant 0 in closure(edges, |g|, k)
                decreases steps - k
            {
                closure_monotone_one(edges, |g|, k);
                k := k + 1;
            }
        }
    }

    assert p[0] in reached;
    assert p[|p| - 1] !in reached;
    assert |p| >= 2;

    crossing_index(p, reached);

    var j: int :|
        0 < j < |p| &&
        p[j - 1] in reached &&
        p[j] !in reached;

    var x := p[j - 1];
    var y := p[j];

    assert edge_in_set(edges, x, y);
    valid_edge_endpoints(g, edges, x, y);
    concrete_edge_equivalence(edges, x, y);

    assert y in closure_step(edges, reached, |g|);
    assert reached <= closure_step(edges, reached, |g|) by {
        closure_bounded(edges, |g|, steps);
    }
    assert reached < closure_step(edges, reached, |g|);
}

lemma closure_large_or_full(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    steps: nat)
    requires |g| > 0
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    requires steps <= |g|
    ensures
        (forall v: int ::
            0 <= v < |g| ==>
            v in closure(edges, |g|, steps))
        ||
        |closure(edges, |g|, steps)| >= steps + 1
    decreases steps
{
    if steps == 0 {
        assert |closure(edges, |g|, 0)| == 1;
    } else {
        closure_large_or_full(g, edges, steps - 1);

        if forall v: int ::
            0 <= v < |g| ==>
            v in closure(edges, |g|, steps - 1)
        {
            closure_monotone_one(edges, |g|, steps - 1);
        } else {
            closure_growth(g, edges, steps - 1);
        }
    }
}

lemma spanning_implies_concretely_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    ensures concretely_spanning(|g|, edges)
{
    closure_large_or_full(g, edges, |g|);

    if !(forall v: int ::
        0 <= v < |g| ==>
        v in closure(edges, |g|, |g|))
    {
        closure_bounded(edges, |g|, |g|);
        vertex_range_facts(|g|);

        assert closure(edges, |g|, |g|)
            <= vertex_range(|g|) by {
            forall v: int |
                v in closure(edges, |g|, |g|)
                ensures v in vertex_range(|g|)
            {
            }
        }

        assert |closure(edges, |g|, |g|)| <= |g|;
        assert |closure(edges, |g|, |g|)| >= |g| + 1;
        assert false;
    }
}

lemma concrete_weight_equivalence(edges: seq<Edge>)
    ensures concrete_weight(edges) == total_weight(edges)
    decreases |edges|
{
    if |edges| != 0 {
        concrete_weight_equivalence(edges[1..]);
    }
}

function row_edges(
    g: seq<seq<(int, int)>>,
    u: nat): seq<Edge>
    requires u < |g|
{
    seq(|g[u]|, i => (u, g[u][i].0, g[u][i].1))
}

function graph_edges_from(
    g: seq<seq<(int, int)>>,
    start: nat): seq<Edge>
    requires start <= |g|
    decreases |g| - start
{
    if start == |g| then []
    else row_edges(g, start) + graph_edges_from(g, start + 1)
}

lemma row_edge_member(
    g: seq<seq<(int, int)>>,
    u: nat,
    i: nat)
    requires u < |g|
    requires i < |g[u]|
    ensures (u, g[u][i].0, g[u][i].1) in row_edges(g, u)
{
    assert row_edges(g, u)[i]
        == (u, g[u][i].0, g[u][i].1);
}

lemma edge_member_from(
    g: seq<seq<(int, int)>>,
    start: nat,
    u: nat,
    i: nat)
    requires start <= u < |g|
    requires i < |g[u]|
    ensures (u, g[u][i].0, g[u][i].1)
        in graph_edges_from(g, start)
    decreases u - start
{
    if start == u {
        row_edge_member(g, u, i);
    } else {
        edge_member_from(g, start + 1, u, i);
    }
}

lemma valid_edge_in_graph_edges(
    g: seq<seq<(int, int)>>,
    e: Edge)
    requires has_edge(g, e.0, e.1, e.2)
    ensures e in graph_edges_from(g, 0)
{
    var i: int :|
        0 <= e.0 < |g| &&
        0 <= i < |g[e.0]| &&
        g[e.0][i].0 == e.1 &&
        g[e.0][i].1 == e.2;

    edge_member_from(g, 0, e.0, i);
}

lemma graph_edges_member_valid_from(
    g: seq<seq<(int, int)>>,
    start: nat,
