  ensures is_valid_is(s, indices[..len])
{
  var p := indices[..len];
  forall a | 0 <= a < |p|
    ensures 0 <= p[a] < |s|
  {
    assert p[a] == indices[a];
    InBounds(s, indices, a);
  }
  forall a, c | 0 <= a < c < |p|
    ensures p[a] < p[c]
  {
    assert p[a] == indices[a];
    assert p[c] == indices[c];
    assert a < c < |indices|;
    OrderedIdx(s, indices, a, c);
  }
  forall a, c | 0 <= a < c < |p|
    ensures s[p[a]] < s[p[c]]
  {
    assert p[a] == indices[a];
    assert p[c] == indices[c];
    OrderedIdx(s, indices, a, c);
    OrderedVal(s, indices, a, c);
    assert s[indices[a]] < s[indices[c]];
  }
  assert p == indices[..len];
  assert forall k :: 0 <= k < |p| ==> 0 <= p[k] < |s|;
  assert forall k, m :: 0 <= k < m < |p| ==> p[k] < p[m];
  assert forall k, m :: 0 <= k < m < |p| ==> s[p[k]] < s[p[m]];
  assert is_valid_is(s, p);
}

lemma ExtendValid(s: seq<int>, rest: seq<int>, prev: int, nxt: int)
  requires is_valid_is(s, rest)
  requires |rest| > 0
  requires rest[|rest| - 1] == prev
  requires 0 <= prev < nxt < |s|
  requires s[prev] < s[nxt]
  ensures is_valid_is(s, rest + [nxt])
{
  var b := rest + [nxt];
  forall a | 0 <= a < |b|
    ensures 0 <= b[a] < |s|
  {
    if a < |rest| {
      assert b[a] == rest[a];
      InBounds(s, rest, a);
    } else {
      assert a == |rest|;
      assert b[a] == nxt;
    }
  }
  forall a, c | 0 <= a < c < |b|
    ensures b[a] < b[c]
  {
    if c < |rest| {
      assert b[a] == rest[a];
      assert b[c] == rest[c];
      OrderedIdx(s, rest, a, c);
    } else {
      assert c == |rest|;
      assert b[c] == nxt;
      assert b[a] == rest[a];
      if a < |rest| - 1 {
        OrderedIdx(s, rest, a, |rest| - 1);
        assert rest[|rest| - 1] == prev;
        assert rest[a] < prev;
        assert prev < nxt;
        assert rest[a] < nxt;
      } else {
        assert a == |rest| - 1;
        assert rest[a] == prev;
        assert prev < nxt;
      }
    }
  }
  forall a, c | 0 <= a < c < |b|
    ensures s[b[a]] < s[b[c]]
  {
    if c < |rest| {
      assert b[a] == rest[a];
      assert b[c] == rest[c];
      OrderedIdx(s, rest, a, c);
      OrderedVal(s, rest, a, c);
    } else {
      assert c == |rest|;
      assert b[c] == nxt;
      assert b[a] == rest[a];
      if a < |rest| - 1 {
        OrderedIdx(s, rest, a, |rest| - 1);
        OrderedVal(s, rest, a, |rest| - 1);
        assert rest[|rest| - 1] == prev;
        assert s[rest[a]] < s[prev];
        assert s[prev] < s[nxt];
        assert s[rest[a]] < s[nxt];
      } else {
        assert a == |rest| - 1;
        assert rest[a] == prev;
        assert s[prev] < s[nxt];
      }
    }
  }
  assert forall k :: 0 <= k < |b| ==> 0 <= b[k] < |s|;
  assert forall k, m :: 0 <= k < m < |b| ==> b[k] < b[m];
  assert forall k, m :: 0 <= k < m < |b| ==> s[b[k]] < s[b[m]];
  assert is_valid_is(s, b);
}

predicate PrefixOK(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>, n: int)
  requires |dp| == |paths|
  requires 0 <= n <= |dp|
  requires n <= |s|
{
  (forall k {:trigger dp[k]} :: 0 <= k < n ==>
      dp[k] >= 1 &&
      dp[k] <= k + 1 &&
      is_valid_is(s, paths[k]) &&
      |paths[k]| == dp[k] &&
      LastOrNeg(paths[k]) == k)
  &&
  (forall a, b {:trigger dp[a], dp[b]} :: 0 <= a < b < n && s[a] < s[b] ==>
      dp[a] + 1 <= dp[b])
}

