lemma MaxStep(dp: seq<int>, t: int, prev: int, newResult: int)
  requires 0 <= t < |dp|
  requires forall k :: 0 <= k < t ==> dp[k] <= prev
  requires prev <= newResult
  requires dp[t] <= newResult
  ensures forall k :: 0 <= k < t + 1 ==> dp[k] <= newResult
{
  forall k | 0 <= k < t + 1
    ensures dp[k] <= newResult
  {
