  ghost var paths: seq<seq<int>> := [];
  var i: int := 0;
  PrefixOKEmpty(s, dp, paths);

  while i < |s|
    invariant 0 <= i <= |s|
    invariant |dp| == i && |paths| == i
    invariant PrefixOK(s, dp, paths, i)
    decreases |s| - i
  {
    var best := 1;
    var bestPred := -1;
    var j := 0;
    InitChoice(s, dp, paths, i);

    while j < i
      invariant 0 <= i < |s|
      invariant |dp| == i && |paths| == i
      invariant 0 <= j <= i
      invariant PrefixOK(s, dp, paths, i)
      invariant GoodChoice(s, dp, paths, i, j, best, bestPred)
      invariant forall m :: 0 <= m < j && s[m] < s[i] ==> dp[m] + 1 <= best
      decreases i - j
    {
      var nextJ := j + 1;
      assert j < i;
      assert nextJ == j + 1;
      assert nextJ <= i;

      if s[j] < s[i] && dp[j] + 1 > best {
        ghost var oldBest := best;
        assert oldBest == best;
        assert forall m :: 0 <= m < j && s[m] < s[i] ==> dp[m] + 1 <= oldBest;
        PrefixAt(s, dp, paths, i, j);
        assert dp[j] >= 1;
        assert dp[j] <= j + 1;
        assert j + 1 <= i;
        assert dp[j] <= i;
        assert dp[j] + 1 <= i + 1;
        assert oldBest < dp[j] + 1;
        assert is_valid_is(s, paths[j]);
        assert |paths[j]| == dp[j];
        assert LastOrNeg(paths[j]) == j;
        best := dp[j] + 1;
        bestPred := j;
        assert best == dp[j] + 1;
        assert best == dp[bestPred] + 1;
        assert oldBest < best;
        assert best >= 1;
        assert best <= i + 1;
        assert 0 <= bestPred < nextJ;
        assert dp[bestPred] >= 1;
        assert s[bestPred] < s[i];
        assert is_valid_is(s, paths[bestPred]);
        assert |paths[bestPred]| == dp[bestPred];
        assert LastOrNeg(paths[bestPred]) == bestPred;
        StepImproves(s, dp, i, j, oldBest, best);
        RenameCov(s, dp, i, j + 1, nextJ, best);
        ChoiceFromWitness(s, dp, paths, i, nextJ, best, bestPred);
      } else {
        if s[j] < s[i] {
          assert dp[j] + 1 <= best;
        }
        assert s[j] < s[i] ==> dp[j] + 1 <= best;
        StepCovers(s, dp, i, j, best);
        RenameCov(s, dp, i, j + 1, nextJ, best);
        ChoiceAdvanceJ(s, dp, paths, i, j, nextJ, best, bestPred);
      }

      assert GoodChoice(s, dp, paths, i, nextJ, best, bestPred);
      assert forall m :: 0 <= m < nextJ && s[m] < s[i] ==> dp[m] + 1 <= best;
      j := nextJ;
      GoodChoiceEq(s, dp, paths, i, nextJ, j, best, bestPred);
      RenameCov(s, dp, i, nextJ, j, best);
    }

    assert j <= i;
    assert !(j < i);
    assert j == i;
    GoodChoiceEq(s, dp, paths, i, j, i, best, bestPred);
    RenameCov(s, dp, i, j, i, best);

    ghost var i0 := i;
    ghost var newPath: seq<int> := ExtendOK(s, dp, paths, i, best, bestPred);
    var dpNext := dp + [best];
    ghost var pathsNext := paths + [newPath];
    assert i == i0;
    assert i < |s|;
    assert i + 1 <= |s|;
    assert i + 1 == i0 + 1;
    assert dpNext == dp + [best];
    assert pathsNext == paths + [newPath];
    PrefixOKEq(s, dp + [best], paths + [newPath], dpNext, pathsNext, i + 1, i0 + 1);
    dp := dpNext;
    paths := pathsNext;
    i := i0 + 1;
    assert dp == dpNext;
    assert paths == pathsNext;
    assert i == i0 + 1;
    PrefixOKEq(s, dpNext, pathsNext, dp, paths, i0 + 1, i);
  }

  assert i == |s|;
  assert |dp| == i && |paths| == i;
  PrefixOKEq(s, dp, paths, dp, paths, i, |s|);
  assert |dp| == |s| && |paths| == |s|;

  PrefixAt(s, dp, paths, |s|, 0);
  result := dp[0];
  var wit := 0;
  var t := 1;
  assert result >= 1;
  assert result == dp[wit];
  assert 0 <= wit < t;
  InitMax(dp, result);
  RenameLe(dp, 1, t, result);

  while t < |dp|
    invariant 1 <= t <= |dp|
    invariant 0 <= wit < t
    invariant result == dp[wit]
    invariant result >= 1
    invariant forall k :: 0 <= k < t ==> dp[k] <= result
    decreases |dp| - t
  {
    ghost var t0 := t;
    ghost var prev := result;
    assert prev == result;
    assert forall k :: 0 <= k < t0 ==> dp[k] <= prev;
    if dp[t] > prev {
      result := dp[t];
      wit := t;
      assert result > prev;
      assert result >= prev;
      assert dp[t0] == result;
      assert dp[t0] <= result;
      assert wit == t0;
      assert 0 <= wit < t0 + 1;
      assert result == dp[wit];
      assert result >= 1;
    } else {
      assert dp[t] <= prev;
      assert result == prev;
      assert result >= prev;
      assert dp[t0] <= result;
      assert 0 <= wit < t0;
      assert wit < t0 + 1;
      assert result == dp[wit];
      assert result >= 1;
    }
    MaxStep(dp, t0, prev, result);
    t := t0 + 1;
    RenameLe(dp, t0 + 1, t, result);
    assert 0 <= wit < t;
    assert result == dp[wit];
  }

  assert t == |dp|;
  assert |dp| == |s|;
  assert t == |s|;
  assert 0 <= wit < t;
  assert wit < |s|;
  assert result == dp[wit];
  forall k | 0 <= k < |s|
    ensures dp[k] <= result
  {
    assert 0 <= k < t;
    InstLe(dp, t, result, k);
  }
  ProveSpec(s, dp, paths, result, wit);
}
