    assert vs <= vertex_range(n) by {
        forall x: int | x in vs
            ensures x in vertex_range(n)
        {
        }
    }

    if !(exists x: int :: 0 <= x < n && x !in vs) {
        assert vertex_range(n) <= vs by {
            forall x: int | x in vertex_range(n)
                ensures x in vs
            {
            }
        }

        assert vs == vertex_range(n);
        assert |vs| == n;
        assert false;
    }
}

lemma crossing_index(p: seq<int>, vs: set<int>)
    requires |p| >= 2
    requires p[0] in vs
    requires p[|p| - 1] !in vs
    ensures exists j: int ::
        0 < j < |p| &&
        p[j - 1] in vs &&
        p[j] !in vs
    decreases |p|
{
    if p[1] !in vs {
        assert 0 < 1 < |p|;
    } else {
        if |p| == 2 {
            assert p[1] == p[|p| - 1];
            assert false;
        }

        crossing_index(p[1..], vs);

        var k: int :|
            0 < k < |p[1..]| &&
            p[1..][k - 1] in vs &&
            p[1..][k] !in vs;

        assert 0 < k + 1 < |p|;
        assert p[k] in vs;
        assert p[k + 1] !in vs;
    }
}

lemma edge_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    u: int,
    v: int)
    requires edge_in_set(oldEdges, u, v)
    ensures edge_in_set(oldEdges + [e], u, v)
{
    var i: int :|
        0 <= i < |oldEdges| &&
        ((oldEdges[i].0 == u && oldEdges[i].1 == v) ||
         (oldEdges[i].0 == v && oldEdges[i].1 == u));

    assert (oldEdges + [e])[i] == oldEdges[i];
}

lemma path_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    p: seq<int>)
    requires path_follows_edges(oldEdges, p)
    ensures path_follows_edges(oldEdges + [e], p)
{
    forall k: int | 0 <= k < |p| - 1
        ensures edge_in_set(oldEdges + [e], p[k], p[k + 1])
    {
        edge_in_extended(oldEdges, e, p[k], p[k + 1]);
    }
}

lemma connected_in_extended(
    oldEdges: seq<Edge>,
    e: Edge,
    u: int,
    v: int)
    requires edges_connected(oldEdges, u, v)
    ensures edges_connected(oldEdges + [e], u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(oldEdges, p);

    path_in_extended(oldEdges, e, p);
}

lemma path_append_vertex(
    edges: seq<Edge>,
    p: seq<int>,
    v: int)
    requires |p| > 0
    requires path_follows_edges(edges, p)
    requires edge_in_set(edges, p[|p| - 1], v)
    ensures path_follows_edges(edges, p + [v])
{
    forall k: int | 0 <= k < |p + [v]| - 1
        ensures edge_in_set(edges, (p + [v])[k], (p + [v])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + [v])[k] == p[k];
            assert (p + [v])[k + 1] == p[k + 1];
        } else {
            assert k == |p| - 1;
            assert (p + [v])[k] == p[|p| - 1];
            assert (p + [v])[k + 1] == v;
        }
    }
}

lemma path_prepend_vertex(
    edges: seq<Edge>,
    u: int,
    p: seq<int>)
    requires |p| > 0
    requires path_follows_edges(edges, p)
    requires edge_in_set(edges, u, p[0])
    ensures path_follows_edges(edges, [u] + p)
{
    forall k: int | 0 <= k < |[u] + p| - 1
        ensures edge_in_set(edges, ([u] + p)[k], ([u] + p)[k + 1])
    {
        if k == 0 {
            assert ([u] + p)[0] == u;
            assert ([u] + p)[1] == p[0];
        } else {
            assert ([u] + p)[k] == p[k - 1];
            assert ([u] + p)[k + 1] == p[k];
            assert 0 <= k - 1 < |p| - 1;
        }
    }
}

lemma connected_append_vertex(
