lemma path_join(
    edges: seq<Edge>,
    p: seq<int>,
    q: seq<int>)
    requires |p| > 0
    requires |q| > 0
    requires p[|p| - 1] == q[0]
    requires path_follows_edges(edges, p)
    requires path_follows_edges(edges, q)
    ensures path_follows_edges(edges, p + q[1..])
{
    if |q| == 1 {
        assert q[1..] == [];
    } else {
        forall k: int | 0 <= k < |p + q[1..]| - 1
            ensures edge_in_set(
                edges,
                (p + q[1..])[k],
                (p + q[1..])[k + 1])
        {
            if k < |p| - 1 {
                assert (p + q[1..])[k] == p[k];
                assert (p + q[1..])[k + 1] == p[k + 1];
            } else if k == |p| - 1 {
                assert (p + q[1..])[k] == p[|p| - 1];
                assert (p + q[1..])[k + 1] == q[1];
                assert edge_in_set(edges, q[0], q[1]);
            } else {
                var j := k - |p| + 1;
                assert 1 <= j < |q| - 1;
                assert (p + q[1..])[k] == q[j];
                assert (p + q[1..])[k + 1] == q[j + 1];
            }
        }
    }
}

lemma connected_transitive(
    edges: seq<Edge>,
    u: int,
    x: int,
    v: int)
    requires edges_connected(edges, u, x)
    requires edges_connected(edges, x, v)
    ensures edges_connected(edges, u, v)
{
    var p: seq<int> :|
        |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == x &&
        path_follows_edges(edges, p);

    var q: seq<int> :|
        |q| > 0 &&
        q[0] == x &&
        q[|q| - 1] == v &&
        path_follows_edges(edges, q);

    path_join(edges, p, q);

    if |q| == 1 {
        assert q[0] == v;
        assert x == v;
    }
}

lemma add_valid_edge(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    e: Edge)
    requires are_valid_edges(g, edges)
    requires has_edge(g, e.0, e.1, e.2)
    ensures are_valid_edges(g, edges + [e])
{
    forall k: int | 0 <= k < |edges + [e]|
        ensures has_edge(
            g,
            (edges + [e])[k].0,
            (edges + [e])[k].1,
            (edges + [e])[k].2)
    {
        if k < |edges| {
            assert (edges + [e])[k] == edges[k];
        } else {
            assert k == |edges|;
            assert (edges + [e])[k] == e;
        }
    }
}

ghost predicate endpoints_bounded(g: seq<seq<(int, int)>>)
{
    forall u: int, i: int ::
        0 <= u < |g| && 0 <= i < |g[u]| ==>
