ghost method build_spanning_tree(
    graph: WeightedGraph,
    vs: set<int>,
    partial: seq<Edge>)
    returns (tree: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    requires 0 in vs
    requires forall x: int :: x in vs ==> 0 <= x < size(graph)
    requires are_valid_edges(view(graph), partial)
    requires |partial| == |vs| - 1
    requires forall x: int :: x in vs ==>
        edges_connected(partial, 0, x) &&
        edges_connected(partial, x, 0)
    ensures are_valid_edges(view(graph), tree)
    ensures |tree| == size(graph) - 1
    ensures forall x: int :: 0 <= x < size(graph) ==>
        edges_connected(tree, 0, x) &&
        edges_connected(tree, x, 0)
    decreases size(graph) - |vs|
{
    var n := size(graph);

    bounded_set_cardinality(vs, n);
    assert |vs| <= n;

    if |vs| == n {
        tree := partial;

        vertex_range_facts(n);

        assert vs <= vertex_range(n) by {
            forall x: int | x in vs
                ensures x in vertex_range(n)
            {
            }
        }

        assert vertex_range(n) <= vs by {
            forall x: int | x in vertex_range(n)
                ensures x in vs
            {
                if x !in vs {
                    assert vs + {x} <= vertex_range(n) by {
                        forall z: int | z in vs + {x}
                            ensures z in vertex_range(n)
                        {
                            if z != x {
                                assert z in vs;
                            }
                        }
                    }

                    assert |vs + {x}| <= |vertex_range(n)|;
                    assert |vs + {x}| == |vs| + 1;
                    assert |vertex_range(n)| == n;
                    assert false;
                }
            }
        }

        assert vs == vertex_range(n);
    } else {
        assert |vs| < n;
        missing_vertex(vs, n);

        var target: int :| 0 <= target < n && target !in vs;

        assert nodes_have_path(view(graph), 0, target);

        var p: seq<int> :|
            |p| > 0 &&
            p[0] == 0 &&
            p[|p| - 1] == target &&
            path_follows_graph(view(graph), p);

        assert p[0] in vs;
        assert p[|p| - 1] !in vs;
        assert |p| >= 2;

        crossing_index(p, vs);

        var j: int :|
            0 < j < |p| &&
            p[j - 1] in vs &&
            p[j] !in vs;

        var x := p[j - 1];
        var y := p[j];

        assert 0 <= j - 1 < |p| - 1;
        assert graph_has_any_edge(view(graph), x, y);

        var i: int :|
            0 <= x < |view(graph)| &&
            0 <= i < |view(graph)[x]| &&
            view(graph)[x][i].0 == y;

        var w := view(graph)[x][i].1;
        var e: Edge := (x, y, w);

        var nextEdges := partial + [e];
        var nextVs := vs + {y};

        assert has_edge(view(graph), x, y, w);
        add_valid_edge(view(graph), partial, e);

        assert edge_in_set(nextEdges, x, y) by {
            assert nextEdges[|partial|] == e;
        }
        assert edge_in_set(nextEdges, y, x);

        connected_in_extended(partial, e, 0, x);
        connected_in_extended(partial, e, x, 0);
        connected_append_vertex(nextEdges, 0, x, y);
        connected_prepend_vertex(nextEdges, y, x, 0);

        forall z: int | z in nextVs
            ensures edges_connected(nextEdges, 0, z) &&
                    edges_connected(nextEdges, z, 0)
        {
            if z != y {
                assert z in vs;
                connected_in_extended(partial, e, 0, z);
                connected_in_extended(partial, e, z, 0);
            }
        }

        assert y !in vs;
        assert |nextVs| == |vs| + 1;
        assert |nextEdges| == |partial| + 1;
        assert |nextEdges| == |nextVs| - 1;

        forall z: int | z in nextVs
            ensures 0 <= z < n
        {
            if z != y {
                assert z in vs;
            } else {
                assert 0 <= x < |view(graph)|;
                assert 0 <= i < |view(graph)[x]|;
                assert 0 <= view(graph)[x][i].0 < |view(graph)|;
                assert y == view(graph)[x][i].0;
            }
        }

        tree := build_spanning_tree(graph, nextVs, nextEdges);
    }
}

lemma rooted_tree_is_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires forall x: int :: 0 <= x < |g| ==>
        edges_connected(edges, 0, x) &&
        edges_connected(edges, x, 0)
    ensures is_spanning(g, edges)
{
    forall u: int, v: int |
        0 <= u < |g| && 0 <= v < |g|
        ensures edges_connected(edges, u, v)
    {
        connected_transitive(edges, u, 0, v);
    }
}

ghost method spanning_tree_witness(graph: WeightedGraph)
    returns (tree: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    ensures is_spanning_tree(view(graph), tree)
{
    var initial: seq<Edge> := [];
    var initialVertices: set<int> := {0};

    assert edges_connected(initial, 0, 0) by {
        var p := [0];
        assert path_follows_edges(initial, p);
    }

    tree :=
        build_spanning_tree(graph, initialVertices, initial);

    rooted_tree_is_spanning(view(graph), tree);
}

predicate concrete_edge_in_set(edges: seq<Edge>, u: int, v: int)
{
    exists i: int ::
        0 <= i < |edges| &&
        ((edges[i].0 == u && edges[i].1 == v) ||
         (edges[i].0 == v && edges[i].1 == u))
}

function closure_step(
    edges: seq<Edge>,
    reached: set<int>,
    n: nat): set<int>
{
    set v: int |
        0 <= v < n &&
        (v in reached ||
         exists u: int ::
            u in reached &&
            concrete_edge_in_set(edges, u, v))
}

function closure(
    edges: seq<Edge>,
    n: nat,
    steps: nat): set<int>
    decreases steps
{
    if steps == 0 then {0}
    else closure_step(edges, closure(edges, n, steps - 1), n)
}

predicate concretely_spanning(n: nat, edges: seq<Edge>)
{
    n > 0 &&
    forall v: int :: 0 <= v < n ==> v in closure(edges, n, n)
}

function concrete_weight(edges: seq<Edge>): int
    decreases |edges|
{
    if |edges| == 0 then 0
    else edges[0].2 + concrete_weight(edges[1..])
}

lemma concrete_edge_equivalence(
    edges: seq<Edge>,
    u: int,
    v: int)
    ensures concrete_edge_in_set(edges, u, v)
        <==> edge_in_set(edges, u, v)
{
}

lemma closure_bounded(
    edges: seq<Edge>,
    n: nat,
    steps: nat)
    requires n > 0
    ensures forall v: int ::
        v in closure(edges, n, steps) ==> 0 <= v < n
    decreases steps
{
    if steps == 0 {
    } else {
        closure_bounded(edges, n, steps - 1);
    }
}

lemma closure_monotone_one(
    edges: seq<Edge>,
    n: nat,
    steps: nat)
    requires n > 0
    ensures closure(edges, n, steps)
        <= closure(edges, n, steps + 1)
{
    closure_bounded(edges, n, steps);

    forall v: int | v in closure(edges, n, steps)
        ensures v in closure(edges, n, steps + 1)
    {
    }
}

lemma closure_member_connected(
    edges: seq<Edge>,
    n: nat,
    steps: nat,
    v: int)
    requires n > 0
    requires v in closure(edges, n, steps)
    ensures edges_connected(edges, 0, v)
    ensures edges_connected(edges, v, 0)
    decreases steps
{
    if steps == 0 {
        assert v == 0;

        assert edges_connected(edges, 0, 0) by {
            var p := [0];
            assert path_follows_edges(edges, p);
        }
    } else {
        var previous := closure(edges, n, steps - 1);

        if v in previous {
            closure_member_connected(edges, n, steps - 1, v);
        } else {
            var u: int :|
                u in previous &&
                concrete_edge_in_set(edges, u, v);

            closure_member_connected(edges, n, steps - 1, u);
            concrete_edge_equivalence(edges, u, v);

            connected_append_vertex(edges, 0, u, v);
            connected_prepend_vertex(edges, v, u, 0);
        }
    }
}

lemma concretely_spanning_implies_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires concretely_spanning(|g|, edges)
    ensures is_spanning(g, edges)
{
    forall v: int | 0 <= v < |g|
        ensures edges_connected(edges, 0, v) &&
                edges_connected(edges, v, 0)
    {
        closure_member_connected(edges, |g|, |g|, v);
    }

    rooted_tree_is_spanning(g, edges);
}

lemma valid_edge_endpoints(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    u: int,
    v: int)
    requires endpoints_bounded(g)
    requires are_valid_edges(g, edges)
    requires edge_in_set(edges, u, v)
    ensures 0 <= u < |g|
    ensures 0 <= v < |g|
{
    var i: int :|
        0 <= i < |edges| &&
        ((edges[i].0 == u && edges[i].1 == v) ||
         (edges[i].0 == v && edges[i].1 == u));

    assert has_edge(
        g, edges[i].0, edges[i].1, edges[i].2);

    var j: int :|
        0 <= edges[i].0 < |g| &&
        0 <= j < |g[edges[i].0]| &&
        g[edges[i].0][j].0 == edges[i].1 &&
        g[edges[i].0][j].1 == edges[i].2;

    assert 0 <= g[edges[i].0][j].0 < |g|;
    assert 0 <= edges[i].1 < |g|;

    if edges[i].0 == u && edges[i].1 == v {
        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
    } else {
        assert edges[i].0 == v && edges[i].1 == u;
        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
    }
}

lemma closure_growth(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    steps: nat)
    requires |g| > 0
    requires endpoints_bounded(g)
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    requires steps < |g|
    requires !(forall v: int ::
        0 <= v < |g| ==> v in closure(edges, |g|, steps))
    ensures |closure(edges, |g|, steps + 1)|
        >= |closure(edges, |g|, steps)| + 1
{
    var reached := closure(edges, |g|, steps);

    var target: int :|
        0 <= target < |g| &&
        target !in reached;

    assert edges_connected(edges, 0, target);

    var p: seq<int> :|
        |p| > 0 &&
        p[0] == 0 &&
        p[|p| - 1] == target &&
        path_follows_edges(edges, p);

    assert 0 in reached by {
        if steps == 0 {
        } else {
            closure_monotone_one(edges, |g|, 0);
            assert 0 in closure(edges, |g|, 1);

            var k: nat := 1;
            while k < steps
                invariant 1 <= k <= steps
                invariant 0 in closure(edges, |g|, k)
                decreases steps - k
            {
                closure_monotone_one(edges, |g|, k);
                k := k + 1;
            }
        }
    }

    assert p[0] in reached;
    assert p[|p| - 1] !in reached;
    assert |p| >= 2;

    crossing_index(p, reached);

    var j: int :|
        0 < j < |p| &&
        p[j - 1] in reached &&
        p[j] !in reached;

    var x := p[j - 1];
    var y := p[j];

    assert 0 <= j - 1 < |p| - 1;
    assert edge_in_set(edges, x, y);
    valid_edge_endpoints(g, edges, x, y);
    concrete_edge_equivalence(edges, x, y);

    var next := closure_step(edges, reached, |g|);

    assert y in next;
    assert reached <= next by {
        closure_bounded(edges, |g|, steps);
        forall z: int | z in reached
            ensures z in next
        {
        }
    }

    assert y !in reached;
    assert reached != next;
    assert reached < next;
    assert |reached| < |next|;
    assert |next| >= |reached| + 1;
    assert closure(edges, |g|, steps + 1) == next;
}

lemma closure_large_or_full(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>,
    steps: nat)
    requires |g| > 0
    requires endpoints_bounded(g)
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    requires steps <= |g|
    ensures
        (forall v: int ::
            0 <= v < |g| ==>
            v in closure(edges, |g|, steps))
        ||
        |closure(edges, |g|, steps)| >= steps + 1
    decreases steps
{
    if steps == 0 {
        assert |closure(edges, |g|, 0)| == 1;
    } else {
        closure_large_or_full(g, edges, steps - 1);

        if forall v: int
            {:trigger v in closure(edges, |g|, steps - 1)} ::
            0 <= v < |g| ==>
            v in closure(edges, |g|, steps - 1)
        {
            closure_monotone_one(edges, |g|, steps - 1);

            assert forall v: int ::
                0 <= v < |g| ==>
                v in closure(edges, |g|, steps) by {
                forall v: int | 0 <= v < |g|
                    ensures v in closure(edges, |g|, steps)
                {
                    assert v in closure(edges, |g|, steps - 1);
                }
            }
        } else {
            closure_growth(g, edges, steps - 1);
        }
    }
}

lemma spanning_implies_concretely_spanning(
    g: seq<seq<(int, int)>>,
    edges: seq<Edge>)
    requires |g| > 0
    requires endpoints_bounded(g)
    requires are_valid_edges(g, edges)
    requires is_spanning(g, edges)
    ensures concretely_spanning(|g|, edges)
{
    closure_large_or_full(g, edges, |g|);

    if !(forall v: int ::
        0 <= v < |g| ==>
        v in closure(edges, |g|, |g|))
    {
        closure_bounded(edges, |g|, |g|);
        vertex_range_facts(|g|);

        assert closure(edges, |g|, |g|)
            <= vertex_range(|g|) by {
            forall v: int |
                v in closure(edges, |g|, |g|)
                ensures v in vertex_range(|g|)
            {
            }
        }

        assert |closure(edges, |g|, |g|)|
            <= |vertex_range(|g|)|;
        assert |vertex_range(|g|)| == |g|;
        assert |closure(edges, |g|, |g|)| <= |g|;
        assert |closure(edges, |g|, |g|)| >= |g| + 1;
        assert false;
    }
}

lemma concrete_weight_equivalence(edges: seq<Edge>)
    ensures concrete_weight(edges) == total_weight(edges)
    decreases |edges|
{
    if |edges| != 0 {
