method choose_best(
    candidates: seq<seq<Edge>>,
    n: nat)
    returns (best: seq<Edge>)
    requires exists c: seq<Edge> ::
        c in candidates && concretely_spanning(n, c)
    ensures best in candidates
    ensures concretely_spanning(n, best)
    ensures forall c: seq<Edge> ::
        c in candidates && concretely_spanning(n, c) ==>
        concrete_weight(best) <= concrete_weight(c)
{
    var i := 0;
    var found := false;
    best := [];

    while i < |candidates|
        invariant 0 <= i <= |candidates|
        invariant found ==>
            best in candidates[..i] &&
            concretely_spanning(n, best)
        invariant forall j: int ::
            0 <= j < i &&
            concretely_spanning(n, candidates[j]) ==>
            found &&
            concrete_weight(best)
                <= concrete_weight(candidates[j])
        decreases |candidates| - i
    {
        var current := candidates[i];

        if concretely_spanning(n, current) {
            if !found ||
                concrete_weight(current) < concrete_weight(best)
            {
                best := current;
                found := true;
            }
        }

        i := i + 1;
    }

    if !found {
        var c: seq<Edge> :|
            c in candidates &&
            concretely_spanning(n, c);

        var j: int :|
            0 <= j < |candidates| &&
            candidates[j] == c;

        assert false;
    }

    forall c: seq<Edge> |
        c in candidates &&
        concretely_spanning(n, c)
        ensures concrete_weight(best) <= concrete_weight(c)
    {
        var j: int :|
            0 <= j < |candidates| &&
            candidates[j] == c;
    }
}

method prim_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
    var g := graph.adj;
    var n := |g|;

    well_formed_endpoints(graph);
    assert endpoints_bounded(g);

    ghost var treeWitness :=
        spanning_tree_witness(graph);

    var items := graph_edges_from(g, 0);
    var candidates := powers(items, n - 1);

    assert forall i: int ::
        0 <= i < |treeWitness| ==> treeWitness[i] in items by {
        forall i: int | 0 <= i < |treeWitness|
            ensures treeWitness[i] in items
        {
