    assert treeWitness in candidates;

    spanning_implies_concretely_spanning(g, treeWitness);

    edges := choose_best(candidates, n);

    powers_sound(items, n - 1, edges);

    assert are_valid_edges(g, edges) by {
        forall i: int | 0 <= i < |edges|
            ensures has_edge(
                g,
                edges[i].0,
                edges[i].1,
                edges[i].2)
        {
            assert edges[i] in items;
            graph_edges_member_valid_from(g, 0, edges[i]);
        }
    }

    concretely_spanning_implies_spanning(g, edges);

    assert is_spanning_tree(g, edges);

    assert forall other: seq<Edge>
        {:trigger is_spanning_tree(g, other)} ::
        is_spanning_tree(g, other) ==>
        total_weight(edges) <= total_weight(other) by {
        forall other: seq<Edge>
            {:trigger is_spanning_tree(g, other)} |
            is_spanning_tree(g, other)
            ensures total_weight(edges) <= total_weight(other)
        {
            assert forall i: int ::
                0 <= i < |other| ==> other[i] in items by {
                forall i: int | 0 <= i < |other|
                    ensures other[i] in items
                {
                    assert has_edge(
                        g,
                        other[i].0,
                        other[i].1,
                        other[i].2);
                    valid_edge_in_graph_edges(g, other[i]);
