method prim_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
    var g := graph.adj;
    var n := |g|;

    well_formed_endpoints(graph);
    assert endpoints_bounded(g);

    ghost var treeWitness :=
        spanning_tree_witness(graph);

    var items := graph_edges_from(g, 0);
    var candidates := powers(items, n - 1);

    assert forall i: int ::
        0 <= i < |treeWitness| ==> treeWitness[i] in items by {
        forall i: int | 0 <= i < |treeWitness|
            ensures treeWitness[i] in items
        {
            assert has_edge(
                g,
                treeWitness[i].0,
                treeWitness[i].1,
                treeWitness[i].2);
            valid_edge_in_graph_edges(g, treeWitness[i]);
        }
    }

    powers_complete(items, treeWitness);
    assert |treeWitness| == n - 1;
    assert treeWitness in candidates;

    spanning_implies_concretely_spanning(g, treeWitness);

    edges := choose_best(candidates, n);

    powers_sound(items, n - 1, edges);

    assert are_valid_edges(g, edges) by {
        forall i: int | 0 <= i < |edges|
            ensures has_edge(
                g,
                edges[i].0,
                edges[i].1,
                edges[i].2)
        {
            assert edges[i] in items;
            graph_edges_member_valid_from(g, 0, edges[i]);
        }
    }

    concretely_spanning_implies_spanning(g, edges);

    assert is_spanning_tree(g, edges);

    assert forall other: seq<Edge>
        {:trigger is_spanning_tree(g, other)} ::
        is_spanning_tree(g, other) ==>
        total_weight(edges) <= total_weight(other) by {
        forall other: seq<Edge>
            {:trigger is_spanning_tree(g, other)} |
            is_spanning_tree(g, other)
            ensures total_weight(edges) <= total_weight(other)
        {
            assert forall i: int ::
                0 <= i < |other| ==> other[i] in items by {
                forall i: int | 0 <= i < |other|
                    ensures other[i] in items
                {
                    assert has_edge(
                        g,
                        other[i].0,
                        other[i].1,
                        other[i].2);
                    valid_edge_in_graph_edges(g, other[i]);
                }
            }

            powers_complete(items, other);
            assert |other| == n - 1;
            assert other in candidates;

            spanning_implies_concretely_spanning(g, other);

            assert concrete_weight(edges)
                <= concrete_weight(other);

            concrete_weight_equivalence(edges);
            concrete_weight_equivalence(other);
        }
    }
}
