    var f' := f[(u, v) := x];
    if x == y {
      assert Agree(g, f', other, u, i + 1) by {
        forall a: int, j: int | 0 <= a < |g| && 0 <= j < |g[a]| && before(a, j, u, i + 1)
          ensures get_flow(f', a, g[a][j].0) == get_flow(other, a, g[a][j].0)
        {
          if a == u && j == i {
            assert get_flow(f', u, v) == x;
          } else {
            var w := g[a][j].0;
            if a == u {
              assert j != i;
              assert g[u][j].0 != g[u][i].0;
            }
            assert (a, w) != (u, v);
            assert get_flow(f', a, w) == get_flow(f, a, w);
            assert before(a, j, u, i);
          }
        }
      }
      assert KeysOK(g, f', u, i + 1) by {
        forall a: int, b: int | (a, b) in f'
          ensures 0 <= a < |g| && exists j: int :: 0 <= j < |g[a]| && before(a, j, u, i + 1) && g[a][j].0 == b
        {
          if (a, b) == (u, v) {
            assert before(u, i, u, i + 1);
            assert g[a][i].0 == b;
          } else {
            assert (a, b) in f;
            assert 0 <= a < |g|;
            var j :| 0 <= j < |g[a]| && before(a, j, u, i) && g[a][j].0 == b;
            assert before(a, j, u, i + 1);
          }
        }
      }
      Complete(g, s, t, f', u, i + 1, 0, other);
    } else {
      Complete(g, s, t, f, u, i, x + 1, other);
    }
    CombineProp(enumerate(g, s, t, f', u, i + 1, 0), enumerate(g, s, t, f, u, i, x + 1));
  }
}

method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
  var g := graph.adj;
  assert view(graph) == g;
  assert simple(g);
  var e: FlowMap := map[];
  var r := enumerate(g, s, t, e, 0, 0, 0);
  EmptyValid(g, e, s, t);
  assert Agree(g, e, e, 0, 0);
  assert KeysOK(g, e, 0, 0);
  Complete(g, s, t, e, 0, 0, 0, e);
  Sound(g, s, t, e, 0, 0, 0);
  forall other: FlowMap | is_valid_flow(g, other, s, t)
    ensures r.val >= flow_val(g, other, s)
  {
    assert Agree(g, e, other, 0, 0);
    assert KeysOK(g, e, 0, 0);
    Complete(g, s, t, e, 0, 0, 0, other);
  }
  ghost var f :| is_valid_flow(g, f, s, t) && flow_val(g, f, s) == r.val;
  assert is_max_flow(g, f, s, t);
  max_val := r.val;
}

response:
The approach is to enumerate every integer flow that respects the capacities, check conservation with compiled copies of the spec functions, and keep the best value. This is exhaustive, so it is exponential at runtime. Verification only needs it to terminate, and it keeps the proof simple:

1. **Compiled mirrors.** `cget`, `cout`, `cin`, `cconserved` and `cval` copy the ghost definitions. They are proved equal to the ghost versions by induction (`OutEq`, `InEq`, `CEquiv`).
2. **`enumerate`.** It walks the edges in `(u, i)` order and tries each value `0..capOf(c)` per edge. Its result is a `Res(found, val)` pair, and `combine` merges two results by taking the larger value.
3. **Soundness.** Every partial map stays non-negative and within capacity. So whatever `enumerate` returns comes from a real valid flow.
4. **Completeness.** For any valid `other`, the search follows `other`'s value on each edge. A flow on a non-edge must be 0, so at the end the map agrees with `other` pointwise. Then the value and conservation transfer (`SameFlow`). The simple-graph constraint keeps the keys distinct and the capacity on each edge unique.
5. **Existence.** The empty map is a valid flow, so the search always finds something.

