ghost predicate simple(g: seq<seq<(int, int)>>) {
  forall u: int, i: int, j: int ::
    0 <= u < |g| && 0 <= i < |g[u]| && 0 <= j < |g[u]| && i != j
    ==> g[u][i].0 != g[u][j].0
}

function enumerate(g: seq<seq<(int, int)>>, s: int, t: int, f: FlowMap, u: int, i: int, x: int): Res
  requires 0 <= u <= |g|
  requires u < |g| ==> 0 <= i <= |g[u]|
  decreases |g| - u,
            (if u < |g| then |g[u]| - i else 0),
            (if u < |g| && i < |g[u]| && x <= capOf(g[u][i].1) then capOf(g[u][i].1) - x + 1 else 0)
{
  if u == |g| then
    (if cconserved(g, f, s, t) then Res(true, cval(g, f, s)) else Res(false, 0))
  else if i == |g[u]| then
    enumerate(g, s, t, f, u + 1, 0, 0)
  else if x > capOf(g[u][i].1) then
    Res(false, 0)
  else
    combine(enumerate(g, s, t, f[(u, g[u][i].0) := x], u, i + 1, 0),
            enumerate(g, s, t, f, u, i, x + 1))
}

lemma Sound(g: seq<seq<(int, int)>>, s: int, t: int, f: FlowMap, u: int, i: int, x: int)
  requires 0 <= u <= |g|
  requires u < |g| ==> 0 <= i <= |g[u]|
  requires 0 <= x
  requires respects_capacity(g, f)
  requires forall a: int, b: int :: (a, b) in f ==> f[(a, b)] >= 0
  ensures enumerate(g, s, t, f, u, i, x).found ==>
            exists h: FlowMap :: is_valid_flow(g, h, s, t) && flow_val(g, h, s) == enumerate(g, s, t, f, u, i, x).val
  decreases |g| - u,
            (if u < |g| then |g[u]| - i else 0),
            (if u < |g| && i < |g[u]| && x <= capOf(g[u][i].1) then capOf(g[u][i].1) - x + 1 else 0)
{
  if u == |g| {
    CEquiv(g, f, s, t);
    if cconserved(g, f, s, t) {
      assert is_valid_flow(g, f, s, t);
      assert is_valid_flow(g, f, s, t) && flow_val(g, f, s) == enumerate(g, s, t, f, u, i, x).val;
    }
  } else if i == |g[u]| {
    Sound(g, s, t, f, u + 1, 0, 0);
  } else if x > capOf(g[u][i].1) {
  } else {
    var v := g[u][i].0;
    var f' := f[(u, v) := x];
    assert has_capacity(g, u, v, g[u][i].1);
    forall a: int, b: int | (a, b) in f'
      ensures f'[(a, b)] >= 0
      ensures f'[(a, b)] > 0 ==> exists c: int :: has_capacity(g, a, b, c) && f'[(a, b)] <= c
    {
      if (a, b) == (u, v) {
        assert f'[(a, b)] == x;
        if x > 0 {
          assert x <= g[u][i].1;
          assert has_capacity(g, a, b, g[u][i].1) && f'[(a, b)] <= g[u][i].1;
        }
      } else {
        assert (a, b) in f;
        assert f'[(a, b)] == f[(a, b)];
        if f[(a, b)] > 0 {
          var c :| has_capacity(g, a, b, c) && f[(a, b)] <= c;
          assert has_capacity(g, a, b, c) && f'[(a, b)] <= c;
        }
      }
    }
    assert respects_capacity(g, f');
    Sound(g, s, t, f', u, i + 1, 0);
    Sound(g, s, t, f, u, i, x + 1);
    CombineProp(enumerate(g, s, t, f', u, i + 1, 0), enumerate(g, s, t, f, u, i, x + 1));
  }
}

ghost predicate before(a: int, j: int, u: int, i: int) {
  a < u || (a == u && j < i)
}

ghost predicate Agree(g: seq<seq<(int, int)>>, f: FlowMap, other: FlowMap, u: int, i: int) {
  forall a: int, j: int ::
    0 <= a < |g| && 0 <= j < |g[a]| && before(a, j, u, i)
    ==> get_flow(f, a, g[a][j].0) == get_flow(other, a, g[a][j].0)
}

ghost predicate KeysOK(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int) {
  forall a: int, b: int :: (a, b) in f ==>
    0 <= a < |g| && exists j: int :: 0 <= j < |g[a]| && before(a, j, u, i) && g[a][j].0 == b
}

lemma Complete(g: seq<seq<(int, int)>>, s: int, t: int, f: FlowMap, u: int, i: int, x: int, other: FlowMap)
  requires simple(g)
  requires 0 <= u <= |g|
  requires u < |g| ==> 0 <= i <= |g[u]|
  requires 0 <= x
  requires is_valid_flow(g, other, s, t)
  requires Agree(g, f, other, u, i)
  requires KeysOK(g, f, u, i)
  requires x > 0 && u < |g| && i < |g[u]| ==> x <= get_flow(other, u, g[u][i].0)
  ensures enumerate(g, s, t, f, u, i, x).found
  ensures enumerate(g, s, t, f, u, i, x).val >= flow_val(g, other, s)
  decreases |g| - u,
            (if u < |g| then |g[u]| - i else 0),
            (if u < |g| && i < |g[u]| && x <= capOf(g[u][i].1) then capOf(g[u][i].1) - x + 1 else 0)
{
  forall a: int, b: int ensures get_flow(other, a, b) >= 0 {}
  if u == |g| {
    forall a: int, b: int ensures get_flow(f, a, b) == get_flow(other, a, b) {
      if (a, b) in f {
        assert 0 <= a < |g|;
        var j :| 0 <= j < |g[a]| && before(a, j, u, i) && g[a][j].0 == b;
        assert get_flow(f, a, g[a][j].0) == get_flow(other, a, g[a][j].0);
      } else {
        if (a, b) in other && other[(a, b)] > 0 {
          var c :| has_capacity(g, a, b, c) && other[(a, b)] <= c;
          var j :| 0 <= a < |g| && 0 <= j < |g[a]| && g[a][j].0 == b && g[a][j].1 == c;
          assert before(a, j, u, i);
          assert get_flow(f, a, g[a][j].0) == get_flow(other, a, g[a][j].0);
          assert false;
        }
      }
    }
    SameFlow(g, f, other, s, t);
    CEquiv(g, f, s, t);
  } else if i == |g[u]| {
    assert Agree(g, f, other, u + 1, 0) by {
      forall a: int, j: int | 0 <= a < |g| && 0 <= j < |g[a]| && before(a, j, u + 1, 0)
        ensures get_flow(f, a, g[a][j].0) == get_flow(other, a, g[a][j].0)
      {
        assert before(a, j, u, i);
      }
    }
    assert KeysOK(g, f, u + 1, 0) by {
      forall a: int, b: int | (a, b) in f
        ensures 0 <= a < |g| && exists j: int :: 0 <= j < |g[a]| && before(a, j, u + 1, 0) && g[a][j].0 == b
      {
        assert 0 <= a < |g|;
        var j :| 0 <= j < |g[a]| && before(a, j, u, i) && g[a][j].0 == b;
        assert before(a, j, u + 1, 0);
      }
    }
    Complete(g, s, t, f, u + 1, 0, 0, other);
  } else {
    var v := g[u][i].0;
    var c := g[u][i].1;
    var y := get_flow(other, u, v);
    assert 0 <= y;
    assert x <= y;
    assert y <= capOf(c) by {
      if y > 0 {
        assert (u, v) in other;
        var c' :| has_capacity(g, u, v, c') && other[(u, v)] <= c';
        var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == c';
        if j != i {
          assert g[u][j].0 != g[u][i].0;
        }
        assert c' == c;
      }
    }
    var f' := f[(u, v) := x];
    if x == y {
      assert Agree(g, f', other, u, i + 1) by {
        forall a: int, j: int | 0 <= a < |g| && 0 <= j < |g[a]| && before(a, j, u, i + 1)
          ensures get_flow(f', a, g[a][j].0) == get_flow(other, a, g[a][j].0)
        {
          if a == u && j == i {
            assert get_flow(f', u, v) == x;
          } else {
            var w := g[a][j].0;
            if a == u {
              assert j != i;
              assert g[u][j].0 != g[u][i].0;
            }
            assert (a, w) != (u, v);
            assert get_flow(f', a, w) == get_flow(f, a, w);
            assert before(a, j, u, i);
          }
        }
      }
      assert KeysOK(g, f', u, i + 1) by {
        forall a: int, b: int | (a, b) in f'
          ensures 0 <= a < |g| && exists j: int :: 0 <= j < |g[a]| && before(a, j, u, i + 1) && g[a][j].0 == b
        {
          if (a, b) == (u, v) {
            assert before(u, i, u, i + 1);
            assert g[a][i].0 == b;
          } else {
            assert (a, b) in f;
            assert 0 <= a < |g|;
            var j :| 0 <= j < |g[a]| && before(a, j, u, i) && g[a][j].0 == b;
            assert before(a, j, u, i + 1);
          }
        }
      }
      Complete(g, s, t, f', u, i + 1, 0, other);
    } else {
      Complete(g, s, t, f, u, i, x + 1, other);
    }
    CombineProp(enumerate(g, s, t, f', u, i + 1, 0), enumerate(g, s, t, f, u, i, x + 1));
  }
}

method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
  var g := graph.adj;
  assert view(graph) == g;
  assert simple(g);
  var e: FlowMap := map[];
  var r := enumerate(g, s, t, e, 0, 0, 0);
  EmptyValid(g, e, s, t);
  assert Agree(g, e, e, 0, 0);
  assert KeysOK(g, e, 0, 0);
  Complete(g, s, t, e, 0, 0, 0, e);
  Sound(g, s, t, e, 0, 0, 0);
  forall other: FlowMap | is_valid_flow(g, other, s, t)
    ensures r.val >= flow_val(g, other, s)
  {
    assert Agree(g, e, other, 0, 0);
    assert KeysOK(g, e, 0, 0);
    Complete(g, s, t, e, 0, 0, 0, other);
  }
  ghost var f :| is_valid_flow(g, f, s, t) && flow_val(g, f, s) == r.val;
  assert is_max_flow(g, f, s, t);
  max_val := r.val;
}
