lemma ExtendOK(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, best: int, bestPred: int
  ) returns (newPath: seq<int>)
  requires |dp| == i && |paths| == i
  requires 0 <= i < |s|
  requires PrefixOK(s, dp, paths, i)
  requires GoodChoice(s, dp, paths, i, i, best, bestPred)
  requires forall m :: 0 <= m < i && s[m] < s[i] ==> dp[m] + 1 <= best
  ensures PrefixOK(s, dp + [best], paths + [newPath], i + 1)
{
  GoodChoiceFacts(s, dp, paths, i, i, best, bestPred);
  assert best >= 1;
  assert best <= i + 1;
  if bestPred == -1 {
    assert best == 1;
    newPath := [i];
    SingletonValid(s, i);
    assert newPath == [i];
    assert is_valid_is(s, newPath);
    assert |newPath| == best;
    assert newPath[0] == i;
    assert newPath[|newPath| - 1] == i;
    LastIs(newPath);
    assert LastOrNeg(newPath) == i;
  } else {
    assert 0 <= bestPred < i;
    assert dp[bestPred] >= 1;
    assert s[bestPred] < s[i];
    assert best == dp[bestPred] + 1;
    assert is_valid_is(s, paths[bestPred]);
    assert |paths[bestPred]| == dp[bestPred];
    assert LastOrNeg(paths[bestPred]) == bestPred;
    var rest := paths[bestPred];
    assert |rest| == dp[bestPred];
    assert |rest| > 0;
    LastIs(rest);
    assert rest[|rest| - 1] == bestPred;
    assert 0 <= bestPred < i < |s|;
    ExtendValid(s, rest, bestPred, i);
    newPath := rest + [i];
    assert newPath == rest + [i];
    assert is_valid_is(s, newPath);
    assert |newPath| == |rest| + 1;
    assert |newPath| == best;
    assert newPath[|newPath| - 1] == i;
    LastIs(newPath);
    assert LastOrNeg(newPath) == i;
  }
  assert is_valid_is(s, newPath);
  assert |newPath| == best;
  assert LastOrNeg(newPath) == i;

  var dp2 := dp + [best];
  var paths2 := paths + [newPath];

  forall idx | 0 <= idx < i
    ensures dp2[idx] == dp[idx] && paths2[idx] == paths[idx]
  {
  }
  assert dp2[i] == best;
  assert paths2[i] == newPath;

  forall idx | 0 <= idx < i + 1
    ensures dp2[idx] >= 1 && dp2[idx] <= idx + 1 && is_valid_is(s, paths2[idx]) && |paths2[idx]| == dp2[idx] && LastOrNeg(paths2[idx]) == idx
  {
    if idx < i {
      assert dp2[idx] == dp[idx];
      assert paths2[idx] == paths[idx];
      PrefixAt(s, dp, paths, i, idx);
      assert is_valid_is(s, paths2[idx]);
      assert |paths2[idx]| == dp2[idx];
      assert LastOrNeg(paths2[idx]) == idx;
      assert dp2[idx] >= 1;
      assert dp2[idx] <= idx + 1;
    } else {
      assert idx == i;
      assert dp2[idx] == best;
      assert paths2[idx] == newPath;
      assert |newPath| == best;
      assert LastOrNeg(newPath) == i;
      assert LastOrNeg(paths2[idx]) == idx;
      assert is_valid_is(s, paths2[idx]);
      assert dp2[idx] >= 1;
      assert best <= i + 1;
      assert dp2[idx] <= idx + 1;
    }
  }

  forall a, b | 0 <= a < b < i + 1 && s[a] < s[b]
    ensures dp2[a] + 1 <= dp2[b]
  {
    if b < i {
      assert dp2[a] == dp[a];
      assert dp2[b] == dp[b];
      PrefixDom(s, dp, paths, i, a, b);
    } else {
      assert b == i;
      assert dp2[a] == dp[a];
      assert dp2[b] == best;
      assert a < i;
      CovAt(s, dp, i, a, best);
      assert dp[a] + 1 <= best;
    }
  }

  assert |dp2| == i + 1;
  assert |paths2| == i + 1;
  assert i + 1 <= |s|;
  AssemblePrefix(s, dp2, paths2, i + 1);
  assert dp2 == dp + [best];
  assert paths2 == paths + [newPath];
  PrefixOKEq(s, dp2, paths2, dp + [best], paths + [newPath], i + 1, i + 1);
