    assert |sub| <= dp[last];
    assert 0 <= last < |s|;
    assert last < |dp|;
    LeResult(dp, |s|, result, last);
    assert dp[last] <= result;
    assert |sub| <= result;
  }

  var chosen := paths[wit];
