  var b := rest + [nxt];
  forall a | 0 <= a < |b|
    ensures 0 <= b[a] < |s|
  {
    if a < |rest| {
      assert b[a] == rest[a];
      InBounds(s, rest, a);
    } else {
      assert a == |rest|;
      assert b[a] == nxt;
    }
  }
  forall a, c | 0 <= a < c < |b|
    ensures b[a] < b[c]
  {
    if c < |rest| {
      assert b[a] == rest[a];
      assert b[c] == rest[c];
      OrderedIdx(s, rest, a, c);
    } else {
      assert c == |rest|;
      assert b[c] == nxt;
      assert b[a] == rest[a];
      if a < |rest| - 1 {
        OrderedIdx(s, rest, a, |rest| - 1);
        assert rest[|rest| - 1] == prev;
        assert rest[a] < prev;
        assert prev < nxt;
        assert rest[a] < nxt;
      } else {
        assert a == |rest| - 1;
        assert rest[a] == prev;
        assert prev < nxt;
      }
    }
  }
  forall a, c | 0 <= a < c < |b|
    ensures s[b[a]] < s[b[c]]
  {
    if c < |rest| {
      assert b[a] == rest[a];
      assert b[c] == rest[c];
      OrderedIdx(s, rest, a, c);
      OrderedVal(s, rest, a, c);
    } else {
      assert c == |rest|;
      assert b[c] == nxt;
      assert b[a] == rest[a];
      if a < |rest| - 1 {
        OrderedIdx(s, rest, a, |rest| - 1);
        OrderedVal(s, rest, a, |rest| - 1);
        assert rest[|rest| - 1] == prev;
        assert s[rest[a]] < s[prev];
        assert s[prev] < s[nxt];
        assert s[rest[a]] < s[nxt];
      } else {
        assert a == |rest| - 1;
        assert rest[a] == prev;
        assert s[prev] < s[nxt];
      }
    }
  }
  assert forall k :: 0 <= k < |b| ==> 0 <= b[k] < |s|;
  assert forall k, m :: 0 <= k < m < |b| ==> b[k] < b[m];
  assert forall k, m :: 0 <= k < m < |b| ==> s[b[k]] < s[b[m]];
  assert is_valid_is(s, b);
}

