lemma ExtendOK(
    s: seq<int>, dp: seq<int>, paths: seq<seq<int>>,
    i: int, best: int, bestPred: int
  ) returns (newPath: seq<int>)
  requires |dp| == i && |paths| == i
  requires 0 <= i < |s|
  requires PrefixOK(s, dp, paths, i)
  requires GoodChoice(s, dp, paths, i, i, best, bestPred)
  requires forall m :: 0 <= m < i && s[m] < s[i] ==> dp[m] + 1 <= best
  ensures PrefixOK(s, dp + [best], paths + [newPath], i + 1)
{
  GoodChoiceFacts(s, dp, paths, i, i, best, bestPred);
  assert best >= 1;
  assert best <= i + 1;
  if bestPred == -1 {
    assert best == 1;
    newPath := [i];
    SingletonValid(s, i);
    assert newPath == [i];
    assert is_valid_is(s, newPath);
    assert |newPath| == best;
    assert newPath[0] == i;
    assert newPath[|newPath| - 1] == i;
    LastIs(newPath);
    assert LastOrNeg(newPath) == i;
  } else {
    assert 0 <= bestPred < i;
    assert dp[bestPred] >= 1;
    assert s[bestPred] < s[i];
    assert best == dp[bestPred] + 1;
    assert is_valid_is(s, paths[bestPred]);
    assert |paths[bestPred]| == dp[bestPred];
    assert LastOrNeg(paths[bestPred]) == bestPred;
    var rest := paths[bestPred];
    assert |rest| == dp[bestPred];
    assert |rest| > 0;
    LastIs(rest);
    assert rest[|rest| - 1] == bestPred;
    assert 0 <= bestPred < i < |s|;
    ExtendValid(s, rest, bestPred, i);
    newPath := rest + [i];
    assert newPath == rest + [i];
    assert is_valid_is(s, newPath);
    assert |newPath| == |rest| + 1;
    assert |newPath| == best;
    assert newPath[|newPath| - 1] == i;
    LastIs(newPath);
    assert LastOrNeg(newPath) == i;
  }
  assert is_valid_is(s, newPath);
  assert |newPath| == best;
  assert LastOrNeg(newPath) == i;

  var dp2 := dp + [best];
  var paths2 := paths + [newPath];

  forall idx | 0 <= idx < i
    ensures dp2[idx] == dp[idx] && paths2[idx] == paths[idx]
  {
  }
  assert dp2[i] == best;
  assert paths2[i] == newPath;

  forall idx | 0 <= idx < i + 1
    ensures dp2[idx] >= 1 && dp2[idx] <= idx + 1 && is_valid_is(s, paths2[idx]) && |paths2[idx]| == dp2[idx] && LastOrNeg(paths2[idx]) == idx
  {
    if idx < i {
      assert dp2[idx] == dp[idx];
      assert paths2[idx] == paths[idx];
      PrefixAt(s, dp, paths, i, idx);
      assert is_valid_is(s, paths2[idx]);
      assert |paths2[idx]| == dp2[idx];
      assert LastOrNeg(paths2[idx]) == idx;
      assert dp2[idx] >= 1;
      assert dp2[idx] <= idx + 1;
    } else {
      assert idx == i;
      assert dp2[idx] == best;
      assert paths2[idx] == newPath;
      assert |newPath| == best;
      assert LastOrNeg(newPath) == i;
      assert LastOrNeg(paths2[idx]) == idx;
      assert is_valid_is(s, paths2[idx]);
      assert dp2[idx] >= 1;
      assert best <= i + 1;
      assert dp2[idx] <= idx + 1;
    }
  }

  forall a, b | 0 <= a < b < i + 1 && s[a] < s[b]
    ensures dp2[a] + 1 <= dp2[b]
  {
    if b < i {
      assert dp2[a] == dp[a];
      assert dp2[b] == dp[b];
      PrefixDom(s, dp, paths, i, a, b);
    } else {
      assert b == i;
      assert dp2[a] == dp[a];
      assert dp2[b] == best;
      assert a < i;
      CovAt(s, dp, i, a, best);
      assert dp[a] + 1 <= best;
    }
  }

  assert |dp2| == i + 1;
  assert |paths2| == i + 1;
  assert i + 1 <= |s|;
  AssemblePrefix(s, dp2, paths2, i + 1);
  assert dp2 == dp + [best];
  assert paths2 == paths + [newPath];
  PrefixOKEq(s, dp2, paths2, dp + [best], paths + [newPath], i + 1, i + 1);
}

lemma UpperBound(s: seq<int>, dp: seq<int>, paths: seq<seq<int>>, sub: seq<int>)
  requires |dp| == |s| && |paths| == |s|
  requires PrefixOK(s, dp, paths, |s|)
  requires is_valid_is(s, sub)
  requires |sub| > 0
  ensures |sub| <= dp[sub[|sub| - 1]]
  decreases |sub|
{
  if |sub| == 1 {
    var last := sub[0];
    InBounds(s, sub, 0);
    assert 0 <= last < |s|;
    PrefixAt(s, dp, paths, |s|, last);
    assert dp[last] >= 1;
    assert |sub| - 1 == 0;
    assert sub[|sub| - 1] == last;
    assert |sub| <= dp[last];
    assert |sub| <= dp[sub[|sub| - 1]];
  } else {
    assert |sub| >= 2;
    var lastPos := |sub| - 1;
    var prevPos := |sub| - 2;
    assert prevPos == lastPos - 1;
    PrefixValid(s, sub, lastPos);
    var pre := sub[..lastPos];
    assert |pre| == lastPos;
    assert |pre| == prevPos + 1;
    assert |pre| > 0;
    UpperBound(s, dp, paths, pre);
    var prev := sub[prevPos];
    var last := sub[lastPos];
    assert 0 <= prevPos < |pre|;
    assert pre[prevPos] == sub[prevPos];
    assert pre[|pre| - 1] == prev;
    assert |pre| <= dp[pre[|pre| - 1]];
    assert |pre| <= dp[prev];
    OrderedIdx(s, sub, prevPos, lastPos);
    assert sub[prevPos] < sub[lastPos];
    assert prev < last;
    assert 0 <= prev < |s|;
    assert 0 <= last < |s|;
    OrderedVal(s, sub, prevPos, lastPos);
    assert s[prev] < s[last];
    assert 0 <= prev < last < |s|;
    PrefixDom(s, dp, paths, |s|, prev, last);
    assert dp[prev] + 1 <= dp[last];
    assert |sub| == |pre| + 1;
    assert |sub| <= dp[prev] + 1;
    assert lastPos == |sub| - 1;
    assert last == sub[|sub| - 1];
    assert |sub| <= dp[last];
    assert |sub| <= dp[sub[|sub| - 1]];
  }
}

