lemma FlowPrefixDomain(
    n: int,
    xs: seq<int>,
    k: int,
    u: int,
    v: int
)
    requires 0 < n
    requires 0 <= k <= |xs|
    requires (u, v) in FlowPrefix(n, xs, k)
    ensures exists j: int ::
        0 <= j < k &&
        u == j / n &&
        v == j % n
    decreases k
{
    if k > 0 {
        var previous := FlowPrefix(n, xs, k - 1);
        var j := k - 1;

        if (u, v) == (j / n, j % n) {
            assert 0 <= j < k;
        } else {
            assert (u, v) in previous;
            FlowPrefixDomain(n, xs, k - 1, u, v);
