lemma FlatInCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    u: int,
    k: int
)
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g|
    ensures sum_flow_in_recursive(
                g, FlowOf(|g|, xs), u, k)
            ==
            FlatIn(xs, |g|, u, k)
    decreases k
{
    if k > 0 {
        FlatInCorrespondence(g, xs, u, k - 1);

        var j := (k - 1) * |g| + u;
        assert 0 <= j < |xs|;

        QuotientRemainderCoordinates(
            |g|, k - 1, u);
        FlowOfGet(|g|, xs, j);

        assert get_flow(
                    FlowOf(|g|, xs),
                    k - 1,
                    u)
                == xs[j];
    }
}

lemma FlatOutCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    u: int,
    k: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g[u]|
    ensures sum_flow_out_recursive(
                g, FlowOf(|g|, xs), u, k)
            ==
            FlatOut(g, xs, u, k)
    decreases k
{
    if k > 0 {
        FlatOutCorrespondence(g, xs, u, k - 1);

        var v := g[u][k - 1].0;
        assert 0 <= v < |g|;

        var j := u * |g| + v;
        assert 0 <= j < |xs|;

        QuotientRemainderCoordinates(|g|, u, v);
        FlowOfGet(|g|, xs, j);

        assert get_flow(
                    FlowOf(|g|, xs), u, v)
                == xs[j];
    }
}

lemma FlatOKImpliesValid(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires FlatOK(g, xs, s, t)
    ensures is_valid_flow(
                g, FlowOf(|g|, xs), s, t)
{
    var n := |g|;
    var f := FlowOf(n, xs);

    assert |xs| == n * n;

    forall u: int, v: int | (u, v) in f
        ensures
            f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c)
                &&
                f[(u, v)] <= c
    {
        FlowPrefixDomain(
            n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];

        if f[(u, v)] > 0 {
            var i: int :|
                0 <= i < |g[j / n]|
                &&
                g[j / n][i].0 == j % n
                &&
                xs[j] <= g[j / n][i].1;

            var c := g[j / n][i].1;
            assert has_capacity(g, u, v, c);
        }
    }

    assert respects_capacity(g, f);

    forall u: int, v: int | (u, v) in f
        ensures f[(u, v)] >= 0
    {
        FlowPrefixDomain(
            n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];
        assert 0 <= xs[j];
    }

    forall u: int |
        0 <= u < n && u != s && u != t
        ensures total_flow_in(g, f, u) ==
                total_flow_out(g, f, u)
    {
        FlatInCorrespondence(g, xs, u, n);
        FlatOutCorrespondence(
            g, xs, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == FlatIn(xs, n, u, n);
        assert total_flow_out(g, f, u)
               == FlatOut(g, xs, u, |g[u]|);
    }

    assert is_conserved(g, f, s, t);
}

lemma FlatValueCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= s < |g|
    ensures flow_val(
                g, FlowOf(|g|, xs), s)
            ==
            FlatValue(g, xs, s)
{
    FlatInCorrespondence(
        g, xs, s, |g|);
    FlatOutCorrespondence(
        g, xs, s, |g[s]|);
}

