lemma VectorOfValidFlowIsFlatOK(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires 0 < |g|
    requires is_valid_flow(g, f, s, t)
    ensures FlatOK(g, VectorOf(g, f), s, t)
{
    var n := |g|;
    var xs := VectorOf(g, f);

    assert |xs| == n * n;

    forall k: int | 0 <= k < |xs|
        ensures
            0 <= xs[k] <= 100_000
            &&
            (xs[k] > 0 ==>
                exists i: int |
                    0 <= i < |g[k / n]| ::
                    g[k / n][i].0 == k % n
                    &&
                    xs[k] <= g[k / n][i].1)
    {
        PositionCoordinates(n, k);
        assert 0 <= k / n < n;
        assert 0 <= k % n < n;

        FlowEntryBound(
            g, f, s, t, k / n, k % n);

        assert xs[k]
               == get_flow(
                    f, k / n, k % n);

        if xs[k] > 0 {
            assert respects_capacity(g, f);

            var c: int :|
                has_capacity(
                    g, k / n, k % n, c)
                &&
                xs[k] <= c;

            var i: int :|
                0 <= k / n < |g|
                &&
                0 <= i < |g[k / n]|
                &&
                g[k / n][i].0 == k % n
                &&
                g[k / n][i].1 == c;

            assert xs[k] <= g[k / n][i].1;
        }
    }

    forall u: int |
        0 <= u < n && u != s && u != t
        ensures
            FlatIn(xs, n, u, n)
            ==
            FlatOut(g, xs, u, |g[u]|)
    {
        VectorInCorrespondence(g, f, u, n);
        VectorOutCorrespondence(
            g, f, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == total_flow_out(g, f, u);
    }
}

