lemma CandidateExtension(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    xs: seq<int>,
    d: int
)
    requires 0 < |g|
    requires |prefix| < |g| * |g|
    ensures
        Candidate(
            g, s, t, prefix + [d], xs)
        ==
        (Candidate(g, s, t, prefix, xs)
         && xs[|prefix|] == d)
{
    if Candidate(
        g, s, t, prefix + [d], xs)
    {
        assert xs[..|prefix| + 1]
               == prefix + [d];
        assert xs[..|prefix|] == prefix;
        assert xs[|prefix|] == d;
    }

    if Candidate(g, s, t, prefix, xs)
       && xs[|prefix|] == d
    {
        assert xs[..|prefix| + 1]
               ==
               xs[..|prefix|] +
               [xs[|prefix|]];
        assert xs[..|prefix| + 1]
               == prefix + [d];
    }
}

method SearchMaximum(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
) returns (found: bool, best: int)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= s < |g|
    requires 0 <= t < |g|
    requires |prefix| <= |g| * |g|
    requires forall k: int |
        0 <= k < |prefix| ::
        0 <= prefix[k] <= 100_000
    ensures found ==
        (exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs))
    ensures found ==>
        exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs)
            &&
            FlatValue(g, xs, s) == best
    ensures forall xs: seq<int> ::
        Candidate(g, s, t, prefix, xs)
        ==>
        FlatValue(g, xs, s) <= best
    decreases |g| * |g| - |prefix|
{
    var total := |g| * |g|;

    if |prefix| == total {
        if FlatOK(g, prefix, s, t) {
            found := true;
            best := FlatValue(g, prefix, s);

            assert Candidate(
                g, s, t, prefix, prefix);
        } else {
            found := false;
            best := 0;
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures xs == prefix
        {
            assert |xs| == |prefix|;
            assert xs[..|xs|] == xs;
            assert xs[..|prefix|] == prefix;
        }
    } else {
        var pos := |prefix|;
        found := false;
        best := 0;

        assert !(exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs)
            &&
            xs[pos] < 0) by {
            if exists xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < 0
            {
                var xs: seq<int> :|
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < 0;
                assert 0 <= xs[pos];
                assert false;
            }
        }

        var d := 0;
        while d <= 100_000
            invariant 0 <= d <= 100_001
            invariant found ==
                (exists xs: seq<int> ::
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d)
            invariant found ==>
                exists xs: seq<int> ::
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s) == best
            invariant forall xs: seq<int> ::
                Candidate(
                    g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s) <= best
            decreases 100_001 - d
        {
            assert forall k: int |
                0 <= k < |prefix + [d]| ::
                0 <= (prefix + [d])[k]
                   <= 100_000;

            var childFound, childBest :=
                SearchMaximum(
                    g, s, t, prefix + [d]);

            var oldFound := found;
            var oldBest := best;

            assert oldFound ==
                (exists xs: seq<int> ::
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d);

            assert oldFound ==>
                exists xs: seq<int> ::
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s)
                        == oldBest;

            assert forall xs: seq<int> ::
                Candidate(
                    g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s)
                    <= oldBest;

            if childFound
               && (!oldFound
                   || childBest > oldBest)
            {
                found := true;
                best := childBest;
            } else {
                found := oldFound;
                best := oldBest;
            }

            if oldFound {
                assert oldBest <= best;
            }

            if childFound {
                assert childBest <= best;
            }

            if found {
                if childFound
                   && (!oldFound
                       || childBest > oldBest)
                {
                    var xs: seq<int> :|
                        Candidate(
                            g, s, t,
                            prefix + [d], xs)
                        &&
                        FlatValue(g, xs, s)
                            == childBest;

                    CandidateExtension(
                        g, s, t,
                        prefix, xs, d);

                    assert Candidate(
                        g, s, t, prefix, xs);
                    assert xs[pos] == d;
                    assert xs[pos] < d + 1;
                    assert FlatValue(g, xs, s)
                           == best;
                } else {
                    assert oldFound;
                    var xs: seq<int> :|
                        Candidate(
                            g, s, t,
                            prefix, xs)
                        &&
                        xs[pos] < d
                        &&
                        FlatValue(g, xs, s)
                            == oldBest;

                    assert xs[pos] < d + 1;
                    assert FlatValue(g, xs, s)
                           == best;
                }
            }

            forall xs: seq<int> |
                Candidate(
                    g, s, t, prefix, xs)
                &&
                xs[pos] < d + 1
                ensures
                    FlatValue(g, xs, s)
                    <= best
            {
                if xs[pos] < d {
                    assert FlatValue(g, xs, s)
                           <= oldBest;
                    assert oldFound;
                    assert oldBest <= best;
                } else {
                    assert xs[pos] == d;
                    CandidateExtension(
                        g, s, t,
                        prefix, xs, d);
                    assert Candidate(
                        g, s, t,
                        prefix + [d], xs);
                    assert childFound;
                    assert FlatValue(g, xs, s)
                           <= childBest;
                    assert childBest <= best;
                }
            }

            if exists xs: seq<int> ::
                Candidate(
                    g, s, t, prefix, xs)
                &&
                xs[pos] < d + 1
            {
                var xs: seq<int> :|
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d + 1;

                if xs[pos] < d {
                    assert oldFound;
                    assert found;
                } else {
                    assert xs[pos] == d;
                    CandidateExtension(
                        g, s, t,
                        prefix, xs, d);
                    assert childFound;
                    assert found;
                }
            }

            assert found ==
                (exists xs: seq<int> ::
                    Candidate(
                        g, s, t, prefix, xs)
                    &&
                    xs[pos] < d + 1);

            d := d + 1;
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures 0 <= xs[pos] <= 100_000
        {
            assert FlatOK(g, xs, s, t);
            assert 0 <= pos < |xs|;
        }

        assert found ==
            (exists xs: seq<int> ::
                Candidate(g, s, t, prefix, xs));

        if found {
            var xs: seq<int> :|
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < 100_001
                &&
                FlatValue(g, xs, s) == best;

            assert Candidate(
                g, s, t, prefix, xs);
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures FlatValue(g, xs, s) <= best
        {
            assert xs[pos] < 100_001;
        }
    }
}

method max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int
) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    assert 0 < |g|;

    var found, computed :=
        SearchMaximum(g, s, t, []);

    ghost var zero: FlowMap := map[];
    EmptyFlowIsValid(g, s, t);
    VectorOfValidFlowIsFlatOK(
        g, zero, s, t);

    ghost var zeroVector := VectorOf(g, zero);
    assert Candidate(g, s, t, [], zeroVector);
    assert found;

    max_val := computed;

    ghost var xs: seq<int> :|
        Candidate(g, s, t, [], xs)
        &&
        FlatValue(g, xs, s) == max_val;

    FlatOKImpliesValid(g, xs, s, t);
    FlatValueCorrespondence(g, xs, s);

    ghost var maximumFlow :=
        FlowOf(|g|, xs);

    forall other: FlowMap |
        is_valid_flow(g, other, s, t)
        ensures flow_val(g, other, s)
                <= flow_val(g, maximumFlow, s)
    {
        VectorOfValidFlowIsFlatOK(
            g, other, s, t);

        ghost var otherVector :=
            VectorOf(g, other);

        assert Candidate(
            g, s, t, [], otherVector);

        assert FlatValue(
                    g, otherVector, s)
               <= max_val;

        VectorValueCorrespondence(
            g, other, s);

        assert flow_val(g, maximumFlow, s)
               == max_val;
    }

    assert is_max_flow(
        g, maximumFlow, s, t);
    assert flow_val(
        g, maximumFlow, s) == max_val;
}
