            assert s[0] <= s[i];
        }
    }
}

lemma prepend_sorted(x: int, s: seq<int>)
    requires is_sorted(s)
    requires all_ge(x, s)
    ensures is_sorted([x] + s)
{
    forall i, j | 0 <= i < j < |[x] + s|
        ensures ([x] + s)[i] <= ([x] + s)[j]
    {
        if i == 0 {
            assert 0 <= j - 1 < |s|;
            assert ([x] + s)[i] == x;
            assert ([x] + s)[j] == s[j - 1];
            assert x <= s[j - 1];
        } else {
            assert 0 <= i - 1 < j - 1 < |s|;
            assert ([x] + s)[i] == s[i - 1];
            assert ([x] + s)[j] == s[j - 1];
            assert s[i - 1] <= s[j - 1];
        }
    }
}

