lemma FlatOKImpliesValid(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires FlatOK(g, xs, s, t)
    ensures is_valid_flow(
                g, FlowOf(|g|, xs), s, t)
{
    var n := |g|;
    var f := FlowOf(n, xs);

    assert |xs| == n * n;

    forall u: int, v: int | (u, v) in f
        ensures
            f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c)
                &&
                f[(u, v)] <= c
    {
        FlowPrefixDomain(
            n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];

        if f[(u, v)] > 0 {
            var i: int :|
                0 <= i < |g[j / n]|
                &&
                g[j / n][i].0 == j % n
                &&
                xs[j] <= g[j / n][i].1;

            var c := g[j / n][i].1;
            assert has_capacity(g, u, v, c);
        }
    }

    assert respects_capacity(g, f);

    forall u: int, v: int | (u, v) in f
        ensures f[(u, v)] >= 0
    {
        FlowPrefixDomain(
            n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];
        assert 0 <= xs[j];
    }

    forall u: int |
        0 <= u < n && u != s && u != t
        ensures total_flow_in(g, f, u) ==
                total_flow_out(g, f, u)
    {
        FlatInCorrespondence(g, xs, u, n);
        FlatOutCorrespondence(
            g, xs, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == FlatIn(xs, n, u, n);
        assert total_flow_out(g, f, u)
               == FlatOut(g, xs, u, |g[u]|);
    }

    assert is_conserved(g, f, s, t);
}

