function lift_permutation(p: seq<int>, k: int): seq<int>
    requires 0 <= k <= |p|
{
    seq(|p| + 1, i =>
        if i < k then
            1 + p[i]
        else if i == k then
            0
        else
            1 + p[i - 1])
