lemma lift_valid_permutation(p: seq<int>, k: int, n: int)
    requires 0 < n
    requires 0 <= k < n
    requires is_valid_index_permutation(p, n - 1)
    ensures is_valid_index_permutation(lift_permutation(p, k), n)
{
    assert |p| == n - 1;
    assert |lift_permutation(p, k)| == n;

    forall i | 0 <= i < n
        ensures 0 <= lift_permutation(p, k)[i] < n
    {
        if i == k {
            assert lift_permutation(p, k)[i] == 0;
        } else {
            var r := if i < k then i else i - 1;
            assert 0 <= r < n - 1;
            assert 0 <= p[r] < n - 1;
            assert lift_permutation(p, k)[i] == 1 + p[r];
        }
    }

    forall i, j | 0 <= i < j < n
        ensures lift_permutation(p, k)[i] != lift_permutation(p, k)[j]
    {
        if i == k {
            var rj := if j < k then j else j - 1;
            assert 0 <= rj < n - 1;
            assert 0 <= p[rj] < n - 1;
            assert lift_permutation(p, k)[i] == 0;
            assert lift_permutation(p, k)[j] == 1 + p[rj];
        } else if j == k {
            var ri := if i < k then i else i - 1;
            assert 0 <= ri < n - 1;
            assert 0 <= p[ri] < n - 1;
            assert lift_permutation(p, k)[i] == 1 + p[ri];
            assert lift_permutation(p, k)[j] == 0;
        } else {
            var ri := if i < k then i else i - 1;
            var rj := if j < k then j else j - 1;
            assert 0 <= ri < rj < n - 1;
            assert p[ri] != p[rj];
            assert lift_permutation(p, k)[i] == 1 + p[ri];
            assert lift_permutation(p, k)[j] == 1 + p[rj];
        }
    }
}

lemma equal_multisets_are_permutations(a: seq<int>, b: seq<int>)
    requires multiset(a) == multiset(b)
    ensures is_permutation(a, b)
    decreases |a|
{
    multiset_size(a);
    multiset_size(b);
    assert |a| == |b|;

    if |a| == 0 {
        assert |b| == 0;
        var p: seq<int> := [];
        assert is_valid_index_permutation(p, 0);
        assert forall i {:trigger p[i]} ::
            0 <= i < |a| ==> b[i] == a[p[i]];
        assert exists q: seq<int> ::
            is_valid_index_permutation(q, |a|)
            && |a| == |b|
            && (forall i {:trigger q[i]} ::
                0 <= i < |a| ==> b[i] == a[q[i]]);
    } else {
        assert a[0] in multiset(a);
        assert a[0] in multiset(b);
        multiset_membership(b, a[0]);
        assert a[0] in b;

        var k :| 0 <= k < |b| && b[k] == a[0];
        var ar := a[1..];
        var br := remove_at(b, k);

        assert remove_at(a, 0) == ar;
        remove_at_multiset(a, 0);
        remove_at_multiset(b, k);
        assert multiset(ar) + multiset{a[0]} == multiset(a);
        assert multiset(br) + multiset{a[0]} == multiset(b);
        assert multiset(ar) + multiset{a[0]}
            == multiset(br) + multiset{a[0]};
        multiset_cancel_int(multiset(ar), multiset(br), a[0]);
        assert multiset(ar) == multiset(br);

        equal_multisets_are_permutations(ar, br);

        assert exists p: seq<int> ::
            is_valid_index_permutation(p, |ar|)
            && |ar| == |br|
            && (forall i {:trigger p[i]} ::
                0 <= i < |ar| ==> br[i] == ar[p[i]]);

        var p :|
            is_valid_index_permutation(p, |ar|)
            && |ar| == |br|
            && (forall i {:trigger p[i]} ::
                0 <= i < |ar| ==> br[i] == ar[p[i]]);

        lift_valid_permutation(p, k, |a|);
        var q := lift_permutation(p, k);

        forall i | 0 <= i < |a|
            ensures b[i] == a[q[i]]
        {
            if i == k {
                assert q[i] == 0;
                assert b[i] == a[0];
            } else {
                var r := if i < k then i else i - 1;
                assert 0 <= r < |br|;

                if i < k {
                    remove_at_index(b, k, r);
                    assert br[r] == b[i];
                } else {
                    assert k < i;
                    remove_at_index(b, k, r);
                    assert br[r] == b[i];
                }

                assert 0 <= p[r] < |ar|;
                assert br[r] == ar[p[r]];
                assert ar[p[r]] == a[p[r] + 1];
                assert q[i] == p[r] + 1;
            }
        }

        assert is_valid_index_permutation(q, |a|);
        assert forall i {:trigger q[i]} ::
            0 <= i < |a| ==> b[i] == a[q[i]];
        assert exists r: seq<int> ::
            is_valid_index_permutation(r, |a|)
            && |a| == |b|
            && (forall i {:trigger r[i]} ::
                0 <= i < |a| ==> b[i] == a[r[i]]);
    }
}

