lemma insert_preserves_lower_bound(lo: int, x: int, s: seq<int>)
    requires lo <= x
    requires all_ge(lo, s)
    ensures all_ge(lo, insert_sorted(x, s))
    decreases |s|
{
    if |s| == 0 {
    } else if x <= s[0] {
        forall i | 0 <= i < |[x] + s|
            ensures lo <= ([x] + s)[i]
        {
            if i == 0 {
                assert ([x] + s)[i] == x;
            } else {
                assert ([x] + s)[i] == s[i - 1];
                assert lo <= s[i - 1];
            }
