    } else {
        assert all_ge(lo, s[1..]) by
        {
            forall i | 0 <= i < |s[1..]|
                ensures lo <= s[1..][i]
            {
                assert s[1..][i] == s[i + 1];
                assert lo <= s[i + 1];
            }
        }

        insert_preserves_lower_bound(lo, x, s[1..]);

        forall i | 0 <= i < |[s[0]] + insert_sorted(x, s[1..])|
            ensures lo <= ([s[0]] + insert_sorted(x, s[1..]))[i]
        {
            if i == 0 {
                assert ([s[0]] + insert_sorted(x, s[1..]))[i] == s[0];
                assert lo <= s[0];
            } else {
                assert ([s[0]] + insert_sorted(x, s[1..]))[i]
                    == insert_sorted(x, s[1..])[i - 1];
                assert lo <= insert_sorted(x, s[1..])[i - 1];
            }
        }
    }
}

lemma insert_sorted_correct(x: int, s: seq<int>)
    requires is_sorted(s)
    ensures is_sorted(insert_sorted(x, s))
    ensures multiset(insert_sorted(x, s)) == multiset(s) + multiset{x}
    decreases |s|
{
    if |s| == 0 {
