lemma {:vcs_split_on_every_assert} VectorOfValidFlowIsFlatOK(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires 0 < |g|
    requires is_valid_flow(g, f, s, t)
    ensures FlatOK(g, VectorOf(g, f), s, t)
{
    var n := |g|;
    var xs := VectorOf(g, f);

    assert |xs| == n * n;

    forall k: int | 0 <= k < |xs|
        ensures
            0 <= xs[k] <= 100_000
            &&
            (xs[k] > 0 ==>
                exists i: int |
                    0 <= i < |g[k / n]| ::
                    g[k / n][i].0 == k % n
                    &&
                    xs[k] <= g[k / n][i].1)
