        assert 0 <= k / n < n;
        assert 0 <= k % n < n;

        FlowEntryBound(
            g, f, s, t, k / n, k % n);

        assert xs[k]
               == get_flow(
                    f, k / n, k % n);

        if xs[k] > 0 {
            assert respects_capacity(g, f);

            var c: int :|
                has_capacity(
                    g, k / n, k % n, c)
                &&
                xs[k] <= c;

            var i: int :|
                0 <= k / n < |g|
                &&
                0 <= i < |g[k / n]|
                &&
                g[k / n][i].0 == k % n
                &&
                g[k / n][i].1 == c;

            assert xs[k] <= g[k / n][i].1;
