    forall u: int |
        0 <= u < n && u != s && u != t
        ensures
            FlatIn(xs, n, u, n)
            ==
            FlatOut(g, xs, u, |g[u]|)
    {
        VectorInCorrespondence(g, f, u, n);
        VectorOutCorrespondence(
            g, f, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == total_flow_out(g, f, u);
