            && calculate_revenue(cuts, prices) == result)
{
  if n < 0 {
    // No valid strategy exists for negative n: the upper bound holds vacuously,
    // but the existence postcondition is unsatisfiable on this path.
    forall cuts: seq<int> | is_valid_strategy(cuts, n, prices)
