  ghost var wit: seq<seq<int>> := [[]];
  BaseUB(prices);
  assert is_valid_strategy([], 0, prices);
  var i := 1;
  while i <= n
    invariant 1 <= i <= n + 1
    invariant |dp| == i && |wit| == i
    invariant forall k :: 0 <= k < i ==> dp[k] >= 0
    invariant forall k :: 0 <= k < i ==> is_valid_strategy(wit[k], k, prices) && calculate_revenue(wit[k], prices) == dp[k]
