  requires is_valid_strategy(rest, total - j, prices)
  ensures is_valid_strategy([j] + rest, total, prices)
  ensures calculate_revenue([j] + rest, prices) == prices[j - 1] + calculate_revenue(rest, prices)
{
  var s := [j] + rest;
  assert s[0] == j;
  assert s[1..] == rest;
}

lemma BaseUB(prices: seq<int>)
  ensures UpperBound(0, 0, prices)
{
  forall cuts: seq<int> | is_valid_strategy(cuts, 0, prices)
    ensures calculate_revenue(cuts, prices) <= 0
  {
    if |cuts| > 0 {
      SumNonneg(cuts[1..]);
      assert false;
    }
  }
}

method rod_cutting(n: int, prices: seq<int>) returns (result: int)
    // NOTE: added precondition. Without it the existence postcondition is
    // unsatisfiable for n < 0 (all cuts are positive, so sum_lengths >= 0).
    requires 0 <= n
    requires |prices| >= n
    requires n <= 1000
    // Constraints matching Verus u64/usize unsigned and explicit bounds
    requires forall i: int :: 0 <= i < |prices| ==> 0 <= prices[i] <= 10000
    ensures result >= 0
    // 1. Upper Bound
    ensures forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices) 
            ==> calculate_revenue(cuts, prices) <= result)
    // 2. Existence
    ensures exists cuts: seq<int> :: (is_valid_strategy(cuts, n, prices) 
            && calculate_revenue(cuts, prices) == result)
{
  var dp: seq<int> := [0];
  ghost var wit: seq<seq<int>> := [[]];
  BaseUB(prices);
  assert is_valid_strategy([], 0, prices);
  var i := 1;
  while i <= n
    invariant 1 <= i <= n + 1
    invariant |dp| == i && |wit| == i
    invariant forall k :: 0 <= k < i ==> dp[k] >= 0
    invariant forall k :: 0 <= k < i ==> is_valid_strategy(wit[k], k, prices) && calculate_revenue(wit[k], prices) == dp[k]
    invariant forall k :: 0 <= k < i ==> UpperBound(dp[k], k, prices)
  {
    var best := prices[0] + dp[i - 1];
    ghost var bw := [1] + wit[i - 1];
    Cons(1, wit[i - 1], i, prices);
    var j := 2;
    while j <= i
      invariant 2 <= j <= i + 1
      invariant best >= 0
      invariant forall k :: i - j < k <= i - 1 ==> prices[i - k - 1] + dp[k] <= best
      invariant is_valid_strategy(bw, i, prices) && calculate_revenue(bw, prices) == best
    {
      var cand := prices[j - 1] + dp[i - j];
      if cand > best {
        best := cand;
        bw := [j] + wit[i - j];
        Cons(j, wit[i - j], i, prices);
      }
      j := j + 1;
    }
    forall cuts: seq<int> | is_valid_strategy(cuts, i, prices)
      ensures calculate_revenue(cuts, prices) <= best
    {
      if |cuts| == 0 {
        assert sum_lengths(cuts) == 0;
        assert false;
      }
      ValidTail(cuts, i, prices);
      var c := cuts[0];
      SumNonneg(cuts[1..]);
      assert 1 <= c <= i;
      assert UpperBound(dp[i - c], i - c, prices);
      assert calculate_revenue(cuts[1..], prices) <= dp[i - c];
      assert prices[i - (i - c) - 1] + dp[i - c] <= best;
      assert prices[c - 1] + dp[i - c] <= best;
    }
    assert UpperBound(best, i, prices);
    dp := dp + [best];
    wit := wit + [bw];
    i := i + 1;
  }
  result := dp[n];
  assert UpperBound(dp[n], n, prices);
  assert is_valid_strategy(wit[n], n, prices) && calculate_revenue(wit[n], prices) == result;
}
