    requires forall a: int, b: int :: 0 <= a <= b <= j ==> spec_sum(s, a, b) <= oldResult
    ensures forall a: int, b: int :: 0 <= a <= b <= j + 1 ==> spec_sum(s, a, b) <= result
{
    forall a: int, b: int | 0 <= a <= b <= j + 1
        ensures spec_sum(s, a, b) <= result
    {
        if b <= j {
            assert spec_sum(s, a, b) <= oldResult;
            assert oldResult <= result;
            assert spec_sum(s, a, b) <= result;
        } else if a == j + 1 {
            assert b == j + 1;
            SumEmpty(s, a);
            assert a == b;
            assert spec_sum(s, a, b) == spec_sum(s, a, a);
            assert spec_sum(s, a, b) == 0;
            assert 0 <= result;
            assert spec_sum(s, a, b) <= result;
        } else {
            assert b == j + 1;
            assert a != j + 1;
            assert a <= j;
            assert 0 <= a <= j;
            assert a <= b;
            SumDiff(s, a, b);
            assert spec_sum(s, a, b) == spec_sum(s, 0, b) - spec_sum(s, 0, a);
            assert spec_sum(s, 0, b) == spec_sum(s, 0, j + 1);
            assert spec_sum(s, 0, j + 1) == newP;
            assert spec_sum(s, a, b) == newP - spec_sum(s, 0, a);
            assert minP <= spec_sum(s, 0, a);
            assert spec_sum(s, 0, a) >= minP;
            assert spec_sum(s, 0, a) - minP >= 0;
            assert (newP - minP) - (newP - spec_sum(s, 0, a)) == spec_sum(s, 0, a) - minP;
            assert (newP - minP) - (newP - spec_sum(s, 0, a)) >= 0;
            assert newP - spec_sum(s, 0, a) <= newP - minP;
            assert newP - minP <= result;
            assert spec_sum(s, a, b) <= result;
        }
    }
}

lemma {:vcs_split_on_every_assert} MinStep(s: seq<int>, oldJ: int, min0: int, mi0: int, p: int, newMin: int, nmi: int)
