    requires 0 <= mi0 <= oldJ
    requires min0 == spec_sum(s, 0, mi0)
    requires forall k: int :: 0 <= k <= oldJ ==> min0 <= spec_sum(s, 0, k)
    requires p == spec_sum(s, 0, oldJ + 1)
    requires p < min0 ==> newMin == p && nmi == oldJ + 1
    requires !(p < min0) ==> newMin == min0 && nmi == mi0
    ensures 0 <= nmi <= oldJ + 1
    ensures newMin == spec_sum(s, 0, nmi)
    ensures forall k: int :: 0 <= k <= oldJ + 1 ==> newMin <= spec_sum(s, 0, k)
{
    if p < min0 {
        assert newMin == p;
        assert nmi == oldJ + 1;
        assert p == spec_sum(s, 0, oldJ + 1);
        assert newMin == spec_sum(s, 0, nmi);
        assert 0 <= nmi <= oldJ + 1;
        forall k: int | 0 <= k <= oldJ + 1
            ensures newMin <= spec_sum(s, 0, k)
        {
            if k <= oldJ {
                assert min0 <= spec_sum(s, 0, k);
                assert newMin == p;
                assert p < min0;
                assert newMin < min0;
                assert newMin <= spec_sum(s, 0, k);
            } else {
                assert !(k <= oldJ);
                assert k == oldJ + 1;
                assert spec_sum(s, 0, k) == p;
                assert newMin == p;
                assert newMin <= spec_sum(s, 0, k);
            }
        }
    } else {
        assert !(p < min0);
        assert p >= min0;
        assert newMin == min0;
        assert nmi == mi0;
        assert newMin == spec_sum(s, 0, nmi);
        assert 0 <= nmi <= oldJ;
        assert 0 <= nmi <= oldJ + 1;
        forall k: int | 0 <= k <= oldJ + 1
            ensures newMin <= spec_sum(s, 0, k)
        {
            if k <= oldJ {
                assert min0 <= spec_sum(s, 0, k);
                assert newMin == min0;
                assert newMin <= spec_sum(s, 0, k);
            } else {
                assert !(k <= oldJ);
                assert k == oldJ + 1;
                assert spec_sum(s, 0, k) == p;
                assert p >= min0;
