    {
        assert k == 0;
        assert spec_sum(s, 0, k) == 0;
        assert minP == 0;
        assert minP <= spec_sum(s, 0, k);
    }

    forall a: int, b: int | 0 <= a <= b <= j
        ensures spec_sum(s, a, b) <= result
    {
        assert a == 0 && b == 0;
        assert a == b;
        SumEmpty(s, a);
        assert spec_sum(s, a, b) == spec_sum(s, a, a);
        assert spec_sum(s, a, b) == 0;
        assert result == 0;
        assert spec_sum(s, a, b) <= result;
    }

    while j < |s|
        invariant 0 <= j <= |s|
        invariant p == spec_sum(s, 0, j)
        invariant 0 <= mi <= j
        invariant minP == spec_sum(s, 0, mi)
        invariant forall k: int :: 0 <= k <= j ==> minP <= spec_sum(s, 0, k)
        invariant 0 <= bi <= bj <= j
        invariant result == spec_sum(s, bi, bj)
        invariant result >= 0
        invariant forall a: int, b: int :: 0 <= a <= b <= j ==> spec_sum(s, a, b) <= result
        decreases |s| - j
    {
        ghost var j0 := j;
        var min0 := minP;
        ghost var mi0 := mi;
        ghost var oldBi := bi;
        ghost var oldBj := bj;
        var oldResult := result;

        assert 0 <= j0 < |s|;
        assert j == j0;
        assert p == spec_sum(s, 0, j);
        assert p == spec_sum(s, 0, j0);
        assert minP == min0;
        assert mi == mi0;
        assert 0 <= mi0 <= j0;
        assert min0 == spec_sum(s, 0, mi0);
        assert result == oldResult;
        assert bi == oldBi && bj == oldBj;
        assert 0 <= oldBi <= oldBj <= j0;
        assert oldResult == spec_sum(s, oldBi, oldBj);
        assert oldResult >= 0;

        forall k: int | 0 <= k <= j0
            ensures min0 <= spec_sum(s, 0, k)
        {
            assert 0 <= k <= j;
            assert minP <= spec_sum(s, 0, k);
            assert minP == min0;
            assert min0 <= spec_sum(s, 0, k);
