        SumExtend(s, 0, j0);
        assert spec_sum(s, 0, j0 + 1) == spec_sum(s, 0, j0) + s[j0];
        var newP := p + s[j];
        assert j == j0;
        assert s[j] == s[j0];
        assert p == spec_sum(s, 0, j0);
        assert newP == spec_sum(s, 0, j0) + s[j0];
        assert newP == spec_sum(s, 0, j0 + 1);

        SumDiff(s, mi0, j0 + 1);
        assert spec_sum(s, mi0, j0 + 1) == spec_sum(s, 0, j0 + 1) - spec_sum(s, 0, mi0);
        assert spec_sum(s, 0, mi0) == min0;
        assert spec_sum(s, mi0, j0 + 1) == newP - min0;

        var cand := newP - min0;
        assert cand == newP - min0;
        assert cand == spec_sum(s, mi0, j0 + 1);

        if cand > oldResult {
            result := cand;
            bi := mi0;
            bj := j0 + 1;
            assert result == cand;
            assert bi == mi0 && bj == j0 + 1;
            assert result == spec_sum(s, mi0, j0 + 1);
            assert result == spec_sum(s, bi, bj);
            assert 0 <= mi0 <= j0;
            assert 0 <= bi <= bj <= j0 + 1;
            assert cand > oldResult;
            assert oldResult <= result;
            assert cand <= result;
            assert oldResult >= 0;
            assert result >= 0;
        } else {
            assert !(cand > oldResult);
            assert cand <= oldResult;
            assert result == oldResult;
            assert bi == oldBi && bj == oldBj;
            assert oldResult == spec_sum(s, oldBi, oldBj);
            assert result == spec_sum(s, bi, bj);
            assert 0 <= bi <= bj <= j0;
            assert bj <= j0 + 1;
            assert 0 <= bi <= bj <= j0 + 1;
            assert oldResult <= result;
            assert cand <= result;
            assert oldResult >= 0;
            assert result >= 0;
