        assert cand <= result;
        assert cand == newP - min0;
        assert newP - min0 <= result;
        assert oldResult <= result;
        assert result >= 0;
        assert result == spec_sum(s, bi, bj);
        assert 0 <= bi <= bj <= j0 + 1;
        assert newP == spec_sum(s, 0, j0 + 1);

        ExtendMax(s, j0, oldResult, result, min0, newP);
        assert forall a: int, b: int :: 0 <= a <= b <= j0 + 1 ==> spec_sum(s, a, b) <= result;

        assert j == j0;
        p := newP;
        j := j + 1;
        assert p == newP;
        assert p == spec_sum(s, 0, j0 + 1);
        assert j == j0 + 1;
        assert p == spec_sum(s, 0, j);
        assert 0 <= j <= |s|;

        if p < min0 {
            minP := p;
            mi := j;
            assert p < min0;
            assert j == j0 + 1;
            assert minP == p && mi == j0 + 1;
            MinStep(s, j0, min0, mi0, p, minP, mi);
            assert 0 <= mi <= j0 + 1;
            assert minP == spec_sum(s, 0, mi);
            assert forall k: int :: 0 <= k <= j0 + 1 ==> minP <= spec_sum(s, 0, k);
        } else {
            minP := min0;
            mi := mi0;
            assert !(p < min0);
            assert minP == min0 && mi == mi0;
            MinStep(s, j0, min0, mi0, p, minP, mi);
            assert 0 <= mi <= j0 + 1;
            assert minP == spec_sum(s, 0, mi);
            assert forall k: int :: 0 <= k <= j0 + 1 ==> minP <= spec_sum(s, 0, k);
        }

        assert j == j0 + 1;
        assert 0 <= mi <= j0 + 1;
        assert 0 <= mi <= j;
        assert minP == spec_sum(s, 0, mi);
        assert forall k: int :: 0 <= k <= j0 + 1 ==> minP <= spec_sum(s, 0, k);

        forall k: int | 0 <= k <= j
            ensures minP <= spec_sum(s, 0, k)
        {
