        forall a: int, b: int | 0 <= a <= b <= j
            ensures spec_sum(s, a, b) <= result
        {
            assert j == j0 + 1;
            assert 0 <= a <= b <= j0 + 1;
            assert spec_sum(s, a, b) <= result;
        }

        assert 0 <= bi <= bj <= j0 + 1;
        assert j == j0 + 1;
        assert 0 <= bi <= bj <= j;
        assert result == spec_sum(s, bi, bj);
