    assert j == |s|;
    assert 0 <= bi <= bj <= j;
    assert 0 <= bi <= bj <= |s|;
    assert result == spec_sum(s, bi, bj);
    assert result >= 0;

    forall a: int, b: int | 0 <= a <= b <= |s|
