    if |prefix| == total {
        if FlatOK(g, prefix, s, t) {
            found := true;
            best := FlatValue(g, prefix, s);
            assert Candidate(g, s, t, prefix, prefix);
        } else {
            found := false;
            best := 0;
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures xs == prefix
        {
            assert |xs| == |prefix|;
            assert xs[..|xs|] == xs;
            assert xs[..|prefix|] == prefix;
        }
    } else {
        var pos := |prefix|;
        found := false;
        best := 0;

        assert !(exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs)
            &&
            xs[pos] < 0) by
        {
            if exists xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < 0
