                ghost var xs: seq<int> :|
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < 0;

                assert FlatOK(g, xs, s, t);
                assert 0 <= pos < |xs|;
                FlatOKEntry(g, xs, s, t, pos);
                assert false;
            }
        }

        var d := 0;
        while d <= 100_000
            invariant 0 <= d <= 100_001
            invariant found ==
                (exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d)
            invariant found ==>
                exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s) == best
            invariant forall xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s) <= best
            decreases 100_001 - d
        {
            assert forall k: int |
                0 <= k < |prefix + [d]| ::
                0 <= (prefix + [d])[k] <= 100_000;

            var childFound, childBest :=
                SearchMaximum(g, s, t, prefix + [d]);

            var oldFound := found;
            var oldBest := best;

            assert oldFound ==
                (exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d);

            assert oldFound ==>
                exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s) == oldBest;

            assert forall xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s) <= oldBest;

            if childFound
               && (!oldFound || childBest > oldBest)
            {
                found := true;
                best := childBest;
            } else {
                found := oldFound;
                best := oldBest;
            }

            if oldFound {
                assert oldBest <= best;
            }

            if childFound {
                assert childBest <= best;
            }

            if found {
                if childFound
                   && (!oldFound || childBest > oldBest)
                {
                    ghost var xs: seq<int> :|
                        Candidate(g, s, t, prefix + [d], xs)
