            }

            forall xs: seq<int> |
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d + 1
                ensures FlatValue(g, xs, s) <= best
            {
                if xs[pos] < d {
                    assert FlatValue(g, xs, s) <= oldBest;
