                ghost var xs: seq<int> :|
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d + 1;

                if xs[pos] < d {
                    assert oldFound;
                    assert found;
                } else {
                    assert xs[pos] == d;
                    CandidateExtension(g, s, t, prefix, xs, d);
                    assert childFound;
                    assert found;
                }
            }

            assert found ==
                (exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d + 1);

            d := d + 1;
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures 0 <= xs[pos] <= 100_000
        {
            assert FlatOK(g, xs, s, t);
            assert 0 <= pos < |xs|;
