method {:vcs_split_on_every_assert} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int
) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    assert 0 < |g|;

    var found, computed :=
        SearchMaximum(g, s, t, []);

    ghost var zero: FlowMap := map[];
    EmptyFlowIsValid(g, s, t);
    VectorOfValidFlowIsFlatOK(g, zero, s, t);

    ghost var zeroVector := VectorOf(g, zero);
    assert Candidate(g, s, t, [], zeroVector);
    assert found;

    max_val := computed;

    ghost var xs: seq<int> :|
        Candidate(g, s, t, [], xs)
        &&
        FlatValue(g, xs, s) == max_val;

    FlatOKImpliesValid(g, xs, s, t);
    FlatValueCorrespondence(g, xs, s);

    ghost var maximumFlow := FlowOf(|g|, xs);

    assert is_valid_flow(g, maximumFlow, s, t);
    assert flow_val(g, maximumFlow, s) == max_val;

    forall other: FlowMap |
        is_valid_flow(g, other, s, t)
        ensures flow_val(g, other, s)
                <= flow_val(g, maximumFlow, s)
    {
        VectorOfValidFlowIsFlatOK(g, other, s, t);

        ghost var otherVector := VectorOf(g, other);
        assert Candidate(g, s, t, [], otherVector);
        assert FlatValue(g, otherVector, s) <= max_val;

        VectorValueCorrespondence(g, other, s);

        assert flow_val(g, maximumFlow, s) == max_val;
    }

    assert is_max_flow(g, maximumFlow, s, t);
    assert flow_val(g, maximumFlow, s) == max_val;
}

