    ensures (j / n) * n + j % n == j
{
    assert 0 <= j / n;
    assert 0 <= j % n < n;
    assert j == (j / n) * n + j % n;
}

lemma {:vcs_split_on_every_assert} SquarePosition(
    n: int,
    j: int
)
    requires 0 < n
    requires 0 <= j < n * n
    ensures 0 <= j / n < n
    ensures 0 <= j % n < n
    ensures (j / n) * n + j % n == j
{
    PositionCoordinates(n, j);

    var q := j / n;
    var r := j % n;

    if q >= n {
        assert n * n <= q * n;
        assert q * n <= q * n + r;
        assert q * n + r == j;
        assert false;
    }
}

lemma {:vcs_split_on_every_assert} CoordinateUniqueness(
    n: int,
    j: int,
    k: int
)
    requires 0 < n
    requires 0 <= j
    requires 0 <= k
    requires j / n == k / n
    requires j % n == k % n
    ensures j == k
{
    PositionCoordinates(n, j);
    PositionCoordinates(n, k);
}

function {:vcs_split_on_every_assert} FlatIn(
    xs: seq<int>,
    n: int,
    u: int,
    k: int
): int
    requires 0 < n
    requires |xs| == n * n
    requires 0 <= u < n
    requires 0 <= k <= n
    decreases k
{
    if k == 0 then
        0
    else
        FlatIn(xs, n, u, k - 1) +
        xs[(k - 1) * n + u]
}

function {:vcs_split_on_every_assert} FlatOut(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    u: int,
    k: int
): int
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g[u]|
    decreases k
{
    if k == 0 then
        0
    else
        var v := g[u][k - 1].0;
        var j := u * |g| + v;
        FlatOut(g, xs, u, k - 1) +
        (if 0 <= v < |g| && 0 <= j < |xs|
         then xs[j]
         else 0)
}

function {:vcs_split_on_every_assert} FlatValue(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int
): int
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= s < |g|
{
    FlatOut(g, xs, s, |g[s]|) -
    FlatIn(xs, |g|, s, |g|)
}

function {:vcs_split_on_every_assert} FlatOK(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int,
    t: int
): bool
    requires 0 < |g|
{
    var n := |g|;

    |xs| == n * n
    &&
    (forall k: int | 0 <= k < |xs| ::
        0 <= k / n < n
        &&
        0 <= k % n < n
        &&
        0 <= xs[k] <= 100_000
        &&
        (xs[k] > 0 ==>
            exists i: int |
                0 <= i < |g[k / n]| ::
                g[k / n][i].0 == k % n
                &&
                xs[k] <= g[k / n][i].1))
    &&
    (forall u: int |
        0 <= u < n && u != s && u != t ::
        FlatIn(xs, n, u, n) ==
        FlatOut(g, xs, u, |g[u]|))
}

lemma {:vcs_split_on_every_assert} FlatOKEntry(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int,
    t: int,
    k: int
)
    requires 0 < |g|
    requires FlatOK(g, xs, s, t)
    requires 0 <= k < |xs|
    ensures |xs| == |g| * |g|
    ensures 0 <= k / |g| < |g|
    ensures 0 <= k % |g| < |g|
    ensures 0 <= xs[k] <= 100_000
    ensures xs[k] > 0 ==>
        exists i: int |
            0 <= i < |g[k / |g|]| ::
            g[k / |g|][i].0 == k % |g|
            &&
            xs[k] <= g[k / |g|][i].1
{
}

function {:vcs_split_on_every_assert} FlowPrefix(
    n: int,
    xs: seq<int>,
    k: int
): FlowMap
    requires 0 < n
    requires 0 <= k <= |xs|
    decreases k
{
    if k == 0 then
        map[]
    else
        FlowPrefix(n, xs, k - 1)[
            ((k - 1) / n, (k - 1) % n) :=
                xs[k - 1]
        ]
}

function {:vcs_split_on_every_assert} FlowOf(
    n: int,
    xs: seq<int>
): FlowMap
    requires 0 < n
{
    FlowPrefix(n, xs, |xs|)
}

lemma {:vcs_split_on_every_assert} FlowPrefixDomain(
    n: int,
    xs: seq<int>,
    k: int,
    u: int,
    v: int
)
    requires 0 < n
    requires 0 <= k <= |xs|
    requires (u, v) in FlowPrefix(n, xs, k)
    ensures exists j: int ::
        0 <= j < k &&
        u == j / n &&
        v == j % n
    decreases k
{
    if k > 0 {
        var previous := FlowPrefix(n, xs, k - 1);
        var j := k - 1;

        if (u, v) == (j / n, j % n) {
            assert 0 <= j < k;
        } else {
            assert (u, v) in previous;
            FlowPrefixDomain(n, xs, k - 1, u, v);
        }
    }
}

lemma {:vcs_split_on_every_assert} FlowPrefixGet(
    n: int,
    xs: seq<int>,
    k: int,
    j: int
)
    requires 0 < n
    requires |xs| == n * n
    requires 0 <= k <= |xs|
    requires 0 <= j < |xs|
    ensures get_flow(
                FlowPrefix(n, xs, k),
                j / n,
                j % n)
            ==
            (if j < k then xs[j] else 0)
    decreases k
{
    if k > 0 {
        var q := k - 1;
        FlowPrefixGet(n, xs, k - 1, j);

        if j != q &&
           (j / n, j % n) == (q / n, q % n)
        {
            CoordinateUniqueness(n, j, q);
            assert false;
        }
    }
}

lemma {:vcs_split_on_every_assert} FlowOfGet(
    n: int,
    xs: seq<int>,
    j: int
)
    requires 0 < n
    requires |xs| == n * n
    requires 0 <= j < |xs|
    ensures get_flow(
                FlowOf(n, xs),
                j / n,
                j % n)
            == xs[j]
{
    FlowPrefixGet(n, xs, |xs|, j);
}

lemma {:vcs_split_on_every_assert} FlatInCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    u: int,
    k: int
)
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g|
    ensures sum_flow_in_recursive(
                g, FlowOf(|g|, xs), u, k)
            ==
            FlatIn(xs, |g|, u, k)
    decreases k
{
    if k > 0 {
        FlatInCorrespondence(g, xs, u, k - 1);

        var row := k - 1;
        var j := row * |g| + u;

        MatrixIndexBound(|g|, row, u);
        assert 0 <= j < |xs|;

        QuotientRemainderCoordinates(|g|, row, u);
        FlowOfGet(|g|, xs, j);

        assert j / |g| == row;
        assert j % |g| == u;
        assert get_flow(FlowOf(|g|, xs), row, u) == xs[j];
    }
}

lemma {:vcs_split_on_every_assert} FlatOutCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    u: int,
    k: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g[u]|
    ensures sum_flow_out_recursive(
                g, FlowOf(|g|, xs), u, k)
            ==
            FlatOut(g, xs, u, k)
    decreases k
{
    if k > 0 {
        FlatOutCorrespondence(g, xs, u, k - 1);

        var v := g[u][k - 1].0;
        assert 0 <= v < |g|;

        var j := u * |g| + v;
        MatrixIndexBound(|g|, u, v);
        assert 0 <= j < |xs|;

        QuotientRemainderCoordinates(|g|, u, v);
        FlowOfGet(|g|, xs, j);

        assert j / |g| == u;
        assert j % |g| == v;
        assert get_flow(FlowOf(|g|, xs), u, v) == xs[j];
    }
}

lemma {:vcs_split_on_every_assert} FlatOKImpliesValid(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires FlatOK(g, xs, s, t)
    ensures is_valid_flow(
                g, FlowOf(|g|, xs), s, t)
{
    var n := |g|;
    var f := FlowOf(n, xs);

    assert |xs| == n * n;

    forall u: int, v: int | (u, v) in f
        ensures
            f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c)
                &&
                f[(u, v)] <= c
    {
        FlowPrefixDomain(n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlatOKEntry(g, xs, s, t, j);
        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];
        assert 0 <= u < n;
        assert 0 <= v < n;

        if f[(u, v)] > 0 {
            assert xs[j] > 0;

            var i: int :|
                0 <= i < |g[j / n]|
                &&
                g[j / n][i].0 == j % n
                &&
                xs[j] <= g[j / n][i].1;

            var c := g[u][i].1;
            assert 0 <= i < |g[u]|;
            assert g[u][i].0 == v;
            assert has_capacity(g, u, v, c);
            assert f[(u, v)] <= c;
        }
    }

    assert respects_capacity(g, f);

    forall u: int, v: int | (u, v) in f
        ensures f[(u, v)] >= 0
    {
        FlowPrefixDomain(n, xs, |xs|, u, v);

        var j: int :|
            0 <= j < |xs|
            &&
            u == j / n
            &&
            v == j % n;

        FlatOKEntry(g, xs, s, t, j);
        FlowOfGet(n, xs, j);
        assert f[(u, v)] == xs[j];
    }

    forall u: int |
        0 <= u < n && u != s && u != t
        ensures total_flow_in(g, f, u) ==
                total_flow_out(g, f, u)
    {
        FlatInCorrespondence(g, xs, u, n);
        FlatOutCorrespondence(g, xs, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == FlatIn(xs, n, u, n);
        assert total_flow_out(g, f, u)
               == FlatOut(g, xs, u, |g[u]|);
    }

    assert is_conserved(g, f, s, t);
}

lemma {:vcs_split_on_every_assert} FlatValueCorrespondence(
    g: seq<seq<(int, int)>>,
    xs: seq<int>,
    s: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires |xs| == |g| * |g|
    requires 0 <= s < |g|
    ensures flow_val(
                g, FlowOf(|g|, xs), s)
            ==
            FlatValue(g, xs, s)
{
    FlatInCorrespondence(g, xs, s, |g|);
    FlatOutCorrespondence(g, xs, s, |g[s]|);
}

ghost function {:vcs_split_on_every_assert} VectorOf(
    g: seq<seq<(int, int)>>,
    f: FlowMap
): seq<int>
{
    var n := |g|;
    seq(n * n,
        k requires 0 <= k < n * n =>
            get_flow(f, k / n, k % n))
}

lemma {:vcs_split_on_every_assert} VectorInCorrespondence(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    k: int
)
    requires 0 < |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g|
    ensures FlatIn(
                VectorOf(g, f), |g|, u, k)
            ==
            sum_flow_in_recursive(g, f, u, k)
    decreases k
{
    if k > 0 {
        VectorInCorrespondence(g, f, u, k - 1);

        var row := k - 1;
        var j := row * |g| + u;

        MatrixIndexBound(|g|, row, u);
        assert 0 <= j < |g| * |g|;

        QuotientRemainderCoordinates(|g|, row, u);
        assert j / |g| == row;
        assert j % |g| == u;

        assert VectorOf(g, f)[j]
               == get_flow(f, row, u);
    }
}

lemma {:vcs_split_on_every_assert} VectorOutCorrespondence(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    k: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= u < |g|
    requires 0 <= k <= |g[u]|
    ensures FlatOut(
                g, VectorOf(g, f), u, k)
            ==
            sum_flow_out_recursive(g, f, u, k)
    decreases k
{
    if k > 0 {
        VectorOutCorrespondence(g, f, u, k - 1);

        var v := g[u][k - 1].0;
        assert 0 <= v < |g|;

        var j := u * |g| + v;
        MatrixIndexBound(|g|, u, v);
        assert 0 <= j < |g| * |g|;

        QuotientRemainderCoordinates(|g|, u, v);
        assert j / |g| == u;
        assert j % |g| == v;

        assert VectorOf(g, f)[j]
               == get_flow(f, u, v);
    }
}

lemma {:vcs_split_on_every_assert} VectorOfValidFlowIsFlatOK(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires 0 < |g|
    requires is_valid_flow(g, f, s, t)
    ensures FlatOK(g, VectorOf(g, f), s, t)
{
    var n := |g|;
    var xs := VectorOf(g, f);

    assert |xs| == n * n;

    forall k: int | 0 <= k < |xs|
        ensures
            0 <= k / n < n
            &&
            0 <= k % n < n
            &&
            0 <= xs[k] <= 100_000
            &&
            (xs[k] > 0 ==>
                exists i: int |
                    0 <= i < |g[k / n]| ::
                    g[k / n][i].0 == k % n
                    &&
                    xs[k] <= g[k / n][i].1)
    {
        assert 0 <= k < n * n;
        SquarePosition(n, k);

        var u := k / n;
        var v := k % n;

        assert 0 <= u < n;
        assert 0 <= v < n;
        assert xs[k] == get_flow(f, u, v);

        FlowEntryBound(g, f, s, t, u, v);

        if xs[k] > 0 {
            assert get_flow(f, u, v) > 0;

            if (u, v) !in f {
                assert get_flow(f, u, v) == 0;
                assert false;
            }

            assert f[(u, v)] == get_flow(f, u, v);
            var c: int :|
                has_capacity(g, u, v, c)
                &&
                f[(u, v)] <= c;

            var i: int :|
                0 <= u < |g|
                &&
                0 <= i < |g[u]|
                &&
                g[u][i].0 == v
                &&
                g[u][i].1 == c;

            assert xs[k] <= g[u][i].1;
        }
    }

    forall u: int |
        0 <= u < n && u != s && u != t
        ensures
            FlatIn(xs, n, u, n)
            ==
            FlatOut(g, xs, u, |g[u]|)
    {
        VectorInCorrespondence(g, f, u, n);
        VectorOutCorrespondence(g, f, u, |g[u]|);

        assert total_flow_in(g, f, u)
               == total_flow_out(g, f, u);
    }
}

lemma {:vcs_split_on_every_assert} VectorValueCorrespondence(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int
)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= s < |g|
    ensures FlatValue(
                g, VectorOf(g, f), s)
            ==
            flow_val(g, f, s)
{
    VectorInCorrespondence(g, f, s, |g|);
    VectorOutCorrespondence(g, f, s, |g[s]|);
}

ghost predicate Candidate(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    xs: seq<int>
) {
    0 < |g|
    &&
    |xs| == |g| * |g|
    &&
    |prefix| <= |xs|
    &&
    xs[..|prefix|] == prefix
    &&
    FlatOK(g, xs, s, t)
}

lemma {:vcs_split_on_every_assert} CandidateExtension(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    xs: seq<int>,
    d: int
)
    requires 0 < |g|
    requires |prefix| < |g| * |g|
    ensures
        Candidate(g, s, t, prefix + [d], xs)
        ==
        (Candidate(g, s, t, prefix, xs)
         && xs[|prefix|] == d)
{
    if Candidate(g, s, t, prefix + [d], xs) {
        assert xs[..|prefix| + 1] == prefix + [d];
        assert xs[..|prefix|] == prefix;
        assert xs[|prefix|] == d;
    }

    if Candidate(g, s, t, prefix, xs)
       && xs[|prefix|] == d
    {
        assert |prefix| < |xs|;
        assert xs[..|prefix| + 1]
               == xs[..|prefix|] + [xs[|prefix|]];
        assert xs[..|prefix| + 1] == prefix + [d];
    }
}

method {:vcs_split_on_every_assert} SearchMaximum(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
) returns (found: bool, best: int)
    requires well_formed(CapacityGraph(g))
    requires 0 < |g|
    requires 0 <= s < |g|
    requires 0 <= t < |g|
    requires |prefix| <= |g| * |g|
    requires forall k: int |
        0 <= k < |prefix| ::
        0 <= prefix[k] <= 100_000
    ensures found ==
        (exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs))
    ensures found ==>
        exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs)
            &&
            FlatValue(g, xs, s) == best
    ensures forall xs: seq<int> ::
        Candidate(g, s, t, prefix, xs)
        ==>
        FlatValue(g, xs, s) <= best
    decreases |g| * |g| - |prefix|
{
    var total := |g| * |g|;

    if |prefix| == total {
        if FlatOK(g, prefix, s, t) {
            found := true;
            best := FlatValue(g, prefix, s);
            assert Candidate(g, s, t, prefix, prefix);
        } else {
            found := false;
            best := 0;
        }

        forall xs: seq<int> |
            Candidate(g, s, t, prefix, xs)
            ensures xs == prefix
        {
            assert |xs| == |prefix|;
            assert xs[..|xs|] == xs;
            assert xs[..|prefix|] == prefix;
        }
    } else {
        var pos := |prefix|;
        found := false;
        best := 0;

        assert !(exists xs: seq<int> ::
            Candidate(g, s, t, prefix, xs)
            &&
            xs[pos] < 0) by
        {
            if exists xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < 0
            {
                ghost var xs: seq<int> :|
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < 0;

                assert FlatOK(g, xs, s, t);
                assert 0 <= pos < |xs|;
                FlatOKEntry(g, xs, s, t, pos);
                assert false;
            }
        }

        var d := 0;
        while d <= 100_000
            invariant 0 <= d <= 100_001
            invariant found ==
                (exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d)
            invariant found ==>
                exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s) == best
            invariant forall xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s) <= best
            decreases 100_001 - d
        {
            assert forall k: int |
                0 <= k < |prefix + [d]| ::
                0 <= (prefix + [d])[k] <= 100_000;

            var childFound, childBest :=
                SearchMaximum(g, s, t, prefix + [d]);

            var oldFound := found;
            var oldBest := best;

            assert oldFound ==
                (exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d);

            assert oldFound ==>
                exists xs: seq<int> ::
                    Candidate(g, s, t, prefix, xs)
                    &&
                    xs[pos] < d
                    &&
                    FlatValue(g, xs, s) == oldBest;

            assert forall xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d
                ==>
                FlatValue(g, xs, s) <= oldBest;

            if childFound
               && (!oldFound || childBest > oldBest)
            {
                found := true;
                best := childBest;
            } else {
                found := oldFound;
                best := oldBest;
            }

            if oldFound {
                assert oldBest <= best;
            }

            if childFound {
                assert childBest <= best;
            }

            if found {
                if childFound
                   && (!oldFound || childBest > oldBest)
                {
                    ghost var xs: seq<int> :|
                        Candidate(g, s, t, prefix + [d], xs)
                        &&
                        FlatValue(g, xs, s) == childBest;

                    CandidateExtension(g, s, t, prefix, xs, d);

                    assert Candidate(g, s, t, prefix, xs);
                    assert xs[pos] == d;
                    assert xs[pos] < d + 1;
                    assert FlatValue(g, xs, s) == best;
                } else {
                    assert oldFound;

                    ghost var xs: seq<int> :|
                        Candidate(g, s, t, prefix, xs)
                        &&
                        xs[pos] < d
                        &&
                        FlatValue(g, xs, s) == oldBest;

                    assert xs[pos] < d + 1;
                    assert FlatValue(g, xs, s) == best;
                }
            }

            forall xs: seq<int> |
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d + 1
                ensures FlatValue(g, xs, s) <= best
            {
                if xs[pos] < d {
                    assert FlatValue(g, xs, s) <= oldBest;
                    assert oldFound;
                    assert oldBest <= best;
                } else {
                    assert xs[pos] == d;
                    CandidateExtension(g, s, t, prefix, xs, d);
                    assert Candidate(g, s, t, prefix + [d], xs);
                    assert childFound;
                    assert FlatValue(g, xs, s) <= childBest;
                    assert childBest <= best;
                }
            }

            if exists xs: seq<int> ::
                Candidate(g, s, t, prefix, xs)
                &&
                xs[pos] < d + 1
            {
                ghost var xs: seq<int> :|
                    Candidate(g, s, t, prefix, xs)
                    &&
