lemma PathRefl(g: seq<seq<int>>, a: int)
    ensures has_path(g, a, a)
{
    var p := [a];
    assert path_valid(g, p);
}

lemma EdgePath(g: seq<seq<int>>, a: int, b: int)
    requires has_edge(g, a, b)
    ensures has_path(g, a, b)
{
    var p := [a, b];
    assert p[0] == a && p[1] == b;
    assert has_edge(g, p[0], p[1]);
    assert path_valid(g, p);
}

lemma PathTrans(g: seq<seq<int>>, a: int, b: int, c: int)
    requires has_path(g, a, b) && has_path(g, b, c)
    ensures has_path(g, a, c)
{
    var p :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_valid(g, p);
    var q :| |q| > 0 && q[0] == b && q[|q| - 1] == c && path_valid(g, q);
    var r := p + q[1..];
    forall k | 0 <= k < |r| - 1 ensures has_edge(g, r[k], r[k + 1]) {
        if k < |p| - 1 {
            assert r[k] == p[k] && r[k + 1] == p[k + 1];
        } else {
            var j := k - |p| + 1;
            assert 0 <= j < |q| - 1;
            if k == |p| - 1 {
                assert r[k] == p[|p| - 1] == q[0];
            } else {
                assert r[k] == q[1..][k - |p|] == q[j];
            }
            assert r[k + 1] == q[1..][k + 1 - |p|] == q[j + 1];
            assert has_edge(g, q[j], q[j + 1]);
        }
    }
    assert path_valid(g, r);
    assert r[0] == a;
    if |q| == 1 {
        assert r == p;
    } else {
        assert r[|r| - 1] == q[1..][|q| - 2] == q[|q| - 1];
    }
}

lemma MutualTrans(g: seq<seq<int>>, a: int, b: int, c: int)
