    PathTrans(g, c, b, a);
}

lemma ClosedReach(g: seq<seq<int>>, vis: seq<bool>, s: int, x: int)
    requires wf(g)
    requires |vis| == |g|
    requires 0 <= s < |g| && vis[s]
    requires forall v, i :: 0 <= v < |g| && vis[v] && 0 <= i < |g[v]| ==> vis[g[v][i]]
    requires has_path(g, s, x)
    ensures 0 <= x < |g| && vis[x]
{
    var p :| |p| > 0 && p[0] == s && p[|p| - 1] == x && path_valid(g, p);
    var k := 0;
    while k < |p| - 1
        invariant 0 <= k <= |p| - 1
        invariant 0 <= p[k] < |g| && vis[p[k]]
    {
        assert has_edge(g, p[k], p[k + 1]);
        var i :| 0 <= i < |g[p[k]]| && g[p[k]][i] == p[k + 1];
        k := k + 1;
    }
}

