        invariant |vis| == n && |done| == n
        invariant vis[s]
        invariant forall v :: 0 <= v < n && vis[v] ==> has_path(g, s, v)
        invariant forall v :: 0 <= v < n && done[v] ==> vis[v]
        invariant forall v, i :: 0 <= v < n && done[v] && 0 <= i < |g[v]| ==> vis[g[v][i]]
        decreases set v | 0 <= v < n && !done[v]
