        var w := 0;
        while w < n && !(vis[w] && !done[w])
            invariant 0 <= w <= n
            invariant forall x :: 0 <= x < w ==> !(vis[x] && !done[x])
        {
            w := w + 1;
        }
        if w == n {
            forall v | 0 <= v < n && vis[v] ensures done[v] { }
            forall x | 0 <= x < n ensures vis[x] <==> has_path(g, s, x) {
                if has_path(g, s, x) {
                    ClosedReach(g, vis, s, x);
                }
            }
            return;
        }
        ghost var oldUnd := set v | 0 <= v < n && !done[v];
        done := done[w := true];
        var i := 0;
        while i < |g[w]|
            invariant 0 <= i <= |g[w]|
            invariant |vis| == n
            invariant vis[s]
            invariant forall v :: 0 <= v < n && vis[v] ==> has_path(g, s, v)
            invariant forall v :: 0 <= v < n && done[v] ==> vis[v]
            invariant forall v, j :: 0 <= v < n && done[v] && v != w && 0 <= j < |g[v]| ==> vis[g[v][j]]
            invariant forall j :: 0 <= j < i ==> vis[g[w][j]]
        {
            var x := g[w][i];
            assert has_edge(g, w, x);
            EdgePath(g, w, x);
            PathTrans(g, s, w, x);
            vis := vis[x := true];
            i := i + 1;
