            vis := vis[x := true];
            i := i + 1;
        }
        assert w in oldUnd;
        assert w !in (set v | 0 <= v < n && !done[v]);
        assert (set v | 0 <= v < n && !done[v]) < oldUnd;
    }
}

lemma FinalProps(g: seq<seq<int>>, sccs: seq<seq<int>>, reps: seq<int>)
    requires |reps| == |sccs|
    requires forall k :: 0 <= k < |sccs| ==> 0 <= reps[k] < |g|
    requires forall k, x :: 0 <= k < |sccs| ==> (x in sccs[k] <==> (0 <= x < |g| && mutual(g, reps[k], x)))
    requires forall k, l :: 0 <= k < |sccs| && 0 <= l < |sccs| && k != l ==> !mutual(g, reps[k], reps[l])
    requires forall x :: 0 <= x < |g| ==> is_covered(sccs, x)
    ensures is_valid_scc_result(g, sccs)
{
    forall i, j, x | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures !(seq_contains(sccs[i], x) && seq_contains(sccs[j], x))
    {
        SeqContainsIff(sccs[i], x);
        SeqContainsIff(sccs[j], x);
        if x in sccs[i] && x in sccs[j] {
            MutualTrans(g, reps[i], x, reps[j]);
        }
    }
    assert are_disjoint(sccs);
    forall i | 0 <= i < |sccs| ensures is_strongly_connected(g, sccs[i]) {
        var r := reps[i];
        PathRefl(g, r);
        assert r in sccs[i];
        forall t | 0 <= t < |sccs[i]| ensures 0 <= sccs[i][t] < |g| {
            assert sccs[i][t] in sccs[i];
        }
        forall a, b | seq_contains(sccs[i], a) && seq_contains(sccs[i], b)
            ensures has_path(g, a, b) && has_path(g, b, a)
        {
            SeqContainsIff(sccs[i], a);
            SeqContainsIff(sccs[i], b);
            MutualTrans(g, a, r, b);
        }
    }
    forall i, j | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures scc_has_path(g, sccs, i, j) ==> !scc_has_path(g, sccs, j, i)
    {
        if scc_has_path(g, sccs, i, j) && scc_has_path(g, sccs, j, i) {
            var a, b :| seq_contains(sccs[i], a) && seq_contains(sccs[j], b) && has_path(g, a, b);
            var c, d :| seq_contains(sccs[j], c) && seq_contains(sccs[i], d) && has_path(g, c, d);
            SeqContainsIff(sccs[i], a);
            SeqContainsIff(sccs[j], b);
            SeqContainsIff(sccs[j], c);
            SeqContainsIff(sccs[i], d);
            PathTrans(g, reps[i], a, b);
            PathTrans(g, reps[i], b, reps[j]);
            PathTrans(g, reps[j], c, d);
            PathTrans(g, reps[j], d, reps[i]);
            assert mutual(g, reps[i], reps[j]);
            assert false;
        }
    }
}

method find_sccs(graph: Graph) returns (sccs: seq<seq<int>>)
    requires well_formed(graph)
    requires size_bounded(view(graph))
    ensures is_valid_scc_result(view(graph), sccs)
{
    var g := graph.adj;
    assert wf(g);
    var n := |g|;
    var R: seq<seq<bool>> := [];
    var u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant |R| == u
        invariant forall a :: 0 <= a < u ==> |R[a]| == n && (forall b :: 0 <= b < n ==> (R[a][b] <==> has_path(g, a, b)))
    {
        var r := Reach(g, u);
        R := R + [r];
        u := u + 1;
    }

    var marked := seq(n, i => false);
    sccs := [];
    ghost var reps: seq<int> := [];
    u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant |R| == n && forall a :: 0 <= a < n ==> |R[a]| == n && (forall b :: 0 <= b < n ==> (R[a][b] <==> has_path(g, a, b)))
        invariant |marked| == n
        invariant |reps| == |sccs|
        invariant forall k :: 0 <= k < |sccs| ==> 0 <= reps[k] < n
        invariant forall k, x :: 0 <= k < |sccs| ==> (x in sccs[k] <==> (0 <= x < n && mutual(g, reps[k], x)))
        invariant forall k, l :: 0 <= k < |sccs| && 0 <= l < |sccs| && k != l ==> !mutual(g, reps[k], reps[l])
        invariant forall k, x :: 0 <= k < |sccs| && x in sccs[k] ==> 0 <= x < n && marked[x]
        invariant forall x :: 0 <= x < n && marked[x] ==> is_covered(sccs, x)
        invariant forall x :: 0 <= x < u ==> marked[x]
    {
        if !marked[u] {
            PathRefl(g, u);
            forall k | 0 <= k < |sccs| ensures !mutual(g, reps[k], u) && !mutual(g, u, reps[k]) {
                if mutual(g, reps[k], u) || mutual(g, u, reps[k]) {
                    assert mutual(g, reps[k], u);
                    assert u in sccs[k];
                    assert marked[u];
                }
            }
            var comp: seq<int> := [];
            ghost var marked0 := marked;
            var v := 0;
            while v < n
                invariant 0 <= v <= n
                invariant |marked| == n
                invariant forall x :: x in comp <==> (0 <= x < v && mutual(g, u, x))
                invariant forall x :: 0 <= x < n ==> (marked[x] <==> (marked0[x] || (x < v && mutual(g, u, x))))
            {
                if R[u][v] && R[v][u] {
                    comp := comp + [v];
                    marked := marked[v := true];
                }
                v := v + 1;
            }
            var sccs2 := sccs + [comp];
            ghost var reps2 := reps + [u];
            forall k, l | 0 <= k < |sccs2| && 0 <= l < |sccs2| && k != l
                ensures !mutual(g, reps2[k], reps2[l])
            {
                if k < |sccs| && l < |sccs| {
                    assert reps2[k] == reps[k] && reps2[l] == reps[l];
                } else if k < |sccs| {
                    assert reps2[l] == u && reps2[k] == reps[k];
                } else {
                    assert reps2[k] == u && reps2[l] == reps[l];
                }
            }
            forall k, x | 0 <= k < |sccs2|
                ensures x in sccs2[k] <==> (0 <= x < n && mutual(g, reps2[k], x))
            {
                if k < |sccs| {
                    assert sccs2[k] == sccs[k] && reps2[k] == reps[k];
                } else {
                    assert sccs2[k] == comp && reps2[k] == u;
                }
            }
            forall k, x | 0 <= k < |sccs2| && x in sccs2[k]
                ensures 0 <= x < n && marked[x]
            {
                if k < |sccs| {
                    assert sccs2[k] == sccs[k];
                    assert marked0[x];
                } else {
                    assert sccs2[k] == comp;
                }
            }
            forall x | 0 <= x < n && marked[x] ensures is_covered(sccs2, x) {
                if marked0[x] {
                    CoveredExtend(sccs, comp, x);
                } else {
                    assert mutual(g, u, x);
                    assert x in comp;
                    SeqContainsIff(comp, x);
                    assert sccs2[|sccs|] == comp;
                    assert seq_contains(sccs2[|sccs|], x);
                }
            }
            sccs := sccs2;
            reps := reps2;
        }
        u := u + 1;
    }
    FinalProps(g, sccs, reps);
}
