        assert l < mid < r;
        var lt := build_aux(l, mid);
        var rt := build_aux(mid, r);
        res := Node(0, l, r, Some(lt), Some(rt));
        assert res.view() == lt.view() + rt.view();
        assert forall k :: k in res.view() <==> (k in lt.view() || k in rt.view());
