lemma midpoint_bounds(l: int, r: int)
    requires 0 <= l
    requires l + 1 < r
    ensures l < (l + r) / 2 < r
{
    assert 2 * (l + 1) <= l + r;
    assert l + r < 2 * r;
}

lemma leaf_is_segment_tree(l: int)
    requires 0 <= l
    ensures Node(0, l, l + 1, None, None).is_segment_tree()
{
    var n := Node(0, l, l + 1, None, None);

    assert n.view() == map[l := 0];

    forall k
        ensures k in n.view() <==> l <= k < l + 1
    {
        if k == l {
            assert k in n.view();
        } else {
            assert k !in n.view();
        }
    }

    forall k | k in n.view()
        ensures n.view()[k] <= n.val
    {
        assert k == l;
        assert n.view()[k] == 0;
    }

    assert n.is_segment_tree();
}

lemma join_is_segment_tree(
    a: Node,
    b: Node,
    l: int,
    m: int,
    r: int)
    requires 0 <= l < m < r
    requires m == (l + r) / 2
    requires a.low == l && a.high == m
    requires b.low == m && b.high == r
    requires a.is_segment_tree()
    requires b.is_segment_tree()
    ensures Node(
        if a.val > b.val then a.val else b.val,
        l, r, Some(a), Some(b)).is_segment_tree()
{
    var n := Node(
        if a.val > b.val then a.val else b.val,
        l, r, Some(a), Some(b));

    assert n.view() == a.view() + b.view();
    assert 0 <= a.val;
    assert 0 <= b.val;
    assert 0 <= n.val;

    forall k
        ensures k in n.view() <==> l <= k < r
    {
        assert k in a.view() <==> l <= k < m;
        assert k in b.view() <==> m <= k < r;
        assert k in n.view() <==>
            (k in a.view() || k in b.view());
    }

    forall k | k in n.view()
        ensures n.view()[k] <= n.val
    {
        assert k in a.view() || k in b.view();

        if k in b.view() {
            assert b.view()[k] <= b.val;
            assert n.view()[k] == b.view()[k];

            if a.val > b.val {
                assert b.val < n.val;
            } else {
                assert b.val == n.val;
            }
        } else {
            assert k in a.view();
            assert n.view()[k] == a.view()[k];
            assert a.view()[k] <= a.val;

            if a.val > b.val {
                assert a.val == n.val;
            } else {
                assert a.val <= n.val;
            }
        }
    }

    assert n.is_segment_tree();
}

