ghost predicate mutually_reachable(g: seq<seq<int>>, u: int, v: int)
{
    0 <= u < |g| &&
    0 <= v < |g| &&
    has_path(g, u, v) &&
    has_path(g, v, u)
}

lemma path_reflexive(g: seq<seq<int>>, u: int)
    ensures has_path(g, u, u)
{
    var p := [u];
    assert path_valid(g, p);
    assert |p| > 0 && p[0] == u && p[|p| - 1] == u;
}

lemma path_transitive(g: seq<seq<int>>, u: int, v: int, w: int)
    requires has_path(g, u, v)
    requires has_path(g, v, w)
    ensures has_path(g, u, w)
{
    var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == v &&
             path_valid(g, p);
    var q :| |q| > 0 &&
             q[0] == v &&
             q[|q| - 1] == w &&
             path_valid(g, q);

    var r := p + q[1..];

    assert |r| > 0;
    assert r[0] == u;
    assert r[|r| - 1] == w;

    assert path_valid(g, r) by {
        forall k: int | 0 <= k < |r| - 1
            ensures has_edge(g, r[k], r[k + 1])
        {
            if k < |p| - 1 {
                assert r[k] == p[k];
                assert r[k + 1] == p[k + 1];
            } else if k == |p| - 1 {
                assert |q| > 1;
                assert r[k] == p[|p| - 1];
                assert r[k] == q[0];
                assert r[k + 1] == q[1];
            } else {
                var j := k - |p| + 1;
                assert 0 <= j < |q| - 1;
                assert r[k] == q[j];
                assert r[k + 1] == q[j + 1];
            }
        }
    }
}

function search_path(
    g: seq<seq<int>>,
    u: int,
    v: int,
    seen: set<int>): bool
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires forall x: int :: x in seen ==> 0 <= x < |g|
    decreases |g| - |seen|
{
    if u == v then
        true
    else if u in seen then
        false
    else
        exists i: int ::
            0 <= i < |g[u]| &&
            0 <= g[u][i] < |g| &&
            search_path(g, g[u][i], v, seen + {u})
}

ghost function last_position(p: seq<int>, x: int): int
    requires |p| > 0
    requires seq_contains(p, x)
    decreases |p|
{
    if p[|p| - 1] == x then
        |p| - 1
    else
        last_position(p[..|p| - 1], x)
}

lemma last_position_properties(p: seq<int>, x: int)
    requires |p| > 0
    requires seq_contains(p, x)
    ensures 0 <= last_position(p, x) < |p|
    ensures p[last_position(p, x)] == x
    ensures forall j: int ::
        last_position(p, x) < j < |p| ==> p[j] != x
    decreases |p|
{
    if p[|p| - 1] != x {
        assert seq_contains(p[..|p| - 1], x) by {
            var i :| 0 <= i < |p| && p[i] == x;
            assert i < |p| - 1;
        }
        last_position_properties(p[..|p| - 1], x);
    }
}

lemma search_path_sound(
    g: seq<seq<int>>,
    u: int,
    v: int,
    seen: set<int>)
    requires 0 <= u < |g|
