                component_contains(g, rs[j], u);
                assert representative(g, u) == rs[i];
                assert representative(g, u) == rs[j];
                assert rs[i] == rs[j];

                if i < j {
                    assert rs[i] < rs[j];
                    assert false;
                } else {
                    assert j < i;
                    assert rs[j] < rs[i];
                    assert false;
