lemma search_path_complete_for_path(
    g: seq<seq<int>>,
    p: seq<int>,
    seen: set<int>)
    requires |p| > 0
    requires path_valid(g, p)
    requires forall k: int ::
        0 <= k < |p| ==> 0 <= p[k] < |g|
    requires forall k: int ::
        0 <= k < |p| ==> p[k] !in seen
    requires forall x: int ::
        x in seen ==> 0 <= x < |g|
    ensures search_path(g, p[0], p[|p| - 1], seen)
    decreases |g| - |seen|
