    var u := p[0];
    var v := p[|p| - 1];

    if u != v {
        assert seq_contains(p, u);
        last_position_properties(p, u);
        var l := last_position(p, u);

        assert l < |p| - 1;
        assert has_edge(g, p[l], p[l + 1]);

        var edgeIndex :|
            0 <= edgeIndex < |g[p[l]]| &&
            g[p[l]][edgeIndex] == p[l + 1];

        var q := p[l + 1..];
        assert |q| > 0;
        assert q[0] == p[l + 1];
        assert q[|q| - 1] == v;

        assert path_valid(g, q) by {
            forall k: int | 0 <= k < |q| - 1
                ensures has_edge(g, q[k], q[k + 1])
            {
                assert q[k] == p[l + 1 + k];
                assert q[k + 1] == p[l + 2 + k];
            }
        }

        assert forall k: int ::
            0 <= k < |q| ==> 0 <= q[k] < |g| by {
            forall k: int | 0 <= k < |q|
                ensures 0 <= q[k] < |g|
            {
                assert q[k] == p[l + 1 + k];
            }
        }

        assert forall k: int ::
            0 <= k < |q| ==> q[k] !in seen + {u} by {
            forall k: int | 0 <= k < |q|
                ensures q[k] !in seen + {u}
            {
                assert q[k] == p[l + 1 + k];
                assert l < l + 1 + k < |p|;
                assert p[l + 1 + k] != u;
                assert p[l + 1 + k] !in seen;
            }
        }

        assert forall x: int ::
            x in seen + {u} ==> 0 <= x < |g|;

        search_path_complete_for_path(g, q, seen + {u});

        assert 0 <= edgeIndex < |g[u]|;
        assert 0 <= g[u][edgeIndex] < |g|;
        assert g[u][edgeIndex] == q[0];
        assert search_path(
            g, g[u][edgeIndex], v, seen + {u});
    }
}

