lemma scc_construction_is_valid(graph: Graph)
    requires well_formed(graph)
    ensures is_valid_scc_result(
        view(graph),
        make_components(
            view(graph), representatives(view(graph))))
{
    var g := view(graph);
    var rs := representatives(g);
    var result := make_components(g, rs);

    make_components_length(g, rs);
    representatives_values(g);
    representatives_strict(g);

    assert are_disjoint(result) by {
        forall i: int, j: int, u: int |
            0 <= i < |result| &&
            0 <= j < |result| &&
            i != j
            ensures !(seq_contains(result[i], u) &&
                      seq_contains(result[j], u))
