    decreases |p|
{
    if p[|p| - 1] == x then
        |p| - 1
    else
        last_position(p[..|p| - 1], x)
}

lemma last_position_properties(p: seq<int>, x: int)
    requires |p| > 0
    requires seq_contains(p, x)
    ensures 0 <= last_position(p, x) < |p|
    ensures p[last_position(p, x)] == x
    ensures forall j: int ::
        last_position(p, x) < j < |p| ==> p[j] != x
    decreases |p|
{
    if p[|p| - 1] != x {
        assert seq_contains(p[..|p| - 1], x) by {
            var i :| 0 <= i < |p| && p[i] == x;
            assert i < |p| - 1;
        }
        last_position_properties(p[..|p| - 1], x);
    }
}

lemma search_path_sound(
    g: seq<seq<int>>,
    u: int,
    v: int,
    allowed: set<int>)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires allowed <= vertices(g)
    requires search_path(g, u, v, allowed)
    ensures has_path(g, u, v)
    decreases allowed
{
    if u == v {
        path_reflexive(g, u);
    } else {
        assert u in allowed;

        var i :| 0 <= i < |g[u]| &&
                  0 <= g[u][i] < |g| &&
                  search_path(
                      g, g[u][i], v, allowed - {u});

        var w := g[u][i];
        assert allowed - {u} <= vertices(g);
        search_path_sound(g, w, v, allowed - {u});

        assert has_edge(g, u, w);
        var p := [u, w];
        assert path_valid(g, p);
        assert has_path(g, u, w);
        path_transitive(g, u, w, v);
    }
}

lemma search_path_complete_for_path(
    g: seq<seq<int>>,
    p: seq<int>,
    allowed: set<int>)
    requires |p| > 0
    requires path_valid(g, p)
    requires allowed <= vertices(g)
    requires forall k: int ::
        0 <= k < |p| ==> p[k] in allowed
    ensures search_path(
        g, p[0], p[|p| - 1], allowed)
    decreases allowed
{
    var u := p[0];
    var v := p[|p| - 1];

    assert u in allowed;
    assert v in allowed;
    assert 0 <= u < |g|;
    assert 0 <= v < |g|;

    if u != v {
        assert seq_contains(p, u);
        last_position_properties(p, u);
        var l := last_position(p, u);

        assert l < |p| - 1;
        assert p[l] == u;
        assert has_edge(g, p[l], p[l + 1]);

        var edgeIndex :|
            0 <= edgeIndex < |g[p[l]]| &&
            g[p[l]][edgeIndex] == p[l + 1];

        var q := p[l + 1..];
        assert |q| > 0;
        assert q[0] == p[l + 1];
        assert q[|q| - 1] == v;

        assert path_valid(g, q) by {
            forall k: int | 0 <= k < |q| - 1
                ensures has_edge(g, q[k], q[k + 1])
            {
                assert q[k] == p[l + 1 + k];
                assert q[k + 1] == p[l + 2 + k];
            }
        }

        assert allowed - {u} <= vertices(g);

        assert forall k: int ::
            0 <= k < |q| ==> q[k] in allowed - {u} by {
            forall k: int | 0 <= k < |q|
                ensures q[k] in allowed - {u}
            {
                assert q[k] == p[l + 1 + k];
                assert l < l + 1 + k < |p|;
                assert p[l + 1 + k] != u;
                assert p[l + 1 + k] in allowed;
            }
        }

        search_path_complete_for_path(g, q, allowed - {u});

        assert 0 <= edgeIndex < |g[u]|;
        assert 0 <= g[u][edgeIndex] < |g|;
        assert g[u][edgeIndex] == q[0];
        assert search_path(
            g, g[u][edgeIndex], v, allowed - {u});
    }
}

lemma path_nodes_in_range(
    g: seq<seq<int>>,
    p: seq<int>,
    u: int,
    v: int)
    requires |p| > 0
    requires p[0] == u
    requires p[|p| - 1] == v
    requires path_valid(g, p)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    ensures forall k: int ::
        0 <= k < |p| ==> 0 <= p[k] < |g|
{
    forall k: int | 0 <= k < |p|
        ensures 0 <= p[k] < |g|
    {
        if k == |p| - 1 {
            assert p[k] == v;
        } else {
            assert has_edge(g, p[k], p[k + 1]);
        }
    }
}

lemma search_path_complete(g: seq<seq<int>>, u: int, v: int)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires has_path(g, u, v)
    ensures search_path(g, u, v, vertices(g))
{
    var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == v &&
             path_valid(g, p);

    path_nodes_in_range(g, p, u, v);

    assert forall k: int ::
        0 <= k < |p| ==> p[k] in vertices(g) by {
        forall k: int | 0 <= k < |p|
            ensures p[k] in vertices(g)
        {
            assert 0 <= p[k] < |g|;
        }
    }

    assert vertices(g) <= vertices(g);
    search_path_complete_for_path(g, p, vertices(g));
}

function computable_mutually_reachable(
    g: seq<seq<int>>, u: int, v: int): bool
    requires 0 <= u < |g|
    requires 0 <= v < |g|
{
    search_path(g, u, v, vertices(g)) &&
    search_path(g, v, u, vertices(g))
}

lemma computable_mutually_reachable_equivalence(
    g: seq<seq<int>>, u: int, v: int)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    ensures computable_mutually_reachable(g, u, v)
        <==> mutually_reachable(g, u, v)
{
    if computable_mutually_reachable(g, u, v) {
        search_path_sound(g, u, v, vertices(g));
        search_path_sound(g, v, u, vertices(g));
    }

    if mutually_reachable(g, u, v) {
        search_path_complete(g, u, v);
        search_path_complete(g, v, u);
    }
}

lemma mutually_reachable_reflexive(
    g: seq<seq<int>>, u: int)
    requires 0 <= u < |g|
    ensures mutually_reachable(g, u, u)
{
    path_reflexive(g, u);
}

lemma mutually_reachable_symmetric(
    g: seq<seq<int>>, u: int, v: int)
    requires mutually_reachable(g, u, v)
    ensures mutually_reachable(g, v, u)
{
}

lemma mutually_reachable_transitive(
    g: seq<seq<int>>, u: int, v: int, w: int)
    requires mutually_reachable(g, u, v)
    requires mutually_reachable(g, v, w)
    ensures mutually_reachable(g, u, w)
{
    path_transitive(g, u, v, w);
    path_transitive(g, w, v, u);
}

function representative_from(
    g: seq<seq<int>>, u: int, k: int): int
    requires 0 <= u < |g|
    requires 0 <= k <= u
    ensures k <= representative_from(g, u, k) <= u
    decreases u - k
{
    if k == u then
        u
    else if computable_mutually_reachable(g, k, u) then
        k
    else
        representative_from(g, u, k + 1)
}

function representative(g: seq<seq<int>>, u: int): int
    requires 0 <= u < |g|
    ensures 0 <= representative(g, u) <= u
    ensures representative(g, u) < |g|
{
    representative_from(g, u, 0)
}

lemma representative_from_properties(
    g: seq<seq<int>>, u: int, k: int)
    requires 0 <= u < |g|
    requires 0 <= k <= u
    ensures k <= representative_from(g, u, k) <= u
    ensures mutually_reachable(
        g, representative_from(g, u, k), u)
    ensures forall x: int ::
        k <= x < representative_from(g, u, k) ==>
        !mutually_reachable(g, x, u)
    decreases u - k
{
    if k == u {
        mutually_reachable_reflexive(g, u);
    } else {
        computable_mutually_reachable_equivalence(g, k, u);
        if !computable_mutually_reachable(g, k, u) {
            representative_from_properties(g, u, k + 1);
        }
    }
}

lemma representative_properties(g: seq<seq<int>>, u: int)
    requires 0 <= u < |g|
    ensures 0 <= representative(g, u) <= u
    ensures representative(g, u) < |g|
    ensures mutually_reachable(g, representative(g, u), u)
    ensures forall x: int ::
        0 <= x < representative(g, u) ==>
        !mutually_reachable(g, x, u)
{
    representative_from_properties(g, u, 0);
}

lemma equal_representatives(
    g: seq<seq<int>>, u: int, v: int)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires mutually_reachable(g, u, v)
    ensures representative(g, u) == representative(g, v)
{
    representative_properties(g, u);
    representative_properties(g, v);

    var ru := representative(g, u);
    var rv := representative(g, v);

    if ru < rv {
        mutually_reachable_transitive(g, ru, u, v);
        assert !mutually_reachable(g, ru, v);
        assert false;
    } else if rv < ru {
        mutually_reachable_symmetric(g, u, v);
        mutually_reachable_transitive(g, rv, v, u);
        assert !mutually_reachable(g, rv, u);
        assert false;
    }
}

lemma representative_idempotent(
    g: seq<seq<int>>, u: int)
    requires 0 <= u < |g|
    ensures representative(g, representative(g, u))
         == representative(g, u)
{
    representative_properties(g, u);
    var r := representative(g, u);
    assert 0 <= r < |g|;
    equal_representatives(g, r, u);
}

lemma same_representative_reachable(
    g: seq<seq<int>>, u: int, v: int)
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    requires representative(g, u) == representative(g, v)
    ensures mutually_reachable(g, u, v)
{
    representative_properties(g, u);
    representative_properties(g, v);

    var r := representative(g, u);
    mutually_reachable_symmetric(g, r, u);
    mutually_reachable_transitive(g, u, r, v);
}

lemma seq_contains_cons(
    x: int, s: seq<int>, u: int)
    ensures seq_contains([x] + s, u)
        <==> x == u || seq_contains(s, u)
{
    if seq_contains([x] + s, u) {
        var i :| 0 <= i < |[x] + s| &&
                  ([x] + s)[i] == u;
        if i == 0 {
            assert x == u;
        } else {
            assert 0 <= i - 1 < |s|;
            assert ([x] + s)[i] == s[i - 1];
            assert s[i - 1] == u;
            assert seq_contains(s, u);
        }
    }

    if x == u || seq_contains(s, u) {
        if x == u {
            assert 0 <= 0 < |[x] + s|;
            assert ([x] + s)[0] == u;
            assert seq_contains([x] + s, u);
        } else {
            var j :| 0 <= j < |s| && s[j] == u;
            assert 0 <= j + 1 < |[x] + s|;
            assert ([x] + s)[j + 1] == s[j];
            assert ([x] + s)[j + 1] == u;
            assert seq_contains([x] + s, u);
        }
    }
}

function component_from(
    g: seq<seq<int>>, r: int, k: int): seq<int>
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then
        []
    else if representative(g, k) == r then
        [k] + component_from(g, r, k + 1)
    else
        component_from(g, r, k + 1)
}

function component(
    g: seq<seq<int>>, r: int): seq<int>
{
    component_from(g, r, 0)
}

lemma component_from_contains(
    g: seq<seq<int>>, r: int, k: int, u: int)
    requires 0 <= k <= |g|
    ensures seq_contains(component_from(g, r, k), u)
        <==>
        k <= u < |g| && representative(g, u) == r
    decreases |g| - k
{
    if k == |g| {
        assert component_from(g, r, k) == [];
        assert !seq_contains([], u);
        assert !(k <= u < |g|);
    } else {
        var tail := component_from(g, r, k + 1);
        component_from_contains(g, r, k + 1, u);

        if representative(g, k) == r {
            assert component_from(g, r, k) == [k] + tail;
            seq_contains_cons(k, tail, u);

            if seq_contains(component_from(g, r, k), u) {
                assert u == k || seq_contains(tail, u);
                if u == k {
                    assert k <= u < |g|;
                    assert representative(g, u) == r;
                } else {
                    assert k + 1 <= u < |g|;
                    assert representative(g, u) == r;
                }
            }

            if k <= u < |g| &&
               representative(g, u) == r
            {
                if u == k {
                    assert seq_contains([k] + tail, u);
                } else {
                    assert k + 1 <= u < |g|;
                    assert seq_contains(tail, u);
                    assert seq_contains([k] + tail, u);
                }
            }
        } else {
            assert component_from(g, r, k) == tail;

            if seq_contains(component_from(g, r, k), u) {
                assert k + 1 <= u < |g|;
                assert representative(g, u) == r;
            }

            if k <= u < |g| &&
               representative(g, u) == r
            {
                if u == k {
                    assert representative(g, k) == r;
                    assert false;
                }
                assert k + 1 <= u < |g|;
                assert seq_contains(tail, u);
            }
        }
    }
}

lemma component_contains(
    g: seq<seq<int>>, r: int, u: int)
    ensures seq_contains(component(g, r), u)
        <==>
        0 <= u < |g| && representative(g, u) == r
{
    component_from_contains(g, r, 0, u);
}

function representatives_from(
    g: seq<seq<int>>, k: int): seq<int>
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then
        []
    else if representative(g, k) == k then
        [k] + representatives_from(g, k + 1)
    else
        representatives_from(g, k + 1)
}

function representatives(
    g: seq<seq<int>>): seq<int>
{
    representatives_from(g, 0)
}

lemma representatives_from_contains(
    g: seq<seq<int>>, k: int, r: int)
    requires 0 <= k <= |g|
    ensures seq_contains(representatives_from(g, k), r)
        <==>
        k <= r < |g| && representative(g, r) == r
    decreases |g| - k
{
    if k == |g| {
        assert representatives_from(g, k) == [];
        assert !seq_contains([], r);
        assert !(k <= r < |g|);
    } else {
        var tail := representatives_from(g, k + 1);
        representatives_from_contains(g, k + 1, r);

        if representative(g, k) == k {
            assert representatives_from(g, k) == [k] + tail;
            seq_contains_cons(k, tail, r);

            if seq_contains(representatives_from(g, k), r) {
                assert r == k || seq_contains(tail, r);
                if r == k {
                    assert k <= r < |g|;
                    assert representative(g, r) == r;
                } else {
                    assert k + 1 <= r < |g|;
                    assert representative(g, r) == r;
                }
            }

            if k <= r < |g| &&
               representative(g, r) == r
            {
                if r == k {
                    assert seq_contains([k] + tail, r);
                } else {
                    assert k + 1 <= r < |g|;
                    assert seq_contains(tail, r);
                    assert seq_contains([k] + tail, r);
                }
            }
        } else {
            assert representatives_from(g, k) == tail;

            if seq_contains(representatives_from(g, k), r) {
                assert k + 1 <= r < |g|;
                assert representative(g, r) == r;
            }

            if k <= r < |g| &&
               representative(g, r) == r
            {
                if r == k {
                    assert representative(g, k) == k;
                    assert false;
                }
                assert k + 1 <= r < |g|;
                assert seq_contains(tail, r);
            }
        }
    }
}

lemma representatives_contains(
    g: seq<seq<int>>, r: int)
    ensures seq_contains(representatives(g), r)
        <==>
        0 <= r < |g| && representative(g, r) == r
{
    representatives_from_contains(g, 0, r);
}

lemma representatives_from_values(
    g: seq<seq<int>>, k: int)
    requires 0 <= k <= |g|
    ensures forall i: int ::
        0 <= i < |representatives_from(g, k)| ==>
        k <= representatives_from(g, k)[i] < |g| &&
        representative(
            g, representatives_from(g, k)[i])
          == representatives_from(g, k)[i]
    decreases |g| - k
{
    if k < |g| {
        representatives_from_values(g, k + 1);
    }
}

lemma representatives_from_strict(
    g: seq<seq<int>>, k: int)
    requires 0 <= k <= |g|
    ensures forall i: int, j: int ::
        0 <= i < j < |representatives_from(g, k)| ==>
        representatives_from(g, k)[i]
          < representatives_from(g, k)[j]
    decreases |g| - k
{
    if k < |g| {
        representatives_from_values(g, k + 1);
        representatives_from_strict(g, k + 1);
    }
}

lemma representatives_values(g: seq<seq<int>>)
    ensures forall i: int ::
        0 <= i < |representatives(g)| ==>
        0 <= representatives(g)[i] < |g| &&
        representative(g, representatives(g)[i])
          == representatives(g)[i]
{
    representatives_from_values(g, 0);
}

lemma representatives_strict(g: seq<seq<int>>)
    ensures forall i: int, j: int ::
        0 <= i < j < |representatives(g)| ==>
        representatives(g)[i] < representatives(g)[j]
{
    representatives_from_strict(g, 0);
}

function make_components(
    g: seq<seq<int>>, rs: seq<int>): seq<seq<int>>
    ensures |make_components(g, rs)| == |rs|
    decreases |rs|
{
    if |rs| == 0 then
        []
    else
        [component(g, rs[0])] +
        make_components(g, rs[1..])
}

lemma make_components_at(
    g: seq<seq<int>>, rs: seq<int>, i: int)
    requires 0 <= i < |rs|
    ensures make_components(g, rs)[i]
        == component(g, rs[i])
    decreases |rs|
{
    if i > 0 {
        make_components_at(g, rs[1..], i - 1);
    }
}

lemma scc_construction_is_valid(graph: Graph)
    requires well_formed(graph)
    ensures is_valid_scc_result(
        view(graph),
        make_components(
            view(graph), representatives(view(graph))))
{
    var g := view(graph);
    var rs := representatives(g);
    var result := make_components(g, rs);

    representatives_values(g);
    representatives_strict(g);

    assert are_disjoint(result) by {
        forall i: int, j: int, u: int |
            0 <= i < |result| &&
            0 <= j < |result| &&
            i != j
            ensures !(seq_contains(result[i], u) &&
                      seq_contains(result[j], u))
        {
            make_components_at(g, rs, i);
            make_components_at(g, rs, j);

            if seq_contains(result[i], u) &&
               seq_contains(result[j], u)
            {
                component_contains(g, rs[i], u);
                component_contains(g, rs[j], u);
                assert representative(g, u) == rs[i];
                assert representative(g, u) == rs[j];
                assert rs[i] == rs[j];

                if i < j {
                    assert rs[i] < rs[j];
                    assert false;
                } else {
                    assert j < i;
                    assert rs[j] < rs[i];
                    assert false;
                }
            }
        }
    }

    assert forall u: int ::
        0 <= u < |g| ==> is_covered(result, u) by {
        forall u: int | 0 <= u < |g|
            ensures is_covered(result, u)
        {
            representative_properties(g, u);
            representative_idempotent(g, u);

            var r := representative(g, u);
            representatives_contains(g, r);
            assert seq_contains(rs, r);

            var i :| 0 <= i < |rs| && rs[i] == r;
            make_components_at(g, rs, i);
            component_contains(g, r, u);

            assert seq_contains(result[i], u);
        }
    }

    assert is_partition(g, result);

    assert forall i: int ::
        0 <= i < |result| ==>
        is_strongly_connected(g, result[i]) by {
        forall i: int | 0 <= i < |result|
            ensures is_strongly_connected(g, result[i])
        {
            make_components_at(g, rs, i);
            var r := rs[i];

            assert 0 <= r < |g|;
            assert representative(g, r) == r;
            component_contains(g, r, r);
            assert seq_contains(result[i], r);
            assert |result[i]| > 0;

            assert forall k: int ::
                0 <= k < |result[i]| ==>
                0 <= result[i][k] < |g| by {
                forall k: int | 0 <= k < |result[i]|
                    ensures 0 <= result[i][k] < |g|
                {
                    assert seq_contains(
                        result[i], result[i][k]);
                    component_contains(
                        g, r, result[i][k]);
                }
            }

            assert forall u: int, v: int ::
                seq_contains(result[i], u) &&
                seq_contains(result[i], v) ==>
                has_path(g, u, v) &&
                has_path(g, v, u) by {
                forall u: int, v: int |
                    seq_contains(result[i], u) &&
                    seq_contains(result[i], v)
                    ensures has_path(g, u, v) &&
                            has_path(g, v, u)
                {
                    component_contains(g, r, u);
                    component_contains(g, r, v);
                    assert representative(g, u) == r;
                    assert representative(g, v) == r;
                    same_representative_reachable(g, u, v);
                }
            }
        }
    }

    assert is_maximal_scc_structure(g, result) by {
        forall i: int, j: int |
            0 <= i < |result| &&
            0 <= j < |result| &&
            i != j
            ensures scc_has_path(g, result, i, j) ==>
                    !scc_has_path(g, result, j, i)
        {
            make_components_at(g, rs, i);
            make_components_at(g, rs, j);

            if scc_has_path(g, result, i, j) &&
               scc_has_path(g, result, j, i)
            {
                var u: int, v: int :|
                    seq_contains(result[i], u) &&
                    seq_contains(result[j], v) &&
                    has_path(g, u, v);

                var x: int, y: int :|
                    seq_contains(result[j], x) &&
                    seq_contains(result[i], y) &&
                    has_path(g, x, y);

                component_contains(g, rs[i], u);
                component_contains(g, rs[j], v);
                component_contains(g, rs[j], x);
                component_contains(g, rs[i], y);

                assert representative(g, u) == rs[i];
                assert representative(g, y) == rs[i];
                assert representative(g, v) == rs[j];
                assert representative(g, x) == rs[j];

                same_representative_reachable(g, v, x);
                same_representative_reachable(g, y, u);

                path_transitive(g, v, x, y);
                path_transitive(g, v, y, u);

                assert 0 <= u < |g|;
                assert 0 <= v < |g|;
                assert has_path(g, u, v);
                assert has_path(g, v, u);
