lemma MapUpdateLeft(
    a: map<int, int>,
    b: map<int, int>,
    key: int,
    value: int)
    requires key !in b
    ensures a[key := value] + b == (a + b)[key := value]
{
    var lhs := a[key := value] + b;
    var rhs := (a + b)[key := value];

    forall x
        ensures x in lhs <==> x in rhs
    {
        assert x in a[key := value] <==> x == key || x in a;
        assert x in a + b <==> x in a || x in b;
        assert x in lhs <==> x in a[key := value] || x in b;
        assert x in rhs <==> x == key || x in a + b;
    }

    forall x | x in lhs
        ensures lhs[x] == rhs[x]
    {
        assert x in rhs;

        if x == key {
            assert x !in b;
            assert lhs[x] == value;
            assert rhs[x] == value;
        } else if x in b {
            assert lhs[x] == b[x];
            assert (a + b)[x] == b[x];
            assert rhs[x] == (a + b)[x];
        } else {
            assert x in a;
            assert lhs[x] == a[x];
            assert (a + b)[x] == a[x];
            assert rhs[x] == (a + b)[x];
        }
    }

    assert lhs == rhs;
}

