lemma LeafIsSegmentTree(low: int, value: int)
    requires 0 <= low
    requires 0 <= value
    ensures Node(value, low, low + 1, None, None).is_segment_tree()
{
    var n := Node(value, low, low + 1, None, None);

    assert n.view() == map[low := value];

    forall k
        ensures k in n.view() <==> n.low <= k < n.high
    {
        assert k in n.view() <==> k == low;

        if n.low <= k < n.high {
            assert k == low;
        }
    }

    forall k | k in n.view()
        ensures n.view()[k] <= n.val
