    requires v >= 0
    requires node.is_segment_tree()
    requires node.low <= idx < node.high
    ensures
        && res.is_segment_tree()
        && res.low == node.low
        && res.high == node.high
        && res.view() == node.view()[idx := v]
    decreases node
{
    SegmentTreeShape(node);

    if node.left.None? {
        assert node.right.None?;
        assert node.high == node.low + 1;
        assert idx == node.low;

        LeafIsSegmentTree(node.low, v);
        res := Node(v, node.low, node.high, None, None);

        assert res.view() == map[node.low := v];
        assert node.view() == map[node.low := node.val];
        assert res.view() == node.view()[idx := v];
    } else {
        assert node.left.Some?;
        assert node.right.Some?;

        var l := node.left.value;
        var r := node.right.value;
        var mid := (node.low + node.high) / 2;

        assert l.low == node.low;
        assert l.high == mid;
        assert r.low == mid;
        assert r.high == node.high;
        assert l.is_segment_tree();
        assert r.is_segment_tree();
        assert node.view() == l.view() + r.view();

        if idx < mid {
            assert l.low <= idx < l.high;
            assert idx < r.low;
            assert idx !in r.view();

            var updatedLeft := update(l, idx, v);
            var maximum :=
                if updatedLeft.val > r.val
                then updatedLeft.val
                else r.val;

            JoinIsSegmentTree(updatedLeft, r);
            res := Node(
                maximum,
                node.low,
                node.high,
                Some(updatedLeft),
                Some(r));

            assert updatedLeft.low == l.low;
            assert updatedLeft.high == l.high;
            assert updatedLeft.view() == l.view()[idx := v];
            assert res.view() == updatedLeft.view() + r.view();

            MapUpdateLeft(l.view(), r.view(), idx, v);

            calc {
                res.view();
                == updatedLeft.view() + r.view();
                == l.view()[idx := v] + r.view();
                == (l.view() + r.view())[idx := v];
                == node.view()[idx := v];
            }
        } else {
            assert r.low <= idx < r.high;

            var updatedRight := update(r, idx, v);
            var maximum :=
                if l.val > updatedRight.val
                then l.val
                else updatedRight.val;

            JoinIsSegmentTree(l, updatedRight);
            res := Node(
                maximum,
                node.low,
                node.high,
                Some(l),
                Some(updatedRight));

            assert updatedRight.low == r.low;
            assert updatedRight.high == r.high;
            assert updatedRight.view() == r.view()[idx := v];
            assert res.view() == l.view() + updatedRight.view();

            MapUpdateRight(l.view(), r.view(), idx, v);

            calc {
                res.view();
                == l.view() + updatedRight.view();
                == l.view() + r.view()[idx := v];
                == (l.view() + r.view())[idx := v];
                == node.view()[idx := v];
            }
        }
    }
