    requires r.is_segment_tree()
    requires l.high == r.low
    requires l.high == (l.low + r.high) / 2
    ensures Node(
        if l.val > r.val then l.val else r.val,
        l.low,
        r.high,
        Some(l),
        Some(r)).is_segment_tree()
{
    var maximum := if l.val > r.val then l.val else r.val;
    var n := Node(maximum, l.low, r.high, Some(l), Some(r));

    SegmentTreeShape(l);
    SegmentTreeShape(r);

    assert n.low == l.low;
    assert n.high == r.high;
    assert (n.low + n.high) / 2 == l.high;
    assert r.low == l.high;
    assert 0 <= n.low < n.high;
    assert 0 <= n.val;
    assert n.view() == l.view() + r.view();

    forall k
        ensures k in n.view() <==> n.low <= k < n.high
    {
        if k in n.view() {
            assert k in l.view() || k in r.view();

            if k in r.view() {
                assert r.low <= k < r.high;
            } else {
                assert k in l.view();
                assert l.low <= k < l.high;
            }
        } else if n.low <= k < n.high {
            if k < l.high {
                assert l.low <= k < l.high;
                assert k in l.view();
                assert k in n.view();
            } else {
                assert r.low <= k < r.high;
                assert k in r.view();
                assert k in n.view();
            }
        }
    }

    forall k | k in n.view()
        ensures n.view()[k] <= n.val
    {
        if k in r.view() {
            assert n.view()[k] == r.view()[k];
            assert r.view()[k] <= r.val;

            if l.val > r.val {
                assert r.val <= l.val;
                assert n.val == l.val;
            } else {
                assert n.val == r.val;
            }
        } else {
            assert k in l.view();
            assert n.view()[k] == l.view()[k];
            assert l.view()[k] <= l.val;

            if l.val > r.val {
                assert n.val == l.val;
            } else {
                assert l.val <= r.val;
                assert n.val == r.val;
            }
        }
    }

    assert n.is_segment_tree();
}

method update(node: Node, idx: int, v: int) returns (res: Node)
    requires v >= 0
    requires node.is_segment_tree()
    requires node.low <= idx < node.high
    ensures
        && res.is_segment_tree()
        && res.low == node.low
        && res.high == node.high
        && res.view() == node.view()[idx := v]
    decreases node
{
    SegmentTreeShape(node);

    if node.left.None? {
        assert node.right.None?;
        assert node.high == node.low + 1;
        assert idx == node.low;

        LeafIsSegmentTree(node.low, v);
        res := Node(v, node.low, node.high, None, None);

        assert res.view() == map[node.low := v];
        assert node.view() == map[node.low := node.val];
        assert res.view() == node.view()[idx := v];
    } else {
        assert node.left.Some?;
        assert node.right.Some?;

        var l := node.left.value;
        var r := node.right.value;
        var mid := (node.low + node.high) / 2;

        assert l.low == node.low;
        assert l.high == mid;
        assert r.low == mid;
        assert r.high == node.high;
        assert l.is_segment_tree();
        assert r.is_segment_tree();
        assert node.view() == l.view() + r.view();

        if idx < mid {
            assert l.low <= idx < l.high;
            assert idx < r.low;
            assert idx !in r.view();

            var updatedLeft := update(l, idx, v);
            var maximum :=
                if updatedLeft.val > r.val
                then updatedLeft.val
                else r.val;

            JoinIsSegmentTree(updatedLeft, r);
            res := Node(
                maximum,
                node.low,
                node.high,
                Some(updatedLeft),
                Some(r));

            assert updatedLeft.low == l.low;
            assert updatedLeft.high == l.high;
            assert updatedLeft.view() == l.view()[idx := v];
            assert res.view() == updatedLeft.view() + r.view();

            MapUpdateLeft(l.view(), r.view(), idx, v);

            calc {
                res.view();
                == updatedLeft.view() + r.view();
                == l.view()[idx := v] + r.view();
                == (l.view() + r.view())[idx := v];
                == node.view()[idx := v];
            }
        } else {
            assert r.low <= idx < r.high;

            var updatedRight := update(r, idx, v);
            var maximum :=
                if l.val > updatedRight.val
                then l.val
                else updatedRight.val;

            JoinIsSegmentTree(l, updatedRight);
            res := Node(
                maximum,
                node.low,
                node.high,
                Some(l),
                Some(updatedRight));

            assert updatedRight.low == r.low;
            assert updatedRight.high == r.high;
            assert updatedRight.view() == r.view()[idx := v];
            assert res.view() == l.view() + updatedRight.view();

            MapUpdateRight(l.view(), r.view(), idx, v);

            calc {
                res.view();
                == l.view() + updatedRight.view();
                == l.view() + r.view()[idx := v];
                == (l.view() + r.view())[idx := v];
                == node.view()[idx := v];
            }
        }
    }
}
