lemma SumUnfold(cuts: seq<int>)
  requires |cuts| > 0
  ensures sum_lengths(cuts) == cuts[0] + sum_lengths(cuts[1..])
{
  assert sum_lengths(cuts) == (if |cuts| == 0 then 0 else cuts[0] + sum_lengths(cuts[1..]));
}

lemma RevenueUnfold(cuts: seq<int>, prices: seq<int>)
  requires |cuts| > 0
  ensures calculate_revenue(cuts, prices) ==
          get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices)
{
  assert calculate_revenue(cuts, prices) ==
    (if |cuts| == 0 then 0
     else get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices));
}

lemma GetPriceEq(prices: seq<int>, idx: int)
  requires 0 <= idx < |prices|
  ensures get_price(prices, idx) == prices[idx]
{
  assert get_price(prices, idx) == (if 0 <= idx < |prices| then prices[idx] else 0);
}

lemma ConsSlice<T>(x: T, xs: seq<T>)
  ensures ([x] + xs)[0] == x
  ensures ([x] + xs)[1..] == xs
  ensures |[x] + xs| == |xs| + 1
{
  var s := [x] + xs;
  assert s[0] == x;
  assert |s| == |xs| + 1;
  forall idx | 0 <= idx < |xs|
    ensures s[1..][idx] == xs[idx]
  {
    assert s[idx + 1] == xs[idx];
    assert s[1..][idx] == s[idx + 1];
  }
  assert |s[1..]| == |xs|;
  assert forall idx :: 0 <= idx < |xs| ==> s[1..][idx] == xs[idx];
  assert s[1..] == xs;
}

lemma SumCons(x: int, xs: seq<int>)
  ensures sum_lengths([x] + xs) == x + sum_lengths(xs)
{
  var s := [x] + xs;
  ConsSlice(x, xs);
  assert s[0] == x;
  assert s[1..] == xs;
  SumUnfold(s);
}

lemma RevenueCons(x: int, xs: seq<int>, prices: seq<int>)
  ensures calculate_revenue([x] + xs, prices) ==
          get_price(prices, x - 1) + calculate_revenue(xs, prices)
{
  var s := [x] + xs;
  ConsSlice(x, xs);
  assert s[0] == x;
  assert s[1..] == xs;
  RevenueUnfold(s, prices);
  assert s[0] - 1 == x - 1;
}

lemma SumLengthsNonnegative(cuts: seq<int>)
  requires forall idx :: 0 <= idx < |cuts| ==> 0 <= cuts[idx]
  ensures sum_lengths(cuts) >= 0
  decreases |cuts|
{
  if |cuts| == 0 {
    assert sum_lengths(cuts) == 0;
  } else {
    forall idx | 0 <= idx < |cuts[1..]|
      ensures 0 <= cuts[1..][idx]
    {
      assert cuts[1..][idx] == cuts[idx + 1];
      assert 0 <= idx + 1 < |cuts|;
      assert 0 <= cuts[idx + 1];
      assert 0 <= cuts[1..][idx];
    }
    SumLengthsNonnegative(cuts[1..]);
    SumUnfold(cuts);
    assert sum_lengths(cuts) == cuts[0] + sum_lengths(cuts[1..]);
    assert 0 <= cuts[0];
    assert 0 <= sum_lengths(cuts[1..]);
  }
}

lemma NoPositiveRodSumsToZero(cuts: seq<int>)
  requires forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0
  requires sum_lengths(cuts) == 0
  ensures |cuts| == 0
  decreases |cuts|
{
  if |cuts| > 0 {
    forall idx | 0 <= idx < |cuts[1..]|
      ensures 0 <= cuts[1..][idx]
    {
      assert cuts[1..][idx] == cuts[idx + 1];
      assert 0 <= idx + 1 < |cuts|;
      assert cuts[idx + 1] > 0;
      assert 0 <= cuts[1..][idx];
    }
    SumLengthsNonnegative(cuts[1..]);
    SumUnfold(cuts);
    assert sum_lengths(cuts) == cuts[0] + sum_lengths(cuts[1..]);
    assert cuts[0] > 0;
    assert cuts[0] >= 1;
    assert sum_lengths(cuts[1..]) >= 0;
    assert sum_lengths(cuts) >= 1;
    assert false;
  }
}

lemma NonEmpty(cuts: seq<int>, total: int, prices: seq<int>)
  requires is_valid_strategy(cuts, total, prices)
  requires total > 0
  ensures |cuts| >= 1
{
  if |cuts| == 0 {
    assert sum_lengths(cuts) == 0;
    assert sum_lengths(cuts) == total;
    assert false;
  }
}

lemma SplitStrategy(cuts: seq<int>, total: int, prices: seq<int>)
  requires |cuts| >= 1
  requires is_valid_strategy(cuts, total, prices)
  requires total > 0
  ensures 1 <= cuts[0] <= total
  ensures 0 <= cuts[0] - 1 < |prices|
  ensures is_valid_strategy(cuts[1..], total - cuts[0], prices)
  ensures calculate_revenue(cuts, prices) ==
          get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices)
{
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] - 1 < |prices|;
  assert sum_lengths(cuts) == total;

  var first := cuts[0];
  var rest := cuts[1..];
  SumUnfold(cuts);
  assert sum_lengths(cuts) == first + sum_lengths(rest);

  forall idx | 0 <= idx < |rest|
    ensures 0 <= rest[idx]
  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
    assert 0 <= rest[idx];
  }
  SumLengthsNonnegative(rest);
  assert sum_lengths(rest) >= 0;
  assert first + sum_lengths(rest) == total;
  assert sum_lengths(rest) == total - first;
  assert first <= total;
  assert first > 0;
  assert first >= 1;
  assert 0 <= first - 1;
  assert first - 1 < |prices|;

  RevenueUnfold(cuts, prices);

  forall idx | 0 <= idx < |rest|
    ensures rest[idx] > 0 && rest[idx] - 1 < |prices|
  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
    assert cuts[idx + 1] - 1 < |prices|;
  }
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] > 0;
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] - 1 < |prices|;
  assert is_valid_strategy(rest, total - first, prices);
}

lemma CombineStrategy(j: int, rest: seq<int>, total: int, prices: seq<int>)
  requires j >= 1
  requires 0 <= j - 1 < |prices|
  requires is_valid_strategy(rest, total - j, prices)
  ensures is_valid_strategy([j] + rest, total, prices)
  ensures calculate_revenue([j] + rest, prices) ==
          get_price(prices, j - 1) + calculate_revenue(rest, prices)
{
  var cuts := [j] + rest;
  SumCons(j, rest);
  RevenueCons(j, rest, prices);
  assert sum_lengths(rest) == total - j;
  assert sum_lengths(cuts) == j + sum_lengths(rest);
  assert sum_lengths(cuts) == j + (total - j);
  assert sum_lengths(cuts) == total;

  assert forall t :: 0 <= t < |rest| ==> rest[t] > 0;
  assert forall t :: 0 <= t < |rest| ==> rest[t] - 1 < |prices|;

  forall idx | 0 <= idx < |cuts|
    ensures cuts[idx] > 0 && cuts[idx] - 1 < |prices|
  {
    if idx == 0 {
      assert cuts[0] == j;
      assert j > 0;
      assert j - 1 < |prices|;
    } else {
      assert idx >= 1;
      assert 0 <= idx - 1 < |rest|;
      assert cuts[idx] == rest[idx - 1];
      assert rest[idx - 1] > 0;
      assert rest[idx - 1] - 1 < |prices|;
    }
  }
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] - 1 < |prices|;
  assert is_valid_strategy(cuts, total, prices);
}

lemma AllCutsBounded(i: int, best: int, prices: seq<int>, dp: seq<int>)
  requires i > 0
  requires |dp| >= i
  requires |prices| >= i
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==>
            (forall cuts: seq<int> {:trigger is_valid_strategy(cuts, len, prices)} ::
              is_valid_strategy(cuts, len, prices) ==>
              calculate_revenue(cuts, prices) <= dp[len])
  requires forall k :: 1 <= k <= i ==> best >= Elem(prices, k - 1) + Elem(dp, i - k)
  ensures forall cuts: seq<int> ::
            is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best
{
  forall cuts | is_valid_strategy(cuts, i, prices)
    ensures calculate_revenue(cuts, prices) <= best
  {
    NonEmpty(cuts, i, prices);
    SplitStrategy(cuts, i, prices);
    var first := cuts[0];
    var rest := cuts[1..];
    assert 1 <= first <= i;
    assert 0 <= first - 1 < |prices|;
    GetPriceEq(prices, first - 1);
    assert calculate_revenue(cuts, prices) ==
      get_price(prices, first - 1) + calculate_revenue(rest, prices);
    assert calculate_revenue(cuts, prices) ==
      prices[first - 1] + calculate_revenue(rest, prices);

    assert 0 <= i - first < i;
    assert 0 <= i - first < |dp|;
    assert is_valid_strategy(rest, i - first, prices);
    assert forall other: seq<int> ::
      is_valid_strategy(other, i - first, prices) ==>
      calculate_revenue(other, prices) <= dp[i - first];
    assert calculate_revenue(rest, prices) <= dp[i - first];

    assert Elem(prices, first - 1) == prices[first - 1];
    assert Elem(dp, i - first) == dp[i - first];
    assert best >= Elem(prices, first - 1) + Elem(dp, i - first);
    assert best >= prices[first - 1] + dp[i - first];
    assert prices[first - 1] + calculate_revenue(rest, prices)
        <= prices[first - 1] + dp[i - first];
    assert calculate_revenue(cuts, prices) <= best;
  }
}

lemma ZeroOptimal(prices: seq<int>)
  ensures IsOptimal(0, 0, [], prices)
{
  assert sum_lengths([]) == 0;
  assert calculate_revenue([], prices) == 0;
  assert forall idx: int :: 0 <= idx < |[]| ==> ([][idx] > 0);
  assert forall idx: int :: 0 <= idx < |[]| ==> ([][idx] - 1 < |prices|);
  assert is_valid_strategy([], 0, prices);

  forall cuts | is_valid_strategy(cuts, 0, prices)
    ensures calculate_revenue(cuts, prices) <= 0
  {
    assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
    assert sum_lengths(cuts) == 0;
    NoPositiveRodSumsToZero(cuts);
    assert |cuts| == 0;
    assert calculate_revenue(cuts, prices) == 0;
  }
  CloseOptimal(0, 0, [], prices);
}

method {:vcs_split_on_every_assert} MaxForLength(i: int, dp: seq<int>, prices: seq<int>)
    returns (best: int, bestJ: int)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx]
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len]
  ensures 1 <= bestJ <= i
  ensures 0 <= best
  ensures best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  ensures forall k :: 1 <= k <= i ==> best >= Elem(prices, k - 1) + Elem(dp, i - k)
{
  assert 0 <= i - 1 < i;
  assert 0 <= i - 1 < |dp|;
  assert 0 <= dp[i - 1];
  assert 0 < |prices|;
  assert 0 <= prices[0];
  assert Elem(prices, 0) == prices[0];
  assert Elem(dp, i - 1) == dp[i - 1];

  best := prices[0] + dp[i - 1];
  bestJ := 1;
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  assert 0 <= best;

  var j := 2;
  assert i + 1 >= 2;
  assert j <= i + 1;
  assert forall k :: 1 <= k < j ==> best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
    forall k | 1 <= k < j
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert k == 1;
      assert Elem(prices, k - 1) + Elem(dp, i - k) == prices[0] + dp[i - 1];
    }
  };

  while j <= i
    invariant 2 <= j <= i + 1
    invariant 0 <= i - j + 1
    invariant 1 <= bestJ < j
    invariant 0 <= best
    invariant best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
    invariant forall k :: 1 <= k < j ==> best >= Elem(prices, k - 1) + Elem(dp, i - k)
    decreases i - j + 1
  {
    var j0 := j;
    var oldBest := best;
    var oldBestJ := bestJ;
    assert j0 <= i;
    assert 0 <= i - j0 + 1;

    assert forall k :: 1 <= k < j0 ==> oldBest >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k < j0
        ensures oldBest >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      }
    }
    assert oldBest == Elem(prices, oldBestJ - 1) + Elem(dp, i - oldBestJ);
    assert 0 <= oldBest;
    assert 1 <= oldBestJ < j0;

    assert 1 <= j0 <= i;
    assert 0 <= j0 - 1 < |prices|;
    assert 0 <= i - j0 < i;
    assert 0 <= i - j0 < |dp|;
    assert 0 <= prices[j0 - 1];
    assert 0 <= dp[i - j0];
    var cand := prices[j0 - 1] + dp[i - j0];
    assert 0 <= cand;
    assert Elem(prices, j0 - 1) == prices[j0 - 1];
    assert Elem(dp, i - j0) == dp[i - j0];
    assert cand == Elem(prices, j0 - 1) + Elem(dp, i - j0);

    if cand > oldBest {
      best := cand;
      bestJ := j0;
      assert best == cand;
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best >= oldBest;
      assert 1 <= bestJ <= j0;
    } else {
      best := oldBest;
      bestJ := oldBestJ;
      assert cand <= oldBest;
      assert best >= cand;
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert 1 <= bestJ <= j0;
    }
    assert best >= oldBest;
    assert best >= cand;
    assert 0 <= best;
    assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
    assert 1 <= bestJ <= j0;

    assert forall k :: 1 <= k <= j0 ==> best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k <= j0
        ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        if k < j0 {
          assert oldBest >= Elem(prices, k - 1) + Elem(dp, i - k);
          assert best >= oldBest;
        } else {
          assert k == j0;
          assert Elem(prices, k - 1) + Elem(dp, i - k) == cand;
          assert best >= cand;
        }
      }
    }

    j := j0 + 1;
    assert j == j0 + 1;
    assert 2 <= j <= i + 1;
    assert 0 <= i - j + 1;
    assert bestJ <= j0;
    assert 1 <= bestJ < j;
    assert forall k :: 1 <= k < j ==> best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k < j
        ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        assert k <= j0;
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      }
    }
  }

  assert j > i;
  assert j >= i + 1;
  assert j <= i + 1;
  assert j == i + 1;
  assert 1 <= bestJ < j;
  assert 1 <= bestJ <= i;
  assert 0 <= best;
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  assert forall k :: 1 <= k <= i ==> best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
    forall k | 1 <= k <= i
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert 1 <= k < j;
    }
  }
}

method {:vcs_split_on_every_assert} rod_cutting(n: int, prices: seq<int>) returns (result: int)
  requires 0 <= n
  requires |prices| >= n
  requires n <= 1000
  // Constraints matching Verus u64/usize unsigned and explicit bounds
  requires forall i: int :: 0 <= i < |prices| ==> 0 <= prices[i] <= 10000
  ensures result >= 0
  // 1. Upper Bound
  ensures forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          ==> calculate_revenue(cuts, prices) <= result)
  // 2. Existence
  ensures exists cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          && calculate_revenue(cuts, prices) == result)
{
  var dp: seq<int> := [0];
  ghost var ws: seq<seq<int>> := [[]];

  ZeroOptimal(prices);
  assert dp[0] == 0;
  assert ws[0] == [];
  assert IsOptimal(0, dp[0], ws[0], prices);

  assert forall idx :: 0 <= idx < |prices| ==> 0 <= prices[idx] by {
    forall idx | 0 <= idx < |prices|
      ensures 0 <= prices[idx]
    {
      assert 0 <= prices[idx] <= 10000;
    }
  };

  var i := 1;
