  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
  }
  SumLengthsNonnegative(rest);
  assert sum_lengths(rest) >= 0;
  assert first + sum_lengths(rest) == total;
  assert sum_lengths(rest) == total - first;
  assert first <= total;
  assert first > 0;
  assert first >= 1;
  assert 0 <= first - 1;
  assert first - 1 < |prices|;
  assert 0 <= cuts[0] - 1 < |prices|;
  assert 1 <= cuts[0] <= total;

  RevenueUnfold(cuts, prices);

  forall idx | 0 <= idx < |rest|
    ensures rest[idx] > 0 && rest[idx] - 1 < |prices|
  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
    assert cuts[idx + 1] - 1 < |prices|;
  }
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] > 0;
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] - 1 < |prices|;
  assert sum_lengths(rest) == total - first;
  assert is_valid_strategy(rest, total - first, prices);
  assert rest == cuts[1..];
  assert is_valid_strategy(cuts[1..], total - cuts[0], prices);
  assert calculate_revenue(cuts, prices) ==
    get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices);
}

lemma {:vcs_split_on_every_assert} CombineStrategy(j: int, rest: seq<int>, total: int, prices: seq<int>)
  requires j >= 1
  requires 0 <= j - 1 < |prices|
  requires is_valid_strategy(rest, total - j, prices)
  ensures is_valid_strategy([j] + rest, total, prices)
  ensures calculate_revenue([j] + rest, prices) ==
          get_price(prices, j - 1) + calculate_revenue(rest, prices)
{
  var cuts := [j] + rest;
  SumCons(j, rest);
  RevenueCons(j, rest, prices);
  assert sum_lengths(rest) == total - j;
  assert sum_lengths(cuts) == j + sum_lengths(rest);
  assert sum_lengths(cuts) == j + (total - j);
  assert sum_lengths(cuts) == total;

  assert forall t :: 0 <= t < |rest| ==> rest[t] > 0;
  assert forall t :: 0 <= t < |rest| ==> rest[t] - 1 < |prices|;

  forall idx | 0 <= idx < |cuts|
    ensures cuts[idx] > 0 && cuts[idx] - 1 < |prices|
  {
    if idx == 0 {
      assert cuts[0] == j;
      assert j > 0;
      assert 0 <= j - 1 < |prices|;
    } else {
      assert idx >= 1;
      assert 0 <= idx - 1 < |rest|;
      assert cuts[idx] == rest[idx - 1];
      assert rest[idx - 1] > 0;
      assert rest[idx - 1] - 1 < |prices|;
    }
  }
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] - 1 < |prices|;
  assert is_valid_strategy(cuts, total, prices);
  assert calculate_revenue(cuts, prices) ==
    get_price(prices, j - 1) + calculate_revenue(rest, prices);
}

lemma {:vcs_split_on_every_assert} AllCutsBounded(i: int, best: int, prices: seq<int>, dp: seq<int>)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==>
            (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
              is_valid_strategy(other, len, prices) ==>
              calculate_revenue(other, prices) <= dp[len])
  requires forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
  ensures forall cuts: seq<int> {:trigger is_valid_strategy(cuts, i, prices)} ::
            is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best
{
  forall cuts | is_valid_strategy(cuts, i, prices)
    ensures calculate_revenue(cuts, prices) <= best
  {
    NonEmpty(cuts, i, prices);
    SplitStrategy(cuts, i, prices);
    var first := cuts[0];
    var rest := cuts[1..];
    assert 1 <= first <= i;
    assert 0 <= first - 1 < |prices|;
    GetPriceEq(prices, first - 1);
    assert get_price(prices, first - 1) == prices[first - 1];
    assert calculate_revenue(cuts, prices) ==
      get_price(prices, first - 1) + calculate_revenue(rest, prices);
    assert calculate_revenue(cuts, prices) ==
      prices[first - 1] + calculate_revenue(rest, prices);

    var plen := i - first;
    assert plen == i - first;
    assert 0 <= plen < i;
    assert 0 <= plen < |dp|;
    var bound := dp[plen];
    assert bound == dp[plen];
    assert forall other: seq<int> {:trigger is_valid_strategy(other, plen, prices)} ::
      is_valid_strategy(other, plen, prices) ==>
      calculate_revenue(other, prices) <= dp[plen];
    assert is_valid_strategy(rest, plen, prices);
    assert calculate_revenue(rest, prices) <= dp[plen];
    assert calculate_revenue(rest, prices) <= bound;

    ElemEq(prices, first - 1);
    ElemEq(dp, plen);
    assert Elem(prices, first - 1) == prices[first - 1];
    assert Elem(dp, plen) == dp[plen];
    assert Elem(dp, i - first) == bound;
    assert best >= Elem(prices, first - 1) + Elem(dp, i - first);
    assert best >= prices[first - 1] + bound;

    AddLe(prices[first - 1], calculate_revenue(rest, prices), bound);
    var rev := calculate_revenue(cuts, prices);
    var mid := prices[first - 1] + bound;
    assert rev == prices[first - 1] + calculate_revenue(rest, prices);
    assert rev <= mid;
    assert mid <= best;
    TransLe(rev, mid, best);
    assert rev <= best;
    assert calculate_revenue(cuts, prices) <= best;
  }
}

lemma {:vcs_split_on_every_assert} ZeroOptimal(prices: seq<int>)
  ensures IsOptimal(0, 0, [], prices)
{
  assert sum_lengths([]) == 0;
  assert calculate_revenue([], prices) == 0;
  assert is_valid_strategy([], 0, prices);

  forall cuts | is_valid_strategy(cuts, 0, prices)
    ensures calculate_revenue(cuts, prices) <= 0
  {
    assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
    assert sum_lengths(cuts) == 0;
    NoPositiveRodSumsToZero(cuts);
    assert |cuts| == 0;
    assert calculate_revenue(cuts, prices) == 0;
  }
  assert forall cuts: seq<int> {:trigger is_valid_strategy(cuts, 0, prices)} ::
    is_valid_strategy(cuts, 0, prices) ==> calculate_revenue(cuts, prices) <= 0;
  CloseOptimal(0, 0, [], prices);
}

method {:vcs_split_on_every_assert} MaxForLength(i: int, dp: seq<int>, prices: seq<int>)
    returns (best: int, bestJ: int)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx]
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len]
  ensures 1 <= bestJ <= i
  ensures 0 <= best
  ensures 0 <= bestJ - 1 < |prices|
  ensures 0 <= i - bestJ < |dp|
  ensures best == prices[bestJ - 1] + dp[i - bestJ]
  ensures best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  ensures forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
{
  assert 0 <= i - 1 < i;
  assert |dp| >= i;
  assert 0 <= i - 1 < |dp|;
  assert 0 <= dp[i - 1];
  assert |prices| >= i;
  assert |prices| >= 1;
  assert 0 <= 0 < |prices|;
  assert 0 <= prices[0];
  ElemEq(prices, 0);
  ElemEq(dp, i - 1);
  assert Elem(prices, 0) == prices[0];
  assert Elem(dp, i - 1) == dp[i - 1];

  NonnegAdd(prices[0], dp[i - 1]);
  best := prices[0] + dp[i - 1];
  bestJ := 1;
  assert best == prices[0] + dp[i - 1];
  assert 0 <= best;
  assert best == Elem(prices, 0) + Elem(dp, i - 1);
  assert bestJ - 1 == 0;
  assert i - bestJ == i - 1;
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  assert 0 <= bestJ - 1 < |prices|;
  assert 0 <= i - bestJ < |dp|;

  var j := 2;
  assert j == 2;
  assert i + 1 >= 2;
  assert 2 <= j <= i + 1;
  assert i - j + 1 == i - 1;
  assert 0 <= i - j + 1;
  assert 1 <= bestJ < j;

  assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
      best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
    forall k | 1 <= k < j
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert j == 2;
      assert k == 1;
      assert Elem(prices, k - 1) == prices[0];
      assert Elem(dp, i - k) == dp[i - 1];
      assert best == Elem(prices, k - 1) + Elem(dp, i - k);
    }
  };

  while j <= i
    invariant 2 <= j <= i + 1
    invariant 0 <= i - j + 1
    invariant 1 <= bestJ < j
    invariant 0 <= best
    invariant 0 <= bestJ - 1 < |prices|
    invariant 0 <= i - bestJ < |dp|
    invariant best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
    invariant forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
                best >= Elem(prices, k - 1) + Elem(dp, i - k)
    decreases i - j + 1
  {
    var j0 := j;
    var oldBest := best;
    var oldBestJ := bestJ;
    assert j0 == j;
    assert oldBest == best;
    assert oldBestJ == bestJ;
    assert 1 <= oldBestJ < j0;
    assert 0 <= oldBest;
    assert oldBest == Elem(prices, oldBestJ - 1) + Elem(dp, i - oldBestJ);
    assert 0 <= oldBestJ - 1 < |prices|;
    assert 0 <= i - oldBestJ < |dp|;

    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j0 ==>
        oldBest >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k < j0
        ensures oldBest >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        assert 1 <= k < j;
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
        assert oldBest == best;
      }
    };

    assert 1 <= j0 <= i;
    assert 0 <= j0 - 1 < i;
    assert 0 <= j0 - 1 < |prices|;
    assert 0 <= prices[j0 - 1];
    assert 0 <= i - j0;
    assert i - j0 < i;
    assert 0 <= i - j0 < |dp|;
    assert 0 <= dp[i - j0];
    NonnegAdd(prices[j0 - 1], dp[i - j0]);
    var cand := prices[j0 - 1] + dp[i - j0];
    assert cand == prices[j0 - 1] + dp[i - j0];
    assert 0 <= cand;
    ElemEq(prices, j0 - 1);
    ElemEq(dp, i - j0);
    assert Elem(prices, j0 - 1) == prices[j0 - 1];
    assert Elem(dp, i - j0) == dp[i - j0];
    assert cand == Elem(prices, j0 - 1) + Elem(dp, i - j0);

    if cand > oldBest {
      best := cand;
      bestJ := j0;
      assert best == cand;
      assert bestJ == j0;
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best > oldBest;
      assert best >= oldBest;
      assert best >= cand;
      assert 0 <= best;
      assert 1 <= bestJ <= j0;
      assert 0 <= bestJ - 1 < |prices|;
      assert 0 <= i - bestJ < |dp|;
    } else {
      best := oldBest;
      bestJ := oldBestJ;
      assert cand <= oldBest;
      assert best == oldBest;
      assert bestJ == oldBestJ;
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best >= cand;
      assert best >= oldBest;
      assert 0 <= best;
      assert 1 <= bestJ < j0;
      assert 1 <= bestJ <= j0;
      assert 0 <= bestJ - 1 < |prices|;
      assert 0 <= i - bestJ < |dp|;
    }
    assert best >= oldBest;
    assert best >= cand;
    assert 0 <= best;
    assert 1 <= bestJ <= j0;
    assert 0 <= bestJ - 1 < |prices|;
    assert 0 <= i - bestJ < |dp|;
    assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);

    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= j0 ==>
        best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k <= j0
        ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        if k < j0 {
          assert oldBest >= Elem(prices, k - 1) + Elem(dp, i - k);
          assert best >= oldBest;
          assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
        } else {
          assert k == j0;
          assert Elem(prices, k - 1) + Elem(dp, i - k) == cand;
          assert best >= cand;
          assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
        }
      }
    };

    j := j0 + 1;
    assert j == j0 + 1;
    assert 2 <= j;
    assert j0 <= i;
    assert j <= i + 1;
    assert 2 <= j <= i + 1;
    assert i - j + 1 == i - j0;
    assert 0 <= i - j + 1;
    assert bestJ <= j0;
    assert bestJ < j;
    assert 1 <= bestJ < j;
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
        best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
      forall k | 1 <= k < j
        ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
      {
        assert k <= j0;
        assert 1 <= k <= j0;
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      }
    };
  }

  assert j > i;
  assert j >= i + 1;
  assert j <= i + 1;
  assert j == i + 1;
  assert 1 <= bestJ < j;
  assert bestJ <= i;
  assert 1 <= bestJ <= i;
  assert 0 <= best;
  assert 0 <= bestJ - 1 < |prices|;
  assert 0 <= i - bestJ < |dp|;
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  ElemEq(prices, bestJ - 1);
  ElemEq(dp, i - bestJ);
  assert Elem(prices, bestJ - 1) == prices[bestJ - 1];
  assert Elem(dp, i - bestJ) == dp[i - bestJ];
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
      best >= Elem(prices, k - 1) + Elem(dp, i - k) by {
    forall k | 1 <= k <= i
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert 1 <= k < j;
      assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
    }
  };
}

method {:vcs_split_on_every_assert} rod_cutting(n: int, prices: seq<int>) returns (result: int)
  requires 0 <= n
  requires |prices| >= n
  requires n <= 1000
  // Constraints matching Verus u64/usize unsigned and explicit bounds
  requires forall i: int :: 0 <= i < |prices| ==> 0 <= prices[i] <= 10000
  ensures result >= 0
  // 1. Upper Bound
  ensures forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          ==> calculate_revenue(cuts, prices) <= result)
  // 2. Existence
  ensures exists cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          && calculate_revenue(cuts, prices) == result)
{
  var dp: seq<int> := [0];
  ghost var ws: seq<seq<int>> := [[]];

  ZeroOptimal(prices);
  assert |dp| == 1;
  assert |ws| == 1;
  assert dp[0] == 0;
  assert ws[0] == [];
  assert IsOptimal(0, 0, [], prices);
  assert IsOptimal(0, dp[0], ws[0], prices);

  assert forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx] by {
    forall idx | 0 <= idx < |prices|
      ensures 0 <= prices[idx]
    {
      assert 0 <= prices[idx] <= 10000;
    }
  };

  var i := 1;
  assert 0 <= n;
  assert 1 <= i <= n + 1;
  assert 0 <= n - i + 1;
  assert |dp| == i;
  assert |ws| == i;
  assert forall len {:trigger dp[len]} {:trigger ws[len]} ::
      0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices) by {
    forall len | 0 <= len < i
      ensures IsOptimal(len, dp[len], ws[len], prices)
    {
      assert len == 0;
      assert dp[len] == 0;
      assert ws[len] == [];
      assert IsOptimal(len, dp[len], ws[len], prices);
    }
  };

  while i <= n
    invariant 1 <= i <= n + 1
    invariant 0 <= n - i + 1
    invariant |dp| == i
    invariant |ws| == i
    invariant forall len {:trigger dp[len]} {:trigger ws[len]} ::
                0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices)
    decreases n - i + 1
  {
    ghost var baseDp := dp;
    ghost var baseWs := ws;
    assert baseDp == dp;
    assert baseWs == ws;
    assert forall len {:trigger baseDp[len]} {:trigger baseWs[len]} ::
        0 <= len < i ==> IsOptimal(len, baseDp[len], baseWs[len], prices) by {
      forall len | 0 <= len < i
        ensures IsOptimal(len, baseDp[len], baseWs[len], prices)
      {
        assert baseDp[len] == dp[len];
        assert baseWs[len] == ws[len];
        assert IsOptimal(len, dp[len], ws[len], prices);
        assert IsOptimal(len, baseDp[len], baseWs[len], prices);
      }
    };

    assert 1 <= i;
    assert i <= n;
    assert |prices| >= n;
    assert |prices| >= i;
    assert |dp| == i;
    assert |ws| == i;

    assert forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len] by {
      forall len | 0 <= len < i
        ensures 0 <= dp[len]
      {
        assert IsOptimal(len, dp[len], ws[len], prices);
        OpenOptimal(len, dp[len], ws[len], prices);
        assert 0 <= dp[len];
      }
    };

    var best, bestJ := MaxForLength(i, dp, prices);
    assert 1 <= bestJ <= i;
    assert 0 <= best;
    assert 0 <= bestJ - 1 < |prices|;
    assert 0 <= i - bestJ < |dp|;
    assert best == prices[bestJ - 1] + dp[i - bestJ];
    assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
      best >= Elem(prices, k - 1) + Elem(dp, i - k);

    assert 0 <= i - bestJ < i;
    assert 0 <= i - bestJ < |ws|;
    ghost var sub := ws[i - bestJ];
    assert sub == ws[i - bestJ];
    assert IsOptimal(i - bestJ, dp[i - bestJ], sub, prices);
    OpenOptimal(i - bestJ, dp[i - bestJ], sub, prices);
    assert is_valid_strategy(sub, i - bestJ, prices);
    assert calculate_revenue(sub, prices) == dp[i - bestJ];
    assert 0 <= bestJ - 1 < |prices|;
    assert bestJ >= 1;

    ghost var bestCuts := [bestJ] + sub;
    CombineStrategy(bestJ, sub, i, prices);
    assert bestCuts == [bestJ] + sub;
    assert is_valid_strategy(bestCuts, i, prices);
    assert calculate_revenue(bestCuts, prices) ==
      get_price(prices, bestJ - 1) + calculate_revenue(sub, prices);
    GetPriceEq(prices, bestJ - 1);
    assert get_price(prices, bestJ - 1) == prices[bestJ - 1];
    assert calculate_revenue(bestCuts, prices) ==
      prices[bestJ - 1] + calculate_revenue(sub, prices);
    assert calculate_revenue(sub, prices) == dp[i - bestJ];
    assert calculate_revenue(bestCuts, prices) == prices[bestJ - 1] + dp[i - bestJ];
    assert best == prices[bestJ - 1] + dp[i - bestJ];
    assert calculate_revenue(bestCuts, prices) == best;

    assert forall len {:trigger dp[len]} :: 0 <= len < i ==>
      (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
        is_valid_strategy(other, len, prices) ==>
        calculate_revenue(other, prices) <= dp[len]) by {
      forall len | 0 <= len < i
        ensures forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
          is_valid_strategy(other, len, prices) ==>
          calculate_revenue(other, prices) <= dp[len]
      {
        assert IsOptimal(len, dp[len], ws[len], prices);
        OpenOptimal(len, dp[len], ws[len], prices);
      }
    };

    AllCutsBounded(i, best, prices, dp);
    assert forall cuts: seq<int> {:trigger is_valid_strategy(cuts, i, prices)} ::
      is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best;
    CloseOptimal(i, best, bestCuts, prices);
    assert IsOptimal(i, best, bestCuts, prices);

    var i0 := i;
    assert i0 == i;
    assert i0 <= n;
    assert |dp| == i0;
    assert |ws| == i0;
    assert dp == baseDp;
    assert ws == baseWs;
    ghost var savedDp := dp;
    ghost var savedWs := ws;
    assert savedDp == baseDp;
    assert savedWs == baseWs;
    assert |savedDp| == i0;
    assert |savedWs| == i0;
    dp := savedDp + [best];
    ws := savedWs + [bestCuts];
    assert dp == savedDp + [best];
    assert ws == savedWs + [bestCuts];
    AppendAt(savedDp, best, i0);
    AppendAt(savedWs, bestCuts, i0);
    assert |dp| == i0 + 1;
    assert |ws| == i0 + 1;
    assert dp[i0] == best;
    assert ws[i0] == bestCuts;

    assert forall len {:trigger dp[len]} {:trigger ws[len]} ::
        0 <= len <= i0 ==> IsOptimal(len, dp[len], ws[len], prices) by {
      forall len | 0 <= len <= i0
        ensures IsOptimal(len, dp[len], ws[len], prices)
      {
        if len < i0 {
          assert 0 <= len < |savedDp|;
          AppendAt(savedDp, best, len);
          AppendAt(savedWs, bestCuts, len);
          assert dp[len] == savedDp[len];
          assert savedDp[len] == baseDp[len];
          assert ws[len] == savedWs[len];
          assert savedWs[len] == baseWs[len];
          assert IsOptimal(len, baseDp[len], baseWs[len], prices);
          assert IsOptimal(len, dp[len], ws[len], prices);
        } else {
          assert len == i0;
          assert len == |savedDp|;
          assert dp[len] == best;
          assert ws[len] == bestCuts;
          assert IsOptimal(i0, best, bestCuts, prices);
          assert IsOptimal(len, dp[len], ws[len], prices);
        }
      }
    };

    i := i0 + 1;
    assert i == i0 + 1;
    assert 1 <= i <= n + 1;
    assert 0 <= n - i + 1;
    assert |dp| == i;
    assert |ws| == i;
    assert forall len {:trigger dp[len]} {:trigger ws[len]} ::
        0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices) by {
      forall len | 0 <= len < i
        ensures IsOptimal(len, dp[len], ws[len], prices)
      {
        assert 0 <= len <= i0;
        assert IsOptimal(len, dp[len], ws[len], prices);
      }
    };
  }

  assert i <= n + 1;
  assert i > n;
  assert i >= n + 1;
  assert i == n + 1;
  assert |dp| == i;
  assert |ws| == i;
  assert 0 <= n < i;
  assert 0 <= n < |dp|;
  assert 0 <= n < |ws|;
  assert IsOptimal(n, dp[n], ws[n], prices);
  result := dp[n];
  assert result == dp[n];
  assert IsOptimal(n, result, ws[n], prices);
