    assert left.low == l && left.high == mid;
    assert right.low == mid && right.high == r;
    assert left.low == res.low;
    assert left.high == (res.low + res.high) / 2;
    assert right.low == (res.low + res.high) / 2;
    assert right.high == res.high;
    assert left.is_segment_tree() && right.is_segment_tree();

    forall j | left.low <= j < left.high
