    var r := n.right.value;
    var mid := (n.low + n.high) / 2;
    assert l.low == n.low && l.high == mid;
    assert r.low == mid && r.high == n.high;
    assert n.low < mid < n.high;
    assert 0 <= mid - n.low;
    assert mid - n.low < n.high - n.low;
    assert l.high - l.low == mid - n.low;
    assert 0 <= l.high - l.low < n.high - n.low;
    assert 0 <= n.high - mid;
    assert n.high - mid < n.high - n.low;
    assert r.high - r.low == n.high - mid;
    assert 0 <= r.high - r.low < n.high - n.low;
}

lemma {:induction false} {:vcs_split_on_every_assert} SingletonMem(k0: int, v0: int, k: int)
    ensures (k in map[k0 := v0]) <==> (k == k0)
    ensures k == k0 ==> map[k0 := v0][k] == v0
{
    var m := map[k0 := v0];
    if k == k0 {
        assert k in m;
        assert m[k] == v0;
    } else {
        assert k !in m;
    }
    assert (k in m) <==> (k == k0);
    assert k == k0 ==> m[k] == v0;
}

lemma {:induction false} {:vcs_split_on_every_assert} MapOverwriteKey(k: int, a: int, b: int)
    ensures map[k := a][k := b] == map[k := b]
{
    var lhs := map[k := a][k := b];
    var rhs := map[k := b];
    forall x: int
        ensures (x in lhs) <==> (x in rhs)
        ensures x in lhs ==> lhs[x] == rhs[x]
    {
        SingletonMem(k, a, x);
        SingletonMem(k, b, x);
        if x == k {
            assert x in map[k := a];
            assert x in lhs;
            assert lhs[x] == b;
            assert x in rhs;
            assert rhs[x] == b;
            assert lhs[x] == rhs[x];
        } else {
            assert x !in map[k := a];
            assert x !in lhs;
            assert x !in rhs;
        }
        assert (x in lhs) <==> (x in rhs);
        if x in lhs {
            assert lhs[x] == rhs[x];
        }
    }
    assert lhs == rhs;
}

lemma {:induction false} {:vcs_split_on_every_assert} InUnion(m1: map<int, int>, m2: map<int, int>, k: int)
    ensures (k in (m1 + m2)) <==> (k in m1 || k in m2)
    ensures k in m2 ==> (m1 + m2)[k] == m2[k]
    ensures (k !in m2 && k in m1) ==> (m1 + m2)[k] == m1[k]
{
    if k in m2 {
        assert k in (m1 + m2);
        assert (m1 + m2)[k] == m2[k];
    } else if k in m1 {
        assert k in (m1 + m2);
        assert (m1 + m2)[k] == m1[k];
    } else {
        assert k !in (m1 + m2);
    }
}

lemma {:induction false} {:vcs_split_on_every_assert} InUpdate(m: map<int, int>, k: int, newv: int, x: int)
    ensures (x in (m[k := newv])) <==> (x == k || x in m)
    ensures (m[k := newv])[k] == newv
    ensures (x != k && x in m) ==> (m[k := newv])[x] == m[x]
    ensures (x != k && x !in m) ==> x !in (m[k := newv])
{
    if x == k {
        assert x in (m[k := newv]);
        assert (m[k := newv])[x] == newv;
    } else if x in m {
        assert x in (m[k := newv]);
        assert (m[k := newv])[x] == m[x];
    } else {
        assert x !in (m[k := newv]);
    }
    assert (m[k := newv])[k] == newv;
}

lemma {:induction false} {:vcs_split_on_every_assert} MapUpdateOnLeft(m1: map<int, int>, m2: map<int, int>, k: int, newv: int)
    requires k in m1
    requires k !in m2
    ensures (m1 + m2)[k := newv] == (m1[k := newv]) + m2
{
    var lhs := (m1 + m2)[k := newv];
    var rhs := (m1[k := newv]) + m2;

    forall x: int
        ensures (x in lhs) <==> (x in rhs)
        ensures x in lhs ==> lhs[x] == rhs[x]
    {
        InUpdate(m1 + m2, k, newv, x);
        InUpdate(m1, k, newv, x);
        InUnion(m1, m2, x);
        InUnion(m1[k := newv], m2, x);

        if x == k {
            assert x in m1 && x !in m2;
            assert x in (m1 + m2);
            assert x in lhs;
            assert lhs[x] == newv;
            assert x in (m1[k := newv]);
            assert (m1[k := newv])[x] == newv;
            assert rhs[x] == newv;
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else if x in m2 {
            assert x in (m1 + m2);
            assert lhs[x] == (m1 + m2)[x];
            assert (m1 + m2)[x] == m2[x];
            assert x in lhs;
            assert rhs[x] == m2[x];
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else if x in m1 {
            assert x != k && x !in m2;
            assert x in (m1 + m2);
            assert lhs[x] == m1[x];
            assert x in lhs;
            assert x in (m1[k := newv]);
            assert (m1[k := newv])[x] == m1[x];
            assert rhs[x] == m1[x];
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else {
            assert x != k && x !in m1 && x !in m2;
            assert x !in (m1 + m2);
            assert x !in lhs;
            assert x !in (m1[k := newv]);
            assert x !in rhs;
        }
        assert (x in lhs) <==> (x in rhs);
        if x in lhs {
            assert lhs[x] == rhs[x];
        }
    }
    assert lhs == rhs;
}

lemma {:induction false} {:vcs_split_on_every_assert} MapUpdateOnRight(m1: map<int, int>, m2: map<int, int>, k: int, newv: int)
    requires k in m2
    requires k !in m1
    ensures (m1 + m2)[k := newv] == m1 + (m2[k := newv])
{
    var lhs := (m1 + m2)[k := newv];
    var rhs := m1 + (m2[k := newv]);

    forall x: int
        ensures (x in lhs) <==> (x in rhs)
        ensures x in lhs ==> lhs[x] == rhs[x]
    {
        InUpdate(m1 + m2, k, newv, x);
        InUpdate(m2, k, newv, x);
        InUnion(m1, m2, x);
        InUnion(m1, m2[k := newv], x);

        if x == k {
            assert x in m2 && x !in m1;
            assert x in (m1 + m2);
            assert x in lhs;
            assert lhs[x] == newv;
            assert x in (m2[k := newv]);
            assert (m2[k := newv])[x] == newv;
            assert rhs[x] == newv;
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else if x in m2 {
            assert x in (m1 + m2);
            assert lhs[x] == m2[x];
            assert x in lhs;
            assert x in (m2[k := newv]);
            assert (m2[k := newv])[x] == m2[x];
            assert rhs[x] == m2[x];
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else if x in m1 {
            assert x != k && x !in m2;
            assert x in (m1 + m2);
            assert lhs[x] == m1[x];
            assert x in lhs;
            assert x !in (m2[k := newv]);
            assert rhs[x] == m1[x];
            assert x in rhs;
            assert lhs[x] == rhs[x];
        } else {
            assert x != k && x !in m1 && x !in m2;
            assert x !in (m1 + m2);
            assert x !in lhs;
            assert x !in (m2[k := newv]);
            assert x !in rhs;
        }
        assert (x in lhs) <==> (x in rhs);
        if x in lhs {
            assert lhs[x] == rhs[x];
        }
    }
    assert lhs == rhs;
}

lemma {:induction false} {:vcs_split_on_every_assert} ViewDomain(n: Node, k: int)
    requires n.is_segment_tree()
    ensures k in n.view() <==> n.low <= k < n.high
    decreases n.high - n.low
{
    Bounds(n);
    WellFormedShape(n);
    assert 0 < n.high - n.low;

    if n.left.None? {
        assert n.right.None?;
        OpenLeaf(n);
        assert n.view() == map[n.low := n.val];
        assert n.high == n.low + 1;
        SingletonMem(n.low, n.val, k);
        assert (k in map[n.low := n.val]) <==> (k == n.low);
        assert (k in n.view()) <==> (k == n.low);
        assert (n.low <= k < n.high) <==> (k == n.low);
        assert (k in n.view()) <==> (n.low <= k < n.high);
    } else {
        assert n.left.Some? && n.right.Some?;
        OpenInternal(n);
        ChildSmaller(n);
        var l := n.left.value;
        var r := n.right.value;
        var mid := (n.low + n.high) / 2;
        assert l.low == n.low && l.high == mid;
        assert r.low == mid && r.high == n.high;
        assert n.low < mid < n.high;
        UnfoldView(n);
        assert n.view() == l.view() + r.view();

        assert 0 <= l.high - l.low < n.high - n.low;
        ViewDomain(l, k);
        assert 0 <= r.high - r.low < n.high - n.low;
        ViewDomain(r, k);

        if k in n.view() {
            InUnion(l.view(), r.view(), k);
            if k in r.view() {
                assert r.low <= k < r.high;
                assert n.low <= k;
                assert k < n.high;
                assert n.low <= k < n.high;
            } else {
                assert k !in r.view();
                assert k in l.view();
                assert l.low <= k < l.high;
                assert n.low <= k;
                assert k < n.high;
                assert n.low <= k < n.high;
            }
        }
        assert (k in n.view()) ==> (n.low <= k < n.high);

        if n.low <= k < n.high {
            if k < mid {
                assert l.low <= k < l.high;
                assert k in l.view();
                InUnion(l.view(), r.view(), k);
                assert k in n.view();
            } else {
                assert r.low <= k < r.high;
                assert k in r.view();
                InUnion(l.view(), r.view(), k);
                assert k in n.view();
            }
        }
        assert (n.low <= k < n.high) ==> (k in n.view());
        assert (k in n.view()) <==> (n.low <= k < n.high);
    }
}

lemma {:induction false} {:vcs_split_on_every_assert} ViewLe(n: Node, k: int)
    requires n.is_segment_tree()
    requires k in n.view()
    ensures n.view()[k] <= n.val
    decreases n.high - n.low
{
    Bounds(n);
    WellFormedShape(n);
    assert 0 < n.high - n.low;

    if n.left.None? {
        assert n.right.None?;
        OpenLeaf(n);
        assert n.view() == map[n.low := n.val];
        SingletonMem(n.low, n.val, k);
        assert k == n.low;
        assert n.view()[k] == n.val;
    } else {
        assert n.left.Some? && n.right.Some?;
        OpenInternal(n);
        ChildSmaller(n);
        var l := n.left.value;
        var r := n.right.value;
        var mid := (n.low + n.high) / 2;
        assert l.val <= n.val && r.val <= n.val;
        UnfoldView(n);
        assert n.view() == l.view() + r.view();
        InUnion(l.view(), r.view(), k);

        assert 0 <= l.high - l.low < n.high - n.low;
        assert 0 <= r.high - r.low < n.high - n.low;

        if k in r.view() {
            ViewLe(r, k);
            assert n.view()[k] == r.view()[k];
            assert r.view()[k] <= r.val;
            assert n.view()[k] <= n.val;
        } else {
            assert k !in r.view();
            assert k in l.view();
            ViewLe(l, k);
            assert n.view()[k] == l.view()[k];
            assert l.view()[k] <= l.val;
            assert n.view()[k] <= n.val;
        }
    }
}

lemma {:induction false} {:vcs_split_on_every_assert} ProveLeaf(n: Node)
    requires n.left.None? && n.right.None?
    requires n.high == n.low + 1
    requires 0 <= n.low
    requires 0 <= n.val
    ensures n.is_segment_tree()
    ensures n.view() == map[n.low := n.val]
{
    UnfoldView(n);
    assert n.view() == map[n.low := n.val];
    assert 0 <= n.low < n.high;

    forall k: int
        ensures (k in n.view() <==> n.low <= k < n.high) && (k in n.view() ==> n.view()[k] <= n.val)
    {
        SingletonMem(n.low, n.val, k);
        assert n.view() == map[n.low := n.val];
        assert (k in map[n.low := n.val]) <==> (k == n.low);
        assert (k in n.view()) <==> (k == n.low);
        assert n.high == n.low + 1;
        assert (n.low <= k < n.high) <==> (k == n.low);
        assert (k in n.view()) <==> (n.low <= k < n.high);
        if k in n.view() {
            assert k == n.low;
            assert n.view()[k] == n.val;
        }
        assert k in n.view() ==> n.view()[k] <= n.val;
    }

    assert {:split_here} true;
    assert n.is_segment_tree();
}

lemma {:induction false} {:vcs_split_on_every_assert} ProveInternal(n: Node)
    requires n.left.Some? && n.right.Some?
    requires 0 <= n.low < n.high
    requires 0 <= n.val
    requires n.left.value.is_segment_tree()
    requires n.right.value.is_segment_tree()
    requires n.left.value.low == n.low
    requires n.left.value.high == (n.low + n.high) / 2
    requires n.right.value.low == (n.low + n.high) / 2
    requires n.right.value.high == n.high
    requires n.val == (if n.left.value.val > n.right.value.val then n.left.value.val else n.right.value.val)
    ensures n.is_segment_tree()
{
    var l := n.left.value;
    var r := n.right.value;
    var mid := (n.low + n.high) / 2;
    assert l.low == n.low && l.high == mid;
    assert r.low == mid && r.high == n.high;
    assert l.is_segment_tree() && r.is_segment_tree();
    Bounds(l);
    Bounds(r);
    assert 0 <= l.low < l.high;
    assert 0 <= r.low < r.high;
    assert n.low < mid < n.high;

    if l.val > r.val {
        assert n.val == l.val;
        assert l.val <= n.val && r.val <= n.val;
    } else {
        assert n.val == r.val;
        assert l.val <= n.val && r.val <= n.val;
    }
    assert l.val <= n.val && r.val <= n.val;

    UnfoldView(n);
    assert n.view() == l.view() + r.view();

    forall k: int
        ensures (k in n.view() <==> n.low <= k < n.high) && (k in n.view() ==> n.view()[k] <= n.val)
    {
        if k in n.view() {
            InUnion(l.view(), r.view(), k);
            if k in r.view() {
                ViewDomain(r, k);
                ViewLe(r, k);
                assert r.low <= k < r.high;
                assert n.low <= k < n.high;
                assert n.view()[k] == r.view()[k];
                assert r.view()[k] <= r.val;
                assert r.val <= n.val;
                assert n.view()[k] <= n.val;
            } else {
                assert k !in r.view();
                assert k in l.view();
                ViewDomain(l, k);
                ViewLe(l, k);
                assert l.low <= k < l.high;
                assert n.low <= k < n.high;
                assert n.view()[k] == l.view()[k];
                assert l.view()[k] <= l.val;
                assert l.val <= n.val;
                assert n.view()[k] <= n.val;
            }
        }
        assert (k in n.view()) ==> (n.low <= k < n.high);
        assert (k in n.view()) ==> n.view()[k] <= n.val;

        if n.low <= k < n.high {
            if k < mid {
                assert l.low <= k < l.high;
                ViewDomain(l, k);
                assert k in l.view();
                InUnion(l.view(), r.view(), k);
                assert k in n.view();
            } else {
                assert r.low <= k < r.high;
                ViewDomain(r, k);
                assert k in r.view();
                InUnion(l.view(), r.view(), k);
                assert k in n.view();
            }
        }
        assert (n.low <= k < n.high) ==> (k in n.view());
        assert (k in n.view()) <==> (n.low <= k < n.high);
    }

    assert 0 <= n.low < n.high;
    assert 0 <= n.val;
    assert n.left.Some? && n.right.Some?;
    assert l.is_segment_tree() && r.is_segment_tree();
    assert l.low == n.low && l.high == mid && r.low == mid && r.high == n.high;
    assert n.val == (if l.val > r.val then l.val else r.val);
    assert {:split_here} true;
    assert n.is_segment_tree();
}

method {:vcs_split_on_every_assert} update(node: Node, idx: int, v: int) returns (res: Node)
    // Constraint: unsigned integers
    requires v >= 0
    requires node.is_segment_tree()
    requires node.low <= idx < node.high
    ensures
        && res.is_segment_tree()
        && res.low == node.low
        && res.high == node.high
        // Functional Correctness & Frame Preservation:
        // The view matches the old view, but with the specific key updated
        && res.view() == node.view()[idx := v]
    decreases node.high - node.low
{
    Bounds(node);
    WellFormedShape(node);
    assert 0 <= node.low < node.high;
    assert 0 < node.high - node.low;
    assert (node.left.Some? && node.right.Some?) || (node.left.None? && node.right.None?);

    if node.left.None? {
        assert node.right.None?;
        OpenLeaf(node);
        assert node.high == node.low + 1;
        assert node.low <= idx < node.high;
        assert idx == node.low;
        assert node.view() == map[node.low := node.val];

        res := Node(v, node.low, node.high, None, None);
        assert res.left.None? && res.right.None?;
        assert res.low == node.low && res.high == node.high;
        assert res.high == res.low + 1;
        assert res.val == v;
        assert 0 <= res.low && 0 <= res.val;
        ProveLeaf(res);
        assert res.is_segment_tree();
        assert res.view() == map[res.low := res.val];
        assert res.view() == map[node.low := v];

        MapOverwriteKey(node.low, node.val, v);
        assert map[node.low := node.val][node.low := v] == map[node.low := v];
        assert node.view()[idx := v] == map[node.low := node.val][node.low := v];
        assert node.view()[idx := v] == map[node.low := v];
        assert res.view() == node.view()[idx := v];
    } else {
        assert node.left.Some? && node.right.Some?;
        var l := node.left.value;
        var r := node.right.value;
        assert l == node.left.value && r == node.right.value;
        OpenInternal(node);
        ChildSmaller(node);
        var mid := (node.low + node.high) / 2;
        assert l.low == node.low && l.high == mid;
        assert r.low == mid && r.high == node.high;
        assert l.is_segment_tree() && r.is_segment_tree();
        assert node.low < mid < node.high;
        assert 0 <= l.val && 0 <= r.val;
        UnfoldView(node);
        assert node.view() == l.view() + r.view();

        if idx < mid {
            assert node.low <= idx < mid;
            assert l.low <= idx < l.high;
            assert 0 <= l.high - l.low < node.high - node.low;
            var newL := update(l, idx, v);
            assert newL.is_segment_tree();
            assert newL.low == l.low && newL.high == l.high;
            assert newL.view() == l.view()[idx := v];
            Bounds(newL);
            Bounds(r);
            assert 0 <= newL.val && 0 <= r.val;
            var newVal := if newL.val > r.val then newL.val else r.val;
            assert 0 <= newVal;
            assert newVal == (if newL.val > r.val then newL.val else r.val);

            res := Node(newVal, node.low, node.high, Some(newL), Some(r));
            assert res.left.Some? && res.right.Some?;
            assert res.left.value == newL && res.right.value == r;
            assert res.val == newVal;
            assert res.low == node.low && res.high == node.high;
            assert 0 <= res.low < res.high;
            assert newL.low == res.low && newL.high == mid;
            assert r.low == mid && r.high == res.high;
            assert mid == (res.low + res.high) / 2;
            assert res.left.value.is_segment_tree() && res.right.value.is_segment_tree();
            assert res.val == (if res.left.value.val > res.right.value.val then res.left.value.val else res.right.value.val);
            ProveInternal(res);
            assert res.is_segment_tree();

            UnfoldView(res);
            assert res.view() == newL.view() + r.view();
            ViewDomain(l, idx);
            assert idx in l.view();
            ViewDomain(r, idx);
            assert idx < r.low;
            assert !(r.low <= idx < r.high);
            assert idx !in r.view();
            MapUpdateOnLeft(l.view(), r.view(), idx, v);
            assert (l.view() + r.view())[idx := v] == (l.view()[idx := v]) + r.view();
            assert newL.view() == l.view()[idx := v];
            assert res.view() == (l.view()[idx := v]) + r.view();
            assert node.view()[idx := v] == (l.view() + r.view())[idx := v];
            assert res.view() == node.view()[idx := v];
        } else {
            assert mid <= idx < node.high;
            assert r.low <= idx < r.high;
            assert 0 <= r.high - r.low < node.high - node.low;
            var newR := update(r, idx, v);
            assert newR.is_segment_tree();
            assert newR.low == r.low && newR.high == r.high;
            assert newR.view() == r.view()[idx := v];
            Bounds(l);
            Bounds(newR);
            assert 0 <= l.val && 0 <= newR.val;
            var newVal := if l.val > newR.val then l.val else newR.val;
            assert 0 <= newVal;
            assert newVal == (if l.val > newR.val then l.val else newR.val);

            res := Node(newVal, node.low, node.high, Some(l), Some(newR));
            assert res.left.Some? && res.right.Some?;
            assert res.left.value == l && res.right.value == newR;
            assert res.val == newVal;
            assert res.low == node.low && res.high == node.high;
            assert 0 <= res.low < res.high;
            assert l.low == res.low && l.high == mid;
            assert newR.low == mid && newR.high == res.high;
            assert mid == (res.low + res.high) / 2;
            assert res.left.value.is_segment_tree() && res.right.value.is_segment_tree();
            assert res.val == (if res.left.value.val > res.right.value.val then res.left.value.val else res.right.value.val);
            ProveInternal(res);
            assert res.is_segment_tree();

            UnfoldView(res);
            assert res.view() == l.view() + newR.view();
            ViewDomain(r, idx);
            assert idx in r.view();
            ViewDomain(l, idx);
            assert l.high == mid <= idx;
            assert !(l.low <= idx < l.high);
