method query(node: Node, ql: int, qr: int) returns (res: int)
    requires node.is_segment_tree()
    requires ql < qr
    requires node.low <= ql
    requires qr <= node.high
    ensures res >= 0
    // Correctness: result is >= everything in the query range
    ensures forall k :: ql <= k < qr ==> node.view()[k] <= res
    // Tightness: result actually exists in the query range
    ensures exists k :: ql <= k < qr && node.view()[k] == res
    decreases node
{
    match (node.left, node.right) {
        case (None, None) =>
            assert node.view() == map[node.low := node.val];
            assert ql == node.low && qr == node.low + 1;
            res := node.val;
            assert node.view()[ql] == res;
        case (Some(l), Some(r)) =>
            var mid := (node.low + node.high) / 2;
            assert l.low == node.low && l.high == mid && r.low == mid && r.high == node.high;
            assert l.is_segment_tree() && r.is_segment_tree();
            assert node.view() == l.view() + r.view();
            forall k | node.low <= k < mid
                ensures k in node.view() && node.view()[k] == l.view()[k]
            {
                assert k in l.view();
                assert k !in r.view();
            }
            forall k | mid <= k < node.high
                ensures k in node.view() && node.view()[k] == r.view()[k]
            {
                assert k in r.view();
