  assert is_valid_strategy(cuts, n, prices) && calculate_revenue(cuts, prices) == result;
  assert (exists c: seq<int> ::
      is_valid_strategy(c, n, prices) && calculate_revenue(c, prices) == result) by {
    var c := cuts;
    assert is_valid_strategy(c, n, prices);
    assert calculate_revenue(c, prices) == result;
  }
}

