lemma {:vcs_split_on_every_assert} StepOptimal(
    i: int,
    dp: seq<int>,
    ws: seq<seq<int>>,
    prices: seq<int>,
    best: int,
    bestJ: int)
  requires 1 <= i
  requires |dp| == i
  requires |ws| == i
  requires |prices| >= i
  requires 1 <= bestJ <= i
  requires 0 <= best
  requires 0 <= bestJ - 1 < |prices|
  requires 0 <= i - bestJ < |dp|
  requires best == prices[bestJ - 1] + dp[i - bestJ]
  requires best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  requires forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
  requires forall len {:trigger dp[len]} {:trigger ws[len]} ::
            0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices)
  ensures IsOptimal(i, best, [bestJ] + ws[i - bestJ], prices)
{
  assert 0 <= i - bestJ < i;
  assert 0 <= i - bestJ < |ws|;
  UseBelow(i, i - bestJ, dp, ws, prices);
  var sub := ws[i - bestJ];
  assert sub == ws[i - bestJ];
  assert IsOptimal(i - bestJ, dp[i - bestJ], sub, prices);
  OpenOptimal(i - bestJ, dp[i - bestJ], sub, prices);

  var bestCuts := [bestJ] + sub;
  CombineStrategy(bestJ, sub, i, prices);
  assert is_valid_strategy(bestCuts, i, prices);
  assert calculate_revenue(bestCuts, prices) ==
    get_price(prices, bestJ - 1) + calculate_revenue(sub, prices);
  GetPriceEq(prices, bestJ - 1);
  assert get_price(prices, bestJ - 1) == prices[bestJ - 1];
  assert calculate_revenue(sub, prices) == dp[i - bestJ];
  assert calculate_revenue(bestCuts, prices) ==
    prices[bestJ - 1] + dp[i - bestJ];
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert calculate_revenue(bestCuts, prices) == best;

  forall len | 0 <= len < i
    ensures forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
      is_valid_strategy(other, len, prices) ==>
      calculate_revenue(other, prices) <= dp[len]
  {
    assert 0 <= len < |dp|;
    assert 0 <= len < |ws|;
    UseBelow(i, len, dp, ws, prices);
    OpenOptimal(len, dp[len], ws[len], prices);
    assert dp[len] == dp[len];
  }

  assert forall len {:trigger dp[len]} :: 0 <= len < i ==>
    (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
      is_valid_strategy(other, len, prices) ==>
      calculate_revenue(other, prices) <= dp[len]);

  AllCutsBounded(i, best, prices, dp);
  assert forall cuts: seq<int> {:trigger is_valid_strategy(cuts, i, prices)} ::
    is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best;

  CloseOptimal(i, best, bestCuts, prices);
  assert bestCuts == [bestJ] + sub;
  assert sub == ws[i - bestJ];
  assert bestCuts == [bestJ] + ws[i - bestJ];
  assert IsOptimal(i, best, bestCuts, prices);
  assert IsOptimal(i, best, [bestJ] + ws[i - bestJ], prices);
}

lemma {:vcs_split_on_every_assert} PreserveAfterAppend(
    i: int,
    oldDp: seq<int>,
    oldWs: seq<seq<int>>,
    newDp: seq<int>,
    newWs: seq<seq<int>>,
    best: int,
    bestCuts: seq<int>,
    prices: seq<int>)
  requires |oldDp| == i
  requires |oldWs| == i
  requires newDp == oldDp + [best]
  requires newWs == oldWs + [bestCuts]
  requires forall len {:trigger oldDp[len]} {:trigger oldWs[len]} ::
            0 <= len < i ==> IsOptimal(len, oldDp[len], oldWs[len], prices)
  requires IsOptimal(i, best, bestCuts, prices)
  ensures |newDp| == i + 1
  ensures |newWs| == i + 1
  ensures forall len {:trigger newDp[len]} {:trigger newWs[len]} ::
            0 <= len <= i ==> IsOptimal(len, newDp[len], newWs[len], prices)
{
  AppendAt(oldDp, best, i);
  AppendAt(oldWs, bestCuts, i);
  assert |newDp| == i + 1;
  assert |newWs| == i + 1;
  assert newDp[i] == best;
  assert newWs[i] == bestCuts;

  forall len | 0 <= len <= i
    ensures IsOptimal(len, newDp[len], newWs[len], prices)
  {
    if len < i {
      assert 0 <= len < |oldDp|;
      assert 0 <= len < |oldWs|;
      UseBelow(i, len, oldDp, oldWs, prices);
      AppendAt(oldDp, best, len);
      AppendAt(oldWs, bestCuts, len);
      assert newDp[len] == oldDp[len];
      assert newWs[len] == oldWs[len];
      assert IsOptimal(len, oldDp[len], oldWs[len], prices);
      assert IsOptimal(len, newDp[len], newWs[len], prices);
    } else {
      assert len == i;
      assert newDp[len] == best;
      assert newWs[len] == bestCuts;
      assert IsOptimal(i, best, bestCuts, prices);
      assert IsOptimal(len, newDp[len], newWs[len], prices);
    }
  }
}

method {:vcs_split_on_every_assert} MaxForLength(i: int, dp: seq<int>, prices: seq<int>)
    returns (best: int, bestJ: int)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx]
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len]
  ensures 1 <= bestJ <= i
  ensures 0 <= best
  ensures 0 <= bestJ - 1 < |prices|
  ensures 0 <= i - bestJ < |dp|
  ensures best == prices[bestJ - 1] + dp[i - bestJ]
  ensures best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  ensures forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
{
  assert 0 <= i - 1 < i;
  assert 0 <= i - 1 < |dp|;
  assert 0 <= 0 < |prices|;
  PriceNonNeg(prices, 0);
  DpNonNeg(i, i - 1, dp);
  assert 0 <= prices[0];
  assert 0 <= dp[i - 1];
  NonnegAdd(prices[0], dp[i - 1]);
  best := prices[0] + dp[i - 1];
  bestJ := 1;
  ElemEq(prices, 0);
  ElemEq(dp, i - 1);
  assert Elem(prices, 0) == prices[0];
  assert Elem(dp, i - 1) == dp[i - 1];
  assert best == prices[0] + dp[i - 1];
  assert best == Elem(prices, 0) + Elem(dp, i - 1);
  assert bestJ - 1 == 0;
  assert i - bestJ == i - 1;
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  assert 0 <= best;
  assert 0 <= bestJ - 1 < |prices|;
  assert 0 <= i - bestJ < |dp|;

  var j := 2;
  assert j == 2;
  assert 2 <= j <= i + 1;
  assert 0 <= i - j + 1;
  assert 1 <= bestJ < j;

  forall k | 1 <= k < j
    ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
  {
    assert k == 1;
    assert Elem(prices, k - 1) == Elem(prices, 0);
    assert Elem(dp, i - k) == Elem(dp, i - 1);
    assert best == Elem(prices, k - 1) + Elem(dp, i - k);
    assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
  }
  assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
    best >= Elem(prices, k - 1) + Elem(dp, i - k);

  while j <= i
    invariant 2 <= j <= i + 1
    invariant 0 <= i - j + 1
    invariant 1 <= bestJ < j
    invariant 0 <= best
    invariant 0 <= bestJ - 1 < |prices|
    invariant 0 <= i - bestJ < |dp|
    invariant best == prices[bestJ - 1] + dp[i - bestJ]
    invariant best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
    invariant forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
                best >= Elem(prices, k - 1) + Elem(dp, i - k)
    decreases i + 1 - j
  {
    var j0 := j;
    var oldBest := best;
    var oldBestJ := bestJ;
    assert j0 == j;
    assert oldBest == best;
    assert oldBestJ == bestJ;
    assert 1 <= j0 <= i;
    assert 1 <= oldBestJ < j0;
    assert oldBest == prices[oldBestJ - 1] + dp[i - oldBestJ];
    assert oldBest == Elem(prices, oldBestJ - 1) + Elem(dp, i - oldBestJ);
    assert 0 <= oldBest;
    assert 0 <= oldBestJ - 1 < |prices|;
    assert 0 <= i - oldBestJ < |dp|;

    forall k | 1 <= k < j0
      ensures oldBest >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert 1 <= k < j;
      assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      assert oldBest == best;
    }
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j0 ==>
      oldBest >= Elem(prices, k - 1) + Elem(dp, i - k);

    assert 0 <= j0 - 1 < |prices|;
    assert 0 <= i - j0 < i;
    assert 0 <= i - j0 < |dp|;
    PriceNonNeg(prices, j0 - 1);
    DpNonNeg(i, i - j0, dp);
    assert 0 <= prices[j0 - 1];
    assert 0 <= dp[i - j0];
    NonnegAdd(prices[j0 - 1], dp[i - j0]);
    var cand := prices[j0 - 1] + dp[i - j0];
    ElemEq(prices, j0 - 1);
    ElemEq(dp, i - j0);
    assert Elem(prices, j0 - 1) == prices[j0 - 1];
    assert Elem(dp, i - j0) == dp[i - j0];
    assert cand == Elem(prices, j0 - 1) + Elem(dp, i - j0);
    assert 0 <= cand;

    if cand > oldBest {
      best := cand;
      bestJ := j0;
      assert best == cand;
      assert bestJ == j0;
      assert best == prices[j0 - 1] + dp[i - j0];
      assert prices[bestJ - 1] == prices[j0 - 1];
      assert dp[i - bestJ] == dp[i - j0];
      assert best == prices[bestJ - 1] + dp[i - bestJ];
      assert Elem(prices, bestJ - 1) == Elem(prices, j0 - 1);
      assert Elem(dp, i - bestJ) == Elem(dp, i - j0);
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best > oldBest;
      assert best >= oldBest;
      assert best >= cand;
      assert 0 <= best;
      assert 1 <= bestJ <= j0;
      assert 0 <= bestJ - 1 < |prices|;
      assert 0 <= i - bestJ < |dp|;
    } else {
      assert cand <= oldBest;
      best := oldBest;
      bestJ := oldBestJ;
      assert best == oldBest;
      assert bestJ == oldBestJ;
      assert best == prices[bestJ - 1] + dp[i - bestJ];
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best >= cand;
      assert best >= oldBest;
      assert 0 <= best;
      assert 1 <= bestJ < j0;
      assert 1 <= bestJ <= j0;
      assert 0 <= bestJ - 1 < |prices|;
      assert 0 <= i - bestJ < |dp|;
    }

    assert best >= oldBest;
    assert best >= cand;
    assert 0 <= best;
    assert 1 <= bestJ <= j0;
    assert 0 <= bestJ - 1 < |prices|;
    assert 0 <= i - bestJ < |dp|;
    assert best == prices[bestJ - 1] + dp[i - bestJ];
    assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);

    forall k | 1 <= k <= j0
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      if k < j0 {
        assert 1 <= k < j0;
        assert oldBest >= Elem(prices, k - 1) + Elem(dp, i - k);
        assert best >= oldBest;
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      } else {
        assert k == j0;
        assert cand == Elem(prices, k - 1) + Elem(dp, i - k);
        assert best >= cand;
        assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      }
    }
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= j0 ==>
      best >= Elem(prices, k - 1) + Elem(dp, i - k);

    j := j0 + 1;
    assert j == j0 + 1;
    assert 2 <= j <= i + 1;
    assert 0 <= i - j + 1;
    assert bestJ <= j0;
    assert bestJ < j;
    assert 1 <= bestJ < j;

    forall k | 1 <= k < j
      ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert 1 <= k <= j0;
      assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
    }
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
      best >= Elem(prices, k - 1) + Elem(dp, i - k);
  }

  assert j > i;
  assert j >= i + 1;
  assert j <= i + 1;
  assert j == i + 1;
  assert 1 <= bestJ < j;
  assert 1 <= bestJ <= i;
  assert 0 <= best;
  assert 0 <= bestJ - 1 < |prices|;
  assert 0 <= i - bestJ < |dp|;
  ElemEq(prices, bestJ - 1);
  ElemEq(dp, i - bestJ);
  assert Elem(prices, bestJ - 1) == prices[bestJ - 1];
  assert Elem(dp, i - bestJ) == dp[i - bestJ];
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);

  forall k | 1 <= k <= i
    ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
  {
    assert 1 <= k < j;
    assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
  }
  assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
    best >= Elem(prices, k - 1) + Elem(dp, i - k);
}

method {:vcs_split_on_every_assert} rod_cutting(n: int, prices: seq<int>) returns (result: int)
  requires 0 <= n
  requires |prices| >= n
  requires n <= 1000
  // Constraints matching Verus u64/usize unsigned and explicit bounds
  requires forall i: int :: 0 <= i < |prices| ==> 0 <= prices[i] <= 10000
  ensures result >= 0
  // 1. Upper Bound
  ensures forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          ==> calculate_revenue(cuts, prices) <= result)
  // 2. Existence
  ensures exists cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          && calculate_revenue(cuts, prices) == result)
{
  var dp: seq<int> := [0];
  ghost var ws: seq<seq<int>> := [[]];
  ZeroOptimal(prices);

  var i := 1;
  assert dp == [0];
  assert ws == [[]];
  assert |dp| == 1;
  assert |ws| == 1;
  assert dp[0] == 0;
  assert ws[0] == [];
  assert IsOptimal(0, 0, [], prices);
  assert IsOptimal(0, dp[0], ws[0], prices);
  assert 1 <= i <= n + 1;
  assert |dp| == i;
  assert |ws| == i;

  forall len | 0 <= len < i
    ensures IsOptimal(len, dp[len], ws[len], prices)
  {
    assert len == 0;
    assert dp[len] == 0;
    assert ws[len] == [];
    assert IsOptimal(len, dp[len], ws[len], prices);
  }
  assert forall len {:trigger dp[len]} {:trigger ws[len]} ::
    0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices);

  while i <= n
    invariant 1 <= i <= n + 1
    invariant |dp| == i
    invariant |ws| == i
    invariant forall len {:trigger dp[len]} {:trigger ws[len]} ::
                0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices)
    decreases n + 1 - i
  {
    assert i <= n;
    assert |prices| >= n;
    assert |prices| >= i;
    assert |dp| == i;
    assert |ws| == i;
    assert |dp| >= i;

    forall len | 0 <= len < i
      ensures 0 <= dp[len]
    {
      assert |dp| == i;
      assert |ws| == i;
      assert 0 <= len < |dp|;
      assert 0 <= len < |ws|;
      UseBelow(i, len, dp, ws, prices);
      OpenOptimal(len, dp[len], ws[len], prices);
      assert 0 <= dp[len];
    }
    assert forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len];

    forall idx | 0 <= idx < |prices|
      ensures 0 <= prices[idx]
    {
      assert 0 <= prices[idx] <= 10000;
      assert 0 <= prices[idx];
    }
    assert forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx];

    var best, bestJ := MaxForLength(i, dp, prices);
    assert 1 <= bestJ <= i;
    assert 0 <= best;
    assert 0 <= bestJ - 1 < |prices|;
    assert 0 <= i - bestJ < |dp|;
    assert |ws| == |dp|;
    assert 0 <= i - bestJ < |ws|;

    StepOptimal(i, dp, ws, prices, best, bestJ);
    ghost var bestCuts := [bestJ] + ws[i - bestJ];
    assert bestCuts == [bestJ] + ws[i - bestJ];
    assert IsOptimal(i, best, bestCuts, prices);

    ghost var oldDp := dp;
    ghost var oldWs := ws;
    assert oldDp == dp;
    assert oldWs == ws;
    assert |oldDp| == i;
    assert |oldWs| == i;

    forall len | 0 <= len < i
      ensures IsOptimal(len, oldDp[len], oldWs[len], prices)
    {
      assert 0 <= len < |dp|;
      assert 0 <= len < |ws|;
      UseBelow(i, len, dp, ws, prices);
      assert dp[len] == oldDp[len];
      assert ws[len] == oldWs[len];
      assert IsOptimal(len, dp[len], ws[len], prices);
      assert IsOptimal(len, oldDp[len], oldWs[len], prices);
    }
    assert forall len {:trigger oldDp[len]} {:trigger oldWs[len]} ::
      0 <= len < i ==> IsOptimal(len, oldDp[len], oldWs[len], prices);

    var newDp := dp + [best];
    ghost var newWs := ws + [bestCuts];
    assert newDp == oldDp + [best];
    assert newWs == oldWs + [bestCuts];

    PreserveAfterAppend(i, oldDp, oldWs, newDp, newWs, best, bestCuts, prices);
    assert |newDp| == i + 1;
    assert |newWs| == i + 1;
    assert forall len {:trigger newDp[len]} {:trigger newWs[len]} ::
      0 <= len <= i ==> IsOptimal(len, newDp[len], newWs[len], prices);

    var i0 := i;
    assert i0 == i;
    dp := newDp;
    ws := newWs;
    assert dp == newDp;
    assert ws == newWs;
    i := i0 + 1;
    assert i == i0 + 1;
    assert |dp| == i;
    assert |ws| == i;
    assert 1 <= i <= n + 1;

    forall len | 0 <= len < i
      ensures IsOptimal(len, dp[len], ws[len], prices)
    {
      assert 0 <= len <= i0;
      assert |newDp| == i0 + 1;
      assert |newWs| == i0 + 1;
      assert 0 <= len < |newDp|;
      assert 0 <= len < |newWs|;
      ReadPreserve(i0, len, newDp, newWs, prices);
      assert dp == newDp;
      assert ws == newWs;
      assert dp[len] == newDp[len];
      assert ws[len] == newWs[len];
      assert IsOptimal(len, newDp[len], newWs[len], prices);
      assert IsOptimal(len, dp[len], ws[len], prices);
    }
    assert forall len {:trigger dp[len]} {:trigger ws[len]} ::
      0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices);
  }

  assert i <= n + 1;
  assert i > n;
  assert i >= n + 1;
  assert i == n + 1;
  assert |dp| == i;
  assert |ws| == i;
  assert 0 <= n < i;
  assert 0 <= n < |dp|;
  assert 0 <= n < |ws|;
  UseBelow(i, n, dp, ws, prices);
  assert IsOptimal(n, dp[n], ws[n], prices);

  result := dp[n];
  assert result == dp[n];
  assert IsOptimal(n, result, ws[n], prices);
  OpenOptimal(n, result, ws[n], prices);
  assert result >= 0;
  assert forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices)
          ==> calculate_revenue(cuts, prices) <= result);
  ExistsCuts(ws[n], n, prices, result);
}
