lemma MidBounds(l: int, r: int)
  requires 0 <= l
  requires l + 2 <= r
  ensures l < (l + r) / 2 < r
{
  var a := l + r;
  var q := a / 2;
  var m := a % 2;
  assert 0 <= m < 2;
  assert a == 2 * q + m;
  assert a >= 2 * l + 2;
  assert a <= 2 * r - 2;

  if q <= l {
    assert 2 * q + m <= 2 * l + m;
    assert 2 * l + m <= 2 * l + 1;
    assert 2 * q + m <= 2 * l + 1;
    assert 2 * l + 2 <= a;
    assert 2 * l + 1 < 2 * l + 2;
    assert 2 * q + m < a;
    assert a == 2 * q + m;
    assert false;
  }
  if q >= r {
    assert a <= 2 * r - 2;
    assert 2 * r - 2 < 2 * r;
    assert 2 * q + m >= 2 * r;
    assert a < 2 * q + m;
    assert a == 2 * q + m;
    assert false;
  }
  assert q >= l + 1;
  assert q <= r - 1;
  assert l < q < r;
  assert q == (l + r) / 2;
}

