method IsPrimeCheck(k: int) returns (b: bool)
  ensures b == is_prime(k)
{
  if k <= 1 {
    return false;
  }
  var d := 2;
  while d < k
    invariant 2 <= d <= k
    invariant forall e :: 1 < e < d ==> !divides(e, k)
  {
    if k % d == 0 {
      assert divides(d, k);
      return false;
    }
    d := d + 1;
  }
  return true;
}

