lemma ConsSlice<T>(x: T, xs: seq<T>)
  ensures ([x] + xs)[0] == x
  ensures ([x] + xs)[1..] == xs
  ensures |[x] + xs| == |xs| + 1
{
  var s := [x] + xs;
  assert s[0] == x;
  assert |s| == |xs| + 1;
  forall idx | 0 <= idx < |xs|
    ensures s[1..][idx] == xs[idx]
  {
    assert s[idx + 1] == xs[idx];
    assert s[1..][idx] == s[idx + 1];
  }
  assert |s[1..]| == |xs|;
  assert forall idx :: 0 <= idx < |xs| ==> s[1..][idx] == xs[idx];
  assert s[1..] == xs;
}

