    SumLengthsNonnegative(cuts[1..]);
    SumUnfold(cuts);
    assert sum_lengths(cuts) == cuts[0] + sum_lengths(cuts[1..]);
    assert 0 <= cuts[0];
    assert 0 <= sum_lengths(cuts[1..]);
  }
}

lemma NoPositiveRodSumsToZero(cuts: seq<int>)
  requires forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0
  requires sum_lengths(cuts) == 0
  ensures |cuts| == 0
{
  if |cuts| > 0 {
    assert cuts[0] > 0;
    assert cuts[0] >= 1;
    forall idx | 0 <= idx < |cuts[1..]|
      ensures 0 <= cuts[1..][idx]
    {
      assert cuts[1..][idx] == cuts[idx + 1];
      assert 0 <= idx + 1 < |cuts|;
      assert cuts[idx + 1] > 0;
      assert 0 <= cuts[1..][idx];
    }
    SumLengthsNonnegative(cuts[1..]);
    SumUnfold(cuts);
    assert sum_lengths(cuts) == cuts[0] + sum_lengths(cuts[1..]);
    assert sum_lengths(cuts[1..]) >= 0;
    assert sum_lengths(cuts) >= 1;
    assert sum_lengths(cuts) == 0;
    assert false;
  }
  assert |cuts| == 0;
}

lemma NonEmpty(cuts: seq<int>, total: int, prices: seq<int>)
  requires is_valid_strategy(cuts, total, prices)
  requires total > 0
  ensures |cuts| >= 1
{
  if |cuts| == 0 {
    assert sum_lengths(cuts) == 0;
    assert sum_lengths(cuts) == total;
    assert false;
  }
}

lemma {:vcs_split_on_every_assert} SplitStrategy(cuts: seq<int>, total: int, prices: seq<int>)
  requires |cuts| >= 1
  requires is_valid_strategy(cuts, total, prices)
  requires total > 0
  ensures 1 <= cuts[0] <= total
  ensures 0 <= cuts[0] - 1 < |prices|
  ensures is_valid_strategy(cuts[1..], total - cuts[0], prices)
  ensures calculate_revenue(cuts, prices) ==
          get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices)
{
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] - 1 < |prices|;
  assert sum_lengths(cuts) == total;

  var first := cuts[0];
  var rest := cuts[1..];
  SumUnfold(cuts);
  assert sum_lengths(cuts) == first + sum_lengths(rest);

  forall idx | 0 <= idx < |rest|
    ensures 0 <= rest[idx]
  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
  }
  SumLengthsNonnegative(rest);
  assert sum_lengths(rest) >= 0;
  assert first + sum_lengths(rest) == total;
  assert sum_lengths(rest) == total - first;
  assert first <= total;
  assert first > 0;
  assert first >= 1;
  assert 0 <= first - 1;
  assert first - 1 < |prices|;
  assert 0 <= cuts[0] - 1 < |prices|;
  assert 1 <= cuts[0] <= total;

  RevenueUnfold(cuts, prices);

  forall idx | 0 <= idx < |rest|
    ensures rest[idx] > 0 && rest[idx] - 1 < |prices|
  {
    assert rest[idx] == cuts[idx + 1];
    assert 0 <= idx + 1 < |cuts|;
    assert cuts[idx + 1] > 0;
    assert cuts[idx + 1] - 1 < |prices|;
  }
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] > 0;
  assert forall idx :: 0 <= idx < |rest| ==> rest[idx] - 1 < |prices|;
  assert sum_lengths(rest) == total - first;
  assert is_valid_strategy(rest, total - first, prices);
  assert rest == cuts[1..];
  assert is_valid_strategy(cuts[1..], total - cuts[0], prices);
  assert calculate_revenue(cuts, prices) ==
    get_price(prices, cuts[0] - 1) + calculate_revenue(cuts[1..], prices);
}

lemma {:vcs_split_on_every_assert} CombineStrategy(j: int, rest: seq<int>, total: int, prices: seq<int>)
  requires j >= 1
  requires 0 <= j - 1 < |prices|
  requires is_valid_strategy(rest, total - j, prices)
  ensures is_valid_strategy([j] + rest, total, prices)
  ensures calculate_revenue([j] + rest, prices) ==
          get_price(prices, j - 1) + calculate_revenue(rest, prices)
{
  var cuts := [j] + rest;
  SumCons(j, rest);
  RevenueCons(j, rest, prices);
  assert sum_lengths(rest) == total - j;
  assert sum_lengths(cuts) == j + sum_lengths(rest);
  assert sum_lengths(cuts) == j + (total - j);
  assert sum_lengths(cuts) == total;

  assert forall t :: 0 <= t < |rest| ==> rest[t] > 0;
  assert forall t :: 0 <= t < |rest| ==> rest[t] - 1 < |prices|;

  forall idx | 0 <= idx < |cuts|
    ensures cuts[idx] > 0 && cuts[idx] - 1 < |prices|
  {
    if idx == 0 {
      assert cuts[0] == j;
      assert j > 0;
      assert 0 <= j - 1 < |prices|;
    } else {
      assert idx >= 1;
      assert 0 <= idx - 1 < |rest|;
      assert cuts[idx] == rest[idx - 1];
      assert rest[idx - 1] > 0;
      assert rest[idx - 1] - 1 < |prices|;
    }
  }
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
  assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] - 1 < |prices|;
  assert is_valid_strategy(cuts, total, prices);
  assert calculate_revenue(cuts, prices) ==
    get_price(prices, j - 1) + calculate_revenue(rest, prices);
}

lemma SelectLen(i: int, plen: int, dp: seq<int>, prices: seq<int>)
  requires 0 <= plen < i
  requires |dp| >= i
  requires 0 <= plen < |dp|
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==>
            (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
              is_valid_strategy(other, len, prices) ==>
              calculate_revenue(other, prices) <= dp[len])
  ensures forall other: seq<int> {:trigger is_valid_strategy(other, plen, prices)} ::
            is_valid_strategy(other, plen, prices) ==>
            calculate_revenue(other, prices) <= dp[plen]
{
  var v := dp[plen];
  assert v == dp[plen];
  assert 0 <= plen < i;
}

lemma ApplySelected(plen: int, dp: seq<int>, prices: seq<int>, rest: seq<int>)
  requires 0 <= plen < |dp|
  requires is_valid_strategy(rest, plen, prices)
  requires forall other: seq<int> {:trigger is_valid_strategy(other, plen, prices)} ::
            is_valid_strategy(other, plen, prices) ==>
            calculate_revenue(other, prices) <= dp[plen]
  ensures calculate_revenue(rest, prices) <= dp[plen]
{
  assert is_valid_strategy(rest, plen, prices);
}

lemma SelectCut(i: int, best: int, first: int, dp: seq<int>, prices: seq<int>)
  requires 1 <= first <= i
  requires forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
  ensures best >= Elem(prices, first - 1) + Elem(dp, i - first)
{
  var priceTerm := Elem(prices, first - 1);
  var dpTerm := Elem(dp, i - first);
  assert best >= priceTerm + dpTerm;
}

lemma {:vcs_split_on_every_assert} AllCutsBounded(i: int, best: int, prices: seq<int>, dp: seq<int>)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==>
            (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
              is_valid_strategy(other, len, prices) ==>
              calculate_revenue(other, prices) <= dp[len])
  requires forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
  ensures forall cuts: seq<int> {:trigger is_valid_strategy(cuts, i, prices)} ::
            is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best
{
  forall cuts | is_valid_strategy(cuts, i, prices)
    ensures calculate_revenue(cuts, prices) <= best
  {
    NonEmpty(cuts, i, prices);
    SplitStrategy(cuts, i, prices);
    var first := cuts[0];
    var rest := cuts[1..];
    var plen := i - first;

    assert first == cuts[0];
    assert rest == cuts[1..];
    assert 1 <= first <= i;
    assert 0 <= first - 1 < |prices|;
    assert plen == i - cuts[0];
    assert 0 <= plen < i;
    assert 0 <= plen < |dp|;
    assert is_valid_strategy(rest, plen, prices);

    GetPriceEq(prices, first - 1);
    assert calculate_revenue(cuts, prices) ==
      get_price(prices, first - 1) + calculate_revenue(rest, prices);
    assert get_price(prices, first - 1) == prices[first - 1];
    assert calculate_revenue(cuts, prices) ==
      prices[first - 1] + calculate_revenue(rest, prices);

    SelectLen(i, plen, dp, prices);
    ApplySelected(plen, dp, prices, rest);
    assert calculate_revenue(rest, prices) <= dp[plen];

    SelectCut(i, best, first, dp, prices);
    ElemEq(prices, first - 1);
    ElemEq(dp, plen);
    assert Elem(prices, first - 1) == prices[first - 1];
    assert Elem(dp, plen) == dp[plen];
    assert plen == i - first;
    assert Elem(dp, i - first) == dp[plen];
    assert best >= Elem(prices, first - 1) + Elem(dp, i - first);
    assert best >= prices[first - 1] + dp[plen];

    AddLe(prices[first - 1], calculate_revenue(rest, prices), dp[plen]);
    var rev := calculate_revenue(cuts, prices);
    var mid := prices[first - 1] + dp[plen];
    assert rev == prices[first - 1] + calculate_revenue(rest, prices);
    assert rev <= mid;
    assert mid <= best;
    TransLe(rev, mid, best);
    assert rev <= best;
  }
}

lemma {:vcs_split_on_every_assert} ZeroOptimal(prices: seq<int>)
  ensures IsOptimal(0, 0, [], prices)
{
  assert sum_lengths([]) == 0;
  assert calculate_revenue([], prices) == 0;
  assert is_valid_strategy([], 0, prices);

  forall cuts | is_valid_strategy(cuts, 0, prices)
    ensures calculate_revenue(cuts, prices) <= 0
  {
    assert forall idx :: 0 <= idx < |cuts| ==> cuts[idx] > 0;
    assert sum_lengths(cuts) == 0;
    NoPositiveRodSumsToZero(cuts);
    assert |cuts| == 0;
    assert calculate_revenue(cuts, prices) == 0;
  }
  assert forall cuts: seq<int> {:trigger is_valid_strategy(cuts, 0, prices)} ::
    is_valid_strategy(cuts, 0, prices) ==> calculate_revenue(cuts, prices) <= 0;
  CloseOptimal(0, 0, [], prices);
}

lemma UseBelow(i: int, len: int, dp: seq<int>, ws: seq<seq<int>>, prices: seq<int>)
  requires 0 <= len < i
  requires 0 <= len < |dp|
  requires 0 <= len < |ws|
  requires forall l {:trigger dp[l]} {:trigger ws[l]} ::
            0 <= l < i ==> IsOptimal(l, dp[l], ws[l], prices)
  ensures IsOptimal(len, dp[len], ws[len], prices)
{
  var d := dp[len];
  var w := ws[len];
  assert IsOptimal(len, d, w, prices);
}

lemma DpNonNeg(i: int, len: int, dp: seq<int>)
  requires 0 <= len < i
  requires 0 <= len < |dp|
  requires forall l {:trigger dp[l]} :: 0 <= l < i ==> 0 <= dp[l]
  ensures 0 <= dp[len]
{
  var v := dp[len];
  assert v == dp[len];
  assert 0 <= v;
}

lemma PriceNonNeg(prices: seq<int>, idx: int)
  requires 0 <= idx < |prices|
  requires forall t {:trigger prices[t]} :: 0 <= t < |prices| ==> 0 <= prices[t]
  ensures 0 <= prices[idx]
{
  var v := prices[idx];
  assert v == prices[idx];
  assert 0 <= v;
}

lemma ExistsCuts(cuts: seq<int>, n: int, prices: seq<int>, result: int)
  requires is_valid_strategy(cuts, n, prices)
  requires calculate_revenue(cuts, prices) == result
  ensures exists c: seq<int> :: is_valid_strategy(c, n, prices) && calculate_revenue(c, prices) == result
{
  assert exists c: seq<int> :: is_valid_strategy(c, n, prices) && calculate_revenue(c, prices) == result by {
    var c := cuts;
    assert is_valid_strategy(c, n, prices);
    assert calculate_revenue(c, prices) == result;
  }
}

lemma ReadPreserve(i: int, len: int, newDp: seq<int>, newWs: seq<seq<int>>, prices: seq<int>)
  requires 0 <= len <= i
  requires 0 <= len < |newDp|
  requires 0 <= len < |newWs|
  requires forall l {:trigger newDp[l]} {:trigger newWs[l]} ::
            0 <= l <= i ==> IsOptimal(l, newDp[l], newWs[l], prices)
  ensures IsOptimal(len, newDp[len], newWs[len], prices)
{
  var d := newDp[len];
  var w := newWs[len];
  assert IsOptimal(len, d, w, prices);
}

lemma {:vcs_split_on_every_assert} StepOptimal(
    i: int,
    dp: seq<int>,
    ws: seq<seq<int>>,
    prices: seq<int>,
    best: int,
    bestJ: int)
  requires 1 <= i
  requires |dp| == i
  requires |ws| == i
  requires |prices| >= i
  requires 1 <= bestJ <= i
  requires 0 <= best
  requires 0 <= bestJ - 1 < |prices|
  requires 0 <= i - bestJ < |dp|
  requires best == prices[bestJ - 1] + dp[i - bestJ]
  requires best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  requires forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
  requires forall len {:trigger dp[len]} {:trigger ws[len]} ::
            0 <= len < i ==> IsOptimal(len, dp[len], ws[len], prices)
  ensures IsOptimal(i, best, [bestJ] + ws[i - bestJ], prices)
{
  assert 0 <= i - bestJ < i;
  assert 0 <= i - bestJ < |ws|;
  UseBelow(i, i - bestJ, dp, ws, prices);
  var sub := ws[i - bestJ];
  assert sub == ws[i - bestJ];
  assert IsOptimal(i - bestJ, dp[i - bestJ], sub, prices);
  OpenOptimal(i - bestJ, dp[i - bestJ], sub, prices);

  var bestCuts := [bestJ] + sub;
  CombineStrategy(bestJ, sub, i, prices);
  assert is_valid_strategy(bestCuts, i, prices);
  assert calculate_revenue(bestCuts, prices) ==
    get_price(prices, bestJ - 1) + calculate_revenue(sub, prices);
  GetPriceEq(prices, bestJ - 1);
  assert get_price(prices, bestJ - 1) == prices[bestJ - 1];
  assert calculate_revenue(sub, prices) == dp[i - bestJ];
  assert calculate_revenue(bestCuts, prices) ==
    prices[bestJ - 1] + dp[i - bestJ];
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert calculate_revenue(bestCuts, prices) == best;

  forall len | 0 <= len < i
    ensures forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
      is_valid_strategy(other, len, prices) ==>
      calculate_revenue(other, prices) <= dp[len]
  {
    assert 0 <= len < |dp|;
    assert 0 <= len < |ws|;
    UseBelow(i, len, dp, ws, prices);
    OpenOptimal(len, dp[len], ws[len], prices);
    assert dp[len] == dp[len];
  }

  assert forall len {:trigger dp[len]} :: 0 <= len < i ==>
    (forall other: seq<int> {:trigger is_valid_strategy(other, len, prices)} ::
      is_valid_strategy(other, len, prices) ==>
      calculate_revenue(other, prices) <= dp[len]);

  AllCutsBounded(i, best, prices, dp);
  assert forall cuts: seq<int> {:trigger is_valid_strategy(cuts, i, prices)} ::
    is_valid_strategy(cuts, i, prices) ==> calculate_revenue(cuts, prices) <= best;

  CloseOptimal(i, best, bestCuts, prices);
  assert bestCuts == [bestJ] + sub;
  assert sub == ws[i - bestJ];
  assert bestCuts == [bestJ] + ws[i - bestJ];
  assert IsOptimal(i, best, bestCuts, prices);
  assert IsOptimal(i, best, [bestJ] + ws[i - bestJ], prices);
}

lemma {:vcs_split_on_every_assert} PreserveAfterAppend(
    i: int,
    oldDp: seq<int>,
    oldWs: seq<seq<int>>,
    newDp: seq<int>,
    newWs: seq<seq<int>>,
    best: int,
    bestCuts: seq<int>,
    prices: seq<int>)
  requires |oldDp| == i
  requires |oldWs| == i
  requires newDp == oldDp + [best]
  requires newWs == oldWs + [bestCuts]
  requires forall len {:trigger oldDp[len]} {:trigger oldWs[len]} ::
            0 <= len < i ==> IsOptimal(len, oldDp[len], oldWs[len], prices)
  requires IsOptimal(i, best, bestCuts, prices)
  ensures |newDp| == i + 1
  ensures |newWs| == i + 1
  ensures forall len {:trigger newDp[len]} {:trigger newWs[len]} ::
            0 <= len <= i ==> IsOptimal(len, newDp[len], newWs[len], prices)
{
  AppendAt(oldDp, best, i);
  AppendAt(oldWs, bestCuts, i);
  assert |newDp| == i + 1;
  assert |newWs| == i + 1;
  assert newDp[i] == best;
  assert newWs[i] == bestCuts;

  forall len | 0 <= len <= i
    ensures IsOptimal(len, newDp[len], newWs[len], prices)
  {
    if len < i {
      assert 0 <= len < |oldDp|;
      assert 0 <= len < |oldWs|;
      UseBelow(i, len, oldDp, oldWs, prices);
      AppendAt(oldDp, best, len);
      AppendAt(oldWs, bestCuts, len);
      assert newDp[len] == oldDp[len];
      assert newWs[len] == oldWs[len];
      assert IsOptimal(len, oldDp[len], oldWs[len], prices);
      assert IsOptimal(len, newDp[len], newWs[len], prices);
    } else {
      assert len == i;
      assert newDp[len] == best;
      assert newWs[len] == bestCuts;
      assert IsOptimal(i, best, bestCuts, prices);
      assert IsOptimal(len, newDp[len], newWs[len], prices);
    }
  }
}

method {:vcs_split_on_every_assert} MaxForLength(i: int, dp: seq<int>, prices: seq<int>)
    returns (best: int, bestJ: int)
  requires 1 <= i
  requires |dp| >= i
  requires |prices| >= i
  requires forall idx {:trigger prices[idx]} :: 0 <= idx < |prices| ==> 0 <= prices[idx]
  requires forall len {:trigger dp[len]} :: 0 <= len < i ==> 0 <= dp[len]
  ensures 1 <= bestJ <= i
  ensures 0 <= best
  ensures 0 <= bestJ - 1 < |prices|
  ensures 0 <= i - bestJ < |dp|
  ensures best == prices[bestJ - 1] + dp[i - bestJ]
  ensures best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
  ensures forall k {:trigger Elem(prices, k - 1)} :: 1 <= k <= i ==>
            best >= Elem(prices, k - 1) + Elem(dp, i - k)
{
  assert 0 <= i - 1 < i;
  assert 0 <= i - 1 < |dp|;
  assert 0 <= 0 < |prices|;
  PriceNonNeg(prices, 0);
  DpNonNeg(i, i - 1, dp);
  assert 0 <= prices[0];
  assert 0 <= dp[i - 1];
  NonnegAdd(prices[0], dp[i - 1]);
  best := prices[0] + dp[i - 1];
  bestJ := 1;
  ElemEq(prices, 0);
  ElemEq(dp, i - 1);
  assert Elem(prices, 0) == prices[0];
  assert Elem(dp, i - 1) == dp[i - 1];
  assert best == prices[0] + dp[i - 1];
  assert best == Elem(prices, 0) + Elem(dp, i - 1);
  assert bestJ - 1 == 0;
  assert i - bestJ == i - 1;
  assert best == prices[bestJ - 1] + dp[i - bestJ];
  assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
  assert 0 <= best;
  assert 0 <= bestJ - 1 < |prices|;
  assert 0 <= i - bestJ < |dp|;

  var j := 2;
  assert j == 2;
  assert 2 <= j <= i + 1;
  assert 0 <= i - j + 1;
  assert 1 <= bestJ < j;

  forall k | 1 <= k < j
    ensures best >= Elem(prices, k - 1) + Elem(dp, i - k)
  {
    assert k == 1;
    assert Elem(prices, k - 1) == Elem(prices, 0);
    assert Elem(dp, i - k) == Elem(dp, i - 1);
    assert best == Elem(prices, k - 1) + Elem(dp, i - k);
    assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
  }
  assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
    best >= Elem(prices, k - 1) + Elem(dp, i - k);

  while j <= i
    invariant 2 <= j <= i + 1
    invariant 0 <= i - j + 1
    invariant 1 <= bestJ < j
    invariant 0 <= best
    invariant 0 <= bestJ - 1 < |prices|
    invariant 0 <= i - bestJ < |dp|
    invariant best == prices[bestJ - 1] + dp[i - bestJ]
    invariant best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ)
    invariant forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j ==>
                best >= Elem(prices, k - 1) + Elem(dp, i - k)
    decreases i + 1 - j
  {
    var j0 := j;
    var oldBest := best;
    var oldBestJ := bestJ;
    assert j0 == j;
    assert oldBest == best;
    assert oldBestJ == bestJ;
    assert 1 <= j0 <= i;
    assert 1 <= oldBestJ < j0;
    assert oldBest == prices[oldBestJ - 1] + dp[i - oldBestJ];
    assert oldBest == Elem(prices, oldBestJ - 1) + Elem(dp, i - oldBestJ);
    assert 0 <= oldBest;
    assert 0 <= oldBestJ - 1 < |prices|;
    assert 0 <= i - oldBestJ < |dp|;

    forall k | 1 <= k < j0
      ensures oldBest >= Elem(prices, k - 1) + Elem(dp, i - k)
    {
      assert 1 <= k < j;
      assert best >= Elem(prices, k - 1) + Elem(dp, i - k);
      assert oldBest == best;
    }
    assert forall k {:trigger Elem(prices, k - 1)} :: 1 <= k < j0 ==>
      oldBest >= Elem(prices, k - 1) + Elem(dp, i - k);

    assert 0 <= j0 - 1 < |prices|;
    assert 0 <= i - j0 < i;
    assert 0 <= i - j0 < |dp|;
    PriceNonNeg(prices, j0 - 1);
    DpNonNeg(i, i - j0, dp);
    assert 0 <= prices[j0 - 1];
    assert 0 <= dp[i - j0];
    NonnegAdd(prices[j0 - 1], dp[i - j0]);
    var cand := prices[j0 - 1] + dp[i - j0];
    ElemEq(prices, j0 - 1);
    ElemEq(dp, i - j0);
    assert Elem(prices, j0 - 1) == prices[j0 - 1];
    assert Elem(dp, i - j0) == dp[i - j0];
    assert cand == Elem(prices, j0 - 1) + Elem(dp, i - j0);
    assert 0 <= cand;

    if cand > oldBest {
      best := cand;
      bestJ := j0;
      assert best == cand;
      assert bestJ == j0;
      assert best == prices[j0 - 1] + dp[i - j0];
      assert prices[bestJ - 1] == prices[j0 - 1];
      assert dp[i - bestJ] == dp[i - j0];
      assert best == prices[bestJ - 1] + dp[i - bestJ];
      assert Elem(prices, bestJ - 1) == Elem(prices, j0 - 1);
      assert Elem(dp, i - bestJ) == Elem(dp, i - j0);
      assert best == Elem(prices, bestJ - 1) + Elem(dp, i - bestJ);
      assert best > oldBest;
      assert best >= oldBest;
      assert best >= cand;
      assert 0 <= best;
      assert 1 <= bestJ <= j0;
      assert 0 <= bestJ - 1 < |prices|;
      assert 0 <= i - bestJ < |dp|;
    } else {
      assert cand <= oldBest;
      best := oldBest;
      bestJ := oldBestJ;
      assert best == oldBest;
      assert bestJ == oldBestJ;
