lemma {:induction false} Structural(node: Node)
  requires node.is_segment_tree()
  ensures 0 <= node.low < node.high
  ensures 0 <= node.val
  ensures match (node.left, node.right) {
    case (Some(l), Some(r)) =>
      var mid := (node.low + node.high) / 2;
      l.low == node.low && l.high == mid &&
      r.low == mid && r.high == node.high &&
      l.is_segment_tree() && r.is_segment_tree() &&
      node.val == (if l.val > r.val then l.val else r.val)
    case (None, None) =>
      node.high == node.low + 1
    case _ =>
      false
  }
{
  assert 0 <= node.low < node.high;
  assert 0 <= node.val;
  assert match (node.left, node.right) {
    case (Some(l), Some(r)) =>
      var mid := (node.low + node.high) / 2;
      l.low == node.low && l.high == mid &&
      r.low == mid && r.high == node.high &&
      l.is_segment_tree() && r.is_segment_tree() &&
      node.val == (if l.val > r.val then l.val else r.val)
    case (None, None) =>
      node.high == node.low + 1
    case _ =>
      false
  };
}

lemma {:induction false} {:vcs_split_on_every_assert} EvalView(node: Node)
  ensures node.left.None? && node.right.None? ==> node.view() == map[node.low := node.val]
  ensures node.left.Some? && node.right.Some? ==>
    node.view() == node.left.value.view() + node.right.value.view()
{
  var left_view := match node.left {
    case Some(ll) => ll.view()
    case None => map[]
  };
  var right_view := match node.right {
    case Some(rr) => rr.view()
    case None => map[]
  };
  assert node.view() == (
    if node.left.None? && node.right.None? then
      map[node.low := node.val]
    else
      left_view + right_view
  );
  if node.left.None? && node.right.None? {
    assert node.view() == map[node.low := node.val];
  }
  if node.left.Some? && node.right.Some? {
    assert !(node.left.None? && node.right.None?);
    assert node.view() == left_view + right_view;
    match node.left {
      case Some(ll) =>
        assert ll == node.left.value;
        assert left_view == ll.view();
      case None =>
        assert false;
    }
    match node.right {
      case Some(rr) =>
        assert rr == node.right.value;
        assert right_view == rr.view();
      case None =>
