ghost predicate Sieved(primes: seq<bool>, n: int, d: int)
  requires |primes| == n
{
  forall i {:trigger primes[i]} :: 0 <= i < n ==> primes[i] == Unmarked(i, d)
}

ghost predicate MarkedUpTo(primes: seq<bool>, oldPrimes: seq<bool>, n: int, d: int, j: int)
  requires |primes| == n
  requires |oldPrimes| == n
  requires d > 0
{
  forall i {:trigger primes[i]} :: 0 <= i < n ==>
    primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i])
}

lemma {:vcs_split_on_every_assert} UnmarkedStep(i: int, d: int, dNext: int)
  requires d >= 2
  requires dNext == d + 1
  ensures Unmarked(i, dNext) <==> (Unmarked(i, d) && (d < i ==> !divides(d, i)))
{
  assert Unmarked(i, dNext) ==> (Unmarked(i, d) && (d < i ==> !divides(d, i))) by {
    if Unmarked(i, dNext) {
      assert i > 1;
      forall k | 2 <= k < d && k < i
        ensures !divides(k, i)
      {
        assert k < d;
        assert d < dNext;
        assert k < dNext;
        assert 2 <= k < dNext && k < i;
        assert !divides(k, i);
      }
      assert Unmarked(i, d);
      if d < i {
        assert 2 <= d;
        assert d < dNext;
        assert 2 <= d < dNext && d < i;
        assert !divides(d, i);
      }
      assert d < i ==> !divides(d, i);
      assert Unmarked(i, d) && (d < i ==> !divides(d, i));
    }
  };
  assert (Unmarked(i, d) && (d < i ==> !divides(d, i))) ==> Unmarked(i, dNext) by {
    if Unmarked(i, d) && (d < i ==> !divides(d, i)) {
      assert i > 1;
      forall k | 2 <= k < dNext && k < i
        ensures !divides(k, i)
      {
        if k < d {
          assert 2 <= k < d && k < i;
          assert !divides(k, i);
        } else {
          assert k >= d;
          assert k < dNext;
          assert dNext == d + 1;
          assert k == d;
          assert d < i;
          assert !divides(d, i);
          assert !divides(k, i);
        }
      }
      assert Unmarked(i, dNext);
    }
  };
}

lemma {:vcs_split_on_every_assert} UnmarkedIsPrime(i: int, bound: int)
  requires i < bound
  ensures Unmarked(i, bound) == is_prime(i)
{
  if i <= 1 {
    assert !(i > 1);
    assert !Unmarked(i, bound);
    assert !is_prime(i);
    assert Unmarked(i, bound) == is_prime(i);
  } else {
    assert Unmarked(i, bound) ==> is_prime(i) by {
      if Unmarked(i, bound) {
        assert i > 1;
        forall m | 1 < m < i
          ensures !divides(m, i)
        {
          assert 2 <= m;
          assert m < i < bound;
          assert 2 <= m < bound && m < i;
          assert !divides(m, i);
        }
        assert is_prime(i);
      }
    };
    assert is_prime(i) ==> Unmarked(i, bound) by {
      if is_prime(i) {
        assert i > 1;
        forall k | 2 <= k < bound && k < i
          ensures !divides(k, i)
        {
          assert 1 < k < i;
          assert !divides(k, i);
        }
        assert Unmarked(i, bound);
      }
    };
    assert Unmarked(i, bound) == is_prime(i);
  }
}

lemma {:vcs_split_on_every_assert} InitCorrect(n: int, primes: seq<bool>, d: int)
  requires 0 <= n
  requires |primes| == n
  requires d == 2
  requires forall i :: 0 <= i < n ==> primes[i] == (i >= 2)
  ensures Sieved(primes, n, d)
{
  forall i | 0 <= i < n
    ensures primes[i] == Unmarked(i, d)
  {
