    if i > 1 {
      assert i >= 2;
      assert primes[i] == true;
      forall k | 2 <= k < d && k < i
        ensures !divides(k, i)
      {
        assert d == 2;
        assert 2 <= k < 2;
        assert false;
      }
      assert i > 1;
      assert Unmarked(i, d);
      assert primes[i] == Unmarked(i, d);
    } else {
      assert i <= 1;
      assert !(i > 1);
      assert !Unmarked(i, d);
