lemma {:vcs_split_on_every_assert} InnerStep(
  n: int,
  d: int,
  j: int,
  jNext: int,
  oldPrimes: seq<bool>,
  pre: seq<bool>,
  primes: seq<bool>
)
  requires 2 <= d
  requires 0 <= n
  requires 0 <= j < n
  requires 2 * d <= j
  requires j % d == 0
  requires jNext == j + d
  requires |oldPrimes| == n
  requires |pre| == n
  requires |primes| == n
  requires primes == pre[j := false]
  requires MarkedUpTo(pre, oldPrimes, n, d, j)
  ensures MarkedUpTo(primes, oldPrimes, n, d, jNext)
{
  assert d > 0;
  assert jNext == j + d;
  assert j < jNext;

  forall i | 0 <= i < n
    ensures primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i])
  {
    assert primes[j] == false;
    if i == j {
      assert 2 * d <= i;
      assert i < jNext;
      assert i % d == 0;
      assert 2 * d <= i < jNext && i % d == 0;
      assert primes[i] == false;
      assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
    } else if 2 * d <= i < j && i % d == 0 {
      assert primes[i] == pre[i];
      assert pre[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
      assert pre[i] == false;
      assert primes[i] == false;
      assert i < jNext;
      assert 2 * d <= i < jNext && i % d == 0;
      assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
    } else {
      assert i != j;
      assert primes[i] == pre[i];
      if 2 * d <= i < jNext && i % d == 0 {
        if i < j {
          assert 2 * d <= i < j && i % d == 0;
          assert false;
        } else {
          assert j <= i;
          assert i != j;
          assert j < i;
          assert i < jNext;
          assert i < j + d;
          NoMultipleInBetween(j, i, d);
          assert i % d != 0;
          assert false;
        }
      } else {
        assert !(2 * d <= i < jNext && i % d == 0);
        if 2 * d <= i < j && i % d == 0 {
          assert i < jNext;
          assert 2 * d <= i < jNext && i % d == 0;
          assert false;
        }
        assert !(2 * d <= i < j && i % d == 0);
        assert pre[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
        assert pre[i] == oldPrimes[i];
        assert primes[i] == oldPrimes[i];
        assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
      }
    }
  }
  assert MarkedUpTo(primes, oldPrimes, n, d, jNext);
}

lemma {:vcs_split_on_every_assert} AfterMarking(
  n: int,
  d: int,
  dNext: int,
  oldPrimes: seq<bool>,
  primes: seq<bool>,
  j: int
)
  requires 2 <= d
  requires 0 <= n
  requires |oldPrimes| == n
  requires |primes| == n
  requires j >= n
  requires dNext == d + 1
  requires Sieved(oldPrimes, n, d)
  requires MarkedUpTo(primes, oldPrimes, n, d, j)
  ensures Sieved(primes, n, dNext)
{
  forall i | 0 <= i < n
    ensures primes[i] == Unmarked(i, dNext)
  {
    assert i < n <= j;
    assert i < j;
    assert oldPrimes[i] == Unmarked(i, d);
    assert primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
    UnmarkedStep(i, d, dNext);

    if 2 * d <= i && i % d == 0 {
      assert 2 * d <= i < j && i % d == 0;
      assert primes[i] == false;
      DivModEquiv(d, i);
      assert divides(d, i);
      assert d > 0;
      assert d < 2 * d;
      assert d < i;
      assert Unmarked(i, dNext) == (Unmarked(i, d) && (d < i ==> !divides(d, i)));
      assert divides(d, i);
      assert !(d < i ==> !divides(d, i));
      assert !Unmarked(i, dNext);
      assert primes[i] == Unmarked(i, dNext);
    } else {
      assert !(2 * d <= i && i % d == 0);
      assert !(2 * d <= i < j && i % d == 0);
      assert primes[i] == oldPrimes[i];
      if d < i && divides(d, i) {
        DivModEquiv(d, i);
        assert i % d == 0;
        MultipleAtLeastTwice(d, i);
        assert 2 * d <= i && i % d == 0;
        assert false;
      }
      assert !(d < i && divides(d, i));
      assert d < i ==> !divides(d, i);
      assert Unmarked(i, dNext) == (Unmarked(i, d) && (d < i ==> !divides(d, i)));
      assert Unmarked(i, dNext) == Unmarked(i, d);
      assert primes[i] == Unmarked(i, d);
      assert primes[i] == Unmarked(i, dNext);
    }
  }
  assert Sieved(primes, n, dNext);
}

lemma {:vcs_split_on_every_assert} AllPrime(n: int, primes: seq<bool>, d: int)
