  }
}

method {:vcs_split_on_every_assert} sieve_of_eratosthenes(n: int) returns (primes: seq<bool>)
  // Simulate usize (non-negative) and bound constraint
  requires 0 <= n <= 100_000

  ensures |primes| == n
  // Functional Correctness:
  // Dafny automatically triggers on primes[i] here because it appears in the body.
  ensures forall i :: 0 <= i < n ==> primes[i] == is_prime(i)
{
  primes := seq(n, i => i >= 2);
  assert |primes| == n;
  assert forall i :: 0 <= i < n ==> primes[i] == (i >= 2);

  var d := 2;
  InitCorrect(n, primes, d);
  assert Sieved(primes, n, d);

  while d < n
    invariant 2 <= d
    invariant |primes| == n
    invariant Sieved(primes, n, d)
    decreases n - d
  {
    ghost var oldPrimes := primes;
    assert oldPrimes == primes;
    assert |oldPrimes| == n;
    assert Sieved(oldPrimes, n, d);

    var j := 2 * d;
    assert d > 0;
    assert j == 2 * d;
    assert j >= 4;
    assert j >= 0;
    assert 0 <= 0 < d;
    assert j == 2 * d + 0;
    ModUnique(j, d, 2, 0);
    assert j % d == 0;
    assert 2 * d <= j;

    forall i | 0 <= i < n
      ensures primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i])
    {
      assert j == 2 * d;
      assert !(2 * d <= i < j);
      assert primes[i] == oldPrimes[i];
      assert primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
    }
    assert MarkedUpTo(primes, oldPrimes, n, d, j);

    while j < n
      invariant 2 <= d
      invariant 0 <= j
      invariant 2 * d <= j
      invariant j % d == 0
      invariant |primes| == n
      invariant |oldPrimes| == n
      invariant MarkedUpTo(primes, oldPrimes, n, d, j)
      decreases n - j
    {
      ghost var pre := primes;
      assert pre == primes;
      assert |pre| == n;
      forall i | 0 <= i < n
        ensures pre[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i])
      {
        assert primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
        assert pre[i] == primes[i];
      }
      assert MarkedUpTo(pre, oldPrimes, n, d, j);

      primes := primes[j := false];
      assert primes == pre[j := false];
      assert |primes| == n;

      var jNext := j + d;
      assert jNext == j + d;
      InnerStep(n, d, j, jNext, oldPrimes, pre, primes);
      assert MarkedUpTo(primes, oldPrimes, n, d, jNext);

      AddMultiple(j, d, jNext);
      assert jNext % d == 0;
      assert jNext == j + d;
      assert d >= 2;
      assert jNext >= j;
      assert 2 * d <= jNext;
      assert 0 <= jNext;
      j := jNext;
    }

    assert j >= n;
    assert Sieved(oldPrimes, n, d);
    assert MarkedUpTo(primes, oldPrimes, n, d, j);

    var dNext := d + 1;
    assert dNext == d + 1;
    AfterMarking(n, d, dNext, oldPrimes, primes, j);
    assert Sieved(primes, n, dNext);
    assert |primes| == n;
    assert 2 <= dNext;
    d := dNext;
  }

  assert d >= n;
  assert |primes| == n;
  assert Sieved(primes, n, d);
  AllPrime(n, primes, d);
}
