lemma {:induction false} {:vcs_split_on_every_assert} NotInView(node: Node, k: int)
  requires node.is_segment_tree()
  requires k < node.low || node.high <= k
  ensures k !in node.view()
  decreases node.high - node.low
{
  if node.left.None? && node.right.None? {
    OpenLeaf(node);
    assert node.high == node.low + 1;
    assert node.view() == map[node.low := node.val];
    if k < node.low {
      assert k != node.low;
    } else {
      assert node.high <= k;
      assert node.low + 1 <= k;
      assert k != node.low;
    }
    assert k !in map[node.low := node.val];
    assert k !in node.view();
  } else {
    BothSome(node);
    OpenInternal(node);
    var l := node.left.value;
    var r := node.right.value;
    var mid := (node.low + node.high) / 2;
    assert l.low == node.low && l.high == mid;
    assert r.low == mid && r.high == node.high;
    assert 0 <= l.high - l.low < node.high - node.low;
    assert 0 <= r.high - r.low < node.high - node.low;
    if k < node.low {
      assert k < l.low;
      assert node.low < mid;
      assert k < r.low;
      NotInView(l, k);
      NotInView(r, k);
    } else {
      assert node.high <= k;
      assert mid < node.high;
      assert l.high <= k;
      assert r.high <= k;
      NotInView(l, k);
      NotInView(r, k);
    }
    assert k !in l.view();
    assert k !in r.view();
    assert node.view() == l.view() + r.view();
