lemma {:induction false} Pick(n: Node, a: int, b: int, res: int) returns (k: int)
  requires n.is_segment_tree()
  requires n.low <= a < b <= n.high
  requires exists i :: a <= i < b && n.view()[i] == res
  ensures a <= k < b
  ensures k in n.view()
  ensures n.view()[k] == res
{
  forall i | a <= i < b
    ensures i in n.view()
  {
    assert n.low <= i < n.high;
    InView(n, i);
