  ensures k in node.view()
  ensures node.view()[k] == node.val
  decreases node.high - node.low
{
  if node.left.None? && node.right.None? {
    OpenLeaf(node);
    k := node.low;
    assert node.high == node.low + 1;
    assert node.low <= k < node.high;
    assert k in node.view();
    assert node.view()[k] == node.val;
  } else {
    BothSome(node);
    OpenInternal(node);
    var l := node.left.value;
    var r := node.right.value;
    var mid := (node.low + node.high) / 2;
    assert node.val == (if l.val > r.val then l.val else r.val);
    assert node.low < mid < node.high;
