}

lemma {:induction false} ProperSubrange(low: int, high: int, ql: int, qr: int)
  requires low <= ql < qr <= high
  requires !(ql == low && qr == high)
  ensures high >= low + 2
{
  assert low < high;
  assert high >= low + 1;
  if high == low + 1 {
    assert low <= ql;
    assert ql < qr;
    assert qr <= low + 1;
    assert ql + 1 <= qr;
    assert ql + 1 <= low + 1;
    assert ql <= low;
    assert ql == low;
    assert low + 1 <= qr;
    assert qr <= low + 1;
    assert qr == low + 1;
    assert qr == high;
    assert ql == low && qr == high;
    assert false;
  }
  assert high != low + 1;
  assert high >= low + 2;
}

