}

method {:vcs_split_on_every_assert} query(node: Node, ql: int, qr: int) returns (res: int)
  requires node.is_segment_tree()
  requires ql < qr
  requires node.low <= ql
  requires qr <= node.high
  ensures res >= 0
  // Correctness: result is >= everything in the query range
  ensures forall k :: ql <= k < qr ==> node.view()[k] <= res
  // Tightness: result actually exists in the query range
  ensures exists k :: ql <= k < qr && node.view()[k] == res
  decreases node.high - node.low
{
  if ql == node.low && qr == node.high {
    Structural(node);
    assert 0 <= node.val;
    res := node.val;
    assert res >= 0;
    ghost var w := PickFull(node);
    assert node.low <= w < node.high;
    assert w in node.view();
    assert node.view()[w] == node.val;
    assert ql <= w < qr;
    assert node.view()[w] == res;
    forall i | ql <= i < qr
      ensures node.view()[i] <= res
    {
      assert node.low <= i < node.high;
      InView(node, i);
      assert node.view()[i] <= node.val;
      assert node.view()[i] <= res;
    }
    assert exists j :: ql <= j < qr && node.view()[j] == res;
  } else {
    ProperSubrange(node.low, node.high, ql, qr);
    assert node.high >= node.low + 2;
    InternalFromSpan(node);
    assert node.left.Some? && node.right.Some?;
    var l := node.left.value;
    var r := node.right.value;
    OpenInternal(node);
    var mid := (node.low + node.high) / 2;
    assert l == node.left.value && r == node.right.value;
    assert l.is_segment_tree() && r.is_segment_tree();
    assert l.low == node.low && l.high == mid;
    assert r.low == mid && r.high == node.high;
    assert node.low < mid < node.high;
    assert 0 <= l.high - l.low < node.high - node.low;
    assert 0 <= r.high - r.low < node.high - node.low;

    if qr <= mid {
      assert l.low <= ql;
      assert ql < qr;
      assert qr <= l.high;
      res := query(l, ql, qr);
      assert res >= 0;
      forall i | ql <= i < qr
        ensures node.view()[i] <= res
      {
        assert node.low <= i;
        assert i < qr;
        assert i < mid;
        assert node.low <= i < mid;
        AgreeLeft(node, i);
        assert node.view()[i] == l.view()[i];
        assert l.view()[i] <= res;
        assert node.view()[i] <= res;
      }
      assert l.is_segment_tree();
      assert l.low <= ql < qr <= l.high;
      assert exists i :: ql <= i < qr && l.view()[i] == res;
      ghost var w := Pick(l, ql, qr, res);
      assert ql <= w < qr;
      assert w in l.view();
      assert node.low <= w < mid;
      assert l.view()[w] == res;
      AgreeLeft(node, w);
      assert node.view()[w] == l.view()[w];
      assert node.view()[w] == res;
      assert exists j :: ql <= j < qr && node.view()[j] == res;
    } else if mid <= ql {
      assert r.low <= ql;
      assert ql < qr;
      assert qr <= r.high;
      res := query(r, ql, qr);
      assert res >= 0;
      forall i | ql <= i < qr
        ensures node.view()[i] <= res
      {
        assert mid <= ql <= i;
        assert i < qr <= node.high;
        assert mid <= i < node.high;
        AgreeRight(node, i);
        assert node.view()[i] == r.view()[i];
        assert r.view()[i] <= res;
        assert node.view()[i] <= res;
      }
      assert r.is_segment_tree();
      assert r.low <= ql < qr <= r.high;
      assert exists i :: ql <= i < qr && r.view()[i] == res;
      ghost var w := Pick(r, ql, qr, res);
      assert ql <= w < qr;
      assert w in r.view();
      assert mid <= w < node.high;
      assert r.view()[w] == res;
      AgreeRight(node, w);
      assert node.view()[w] == r.view()[w];
      assert node.view()[w] == res;
      assert exists j :: ql <= j < qr && node.view()[j] == res;
    } else {
      assert ql < mid;
      assert mid < qr;
      assert l.low <= ql && mid <= l.high;
      assert r.low <= mid && qr <= r.high;
      var leftRes := query(l, ql, mid);
      var rightRes := query(r, mid, qr);
      assert leftRes >= 0;
      assert rightRes >= 0;
      if leftRes >= rightRes {
        res := leftRes;
        assert res >= 0;
        assert rightRes <= res;
        forall i | ql <= i < qr
          ensures node.view()[i] <= res
        {
          if i < mid {
            assert ql <= i < mid;
            assert node.low <= i < mid;
            AgreeLeft(node, i);
            assert node.view()[i] == l.view()[i];
            assert l.view()[i] <= leftRes;
            assert node.view()[i] <= res;
          } else {
            assert mid <= i < qr;
            assert mid <= i < node.high;
            AgreeRight(node, i);
            assert node.view()[i] == r.view()[i];
            assert r.view()[i] <= rightRes;
            assert rightRes <= res;
            assert node.view()[i] <= res;
          }
        }
        assert l.is_segment_tree();
        assert l.low <= ql < mid <= l.high;
        assert exists i :: ql <= i < mid && l.view()[i] == leftRes;
        ghost var w := Pick(l, ql, mid, leftRes);
        assert ql <= w < mid;
        assert w in l.view();
        assert node.low <= w < mid;
        assert l.view()[w] == leftRes;
        AgreeLeft(node, w);
        assert node.view()[w] == l.view()[w];
        assert node.view()[w] == res;
        assert w < qr;
        assert ql <= w < qr;
        assert exists j :: ql <= j < qr && node.view()[j] == res;
      } else {
        res := rightRes;
        assert leftRes < rightRes;
        assert res >= 0;
        assert leftRes <= res;
        forall i | ql <= i < qr
          ensures node.view()[i] <= res
        {
          if i < mid {
            assert ql <= i < mid;
            assert node.low <= i < mid;
            AgreeLeft(node, i);
            assert node.view()[i] == l.view()[i];
            assert l.view()[i] <= leftRes;
            assert leftRes <= res;
            assert node.view()[i] <= res;
          } else {
            assert mid <= i < qr;
            assert mid <= i < node.high;
            AgreeRight(node, i);
            assert node.view()[i] == r.view()[i];
            assert r.view()[i] <= rightRes;
            assert node.view()[i] <= res;
          }
        }
        assert r.is_segment_tree();
        assert r.low <= mid < qr <= r.high;
        assert exists i :: mid <= i < qr && r.view()[i] == rightRes;
        ghost var w := Pick(r, mid, qr, rightRes);
        assert mid <= w < qr;
        assert w in r.view();
        assert mid <= w < node.high;
        assert r.view()[w] == rightRes;
        AgreeRight(node, w);
        assert node.view()[w] == r.view()[w];
        assert node.view()[w] == res;
        assert ql <= w;
        assert ql <= w < qr;
        assert exists j :: ql <= j < qr && node.view()[j] == res;
      }
    }
  }
}
