method splay(tree: Tree, v: int) returns (res: Tree)
    // tree is Box<Node>, so it cannot be Empty
    requires tree.Node?
    requires is_bst(tree)
    // res is Box<Node>, so it cannot be Empty
    ensures res.Node?
    ensures is_bst(res)
    ensures view(res) == view(tree)
    // Postcondition: If v was in the tree, it is now at the root.
    ensures v in view(tree) ==> res.val == v
    // Postcondition: If v was NOT in the tree, the new root is 
    // the last node accessed (implicitly true if res.Node?, but kept for fidelity)
    ensures v !in view(tree) ==> res.val in view(res)
    decreases tree
{
    var x := tree.val;
    var l := tree.left;
    var r := tree.right;
    assert view(tree) == view(l) + view(r) + {x};
    if v == x {
        res := tree;
    } else if v < x {
        if l.Empty? {
            assert v in view(tree) ==> v in view(r);
            res := tree;
        } else {
            assert v in view(tree) ==> v in view(l);
            var l2 := splay(l, v);
            var y := l2.val;
            var a := l2.left;
            var b := l2.right;
            assert view(l2) == view(a) + view(b) + {y};
            assert y in view(l);
            assert y < x;
            assert forall z :: z in view(b) ==> z in view(l);
            assert forall z :: z in view(b) ==> z < x;
            var t := Node(x, b, r);
            assert view(t) == view(b) + view(r) + {x};
            assert is_bst(t);
            assert forall z :: z in view(r) ==> z > y;
            assert forall z :: z in view(t) ==> z > y;
            res := Node(y, a, t);
            assert view(res) == view(a) + view(t) + {y};
            assert is_bst(res);
        }
    } else {
        if r.Empty? {
            assert v in view(tree) ==> v in view(l);
            res := tree;
        } else {
            assert v in view(tree) ==> v in view(r);
            var r2 := splay(r, v);
            var y := r2.val;
            var a := r2.left;
            var b := r2.right;
            assert view(r2) == view(a) + view(b) + {y};
            assert y in view(r);
            assert y > x;
            assert forall z :: z in view(a) ==> z in view(r);
            assert forall z :: z in view(a) ==> z > x;
            var t := Node(x, l, a);
            assert view(t) == view(l) + view(a) + {x};
            assert is_bst(t);
            assert forall z :: z in view(l) ==> z < y;
            assert forall z :: z in view(t) ==> z < y;
            res := Node(y, t, b);
            assert view(res) == view(t) + view(b) + {y};
            assert is_bst(res);
        }
    }
