    ensures view(lo) <= view(t)
    ensures view(hi) <= view(t)
    ensures forall x :: x in view(lo) ==> x < key
    ensures forall x :: x in view(hi) ==> x > key
    decreases t
{
    match t
    case Empty =>
        lo := Empty;
        found := false;
        hi := Empty;

