method {:vcs_split_on_every_assert} splay(tree: Tree, v: int) returns (res: Tree)
  requires tree.Node?
  requires is_bst(tree)
  ensures res.Node?
  ensures is_bst(res)
  ensures view(res) == view(tree)
  ensures v in view(tree) ==> res.val == v
  ensures v !in view(tree) ==> res.val in view(res)
  decreases tree
{
  if v == tree.val {
    res := tree;
    assert res == tree;
    assert res.Node?;
    assert is_bst(res);
    assert view(res) == view(tree);
    RootInView(res);
    assert res.val in view(res);
    assert res.val == v;
    assert v in view(tree) ==> res.val == v;
  } else if v < tree.val {
    BstSplitLeft(tree, v);
    if tree.left.Empty? {
      res := tree;
      ViewEmpty(tree.left);
      assert view(tree.left) == {};
      assert v !in {};
      assert v !in view(tree.left);
      assert v !in view(tree) by {
        if v in view(tree) {
          assert v in view(tree.left);
          assert false;
        }
      };
      assert res.Node?;
      assert is_bst(res);
      assert view(res) == view(tree);
      RootInView(res);
      assert res.val in view(res);
      assert v in view(tree) ==> res.val == v;
    } else {
      assert tree.left.Node?;
      ExtractBst(tree);
      var leftS := splay(tree.left, v);
      assert leftS.Node?;
      assert is_bst(leftS);
      assert view(leftS) == view(tree.left);
      assert forall x :: x in view(tree.left) ==> x < tree.val;
      TransferLt(view(leftS), view(tree.left), tree.val);
      assert forall x :: x in view(leftS) ==> x < tree.val;
      assert forall x :: x in view(tree.right) ==> x > tree.val;
      assert is_bst(tree.right);
      RotateRightOk(leftS, tree.val, tree.right);
      res := Node(leftS.val, leftS.left, Node(tree.val, leftS.right, tree.right));
      assert res.Node?;
      assert is_bst(res);
      assert view(res) == view(leftS) + view(tree.right) + {tree.val};
      UnionCong(view(leftS), view(tree.left), view(tree.right), {tree.val});
      assert view(res) == view(tree.left) + view(tree.right) + {tree.val};
      assert view(tree) == view(tree.left) + view(tree.right) + {tree.val};
      assert view(res) == view(tree);
      assert (v in view(tree)) ==> res.val == v by {
        if v in view(tree) {
          assert v in view(tree.left);
          assert v in view(tree.left) ==> leftS.val == v;
          assert leftS.val == v;
          assert res.val == leftS.val;
          assert res.val == v;
        }
      };
      RootInView(res);
      assert res.val in view(res);
    }
  } else {
    assert v > tree.val;
    BstSplitRight(tree, v);
    if tree.right.Empty? {
      res := tree;
      ViewEmpty(tree.right);
      assert view(tree.right) == {};
      assert v !in {};
      assert v !in view(tree.right);
      assert v !in view(tree) by {
        if v in view(tree) {
          assert v in view(tree.right);
          assert false;
        }
      };
      assert res.Node?;
      assert is_bst(res);
      assert view(res) == view(tree);
      RootInView(res);
      assert res.val in view(res);
      assert v in view(tree) ==> res.val == v;
    } else {
      assert tree.right.Node?;
