      assert is_bst(rightS);
      assert view(rightS) == view(tree.right);
      assert forall x :: x in view(tree.right) ==> x > tree.val;
      TransferGt(view(rightS), view(tree.right), tree.val);
      assert forall x :: x in view(rightS) ==> x > tree.val;
      assert forall x :: x in view(tree.left) ==> x < tree.val;
      assert is_bst(tree.left);
      RotateLeftOk(rightS, tree.val, tree.left);
