  } else {
    assert k >= 2;
    MulGe(k - 1, d);
    MulSuccLeft(k - 1, d);
    assert k == (k - 1) + 1;
    assert ((k - 1) + 1) * d == (k - 1) * d + d;
    assert k * d == (k - 1) * d + d;
    assert (k - 1) * d >= d;
    assert (k - 1) * d + d >= d + d;
    assert k * d >= d + d;
    assert d + d >= d;
    assert k * d >= d;
  }
}

lemma {:induction false} {:vcs_split_on_every_assert} MulLe(k: int, d: int)
  requires d > 0
  requires k <= -1
  ensures k * d <= -d
  decreases -k
{
  if k == -1 {
    NegMul(d);
    assert k * d == (-1) * d;
    assert (-1) * d == -d;
    assert k * d <= -d;
  } else {
    assert k <= -2;
    MulLe(k + 1, d);
    SubDist(k + 1, 1, d);
    assert ((k + 1) - 1) * d == (k + 1) * d - 1 * d;
    OneMul(d);
    assert 1 * d == d;
    assert (k + 1) * d - 1 * d == (k + 1) * d - d;
    assert k == (k + 1) - 1;
    assert k * d == (k + 1) * d - d;
    assert (k + 1) * d <= -d;
    assert k * d <= -d - d;
    assert -d - d <= -d;
    assert k * d <= -d;
  }
}

lemma {:induction false} {:vcs_split_on_every_assert} ModUnique(x: int, d: int, q: int, r: int)
  requires d > 0
  requires x >= 0
  requires 0 <= r < d
  requires x == q * d + r
  ensures x / d == q
  ensures x % d == r
{
  assert 0 <= x % d < d;
  assert x == (x / d) * d + (x % d);
  var rr := x % d;
  var qq := x / d;
  var diff := rr - r;

  assert 0 <= rr;
  assert rr < d;
  assert rr <= d - 1;
  assert 0 <= r;
  assert r <= d - 1;
  assert diff >= 0 - (d - 1);
  assert diff <= (d - 1) - 0;
  assert 0 - (d - 1) == 1 - d;
  assert 1 - d == (-d) + 1;
  assert diff >= (-d) + 1;
  assert diff <= d - 1;
  assert diff < d;
  assert diff > -d;

  assert q * d + r == qq * d + rr;
  assert q * d - qq * d == rr - r;
  SubDist(q, qq, d);
  assert (q - qq) * d == q * d - qq * d;
  assert q * d - qq * d == diff;
  assert (q - qq) * d == diff;

  var k := q - qq;
  assert k * d == diff;

  if k >= 1 {
    MulGe(k, d);
    assert k * d >= d;
    assert diff >= d;
    assert diff < d;
    assert false;
    assert k == 0;
    assert diff == 0;
  } else if k <= -1 {
    MulLe(k, d);
    assert k * d <= -d;
    assert diff <= -d;
    assert diff >= (-d) + 1;
    assert false;
    assert k == 0;
    assert diff == 0;
  } else {
    assert k == 0;
    ZeroMul(d);
    assert k * d == 0 * d;
    assert 0 * d == 0;
    assert diff == 0;
  }
  assert k == 0;
  assert diff == 0;
  assert rr - r == 0;
  assert rr == r;
  assert x % d == r;
  assert qq == q;
  assert x / d == q;
}

lemma {:induction false} Twice(d: int)
  ensures 2 * d == d + d
{
  MulSuccLeft(1, d);
  assert (1 + 1) * d == 1 * d + d;
  OneMul(d);
  assert 1 * d == d;
  assert 1 + 1 == 2;
  assert (1 + 1) * d == 2 * d;
  assert 2 * d == d + d;
}

lemma {:induction false} GtTwice(d: int)
  requires d > 0
  ensures d < 2 * d
{
  Twice(d);
  assert 2 * d == d + d;
  assert 0 < d;
  assert d + 0 < d + d;
  assert d < d + d;
  assert d < 2 * d;
}

lemma {:induction false} DivEq(d: int, n: int)
  requires d != 0
  ensures divides(d, n) == (n % d == 0)
{
  assert divides(d, n) == (n % d == 0);
}

lemma {:induction false} {:vcs_split_on_every_assert} AddMultiple(j: int, d: int, jNext: int)
  requires d > 0
  requires j >= 0
  requires j % d == 0
  requires jNext == j + d
  ensures jNext % d == 0
{
  assert j == (j / d) * d + (j % d);
  assert j % d == 0;
  assert j == (j / d) * d;
  var q := j / d;
  MulSuccLeft(q, d);
  assert (q + 1) * d == q * d + d;
  assert jNext == j + d;
  assert j + d == q * d + d;
  assert jNext == q * d + d;
  assert jNext == (q + 1) * d;
  assert jNext == (q + 1) * d + 0;
  assert j >= 0;
  assert d > 0;
  assert jNext >= 0;
  ModUnique(jNext, d, q + 1, 0);
  assert jNext % d == 0;
}

lemma {:induction false} {:vcs_split_on_every_assert} NoMultipleInBetween(j: int, i: int, d: int)
  requires d > 0
  requires j >= 0
  requires j % d == 0
  requires j < i < j + d
  ensures i % d != 0
{
  assert j == (j / d) * d + (j % d);
  assert j == (j / d) * d;
  var r := i - j;
  assert 0 < r < d;
  assert 0 <= r;
  assert i == j + r;
  assert i == (j / d) * d + r;
  assert i > j;
  assert i >= 0;
  ModUnique(i, d, j / d, r);
  assert i % d == r;
  assert r != 0;
  assert i % d != 0;
}

lemma {:induction false} {:vcs_split_on_every_assert} DoubleMultiple(d: int, j: int)
  requires d >= 2
  requires j == 2 * d
  ensures j % d == 0
  ensures 0 <= j
{
  Twice(d);
  assert 2 * d == d + d;
  assert j == d + d;
  assert j >= 0;
  assert j == 2 * d + 0;
  assert 0 <= 0 < d;
  ModUnique(j, d, 2, 0);
  assert j % d == 0;
}

lemma {:induction false} {:vcs_split_on_every_assert} MultipleAtLeastTwice(d: int, i: int)
  requires d >= 2
  requires d < i
  requires i % d == 0
  ensures i >= 2 * d
{
  if i < 2 * d {
    Twice(d);
    assert 2 * d == d + d;
    assert d < i < d + d;
    OneMul(d);
    assert 1 * d == d;
    assert d == 1 * d + 0;
    assert d >= 0;
    ModUnique(d, d, 1, 0);
    assert d % d == 0;
    NoMultipleInBetween(d, i, d);
    assert i % d != 0;
    assert false;
  }
  assert i >= 2 * d;
}

ghost predicate {:fuel 1} Unmarked(i: int, bound: int)
{
  i > 1 && (forall k :: 2 <= k < bound && k < i ==> !divides(k, i))
}

ghost predicate {:fuel 1} Sieved(primes: seq<bool>, n: int, d: int)
  requires |primes| == n
{
  forall i :: 0 <= i < n ==> primes[i] == Unmarked(i, d)
}

ghost predicate {:fuel 1} MarkedUpTo(primes: seq<bool>, oldPrimes: seq<bool>, n: int, d: int, j: int)
  requires |primes| == n
  requires |oldPrimes| == n
  requires d > 0
{
  forall i :: 0 <= i < n ==>
    primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i])
}

