}

lemma {:induction false} MakeUnmarked(i: int, bound: int)
  requires i > 1
  requires forall k :: 2 <= k < bound && k < i ==> !divides(k, i)
  ensures Unmarked(i, bound)
{
  assert i > 1 && (forall k :: 2 <= k < bound && k < i ==> !divides(k, i));
  assert Unmarked(i, bound) == (i > 1 && (forall k :: 2 <= k < bound && k < i ==> !divides(k, i)));
  assert Unmarked(i, bound);
}

lemma {:induction false} NotUnmarked(i: int, bound: int)
  requires !(i > 1)
  ensures !Unmarked(i, bound)
{
  assert Unmarked(i, bound) == (i > 1 && (forall k :: 2 <= k < bound && k < i ==> !divides(k, i)));
  assert !Unmarked(i, bound);
}

lemma {:induction false} OpenSieved(primes: seq<bool>, n: int, d: int)
  requires |primes| == n
  requires Sieved(primes, n, d)
  ensures forall i :: 0 <= i < n ==> primes[i] == Unmarked(i, d)
