}

lemma {:induction false} MakePrime(i: int)
  requires i > 1
  requires forall m :: 1 < m < i ==> !divides(m, i)
  ensures is_prime(i)
{
  assert i > 1 && (forall m :: 1 < m < i ==> !divides(m, i));
  assert is_prime(i) == (i > 1 && (forall m :: 1 < m < i ==> !divides(m, i)));
  assert is_prime(i);
