lemma {:induction false} Pick(i: int, bound: int, k: int)
  requires Unmarked(i, bound)
  requires 2 <= k < bound && k < i
  ensures !divides(k, i)
{
  OpenUnmarked(i, bound);
  assert 2 <= k < bound && k < i;
  assert !divides(k, i);
}

lemma {:induction false} {:vcs_split_on_every_assert} UnmarkedStep(i: int, d: int)
  requires d >= 2
  ensures Unmarked(i, d + 1) <==> (Unmarked(i, d) && (d < i ==> !divides(d, i)))
{
  var rhs := Unmarked(i, d) && (d < i ==> !divides(d, i));
  if Unmarked(i, d + 1) {
    OpenUnmarked(i, d + 1);
    assert i > 1;
    forall k | 2 <= k < d && k < i
      ensures !divides(k, i)
    {
      assert 2 <= k < d + 1;
      assert k < i;
      Pick(i, d + 1, k);
    }
    MakeUnmarked(i, d);
    if d < i {
      assert 2 <= d;
      assert d < d + 1;
      assert d < i;
      Pick(i, d + 1, d);
      assert !divides(d, i);
    }
    assert d < i ==> !divides(d, i);
    assert rhs;
    assert Unmarked(i, d + 1) == rhs;
  } else {
    if rhs {
      assert Unmarked(i, d);
      OpenUnmarked(i, d);
      assert i > 1;
      assert d < i ==> !divides(d, i);
      forall k | 2 <= k < d + 1 && k < i
        ensures !divides(k, i)
      {
        if k < d {
          assert 2 <= k < d && k < i;
          Pick(i, d, k);
        } else {
          assert d <= k < d + 1;
          assert k == d;
          assert k < i;
          assert d < i;
          assert !divides(d, i);
          assert !divides(k, i);
        }
      }
      MakeUnmarked(i, d + 1);
      assert Unmarked(i, d + 1);
      assert false;
    }
    assert !Unmarked(i, d + 1);
    assert !rhs;
    assert Unmarked(i, d + 1) == rhs;
  }
  assert Unmarked(i, d + 1) == rhs;
  assert rhs == (Unmarked(i, d) && (d < i ==> !divides(d, i)));
  assert Unmarked(i, d + 1) <==> (Unmarked(i, d) && (d < i ==> !divides(d, i)));
}

lemma {:induction false} {:vcs_split_on_every_assert} UnmarkedToPrime(i: int, bound: int)
  requires i < bound
  requires Unmarked(i, bound)
  ensures is_prime(i)
{
  OpenUnmarked(i, bound);
  assert i > 1;
  forall m | 1 < m < i
    ensures !divides(m, i)
  {
    assert 2 <= m;
    assert m < i < bound;
    assert m < bound;
    Pick(i, bound, m);
  }
  MakePrime(i);
  assert is_prime(i);
}

lemma {:induction false} {:vcs_split_on_every_assert} PrimeToUnmarked(i: int, bound: int)
  requires i < bound
  requires is_prime(i)
  ensures Unmarked(i, bound)
{
  OpenPrime(i);
  assert i > 1;
  forall k | 2 <= k < bound && k < i
    ensures !divides(k, i)
  {
    assert 1 < k < i;
    assert !divides(k, i);
  }
  MakeUnmarked(i, bound);
}

lemma {:induction false} {:vcs_split_on_every_assert} UnmarkedIsPrime(i: int, bound: int)
  requires i < bound
  ensures Unmarked(i, bound) == is_prime(i)
{
  if i <= 1 {
    NotUnmarked(i, bound);
    NotPrime(i);
    assert !Unmarked(i, bound);
    assert !is_prime(i);
    assert Unmarked(i, bound) == is_prime(i);
  } else {
    if Unmarked(i, bound) {
      UnmarkedToPrime(i, bound);
      assert is_prime(i);
      assert Unmarked(i, bound) == is_prime(i);
    } else {
      if is_prime(i) {
        PrimeToUnmarked(i, bound);
        assert Unmarked(i, bound);
        assert false;
      }
      assert !Unmarked(i, bound);
      assert !is_prime(i);
      assert Unmarked(i, bound) == is_prime(i);
    }
  }
}

lemma {:induction false} {:vcs_split_on_every_assert} InitCorrect(n: int, primes: seq<bool>)
  requires 0 <= n
  requires |primes| == n
  requires forall i :: 0 <= i < n ==> primes[i] == (i >= 2)
  ensures Sieved(primes, n, 2)
{
  forall i | 0 <= i < n
    ensures primes[i] == Unmarked(i, 2)
  {
    assert primes[i] == (i >= 2);
    if i >= 2 {
      assert i > 1;
      forall k | 2 <= k < 2 && k < i
        ensures !divides(k, i)
      {
        assert 2 <= k < 2;
        assert false;
      }
      MakeUnmarked(i, 2);
      assert primes[i] == true;
      assert Unmarked(i, 2);
      assert primes[i] == Unmarked(i, 2);
    } else {
      assert i <= 1;
      assert !(i > 1);
      NotUnmarked(i, 2);
      assert primes[i] == false;
      assert primes[i] == Unmarked(i, 2);
    }
  }
  MakeSieved(primes, n, 2);
}

lemma {:induction false} {:vcs_split_on_every_assert} StartMarked(
  n: int,
  d: int,
  j: int,
  primes: seq<bool>,
  oldPrimes: seq<bool>
)
  requires 0 <= n
  requires d >= 2
  requires |primes| == n
  requires |oldPrimes| == n
  requires primes == oldPrimes
  requires j == 2 * d
  ensures MarkedUpTo(primes, oldPrimes, n, d, j)
{
  forall i | 0 <= i < n
    ensures primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i])
  {
    assert j == 2 * d;
    assert i < j ==> i < 2 * d;
    assert !(2 * d <= i && i < j);
    assert !(2 * d <= i < j && i % d == 0);
    assert primes[i] == oldPrimes[i];
    assert primes[i] == (if 2 * d <= i < j && i % d == 0 then false else oldPrimes[i]);
  }
  MakeMarked(primes, oldPrimes, n, d, j);
}

lemma {:induction false} {:vcs_split_on_every_assert} InnerStep(
  n: int,
  d: int,
  j: int,
  jNext: int,
  oldPrimes: seq<bool>,
  pre: seq<bool>,
  primes: seq<bool>
)
  requires 2 <= d
  requires 0 <= n
  requires 0 <= j < n
  requires 2 * d <= j
  requires j % d == 0
  requires jNext == j + d
  requires |oldPrimes| == n
  requires |pre| == n
  requires |primes| == n
  requires primes == pre[j := false]
  requires MarkedUpTo(pre, oldPrimes, n, d, j)
  ensures MarkedUpTo(primes, oldPrimes, n, d, jNext)
{
  assert d > 0;
  assert jNext == j + d;
  assert j < jNext;

  forall i | 0 <= i < n
    ensures primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i])
  {
    ReadMarked(pre, oldPrimes, n, d, j, i);
    if i == j {
      assert primes == pre[j := false];
      assert primes[i] == false;
      assert 2 * d <= i;
      assert i < jNext;
      assert i % d == 0;
      assert 2 * d <= i < jNext && i % d == 0;
      assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
    } else {
      assert i != j;
      assert primes == pre[j := false];
      assert primes[i] == pre[i];
      if 2 * d <= i < j && i % d == 0 {
        assert pre[i] == false;
        assert primes[i] == false;
        assert i < jNext;
        assert 2 * d <= i < jNext && i % d == 0;
        assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
      } else if 2 * d <= i < jNext && i % d == 0 {
        if i < j {
          assert 2 * d <= i < j && i % d == 0;
          assert false;
        } else {
          assert j <= i;
          assert i != j;
          assert j < i;
          assert i < jNext;
          assert i < j + d;
          NoMultipleInBetween(j, i, d);
          assert i % d != 0;
          assert false;
        }
        assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
      } else {
        assert !(2 * d <= i < jNext && i % d == 0);
        assert !(2 * d <= i < j && i % d == 0);
        assert pre[i] == oldPrimes[i];
        assert primes[i] == oldPrimes[i];
        assert primes[i] == (if 2 * d <= i < jNext && i % d == 0 then false else oldPrimes[i]);
      }
    }
  }
  MakeMarked(primes, oldPrimes, n, d, jNext);
}

lemma {:induction false} {:vcs_split_on_every_assert} AfterMarking(
  n: int,
  d: int,
  dNext: int,
  oldPrimes: seq<bool>,
  primes: seq<bool>,
  j: int
)
  requires 0 <= n
  requires 2 <= d
  requires dNext == d + 1
  requires |oldPrimes| == n
  requires |primes| == n
  requires j >= n
  requires Sieved(oldPrimes, n, d)
  requires MarkedUpTo(primes, oldPrimes, n, d, j)
  ensures Sieved(primes, n, dNext)
{
  forall i | 0 <= i < n
    ensures primes[i] == Unmarked(i, dNext)
  {
    ReadSieved(oldPrimes, n, d, i);
    ReadMarked(primes, oldPrimes, n, d, j, i);
    assert i < n;
    assert n <= j;
    assert i < j;
    UnmarkedStep(i, d);
    assert dNext == d + 1;
    assert Unmarked(i, d + 1) <==> (Unmarked(i, d) && (d < i ==> !divides(d, i)));

    if 2 * d <= i && i % d == 0 {
      assert 2 * d <= i < j && i % d == 0;
      assert primes[i] == false;
      GtTwice(d);
      assert d < 2 * d;
      assert d < 2 * d <= i;
      assert d < i;
      DivEq(d, i);
      assert divides(d, i);
      assert !(d < i ==> !divides(d, i));
      assert !(Unmarked(i, d) && (d < i ==> !divides(d, i)));
      assert !Unmarked(i, d + 1);
      assert Unmarked(i, dNext) == Unmarked(i, d + 1);
      assert !Unmarked(i, dNext);
      assert primes[i] == Unmarked(i, dNext);
    } else {
      assert !(2 * d <= i && i % d == 0);
      assert !(2 * d <= i < j && i % d == 0);
      assert primes[i] == oldPrimes[i];
      if d < i && i % d == 0 {
        MultipleAtLeastTwice(d, i);
        assert 2 * d <= i;
        assert 2 * d <= i && i % d == 0;
        assert false;
      }
      assert d < i ==> i % d != 0;
      if d < i {
        assert i % d != 0;
        DivEq(d, i);
        assert !divides(d, i);
      }
      assert d < i ==> !divides(d, i);
      var extra := d < i ==> !divides(d, i);
      assert extra;
      assert Unmarked(i, d + 1) <==> (Unmarked(i, d) && extra);
      if Unmarked(i, d) {
