{
  var rhs := Unmarked(i, d) && (d < i ==> !divides(d, i));
  if Unmarked(i, d + 1) {
    OpenUnmarked(i, d + 1);
    assert i > 1;
    forall k | 2 <= k < d && k < i
      ensures !divides(k, i)
    {
      assert 2 <= k < d + 1;
      assert k < i;
      Pick(i, d + 1, k);
    }
    MakeUnmarked(i, d);
    if d < i {
      assert 2 <= d;
      assert d < d + 1;
      assert d < i;
      Pick(i, d + 1, d);
      assert !divides(d, i);
    }
    assert d < i ==> !divides(d, i);
    assert rhs;
    assert Unmarked(i, d + 1) == rhs;
  } else {
    if rhs {
      assert Unmarked(i, d);
      OpenUnmarked(i, d);
      assert i > 1;
      assert d < i ==> !divides(d, i);
      forall k | 2 <= k < d + 1 && k < i
        ensures !divides(k, i)
      {
        if k < d {
          assert 2 <= k < d && k < i;
          Pick(i, d, k);
        } else {
          assert d <= k < d + 1;
          assert k == d;
          assert k < i;
          assert d < i;
          assert !divides(d, i);
          assert !divides(k, i);
        }
      }
      MakeUnmarked(i, d + 1);
      assert Unmarked(i, d + 1);
      assert false;
    }
    assert !Unmarked(i, d + 1);
    assert !rhs;
    assert Unmarked(i, d + 1) == rhs;
  }
  assert Unmarked(i, d + 1) == rhs;
  assert rhs == (Unmarked(i, d) && (d < i ==> !divides(d, i)));
  assert Unmarked(i, d + 1) <==> (Unmarked(i, d) && (d < i ==> !divides(d, i)));
}

