method naive_search(haystack: seq<int>, needle: seq<int>) returns (indices: seq<int>)
    requires |haystack| < 1000000
    requires |needle| < 1000000
    ensures 
        // Type Constraint: Indices must be non-negative (simulating usize)
        forall k :: 0 <= k < |indices| ==> indices[k] >= 0
    ensures
        // Soundness: Every index returned is a valid match
        forall i :: 0 <= i < |indices| ==> 
            matches_at(haystack, needle, indices[i])
    ensures
        // Completeness: Every valid match in the haystack is found
        forall i :: matches_at(haystack, needle, i) ==> 
            exists k :: 0 <= k < |indices| && indices[k] == i
{
    indices := [];
    var i := 0;
    while i + |needle| <= |haystack|
        invariant 0 <= i
        invariant forall k :: 0 <= k < |indices| ==> indices[k] >= 0
        invariant forall k :: 0 <= k < |indices| ==> matches_at(haystack, needle, indices[k])
        invariant forall j :: 0 <= j < i && matches_at(haystack, needle, j) ==> j in indices
        decreases |haystack| - i
    {
        var j := 0;
        var ok := true;
        while j < |needle| && ok
            invariant 0 <= j <= |needle|
            invariant ok ==> forall t :: 0 <= t < j ==> haystack[i + t] == needle[t]
            invariant !ok ==> !matches_at(haystack, needle, i)
            decreases |needle| - j + (if ok then 1 else 0)
        {
            if haystack[i + j] != needle[j] {
                assert !(haystack[i + j] == needle[j]);
                ok := false;
            } else {
                j := j + 1;
            }
        }
        if ok {
            assert j == |needle|;
            assert matches_at(haystack, needle, i);
            var old_indices := indices;
            indices := indices + [i];
            assert forall x :: x in old_indices ==> x in indices;
            assert i in indices;
        }
        i := i + 1;
    }
    forall x | matches_at(haystack, needle, x)
        ensures exists k :: 0 <= k < |indices| && indices[k] == x
    {
        assert x < i;
        assert x in indices;
    }
}

