predicate WellFormedSeq(g: seq<seq<int>>) {
  forall u: int, i: int ::
    0 <= u < |g| && 0 <= i < |g[u]| ==>
      0 <= g[u][i] < |g|
}

predicate path_ok(g: seq<seq<int>>, p: seq<int>, u: int, v: int) {
  |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p)
}

predicate intermediates_below(p: seq<int>, k: int) {
  forall t :: 1 <= t <= |p| - 2 ==> p[t] < k
}

predicate has_path_via(g: seq<seq<int>>, u: int, v: int, k: int) {
  exists p: seq<int> {:trigger path_ok(g, p, u, v)} ::
    path_ok(g, p, u, v) && intermediates_below(p, k)
}

predicate RepRoots(rep: seq<int>) {
  forall a :: 0 <= a < |rep| ==>
    0 <= rep[a] <= a && rep[rep[a]] == rep[a]
}

predicate RepCorrect(g: seq<seq<int>>, rep: seq<int>) {
  && |rep| == |g|
  && RepRoots(rep)
  && (forall a :: 0 <= a < |g| ==>
        has_path(g, a, rep[a]) && has_path(g, rep[a], a))
  && (forall a: int, t: int ::
        0 <= a < |g| && 0 <= t < rep[a] ==>
          !(has_path(g, a, t) && has_path(g, t, a)))
}

predicate ClassComp(rep: seq<int>, root: int, comp: seq<int>) {
  && 0 <= root < |rep|
  && rep[root] == root
  && |comp| > 0
  && comp[0] == root
  && (forall t :: 0 <= t < |comp| ==>
        0 <= comp[t] < |rep| && rep[comp[t]] == root)
  && (forall x :: 0 <= x < |rep| && rep[x] == root ==>
        seq_contains(comp, x))
  && (forall a, b :: 0 <= a < b < |comp| ==> comp[a] < comp[b])
}

predicate SccsMatch(rep: seq<int>, sccs: seq<seq<int>>) {
  && (forall i :: 0 <= i < |sccs| ==>
        |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]))
  && (forall i, j ::
        0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
          |sccs[i]| > 0 && |sccs[j]| > 0 && sccs[i][0] != sccs[j][0])
  && (forall u :: 0 <= u < |rep| ==>
        exists i :: 0 <= i < |sccs| && seq_contains(sccs[i], u))
}

lemma ViewWellFormed(graph: Graph)
  requires well_formed(graph)
  ensures WellFormedSeq(view(graph))
{
  var g := view(graph);
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures 0 <= g[u][i] < |g|
  {
    assert 0 <= graph.adj[u][i] < |graph.adj|;
  }
}

method EdgeExists(g: seq<seq<int>>, u: int, v: int) returns (b: bool)
  requires 0 <= u < |g|
  ensures b == has_edge(g, u, v)
{
  var t := 0;
  while t < |g[u]|
    invariant 0 <= t <= |g[u]|
    invariant forall q :: 0 <= q < t ==> g[u][q] != v
    decreases |g[u]| - t
  {
    if g[u][t] == v {
      b := true;
      assert has_edge(g, u, v) by {
        assert 0 <= u < |g| && 0 <= t < |g[u]| && g[u][t] == v;
      }
      return;
    }
    t := t + 1;
  }
  b := false;
  assert !has_edge(g, u, v) by {
    if has_edge(g, u, v) {
      var q :| 0 <= u < |g| && 0 <= q < |g[u]| && g[u][q] == v;
      assert g[u][q] != v;
      assert false;
    }
  }
}

lemma PathNodeInRange(g: seq<seq<int>>, p: seq<int>, t: int)
  requires WellFormedSeq(g)
  requires path_valid(g, p)
  requires |p| >= 2
  requires 0 <= t < |p|
  ensures 0 <= p[t] < |g|
{
  assert forall kk :: 0 <= kk < |p| - 1 ==> has_edge(g, p[kk], p[kk + 1]);
  if t == 0 {
    assert has_edge(g, p[0], p[1]);
    var i :| 0 <= p[0] < |g| && 0 <= i < |g[p[0]]| && g[p[0]][i] == p[1];
  } else {
    assert has_edge(g, p[t - 1], p[t]);
    var i :| 0 <= p[t - 1] < |g| && 0 <= i < |g[p[t - 1]]| && g[p[t - 1]][i] == p[t];
    assert forall x, j :: 0 <= x < |g| && 0 <= j < |g[x]| ==> 0 <= g[x][j] < |g|;
    assert 0 <= g[p[t - 1]][i] < |g|;
    assert p[t] == g[p[t - 1]][i];
  }
}

lemma ViaZeroCorrect(g: seq<seq<int>>, u: int, v: int)
  requires WellFormedSeq(g)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures has_path_via(g, u, v, 0) <==> (u == v || has_edge(g, u, v))
{
