  forall t | 1 <= t <= |p| - 2
    ensures p[t] < k2
  {
    assert p[t] < k1;
  }
  assert intermediates_below(p, k2);
  assert has_path_via(g, u, v, k2) by {
    assert path_ok(g, p, u, v);
  }
}

lemma SubpathValid(g: seq<seq<int>>, p: seq<int>, lo: int, hi: int)
  requires path_valid(g, p)
  requires 0 <= lo < hi <= |p|
  ensures path_valid(g, p[lo..hi])
  ensures |p[lo..hi]| == hi - lo
  ensures (p[lo..hi])[0] == p[lo]
  ensures (p[lo..hi])[(hi - lo) - 1] == p[hi - 1]
{
  var q := p[lo..hi];
  assert |q| == hi - lo;
  assert q[0] == p[lo];
  assert q[|q| - 1] == p[hi - 1];
  forall kk | 0 <= kk < |q| - 1
    ensures has_edge(g, q[kk], q[kk + 1])
  {
    assert q[kk] == p[lo + kk];
    assert q[kk + 1] == p[lo + kk + 1];
    assert kk <= hi - lo - 2;
    assert lo + kk <= hi - 2;
    assert lo + kk <= |p| - 2;
    assert has_edge(g, p[lo + kk], p[lo + kk + 1]);
  }
}

lemma ConcatPathValid(g: seq<seq<int>>, p1: seq<int>, p2: seq<int>)
  requires |p1| > 0 && |p2| > 0
  requires path_valid(g, p1)
  requires path_valid(g, p2)
  requires p1[|p1| - 1] == p2[0]
  ensures var p := p1[..|p1| - 1] + p2;
    path_valid(g, p) && |p| == |p1| + |p2| - 1 && p[0] == p1[0] && p[|p| - 1] == p2[|p2| - 1]
{
  var prefLen := |p1| - 1;
  var pref := p1[..prefLen];
  var p := pref + p2;
  assert |pref| == prefLen;
  assert |p| == |p1| + |p2| - 1;

  if |pref| == 0 {
    assert |p1| == 1;
    assert p1[0] == p1[|p1| - 1];
    assert p1[0] == p2[0];
    assert p == p2;
    assert p[0] == p1[0];
  } else {
    assert p[0] == pref[0];
    assert pref[0] == p1[0];
  }
  assert p[|p| - 1] == p2[|p2| - 1];

  forall kk | 0 <= kk < |p| - 1
    ensures has_edge(g, p[kk], p[kk + 1])
  {
    if kk < |p1| - 1 {
      assert 0 <= kk <= |p1| - 2;
      assert p[kk] == p1[kk];
      if kk + 1 < |p1| - 1 {
        assert p[kk + 1] == pref[kk + 1];
        assert pref[kk + 1] == p1[kk + 1];
      } else {
        assert kk + 1 == |p1| - 1;
        assert p[kk + 1] == p2[0];
        assert p2[0] == p1[|p1| - 1];
        assert p[kk + 1] == p1[kk + 1];
      }
      assert forall t :: 0 <= t < |p1| - 1 ==> has_edge(g, p1[t], p1[t + 1]);
      assert has_edge(g, p1[kk], p1[kk + 1]);
    } else {
      var j := kk - (|p1| - 1);
      assert kk >= |p1| - 1;
      assert j >= 0;
      assert kk <= |p1| + |p2| - 3;
      assert j <= |p2| - 2;
      assert 0 <= j < |p2| - 1;
      assert p[kk] == p2[j];
      assert p[kk + 1] == p2[j + 1];
      assert forall t :: 0 <= t < |p2| - 1 ==> has_edge(g, p2[t], p2[t + 1]);
      assert has_edge(g, p2[j], p2[j + 1]);
    }
  }
}

lemma ConcatVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, k, k)
  requires has_path_via(g, k, v, k)
  ensures has_path_via(g, u, v, k + 1)
{
  var p1 :| path_ok(g, p1, u, k) && intermediates_below(p1, k);
  var p2 :| path_ok(g, p2, k, v) && intermediates_below(p2, k);
  ConcatPathValid(g, p1, p2);
  var p := p1[..|p1| - 1] + p2;
  var L := |p1| - 1;
  assert path_valid(g, p);
  assert |p| == |p1| + |p2| - 1;
  assert p[0] == p1[0] == u;
  assert p[|p| - 1] == v;

  forall t | 1 <= t <= |p| - 2
    ensures p[t] < k + 1
  {
    if t < L {
      assert p[t] == p1[t];
      assert 1 <= t <= |p1| - 2;
      assert p1[t] < k;
    } else if t == L {
      assert p[t] == p2[0];
      assert p2[0] == k;
      assert k < k + 1;
    } else {
      var j := t - L;
      assert t >= L + 1;
      assert j >= 1;
      assert t <= |p| - 2;
      assert |p| - 2 - L == |p2| - 2;
      assert j <= |p2| - 2;
      assert p[t] == p2[j];
      assert p2[j] < k;
    }
  }
  assert intermediates_below(p, k + 1);
  assert has_path_via(g, u, v, k + 1) by {
    assert path_ok(g, p, u, v);
  }
}

lemma SplitVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, v, k + 1)
  ensures has_path_via(g, u, v, k) ||
          (has_path_via(g, u, k, k) && has_path_via(g, k, v, k))
{
  var p :| path_ok(g, p, u, v) && intermediates_below(p, k + 1);
  if exists t :: 0 <= t < |p| && p[t] == k {
    var witness :| 0 <= witness < |p| && p[witness] == k;
    var i := 0;
    while p[i] != k
      invariant 0 <= i <= witness
      invariant i < |p|
      invariant forall t :: 0 <= t < i ==> p[t] != k
      decreases witness - i
    {
      forall t | 0 <= t <= i
        ensures p[t] != k
      {
        if t < i {
          assert p[t] != k;
        } else {
          assert t == i;
          assert p[i] != k;
        }
      }
      i := i + 1;
    }
    assert p[i] == k;
    assert forall t :: 0 <= t < i ==> p[t] != k;

    var j := |p| - 1;
    while p[j] != k
      invariant witness <= j < |p|
      invariant forall t :: j < t < |p| ==> p[t] != k
      decreases j - witness
    {
      forall t | j - 1 < t < |p|
        ensures p[t] != k
      {
        if t == j {
          assert p[j] != k;
        } else {
          assert j < t < |p|;
          assert p[t] != k;
        }
      }
      j := j - 1;
    }
    assert p[j] == k;
    assert forall t :: j < t < |p| ==> p[t] != k;
    assert 0 <= i < |p|;
    assert i + 1 <= |p|;

    SubpathValid(g, p, 0, i + 1);
    SubpathValid(g, p, j, |p|);
    var left := p[0 .. i + 1];
    var right := p[j .. |p|];
    assert path_valid(g, left);
    assert left[0] == p[0];
    assert p[0] == u;
    assert left[|left| - 1] == p[i];
    assert p[i] == k;
    assert path_valid(g, right);
    assert right[0] == p[j];
    assert right[|right| - 1] == p[|p| - 1];
    assert p[|p| - 1] == v;

