      ensures left[t] < k
    {
      assert left[t] == p[t];
      assert |left| == i + 1;
      assert t <= i - 1;
      assert t < i;
      assert p[t] != k;
      assert i <= |p| - 1;
      assert t <= |p| - 2;
      assert p[t] < k + 1;
      assert p[t] < k;
    }
    assert intermediates_below(left, k);
    assert has_path_via(g, u, k, k) by {
      assert path_ok(g, left, u, k);
    }

