      assert t <= |p| - j - 2;
      assert s <= |p| - 2;
      assert s >= j + 1;
      assert j < s < |p|;
      assert p[s] != k;
      assert 1 <= s <= |p| - 2;
      assert p[s] < k + 1;
      assert p[s] < k;
    }
    assert intermediates_below(right, k);
    assert has_path_via(g, k, v, k) by {
