      assert p[t] != k;
      assert p[t] < k + 1;
      assert p[t] < k;
    }
    assert intermediates_below(p, k);
    assert has_path_via(g, u, v, k) by {
      assert path_ok(g, p, u, v);
    }
  }
}

lemma FWStep(g: seq<seq<int>>, u: int, v: int, k: int)
  ensures has_path_via(g, u, v, k + 1) <==>
          (has_path_via(g, u, v, k) ||
            (has_path_via(g, u, k, k) && has_path_via(g, k, v, k)))
{
  if has_path_via(g, u, v, k) {
    ViaMonotone(g, u, v, k, k + 1);
  }
  if has_path_via(g, u, k, k) && has_path_via(g, k, v, k) {
    ConcatVia(g, u, v, k);
  }
  if has_path_via(g, u, v, k + 1) {
    SplitVia(g, u, v, k);
  }
}

lemma ViaIffPath(g: seq<seq<int>>, u: int, v: int)
  requires WellFormedSeq(g)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures has_path_via(g, u, v, |g|) <==> has_path(g, u, v)
{
  if has_path_via(g, u, v, |g|) {
    var p :| path_ok(g, p, u, v) && intermediates_below(p, |g|);
    assert has_path(g, u, v) by {
      assert path_valid(g, p);
      assert |p| > 0 && p[0] == u && p[|p| - 1] == v;
    }
  }
  if has_path(g, u, v) {
    var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p);
    forall t | 1 <= t <= |p| - 2
      ensures p[t] < |g|
    {
      assert |p| >= 3;
      PathNodeInRange(g, p, t);
    }
    assert intermediates_below(p, |g|);
    assert has_path_via(g, u, v, |g|) by {
      assert path_ok(g, p, u, v);
    }
  }
}

lemma Reflexive(g: seq<seq<int>>, u: int)
  requires 0 <= u < |g|
  ensures has_path(g, u, u)
{
  var p := [u];
  assert has_path(g, u, u) by {
    assert path_valid(g, p);
    assert |p| > 0 && p[0] == u && p[|p| - 1] == u;
  }
}

lemma PathConcat(g: seq<seq<int>>, u: int, v: int, w: int)
  requires has_path(g, u, v)
  requires has_path(g, v, w)
  ensures has_path(g, u, w)
{
  var p1 :| |p1| > 0 && p1[0] == u && p1[|p1| - 1] == v && path_valid(g, p1);
  var p2 :| |p2| > 0 && p2[0] == v && p2[|p2| - 1] == w && path_valid(g, p2);
  ConcatPathValid(g, p1, p2);
  var p := p1[..|p1| - 1] + p2;
  assert has_path(g, u, w) by {
    assert path_valid(g, p);
    assert |p| > 0;
    assert p[0] == u;
    assert p[|p| - 1] == w;
  }
}

lemma PathConcat3(g: seq<seq<int>>, a: int, b: int, c: int, d: int)
  requires has_path(g, a, b)
  requires has_path(g, b, c)
  requires has_path(g, c, d)
  ensures has_path(g, a, d)
{
  PathConcat(g, a, b, c);
  PathConcat(g, a, c, d);
}

method InitReach(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path_via(g, a, b, 0)
{
  var n := |g|;
  reach := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |reach| == i
    invariant forall a :: 0 <= a < i ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, 0)
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==> row[b] == has_path_via(g, i, b, 0)
      decreases n - j
    {
      var e := EdgeExists(g, i, j);
      ViaZeroCorrect(g, i, j);
      var bit := (i == j) || e;
      assert e == has_edge(g, i, j);
      assert bit == (i == j || has_edge(g, i, j));
      assert bit == has_path_via(g, i, j, 0);
      row := row + [bit];
      j := j + 1;
    }
    assert |row| == n;
    assert forall b :: 0 <= b < n ==> row[b] == has_path_via(g, i, b, 0);
    reach := reach + [row];
    i := i + 1;
  }
}

method SquareStep(reach: seq<seq<bool>>, k: int) returns (next: seq<seq<bool>>)
  requires 0 <= k < |reach|
  requires forall a :: 0 <= a < |reach| ==> |reach[a]| == |reach|
  ensures |next| == |reach|
  ensures forall a :: 0 <= a < |next| ==> |next[a]| == |reach|
  ensures forall a, b :: 0 <= a < |reach| && 0 <= b < |reach| ==>
      next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
{
  var n := |reach|;
  next := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |next| == i
    invariant forall a :: 0 <= a < i ==> |next[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==>
          row[b] == (reach[i][b] || (reach[i][k] && reach[k][b]))
      decreases n - j
    {
      var bit := reach[i][j] || (reach[i][k] && reach[k][j]);
      row := row + [bit];
      j := j + 1;
    }
    next := next + [row];
    i := i + 1;
  }
}

method FloydWarshall(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path(g, a, b)
{
  var n := |g|;
  reach := InitReach(g);
  var k := 0;
  while k < n
    invariant 0 <= k <= n
    invariant |reach| == n
    invariant forall a :: 0 <= a < n ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, k)
    decreases n - k
  {
    var old := reach;
    var next := SquareStep(old, k);
    forall a, b | 0 <= a < n && 0 <= b < n
      ensures next[a][b] == has_path_via(g, a, b, k + 1)
    {
      assert old[a][b] == has_path_via(g, a, b, k);
      assert old[a][k] == has_path_via(g, a, k, k);
      assert old[k][b] == has_path_via(g, k, b, k);
      assert next[a][b] == (old[a][b] || (old[a][k] && old[k][b]));
      FWStep(g, a, b, k);
    }
    reach := next;
    assert reach == next;
    assert forall a, b :: 0 <= a < n && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, k + 1);
    k := k + 1;
  }
  forall a, b | 0 <= a < n && 0 <= b < n
    ensures reach[a][b] == has_path(g, a, b)
  {
    assert reach[a][b] == has_path_via(g, a, b, n);
    ViaIffPath(g, a, b);
  }
}

lemma IdempotentOne(g: seq<seq<int>>, rep: seq<int>, u: int)
  requires |rep| == |g|
  requires 0 <= u < |g|
  requires forall a :: 0 <= a < |g| ==>
      0 <= rep[a] <= a && has_path(g, a, rep[a]) && has_path(g, rep[a], a)
  requires forall a: int, t: int ::
      0 <= a < |g| && 0 <= t < rep[a] ==>
        !(has_path(g, a, t) && has_path(g, t, a))
  ensures rep[rep[u]] == rep[u]
{
  var r := rep[u];
  assert 0 <= r <= u;
  assert 0 <= r < |g|;
  var rr := rep[r];
  assert 0 <= rr <= r;
  assert has_path(g, u, r) && has_path(g, r, u);
  assert has_path(g, r, rr) && has_path(g, rr, r);
  PathConcat(g, rr, r, u);
  PathConcat(g, u, r, rr);
  assert has_path(g, rr, u) && has_path(g, u, rr);
  if rr < r {
    assert 0 <= rr < rep[u];
    assert !(has_path(g, u, rr) && has_path(g, rr, u));
    assert has_path(g, u, rr) && has_path(g, rr, u);
    assert false;
  }
  assert rr == r;
}

lemma RepMutual(g: seq<seq<int>>, rep: seq<int>, u: int, v: int)
  requires RepCorrect(g, rep)
  requires 0 <= u < |rep| && 0 <= v < |rep|
  ensures (rep[u] == rep[v]) <==> (has_path(g, u, v) && has_path(g, v, u))
{
  if rep[u] == rep[v] {
    var r := rep[u];
    assert has_path(g, u, r) && has_path(g, r, u);
    assert has_path(g, v, r) && has_path(g, r, v);
    PathConcat(g, u, r, v);
    PathConcat(g, v, r, u);
  }
  if has_path(g, u, v) && has_path(g, v, u) {
    var ru := rep[u];
    var rv := rep[v];
    assert has_path(g, ru, u) && has_path(g, u, ru);
    assert has_path(g, rv, v) && has_path(g, v, rv);
    PathConcat(g, ru, u, v);
    PathConcat(g, v, u, ru);
    PathConcat(g, rv, v, u);
    PathConcat(g, u, v, rv);
    assert has_path(g, ru, v) && has_path(g, v, ru);
    assert has_path(g, rv, u) && has_path(g, u, rv);
    if ru < rv {
      assert 0 <= ru < rep[v];
      assert !(has_path(g, v, ru) && has_path(g, ru, v));
      assert false;
    }
    if rv < ru {
      assert 0 <= rv < rep[u];
      assert !(has_path(g, u, rv) && has_path(g, rv, u));
      assert false;
    }
    assert ru == rv;
  }
}

method ComputeRep(g: seq<seq<int>>, reach: seq<seq<bool>>) returns (rep: seq<int>)
  requires |reach| == |g|
  requires forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path(g, a, b)
  ensures RepCorrect(g, rep)
{
  var n := |g|;
  rep := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |rep| == i
    invariant forall a :: 0 <= a < i ==> rep[a] == a
    decreases n - i
  {
    rep := rep + [i];
    i := i + 1;
  }

  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |rep| == n
    invariant forall a :: u <= a < n ==> rep[a] == a
    invariant forall a :: 0 <= a < u ==>
        0 <= rep[a] <= a && reach[a][rep[a]] && reach[rep[a]][a]
    invariant forall a: int, t: int ::
        0 <= a < u && 0 <= t < rep[a] ==>
          !(reach[a][t] && reach[t][a])
    decreases n - u
  {
    Reflexive(g, u);
    assert reach[u][u];
    var r := u;
    var v := 0;
    while v < u
      invariant 0 <= v <= u
      invariant 0 <= r <= u
      invariant reach[u][r] && reach[r][u]
      invariant r == u || r < v
      invariant forall t :: 0 <= t < v && reach[u][t] && reach[t][u] ==> r <= t
      decreases u - v
    {
      if reach[u][v] && reach[v][u] && v < r {
        r := v;
      }
      v := v + 1;
    }
    forall t | 0 <= t < r
      ensures !(reach[u][t] && reach[t][u])
    {
      if reach[u][t] && reach[t][u] {
        assert t < u;
        assert r <= t;
        assert false;
      }
    }
    var newRep := rep[u := r];
    assert newRep[u] == r;
    forall a | 0 <= a < u
      ensures newRep[a] == rep[a]
    {
      assert a != u;
    }
    forall a | u + 1 <= a < n
      ensures newRep[a] == a
    {
      assert newRep[a] == rep[a];
      assert rep[a] == a;
    }
    forall a | 0 <= a < u + 1
      ensures 0 <= newRep[a] <= a && reach[a][newRep[a]] && reach[newRep[a]][a]
    {
      if a < u {
        assert newRep[a] == rep[a];
      } else {
        assert a == u;
        assert newRep[a] == r;
        assert reach[u][r] && reach[r][u];
      }
    }
    forall a, t | 0 <= a < u + 1 && 0 <= t < newRep[a]
      ensures !(reach[a][t] && reach[t][a])
    {
      if a < u {
        assert newRep[a] == rep[a];
      } else {
        assert a == u && newRep[a] == r;
        assert !(reach[u][t] && reach[t][u]);
      }
    }
    rep := newRep;
    u := u + 1;
  }

  forall a | 0 <= a < n
    ensures 0 <= rep[a] <= a && has_path(g, a, rep[a]) && has_path(g, rep[a], a)
  {
    assert reach[a][rep[a]] && reach[rep[a]][a];
  }
  forall a, t | 0 <= a < n && 0 <= t < rep[a]
    ensures !(has_path(g, a, t) && has_path(g, t, a))
  {
    assert !(reach[a][t] && reach[t][a]);
  }
  forall a | 0 <= a < n
    ensures rep[rep[a]] == rep[a]
  {
    IdempotentOne(g, rep, a);
  }
  assert RepRoots(rep);
  assert RepCorrect(g, rep);
}

method BuildComp(rep: seq<int>, root: int) returns (comp: seq<int>)
  requires RepRoots(rep)
  requires 0 <= root < |rep|
  requires rep[root] == root
  ensures ClassComp(rep, root, comp)
{
  comp := [];
  var u := 0;
  while u < |rep|
    invariant 0 <= u <= |rep|
    invariant forall t :: 0 <= t < |comp| ==> 0 <= comp[t] < u && rep[comp[t]] == root
    invariant forall x :: 0 <= x < u && rep[x] == root ==> seq_contains(comp, x)
    invariant forall a, b :: 0 <= a < b < |comp| ==> comp[a] < comp[b]
    invariant u <= root ==> |comp| == 0
    invariant u > root ==> |comp| > 0 && comp[0] == root
    decreases |rep| - u
  {
    assert 0 <= rep[u] <= u;
    if rep[u] == root {
      assert root <= u;
      var oldC := comp;
      var nc := oldC + [u];

      forall x | 0 <= x < u + 1 && rep[x] == root
        ensures seq_contains(nc, x)
      {
        if x < u {
          var idx :| 0 <= idx < |oldC| && oldC[idx] == x;
          assert nc[idx] == oldC[idx];
          assert nc[idx] == x;
        } else {
          assert x == u;
          assert nc[|oldC|] == u;
        }
      }

      forall a, b | 0 <= a < b < |nc|
        ensures nc[a] < nc[b]
      {
        if b < |oldC| {
          assert nc[a] == oldC[a];
          assert nc[b] == oldC[b];
        } else {
          assert b == |oldC|;
          assert nc[b] == u;
          assert nc[a] == oldC[a];
          assert oldC[a] < u;
        }
      }

      forall t | 0 <= t < |nc|
        ensures 0 <= nc[t] < u + 1 && rep[nc[t]] == root
      {
        if t < |oldC| {
          assert nc[t] == oldC[t];
          assert oldC[t] < u;
        } else {
          assert t == |oldC|;
          assert nc[t] == u;
          assert rep[u] == root;
        }
      }

      if u == root {
        assert |oldC| == 0;
        assert nc[0] == root;
        assert |nc| == 1;
      } else {
        assert u > root;
        assert |oldC| > 0;
        assert oldC[0] == root;
        assert nc[0] == oldC[0];
      }

      comp := nc;
      assert comp == nc;
    } else {
      forall x | 0 <= x < u + 1 && rep[x] == root
        ensures seq_contains(comp, x)
      {
        if x == u {
          assert rep[u] == root;
          assert false;
        } else {
          assert x < u;
          var idx :| 0 <= idx < |comp| && comp[idx] == x;
          assert comp[idx] == x;
        }
      }
      forall t | 0 <= t < |comp|
        ensures comp[t] < u + 1
      {
        assert comp[t] < u;
      }
      if u < root {
        assert |comp| == 0;
      } else if u == root {
        assert rep[root] == root;
        assert false;
      } else {
        assert |comp| > 0 && comp[0] == root;
      }
    }
    u := u + 1;
  }
  assert u == |rep|;
  assert root < |rep|;
  assert u > root;
  assert |comp| > 0 && comp[0] == root;
  assert forall t :: 0 <= t < |comp| ==> 0 <= comp[t] < |rep| && rep[comp[t]] == root;
  assert forall x :: 0 <= x < |rep| && rep[x] == root ==> seq_contains(comp, x);
  assert ClassComp(rep, root, comp);
}

lemma StillCovered(sccs: seq<seq<int>>, comp: seq<int>, u: int)
  requires exists i :: 0 <= i < |sccs| && seq_contains(sccs[i], u)
  ensures exists i :: 0 <= i < |sccs + [comp]| && seq_contains((sccs + [comp])[i], u)
{
  var i :| 0 <= i < |sccs| && seq_contains(sccs[i], u);
  assert (sccs + [comp])[i] == sccs[i];
  assert seq_contains((sccs + [comp])[i], u);
}

lemma NewCovered(sccs: seq<seq<int>>, comp: seq<int>, u: int)
  requires seq_contains(comp, u)
  ensures exists i :: 0 <= i < |sccs + [comp]| && seq_contains((sccs + [comp])[i], u)
{
  assert (sccs + [comp])[|sccs|] == comp;
  assert seq_contains((sccs + [comp])[|sccs|], u);
}

method AssembleSccs(rep: seq<int>) returns (sccs: seq<seq<int>>)
  requires RepRoots(rep)
  ensures SccsMatch(rep, sccs)
{
  var n := |rep|;
  sccs := [];
  var r := 0;
  while r < n
    invariant 0 <= r <= n
    invariant forall i :: 0 <= i < |sccs| ==>
        |sccs[i]| > 0 && sccs[i][0] < r && ClassComp(rep, sccs[i][0], sccs[i])
    invariant forall i, j :: 0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
        sccs[i][0] != sccs[j][0]
    invariant forall u :: 0 <= u < n && rep[u] < r ==>
        exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], u)
    decreases n - r
  {
    if rep[r] == r {
      var old := sccs;
      var comp := BuildComp(rep, r);
      var nw := old + [comp];

      forall i | 0 <= i < |nw|
        ensures |nw[i]| > 0 && nw[i][0] < r + 1 && ClassComp(rep, nw[i][0], nw[i])
      {
        if i < |old| {
          assert nw[i] == old[i];
          assert old[i][0] < r;
          assert ClassComp(rep, old[i][0], old[i]);
        } else {
          assert i == |old|;
          assert nw[i] == comp;
          assert comp[0] == r;
          assert ClassComp(rep, r, comp);
        }
      }

      forall i, j | 0 <= i < |nw| && 0 <= j < |nw| && i != j
        ensures nw[i][0] != nw[j][0]
      {
        if i < |old| && j < |old| {
          assert nw[i] == old[i];
          assert nw[j] == old[j];
          assert old[i][0] != old[j][0];
        } else if i == |old| {
          assert nw[i] == comp;
          assert nw[i][0] == r;
          assert j < |old|;
          assert nw[j] == old[j];
          assert old[j][0] < r;
        } else {
          assert j == |old|;
          assert nw[j] == comp;
          assert nw[j][0] == r;
          assert i < |old|;
          assert nw[i] == old[i];
          assert old[i][0] < r;
        }
      }

      forall u | 0 <= u < n && rep[u] < r + 1
        ensures exists ii :: 0 <= ii < |nw| && seq_contains(nw[ii], u)
      {
        if rep[u] < r {
          StillCovered(old, comp, u);
        } else {
          assert rep[u] == r;
          assert ClassComp(rep, r, comp);
          assert seq_contains(comp, u);
          NewCovered(old, comp, u);
        }
      }

      sccs := nw;
    } else {
      forall u | 0 <= u < n && rep[u] < r + 1
        ensures exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], u)
      {
        if rep[u] < r {
          var ii :| 0 <= ii < |sccs| && seq_contains(sccs[ii], u);
        } else {
          assert rep[u] == r;
          assert rep[rep[u]] == rep[u];
          assert rep[r] == r;
          assert rep[r] != r;
          assert false;
        }
      }
      forall i | 0 <= i < |sccs|
        ensures sccs[i][0] < r + 1
      {
        assert sccs[i][0] < r;
      }
    }
    r := r + 1;
  }

  forall u | 0 <= u < n
    ensures exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], u)
  {
    assert 0 <= rep[u] <= u;
    assert rep[u] < n;
  }
  assert forall i :: 0 <= i < |sccs| ==>
      |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]);
  assert forall i, j :: 0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
      |sccs[i]| > 0 && |sccs[j]| > 0 && sccs[i][0] != sccs[j][0];
  assert SccsMatch(rep, sccs);
}

lemma RepOfMember(rep: seq<int>, comp: seq<int>, node: int)
  requires |comp| > 0 && ClassComp(rep, comp[0], comp)
  requires seq_contains(comp, node)
  ensures 0 <= node < |rep|
  ensures rep[node] == comp[0]
{
  var t :| 0 <= t < |comp| && comp[t] == node;
