lemma ProveValid(g: seq<seq<int>>, rep: seq<int>, sccs: seq<seq<int>>)
  requires RepCorrect(g, rep)
  requires SccsMatch(rep, sccs)
  ensures is_valid_scc_result(g, sccs)
{
  forall ci | 0 <= ci < |sccs|
    ensures is_strongly_connected(g, sccs[ci])
  {
    var comp := sccs[ci];
    assert |comp| > 0;
    assert ClassComp(rep, comp[0], comp);
    forall t | 0 <= t < |comp|
      ensures 0 <= comp[t] < |g|
    {
      assert forall z :: 0 <= z < |comp| ==> 0 <= comp[z] < |rep|;
      assert 0 <= comp[t] < |rep|;
      assert |rep| == |g|;
    }
    forall a, b | seq_contains(comp, a) && seq_contains(comp, b)
      ensures has_path(g, a, b) && has_path(g, b, a)
    {
      RepOfMember(rep, comp, a);
      RepOfMember(rep, comp, b);
      assert rep[a] == comp[0];
      assert rep[b] == comp[0];
      RepMutual(g, rep, a, b);
    }
    assert is_strongly_connected(g, comp);
  }

  forall i, j, node | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
    ensures !(seq_contains(sccs[i], node) && seq_contains(sccs[j], node))
  {
    if seq_contains(sccs[i], node) && seq_contains(sccs[j], node) {
      assert |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]);
      assert |sccs[j]| > 0 && ClassComp(rep, sccs[j][0], sccs[j]);
      RepOfMember(rep, sccs[i], node);
      RepOfMember(rep, sccs[j], node);
      assert rep[node] == sccs[i][0];
      assert rep[node] == sccs[j][0];
      assert sccs[i][0] == sccs[j][0];
      assert sccs[i][0] != sccs[j][0];
      assert false;
    }
  }
  assert are_disjoint(sccs);

  forall u | 0 <= u < |g|
    ensures is_covered(sccs, u)
  {
    assert |rep| == |g|;
    assert exists i :: 0 <= i < |sccs| && seq_contains(sccs[i], u);
  }
  assert is_partition(g, sccs);

  forall i, j | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
    ensures scc_has_path(g, sccs, i, j) ==> !scc_has_path(g, sccs, j, i)
  {
    if scc_has_path(g, sccs, i, j) {
      if scc_has_path(g, sccs, j, i) {
        var a, b :| seq_contains(sccs[i], a) && seq_contains(sccs[j], b) && has_path(g, a, b);
        var c, d :| seq_contains(sccs[j], c) && seq_contains(sccs[i], d) && has_path(g, c, d);
        assert |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]);
        assert |sccs[j]| > 0 && ClassComp(rep, sccs[j][0], sccs[j]);
        var ri := sccs[i][0];
        var rj := sccs[j][0];
        assert ri != rj;
        RepOfMember(rep, sccs[i], a);
        RepOfMember(rep, sccs[j], b);
        RepOfMember(rep, sccs[j], c);
        RepOfMember(rep, sccs[i], d);
        assert rep[a] == ri && rep[b] == rj && rep[c] == rj && rep[d] == ri;
        assert has_path(g, rep[a], a);
        assert has_path(g, b, rep[b]);
        assert has_path(g, ri, a);
        assert has_path(g, b, rj);
        PathConcat3(g, ri, a, b, rj);

        assert has_path(g, rep[c], c);
        assert has_path(g, d, rep[d]);
        assert has_path(g, rj, c);
        assert has_path(g, d, ri);
        PathConcat3(g, rj, c, d, ri);

        assert has_path(g, ri, rj) && has_path(g, rj, ri);
        assert 0 <= ri < |rep| && 0 <= rj < |rep|;
        RepMutual(g, rep, ri, rj);
        assert rep[ri] == rep[rj];
        assert rep[ri] == ri;
        assert rep[rj] == rj;
        assert ri == rj;
        assert false;
      }
      assert !scc_has_path(g, sccs, j, i);
    }
  }
  assert is_maximal_scc_structure(g, sccs);
  assert is_valid_scc_result(g, sccs);
}

