}

lemma {:vcs_split_on_every_assert} InTreeImpliesInLeft(val: int, l: Tree, r: Tree, v: int)
  requires v < val
  requires v !in view(r)
  ensures (v in view(Node(val, l, r))) ==> (v in view(l))
{
