lemma {:vcs_split_on_every_assert} BstSplitLeft(t: Tree, v: int)
  requires t.Node?
  requires is_bst(t)
  requires v < t.val
  ensures v !in view(t.right)
  ensures (v in view(t)) <==> (v in view(t.left))
{
  match t {
    case Empty =>
      assert false;
    case Node(val, l, r) =>
      assert t == Node(val, l, r);
      assert v < val;
      assert is_bst(Node(val, l, r));
      assert (forall x :: x in view(l) ==> x < val) && is_bst(l) && (forall x :: x in view(r) ==> x > val) && is_bst(r);
      assert forall x :: x in view(l) ==> x < val;
      assert forall x :: x in view(r) ==> x > val;
      if v in view(r) {
        assert v > val;
        assert false;
      }
      assert v !in view(r);
      assert r == t.right;
      assert v !in view(t.right);
      InTreeImpliesInLeft(val, l, r, v);
      assert (v in view(Node(val, l, r))) ==> (v in view(l));
      MemberEq(t, Node(val, l, r), v);
      assert (v in view(t)) <==> (v in view(Node(val, l, r)));
      IffLeft(v in view(t), v in view(Node(val, l, r)));
      assert (v in view(t)) ==> (v in view(Node(val, l, r)));
      ImplTrans(v in view(t), v in view(Node(val, l, r)), v in view(l));
      assert (v in view(t)) ==> (v in view(l));
      InLeftImpliesInTree(val, l, r, v);
      assert (v in view(l)) ==> (v in view(Node(val, l, r)));
      IffSym(v in view(t), v in view(Node(val, l, r)));
      assert (v in view(Node(val, l, r))) <==> (v in view(t));
      IffLeft(v in view(Node(val, l, r)), v in view(t));
      assert (v in view(Node(val, l, r))) ==> (v in view(t));
      ImplTrans(v in view(l), v in view(Node(val, l, r)), v in view(t));
      assert (v in view(l)) ==> (v in view(t));
      IffFromImpl(v in view(t), v in view(l));
      assert (v in view(t)) <==> (v in view(l));
      assert l == t.left;
      MemberEq(l, t.left, v);
      assert (v in view(l)) <==> (v in view(t.left));
      IffTrans(v in view(t), v in view(l), v in view(t.left));
      assert (v in view(t)) <==> (v in view(t.left));
  }
}

