lemma {:vcs_split_on_every_assert} RotateRightOk(left: Tree, rval: int, rr: Tree)
  requires left.Node?
  requires is_bst(left)
  requires is_bst(rr)
  requires forall x :: x in view(left) ==> x < rval
  requires forall x :: x in view(rr) ==> x > rval
  ensures is_bst(Node(left.val, left.left, Node(rval, left.right, rr)))
  ensures view(Node(left.val, left.left, Node(rval, left.right, rr))) == view(left) + view(rr) + {rval}
{
  NodeParts(left);
  var lval := left.val;
  var ll := left.left;
  var lr := left.right;
  assert left == Node(lval, ll, lr);

  ExtractBst(left);
  assert is_bst(left.left);
  assert is_bst(left.right);
  assert ll == left.left && lr == left.right && lval == left.val;
  assert is_bst(ll);
  assert is_bst(lr);
  assert lval in view(left);
  assert lval < rval;

  forall y | y in view(ll)
    ensures y < lval
  {
    assert y in view(left.left);
    assert y < left.val;
  }
  forall y | y in view(lr)
    ensures y > lval
  {
    assert y in view(left.right);
    assert y > left.val;
  }

  forall x | x in view(lr)
    ensures x < rval
  {
    ViewMember(lval, ll, lr, x);
    assert x in view(Node(lval, ll, lr));
    assert x in view(left);
    assert x < rval;
  }

  assert forall x :: x in view(lr) ==> x < rval;
  assert forall x :: x in view(rr) ==> x > rval;
  assert is_bst(lr);
  assert is_bst(rr);
  ProveBst(rval, lr, rr);
  var inner := Node(rval, lr, rr);
  assert is_bst(inner);

  forall x | x in view(inner)
    ensures x > lval
  {
    ViewMember(rval, lr, rr, x);
    assert x == rval || x in view(lr) || x in view(rr);
    if x == rval {
      assert lval < rval;
      assert x > lval;
    } else if x in view(lr) {
      assert x > lval;
    } else {
      assert x != rval;
      assert x !in view(lr);
      assert x in view(rr);
      assert x > rval;
      assert lval < rval;
      assert x > lval;
    }
  }

  assert forall x :: x in view(inner) ==> x > lval;
  assert forall x :: x in view(ll) ==> x < lval;
  assert is_bst(ll);
  assert is_bst(inner);
  ProveBst(lval, ll, inner);
  var res := Node(lval, ll, inner);
  assert is_bst(res);
  assert lval == left.val && ll == left.left && lr == left.right;
  assert inner == Node(rval, lr, rr);
  assert res == Node(left.val, left.left, Node(rval, left.right, rr));
  assert is_bst(Node(left.val, left.left, Node(rval, left.right, rr)));

  var target := view(left) + view(rr) + {rval};
  forall x {:trigger x in view(res)} {:trigger x in target}
    ensures (x in view(res)) <==> (x in target)
  {
    assert res == Node(lval, ll, inner);
    assert inner == Node(rval, lr, rr);
    ViewMember(lval, ll, inner, x);
    ViewMember(rval, lr, rr, x);
    ViewMember(lval, ll, lr, x);
    assert (x in view(res)) <==> (x == lval || x in view(ll) || x in view(inner));
    assert (x in view(inner)) <==> (x == rval || x in view(lr) || x in view(rr));
    assert (x in view(Node(lval, ll, lr))) <==> (x == lval || x in view(ll) || x in view(lr));
    assert left == Node(lval, ll, lr);
    assert (x in view(left)) <==> (x == lval || x in view(ll) || x in view(lr));
    InAdd(x, view(left) + view(rr), {rval});
    InAdd(x, view(left), view(rr));
    InSingleton(x, rval);
    assert target == (view(left) + view(rr)) + {rval};
    assert (x in target) <==> (x in ((view(left) + view(rr)) + {rval}));
    assert (x in ((view(left) + view(rr)) + {rval})) <==> (x in (view(left) + view(rr)) || x in {rval});
    assert (x in (view(left) + view(rr))) <==> (x in view(left) || x in view(rr));
    assert (x in {rval}) <==> (x == rval);
    assert (x in target) <==> (x in view(left) || x in view(rr) || x == rval);
    assert (x in view(left) || x in view(rr) || x == rval) <==> (x == lval || x in view(ll) || x in view(lr) || x in view(rr) || x == rval);
    assert (x in view(res)) <==> (x == lval || x in view(ll) || x == rval || x in view(lr) || x in view(rr));
    assert (x in target) <==> (x == lval || x in view(ll) || x in view(lr) || x in view(rr) || x == rval);
    assert (x in view(res)) <==> (x in target);
  }
  assert forall x {:trigger x in view(res)} {:trigger x in target} :: (x in view(res)) <==> (x in target);
  SetEq(view(res), target);
  assert view(res) == target;
  assert target == view(left) + view(rr) + {rval};
  assert view(res) == view(left) + view(rr) + {rval};
  assert view(Node(left.val, left.left, Node(rval, left.right, rr))) == view(res);
  assert view(Node(left.val, left.left, Node(rval, left.right, rr))) == view(left) + view(rr) + {rval};
}

lemma {:vcs_split_on_every_assert} RotateLeftOk(right: Tree, lval: int, ll: Tree)
  requires right.Node?
  requires is_bst(right)
  requires is_bst(ll)
  requires forall x :: x in view(right) ==> x > lval
  requires forall x :: x in view(ll) ==> x < lval
  ensures is_bst(Node(right.val, Node(lval, ll, right.left), right.right))
  ensures view(Node(right.val, Node(lval, ll, right.left), right.right)) == view(ll) + view(right) + {lval}
{
  NodeParts(right);
  var rval := right.val;
  var rl := right.left;
  var rr := right.right;
  assert right == Node(rval, rl, rr);

  ExtractBst(right);
  assert is_bst(right.left);
  assert is_bst(right.right);
  assert rl == right.left && rr == right.right && rval == right.val;
  assert is_bst(rl);
  assert is_bst(rr);
  ViewMember(rval, rl, rr, rval);
  assert rval in view(Node(rval, rl, rr));
  assert rval in view(right);
  assert rval > lval;
  assert lval < rval;

  forall y | y in view(rl)
    ensures y > lval
  {
    ViewMember(rval, rl, rr, y);
    assert y in view(Node(rval, rl, rr));
    assert y in view(right);
    assert y > lval;
  }
  forall y | y in view(rl)
    ensures y < rval
  {
    assert y in view(right.left);
    assert y < right.val;
    assert right.val == rval;
  }
  forall y | y in view(rr)
    ensures y > rval
  {
    assert y in view(right.right);
    assert y > right.val;
    assert right.val == rval;
  }

  assert forall y :: y in view(rl) ==> y > lval;
  assert forall y :: y in view(ll) ==> y < lval;
  assert is_bst(ll);
  assert is_bst(rl);
  ProveBst(lval, ll, rl);
  var inner := Node(lval, ll, rl);
  assert is_bst(inner);

  forall x | x in view(inner)
    ensures x < rval
  {
    ViewMember(lval, ll, rl, x);
    assert x == lval || x in view(ll) || x in view(rl);
    if x == lval {
      assert x < rval;
    } else if x in view(ll) {
      assert x < lval;
      assert lval < rval;
      assert x < rval;
    } else {
      assert x != lval;
      assert x !in view(ll);
      assert x in view(rl);
      assert x < rval;
    }
  }

  assert forall x :: x in view(inner) ==> x < rval;
  assert forall x :: x in view(rr) ==> x > rval;
  assert is_bst(inner);
  assert is_bst(rr);
  ProveBst(rval, inner, rr);
  var res := Node(rval, inner, rr);
  assert is_bst(res);
  assert rval == right.val && rl == right.left && rr == right.right;
  assert inner == Node(lval, ll, rl);
  assert res == Node(right.val, Node(lval, ll, right.left), right.right);
  assert is_bst(Node(right.val, Node(lval, ll, right.left), right.right));

  var target := view(ll) + view(right) + {lval};
  forall x {:trigger x in view(res)} {:trigger x in target}
    ensures (x in view(res)) <==> (x in target)
  {
    assert res == Node(rval, inner, rr);
    assert inner == Node(lval, ll, rl);
    ViewMember(rval, inner, rr, x);
    ViewMember(lval, ll, rl, x);
    ViewMember(rval, rl, rr, x);
    assert (x in view(res)) <==> (x == rval || x in view(inner) || x in view(rr));
    assert (x in view(inner)) <==> (x == lval || x in view(ll) || x in view(rl));
    assert (x in view(Node(rval, rl, rr))) <==> (x == rval || x in view(rl) || x in view(rr));
    assert right == Node(rval, rl, rr);
    assert (x in view(right)) <==> (x == rval || x in view(rl) || x in view(rr));
    InAdd(x, view(ll) + view(right), {lval});
    InAdd(x, view(ll), view(right));
    InSingleton(x, lval);
    assert target == (view(ll) + view(right)) + {lval};
    assert (x in target) <==> (x in ((view(ll) + view(right)) + {lval}));
    assert (x in ((view(ll) + view(right)) + {lval})) <==> (x in (view(ll) + view(right)) || x in {lval});
    assert (x in (view(ll) + view(right))) <==> (x in view(ll) || x in view(right));
    assert (x in {lval}) <==> (x == lval);
    assert (x in target) <==> (x in view(ll) || x in view(right) || x == lval);
    assert (x in view(ll) || x in view(right) || x == lval) <==> (x in view(ll) || x == rval || x in view(rl) || x in view(rr) || x == lval);
    assert (x in view(res)) <==> (x == rval || x == lval || x in view(ll) || x in view(rl) || x in view(rr));
    assert (x in target) <==> (x == lval || x in view(ll) || x == rval || x in view(rl) || x in view(rr));
    assert (x in view(res)) <==> (x in target);
  }
  assert forall x {:trigger x in view(res)} {:trigger x in target} :: (x in view(res)) <==> (x in target);
  SetEq(view(res), target);
  assert view(res) == target;
  assert target == view(ll) + view(right) + {lval};
  assert view(Node(right.val, Node(lval, ll, right.left), right.right)) == view(res);
  assert view(Node(right.val, Node(lval, ll, right.left), right.right)) == view(ll) + view(right) + {lval};
}

method {:vcs_split_on_every_assert} splay(tree: Tree, v: int) returns (res: Tree)
  requires tree.Node?
  requires is_bst(tree)
  ensures res.Node?
  ensures is_bst(res)
  ensures view(res) == view(tree)
  ensures v in view(tree) ==> res.val == v
  ensures v !in view(tree) ==> res.val in view(res)
  decreases tree
{
  if v == tree.val {
    res := tree;
    assert res == tree;
    assert res.Node?;
    assert is_bst(res);
    assert view(res) == view(tree);
    RootInView(res);
    assert res.val in view(res);
    assert res.val == v;
    assert v in view(tree) ==> res.val == v;
  } else if v < tree.val {
    BstSplitLeft(tree, v);
    if tree.left.Empty? {
      res := tree;
      ViewEmpty(tree.left);
      assert view(tree.left) == {};
      assert v !in {};
      assert v !in view(tree.left);
      assert (v in view(tree)) <==> (v in view(tree.left));
      IffFalse(v in view(tree), v in view(tree.left));
      assert v !in view(tree);
      assert res.Node?;
      assert is_bst(res);
      assert view(res) == view(tree);
      RootInView(res);
      assert res.val in view(res);
      assert v in view(tree) ==> res.val == v;
    } else {
      assert tree.left.Node?;
      ExtractBst(tree);
      var leftS := splay(tree.left, v);
      assert leftS.Node?;
      assert is_bst(leftS);
      assert view(leftS) == view(tree.left);
      assert forall x :: x in view(tree.left) ==> x < tree.val;
      TransferLt(view(leftS), view(tree.left), tree.val);
      assert forall x :: x in view(leftS) ==> x < tree.val;
      assert forall x :: x in view(tree.right) ==> x > tree.val;
      assert is_bst(tree.right);
      RotateRightOk(leftS, tree.val, tree.right);
      res := Node(leftS.val, leftS.left, Node(tree.val, leftS.right, tree.right));
      assert res.Node?;
      assert is_bst(res);
      assert view(res) == view(leftS) + view(tree.right) + {tree.val};
      UnionCong(view(leftS), view(tree.left), view(tree.right), {tree.val});
      assert view(res) == view(tree.left) + view(tree.right) + {tree.val};
