lemma EmptyNodeView(n: Node)
    requires n.is_empty()
    ensures n.view() == iset{}
{
    forall key: seq<int>
        ensures key !in n.view()
    {
        if |key| == 0 {
            assert !n.contains(key);
        } else if key[0] < n.val {
            assert n.left.None?;
            assert !n.contains(key);
        } else if key[0] > n.val {
            assert n.right.None?;
            assert !n.contains(key);
        } else if |key| == 1 {
            assert !n.is_end;
            assert !n.contains(key);
