method PackNode(
    v: int,
    e: bool,
    l: Option<Node>,
    m: Option<Node>,
    r: Option<Node>
) returns (o: Option<Node>)
    requires 0 <= v < 256
    requires opt_well_formed(l)
    requires opt_well_formed(m)
    requires opt_well_formed(r)
    requires forall s | s in opt_view(l) :: |s| > 0 && s[0] < v
    requires forall s | s in opt_view(r) :: |s| > 0 && s[0] > v
    ensures opt_well_formed(o)
    ensures opt_view(o) == Node(v, e, l, m, r).view()
{
    var n := Node(v, e, l, m, r);

    match l {
        case Some(x) =>
            assert x.well_formed();
            assert !x.is_empty();
            assert opt_view(l) == x.view();
            assert forall s | s in x.view() ::
                |s| > 0 && s[0] < v;
        case None =>
    }

    match m {
        case Some(x) =>
            assert x.well_formed();
            assert !x.is_empty();
        case None =>
    }

    match r {
        case Some(x) =>
            assert x.well_formed();
            assert !x.is_empty();
            assert opt_view(r) == x.view();
            assert forall s | s in x.view() ::
                |s| > 0 && s[0] > v;
        case None =>
    }

    assert n.well_formed();

    if !e && l.None? && m.None? && r.None? {
        assert n.is_empty();
        EmptyNodeView(n);
        o := None;
    } else {
        assert !n.is_empty();
        o := Some(n);
