lemma ViewAfterLeft(
    n: Node,
    nl: Option<Node>,
    key: seq<int>
)
    requires |key| > 0
    requires key[0] < n.val
    requires opt_view(nl) == opt_view(n.left) - iset{key}
    ensures
        Node(n.val, n.is_end, nl, n.mid, n.right).view()
        == n.view() - iset{key}
{
    var nn := Node(n.val, n.is_end, nl, n.mid, n.right);

    forall q: seq<int>
        ensures
            q in nn.view()
            <==>
            q in n.view() - iset{key}
    {
        if |q| == 0 {
            assert !nn.contains(q);
            assert !n.contains(q);
            assert q != key;
        } else if q[0] < n.val {
            assert q in nn.view() <==> q in opt_view(nl);
            assert q in n.view() <==> q in opt_view(n.left);
            assert q in opt_view(nl)
                <==> q in opt_view(n.left) - iset{key};
            assert q in opt_view(nl)
                <==> q in opt_view(n.left) && q != key;
        } else {
            assert nn.contains(q) == n.contains(q);
            assert q in nn.view() <==> q in n.view();
            if q == key {
                assert q[0] == key[0];
                assert false;
            }
            assert q != key;
        }

        assert q in n.view() - iset{key}
            <==> q in n.view() && q != key;
        assert q in nn.view()
            <==> q in n.view() && q != key;
    }

    assert nn.view() == n.view() - iset{key};
}

