method insert(tree: Option<Node>, key: seq<int>) returns (res: Node)
    requires opt_well_formed(tree)
    // Constraint: Input key elements must represent bytes (u8)
    requires forall k :: k in key ==> 0 <= k < 256
    requires |key| > 0
    ensures
        // Invariant Preservation
        && res.well_formed()
        && !res.is_empty()
        // Set Update
        && res.view() == opt_view(tree) + iset{key}
    decreases |key|, tree
{
    assert key[0] in key;
    assert 0 <= key[0] < 256;

    match tree
    case None =>
        if |key| == 1 {
            res := Node(key[0], true, None, None, None);
            fresh_leaf_well_formed(key);
            fresh_leaf_view(key);
        } else {
            assert |key[1..]| > 0;
            assert
                forall k :: k in key[1..] ==> 0 <= k < 256;

            var child := insert(None, key[1..]);

            fresh_branch_well_formed(key, child);
            fresh_branch_view(key, child);

            res :=
                Node(key[0], false, None, Some(child), None);
        }

    case Some(n) =>
        assert n.well_formed();
        assert !n.is_empty();
        children_well_formed(n);

        if key[0] < n.val {
            var child := insert(n.left, key);

            left_update_well_formed(n, child, key);
            left_update_view(n, child, key);

            res :=
                Node(
                    n.val, n.is_end,
                    Some(child), n.mid, n.right
                );
        } else if key[0] > n.val {
            var child := insert(n.right, key);

            right_update_well_formed(n, child, key);
            right_update_view(n, child, key);

            res :=
                Node(
                    n.val, n.is_end,
                    n.left, n.mid, Some(child)
                );
        } else if |key| == 1 {
            mark_end_well_formed(n);
            mark_end_view(n, key);

            res :=
                Node(
                    n.val, true, n.left, n.mid, n.right
