        } else {
            assert |key[1..]| > 0;
            assert
                forall k :: k in key[1..] ==> 0 <= k < 256;

            var child := insert(n.mid, key[1..]);

            middle_update_well_formed(n, child);
            middle_update_view(n, child, key);

            res :=
                Node(
                    n.val, n.is_end,
                    n.left, Some(child), n.right
                );
        }
