lemma {:vcs_split_on_every_assert} Decompose(f: FlowMap, cut: seq<bool>, rows: int, cols: int)
  requires 0 <= rows <= |cut|
  requires 0 < cols <= |cut|
  ensures SumSel(f, cut, rows, cols, true, false) ==
    SumSel(f, cut, rows, cols - 1, true, false) +
      (if cut[cols - 1] then ColSel(f, cut, cols - 1, rows, true) else 0)
  decreases rows
{
  if rows == 0 {
    assert SumSel(f, cut, 0, cols, true, false) == 0;
    assert SumSel(f, cut, 0, cols - 1, true, false) == 0;
    assert ColSel(f, cut, cols - 1, 0, true) == 0;
  } else {
    Decompose(f, cut, rows - 1, cols);
    var x := rows - 1;
    var cR := cut[x];
    var cC := cut[cols - 1];
    var flow := get_flow(f, x, cols - 1);
    SumSelStep(f, cut, rows, cols, true, false);
    SumSelStep(f, cut, rows, cols - 1, true, false);
    RowSelStep(f, cut, x, cols, true);
    ColSelStep(f, cut, cols - 1, rows, true);
    var A := SumSel(f, cut, x, cols - 1, true, false);
    assert SumSel(f, cut, x, cols, true, false) ==
      A + (if cC then ColSel(f, cut, cols - 1, x, true) else 0);
    if cR && cC {
      assert RowSel(f, cut, x, cols, true) == RowSel(f, cut, x, cols - 1, true) + flow;
      assert ColSel(f, cut, cols - 1, rows, true) == ColSel(f, cut, cols - 1, x, true) + flow;
      assert SumSel(f, cut, rows, cols, true, false) ==
        SumSel(f, cut, x, cols, true, false) + RowSel(f, cut, x, cols, true);
      assert SumSel(f, cut, rows, cols - 1, true, false) ==
        A + RowSel(f, cut, x, cols - 1, true);
    } else if cR && !cC {
      assert RowSel(f, cut, x, cols, true) == RowSel(f, cut, x, cols - 1, true);
      assert SumSel(f, cut, rows, cols, true, false) ==
        SumSel(f, cut, x, cols, true, false) + RowSel(f, cut, x, cols, true);
      assert SumSel(f, cut, rows, cols - 1, true, false) ==
        A + RowSel(f, cut, x, cols - 1, true);
      assert SumSel(f, cut, x, cols, true, false) == A;
    } else if !cR && cC {
      assert SumSel(f, cut, rows, cols, true, false) == SumSel(f, cut, x, cols, true, false);
      assert SumSel(f, cut, rows, cols - 1, true, false) == A;
      assert ColSel(f, cut, cols - 1, rows, true) == ColSel(f, cut, cols - 1, x, true);
    } else {
      assert SumSel(f, cut, rows, cols, true, false) == SumSel(f, cut, x, cols, true, false);
      assert SumSel(f, cut, rows, cols - 1, true, false) == A;
      assert SumSel(f, cut, x, cols, true, false) == A;
    }
  }
}

lemma Transpose(f: FlowMap, cut: seq<bool>, i: int, j: int)
  requires 0 <= i <= |cut| && 0 <= j <= |cut|
  ensures SumSel(f, cut, i, j, true, true) == SumSel(f, cut, j, i, true, false)
  decreases i, j
{
  if i == 0 || j == 0 {
    if i == 0 {
      assert SumSel(f, cut, i, j, true, true) == 0;
      SumSelZeroJ(f, cut, j, true, false);
    }
    if j == 0 {
      SumSelZeroJ(f, cut, i, true, true);
      assert SumSel(f, cut, j, i, true, false) == 0;
    }
  } else {
    Transpose(f, cut, i - 1, j);
    Decompose(f, cut, j, i);
    SumSelStep(f, cut, i, j, true, true);
    assert SumSel(f, cut, i, j, true, true) ==
      SumSel(f, cut, i - 1, j, true, true) +
        (if cut[i - 1] then ColSel(f, cut, i - 1, j, true) else 0);
    assert SumSel(f, cut, i - 1, j, true, true) == SumSel(f, cut, j, i - 1, true, false);
  }
}

