  ensures EdgeIndex(g, u, v) >= 0
{
  assert exists i :: 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == c;
  var i :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == c;
  EdgeIndexAt(g, u, i);
  CapAt(g, u, i);
}

ghost function ExcessTo(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0
  else if 0 <= u < |res| && 0 <= j - 1 < |res[u]| then
    ExcessTo(g, res, u, j - 1) + Cap(g, u, j - 1) - res[u][j - 1]
  else
    ExcessTo(g, res, u, j - 1)
}

ghost function Excess(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int): int {
  if 0 <= u < |g| && u < |res| && |res[u]| >= |g| then ExcessTo(g, res, u, |g|) else 0
}

lemma ExcessToStep(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int)
  requires j > 0
  requires 0 <= u < |res| && j - 1 < |res[u]|
  ensures ExcessTo(g, res, u, j) == ExcessTo(g, res, u, j - 1) + Cap(g, u, j - 1) - res[u][j - 1]
{
}

lemma ExcessInit(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int)
  requires 0 <= u < |g| && u < |res| && 0 <= j <= |res[u]|
  requires forall v :: 0 <= v < j ==> res[u][v] == Cap(g, u, v)
  ensures ExcessTo(g, res, u, j) == 0
  decreases j
{
  if j > 0 {
    ExcessInit(g, res, u, j - 1);
    ExcessToStep(g, res, u, j);
  }
}

lemma ExcessBound(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int)
  requires 0 <= u < |g| && u < |res| && 0 <= j <= |res[u]|
  requires forall v :: 0 <= v < j ==> res[u][v] >= 0
  requires forall v :: 0 <= v < j ==> Cap(g, u, v) <= 100_000
  ensures ExcessTo(g, res, u, j) <= j * 100_000
  decreases j
{
  if j > 0 {
    ExcessBound(g, res, u, j - 1);
    ExcessToStep(g, res, u, j);
    assert res[u][j - 1] >= 0;
    assert Cap(g, u, j - 1) - res[u][j - 1] <= Cap(g, u, j - 1);
    assert Cap(g, u, j - 1) <= 100_000;
    assert ExcessTo(g, res, u, j) <= (j - 1) * 100_000 + 100_000;
  }
}

lemma LimitMul(n: int)
  requires 0 <= n <= 1000
  ensures n * 100_000 <= 1000 * 100_000
{
  assert 1000 * 100_000 - n * 100_000 == (1000 - n) * 100_000;
  assert (1000 - n) * 100_000 >= 0;
}

ghost function FlowOn(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, v: int): int {
  if 0 <= u < |g| && 0 <= v < |g| && u < |res| && v < |res[u]| then
    var c := Cap(g, u, v);
    if c > res[u][v] then c - res[u][v] else 0
  else 0
}

lemma FlowOnLeCap(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, v: int)
  requires 0 <= u < |g| && 0 <= v < |g| && u < |res| && v < |res[u]|
  requires res[u][v] >= 0
  requires Cap(g, u, v) >= 0
  ensures 0 <= FlowOn(g, res, u, v) <= Cap(g, u, v)
{
  var c := Cap(g, u, v);
  if c > res[u][v] {
    assert FlowOn(g, res, u, v) == c - res[u][v];
  }
}

lemma FlowDiff(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, v: int)
  requires 0 <= u < |g| && 0 <= v < |g|
  requires DimOK(g, res)
  requires res[u][v] >= 0 && res[v][u] >= 0
  requires res[u][v] + res[v][u] == Cap(g, u, v) + Cap(g, v, u)
  ensures FlowOn(g, res, u, v) - FlowOn(g, res, v, u) == Cap(g, u, v) - res[u][v]
{
  var a := Cap(g, u, v);
  var b := Cap(g, v, u);
  var r := res[u][v];
  var q := res[v][u];
  assert r + q == a + b;
  if u == v {
    assert r == q;
    assert 2 * r == 2 * a;
    assert r == a;
    assert FlowOn(g, res, u, v) == 0;
  } else if r < a {
    assert q == a + b - r;
    assert q >= b;
    assert FlowOn(g, res, u, v) == a - r;
    assert FlowOn(g, res, v, u) == 0;
  } else if r == a {
    assert q == a + b - r;
    assert q >= b;
    assert FlowOn(g, res, u, v) == 0;
    assert FlowOn(g, res, v, u) == 0;
    assert a - r == 0;
  } else {
    assert r > a;
    assert q == a + b - r;
    assert q < b;
    assert FlowOn(g, res, u, v) == 0;
    assert FlowOn(g, res, v, u) == b - q;
    assert b - q == r - a;
    assert 0 - (b - q) == a - r;
  }
}

lemma SaturatePair(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, v: int)
  requires 0 <= u < |g| && 0 <= v < |g|
  requires DimOK(g, res)
  requires res[u][v] == 0
  requires res[v][u] >= 0
  requires Cap(g, u, v) >= 0 && Cap(g, v, u) >= 0
  requires res[u][v] + res[v][u] == Cap(g, u, v) + Cap(g, v, u)
  ensures FlowOn(g, res, u, v) == Cap(g, u, v)
  ensures FlowOn(g, res, v, u) == 0
{
  var a := Cap(g, u, v);
  var b := Cap(g, v, u);
  assert res[v][u] == a + b;
  assert res[v][u] >= b;
  assert FlowOn(g, res, v, u) == 0;
  if a > 0 {
    assert FlowOn(g, res, u, v) == a;
  } else {
    assert a == 0;
    assert FlowOn(g, res, u, v) == 0;
  }
}

ghost function SumFOut(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0 else SumFOut(g, res, u, j - 1) + FlowOn(g, res, u, j - 1)
}

ghost function SumFIn(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0 else SumFIn(g, res, u, j - 1) + FlowOn(g, res, j - 1, u)
}

lemma SumFlowDiff(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, j: int)
  requires DimOK(g, res)
  requires 0 <= u < |g| && 0 <= j <= |g|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==> res[a][b] >= 0
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
    res[a][b] + res[b][a] == Cap(g, a, b) + Cap(g, b, a)
  ensures SumFOut(g, res, u, j) - SumFIn(g, res, u, j) == ExcessTo(g, res, u, j)
  decreases j
{
  if j > 0 {
    SumFlowDiff(g, res, u, j - 1);
    FlowDiff(g, res, u, j - 1);
    ExcessToStep(g, res, u, j);
  }
}

ghost predicate ResOk(g: seq<seq<(int, int)>>, res: seq<seq<int>>, s: int, t: int, total: int) {
  var n := |g|;
  WFSeq(g) && DimOK(g, res) &&
  0 <= s < n && 0 <= t < n && s != t &&
  (forall u, v :: 0 <= u < n && 0 <= v < n ==> res[u][v] >= 0) &&
  (forall u, v :: 0 <= u < n && 0 <= v < n ==>
      res[u][v] + res[v][u] == Cap(g, u, v) + Cap(g, v, u)) &&
  (forall u :: 0 <= u < n && u != s && u != t ==> Excess(g, res, u) == 0) &&
  Excess(g, res, s) == total &&
  Excess(g, res, t) == -total
}

lemma InitSkews(g: seq<seq<(int, int)>>, res: seq<seq<int>>, s: int, t: int)
  requires WFSeq(g) && DimOK(g, res)
  requires 0 <= s < |g| && 0 <= t < |g| && s != t
  requires forall u, v :: 0 <= u < |g| && 0 <= v < |g| ==> res[u][v] == Cap(g, u, v)
  requires forall u, v :: 0 <= u < |g| && 0 <= v < |g| ==> res[u][v] >= 0
  ensures ResOk(g, res, s, t, 0)
{
  var n := |g|;
  forall u | 0 <= u < n
    ensures Excess(g, res, u) == 0
  {
    ExcessInit(g, res, u, n);
    assert Excess(g, res, u) == ExcessTo(g, res, u, n);
  }
}

method ConstInt(n: int, val: int) returns (s: seq<int>)
  requires n >= 0
  ensures |s| == n
  ensures forall i :: 0 <= i < n ==> s[i] == val
{
  s := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n && |s| == i
    invariant forall j :: 0 <= j < i ==> s[j] == val
  {
    s := s + [val];
    i := i + 1;
  }
}

method ConstBool(n: int, val: bool) returns (s: seq<bool>)
  requires n >= 0
  ensures |s| == n
  ensures forall i :: 0 <= i < n ==> s[i] == val
{
  s := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n && |s| == i
    invariant forall j :: 0 <= j < i ==> s[j] == val
  {
    s := s + [val];
    i := i + 1;
  }
}

method InitRes(g: seq<seq<(int, int)>>) returns (res: seq<seq<int>>)
  requires WFSeq(g)
  requires capacities_bounded(g)
  ensures DimOK(g, res)
  ensures forall u, v :: 0 <= u < |g| && 0 <= v < |g| ==> res[u][v] == Cap(g, u, v)
  ensures forall u, v :: 0 <= u < |g| && 0 <= v < |g| ==> res[u][v] >= 0
{
  var n := |g|;
  res := [];
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |res| == u
    invariant forall a :: 0 <= a < u ==> |res[a]| == n
    invariant forall a, b :: 0 <= a < u && 0 <= b < n ==> res[a][b] == Cap(g, a, b)
    invariant forall a, b :: 0 <= a < u && 0 <= b < n ==> res[a][b] >= 0
  {
    var row := ConstInt(n, 0);
    var i := 0;
    while i < |g[u]|
      invariant 0 <= i <= |g[u]|
      invariant |row| == n
      invariant forall b :: 0 <= b < n ==> row[b] == CapPrefix(g, u, b, i)
      invariant forall b :: 0 <= b < n ==> row[b] >= 0
    {
      var v := g[u][i].0;
      var c := g[u][i].1;
      assert 0 <= v < n;
      assert has_capacity(g, u, v, c) by {
        assert 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == c;
      }
      assert c >= 0;
      ghost var old := row;
      ghost var oldI := i;
      row := row[v := c];
      i := i + 1;
      forall b | 0 <= b < n
        ensures row[b] == CapPrefix(g, u, b, i)
      {
        CapPrefixStep(g, u, b, oldI);
        if b == v {
          assert g[u][oldI].0 == v;
          assert CapPrefix(g, u, b, oldI + 1) == c;
          assert row[b] == c;
        } else {
          assert row[b] == old[b];
          assert g[u][oldI].0 != b;
          assert CapPrefix(g, u, b, oldI + 1) == CapPrefix(g, u, b, oldI);
        }
      }
    }
    forall b | 0 <= b < n
      ensures row[b] == Cap(g, u, b)
    {
      assert Cap(g, u, b) == CapPrefix(g, u, b, |g[u]|);
    }
    res := res + [row];
    u := u + 1;
  }
}

ghost function CountVal(q: seq<int>, k: int, v: int): int
  decreases if k > 0 then k else 0
{
  if k <= 0 then 0
  else CountVal(q, k - 1, v) + (if 0 <= k - 1 < |q| && q[k - 1] == v then 1 else 0)
}

ghost function SumCount(q: seq<int>, k: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0 else SumCount(q, k, j - 1) + CountVal(q, k, j - 1)
}

lemma CountStep(q: seq<int>, k: int, v: int)
  requires k > 0 && k - 1 < |q|
  ensures CountVal(q, k, v) == CountVal(q, k - 1, v) + (if q[k - 1] == v then 1 else 0)
{
}

lemma CountPositiveMeansExists(q: seq<int>, k: int, v: int)
  requires 0 <= k <= |q|
  requires CountVal(q, k, v) >= 1
  ensures exists t :: 0 <= t < k && q[t] == v
  decreases k
{
  if k == 0 {
    assert CountVal(q, 0, v) == 0;
    assert false;
  } else if q[k - 1] == v {
    assert 0 <= k - 1 < k;
  } else {
    CountStep(q, k, v);
    assert CountVal(q, k, v) == CountVal(q, k - 1, v);
    CountPositiveMeansExists(q, k - 1, v);
  }
}

lemma CountsLeOne(q: seq<int>, k: int, v: int)
  requires 0 <= k <= |q|
  requires forall a, b :: 0 <= a < b < k ==> q[a] != q[b]
  ensures CountVal(q, k, v) <= 1
  decreases k
{
  if k > 0 {
    assert forall a, b :: 0 <= a < b < k - 1 ==> q[a] != q[b];
    CountsLeOne(q, k - 1, v);
    CountStep(q, k, v);
    if q[k - 1] == v && CountVal(q, k - 1, v) >= 1 {
      CountPositiveMeansExists(q, k - 1, v);
      var t :| 0 <= t < k - 1 && q[t] == v;
      assert q[t] == q[k - 1];
      assert false;
    }
  }
}

lemma SumAddOneJ(q: seq<int>, k: int, j: int, v0: int)
  requires 0 < k <= |q|
  requires q[k - 1] == v0
  ensures SumCount(q, k, j) == SumCount(q, k - 1, j) + (if 0 <= v0 < j then 1 else 0)
  decreases j
{
  if j > 0 {
    SumAddOneJ(q, k, j - 1, v0);
    CountStep(q, k, j - 1);
    var cNew := CountVal(q, k, j - 1);
    var cOld := CountVal(q, k - 1, j - 1);
    assert cNew == cOld + (if v0 == j - 1 then 1 else 0);
    var ePrev := if 0 <= v0 < j - 1 then 1 else 0;
    var eNow := if 0 <= v0 < j then 1 else 0;
    if v0 == j - 1 {
      assert ePrev == 0;
      assert eNow == 1;
    } else if 0 <= v0 < j - 1 {
      assert ePrev == 1 && eNow == 1;
    } else {
      assert ePrev == 0 && eNow == 0;
    }
  }
}

lemma SumEq(q: seq<int>, k: int, n: int)
  requires 0 <= k <= |q|
  requires n >= 0
  requires forall t :: 0 <= t < k ==> 0 <= q[t] < n
  ensures SumCount(q, k, n) == k
  decreases k
{
  if k > 0 {
    assert forall t :: 0 <= t < k - 1 ==> 0 <= q[t] < n;
    SumEq(q, k - 1, n);
    SumAddOneJ(q, k, n, q[k - 1]);
    assert 0 <= q[k - 1] < n;
  }
}

lemma SumLe(q: seq<int>, k: int, j: int)
  requires forall v :: 0 <= v < j ==> CountVal(q, k, v) <= 1
  ensures SumCount(q, k, j) <= j
  decreases j
{
  if j > 0 {
    assert forall v :: 0 <= v < j - 1 ==> CountVal(q, k, v) <= 1;
    SumLe(q, k, j - 1);
  }
}

lemma InjLen(q: seq<int>, n: int)
  requires n >= 0
  requires forall t :: 0 <= t < |q| ==> 0 <= q[t] < n
  requires forall a, b :: 0 <= a < b < |q| ==> q[a] != q[b]
  ensures |q| <= n
{
  forall v | 0 <= v < n
    ensures CountVal(q, |q|, v) <= 1
  {
    CountsLeOne(q, |q|, v);
  }
  SumEq(q, |q|, n);
  SumLe(q, |q|, n);
}

ghost predicate PathTree(res: seq<seq<int>>, parent: seq<int>, depth: seq<int>, vis: seq<bool>, s: int, n: int)
{
  |res| == n && |parent| == n && |depth| == n && |vis| == n &&
  (forall u :: 0 <= u < n ==> |res[u]| == n) &&
  0 <= s < n &&
  vis[s] && depth[s] == 0 &&
  (forall x :: 0 <= x < n && vis[x] ==> 0 <= depth[x] < n) &&
  (forall x :: 0 <= x < n && vis[x] && x != s ==>
      0 <= parent[x] < n && vis[parent[x]] &&
      depth[parent[x]] == depth[x] - 1 &&
      depth[x] >= 1 &&
      res[parent[x]][x] > 0)
}

method {:vcs_split_on_every_assert} Bfs(res: seq<seq<int>>, s: int, t: int)
  returns (found: bool, parent: seq<int>, depth: seq<int>, vis: seq<bool>)
  requires |res| >= 2
  requires forall u :: 0 <= u < |res| ==> |res[u]| == |res|
  requires 0 <= s < |res| && 0 <= t < |res| && s != t
  ensures var n := |res|;
    |vis| == n && |parent| == n && |depth| == n &&
    found == vis[t] &&
    PathTree(res, parent, depth, vis, s, n) &&
    (forall u, v :: 0 <= u < n && 0 <= v < n && vis[u] && res[u][v] > 0 ==> vis[v])
{
  var n := |res|;
  vis := ConstBool(n, false);
  parent := ConstInt(n, -1);
  depth := ConstInt(n, 0);
  var pos := ConstInt(n, -1);
  vis := vis[s := true];
  pos := pos[s := 0];
  var q: seq<int> := [s];
  var qi := 0;
  while qi < |q|
    invariant |vis| == n && |parent| == n && |depth| == n && |pos| == n
    invariant 0 <= qi <= |q| <= n
    invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n
    invariant forall k :: 0 <= k < |q| ==> vis[q[k]] && pos[q[k]] == k && 0 <= depth[q[k]] <= k
    invariant forall a, b :: 0 <= a < b < |q| ==> q[a] != q[b]
    invariant forall x :: 0 <= x < n ==> (vis[x] <==> 0 <= pos[x] < |q|)
    invariant forall x :: 0 <= x < n && vis[x] ==> q[pos[x]] == x
    invariant vis[s] && pos[s] == 0 && depth[s] == 0 && q[0] == s
    invariant forall x :: 0 <= x < n && vis[x] && x != s ==>
      0 <= parent[x] < n && vis[parent[x]] &&
      depth[parent[x]] == depth[x] - 1 && depth[x] >= 1 && res[parent[x]][x] > 0
    invariant forall k :: 0 <= k < qi ==> forall w :: 0 <= w < n && res[q[k]][w] > 0 ==> vis[w]
    decreases n - qi
  {
    var u := q[qi];
    var v := 0;
    while v < n
      invariant 0 <= v <= n
      invariant |vis| == n && |parent| == n && |depth| == n && |pos| == n
      invariant 0 <= qi < |q| <= n
      invariant u == q[qi]
      invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n
      invariant forall k :: 0 <= k < |q| ==> vis[q[k]] && pos[q[k]] == k && 0 <= depth[q[k]] <= k
      invariant forall a, b :: 0 <= a < b < |q| ==> q[a] != q[b]
      invariant forall x :: 0 <= x < n ==> (vis[x] <==> 0 <= pos[x] < |q|)
      invariant forall x :: 0 <= x < n && vis[x] ==> q[pos[x]] == x
      invariant vis[s] && pos[s] == 0 && depth[s] == 0 && q[0] == s
      invariant forall x :: 0 <= x < n && vis[x] && x != s ==>
        0 <= parent[x] < n && vis[parent[x]] &&
        depth[parent[x]] == depth[x] - 1 && depth[x] >= 1 && res[parent[x]][x] > 0
      invariant forall k :: 0 <= k < qi ==> forall w :: 0 <= w < n && res[q[k]][w] > 0 ==> vis[w]
      invariant forall w :: 0 <= w < v && res[u][w] > 0 ==> vis[w]
      decreases n - v
    {
      if res[u][v] > 0 && !vis[v] {
        var idx := |q|;
        assert pos[u] == qi;
        assert depth[u] <= qi;
        assert qi < idx;
        assert depth[u] + 1 <= idx;
        forall a | 0 <= a < |q|
          ensures q[a] != v
        {
          if q[a] == v {
            assert vis[v];
            assert false;
          }
        }
        ghost var qExt := q + [v];
        forall a, b | 0 <= a < b < |qExt|
          ensures qExt[a] != qExt[b]
        {
          if b < |q| {
            assert qExt[a] == q[a] && qExt[b] == q[b];
          } else {
            assert b == |q|;
            assert qExt[b] == v;
            assert qExt[a] == q[a];
            assert q[a] != v;
          }
        }
        forall t | 0 <= t < |qExt|
          ensures 0 <= qExt[t] < n
        {
          if t < |q| {
            assert qExt[t] == q[t];
          } else {
            assert qExt[t] == v && 0 <= v < n;
          }
        }
        InjLen(qExt, n);
        assert |qExt| <= n;
        assert idx < n;
        pos := pos[v := idx];
        vis := vis[v := true];
        parent := parent[v := u];
        depth := depth[v := depth[u] + 1];
        q := q + [v];
        assert depth[v] <= idx;
        assert q[idx] == v && pos[v] == idx;
      }
      v := v + 1;
    }
    qi := qi + 1;
  }
  found := vis[t];
  forall u, w | 0 <= u < n && 0 <= w < n && vis[u] && res[u][w] > 0
    ensures vis[w]
  {
    var k := pos[u];
    assert 0 <= k < |q|;
    assert k < qi;
    assert q[k] == u;
  }
  forall x | 0 <= x < n && vis[x]
    ensures 0 <= depth[x] < n
  {
    var k := pos[x];
    assert depth[x] <= k;
    assert k < |q| <= n;
    assert depth[x] < n;
  }
}

method BuildPath(res: seq<seq<int>>, parent: seq<int>, depth: seq<int>, vis: seq<bool>, s: int, t: int)
  returns (path: seq<int>)
  requires PathTree(res, parent, depth, vis, s, |res|)
  requires vis[t] && s != t
  ensures |path| >= 2
  ensures path[0] == s && path[|path| - 1] == t
  ensures forall k :: 0 <= k < |path| ==> 0 <= path[k] < |res| && vis[path[k]] && depth[path[k]] == k
  ensures forall k :: 0 <= k < |path| - 1 ==> parent[path[k + 1]] == path[k] && res[path[k]][path[k + 1]] > 0
  ensures forall k, m :: 0 <= k < m < |path| ==> path[k] != path[m]
{
  var n := |res|;
  var rev: seq<int> := [t];
  var cur := t;
  while cur != s
    invariant vis[cur] && 0 <= cur < n
    invariant |rev| >= 1 && rev[0] == cur && rev[|rev| - 1] == t
    invariant |rev| == depth[t] - depth[cur] + 1
    invariant forall k :: 0 <= k < |rev| ==> vis[rev[k]] && depth[rev[k]] == depth[cur] + k && 0 <= rev[k] < n
    invariant forall k :: 0 <= k < |rev| - 1 ==> parent[rev[k + 1]] == rev[k] && res[rev[k]][rev[k + 1]] > 0
    decreases depth[cur]
  {
    assert cur != s;
    var p := parent[cur];
    assert depth[p] == depth[cur] - 1;
    rev := [p] + rev;
    cur := p;
  }
  path := rev;
  assert depth[cur] == 0;
  assert depth[s] == 0;
  forall k, m | 0 <= k < m < |path|
    ensures path[k] != path[m]
  {
    assert depth[path[k]] == k && depth[path[m]] == m;
  }
  assert depth[t] >= 1;
  assert |path| == depth[t] + 1;
}

method MinRes(res: seq<seq<int>>, path: seq<int>) returns (d: int)
  requires |path| >= 2
  requires forall k :: 0 <= k < |path| ==> 0 <= path[k] < |res|
  requires forall k :: 0 <= k < |path| - 1 ==> path[k + 1] < |res[path[k]]|
  requires forall k :: 0 <= k < |path| - 1 ==> res[path[k]][path[k + 1]] > 0
  ensures d >= 1
  ensures forall k :: 0 <= k < |path| - 1 ==> d <= res[path[k]][path[k + 1]]
{
  d := res[path[0]][path[1]];
  var i := 1;
  while i < |path| - 1
    invariant 1 <= i <= |path| - 1
    invariant d >= 1
    invariant forall k :: 0 <= k < i ==> d <= res[path[k]][path[k + 1]]
    decreases |path| - i
  {
    var r := res[path[i]][path[i + 1]];
    var nd := if r < d then r else d;
    assert nd >= 1;
    assert forall k :: 0 <= k < i ==> nd <= res[path[k]][path[k + 1]];
    assert nd <= r;
    d := nd;
    i := i + 1;
  }
}

ghost function PathDelta(path: seq<int>, x: int, e: int): int
  decreases if e > 0 then e else 0
{
  if e <= 0 || e >= |path| then 0
  else PathDelta(path, x, e - 1) + (if path[e - 1] == x then 1 else 0) - (if path[e] == x then 1 else 0)
}

lemma PathDeltaStep(path: seq<int>, x: int, e: int)
  requires 0 <= e < |path| - 1
  ensures PathDelta(path, x, e + 1) ==
    PathDelta(path, x, e) + (if path[e] == x then 1 else 0) - (if path[e + 1] == x then 1 else 0)
{
}

lemma DeltaForm(path: seq<int>, u: int, e: int)
  requires 0 <= e < |path|
  ensures PathDelta(path, u, e) ==
    (if e == 0 then 0
     else (if u == path[0] then 1 else 0) - (if u == path[e] then 1 else 0))
  decreases e
{
  if e == 0 {
  } else if e == 1 {
    assert PathDelta(path, u, 1) ==
      (if path[0] == u then 1 else 0) - (if path[1] == u then 1 else 0);
  } else {
    DeltaForm(path, u, e - 1);
    PathDeltaStep(path, u, e - 1);
    var left := if u == path[0] then 1 else 0;
    var mid := if u == path[e - 1] then 1 else 0;
    var right := if u == path[e] then 1 else 0;
    assert PathDelta(path, u, e - 1) == left - mid;
    assert PathDelta(path, u, e) == left - mid + mid - right;
    assert PathDelta(path, u, e) == left - right;
  }
}

lemma DeltaFinal(path: seq<int>, s: int, t: int, u: int)
  requires |path| >= 2
  requires path[0] == s && path[|path| - 1] == t
  requires s != t
  ensures PathDelta(path, u, |path| - 1) == (if u == s then 1 else if u == t then -1 else 0)
{
  var e := |path| - 1;
  DeltaForm(path, u, e);
  if u == s {
    assert PathDelta(path, u, e) == 1;
  } else if u == t {
    assert PathDelta(path, u, e) == -1;
  } else {
    assert PathDelta(path, u, e) == 0;
  }
}

lemma ExcessToPush(g: seq<seq<(int, int)>>, prev: seq<seq<int>>, res: seq<seq<int>>, u: int, j: int, a: int, b: int, d: int)
  requires DimOK(g, prev) && DimOK(g, res)
  requires 0 <= u < |g| && 0 <= j <= |g|
  requires 0 <= a < |g| && 0 <= b < |g|
  requires forall v :: 0 <= v < |g| ==>
    res[u][v] == prev[u][v] + (if u == b && v == a then d else 0) - (if u == a && v == b then d else 0)
  ensures ExcessTo(g, res, u, j) == ExcessTo(g, prev, u, j)
      + (if u == a && b < j then d else 0)
      - (if u == b && a < j then d else 0)
  decreases j
{
  if j > 0 {
    ExcessToPush(g, prev, res, u, j - 1, a, b, d);
    ExcessToStep(g, res, u, j);
    ExcessToStep(g, prev, u, j);
    var v := j - 1;
    assert res[u][v] - prev[u][v] ==
      (if u == b && v == a then d else 0) - (if u == a && v == b then d else 0);
  }
}

lemma NoReverse(path: seq<int>, e: int, k: int)
  requires 0 <= e < k < |path| - 1
  requires forall p, q :: 0 <= p < q < |path| ==> path[p] != path[q]
  ensures path[k] != path[e] || path[k + 1] != path[e + 1]
  ensures !(path[k] == path[e + 1] && path[k + 1] == path[e])
{
  if path[k] == path[e] && path[k + 1] == path[e + 1] {
    assert false;
  }
  if path[k] == path[e + 1] && path[k + 1] == path[e] {
    if k == e + 1 {
      assert path[e + 2] == path[e];
      assert e + 2 != e;
      assert false;
    } else {
      assert false;
    }
  }
}

method {:vcs_split_on_every_assert} Augment(
    g: seq<seq<(int, int)>>,
    res: seq<seq<int>>,
    parent: seq<int>,
    depth: seq<int>,
    vis: seq<bool>,
    s: int, t: int, total: int
) returns (res2: seq<seq<int>>, d: int)
  requires capacities_bounded(g)
  requires ResOk(g, res, s, t, total)
  requires PathTree(res, parent, depth, vis, s, |g|)
  requires vis[t]
  ensures d >= 1
  ensures ResOk(g, res2, s, t, total + d)
{
  var n := |g|;
  var path := BuildPath(res, parent, depth, vis, s, t);
  d := MinRes(res, path);
  ghost var res0 := res;
  var cur := res;
  var e := 0;
  while e < |path| - 1
    invariant 0 <= e <= |path| - 1
    invariant DimOK(g, cur)
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==> cur[a][b] >= 0
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==>
      cur[a][b] + cur[b][a] == Cap(g, a, b) + Cap(g, b, a)
    invariant forall u :: 0 <= u < n ==>
      Excess(g, cur, u) == Excess(g, res0, u) + d * PathDelta(path, u, e)
    invariant forall k :: e <= k < |path| - 1 ==> cur[path[k]][path[k + 1]] >= d
    decreases |path| - 1 - e
  {
    var a := path[e];
    var b := path[e + 1];
    assert a != b;
    assert cur[a][b] >= d;
    ghost var prev := cur;
    var rowa := cur[a][b := cur[a][b] - d];
    cur := cur[a := rowa];
    var rowb := cur[b][a := cur[b][a] + d];
    cur := cur[b := rowb];
    forall u, v | 0 <= u < n && 0 <= v < n
      ensures cur[u][v] == prev[u][v] + (if u == b && v == a then d else 0) - (if u == a && v == b then d else 0)
    {
      if u == a {
        assert cur[a] == rowa;
        if v == b {
          assert rowa[v] == prev[a][b] - d;
        } else {
          assert rowa[v] == prev[a][v];
        }
      } else if u == b {
        assert cur[b] == rowb;
        assert prev[b] == rowb[a := rowb[a] - d] || true;
        if v == a {
          assert rowb[a] == prev[b][a] + d;
        } else {
          assert rowb[v] == prev[b][v];
        }
      } else {
        assert cur[u] == prev[u];
      }
    }
    forall u, v | 0 <= u < n && 0 <= v < n
      ensures cur[u][v] >= 0
    {
      if u == a && v == b {
        assert cur[u][v] == prev[u][v] - d;
        assert prev[u][v] >= d;
      } else if u == b && v == a {
        assert cur[u][v] == prev[u][v] + d;
      } else {
        assert cur[u][v] == prev[u][v];
      }
    }
    forall u, v | 0 <= u < n && 0 <= v < n
      ensures cur[u][v] + cur[v][u] == Cap(g, u, v) + Cap(g, v, u)
    {
      var duv := (if u == b && v == a then d else 0) - (if u == a && v == b then d else 0);
      var dvu := (if v == b && u == a then d else 0) - (if v == a && u == b then d else 0);
      assert dvu == -duv;
      assert cur[u][v] == prev[u][v] + duv;
      assert cur[v][u] == prev[v][u] + dvu;
      assert prev[u][v] + prev[v][u] == Cap(g, u, v) + Cap(g, v, u);
    }
    forall uu | 0 <= uu < n
      ensures Excess(g, cur, uu) == Excess(g, res0, uu) + d * PathDelta(path, uu, e + 1)
    {
      forall v | 0 <= v < n
        ensures cur[uu][v] == prev[uu][v] + (if uu == b && v == a then d else 0) - (if uu == a && v == b then d else 0)
      {
      }
      ExcessToPush(g, prev, cur, uu, n, a, b, d);
      assert Excess(g, cur, uu) == ExcessTo(g, cur, uu, n);
      assert Excess(g, prev, uu) == ExcessTo(g, prev, uu, n);
      var delta := (if uu == a then d else 0) - (if uu == b then d else 0);
      assert Excess(g, cur, uu) == Excess(g, prev, uu) + delta;
      PathDeltaStep(path, uu, e);
      assert PathDelta(path, uu, e + 1) ==
        PathDelta(path, uu, e) + (if uu == a then 1 else 0) - (if uu == b then 1 else 0);
      assert delta == d * ((if uu == a then 1 else 0) - (if uu == b then 1 else 0));
      assert Excess(g, prev, uu) == Excess(g, res0, uu) + d * PathDelta(path, uu, e);
    }
    forall k | e + 1 <= k < |path| - 1
      ensures cur[path[k]][path[k + 1]] >= d
    {
      NoReverse(path, e, k);
      var x := path[k];
      var y := path[k + 1];
      assert !(x == a && y == b);
      assert !(x == b && y == a);
      assert cur[x][y] == prev[x][y];
      assert prev[x][y] >= d;
    }
    e := e + 1;
  }
  res2 := cur;
  forall uu | 0 <= uu < n
    ensures Excess(g, res2, uu) == Excess(g, res0, uu) + d * (if uu == s then 1 else if uu == t then -1 else 0)
  {
    DeltaFinal(path, s, t, uu);
    assert PathDelta(path, uu, |path| - 1) == (if uu == s then 1 else if uu == t then -1 else 0);
  }
  assert Excess(g, res0, s) == total;
  assert Excess(g, res0, t) == -total;
  forall uu | 0 <= uu < n && uu != s && uu != t
    ensures Excess(g, res2, uu) == 0
  {
    assert Excess(g, res0, uu) == 0;
    assert Excess(g, res2, uu) == 0;
  }
  assert Excess(g, res2, s) == total + d;
  assert Excess(g, res2, t) == -total - d;
}

ghost predicate After(u0: int, i0: int, u: int, i: int) {
  u > u0 || (u == u0 && i >= i0)
}

ghost function ExpectedFlow(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u0: int, i0: int, x: int, y: int): int
{
  if !(0 <= x < |g| && 0 <= y < |g|) then 0
  else
    var idx := EdgeIndex(g, x, y);
    var fl := FlowOn(g, res, x, y);
    if idx >= 0 && After(u0, i0, x, idx) && fl > 0 then fl else 0
}

ghost function BuildFlow(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, i: int): FlowMap
  requires WFSeq(g)
  requires DimOK(g, res)
  requires 0 <= u <= |g|
  requires u < |g| ==> 0 <= i <= |g[u]|
  decreases |g| - u, if u < |g| then |g[u]| - i else 0
{
  if u == |g| then map[]
  else if i == |g[u]| then BuildFlow(g, res, u + 1, 0)
  else
    var v := g[u][i].0;
    var fl := FlowOn(g, res, u, v);
    var rest := BuildFlow(g, res, u, i + 1);
    if fl > 0 then rest[(u, v) := fl] else rest
}

lemma MapUpdateSame(m: FlowMap, x: int, y: int, fl: int)
  ensures get_flow(m[(x, y) := fl], x, y) == fl
{
}

lemma MapUpdateOther(m: FlowMap, x: int, y: int, fl: int, a: int, b: int)
  requires (a, b) != (x, y)
  ensures get_flow(m[(x, y) := fl], a, b) == get_flow(m, a, b)
{
}

lemma {:vcs_split_on_every_assert} BuildAgrees(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u0: int, i0: int, x: int, y: int)
  requires WFSeq(g) && DimOK(g, res)
  requires 0 <= u0 <= |g|
  requires u0 < |g| ==> 0 <= i0 <= |g[u0]|
  ensures get_flow(BuildFlow(g, res, u0, i0), x, y) == ExpectedFlow(g, res, u0, i0, x, y)
  decreases |g| - u0, if u0 < |g| then |g[u0]| - i0 else 0
{
  if u0 == |g| {
    if 0 <= x < |g| && 0 <= y < |g| {
      var idx := EdgeIndex(g, x, y);
      assert !After(u0, i0, x, idx);
    }
    assert BuildFlow(g, res, u0, i0) == map[];
    assert get_flow(map[], x, y) == 0;
  } else if i0 == |g[u0]| {
    BuildAgrees(g, res, u0 + 1, 0, x, y);
    if 0 <= x < |g| && 0 <= y < |g| {
      var idx := EdgeIndex(g, x, y);
      if idx >= 0 {
        assert After(u0, i0, x, idx) <==> After(u0 + 1, 0, x, idx);
      }
    }
  } else {
    var v := g[u0][i0].0;
    var fl := FlowOn(g, res, u0, v);
    BuildAgrees(g, res, u0, i0 + 1, x, y);
    var rest := BuildFlow(g, res, u0, i0 + 1);
    if fl > 0 {
      assert BuildFlow(g, res, u0, i0) == rest[(u0, v) := fl];
    } else {
      assert BuildFlow(g, res, u0, i0) == rest;
    }
    if x == u0 && y == v {
      EdgeIndexAt(g, u0, i0);
      assert EdgeIndex(g, u0, v) == i0;
      assert !After(u0, i0 + 1, u0, i0);
      assert ExpectedFlow(g, res, u0, i0 + 1, x, y) == 0;
      assert get_flow(rest, x, y) == 0;
      assert After(u0, i0, u0, i0);
      if fl > 0 {
        MapUpdateSame(rest, u0, v, fl);
        assert get_flow(rest[(u0, v) := fl], x, y) == fl;
        assert ExpectedFlow(g, res, u0, i0, x, y) == fl;
      } else {
        assert ExpectedFlow(g, res, u0, i0, x, y) == 0;
      }
    } else {
      if fl > 0 {
        assert (x, y) != (u0, v);
        MapUpdateOther(rest, u0, v, fl, x, y);
      }
      assert get_flow(BuildFlow(g, res, u0, i0), x, y) == get_flow(rest, x, y);
      if 0 <= x < |g| && 0 <= y < |g| {
        var idx := EdgeIndex(g, x, y);
        if idx == i0 && x == u0 {
          IdxIsTarget(g, u0, i0, y);
          assert y == v;
          assert false;
        }
        if idx >= 0 {
          assert After(u0, i0, x, idx) <==> After(u0, i0 + 1, x, idx);
        }
      }
    }
  }
}

lemma KeyPos(g: seq<seq<(int, int)>>, res: seq<seq<int>>, u: int, i: int, x: int, y: int)
  requires WFSeq(g) && DimOK(g, res)
  requires 0 <= u <= |g|
  requires u < |g| ==> 0 <= i <= |g[u]|
  ensures (x, y) in BuildFlow(g, res, u, i) ==> get_flow(BuildFlow(g, res, u, i), x, y) > 0
  decreases |g| - u, if u < |g| then |g[u]| - i else 0
{
  if u == |g| {
    assert (x, y) !in map[];
  } else if i == |g[u]| {
    KeyPos(g, res, u + 1, 0, x, y);
  } else {
    var v := g[u][i].0;
    var fl := FlowOn(g, res, u, v);
    KeyPos(g, res, u, i + 1, x, y);
    var rest := BuildFlow(g, res, u, i + 1);
    if fl > 0 {
      assert BuildFlow(g, res, u, i) == rest[(u, v) := fl];
      if (x, y) == (u, v) {
        MapUpdateSame(rest, u, v, fl);
        assert get_flow(rest[(u, v) := fl], x, y) == fl;
        assert fl > 0;
      } else if (x, y) in rest[(u, v) := fl] {
        assert (x, y) in rest;
        MapUpdateOther(rest, u, v, fl, x, y);
      }
    } else {
      assert BuildFlow(g, res, u, i) == rest;
    }
  }
}

lemma FinalFlow(g: seq<seq<(int, int)>>, res: seq<seq<int>>, x: int, y: int)
  requires WFSeq(g) && DimOK(g, res)
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==> res[a][b] >= 0
  ensures get_flow(BuildFlow(g, res, 0, 0), x, y) ==
    (if 0 <= x < |g| && 0 <= y < |g| then FlowOn(g, res, x, y) else 0)
{
  BuildAgrees(g, res, 0, 0, x, y);
  if 0 <= x < |g| && 0 <= y < |g| {
    var fl := FlowOn(g, res, x, y);
    if fl > 0 {
      assert Cap(g, x, y) > res[x][y];
      assert Cap(g, x, y) > 0;
      PositiveCapHasEdge(g, x, y);
      var idx := EdgeIndex(g, x, y);
      assert idx >= 0;
      assert After(0, 0, x, idx);
      assert ExpectedFlow(g, res, 0, 0, x, y) == fl;
    } else {
      assert ExpectedFlow(g, res, 0, 0, x, y) == 0;
    }
  }
}

ghost function RowSum(f: FlowMap, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0 else RowSum(f, u, j - 1) + get_flow(f, u, j - 1)
}

ghost function ColSum(f: FlowMap, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0 else ColSum(f, u, j - 1) + get_flow(f, j - 1, u)
}

lemma RowStep(f: FlowMap, u: int, j: int)
  requires j > 0
  ensures RowSum(f, u, j) == RowSum(f, u, j - 1) + get_flow(f, u, j - 1)
{
}

lemma ColStep(f: FlowMap, u: int, j: int)
  requires j > 0
  ensures ColSum(f, u, j) == ColSum(f, u, j - 1) + get_flow(f, j - 1, u)
{
}

lemma SumFRow(g: seq<seq<(int, int)>>, res: seq<seq<int>>, f: FlowMap, u: int, j: int)
  requires forall v :: 0 <= v < j ==> get_flow(f, u, v) == FlowOn(g, res, u, v)
  ensures SumFOut(g, res, u, j) == RowSum(f, u, j)
  decreases j
{
  if j > 0 {
    SumFRow(g, res, f, u, j - 1);
    RowStep(f, u, j);
  }
}

lemma SumFCol(g: seq<seq<(int, int)>>, res: seq<seq<int>>, f: FlowMap, u: int, j: int)
  requires forall v :: 0 <= v < j ==> get_flow(f, v, u) == FlowOn(g, res, v, u)
  ensures SumFIn(g, res, u, j) == ColSum(f, u, j)
  decreases j
{
  if j > 0 {
    SumFCol(g, res, f, u, j - 1);
    ColStep(f, u, j);
  }
}

ghost function EdgeSum(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int): int
  decreases if i > 0 then i else 0
{
  if i <= 0 then 0
  else if 0 <= u < |g| && i - 1 < |g[u]| then
    EdgeSum(g, f, u, i - 1) + get_flow(f, u, g[u][i - 1].0)
  else
    EdgeSum(g, f, u, i - 1)
}

lemma EdgeSumOut(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int)
  requires 0 <= u < |g| && 0 <= i <= |g[u]|
  ensures EdgeSum(g, f, u, i) == sum_flow_out_recursive(g, f, u, i)
  decreases i
{
  if i > 0 {
    EdgeSumOut(g, f, u, i - 1);
    assert i - 1 < |g[u]|;
    assert sum_flow_out_recursive(g, f, u, i) ==
      sum_flow_out_recursive(g, f, u, i - 1) + get_flow(f, u, g[u][i - 1].0);
  }
}

ghost function Covered(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0
  else
    var idx := if 0 <= u < |g| && 0 <= j - 1 then EdgeIndex(g, u, j - 1) else -1;
    var add := if 0 <= idx < i then get_flow(f, u, j - 1) else 0;
    Covered(g, f, u, i, j - 1) + add
}

lemma CoveredDiff(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int, j: int)
  requires WFSeq(g)
  requires 0 <= u < |g| && 0 <= i < |g[u]| && 0 <= j <= |g|
  ensures Covered(g, f, u, i + 1, j) ==
    Covered(g, f, u, i, j) + (if g[u][i].0 < j then get_flow(f, u, g[u][i].0) else 0)
  decreases j
{
  if j > 0 {
    CoveredDiff(g, f, u, i, j - 1);
    var target := g[u][i].0;
    EdgeIndexAt(g, u, i);
    var v := j - 1;
    if v == target {
      assert EdgeIndex(g, u, v) == i;
    } else if 0 <= v < |g| && EdgeIndex(g, u, v) == i {
      IndexTarget(g, u, v);
      assert g[u][i].0 == v;
      assert false;
    }
  }
}

lemma EdgeSumCovered(g: seq<seq<(int, int)>>, f: FlowMap, u: int, i: int)
  requires WFSeq(g)
  requires 0 <= u < |g| && 0 <= i <= |g[u]|
  ensures EdgeSum(g, f, u, i) == Covered(g, f, u, i, |g|)
  decreases i
{
  if i > 0 {
    EdgeSumCovered(g, f, u, i - 1);
    var target := g[u][i - 1].0;
    assert 0 <= target < |g|;
    CoveredDiff(g, f, u, i - 1, |g|);
    assert target < |g|;
    assert Covered(g, f, u, i, |g|) == Covered(g, f, u, i - 1, |g|) + get_flow(f, u, target);
  } else {
    assert EdgeSum(g, f, u, 0) == 0;
  }
}

lemma RowVsCovered(g: seq<seq<(int, int)>>, f: FlowMap, u: int, j: int)
  requires WFSeq(g)
  requires 0 <= u < |g| && 0 <= j <= |g|
  requires forall v :: 0 <= v < j && EdgeIndex(g, u, v) < 0 ==> get_flow(f, u, v) == 0
  ensures RowSum(f, u, j) == Covered(g, f, u, |g[u]|, j)
  decreases j
{
  if j > 0 {
    assert forall v :: 0 <= v < j - 1 && EdgeIndex(g, u, v) < 0 ==> get_flow(f, u, v) == 0;
    RowVsCovered(g, f, u, j - 1);
    var v := j - 1;
    var idx := EdgeIndex(g, u, v);
    RowStep(f, u, j);
    if idx >= 0 {
      IndexTarget(g, u, v);
      assert 0 <= idx < |g[u]|;
    } else {
      assert get_flow(f, u, v) == 0;
    }
  }
}

lemma OutEqRow(g: seq<seq<(int, int)>>, f: FlowMap, u: int)
  requires WFSeq(g)
  requires 0 <= u < |g|
  requires forall v :: 0 <= v < |g| && EdgeIndex(g, u, v) < 0 ==> get_flow(f, u, v) == 0
  ensures total_flow_out(g, f, u) == RowSum(f, u, |g|)
{
  EdgeSumOut(g, f, u, |g[u]|);
  EdgeSumCovered(g, f, u, |g[u]|);
  RowVsCovered(g, f, u, |g|);
  assert total_flow_out(g, f, u) == sum_flow_out_recursive(g, f, u, |g[u]|);
}

lemma InEqCol(g: seq<seq<(int, int)>>, f: FlowMap, u: int, j: int)
  ensures sum_flow_in_recursive(g, f, u, j) == ColSum(f, u, j)
  decreases if j > 0 then j else 0
{
  if j > 0 {
    InEqCol(g, f, u, j - 1);
    ColStep(f, u, j);
    assert sum_flow_in_recursive(g, f, u, j) ==
      sum_flow_in_recursive(g, f, u, j - 1) + get_flow(f, j - 1, u);
  }
}

lemma TotalIn(g: seq<seq<(int, int)>>, f: FlowMap, u: int)
  ensures total_flow_in(g, f, u) == ColSum(f, u, |g|)
{
  InEqCol(g, f, u, |g|);
}

lemma GetNonneg(f: FlowMap, u: int, v: int)
  requires forall a, b :: (a, b) in f ==> f[(a, b)] >= 0
  ensures get_flow(f, u, v) >= 0
{
}

lemma OffEdgeZero(g: seq<seq<(int, int)>>, f: FlowMap, u: int, v: int)
  requires WFSeq(g)
  requires respects_capacity(g, f)
  requires forall a, b :: (a, b) in f ==> f[(a, b)] >= 0
  requires 0 <= u < |g| && 0 <= v < |g|
  requires EdgeIndex(g, u, v) < 0
  ensures get_flow(f, u, v) == 0
{
  GetNonneg(f, u, v);
  if get_flow(f, u, v) > 0 {
    assert (u, v) in f;
    assert f[(u, v)] > 0;
    assert exists c :: has_capacity(g, u, v, c) && f[(u, v)] <= c;
    var c :| has_capacity(g, u, v, c) && f[(u, v)] <= c;
    HasCapIsCap(g, u, v, c);
    assert false;
  }
}

lemma GetFlowBounded(g: seq<seq<(int, int)>>, f: FlowMap, u: int, v: int)
  requires WFSeq(g)
  requires capacities_bounded(g)
  requires respects_capacity(g, f)
  requires forall a, b :: (a, b) in f ==> f[(a, b)] >= 0
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures 0 <= get_flow(f, u, v) <= Cap(g, u, v)
{
  CapBounded(g, u, v);
  GetNonneg(f, u, v);
  if (u, v) in f && f[(u, v)] > 0 {
    assert exists c :: has_capacity(g, u, v, c) && f[(u, v)] <= c;
    var c :| has_capacity(g, u, v, c) && f[(u, v)] <= c;
    HasCapIsCap(g, u, v, c);
    assert get_flow(f, u, v) == f[(u, v)];
    assert get_flow(f, u, v) <= Cap(g, u, v);
  } else {
    assert get_flow(f, u, v) == 0 || (u, v) !in f || f[(u, v)] == 0;
    if (u, v) !in f {
      assert get_flow(f, u, v) == 0;
    } else if f[(u, v)] == 0 {
      assert get_flow(f, u, v) == 0;
    }
  }
}

