lemma SplitRow(f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires 0 <= j <= |cut|
  ensures RowSum(f, u, j) == RowSel(f, cut, u, j, true) + RowSel(f, cut, u, j, false)
  decreases j
{
  if j > 0 {
    SplitRow(f, cut, u, j - 1);
    var v := j - 1;
    RowStep(f, u, j);
    RowSelStep(f, cut, u, j, true);
    RowSelStep(f, cut, u, j, false);
    if cut[v] {
      assert RowSel(f, cut, u, j, true) == RowSel(f, cut, u, j - 1, true) + get_flow(f, u, v);
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false);
    } else {
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false) + get_flow(f, u, v);
      assert RowSel(f, cut, u, j, true) == RowSel(f, cut, u, j - 1, true);
    }
  }
}

