    if cut[v] {
      assert ColSel(f, cut, u, j, true) == ColSel(f, cut, u, j - 1, true) + get_flow(f, v, u);
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false);
    } else {
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false) + get_flow(f, v, u);
      assert ColSel(f, cut, u, j, true) == ColSel(f, cut, u, j - 1, true);
