  }
}

ghost function SumSel(f: FlowMap, cut: seq<bool>, i: int, j: int, want: bool, swapped: bool): int
  decreases if i > 0 then i else 0
{
  if i <= 0 then 0
  else
    var prev := SumSel(f, cut, i - 1, j, want, swapped);
    if 0 <= i - 1 < |cut| && cut[i - 1] then
      prev + (if swapped then ColSel(f, cut, i - 1, j, want) else RowSel(f, cut, i - 1, j, want))
    else prev
}

