lemma SumSelZeroJ(f: FlowMap, cut: seq<bool>, i: int, want: bool, swapped: bool)
  ensures SumSel(f, cut, i, 0, want, swapped) == 0
  decreases if i > 0 then i else 0
{
  if i > 0 {
    SumSelZeroJ(f, cut, i - 1, want, swapped);
    SumSelStep(f, cut, i, 0, want, swapped);
    if swapped {
      assert ColSel(f, cut, i - 1, 0, want) == 0;
    } else {
      assert RowSel(f, cut, i - 1, 0, want) == 0;
    }
  }
