lemma CrossSplit(f: FlowMap, cut: seq<bool>, i: int)
  requires 0 <= i <= |cut|
  ensures CrossClean(f, cut, i) ==
    SumSel(f, cut, i, |cut|, false, false) - SumSel(f, cut, i, |cut|, false, true)
  decreases i
{
  if i > 0 {
    CrossSplit(f, cut, i - 1);
    CrossStep(f, cut, i);
    SumSelStep(f, cut, i, |cut|, false, false);
    SumSelStep(f, cut, i, |cut|, false, true);
    if 0 <= i - 1 < |cut| && cut[i - 1] {
      EdgeIsDiff(f, cut, i - 1, |cut|);
    }
  }
}

