lemma NetSplit(f: FlowMap, cut: seq<bool>, n: int, i: int)
  requires |cut| == n && 0 <= i <= n
  ensures NetClean(f, cut, n, i) ==
    SumSel(f, cut, i, n, true, false) - SumSel(f, cut, i, n, true, true) +
    SumSel(f, cut, i, n, false, false) - SumSel(f, cut, i, n, false, true)
  decreases i
{
  if i > 0 {
    NetSplit(f, cut, n, i - 1);
    NetStep(f, cut, n, i);
    SumSelStep(f, cut, i, n, true, false);
    SumSelStep(f, cut, i, n, true, true);
    SumSelStep(f, cut, i, n, false, false);
    SumSelStep(f, cut, i, n, false, true);
    if 0 <= i - 1 < n && cut[i - 1] {
      SplitRow(f, cut, i - 1, n);
      SplitCol(f, cut, i - 1, n);
    }
  }
}

lemma NetEqCross(f: FlowMap, cut: seq<bool>)
  requires |cut| >= 0
  ensures NetClean(f, cut, |cut|, |cut|) == CrossClean(f, cut, |cut|)
