  var n := |cut|;
  NetSplit(f, cut, n, n);
  CrossSplit(f, cut, n);
  Transpose(f, cut, n, n);
  assert SumSel(f, cut, n, n, true, true) == SumSel(f, cut, n, n, true, false);
}

