  requires 0 <= lo < hi <= |p|
  ensures path_valid(g, p[lo..hi])
  ensures |p[lo..hi]| == hi - lo
  ensures (p[lo..hi])[0] == p[lo]
  ensures (p[lo..hi])[hi - lo - 1] == p[hi - 1]
{
  var q := p[lo..hi];
  assert |q| == hi - lo;
  assert q[0] == p[lo];
  assert q[|q| - 1] == p[hi - 1];
  forall kk | 0 <= kk < |q| - 1
    ensures has_edge(g, q[kk], q[kk + 1])
  {
    assert q[kk] == p[lo + kk];
    assert q[kk + 1] == p[lo + kk + 1];
    assert 0 <= lo + kk < |p| - 1;
    assert has_edge(g, p[lo + kk], p[lo + kk + 1]);
  }
  assert path_valid(g, q);
}

lemma {:vcs_split_on_every_assert} ConcatPathValid(g: seq<seq<int>>, p1: seq<int>, p2: seq<int>)
  requires |p1| > 0 && |p2| > 0
  requires path_valid(g, p1)
  requires path_valid(g, p2)
  requires p1[|p1| - 1] == p2[0]
  ensures path_valid(g, joined(p1, p2))
  ensures |joined(p1, p2)| == |p1| + |p2| - 1
  ensures joined(p1, p2)[0] == p1[0]
  ensures joined(p1, p2)[|joined(p1, p2)| - 1] == p2[|p2| - 1]
{
  var p := joined(p1, p2);
  var L := |p1| - 1;
  var pref := p1[..L];
  assert p == pref + p2;
  assert |pref| == L;
  assert |p| == |p1| + |p2| - 1;

  if L == 0 {
    assert |p1| == 1;
    assert pref == [];
    assert p == p2;
    assert p1[0] == p2[0];
    assert p[0] == p1[0];
    assert p[|p| - 1] == p2[|p2| - 1];
    assert path_valid(g, p);
  } else {
    assert |pref| > 0;
    assert p[0] == pref[0] == p1[0];
    assert p[|p| - 1] == p2[|p2| - 1];
    forall kk | 0 <= kk < |p| - 1
      ensures has_edge(g, p[kk], p[kk + 1])
    {
      if kk < L {
        assert p[kk] == pref[kk] == p1[kk];
        assert 0 <= kk < |p1| - 1;
        if kk + 1 < L {
          assert p[kk + 1] == pref[kk + 1] == p1[kk + 1];
        } else {
          assert kk + 1 == L;
          assert p[L] == p2[0];
          assert p2[0] == p1[|p1| - 1] == p1[L];
          assert p[kk + 1] == p1[kk + 1];
        }
        assert has_edge(g, p1[kk], p1[kk + 1]);
        assert has_edge(g, p[kk], p[kk + 1]);
      } else {
        assert kk >= L;
        assert kk <= |p| - 2;
        assert |p| - 2 == L + |p2| - 2;
        assert |p2| >= 2;
        var j := kk - L;
        assert 0 <= j <= |p2| - 2;
        assert j < |p2| - 1;
        assert p[L + j] == p2[j];
        assert kk == L + j;
        assert p[kk] == p2[j];
        assert p[kk + 1] == p2[j + 1];
        assert has_edge(g, p2[j], p2[j + 1]);
      }
    }
    assert path_valid(g, p);
  }
}

lemma ConcatVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, k, k)
  requires has_path_via(g, k, v, k)
  ensures has_path_via(g, u, v, k + 1)
{
  var p1 :| path_ok(g, p1, u, k) && intermediates_below(p1, k);
  var p2 :| path_ok(g, p2, k, v) && intermediates_below(p2, k);
  ConcatPathValid(g, p1, p2);
  var p := joined(p1, p2);
  var L := |p1| - 1;
  assert path_valid(g, p);
  assert |p| == |p1| + |p2| - 1;
  assert p[0] == u;
  assert p[|p| - 1] == v;
  var pref := p1[..L];
  assert p == pref + p2;
  assert |pref| == L;

  forall t | 1 <= t <= |p| - 2
    ensures p[t] < k + 1
  {
    if t < L {
      assert |p1| >= 3;
      assert 1 <= t <= |p1| - 2;
      assert p[t] == pref[t] == p1[t];
      assert p1[t] < k;
      assert p[t] < k + 1;
    } else if t == L {
      assert p[L] == p2[0];
      assert p2[0] == k;
      assert p[t] == k;
      assert k < k + 1;
    } else {
      var j := t - L;
      assert t >= L + 1;
      assert j >= 1;
      assert t <= |p| - 2;
      assert |p| - 2 - L == |p2| - 2;
      assert j <= |p2| - 2;
      assert 1 <= j <= |p2| - 2;
      assert p[L + j] == p2[j];
      assert t == L + j;
      assert p[t] == p2[j];
      assert p2[j] < k;
      assert p[t] < k + 1;
    }
  }
  assert intermediates_below(p, k + 1);
  assert path_ok(g, p, u, v);
  assert has_path_via(g, u, v, k + 1) by {
    assert path_ok(g, p, u, v);
    assert intermediates_below(p, k + 1);
  }
}

lemma {:vcs_split_on_every_assert} SplitVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, v, k + 1)
  ensures has_path_via(g, u, v, k) ||
          (has_path_via(g, u, k, k) && has_path_via(g, k, v, k))
{
  var p :| path_ok(g, p, u, v) && intermediates_below(p, k + 1);
  if exists t :: 0 <= t < |p| && p[t] == k {
    var hit :| 0 <= hit < |p| && p[hit] == k;
    var i := 0;
    while p[i] != k
      invariant 0 <= i <= hit < |p|
      invariant p[hit] == k
      invariant forall t :: 0 <= t < i ==> p[t] != k
      decreases hit - i
    {
      assert p[i] != k;
      if i == hit {
        assert p[hit] == k;
        assert false;
      }
      assert i < hit;
      i := i + 1;
    }
    assert i < |p|;
    assert p[i] == k;
    assert forall t :: 0 <= t < i ==> p[t] != k;

    assert hit <= |p| - 1;
    var j := |p| - 1;
    while p[j] != k
      invariant hit <= j < |p|
      invariant p[hit] == k
      invariant forall t :: j < t < |p| ==> p[t] != k
      decreases j - hit
    {
      assert p[j] != k;
      if j == hit {
        assert p[hit] == k;
        assert false;
      }
      assert j > hit;
      forall t | j - 1 < t < |p|
        ensures p[t] != k
      {
        if t == j {
          assert p[j] != k;
        } else {
          assert j < t < |p|;
          assert p[t] != k;
        }
      }
      j := j - 1;
    }
    assert hit <= j < |p|;
    assert p[j] == k;
    assert forall t :: j < t < |p| ==> p[t] != k;

    SubpathValid(g, p, 0, i + 1);
    var left := p[0 .. i + 1];
    assert left == p[0 .. i + 1];
    assert path_valid(g, left);
    assert |left| == i + 1;
    assert left[0] == p[0] == u;
    assert left[|left| - 1] == p[i] == k;
    forall t | 1 <= t <= |left| - 2
      ensures left[t] < k
    {
      assert left[t] == p[t];
      assert 1 <= t <= i - 1;
      assert t < i;
      assert p[t] != k;
      assert 1 <= t <= |p| - 2;
      assert p[t] < k + 1;
      assert p[t] <= k;
      assert p[t] < k;
    }
    assert intermediates_below(left, k);
    assert path_ok(g, left, u, k);
    assert has_path_via(g, u, k, k) by {
      assert path_ok(g, left, u, k);
      assert intermediates_below(left, k);
    }

    SubpathValid(g, p, j, |p|);
    var right := p[j .. |p|];
    assert right == p[j .. |p|];
    assert path_valid(g, right);
    assert |right| == |p| - j;
    assert right[0] == p[j] == k;
    assert right[|right| - 1] == p[|p| - 1] == v;
    forall t | 1 <= t <= |right| - 2
      ensures right[t] < k
    {
      var s := j + t;
      assert right[t] == p[s];
      assert |right| == |p| - j;
      assert 1 <= t <= |p| - j - 2;
      assert s == j + t;
      assert j >= 0;
      assert s >= j + 1;
      assert s <= |p| - 2;
      assert 1 <= s <= |p| - 2;
      assert j < s < |p|;
      assert p[s] != k;
      assert p[s] < k + 1;
      assert p[s] <= k;
      assert p[s] < k;
    }
    assert intermediates_below(right, k);
    assert path_ok(g, right, k, v);
    assert has_path_via(g, k, v, k) by {
      assert path_ok(g, right, k, v);
      assert intermediates_below(right, k);
    }
  } else {
    forall t | 1 <= t <= |p| - 2
      ensures p[t] < k
    {
      assert 0 <= t < |p|;
      assert p[t] != k;
      assert p[t] < k + 1;
      assert p[t] <= k;
      assert p[t] < k;
    }
    assert intermediates_below(p, k);
    assert has_path_via(g, u, v, k) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, k);
    }
  }
}

lemma FWStep(g: seq<seq<int>>, u: int, v: int, k: int)
  ensures has_path_via(g, u, v, k + 1) <==>
          (has_path_via(g, u, v, k) ||
            (has_path_via(g, u, k, k) && has_path_via(g, k, v, k)))
{
  if has_path_via(g, u, v, k) || (has_path_via(g, u, k, k) && has_path_via(g, k, v, k)) {
    if has_path_via(g, u, v, k) {
      ViaMonotone(g, u, v, k, k + 1);
    } else {
      assert has_path_via(g, u, k, k) && has_path_via(g, k, v, k);
      ConcatVia(g, u, v, k);
    }
    assert has_path_via(g, u, v, k + 1);
  }
  if has_path_via(g, u, v, k + 1) {
    SplitVia(g, u, v, k);
    assert has_path_via(g, u, v, k) ||
      (has_path_via(g, u, k, k) && has_path_via(g, k, v, k));
  }
}

lemma ViaIffPath(g: seq<seq<int>>, u: int, v: int)
  requires WellFormedSeq(g)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures has_path_via(g, u, v, |g|) <==> has_path(g, u, v)
{
  if has_path_via(g, u, v, |g|) {
    var p :| path_ok(g, p, u, v) && intermediates_below(p, |g|);
    assert has_path(g, u, v) by {
      assert |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p);
    }
  }
  if has_path(g, u, v) {
    var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p);
    forall t | 1 <= t <= |p| - 2
      ensures p[t] < |g|
    {
      assert |p| >= 3;
      PathNodeInRange(g, p, t);
      assert p[t] < |g|;
    }
    assert intermediates_below(p, |g|);
    assert path_ok(g, p, u, v);
    assert has_path_via(g, u, v, |g|) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, |g|);
    }
  }
}

lemma Reflexive(g: seq<seq<int>>, u: int)
  requires 0 <= u < |g|
  ensures has_path(g, u, u)
{
  var p := [u];
  assert path_valid(g, p);
  assert has_path(g, u, u) by {
    assert |p| > 0 && p[0] == u && p[|p| - 1] == u && path_valid(g, p);
  }
}

lemma PathConcat(g: seq<seq<int>>, u: int, v: int, w: int)
  requires has_path(g, u, v)
  requires has_path(g, v, w)
  ensures has_path(g, u, w)
{
  var p1 :| |p1| > 0 && p1[0] == u && p1[|p1| - 1] == v && path_valid(g, p1);
  var p2 :| |p2| > 0 && p2[0] == v && p2[|p2| - 1] == w && path_valid(g, p2);
  ConcatPathValid(g, p1, p2);
  var p := joined(p1, p2);
  assert path_valid(g, p);
  assert |p| == |p1| + |p2| - 1;
  assert |p| > 0;
  assert p[0] == p1[0] == u;
  assert p[|p| - 1] == p2[|p2| - 1] == w;
  assert has_path(g, u, w) by {
    assert |p| > 0 && p[0] == u && p[|p| - 1] == w && path_valid(g, p);
  }
}

lemma PathConcat3(g: seq<seq<int>>, a: int, b: int, c: int, d: int)
  requires has_path(g, a, b)
  requires has_path(g, b, c)
  requires has_path(g, c, d)
  ensures has_path(g, a, d)
{
  PathConcat(g, a, b, c);
  PathConcat(g, a, c, d);
}

method InitReach(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path_via(g, a, b, 0)
{
  var n := |g|;
  reach := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |reach| == i
    invariant forall a :: 0 <= a < i ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, 0)
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==> row[b] == has_path_via(g, i, b, 0)
      decreases n - j
    {
      var e := EdgeExists(g, i, j);
      ViaZeroCorrect(g, i, j);
      var bit := (i == j) || e;
      assert e == has_edge(g, i, j);
      assert bit == (i == j || has_edge(g, i, j));
      assert has_path_via(g, i, j, 0) == (i == j || has_edge(g, i, j));
      assert bit == has_path_via(g, i, j, 0);
      row := row + [bit];
      j := j + 1;
    }
    reach := reach + [row];
    i := i + 1;
  }
}

method SquareStep(reach: seq<seq<bool>>, k: int) returns (next: seq<seq<bool>>)
  requires 0 <= k < |reach|
  requires forall a :: 0 <= a < |reach| ==> |reach[a]| == |reach|
  ensures |next| == |reach|
  ensures forall a :: 0 <= a < |next| ==> |next[a]| == |reach|
  ensures forall a, b :: 0 <= a < |reach| && 0 <= b < |reach| ==>
      next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
{
  var n := |reach|;
  next := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |next| == i
    invariant forall a :: 0 <= a < i ==> |next[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==>
          row[b] == (reach[i][b] || (reach[i][k] && reach[k][b]))
      decreases n - j
    {
      var bit := reach[i][j] || (reach[i][k] && reach[k][j]);
      row := row + [bit];
      j := j + 1;
    }
    next := next + [row];
    i := i + 1;
  }
}

method {:vcs_split_on_every_assert} FloydWarshall(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path(g, a, b)
{
  var n := |g|;
  reach := InitReach(g);
  var k := 0;
  while k < n
    invariant 0 <= k <= n
    invariant |reach| == n
    invariant forall a :: 0 <= a < n ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, k)
    decreases n - k
  {
    var prevReach := reach;
    var next := SquareStep(prevReach, k);
    forall a, b | 0 <= a < n && 0 <= b < n
      ensures next[a][b] == has_path_via(g, a, b, k + 1)
    {
      assert prevReach[a][b] == has_path_via(g, a, b, k);
      assert prevReach[a][k] == has_path_via(g, a, k, k);
      assert prevReach[k][b] == has_path_via(g, k, b, k);
      assert next[a][b] == (prevReach[a][b] || (prevReach[a][k] && prevReach[k][b]));
      FWStep(g, a, b, k);
      assert next[a][b] == has_path_via(g, a, b, k + 1);
    }
    reach := next;
    k := k + 1;
  }
  forall a, b | 0 <= a < n && 0 <= b < n
    ensures reach[a][b] == has_path(g, a, b)
  {
    assert reach[a][b] == has_path_via(g, a, b, n);
    ViaIffPath(g, a, b);
  }
}

lemma IdempotentOne(g: seq<seq<int>>, rep: seq<int>, u: int)
  requires |rep| == |g|
  requires 0 <= u < |g|
  requires forall a :: 0 <= a < |g| ==>
      0 <= rep[a] <= a && has_path(g, a, rep[a]) && has_path(g, rep[a], a)
  requires forall a: int, t: int ::
      0 <= a < |g| && 0 <= t < rep[a] ==>
        !(has_path(g, a, t) && has_path(g, t, a))
  ensures rep[rep[u]] == rep[u]
{
  var r := rep[u];
  assert 0 <= r <= u;
  assert 0 <= r < |g|;
  var rr := rep[r];
  assert 0 <= rr <= r;
  assert has_path(g, u, r) && has_path(g, r, u);
  assert has_path(g, r, rr) && has_path(g, rr, r);
  PathConcat(g, rr, r, u);
  PathConcat(g, u, r, rr);
  assert has_path(g, rr, u) && has_path(g, u, rr);
  if rr < r {
    assert 0 <= rr < rep[u];
    assert !(has_path(g, u, rr) && has_path(g, rr, u));
    assert false;
  }
  assert rr == r;
}

lemma RepMutual(g: seq<seq<int>>, rep: seq<int>, u: int, v: int)
  requires RepCorrect(g, rep)
  requires 0 <= u < |rep| && 0 <= v < |rep|
  ensures (rep[u] == rep[v]) <==> (has_path(g, u, v) && has_path(g, v, u))
{
  if rep[u] == rep[v] {
    var r := rep[u];
    assert has_path(g, u, r) && has_path(g, r, u);
    assert has_path(g, v, r) && has_path(g, r, v);
    PathConcat(g, u, r, v);
    PathConcat(g, v, r, u);
    assert has_path(g, u, v) && has_path(g, v, u);
  }
  if has_path(g, u, v) && has_path(g, v, u) {
    var ru := rep[u];
    var rv := rep[v];
    assert has_path(g, ru, u) && has_path(g, u, ru);
    assert has_path(g, rv, v) && has_path(g, v, rv);
    PathConcat(g, ru, u, v);
    PathConcat(g, v, u, ru);
    PathConcat(g, rv, v, u);
    PathConcat(g, u, v, rv);
    assert has_path(g, ru, v) && has_path(g, v, ru);
    assert has_path(g, rv, u) && has_path(g, u, rv);
    if ru < rv {
      assert 0 <= ru < rep[v];
      assert has_path(g, v, ru) && has_path(g, ru, v);
      assert !(has_path(g, v, ru) && has_path(g, ru, v));
      assert false;
    }
    if rv < ru {
      assert 0 <= rv < rep[u];
      assert has_path(g, u, rv) && has_path(g, rv, u);
      assert !(has_path(g, u, rv) && has_path(g, rv, u));
      assert false;
    }
    assert ru == rv;
  }
}

method {:vcs_split_on_every_assert} PickMin(reach: seq<seq<bool>>, u: int) returns (r: int)
  requires 0 <= u < |reach|
  requires forall a :: 0 <= a < |reach| ==> |reach[a]| == |reach|
  requires reach[u][u]
  ensures 0 <= r <= u
  ensures reach[u][r] && reach[r][u]
  ensures forall t :: 0 <= t < r ==> !(reach[u][t] && reach[t][u])
{
  r := u;
  var v := 0;
  while v < u
    invariant 0 <= v <= u
    invariant 0 <= r <= u
    invariant reach[u][r] && reach[r][u]
    invariant r == u || r < v
    invariant forall t :: 0 <= t < v && reach[u][t] && reach[t][u] ==> r <= t
    decreases u - v
  {
    if reach[u][v] && reach[v][u] && v < r {
      var bound := v;
      forall t | 0 <= t < bound
        ensures !(reach[u][t] && reach[t][u])
      {
        if reach[u][t] && reach[t][u] {
          assert r <= t;
          assert t < bound;
          assert bound < r;
          assert false;
        }
      }
      assert forall tt :: 0 <= tt < bound ==> !(reach[u][tt] && reach[tt][u]);
      r := bound;
      v := bound + 1;
      assert 0 <= r < u;
      assert r <= u;
      assert reach[u][r] && reach[r][u];
      assert r < v;
      assert v <= u;
      forall t | 0 <= t < v && reach[u][t] && reach[t][u]
        ensures r <= t
      {
        if t < bound {
          assert !(reach[u][t] && reach[t][u]);
          assert false;
        } else {
          assert t == bound;
          assert t == r;
        }
      }
    } else {
      var bound := v;
      if reach[u][bound] && reach[bound][u] {
        assert !(bound < r);
        assert r <= bound;
      }
      assert (reach[u][bound] && reach[bound][u]) ==> r <= bound;
