        0 <= a < |g| && 0 <= t < rep[a] ==>
          !(has_path(g, a, t) && has_path(g, t, a)))
}

ghost predicate ClassComp(rep: seq<int>, root: int, comp: seq<int>) {
  && 0 <= root < |rep|
  && rep[root] == root
  && |comp| > 0
  && comp[0] == root
  && (forall t :: 0 <= t < |comp| ==>
        0 <= comp[t] < |rep| && rep[comp[t]] == root)
  && (forall x :: 0 <= x < |rep| && rep[x] == root ==>
        seq_contains(comp, x))
  && (forall a, b :: 0 <= a < b < |comp| ==> comp[a] < comp[b])
}

ghost predicate SccsMatch(rep: seq<int>, sccs: seq<seq<int>>) {
  && (forall i :: 0 <= i < |sccs| ==>
        |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]))
  && (forall i, j ::
        0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
          |sccs[i]| > 0 && |sccs[j]| > 0 && sccs[i][0] != sccs[j][0])
  && (forall u :: 0 <= u < |rep| ==>
        exists i :: 0 <= i < |sccs| && seq_contains(sccs[i], u))
}

ghost function joined(p1: seq<int>, p2: seq<int>): seq<int>
  requires |p1| > 0
{
  p1[..|p1| - 1] + p2
}

lemma ViewWellFormed(graph: Graph)
  requires well_formed(graph)
  ensures WellFormedSeq(view(graph))
{
  var g := view(graph);
  assert g == graph.adj;
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures 0 <= g[u][i] < |g|
  {
    assert 0 <= graph.adj[u][i] < |graph.adj|;
    assert g[u][i] == graph.adj[u][i];
    assert |g| == |graph.adj|;
  }
}

method EdgeExists(g: seq<seq<int>>, u: int, v: int) returns (b: bool)
  requires 0 <= u < |g|
  ensures b == has_edge(g, u, v)
{
  var t := 0;
  while t < |g[u]|
    invariant 0 <= t <= |g[u]|
    invariant forall q :: 0 <= q < t ==> g[u][q] != v
    decreases |g[u]| - t
  {
    if g[u][t] == v {
      b := true;
      assert has_edge(g, u, v) by {
        assert 0 <= u < |g| && 0 <= t < |g[u]| && g[u][t] == v;
      }
      return;
    }
    t := t + 1;
  }
  b := false;
  assert forall q :: 0 <= q < |g[u]| ==> g[u][q] != v;
  assert !has_edge(g, u, v) by {
    if has_edge(g, u, v) {
      var q :| 0 <= u < |g| && 0 <= q < |g[u]| && g[u][q] == v;
      assert g[u][q] != v;
      assert false;
    }
  }
}

lemma PathNodeInRange(g: seq<seq<int>>, p: seq<int>, t: int)
  requires WellFormedSeq(g)
  requires path_valid(g, p)
  requires |p| >= 2
  requires 0 <= t < |p|
  ensures 0 <= p[t] < |g|
{
  if t == 0 {
    assert has_edge(g, p[0], p[1]);
    var i :| 0 <= p[0] < |g| && 0 <= i < |g[p[0]]| && g[p[0]][i] == p[1];
    assert 0 <= p[0] < |g|;
  } else {
    assert has_edge(g, p[t - 1], p[t]);
    var i :| 0 <= p[t - 1] < |g| && 0 <= i < |g[p[t - 1]]| && g[p[t - 1]][i] == p[t];
    assert 0 <= p[t - 1] < |g|;
    assert 0 <= i < |g[p[t - 1]]|;
    assert 0 <= g[p[t - 1]][i] < |g|;
    assert p[t] == g[p[t - 1]][i];
  }
}

lemma ViaZeroCorrect(g: seq<seq<int>>, u: int, v: int)
  requires WellFormedSeq(g)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures has_path_via(g, u, v, 0) <==> (u == v || has_edge(g, u, v))
{
  if u == v {
    var p := [u];
    assert path_valid(g, p);
    assert path_ok(g, p, u, v);
    assert intermediates_below(p, 0);
    assert has_path_via(g, u, v, 0) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, 0);
    }
  }
  if has_edge(g, u, v) {
    var p := [u, v];
    forall kk | 0 <= kk < |p| - 1
      ensures has_edge(g, p[kk], p[kk + 1])
    {
      assert kk == 0;
      assert p[0] == u && p[1] == v;
    }
    assert path_valid(g, p);
    assert path_ok(g, p, u, v);
    assert intermediates_below(p, 0);
    assert has_path_via(g, u, v, 0) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, 0);
    }
  }
  if has_path_via(g, u, v, 0) {
    var p :| path_ok(g, p, u, v) && intermediates_below(p, 0);
    if |p| >= 3 {
      assert 1 <= 1 <= |p| - 2;
      assert p[1] < 0;
      PathNodeInRange(g, p, 1);
      assert 0 <= p[1];
      assert false;
    } else if |p| == 1 {
      assert u == v;
    } else {
      assert |p| == 2;
      assert has_edge(g, p[0], p[1]);
      assert p[0] == u && p[1] == v;
      assert has_edge(g, u, v);
    }
  }
}

lemma ViaMonotone(g: seq<seq<int>>, u: int, v: int, k1: int, k2: int)
  requires k1 <= k2
  requires has_path_via(g, u, v, k1)
  ensures has_path_via(g, u, v, k2)
{
  var p :| path_ok(g, p, u, v) && intermediates_below(p, k1);
  forall t | 1 <= t <= |p| - 2
    ensures p[t] < k2
  {
    assert p[t] < k1;
  }
  assert intermediates_below(p, k2);
  assert has_path_via(g, u, v, k2) by {
    assert path_ok(g, p, u, v);
    assert intermediates_below(p, k2);
  }
}

lemma SubpathValid(g: seq<seq<int>>, p: seq<int>, lo: int, hi: int)
  requires path_valid(g, p)
  requires 0 <= lo < hi <= |p|
  ensures path_valid(g, p[lo..hi])
  ensures |p[lo..hi]| == hi - lo
  ensures (p[lo..hi])[0] == p[lo]
  ensures (p[lo..hi])[hi - lo - 1] == p[hi - 1]
{
  var q := p[lo..hi];
  assert |q| == hi - lo;
  assert q[0] == p[lo];
  assert q[|q| - 1] == p[hi - 1];
  forall kk | 0 <= kk < |q| - 1
    ensures has_edge(g, q[kk], q[kk + 1])
  {
    assert q[kk] == p[lo + kk];
    assert q[kk + 1] == p[lo + kk + 1];
    assert 0 <= lo + kk < |p| - 1;
    assert has_edge(g, p[lo + kk], p[lo + kk + 1]);
  }
  assert path_valid(g, q);
}

lemma {:vcs_split_on_every_assert} ConcatPathValid(g: seq<seq<int>>, p1: seq<int>, p2: seq<int>)
  requires |p1| > 0 && |p2| > 0
  requires path_valid(g, p1)
  requires path_valid(g, p2)
  requires p1[|p1| - 1] == p2[0]
  ensures path_valid(g, joined(p1, p2))
  ensures |joined(p1, p2)| == |p1| + |p2| - 1
  ensures joined(p1, p2)[0] == p1[0]
  ensures joined(p1, p2)[|joined(p1, p2)| - 1] == p2[|p2| - 1]
{
  var p := joined(p1, p2);
  var L := |p1| - 1;
  var pref := p1[..L];
  assert p == pref + p2;
  assert |pref| == L;
  assert |p| == |p1| + |p2| - 1;

  if L == 0 {
    assert |p1| == 1;
    assert pref == [];
    assert p == p2;
    assert p1[0] == p2[0];
    assert p[0] == p1[0];
    assert p[|p| - 1] == p2[|p2| - 1];
    assert path_valid(g, p);
  } else {
    assert |pref| > 0;
    assert p[0] == pref[0] == p1[0];
    assert p[|p| - 1] == p2[|p2| - 1];
    forall kk | 0 <= kk < |p| - 1
      ensures has_edge(g, p[kk], p[kk + 1])
    {
      if kk < L {
        assert p[kk] == pref[kk] == p1[kk];
        assert 0 <= kk < |p1| - 1;
        if kk + 1 < L {
          assert p[kk + 1] == pref[kk + 1] == p1[kk + 1];
        } else {
          assert kk + 1 == L;
          assert p[L] == p2[0];
          assert p2[0] == p1[|p1| - 1] == p1[L];
          assert p[kk + 1] == p1[kk + 1];
        }
        assert has_edge(g, p1[kk], p1[kk + 1]);
        assert has_edge(g, p[kk], p[kk + 1]);
      } else {
        assert kk >= L;
        assert kk <= |p| - 2;
        assert |p| - 2 == L + |p2| - 2;
        assert |p2| >= 2;
        var j := kk - L;
        assert 0 <= j <= |p2| - 2;
        assert j < |p2| - 1;
        assert p[L + j] == p2[j];
        assert kk == L + j;
        assert p[kk] == p2[j];
        assert p[kk + 1] == p2[j + 1];
        assert has_edge(g, p2[j], p2[j + 1]);
      }
    }
    assert path_valid(g, p);
  }
}

lemma ConcatVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, k, k)
  requires has_path_via(g, k, v, k)
  ensures has_path_via(g, u, v, k + 1)
{
  var p1 :| path_ok(g, p1, u, k) && intermediates_below(p1, k);
  var p2 :| path_ok(g, p2, k, v) && intermediates_below(p2, k);
  ConcatPathValid(g, p1, p2);
  var p := joined(p1, p2);
  var L := |p1| - 1;
  assert path_valid(g, p);
  assert |p| == |p1| + |p2| - 1;
  assert p[0] == u;
  assert p[|p| - 1] == v;
  var pref := p1[..L];
  assert p == pref + p2;
  assert |pref| == L;

  forall t | 1 <= t <= |p| - 2
    ensures p[t] < k + 1
  {
    if t < L {
      assert |p1| >= 3;
      assert 1 <= t <= |p1| - 2;
      assert p[t] == pref[t] == p1[t];
      assert p1[t] < k;
      assert p[t] < k + 1;
    } else if t == L {
      assert p[L] == p2[0];
      assert p2[0] == k;
      assert p[t] == k;
      assert k < k + 1;
    } else {
      var j := t - L;
      assert t >= L + 1;
      assert j >= 1;
      assert t <= |p| - 2;
      assert |p| - 2 - L == |p2| - 2;
      assert j <= |p2| - 2;
      assert 1 <= j <= |p2| - 2;
      assert p[L + j] == p2[j];
      assert t == L + j;
      assert p[t] == p2[j];
      assert p2[j] < k;
      assert p[t] < k + 1;
    }
  }
  assert intermediates_below(p, k + 1);
  assert path_ok(g, p, u, v);
  assert has_path_via(g, u, v, k + 1) by {
    assert path_ok(g, p, u, v);
    assert intermediates_below(p, k + 1);
  }
}

lemma {:vcs_split_on_every_assert} SplitVia(g: seq<seq<int>>, u: int, v: int, k: int)
  requires has_path_via(g, u, v, k + 1)
  ensures has_path_via(g, u, v, k) ||
          (has_path_via(g, u, k, k) && has_path_via(g, k, v, k))
{
  var p :| path_ok(g, p, u, v) && intermediates_below(p, k + 1);
  if exists t :: 0 <= t < |p| && p[t] == k {
    var hit :| 0 <= hit < |p| && p[hit] == k;
    var i := 0;
    while p[i] != k
      invariant 0 <= i <= hit < |p|
      invariant p[hit] == k
      invariant forall t :: 0 <= t < i ==> p[t] != k
      decreases hit - i
    {
      assert p[i] != k;
      if i == hit {
        assert p[hit] == k;
        assert false;
      }
      assert i < hit;
      i := i + 1;
    }
    assert i < |p|;
    assert p[i] == k;
    assert forall t :: 0 <= t < i ==> p[t] != k;

    assert hit <= |p| - 1;
    var j := |p| - 1;
    while p[j] != k
      invariant hit <= j < |p|
      invariant p[hit] == k
      invariant forall t :: j < t < |p| ==> p[t] != k
      decreases j - hit
    {
      assert p[j] != k;
      if j == hit {
        assert p[hit] == k;
        assert false;
      }
      assert j > hit;
      forall t | j - 1 < t < |p|
        ensures p[t] != k
      {
        if t == j {
          assert p[j] != k;
        } else {
          assert j < t < |p|;
          assert p[t] != k;
        }
      }
      j := j - 1;
    }
    assert hit <= j < |p|;
    assert p[j] == k;
    assert forall t :: j < t < |p| ==> p[t] != k;

    SubpathValid(g, p, 0, i + 1);
    var left := p[0 .. i + 1];
    assert left == p[0 .. i + 1];
    assert path_valid(g, left);
    assert |left| == i + 1;
    assert left[0] == p[0] == u;
    assert left[|left| - 1] == p[i] == k;
    forall t | 1 <= t <= |left| - 2
      ensures left[t] < k
    {
      assert left[t] == p[t];
      assert 1 <= t <= i - 1;
      assert t < i;
      assert p[t] != k;
      assert 1 <= t <= |p| - 2;
      assert p[t] < k + 1;
      assert p[t] <= k;
      assert p[t] < k;
    }
    assert intermediates_below(left, k);
    assert path_ok(g, left, u, k);
    assert has_path_via(g, u, k, k) by {
      assert path_ok(g, left, u, k);
      assert intermediates_below(left, k);
    }

    SubpathValid(g, p, j, |p|);
    var right := p[j .. |p|];
    assert right == p[j .. |p|];
    assert path_valid(g, right);
    assert |right| == |p| - j;
    assert right[0] == p[j] == k;
    assert right[|right| - 1] == p[|p| - 1] == v;
    forall t | 1 <= t <= |right| - 2
      ensures right[t] < k
    {
      var s := j + t;
      assert right[t] == p[s];
      assert |right| == |p| - j;
      assert 1 <= t <= |p| - j - 2;
      assert s == j + t;
      assert j >= 0;
      assert s >= j + 1;
      assert s <= |p| - 2;
      assert 1 <= s <= |p| - 2;
      assert j < s < |p|;
      assert p[s] != k;
      assert p[s] < k + 1;
      assert p[s] <= k;
      assert p[s] < k;
    }
    assert intermediates_below(right, k);
    assert path_ok(g, right, k, v);
    assert has_path_via(g, k, v, k) by {
      assert path_ok(g, right, k, v);
      assert intermediates_below(right, k);
    }
  } else {
    forall t | 1 <= t <= |p| - 2
      ensures p[t] < k
    {
      assert 0 <= t < |p|;
      assert p[t] != k;
      assert p[t] < k + 1;
      assert p[t] <= k;
      assert p[t] < k;
    }
    assert intermediates_below(p, k);
    assert has_path_via(g, u, v, k) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, k);
    }
  }
}

lemma FWStep(g: seq<seq<int>>, u: int, v: int, k: int)
  ensures has_path_via(g, u, v, k + 1) <==>
          (has_path_via(g, u, v, k) ||
            (has_path_via(g, u, k, k) && has_path_via(g, k, v, k)))
{
  if has_path_via(g, u, v, k) || (has_path_via(g, u, k, k) && has_path_via(g, k, v, k)) {
    if has_path_via(g, u, v, k) {
      ViaMonotone(g, u, v, k, k + 1);
    } else {
      assert has_path_via(g, u, k, k) && has_path_via(g, k, v, k);
      ConcatVia(g, u, v, k);
    }
    assert has_path_via(g, u, v, k + 1);
  }
  if has_path_via(g, u, v, k + 1) {
    SplitVia(g, u, v, k);
    assert has_path_via(g, u, v, k) ||
      (has_path_via(g, u, k, k) && has_path_via(g, k, v, k));
  }
}

lemma ViaIffPath(g: seq<seq<int>>, u: int, v: int)
  requires WellFormedSeq(g)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures has_path_via(g, u, v, |g|) <==> has_path(g, u, v)
{
  if has_path_via(g, u, v, |g|) {
    var p :| path_ok(g, p, u, v) && intermediates_below(p, |g|);
    assert has_path(g, u, v) by {
      assert |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p);
    }
  }
  if has_path(g, u, v) {
    var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_valid(g, p);
    forall t | 1 <= t <= |p| - 2
      ensures p[t] < |g|
    {
      assert |p| >= 3;
      PathNodeInRange(g, p, t);
      assert p[t] < |g|;
    }
    assert intermediates_below(p, |g|);
    assert path_ok(g, p, u, v);
    assert has_path_via(g, u, v, |g|) by {
      assert path_ok(g, p, u, v);
      assert intermediates_below(p, |g|);
    }
  }
}

lemma Reflexive(g: seq<seq<int>>, u: int)
  requires 0 <= u < |g|
  ensures has_path(g, u, u)
{
  var p := [u];
  assert path_valid(g, p);
  assert has_path(g, u, u) by {
    assert |p| > 0 && p[0] == u && p[|p| - 1] == u && path_valid(g, p);
  }
}

lemma PathConcat(g: seq<seq<int>>, u: int, v: int, w: int)
  requires has_path(g, u, v)
  requires has_path(g, v, w)
  ensures has_path(g, u, w)
{
  var p1 :| |p1| > 0 && p1[0] == u && p1[|p1| - 1] == v && path_valid(g, p1);
  var p2 :| |p2| > 0 && p2[0] == v && p2[|p2| - 1] == w && path_valid(g, p2);
  ConcatPathValid(g, p1, p2);
  var p := joined(p1, p2);
  assert path_valid(g, p);
  assert |p| == |p1| + |p2| - 1;
  assert |p| > 0;
  assert p[0] == p1[0] == u;
  assert p[|p| - 1] == p2[|p2| - 1] == w;
  assert has_path(g, u, w) by {
    assert |p| > 0 && p[0] == u && p[|p| - 1] == w && path_valid(g, p);
  }
}

lemma PathConcat3(g: seq<seq<int>>, a: int, b: int, c: int, d: int)
  requires has_path(g, a, b)
  requires has_path(g, b, c)
  requires has_path(g, c, d)
  ensures has_path(g, a, d)
{
  PathConcat(g, a, b, c);
  PathConcat(g, a, c, d);
}

method InitReach(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path_via(g, a, b, 0)
{
  var n := |g|;
  reach := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |reach| == i
    invariant forall a :: 0 <= a < i ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, 0)
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==> row[b] == has_path_via(g, i, b, 0)
      decreases n - j
    {
      var e := EdgeExists(g, i, j);
      ViaZeroCorrect(g, i, j);
      var bit := (i == j) || e;
      assert e == has_edge(g, i, j);
      assert bit == (i == j || has_edge(g, i, j));
      assert has_path_via(g, i, j, 0) == (i == j || has_edge(g, i, j));
      assert bit == has_path_via(g, i, j, 0);
      row := row + [bit];
      j := j + 1;
    }
    reach := reach + [row];
    i := i + 1;
  }
}

method SquareStep(reach: seq<seq<bool>>, k: int) returns (next: seq<seq<bool>>)
  requires 0 <= k < |reach|
  requires forall a :: 0 <= a < |reach| ==> |reach[a]| == |reach|
  ensures |next| == |reach|
  ensures forall a :: 0 <= a < |next| ==> |next[a]| == |reach|
  ensures forall a, b :: 0 <= a < |reach| && 0 <= b < |reach| ==>
      next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
{
  var n := |reach|;
  next := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |next| == i
    invariant forall a :: 0 <= a < i ==> |next[a]| == n
    invariant forall a, b :: 0 <= a < i && 0 <= b < n ==>
        next[a][b] == (reach[a][b] || (reach[a][k] && reach[k][b]))
    decreases n - i
  {
    var row: seq<bool> := [];
    var j := 0;
    while j < n
      invariant 0 <= j <= n
      invariant |row| == j
      invariant forall b :: 0 <= b < j ==>
          row[b] == (reach[i][b] || (reach[i][k] && reach[k][b]))
      decreases n - j
    {
      var bit := reach[i][j] || (reach[i][k] && reach[k][j]);
      row := row + [bit];
      j := j + 1;
    }
    next := next + [row];
    i := i + 1;
  }
}

method {:vcs_split_on_every_assert} FloydWarshall(g: seq<seq<int>>) returns (reach: seq<seq<bool>>)
  requires WellFormedSeq(g)
  ensures |reach| == |g|
  ensures forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  ensures forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path(g, a, b)
{
  var n := |g|;
  reach := InitReach(g);
  var k := 0;
  while k < n
    invariant 0 <= k <= n
    invariant |reach| == n
    invariant forall a :: 0 <= a < n ==> |reach[a]| == n
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==>
        reach[a][b] == has_path_via(g, a, b, k)
    decreases n - k
  {
    var prevReach := reach;
    var next := SquareStep(prevReach, k);
    forall a, b | 0 <= a < n && 0 <= b < n
      ensures next[a][b] == has_path_via(g, a, b, k + 1)
    {
      assert prevReach[a][b] == has_path_via(g, a, b, k);
      assert prevReach[a][k] == has_path_via(g, a, k, k);
      assert prevReach[k][b] == has_path_via(g, k, b, k);
      assert next[a][b] == (prevReach[a][b] || (prevReach[a][k] && prevReach[k][b]));
      FWStep(g, a, b, k);
      assert next[a][b] == has_path_via(g, a, b, k + 1);
    }
    reach := next;
    k := k + 1;
  }
  forall a, b | 0 <= a < n && 0 <= b < n
    ensures reach[a][b] == has_path(g, a, b)
  {
    assert reach[a][b] == has_path_via(g, a, b, n);
    ViaIffPath(g, a, b);
  }
}

lemma IdempotentOne(g: seq<seq<int>>, rep: seq<int>, u: int)
  requires |rep| == |g|
  requires 0 <= u < |g|
  requires forall a :: 0 <= a < |g| ==>
      0 <= rep[a] <= a && has_path(g, a, rep[a]) && has_path(g, rep[a], a)
  requires forall a: int, t: int ::
      0 <= a < |g| && 0 <= t < rep[a] ==>
        !(has_path(g, a, t) && has_path(g, t, a))
  ensures rep[rep[u]] == rep[u]
{
  var r := rep[u];
  assert 0 <= r <= u;
  assert 0 <= r < |g|;
  var rr := rep[r];
  assert 0 <= rr <= r;
  assert has_path(g, u, r) && has_path(g, r, u);
  assert has_path(g, r, rr) && has_path(g, rr, r);
  PathConcat(g, rr, r, u);
  PathConcat(g, u, r, rr);
  assert has_path(g, rr, u) && has_path(g, u, rr);
  if rr < r {
    assert 0 <= rr < rep[u];
    assert !(has_path(g, u, rr) && has_path(g, rr, u));
    assert false;
  }
  assert rr == r;
}

lemma RepMutual(g: seq<seq<int>>, rep: seq<int>, u: int, v: int)
  requires RepCorrect(g, rep)
  requires 0 <= u < |rep| && 0 <= v < |rep|
  ensures (rep[u] == rep[v]) <==> (has_path(g, u, v) && has_path(g, v, u))
{
  if rep[u] == rep[v] {
    var r := rep[u];
    assert has_path(g, u, r) && has_path(g, r, u);
    assert has_path(g, v, r) && has_path(g, r, v);
    PathConcat(g, u, r, v);
    PathConcat(g, v, r, u);
    assert has_path(g, u, v) && has_path(g, v, u);
  }
  if has_path(g, u, v) && has_path(g, v, u) {
    var ru := rep[u];
    var rv := rep[v];
    assert has_path(g, ru, u) && has_path(g, u, ru);
    assert has_path(g, rv, v) && has_path(g, v, rv);
    PathConcat(g, ru, u, v);
    PathConcat(g, v, u, ru);
    PathConcat(g, rv, v, u);
    PathConcat(g, u, v, rv);
    assert has_path(g, ru, v) && has_path(g, v, ru);
    assert has_path(g, rv, u) && has_path(g, u, rv);
    if ru < rv {
      assert 0 <= ru < rep[v];
      assert has_path(g, v, ru) && has_path(g, ru, v);
      assert !(has_path(g, v, ru) && has_path(g, ru, v));
      assert false;
    }
    if rv < ru {
      assert 0 <= rv < rep[u];
      assert has_path(g, u, rv) && has_path(g, rv, u);
      assert !(has_path(g, u, rv) && has_path(g, rv, u));
      assert false;
    }
    assert ru == rv;
  }
}

method {:vcs_split_on_every_assert} PickMin(reach: seq<seq<bool>>, u: int) returns (r: int)
  requires 0 <= u < |reach|
  requires forall a :: 0 <= a < |reach| ==> |reach[a]| == |reach|
  requires reach[u][u]
  ensures 0 <= r <= u
  ensures reach[u][r] && reach[r][u]
  ensures forall t :: 0 <= t < r ==> !(reach[u][t] && reach[t][u])
{
  r := u;
  var v := 0;
  while v < u
    invariant 0 <= v <= u
    invariant 0 <= r <= u
    invariant reach[u][r] && reach[r][u]
    invariant r == u || r < v
    invariant forall t :: 0 <= t < v && reach[u][t] && reach[t][u] ==> r <= t
    decreases u - v
  {
    if reach[u][v] && reach[v][u] && v < r {
      var bound := v;
      forall t | 0 <= t < bound
        ensures !(reach[u][t] && reach[t][u])
      {
        if reach[u][t] && reach[t][u] {
          assert r <= t;
          assert t < bound;
          assert bound < r;
          assert false;
        }
      }
      assert forall tt :: 0 <= tt < bound ==> !(reach[u][tt] && reach[tt][u]);
      r := bound;
      v := bound + 1;
      assert 0 <= r < u;
      assert r <= u;
      assert reach[u][r] && reach[r][u];
      assert r < v;
      assert v <= u;
      forall t | 0 <= t < v && reach[u][t] && reach[t][u]
        ensures r <= t
      {
        if t < bound {
          assert !(reach[u][t] && reach[t][u]);
          assert false;
        } else {
          assert t == bound;
          assert t == r;
        }
      }
    } else {
      var bound := v;
      if reach[u][bound] && reach[bound][u] {
        assert !(bound < r);
        assert r <= bound;
      }
      assert (reach[u][bound] && reach[bound][u]) ==> r <= bound;
      assert forall tt :: 0 <= tt < bound && reach[u][tt] && reach[tt][u] ==> r <= tt;
      assert r == u || r < bound;
      v := bound + 1;
      assert v == bound + 1;
      assert r == u || r < v;
      forall t | 0 <= t < v && reach[u][t] && reach[t][u]
        ensures r <= t
      {
        if t < bound {
          assert r <= t;
        } else {
          assert t == bound;
          assert reach[u][bound] && reach[bound][u];
          assert r <= bound;
        }
      }
    }
  }
  assert v == u;
  forall t | 0 <= t < r
    ensures !(reach[u][t] && reach[t][u])
  {
    if reach[u][t] && reach[t][u] {
      assert t < r <= u;
      assert t < u;
      assert r <= t;
      assert false;
    }
  }
}

method {:vcs_split_on_every_assert} ComputeRep(g: seq<seq<int>>, reach: seq<seq<bool>>) returns (rep: seq<int>)
  requires |reach| == |g|
  requires forall a :: 0 <= a < |g| ==> |reach[a]| == |g|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==>
      reach[a][b] == has_path(g, a, b)
  ensures RepCorrect(g, rep)
{
  var n := |g|;
  rep := [];
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |rep| == i
    invariant forall a :: 0 <= a < i ==> rep[a] == a
    decreases n - i
  {
    rep := rep + [i];
    i := i + 1;
  }

  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |rep| == n
    invariant forall a :: u <= a < n ==> rep[a] == a
    invariant forall a :: 0 <= a < u ==>
        0 <= rep[a] <= a && reach[a][rep[a]] && reach[rep[a]][a]
    invariant forall a: int, t: int ::
        0 <= a < u && 0 <= t < rep[a] ==>
          !(reach[a][t] && reach[t][a])
    decreases n - u
  {
    Reflexive(g, u);
    assert has_path(g, u, u);
    assert reach[u][u] == has_path(g, u, u);
    assert reach[u][u];
    var r := PickMin(reach, u);
    var newRep := rep[u := r];
    assert newRep[u] == r;
    assert forall a :: 0 <= a < n && a != u ==> newRep[a] == rep[a];

    forall a | 0 <= a < u
      ensures newRep[a] == rep[a]
    {
      assert a != u;
      assert newRep[a] == rep[a];
    }
    forall a | u + 1 <= a < n
      ensures newRep[a] == a
    {
      assert a != u;
      assert newRep[a] == rep[a];
      assert rep[a] == a;
    }
    forall a | 0 <= a < u + 1
      ensures 0 <= newRep[a] <= a && reach[a][newRep[a]] && reach[newRep[a]][a]
    {
      if a < u {
        assert newRep[a] == rep[a];
        assert 0 <= rep[a] <= a;
        assert reach[a][rep[a]] && reach[rep[a]][a];
      } else {
        assert a == u;
        assert newRep[a] == r;
        assert 0 <= r <= u;
        assert reach[u][r] && reach[r][u];
      }
    }
    forall a, t | 0 <= a < u + 1 && 0 <= t < newRep[a]
      ensures !(reach[a][t] && reach[t][a])
    {
      if a < u {
        assert newRep[a] == rep[a];
        assert 0 <= t < rep[a];
        assert !(reach[a][t] && reach[t][a]);
      } else {
        assert a == u;
        assert newRep[a] == r;
        assert 0 <= t < r;
        assert !(reach[u][t] && reach[t][u]);
      }
    }
    rep := newRep;
    u := u + 1;
  }

  forall a | 0 <= a < n
    ensures 0 <= rep[a] <= a && has_path(g, a, rep[a]) && has_path(g, rep[a], a)
  {
    assert 0 <= rep[a] <= a;
    assert 0 <= rep[a] < n;
    assert reach[a][rep[a]] == has_path(g, a, rep[a]);
    assert reach[rep[a]][a] == has_path(g, rep[a], a);
    assert reach[a][rep[a]] && reach[rep[a]][a];
  }
  forall a, t | 0 <= a < n && 0 <= t < rep[a]
    ensures !(has_path(g, a, t) && has_path(g, t, a))
  {
    assert 0 <= t < n;
    assert reach[a][t] == has_path(g, a, t);
    assert reach[t][a] == has_path(g, t, a);
    assert !(reach[a][t] && reach[t][a]);
  }
  forall a | 0 <= a < n
    ensures rep[rep[a]] == rep[a]
  {
    IdempotentOne(g, rep, a);
  }
  forall a | 0 <= a < n
    ensures 0 <= rep[a] <= a && rep[rep[a]] == rep[a]
  {
    assert 0 <= rep[a] <= a;
    assert rep[rep[a]] == rep[a];
  }
  assert RepRoots(rep);
  assert |rep| == |g|;
  assert RepCorrect(g, rep);
}

lemma AppendPreserves(s: seq<int>, x: int, y: int)
  requires seq_contains(s, y)
  ensures seq_contains(s + [x], y)
{
  var i :| 0 <= i < |s| && s[i] == y;
  assert 0 <= i < |s + [x]|;
  assert (s + [x])[i] == s[i];
  assert (s + [x])[i] == y;
}

lemma Appended(s: seq<int>, x: int)
  ensures seq_contains(s + [x], x)
{
  assert |s + [x]| == |s| + 1;
  assert (s + [x])[|s|] == x;
}

lemma AppendIncreasing(s: seq<int>, x: int)
  requires forall a, b :: 0 <= a < b < |s| ==> s[a] < s[b]
  requires forall t :: 0 <= t < |s| ==> s[t] < x
  ensures forall a, b :: 0 <= a < b < |s + [x]| ==> (s + [x])[a] < (s + [x])[b]
{
  var nc := s + [x];
  forall a, b | 0 <= a < b < |nc|
    ensures nc[a] < nc[b]
  {
    if b < |s| {
      assert nc[a] == s[a];
      assert nc[b] == s[b];
      assert s[a] < s[b];
    } else {
      assert b == |s|;
      assert nc[b] == x;
      assert a < |s|;
      assert nc[a] == s[a];
      assert s[a] < x;
    }
  }
}

method {:vcs_split_on_every_assert} BuildComp(rep: seq<int>, root: int) returns (comp: seq<int>)
  requires RepRoots(rep)
  requires 0 <= root < |rep|
  requires rep[root] == root
  ensures ClassComp(rep, root, comp)
{
  comp := [];
  var u := 0;
  while u < |rep|
    invariant 0 <= u <= |rep|
    invariant forall t :: 0 <= t < |comp| ==> 0 <= comp[t] < u && rep[comp[t]] == root
    invariant forall x :: 0 <= x < u && rep[x] == root ==> seq_contains(comp, x)
    invariant forall a, b :: 0 <= a < b < |comp| ==> comp[a] < comp[b]
    invariant u <= root ==> |comp| == 0
    invariant u > root ==> |comp| > 0 && comp[0] == root
    decreases |rep| - u
  {
    var u0 := u;
    assert 0 <= u0 < |rep|;
    assert 0 <= rep[u0] <= u0;
    if rep[u0] == root {
      assert root <= u0;
      var base := comp;
      assert base == comp;
      var nc := base + [u0];
      Appended(base, u0);
      assert seq_contains(nc, u0);

      forall x | 0 <= x < u0 && rep[x] == root
        ensures seq_contains(nc, x)
      {
        assert seq_contains(base, x);
        AppendPreserves(base, u0, x);
        assert seq_contains(base + [u0], x);
        assert nc == base + [u0];
      }
      forall x | 0 <= x < u0 + 1 && rep[x] == root
        ensures seq_contains(nc, x)
      {
        if x < u0 {
          assert seq_contains(nc, x);
        } else {
          assert x == u0;
          assert seq_contains(nc, u0);
        }
      }

      forall t | 0 <= t < |base|
        ensures base[t] < u0
      {
        assert base[t] < u0;
      }
      AppendIncreasing(base, u0);

      forall t | 0 <= t < |nc|
        ensures 0 <= nc[t] < u0 + 1 && rep[nc[t]] == root
      {
        if t < |base| {
          assert nc[t] == base[t];
          assert 0 <= base[t] < u0;
          assert rep[base[t]] == root;
        } else {
          assert t == |base|;
          assert nc[t] == u0;
          assert rep[u0] == root;
          assert 0 <= u0 < u0 + 1;
        }
      }

      if u0 == root {
        assert u0 <= root;
        assert |base| == 0;
        assert |nc| == 1;
        assert nc[0] == u0;
        assert nc[0] == root;
      } else {
        assert root <= u0;
        assert u0 > root;
        assert |base| > 0 && base[0] == root;
        assert nc[0] == base[0];
        assert nc[0] == root;
        assert |nc| > 0;
      }
      assert |nc| > 0 && nc[0] == root;
      assert u0 + 1 > root;
      assert forall a, b :: 0 <= a < b < |nc| ==> nc[a] < nc[b];

      comp := nc;
      u := u0 + 1;
    } else {
      assert rep[u0] != root;
      if u0 == root {
        assert rep[root] == root;
        assert false;
      }
      forall x | 0 <= x < u0 + 1 && rep[x] == root
        ensures seq_contains(comp, x)
      {
        if x == u0 {
          assert rep[u0] == root;
          assert false;
        } else {
          assert x < u0;
          assert seq_contains(comp, x);
        }
      }
      forall t | 0 <= t < |comp|
        ensures 0 <= comp[t] < u0 + 1 && rep[comp[t]] == root
      {
        assert 0 <= comp[t] < u0;
        assert rep[comp[t]] == root;
      }
      if u0 < root {
        assert |comp| == 0;
        assert u0 + 1 <= root;
      } else {
        assert u0 > root;
        assert |comp| > 0 && comp[0] == root;
        assert u0 + 1 > root;
      }
      u := u0 + 1;
    }
  }
  assert u == |rep|;
  assert root < |rep|;
  assert u > root;
  assert |comp| > 0 && comp[0] == root;
  assert forall t :: 0 <= t < |comp| ==> 0 <= comp[t] < |rep| && rep[comp[t]] == root;
  assert forall x :: 0 <= x < |rep| && rep[x] == root ==> seq_contains(comp, x);
  assert forall a, b :: 0 <= a < b < |comp| ==> comp[a] < comp[b];
  assert rep[root] == root;
  assert ClassComp(rep, root, comp);
}

lemma StillCovered(sccs: seq<seq<int>>, comp: seq<int>, node: int)
  requires exists i :: 0 <= i < |sccs| && seq_contains(sccs[i], node)
  ensures exists i :: 0 <= i < |sccs + [comp]| && seq_contains((sccs + [comp])[i], node)
{
  var i :| 0 <= i < |sccs| && seq_contains(sccs[i], node);
  assert (sccs + [comp])[i] == sccs[i];
  assert seq_contains((sccs + [comp])[i], node);
}

lemma NewCovered(sccs: seq<seq<int>>, comp: seq<int>, node: int)
  requires seq_contains(comp, node)
  ensures exists i :: 0 <= i < |sccs + [comp]| && seq_contains((sccs + [comp])[i], node)
{
  assert (sccs + [comp])[|sccs|] == comp;
  assert seq_contains((sccs + [comp])[|sccs|], node);
}

method {:vcs_split_on_every_assert} AssembleSccs(rep: seq<int>) returns (sccs: seq<seq<int>>)
  requires RepRoots(rep)
  ensures SccsMatch(rep, sccs)
{
  var n := |rep|;
  sccs := [];
  var r := 0;
  while r < n
    invariant 0 <= r <= n
    invariant forall i :: 0 <= i < |sccs| ==>
        |sccs[i]| > 0 && sccs[i][0] < r && ClassComp(rep, sccs[i][0], sccs[i])
    invariant forall i, j :: 0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
        sccs[i][0] != sccs[j][0]
    invariant forall node :: 0 <= node < n && rep[node] < r ==>
        exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], node)
    decreases n - r
  {
    var r0 := r;
    if rep[r0] == r0 {
      var prevSccs := sccs;
      var comp := BuildComp(rep, r0);
      var nw := prevSccs + [comp];

      forall i | 0 <= i < |nw|
        ensures |nw[i]| > 0 && nw[i][0] < r0 + 1 && ClassComp(rep, nw[i][0], nw[i])
      {
        if i < |prevSccs| {
          assert nw[i] == prevSccs[i];
          assert prevSccs[i][0] < r0;
          assert ClassComp(rep, prevSccs[i][0], prevSccs[i]);
          assert nw[i][0] < r0 + 1;
        } else {
          assert i == |prevSccs|;
          assert nw[i] == comp;
          assert comp[0] == r0;
          assert ClassComp(rep, r0, comp);
          assert nw[i][0] == r0;
          assert r0 < r0 + 1;
        }
      }

      forall i, j | 0 <= i < |nw| && 0 <= j < |nw| && i != j
        ensures nw[i][0] != nw[j][0]
      {
        if i < |prevSccs| && j < |prevSccs| {
          assert nw[i] == prevSccs[i];
          assert nw[j] == prevSccs[j];
          assert prevSccs[i][0] != prevSccs[j][0];
        } else if i == |prevSccs| {
          assert nw[i] == comp;
          assert nw[i][0] == r0;
          assert j < |prevSccs|;
          assert nw[j] == prevSccs[j];
          assert prevSccs[j][0] < r0;
        } else {
          assert j == |prevSccs|;
          assert nw[j] == comp;
          assert nw[j][0] == r0;
          assert i < |prevSccs|;
          assert nw[i] == prevSccs[i];
          assert prevSccs[i][0] < r0;
        }
      }

      forall node | 0 <= node < n && rep[node] < r0 + 1
        ensures exists ii :: 0 <= ii < |nw| && seq_contains(nw[ii], node)
      {
        if rep[node] < r0 {
          StillCovered(prevSccs, comp, node);
          assert exists ii :: 0 <= ii < |prevSccs + [comp]| && seq_contains((prevSccs + [comp])[ii], node);
          assert nw == prevSccs + [comp];
        } else {
          assert rep[node] == r0;
          assert ClassComp(rep, r0, comp);
          assert 0 <= node < |rep|;
          assert seq_contains(comp, node);
          NewCovered(prevSccs, comp, node);
          assert nw == prevSccs + [comp];
        }
      }

      sccs := nw;
      r := r0 + 1;
    } else {
      forall node | 0 <= node < n && rep[node] < r0 + 1
        ensures exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], node)
      {
        if rep[node] < r0 {
          var ii :| 0 <= ii < |sccs| && seq_contains(sccs[ii], node);
        } else {
          assert rep[node] == r0;
          assert 0 <= node < |rep|;
          assert rep[rep[node]] == rep[node];
          assert rep[r0] == rep[node];
          assert rep[r0] == r0;
          assert rep[r0] != r0;
          assert false;
        }
      }
      forall i | 0 <= i < |sccs|
        ensures |sccs[i]| > 0 && sccs[i][0] < r0 + 1 && ClassComp(rep, sccs[i][0], sccs[i])
      {
        assert sccs[i][0] < r0;
        assert sccs[i][0] < r0 + 1;
      }
      r := r0 + 1;
    }
  }

  forall node | 0 <= node < n
    ensures exists ii :: 0 <= ii < |sccs| && seq_contains(sccs[ii], node)
  {
    assert 0 <= rep[node] <= node;
    assert rep[node] < n;
  }
  assert forall i :: 0 <= i < |sccs| ==>
      |sccs[i]| > 0 && ClassComp(rep, sccs[i][0], sccs[i]);
  assert forall i, j :: 0 <= i < |sccs| && 0 <= j < |sccs| && i != j ==>
      |sccs[i]| > 0 && |sccs[j]| > 0 && sccs[i][0] != sccs[j][0];
  assert SccsMatch(rep, sccs);
}

lemma RepOfMember(rep: seq<int>, comp: seq<int>, node: int)
  requires |comp| > 0 && ClassComp(rep, comp[0], comp)
  requires seq_contains(comp, node)
  ensures 0 <= node < |rep|
  ensures rep[node] == comp[0]
{
  var t :| 0 <= t < |comp| && comp[t] == node;
  assert 0 <= comp[t] < |rep|;
  assert rep[comp[t]] == comp[0];
  assert node == comp[t];
}

