lemma SplitRow(f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires 0 <= j <= |cut|
  ensures RowSum(f, u, j) == RowSel(f, cut, u, j, true) + RowSel(f, cut, u, j, false)
  decreases j
{
  if j > 0 {
    SplitRow(f, cut, u, j - 1);
    var v := j - 1;
    RowStep(f, u, j);
    RowSelStep(f, cut, u, j, true);
    RowSelStep(f, cut, u, j, false);
    if cut[v] {
      assert RowSel(f, cut, u, j, true) == RowSel(f, cut, u, j - 1, true) + get_flow(f, u, v);
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false);
    } else {
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false) + get_flow(f, u, v);
      assert RowSel(f, cut, u, j, true) == RowSel(f, cut, u, j - 1, true);
    }
  }
}

lemma SplitCol(f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires 0 <= j <= |cut|
  ensures ColSum(f, u, j) == ColSel(f, cut, u, j, true) + ColSel(f, cut, u, j, false)
  decreases j
{
  if j > 0 {
    SplitCol(f, cut, u, j - 1);
    var v := j - 1;
    ColStep(f, u, j);
    ColSelStep(f, cut, u, j, true);
    ColSelStep(f, cut, u, j, false);
    if cut[v] {
      assert ColSel(f, cut, u, j, true) == ColSel(f, cut, u, j - 1, true) + get_flow(f, v, u);
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false);
    } else {
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false) + get_flow(f, v, u);
      assert ColSel(f, cut, u, j, true) == ColSel(f, cut, u, j - 1, true);
    }
  }
}

ghost function SumSel(f: FlowMap, cut: seq<bool>, i: int, j: int, want: bool, swapped: bool): int
  decreases if i > 0 then i else 0
{
  if i <= 0 then 0
  else
    var prev := SumSel(f, cut, i - 1, j, want, swapped);
    if 0 <= i - 1 < |cut| && cut[i - 1] then
      prev + (if swapped then ColSel(f, cut, i - 1, j, want) else RowSel(f, cut, i - 1, j, want))
    else prev
}

lemma SumSelStep(f: FlowMap, cut: seq<bool>, i: int, j: int, want: bool, swapped: bool)
  requires i > 0
  ensures SumSel(f, cut, i, j, want, swapped) ==
    SumSel(f, cut, i - 1, j, want, swapped) +
      (if 0 <= i - 1 < |cut| && cut[i - 1] then
        (if swapped then ColSel(f, cut, i - 1, j, want) else RowSel(f, cut, i - 1, j, want))
       else 0)
{
}

lemma SumSelZeroJ(f: FlowMap, cut: seq<bool>, i: int, want: bool, swapped: bool)
  ensures SumSel(f, cut, i, 0, want, swapped) == 0
  decreases if i > 0 then i else 0
{
  if i > 0 {
    SumSelZeroJ(f, cut, i - 1, want, swapped);
    SumSelStep(f, cut, i, 0, want, swapped);
    if swapped {
      assert ColSel(f, cut, i - 1, 0, want) == 0;
    } else {
      assert RowSel(f, cut, i - 1, 0, want) == 0;
    }
  }
}

lemma {:vcs_split_on_every_assert} Decompose(f: FlowMap, cut: seq<bool>, rows: int, cols: int)
  requires 0 <= rows <= |cut|
  requires 0 < cols <= |cut|
  ensures SumSel(f, cut, rows, cols, true, false) ==
    SumSel(f, cut, rows, cols - 1, true, false) +
      (if cut[cols - 1] then ColSel(f, cut, cols - 1, rows, true) else 0)
  decreases rows
{
  if rows == 0 {
    assert SumSel(f, cut, 0, cols, true, false) == 0;
    assert SumSel(f, cut, 0, cols - 1, true, false) == 0;
    assert ColSel(f, cut, cols - 1, 0, true) == 0;
  } else {
    Decompose(f, cut, rows - 1, cols);
    var x := rows - 1;
    var cR := cut[x];
    var cC := cut[cols - 1];
    var flow := get_flow(f, x, cols - 1);
    SumSelStep(f, cut, rows, cols, true, false);
    SumSelStep(f, cut, rows, cols - 1, true, false);
    RowSelStep(f, cut, x, cols, true);
    ColSelStep(f, cut, cols - 1, rows, true);
    var A := SumSel(f, cut, x, cols - 1, true, false);
    assert SumSel(f, cut, x, cols, true, false) ==
      A + (if cC then ColSel(f, cut, cols - 1, x, true) else 0);
    if cR && cC {
      assert RowSel(f, cut, x, cols, true) == RowSel(f, cut, x, cols - 1, true) + flow;
      assert ColSel(f, cut, cols - 1, rows, true) == ColSel(f, cut, cols - 1, x, true) + flow;
      assert SumSel(f, cut, rows, cols, true, false) ==
        SumSel(f, cut, x, cols, true, false) + RowSel(f, cut, x, cols, true);
      assert SumSel(f, cut, rows, cols - 1, true, false) ==
        A + RowSel(f, cut, x, cols - 1, true);
    } else if cR && !cC {
      assert RowSel(f, cut, x, cols, true) == RowSel(f, cut, x, cols - 1, true);
      assert SumSel(f, cut, rows, cols, true, false) ==
        SumSel(f, cut, x, cols, true, false) + RowSel(f, cut, x, cols, true);
      assert SumSel(f, cut, rows, cols - 1, true, false) ==
        A + RowSel(f, cut, x, cols - 1, true);
      assert SumSel(f, cut, x, cols, true, false) == A;
    } else if !cR && cC {
      assert SumSel(f, cut, rows, cols, true, false) == SumSel(f, cut, x, cols, true, false);
      assert SumSel(f, cut, rows, cols - 1, true, false) == A;
      assert ColSel(f, cut, cols - 1, rows, true) == ColSel(f, cut, cols - 1, x, true);
    } else {
      assert SumSel(f, cut, rows, cols, true, false) == SumSel(f, cut, x, cols, true, false);
      assert SumSel(f, cut, rows, cols - 1, true, false) == A;
      assert SumSel(f, cut, x, cols, true, false) == A;
    }
  }
}

lemma Transpose(f: FlowMap, cut: seq<bool>, i: int, j: int)
  requires 0 <= i <= |cut| && 0 <= j <= |cut|
  ensures SumSel(f, cut, i, j, true, true) == SumSel(f, cut, j, i, true, false)
  decreases i, j
{
  if i == 0 || j == 0 {
    if i == 0 {
      assert SumSel(f, cut, i, j, true, true) == 0;
      SumSelZeroJ(f, cut, j, true, false);
    }
    if j == 0 {
      SumSelZeroJ(f, cut, i, true, true);
      assert SumSel(f, cut, j, i, true, false) == 0;
    }
  } else {
    Transpose(f, cut, i - 1, j);
    Decompose(f, cut, j, i);
    SumSelStep(f, cut, i, j, true, true);
    assert SumSel(f, cut, i, j, true, true) ==
      SumSel(f, cut, i - 1, j, true, true) +
        (if cut[i - 1] then ColSel(f, cut, i - 1, j, true) else 0);
    assert SumSel(f, cut, i - 1, j, true, true) == SumSel(f, cut, j, i - 1, true, false);
  }
}

ghost function EdgeCross(f: FlowMap, cut: seq<bool>, u: int, j: int): int
  decreases if j > 0 then j else 0
{
  if j <= 0 then 0
  else
    var v := j - 1;
    var add := if 0 <= v < |cut| && !cut[v] then get_flow(f, u, v) - get_flow(f, v, u) else 0;
    EdgeCross(f, cut, u, j - 1) + add
}

lemma EdgeCrossStep(f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires j > 0
  ensures EdgeCross(f, cut, u, j) ==
    EdgeCross(f, cut, u, j - 1) +
      (if 0 <= j - 1 < |cut| && !cut[j - 1] then get_flow(f, u, j - 1) - get_flow(f, j - 1, u) else 0)
{
}

lemma EdgeIsDiff(f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires 0 <= j <= |cut|
  ensures EdgeCross(f, cut, u, j) == RowSel(f, cut, u, j, false) - ColSel(f, cut, u, j, false)
  decreases j
{
  if j > 0 {
    EdgeIsDiff(f, cut, u, j - 1);
    var v := j - 1;
    EdgeCrossStep(f, cut, u, j);
    RowSelStep(f, cut, u, j, false);
    ColSelStep(f, cut, u, j, false);
    if !cut[v] {
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false) + get_flow(f, u, v);
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false) + get_flow(f, v, u);
    } else {
      assert RowSel(f, cut, u, j, false) == RowSel(f, cut, u, j - 1, false);
      assert ColSel(f, cut, u, j, false) == ColSel(f, cut, u, j - 1, false);
    }
  }
}

ghost function CrossClean(f: FlowMap, cut: seq<bool>, i: int): int
