lemma {:vcs_split_on_every_assert} SumExcessOnlyST(g: seq<seq<(int, int)>>, f: FlowMap, cut: seq<bool>, s: int, t: int, i: int)
  requires 0 <= i <= |g|
  requires |cut| == |g|
  requires 0 <= s < |g| && 0 <= t < |g| && s != t
  requires forall u :: 0 <= u < |g| && u != s && u != t ==>
    total_flow_out(g, f, u) == total_flow_in(g, f, u)
  ensures ExcessSum(g, f, cut, i) ==
    (if 0 <= s < i && cut[s] then total_flow_out(g, f, s) - total_flow_in(g, f, s) else 0) +
    (if 0 <= t < i && cut[t] then total_flow_out(g, f, t) - total_flow_in(g, f, t) else 0)
  decreases i
{
  if i > 0 {
    SumExcessOnlyST(g, f, cut, s, t, i - 1);
    ExcessSumStep(g, f, cut, i);
    var u := i - 1;
    var sold := if 0 <= s < i - 1 && cut[s] then total_flow_out(g, f, s) - total_flow_in(g, f, s) else 0;
    var told := if 0 <= t < i - 1 && cut[t] then total_flow_out(g, f, t) - total_flow_in(g, f, t) else 0;
    assert ExcessSum(g, f, cut, i - 1) == sold + told;
    if u == s && cut[s] {
      assert s == i - 1;
      assert !(0 <= s < i - 1);
      assert 0 <= s < i;
      assert t != s;
      assert (0 <= t < i) <==> (0 <= t < i - 1);
    } else if u == s && !cut[s] {
      assert !(cut[s]);
      assert (0 <= t < i) <==> (0 <= t < i - 1);
    } else if u == t && cut[t] {
      assert t == i - 1;
      assert !(0 <= t < i - 1);
      assert 0 <= t < i;
      assert (0 <= s < i) <==> (0 <= s < i - 1);
    } else if u == t && !cut[t] {
      assert (0 <= s < i) <==> (0 <= s < i - 1);
    } else {
      assert u != s && u != t;
      if cut[u] {
        assert total_flow_out(g, f, u) == total_flow_in(g, f, u);
      }
      assert (0 <= s < i) <==> (0 <= s < i - 1);
      assert (0 <= t < i) <==> (0 <= t < i - 1);
    }
  }
}

lemma ExcessSumNet(g: seq<seq<(int, int)>>, f: FlowMap, cut: seq<bool>, i: int)
  requires |cut| == |g|
  requires 0 <= i <= |g|
  requires forall u :: 0 <= u < i ==>
    total_flow_out(g, f, u) - total_flow_in(g, f, u) == RowSum(f, u, |g|) - ColSum(f, u, |g|)
  ensures ExcessSum(g, f, cut, i) == NetClean(f, cut, |g|, i)
  decreases i
{
  if i > 0 {
    assert forall u :: 0 <= u < i - 1 ==>
      total_flow_out(g, f, u) - total_flow_in(g, f, u) == RowSum(f, u, |g|) - ColSum(f, u, |g|);
    ExcessSumNet(g, f, cut, i - 1);
    ExcessSumStep(g, f, cut, i);
    NetStep(f, cut, |g|, i);
  }
}

lemma ValEqCross(g: seq<seq<(int, int)>>, f: FlowMap, cut: seq<bool>, s: int, t: int)
  requires WFSeq(g)
  requires capacities_bounded(g)
  requires is_valid_flow(g, f, s, t)
  requires |cut| == |g|
  requires 0 <= s < |g| && 0 <= t < |g| && s != t
  requires cut[s] && !cut[t]
  ensures flow_val(g, f, s) == CrossClean(f, cut, |g|)
{
  var n := |g|;
  forall u | 0 <= u < n
    ensures total_flow_out(g, f, u) - total_flow_in(g, f, u) == RowSum(f, u, n) - ColSum(f, u, n)
  {
    forall v | 0 <= v < n && EdgeIndex(g, u, v) < 0
      ensures get_flow(f, u, v) == 0
    {
      OffEdgeZero(g, f, u, v);
    }
    OutEqRow(g, f, u);
    TotalIn(g, f, u);
  }
  SumExcessOnlyST(g, f, cut, s, t, n);
  assert ExcessSum(g, f, cut, n) == total_flow_out(g, f, s) - total_flow_in(g, f, s);
  assert flow_val(g, f, s) == total_flow_out(g, f, s) - total_flow_in(g, f, s);
  ExcessSumNet(g, f, cut, n);
  NetEqCross(f, cut);
}

