lemma EdgeLeqCap(g: seq<seq<(int, int)>>, f: FlowMap, cut: seq<bool>, u: int, j: int)
  requires |cut| == |g|
  requires 0 <= j <= |cut|
  requires 0 <= u < |g|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| ==> 0 <= get_flow(f, a, b) <= Cap(g, a, b)
  ensures EdgeCross(f, cut, u, j) <= CapSel(g, cut, u, j)
  decreases j
{
  if j > 0 {
    EdgeLeqCap(g, f, cut, u, j - 1);
    var v := j - 1;
    EdgeCrossStep(f, cut, u, j);
    CapSelStep(g, cut, u, j);
    if 0 <= v < |cut| && !cut[v] {
      assert get_flow(f, v, u) >= 0;
      assert get_flow(f, u, v) - get_flow(f, v, u) <= get_flow(f, u, v);
      assert get_flow(f, u, v) <= Cap(g, u, v);
