lemma {:vcs_split_on_every_assert} OurValid(g: seq<seq<(int, int)>>, res: seq<seq<int>>, f: FlowMap, s: int, t: int, total: int)
  requires capacities_bounded(g)
  requires ResOk(g, res, s, t, total)
  requires f == BuildFlow(g, res, 0, 0)
  ensures is_valid_flow(g, f, s, t)
  ensures flow_val(g, f, s) == total
{
  var n := |g|;
  forall x, y | true
    ensures get_flow(f, x, y) == (if 0 <= x < n && 0 <= y < n then FlowOn(g, res, x, y) else 0)
  {
    FinalFlow(g, res, x, y);
  }
  forall x, y | (x, y) in f
    ensures f[(x, y)] >= 0
  {
    KeyPos(g, res, 0, 0, x, y);
    assert get_flow(f, x, y) > 0;
    assert f[(x, y)] == get_flow(f, x, y);
  }
  forall x, y | (x, y) in f
    ensures f[(x, y)] > 0 ==> exists c :: has_capacity(g, x, y, c) && f[(x, y)] <= c
  {
    KeyPos(g, res, 0, 0, x, y);
    assert get_flow(f, x, y) > 0;
    FinalFlow(g, res, x, y);
    assert 0 <= x < n && 0 <= y < n;
    assert FlowOn(g, res, x, y) > 0;
    CapBounded(g, x, y);
    FlowOnLeCap(g, res, x, y);
    assert Cap(g, x, y) > 0;
