  requires |cut| == |g|
  requires 0 <= j <= |cut|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| && cut[a] && !cut[b] ==>
    get_flow(f, a, b) - get_flow(f, b, a) == Cap(g, a, b)
  ensures EdgeCross(f, cut, u, j) == CapSel(g, cut, u, j)
  decreases j
{
  if j > 0 {
    EdgeEqCap(g, f, cut, u, j - 1);
    var v := j - 1;
    EdgeCrossStep(f, cut, u, j);
    CapSelStep(g, cut, u, j);
    if 0 <= v < |cut| && !cut[v] && 0 <= u < |g| && cut[u] {
