lemma CrossEqCap(g: seq<seq<(int, int)>>, f: FlowMap, cut: seq<bool>, i: int)
  requires |cut| == |g|
  requires 0 <= i <= |cut|
  requires forall a, b :: 0 <= a < |g| && 0 <= b < |g| && cut[a] && !cut[b] ==>
    get_flow(f, a, b) - get_flow(f, b, a) == Cap(g, a, b)
  ensures CrossClean(f, cut, i) == CutCapClean(g, cut, i)
  decreases i
{
