  requires vis[s] && !vis[t]
  requires forall u, v :: 0 <= u < |g| && 0 <= v < |g| && vis[u] && res[u][v] > 0 ==> vis[v]
  ensures exists f: FlowMap :: is_max_flow(g, f, s, t) && flow_val(g, f, s) == total
