    ensures get_flow(f, u, v) - get_flow(f, v, u) == Cap(g, u, v)
  {
    if res[u][v] > 0 {
      assert vis[v];
      assert false;
    }
    assert res[u][v] == 0;
    CapBounded(g, u, v);
    CapBounded(g, v, u);
    SaturatePair(g, res, u, v);
    FinalFlow(g, res, u, v);
    FinalFlow(g, res, v, u);
    assert get_flow(f, u, v) == FlowOn(g, res, u, v);
    assert get_flow(f, v, u) == FlowOn(g, res, v, u);
