  CrossEqCap(g, f, vis, n);
  ValEqCross(g, f, vis, s, t);
  assert flow_val(g, f, s) == CutCapClean(g, vis, n);

  forall other: FlowMap {:trigger is_valid_flow(g, other, s, t)} | is_valid_flow(g, other, s, t)
    ensures flow_val(g, f, s) >= flow_val(g, other, s)
  {
