lemma {:induction false} new_left_prefix(n: Node, newLeft: Node, key: seq<int>)
    requires n.well_formed()
    requires |key| > 0
    requires key[0] < n.val
    requires newLeft.view() == opt_view(n.left) + iset{key}
    ensures forall s: seq<int> :: s in newLeft.view() ==> |s| > 0 && s[0] < n.val
{
    parts_eq(n);
    forall s: seq<int> | s in newLeft.view()
        ensures |s| > 0 && s[0] < n.val
    {
        union_mem(opt_view(n.left), iset{key}, s);
        singleton_mem(s, key);
        assert s in (opt_view(n.left) + iset{key});
        assert s in opt_view(n.left) || s == key;
        if s == key {
            assert |key| > 0 && key[0] < n.val;
        } else {
            assert s in opt_view(n.left);
            match n.left {
                case Some(l) =>
                    assert opt_view(n.left) == l.view();
                    assert s in l.view();
                    assert leftOK(n);
                    left_props(n, l);
                    assert |s| > 0 && s[0] < n.val;
                case None =>
                    assert opt_view(n.left) == iset{};
                    assert s in iset{};
                    assert false;
            }
        }
    }
}

