lemma {:induction false} mid_preserves(n: Node, newMid: Node, key: seq<int>, res: Node, q: seq<int>)
    requires |key| > 1
    requires key[0] == n.val
    requires newMid.view() == opt_view(n.mid) + iset{key[1..]}
    requires res == Node(n.val, n.is_end, n.left, Some(newMid), n.right)
    ensures res.contains(q) <==> n.contains(q) || q == key
{
    assert res.val == n.val;
    assert res.is_end == n.is_end;
    assert res.left == n.left;
    assert res.right == n.right;
    assert res.mid == Some(newMid);

    if |q| == 0 {
        contains_empty(res, q);
        contains_empty(n, q);
        assert q != key;
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else if q[0] < n.val {
        contains_lt(res, q);
        contains_lt(n, q);
        assert opt_contains(res.left, q) == opt_contains(n.left, q);
        assert q[0] != key[0];
        assert q != key;
        assert res.contains(q) == n.contains(q);
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else if q[0] > n.val {
        contains_gt(res, q);
        contains_gt(n, q);
        assert opt_contains(res.right, q) == opt_contains(n.right, q);
        assert q[0] != key[0];
        assert q != key;
        assert res.contains(q) == n.contains(q);
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else if |q| == 1 {
        contains_eq_one(res, q);
        contains_eq_one(n, q);
        assert res.contains(q) == res.is_end == n.is_end == n.contains(q);
        assert |key| > 1;
        assert q != key;
        assert res.contains(q) == n.contains(q);
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else {
        contains_eq_rest(res, q);
        contains_eq_rest(n, q);
        assert opt_contains(res.mid, q[1..]) == newMid.contains(q[1..]);
        assert n.contains(q) == opt_contains(n.mid, q[1..]);
        child_contains_spec(newMid, n.mid, key[1..], q[1..]);
        assert q[0] == key[0] == n.val;
        assert newMid.contains(q[1..]) <==> opt_contains(n.mid, q[1..]) || q[1..] == key[1..];
        assert res.contains(q) == newMid.contains(q[1..]);
        if q[1..] == key[1..] {
