            assert q == key;
            assert newMid.contains(q[1..]);
            assert res.contains(q);
            assert res.contains(q) <==> n.contains(q) || q == key;
        } else {
            assert q[1..] != key[1..];
            assert q != key;
            assert newMid.contains(q[1..]) == opt_contains(n.mid, q[1..]);
            assert res.contains(q) == n.contains(q);
            assert res.contains(q) <==> n.contains(q) || q == key;
        }
    }
