lemma {:induction false} establish_wf_left(n: Node, newLeft: Node, res: Node)
    requires n.well_formed()
    requires newLeft.well_formed() && !newLeft.is_empty()
    requires res == Node(n.val, n.is_end, Some(newLeft), n.mid, n.right)
    requires forall s | s in newLeft.view() :: |s| > 0 && s[0] < n.val
    ensures res.well_formed()
{
    parts_eq(n);
    assert res.val == n.val;
    assert res.left == Some(newLeft);
    assert res.mid == n.mid;
    assert res.right == n.right;
    assert 0 <= res.val < 256;

    forall s | s in newLeft.view()
        ensures |s| > 0 && s[0] < res.val
    {
        assert |s| > 0 && s[0] < n.val;
        assert n.val == res.val;
    }
    assert forall s | s in newLeft.view() :: |s| > 0 && s[0] < res.val;
    assert leftOK(res);

    rightOK_same(n, res);
    midOK_same(n, res);
    assert rightOK(res);
    assert midOK(res);
    parts_suffice(res);
}

