lemma {:induction false} left_preserves(n: Node, newLeft: Node, key: seq<int>, res: Node, q: seq<int>)
    requires |key| > 0
    requires key[0] < n.val
    requires newLeft.view() == opt_view(n.left) + iset{key}
    requires res == Node(n.val, n.is_end, Some(newLeft), n.mid, n.right)
    ensures res.contains(q) <==> n.contains(q) || q == key
{
    assert res.val == n.val;
    assert res.is_end == n.is_end;
    assert res.left == Some(newLeft);
    assert res.mid == n.mid;
    assert res.right == n.right;
    child_contains_spec(newLeft, n.left, key, q);

    if |q| == 0 {
        contains_empty(res, q);
        contains_empty(n, q);
        assert q != key;
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else if q[0] < n.val {
        contains_lt(res, q);
        contains_lt(n, q);
        assert q[0] < res.val;
        assert opt_contains(res.left, q) == newLeft.contains(q);
        assert res.contains(q) == newLeft.contains(q);
        assert n.contains(q) == opt_contains(n.left, q);
        assert newLeft.contains(q) <==> opt_contains(n.left, q) || q == key;
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else if q[0] > n.val {
        contains_gt(res, q);
        contains_gt(n, q);
        assert q[0] > res.val;
        assert opt_contains(res.right, q) == opt_contains(n.right, q);
        assert key[0] < n.val && q[0] > n.val;
        assert q[0] != key[0];
        assert q != key;
        assert res.contains(q) == n.contains(q);
        assert res.contains(q) <==> n.contains(q) || q == key;
    } else {
        assert q[0] == n.val == res.val;
        assert key[0] < n.val;
        assert q[0] != key[0];
        assert q != key;
        if |q| == 1 {
            contains_eq_one(res, q);
            contains_eq_one(n, q);
            assert res.contains(q) == n.contains(q);
            assert res.contains(q) <==> n.contains(q) || q == key;
        } else {
            contains_eq_rest(res, q);
            contains_eq_rest(n, q);
            assert opt_contains(res.mid, q[1..]) == opt_contains(n.mid, q[1..]);
            assert res.contains(q) == n.contains(q);
            assert res.contains(q) <==> n.contains(q) || q == key;
        }
    }
}

