        assert !opt_contains(res.mid, q[1..]);
        assert !res.contains(q);
        assert |q| != |key|;
        assert q != key;
        assert res.contains(q) <==> q == key;
    }
}

lemma {:induction false} chain_contains_at(key: seq<int>, mid: Node, res: Node, q: seq<int>)
    requires |key| > 1
    requires res == Node(key[0], false, None, Some(mid), None)
    requires forall s: seq<int> :: mid.contains(s) <==> s == key[1..]
    ensures res.contains(q) <==> q == key
{
    assert res.val == key[0];
    assert !res.is_end;
    assert res.left.None?;
    assert res.right.None?;
    assert res.mid == Some(mid);
    if |q| == 0 {
        contains_empty(res, q);
        assert q != key;
        assert res.contains(q) <==> q == key;
    } else if q[0] < res.val {
        contains_lt(res, q);
        assert !opt_contains(res.left, q);
        assert !res.contains(q);
        assert q[0] != key[0];
        assert q != key;
        assert res.contains(q) <==> q == key;
    } else if q[0] > res.val {
        contains_gt(res, q);
        assert !opt_contains(res.right, q);
        assert !res.contains(q);
        assert q[0] != key[0];
        assert q != key;
        assert res.contains(q) <==> q == key;
    } else if |q| == 1 {
        contains_eq_one(res, q);
        assert res.contains(q) == false;
        assert |key| > 1;
        assert q != key;
        assert res.contains(q) <==> q == key;
    } else {
        contains_eq_rest(res, q);
        assert opt_contains(res.mid, q[1..]) == mid.contains(q[1..]);
        assert mid.contains(q[1..]) <==> q[1..] == key[1..];
        assert res.contains(q) == mid.contains(q[1..]);
        assert q[0] == key[0];
        if q[1..] == key[1..] {
            seq_cons_eq(q, key);
            assert res.contains(q);
            assert q == key;
            assert res.contains(q) <==> q == key;
        } else {
            assert !mid.contains(q[1..]);
            assert !res.contains(q);
            assert q != key;
            assert res.contains(q) <==> q == key;
        }
    }
}

lemma {:induction false} prove_singleton(key: seq<int>, res: Node)
    requires |key| == 1
    requires 0 <= key[0] < 256
    requires res == Node(key[0], true, None, None, None)
    ensures res.well_formed()
    ensures !res.is_empty()
    ensures forall q: seq<int> :: res.contains(q) <==> q == key
    ensures res.view() == iset{key}
{
    assert res.val == key[0];
    assert 0 <= res.val < 256;
    assert res.left.None?;
    assert res.mid.None?;
    assert res.right.None?;
    assert res.is_end;
    assert leftOK(res);
    assert rightOK(res);
    assert midOK(res);
    parts_suffice(res);
    not_empty_end(res);
    forall q: seq<int>
        ensures res.contains(q) <==> q == key
    {
        singleton_contains_at(key, res, q);
    }
    view_eq_singleton(res, key);
}

lemma {:induction false} prove_chain(key: seq<int>, mid: Node, res: Node)
    requires |key| > 1
    requires 0 <= key[0] < 256
    requires mid.well_formed() && !mid.is_empty()
    requires forall s: seq<int> :: mid.contains(s) <==> s == key[1..]
    requires res == Node(key[0], false, None, Some(mid), None)
    ensures res.well_formed()
    ensures !res.is_empty()
    ensures forall q: seq<int> :: res.contains(q) <==> q == key
    ensures res.view() == iset{key}
{
    assert res.val == key[0];
    assert 0 <= res.val < 256;
    assert res.left.None?;
    assert res.right.None?;
    assert res.mid == Some(mid);
    assert leftOK(res);
    assert rightOK(res);
    assert midOK(res);
    parts_suffice(res);
    not_empty_mid(res);
    forall q: seq<int>
        ensures res.contains(q) <==> q == key
    {
        chain_contains_at(key, mid, res, q);
    }
    view_eq_singleton(res, key);
}

method build(key: seq<int>) returns (res: Node)
    requires |key| > 0
    requires forall k :: k in key ==> 0 <= k < 256
    ensures res.well_formed()
    ensures !res.is_empty()
    ensures res.view() == iset{key}
    ensures forall q: seq<int> :: res.contains(q) <==> q == key
    decreases |key|
{
    if |key| == 1 {
        head_byte(key);
        res := Node(key[0], true, None, None, None);
        prove_singleton(key, res);
    } else {
        assert |key| > 1;
        tail_bytes(key);
        assert |key[1..]| > 0;
        assert |key[1..]| < |key|;
        var mid := build(key[1..]);
        head_byte(key);
        res := Node(key[0], false, None, Some(mid), None);
        prove_chain(key, mid, res);
    }
}

method insert(tree: Option<Node>, key: seq<int>) returns (res: Node)
    requires opt_well_formed(tree)
    // Constraint: Input key elements must represent bytes (u8)
    requires forall k :: k in key ==> 0 <= k < 256
    requires |key| > 0
    ensures
        // Invariant Preservation
        && res.well_formed()
        && !res.is_empty()
        // Set Update
        && res.view() == opt_view(tree) + iset{key}
    decreases optSize(tree), |key|
{
    match tree {
        case None =>
            res := build(key);
            opt_view_none(tree);
            empty_union(iset{key});
            assert res.view() == iset{key};
            assert opt_view(tree) == iset{};
            assert opt_view(tree) + iset{key} == iset{key};
            assert res.view() == opt_view(tree) + iset{key};
            assert res.well_formed();
            assert !res.is_empty();
        case Some(n) =>
            assert tree == Some(n);
            assert n.well_formed() && !n.is_empty();
            size_child(n);
            optSize_some(n);
            assert optSize(tree) == optSize(Some(n));
            assert optSize(n.left) < optSize(tree);
            assert optSize(n.mid) < optSize(tree);
            assert optSize(n.right) < optSize(tree);
            children_wf(n);
            if key[0] < n.val {
                assert opt_well_formed(n.left);
                var newLeft := insert(n.left, key);
                res := Node(n.val, n.is_end, Some(newLeft), n.mid, n.right);
                left_insert_ok(n, newLeft, key, res);
                opt_view_some(n);
                assert opt_view(tree) == n.view();
                assert res.view() == n.view() + iset{key};
                assert res.view() == opt_view(tree) + iset{key};
            } else if key[0] > n.val {
                assert opt_well_formed(n.right);
                var newRight := insert(n.right, key);
                res := Node(n.val, n.is_end, n.left, n.mid, Some(newRight));
                right_insert_ok(n, newRight, key, res);
                opt_view_some(n);
                assert opt_view(tree) == n.view();
                assert res.view() == n.view() + iset{key};
                assert res.view() == opt_view(tree) + iset{key};
            } else if |key| == 1 {
                assert key[0] == n.val;
                res := Node(n.val, true, n.left, n.mid, n.right);
                end_insert_ok(n, key, res);
                opt_view_some(n);
                assert opt_view(tree) == n.view();
                assert res.view() == n.view() + iset{key};
                assert res.view() == opt_view(tree) + iset{key};
            } else {
                assert key[0] == n.val;
                assert |key| > 1;
                tail_bytes(key);
                assert |key[1..]| > 0;
                assert opt_well_formed(n.mid);
                assert optSize(n.mid) < optSize(tree);
                var newMid := insert(n.mid, key[1..]);
                res := Node(n.val, n.is_end, n.left, Some(newMid), n.right);
                mid_insert_ok(n, newMid, key, res);
                opt_view_some(n);
                assert opt_view(tree) == n.view();
                assert res.view() == n.view() + iset{key};
                assert res.view() == opt_view(tree) + iset{key};
            }
    }
}
