            case Some(l) => res := searchNode(l, key);
            case None => res := false;
        }
    } else if c > n.val {
        match n.right {
            case Some(r) => res := searchNode(r, key);
            case None => res := false;
        }
    } else {
        if |key| == 1 {
            res := n.is_end;
        } else {
            match n.mid {
                case Some(m) => res := searchNode(m, key[1..]);
                case None => res := false;
            }
        }
    }
}

