lemma EdgeEnds(g: Graph, u: int, v: int)
  requires well_formed(g)
  requires has_edge(g, u, v)
  ensures 0 <= u < |g.adj| && 0 <= v < |g.adj|
{
  var i :| 0 <= u < |g.adj| && 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
}

lemma CardRange(s: set<int>, n: int)
  requires n >= 0
  requires forall w :: w in s <==> 0 <= w < n
  ensures |s| == n
  decreases n
{
  if n == 0 {
    assert s == {};
  } else {
    assert n - 1 in s;
    var s' := s - {n - 1};
    CardRange(s', n - 1);
  }
}

lemma PathIncreases(g: Graph, order: seq<int>, p: seq<int>, i0: int, k: int) returns (idx: int)
  requires well_formed(g)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires forall i, j :: 0 <= j <= i < |order| ==> !has_edge(g, order[i], order[j])
  requires is_path(g, p)
  requires 0 <= i0 < |order| && order[i0] == p[0]
  requires 0 < k < |p|
  ensures i0 < idx < |order| && order[idx] == p[k]
  decreases k
{
  var prev: int;
  if k == 1 {
    prev := i0;
  } else {
    prev := PathIncreases(g, order, p, i0, k - 1);
  }
  assert order[prev] == p[k - 1];
  var j := k - 1;
  assert has_edge(g, p[j], p[j + 1]);
  assert has_edge(g, p[k - 1], p[k]);
  EdgeEnds(g, p[k - 1], p[k]);
  assert p[k] in order;
  idx :| 0 <= idx < |order| && order[idx] == p[k];
  if idx <= prev {
    assert !has_edge(g, order[prev], order[idx]);
    assert false;
  }
}

lemma NoCycle(g: Graph, order: seq<int>)
  requires well_formed(g)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires forall i, j :: 0 <= i < j < |order| ==> order[i] != order[j]
  requires forall i, j :: 0 <= j <= i < |order| ==> !has_edge(g, order[i], order[j])
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);
    var z := 0;
    assert has_edge(g, p[z], p[z + 1]);
    assert has_edge(g, p[0], p[1]);
    EdgeEnds(g, p[0], p[1]);
    assert p[0] in order;
    var i0 :| 0 <= i0 < |order| && order[i0] == p[0];
    var idx := PathIncreases(g, order, p, i0, |p| - 1);
    assert order[idx] == p[|p| - 1];
    assert order[idx] == order[i0];
    assert false;
  }
}

lemma WalkBack(g: Graph, removed: seq<bool>, p: seq<int>, unvisited: set<int>)
  requires |removed| == |g.adj|
  requires forall w :: 0 <= w < |g.adj| && !removed[w] ==> exists u :: 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, w)
  requires is_path(g, p)
  requires 0 <= p[0] < |g.adj| && !removed[p[0]]
  requires forall w :: 0 <= w < |g.adj| && w !in p ==> w in unvisited
  ensures graph_has_cycle(g)
  decreases |unvisited|
{
  var u :| 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, p[0]);
  if u in p {
    var i :| 0 <= i < |p| && p[i] == u;
    var c := [u] + p[..i + 1];
    assert |c| == i + 2;
    forall k | 0 <= k < |c| - 1
      ensures has_edge(g, c[k], c[k + 1])
    {
      if k == 0 {
        assert c[0] == u && c[1] == p[0];
      } else {
        var j := k - 1;
        assert has_edge(g, p[j], p[j + 1]);
        assert c[k] == p[k - 1] && c[k + 1] == p[k];
      }
    }
    assert is_path(g, c);
    assert c[0] == u && c[|c| - 1] == p[i];
    assert is_cycle(g, c);
  } else {
    assert u in unvisited;
    var p' := [u] + p;
    forall k | 0 <= k < |p'| - 1
      ensures has_edge(g, p'[k], p'[k + 1])
    {
      if k == 0 {
        assert p'[0] == u && p'[1] == p[0];
      } else {
        var j := k - 1;
        assert has_edge(g, p[j], p[j + 1]);
        assert p'[k] == p[k - 1] && p'[k + 1] == p[k];
      }
    }
    assert is_path(g, p');
    WalkBack(g, removed, p', unvisited - {u});
  }
}

method find_pred(g: Graph, removed: seq<bool>, v: int) returns (found: bool, u: int)
  requires |removed| == |g.adj|
  ensures found ==> 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, v)
  ensures !found ==> forall w :: 0 <= w < |g.adj| && !removed[w] ==> !has_edge(g, w, v)
{
  var n := |g.adj|;
  var w := 0;
  while w < n
    invariant 0 <= w <= n
    invariant forall x :: 0 <= x < w && !removed[x] ==> !has_edge(g, x, v)
  {
    if !removed[w] {
      var i := 0;
      while i < |g.adj[w]|
        invariant 0 <= i <= |g.adj[w]|
        invariant forall j :: 0 <= j < i ==> g.adj[w][j] != v
      {
        if g.adj[w][i] == v {
          assert has_edge(g, w, v);
          return true, w;
        }
        i := i + 1;
      }
      assert !has_edge(g, w, v);
    }
    w := w + 1;
  }
  return false, 0;
}

method find_source(g: Graph, removed: seq<bool>) returns (found: bool, s: int)
  requires |removed| == |g.adj|
  ensures found ==> 0 <= s < |g.adj| && !removed[s] && forall u :: 0 <= u < |g.adj| && !removed[u] ==> !has_edge(g, u, s)
  ensures !found ==> forall w :: 0 <= w < |g.adj| && !removed[w] ==> exists u :: 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, w)
{
  var v := 0;
  while v < |g.adj|
    invariant 0 <= v <= |g.adj|
    invariant forall w :: 0 <= w < v && !removed[w] ==> exists u :: 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, w)
  {
    if !removed[v] {
      var f, u := find_pred(g, removed, v);
      if !f {
        return true, v;
      }
      assert 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, v);
    }
    v := v + 1;
  }
  return false, 0;
}

method topological_sort(graph: Graph) returns (res: Option<seq<int>>)
  requires well_formed(graph)
  ensures match res {
    case Some(order) => 
      // 1. The graph must be acyclic
      !graph_has_cycle(graph) 
      // 2. The returned vector is a valid ordering
      && is_topological_ordering(graph, order)
    case None => 
      // Must contain a cycle if sort is impossible
      graph_has_cycle(graph)
  }
{
  var n := |graph.adj|;
  var removed: seq<bool> := seq(n, _ => false);
  ghost var rem: set<int> := set w | 0 <= w < n;
  CardRange(rem, n);
  var order: seq<int> := [];
  var k := 0;
  while k < n
    invariant 0 <= k <= n
    invariant |removed| == n
    invariant |order| == k
    invariant forall w :: w in rem <==> 0 <= w < n && !removed[w]
    invariant |rem| == n - k
    invariant forall j :: 0 <= j < |order| ==> 0 <= order[j] < n && removed[order[j]]
    invariant forall w :: 0 <= w < n && removed[w] ==> w in order
