lemma PathIncreases(g: Graph, order: seq<int>, p: seq<int>, i0: int, k: int) returns (idx: int)
  requires well_formed(g)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires NoBack(g, order)
  requires is_path(g, p)
  requires 0 <= i0 < |order| && order[i0] == p[0]
  requires 0 < k < |p|
  ensures i0 < idx < |order| && order[idx] == p[k]
  decreases k
{
  var prev: int;
  if k == 1 {
    prev := i0;
  } else {
    prev := PathIncreases(g, order, p, i0, k - 1);
  }
  assert order[prev] == p[k - 1];
  var j := k - 1;
  assert has_edge(g, p[j], p[j + 1]);
  assert has_edge(g, p[k - 1], p[k]);
  EdgeEnds(g, p[k - 1], p[k]);
  assert p[k] in order;
  idx :| 0 <= idx < |order| && order[idx] == p[k];
  if idx <= prev {
    assert !has_edge(g, order[prev], order[idx]);
    assert false;
  }
}

lemma NoCycle(g: Graph, order: seq<int>)
  requires well_formed(g)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires forall i, j :: 0 <= i < j < |order| ==> order[i] != order[j]
  requires NoBack(g, order)
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);
    var z := 0;
    assert has_edge(g, p[z], p[z + 1]);
    assert has_edge(g, p[0], p[1]);
    EdgeEnds(g, p[0], p[1]);
    assert p[0] in order;
    var i0 :| 0 <= i0 < |order| && order[i0] == p[0];
    var idx := PathIncreases(g, order, p, i0, |p| - 1);
    assert order[idx] == p[|p| - 1];
    assert order[idx] == order[i0];
    assert false;
  }
}

lemma PrependPath(g: Graph, u: int, p: seq<int>)
  requires is_path(g, p)
  requires has_edge(g, u, p[0])
  ensures is_path(g, [u] + p)
{
  var c := [u] + p;
  forall k | 0 <= k < |c| - 1
    ensures has_edge(g, c[k], c[k + 1])
  {
    if k == 0 {
      assert c[0] == u && c[1] == p[0];
    } else {
      var j := k - 1;
      assert has_edge(g, p[j], p[j + 1]);
      assert c[k] == p[k - 1] && c[k + 1] == p[k];
    }
  }
}

