}

lemma WalkBack(g: Graph, removed: seq<bool>, p: seq<int>, unvisited: set<int>)
  requires |removed| == |g.adj|
  requires AllHavePred(g, removed)
  requires is_path(g, p)
  requires 0 <= p[0] < |g.adj| && !removed[p[0]]
  requires forall w :: 0 <= w < |g.adj| && !removed[w] && w !in p ==> w in unvisited
  ensures graph_has_cycle(g)
  decreases |unvisited|
{
  assert HasPred(g, removed, p[0]);
  var u :| 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, p[0]);
  if u in p {
    var i :| 0 <= i < |p| && p[i] == u;
    PrefixPath(g, p, i);
    var q := p[..i + 1];
    assert q[0] == p[0];
    PrependPath(g, u, q);
    var c := [u] + q;
    assert |c| == i + 2;
    assert c[0] == u;
    assert c[|c| - 1] == q[i] == u;
    assert is_cycle(g, c);
  } else {
    assert u in unvisited;
    PrependPath(g, u, p);
    var p' := [u] + p;
    forall w | 0 <= w < |g.adj| && !removed[w] && w !in p'
      ensures w in unvisited - {u}
    {
      assert w != u;
      assert w !in p;
    }
    WalkBack(g, removed, p', unvisited - {u});
  }
}

lemma Step(g: Graph, removed: seq<bool>, order: seq<int>, s: int)
  requires |removed| == |g.adj|
  requires NoBack(g, order)
  requires NoInto(g, removed, order)
  requires IsSource(g, removed, s)
  ensures NoBack(g, order + [s])
  ensures NoInto(g, removed[s := true], order + [s])
{
  var o := order + [s];
  var r := removed[s := true];
  forall i, j | 0 <= j <= i < |o|
    ensures !has_edge(g, o[i], o[j])
  {
    if i < |order| {
      assert o[i] == order[i] && o[j] == order[j];
    } else if j < |order| {
      assert o[i] == s && o[j] == order[j];
      assert !has_edge(g, s, order[j]);
    } else {
      assert o[i] == s && o[j] == s;
    }
  }
  forall j, u | 0 <= j < |o| && 0 <= u < |g.adj| && !r[u]
    ensures !has_edge(g, u, o[j])
  {
    assert u != s;
    assert !removed[u];
    if j < |order| {
      assert o[j] == order[j];
    } else {
      assert o[j] == s;
    }
  }
}

method find_pred(g: Graph, removed: seq<bool>, v: int) returns (found: bool, u: int)
  requires |removed| == |g.adj|
  ensures found ==> 0 <= u < |g.adj| && !removed[u] && has_edge(g, u, v)
  ensures !found ==> forall w :: 0 <= w < |g.adj| && !removed[w] ==> !has_edge(g, w, v)
