        invariant forall j :: 0 <= j < i ==> g.adj[w][j] != v
      {
        if g.adj[w][i] == v {
          assert has_edge(g, w, v);
          return true, w;
        }
        i := i + 1;
      }
      assert !has_edge(g, w, v);
    }
    w := w + 1;
  }
  return false, 0;
}

method find_source(g: Graph, removed: seq<bool>) returns (found: bool, s: int)
