    forall x | x in Nodes(n)
      ensures 0 <= x < n
    {
      if x != n - 1 {
        assert x in Nodes(n - 1);
      }
    }

    forall x | 0 <= x < n
      ensures x in Nodes(n)
    {
      if x < n - 1 {
        assert x in Nodes(n - 1);
      } else {
        assert x == n - 1;
      }
    }

    forall i: int, j: int |
        0 <= i < j < |Nodes(n)|
      ensures Nodes(n)[i] != Nodes(n)[j]
    {
      if j < |Nodes(n - 1)| {
        assert Nodes(n)[i] == Nodes(n - 1)[i];
        assert Nodes(n)[j] == Nodes(n - 1)[j];
      } else {
        assert j == |Nodes(n - 1)|;
        assert Nodes(n)[j] == n - 1;
        assert Nodes(n)[i] in Nodes(n - 1);
        assert Nodes(n)[i] < n - 1;
