lemma IncomingEquivalence(g: Graph, remaining: seq<int>, v: int)
  requires forall i: int ::
    0 <= i < |remaining| ==> 0 <= remaining[i] < |g.adj|
  ensures Incoming(g, remaining, v) <==>
    exists u: int :: u in remaining && has_edge(g, u, v)
{
  if Incoming(g, remaining, v) {
    var i :| 0 <= i < |remaining| && Edge(g, remaining[i], v);
    EdgeEquivalence(g, remaining[i], v);
  } else if exists u: int :: u in remaining && has_edge(g, u, v) {
    var u :| u in remaining && has_edge(g, u, v);
    var i :| 0 <= i < |remaining| && remaining[i] == u;
    EdgeEquivalence(g, u, v);
    assert Edge(g, remaining[i], v);
  }
}

method IncomingIndex(
    g: Graph, remaining: seq<int>, v: int) returns (index: int)
  requires forall i: int ::
    0 <= i < |remaining| ==> 0 <= remaining[i] < |g.adj|
  requires Incoming(g, remaining, v)
  ensures 0 <= index < |remaining|
  ensures has_edge(g, remaining[index], v)
{
  index := 0;
  while index < |remaining| && !Edge(g, remaining[index], v)
    invariant 0 <= index <= |remaining|
    invariant forall i: int ::
      0 <= i < index ==> !Edge(g, remaining[i], v)
    decreases |remaining| - index
  {
    index := index + 1;
  }

  if index == |remaining| {
    assert forall i: int ::
      0 <= i < |remaining| ==> !Edge(g, remaining[i], v);
    assert !Incoming(g, remaining, v);
    assert false;
  }

  EdgeEquivalence(g, remaining[index], v);
}

