  forall x | x in next
    ensures 0 <= x < n
  {
    assert x in remaining;
  }

  forall x | 0 <= x < n
    ensures x in ordered + [u] || x in next
  {
    if x in ordered {
    } else if x == u {
    } else {
      assert x in remaining;
      assert x in next;
    }
  }

  forall x | x in ordered + [u]
    ensures !(x in next)
