lemma AdvanceEdges(
    g: Graph, ordered: seq<int>, remaining: seq<int>, k: int)
  requires 0 <= k < |remaining|
  requires forall i: int ::
    0 <= i < |remaining| ==> 0 <= remaining[i] < |g.adj|
  requires Unique(remaining)
  requires StrongOrder(g, ordered)
  requires NoEdgeTo(g, remaining, ordered)
  requires !Incoming(g, remaining, remaining[k])
  ensures StrongOrder(g, ordered + [remaining[k]])
  ensures NoEdgeTo(
    g,
    RemoveAt(remaining, k),
    ordered + [remaining[k]])
{
  var u := remaining[k];
  var next := RemoveAt(remaining, k);
  RemoveAtFacts(remaining, k);
  IncomingEquivalence(g, remaining, u);

  forall i: int, j: int |
      0 <= j <= i < |ordered + [u]|
    ensures !has_edge(
      g, (ordered + [u])[i], (ordered + [u])[j])
  {
    if i < |ordered| {
    } else {
      assert i == |ordered|;
      assert (ordered + [u])[i] == u;
      if j < |ordered| {
        assert (ordered + [u])[j] in ordered;
        assert u in remaining;
      } else {
        assert j == i;
        if has_edge(g, u, u) {
          assert exists x: int ::
            x in remaining && has_edge(g, x, u);
          assert false;
        }
      }
    }
  }

  forall x: int, y: int |
      x in next && y in ordered + [u]
    ensures !has_edge(g, x, y)
  {
    assert x in remaining;
    if y in ordered {
    } else {
      assert y == u;
      if has_edge(g, x, u) {
        assert exists z: int ::
          z in remaining && has_edge(g, z, u);
        assert false;
      }
    }
  }
}

lemma PrependPath(g: Graph, p: seq<int>, x: int)
  requires is_path(g, p)
