lemma Pigeonhole(s: seq<int>, universe: seq<int>)
  requires Unique(universe)
  requires |s| > |universe|
  requires forall x: int :: x in s ==> x in universe
  ensures exists i: int, j: int ::
    0 <= i < j < |s| && s[i] == s[j]
  decreases |universe|
{
  if |universe| == 0 {
    assert |s| > 0;
    assert 0 <= 0 < |s|;
    assert s[0] in s;
    assert s[0] in universe;
    assert false;
  } else {
    assert |s| > 0;
    assert 0 <= 0 < |s|;
    assert s[0] in s;
    assert s[0] in universe;
    var k :| 0 <= k < |universe| && universe[k] == s[0];

    if exists j: int :: 1 <= j < |s| && s[j] == s[0] {
      var j :| 1 <= j < |s| && s[j] == s[0];
      assert 0 <= 0 < j < |s|;
    } else {
      var tail := s[1..];
      var smaller := RemoveAt(universe, k);
      RemoveAtFacts(universe, k);

      assert |tail| > |smaller|;

      forall x | x in tail
        ensures x in smaller
      {
        assert x in s;
        assert x in universe;
        if x == universe[k] {
          var j :| 0 <= j < |tail| && tail[j] == x;
          assert s[j + 1] == s[0];
          assert 1 <= j + 1 < |s|;
          assert false;
        }
      }

      Pigeonhole(tail, smaller);
      var a, b :|
        0 <= a < b < |tail| && tail[a] == tail[b];
      assert 0 <= a + 1 < b + 1 < |s|;
      assert s[a + 1] == s[b + 1];
    }
  }
}

