      assert !(u in ordered);
    }
  }

  forall x | x in ordered + [u]
    ensures 0 <= x < n
  {
    if x in ordered {
    } else {
      assert x == u;
    }
  }

  forall x | x in next
    ensures 0 <= x < n
  {
    assert x in remaining;
  }

  forall x | 0 <= x < n
    ensures x in ordered + [u] || x in next
  {
    if x in ordered {
    } else if x == u {
    } else {
      assert x in remaining;
      assert x in next;
    }
  }

  forall x | x in ordered + [u]
    ensures !(x in next)
  {
    if x in ordered {
      if x in next {
        assert x in remaining;
        assert false;
      }
    } else {
      assert x == u;
    }
  }
}

ghost predicate StrongOrder(g: Graph, ordered: seq<int>)
{
  forall i: int, j: int ::
    0 <= j <= i < |ordered| ==>
      !has_edge(g, ordered[i], ordered[j])
}

ghost predicate NoEdgeTo(
    g: Graph, sources: seq<int>, targets: seq<int>)
{
  forall u: int, v: int ::
    u in sources && v in targets ==> !has_edge(g, u, v)
}

lemma AdvanceEdges(
    g: Graph, ordered: seq<int>, remaining: seq<int>, k: int)
  requires 0 <= k < |remaining|
  requires forall i: int ::
    0 <= i < |remaining| ==> 0 <= remaining[i] < |g.adj|
  requires Unique(remaining)
  requires StrongOrder(g, ordered)
  requires NoEdgeTo(g, remaining, ordered)
  requires !Incoming(g, remaining, remaining[k])
  ensures StrongOrder(g, ordered + [remaining[k]])
  ensures NoEdgeTo(
    g,
    RemoveAt(remaining, k),
    ordered + [remaining[k]])
{
  var u := remaining[k];
  var next := RemoveAt(remaining, k);
  RemoveAtFacts(remaining, k);
  IncomingEquivalence(g, remaining, u);

  forall i: int, j: int |
      0 <= j <= i < |ordered + [u]|
    ensures !has_edge(
      g, (ordered + [u])[i], (ordered + [u])[j])
  {
    if i < |ordered| {
    } else {
      assert i == |ordered|;
      assert (ordered + [u])[i] == u;
      if j < |ordered| {
        assert (ordered + [u])[j] in ordered;
        assert u in remaining;
      } else {
        assert j == i;
        if has_edge(g, u, u) {
          assert exists x: int ::
            x in remaining && has_edge(g, x, u);
          assert false;
        }
      }
    }
  }

  forall x: int, y: int |
      x in next && y in ordered + [u]
    ensures !has_edge(g, x, y)
  {
    assert x in remaining;
    if y in ordered {
    } else {
      assert y == u;
      if has_edge(g, x, u) {
        assert exists z: int ::
          z in remaining && has_edge(g, z, u);
        assert false;
      }
    }
  }
}

lemma PrependPath(g: Graph, p: seq<int>, x: int)
  requires is_path(g, p)
  requires has_edge(g, x, p[0])
  ensures is_path(g, [x] + p)
{
  forall i | 0 <= i < |[x] + p| - 1
    ensures has_edge(g, ([x] + p)[i], ([x] + p)[i + 1])
  {
    if i == 0 {
    } else {
      assert ([x] + p)[i] == p[i - 1];
      assert ([x] + p)[i + 1] == p[i];
    }
  }
}

lemma PathSlice(g: Graph, p: seq<int>, i: int, j: int)
  requires is_path(g, p)
  requires 0 <= i < j < |p|
  ensures is_path(g, p[i..j + 1])
{
  forall k
      {:trigger has_edge(
        g, p[i..j + 1][k], p[i..j + 1][k + 1])}
      | 0 <= k < |p[i..j + 1]| - 1
    ensures has_edge(
      g, p[i..j + 1][k], p[i..j + 1][k + 1])
  {
    assert p[i..j + 1][k] == p[i + k];
    assert p[i..j + 1][k + 1] == p[i + k + 1];
  }
}

lemma {:vcs_split_on_every_assert} RepeatedPathNodeGivesCycle(
    g: Graph, p: seq<int>, i: int, j: int)
  requires is_path(g, p)
  requires 0 <= i < j < |p|
  requires p[i] == p[j]
  ensures graph_has_cycle(g)
{
  PathSlice(g, p, i, j);
  ghost var cycle := p[i..j + 1];

  assert is_path(g, cycle);
  assert |cycle| == j - i + 1;
  assert |cycle| > 1;
  assert cycle[0] == p[i];
  assert |cycle| - 1 == j - i;
  assert cycle[|cycle| - 1] == p[i + (j - i)];
  assert i + (j - i) == j;
  assert cycle[|cycle| - 1] == p[j];
  assert cycle[0] == cycle[|cycle| - 1];
  assert is_cycle(g, cycle);
  assert exists q: seq<int> :: is_cycle(g, q);
}

lemma Pigeonhole(s: seq<int>, universe: seq<int>)
  requires Unique(universe)
  requires |s| > |universe|
  requires forall x: int :: x in s ==> x in universe
  ensures exists i: int, j: int ::
    0 <= i < j < |s| && s[i] == s[j]
  decreases |universe|
{
  if |universe| == 0 {
    assert |s| > 0;
    assert 0 <= 0 < |s|;
    assert s[0] in s;
    assert s[0] in universe;
    assert false;
  } else {
    assert |s| > 0;
    assert 0 <= 0 < |s|;
    assert s[0] in s;
    assert s[0] in universe;
    var k :| 0 <= k < |universe| && universe[k] == s[0];

    if exists j: int :: 1 <= j < |s| && s[j] == s[0] {
      var j :| 1 <= j < |s| && s[j] == s[0];
      assert 0 <= 0 < j < |s|;
    } else {
      var tail := s[1..];
      var smaller := RemoveAt(universe, k);
      RemoveAtFacts(universe, k);

      assert |tail| > |smaller|;

      forall x | x in tail
        ensures x in smaller
      {
        assert x in s;
        assert x in universe;
        if x == universe[k] {
          var j :| 0 <= j < |tail| && tail[j] == x;
          assert s[j + 1] == s[0];
          assert 1 <= j + 1 < |s|;
          assert false;
        }
      }

      Pigeonhole(tail, smaller);
      var a, b :|
        0 <= a < b < |tail| && tail[a] == tail[b];
      assert 0 <= a + 1 < b + 1 < |s|;
      assert s[a + 1] == s[b + 1];
    }
  }
}

ghost function IndexOf(s: seq<int>, x: int): int
  requires x in s
  decreases |s|
{
  if s[0] == x then 0
  else 1 + IndexOf(s[1..], x)
}

lemma IndexOfFacts(s: seq<int>, x: int)
  requires x in s
  ensures 0 <= IndexOf(s, x) < |s|
  ensures s[IndexOf(s, x)] == x
  decreases |s|
{
  if s[0] != x {
    assert x in s[1..];
    IndexOfFacts(s[1..], x);
  }
}

lemma EdgeGoesForward(
    g: Graph, ordered: seq<int>, u: int, v: int)
  requires StrongOrder(g, ordered)
  requires u in ordered
  requires v in ordered
  requires has_edge(g, u, v)
  ensures IndexOf(ordered, u) < IndexOf(ordered, v)
{
  IndexOfFacts(ordered, u);
  IndexOfFacts(ordered, v);
  var i := IndexOf(ordered, u);
  var j := IndexOf(ordered, v);
  if j <= i {
    assert 0 <= j <= i < |ordered|;
    assert !has_edge(g, ordered[i], ordered[j]);
    assert ordered[i] == u;
    assert ordered[j] == v;
    assert false;
  }
}

lemma PathNodesBound(g: Graph, p: seq<int>)
  requires well_formed(g)
  requires is_path(g, p)
  requires |p| > 1
  ensures forall i: int ::
    0 <= i < |p| ==> 0 <= p[i] < |g.adj|
{
  forall i | 0 <= i < |p|
    ensures 0 <= p[i] < |g.adj|
  {
    if i < |p| - 1 {
      assert has_edge(g, p[i], p[i + 1]);
      EdgeBounds(g, p[i], p[i + 1]);
    } else {
      assert i == |p| - 1;
      assert has_edge(g, p[i - 1], p[i]);
      EdgeBounds(g, p[i - 1], p[i]);
    }
  }
}

lemma PathEndpointIncrease(
    g: Graph, ordered: seq<int>, p: seq<int>)
  requires is_path(g, p)
  requires |p| > 1
  requires StrongOrder(g, ordered)
  requires forall i: int :: 0 <= i < |p| ==> p[i] in ordered
  ensures IndexOf(ordered, p[0])
        < IndexOf(ordered, p[|p| - 1])
  decreases |p|
{
  assert has_edge(g, p[0], p[1]);
  EdgeGoesForward(g, ordered, p[0], p[1]);

  if |p| > 2 {
    var tail := p[1..];
    assert |tail| > 1;

    forall i | 0 <= i < |tail| - 1
      ensures has_edge(g, tail[i], tail[i + 1])
    {
      assert tail[i] == p[i + 1];
      assert tail[i + 1] == p[i + 2];
    }

    assert is_path(g, tail);

    forall i | 0 <= i < |tail|
      ensures tail[i] in ordered
    {
      assert tail[i] == p[i + 1];
    }

    PathEndpointIncrease(g, ordered, tail);
    assert tail[0] == p[1];
    assert tail[|tail| - 1] == p[|p| - 1];
  } else {
    assert |p| == 2;
    assert p[1] == p[|p| - 1];
  }
}

lemma StrongOrderIsAcyclic(
    g: Graph, ordered: seq<int>)
  requires well_formed(g)
  requires StrongOrder(g, ordered)
  requires forall n: int ::
    0 <= n < |g.adj| ==> n in ordered
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);
    assert is_path(g, p);
    assert |p| > 1;
    PathNodesBound(g, p);

    forall i | 0 <= i < |p|
      ensures p[i] in ordered
    {
      assert 0 <= p[i] < |g.adj|;
    }

    PathEndpointIncrease(g, ordered, p);
    assert p[0] == p[|p| - 1];
    assert IndexOf(ordered, p[0])
        == IndexOf(ordered, p[|p| - 1]);
    assert false;
  }
}

method {:vcs_split_on_every_assert} topological_sort(
    graph: Graph) returns (res: Option<seq<int>>)
  requires well_formed(graph)
  ensures match res {
    case Some(order) =>
      !graph_has_cycle(graph)
      && is_topological_ordering(graph, order)
    case None =>
      graph_has_cycle(graph)
  }
{
  var n := |graph.adj|;
  var ordered: seq<int> := [];
  var remaining := Nodes(n);
  NodesFacts(n);

  while |remaining| > 0
    invariant Partition(n, ordered, remaining)
    invariant |ordered| + |remaining| == n
    invariant StrongOrder(graph, ordered)
    invariant NoEdgeTo(graph, remaining, ordered)
    decreases |remaining|
  {
    forall i | 0 <= i < |remaining|
      ensures 0 <= remaining[i] < |graph.adj|
    {
      assert remaining[i] in remaining;
      assert 0 <= remaining[i] < n;
      assert n == |graph.adj|;
    }

    var k := 0;

    while k < |remaining|
          && Incoming(graph, remaining, remaining[k])
      invariant 0 <= k <= |remaining|
      invariant forall i: int ::
        0 <= i < |remaining| ==>
          0 <= remaining[i] < |graph.adj|
      invariant forall q: int ::
        0 <= q < k ==>
          Incoming(graph, remaining, remaining[q])
      decreases |remaining| - k
    {
      k := k + 1;
    }

    if k == |remaining| {
      assert |remaining| > 0;
      assert forall q: int ::
        0 <= q < |remaining| ==>
          Incoming(graph, remaining, remaining[q]);

      var walk := [remaining[0]];
      var steps := 0;

      while steps < |remaining|
        invariant 0 <= steps <= |remaining|
        invariant |walk| == steps + 1
        invariant is_path(graph, walk)
        invariant forall x: int :: x in walk ==> x in remaining
        decreases |remaining| - steps
      {
        assert walk[0] in remaining;
        var q :| 0 <= q < |remaining|
                  && remaining[q] == walk[0];
        assert Incoming(graph, remaining, walk[0]);

        var predecessor :=
          IncomingIndex(graph, remaining, walk[0]);
        assert has_edge(
          graph, remaining[predecessor], walk[0]);

        PrependPath(
          graph, walk, remaining[predecessor]);
        walk := [remaining[predecessor]] + walk;
        steps := steps + 1;
      }

      assert |walk| == |remaining| + 1;
      assert forall x: int ::
        x in walk ==> x in remaining;

      Pigeonhole(walk, remaining);
      ghost var i, j :|
        0 <= i < j < |walk| && walk[i] == walk[j];

      RepeatedPathNodeGivesCycle(graph, walk, i, j);
      res := None;
      return;
    }

    assert 0 <= k < |remaining|;
    assert !Incoming(
      graph, remaining, remaining[k]);

    var u := remaining[k];
    var next := RemoveAt(remaining, k);

    MovePartition(n, ordered, remaining, k);
    AdvanceEdges(graph, ordered, remaining, k);
    RemoveAtFacts(remaining, k);

    ordered := ordered + [u];
    remaining := next;
  }

  assert |ordered| == n;
  assert forall x: int ::
    0 <= x < n ==> x in ordered;

  assert forall i: int, j: int ::
    0 <= i < j < |ordered| ==> ordered[i] != ordered[j];

  assert forall i: int, j: int ::
    0 <= j < i < |ordered| ==>
      !has_edge(graph, ordered[i], ordered[j]);

  assert is_topological_ordering(graph, ordered);
  StrongOrderIsAcyclic(graph, ordered);
  res := Some(ordered);
}
