                    assert key == [index] + tail;
                } else if key == [index] + tail {
                    assert key[1..] == ([index] + tail)[1..];
                    assert rest == tail;
                }

                assert
                    (key == [index] + tail) <==>
                    (rest == tail);
                assert updated.contains(key) <==>
                    child.contains(rest);
                assert n.contains(key) <==>
                    option_contains(n.children[index], rest);
            } else {
                assert updated.children[head] == n.children[head];

                if key == [index] + tail {
                    assert key[0] == index;
                    assert head == index;
                }

                assert key != [index] + tail;
                assert updated.contains(key) <==> n.contains(key);
            }
        } else {
            if key == [index] + tail {
                assert key[0] == index;
                assert head == index;
            }

            assert key != [index] + tail;
            assert !n.contains(key);
            assert !updated.contains(key);
        }
    }
}

lemma replacement_properties(
    n: Node,
    index: int,
    child: Node,
    tail: seq<int>
)
    requires n.well_formed()
    requires 0 <= index < 256
    requires child.well_formed()
    requires !child.is_empty()
    requires child.view() ==
        opt_view(n.children[index]) + iset{tail}
    ensures
        Node(
            n.is_end,
            n.children[index := Some(child)]
        ).well_formed()
    ensures
        !Node(
            n.is_end,
            n.children[index := Some(child)]
        ).is_empty()
    ensures
        Node(
            n.is_end,
            n.children[index := Some(child)]
        ).view()
        ==
        n.view() + iset{[index] + tail}
{
    var updatedChildren := n.children[index := Some(child)];
    var updated := Node(n.is_end, updatedChildren);

    assert |n.children| == 256;
    assert |updatedChildren| == 256;
    assert |updated.children| == 256;

    forall i: int | 0 <= i < 256
        ensures
            match updated.children[i] {
                case Some(c) =>
                    c.well_formed() && !c.is_empty()
                case None => true
            }
    {
        if i == index {
            assert updated.children[i] == Some(child);
        } else {
            assert updated.children[i] == n.children[i];
            assert
                match n.children[i] {
                    case Some(c) =>
                        c.well_formed() && !c.is_empty()
                    case None => true
                };
        }
    }

    assert updated.well_formed();

    assert !updated.is_empty() by {
        if updated.is_empty() {
            assert updated.children[index].None?;
            assert updated.children[index] == Some(child);
            assert false;
        }
    }

    assert updated.view() ==
        n.view() + iset{[index] + tail} by
    {
        forall key: seq<int>
            ensures
                (key in updated.view()) <==>
                (key in n.view() + iset{[index] + tail})
        {
            replacement_contains(n, index, child, tail, key);
            assert (key in updated.view()) <==>
                updated.contains(key);
            assert (key in n.view()) <==> n.contains(key);
            assert
                (key in n.view() + iset{[index] + tail})
                <==>
                (n.contains(key) || key == [index] + tail);
        }
    }
}

method insert(tree: Option<Node>, key: seq<int>) returns (res: Node)
    requires opt_well_formed(tree)
    requires forall k :: k in key ==> 0 <= k < 256
    ensures 
        && res.well_formed()
        && !res.is_empty()
        && res.view() == opt_view(tree) + iset{key}
    decreases |key|
{
    var n: Node;

    match tree {
        case Some(root) =>
            n := root;
            assert n.well_formed();
            assert n.view() == opt_view(tree);

        case None =>
            empty_node_properties();
            n := empty_node();
            assert n.well_formed();
            assert n.view() == opt_view(tree);
    }

    if |key| == 0 {
        assert key == [];
        mark_end_properties(n);
        res := Node(true, n.children);

        assert res.well_formed();
        assert !res.is_empty();
        assert res.view() == n.view() + iset{[]};
        assert res.view() == opt_view(tree) + iset{key};
    } else {
        var index := key[0];
        assert key[0] in key;
        assert 0 <= index < 256;
        assert key == [index] + key[1..];

        var oldChild := n.children[index];

        assert
            match oldChild {
                case Some(child) =>
                    child.well_formed() && !child.is_empty()
                case None => true
            };

        assert opt_well_formed(oldChild);

        forall k: int | k in key[1..]
            ensures 0 <= k < 256
        {
            assert k in key;
        }

        var newChild := insert(oldChild, key[1..]);

        replacement_properties(
            n,
            index,
            newChild,
            key[1..]
        );

        res := Node(
            n.is_end,
            n.children[index := Some(newChild)]
        );

        assert res.well_formed();
        assert !res.is_empty();
        assert res.view() ==
            n.view() + iset{[index] + key[1..]};
        assert [index] + key[1..] == key;
        assert res.view() == opt_view(tree) + iset{key};
    }
}
