method search(tree: Option<Node>, key: seq<int>) returns (res: bool)
    requires opt_well_formed(tree)
    // Constraint: Input key elements must represent bytes (u8)
    requires forall k :: k in key ==> 0 <= k < 256 
    ensures res == (key in opt_view(tree))
{
    if tree.None? {
        return false;
    }
    var root := tree.value;
    assert key in opt_view(tree) <==> root.contains(key);
    var node := root;
    var i := 0;
    assert key[0..] == key;
    while i < |key|
        invariant 0 <= i <= |key|
        invariant node.contains(key[i..]) == root.contains(key)
        decreases |key| - i
    {
        var c := key[i];
        assert key[i..][0] == c;
        assert key[i..][1..] == key[i+1..];
        if c < 0 || c >= |node.children| {
            return false;
        }
        match node.children[c] {
            case None =>
                return false;
            case Some(child) =>
                node := child;
        }
        i := i + 1;
    }
    assert key[i..] == [];
    res := node.is_end;
}

