method Partition(a: array<int>) returns (lo: int, hi: int)
  modifies a
  ensures 0 <= lo <= hi <= a.Length
  ensures forall x | 0 <= x < lo :: a[x] < 0
  ensures forall x | lo <= x < hi :: a[x] == 0
  ensures forall x | hi <= x < a.Length :: a[x] > 0
{
  lo := 0;
  var mid := 0;
  hi := a.Length;
  while mid < hi
    invariant 0 <= lo <= mid <= hi <= a.Length
    invariant forall x | 0 <= x < lo :: a[x] < 0
    invariant forall x | lo <= x < mid :: a[x] == 0
    invariant forall x | hi <= x < a.Length :: a[x] > 0
    decreases hi - mid
  {
    if a[mid] < 0 {
      var tmp := a[lo];
      a[lo] := a[mid];
      a[mid] := tmp;
      lo := lo + 1;
      mid := mid + 1;
    } else if a[mid] == 0 {
      mid := mid + 1;
    } else {
      hi := hi - 1;
      var tmp := a[mid];
      a[mid] := a[hi];
      a[hi] := tmp;
    }
  }
}

