  requires 0 <= i < |s|
  ensures multiset(s[i := v]) + multiset{s[i]}
       == multiset(s) + multiset{v}
{
  assert s == s[..i] + [s[i]] + s[i + 1..];
  assert s[i := v] == s[..i] + [v] + s[i + 1..];

  calc {
    multiset(s[i := v]) + multiset{s[i]};
    == (multiset(s[..i]) + multiset{v} + multiset(s[i + 1..]))
       + multiset{s[i]};
    == (multiset(s[..i]) + multiset{s[i]} + multiset(s[i + 1..]))
       + multiset{v};
    == multiset(s) + multiset{v};
  }
}

