    == (multiset(s[..i]) + multiset{v} + multiset(s[i + 1..]))
       + multiset{s[i]};
    == (multiset(s[..i]) + multiset{s[i]} + multiset(s[i + 1..]))
       + multiset{v};
    == multiset(s) + multiset{v};
  }
}

lemma CancelSingleton(m: multiset<int>, n: multiset<int>, x: int)
  requires m + multiset{x} == n + multiset{x}
  ensures m == n
{
  forall y
    ensures m[y] == n[y]
  {
    assert (m + multiset{x})[y] == (n + multiset{x})[y];
  }
}

lemma SwapPreservesMultiset(s: seq<int>, i: int, j: int)
  requires 0 <= i < |s|
  requires 0 <= j < |s|
  ensures multiset(s[i := s[j]][j := s[i]]) == multiset(s)
{
  if i == j {
    assert s[i := s[j]][j := s[i]] == s;
  } else {
    var t := s[i := s[j]];

    assert t[j] == s[j];
    UpdateMultisetBalance(s, i, s[j]);
    UpdateMultisetBalance(t, j, s[i]);

    assert multiset(t[j := s[i]]) + multiset{s[j]}
        == multiset(s) + multiset{s[j]};

    CancelSingleton(
      multiset(t[j := s[i]]),
      multiset(s),
      s[j]
    );
  }
}

method swap(a: array<int>, i: int, j: int)
  requires 0 <= i < a.Length && 0 <= j < a.Length
  modifies a
  ensures a[..] == old(a[..]) [i := old(a[j])] [j := old(a[i])]
  ensures valid_permut(a[..], old(a[..]))
{
  ghost var s := a[..];
  assert s == old(a[..]);

  var ai := a[i];
  var aj := a[j];

  a[i] := aj;
  assert a[..] == s[i := s[j]];

  a[j] := ai;
  assert a[..] == s[i := s[j]][j := s[i]];

  SwapPreservesMultiset(s, i, j);
  assert multiset(a[..]) == multiset(s);
  assert |a[..]| == |s|;
  assert valid_permut(a[..], s);
}
