        invariant 1 <= k <= prices.Length
        invariant forall i :: 0 <= i < k ==> minp <= prices[i]
        invariant forall i, j :: 0 <= i < j < k ==> max_profit >= prices[j] - prices[i]
        decreases prices.Length - k
