method contains_duplicate(nums: seq<int>) returns (result: bool)
    requires 1 <= |nums| <= 100000
    requires forall i :: 0 <= i < |nums| ==> -1000000000 <= nums[i] <= 1000000000
    ensures result <==> distinct(nums)
{
    var seen: set<int> := {};
    var i := 0;
    while i < |nums|
        invariant 0 <= i <= |nums|
        invariant forall x :: x in seen <==> exists k :: 0 <= k < i && nums[k] == x
        invariant forall a, b :: 0 <= a < b < i ==> nums[a] != nums[b]
    {
        if nums[i] in seen {
            ghost var k :| 0 <= k < i && nums[k] == nums[i];
            assert nums[k] == nums[i];
            assert !distinct(nums);
            return false;
        }
        assert forall k :: 0 <= k < i ==> nums[k] != nums[i];
        seen := seen + {nums[i]};
        i := i + 1;
    }
    return true;
}

