method SortSeqPred(s: seq<int>, p: seq<bool>) returns (sorted: seq<int>)

  requires |s| == |p|

  ensures |sorted| == |s|
  ensures forall i, j :: 0 <= i < j < |sorted| && p[i] && p[j] ==> sorted[i] <= sorted[j]
  ensures multiset(s) == multiset(sorted)
  ensures forall i :: 0 <= i < |s| && !p[i] ==> sorted[i] == s[i]
{
  var n := |s|;
  var a := s;
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |a| == n
    invariant forall t :: 0 <= t < n && !p[t] ==> a[t] == s[t]
    invariant multiset(a) == multiset(s)
    invariant forall x, y :: 0 <= x < y < i && p[x] && p[y] ==> a[x] <= a[y]
    invariant forall x, y :: 0 <= x < i && i <= y < n && p[x] && p[y] ==> a[x] <= a[y]
  {
    if p[i] {
      var m := i;
      var j := i + 1;
      while j < n
        invariant i + 1 <= j <= n
        invariant i <= m < j && p[m]
        invariant forall t :: i <= t < j && p[t] ==> a[m] <= a[t]
      {
        if p[j] && a[j] < a[m] {
          m := j;
        }
        j := j + 1;
      }
      assert forall t :: i <= t < n && p[t] ==> a[m] <= a[t];
      var ai := a[i];
      var am := a[m];
      var a1 := a[i := am];
      assert multiset(a1) == multiset(a) - multiset{ai} + multiset{am};
      var a2 := a1[m := ai];
      assert multiset(a2) == multiset(a1) - multiset{a1[m]} + multiset{ai};
      assert a1[m] == am;
      assert multiset(a2) == multiset(a);
      a := a2;
    }
    i := i + 1;
  }
  sorted := a;
}

