lemma MulNonneg(x: nat, y: nat)
  ensures x * y >= 0
  decreases y
{
  if y > 0 {
    MulNonneg(x, y - 1);
    assert x * y == x * (y - 1) + x;
  }
}

lemma MultipleMod(x: int, d: int, k: int)
  requires d != 0 && x == k * d
  ensures x % d == 0
{
  var q := x / d;
  var r := x % d;
  var e: int := if d > 0 then d else -d;
  var t: int := if d > 0 then k - q else q - k;
  assert x == d * q + r;
  assert 0 <= r < e;
  assert r == e * t by {
    assert r == k * d - d * q;
    if d > 0 {
      assert k * d - d * q == d * (k - q);
    } else {
      assert k * d - d * q == (-d) * (q - k);
    }
  }
  if t >= 1 {
    MulNonneg(e, t - 1);
    assert e * t == e * (t - 1) + e;
    assert false;
  } else if t <= -1 {
    MulNonneg(e, -t - 1);
    assert e * t == -(e * (-t - 1)) - e;
    assert false;
  }
  assert t == 0;
  assert e * t == 0;
}

method LcmInt(a: int, b: int) returns (result: int)
    requires a != 0 && b != 0
    ensures result >= 0
    ensures result % a == 0
    ensures result % b == 0
{
  var A: int := if a > 0 then a else -a;
  var B: int := if b > 0 then b else -b;
  var k: int := 1;
  var m: int := A;
  while m % b != 0
    invariant 1 <= k <= B
    invariant m == k * A
    decreases B - k
  {
    if k == B {
      if b > 0 {
        assert m == A * b;
        MultipleMod(m, b, A);
      } else {
        assert m == (-A) * b;
        MultipleMod(m, b, -A);
      }
      assert false;
    }
    assert (k + 1) * A == k * A + A;
    k := k + 1;
    m := m + A;
  }
  if a > 0 {
    assert m == k * a;
    MultipleMod(m, a, k);
  } else {
    assert m == (-k) * a;
    MultipleMod(m, a, -k);
  }
  MulNonneg(k, A);
  result := m;
}

