predicate SortedStrict(s: seq<int>)
{
  forall i, j :: 0 <= i < j < |s| ==> s[i] < s[j]
}

method InsertSorted(s: seq<int>, x: int) returns (r: seq<int>)
  requires SortedStrict(s)
  requires x !in s
  ensures SortedStrict(r)
  ensures forall v :: v in r <==> (v in s || v == x)
{
  var k := 0;
  while k < |s| && s[k] < x
    invariant 0 <= k <= |s|
    invariant forall i :: 0 <= i < k ==> s[i] < x
  {
    k := k + 1;
  }
  if k < |s| {
    assert s[k] != x;
    assert s[k] > x;
  }
  assert forall i :: k <= i < |s| ==> s[i] > x;
  r := s[..k] + [x] + s[k..];
  assert |r| == |s| + 1;
  assert forall i :: 0 <= i < |r| ==> r[i] == (if i < k then s[i] else if i == k then x else s[i-1]);
  assert s == s[..k] + s[k..];
  forall v
    ensures v in r <==> (v in s || v == x)
  {
    if v in r {
      var i :| 0 <= i < |r| && r[i] == v;
      if i < k {
        assert s[i] == v;
      } else if i > k {
        assert s[i-1] == v;
      }
    }
    if v in s {
      var i :| 0 <= i < |s| && s[i] == v;
      if i < k {
        assert r[i] == v;
      } else {
        assert r[i+1] == v;
      }
    }
    if v == x {
      assert r[k] == x;
    }
  }
}

method intersect1d(ar1: seq<int>, ar2: seq<int>) returns (result: seq<int>)
  ensures // Result contains only values that exist in both input arrays
    forall i :: 0 <= i < |result| ==> result[i] in ar1 && result[i] in ar2
  ensures // Result is sorted in strict ascending order (which ensures uniqueness)
    forall i, j :: 0 <= i < j < |result| ==> result[i] < result[j]
  ensures // Result is complete - contains all values that appear in both arrays
    forall val :: val in ar1 && val in ar2 ==> val in result
{
  result := [];
  for i := 0 to |ar1|
    invariant SortedStrict(result)
    invariant forall v :: v in result ==> v in ar1 && v in ar2
    invariant forall j :: 0 <= j < i && ar1[j] in ar2 ==> ar1[j] in result
  {
    if ar1[i] in ar2 && ar1[i] !in result {
      result := InsertSorted(result, ar1[i]);
    }
  }
  forall k | 0 <= k < |result|
    ensures result[k] in ar1 && result[k] in ar2
  {
    assert result[k] in result;
  }
  forall val | val in ar1 && val in ar2
    ensures val in result
  {
    var j :| 0 <= j < |ar1| && ar1[j] == val;
  }
}

