predicate StrictSorted(s: seq<int>)
{
  forall i, j :: 0 <= i < j < |s| ==> s[i] < s[j]
}

function InsertSorted(s: seq<int>, x: int): seq<int>
  decreases |s|
{
  if |s| == 0 then
    [x]
  else if x < s[0] then
    [x] + s
  else
    [s[0]] + InsertSorted(s[1..], x)
}

lemma InsertSortedElements(s: seq<int>, x: int)
  ensures forall y :: y in InsertSorted(s, x) <==> y == x || y in s
  decreases |s|
{
  if |s| > 0 && !(x < s[0]) {
    InsertSortedElements(s[1..], x);
  }
}

lemma TailIsStrictSorted(s: seq<int>)
  requires |s| > 0
  requires StrictSorted(s)
  ensures StrictSorted(s[1..])
{
  forall i, j | 0 <= i < j < |s[1..]|
    ensures s[1..][i] < s[1..][j]
  {
    assert s[1..][i] == s[i + 1];
    assert s[1..][j] == s[j + 1];
    assert 0 <= i + 1 < j + 1 < |s|;
  }
}

lemma HeadLessThanTail(s: seq<int>)
  requires |s| > 0
  requires StrictSorted(s)
  ensures forall y :: y in s[1..] ==> s[0] < y
{
  forall y | y in s[1..]
    ensures s[0] < y
  {
    var i :| 0 <= i < |s[1..]| && s[1..][i] == y;
    assert s[1..][i] == s[i + 1];
    assert 0 < i + 1 < |s|;
    assert s[0] < s[i + 1];
  }
}

lemma PrependStrictSorted(x: int, s: seq<int>)
  requires StrictSorted(s)
  requires forall y :: y in s ==> x < y
  ensures StrictSorted([x] + s)
{
  forall i, j | 0 <= i < j < |[x] + s|
    ensures ([x] + s)[i] < ([x] + s)[j]
  {
    if i == 0 {
      assert 0 <= j - 1 < |s|;
      assert ([x] + s)[i] == x;
      assert ([x] + s)[j] == s[j - 1];
      assert s[j - 1] in s;
    } else {
      assert 0 <= i - 1 < j - 1 < |s|;
      assert ([x] + s)[i] == s[i - 1];
      assert ([x] + s)[j] == s[j - 1];
    }
  }
}

lemma InsertPreservesStrictSorting(s: seq<int>, x: int)
  requires StrictSorted(s)
  requires x !in s
  ensures StrictSorted(InsertSorted(s, x))
  decreases |s|
{
  if |s| == 0 {
    assert InsertSorted(s, x) == [x];
  } else if x < s[0] {
    forall y | y in s
      ensures x < y
    {
      var i :| 0 <= i < |s| && s[i] == y;
      if i == 0 {
        assert y == s[0];
      } else {
        assert s[0] < s[i];
      }
    }
    PrependStrictSorted(x, s);
    assert InsertSorted(s, x) == [x] + s;
  } else {
    assert x != s[0];
    assert s[0] < x;
    assert x !in s[1..];

    TailIsStrictSorted(s);
    HeadLessThanTail(s);
    InsertPreservesStrictSorting(s[1..], x);
    InsertSortedElements(s[1..], x);

    forall y | y in InsertSorted(s[1..], x)
      ensures s[0] < y
    {
      assert y == x || y in s[1..];
      if y != x {
        assert s[0] < y;
      }
    }

    PrependStrictSorted(s[0], InsertSorted(s[1..], x));
