predicate StrictSorted(s: seq<int>)
{
  forall a, b :: 0 <= a < b < |s| ==> s[a] < s[b]
}

method Insert(s: seq<int>, x: int) returns (r: seq<int>)
  requires StrictSorted(s)
  ensures StrictSorted(r)
  ensures |r| <= |s| + 1
  ensures x in r
  ensures forall y :: y in s ==> y in r
  ensures forall y :: y in r ==> y in s || y == x
{
  var i := 0;
  while i < |s| && s[i] < x
    invariant 0 <= i <= |s|
    invariant forall k :: 0 <= k < i ==> s[k] < x
  {
    i := i + 1;
  }
  if i < |s| && s[i] == x {
    r := s;
    assert r[i] == x;
  } else {
    assert forall k :: i <= k < |s| ==> s[k] > x by {
      forall k | i <= k < |s| ensures s[k] > x {
        if k > i {
          assert s[i] < s[k];
        }
      }
    }
    r := s[..i] + [x] + s[i..];
    assert |r| == |s| + 1;
    assert forall k :: 0 <= k < i ==> r[k] == s[k];
    assert r[i] == x;
    assert forall k :: i < k < |r| ==> r[k] == s[k-1];
    forall a, b | 0 <= a < b < |r| ensures r[a] < r[b] {
      if b < i {
        assert r[a] == s[a] && r[b] == s[b];
      } else if b == i {
        assert r[a] == s[a];
      } else if a < i {
        assert r[a] == s[a] && r[b] == s[b-1];
      } else if a == i {
        assert r[b] == s[b-1];
      } else {
        assert r[a] == s[a-1] && r[b] == s[b-1];
      }
    }
    forall y | y in s ensures y in r {
      var k :| 0 <= k < |s| && s[k] == y;
      if k < i {
        assert r[k] == y;
      } else {
        assert r[k+1] == y;
      }
    }
    forall y | y in r ensures y in s || y == x {
      var k :| 0 <= k < |r| && r[k] == y;
      if k < i {
        assert s[k] == y;
      } else if k > i {
        assert s[k-1] == y;
      }
    }
  }
