predicate StrictSorted(s: seq<int>)
{
    forall i, j :: 0 <= i < j < |s| ==> s[i] < s[j]
}

lemma HeadMembership(s: seq<int>, x: int)
    requires 0 < |s|
    ensures x in s <==> x == s[0] || x in s[1..]
{
    if x in s {
        var i :| 0 <= i < |s| && s[i] == x;
        if i == 0 {
            assert x == s[0];
        } else {
            assert 0 <= i - 1 < |s[1..]|;
            assert s[1..][i - 1] == s[i];
            assert x in s[1..];
        }
    }

    if x == s[0] {
        assert x in s;
    }

    if x in s[1..] {
        var i :| 0 <= i < |s[1..]| && s[1..][i] == x;
        assert s[i + 1] == x;
        assert x in s;
    }
}

lemma TailIsSorted(s: seq<int>)
    requires 0 < |s|
    requires StrictSorted(s)
    ensures StrictSorted(s[1..])
{
    forall i, j | 0 <= i < j < |s[1..]|
        ensures s[1..][i] < s[1..][j]
    {
        assert s[1..][i] == s[i + 1];
        assert s[1..][j] == s[j + 1];
        assert 0 <= i + 1 < j + 1 < |s|;
        assert s[i + 1] < s[j + 1];
    }
}

lemma PrependIsSorted(x: int, s: seq<int>)
    requires StrictSorted(s)
    requires forall i :: 0 <= i < |s| ==> x < s[i]
    ensures StrictSorted([x] + s)
{
    forall i, j | 0 <= i < j < |[x] + s|
        ensures ([x] + s)[i] < ([x] + s)[j]
    {
        if i == 0 {
            assert 0 <= j - 1 < |s|;
            assert ([x] + s)[i] == x;
            assert ([x] + s)[j] == s[j - 1];
            assert x < s[j - 1];
        } else {
            assert 0 <= i - 1 < j - 1 < |s|;
            assert ([x] + s)[i] == s[i - 1];
            assert ([x] + s)[j] == s[j - 1];
            assert s[i - 1] < s[j - 1];
        }
    }
}

method insertUnique(s: seq<int>, x: int) returns (r: seq<int>)
