method InsertionSort(xs: array<int>) returns (result: array<int>)
    ensures Sorted(result)
    ensures MultisetEquivalent(xs, result)
{
  result := new int[xs.Length];
  var k := 0;
  while k < xs.Length
    invariant 0 <= k <= xs.Length
    invariant result.Length == xs.Length
  {
    result[k] := xs[k];
    k := k + 1;
  }

  var i := 0;
  while i < result.Length
    invariant 0 <= i <= result.Length
    invariant forall a, b :: 0 <= a < b < i ==> result[a] <= result[b]
  {
    var j := i;
    while j > 0 && result[j-1] > result[j]
      invariant 0 <= j <= i
      invariant forall a, b :: 0 <= a < b <= i && a != j && b != j ==> result[a] <= result[b]
      invariant forall b :: j < b <= i ==> result[j] <= result[b]
      decreases j
    {
      result[j-1], result[j] := result[j], result[j-1];
      j := j - 1;
    }
    assert forall a, b :: 0 <= a < b <= i ==> result[a] <= result[b] by {
      forall a, b | 0 <= a < b <= i
        ensures result[a] <= result[b]
      {
        if b == j {
          if a < j - 1 {
            assert result[a] <= result[j-1];
          }
        }
      }
    }
    i := i + 1;
  }
}

