method MaxProfit(prices: seq<nat>) returns (result: nat)
    ensures
        (result == 0 && |prices| == 0) ||
        (exists i: int, j: int :: 0 <= i < j < |prices| && prices[j] >= prices[i] && prices[j] - prices[i] == result) ||
        (forall i: int, j: int :: 0 <= i < j < |prices| ==> prices[j] < prices[i])
{
    if |prices| == 0 {
        return 0;
    }
    var minIdx := 0;
    result := 0;
    var found := false;
    var bi := 0;
    var bj := 0;
    var k := 1;
    while k < |prices|
        invariant 1 <= k <= |prices|
        invariant 0 <= minIdx < k
        invariant forall a :: 0 <= a < k ==> prices[minIdx] <= prices[a]
        invariant found ==> 0 <= bi < bj < k && prices[bj] >= prices[bi] && prices[bj] - prices[bi] == result
        invariant !found ==> forall a, b :: 0 <= a < b < k ==> prices[b] < prices[a]
        invariant !found ==> result == 0
        decreases |prices| - k
    {
        if prices[k] >= prices[minIdx] {
            if !found || prices[k] - prices[minIdx] > result {
                found := true;
                bi := minIdx;
                bj := k;
                result := prices[k] - prices[minIdx];
            }
        } else {
            minIdx := k;
        }
        k := k + 1;
    }
    if found {
        assert 0 <= bi < bj < |prices| && prices[bj] >= prices[bi] && prices[bj] - prices[bi] == result;
    }
}

