method PartitionEvensOdds(nums: array<nat>) returns (evens: array<nat>, odds: array<nat>)
    requires true
    ensures forall i :: 0 <= i < evens.Length ==> evens[i] % 2 == 0
    ensures forall i :: 0 <= i < odds.Length ==> odds[i] % 2 == 1
{
