  var os: seq<nat> := [];
  var i := 0;
  while i < nums.Length
    invariant 0 <= i <= nums.Length
    invariant forall j :: 0 <= j < |es| ==> es[j] % 2 == 0
    invariant forall j :: 0 <= j < |os| ==> os[j] % 2 == 1
  {
    if nums[i] % 2 == 0 {
      es := es + [nums[i]];
    } else {
      os := os + [nums[i]];
    }
    i := i + 1;
  }

  evens := new nat[|es|];
  var k := 0;
  while k < |es|
    invariant 0 <= k <= |es|
    invariant evens.Length == |es|
    invariant forall j :: 0 <= j < k ==> evens[j] == es[j]
    modifies evens
  {
    evens[k] := es[k];
    k := k + 1;
  }
  assert forall j :: 0 <= j < evens.Length ==> evens[j] % 2 == 0;

  odds := new nat[|os|];
  k := 0;
  while k < |os|
    invariant 0 <= k <= |os|
    invariant odds.Length == |os|
    invariant forall j :: 0 <= j < k ==> odds[j] == os[j]
    modifies odds
  {
    odds[k] := os[k];
    k := k + 1;
  }
}

