method BubbleSort(a: seq<int>) returns (result: seq<int>)
    ensures |result| == |a|
    ensures forall i, j :: 0 <= i < j < |result| ==> result[i] <= result[j]
    ensures multiset(a) == multiset(result)
{
  result := a;
  var n := |result|;
  var i := n;
  while i > 0
    invariant 0 <= i <= n
    invariant |result| == n
    invariant multiset(result) == multiset(a)
    invariant forall x, y :: i <= x < y < n ==> result[x] <= result[y]
    invariant forall x, y :: 0 <= x < i <= y < n ==> result[x] <= result[y]
    decreases i
  {
    var j := 0;
    while j < i - 1
      invariant 0 <= j <= i - 1
      invariant |result| == n
      invariant multiset(result) == multiset(a)
      invariant forall x, y :: i <= x < y < n ==> result[x] <= result[y]
      invariant forall x, y :: 0 <= x < i <= y < n ==> result[x] <= result[y]
      invariant forall x :: 0 <= x <= j ==> result[x] <= result[j]
      decreases i - 1 - j
    {
      if result[j] > result[j + 1] {
        var old_r := result;
        result := result[j := old_r[j + 1]][j + 1 := old_r[j]];
        assert multiset(result) == multiset(old_r);
      }
      j := j + 1;
    }
    i := i - 1;
  }
}

