lemma TransferMember(s: seq<int>, t: seq<int>, x: int)
    requires multiset(s) == multiset(t)
    requires x in s
    ensures x in t
{
    assert multiset(s)[x] > 0;
    assert multiset(t)[x] > 0;
}

method ExtractMin(s: seq<int>) returns (m: int, rest: seq<int>)
    requires |s| > 0
    ensures |rest| + 1 == |s|
    ensures multiset(s) == multiset([m]) + multiset(rest)
    ensures forall x :: x in s ==> m <= x
    ensures forall x :: x in rest ==> m <= x
    decreases |s|
{
    if |s| == 1 {
        m := s[0];
        rest := [];
        assert s == [s[0]];
    } else {
        assert |s[1..]| > 0;
        assert |s[1..]| < |s|;
        assert s == [s[0]] + s[1..];

        var tailMin, tailRest := ExtractMin(s[1..]);

        if s[0] <= tailMin {
            m := s[0];
            rest := s[1..];

            calc {
                multiset(s);
                == multiset([s[0]]) + multiset(s[1..]);
                == multiset([m]) + multiset(rest);
            }

            forall x | x in s
                ensures m <= x
            {
                if x != s[0] {
                    assert x in s[1..];
                    assert tailMin <= x;
                }
            }

            forall x | x in rest
                ensures m <= x
            {
                assert x in s[1..];
                assert tailMin <= x;
            }
        } else {
            m := tailMin;
            rest := [s[0]] + tailRest;

            calc {
                multiset(s);
                == multiset([s[0]]) + multiset(s[1..]);
                == multiset([s[0]]) +
                   (multiset([tailMin]) + multiset(tailRest));
                == multiset([tailMin]) +
                   (multiset([s[0]]) + multiset(tailRest));
                == multiset([m]) + multiset(rest);
            }

            forall x | x in s
                ensures m <= x
            {
                if x == s[0] {
                    assert tailMin < s[0];
                } else {
                    assert x in s[1..];
                    assert tailMin <= x;
                }
            }

            forall x | x in rest
                ensures m <= x
            {
                if x == s[0] {
                    assert tailMin < s[0];
                } else {
                    assert x in tailRest;
                    assert tailMin <= x;
                }
            }
        }
    }
}

method BubbleSort(a: seq<int>) returns (result: seq<int>)
    ensures |result| == |a|
    ensures forall i, j :: 0 <= i < j < |result| ==> result[i] <= result[j]
    ensures multiset(a) == multiset(result)
    decreases |a|
{
    if |a| == 0 {
        result := [];
    } else {
        var m, rest := ExtractMin(a);
        assert |rest| < |a|;

        var tail := BubbleSort(rest);

        forall k | 0 <= k < |tail|
            ensures m <= tail[k]
        {
            assert tail[k] in tail;
            TransferMember(tail, rest, tail[k]);
            assert m <= tail[k];
        }

        result := [m] + tail;

        calc {
            multiset(a);
            == multiset([m]) + multiset(rest);
            == multiset([m]) + multiset(tail);
            == multiset(result);
        }

        forall i, j | 0 <= i < j < |result|
            ensures result[i] <= result[j]
        {
            if i == 0 {
                assert 0 <= j - 1 < |tail|;
                assert result[i] == m;
                assert result[j] == tail[j - 1];
                assert m <= tail[j - 1];
            } else {
                assert 0 <= i - 1 < j - 1 < |tail|;
                assert result[i] == tail[i - 1];
                assert result[j] == tail[j - 1];
                assert tail[i - 1] <= tail[j - 1];
            }
        }
    }
}

